  PUBLIC :: CD_Init_Deck_System
  PUBLIC :: CD_Init_Deck_HermiteCable
  PUBLIC :: CD_Init_Deck_Aggregate
  PUBLIC :: CD_Deck_Query_dtM
  PUBLIC :: CD_End_Deck_Aggregate
  PUBLIC :: CD_DeckAggregateType
  PUBLIC :: CD_LineInitSummary
  ! Coupled Rigid6 runtime: the aggregate facade owns a CD_Rigid6RuntimeType and marches
  ! it over the EI=0 system each mooring step (opaque; RigidBodyState/DeckOptions stay private).
  PUBLIC :: CD_Rigid6RuntimeType
  PUBLIC :: CD_Init_Deck_Aggregate_Rigid6, CD_Step_Aggregate_Rigid6
  PUBLIC :: CD_Rigid6_NBodies, CD_Rigid6_Snapshot, CD_Rigid6_Restore, CD_Rigid6_End
  PUBLIC :: CD_Rigid6_GetRefPositions, CD_Rigid6_SetHeldFluid
  PUBLIC :: CD_Rigid6_NHost, CD_Rigid6_AllHost, CD_Rigid6_SetHostKinematics, CD_Rigid6_GetHostKinematics
  PUBLIC :: CD_Rigid6_ScatterHostPoints, CD_Rigid6_HostWrench, CD_Rigid6_Stage, CD_Rigid6_Unstage
  PUBLIC :: CD_RodRuntimeType
  PUBLIC :: CD_Init_Deck_Aggregate_Rod, CD_Step_Aggregate_Rod
  PUBLIC :: CD_Rod_NRods, CD_Rod_Snapshot, CD_Rod_Restore, CD_Rod_End
  PUBLIC :: CD_Rod_MirrorSize, CD_Rod_Get_States, CD_Rod_Set_States, CD_Rod_Apply_States
  PUBLIC :: CD_Rod_GetFluidPositions, CD_Rod_SetHeldFluid, CD_Rod_NFluidStations, CD_Rod_NStations
  PUBLIC :: CD_Rod_NHost, CD_Rod_SetHostKinematics, CD_Rod_GetHostKinematics, CD_Rod_ScatterHostPoints
  PUBLIC :: CD_Rod_HostWrench, CD_Rod_Stage, CD_Rod_Unstage
  PUBLIC :: CD_Rod_Hydro_Probe, CD_Rigid6_Hydrostatics_Probe, CD_Deck_Fluid_Probe, CD_Rigid6_Fluid_Probe
  ! Checkpoint-restart 6-DOF body-state mirror (per-body reals + pack/unpack).
  ! CD_RIGID6_MIRROR_PER_BODY carries its own PUBLIC attribute at its PARAMETER declaration.
  PUBLIC :: CD_Rigid6_MirrorSize
  PUBLIC :: CD_Rigid6_Get_States, CD_Rigid6_Set_States
  PUBLIC :: DeckFailure, DeckLine, DeckPoint
  PUBLIC :: CD_Fire_Deck_Failures
  PUBLIC :: CD_Check_System_Plausibility
  PUBLIC :: CD_Replay_Deck_Failures
  PUBLIC :: CD_Classify_Dynamic_Completion
  ! Geometric output-channel helpers, exposed so the channel gate (test_driver_channels)
  ! can verify curvature/bend-moment/declination/azimuth against hand-computed geometry.
  PUBLIC :: line_geom_value, menger_curvature, tangent_declination_deg, tangent_azimuth_deg
  PUBLIC :: circumcircle_curvature_vector
  ! OpenFAST CompMooring=5 output-channel surface: the OpenFAST shell (via the aggregate
  ! facade) evaluates a deck OUTPUTS token against a built aggregate (EI=0 mooring system +
  ! finite-EI cables) with CD_Eval_Aggregate_Channel and labels its unit with CD_Channel_Unit.
  ! Both reuse the same private evaluators the standalone .out writers use, so a coupled run
  ! and the standalone driver report identical channel values on a shared configuration.
  PUBLIC :: CD_Eval_Aggregate_Channel, CD_Channel_Unit
  ! In-process object queries of the C API (CableDyn_CAPI): segment tensions in the .t.out
  ! convention, and the body/rod inventories the Body<N>/Rod<N> channels resolve on.
  PUBLIC :: CD_Eval_Aggregate_Segment_Tensions, CD_Rigid6_Inventory, CD_Rod_Inventory, CD_Channel_Token_Parses
  ! Range graphs of an aggregate run (the standalone mixed route samples and writes them).
  PUBLIC :: CD_Deck_Range_Sample_Aggregate, CD_Deck_Range_Write
  ! Diagnostic probe of the multibody march (verification tests): CD_Multibody_Probe_Arm makes
  ! the next multibody run start body 1 with the given velocity and angular velocity and record
  ! its full-precision state after every step; CD_Multibody_Probe_Get returns the record.
  PUBLIC :: CD_Multibody_Probe_Arm, CD_Multibody_Probe_Get
  INTEGER, PARAMETER, PUBLIC :: CD_MB_PROBE_NCOL = 29
  LOGICAL, SAVE :: probe_armed = .FALSE.
  REAL(wp), SAVE :: probe_v0(3) = 0.0_wp, probe_w0(3) = 0.0_wp
  REAL(wp), ALLOCATABLE, SAVE :: probe_rec(:, :)
  INTEGER, PARAMETER, PUBLIC :: CD_DECKDRV_OK = 0, CD_DECKDRV_BADINPUT = 1, CD_DECKDRV_SOLVEFAIL = 2

  ! Deck token / OUTPUTS channel-name length. Public so the aggregate facade can declare its
  ! retained channel-name store with a matching length.
  INTEGER, PARAMETER, PUBLIC :: CD_DECK_NAMELEN = 64
  ! Auxiliary-file paths are not deck identifiers. Keep their storage independent of
  ! CD_DECK_NAMELEN so ordinary nested directory layouts cannot be silently truncated
  ! while the parser is reading motionFile, bathymetryFile, or WaterKin.
  INTEGER, PARAMETER, PUBLIC :: CD_DECK_PATHLEN = 512
  ! Reals mirrored per Rigid6 body for checkpoint restart: r(3) v(3) a(3) omega(3) alpha(3)
  ! rot_mat(9) = 24. eta and the reference frame are re-derived / constant (see CD_Rigid6_Set_States).
  INTEGER, PARAMETER, PUBLIC :: CD_RIGID6_MIRROR_PER_BODY = 24
  INTEGER, PARAMETER, PUBLIC :: CD_ROD_MIRROR_PER_ROD = 24
  INTEGER, PARAMETER :: NAMELEN = CD_DECK_NAMELEN
  ! appended to a failed standalone march's message: the .out file keeps the committed rows
  CHARACTER(*), PARAMETER :: INSPECTION_NOTE = ' Output contains only committed states and is for inspection only.'
  REAL(wp), PARAMETER :: QUARTER_PI = 0.785398163397448309616_wp   ! pi/4 (displaced-area factor)
  REAL(wp), PARAMETER :: CD_RAD2DEG = 57.29577951308232087680_wp   ! 180/pi (declination/azimuth output)
  INTEGER, PARAMETER :: WAVE_NONE = 0, WAVE_AIRY = 1, WAVE_JONSWAP = 2, WAVE_COMPONENTS = 3
  ! WAVE_SEA: spectral/multi-train/spread seas of CableDyn_WaveSpectra
  INTEGER, PARAMETER :: WAVE_SEA = 4
  ! WAVE_STREAM: regular nonlinear stream-function (Dean) wave of CableDyn_StreamWave
  INTEGER, PARAMETER :: WAVE_STREAM = 5
  ! One line's modal result (OPTION nModes)
  TYPE :: ModalLineResult
    INTEGER :: n_found = 0, dof_per_node = 3
    REAL(wp), ALLOCATABLE :: omega2(:), shapes(:, :), q(:)
  END TYPE ModalLineResult
  REAL(wp), PARAMETER :: TWO_PI = 8.0_wp*QUARTER_PI
  ! Deck and auxiliary-file record buffer length. next_record reports a record whose
  ! non-comment text does not fit with REC_TOO_LONG instead of truncating it.
  INTEGER, PARAMETER :: DECK_RECLEN = 512
  INTEGER, PARAMETER :: REC_TOO_LONG = 1000001
  ! next_record status for a record whose non-comment text holds a non-ASCII (UTF-8
  ! encoded) whitespace character or a NUL byte, which the tokenizer does not treat as
  ! a separator and would otherwise hide inside a token.
  INTEGER, PARAMETER :: REC_BAD_CHAR = 1000002, REC_NUL_CHAR = 1000003
  ! Time column of every tabular output: 17 significant digits round-trip a double, so
  ! long records and fine steps keep distinct, uniformly spaced stamps.
  CHARACTER(*), PARAMETER :: TIME_COLUMN_FMT = '(ES25.16E3)'
  ! A whole time-series row in one WRITE: the time column, then TAB-separated ES15.7E3 values
  ! (a three-digit exponent field, so |values| below 1e-99 keep their exponent letter).
  CHARACTER(*), PARAMETER :: ROW_VALUES_FMT = TIME_COLUMN_FMT(1:LEN(TIME_COLUMN_FMT) - 1)//',*(A,ES15.7E3))'
  ! Largest step count a dtM/TMax (or motion-file) grid may index with default INTEGER.
  REAL(wp), PARAMETER :: MAX_GRID_STEPS = REAL(HUGE(1) - 1, wp)
  INTEGER, PARAMETER :: MOTION_POINT_ROWS = 0, MOTION_VESSEL_FILE = 1, MOTION_VESSEL_RAO = 2
  ! Largest WaterKin WaveKinMod-1 record (TMax/dtWave samples) reduced to Fourier components.
  REAL(wp), PARAMETER :: MAX_WAVE_SAMPLES = 1.0e6_wp
  ! a wave record above this many samples prints a setup-time note before its O(N^2) reduction
  INTEGER, PARAMETER :: LONG_WAVE_RECORD = 100000
  ! real_value_defect classes of an input number
  INTEGER, PARAMETER :: REAL_OK = 0, REAL_NONFINITE = 1, REAL_SUBNORMAL = 2
  ! Admissible input magnitudes (documented in driver_format.md, "Admissible input ranges").
  ! Beyond them the solver's force, length or time scales overflow (a trapped FPE, or Inf in
  ! Release) instead of failing to converge, so the deck is rejected with a typed message.
  REAL(wp), PARAMETER :: MAX_COORDINATE = 1.0e6_wp        ! |x|, |y|, |z|, WtrDpth [m]
  REAL(wp), PARAMETER :: MAX_GRAVITY = 1.0e3_wp           ! g [m/s^2]
  REAL(wp), PARAMETER :: MAX_WATER_DENSITY = 1.0e5_wp     ! rhoW [kg/m^3]
  REAL(wp), PARAMETER :: MAX_COEFFICIENT = 1.0e15_wp      ! EA, EI, |BA|, kBot, cBot, masses, inertias
  REAL(wp), PARAMETER :: MAX_COEFFICIENT_SMALL = 1.0e3_wp ! Cd, Ca and other dimensionless coefficients
  REAL(wp), PARAMETER :: MIN_EA = 1.0e-3_wp               ! EA [N]
  REAL(wp), PARAMETER :: MIN_DIAMETER = 1.0e-6_wp         ! Diam [m]
  REAL(wp), PARAMETER :: MAX_FLUID_SPEED = 1.0e3_wp       ! current components [m/s]
  REAL(wp), PARAMETER :: MAX_WAVE_HEIGHT = 1.0e3_wp       ! wave height / component amplitude [m]
  REAL(wp), PARAMETER :: MIN_WAVE_PERIOD = 0.1_wp, MAX_WAVE_PERIOD = 1.0e5_wp  ! [s]
  REAL(wp), PARAMETER :: MAX_WAVE_OMEGA = 1.0e4_wp        ! WaveKinMod 1 component frequency [rad/s]
  REAL(wp), PARAMETER :: MAX_MOTION_SPEED = 1.0e4_wp      ! prescribed velocity [m/s, rad/s]
  REAL(wp), PARAMETER :: MAX_MOTION_ACCEL = 1.0e6_wp      ! prescribed acceleration [m/s^2, rad/s^2]

  TYPE :: DeckLineType
    CHARACTER(NAMELEN) :: name = ''
    REAL(wp) :: diam = CD_ZERO, mass = CD_ZERO, ea = CD_ZERO
    REAL(wp) :: ba = CD_ZERO, ei = CD_ZERO
    REAL(wp) :: gas = CD_ZERO, gj = CD_ZERO
    REAL(wp) :: i_rt = CD_ZERO, i_rn = CD_ZERO
    REAL(wp) :: cdn = CD_ZERO, cdt = CD_ZERO, can = CD_ZERO, cat = CD_ZERO
    ! Viscoelastic stiffness (MoorDyn ElasticMod): the EA column's bar-separated
    ! parts select the model -- 1 part = plain (mode 1), 2 = constant dynamic
    ! stiffness Es|Ed (mode 2), 3 = load-dependent Es|alphaMBL|vbeta (mode 3);
    ! the BA column may carry Bs|Bd with no more parts than EA.
    INTEGER :: elastic_mod = 1
    REAL(wp) :: ea_d = CD_ZERO, ba_d = CD_ZERO
    REAL(wp) :: alpha_mbl = CD_ZERO, vbeta = CD_ZERO
    ! Syrope polyester working-curve model: the EA column's first bar-part is
    ! SYROPE:<settings-file> (relative to the deck), with the dynamic fast-spring
    ! constants alpha|beta following (EA = SYROPE:file|alpha|beta); the BA column
    ! carries MoorDyn's static/dynamic damping pair BA_s|BA_d. is_syrope marks the row.
    LOGICAL :: is_syrope = .FALSE.
    CHARACTER(CD_DECK_PATHLEN) :: syrope_file = ''
    REAL(wp) :: syrope_alpha = CD_ZERO, syrope_beta = CD_ZERO
    REAL(wp) :: syrope_c1 = CD_ZERO, syrope_c2 = CD_ZERO
    ! The original working-curve table + shape, read from the settings file
    ! during parse (resolved relative to the deck) and stored here so the model
    ! build needs no deck-path threading. syrope_wc_mod > 0 marks it resolved.
    INTEGER :: syrope_wc_mod = 0
    REAL(wp) :: syrope_p1 = CD_ZERO, syrope_p2 = CD_ZERO
    REAL(wp), ALLOCATABLE :: syrope_owc_strain(:), syrope_owc_tension(:)
    ! The OWC table file the settings file names, resolved.
    CHARACTER(CD_DECK_PATHLEN) :: syrope_owc_file = ''
    ! Deck file line of the row (0 when not read from a file), for error messages.
    INTEGER :: deck_line = 0
  END TYPE

  ! Body<N>/Rod<N> output quantities (parse_object_channel)
  CHARACTER(4), PARAMETER :: OBJ_QTY(27) = ['px  ', 'py  ', 'pz  ', 'rx  ', 'ry  ', 'rz  ', 'vx  ', 'vy  ', &
                                            'vz  ', 'rvx ', 'rvy ', 'rvz ', 'ax  ', 'ay  ', 'az  ', 'rax ', &
                                            'ray ', 'raz ', 'fx  ', 'fy  ', 'fz  ', 'mx  ', 'my  ', 'mz  ', &
                                            'tena', 'tenb', 'sub ']

  TYPE :: DeckPoint
    INTEGER :: id = 0
    INTEGER :: body_id = 0
    ! a Body<M> point made from an end of a rod fixed to body M: the rod id and end (1 A, 2 B)
    INTEGER :: rod_ref = 0, rod_end = 0
    INTEGER :: turbine_id = 0             ! FAST.Farm: >0 = coupled to turbine J (Turbine<J>)
    CHARACTER(NAMELEN) :: ptype = ''      ! fixed | coupled | body<n> | connect | free
    REAL(wp) :: pos(3) = CD_ZERO
    ! standalone TURBINES deck: the turbine-local coordinates of a Turbine<J> point
    REAL(wp) :: turb_local(3) = CD_ZERO
    REAL(wp) :: body_offset(3) = CD_ZERO
    REAL(wp) :: mass = CD_ZERO, vol = CD_ZERO, cda = CD_ZERO, ca = CD_ZERO
    INTEGER :: deck_line = 0              ! deck file line of the row, for error messages
  END TYPE

  TYPE :: DeckBody
    INTEGER :: id = 0
    CHARACTER(NAMELEN) :: btype = ''
    REAL(wp) :: pos(3) = CD_ZERO
    REAL(wp) :: rot(3) = CD_ZERO
    REAL(wp) :: mass = CD_ZERO, vol = CD_ZERO
    REAL(wp) :: c33 = CD_ZERO, c44 = CD_ZERO, c55 = CD_ZERO
    REAL(wp) :: cda = CD_ZERO, ca = CD_ZERO
    REAL(wp) :: inertia(3) = CD_ZERO
    ! centre of gravity (body frame, from the reference point; MoorDyn 14-column rows), also the
    ! centre of buoyancy; inertia is about it
    REAL(wp) :: cg(3) = CD_ZERO
    ! EXTERNAL LOADS: constant force and linear/quadratic translational damping, summed over
    ! every row on the body; column 1 holds the global-frame (CSys G) sum and column 2 the
    ! body-frame (CSys L) sum, as MoorDyn-F keeps separate global and local accumulators
    REAL(wp) :: ext_f(3, 2) = CD_ZERO, ext_blin(3, 2) = CD_ZERO, ext_bquad(3, 2) = CD_ZERO
    INTEGER :: deck_line = 0              ! deck file line of the row, for error messages
    ! Static-equilibrium pose (solve_body_equilibrium): the body starts there, while pos/rot
    ! stay the reference of the hydrostatic restoring C33/C44/C55.
    LOGICAL :: has_eq = .FALSE.
    REAL(wp) :: pos_eq(3) = CD_ZERO
    REAL(wp) :: rot_eq(3, 3) = CD_ZERO
    ! Coupled/Vessel body (MoorDyn "Coupled"): a Rigid6 body whose pose follows the host (the
    ! coupled platform, or motionFile rows standalone) instead of being integrated.
    LOGICAL :: host_coupled = .FALSE.
  END TYPE

  TYPE :: DeckRodType
    CHARACTER(NAMELEN) :: name = ''
    REAL(wp) :: diam = CD_ZERO, mass = CD_ZERO
    ! cdn/can: side normal drag and added mass (MoorDyn Cd, Ca); cdend/caend: MoorDyn end
    ! coefficients (columns 6-7); cdt/cat: CableDyn axial side drag and added mass (optional
    ! columns 8-9, default 0 = MoorDyn).
    REAL(wp) :: cdn = CD_ZERO, can = CD_ZERO, cdt = CD_ZERO, cat = CD_ZERO
    REAL(wp) :: cdend = CD_ZERO, caend = CD_ZERO
    INTEGER :: deck_line = 0              ! deck file line of the row, for error messages
  END TYPE

  TYPE :: DeckRod
    INTEGER :: id = 0
    INTEGER :: rtype = 0
    CHARACTER(NAMELEN) :: rtype_name = ''
    CHARACTER(NAMELEN) :: rod_type = ''
    REAL(wp) :: end_a(3) = CD_ZERO
    REAL(wp) :: end_b(3) = CD_ZERO
    INTEGER :: nsegs = 0
    CHARACTER(NAMELEN) :: outputs = '-'
    INTEGER :: deck_line = 0              ! deck file line of the row, for error messages
  END TYPE

  ! END CONNECTIONS torsional restraint (TorsStiffness column)
  INTEGER, PARAMETER :: TORS_FREE = 0, TORS_RIGID = 1, TORS_FINITE = 2
  ! Smallest |Nx x Ez| / |Nx| accepted for a reference normal (about 0.06 degrees off Ez).
  REAL(wp), PARAMETER :: TORS_NX_PARALLEL_TOL = 1.0e-3_wp
  REAL(wp), PARAMETER :: DEG2RAD_TORS = 3.14159265358979323846264338327950288_wp/180.0_wp

  TYPE :: DeckLine
    INTEGER :: id = 0, nodeA = 0, nodeB = 0
    CHARACTER(NAMELEN) :: outputs = '-'
    ! True for the stock 7-column LINES row, which already defines the line's single
    ! section (type, length, segments); SECTIONS rows may not add to it.
    LOGICAL :: stock_row = .FALSE.
    LOGICAL :: has_syrope_ic = .FALSE.
    REAL(wp) :: syrope_tmax0 = CD_ZERO, syrope_tmean0 = CD_ZERO
    ! Public deck order is End A (column 1) then End B (column 2). The no-moment
    ! Ez vectors follow the A-to-B convention and are expressed in the connected
    ! parent's reference axes (global axes for fixed/anchored ends).
    INTEGER :: endconn_mode(2) = CD_ENDCONN_PINNED
    REAL(wp) :: endconn_k(2) = CD_ZERO
    REAL(wp) :: endconn_ez_ref(3, 2) = CD_ZERO
    ! Torsional end restraint of the optional END CONNECTIONS columns (End A, End B): mode
    ! TORS_FREE (default), TORS_RIGID or TORS_FINITE with stiffness tors_k [N m/rad]; tors_nx the
    ! unit zero-twist reference normal in the frame of Ez (perpendicular to Ez); tors_pretwist
    ! the roll of the end frame about Ez [rad]. Torsion is active only with both ends restrained.
    INTEGER :: tors_mode(2) = TORS_FREE
    REAL(wp) :: tors_k(2) = CD_ZERO
    REAL(wp) :: tors_nx(3, 2) = CD_ZERO
    REAL(wp) :: tors_pretwist(2) = CD_ZERO
    INTEGER :: deck_line = 0              ! deck file line of the row, for error messages
    ! ATTACHMENTS (finite-EI lines): one column per discrete attachment -- arc length from
    ! End A [m], mass [kg], displaced volume [m^3], drag area CdA [m^2], added-mass Ca [-],
    ! axial drag area CdAx [m^2] (rows 1-6).
    REAL(wp), ALLOCATABLE :: att(:, :)
  END TYPE

  TYPE :: DeckEndConnection
    INTEGER :: line_id = 0
    INTEGER :: end_index = 0
    INTEGER :: mode = CD_ENDCONN_PINNED
    REAL(wp) :: stiffness = CD_ZERO
    REAL(wp) :: ez(3) = CD_ZERO
    INTEGER :: tors_mode = TORS_FREE
    REAL(wp) :: tors_k = CD_ZERO
    REAL(wp) :: nx(3) = CD_ZERO
    REAL(wp) :: pretwist = CD_ZERO
  END TYPE

  TYPE :: DeckFailure
    !! One FAILURE row (MoorDyn v2): FailID  Point  LineID[,LineID...]  FailTime  FailTen.
    !! Triggered at a committed advance when t >= fail_time (>0) OR the attachment
    !! tension >= fail_ten (>0); the listed line ends detach onto a pre-allocated
    !! reserve Free point at the old attachment kinematics.
    INTEGER :: fail_id = 0
    INTEGER :: point_id = 0
    INTEGER, ALLOCATABLE :: line_ids(:)
    REAL(wp) :: fail_time = CD_ZERO
    REAL(wp) :: fail_ten = CD_ZERO
    LOGICAL :: failed = .FALSE.
  END TYPE

  TYPE :: DeckControl
    !! One CONTROL row (MoorDyn cable control): ChannelID  LineID[,LineID...].
    !! The host's DeltaL/DeltaLdot input for this channel modulates the LAST
    !! (fairlead-side) segment's unstretched length of every listed line.
    INTEGER :: channel = 0
    INTEGER, ALLOCATABLE :: line_ids(:)
  END TYPE

  TYPE :: DeckSection
    INTEGER :: line_id = 0, ltype = 0, nsegs = 0
    CHARACTER(NAMELEN) :: ltype_name = ''
    REAL(wp) :: length = CD_ZERO
    INTEGER :: deck_line = 0              ! deck file line of the row, for error messages
  END TYPE

  TYPE :: DeckEquivalentBuoyancy
    CHARACTER(NAMELEN) :: ltype_name = ''
    REAL(wp) :: diameter = CD_ZERO
    REAL(wp) :: submerged_weight = CD_ZERO
  END TYPE

  TYPE :: DeckOptions
    REAL(wp) :: g = 9.80665_wp, rhoW = 1025.0_wp, wtrdpth = CD_ZERO
    REAL(wp) :: kbot = 1.0e5_wp, cbot = 1.0e4_wp
    REAL(wp) :: dtM = CD_ZERO, tmax = CD_ZERO, rho_inf = 0.4_wp
    ! OPTION RangeStart: first output time accumulated into the range graphs (LINES flag r)
    REAL(wp) :: range_start = CD_ZERO
    LOGICAL :: has_range_start = .FALSE.
    REAL(wp) :: dynamic_rel_tol = 1.0e-8_wp, dynamic_abs_tol = 1.0e-14_wp
    INTEGER :: dynamic_max_iter = 30, dynamic_backtracks = 12
    INTEGER :: recovery_max_substeps = 1024
    INTEGER :: axial_quadrature_order = 4, bending_quadrature_order = 4
    REAL(wp) :: current_velocity(3) = CD_ZERO
    REAL(wp) :: wave_height = CD_ZERO, wave_period = CD_ZERO, wave_direction = CD_ZERO
    REAL(wp) :: wave_gamma = CD_ONE
    REAL(wp) :: wave_omega = CD_ZERO, wave_k = CD_ZERO
    REAL(wp) :: jonswap_omega(CD_JONSWAP_COMPONENTS) = CD_ZERO
    REAL(wp) :: jonswap_k(CD_JONSWAP_COMPONENTS) = CD_ZERO
    ! exp(-2 jonswap_k wtrdpth), fixed with the table (CD_Component_Wave_Kinematics exp_m2kd)
    REAL(wp) :: jonswap_e2kd(CD_JONSWAP_COMPONENTS) = CD_ZERO
    REAL(wp) :: jonswap_amplitude(CD_JONSWAP_COMPONENTS) = CD_ZERO
    ! Random-phase, bin-jittered JONSWAP synthesis (OPTION WaveSeed, a positive integer;
    ! the same seed always gives the same sea).
    REAL(wp) :: jonswap_phase(CD_JONSWAP_COMPONENTS) = CD_ZERO
    INTEGER :: wave_seed = 1
    ! Spectral and multi-train seas (CableDyn_WaveSpectra): wavetrain rows accumulate in
    ! sea%trains; a single-train waves row of a new spectrum is held in wave_train;
    ! OPTION WaveSpreading spreads the waves-row spectral train (resolve_deck_sea).
    TYPE(CD_SeaType) :: sea
    TYPE(CD_WaveTrainType) :: wave_train
    REAL(wp) :: wave_spreading = CD_ZERO
    ! Stream-function wave (stream H T dir waves) and its Fourier order (OPTION StreamOrder,
    ! 0 = default)
    TYPE(CD_StreamWaveType) :: stream
    INTEGER :: stream_order = 0
    ! Modal analysis (OPTION nModes): the N lowest modes of every line about its static
    ! equilibrium, written to <root>.modes.out; 0 = off.
    INTEGER :: n_modes = 0
    ! Start-up wave ramp (OPTION rampTime, s): the wave amplitudes rise with a half-cosine
    ! from still water at t = 0 to full height at t = rampTime; 0 = no ramp.
    REAL(wp) :: ramp_time = CD_ZERO
    ! Per-step plausibility guard (OPTION maxStrain): a committed dynamic state with any
    ! element stretched beyond this strain (or non-finite) fails the run; 0 disables.
    REAL(wp) :: max_strain = 0.5_wp
    ! WaveKinMod-1 elevation history reduced once to its real Fourier components.
    ! These feed the same arbitrary-component Airy kernel used by reference-matched
    ! irregular seas; wave_eta_mean carries the zero-frequency waterline offset.
    REAL(wp), ALLOCATABLE :: wave_component_omega(:), wave_component_k(:)
    REAL(wp), ALLOCATABLE :: wave_component_amplitude(:), wave_component_phase(:)
    REAL(wp) :: wave_eta_mean = CD_ZERO
    ! N-level vertical current profile (ascending z): from the two-point deck
    ! OPTION row or a MoorDyn WaterKin file's CurrentMod-1 depth table.
    REAL(wp), ALLOCATABLE :: current_profile_z(:)
    REAL(wp), ALLOCATABLE :: current_profile_velocity(:, :)
    REAL(wp) :: friction_mu = CD_ZERO
    ! Anisotropic seabed friction (frictionMuAxial / frictionMuLateral rows, resolved by
    ! resolve_deck_friction): friction_mu is the lateral coefficient and friction_mu_axial
    ! the one along the line; -1 = isotropic (frictionMu alone).
    REAL(wp) :: friction_mu_axial = -1.0_wp
    REAL(wp) :: friction_mu_axial_row = -1.0_wp, friction_mu_lateral_row = -1.0_wp
    LOGICAL  :: has_wtrdpth = .FALSE.
    LOGICAL  :: has_bathymetry_file = .FALSE.
    LOGICAL  :: has_dtm = .FALSE., has_tmax = .FALSE.
    LOGICAL  :: has_motion_file = .FALSE.
    ! Source of the prescribed motion when has_motion_file: MOTION_POINT_ROWS (motionFile),
    ! MOTION_VESSEL_FILE (vesselMotion 6-DOF record) or MOTION_VESSEL_RAO (vesselRAO table
    ! driven by the deck waves). motion_file then holds the vessel record or RAO table path.
    INTEGER  :: motion_kind = 0
    REAL(wp) :: vessel_ref(3) = CD_ZERO
    LOGICAL  :: has_current = .FALSE.
    LOGICAL  :: has_current_profile = .FALSE.
    ! MoorDyn WaterKin OPTION: a filename declaring file-driven water kinematics
    ! for STANDALONE runs (coupled runs consume SeaState).
    CHARACTER(CD_DECK_PATHLEN) :: waterkin_file = ''
    LOGICAL  :: has_waterkin_file = .FALSE.
    ! The WaveKinFile the WaterKin file names, resolved (blank when none is read).
    CHARACTER(CD_DECK_PATHLEN) :: waterkin_wave_file = ''
    ! Parsed WaterKin provenance. -1 means no resolved WaterKin policy; 0/1/2
    ! retain the independent WaveKinMod/CurrentMod values. Do not infer these
    ! from has_wave/has_current_profile: ordinary deck OPTION rows share those
    ! aggregate flags and may legally coexist with a WaterKin file.
    INTEGER  :: waterkin_wave_mode = -1
    INTEGER  :: waterkin_current_mode = -1
    ! MoorDyn-C numeric WaveKin / Currents OPTIONS (0: none): WaveKin 3 reads wave_elevation.txt,
    ! WaveKin 7 wave_frequencies.txt, Currents 1 current_profile.txt, all in the deck folder
    ! (read_moordyn_c_kinematics); dtWave is the WaveKin 3 resampling step.
    INTEGER  :: mdc_wave_kin = 0
    INTEGER  :: mdc_currents = 0
    REAL(wp) :: mdc_dt_wave = 0.25_wp
    LOGICAL  :: waterkin_seastate = .FALSE.
    LOGICAL  :: waterkin_host_wave = .FALSE.
    LOGICAL  :: waterkin_host_current = .FALSE.
    LOGICAL  :: has_wave = .FALSE.
    LOGICAL  :: wave_cache_ready = .FALSE.
    LOGICAL  :: has_friction = .FALSE.
    LOGICAL  :: dynamic_modified_newton = .FALSE.
    ! Coupled-comparison control. The finite-EI cable is always solved and its
    ! channels remain available; FALSE suppresses only its reaction at the host
    ! moving-point boundary. The default preserves ordinary two-way coupling.
    LOGICAL  :: cable_load_feedback = .TRUE.
    ! Opt-in adaptive mesh for COUPLED finite-EI cables: when set, a cable whose static IC is
    ! diagnosed under-resolved (CD_HermiteCable_Resolution_Metrics fragile) is refined by
    ! warm-started cubic-Hermite prolongation before the coupled dynamic run. Default FALSE keeps
    ! the deck's NumSegs exactly (bit-for-bit), since the h*kappa target is deliberately
    ! conservative and would refine adequately-converging coarse decks.
    LOGICAL  :: adaptive_mesh = .FALSE.
    ! Generalised-alpha blend of the finite-EI dynamics (alpha_force_blend): force blend
    ! (default) or the configuration blend f_int(q_alpha_f).
    LOGICAL  :: alpha_force_blend = CD_HC_FORCE_BLEND_DEFAULT
    ! Finite-EI static route order (cable_statics): 'continuation' (default) solves the
    ! catenary-seeded EI continuation first and the mesh-sequenced route as its fallback;
    ! 'sequenced' runs the mesh-sequenced route first.
    LOGICAL  :: cable_statics_sequenced = .FALSE.
    INTEGER  :: tensile_mode = CD_HCDYN_TENSILE_OFF
    REAL(wp) :: tensile_strain_tolerance = 2.0e-6_wp
    ! HOST-DRIVEN AMBIENT FLUID (not a deck keyword): set by CD_Init_Deck_Aggregate when
    ! the coupled host (the OpenFAST shell sampling a SeaState WaveField) will prescribe
    ! per-node fluid kinematics each step. The EI=0 line models are then built with the
    ! FULL wave-capable hydro set (drag + Froude-Krylov + added mass + wetting waterlines)
    ! at ZERO initial fields -- exactly zero added load until the host writes fields, so
    ! the build is response-identical to the plain one until driven.
    LOGICAL  :: external_fluid = .FALSE.
    ! host_coupled_objects: a coupled host (the CompMooring=5 aggregate) drives Coupled/Vessel RODS
    ! and BODIES through its moving mesh, so they need no motionFile (parse_deck's argument).
    LOGICAL  :: host_coupled_objects = .FALSE.
    ! bodyIC: free Rigid6 bodies and rods start at their static equilibrium (default) or at
    ! the deck pose
    LOGICAL :: body_ic_static = .TRUE.
    ! bodyWetting moordyn: Rigid6 bodies fully wet at any elevation (MoorDyn); default sphere
    LOGICAL :: body_wetting_moordyn = .FALSE.
    ! bodyScheme staggered: the staggered body/point coupling (explicit object predictor,
    ! sub-cycled, explicit Free/Connect points); default monolithic implicit generalised-alpha
    LOGICAL :: body_scheme_staggered = .FALSE.
    ! the deck names bodyScheme monolithic (a deck without lines steps on the monolithic march
    ! only then)
    LOGICAL :: body_scheme_monolithic_named = .FALSE.
    ! bodySubstep accuracy: the monolithic step sub-steps to omega*dt <= ACCURACY_OMEGA_DT for the
    ! stiffest object-mooring mode (default; the step is stable without it, none takes dtM as given)
    LOGICAL :: body_substep_accuracy = .TRUE.
    ! bodyHydro moordyn: no fluid-inertia (Froude-Krylov) force on Rigid6 bodies (MoorDyn)
    LOGICAL :: body_hydro_moordyn = .FALSE.
    ! rodHydro moordyn: add MoorDyn's surface-piercing rod moment (net waterplane stiffness
    ! rhoW g pi d^4/32 above the exact second moment)
    LOGICAL :: rod_hydro_moordyn = .FALSE.
    ! standalone TURBINES section: reference position and initial displacement per turbine J
    INTEGER :: n_turb = 0
    REAL(wp), ALLOCATABLE :: turb_ref(:, :), turb_ptfm(:, :)
    ! zero-length rods (NumSegs 0) collapsed to connector points: rod id -> point id
    INTEGER, ALLOCATABLE :: zl_rod(:), zl_point(:)
    INTEGER :: wave_kind = WAVE_NONE
    CHARACTER(CD_DECK_PATHLEN) :: motion_file = ''
    CHARACTER(CD_DECK_PATHLEN) :: bathymetry_file = ''
  END TYPE

  TYPE :: HydroUpdateWorkspace
    REAL(wp), ALLOCATABLE :: q(:), v(:), a(:)
    REAL(wp), ALLOCATABLE :: fluid_velocity(:, :), fluid_acceleration(:, :), waterline(:)
  END TYPE

  TYPE :: ModelOutputWorkspace
    REAL(wp), ALLOCATABLE :: q(:), v(:), a(:), tension(:)
    ! Row-output plan for the dynamic .out writers: every channel name is resolved
    ! once into a descriptor (kind, line, node, component, aux), and each line's
    ! state and tensions are fetched at most once per output row. Rows are keyed by
    ! the counter `row`; a line cache is valid when its stamp equals that counter.
    LOGICAL :: plan_ready = .FALSE.
    LOGICAL :: plan_motion = .FALSE.
    INTEGER :: row = 0
    INTEGER, ALLOCATABLE :: ch_kind(:), ch_line(:), ch_node(:), ch_comp(:), ch_aux(:)
    REAL(wp), ALLOCATABLE :: ch_val(:)
    INTEGER, ALLOCATABLE :: line_ndof(:), line_ne(:), state_off(:), ten_off(:)
    INTEGER, ALLOCATABLE :: state_row(:), ten_row(:)
    REAL(wp), ALLOCATABLE :: line_q(:), line_v(:), line_a(:), line_ten(:)
    ! Range graphs and touchdown channels of the run (sized by range_setup_planned; every
    ! row samples the lines that need it before the channels are evaluated).
    TYPE(CD_RangeSet) :: rset
  END TYPE

  TYPE :: LineStepWorkspace
    REAL(wp), ALLOCATABLE :: q(:), v(:), a(:)
    INTEGER, ALLOCATABLE :: coupled_dofs(:)
  END TYPE

  TYPE :: MotionTable
    INTEGER :: n_time = 0, n_point = 0
    INTEGER, ALLOCATABLE :: point_ids(:)
    REAL(wp), ALLOCATABLE :: time(:)
    REAL(wp), ALLOCATABLE :: q(:, :, :)
    REAL(wp), ALLOCATABLE :: v(:, :, :)
    REAL(wp), ALLOCATABLE :: a(:, :, :)
    ! Vessel rotation (vesselMotion/vesselRAO): vessel-to-global R(3,3,t) and the global-axis
    ! angular velocity and acceleration (3,t); an end connection on a vessel point turns with R.
    LOGICAL :: has_rot = .FALSE.
    REAL(wp), ALLOCATABLE :: rot(:, :, :), omega(:, :), alpha(:, :)
    ! Roll column of motionFile point rows (read only on a deck with a torsional line): roll(p, t)
    ! [rad] of the line end frames at point p about their directors, added to the END
    ! CONNECTIONS Pretwist of those ends; has_roll when some row gives one.
    LOGICAL :: has_roll = .FALSE.
    REAL(wp), ALLOCATABLE :: roll(:, :)
  END TYPE

  TYPE :: DriverProgress
    INTEGER :: nstep = 0
    INTEGER :: report_stride = 1
    INTEGER(int64) :: start_count = 0_int64
    INTEGER(int64) :: count_rate = 0_int64
  END TYPE

  TYPE :: RodState
    INTEGER :: rod_id = 0
    INTEGER :: point_a_index = 0
    INTEGER :: point_b_index = 0
    LOGICAL :: is_free = .FALSE.
    LOGICAL :: is_prescribed = .FALSE.
    ! Pinned rod: End A held at pin, the rod turns about it (three rotational DOFs)
    LOGICAL :: is_pinned = .FALSE.
    REAL(wp) :: pin(3) = CD_ZERO
    ! Rod pinned to a body (Body<N>Pinned): the index of the parent body in the march's body
    ! states and the pin (End A) in the body frame; pin then follows the body
    INTEGER :: parent = 0
    REAL(wp) :: pin_body(3) = CD_ZERO
    REAL(wp) :: r(3) = CD_ZERO, v(3) = CD_ZERO, a(3) = CD_ZERO
    REAL(wp) :: rot_mat(3, 3) = CD_ZERO
    REAL(wp) :: omega(3) = CD_ZERO, alpha(3) = CD_ZERO
    REAL(wp) :: mass = CD_ZERO, volume = CD_ZERO
    REAL(wp) :: diam = CD_ZERO, length = CD_ZERO, half_length = CD_ZERO
    REAL(wp) :: cdn = CD_ZERO, cdt = CD_ZERO, can = CD_ZERO, cat = CD_ZERO
    REAL(wp) :: cdend = CD_ZERO, caend = CD_ZERO
    ! NumSegs: the hydrodynamic segments of rod_environment_force
    INTEGER :: nsegs = 1
    REAL(wp) :: inertia(3) = CD_ZERO
    ! Whether a/alpha hold the committed acceleration (see RigidBodyState%accel_valid).
    LOGICAL :: accel_valid = .FALSE.
    ! Host fields sampled at the NumSegs + 1 segment stations s_j = -L/2 + j L/NumSegs
    ! (j = 0..NumSegs, End A to End B); rod_environment_force interpolates them linearly
    ! along the rod. held_pd is the wave dynamic pressure per unit density at the stations
    ! (has_held_pd: the host supplied it; the end caps then carry it). They are refreshed
    ! every coupled step and are not checkpoint state.
    REAL(wp), ALLOCATABLE :: held_vel(:, :), held_acc(:, :)
    REAL(wp), ALLOCATABLE :: held_eta(:), held_pd(:)
    LOGICAL :: has_held = .FALSE.
    LOGICAL :: has_held_pd = .FALSE.
  END TYPE

  TYPE :: RigidBodyState
    INTEGER :: body_id = 0
    INTEGER :: body_index = 0
    ! Host-driven (Coupled/Vessel) body: its state is imposed, never integrated.
    LOGICAL :: is_prescribed = .FALSE.
    INTEGER, ALLOCATABLE :: point_indices(:)
    REAL(wp) :: r_ref(3) = CD_ZERO
    REAL(wp) :: rot_ref(3, 3) = CD_ZERO
    REAL(wp) :: r(3) = CD_ZERO, v(3) = CD_ZERO, a(3) = CD_ZERO
    REAL(wp) :: eta(3) = CD_ZERO, omega(3) = CD_ZERO, alpha(3) = CD_ZERO
    REAL(wp) :: rot_mat(3, 3) = CD_ZERO
    REAL(wp) :: mass = CD_ZERO, vol = CD_ZERO
    REAL(wp) :: cda = CD_ZERO, ca = CD_ZERO
    REAL(wp) :: inertia(3) = CD_ZERO
    REAL(wp) :: c33 = CD_ZERO, c44 = CD_ZERO, c55 = CD_ZERO
    ! centres of gravity and buoyancy in the body frame, relative to the reference point
    REAL(wp) :: cg(3) = CD_ZERO, cb(3) = CD_ZERO
    ! EXTERNAL LOADS (see DeckBody): column 1 global frame, column 2 body frame
    REAL(wp) :: ext_f(3, 2) = CD_ZERO, ext_blin(3, 2) = CD_ZERO, ext_bquad(3, 2) = CD_ZERO
    ! Whether a/alpha hold the committed acceleration of the current state (set by the first
    ! free step, a checkpoint restore, or a prescribed row). A free step computes it first
    ! when unset, so the central-difference predictor starts from the actual a_0.
    LOGICAL :: accel_valid = .FALSE.
    ! Host-driven ambient fluid at the body reference point (the coupled fluid contract):
    ! when has_held, rigid6_environment_force uses these instead of the deck's own wave/current
    ! model. Set each mooring step by CD_Rigid6_SetHeldFluid from the aggregate SeaState sample;
    ! transient per-step input (re-set every advance), NOT part of the 24-real checkpoint mirror.
    REAL(wp) :: held_vel(3) = CD_ZERO, held_acc(3) = CD_ZERO, held_eta = CD_ZERO
    LOGICAL :: has_held = .FALSE.
    ! Rods fixed to the body (RODS type Body<N>): their states follow the body pose; att_c is
    ! each rod centre and att_rot its orientation in the body frame (from the reference point).
    TYPE(RodState), ALLOCATABLE :: att_rods(:)
    REAL(wp), ALLOCATABLE :: att_c(:, :), att_rot(:, :, :)
  END TYPE

  TYPE :: RodStepWorkspace
    REAL(wp), ALLOCATABLE :: q(:), v(:), a(:), loads(:)
    REAL(wp), ALLOCATABLE :: dload_da(:, :)
    TYPE(RodState), ALLOCATABLE :: old_rods(:)
    TYPE(CD_SystemPointType), ALLOCATABLE :: old_points(:)
  END TYPE

  TYPE :: RigidStepWorkspace
    REAL(wp), ALLOCATABLE :: q(:), v(:), a(:), loads(:)
    REAL(wp), ALLOCATABLE :: dload_da(:, :)
    REAL(wp), ALLOCATABLE :: f_env(:, :), mass_eff(:)
    TYPE(RigidBodyState), ALLOCATABLE :: old_rigid(:)
    TYPE(CD_SystemPointType), ALLOCATABLE :: old_points(:)
  END TYPE

  !> State of the standalone multibody march (write_multibody_dynamic_out): Rigid6 bodies (with
  !> their fixed rods), free, pinned and fixed rods (including rods pinned to a body), the EI=0
  !> line system with its Free/Connect points, and the finite-EI cables with their attachments.
  ! bodySubstep accuracy: largest omega*dt of the stiffest object-mooring mode per monolithic step:
  ! 0.4/sqrt(2), the phase accuracy of the staggered sub-steps (omega*dt <= 0.4 with the central
  ! difference error constant 1/24) with the trapezoidal object block (error constant 1/12)
  REAL(wp), PARAMETER :: ACCURACY_OMEGA_DT = 0.28_wp
  ! Newton tolerance of a cable clamped to a body or rod (re-stepped in the monolithic outer
  ! Newton, so its end loads must be converged well inside the junction tolerance)
  REAL(wp), PARAMETER :: CLAMPED_CABLE_TOL = 1.0e-8_wp
  TYPE :: MultibodyMarch
    LOGICAL :: has_sys = .FALSE., has_dyn = .FALSE., started = .FALSE.
    TYPE(CD_SystemType) :: system
    TYPE(CD_HFMF_ModuleType), ALLOCATABLE :: cables(:)
    ! cable End A attachment: kind 1 body (cab_obj body index, cab_off body-frame offset),
    ! 2 rod end (cab_obj rod index, cab_off(1) = -1 End A, +1 End B), 0 held point
    INTEGER, ALLOCATABLE :: cab_kind(:), cab_obj(:), cable_points(:, :)
    REAL(wp), ALLOCATABLE :: cab_off(:, :), cab_force(:, :)
    ! cab_clamp: End A carries a Rigid or elastic END CONNECTION on its body or rod; its end
    ! tangent then follows the object orientation, the cable is re-stepped at every outer
    ! iteration of the monolithic step (implicit coupling, its end stiffness in the Jacobian) and
    ! its end moment returns to the object. cab_force/cab_moment: the loads the junction residual
    ! applies (alpha level for a clamped cable); cab_fend/cab_mend: the committed end loads of
    ! the last step (outputs); cab_f0/cab_m0: those at the step entry. Rebuilt every step from
    ! the committed cable states; no state of their own.
    LOGICAL, ALLOCATABLE :: cab_clamp(:)
    REAL(wp), ALLOCATABLE :: cab_moment(:, :), cab_fend(:, :), cab_mend(:, :), cab_f0(:, :), cab_m0(:, :)
    LOGICAL, ALLOCATABLE :: line_is_cable(:)
    INTEGER, ALLOCATABLE :: line_obj_index(:)
    TYPE(RigidBodyState), ALLOCATABLE :: rigid(:), old_rigid(:)
    TYPE(RodState), ALLOCATABLE :: rods(:), old_rods(:)
    REAL(wp), ALLOCATABLE :: q(:), v(:), a(:), loads(:), dload_da(:, :)
    REAL(wp), ALLOCATABLE :: acc_b(:, :), alpha_b(:, :), acc_r(:, :), alpha_r(:, :)
    ! bodyScheme monolithic (mb_step_implicit): junction layout (mb_junction_layout), step-entry
    ! coupled motion and point states, the lines' alpha-level end loads and condensed tangent,
    ! the attachment map and the alpha-level evaluation states; counters for the outer
    ! iterations and step halvings. All of it is rebuilt every step from the committed states.
    LOGICAL :: implicit = .FALSE.
    INTEGER :: nj = 0, ng = 0
    INTEGER :: n_outer = 0, max_outer = 0, n_steps_imp = 0, n_subdiv = 0
    ! condensed line tangent reuse: steps since the last refresh and the last step's outer count
    INTEGER :: tan_age = HUGE(1), last_outer = 0, n_refresh = 0
    INTEGER, ALLOCATABLE :: jb_off(:), jr_off(:), jp_off(:), g_kind(:), g_idx(:), g_lo(:), g_hi(:)
    LOGICAL, ALLOCATABLE :: jactive(:), is_rot(:)
    ! jobj: coupled DOFs driven by a body or rod (the objects' trapezoidal levels at the line
    ! ends); jbeta: the Newmark beta of each junction coordinate
    LOGICAL, ALLOCATABLE :: jobj(:)
    REAL(wp), ALLOCATABLE :: jbeta(:)
    INTEGER, ALLOCATABLE :: jact_idx(:)
    REAL(wp), ALLOCATABLE :: q0(:), v0(:), a0(:), floads(:), fabs(:), kline(:, :), gam(:, :)
    TYPE(CD_SystemPointType), ALLOCATABLE :: old_points(:), pt_af(:)
    TYPE(RigidBodyState), ALLOCATABLE :: rig_af(:)
    TYPE(RodState), ALLOCATABLE :: rod_af(:)
  END TYPE

  !> Opaque runtime bundle that lets the OpenFAST CompMooring=5 aggregate own and march
  !> Rigid6 bodies over its EI=0 system without seeing the private RigidBodyState /
  !> DeckOptions / DeckPoint internals. Populated by CD_Init_Deck_Aggregate_Rigid6 and
  !> advanced by CD_Step_Aggregate_Rigid6; snap_rigid carries the correction-rewind twin.
  TYPE :: CD_Rigid6RuntimeType
    PRIVATE
    TYPE(DeckOptions) :: opts
    TYPE(DeckPoint), ALLOCATABLE :: points(:)
    TYPE(RigidBodyState), ALLOCATABLE :: rigid(:)
    TYPE(RigidBodyState), ALLOCATABLE :: snap_rigid(:)
    TYPE(RigidStepWorkspace) :: work
    ! Coupled/Vessel bodies driven by the host (one 6-DOF host node each, at the reference
    ! point): host_body(k) is the body index of host node k, host_rrel(:, :, k) the body frame
    ! in host axes (O0 R0, constant), host_o0 the host orientation at Init. stage_rigid holds
    ! the pre-transfer bodies of a staged step.
    INTEGER, ALLOCATABLE :: host_body(:)
    REAL(wp), ALLOCATABLE :: host_rrel(:, :, :)
    REAL(wp) :: host_o0(3, 3) = CD_ZERO
    TYPE(RigidBodyState), ALLOCATABLE :: stage_rigid(:)
  END TYPE

  !> Opaque runtime bundle that lets the OpenFAST CompMooring=5 aggregate own and march rigid
  !> RODS over its EI=0 system without seeing the private RodState / DeckOptions / DeckPoint
  !> internals -- the rod twin of CD_Rigid6RuntimeType. Populated by CD_Init_Deck_Aggregate_Rod
  !> and advanced by CD_Step_Aggregate_Rod; snap_rods carries the correction-rewind twin.
  TYPE :: CD_RodRuntimeType
    PRIVATE
    TYPE(DeckOptions) :: opts
    TYPE(DeckPoint), ALLOCATABLE :: points(:)
    TYPE(RodState), ALLOCATABLE :: rods(:)
    TYPE(RodState), ALLOCATABLE :: snap_rods(:)
    TYPE(RodStepWorkspace) :: work
    ! Coupled/Vessel rods driven by the host (one 6-DOF host node each, at End A):
    ! host_rod(k) is the rod index of host node k, host_rrel(:, :, k) the rod frame in host
    ! axes (O0 R0, constant), host_o0 the host orientation at Init (used when a caller
    ! supplies no orientation). stage_rods holds the pre-transfer rods of a staged step.
    INTEGER, ALLOCATABLE :: host_rod(:)
    REAL(wp), ALLOCATABLE :: host_rrel(:, :, :)
    REAL(wp) :: host_o0(3, 3) = CD_ZERO
    TYPE(RodState), ALLOCATABLE :: stage_rods(:)
  END TYPE

  TYPE :: FiniteDeckModel
    TYPE(CD_FiniteEIModelType) :: model
    INTEGER :: n_elem = 0
    LOGICAL :: has_seabed = .FALSE.
    LOGICAL :: has_bathymetry = .FALSE.
    REAL(wp) :: seabed_z_floor = CD_ZERO
    TYPE(CD_BathymetryType) :: bathymetry
    REAL(wp), ALLOCATABLE :: l0(:)
    REAL(wp), ALLOCATABLE :: ea(:)
    REAL(wp), ALLOCATABLE :: ei(:)
    REAL(wp), ALLOCATABLE :: base_f_ext(:)
    REAL(wp), ALLOCATABLE :: diam(:)
    REAL(wp), ALLOCATABLE :: cdn(:)
    REAL(wp), ALLOCATABLE :: cdt(:)
    REAL(wp), ALLOCATABLE :: can(:)
    REAL(wp), ALLOCATABLE :: cat(:)
    REAL(wp), ALLOCATABLE :: seabed_kn(:)
    REAL(wp), ALLOCATABLE :: seabed_cn(:)
    REAL(wp), ALLOCATABLE :: q_work(:), v_work(:), a_work(:)
    REAL(wp), ALLOCATABLE :: f_ext_work(:), contact_work(:), env_work(:)
    REAL(wp), ALLOCATABLE :: q_fixed_work(:), v_fixed_work(:), a_fixed_work(:)
    INTEGER, ALLOCATABLE :: free_map_work(:)
  END TYPE

  TYPE :: CD_LineInitSummary
    !! Engineering quantities at the converged static initial condition.  The
    !! fairlead force is the force exerted by the line on public End A and the
    !! tangent/angles point from End A (fairlead) toward End B (anchor).
    INTEGER :: line_id = 0
    REAL(wp) :: fair_tension = CD_ZERO
    REAL(wp) :: fair_force(3) = CD_ZERO
    REAL(wp) :: fair_inclination = CD_ZERO
    REAL(wp) :: fair_declination = CD_ZERO
    REAL(wp) :: fair_azimuth = CD_ZERO
    LOGICAL :: force_is_total = .TRUE.
    ! Static-initialisation notes of a finite-EI line (compression, mesh refinement,
    ! accepted residual floor), one per text line; empty when there is nothing to report.
    CHARACTER(1024) :: note = ''
  END TYPE CD_LineInitSummary

  TYPE :: CD_DeckAggregateType
    !! Transient bundle returned by CD_Init_Deck_Aggregate: the EI=0 mooring SYSTEM
    !! (valid iff has_sys) built from the deck's EI=0 line subset, plus one built
    !! coupled Hermite cable per finite-EI line, with the resolved environment. This
    !! is the raw partition the OpenFAST aggregate facade wraps -- it wraps `sys` into a
    !! CD_FMF module and MOVE_ALLOCs `cables` into its own store. Kept free of any
    !! OpenFAST_FMF dependency so CableDyn_DeckDriver stays below the FMF layer (the FMF
    !! module USEs this one). CD_End_Deck_Aggregate releases whatever the facade did not
    !! take ownership of.
    LOGICAL :: has_sys = .FALSE.
    ! FAST.Farm: number of turbines (0 = single-turbine/plain mode) and, per moving
    ! slot in the aggregate moving-set order, the turbine that drives it.
    INTEGER :: n_turbines = 0
    ! Host SeaState selectors retained from independent WaterKin wave/current modes.
    ! When external_fluid is requested without an explicit host WaterKin mode, both
    ! default true for backward-compatible direct SeaState sampling.
    LOGICAL :: host_wave_enabled = .FALSE.
    LOGICAL :: host_current_enabled = .FALSE.
    LOGICAL :: cable_load_feedback = .TRUE.
    ! OPTION maxStrain, for the per-step plausibility guard of the coupled EI=0 lines.
    REAL(wp) :: max_strain = 0.5_wp
    REAL(wp), ALLOCATABLE :: host_current_profile_z(:)
    REAL(wp), ALLOCATABLE :: host_current_profile_velocity(:, :)
    INTEGER, ALLOCATABLE :: turbine_of_moving(:)
    ! Parsed inventory and unconditional converged-static fairlead report.  These
    ! are independent of the optional OUTPUTS list so an initialization log never
    ! hides a line merely because the user did not request a time-history channel.
    INTEGER :: n_lines = 0, n_points = 0, n_sections = 0
    INTEGER :: n_ei0_lines = 0, n_finite_ei_lines = 0
    TYPE(CD_LineInitSummary), ALLOCATABLE :: init_lines(:)
    TYPE(CD_SystemType) :: sys
    TYPE(CD_HFMF_ModuleType), ALLOCATABLE :: cables(:)
    ! Static-initialisation notes of each finite-EI cable (build_one_hermite_cable).
    CHARACTER(1024), ALLOCATABLE :: cable_note(:)
    ! Deck point ids of each cable's End A and End B (Point<P>F channels).
    INTEGER, ALLOCATABLE :: cable_points(:, :)
    REAL(wp) :: gravity = CD_ZERO, rho_water = CD_ZERO
    ! Deck OUTPUTS channels (already validated by parse_deck -> check_channel) plus the
    ! deck-line-id -> object map the OpenFAST shell needs to resolve a channel's line id to
    ! either an EI=0 system line (line_is_cable = .FALSE., index = system line index) or a
    ! finite-EI cable (line_is_cable = .TRUE., index = cable index). Both map arrays are
    ! indexed directly by deck line id (1 .. max deck line id); line_obj_index = 0 marks an
    ! id with no line. Populated only when the deck declares OUTPUTS (channels present);
    ! otherwise left unallocated and the coupled run emits no CableDyn channels.
    CHARACTER(NAMELEN), ALLOCATABLE :: channels(:)
    LOGICAL, ALLOCATABLE :: line_is_cable(:)
    INTEGER, ALLOCATABLE :: line_obj_index(:)
    ! FAILURE rows plus the deck lines/points the trigger needs at run time
    ! (attachment-end resolution + the reserve-id rule). Populated only for a
    ! failure-declaring deck (pure EI=0, non-farm); the facade owns firing them.
    TYPE(DeckFailure), ALLOCATABLE :: failures(:)
    TYPE(DeckLine), ALLOCATABLE :: fail_lines(:)
    TYPE(DeckPoint), ALLOCATABLE :: fail_points(:)
    ! Active line control (CONTROL section), flattened per controlled line: the
    ! host channel, the system line index, the LAST (fairlead-side) element, and
    ! its base unstretched length -- l(N) = base + DeltaL(chan) each advance.
    INTEGER :: n_ctrl_chans = 0
    INTEGER, ALLOCATABLE :: ctrl_chan(:)
    INTEGER, ALLOCATABLE :: ctrl_line(:)
    INTEGER, ALLOCATABLE :: ctrl_elem(:)
    REAL(wp), ALLOCATABLE :: ctrl_base_l0(:)
    ! Coupled Rigid6 bodies (pure EI=0 deck): the opaque runtime the facade marches over
    ! `sys` each mooring step. Populated only when the deck declares Rigid6 BODYs
    ! (has_rigid6); the facade MOVEs it onto its persistent module state.
    LOGICAL :: has_rigid6 = .FALSE.
    TYPE(CD_Rigid6RuntimeType) :: rigid6
    ! Coupled rigid RODS (pure EI=0 deck): the rod twin of the Rigid6 runtime above, marched over
    ! `sys` each mooring step. Populated only when the deck declares RODs (has_rod).
    LOGICAL :: has_rod = .FALSE.
    TYPE(CD_RodRuntimeType) :: rod
    ! Range graphs (LINES flag r, standalone only) and the touchdown references of the
    ! TDP<L> channels, keyed by deck line id and fixed at the converged initial state.
    TYPE(CD_RangeSet) :: ranges
  END TYPE

CONTAINS

  SUBROUTINE CD_Init_Deck_Models(deck_path, models, ErrStat, ErrMsg)
    !! Parse a supported MoorDyn-style deck and initialize one persistent
    !! CableDyn model per LINE. This is the production lifecycle bridge over the
    !! same parser/validation contract used by the standalone `.out` driver:
    !! supported EI=0 Fixed->Coupled/Vessel line objects become CD_ModelType
    !! instances with static IC, seabed, resolved MoorDyn-convention BA damping, and Morison
    !! added mass configured when the deck supplies a water depth. The caller owns the models'
    !! time-varying inputs: a deck waves OPTION builds wave-capable models whose fluid fields
    !! stay zero until the caller drives CD_Update_Model_Hydro_Fields. A motionFile and
    !! WaterKin WaveKinMod 2/SEASTATE are rejected (nothing on this entry would apply them).
    CHARACTER(*), INTENT(IN) :: deck_path
    TYPE(CD_ModelType), ALLOCATABLE, INTENT(OUT) :: models(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    TYPE(DeckLineType), ALLOCATABLE :: types(:)
    TYPE(DeckBody), ALLOCATABLE :: bodies(:)
    TYPE(DeckRodType), ALLOCATABLE :: rod_types(:)
    TYPE(DeckRod), ALLOCATABLE :: rods(:)
    TYPE(DeckPoint), ALLOCATABLE :: points(:)
    TYPE(DeckLine), ALLOCATABLE :: lines(:)
    TYPE(DeckSection), ALLOCATABLE :: sections(:)
    TYPE(DeckOptions) :: opts
    CHARACTER(NAMELEN), ALLOCATABLE :: channels(:)
    TYPE(CD_BathymetryType) :: bathymetry
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (ALLOCATED(models)) DEALLOCATE (models)
    CALL parse_deck(deck_path, types, bodies, rod_types, rods, points, lines, sections, opts, channels, ErrStat, ErrMsg)
    IF (ErrStat /= 0) RETURN
    IF (deck_has_finite_ei(types, sections)) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Models returns EI=0 line models; finite-EI decks use CD_Run_Deck_Driver')
      RETURN
    END IF
    IF (deck_has_dynamic_points(points)) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Models returns independent line models; '// &
                'Connect/Free decks use CD_Run_Deck_Driver')
      RETURN
    END IF
    IF (SIZE(rods) > 0) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Models returns independent line models; '// &
                'rod decks use CD_Run_Deck_Driver')
      RETURN
    END IF
    IF (opts%has_motion_file) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Models does not apply a motionFile; the caller moves the '// &
                'line ends (or run the deck with CD_Run_Deck_Driver)')
      RETURN
    END IF
    IF (opts%waterkin_seastate) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Models cannot consume WaveKinMod 2/SEASTATE; use the '// &
                'OpenFAST aggregate with its external SeaState field')
      RETURN
    END IF
    ! Bathymetry, when declared, must be loaded and threaded into the per-line static IC on
    ! THIS lifecycle path too -- not only the standalone CD_Run_Deck_Driver. Each model
    ! deep-copies it (CD_Model_Init), so the local copy is released after init.
    IF (opts%has_bathymetry_file) THEN
      CALL load_bathymetry_file(path_join(deck_dir(deck_path), opts%bathymetry_file), bathymetry, ErrStat, ErrMsg, &
                                points=points)
      IF (ErrStat /= 0) RETURN
      CALL init_deck_models_from_parsed(types, points, lines, sections, opts, models, ErrStat, ErrMsg, &
                                        bathymetry=bathymetry)
      CALL CD_End_Bathymetry(bathymetry)
    ELSE
      CALL init_deck_models_from_parsed(types, points, lines, sections, opts, models, ErrStat, ErrMsg)
    END IF
  END SUBROUTINE CD_Init_Deck_Models

  SUBROUTINE CD_Init_Deck_System(deck_path, system, dtM, gravity, rho_water, ErrStat, ErrMsg, caller_driven, &
                                 env_gravity, env_rho_water, env_wtrdpth, line_ids)
    !! Parse a supported EI=0 deck and initialize one persistent multi-line
    !! CableDyn system with product-facing points and endpoint bindings.
    !! caller_driven (default .FALSE.): the host marches the system, so the deck's
    !! dtM/TMax standalone-marching pairing is not required (stock coupled decks
    !! declare dtM alone; simulation length belongs to the host).
    !! env_gravity / env_rho_water / env_wtrdpth: caller-supplied environment. A
    !! coupled host owns gravity, water density, and depth (MoorDyn-faithful:
    !! host values override deck-declared ones); a deck-declared bathymetryFile
    !! keeps its structured seabed over the host's flat depth.
    !! line_ids: the deck id of each system line (system line order = deck order).
    CHARACTER(*), INTENT(IN) :: deck_path
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    REAL(wp), INTENT(OUT) :: dtM, gravity, rho_water
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    LOGICAL, INTENT(IN), OPTIONAL :: caller_driven
    REAL(wp), INTENT(IN), OPTIONAL :: env_gravity, env_rho_water, env_wtrdpth
    INTEGER, ALLOCATABLE, INTENT(OUT), OPTIONAL :: line_ids(:)

    TYPE(DeckLineType), ALLOCATABLE :: types(:)
    TYPE(DeckBody), ALLOCATABLE :: bodies(:)
    TYPE(DeckRodType), ALLOCATABLE :: rod_types(:)
    TYPE(DeckRod), ALLOCATABLE :: rods(:)
    TYPE(DeckPoint), ALLOCATABLE :: points(:)
    TYPE(DeckLine), ALLOCATABLE :: lines(:)
    TYPE(DeckSection), ALLOCATABLE :: sections(:)
    TYPE(DeckOptions) :: opts
    CHARACTER(NAMELEN), ALLOCATABLE :: channels(:)
    TYPE(CD_BathymetryType) :: bathymetry
    LOGICAL :: ext_march
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    dtM = CD_ZERO
    gravity = CD_ZERO
    rho_water = CD_ZERO
    ext_march = .FALSE.
    IF (PRESENT(caller_driven)) ext_march = caller_driven
    ! The host environment is threaded into the PARSE so equivalent-buoyancy
    ! conversion and all validation (including the WtrDpth/kBot/cBot branch for an
    ! injected depth) run under the environment the model is built with.
    CALL parse_deck(deck_path, types, bodies, rod_types, rods, points, lines, sections, opts, channels, &
                    ErrStat, ErrMsg, caller_driven=ext_march, env_gravity=env_gravity, &
                    env_rho_water=env_rho_water, env_wtrdpth=env_wtrdpth)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    IF (opts%waterkin_seastate) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_System cannot consume WaveKinMod 2/SEASTATE; use the '// &
                'OpenFAST aggregate with its external SeaState field')
      RETURN
    END IF
    IF (opts%has_wave) THEN
      ! The embedded system has no simulation clock of its own, so deck waves could never be
      ! evaluated. Time-varying fluid kinematics enter through the point fluid-field update.
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_System does not apply deck waves; supply time-varying '// &
                'fluid kinematics with CableDyn_UpdatePointFluidFields')
      RETURN
    END IF
    dtM = MERGE(opts%dtM, CD_ZERO, opts%has_dtm)
    gravity = opts%g
    rho_water = opts%rhoW
    IF (deck_has_finite_ei(types, sections)) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_System returns EI=0 point systems; '// &
                'finite-EI decks use CD_Run_Deck_Driver')
      RETURN
    END IF
    IF (SIZE(bodies) > 0) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_System supports point systems; BODY decks use CD_Run_Deck_Driver')
      RETURN
    END IF
    IF (SIZE(rods) > 0) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_System supports point systems; ROD decks use CD_Run_Deck_Driver')
      RETURN
    END IF
    IF (opts%has_motion_file) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_System does not support motionFile point-system initialization')
      RETURN
    END IF
    IF (opts%has_bathymetry_file) THEN
      CALL load_bathymetry_file(path_join(deck_dir(deck_path), opts%bathymetry_file), bathymetry, ErrStat, ErrMsg, &
                                points=points)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL init_deck_system_from_parsed(types, points, lines, sections, opts, system, ErrStat, ErrMsg, &
                                        bathymetry=bathymetry)
      CALL CD_End_Bathymetry(bathymetry)
    ELSE
      CALL init_deck_system_from_parsed(types, points, lines, sections, opts, system, ErrStat, ErrMsg)
    END IF
    IF (PRESENT(line_ids) .AND. ErrStat == CD_DECKDRV_OK) THEN
      ALLOCATE (line_ids(SIZE(lines)))
      line_ids = lines(:)%id
    END IF
  END SUBROUTINE CD_Init_Deck_System

  SUBROUTINE init_deck_models_from_parsed(types, points, lines, sections, opts, models, ErrStat, ErrMsg, bathymetry)
    !! Initialize persistent line models from an already parsed and validated deck.
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(CD_ModelType), ALLOCATABLE, INTENT(OUT) :: models(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    INTEGER :: i, es
    CHARACTER(256) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    ALLOCATE (models(SIZE(lines)))
    DO i = 1, SIZE(lines)
      IF (PRESENT(bathymetry)) THEN
        CALL init_one_model(lines(i), sections, types, points, opts, models(i), es, em, bathymetry=bathymetry)
      ELSE
        CALL init_one_model(lines(i), sections, types, points, opts, models(i), es, em)
      END IF
      IF (es /= CD_DECKDRV_OK) THEN
        CALL end_models(models)
        ErrStat = es
        ! assignment truncates to the caller's buffer; a formatted internal WRITE of a long
        ! nested message would instead abort with an end-of-record runtime error
        ErrMsg = 'CableDyn_DeckDriver: line '//TRIM(int_to_str(lines(i)%id))//' (deck row '// &
                 TRIM(int_to_str(i))//') initialisation failed: '//TRIM(em)
        RETURN
      END IF
    END DO
  END SUBROUTINE init_deck_models_from_parsed

  SUBROUTINE init_deck_system_from_parsed(types, points, lines, sections, opts, system, ErrStat, ErrMsg, bathymetry, &
                                          failures)
    !! Initialize a dynamic point-connected EI=0 system from a parsed deck.
    !! Free/Connect points use Mass as inertial mass and a constant vertical
    !! force (rhoW*Vol - Mass)*g. CdA/Ca add lumped point hydrodynamics when
    !! current or regular Airy waves are active.
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    ! FAILURE rows: one INACTIVE reserve Free point is pre-allocated per row with
    ! id = (max deck point id) + row index -- the same deterministic rule the march
    ! trigger uses to address the reserve at detach time.
    TYPE(DeckFailure), INTENT(IN), OPTIONAL :: failures(:)

    TYPE(CD_ModelType), ALLOCATABLE :: models(:)
    TYPE(CD_SystemPointType), ALLOCATABLE :: sys_points(:)
    TYPE(CD_LineEndpointBinding), ALLOCATABLE :: bindings(:)
    TYPE(DeckPoint), ALLOCATABLE :: pts(:)
    INTEGER :: i, es, nres, maxid
    CHARACTER(256) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (deck_has_dynamic_points(points) .AND. opts%has_friction) THEN
      CALL fail(ErrStat, ErrMsg, 'seabed friction is not supported on decks with Connect/Free points, '// &
                'bodies or rods on this route (coupled Rigid6/ROD decks, point decks and the staggered '// &
                'body scheme); remove frictionMu')
      RETURN
    END IF
    ! Static initial condition of the point system: the Free/Connect points are first moved
    ! to their static force balance (each attached line re-solved for the moving ends), then
    ! every line model is initialized between the balanced end points, so the march starts
    ! from rest at equilibrium.
    pts = points
    IF (PRESENT(bathymetry)) THEN
      CALL solve_point_equilibrium(types, pts, lines, sections, opts, ErrStat, ErrMsg, bathymetry=bathymetry)
    ELSE
      CALL solve_point_equilibrium(types, pts, lines, sections, opts, ErrStat, ErrMsg)
    END IF
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      ErrMsg = 'CableDyn_DeckDriver: '//TRIM(ErrMsg)
      RETURN
    END IF
    IF (PRESENT(bathymetry)) THEN
      CALL init_deck_models_from_parsed(types, pts, lines, sections, opts, models, ErrStat, ErrMsg, &
                                        bathymetry=bathymetry)
    ELSE
      CALL init_deck_models_from_parsed(types, pts, lines, sections, opts, models, ErrStat, ErrMsg)
    END IF
    IF (ErrStat /= CD_DECKDRV_OK) RETURN

    nres = 0
    IF (PRESENT(failures)) nres = SIZE(failures)
    ALLOCATE (sys_points(SIZE(pts) + nres), bindings(2*SIZE(lines)))
    DO i = 1, SIZE(pts)
      sys_points(i)%id = pts(i)%id
      sys_points(i)%point_type = deck_point_type_to_system(pts(i)%ptype)
      sys_points(i)%q = pts(i)%pos
      sys_points(i)%v = CD_ZERO
      sys_points(i)%a = CD_ZERO
      sys_points(i)%mass = pts(i)%mass
      sys_points(i)%volume = pts(i)%vol
      sys_points(i)%cda = pts(i)%cda
      sys_points(i)%ca = pts(i)%ca
      sys_points(i)%force = [CD_ZERO, CD_ZERO, (opts%rhoW*pts(i)%vol - pts(i)%mass)*opts%g]
    END DO
    IF (nres > 0) THEN
      maxid = 0
      DO i = 1, SIZE(pts)
        maxid = MAX(maxid, pts(i)%id)
      END DO
      DO i = 1, nres
        sys_points(SIZE(pts) + i)%id = maxid + i
        sys_points(SIZE(pts) + i)%point_type = CD_POINT_FREE
        sys_points(SIZE(pts) + i)%active = .FALSE.
        sys_points(SIZE(pts) + i)%q = CD_ZERO
        sys_points(SIZE(pts) + i)%v = CD_ZERO
        sys_points(SIZE(pts) + i)%a = CD_ZERO
        sys_points(SIZE(pts) + i)%mass = CD_ZERO
        sys_points(SIZE(pts) + i)%volume = CD_ZERO
        sys_points(SIZE(pts) + i)%cda = CD_ZERO
        sys_points(SIZE(pts) + i)%ca = CD_ZERO
        sys_points(SIZE(pts) + i)%force = CD_ZERO
      END DO
    END IF
    DO i = 1, SIZE(lines)
      bindings(2*i - 1) = CD_LineEndpointBinding(line_index=i, line_end=CD_LINE_END_A, point_id=lines(i)%nodeB)
      bindings(2*i) = CD_LineEndpointBinding(line_index=i, line_end=CD_LINE_END_B, point_id=lines(i)%nodeA)
    END DO
    CALL CD_Init_System_From_Points(system, models, sys_points, bindings, es, em)
    CALL end_models(models)
    IF (es /= CD_SYSTEM_OK) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: point-connected system init failed: '//TRIM(em)
      RETURN
    END IF
  END SUBROUTINE init_deck_system_from_parsed

  SUBROUTINE init_finite_deck_models(types, points, lines, sections, opts, models, ErrStat, ErrMsg, bathymetry)
    !! Initialize persistent finite-EI dynamic line models from a parsed deck.
    !! This deck bridge supports held/prescribed translational endpoints, structural
    !! submerged weight, normal seabed contact, regularized seabed friction, and
    !! translational current/wave forcing.
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(FiniteDeckModel), ALLOCATABLE, INTENT(OUT) :: models(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    INTEGER :: i, es
    CHARACTER(256) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (.NOT. all_lines_have_finite_ei(types, lines, sections)) THEN
      CALL fail(ErrStat, ErrMsg, 'mixed EI=0 and finite-EI dynamic decks are not supported by this entry point')
      RETURN
    END IF

    ALLOCATE (models(SIZE(lines)))
    DO i = 1, SIZE(lines)
      IF (PRESENT(bathymetry)) THEN
        CALL init_one_finite_model(lines(i), sections, types, points, opts, models(i), es, em, bathymetry=bathymetry)
      ELSE
        CALL init_one_finite_model(lines(i), sections, types, points, opts, models(i), es, em)
      END IF
      IF (es /= CD_DECKDRV_OK) THEN
        CALL end_finite_models(models)
        ErrStat = es
        ErrMsg = em
        RETURN
      END IF
    END DO
  END SUBROUTINE init_finite_deck_models

  SUBROUTINE init_one_finite_model(ln, sections, types, points, opts, deck_model, ErrStat, ErrMsg, bathymetry)
    !! Initialize one finite-EI Cosserat dynamic model from a deck LINE.
    TYPE(DeckLine), INTENT(IN) :: ln
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(FiniteDeckModel), INTENT(INOUT) :: deck_model
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    TYPE(GenAlphaConfig) :: dynamic_cfg
    INTEGER, ALLOCATABLE :: conn(:, :), fixed_dofs(:)
    REAL(wp), ALLOCATABLE :: nodes_ref(:, :), q0(:), v0(:), f_ext(:), f3(:), contact_f(:)
    REAL(wp), ALLOCATABLE :: ea(:), gas(:), ei(:), gj(:), rho_a(:), i_rt(:), i_rn(:), diam(:), mpl(:)
    REAL(wp), ALLOCATABLE :: gas_in(:), gj_in(:), i_rt_in(:), i_rn_in(:)
    REAL(wp), ALLOCATABLE :: load_per_length(:, :), w(:)
    REAL(wp) :: anchor(3), fairlead(3)
    INTEGER :: pa, pb, es, nnode, ndof
    CHARACTER(200) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    ! This compatibility model prescribes both endpoint translations and predates
    ! the Hermite end-connection residual.  Never accept a declared bending
    ! connection here: doing so would silently replace it with a pinned end if a
    ! future dispatcher change made this route reachable for that deck.
    IF (ALLOCATED(ln%att)) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI two-moving-end compatibility solver does not support '// &
                'ATTACHMENTS; use a Fixed End B'); RETURN
    END IF
    IF (opts%friction_mu_axial > CD_ZERO) THEN
      CALL fail(ErrStat, ErrMsg, 'the finite-EI two-moving-end compatibility solver has isotropic seabed '// &
                'friction only; remove frictionMuAxial/frictionMuLateral')
      RETURN
    END IF
    IF (ANY(ln%endconn_mode /= CD_ENDCONN_PINNED)) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI two-moving-end compatibility solver does not support '// &
                'END CONNECTIONS; use a Fixed End B')
      RETURN
    END IF
    pa = find_point(points, ln%nodeB)
    pb = find_point(points, ln%nodeA)
    IF (pa < 1 .OR. pb < 1) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI LINE references an unknown endpoint POINT')
      RETURN
    END IF
    anchor = points(pa)%pos
    fairlead = points(pb)%pos

    CALL build_finite_section_mesh(ln, sections, types, conn, deck_model%l0, ea, mpl, diam, ei, &
                                   gas_in, gj_in, i_rt_in, i_rn_in, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    deck_model%n_elem = SIZE(deck_model%l0)
    ALLOCATE (deck_model%ea(deck_model%n_elem), deck_model%ei(deck_model%n_elem))
    deck_model%ea = ea
    ! Per-element bend stiffness (internal anchor->fairlead order, matching ea/l0) for the
    ! BendMom output channel: BendMom = EI(node) * geometric curvature. EI=0 lines report 0.
    deck_model%ei = ei
    ALLOCATE (deck_model%diam(deck_model%n_elem), deck_model%cdn(deck_model%n_elem), &
              deck_model%cdt(deck_model%n_elem), deck_model%can(deck_model%n_elem), &
              deck_model%cat(deck_model%n_elem))
    CALL finite_hydro_arrays(ln, sections, types, deck_model%diam, deck_model%cdn, deck_model%cdt, &
                             deck_model%can, deck_model%cat)

    nnode = deck_model%n_elem + 1
    ndof = 6*nnode
    ALLOCATE (nodes_ref(3, nnode), q0(ndof), v0(ndof), f_ext(ndof), f3(3*nnode), contact_f(ndof), &
              load_per_length(3, deck_model%n_elem), w(deck_model%n_elem), fixed_dofs(6))
    CALL CD_Submerged_Weight(mpl, diam, opts%rhoW, opts%g, w, es, em)
    IF (es /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI submerged weight: '//TRIM(em)); RETURN
    END IF
    CALL finite_section_closure(ea, ei, mpl, diam, gas_in, gj_in, i_rt_in, i_rn_in, &
                                gas, gj, rho_a, i_rt, i_rn, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN

    IF (ANY(w <= CD_ZERO)) THEN
      CALL finite_lazy_wave_reference_and_state(anchor, fairlead, deck_model%l0, nodes_ref, q0, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    ELSE
      CALL finite_reference_and_state(anchor, fairlead, deck_model%l0, nodes_ref, q0)
    END IF
    v0 = CD_ZERO
    f_ext = CD_ZERO
    load_per_length = CD_ZERO
    load_per_length(3, :) = -w
    CALL CD_Assemble_Distributed_Load(conn, deck_model%l0, load_per_length, f3, es, em)
    IF (es /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI load assembly: '//TRIM(em)); RETURN
    END IF
    CALL pack_translational_load(f3, f_ext)
    ALLOCATE (deck_model%base_f_ext(ndof))
    deck_model%base_f_ext = f_ext
    ALLOCATE (deck_model%q_work(ndof), deck_model%v_work(ndof), deck_model%a_work(ndof))
    ALLOCATE (deck_model%f_ext_work(ndof), deck_model%contact_work(ndof), deck_model%env_work(ndof))
    ALLOCATE (deck_model%q_fixed_work(ndof), deck_model%v_fixed_work(ndof), deck_model%a_fixed_work(ndof))
    ALLOCATE (deck_model%free_map_work(ndof))
    deck_model%q_work = CD_ZERO
    deck_model%v_work = CD_ZERO
    deck_model%a_work = CD_ZERO
    deck_model%f_ext_work = CD_ZERO
    deck_model%contact_work = CD_ZERO
    deck_model%env_work = CD_ZERO
    deck_model%q_fixed_work = CD_ZERO
    deck_model%v_fixed_work = CD_ZERO
    deck_model%a_fixed_work = CD_ZERO
    deck_model%free_map_work = 0
    IF (opts%has_wtrdpth .OR. PRESENT(bathymetry)) THEN
      CALL CD_Nodal_Seabed_Stiffness(opts%kbot, diam, deck_model%l0, deck_model%seabed_kn, es, em)
      IF (es /= CD_LINE_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'finite-EI seabed stiffness: '//TRIM(em)); RETURN
      END IF
      ALLOCATE (deck_model%seabed_cn(SIZE(deck_model%seabed_kn)))
      deck_model%seabed_cn = deck_model%seabed_kn*(opts%cbot/opts%kbot)
      deck_model%has_seabed = .TRUE.
      IF (PRESENT(bathymetry)) THEN
        deck_model%bathymetry = bathymetry
        deck_model%has_bathymetry = .TRUE.
        CALL finite_bathymetry_contact_force(q0, v0, deck_model%bathymetry, deck_model%seabed_kn, &
                                             deck_model%seabed_cn, opts%friction_mu, contact_f, ErrStat, ErrMsg)
      ELSE
        deck_model%seabed_z_floor = -opts%wtrdpth
        CALL finite_seabed_contact_force(q0, v0, deck_model%seabed_z_floor, deck_model%seabed_kn, &
                                         deck_model%seabed_cn, opts%friction_mu, contact_f, ErrStat, ErrMsg)
      END IF
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      f_ext = f_ext + contact_f
    END IF

    fixed_dofs = [1, 2, 3, ndof - 5, ndof - 4, ndof - 3]
    dynamic_cfg%rho_inf = opts%rho_inf
    dynamic_cfg%rel_tol = opts%dynamic_rel_tol
    dynamic_cfg%abs_tol = opts%dynamic_abs_tol
    dynamic_cfg%max_iter = opts%dynamic_max_iter
    dynamic_cfg%armijo_max_backtracks = opts%dynamic_backtracks
    dynamic_cfg%modified_newton = opts%dynamic_modified_newton
    CALL CD_Init_FiniteEI_Model(deck_model%model, nodes_ref, conn, ea, gas, ei, gj, rho_a, i_rt, i_rn, .TRUE., &
                                es, em, q0=q0, v0=v0, f_ext=f_ext, fixed_dofs=fixed_dofs, cfg=dynamic_cfg)
    IF (es /= CD_MODEL_OK) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: finite-EI model init failed: '//TRIM(em)
    END IF
  END SUBROUTINE init_one_finite_model

  RECURSIVE SUBROUTINE build_one_hermite_cable(ln, sections, types, points, opts, dt, cable, coupled_node, &
                                               ErrStat, ErrMsg, standalone_controls, bathymetry, &
                                               fairlead_orientation, init_note, coarse_pass)
    !! Build one COUPLED cubic-Hermite lazy-wave cable (CD_HFMF) from a finite-EI deck
    !! LINE -- the production Hermite bending path shared by the coupled route and
    !! standalone and coupled finite-EI dynamics, including flat/structured seabed contact.
    !! Reuses the finite-EI deck extraction (mesh, submerged weight, section closure, and
    !! the cubic-Hermite arch seed) then routes it through the production Hermite static
    !! solve and the coupled FMF shell. Node ordering runs anchor/touchdown (node 1,
    !! held) -> fairlead (node nn, the platform-driven coupled node), matching
    !! init_one_finite_model. Both call routes install flat/structured nodal contact when
    !! the host/deck declares a seabed; a cable that remains clear sees exactly zero reaction.
    TYPE(DeckLine), INTENT(IN) :: ln
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: dt
    TYPE(CD_HFMF_ModuleType), INTENT(INOUT) :: cable
    INTEGER, INTENT(OUT) :: coupled_node
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    LOGICAL, INTENT(IN), OPTIONAL :: standalone_controls
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    REAL(wp), INTENT(IN), OPTIONAL :: fairlead_orientation(3, 3)
    ! Static-initialisation notes, returned to a caller that reports them itself (the
    ! aggregate); a standalone run prints them.
    CHARACTER(*), INTENT(OUT), OPTIONAL :: init_note
    ! Set on the coarsened build of coarse_current_first (see there): no further coarsening.
    LOGICAL, INTENT(IN), OPTIONAL :: coarse_pass

    INTEGER, ALLOCATABLE :: conn(:, :), fixed_dofs(:), dynamic_fixed_dofs(:)
    REAL(wp), ALLOCATABLE :: l0(:), ea(:), mpl(:), diam(:), ei(:), gas_in(:), gj_in(:), i_rt_in(:), i_rn_in(:)
    REAL(wp), ALLOCATABLE :: gas(:), gj(:), rho_a(:), i_rt(:), i_rn(:), w(:), nodes_ref(:, :), q0(:), q_static(:)
    REAL(wp), ALLOCATABLE :: q_sequence(:)
    REAL(wp), ALLOCATABLE :: curv(:), cdn(:), cdt(:), can(:), cat(:), catenary_pos(:)
    REAL(wp), ALLOCATABLE :: ba_raw(:), ba(:), dry_b(:)
    REAL(wp), ALLOCATABLE :: contact_kn(:), contact_cn(:)
    REAL(wp) :: anchor(3), fairlead(3), res, tvec(3), tnrm, contact_z, seed_z, seed_floor_a, seed_floor_b
    REAL(wp) :: dxh, dyh, hspan, frame_cs(2), horizontal_tension, grounded_length
    REAL(wp) :: endconn_k(2), endconn_d0_global(3, 2), endconn_d0_local(3, 2)
    INTEGER :: endconn_mode(2)
    REAL(wp) :: fairlead_dcm(3, 3), dcm_gram(3, 3), dcm_det
    REAL(wp) :: bending_mesh_limit, proposed_coarse_max
    INTEGER :: pa, pb, nnode, ndof, es, iters, i, applied_scale, step_max_iter, sequence_levels, coarse_ne, next_ne
    INTEGER :: nfixed, kfixed
    INTEGER :: sequence_total, adaptive_iters
    INTEGER, ALLOCATABLE :: sequence_iters(:)
    REAL(wp) :: step_tol, static_tol, static_tol_target
    REAL(wp), ALLOCATABLE :: q_coupled_tol(:)
    INTEGER :: polish_iters
    ! Static tolerance of the coupled route (step_tol 5e-3 there), on which the mesh-
    ! sequenced hierarchy's intermediate readiness and recovery budgets are exercised.
    REAL(wp), PARAMETER :: COUPLED_STATIC_TOL = 1.0e-6_wp
    ! Newton-iteration budget of one mesh-sequenced fallback solve: a bounded failure path.
    INTEGER, PARAMETER :: FALLBACK_SEQUENCE_BUDGET = 2000
    LOGICAL :: standalone_mode, contact_enabled, used_trivial_seed, anchor_on_flat_bed, allow_extra_sequence
    LOGICAL :: polish_ready
    LOGICAL :: bathymetry_flat, require_3d_static, sym_broken, planar_unstable, saddle_kept
    ! A planar equilibrium in a current that is a saddle out of its plane (see route_pass).
    REAL(wp), ALLOCATABLE :: l0_saddle(:), ea_saddle(:), ei_saddle(:), w_saddle(:), q_saddle(:), curv_saddle(:)
    INTEGER, ALLOCATABLE :: fixed_saddle(:)
    LOGICAL :: saddle_tol_note, saddle_kink
    REAL(wp) :: saddle_res
    CHARACTER(320) :: saddle_notes
    LOGICAL :: primary_done, primary_inadmissible, tolerance_note, stable, kink_refined, sequence_done
    LOGICAL :: primary_walked, walk_rejected
    ! Why the bow behind the fairlead was not reached (bow_route), blank when not tried.
    CHARACTER(1024) :: bow_msg
    LOGICAL :: tensile_error
    CHARACTER(400) :: note_text
    CHARACTER(512) :: limit_text
    ! Steady deck current for the static solve (unallocated: no current).
    TYPE(CD_HermiteStaticCurrentType), ALLOCATABLE :: cur_obj, cur_exact
    ! Seabed friction holding the line against the deck current (static springs to
    ! the still-water laid shape, continued by elastic-plastic springs in the dynamics).
    LOGICAL :: static_friction
    REAL(wp), ALLOCATABLE :: fr_anchor(:, :), fr_force(:, :)
    INTEGER :: pass
    CHARACTER(1024) :: em, primary_msg, sequence_msg, planar_primary_msg, planar_sequence_msg, coarse_msg
    CHARACTER(320) :: compression_note, resolution_note, fine_note
    ! Shortest admissible finite-EI element, as a fraction of sqrt(EI/EA) (fine_mesh_note).
    REAL(wp), PARAMETER :: FINE_MESH_RATIO = 1.0_wp
    REAL(wp), ALLOCATABLE :: l0_am(:), ea_am(:), ei_am(:), w_am(:)
    INTEGER, ALLOCATABLE :: fixed_am(:)
    TYPE(CD_HermiteResolutionType) :: diag
    ! ATTACHMENTS: the deck-mesh bare submerged weight and mesh (the static solve runs on the
    ! smeared equivalent first), and the attachment nodes on the final mesh.
    LOGICAL :: has_att
    REAL(wp), ALLOCATABLE :: w_bare_deck(:), l0_deck_att(:), w_bare(:)
    INTEGER, ALLOCATABLE :: att_node(:)
    REAL(wp) :: att_offset
    ! Condensed torsion (both END CONNECTIONS rows torsionally restrained): solved as the last
    ! static load stage on the final mesh, then installed in the cable.
    LOGICAL :: tors_line
    TYPE(CD_HermiteTorsionType) :: tors

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    step_max_iter = 200
    step_tol = 5.0e-3_wp
    standalone_mode = .FALSE.
    contact_enabled = .FALSE.
    anchor_on_flat_bed = .FALSE.
    used_trivial_seed = .FALSE.
    allow_extra_sequence = .FALSE.
    bathymetry_flat = .FALSE.
    fairlead_dcm = CD_ZERO
    fairlead_dcm(1, 1) = CD_ONE
    fairlead_dcm(2, 2) = CD_ONE
    fairlead_dcm(3, 3) = CD_ONE
    IF (PRESENT(fairlead_orientation)) THEN
      IF (.NOT. ALL(IEEE_IS_FINITE(fairlead_orientation))) THEN
        CALL fail(ErrStat, ErrMsg, 'finite-EI fairlead orientation must be finite'); RETURN
      END IF
      dcm_gram = MATMUL(fairlead_orientation, TRANSPOSE(fairlead_orientation))
      dcm_det = fairlead_orientation(1, 1)*(fairlead_orientation(2, 2)*fairlead_orientation(3, 3) - &
                                            fairlead_orientation(2, 3)*fairlead_orientation(3, 2)) - &
                fairlead_orientation(1, 2)*(fairlead_orientation(2, 1)*fairlead_orientation(3, 3) - &
                                            fairlead_orientation(2, 3)*fairlead_orientation(3, 1)) + &
                fairlead_orientation(1, 3)*(fairlead_orientation(2, 1)*fairlead_orientation(3, 2) - &
                                            fairlead_orientation(2, 2)*fairlead_orientation(3, 1))
      IF (MAXVAL(ABS(dcm_gram - fairlead_dcm)) > 1.0e-8_wp .OR. ABS(dcm_det - CD_ONE) > 1.0e-8_wp) THEN
        CALL fail(ErrStat, ErrMsg, 'finite-EI fairlead orientation must be a proper orthogonal DCM'); RETURN
      END IF
      fairlead_dcm = fairlead_orientation
    END IF
    contact_z = -2000.0_wp
    IF (PRESENT(standalone_controls)) THEN
      IF (standalone_controls) THEN
        standalone_mode = .TRUE.
        step_max_iter = opts%dynamic_max_iter
        step_tol = opts%dynamic_rel_tol
      END IF
    END IF
    ! Hand the dynamic integrator an equilibrium converged at least as tightly as
    ! its own Newton stopping criterion.  A looser static tolerance can otherwise
    ! appear as an artificial load impulse on the first nominally stationary step,
    ! particularly after local refinement of a light, bending-stiff cable.
    static_tol = MIN(COUPLED_STATIC_TOL, step_tol)
    contact_enabled = opts%has_wtrdpth .OR. PRESENT(bathymetry)
    IF (opts%has_wtrdpth) contact_z = -opts%wtrdpth
    IF (PRESENT(bathymetry)) THEN
      bathymetry_flat = MAXVAL(ABS(bathymetry%depth - bathymetry%average_depth)) <= &
        64.0_wp*EPSILON(CD_ONE)*MAX(CD_ONE, ABS(bathymetry%average_depth))
    END IF
    IF (.NOT. (dt > CD_ZERO)) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI cable build requires a positive coupling dt'); RETURN
    END IF
    pa = find_point(points, ln%nodeB)   ! touchdown/anchor -> node 1
    pb = find_point(points, ln%nodeA)   ! fairlead -> node nn (platform-driven)
    IF (pa < 1 .OR. pb < 1) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI cable LINE references an unknown endpoint POINT'); RETURN
    END IF
    ! Require the endpoint ROLES the coupled builder assumes: End A (nodeA -> node nn) is the
    ! platform-driven fairlead, so it must be a Coupled/Vessel point; End B (nodeB -> node 1) is
    ! the held anchor, so it must be Fixed. parse_deck also admits Connect/Free (dynamic) points
    ! and other roles, which would otherwise be silently coerced into this coupled/held boundary
    ! -- ignoring their point mass/load state -- instead of failing closed. (ptype is stored
    ! lower-case; the aggregator inherits this check since it calls build_one_hermite_cable too.)
    IF (TRIM(points(pb)%ptype) /= 'coupled' .AND. TRIM(points(pb)%ptype) /= 'vessel' .AND. &
        .NOT. (standalone_mode .AND. TRIM(points(pb)%ptype) == 'fixed')) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI coupled cable requires End A (the fairlead) to be a '// &
                'Coupled/Vessel point; got "'//TRIM(points(pb)%ptype)//'"'); RETURN
    END IF
    IF (TRIM(points(pa)%ptype) /= 'fixed') THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI coupled cable requires End B (the anchor) to be a '// &
                'Fixed point; got "'//TRIM(points(pa)%ptype)//'"'); RETURN
    END IF
    anchor = points(pa)%pos
    fairlead = points(pb)%pos
    IF (contact_enabled .AND. PRESENT(bathymetry)) THEN
      CALL CD_Bathymetry_Floor(bathymetry, anchor(1), anchor(2), seed_floor_a, es, em)
      IF (es /= CD_BATHY_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'finite-EI anchor bathymetry query failed: '//TRIM(em)); RETURN
      END IF
      CALL CD_Bathymetry_Floor(bathymetry, fairlead(1), fairlead(2), seed_floor_b, es, em)
      IF (es /= CD_BATHY_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'finite-EI fairlead bathymetry query failed: '//TRIM(em)); RETURN
      END IF
      ! This scalar is only the trivial seed's representative floor when a structured
      ! bathymetry is present; every static/dynamic contact evaluation still queries
      ! the full surface.  Using the lower endpoint floor avoids an artificial seed
      ! penetration on a slope and gives a constant-depth grid the flat-bed seed.
      contact_z = MIN(seed_floor_a, seed_floor_b)
    END IF
    ! CHORD-LOCAL SOLVE FRAME. The static/dynamic solve holds every node's y position and
    ! y tangent (the lazy wave hangs in the vertical plane through its endpoints; the free
    ! out-of-plane mode is soft and the dynamic Newton cannot converge with it left free).
    ! That frozen y is the true out-of-plane direction only in a frame whose x-z plane
    ! contains the chord -- so an AZIMUTHAL cable (nonzero chord y-span, e.g. any deck
    ! whose fairlead was swayed/yawed by ptfm_init) is solved in a local frame rotated
    ! about +z to put the chord's horizontal direction along local x. The FMF boundary
    ! stores the heading and rotates kinematics in / loads out, so every caller stays in
    ! global coordinates. A zero horizontal span (vertical chord: any vertical plane
    ! contains it) and the x-z-aligned case both reduce to the identity heading, keeping
    ! those paths bit-for-bit.
    dxh = fairlead(1) - anchor(1)
    dyh = fairlead(2) - anchor(2)
    hspan = SQRT(dxh*dxh + dyh*dyh)
    frame_cs = [1.0_wp, 0.0_wp]
    IF (hspan > 1.0e-9_wp*MAX(1.0_wp, SUM(ABS(fairlead - anchor))) .AND. ABS(dyh) > CD_ZERO) THEN
      frame_cs = [dxh/hspan, dyh/hspan]
      anchor = [frame_cs(1)*anchor(1) + frame_cs(2)*anchor(2), &
                -frame_cs(2)*anchor(1) + frame_cs(1)*anchor(2), anchor(3)]
      fairlead = [frame_cs(1)*fairlead(1) + frame_cs(2)*fairlead(2), &
                  -frame_cs(2)*fairlead(1) + frame_cs(1)*fairlead(2), fairlead(3)]
    END IF

    ! Deck ends use the public A-to-B Ez convention, while the Hermite state is
    ! ordered anchor-to-fairlead. Consequently both internal preferred tangent
    ! directions are the negative of the corresponding deck Ez vector; the end
    ! columns are also reversed (deck B -> internal node 1, deck A -> final node).
    endconn_k = [ln%endconn_k(2), ln%endconn_k(1)]
    endconn_mode = [ln%endconn_mode(2), ln%endconn_mode(1)]
    endconn_d0_global = CD_ZERO
    endconn_d0_global(:, 1) = -ln%endconn_ez_ref(:, 2)
    endconn_d0_global(:, 2) = MATMUL(TRANSPOSE(fairlead_dcm), -ln%endconn_ez_ref(:, 1))
    DO i = 1, 2
      endconn_d0_local(:, i) = [frame_cs(1)*endconn_d0_global(1, i) + &
                                frame_cs(2)*endconn_d0_global(2, i), &
                                -frame_cs(2)*endconn_d0_global(1, i) + &
                                frame_cs(1)*endconn_d0_global(2, i), &
                                endconn_d0_global(3, i)]
    END DO
    require_3d_static = .FALSE.
    DO i = 1, 2
      IF (endconn_mode(i) /= CD_ENDCONN_PINNED .AND. &
          ABS(endconn_d0_local(2, i)) > 64.0_wp*EPSILON(CD_ONE)) require_3d_static = .TRUE.
    END DO
    ! A twisted line leaves the plane of its chord (the torque bends it out of plane), so a
    ! torsional line is solved in 3D from the start.
    tors_line = line_torsion_active(ln)
    IF (tors_line) require_3d_static = .TRUE.
    ! A current with a component across the vertical plane of the chord pushes the line out
    ! of that plane, which the dynamics (endpoints held, every other DOF free) follow: the
    ! static equilibrium is then solved in 3D as well.
    IF (opts%has_current) THEN
      IF (opts%has_current_profile) THEN
        DO i = 1, SIZE(opts%current_profile_z)
          IF (ABS(-frame_cs(2)*opts%current_profile_velocity(1, i) + frame_cs(1)*opts%current_profile_velocity(2, i)) &
              > 64.0_wp*EPSILON(CD_ONE)*MAX(CD_ONE, NORM2(opts%current_profile_velocity(:, i)))) &
            require_3d_static = .TRUE.
        END DO
      ELSE IF (ABS(-frame_cs(2)*opts%current_velocity(1) + frame_cs(1)*opts%current_velocity(2)) > &
               64.0_wp*EPSILON(CD_ONE)*MAX(CD_ONE, NORM2(opts%current_velocity))) THEN
        require_3d_static = .TRUE.
      END IF
    END IF

    CALL build_finite_section_mesh(ln, sections, types, conn, l0, ea, mpl, diam, ei, &
                                   gas_in, gj_in, i_rt_in, i_rn_in, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    ! Fine-mesh limit: an element shorter than the axial-bending length sqrt(EI/EA) has an
    ! axial stiffness EA/h that dwarfs every bending term; the static Newton system then
    ! loses the precision to converge and the solve stalls after minutes instead of
    ! failing. Named before the solve, so a standalone run shows it at once.
    fine_note = ''
    CALL fine_mesh_note(fine_note)
    IF (LEN_TRIM(fine_note) > 0 .AND. standalone_mode) WRITE (error_unit, '(A)') '   Note: '//TRIM(fine_note)//'.'
    ALLOCATE (ba_raw(SIZE(l0)))
    CALL finite_raw_ba_array(ln, sections, types, ba_raw)
    nnode = SIZE(l0) + 1
    ndof = 6*nnode
    ALLOCATE (w(SIZE(l0)), nodes_ref(3, nnode), q0(ndof))
    CALL CD_Submerged_Weight(mpl, diam, opts%rhoW, opts%g, w, es, em)
    IF (es /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI cable submerged weight: '//TRIM(em)); RETURN
    END IF
    CALL finite_section_closure(ea, ei, mpl, diam, gas_in, gj_in, i_rt_in, i_rn_in, &
                                gas, gj, rho_a, i_rt, i_rn, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    ! Discrete attachments: the static solve first finds the equilibrium with each
    ! attachment's net weight smeared over its node's two elements (the branch the
    ! established seeds and continuations trace), then a homotopy to the lumped loads
    ! (attachment_static_polish) gives the discrete equilibrium.
    has_att = ALLOCATED(ln%att)
    l0_deck_att = l0
    w_bare_deck = w
    IF (has_att) THEN
      CALL attachment_nodes(l0, ln%att(1, :), att_node, att_offset)
      CALL smear_attachments(w, l0, att_node, ln%att, opts%rhoW, opts%g)
    END IF
    anchor_on_flat_bed = contact_enabled .AND. (.NOT. PRESENT(bathymetry) .OR. bathymetry_flat) .AND. &
                         ABS(anchor(3) - contact_z) <= 1.0e-6_wp*MAX(CD_ONE, ABS(contact_z))
    ! A net-buoyant section anywhere makes this a lazy-wave (buoyant-arch) line and needs
    ! the arch seed; an all-heavy line uses the chord/reference seed. Both then solve
    ! with the buoyancy + EI continuation, which produces a
    ! smooth equilibrium the dynamic model can start from.
    IF (ANY(w <= CD_ZERO) .AND. anchor_on_flat_bed) THEN
      ! Full installed lazy-wave cables need a branch-aware cold start.  The generic
      ! single-arch seed has no grounded-tail degree of freedom and can converge to a
      ! high-tension local equilibrium.  Seed the complete anchor-to-fairlead mesh with
      ! the signed-weight, extensible grounded catenary instead: it solves horizontal
      ! tension, lift-off force, and grounded rest length from the deck itself.  No
      ! external centreline or site-specific tuning is involved; finite EI, buoyancy,
      ! and contact are still established by the Hermite continuation below.
      ALLOCATE (catenary_pos(3*nnode))
      CALL CD_Catenary_Seed(anchor, fairlead, l0, ea, w, catenary_pos, horizontal_tension, &
                            grounded_length, es, em)
      IF (es == CD_CAT_OK) THEN
        q0 = CD_ZERO
        DO i = 1, nnode
          nodes_ref(:, i) = catenary_pos(3*(i - 1) + 1:3*i)
          q0(6*(i - 1) + 1:6*(i - 1) + 3) = nodes_ref(:, i)
        END DO
      ELSE
        ! An endpoint can lie on the declared bed without the total geometry admitting
        ! this seed's partially grounded branch.  The analytical seed is an accelerator,
        ! not a new validity condition: retain the established suspended lazy-wave seed
        ! and let the contact continuation find the applicable equilibrium branch.
        CALL finite_lazy_wave_reference_and_state(anchor, fairlead, l0, nodes_ref, q0, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      END IF
    ELSE IF (ANY(w <= CD_ZERO)) THEN
      CALL finite_lazy_wave_reference_and_state(anchor, fairlead, l0, nodes_ref, q0, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    ELSE IF (contact_enabled) THEN
      ! A contact line must not enter the Hermite continuation as a short straight
      ! chord: that is an EA-amplified compressive state and can converge to a folded
      ! local equilibrium before the bed load is established.  The library seed lays
      ! the available length into a suspended/grounded isometric shape.  Use a seed
      ! floor no higher than either endpoint so decks that intentionally bury an
      ! anchor by a small penetration remain admissible; the actual contact solve
      ! still uses contact_z or the structured bathymetry.
      seed_z = MIN(contact_z, anchor(3), fairlead(3))
      CALL CD_HermiteCable_Trivial_Seed(anchor, fairlead, l0, seed_z, q0, es, em)
      IF (es /= CD_HCSTAT_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'finite-EI cable contact seed failed: '//TRIM(em)); RETURN
      END IF
      DO i = 1, nnode
        nodes_ref(:, i) = q0(6*(i - 1) + 1:6*(i - 1) + 3)
      END DO
      used_trivial_seed = .TRUE.
    ELSE
      CALL finite_reference_and_state(anchor, fairlead, l0, nodes_ref, q0)
    END IF

    ! Seed the tangent (m) DOFs as UNIT inter-node directions. The reference-and-state
    ! builders populate only the position DOFs and leave the tangents at zero; |m| is a
    ! soft gauge mode of the pinned static solve, so it converges (to machine precision)
    ! but leaves |m| wherever the seed put it. A near-zero tangent gauge solves statically
    ! yet the dynamic gen-alpha Newton cannot step from it -- seed unit tangents so the
    ! handed-off state is a well-conditioned |m| ~ 1.
    IF (.NOT. used_trivial_seed) THEN
      DO i = 1, nnode
        IF (i < nnode) THEN
          tvec = nodes_ref(:, i + 1) - nodes_ref(:, i)
        ELSE
          tvec = nodes_ref(:, i) - nodes_ref(:, i - 1)
        END IF
        tnrm = SQRT(SUM(tvec**2))
        IF (tnrm > CD_ZERO) q0(6*(i - 1) + 4:6*(i - 1) + 6) = tvec/tnrm
      END DO
    END IF

    ! Held DOFs: both endpoint positions (node 1 touchdown/anchor + node nn fairlead
    ! r-DOFs) AND the whole out-of-plane motion (every node's y position + y tangent).
    ! The lazy-wave hangs in the vertical plane through the two endpoints; the free
    ! out-of-plane mode is soft, and while the static solve tolerates it, the dynamic
    ! gen-alpha Newton cannot converge with it left free. A general-orientation cable (a
    ! mooring azimuth) needs the out-of-plane direction taken from the chord rather than the
    ! global y; frame_cs above supplies it.
    IF (require_3d_static) THEN
      ALLOCATE (fixed_dofs(6))
      fixed_dofs(1:3) = [1, 2, 3]
      fixed_dofs(4:6) = [ndof - 5, ndof - 4, ndof - 3]
    ELSE
      nfixed = 6 + 2*nnode - COUNT(endconn_mode == CD_ENDCONN_RIGID)
      ALLOCATE (fixed_dofs(nfixed))
      fixed_dofs(1:3) = [1, 2, 3]
      fixed_dofs(4:6) = [ndof - 5, ndof - 4, ndof - 3]
      kfixed = 6
      DO i = 1, nnode
        kfixed = kfixed + 1
        fixed_dofs(kfixed) = 6*(i - 1) + 2       ! out-of-plane (y) position
        IF ((i == 1 .AND. endconn_mode(1) == CD_ENDCONN_RIGID) .OR. &
            (i == nnode .AND. endconn_mode(2) == CD_ENDCONN_RIGID)) CYCLE
        kfixed = kfixed + 1
        fixed_dofs(kfixed) = 6*(i - 1) + 5       ! out-of-plane (y) tangent
      END DO
    END IF
    ! A fine net-buoyant cable can have several finite-element equilibria, including a
    ! sharply folded, compression-dominated shape with a plausible fairlead tension.
    ! This affects suspended lazy waves as well as grounded/touchdown installations.
    ! When the caller mesh admits it, select the physical branch on a coarser
    ! bending-resolved representation and prolongate/polish back to the requested mesh.
    ! The nested hierarchy admits odd/prime counts and preserves every section/load
    ! interface, so adjacent user meshes cannot switch routes merely because one count
    ! is divisible by two. It does not use a saved shape or a site-specific parameter.
    sequence_levels = 1
    coarse_ne = SIZE(l0)
    ! Non-flat structured bathymetry changes the active nodal contact set as the mesh
    ! is refined, so keep it on the exact bathymetry-aware AutoMesh route below.
    ! A constant structured grid is mathematically the same plane as WtrDpth and must
    ! use the same hierarchy; otherwise equivalent inputs can select different branches.
    IF (SIZE(l0) >= INSTALLED_SEQUENCE_MIN_ELEMS .AND. ANY(w <= CD_ZERO) .AND. &
        (.NOT. PRESENT(bathymetry) .OR. bathymetry_flat)) THEN
      ! The primary static-sweep guard does not coarsen beyond 3.2 local
      ! bending lengths, lambda=(EI/|w|)^(1/3). This admits the independently
      ! validated 800 m ladder (about 3.1 lambda) without over-coarsening it.
      ! Neutral-weight sections do not constrain the minimum, and the explicit
      ! loop avoids overflow from dividing their EI by a tiny surrogate weight.
      bending_mesh_limit = HUGE(CD_ONE)
      DO i = 1, SIZE(l0)
        IF (ABS(w(i)) > TINY(CD_ONE)) &
          bending_mesh_limit = MIN(bending_mesh_limit, 3.2_wp*(ei(i)/ABS(w(i)))**(CD_ONE/3.0_wp))
      END DO
      DO
        ! the hierarchy builder accepts at most SEQUENCE_MAX_LEVELS levels (a very fine
        ! mesh would otherwise ask for more and fail with an internal message)
        IF (sequence_levels >= SEQUENCE_MAX_LEVELS) EXIT
        next_ne = coarse_ne - coarse_ne/3
        IF (next_ne >= coarse_ne .OR. next_ne < INSTALLED_SEQUENCE_COARSE_FLOOR) EXIT
        ! Query the hierarchy builder itself: for nonuniform section meshes, the
        ! longest proposed cell can be much longer than SUM(l0)/next_ne because
        ! grouping balances fine-element counts and retains every interface.
        IF (contact_enabled) THEN
          CALL CD_HermiteCable_Sequence_Coarse_Max_Length(l0, ea, ei, w, sequence_levels + 1, &
                                                          proposed_coarse_max, es, em, diam)
        ELSE
          CALL CD_HermiteCable_Sequence_Coarse_Max_Length(l0, ea, ei, w, sequence_levels + 1, &
                                                          proposed_coarse_max, es, em)
        END IF
        IF (es /= CD_HCSTAT_OK) THEN
          CALL fail(ErrStat, ErrMsg, 'finite-EI hierarchy preflight failed: '//TRIM(em)); RETURN
        END IF
        ! Suspended hierarchies enforce the longest actual coarse cell. A
        ! flat-bed line whose anchor is already supported keeps the scalar
        ! branch-homotopy depth: its grounded tail is polished and safety-gated
        ! on the exact mesh, and applying the suspended-span limit there removes
        ! the only smooth touchdown branch for otherwise valid installed cables.
        IF ((.NOT. contact_enabled .OR. .NOT. anchor_on_flat_bed) .AND. &
            proposed_coarse_max > bending_mesh_limit) EXIT
        sequence_levels = sequence_levels + 1
        coarse_ne = next_ne
      END DO
      ! If the bending-resolved primary hierarchy fails, permit exactly one deeper
      ! level as bounded numerical globalization. It is never used after a successful
      ! primary solve, never descends below the global coarse floor, and the exact user
      ! mesh plus h*kappa safety gate still decide acceptance.
      next_ne = coarse_ne - coarse_ne/3
      IF (next_ne < coarse_ne .AND. next_ne >= INSTALLED_SEQUENCE_COARSE_FLOOR .AND. &
          sequence_levels < SEQUENCE_MAX_LEVELS) allow_extra_sequence = .TRUE.
    END IF

    ! Solve the finite-EI static state at the deck's segmentation (with the shared standalone/
    ! coupled nodal contact law when declared; otherwise seabed far below and kn = 0), using
    ! n_cont = 8 load steps and damping = 0.7. When the deck opts in to
    ! adaptive_mesh AND CD_HermiteCable_Resolution_Metrics flags the mesh FRAGILE (an
    ! under-resolved arch/touchdown that would stall the coupled dynamic Newton), AutoMesh
    ! refines by WARM-STARTED cubic-Hermite prolongation of the converged IC
    ! (CD_HermiteCable_Refine_Mesh) up to CD_HC_REFINE_CAP. Prolongation -- not a
    ! cold re-solve at the finer mesh -- is essential: a cold fine solve kinks (mesh-sequencing is
    ! the documented practice). inherit_dofs [2,5] carries the planar out-of-plane hold (y
    ! position + y tangent) onto inserted nodes. max_scale = 1 (adaptive_mesh off, the DEFAULT)
    ! disables refinement: AutoMesh does the plain coarse solve + diagnosis, applied_scale = 1,
    ! and the coupled cable is BIT-FOR-BIT the direct-solve build. The h*kappa target is
    ! deliberately conservative, so off-by-default keeps the deck's NumSegs authoritative.
    ! The standalone route tightens static_tol to the dynamic Newton tolerance (1e-8 by
    ! default) so the march starts from an equilibrium as tight as its own steps. The
    ! mesh-sequenced solve at a touchdown is, however, sensitive to that choice: the
    ! first full-load polish of a prolongated level can throw a touchdown node through
    ! the floor (the contact law is C1 only over a 1e-6 m blend), and whether the
    ! recoveries then succeed depends sensitively on where each level stopped, so a cable can
    ! solve at neighbouring tolerances and fail at one in between. A standalone deck must not
    ! fail where its
    ! coupled twin succeeds, so a failed tight solve is repeated at the coupled static
    ! tolerance and the resulting equilibrium is then polished to the tight tolerance on
    ! the final mesh, where Newton starts inside its quadratic basin. Decks that solve
    ! directly are untouched.
    static_tol_target = static_tol
    polish_iters = 0
    iters = 0
    ! Free surface at z = 0 (the waterline the dynamic drag configuration uses): a part of
    ! the line above it regains its displaced-water buoyancy rhoW*g*pi*d^2/4, matching the
    ! EI = 0 statics.
    ALLOCATE (dry_b(SIZE(l0)))
    dry_b = opts%rhoW*opts%g*QUARTER_PI*diam**2
    ! A deck current loads the line at rest: the static equilibrium includes its steady drag
    ! (the drag of the dynamic path at zero velocity), so a run starts at rest in the current.
    static_friction = .FALSE.
    IF (opts%has_current) THEN
      ALLOCATE (cur_obj)
      CALL hermite_static_current(ln, sections, types, opts, l0, frame_cs, cur_obj)
      ! A frictional seabed resists the current from the still-water laid shape (the
      ! OrcaFlex convention): the line is first solved without the current, and that
      ! equilibrium is the reference of the friction springs, whose forces then seed the
      ! stick-slip anchors of the march (standalone and coupled alike).
      static_friction = contact_enabled .AND. opts%has_friction
      IF (static_friction) THEN
        CALL still_water_reference(es, em)
        IF (es /= CD_DECKDRV_OK) THEN
          CALL fail_solve(ErrStat, ErrMsg, 'finite-EI still-water reference for the seabed friction: '// &
                          TRIM(em)); RETURN
        END IF
      END IF
    END IF
    ! Two static routes, each audited (physical branch, stability) before its equilibrium
    ! is used; the second runs only when the first fails or its state is rejected. The
    ! catenary-continuation route (hermite_static_primary) runs first by default; OPTIONS
    ! cable_statics sequenced runs the mesh-sequenced route (branch-controlled
    ! initialisation on the section-preserving hierarchy) first.
    tensile_error = opts%tensile_mode == CD_HCDYN_TENSILE_ERROR
    primary_done = .FALSE.
    sequence_done = .FALSE.
    primary_msg = ''
    sequence_msg = ''
    compression_note = ''
    resolution_note = ''
    tolerance_note = .FALSE.
    kink_refined = .FALSE.
    sym_broken = .FALSE.
    planar_unstable = .FALSE.
    walk_rejected = .FALSE.
    saddle_tol_note = .FALSE.
    saddle_kink = .FALSE.
    saddle_res = CD_ZERO
    saddle_notes = ''
    ! In a current the traced path can end at a fold or a pitchfork of the planar branch
    ! (the grounded run pushed toward its end lifts into a hairpin or turns sideways), and
    ! whether a load step or a Newton polish crosses it depends on the element size: the
    ! same deck could solve on one mesh and fail closed, or reach another equilibrium, on a
    ! finer one. The branch is therefore selected on the coarsest halving of the deck mesh
    ! that still resolves the bending length, and carried to the deck mesh by cubic-Hermite
    ! prolongation and a polish there (coarse_current_first).
    IF (coarse_current_eligible()) THEN
      CALL coarse_current_first(primary_done, coarse_msg)
      IF (LEN_TRIM(coarse_msg) > 0) THEN
        CALL fail_solve(ErrStat, ErrMsg, TRIM(coarse_msg)); RETURN
      END IF
    END IF
    route_pass: DO pass = 1, 3
      IF (primary_done) EXIT route_pass
      ! A planar equilibrium that is unstable out of its plane is not repeated by the
      ! mesh-sequenced route (also planar): the symmetry-breaking pass follows.
      IF (pass == 2 .AND. planar_unstable) CYCLE route_pass
      ! On a mesh finer than sqrt(EI/EA) (fine_note) the failed route is not followed by the
      ! others, which repeat the same ill-conditioned Newton solves on that mesh for minutes;
      ! the failure names the mesh.
      IF (pass >= 2 .AND. LEN_TRIM(fine_note) > 0) THEN
        IF (LEN_TRIM(sequence_msg) == 0) sequence_msg = 'not run: the deck mesh is finer than sqrt(EI/EA)'
        EXIT route_pass
      END IF
      ! Pass 3 (catenary-continuation route): a current in the vertical plane of the chord
      ! is a symmetric problem, solved in that plane. Its planar branch can end where the
      ! grounded run, pushed toward its end, would have to reverse direction; the
      ! equilibrium beyond is out of the plane (a pitchfork: the run turns sideways on the
      ! seabed), which no planar or symmetric Newton reaches. The line is then solved in 3D
      ! under the current with a small cross-flow component (SYM_BREAK of its horizontal
      ! speed) and polished at the exact current below.
      IF (pass == 3) THEN
        IF (.NOT. symmetric_current_retry()) EXIT route_pass
      END IF
      ! A catenary-continuation route that stopped on the frictionless grounded-run
      ! diagnosis (the current drives the run on the seabed into compression) is not
      ! rescued by the mesh-sequenced route, which reaches the same planar limit after
      ! up to a minute; only the symmetry-breaking passes can.
      IF (pass == 2 .AND. .NOT. opts%cable_statics_sequenced .AND. &
          INDEX(primary_msg, 'the run on the seabed') > 0) THEN
        sequence_msg = 'not run: the catenary-continuation route diagnosed the grounded run'
        CYCLE route_pass
      END IF
      static_tol = static_tol_target
      IF (pass <= 2 .AND. ((pass == 1) .EQV. opts%cable_statics_sequenced)) THEN
        static_attempt: DO
          IF (sequence_levels > 1) THEN
            ALLOCATE (q_static(ndof), curv(nnode), sequence_iters(sequence_levels))
            IF (PRESENT(bathymetry) .AND. .NOT. bathymetry_flat) THEN
              CALL CD_HermiteCable_Static_Solve_Sequenced(l0, ea, ei, w, q0, fixed_dofs, contact_z, &
                                                          CD_ZERO, 8, 120, static_tol, 0.7_wp, &
                                                          sequence_levels, q_static, curv, &
                                                          res, sequence_iters, es, em, &
                                                          contact_diameter=diam, contact_kbot=opts%kbot, &
                                                          bathymetry=bathymetry, contact_frame_cs=frame_cs, &
                                                          reseed_coarse_tangents=.TRUE., &
                                                          extra_coarse_level=allow_extra_sequence, &
                                                          iteration_budget=FALLBACK_SEQUENCE_BUDGET, &
                                                          axial_quadrature_order=opts%axial_quadrature_order, &
                                                          bending_quadrature_order=opts%bending_quadrature_order, &
                                                          endconn_stiffness=endconn_k, &
                                                          endconn_direction=endconn_d0_local, &
                                                          endconn_mode=endconn_mode, &
                                                          waterline_z=CD_ZERO, dry_buoyancy=dry_b, &
                                                          water_weight=opts%rhoW*opts%g, current=cur_obj)
            ELSE IF (contact_enabled) THEN
              CALL CD_HermiteCable_Static_Solve_Sequenced(l0, ea, ei, w, q0, fixed_dofs, contact_z, &
                                                          CD_ZERO, 8, 120, static_tol, 0.7_wp, &
                                                          sequence_levels, q_static, curv, &
                                                          res, sequence_iters, es, em, &
                                                          contact_diameter=diam, contact_kbot=opts%kbot, &
                                                          contact_frame_cs=frame_cs, &
                                                          reseed_coarse_tangents=.TRUE., &
                                                          extra_coarse_level=allow_extra_sequence, &
                                                          iteration_budget=FALLBACK_SEQUENCE_BUDGET, &
                                                          axial_quadrature_order=opts%axial_quadrature_order, &
                                                          bending_quadrature_order=opts%bending_quadrature_order, &
                                                          endconn_stiffness=endconn_k, &
                                                          endconn_direction=endconn_d0_local, &
                                                          endconn_mode=endconn_mode, &
                                                          waterline_z=CD_ZERO, dry_buoyancy=dry_b, &
                                                          water_weight=opts%rhoW*opts%g, current=cur_obj)
            ELSE
              ! Positional seabed_z/kn remain part of the public sequenced interface, but
              ! nodal-contact activation is controlled by the presence of these optionals.
              ! Omit them for a genuinely suspended cable so contact_z stays a numerical
              ! sentinel rather than becoming an undeclared physical floor.
              CALL CD_HermiteCable_Static_Solve_Sequenced(l0, ea, ei, w, q0, fixed_dofs, contact_z, &
                                                          CD_ZERO, 8, 120, static_tol, 0.7_wp, &
                                                          sequence_levels, q_static, curv, &
                                                          res, sequence_iters, es, em, &
                                                          reseed_coarse_tangents=.TRUE., &
                                                          extra_coarse_level=allow_extra_sequence, &
                                                          iteration_budget=FALLBACK_SEQUENCE_BUDGET, &
                                                          axial_quadrature_order=opts%axial_quadrature_order, &
                                                          bending_quadrature_order=opts%bending_quadrature_order, &
                                                          endconn_stiffness=endconn_k, &
                                                          endconn_direction=endconn_d0_local, &
                                                          endconn_mode=endconn_mode, &
                                                          waterline_z=CD_ZERO, dry_buoyancy=dry_b, &
                                                          water_weight=opts%rhoW*opts%g, current=cur_obj)
            END IF
            sequence_total = SUM(sequence_iters)
            IF (es == CD_HCSTAT_OK) THEN
              ! Preserve the branch selected by sequencing, then run the normal resolution
              ! diagnosis/refinement from that converged state. AutoMesh prolongates this
              ! warm start if refinement is required; it never cold-starts the fine branch.
              ALLOCATE (q_sequence(SIZE(q_static)))
              q_sequence = q_static
              IF (PRESENT(bathymetry) .AND. .NOT. bathymetry_flat) THEN
                CALL CD_HermiteCable_Static_Solve_AutoMesh(l0, ea, ei, w, q_sequence, fixed_dofs, &
                                                           contact_z, CD_ZERO, 8, 80, static_tol, 0.7_wp, &
                                                           CD_HC_HKAPPA_TARGET, CD_ZERO, &
                                                           CD_HC_REFINE_CAP, [2, 5], &
                                                           l0_am, ea_am, ei_am, &
                                                           w_am, q_static, curv, fixed_am, &
                                                           applied_scale, diag, res, adaptive_iters, es, em, &
                                                           contact_diameter=diam, contact_kbot=opts%kbot, &
                                                           bathymetry=bathymetry, contact_frame_cs=frame_cs, &
                                                           initial_polish=.TRUE., &
                                                           require_resolved=opts%adaptive_mesh, &
                                                           axial_quadrature_order=opts%axial_quadrature_order, &
                                                           bending_quadrature_order=opts%bending_quadrature_order, &
                                                           require_tensile=tensile_error, &
                                                           compression_mode=CD_HC_COMPRESSION_STRICT, &
                                                           refine_non_axial=opts%adaptive_mesh, &
                                                           endconn_stiffness=endconn_k, &
                                                           endconn_direction=endconn_d0_local, &
                                                           endconn_mode=endconn_mode, &
                                                           waterline_z=CD_ZERO, dry_buoyancy=dry_b, &
                                                           water_weight=opts%rhoW*opts%g, current=cur_obj)
              ELSE IF (contact_enabled) THEN
                CALL CD_HermiteCable_Static_Solve_AutoMesh(l0, ea, ei, w, q_sequence, fixed_dofs, &
                                                           contact_z, CD_ZERO, 8, 80, static_tol, 0.7_wp, &
                                                           CD_HC_HKAPPA_TARGET, CD_ZERO, &
                                                           CD_HC_REFINE_CAP, [2, 5], &
                                                           l0_am, ea_am, ei_am, &
                                                           w_am, q_static, curv, fixed_am, &
                                                           applied_scale, diag, res, adaptive_iters, es, em, &
                                                           contact_diameter=diam, contact_kbot=opts%kbot, &
                                                           contact_frame_cs=frame_cs, initial_polish=.TRUE., &
                                                           require_resolved=opts%adaptive_mesh, &
                                                           axial_quadrature_order=opts%axial_quadrature_order, &
                                                           bending_quadrature_order=opts%bending_quadrature_order, &
                                                           require_tensile=tensile_error, &
                                                           compression_mode=CD_HC_COMPRESSION_STRICT, &
                                                           refine_non_axial=opts%adaptive_mesh, &
                                                           endconn_stiffness=endconn_k, &
                                                           endconn_direction=endconn_d0_local, &
                                                           endconn_mode=endconn_mode, &
                                                           waterline_z=CD_ZERO, dry_buoyancy=dry_b, &
                                                           water_weight=opts%rhoW*opts%g, current=cur_obj)
              ELSE
                CALL CD_HermiteCable_Static_Solve_AutoMesh(l0, ea, ei, w, q_sequence, fixed_dofs, &
                                                           contact_z, CD_ZERO, 8, 80, static_tol, 0.7_wp, &
                                                           CD_HC_HKAPPA_TARGET, CD_ZERO, &
                                                           CD_HC_REFINE_CAP, [2, 5], &
                                                           l0_am, ea_am, ei_am, &
                                                           w_am, q_static, curv, fixed_am, &
                                                           applied_scale, diag, res, adaptive_iters, es, em, &
                                                           initial_polish=.TRUE., &
                                                           require_resolved=opts%adaptive_mesh, &
                                                           axial_quadrature_order=opts%axial_quadrature_order, &
                                                           bending_quadrature_order=opts%bending_quadrature_order, &
                                                           require_tensile=tensile_error, &
                                                           compression_mode=CD_HC_COMPRESSION_STRICT, &
                                                           refine_non_axial=opts%adaptive_mesh, &
                                                           endconn_stiffness=endconn_k, &
                                                           endconn_direction=endconn_d0_local, &
                                                           endconn_mode=endconn_mode, &
                                                           waterline_z=CD_ZERO, dry_buoyancy=dry_b, &
                                                           water_weight=opts%rhoW*opts%g, current=cur_obj)
              END IF
              iters = sequence_total + adaptive_iters
            ELSE
              iters = sequence_total
              applied_scale = 1
              ALLOCATE (l0_am(SIZE(l0)), ea_am(SIZE(ea)), ei_am(SIZE(ei)), w_am(SIZE(w)), &
                        fixed_am(SIZE(fixed_dofs)))
              l0_am = l0; ea_am = ea; ei_am = ei; w_am = w; fixed_am = fixed_dofs
            END IF
          ELSE IF (contact_enabled .AND. PRESENT(bathymetry) .AND. .NOT. bathymetry_flat) THEN
            CALL CD_HermiteCable_Static_Solve_AutoMesh(l0, ea, ei, w, q0, fixed_dofs, contact_z, CD_ZERO, &
                                                       8, 80, static_tol, 0.7_wp, CD_HC_HKAPPA_TARGET, CD_ZERO, &
                                                       CD_HC_REFINE_CAP, [2, 5], &
                                                       l0_am, ea_am, ei_am, w_am, &
                                                       q_static, curv, fixed_am, applied_scale, &
                                                       diag, res, iters, es, em, &
                                                       contact_diameter=diam, contact_kbot=opts%kbot, &
                                                       bathymetry=bathymetry, contact_frame_cs=frame_cs, &
                                                       require_resolved=opts%adaptive_mesh, &
                                                       axial_quadrature_order=opts%axial_quadrature_order, &
                                                       bending_quadrature_order=opts%bending_quadrature_order, &
                                                       require_tensile=tensile_error, &
                                                       compression_mode=CD_HC_COMPRESSION_STRICT, &
                                                       refine_non_axial=opts%adaptive_mesh, &
                                                       endconn_stiffness=endconn_k, &
                                                       endconn_direction=endconn_d0_local, &
                                                       endconn_mode=endconn_mode, &
                                                       waterline_z=CD_ZERO, dry_buoyancy=dry_b, &
                                                       water_weight=opts%rhoW*opts%g, current=cur_obj)
          ELSE IF (contact_enabled) THEN
            CALL CD_HermiteCable_Static_Solve_AutoMesh(l0, ea, ei, w, q0, fixed_dofs, contact_z, CD_ZERO, &
                                                       8, 80, static_tol, 0.7_wp, CD_HC_HKAPPA_TARGET, CD_ZERO, &
                                                       CD_HC_REFINE_CAP, [2, 5], &
                                                       l0_am, ea_am, ei_am, w_am, &
                                                       q_static, curv, fixed_am, applied_scale, &
                                                       diag, res, iters, es, em, &
                                                       contact_diameter=diam, contact_kbot=opts%kbot, &
                                                       contact_frame_cs=frame_cs, &
                                                       require_resolved=opts%adaptive_mesh, &
                                                       axial_quadrature_order=opts%axial_quadrature_order, &
                                                       bending_quadrature_order=opts%bending_quadrature_order, &
                                                       require_tensile=tensile_error, &
                                                       compression_mode=CD_HC_COMPRESSION_STRICT, &
                                                       refine_non_axial=opts%adaptive_mesh, &
                                                       endconn_stiffness=endconn_k, &
                                                       endconn_direction=endconn_d0_local, &
                                                       endconn_mode=endconn_mode, &
                                                       waterline_z=CD_ZERO, dry_buoyancy=dry_b, &
                                                       water_weight=opts%rhoW*opts%g, current=cur_obj)
          ELSE
            CALL CD_HermiteCable_Static_Solve_AutoMesh(l0, ea, ei, w, q0, fixed_dofs, -2000.0_wp, CD_ZERO, &
                                                       8, 80, static_tol, 0.7_wp, CD_HC_HKAPPA_TARGET, CD_ZERO, &
                                                       CD_HC_REFINE_CAP, [2, 5], &
                                                       l0_am, ea_am, ei_am, w_am, &
                                                       q_static, curv, fixed_am, applied_scale, &
                                                       diag, res, iters, es, em, &
                                                       require_resolved=opts%adaptive_mesh, &
                                                       axial_quadrature_order=opts%axial_quadrature_order, &
                                                       bending_quadrature_order=opts%bending_quadrature_order, &
                                                       require_tensile=tensile_error, &
                                                       compression_mode=CD_HC_COMPRESSION_STRICT, &
                                                       refine_non_axial=opts%adaptive_mesh, &
                                                       endconn_stiffness=endconn_k, &
                                                       endconn_direction=endconn_d0_local, &
                                                       endconn_mode=endconn_mode, &
                                                       waterline_z=CD_ZERO, dry_buoyancy=dry_b, &
                                                       water_weight=opts%rhoW*opts%g, current=cur_obj)
          END IF
          IF (es == CD_HCSTAT_OK .OR. es == CD_HCSTAT_BADINPUT) EXIT static_attempt
          IF (static_tol >= COUPLED_STATIC_TOL) EXIT static_attempt
          ! The looser tolerance helps a residual stall, not a converged state the tensile
          ! screen rejected for its compression (the same equilibrium would be found again).
          IF (INDEX(em, 'compressive axial resultant') > 0) EXIT static_attempt
          static_tol = COUPLED_STATIC_TOL
          IF (ALLOCATED(q_static)) DEALLOCATE (q_static)
          IF (ALLOCATED(curv)) DEALLOCATE (curv)
          IF (ALLOCATED(sequence_iters)) DEALLOCATE (sequence_iters)
          IF (ALLOCATED(q_sequence)) DEALLOCATE (q_sequence)
          IF (ALLOCATED(l0_am)) DEALLOCATE (l0_am)
          IF (ALLOCATED(ea_am)) DEALLOCATE (ea_am)
          IF (ALLOCATED(ei_am)) DEALLOCATE (ei_am)
          IF (ALLOCATED(w_am)) DEALLOCATE (w_am)
          IF (ALLOCATED(fixed_am)) DEALLOCATE (fixed_am)
        END DO static_attempt
        ! nested: l0_am may be unallocated when es /= OK, and .AND. does not short-circuit
        polish_ready = es == CD_HCSTAT_OK .AND. static_tol > static_tol_target
        IF (polish_ready) polish_ready = SIZE(l0_am) == SIZE(l0)
        IF (polish_ready) THEN
          CALL MOVE_ALLOC(q_static, q_coupled_tol)
          IF (PRESENT(bathymetry) .AND. .NOT. bathymetry_flat) THEN
            CALL CD_HermiteCable_Static_Solve_AutoMesh(l0, ea, ei, w, q_coupled_tol, fixed_dofs, &
                                                       contact_z, CD_ZERO, 8, 80, static_tol_target, 0.7_wp, &
                                                       CD_HC_HKAPPA_TARGET, CD_ZERO, CD_HC_REFINE_CAP, [2, 5], &
                                                       l0_am, ea_am, ei_am, w_am, q_static, curv, fixed_am, &
                                                       applied_scale, diag, res, polish_iters, es, em, &
                                                       contact_diameter=diam, contact_kbot=opts%kbot, &
                                                       bathymetry=bathymetry, contact_frame_cs=frame_cs, &
                                                       initial_polish=.TRUE., &
                                                       require_resolved=opts%adaptive_mesh, &
                                                       axial_quadrature_order=opts%axial_quadrature_order, &
                                                       bending_quadrature_order=opts%bending_quadrature_order, &
                                                       require_tensile=tensile_error, &
                                                       compression_mode=CD_HC_COMPRESSION_STRICT, &
                                                       refine_non_axial=opts%adaptive_mesh, &
                                                       endconn_stiffness=endconn_k, &
                                                       endconn_direction=endconn_d0_local, &
                                                       endconn_mode=endconn_mode, &
                                                       waterline_z=CD_ZERO, dry_buoyancy=dry_b, &
                                                       water_weight=opts%rhoW*opts%g, current=cur_obj)
          ELSE IF (contact_enabled) THEN
            CALL CD_HermiteCable_Static_Solve_AutoMesh(l0, ea, ei, w, q_coupled_tol, fixed_dofs, &
                                                       contact_z, CD_ZERO, 8, 80, static_tol_target, 0.7_wp, &
                                                       CD_HC_HKAPPA_TARGET, CD_ZERO, CD_HC_REFINE_CAP, [2, 5], &
                                                       l0_am, ea_am, ei_am, w_am, q_static, curv, fixed_am, &
                                                       applied_scale, diag, res, polish_iters, es, em, &
                                                       contact_diameter=diam, contact_kbot=opts%kbot, &
                                                       contact_frame_cs=frame_cs, initial_polish=.TRUE., &
                                                       require_resolved=opts%adaptive_mesh, &
                                                       axial_quadrature_order=opts%axial_quadrature_order, &
                                                       bending_quadrature_order=opts%bending_quadrature_order, &
                                                       require_tensile=tensile_error, &
                                                       compression_mode=CD_HC_COMPRESSION_STRICT, &
                                                       refine_non_axial=opts%adaptive_mesh, &
                                                       endconn_stiffness=endconn_k, &
                                                       endconn_direction=endconn_d0_local, &
                                                       endconn_mode=endconn_mode, &
                                                       waterline_z=CD_ZERO, dry_buoyancy=dry_b, &
                                                       water_weight=opts%rhoW*opts%g, current=cur_obj)
          ELSE
            CALL CD_HermiteCable_Static_Solve_AutoMesh(l0, ea, ei, w, q_coupled_tol, fixed_dofs, &
                                                       -2000.0_wp, CD_ZERO, 8, 80, static_tol_target, 0.7_wp, &
                                                       CD_HC_HKAPPA_TARGET, CD_ZERO, CD_HC_REFINE_CAP, [2, 5], &
                                                       l0_am, ea_am, ei_am, w_am, q_static, curv, fixed_am, &
                                                       applied_scale, diag, res, polish_iters, es, em, &
                                                       initial_polish=.TRUE., &
                                                       require_resolved=opts%adaptive_mesh, &
                                                       axial_quadrature_order=opts%axial_quadrature_order, &
                                                       bending_quadrature_order=opts%bending_quadrature_order, &
                                                       require_tensile=tensile_error, &
                                                       compression_mode=CD_HC_COMPRESSION_STRICT, &
                                                       refine_non_axial=opts%adaptive_mesh, &
                                                       endconn_stiffness=endconn_k, &
                                                       endconn_direction=endconn_d0_local, &
                                                       endconn_mode=endconn_mode, &
                                                       waterline_z=CD_ZERO, dry_buoyancy=dry_b, &
                                                       water_weight=opts%rhoW*opts%g, current=cur_obj)
          END IF
          iters = iters + polish_iters
        END IF
        IF (es == CD_HCSTAT_BADINPUT) THEN
          CALL fail(ErrStat, ErrMsg, 'finite-EI cable static solve rejected the input: '//TRIM(em)); RETURN
        ELSE IF (es == CD_HCSTAT_OK) THEN
          CALL audit_hermite_static(l0_am, q_static, ea_am, ei_am, w_am, diam_on(l0, l0_am, diam), endconn_mode, &
                                    sequence_done, sequence_msg, compression_note)
          IF (sequence_done) THEN
            ! A converged state must also be a STABLE equilibrium (positive-definite tangent
            ! on the free DOFs): a compressed strut, a buckled arch or an inverted fold is a
            ! saddle of the potential energy and never a physical static configuration.
            IF (PRESENT(bathymetry) .AND. .NOT. bathymetry_flat) THEN
              CALL hermite_static_stable(l0, l0_am, ea_am, ei_am, w_am, diam, dry_b, q_static, fixed_am, &
                                         contact_enabled, contact_z, frame_cs, endconn_k, endconn_d0_local, &
                                         endconn_mode, opts, stable, ErrStat, ErrMsg, bathymetry=bathymetry, &
                                         cur_obj=cur_obj)
            ELSE
              CALL hermite_static_stable(l0, l0_am, ea_am, ei_am, w_am, diam, dry_b, q_static, fixed_am, &
                                         contact_enabled, contact_z, frame_cs, endconn_k, endconn_d0_local, &
                                         endconn_mode, opts, stable, ErrStat, ErrMsg, cur_obj=cur_obj)
            END IF
            IF (ErrStat /= CD_DECKDRV_OK) RETURN
            IF (.NOT. stable) THEN
              sequence_done = .FALSE.
              sequence_msg = 'the converged state is an unstable equilibrium (tangent stiffness not positive definite)'
            END IF
          END IF
        ELSE
          sequence_msg = em
        END IF
        IF (.NOT. sequence_done) THEN
          compression_note = ''
          IF (ALLOCATED(l0_am)) DEALLOCATE (l0_am)
          IF (ALLOCATED(ea_am)) DEALLOCATE (ea_am)
          IF (ALLOCATED(ei_am)) DEALLOCATE (ei_am)
          IF (ALLOCATED(w_am)) DEALLOCATE (w_am)
          IF (ALLOCATED(q_static)) DEALLOCATE (q_static)
          IF (ALLOCATED(curv)) DEALLOCATE (curv)
          IF (ALLOCATED(fixed_am)) DEALLOCATE (fixed_am)
          IF (ALLOCATED(sequence_iters)) DEALLOCATE (sequence_iters)
          IF (ALLOCATED(q_sequence)) DEALLOCATE (q_sequence)
          IF (ALLOCATED(q_coupled_tol)) DEALLOCATE (q_coupled_tol)
        END IF
      ELSE
        ! Catenary-continuation route: exact EI = 0 catenary seed, bending-stiffness
        ! continuation and the caller-mesh polish (hermite_static_primary), then the same
        ! audit. A constant structured grid is the flat WtrDpth plane and takes the
        ! identical route.
        IF (PRESENT(bathymetry) .AND. .NOT. bathymetry_flat) THEN
          CALL hermite_static_primary(anchor, fairlead, l0, ea, ei, w, diam, dry_b, fixed_dofs, contact_enabled, &
                                      contact_z, frame_cs, endconn_k, endconn_d0_local, endconn_mode, opts, &
                                      static_tol, l0_am, ea_am, ei_am, w_am, q_static, curv, fixed_am, &
                                      applied_scale, diag, res, iters, es, em, primary_inadmissible, &
                                      tolerance_note, kink_refined, bathymetry=bathymetry, cur_obj=cur_obj, &
                                      walked=primary_walked)
        ELSE
          CALL hermite_static_primary(anchor, fairlead, l0, ea, ei, w, diam, dry_b, fixed_dofs, contact_enabled, &
                                      contact_z, frame_cs, endconn_k, endconn_d0_local, endconn_mode, opts, &
                                      static_tol, l0_am, ea_am, ei_am, w_am, q_static, curv, fixed_am, &
                                      applied_scale, diag, res, iters, es, em, primary_inadmissible, &
                                      tolerance_note, kink_refined, cur_obj=cur_obj, walked=primary_walked)
        END IF
        IF (es == CD_HCSTAT_OK) THEN
          ! adaptive_mesh refines while the resolution screen is fragile, up to its cap; an
          ! unreached accuracy target is reported, not turned into a failure.
          IF (opts%adaptive_mesh .AND. diag%fragile) WRITE (resolution_note, '(A,I0,A,ES10.3,A,ES10.3,A)') &
            'adaptive refinement stopped at ', applied_scale, 'x with h*kappa=', diag%h_kappa_peak, &
            ' and end boundary-layer ratio ', diag%boundary_ratio_peak, ' above their accuracy targets'
          CALL audit_hermite_static(l0_am, q_static, ea_am, ei_am, w_am, diam_on(l0, l0_am, diam), endconn_mode, &
                                    primary_done, primary_msg, compression_note)
          IF (primary_done) THEN
            IF (PRESENT(bathymetry) .AND. .NOT. bathymetry_flat) THEN
              CALL hermite_static_stable(l0, l0_am, ea_am, ei_am, w_am, diam, dry_b, q_static, fixed_am, &
                                         contact_enabled, contact_z, frame_cs, endconn_k, endconn_d0_local, &
                                         endconn_mode, opts, stable, ErrStat, ErrMsg, bathymetry=bathymetry, &
                                         cur_obj=cur_obj)
            ELSE
              CALL hermite_static_stable(l0, l0_am, ea_am, ei_am, w_am, diam, dry_b, q_static, fixed_am, &
                                         contact_enabled, contact_z, frame_cs, endconn_k, endconn_d0_local, &
                                         endconn_mode, opts, stable, ErrStat, ErrMsg, cur_obj=cur_obj)
            END IF
            IF (ErrStat /= CD_DECKDRV_OK) RETURN
            IF (.NOT. stable) THEN
              primary_done = .FALSE.
              primary_msg = 'the converged state is an unstable equilibrium (tangent stiffness not positive definite)'
            END IF
          END IF
          ! The equilibrium the anchor walk reached (the line too long to hang as a catenary)
          ! is not physical: the mesh-sequenced route still runs, and if it finds none either
          ! the failure names the geometry, as when the walk stops short.
          IF (.NOT. primary_done .AND. primary_walked) THEN
            ! The arch of the walked state faces the anchor; the bow behind the fairlead is the
            ! other bending-supported equilibrium.
            CALL bow_route(primary_done, bow_msg)
            IF (.NOT. primary_done) THEN
              walk_rejected = .TRUE.
              IF (LEN_TRIM(bow_msg) > 0) primary_msg = TRIM(short_message(primary_msg, 360))// &
                                                       '; the bow behind the fairlead: '// &
                                                       TRIM(short_message(bow_msg, 240))
            END IF
          END IF
        ELSE IF (primary_inadmissible) THEN
          CALL bow_route(primary_done, bow_msg)
          IF (LEN_TRIM(bow_msg) > 0) em = TRIM(short_message(em, 400))//'; the bow behind the fairlead: '// &
                                          TRIM(short_message(bow_msg, 240))
        END IF
        IF (.NOT. primary_done .AND. es /= CD_HCSTAT_OK .AND. primary_inadmissible) THEN
          ! No catenary clears the seabed, and the bending-supported branch traced by walking
          ! the anchor back (hermite_static_primary) gave no admissible equilibrium either;
          ! em says why (where the walk stopped, or what rejected its state).
          CALL fail_solve(ErrStat, ErrMsg, 'finite-EI cable static solve found no admissible planar '// &
                          'equilibrium clear of the seabed: the net-heavy line is too long for its span to '// &
                          'hang as a catenary ('//TRIM(em)//'); shorten the line or move the anchor'); RETURN
        ELSE IF (.NOT. primary_done .AND. es /= CD_HCSTAT_OK) THEN
          primary_msg = em
        END IF
        IF (.NOT. primary_done) THEN
          tolerance_note = .FALSE.
          IF (ALLOCATED(l0_am)) DEALLOCATE (l0_am)
          IF (ALLOCATED(ea_am)) DEALLOCATE (ea_am)
          IF (ALLOCATED(ei_am)) DEALLOCATE (ei_am)
          IF (ALLOCATED(w_am)) DEALLOCATE (w_am)
          IF (ALLOCATED(q_static)) DEALLOCATE (q_static)
          IF (ALLOCATED(curv)) DEALLOCATE (curv)
          IF (ALLOCATED(fixed_am)) DEALLOCATE (fixed_am)
        END IF
      END IF
      ! A planar equilibrium in a current along the plane was solved with the line held in
      ! its plane; it must also be stable once the line may leave it (a grounded run pushed
      ! toward its end can hold in the plane only as a saddle). Otherwise the out-of-plane
      ! (symmetry-breaking) pass finds the stable equilibrium.
      IF ((sequence_done .OR. primary_done) .AND. pass <= 2) THEN
        IF (planar_current_saddle()) THEN
          primary_done = .FALSE.
          sequence_done = .FALSE.
          planar_unstable = .TRUE.
          primary_msg = 'the planar equilibrium in the current is unstable out of its plane (tangent '// &
                        'stiffness not positive definite once the line may leave the plane)'
          sequence_msg = 'not run: the planar equilibrium in the current is unstable out of its plane'
          ! Kept (with its notes) in case no out-of-plane equilibrium is found.
          saddle_notes = compression_note
          saddle_tol_note = tolerance_note
          saddle_kink = kink_refined
          saddle_res = res
          CALL MOVE_ALLOC(l0_am, l0_saddle)
          CALL MOVE_ALLOC(ea_am, ea_saddle)
          CALL MOVE_ALLOC(ei_am, ei_saddle)
          CALL MOVE_ALLOC(w_am, w_saddle)
          CALL MOVE_ALLOC(q_static, q_saddle)
          CALL MOVE_ALLOC(curv, curv_saddle)
          CALL MOVE_ALLOC(fixed_am, fixed_saddle)
          compression_note = ''
          tolerance_note = .FALSE.
          kink_refined = .FALSE.
          IF (ALLOCATED(sequence_iters)) DEALLOCATE (sequence_iters)
          IF (ALLOCATED(q_sequence)) DEALLOCATE (q_sequence)
          IF (ALLOCATED(q_coupled_tol)) DEALLOCATE (q_coupled_tol)
        END IF
      END IF
      IF (sequence_done .OR. primary_done) EXIT route_pass
    END DO route_pass
    IF (sym_broken) THEN
      IF (primary_done) CALL symmetric_current_polish(primary_done)
      IF (.NOT. primary_done) THEN
        primary_msg = planar_primary_msg
        sequence_msg = planar_sequence_msg
      END IF
    END IF
    ! No out-of-plane equilibrium beside a planar one that is a saddle out of its plane: the
    ! planar equilibrium is kept, held in its plane, and a note says so.
    saddle_kept = .FALSE.
    IF (.NOT. (sequence_done .OR. primary_done) .AND. ALLOCATED(q_saddle)) THEN
      IF (ALLOCATED(cur_exact)) cur_obj = cur_exact
      CALL MOVE_ALLOC(l0_saddle, l0_am)
      CALL MOVE_ALLOC(ea_saddle, ea_am)
      CALL MOVE_ALLOC(ei_saddle, ei_am)
      CALL MOVE_ALLOC(w_saddle, w_am)
      CALL MOVE_ALLOC(q_saddle, q_static)
      CALL MOVE_ALLOC(curv_saddle, curv)
      CALL MOVE_ALLOC(fixed_saddle, fixed_am)
      compression_note = saddle_notes
      tolerance_note = saddle_tol_note
      kink_refined = saddle_kink
      res = saddle_res
      primary_done = .TRUE.
      saddle_kept = .TRUE.
    END IF
    IF (.NOT. (sequence_done .OR. primary_done)) THEN
      ! A mesh below the conditioning limit is the likely cause and is named first.
      IF (LEN_TRIM(fine_note) > 0) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'finite-EI cable static solve failed; '//TRIM(fine_note)// &
                        '. Catenary-continuation route: '//TRIM(short_message(primary_msg, 360))// &
                        '. Mesh-sequenced route: '//TRIM(short_message(sequence_msg, 360))); RETURN
      END IF
      IF (walk_rejected) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'finite-EI cable static solve found no admissible planar equilibrium '// &
                        'clear of the seabed: the net-heavy line is too long for its span to hang as a catenary, '// &
                        'and the equilibrium held by its bending stiffness that the anchor walk reached is '// &
                        'rejected ('// &
                        TRIM(short_message(primary_msg, 360))//'); mesh-sequenced route: '// &
                        TRIM(short_message(sequence_msg, 240))//'; shorten the line or move the anchor'); RETURN
      END IF
      ! A current with no tension-only equilibrium is named first, in full: the nested
      ! route diagnostics below are bounded and would cut it. A line already compressed
      ! without the current is named before that: the current starts from that layout.
      limit_text = ''
      IF (opts%has_current) CALL still_water_compression(limit_text)
      IF (LEN_TRIM(limit_text) > 0) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'finite-EI cable has no static equilibrium in the current: '// &
                        TRIM(limit_text)//'. Catenary-continuation route: '// &
                        TRIM(short_message(primary_msg, 360))//'. Mesh-sequenced route: '// &
                        TRIM(short_message(sequence_msg, 360))); RETURN
      END IF
      limit_text = current_limit_diagnosis(primary_msg)
      IF (LEN_TRIM(limit_text) == 0) limit_text = current_limit_diagnosis(sequence_msg)
      IF (LEN_TRIM(limit_text) > 0) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'finite-EI cable has no tension-only static equilibrium in the '// &
                        'current: '//TRIM(limit_text)//'. Catenary-continuation route: '// &
                        TRIM(short_message(primary_msg, 360))//'. Mesh-sequenced route: '// &
                        TRIM(short_message(sequence_msg, 360))); RETURN
      END IF
      CALL fail_solve(ErrStat, ErrMsg, 'finite-EI cable static solve found no physical equilibrium. '// &
                      'Catenary-continuation route: '//TRIM(short_message(primary_msg, 360))// &
                      '. Mesh-sequenced route: '//TRIM(short_message(sequence_msg, 360))); RETURN
    END IF
    ! Initialisation notes: printed by a standalone run, returned to a reporting caller.
    IF (PRESENT(init_note)) THEN
      init_note = ''
      IF (LEN_TRIM(fine_note) > 0) init_note = TRIM(fine_note)
    END IF
    ! "line N carries ..." reads as one clause; the mesh variant is a "line N: ..." note
    IF (LEN_TRIM(compression_note) > 0) THEN
      IF (starts_with(compression_note, 'carries')) THEN
        CALL report_note('line '//TRIM(int_to_str(ln%id))//' '//TRIM(compression_note))
      ELSE
        CALL report_note('line '//TRIM(int_to_str(ln%id))//': '//TRIM(compression_note))
      END IF
    END IF
    IF (kink_refined .AND. primary_done) THEN
      WRITE (note_text, '(A,I0,A,I0,A,I0,A)') 'line ', ln%id, ': the deck mesh (', SIZE(l0), &
        ' elements) could not resolve the curvature of the equilibrium; refined to ', SIZE(l0_am), ' elements'
      CALL report_note(note_text)
    END IF
    IF (LEN_TRIM(resolution_note) > 0 .AND. primary_done) &
      CALL report_note('line '//TRIM(int_to_str(ln%id))//': '//TRIM(resolution_note))
    IF (tolerance_note) THEN
      WRITE (note_text, '(A,I0,A,ES9.2,A,ES9.2)') 'line ', ln%id, ': static residual floor above the '// &
        'dynamic tolerance ', static_tol_target, '; equilibrium accepted at the relative residual ', res
      CALL report_note(note_text)
    END IF
    IF (saddle_kept) THEN
      WRITE (note_text, '(A,I0,A)') 'line ', ln%id, ': the equilibrium in the current is held in the '// &
        'vertical plane of the line; it is unstable out of that plane and no out-of-plane equilibrium was '// &
        'found, so a cross-flow or a lateral disturbance can move the line away from it'
      CALL report_note(note_text)
    END IF
    IF (tors_line) THEN
      CALL torsion_stage(es, em)
      IF (es /= CD_DECKDRV_OK) THEN
        ErrStat = es
        ErrMsg = 'CableDyn_DeckDriver: line '//TRIM(int_to_str(ln%id))//': '//TRIM(em)
        RETURN
      END IF
    END IF
    IF (contact_enabled) CALL anchor_overshoot_note()
    ! Safety is independent of the opt-in adaptive accuracy policy. Diagnose the
    ! equilibrium on the FINAL user/refined mesh and reject an element-localized fold
    ! even when Newton balanced its residual and adaptive_mesh is false.
    IF (PRESENT(bathymetry) .AND. .NOT. bathymetry_flat) THEN
      CALL CD_HermiteCable_Resolution_Metrics(l0_am, q_static, contact_z, CD_ZERO, &
                                              CD_HC_KINK_LIMIT, diag, es, em, &
                                              bathymetry=bathymetry, contact_frame_cs=frame_cs, &
                                              EA=ea_am, EI=ei_am, compression_mode=CD_HC_COMPRESSION_STRICT)
    ELSE
      CALL CD_HermiteCable_Resolution_Metrics(l0_am, q_static, contact_z, CD_ZERO, &
                                              CD_HC_KINK_LIMIT, diag, es, em, EA=ea_am, EI=ei_am, &
                                              compression_mode=CD_HC_COMPRESSION_STRICT)
    END IF
    IF (es /= CD_HCSTAT_OK) THEN
      CALL fail_solve(ErrStat, ErrMsg, 'finite-EI mesh safety diagnosis failed: '//TRIM(em)); RETURN
    END IF
    IF (diag%h_kappa_peak > CD_HC_KINK_LIMIT) THEN
      WRITE (em, '(A,ES12.5,A,ES12.5,A,I0)') &
        'unresolved/kinked finite-EI equilibrium: max(h*kappa)=', diag%h_kappa_peak, &
        ' > safety limit=', CD_HC_KINK_LIMIT, ' at element ', diag%h_kappa_elem
      CALL fail_solve(ErrStat, ErrMsg, TRIM(em)); RETURN
    END IF
    IF (opts%tensile_mode == CD_HCDYN_TENSILE_ERROR .AND. diag%axial_compression) THEN
      WRITE (em, '(A,ES12.5,A,ES12.5,A,I0,A,F8.5,A,ES12.5)') &
        'finite-EI axial compression under tensile_safety True: element-mean axial force=', &
        diag%axial_strain_min_resultant, &
        ' N below tolerance=', diag%axial_tolerance, ' N at element ', diag%axial_strain_min_elem, &
        ', xi=', diag%axial_strain_min_xi, ', strain=', diag%axial_strain_min
      CALL fail_solve(ErrStat, ErrMsg, TRIM(em)); RETURN
    END IF
    ! Build the coarse Morison arrays, then map every per-element quantity onto the
    ! refined reference-arc mesh.  This covers both global refinement and the local
    ! axial-oscillation refinement used by tensile safety.  Every child inherits the
    ! property of the original element containing its reference-arc midpoint.
    ALLOCATE (cdn(SIZE(l0)), cdt(SIZE(l0)), can(SIZE(l0)), cat(SIZE(l0)))
    CALL finite_hydro_arrays(ln, sections, types, diam, cdn, cdt, can, cat)
    IF (SIZE(l0_am) /= SIZE(l0)) THEN
      CALL remap_elem_by_reference_arc(rho_a, l0, l0_am)
      CALL remap_elem_by_reference_arc(diam, l0, l0_am)
      CALL remap_elem_by_reference_arc(cdn, l0, l0_am)
      CALL remap_elem_by_reference_arc(cdt, l0, l0_am)
      CALL remap_elem_by_reference_arc(can, l0, l0_am)
      CALL remap_elem_by_reference_arc(cat, l0, l0_am)
      CALL remap_elem_by_reference_arc(ba_raw, l0, l0_am)
    END IF
    CALL MOVE_ALLOC(l0_am, l0)
    CALL MOVE_ALLOC(ea_am, ea)
    CALL MOVE_ALLOC(ei_am, ei)
    CALL MOVE_ALLOC(w_am, w)
    CALL MOVE_ALLOC(fixed_am, fixed_dofs)
    ALLOCATE (ba(SIZE(l0)))
    DO i = 1, SIZE(l0)
      ! Resolve negative damping-ratio inputs only after adaptive remeshing because
      ! BA = zeta*l0*sqrt(EA*mass_per_length) is defined for the final element length.
      ! A direct positive BA remains a mesh-independent constitutive coefficient.
      CALL CD_Resolve_Legacy_BA(ba_raw(i), l0(i), ea(i), rho_a(i), ba(i), es, em)
      IF (es /= CD_DAMP_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'finite-EI BA resolution failed: '//TRIM(em)); RETURN
      END IF
    END DO
    nnode = SIZE(l0) + 1
    ndof = 6*nnode
    coupled_node = nnode
    ! The equilibrium solve may use a vertical cable plane to remove the static
    ! out-of-plane gauge mode, but a coupled dynamic cable must be free to leave that
    ! plane for EVERY end-connection type.  OpenFAST prescribes all three fairlead
    ! translations.  Retaining the static y/m_y constraints while prescribing a sway
    ! displacement at the fairlead forces the complete offset into the end element,
    ! producing a mesh-dependent curvature spike and, under continued excitation, a
    ! collapse of the endpoint tangent norm.  Release the interior and tangent DOFs at
    ! dynamic hand-off; only the two endpoint translations remain constrained.  The
    ! planar equilibrium is still an exact three-dimensional initial state by symmetry.
    ALLOCATE (dynamic_fixed_dofs(6))
    dynamic_fixed_dofs = [1, 2, 3, ndof - 5, ndof - 4, ndof - 3]
    IF (has_att) THEN
      w_bare = w_bare_deck
      IF (SIZE(l0) /= SIZE(l0_deck_att)) CALL remap_elem_by_reference_arc(w_bare, l0_deck_att, l0)
      CALL attachment_nodes(l0, ln%att(1, :), att_node, att_offset)
      CALL attachment_static_polish(l0, ea, ei, w_bare, w, diam, att_node, ln%att, q_static, fixed_dofs, &
                                    contact_enabled, contact_z, frame_cs, endconn_k, endconn_d0_local, &
                                    endconn_mode, opts, static_tol, ErrStat, ErrMsg, bathymetry, cur_obj)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      w = w_bare
      WRITE (note_text, '(A,I0,A,I0,A,ES10.3,A)') 'line ', ln%id, ': ', SIZE(att_node), &
        ' attachment(s) lumped at the nearest nodes (largest arc offset ', att_offset, ' m)'
      CALL report_note(note_text)
    END IF
    ! Dynamic step controls: a relative Newton tolerance of 5e-3 (0.5% of the physical weight
    ! force scale, on the coupling boundary) with a generous iteration budget. This is the
    ! usual order for a coupling-boundary force residual; a stiffer 1e-4/1e-3 would demand a
    ! static seed tighter than the static solve delivers and add
    ! no coupling-force accuracy. The 1e-6 static seed sits far inside it at rest.
    CALL CD_HFMF_Init(cable, l0, ea, ei, rho_a, w, q_static, dynamic_fixed_dofs, contact_z, CD_ZERO, &
                      opts%rho_inf, dt, coupled_node, es, em, max_iter=step_max_iter, tol=step_tol, &
                      frame_cs=frame_cs, axial_quadrature_order=opts%axial_quadrature_order, &
                      bending_quadrature_order=opts%bending_quadrature_order)
    IF (es /= CD_HFMF_OK) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI cable coupled-shell init failed: '//TRIM(em)); RETURN
    END IF
    IF (ANY(ba > CD_ZERO)) THEN
      CALL CD_HFMF_Set_Axial_Damping(cable, ba, es, em)
      IF (es /= CD_HFMF_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'finite-EI cable axial-damping wiring failed: '//TRIM(em)); RETURN
      END IF
    END IF
    IF (ANY(endconn_mode /= CD_ENDCONN_PINNED)) THEN
      IF (endconn_mode(2) /= CD_ENDCONN_PINNED) THEN
        CALL CD_HFMF_Set_EndConnection(cable, endconn_k, endconn_d0_global, es, em, &
                                       coupled_d0_parent=-ln%endconn_ez_ref(:, 1), &
                                       parent_orientation=fairlead_dcm, connection_mode=endconn_mode)
      ELSE
        CALL CD_HFMF_Set_EndConnection(cable, endconn_k, endconn_d0_global, es, em, &
                                       connection_mode=endconn_mode)
      END IF
      IF (es /= CD_HFMF_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'finite-EI cable end-connection wiring failed: '//TRIM(em)); RETURN
      END IF
    END IF
    IF (tors_line) THEN
      ! The End A torsion frame (director -Ez, reference normal Nx, in the frame of Ez) is held
      ! by End A's parent and turns with it in the dynamics, whatever the bending connection.
      BLOCK
        REAL(wp) :: tframe(3, 2)
        tframe(:, 1) = -ln%endconn_ez_ref(:, 1)/NORM2(ln%endconn_ez_ref(:, 1))
        tframe(:, 2) = ln%tors_nx(:, 1) - DOT_PRODUCT(ln%tors_nx(:, 1), tframe(:, 1))*tframe(:, 1)
        tframe(:, 2) = tframe(:, 2)/NORM2(tframe(:, 2))
        CALL CD_HFMF_Set_Torsion(cable, tors, es, em, coupled_frame_parent=tframe, parent_orientation=fairlead_dcm)
      END BLOCK
      IF (es /= CD_HFMF_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'finite-EI cable torsion wiring failed: '//TRIM(em)); RETURN
      END IF
    END IF
    IF (contact_enabled) THEN
      CALL CD_Nodal_Seabed_Stiffness(opts%kbot, diam, l0, contact_kn, es, em)
      IF (es /= CD_LINE_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'finite-EI Hermite contact stiffness failed: '//TRIM(em)); RETURN
      END IF
      ALLOCATE (contact_cn(SIZE(contact_kn)))
      contact_cn = contact_kn*(opts%cbot/opts%kbot)
      IF (PRESENT(bathymetry)) THEN
        CALL CD_HFMF_Set_Contact(cable, contact_kn, contact_cn, opts%friction_mu, es, em, bathymetry=bathymetry)
      ELSE
        CALL CD_HFMF_Set_Contact(cable, contact_kn, contact_cn, opts%friction_mu, es, em)
      END IF
      IF (es == CD_HFMF_OK .AND. opts%friction_mu_axial > CD_ZERO .AND. opts%friction_mu > CD_ZERO) &
        CALL CD_HermiteCable_Dyn_Set_Friction_Axial(cable%line, opts%friction_mu_axial, es, em)
      IF (es /= CD_HFMF_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'finite-EI Hermite contact wiring failed: '//TRIM(em)); RETURN
      END IF
      ! The static friction force of every node becomes the initial force of its
      ! elastic-plastic spring, so the march starts in the static equilibrium.
      IF (static_friction) THEN
        ALLOCATE (fr_anchor(2, nnode), fr_force(2, nnode))
        IF (PRESENT(bathymetry) .AND. .NOT. bathymetry_flat) THEN
          CALL CD_HermiteCable_Friction_Anchors(l0, q_static, cur_obj%friction, contact_kn, contact_z, &
                                                fr_anchor, fr_force, es, em, bathymetry=bathymetry, &
                                                contact_frame_cs=frame_cs)
        ELSE
          CALL CD_HermiteCable_Friction_Anchors(l0, q_static, cur_obj%friction, contact_kn, contact_z, &
                                                fr_anchor, fr_force, es, em)
        END IF
        IF (es == CD_HCSTAT_OK) CALL CD_HermiteCable_Dyn_Set_Friction_Anchors(cable%line, fr_anchor, es, em)
        IF (es /= CD_HCSTAT_OK) THEN
          CALL fail(ErrStat, ErrMsg, 'finite-EI seabed friction wiring failed: '//TRIM(em)); RETURN
        END IF
      END IF
    END IF
    ! Wire the deck's Morison hydrodynamics (drag + added mass) into the coupled cable. Beyond
    ! being the physics the deck declares (Cdn/Cdt/Can/Cat), the normal drag is the cable's
    ! physical damping: without it a slender power cable driven at the wave frequency rings and
    ! the implicit Newton crawls; with it each coupling step converges quickly. Waterline at
    ! z = 0 and no ambient current here: the standalone march refreshes the deck current and
    ! waves each step, and the coupled route holds the host field. The
    ! diam/cdn/cdt/can/cat arrays were built and (if refined) replicated with the mesh above.
    CALL CD_HFMF_Set_Drag(cable, opts%rhoW, diam, cdn, cdt, CD_ZERO, [CD_ZERO, CD_ZERO, CD_ZERO], es, em, &
                          gravity=opts%g)
    IF (es /= CD_HFMF_OK) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI cable drag wiring failed: '//TRIM(em)); RETURN
    END IF
    CALL CD_HFMF_Set_AddedMass(cable, opts%rhoW, diam, can, cat, CD_ZERO, es, em)
    IF (es /= CD_HFMF_OK) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI cable added-mass wiring failed: '//TRIM(em)); RETURN
    END IF
    IF (has_att) THEN
      CALL CD_HFMF_Set_Attachments(cable, att_node, ln%att(2, :), ln%att(3, :), ln%att(4, :), ln%att(6, :), &
                                   ln%att(5, :), opts%rhoW, opts%g, es, em)
      IF (es /= CD_HFMF_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'finite-EI cable attachment wiring failed: '//TRIM(em)); RETURN
      END IF
    END IF
    IF (opts%tensile_mode /= CD_HCDYN_TENSILE_OFF) THEN
      CALL CD_HFMF_Set_Tensile_Monitor(cable, opts%tensile_mode, es, em, &
                                       opts%tensile_strain_tolerance)
      IF (es /= CD_HFMF_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'finite-EI cable tensile-safety wiring failed: '//TRIM(em)); RETURN
      END IF
    END IF
    CALL CD_HFMF_Set_Recovery_Max_Substeps(cable, opts%recovery_max_substeps, es, em)
    IF (es /= CD_HFMF_OK) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI recovery-cap wiring failed: '//TRIM(em)); RETURN
    END IF
    ! The deck OPTIONS modified_newton drives the SAME switch on every solver the deck
    ! builds: the EI=0 system consumes it through dynamic_cfg, and each coupled finite-EI
    ! cable receives it here (within-step tangent reuse, contraction-gated -- see
    ! CD_HermiteCable_Dyn_Set_ModifiedNewton). Off by default keeps the step bit-identical.
    IF (opts%dynamic_modified_newton) THEN
      CALL CD_HFMF_Set_ModifiedNewton(cable, .TRUE., es, em)
      IF (es /= CD_HFMF_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'finite-EI cable modified-Newton wiring failed: '//TRIM(em)); RETURN
      END IF
    END IF
    ! OPTIONS alpha_force_blend selects the generalised-alpha blend of the cable dynamics.
    CALL CD_HermiteCable_Dyn_Set_ForceBlend(cable%line, opts%alpha_force_blend, es, em)
    IF (es /= CD_HCDYN_OK) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI cable alpha_force_blend wiring failed: '//TRIM(em)); RETURN
    END IF
  CONTAINS

    SUBROUTINE torsion_stage(est, emt)
      !! The condensed-torsion load stage of a line restrained in torsion at both ends: from the
      !! converged untwisted state on the final mesh (l0_am), CD_HermiteCable_Static_Solve ramps
      !! the imposed twist Phi = Pretwist(End B) - Pretwist(End A) with the same loads, contact,
      !! end connections and current as the untwisted solve, tests every stage for stability and
      !! descends from an unstable one. End frames are taken in the solve frame: internal end 1
      !! is deck End B (global axes), end 2 deck End A (its parent's axes, turned with it).
      INTEGER, INTENT(OUT) :: est
      CHARACTER(*), INTENT(OUT) :: emt
      REAL(wp) :: nvec(3), dvec(3), tol_t
      INTEGER :: k, attempt
      CHARACTER(320) :: tnote
      est = CD_DECKDRV_OK
      emt = ''
      tors = CD_HermiteTorsionType()
      tors%active = .TRUE.
      tors%quadrature_order = opts%bending_quadrature_order
      tors%gj = gj_in
      IF (SIZE(l0_am) /= SIZE(l0)) CALL remap_elem_by_reference_arc(tors%gj, l0, l0_am)
      DO k = 1, 2
        dvec = endconn_d0_local(:, k)/NORM2(endconn_d0_local(:, k))
        IF (k == 1) THEN
          nvec = ln%tors_nx(:, 2)
        ELSE
          nvec = MATMUL(TRANSPOSE(fairlead_dcm), ln%tors_nx(:, 1))
        END IF
        nvec = [frame_cs(1)*nvec(1) + frame_cs(2)*nvec(2), -frame_cs(2)*nvec(1) + frame_cs(1)*nvec(2), nvec(3)]
        nvec = nvec - DOT_PRODUCT(nvec, dvec)*dvec
        IF (NORM2(nvec) < TORS_NX_PARALLEL_TOL) THEN
          est = CD_DECKDRV_BADINPUT
          emt = 'torsion reference normal parallel to the end direction'
          RETURN
        END IF
        tors%ends(:, 2*k - 1) = dvec
        tors%ends(:, 2*k) = nvec/NORM2(nvec)
      END DO
      tors%end_compliance = CD_ZERO
      IF (ln%tors_mode(2) == TORS_FINITE) tors%end_compliance(1) = CD_ONE/ln%tors_k(2)
      IF (ln%tors_mode(1) == TORS_FINITE) tors%end_compliance(2) = CD_ONE/ln%tors_k(1)
      tors%phi = ln%tors_pretwist(2) - ln%tors_pretwist(1)
      ! Rotating a buckled shape about a common clamp axis is an exact symmetry only without
      ! weight or current, with both ends clamped on one axis.
      tors%zero_mode_allowed = .NOT. ANY(ABS(w_am) > CD_ZERO) .AND. .NOT. opts%has_current .AND. &
                               ALL(endconn_mode == CD_ENDCONN_RIGID) .AND. &
                               DOT_PRODUCT(tors%ends(:, 1), tors%ends(:, 3)) > CD_ONE - 1.0e-12_wp
      ! As for the untwisted solve: a residual stall at the tight standalone tolerance is
      ! repeated at the coupled static tolerance (a round-off floor of a stiff, light line).
      DO attempt = 1, 2
        tol_t = static_tol_target
        IF (attempt == 2) tol_t = COUPLED_STATIC_TOL
        IF (PRESENT(bathymetry) .AND. .NOT. bathymetry_flat) THEN
          CALL hermite_static_torsion(l0, l0_am, ea_am, ei_am, w_am, diam, dry_b, q_static, curv, fixed_am, &
                                      contact_enabled, contact_z, frame_cs, endconn_k, endconn_d0_local, &
                                      endconn_mode, opts, tol_t, tors, est, emt, bathymetry=bathymetry, &
                                      cur_obj=cur_obj)
        ELSE
          CALL hermite_static_torsion(l0, l0_am, ea_am, ei_am, w_am, diam, dry_b, q_static, curv, fixed_am, &
                                      contact_enabled, contact_z, frame_cs, endconn_k, endconn_d0_local, &
                                      endconn_mode, opts, tol_t, tors, est, emt, cur_obj=cur_obj)
        END IF
        IF (est == CD_DECKDRV_OK .OR. est == CD_DECKDRV_BADINPUT) EXIT
        IF (static_tol_target >= COUPLED_STATIC_TOL) EXIT
      END DO
      IF (est == CD_DECKDRV_OK .AND. tol_t > static_tol_target) THEN
        WRITE (tnote, '(A,I0,A,ES9.2,A,ES9.2)') 'line ', ln%id, ': torsion static residual floor above the '// &
          'tolerance ', static_tol_target, '; twisted equilibrium accepted at ', tol_t
        CALL report_note(tnote)
      END IF
      IF (est /= CD_DECKDRV_OK) RETURN
      WRITE (tnote, '(A,I0,A,ES12.5,A,ES12.5,A,I0,A,I0,A)') 'line ', ln%id, ': torsion solved, imposed twist ', &
        tors%phi*45.0_wp/QUARTER_PI, ' deg, torque ', tors%torque, ' N m (', tors%ramp_steps, &
        ' twist stage(s), ', tors%descents, ' buckling descent(s))'
      CALL report_note(tnote)
    END SUBROUTINE torsion_stage

    SUBROUTINE bow_route(done, why)
      !! A line too long for its span whose anchor walk failed or reached an equilibrium the
      !! audit rejects (an arch facing the anchor that has looped through itself): trace the
      !! bow behind the fairlead (hermite_static_primary with fold_walk) and audit it like the
      !! primary route's state. Flat seabed, still water. done is set with the state in the
      !! *_am outputs; otherwise why says what stopped it (blank when not tried).
      LOGICAL, INTENT(OUT) :: done
      CHARACTER(*), INTENT(OUT) :: why
      INTEGER :: es_b
      CHARACTER(1024) :: em_b
      LOGICAL :: inadm_b, walked_b, tol_b, kink_b, stable_b
      done = .FALSE.
      why = ''
      IF (PRESENT(bathymetry) .AND. .NOT. bathymetry_flat) RETURN
      IF (opts%has_current .OR. .NOT. contact_enabled) RETURN
      ! A bow held by its bending stiffness is in compression, which tensile_safety True rejects.
      IF (opts%tensile_mode == CD_HCDYN_TENSILE_ERROR) RETURN
      CALL hermite_static_primary(anchor, fairlead, l0, ea, ei, w, diam, dry_b, fixed_dofs, contact_enabled, &
                                  contact_z, frame_cs, endconn_k, endconn_d0_local, endconn_mode, opts, &
                                  static_tol, l0_am, ea_am, ei_am, w_am, q_static, curv, fixed_am, &
                                  applied_scale, diag, res, iters, es_b, em_b, inadm_b, &
                                  tol_b, kink_b, cur_obj=cur_obj, walked=walked_b, fold_walk=.TRUE.)
      IF (es_b /= CD_HCSTAT_OK) THEN
        why = em_b
        RETURN
      END IF
      CALL audit_hermite_static(l0_am, q_static, ea_am, ei_am, w_am, diam_on(l0, l0_am, diam), endconn_mode, &
                                done, why, compression_note)
      IF (done) THEN
        CALL hermite_static_stable(l0, l0_am, ea_am, ei_am, w_am, diam, dry_b, q_static, fixed_am, &
                                   contact_enabled, contact_z, frame_cs, endconn_k, endconn_d0_local, &
                                   endconn_mode, opts, stable_b, es_b, em_b, cur_obj=cur_obj)
        IF (es_b /= CD_DECKDRV_OK) THEN
          done = .FALSE.
          why = em_b
        ELSE IF (.NOT. stable_b) THEN
          done = .FALSE.
          why = 'the converged state is an unstable equilibrium (tangent stiffness not positive definite)'
        END IF
      END IF
      IF (done) THEN
        tolerance_note = tol_b
        kink_refined = kink_b
        why = ''
      ELSE
        compression_note = ''
      END IF
    END SUBROUTINE bow_route

    SUBROUTINE still_water_compression(text)
      !! On a failed solve in a current: whether the same line without the current is
      !! already in axial compression (an element-mean force below -1e-3 of the peak
      !! tension, held only by the bending stiffness). Returns the diagnosis, or blank.
      CHARACTER(*), INTENT(OUT) :: text
      TYPE(DeckOptions) :: opts_sw
      TYPE(CD_HFMF_ModuleType) :: sw_cable
      INTEGER :: sw_node, esw, e_min, wios
      REAL(wp) :: t_min, t_max, s_min
      CHARACTER(1024) :: emw
      CHARACTER(2048) :: sw_note
      text = ''
      opts_sw = opts
      opts_sw%has_current = .FALSE.
      opts_sw%has_current_profile = .FALSE.
      IF (PRESENT(bathymetry)) THEN
        CALL build_one_hermite_cable(ln, sections, types, points, opts_sw, dt, sw_cable, sw_node, esw, emw, &
                                     standalone_controls=.FALSE., bathymetry=bathymetry, &
                                     fairlead_orientation=fairlead_dcm, init_note=sw_note)
      ELSE
        CALL build_one_hermite_cable(ln, sections, types, points, opts_sw, dt, sw_cable, sw_node, esw, emw, &
                                     standalone_controls=.FALSE., fairlead_orientation=fairlead_dcm, &
                                     init_note=sw_note)
      END IF
      IF (esw == CD_DECKDRV_OK) THEN
        CALL CD_HermiteCable_Mean_Axial_Extremes(sw_cable%line%l0, sw_cable%line%EA, sw_cable%line%q, t_min, &
                                                 t_max, e_min, s_min, esw, emw)
        IF (esw == CD_HCSTAT_OK .AND. t_min < -1.0e-3_wp*t_max) THEN
          WRITE (text, '(A,ES10.3,A,F10.2,A,ES10.3,A)', IOSTAT=wios) 'the line is already in axial '// &
            'compression without the current (element mean ', t_min, ' N at unstretched arc length ', &
            s_min, ' m from the anchor, peak tension ', t_max, ' N), a layout that only its bending '// &
            'stiffness holds; the current pushes that layout further and no equilibrium follows it'
        END IF
      END IF
      CALL CD_HFMF_End(sw_cable)
    END SUBROUTINE still_water_compression

    LOGICAL FUNCTION symmetric_current_retry() RESULT(retry)
      !! Set up the symmetry-breaking pass (see route_pass): out-of-plane DOFs freed and a
      !! cross-flow of SYM_BREAK of the horizontal current speed added. Only for an in-plane
      !! current whose planar solve failed in the current (not in still water, not over
      !! structured bathymetry, not for a rotationally rigid end).
      REAL(wp), PARAMETER :: SYM_BREAK = 1.0e-2_wp
      REAL(wp) :: nrm(2), uh
      INTEGER :: k
      retry = .FALSE.
      IF (.NOT. opts%has_current .OR. require_3d_static .OR. .NOT. ALLOCATED(cur_obj)) RETURN
      IF (ANY(endconn_mode == CD_ENDCONN_RIGID)) RETURN
      IF (PRESENT(bathymetry)) THEN
        IF (.NOT. bathymetry_flat) RETURN
      END IF
      IF (INDEX(primary_msg, 'current') == 0) RETURN
      planar_primary_msg = primary_msg
      planar_sequence_msg = sequence_msg
      ALLOCATE (cur_exact, SOURCE=cur_obj)
      DEALLOCATE (fixed_dofs)
      ALLOCATE (fixed_dofs(6))
      fixed_dofs = [1, 2, 3, ndof - 5, ndof - 4, ndof - 3]
      sym_broken = .TRUE.
      nrm = [-frame_cs(2), frame_cs(1)]
      uh = NORM2(cur_obj%velocity(1:2))
      cur_obj%velocity(1:2) = cur_obj%velocity(1:2) + SYM_BREAK*uh*nrm
      IF (ALLOCATED(cur_obj%profile_velocity)) THEN
        DO k = 1, SIZE(cur_obj%profile_velocity, 2)
          uh = NORM2(cur_obj%profile_velocity(1:2, k))
          cur_obj%profile_velocity(1:2, k) = cur_obj%profile_velocity(1:2, k) + SYM_BREAK*uh*nrm
        END DO
      END IF
      retry = .TRUE.
    END FUNCTION symmetric_current_retry

    SUBROUTINE symmetric_current_polish(done)
      !! Pass 3 solved the line under the perturbed current: restore the exact current and
      !! polish from that state on its mesh, then audit it again. As on the
      !! catenary-continuation route, a residual floor above the tight tolerance (it rises
      !! with the mesh density) is accepted at the coupled static tolerance, and on the
      !! seabed at the contact floor tolerance, and reported. A state whose bends the mesh
      !! cannot resolve (unresolved/kinked) is polished again on a mesh refined until they
      !! are, as on that route.
      LOGICAL, INTENT(OUT) :: done
      REAL(wp), PARAMETER :: CONTACT_FLOOR_TOL = 1.0e-5_wp
      REAL(wp), ALLOCATABLE :: l0_s(:), ea_s(:), ei_s(:), w_s(:), q_s(:), d_s(:), dry_s(:)
      INTEGER, ALLOCATABLE :: fixed_s(:)
      INTEGER :: scale_s, it_s, es_s, k_tol, k_ref, cap_r
      REAL(wp) :: tol_s(3), h_t
      LOGICAL :: refine_r
      CHARACTER(1024) :: em_s
      done = .FALSE.
      cur_obj = cur_exact
      CALL MOVE_ALLOC(l0_am, l0_s); CALL MOVE_ALLOC(ea_am, ea_s); CALL MOVE_ALLOC(ei_am, ei_s)
      CALL MOVE_ALLOC(w_am, w_s); CALL MOVE_ALLOC(q_static, q_s); CALL MOVE_ALLOC(fixed_am, fixed_s)
      d_s = diam_on(l0, l0_s, diam)
      dry_s = opts%rhoW*opts%g*QUARTER_PI*d_s**2
      tol_s = [static_tol_target, MAX(static_tol_target, COUPLED_STATIC_TOL), &
               MERGE(MAX(static_tol_target, CONTACT_FLOOR_TOL), CD_ZERO, contact_enabled)]
      refine_ladder: DO k_ref = 1, 2
        h_t = MERGE(CD_HC_HKAPPA_TARGET, 0.5_wp*CD_HC_KINK_LIMIT, k_ref == 1)
        cap_r = MERGE(1, CD_HC_REFINE_CAP, k_ref == 1)
        refine_r = k_ref > 1
        em_s = ''
        DO k_tol = 1, 3
          IF (k_tol > 1) THEN
            IF (.NOT. (tol_s(k_tol) > MAXVAL(tol_s(1:k_tol - 1)))) CYCLE
            IF (INDEX(em_s, 'Newton did not converge') == 0) EXIT
          END IF
          IF (ALLOCATED(l0_am)) DEALLOCATE (l0_am)
          IF (ALLOCATED(ea_am)) DEALLOCATE (ea_am)
          IF (ALLOCATED(ei_am)) DEALLOCATE (ei_am)
          IF (ALLOCATED(w_am)) DEALLOCATE (w_am)
          IF (ALLOCATED(q_static)) DEALLOCATE (q_static)
          IF (ALLOCATED(curv)) DEALLOCATE (curv)
          IF (ALLOCATED(fixed_am)) DEALLOCATE (fixed_am)
          IF (contact_enabled) THEN
            CALL CD_HermiteCable_Static_Solve_AutoMesh(l0_s, ea_s, ei_s, w_s, q_s, fixed_s, contact_z, CD_ZERO, &
                                                       8, 80, tol_s(k_tol), 0.7_wp, h_t, &
                                                       CD_ZERO, cap_r, [2, 5], l0_am, ea_am, ei_am, w_am, q_static, &
                                                       curv, fixed_am, scale_s, diag, res, it_s, es_s, em_s, &
                                                       contact_diameter=d_s, contact_kbot=opts%kbot, &
                                                       contact_frame_cs=frame_cs, initial_polish=.TRUE., &
                                                       axial_quadrature_order=opts%axial_quadrature_order, &
                                                       bending_quadrature_order=opts%bending_quadrature_order, &
                                                       require_tensile=tensile_error, refine_non_axial=refine_r, &
                                                       compression_mode=CD_HC_COMPRESSION_STRICT, &
                                                       endconn_stiffness=endconn_k, &
                                                       endconn_direction=endconn_d0_local, &
                                                       endconn_mode=endconn_mode, waterline_z=CD_ZERO, &
                                                       dry_buoyancy=dry_s, water_weight=opts%rhoW*opts%g, &
                                                       current=cur_obj)
          ELSE
            CALL CD_HermiteCable_Static_Solve_AutoMesh(l0_s, ea_s, ei_s, w_s, q_s, fixed_s, -2000.0_wp, CD_ZERO, &
                                                       8, 80, tol_s(k_tol), 0.7_wp, h_t, &
                                                       CD_ZERO, cap_r, [2, 5], l0_am, ea_am, ei_am, w_am, q_static, &
                                                       curv, fixed_am, scale_s, diag, res, it_s, es_s, em_s, &
                                                       initial_polish=.TRUE., &
                                                       axial_quadrature_order=opts%axial_quadrature_order, &
                                                       bending_quadrature_order=opts%bending_quadrature_order, &
                                                       require_tensile=tensile_error, refine_non_axial=refine_r, &
                                                       compression_mode=CD_HC_COMPRESSION_STRICT, &
                                                       endconn_stiffness=endconn_k, &
                                                       endconn_direction=endconn_d0_local, &
                                                       endconn_mode=endconn_mode, waterline_z=CD_ZERO, &
                                                       dry_buoyancy=dry_s, water_weight=opts%rhoW*opts%g, &
                                                       current=cur_obj)
          END IF
          iters = iters + it_s
          IF (es_s == CD_HCSTAT_OK) THEN
            IF (k_tol > 1) tolerance_note = .TRUE.
            EXIT
          END IF
        END DO
        IF (es_s == CD_HCSTAT_OK) THEN
          IF (k_ref > 1) kink_refined = .TRUE.
          EXIT refine_ladder
        END IF
        IF (INDEX(em_s, 'unresolved/kinked') == 0) EXIT refine_ladder
      END DO refine_ladder
      IF (es_s /= CD_HCSTAT_OK) RETURN
      CALL audit_hermite_static(l0_am, q_static, ea_am, ei_am, w_am, diam_on(l0, l0_am, diam), endconn_mode, &
                                done, em_s, compression_note)
      IF (.NOT. done) RETURN
      CALL hermite_static_stable(l0, l0_am, ea_am, ei_am, w_am, diam, dry_b, q_static, fixed_am, &
                                 contact_enabled, contact_z, frame_cs, endconn_k, endconn_d0_local, &
                                 endconn_mode, opts, done, es_s, em_s, cur_obj=cur_obj)
      IF (es_s /= CD_DECKDRV_OK) done = .FALSE.
    END SUBROUTINE symmetric_current_polish

    LOGICAL FUNCTION in_plane_current() RESULT(ok)
      !! A current along the vertical plane of the chord over a flat seabed (or none), no
      !! rotationally rigid end: the symmetric problem whose planar branch can end at a
      !! fold or a pitchfork (see route_pass).
      ok = .FALSE.
      IF (.NOT. opts%has_current .OR. require_3d_static .OR. .NOT. ALLOCATED(cur_obj)) RETURN
      IF (ANY(endconn_mode == CD_ENDCONN_RIGID)) RETURN
      IF (PRESENT(bathymetry)) THEN
        IF (.NOT. bathymetry_flat) RETURN
      END IF
      ok = .TRUE.
    END FUNCTION in_plane_current

    LOGICAL FUNCTION planar_current_saddle() RESULT(saddle)
      !! Whether the converged planar state (q_static on l0_am, held in its plane) is
      !! unstable once only the end positions are held.
      INTEGER, ALLOCATABLE :: fixed_3d(:)
      INTEGER :: nd, es_p
      LOGICAL :: stable_3d
      CHARACTER(1024) :: em_p
      saddle = .FALSE.
      IF (.NOT. in_plane_current()) RETURN
      IF (.NOT. ALLOCATED(fixed_am) .OR. .NOT. ALLOCATED(q_static)) RETURN
      IF (SIZE(fixed_am) <= 6) RETURN
      nd = SIZE(q_static)
      fixed_3d = [1, 2, 3, nd - 5, nd - 4, nd - 3]
      CALL hermite_static_stable(l0, l0_am, ea_am, ei_am, w_am, diam, dry_b, q_static, fixed_3d, &
                                 contact_enabled, contact_z, frame_cs, endconn_k, endconn_d0_local, &
                                 endconn_mode, opts, stable_3d, es_p, em_p, cur_obj=cur_obj)
      saddle = es_p == CD_DECKDRV_OK .AND. .NOT. stable_3d
    END FUNCTION planar_current_saddle

    LOGICAL FUNCTION coarse_current_eligible() RESULT(ok)
      !! coarse_current_first applies to an in-plane current (in_plane_current) without
      !! seabed friction or attachments, on a deck build that is not itself the coarse one,
      !! and not to a deck mesh finer than sqrt(EI/EA) (fine_note), where the polish stalls.
      ok = .FALSE.
      IF (PRESENT(coarse_pass)) THEN
        IF (coarse_pass) RETURN
      END IF
      IF (static_friction .OR. has_att .OR. LEN_TRIM(fine_note) > 0) RETURN
      ok = in_plane_current()
    END FUNCTION coarse_current_eligible

    SUBROUTINE coarse_current_first(done, fail_msg)
      !! Select the equilibrium branch in the current on a coarsened deck mesh: the deck's
      !! section NumSegs halved (rounded up) as often as every element stays within one
      !! bending length (EI/|w|)^(1/3) and the line keeps COARSE_MIN_ELEMS elements. The
      !! coarse line is built through this routine (every route, audit and the stability
      !! check), its equilibrium is carried to the deck mesh by cubic-Hermite prolongation
      !! and polished there at the exact current with the line free to leave its plane, then
      !! audited and checked for stability as any other. Decks whose meshes are halvings of
      !! each other select the same coarse mesh and so the same branch. The polished
      !! equilibrium sets done; a coarse line with no equilibrium in the current fails closed
      !! with its diagnosis (fail_msg); any other outcome leaves the deck-mesh routes to run.
      LOGICAL, INTENT(INOUT) :: done
      CHARACTER(*), INTENT(OUT) :: fail_msg
      REAL(wp), PARAMETER :: COARSE_H_LAMBDA = 1.0_wp, CONTACT_FLOOR_TOL = 1.0e-5_wp
      INTEGER, PARAMETER :: COARSE_MIN_ELEMS = 16, COARSE_MAX_HALVINGS = 8
      TYPE(DeckSection), ALLOCATABLE :: sec_c(:), sec_try(:)
      TYPE(DeckOptions) :: opts_c
      TYPE(CD_HFMF_ModuleType) :: c_cable
      INTEGER, ALLOCATABLE :: conn_c(:, :), fixed_3d(:)
      REAL(wp), ALLOCATABLE :: l0_c(:), ea_c(:), mpl_c(:), diam_c(:), ei_c(:), g1(:), g2(:), g3(:), g4(:)
      REAL(wp), ALLOCATABLE :: w_c(:), q_p(:)
      INTEGER :: k, j, fac, c_node, esc, e, scale_c, it_c, k_tol, ne_c, k_ref
      REAL(wp) :: worst, tol_c(3), h_t
      LOGICAL :: refine_r
      CHARACTER(1024) :: emc
      CHARACTER(2048) :: c_note
      LOGICAL :: stable_c
      fail_msg = ''
      fac = 1
      ne_c = SIZE(l0)
      DO k = 1, COARSE_MAX_HALVINGS
        sec_try = sections
        DO j = 1, SIZE(sec_try)
          IF (sec_try(j)%line_id == ln%id) sec_try(j)%nsegs = MAX(1, (sec_try(j)%nsegs + 2*fac - 1)/(2*fac))
        END DO
        CALL build_finite_section_mesh(ln, sec_try, types, conn_c, l0_c, ea_c, mpl_c, diam_c, ei_c, &
                                       g1, g2, g3, g4, esc, emc)
        IF (esc /= CD_DECKDRV_OK) EXIT
        IF (SIZE(l0_c) < COARSE_MIN_ELEMS .OR. SIZE(l0_c) >= ne_c) EXIT
        IF (ALLOCATED(w_c)) DEALLOCATE (w_c)
        ALLOCATE (w_c(SIZE(l0_c)))
        CALL CD_Submerged_Weight(mpl_c, diam_c, opts%rhoW, opts%g, w_c, esc, emc)
        IF (esc /= 0) EXIT
        worst = CD_ZERO
        DO e = 1, SIZE(l0_c)
          IF (ei_c(e) > CD_ZERO .AND. ABS(w_c(e)) > TINY(CD_ONE)) &
            worst = MAX(worst, l0_c(e)/(ei_c(e)/ABS(w_c(e)))**(CD_ONE/3.0_wp))
        END DO
        IF (worst > COARSE_H_LAMBDA) EXIT
        fac = 2*fac
        ne_c = SIZE(l0_c)
        CALL MOVE_ALLOC(sec_try, sec_c)
      END DO
      IF (fac == 1) RETURN
      ! The coarse line only selects the branch: its tensile audit and accuracy refinement
      ! are left to the deck mesh, which decides acceptance.
      opts_c = opts
      opts_c%tensile_mode = CD_HCDYN_TENSILE_OFF
      opts_c%adaptive_mesh = .FALSE.
      IF (PRESENT(bathymetry)) THEN
        CALL build_one_hermite_cable(ln, sec_c, types, points, opts_c, dt, c_cable, c_node, esc, emc, &
                                     standalone_controls=.FALSE., bathymetry=bathymetry, &
                                     fairlead_orientation=fairlead_dcm, init_note=c_note, coarse_pass=.TRUE.)
      ELSE
        CALL build_one_hermite_cable(ln, sec_c, types, points, opts_c, dt, c_cable, c_node, esc, emc, &
                                     standalone_controls=.FALSE., fairlead_orientation=fairlead_dcm, &
                                     init_note=c_note, coarse_pass=.TRUE.)
      END IF
      IF (esc /= CD_DECKDRV_OK) THEN
        CALL CD_HFMF_End(c_cable)
        IF (esc == CD_DECKDRV_SOLVEFAIL .AND. (INDEX(emc, 'has no tension-only static equilibrium in the current') > 0 &
                                               .OR. INDEX(emc, 'has no static equilibrium in the current') > 0)) THEN
          IF (INDEX(emc, 'CableDyn_DeckDriver: ') == 1) emc = emc(LEN('CableDyn_DeckDriver: ') + 1:)
          ! Assigned, not written: a long diagnosis is truncated by the assignment, where an
          ! internal WRITE past the record length aborts the run.
          fail_msg = TRIM(emc)//' [branch selected on the bending-resolved coarsening of the deck mesh to '// &
                     TRIM(int_to_str(ne_c))//' elements]'
        END IF
        RETURN
      END IF
      ALLOCATE (q_p(ndof))
      CALL CD_HermiteCable_Prolong_Arc(c_cable%line%l0, c_cable%line%q, l0, q_p, esc, emc)
      CALL CD_HFMF_End(c_cable)
      IF (esc /= CD_HCSTAT_OK) RETURN
      fixed_3d = [1, 2, 3, ndof - 5, ndof - 4, ndof - 3]
      tol_c = [static_tol_target, MAX(static_tol_target, COUPLED_STATIC_TOL), &
               MERGE(MAX(static_tol_target, CONTACT_FLOOR_TOL), CD_ZERO, contact_enabled)]
      refine_ladder: DO k_ref = 1, 2
        h_t = MERGE(CD_HC_HKAPPA_TARGET, 0.5_wp*CD_HC_KINK_LIMIT, k_ref == 1)
        refine_r = opts%adaptive_mesh .OR. k_ref > 1
        emc = ''
        DO k_tol = 1, 3
          IF (k_tol > 1) THEN
            IF (.NOT. (tol_c(k_tol) > MAXVAL(tol_c(1:k_tol - 1)))) CYCLE
            IF (INDEX(emc, 'Newton did not converge') == 0) EXIT
          END IF
          IF (ALLOCATED(l0_am)) DEALLOCATE (l0_am)
          IF (ALLOCATED(ea_am)) DEALLOCATE (ea_am)
          IF (ALLOCATED(ei_am)) DEALLOCATE (ei_am)
          IF (ALLOCATED(w_am)) DEALLOCATE (w_am)
          IF (ALLOCATED(q_static)) DEALLOCATE (q_static)
          IF (ALLOCATED(curv)) DEALLOCATE (curv)
          IF (ALLOCATED(fixed_am)) DEALLOCATE (fixed_am)
          IF (contact_enabled) THEN
            CALL CD_HermiteCable_Static_Solve_AutoMesh(l0, ea, ei, w, q_p, fixed_3d, contact_z, CD_ZERO, &
                                                       8, 80, tol_c(k_tol), 0.7_wp, h_t, &
                                                       CD_ZERO, CD_HC_REFINE_CAP, [2, 5], l0_am, ea_am, ei_am, &
                                                       w_am, q_static, curv, fixed_am, scale_c, diag, res, it_c, &
                                                       esc, emc, contact_diameter=diam, contact_kbot=opts%kbot, &
                                                       contact_frame_cs=frame_cs, initial_polish=.TRUE., &
                                                       require_resolved=opts%adaptive_mesh, &
                                                       axial_quadrature_order=opts%axial_quadrature_order, &
                                                       bending_quadrature_order=opts%bending_quadrature_order, &
                                                       require_tensile=tensile_error, &
                                                       compression_mode=CD_HC_COMPRESSION_STRICT, &
                                                       refine_non_axial=refine_r, &
                                                       endconn_stiffness=endconn_k, &
                                                       endconn_direction=endconn_d0_local, &
                                                       endconn_mode=endconn_mode, waterline_z=CD_ZERO, &
                                                       dry_buoyancy=dry_b, water_weight=opts%rhoW*opts%g, &
                                                       current=cur_obj)
          ELSE
            CALL CD_HermiteCable_Static_Solve_AutoMesh(l0, ea, ei, w, q_p, fixed_3d, -2000.0_wp, CD_ZERO, &
                                                       8, 80, tol_c(k_tol), 0.7_wp, h_t, &
                                                       CD_ZERO, CD_HC_REFINE_CAP, [2, 5], l0_am, ea_am, ei_am, &
                                                       w_am, q_static, curv, fixed_am, scale_c, diag, res, it_c, &
                                                       esc, emc, initial_polish=.TRUE., &
                                                       require_resolved=opts%adaptive_mesh, &
                                                       axial_quadrature_order=opts%axial_quadrature_order, &
                                                       bending_quadrature_order=opts%bending_quadrature_order, &
                                                       require_tensile=tensile_error, &
                                                       compression_mode=CD_HC_COMPRESSION_STRICT, &
                                                       refine_non_axial=refine_r, &
                                                       endconn_stiffness=endconn_k, &
                                                       endconn_direction=endconn_d0_local, &
                                                       endconn_mode=endconn_mode, waterline_z=CD_ZERO, &
                                                       dry_buoyancy=dry_b, water_weight=opts%rhoW*opts%g, &
                                                       current=cur_obj)
          END IF
          iters = iters + it_c
          IF (esc == CD_HCSTAT_OK) THEN
            IF (k_tol > 1) tolerance_note = .TRUE.
            EXIT
          END IF
        END DO
        IF (esc == CD_HCSTAT_OK) THEN
          IF (k_ref > 1) kink_refined = .TRUE.
          EXIT refine_ladder
        END IF
        IF (INDEX(emc, 'unresolved/kinked') == 0) EXIT refine_ladder
      END DO refine_ladder
      IF (esc == CD_HCSTAT_OK) THEN
        CALL audit_hermite_static(l0_am, q_static, ea_am, ei_am, w_am, diam_on(l0, l0_am, diam), endconn_mode, &
                                  done, emc, compression_note)
        IF (done) THEN
          CALL hermite_static_stable(l0, l0_am, ea_am, ei_am, w_am, diam, dry_b, q_static, fixed_am, &
                                     contact_enabled, contact_z, frame_cs, endconn_k, endconn_d0_local, &
                                     endconn_mode, opts, stable_c, esc, emc, cur_obj=cur_obj)
          done = esc == CD_DECKDRV_OK .AND. stable_c
        END IF
      END IF
      IF (.NOT. done) THEN
        compression_note = ''
        tolerance_note = .FALSE.
        IF (ALLOCATED(l0_am)) DEALLOCATE (l0_am)
        IF (ALLOCATED(ea_am)) DEALLOCATE (ea_am)
        IF (ALLOCATED(ei_am)) DEALLOCATE (ei_am)
        IF (ALLOCATED(w_am)) DEALLOCATE (w_am)
        IF (ALLOCATED(q_static)) DEALLOCATE (q_static)
        IF (ALLOCATED(curv)) DEALLOCATE (curv)
        IF (ALLOCATED(fixed_am)) DEALLOCATE (fixed_am)
      END IF
    END SUBROUTINE coarse_current_first

    SUBROUTINE still_water_reference(esr, emr)
      !! Friction reference of the current solve: the equilibrium of the same line without
      !! the current (built through this routine with coupled controls, its notes discarded),
      !! as (x, y) in the solve frame along the unstretched arc length.
      INTEGER, INTENT(OUT) :: esr
      CHARACTER(*), INTENT(OUT) :: emr
      TYPE(DeckOptions) :: opts_sw
      TYPE(CD_HFMF_ModuleType) :: sw_cable
      INTEGER :: sw_node, k, nsw
      CHARACTER(2048) :: sw_note
      opts_sw = opts
      opts_sw%has_current = .FALSE.
      opts_sw%has_current_profile = .FALSE.
      IF (PRESENT(bathymetry)) THEN
        CALL build_one_hermite_cable(ln, sections, types, points, opts_sw, dt, sw_cable, sw_node, esr, emr, &
                                     standalone_controls=.FALSE., bathymetry=bathymetry, &
                                     fairlead_orientation=fairlead_dcm, init_note=sw_note)
      ELSE
        CALL build_one_hermite_cable(ln, sections, types, points, opts_sw, dt, sw_cable, sw_node, esr, emr, &
                                     standalone_controls=.FALSE., fairlead_orientation=fairlead_dcm, &
                                     init_note=sw_note)
      END IF
      IF (esr /= CD_DECKDRV_OK) THEN
        CALL CD_HFMF_End(sw_cable)
        RETURN
      END IF
      nsw = sw_cable%line%nn
      ALLOCATE (cur_obj%friction)
      cur_obj%friction%mu = opts%friction_mu
      cur_obj%friction%mu_axial = opts%friction_mu_axial
      ALLOCATE (cur_obj%friction%ref_s(nsw), cur_obj%friction%ref_xy(2, nsw))
      cur_obj%friction%ref_s(1) = CD_ZERO
      DO k = 2, nsw
        cur_obj%friction%ref_s(k) = cur_obj%friction%ref_s(k - 1) + sw_cable%line%l0(k - 1)
      END DO
      DO k = 1, nsw
        cur_obj%friction%ref_xy(:, k) = sw_cable%line%q(6*(k - 1) + 1:6*(k - 1) + 2) - sw_cable%line%q(1:2)
      END DO
      CALL CD_HFMF_End(sw_cable)
    END SUBROUTINE still_water_reference

    SUBROUTINE fine_mesh_note(note)
      !! Sets note when some element is shorter than sqrt(EI/EA) (see its call).
      CHARACTER(*), INTENT(OUT) :: note
      REAL(wp) :: ratio, r, h_min
      INTEGER :: e, e_min
      note = ''
      ratio = HUGE(CD_ONE)
      e_min = 0
      DO e = 1, SIZE(l0)
        IF (.NOT. (ei(e) > CD_ZERO .AND. ea(e) > CD_ZERO)) CYCLE
        r = l0(e)/SQRT(ei(e)/ea(e))
        IF (r < ratio) THEN
          ratio = r
          e_min = e
        END IF
      END DO
      IF (e_min == 0 .OR. ratio >= FINE_MESH_RATIO) RETURN
      h_min = FINE_MESH_RATIO*SQRT(ei(e_min)/ea(e_min))
      WRITE (note, '(A,I0,A,ES9.2,A,ES9.2,A,ES9.2,A)') 'line ', ln%id, ': elements as short as ', l0(e_min), &
        ' m are below sqrt(EI/EA) = ', SQRT(ei(e_min)/ea(e_min)), ' m, where the axial stiffness of an '// &
        'element swamps its bending stiffness and the static solve can stall; use elements of at least ', &
        h_min, ' m'
    END SUBROUTINE fine_mesh_note

    SUBROUTINE anchor_overshoot_note()
      !! Note a static layout whose grounded run lies beyond the anchor, on the side away
      !! from the fairlead: the line is carried past its anchor and folds back to it (a
      !! hairpin). A strong current on a frictionless seabed holds such an equilibrium; it
      !! is reported so that it is not mistaken for the usual layout. Node 1 is the anchor
      !! and q_static is in the solve frame, where anchor and fairlead are also given.
      REAL(wp), PARAMETER :: GROUNDED_TOL = 0.05_wp
      REAL(wp) :: e_h(2), span, past, floor_z, xg, yg, pos(3)
      INTEGER :: k, esb
      CHARACTER(200) :: emb
      span = NORM2(fairlead(1:2) - anchor(1:2))
      IF (span <= 1.0e-9_wp*MAX(CD_ONE, SUM(l0))) RETURN
      e_h = (fairlead(1:2) - anchor(1:2))/span
      past = CD_ZERO
      DO k = 1, SIZE(q_static)/6
        pos = q_static(6*(k - 1) + 1:6*(k - 1) + 3)
        floor_z = contact_z
        IF (PRESENT(bathymetry)) THEN
          IF (.NOT. bathymetry_flat) THEN
            xg = frame_cs(1)*pos(1) - frame_cs(2)*pos(2)
            yg = frame_cs(2)*pos(1) + frame_cs(1)*pos(2)
            CALL CD_Bathymetry_Floor(bathymetry, xg, yg, floor_z, esb, emb)
            IF (esb /= CD_BATHY_OK) RETURN
          END IF
        END IF
        IF (pos(3) > floor_z + GROUNDED_TOL) CYCLE
        past = MAX(past, -DOT_PRODUCT(pos(1:2) - anchor(1:2), e_h))
      END DO
      IF (past <= 0.01_wp*span + 0.5_wp) RETURN
      WRITE (note_text, '(A,I0,A,F0.2,A)') 'line ', ln%id, ': the static layout carries the grounded run ', &
        past, ' m past its anchor, where it folds back (a hairpin); a strong current on a frictionless '// &
        'seabed can hold this equilibrium, but check that it is the intended layout (seabed friction or '// &
        'a shorter line prevents it)'
      CALL report_note(note_text)
    END SUBROUTINE anchor_overshoot_note

    SUBROUTINE report_note(text)
      !! One initialisation note: printed on a standalone run, appended to init_note.
      CHARACTER(*), INTENT(IN) :: text
      IF (standalone_mode) WRITE (error_unit, '(A)') '   Note: '//TRIM(text)//'.'
      IF (PRESENT(init_note)) THEN
        IF (LEN_TRIM(init_note) > 0) THEN
          init_note = TRIM(init_note)//NEW_LINE('a')//TRIM(text)
        ELSE
          init_note = TRIM(text)
        END IF
      END IF
    END SUBROUTINE report_note

  END SUBROUTINE build_one_hermite_cable

  SUBROUTINE attachment_nodes(l0, arc_public, node, max_offset)
    !! Nearest node (internal order: node 1 = End B) of each attachment arc measured from
    !! End A, and the largest distance between an attachment and its node [m].
    REAL(wp), INTENT(IN) :: l0(:), arc_public(:)
    INTEGER, ALLOCATABLE, INTENT(OUT) :: node(:)
    REAL(wp), INTENT(OUT) :: max_offset
    REAL(wp) :: cum(SIZE(l0) + 1), s
    INTEGER :: k, i
    cum(1) = CD_ZERO
    DO i = 1, SIZE(l0)
      cum(i + 1) = cum(i) + l0(i)
    END DO
    ALLOCATE (node(SIZE(arc_public)))
    max_offset = CD_ZERO
    DO k = 1, SIZE(arc_public)
      s = MIN(MAX(cum(SIZE(cum)) - arc_public(k), CD_ZERO), cum(SIZE(cum)))
      node(k) = MINLOC(ABS(cum - s), 1)
      max_offset = MAX(max_offset, ABS(cum(node(k)) - s))
    END DO
  END SUBROUTINE attachment_nodes

  SUBROUTINE smear_attachments(w, l0, node, att, rho_w, g)
    !! Spread each attachment's net weight (m - rho V) g over the elements next to its node
    !! (half to each; all of it into the one element of an end node).
    REAL(wp), INTENT(INOUT) :: w(:)
    REAL(wp), INTENT(IN) :: l0(:), att(:, :), rho_w, g
    INTEGER, INTENT(IN) :: node(:)
    INTEGER :: k, j, ne
    REAL(wp) :: wk
    ne = SIZE(l0)
    DO k = 1, SIZE(node)
      j = node(k)
      wk = (att(2, k) - rho_w*att(3, k))*g
      IF (j == 1) THEN
        w(1) = w(1) + wk/l0(1)
      ELSE IF (j == ne + 1) THEN
        w(ne) = w(ne) + wk/l0(ne)
      ELSE
        w(j - 1) = w(j - 1) + 0.5_wp*wk/l0(j - 1)
        w(j) = w(j) + 0.5_wp*wk/l0(j)
      END IF
    END DO
  END SUBROUTINE smear_attachments

  SUBROUTINE attachment_static_polish(l0, ea, ei, w_bare, w_smear, diam, node, att, q, fixed_dofs, &
                                      contact_enabled, contact_z, frame_cs, endconn_k, endconn_d0, endconn_mode, &
                                      opts, tol, ErrStat, ErrMsg, bathymetry, cur_obj)
    !! Homotopy from the smeared-attachment equilibrium q to the discrete one: in NSTEP
    !! warm-started Newton solves the element weights move from w_smear to w_bare while the
    !! lumped nodal forces -(m - rho V) g e_z and, in a deck current, the attachment current
    !! drag grow from zero to full, with the contact, dry-buoyancy, end-connection and line
    !! current terms of the builder's static problem. The drag depends on the node's depth
    !! (profile current) and line tangent, so the full-load solve is repeated with the drag
    !! of the last solution until the solution stops moving (fixed point).
    REAL(wp), INTENT(IN) :: l0(:), ea(:), ei(:), w_bare(:), w_smear(:), diam(:), att(:, :)
    INTEGER, INTENT(IN) :: node(:), fixed_dofs(:), endconn_mode(2)
    REAL(wp), INTENT(INOUT) :: q(:)
    LOGICAL, INTENT(IN) :: contact_enabled
    REAL(wp), INTENT(IN) :: contact_z, frame_cs(2), endconn_k(2), endconn_d0(3, 2), tol
    TYPE(DeckOptions), INTENT(IN) :: opts
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    TYPE(CD_HermiteStaticCurrentType), INTENT(IN), OPTIONAL :: cur_obj
    INTEGER, PARAMETER :: NSTEP = 8, MAX_FIXED_POINT = 60
    REAL(wp), PARAMETER :: FIXED_POINT_TOL = 1.0e-9_wp   ! m
    REAL(wp), ALLOCATABLE :: f_att(:), f_drag(:), dry(:), knnode(:), wl(:), q_out(:), curv(:)
    REAL(wp) :: lam, res, change
    INTEGER :: i, k, ne, step, fp
    LOGICAL :: has_drag

    ErrStat = CD_DECKDRV_OK; ErrMsg = ''
    ne = SIZE(l0)
    ALLOCATE (f_att(6*(ne + 1)), f_drag(6*(ne + 1)), dry(ne), q_out(SIZE(q)), curv(ne + 1))
    f_att = CD_ZERO
    DO k = 1, SIZE(node)
      f_att(6*(node(k) - 1) + 3) = f_att(6*(node(k) - 1) + 3) - (att(2, k) - opts%rhoW*att(3, k))*opts%g
    END DO
    has_drag = opts%has_current .AND. ANY(att(4, :) > CD_ZERO .OR. att(6, :) > CD_ZERO)
    dry = opts%rhoW*opts%g*QUARTER_PI*diam**2
    IF (contact_enabled) THEN
      ALLOCATE (knnode(ne + 1))
      knnode = CD_ZERO
      DO i = 1, ne
        knnode(i) = knnode(i) + 0.5_wp*opts%kbot*diam(i)*l0(i)
        knnode(i + 1) = knnode(i + 1) + 0.5_wp*opts%kbot*diam(i)*l0(i)
      END DO
    END IF
    DO step = 1, NSTEP
      lam = REAL(step, wp)/REAL(NSTEP, wp)
      wl = w_bare + (CD_ONE - lam)*(w_smear - w_bare)
      CALL solve_with(lam)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END DO
    IF (.NOT. has_drag) RETURN
    DO fp = 1, MAX_FIXED_POINT
      CALL solve_with(CD_ONE, change)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      IF (change <= FIXED_POINT_TOL) RETURN
    END DO
    CALL fail_solve(ErrStat, ErrMsg, 'finite-EI static solve with discrete ATTACHMENTS: the attachment '// &
                    'current drag did not settle to a fixed point')
  CONTAINS
    SUBROUTINE solve_with(scale, dq_max)
      !! One warm-started Newton solve at load fraction scale, with the attachment current
      !! drag evaluated on the incoming state; dq_max is the resulting largest DOF change.
      REAL(wp), INTENT(IN) :: scale
      REAL(wp), INTENT(OUT), OPTIONAL :: dq_max
      INTEGER :: it, es
      CHARACTER(512) :: em
      CHARACTER(48) :: num_buf
      f_drag = CD_ZERO
      IF (has_drag) THEN
        CALL attachment_static_drag(q, node, att, opts, frame_cs, f_drag, es, em)
        IF (es /= CD_DECKDRV_OK) THEN
          CALL fail_solve(ErrStat, ErrMsg, 'finite-EI static attachment drag failed: '//TRIM(em)); RETURN
        END IF
      END IF
      IF (contact_enabled) THEN
        CALL CD_HermiteCable_Static_Solve(l0, ea, ei, wl, q, fixed_dofs, contact_z, CD_ZERO, 1, 200, &
                                          tol, 0.7_wp, q_out, curv, res, it, es, em, &
                                          f_nodal=scale*(f_att + f_drag), n_buoy_steps=1, contact_kn=knnode, &
                                          bathymetry=bathymetry, contact_frame_cs=frame_cs, &
                                          axial_quadrature_order=opts%axial_quadrature_order, &
                                          bending_quadrature_order=opts%bending_quadrature_order, &
                                          endconn_stiffness=endconn_k, endconn_direction=endconn_d0, &
                                          endconn_mode=endconn_mode, waterline_z=CD_ZERO, dry_buoyancy=dry, &
                                          water_weight=opts%rhoW*opts%g, current=cur_obj)
      ELSE
        CALL CD_HermiteCable_Static_Solve(l0, ea, ei, wl, q, fixed_dofs, contact_z, CD_ZERO, 1, 200, &
                                          tol, 0.7_wp, q_out, curv, res, it, es, em, &
                                          f_nodal=scale*(f_att + f_drag), n_buoy_steps=1, &
                                          axial_quadrature_order=opts%axial_quadrature_order, &
                                          bending_quadrature_order=opts%bending_quadrature_order, &
                                          endconn_stiffness=endconn_k, endconn_direction=endconn_d0, &
                                          endconn_mode=endconn_mode, waterline_z=CD_ZERO, dry_buoyancy=dry, &
                                          water_weight=opts%rhoW*opts%g, current=cur_obj)
      END IF
      IF (es /= CD_HCSTAT_OK .OR. .NOT. (res <= tol)) THEN
        ! numbers into a local buffer: an internal WRITE into the caller's ErrMsg would abort
        ! on a short buffer
        WRITE (num_buf, '(F5.3,A,ES10.3)') scale, ' (relative residual ', res
        ErrMsg = 'CableDyn_DeckDriver: finite-EI static solve with discrete ATTACHMENTS failed at load '// &
                 'fraction '//TRIM(num_buf)//'): '//TRIM(em)
        ErrStat = CD_DECKDRV_SOLVEFAIL
        RETURN
      END IF
      IF (PRESENT(dq_max)) dq_max = MAXVAL(ABS(q_out - q))
      q = q_out
    END SUBROUTINE solve_with
  END SUBROUTINE attachment_static_polish

  SUBROUTINE attachment_static_drag(q, node, att, opts, frame_cs, f, ErrStat, ErrMsg)
    !! Current drag of the attachments at rest, as nodal loads in the cable solve frame: the
    !! deck current at each submerged attachment node, rotated into the chord-local frame,
    !! through the shared attachment drag law (normal and axial to the node's line tangent).
    REAL(wp), INTENT(IN) :: q(:), att(:, :), frame_cs(2)
    INTEGER, INTENT(IN) :: node(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(INOUT) :: f(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: k, base, es
    REAL(wp) :: ug(3), ul(3), fd(3)
    CHARACTER(200) :: em
    ErrStat = CD_DECKDRV_OK; ErrMsg = ''
    DO k = 1, SIZE(node)
      IF (.NOT. (att(4, k) > CD_ZERO .OR. att(6, k) > CD_ZERO)) CYCLE
      base = 6*(node(k) - 1)
      IF (q(base + 3) > CD_ZERO) CYCLE
      ug = deck_current_velocity(opts, q(base + 3), es, em)
      IF (es /= CD_HYDRO_OK) THEN
        CALL fail(ErrStat, ErrMsg, TRIM(em)); RETURN
      END IF
      ul = [frame_cs(1)*ug(1) + frame_cs(2)*ug(2), -frame_cs(2)*ug(1) + frame_cs(1)*ug(2), ug(3)]
      CALL CD_HermiteCable_Attachment_Drag(ul, q(base + 4:base + 6), opts%rhoW, att(4, k), att(6, k), fd, es, em)
      IF (es /= CD_HCDYN_OK) THEN
        CALL fail(ErrStat, ErrMsg, TRIM(em)); RETURN
      END IF
      f(base + 1:base + 3) = f(base + 1:base + 3) + fd
    END DO
  END SUBROUTINE attachment_static_drag

  RECURSIVE SUBROUTINE hermite_static_primary(anchor, fairlead, l0, ea, ei, w, diam, dry_b, fixed_dofs, &
                                              contact_enabled, contact_z, frame_cs, endconn_k, endconn_d0, &
                                              endconn_mode, opts, static_tol, l0_am, ea_am, ei_am, w_am, q_static, &
                                              curv, fixed_am, applied_scale, diag, res, iters, ErrStat, ErrMsg, &
                                              inadmissible, tolerance_note, kink_refined, bathymetry, refined_pass, &
                                              cur_obj, walked, fold_walk)
    !! Primary finite-EI static route of a deck cable (the OrcaFlex/MoorPy practice of
    !! "catenary statics, then full statics"):
    !!
    !!  1. seed the whole line with the exact extensible EI = 0 catenary of the same
    !!     segments (signed submerged weight, so buoyancy sections are included), on the
    !!     declared seabed plane -- flat WtrDpth, or the plane fitted to a structured
    !!     bathymetry along the chord -- with the anchor at its actual height, or as a
    !!     line hung in mid-water when no seabed is declared;
    !!  2. trace the bending-stiffness family EI(lambda) = lambda*EI from a stiffness
    !!     fraction whose bending length is below the element length up to lambda = 1
    !!     (CD_HermiteCable_Static_Solve_Continuation), with every load at full value;
    !!  3. polish, diagnose and (when the deck opts in) refine on the caller mesh through
    !!     CD_HermiteCable_Static_Solve_AutoMesh.
    !!
    !! The solve runs in the chord-local frame translated to the anchor's horizontal
    !! position (without structured bathymetry, whose queries need global coordinates),
    !! so a translated or rotated deck sees the same numbers to round-off.
    !! ErrStat follows CD_HCSTAT_*. inadmissible is set when no catenary clears the seabed
    !! (a heavy line longer than its horizontal span plus rise on a planar seabed) and the
    !! anchor walk (seed_walk, walk_anchor) reached no equilibrium held by the bending
    !! stiffness either; callers fail closed naming the geometry, without fallback.
    !! walked (optional) is set when the returned state was reached by that walk.
    !! fold_walk (optional, flat seabed): trace the bow behind the fairlead instead. The anchor is
    !! moved to the far side of the fairlead, where the line hangs as a lazy wave whose arch
    !! faces away from the real anchor, and walked toward it until the grounded run, folded
    !! back about the touchdown point, reaches the real anchor; the folded state is relaxed
    !! and walked the rest of the way (see walk_anchor). The standard walk cannot reach that
    !! equilibrium: its arch faces the anchor and would have to pass through the line hanging
    !! from the fairlead.
    !! tolerance_note is set when the tight dynamic-consistent tolerance was not reachable
    !! (residual floor) and the equilibrium was accepted at the coupled static tolerance.
    !! kink_refined is set when the deck mesh had to be refined to resolve the curvature.
    !! A deck mesh too coarse for the bending length can defeat the continuation or the
    !! refined-mesh polish of its (unresolved) solution: the whole route is then repeated
    !! once on a uniformly refined mesh whose elements are at most half the local bending
    !! length (refined_pass marks that repetition), which also sets kink_refined.
    REAL(wp), INTENT(IN) :: anchor(3), fairlead(3), l0(:), ea(:), ei(:), w(:), diam(:), dry_b(:)
    INTEGER, INTENT(IN) :: fixed_dofs(:)
    LOGICAL, INTENT(IN) :: contact_enabled
    REAL(wp), INTENT(IN) :: contact_z, frame_cs(2), endconn_k(2), endconn_d0(3, 2)
    INTEGER, INTENT(IN) :: endconn_mode(2)
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: static_tol
    REAL(wp), ALLOCATABLE, INTENT(OUT) :: l0_am(:), ea_am(:), ei_am(:), w_am(:), q_static(:), curv(:)
    INTEGER, ALLOCATABLE, INTENT(OUT) :: fixed_am(:)
    INTEGER, INTENT(OUT) :: applied_scale, iters
    TYPE(CD_HermiteResolutionType), INTENT(OUT) :: diag
    REAL(wp), INTENT(OUT) :: res
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    LOGICAL, INTENT(OUT) :: inadmissible, tolerance_note, kink_refined
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    LOGICAL, INTENT(IN), OPTIONAL :: refined_pass
    TYPE(CD_HermiteStaticCurrentType), INTENT(IN), OPTIONAL :: cur_obj
    ! Set when the returned state was reached by walking the anchor (see seed_walk).
    LOGICAL, INTENT(OUT), OPTIONAL :: walked
    ! Trace the bow behind the fairlead (see fold_walk above).
    LOGICAL, INTENT(IN), OPTIONAL :: fold_walk

    ! Static tolerance of the coupled route; the floor accepted when the tighter
    ! dynamic-consistent tolerance is below the attainable residual.
    REAL(wp), PARAMETER :: COUPLED_STATIC_TOL = 1.0e-6_wp
    ! Residual floor accepted (and reported) for a line resting on the seabed.
    REAL(wp), PARAMETER :: CONTACT_FLOOR_TOL = 1.0e-5_wp
    ! Continuation budgets: Newton iterations per stage, and a total that scales with
    ! the inverse mesh size (every iteration costs O(elements)).
    INTEGER, PARAMETER :: STAGE_MAX_ITER = 40, CONT_BUDGET = 600
    INTEGER, PARAMETER :: CONT_ELEMENT_ITERATIONS = 2000000
    ! Continuation floor on a mesh finer than sqrt(EI/EA) (see budget_cont).
    INTEGER, PARAMETER :: FINE_MIN_ITERATIONS = 20
    INTEGER, PARAMETER :: NFIT = 33
    ! Element cap of the refined repetition of the route.
    INTEGER, PARAMETER :: REFINED_MAX_ELEMENTS = 4096
    INTEGER :: nnode, ne, i, es, cont_iters, polish_iters, budget_cont, cmode, k_walk
    ! Anchor retreats tried for a line too long for its span (see seed_walk).
    INTEGER, PARAMETER :: WALK_MAX_TRIES = 6
    LOGICAL :: walk_ok, fold
    CHARACTER(400) :: walk_msg_c
    REAL(wp) :: walk_d, a_seed(3)
    CHARACTER(512) :: walk_msg
    LOGICAL :: tensile, refine_all, planar_bed
    REAL(wp) :: h_target
    REAL(wp) :: origin(2), a_l(3), f_l(3), seabed_z, seabed_slope, horizontal_tension, grounded_length
    REAL(wp) :: lambda0, ratio, span(2), span_len, t, xg, yg, zf, sx, sz, sxx, sxz, xl, yl
    REAL(wp) :: res_cont, cont_tol, phi, penetration, zfit(NFIT), fit_misfit, fine_limit
    REAL(wp), ALLOCATABLE :: pos(:), q_seed(:), q_cont(:), curv_cont(:), knnode(:), tdir(:, :), stretch(:)
    CHARACTER(512) :: em

    ErrStat = CD_HCSTAT_OK
    ErrMsg = ''
    inadmissible = .FALSE.
    tolerance_note = .FALSE.
    kink_refined = .FALSE.
    IF (PRESENT(walked)) walked = .FALSE.
    fold = .FALSE.
    IF (PRESENT(fold_walk)) fold = fold_walk
    applied_scale = 1
    iters = 0
    res = CD_ZERO
    ne = SIZE(l0)
    nnode = ne + 1

    origin = CD_ZERO
    IF (.NOT. PRESENT(bathymetry)) origin = anchor(1:2)
    a_l = [anchor(1) - origin(1), anchor(2) - origin(2), anchor(3)]
    f_l = [fairlead(1) - origin(1), fairlead(2) - origin(2), fairlead(3)]

    ! Seabed plane under the line. A structured bathymetry is represented by its
    ! least-squares plane along the horizontal chord; the contact solve itself always
    ! queries the full surface.
    seabed_z = contact_z
    seabed_slope = CD_ZERO
    fit_misfit = CD_ZERO
    IF (contact_enabled .AND. PRESENT(bathymetry)) THEN
      span = f_l(1:2) - a_l(1:2)
      span_len = NORM2(span)
      sx = CD_ZERO; sz = CD_ZERO; sxx = CD_ZERO; sxz = CD_ZERO
      DO i = 0, NFIT - 1
        t = REAL(i, wp)/REAL(NFIT - 1, wp)
        xl = a_l(1) + t*span(1)
        yl = a_l(2) + t*span(2)
        xg = frame_cs(1)*xl - frame_cs(2)*yl
        yg = frame_cs(2)*xl + frame_cs(1)*yl
        CALL CD_Bathymetry_Floor(bathymetry, xg, yg, zf, es, em)
        IF (es /= CD_BATHY_OK) THEN
          ErrStat = CD_HCSTAT_NOCONVERGE
          ErrMsg = 'bathymetry query for the catenary seed failed: '//TRIM(em); RETURN
        END IF
        sx = sx + t*span_len; sz = sz + zf; sxx = sxx + (t*span_len)**2; sxz = sxz + t*span_len*zf
        zfit(i + 1) = zf
      END DO
      IF (span_len > CD_ZERO) THEN
        seabed_slope = (REAL(NFIT, wp)*sxz - sx*sz)/(REAL(NFIT, wp)*sxx - sx*sx)
      END IF
      seabed_z = (sz - seabed_slope*sx)/REAL(NFIT, wp)
      ! Largest distance of the bathymetry under the chord from the fitted plane: zero when
      ! the seabed profile in the vertical plane of the line is straight.
      fit_misfit = CD_ZERO
      DO i = 0, NFIT - 1
        t = REAL(i, wp)/REAL(NFIT - 1, wp)
        fit_misfit = MAX(fit_misfit, ABS(zfit(i + 1) - seabed_z - seabed_slope*t*span_len))
      END DO
    END IF

    ! 1. exact elastic catenary seed (anchor = node 1, fairlead = node nnode)
    planar_bed = .NOT. PRESENT(bathymetry) .OR. &
                 fit_misfit <= 1.0e-6_wp*MAX(CD_ONE, SUM(l0), ABS(seabed_z))
    ALLOCATE (pos(3*nnode), q_seed(6*nnode))
    ! A line too long for its span has no EI = 0 (catenary) equilibrium clear of the seabed,
    ! but its bending stiffness can hold one (a bow in the vertical plane carrying the excess
    ! length). Such a state is reached by displacement control, as a line is laid: the
    ! anchor is moved back along the chord until the catenary exists, the line is solved
    ! there, and the anchor is walked back to its position (walk_anchor below). Over a
    ! planar seabed (flat, or a structured bathymetry that is a plane along the chord and
    ! behind the anchor), on which the walked anchor keeps its height above the bed.
    walk_ok = contact_enabled .AND. planar_bed
    span_len = NORM2(a_l(1:2) - f_l(1:2))
    IF (span_len <= 1.0e-6_wp*SUM(l0)) walk_ok = .FALSE.
    ! The bow behind the fairlead is traced over a flat seabed only (the bed must continue
    ! beyond the fairlead, where the anchor starts).
    IF (fold .AND. (PRESENT(bathymetry) .OR. .NOT. walk_ok)) THEN
      ErrStat = CD_HCSTAT_NOCONVERGE
      ErrMsg = 'the bow behind the fairlead is traced over a flat seabed only'
      RETURN
    END IF
    walk_d = CD_ZERO
    a_seed = a_l
    walk_msg = ''
    seed_walk: DO k_walk = 0, WALK_MAX_TRIES
      IF (k_walk > 0) THEN
        ! First retreat: the length the line exceeds its span plus rise by, and a tenth of
        ! the line; then half as far again each time.
        IF (k_walk == 1) THEN
          walk_d = MAX(CD_ZERO, SUM(l0) - span_len - ABS(f_l(3) - a_l(3))) + 0.1_wp*SUM(l0)
        ELSE
          walk_d = 1.5_wp*walk_d
        END IF
        a_seed(1:2) = a_l(1:2) + walk_d*(a_l(1:2) - f_l(1:2))/span_len
        a_seed(3) = a_l(3) - seabed_slope*walk_d
        ! The bow behind the fairlead: the anchor mirrored about the fairlead, as far back.
        IF (fold) a_seed(1:2) = f_l(1:2) + (span_len + walk_d)*(f_l(1:2) - a_l(1:2))/span_len
        IF (PRESENT(bathymetry)) THEN
          ! The bathymetry must continue the plane behind the anchor (it is held flat past
          ! the edge of its grid).
          xg = frame_cs(1)*a_seed(1) - frame_cs(2)*a_seed(2)
          yg = frame_cs(2)*a_seed(1) + frame_cs(1)*a_seed(2)
          CALL CD_Bathymetry_Floor(bathymetry, xg, yg, zf, es, em)
          IF (es /= CD_BATHY_OK .OR. ABS(zf - (seabed_z - seabed_slope*walk_d)) > &
              1.0e-6_wp*MAX(CD_ONE, SUM(l0), ABS(seabed_z))) THEN
            CALL walk_failed('the bathymetry does not continue its plane behind the anchor, where the '// &
                             'bending-supported equilibrium would be traced from')
            RETURN
          END IF
        END IF
      END IF
      IF (contact_enabled) THEN
        CALL CD_Catenary_Seed(a_seed, f_l, l0, ea, w, pos, horizontal_tension, grounded_length, es, em, &
                              seabed_z=seabed_z - seabed_slope*walk_d, seabed_slope=seabed_slope)
      ELSE
        CALL CD_Catenary_Seed(a_seed, f_l, l0, ea, w, pos, horizontal_tension, grounded_length, es, em, &
                              suspended=.TRUE.)
      END IF
      IF (es /= CD_CAT_OK) THEN
        ErrStat = CD_HCSTAT_NOCONVERGE
        ErrMsg = 'catenary seed unavailable: '//TRIM(em)
        ! Proven for a planar seabed under the line: a flat one, or a bathymetry whose profile
        ! in the vertical plane of the line is straight (a uniform slope along the chord).
        inadmissible = es == CD_CAT_NOSEED .AND. contact_enabled .AND. planar_bed .AND. &
                       ALL(w >= CD_ZERO) .AND. ANY(w > CD_ZERO)
        IF (k_walk == 0) walk_msg = ErrMsg
        IF (walk_ok .AND. (inadmissible .OR. k_walk > 0)) CYCLE seed_walk
        RETURN
      END IF
      ! A catenary that closes the endpoints only by passing through the seabed is not an
      ! equilibrium. On a planar bed (flat, or a bathymetry whose profile under the chord is
      ! straight) this means that no in-plane EI = 0 equilibrium clears the bed: the
      ! (net-heavy) line is too long for its span to hang as a catenary.
      IF (contact_enabled) THEN
        penetration = CD_ZERO
        DO i = 1, nnode
          ! bed height along the chord, measured from the anchor toward the fairlead (signed:
          ! a node behind a walked-back anchor lies on the plane continued there)
          t = CD_ZERO
          IF (span_len > CD_ZERO) t = DOT_PRODUCT(pos(3*(i - 1) + 1:3*(i - 1) + 2) - a_l(1:2), &
                                                  f_l(1:2) - a_l(1:2))/span_len
          IF (span_len <= CD_ZERO) t = NORM2(pos(3*(i - 1) + 1:3*(i - 1) + 2) - a_l(1:2))
          penetration = MAX(penetration, seabed_z + seabed_slope*t - pos(3*i))
        END DO
        IF (penetration > 1.0e-6_wp*(SUM(l0) + ABS(seabed_z))) THEN
          ErrStat = CD_HCSTAT_NOCONVERGE
          ErrMsg = 'the elastic catenary through the endpoints passes '//TRIM(ADJUSTL(es_to_str(penetration)))// &
                   ' m below the seabed'
          inadmissible = planar_bed
          IF (k_walk == 0) walk_msg = ErrMsg
          IF (walk_ok .AND. (inadmissible .OR. k_walk > 0)) CYCLE seed_walk
          RETURN
        END IF
      END IF
      ErrStat = CD_HCSTAT_OK
      ErrMsg = ''
      inadmissible = .FALSE.
      EXIT seed_walk
    END DO seed_walk
    ! A line that hangs as a catenary needs no bow.
    IF (fold .AND. ErrStat == CD_HCSTAT_OK .AND. .NOT. walk_d > CD_ZERO) THEN
      ErrStat = CD_HCSTAT_NOCONVERGE
      ErrMsg = 'the line hangs as a catenary; no bow behind the fairlead is traced'
      RETURN
    END IF
    IF (ErrStat /= CD_HCSTAT_OK) THEN
      CALL walk_failed('no catenary clear of the seabed at any retreat of the anchor')
      RETURN
    END IF
    q_seed = CD_ZERO
    DO i = 1, nnode
      q_seed(6*(i - 1) + 1:6*(i - 1) + 3) = pos(3*(i - 1) + 1:3*i)
    END DO
    ! Material tangents dr/ds. Direction: central difference of the seed nodes (the
    ! adjacent chord at the two ends). Magnitude: the element stretch |dr/ds| = arc/l0.
    ! A chord underestimates the arc of a curved element by sin(phi/2)/(phi/2), phi the
    ! turning angle across it; without that correction a coarse element in a bend
    ! carries a spurious EA-scaled strain of order phi**2/24.
    ALLOCATE (tdir(3, nnode), stretch(ne))
    tdir(:, 1) = pos(4:6) - pos(1:3)
    tdir(:, nnode) = pos(3*(nnode - 1) + 1:3*nnode) - pos(3*(nnode - 2) + 1:3*(nnode - 1))
    DO i = 2, nnode - 1
      tdir(:, i) = pos(3*i + 1:3*i + 3) - pos(3*(i - 2) + 1:3*(i - 1))
    END DO
    DO i = 1, nnode
      tdir(:, i) = tdir(:, i)/NORM2(tdir(:, i))
    END DO
    DO i = 1, ne
      phi = ACOS(MAX(-CD_ONE, MIN(CD_ONE, DOT_PRODUCT(tdir(:, i), tdir(:, i + 1)))))
      stretch(i) = NORM2(pos(3*i + 1:3*i + 3) - pos(3*(i - 1) + 1:3*i))/l0(i)
      IF (phi > 1.0e-6_wp) stretch(i) = stretch(i)*(0.5_wp*phi)/SIN(0.5_wp*phi)
    END DO
    q_seed(4:6) = stretch(1)*tdir(:, 1)
    q_seed(6*(nnode - 1) + 4:6*nnode) = stretch(ne)*tdir(:, nnode)
    DO i = 2, nnode - 1
      q_seed(6*(i - 1) + 4:6*(i - 1) + 6) = (l0(i - 1)*stretch(i - 1) + l0(i)*stretch(i))/ &
                                            (l0(i - 1) + l0(i))*tdir(:, i)
    END DO

    ! 2. bending-stiffness continuation. Start where the bending length
    ! (lambda*EI/|w|)^(1/3) is at most a quarter of the element length, so the first
    ! stage is the catenary to within the mesh resolution, and at most one per cent of
    ! the full stiffness: on a coarse mesh (elements longer than the bending length) the
    ! C1 elements cannot follow the catenary's touchdown and end transitions, and only a
    ! small stiffness keeps the first stage inside the seed's Newton basin.
    lambda0 = 1.0e-2_wp
    DO i = 1, ne
      IF (ei(i) > CD_ZERO .AND. ABS(w(i)) > CD_ZERO) THEN
        ratio = (0.25_wp*l0(i))**3*ABS(w(i))/ei(i)
        lambda0 = MIN(lambda0, ratio)
      END IF
    END DO
    lambda0 = MIN(CD_ONE, MAX(1.0e-8_wp, lambda0))
    ALLOCATE (q_cont(6*nnode), curv_cont(nnode))
    cont_tol = MAX(static_tol, COUPLED_STATIC_TOL)
    budget_cont = MAX(CONT_BUDGET, CONT_ELEMENT_ITERATIONS/ne)
    ! A mesh finer than sqrt(EI/EA) somewhere loses the precision Newton needs as its
    ! element count grows: a mesh that converges there does so within the element-scaled
    ! work (every iteration costs O(elements)), so the stage floor does not apply and a
    ! stalled continuation stops in seconds instead of minutes.
    fine_limit = HUGE(CD_ONE)
    DO i = 1, ne
      IF (ei(i) > CD_ZERO .AND. ea(i) > CD_ZERO) fine_limit = MIN(fine_limit, l0(i)/SQRT(ei(i)/ea(i)))
    END DO
    IF (fine_limit < CD_ONE) budget_cont = MAX(FINE_MIN_ITERATIONS, CONT_ELEMENT_ITERATIONS/ne)
    IF (contact_enabled) THEN
      ALLOCATE (knnode(nnode))
      knnode = CD_ZERO
      DO i = 1, ne
        knnode(i) = knnode(i) + 0.5_wp*opts%kbot*diam(i)*l0(i)
        knnode(i + 1) = knnode(i + 1) + 0.5_wp*opts%kbot*diam(i)*l0(i)
      END DO
      CALL CD_HermiteCable_Static_Solve_Continuation(l0, ea, ei, w, q_seed, fixed_dofs, contact_z, CD_ZERO, &
                                                     STAGE_MAX_ITER, cont_tol, lambda0, budget_cont, &
                                                     q_cont, curv_cont, res_cont, cont_iters, es, em, &
                                                     contact_kn=knnode, bathymetry=bathymetry, &
                                                     contact_frame_cs=frame_cs, &
                                                     axial_quadrature_order=opts%axial_quadrature_order, &
                                                     bending_quadrature_order=opts%bending_quadrature_order, &
                                                     endconn_stiffness=endconn_k, endconn_direction=endconn_d0, &
                                                     endconn_mode=endconn_mode, waterline_z=CD_ZERO, &
                                                     dry_buoyancy=dry_b, &
                                                     water_weight=opts%rhoW*opts%g, current=cur_obj)
    ELSE
      CALL CD_HermiteCable_Static_Solve_Continuation(l0, ea, ei, w, q_seed, fixed_dofs, contact_z, CD_ZERO, &
                                                     STAGE_MAX_ITER, cont_tol, lambda0, budget_cont, &
                                                     q_cont, curv_cont, res_cont, cont_iters, es, em, &
                                                     axial_quadrature_order=opts%axial_quadrature_order, &
                                                     bending_quadrature_order=opts%bending_quadrature_order, &
                                                     endconn_stiffness=endconn_k, endconn_direction=endconn_d0, &
                                                     endconn_mode=endconn_mode, waterline_z=CD_ZERO, &
                                                     dry_buoyancy=dry_b, &
                                                     water_weight=opts%rhoW*opts%g, current=cur_obj)
    END IF
    iters = cont_iters
    IF (es /= CD_HCSTAT_OK) THEN
      ErrStat = es
      ErrMsg = TRIM(em)
      IF (walk_d > CD_ZERO) THEN
        CALL walk_failed('the line did not solve with its anchor moved '//TRIM(walk_m(walk_d))// &
                         ' m back along the chord ('//TRIM(em)//')')
        RETURN
      END IF
      ! A line held in its plane whose run on a frictionless seabed the current drives into
      ! compression has no planar tension-only equilibrium past that point: a refined mesh
      ! traces the same planar path to the same limit (as the continuation itself does not
      ! follow it around; see planar_run_limit there). The out-of-plane pass follows.
      IF (.NOT. planar_run_diagnosed(em)) CALL refined_restart()
      RETURN
    END IF
    ! A seed taken with the anchor moved back: walk it to its position.
    IF (walk_d > CD_ZERO) THEN
      CALL walk_anchor()
      IF (ErrStat /= CD_HCSTAT_OK) RETURN
      ! With tensile_safety True a walked state whose element-mean axial force (the force
      ! in equilibrium, averaged over three elements) is compressed beyond a tenth of its
      ! peak tension is a bow held by its bending stiffness: the tensile polish below would
      ! refine it for nothing (it removes the pointwise oscillation of a coarse element, not
      ! the compression of an equilibrium) and then reject it. Reject it now, naming it.
      IF (opts%tensile_mode == CD_HCDYN_TENSILE_ERROR) THEN
        CALL walked_compression(walk_msg_c)
        IF (LEN_TRIM(walk_msg_c) > 0) THEN
          CALL walk_failed('the equilibrium held by its bending stiffness, reached by walking the anchor back, '// &
                           'is in axial compression, which tensile_safety True rejects: '//TRIM(walk_msg_c))
          RETURN
        END IF
      END IF
    END IF

    ! 3. caller-mesh polish, diagnosis and opt-in refinement (adaptive_mesh: uniform
    ! refinement of a fragile resolution screen). A coarse mesh whose axial resultant
    ! oscillates is kept and reported by the audit. With tensile_safety True
    ! compression beyond the tighter of the strain band and the tension-relative band is
    ! refined locally and otherwise rejected. A residual floor above the tight
    ! dynamic-consistent tolerance is accepted at the coupled static tolerance.
    tensile = opts%tensile_mode == CD_HCDYN_TENSILE_ERROR
    cmode = MERGE(CD_HC_COMPRESSION_STRICT, CD_HC_COMPRESSION_OSCILLATION, tensile)
    h_target = CD_HC_HKAPPA_TARGET
    refine_all = opts%adaptive_mesh
    CALL polish_with_floor()
    ! Safety-driven refinement: an element-localized fold on the deck mesh means the
    ! mesh cannot represent the bends of this equilibrium. Refine globally (power of two,
    ! capped) until max(h*kappa) is half the kink limit, whatever adaptive_mesh says; the
    ! alternative is no result at all. The caller reports the refined mesh.
    IF (ErrStat == CD_HCSTAT_NOCONVERGE .AND. INDEX(ErrMsg, 'unresolved/kinked') > 0) THEN

      h_target = 0.5_wp*CD_HC_KINK_LIMIT
      refine_all = .TRUE.
      tolerance_note = .FALSE.
      CALL polish_with_floor()
      kink_refined = ErrStat == CD_HCSTAT_OK
    END IF
    IF (ErrStat /= CD_HCSTAT_OK) THEN
      ! An unresolved end boundary layer at a restrained end also shows up as a stalled
      ! polish (the tensile refinement splits the end element into a layer it still cannot
      ! follow); the graded mesh resolves it.
      IF (INDEX(ErrMsg, 'unresolved/kinked') > 0 .OR. INDEX(ErrMsg, 'compressive axial') > 0 .OR. &
          INDEX(ErrMsg, 'polish failed') > 0 .OR. INDEX(ErrMsg, 'Newton did not converge') > 0) CALL graded_restart()
      IF (ErrStat /= CD_HCSTAT_OK .AND. (INDEX(ErrMsg, 'polish failed') > 0 .OR. &
                                         INDEX(ErrMsg, 'unresolved/kinked') > 0 .OR. &
                                         INDEX(ErrMsg, 'Newton did not converge') > 0)) CALL refined_restart()
      ! A route that started from a walked anchor ends on the geometry that required the walk.
      IF (ErrStat /= CD_HCSTAT_OK .AND. walk_d > CD_ZERO .AND. .NOT. inadmissible) THEN
        IF (tensile .AND. INDEX(ErrMsg, 'compressive axial resultant') > 0) THEN
          CALL walk_failed('the equilibrium held by its bending stiffness, reached by walking the anchor back, '// &
                           'is in axial compression, which tensile_safety True rejects: '//TRIM(ErrMsg))
        ELSE
          CALL walk_failed('the state walked back to the anchor was not polished: '//TRIM(ErrMsg))
        END IF
      END IF
      RETURN
    END IF
    DO i = 1, SIZE(q_static)/6
      q_static(6*(i - 1) + 1) = q_static(6*(i - 1) + 1) + origin(1)
      q_static(6*(i - 1) + 2) = q_static(6*(i - 1) + 2) + origin(2)
    END DO
    IF (PRESENT(walked)) walked = walk_d > CD_ZERO

  CONTAINS

    LOGICAL FUNCTION planar_run_diagnosed(msg) RESULT(yes)
      !! Whether msg carries the frictionless grounded-run diagnosis of a current (the
      !! current drives the run on the seabed into compression) for this line held in its
      !! vertical plane (every node's out-of-plane DOF held).
      CHARACTER(*), INTENT(IN) :: msg
      yes = PRESENT(cur_obj)
      IF (yes) yes = COUNT(MOD(fixed_dofs - 1, 6) == 1) >= nnode
      IF (yes) yes = INDEX(msg, 'the run on the seabed is in axial compression') > 0 .OR. &
                     INDEX(msg, 'the run on the seabed folds against its end') > 0
    END FUNCTION planar_run_diagnosed

    SUBROUTINE walked_compression(text)
      !! The element-mean axial compression of the walked state q_cont (see the tensile_safety
      !! check after walk_anchor): the smallest length-weighted mean of the element means of
      !! three consecutive elements, when below a tenth of the peak element mean; blank
      !! otherwise.
      CHARACTER(*), INTENT(OUT) :: text
      TYPE(CD_HermiteBranchAuditType) :: audit_w
      INTEGER :: es_w, ios_w
      CHARACTER(200) :: em_w
      text = ''
      CALL CD_HermiteCable_Branch_Audit(l0, q_cont, ea, audit_w, es_w, em_w)
      IF (es_w /= CD_HCSTAT_OK) RETURN
      IF (audit_w%smoothed_axial_min < -CD_HC_OSCILLATION_REL_TOL*MAX(audit_w%mean_axial_max, CD_ZERO)) &
        WRITE (text, '(A,ES11.4,A,I0,A,ES11.4,A)', IOSTAT=ios_w) 'element-mean axial force ', &
        audit_w%smoothed_axial_min, ' N over three elements about element ', audit_w%smoothed_min_elem, &
        ' (internal order), peak tension ', audit_w%mean_axial_max, ' N'
    END SUBROUTINE walked_compression

    CHARACTER(24) FUNCTION walk_m(x) RESULT(txt)
      !! A length in metres, two decimals.
      REAL(wp), INTENT(IN) :: x
      INTEGER :: ios
      txt = ''
      WRITE (txt, '(F0.2)', IOSTAT=ios) x
    END FUNCTION walk_m

    SUBROUTINE walk_failed(reason)
      !! No equilibrium reached by the anchor walk: the geometric reason the catenary route
      !! could not start (walk_msg) and why the bending-supported branch was not reached.
      CHARACTER(*), INTENT(IN) :: reason
      ErrStat = CD_HCSTAT_NOCONVERGE
      ErrMsg = TRIM(walk_msg)//'; '//TRIM(reason)
      inadmissible = .TRUE.
    END SUBROUTINE walk_failed

    SUBROUTINE walk_anchor()
      !! Displacement control of a line too long for its span: q_cont is its equilibrium
      !! with the anchor at a_seed, walk_d back along the chord; the anchor is moved back to
      !! a_l in steps, each solved from a secant predictor (the first from the previous state
      !! translated with the anchor, the translation fading along the line). The step halves
      !! on a failed solve and doubles after a good one. Without a current each step is a
      !! trust-region minimisation of the potential energy, which can only descend and so
      !! follows the stable branch (plain Newton could cross a limit point onto an unstable
      !! or self-intersecting branch); the drag of a current is not conservative, so plain
      !! Newton there. The walked state becomes the continuation result that step 3 polishes
      !! and audits.
      !!
      !! With fold_walk the anchor starts on the far side of the fairlead, and the arch of the
      !! lazy wave faces away from the real anchor. The walk toward the fairlead then stops
      !! where the grounded run, folded back about the touchdown point, reaches the real
      !! anchor to within FOLD_FIT_TOL of the span (each step is bounded so as not to pass
      !! that point), or at the last state before the arch turns over toward the real anchor.
      !! The run is folded there, the corner at the touchdown relaxed by a longer energy
      !! minimisation, and the anchor walked the rest of the way to its position.
      INTEGER, PARAMETER :: WALK_MAX_ITER = 60
      ! Fold route: fit tolerance (fraction of the span) and the Newton budget of the
      ! relaxation of the folded corner.
      REAL(wp), PARAMETER :: FOLD_FIT_TOL = 0.02_wp
      INTEGER, PARAMETER :: FOLD_RELAX_ITER = 400
      REAL(wp), PARAMETER :: WALK_DT0 = 0.0625_wp, WALK_DT_MIN = 1.0e-4_wp, WALK_DT_MAX = 0.25_wp
      REAL(wp), PARAMETER :: WALK_TOL = 1.0e-5_wp
      ! Newton iterations of the whole walk (every iteration costs O(elements)).
      INTEGER, PARAMETER :: WALK_BUDGET = 3000
      REAL(wp), ALLOCATABLE :: q_try(:), q_new(:), q_prev(:), sref(:), curv_w(:)
      REAL(wp) :: tw, dt, dt_prev, a_cur(3), a_new(3), res_w, wgt, tol_w
      INTEGER :: it_w, es_w, k, total_it
      LOGICAL :: have_prev, energy, folded, fold_now
      REAL(wp) :: fit, path_len, r_td(2), p, up(3), tl
      INTEGER :: k_td, kk
      CHARACTER(512) :: em_w
      ALLOCATE (q_try(6*nnode), q_new(6*nnode), q_prev(6*nnode), sref(nnode), curv_w(nnode))
      sref(1) = CD_ZERO
      DO k = 2, nnode
        sref(k) = sref(k - 1) + l0(k - 1)
      END DO
      energy = .NOT. PRESENT(cur_obj)
      tol_w = MAX(cont_tol, WALK_TOL)
      tw = CD_ZERO
      dt = WALK_DT0
      dt_prev = dt
      have_prev = .FALSE.
      total_it = 0
      em_w = ''
      folded = .NOT. fold
      fold_now = .FALSE.
      DO WHILE (tw < CD_ONE)
        dt = MIN(dt, CD_ONE - tw)
        IF (.NOT. folded) THEN
          CALL fold_fit(q_cont, k_td, fit)
          ! The grounded run gains about the anchor step on its fit: do not step past it.
          IF (k_td > 1 .AND. fit >= -FOLD_FIT_TOL*span_len) fold_now = .TRUE.
          IF (fold_now) THEN
            IF (k_td <= 1) THEN
              iters = iters + total_it
              CALL walk_failed('no bow behind the fairlead was reached: its arch turned over toward the anchor '// &
                               'before the line touched down')
              RETURN
            END IF
            ! Fold the grounded run (nodes 1..k_td) back about the touchdown point toward the
            ! real anchor, give the touchdown node the tangent between the folded run and the
            ! line rising from it, relax that corner with the anchor held where the fold puts
            ! it, and walk from there to the real anchor.
            r_td = q_cont(6*(k_td - 1) + 1:6*(k_td - 1) + 2)
            q_try = q_cont
            DO kk = 1, k_td - 1
              p = DOT_PRODUCT(q_try(6*(kk - 1) + 1:6*(kk - 1) + 2) - r_td, walk_ehat())
              q_try(6*(kk - 1) + 1:6*(kk - 1) + 2) = q_try(6*(kk - 1) + 1:6*(kk - 1) + 2) - 2.0_wp*p*walk_ehat()
              p = DOT_PRODUCT(q_try(6*(kk - 1) + 4:6*(kk - 1) + 5), walk_ehat())
              q_try(6*(kk - 1) + 4:6*(kk - 1) + 5) = q_try(6*(kk - 1) + 4:6*(kk - 1) + 5) - 2.0_wp*p*walk_ehat()
            END DO
            up = q_try(6*k_td + 1:6*k_td + 3) - q_try(6*(k_td - 1) + 1:6*(k_td - 1) + 3)
            up = up/NORM2(up) - [walk_ehat(), CD_ZERO]
            IF (NORM2(up) <= 1.0e-6_wp) up = [CD_ZERO, CD_ZERO, CD_ONE]
            tl = NORM2(q_try(6*(k_td - 1) + 4:6*(k_td - 1) + 6))
            q_try(6*(k_td - 1) + 4:6*(k_td - 1) + 6) = tl*up/NORM2(up)
            a_seed = q_try(1:3)
            CALL CD_HermiteCable_Static_Solve(l0, ea, ei, w, q_try, fixed_dofs, contact_z, CD_ZERO, 1, &
                                              FOLD_RELAX_ITER, tol_w, 0.7_wp, q_new, curv_w, res_w, it_w, es_w, em_w, &
                                              n_buoy_steps=1, contact_kn=knnode, contact_frame_cs=frame_cs, &
                                              axial_quadrature_order=opts%axial_quadrature_order, &
                                              bending_quadrature_order=opts%bending_quadrature_order, &
                                              endconn_stiffness=endconn_k, endconn_direction=endconn_d0, &
                                              endconn_mode=endconn_mode, waterline_z=CD_ZERO, dry_buoyancy=dry_b, &
                                              water_weight=opts%rhoW*opts%g, current=cur_obj, &
                                              energy_minimization=energy)
            total_it = total_it + it_w
            IF (es_w /= CD_HCSTAT_OK) THEN
              iters = iters + total_it
              CALL walk_failed('no bow behind the fairlead was reached: the grounded run folded back to the '// &
                               'anchor did not relax ('//TRIM(em_w)//')')
              RETURN
            END IF
            q_cont = q_new
            folded = .TRUE.
            have_prev = .FALSE.
            tw = CD_ZERO
            dt = WALK_DT0
            dt_prev = dt
            CYCLE
          END IF
          path_len = NORM2(a_l - a_seed)
          IF (k_td > 1) dt = MIN(dt, MAX(WALK_DT_MIN, -fit/path_len))
        END IF
        a_cur = a_seed + tw*(a_l - a_seed)
        a_new = a_seed + (tw + dt)*(a_l - a_seed)
        IF (have_prev) THEN
          q_try = q_cont + (q_cont - q_prev)*(dt/dt_prev)
        ELSE
          q_try = q_cont
          DO k = 1, nnode
            wgt = CD_ONE - sref(k)/sref(nnode)
            q_try(6*(k - 1) + 1:6*(k - 1) + 3) = q_try(6*(k - 1) + 1:6*(k - 1) + 3) + wgt*(a_new - a_cur)
          END DO
        END IF
        q_try(1:3) = a_new
        q_try(6*nnode - 5:6*nnode - 3) = q_cont(6*nnode - 5:6*nnode - 3)
        CALL CD_HermiteCable_Static_Solve(l0, ea, ei, w, q_try, fixed_dofs, contact_z, CD_ZERO, 1, WALK_MAX_ITER, &
                                          tol_w, 0.7_wp, q_new, curv_w, res_w, it_w, es_w, em_w, n_buoy_steps=1, &
                                          contact_kn=knnode, bathymetry=bathymetry, contact_frame_cs=frame_cs, &
                                          axial_quadrature_order=opts%axial_quadrature_order, &
                                          bending_quadrature_order=opts%bending_quadrature_order, &
                                          endconn_stiffness=endconn_k, endconn_direction=endconn_d0, &
                                          endconn_mode=endconn_mode, waterline_z=CD_ZERO, dry_buoyancy=dry_b, &
                                          water_weight=opts%rhoW*opts%g, current=cur_obj, &
                                          energy_minimization=energy)
        total_it = total_it + it_w
        IF (es_w == CD_HCSTAT_OK .AND. .NOT. folded) THEN
          ! The arch turned over toward the real anchor: fold the last state before it.
          IF (arch_turned(q_new)) THEN
            fold_now = .TRUE.
            CYCLE
          END IF
        END IF
        IF (es_w == CD_HCSTAT_OK) THEN
          q_prev = q_cont
          q_cont = q_new
          dt_prev = dt
          have_prev = .TRUE.
          tw = tw + dt
          IF (CD_ONE - tw <= 1.0e-12_wp) tw = CD_ONE
          dt = MIN(2.0_wp*dt, WALK_DT_MAX)
        ELSE
          dt = 0.5_wp*dt
          IF (dt < WALK_DT_MIN .OR. total_it > MIN(budget_cont, WALK_BUDGET)) THEN
            iters = iters + total_it
            IF (fold) THEN
              CALL walk_failed('no bow behind the fairlead was reached: the one traced from the anchor moved '// &
                               TRIM(walk_m(span_len + walk_d))//' m behind the fairlead ends '// &
                               TRIM(walk_m((CD_ONE - tw)*NORM2(a_l - a_seed)))//' m short of '// &
                               TRIM(MERGE('the anchor  ', 'the fold fit', folded))//' ('//TRIM(em_w)//')')
            ELSE
              CALL walk_failed('no equilibrium held by its bending stiffness was reached: the one traced from '// &
                               'the anchor moved '//TRIM(walk_m(walk_d))//' m back along the chord ends '// &
                               TRIM(walk_m((CD_ONE - tw)*walk_d))//' m short of the anchor ('//TRIM(em_w)//')')
            END IF
            RETURN
          END IF
        END IF
      END DO
      iters = iters + total_it
      ErrStat = CD_HCSTAT_OK
      ErrMsg = ''

    END SUBROUTINE walk_anchor

    FUNCTION walk_ehat() RESULT(e)
      !! Horizontal unit vector of the chord from the fairlead toward the anchor.
      REAL(wp) :: e(2)
      e = (a_l(1:2) - f_l(1:2))/span_len
    END FUNCTION walk_ehat

    SUBROUTINE fold_fit(q, k_td, fit)
      !! Touchdown node k_td of the bow route (the last node of the run resting on the bed
      !! from the anchor; 1 when there is no such run) and the fit of the fold there: the
      !! grounded arc length less the distance from the touchdown point to the real anchor
      !! along the chord. A node rests on the bed within one element diameter of it.
      REAL(wp), INTENT(IN) :: q(:)
      INTEGER, INTENT(OUT) :: k_td
      REAL(wp), INTENT(OUT) :: fit
      INTEGER :: kk
      k_td = 1
      DO kk = 2, nnode
        IF (q(6*(kk - 1) + 3) > seabed_z + diam(kk - 1)) EXIT
        k_td = kk
      END DO
      IF (k_td >= nnode) k_td = 1
      fit = SUM(l0(1:k_td - 1)) - DOT_PRODUCT(a_l(1:2) - q(6*(k_td - 1) + 1:6*(k_td - 1) + 2), walk_ehat())
    END SUBROUTINE fold_fit

    LOGICAL FUNCTION arch_turned(q) RESULT(turned)
      !! Whether a suspended node of the bow route reaches over the fairlead toward the real
      !! anchor by more than a hundredth of the span: the arch has turned over.
      REAL(wp), INTENT(IN) :: q(:)
      REAL(wp), PARAMETER :: TURN_TOL = 0.01_wp
      REAL(wp) :: xf
      INTEGER :: kk
      xf = DOT_PRODUCT(q(6*nnode - 5:6*nnode - 4), walk_ehat())
      turned = .FALSE.
      DO kk = 2, nnode - 1
        IF (q(6*(kk - 1) + 3) <= seabed_z + diam(kk - 1)) CYCLE
        IF (DOT_PRODUCT(q(6*(kk - 1) + 1:6*(kk - 1) + 2), walk_ehat()) - xf > TURN_TOL*span_len) turned = .TRUE.
      END DO
    END FUNCTION arch_turned

    RECURSIVE SUBROUTINE graded_restart()
      !! A rotationally restrained end (rigid, or a finite spring) forces the tangent there,
      !! and the line turns to its free direction over the boundary layer sqrt(EI/T), which
      !! can be orders of magnitude shorter than the end element. Repeat the route on a
      !! mesh whose restrained end elements are split geometrically (halving toward the end)
      !! until the element at the end is at most half that boundary layer; T is the seed's
      !! end tension (at least the catenary's horizontal tension).
      INTEGER, PARAMETER :: MAX_HALVINGS = 24
      REAL(wp), ALLOCATABLE :: l0_g(:), ea_g(:), ei_g(:), w_g(:), diam_g(:), dry_g(:)
      INTEGER, ALLOCATABLE :: fixed_g(:), parent_g(:), node_of(:)
      LOGICAL, ALLOCATABLE :: fixed_map(:, :)
      LOGICAL :: planar, inadm_g, walked_sub
      INTEGER :: kend(2), iend, e_end, k, j, n_g, nf, es_g, slot
      REAL(wp) :: t_end, blayer
      CHARACTER(512) :: em_g
      IF (PRESENT(refined_pass) .OR. fold) RETURN
      kend = 0
      DO iend = 1, 2
        IF (endconn_mode(iend) /= CD_ENDCONN_RIGID .AND. &
            .NOT. (endconn_mode(iend) == CD_ENDCONN_FINITE .AND. endconn_k(iend) > CD_ZERO)) CYCLE
        e_end = MERGE(1, ne, iend == 1)
        IF (.NOT. (ei(e_end) > CD_ZERO)) CYCLE
        t_end = MAX(horizontal_tension, ea(e_end)*(stretch(e_end) - CD_ONE), TINY(CD_ONE))
        blayer = SQRT(ei(e_end)/t_end)
        DO WHILE (l0(e_end)/2.0_wp**kend(iend) > 0.5_wp*blayer .AND. kend(iend) < MAX_HALVINGS)
          kend(iend) = kend(iend) + 1
        END DO
      END DO
      IF (ALL(kend == 0)) RETURN
      IF (ne == 1 .AND. ALL(kend > 0)) RETURN
      ! Graded element list: the end element becomes l0*[2^-k, 2^-k, 2^-(k-1), ..., 2^-1]
      ! ordered from the end inward.
      n_g = ne + SUM(kend)
      ALLOCATE (l0_g(n_g), parent_g(n_g), node_of(nnode))
      j = 0
      DO k = 1, ne
        IF (k == 1 .AND. kend(1) > 0) THEN
          j = j + 1; l0_g(j) = l0(1)/2.0_wp**kend(1); parent_g(j) = 1
          DO slot = kend(1), 1, -1
            j = j + 1; l0_g(j) = l0(1)/2.0_wp**slot; parent_g(j) = 1
          END DO
        ELSE IF (k == ne .AND. kend(2) > 0) THEN
          DO slot = 1, kend(2)
            j = j + 1; l0_g(j) = l0(ne)/2.0_wp**slot; parent_g(j) = ne
          END DO
          j = j + 1; l0_g(j) = l0(ne)/2.0_wp**kend(2); parent_g(j) = ne
        ELSE
          j = j + 1; l0_g(j) = l0(k); parent_g(j) = k
        END IF
        node_of(k + 1) = j + 1
      END DO
      node_of(1) = 1
      ALLOCATE (ea_g(n_g), ei_g(n_g), w_g(n_g), diam_g(n_g), dry_g(n_g))
      ea_g = ea(parent_g); ei_g = ei(parent_g); w_g = w(parent_g)
      diam_g = diam(parent_g); dry_g = dry_b(parent_g)
      ! Held DOFs: the parent nodes keep theirs; inserted nodes take the out-of-plane
      ! reduction (y, m_y) when the deck holds it on every node.
      ALLOCATE (fixed_map(6, nnode))
      fixed_map = .FALSE.
      DO k = 1, SIZE(fixed_dofs)
        fixed_map(MOD(fixed_dofs(k) - 1, 6) + 1, (fixed_dofs(k) - 1)/6 + 1) = .TRUE.
      END DO
      planar = ALL(fixed_map(2, :))
      ALLOCATE (fixed_g(6*(n_g + 1)))
      nf = 0
      k = 1
      DO j = 1, n_g + 1
        IF (k <= nnode) THEN
          IF (node_of(k) == j) THEN
            DO slot = 1, 6
              IF (fixed_map(slot, k)) THEN
                nf = nf + 1; fixed_g(nf) = 6*(j - 1) + slot
              END IF
            END DO
            k = k + 1
            CYCLE
          END IF
        END IF
        IF (planar) THEN
          nf = nf + 1; fixed_g(nf) = 6*(j - 1) + 2
          nf = nf + 1; fixed_g(nf) = 6*(j - 1) + 5
        END IF
      END DO
      IF (PRESENT(bathymetry)) THEN
        CALL hermite_static_primary(anchor, fairlead, l0_g, ea_g, ei_g, w_g, diam_g, dry_g, fixed_g(1:nf), &
                                    contact_enabled, contact_z, frame_cs, endconn_k, endconn_d0, endconn_mode, &
                                    opts, static_tol, l0_am, ea_am, ei_am, w_am, q_static, curv, fixed_am, &
                                    applied_scale, diag, res, iters, es_g, em_g, inadm_g, tolerance_note, &
                                    kink_refined, bathymetry=bathymetry, refined_pass=.TRUE., cur_obj=cur_obj, &
                                    walked=walked_sub, fold_walk=fold)
      ELSE
        CALL hermite_static_primary(anchor, fairlead, l0_g, ea_g, ei_g, w_g, diam_g, dry_g, fixed_g(1:nf), &
                                    contact_enabled, contact_z, frame_cs, endconn_k, endconn_d0, endconn_mode, &
                                    opts, static_tol, l0_am, ea_am, ei_am, w_am, q_static, curv, fixed_am, &
                                    applied_scale, diag, res, iters, es_g, em_g, inadm_g, tolerance_note, &
                                    kink_refined, refined_pass=.TRUE., cur_obj=cur_obj, walked=walked_sub, &
                                    fold_walk=fold)
      END IF
      IF (es_g == CD_HCSTAT_OK) THEN
        ErrStat = CD_HCSTAT_OK
        ErrMsg = ''
        kink_refined = .TRUE.
        inadmissible = .FALSE.
        IF (PRESENT(walked)) walked = walked_sub
      ELSE
        ErrMsg = TRIM(ErrMsg)//'; on a mesh graded toward the restrained end(s): '//TRIM(em_g)
        IF (inadm_g) inadmissible = .TRUE.
      END IF
    END SUBROUTINE graded_restart

    RECURSIVE SUBROUTINE refined_restart()
      !! Repeat the route on a uniformly refined mesh (power of two, capped) when the
      !! deck mesh is longer than half the bending length (EI/|w|)^(1/3) somewhere. The
      !! refined equilibrium is returned in the *_am outputs like an adaptive refinement.
      REAL(wp), ALLOCATABLE :: l0_r(:), q_r(:), q_ref_r(:), ea_r(:), ei_r(:), w_r(:), diam_r(:), dry_r(:)
      INTEGER, ALLOCATABLE :: fixed_r(:)
      REAL(wp) :: need
      INTEGER :: scale, scale_need, k, es_r, parent
      CHARACTER(512) :: em_r
      LOGICAL :: inadm_r, walked_sub
      IF (PRESENT(refined_pass) .OR. fold) RETURN
      need = CD_ONE
      DO k = 1, ne
        IF (ei(k) > CD_ZERO .AND. ABS(w(k)) > CD_ZERO) &
          need = MAX(need, l0(k)/(0.5_wp*(ei(k)/ABS(w(k)))**(CD_ONE/3.0_wp)))
      END DO
      scale_need = 1
      DO WHILE (REAL(scale_need, wp) < need .AND. scale_need < CD_HC_REFINE_CAP .AND. &
                ne*2*scale_need <= REFINED_MAX_ELEMENTS)
        scale_need = 2*scale_need
      END DO
      IF (scale_need < 2) RETURN
      ! The needed factor first; when its continuation exhausts its element-scaled iteration
      ! budget, the coarser powers of two down to 2x (a halved mesh, still resolving the
      ! bends, can trace it in a second).
      scale = scale_need
      DO WHILE (scale >= 2)
        IF (ALLOCATED(q_r)) DEALLOCATE (q_r)
        IF (ALLOCATED(l0_r)) DEALLOCATE (l0_r)
        IF (ALLOCATED(q_ref_r)) DEALLOCATE (q_ref_r)
        IF (ALLOCATED(fixed_r)) DEALLOCATE (fixed_r)
        IF (ALLOCATED(ea_r)) DEALLOCATE (ea_r, ei_r, w_r, diam_r, dry_r)
        ALLOCATE (q_r(6*nnode))
        q_r = CD_ZERO
        CALL CD_HermiteCable_Refine_Mesh(l0, q_r, fixed_dofs, scale, l0_r, q_ref_r, fixed_r, es_r, em_r, &
                                         inherit_dofs=[2, 5])
        IF (es_r /= CD_HCSTAT_OK) RETURN
        ALLOCATE (ea_r(ne*scale), ei_r(ne*scale), w_r(ne*scale), diam_r(ne*scale), dry_r(ne*scale))
        DO k = 1, ne*scale
          parent = (k - 1)/scale + 1
          ea_r(k) = ea(parent)
          ei_r(k) = ei(parent)
          w_r(k) = w(parent)
          diam_r(k) = diam(parent)
          dry_r(k) = dry_b(parent)
        END DO
        IF (PRESENT(bathymetry)) THEN
          CALL hermite_static_primary(anchor, fairlead, l0_r, ea_r, ei_r, w_r, diam_r, dry_r, fixed_r, &
                                      contact_enabled, contact_z, frame_cs, endconn_k, endconn_d0, endconn_mode, &
                                      opts, static_tol, l0_am, ea_am, ei_am, w_am, q_static, curv, fixed_am, &
                                      applied_scale, diag, res, iters, es_r, em_r, inadm_r, tolerance_note, &
                                      kink_refined, bathymetry=bathymetry, refined_pass=.TRUE., cur_obj=cur_obj, &
                                      walked=walked_sub, fold_walk=fold)
        ELSE
          CALL hermite_static_primary(anchor, fairlead, l0_r, ea_r, ei_r, w_r, diam_r, dry_r, fixed_r, &
                                      contact_enabled, contact_z, frame_cs, endconn_k, endconn_d0, endconn_mode, &
                                      opts, static_tol, l0_am, ea_am, ei_am, w_am, q_static, curv, fixed_am, &
                                      applied_scale, diag, res, iters, es_r, em_r, inadm_r, tolerance_note, &
                                      kink_refined, refined_pass=.TRUE., cur_obj=cur_obj, walked=walked_sub, &
                                      fold_walk=fold)
        END IF
        IF (es_r == CD_HCSTAT_OK) THEN
          ErrStat = CD_HCSTAT_OK
          ErrMsg = ''
          kink_refined = .TRUE.
          inadmissible = .FALSE.
          IF (PRESENT(walked)) walked = walked_sub
          RETURN
        END IF
        ErrMsg = TRIM(ErrMsg)//'; on a '//TRIM(int_to_str(scale))//'x refined mesh: '//TRIM(em_r)
        ! The geometry, not the mesh, stopped the route: a coarser mesh stops the same way.
        IF (inadm_r) THEN
          inadmissible = .TRUE.
          RETURN
        END IF
        ! Only a continuation that ran out of its element-scaled budget is retried coarser.
        IF (INDEX(em_r, 'iteration budget') == 0) RETURN
        scale = scale/2
      END DO
    END SUBROUTINE refined_restart

    SUBROUTINE polish_with_floor()
      !! Polish at the tight tolerance; accept the coupled static tolerance when the
      !! residual floor lies between the two, and the contact floor tolerance when the
      !! Newton iteration stalls between the coupled tolerance and it (nodes chattering
      !! across the 1 um seabed-contact blend). tolerance_note reports either; res holds
      !! the residual actually reached.
      CALL polish(static_tol)
      ! A looser tolerance does not lift the frictionless grounded-run diagnosis of a current in
      ! the plane of the line (planar_run_diagnosed): the polish is not repeated for it.
      IF (planar_run_diagnosed(ErrMsg)) RETURN
      IF (ErrStat == CD_HCSTAT_NOCONVERGE .AND. static_tol < COUPLED_STATIC_TOL .AND. &
          INDEX(ErrMsg, 'Newton did not converge') > 0) THEN
        CALL polish(COUPLED_STATIC_TOL)
        IF (ErrStat == CD_HCSTAT_OK) tolerance_note = .TRUE.
      END IF
      IF (ErrStat == CD_HCSTAT_NOCONVERGE .AND. contact_enabled .AND. &
          INDEX(ErrMsg, 'Newton did not converge') > 0) THEN
        CALL polish(CONTACT_FLOOR_TOL)
        IF (ErrStat == CD_HCSTAT_OK) tolerance_note = .TRUE.
      END IF
    END SUBROUTINE polish_with_floor

    SUBROUTINE polish(tol_polish)
      REAL(wp), INTENT(IN) :: tol_polish
      IF (ALLOCATED(l0_am)) DEALLOCATE (l0_am, ea_am, ei_am, w_am, q_static, curv, fixed_am)
      IF (contact_enabled .AND. PRESENT(bathymetry)) THEN
        CALL CD_HermiteCable_Static_Solve_AutoMesh(l0, ea, ei, w, q_cont, fixed_dofs, contact_z, CD_ZERO, &
                                                   8, 200, tol_polish, 0.7_wp, h_target, CD_ZERO, &
                                                   CD_HC_REFINE_CAP, [2, 5], l0_am, ea_am, ei_am, w_am, &
                                                   q_static, curv, fixed_am, applied_scale, diag, res, &
                                                   polish_iters, ErrStat, ErrMsg, &
                                                   contact_diameter=diam, contact_kbot=opts%kbot, &
                                                   bathymetry=bathymetry, contact_frame_cs=frame_cs, &
                                                   initial_polish=.TRUE., require_resolved=.FALSE., &
                                                   axial_quadrature_order=opts%axial_quadrature_order, &
                                                   bending_quadrature_order=opts%bending_quadrature_order, &
                                                   require_tensile=tensile, &
                                                   compression_mode=cmode, &
                                                   energy_polish_in=.TRUE., tensile_advisory=.NOT. tensile, &
                                                   refine_non_axial=refine_all, &
                                                   endconn_stiffness=endconn_k, endconn_direction=endconn_d0, &
                                                   endconn_mode=endconn_mode, waterline_z=CD_ZERO, dry_buoyancy=dry_b, &
                                                   water_weight=opts%rhoW*opts%g, current=cur_obj)
      ELSE IF (contact_enabled) THEN
        CALL CD_HermiteCable_Static_Solve_AutoMesh(l0, ea, ei, w, q_cont, fixed_dofs, contact_z, CD_ZERO, &
                                                   8, 200, tol_polish, 0.7_wp, h_target, CD_ZERO, &
                                                   CD_HC_REFINE_CAP, [2, 5], l0_am, ea_am, ei_am, w_am, &
                                                   q_static, curv, fixed_am, applied_scale, diag, res, &
                                                   polish_iters, ErrStat, ErrMsg, &
                                                   contact_diameter=diam, contact_kbot=opts%kbot, &
                                                   contact_frame_cs=frame_cs, &
                                                   initial_polish=.TRUE., require_resolved=.FALSE., &
                                                   axial_quadrature_order=opts%axial_quadrature_order, &
                                                   bending_quadrature_order=opts%bending_quadrature_order, &
                                                   require_tensile=tensile, &
                                                   compression_mode=cmode, &
                                                   energy_polish_in=.TRUE., tensile_advisory=.NOT. tensile, &
                                                   refine_non_axial=refine_all, &
                                                   endconn_stiffness=endconn_k, endconn_direction=endconn_d0, &
                                                   endconn_mode=endconn_mode, waterline_z=CD_ZERO, dry_buoyancy=dry_b, &
                                                   water_weight=opts%rhoW*opts%g, current=cur_obj)
      ELSE
        CALL CD_HermiteCable_Static_Solve_AutoMesh(l0, ea, ei, w, q_cont, fixed_dofs, contact_z, CD_ZERO, &
                                                   8, 200, tol_polish, 0.7_wp, h_target, CD_ZERO, &
                                                   CD_HC_REFINE_CAP, [2, 5], l0_am, ea_am, ei_am, w_am, &
                                                   q_static, curv, fixed_am, applied_scale, diag, res, &
                                                   polish_iters, ErrStat, ErrMsg, &
                                                   initial_polish=.TRUE., require_resolved=.FALSE., &
                                                   axial_quadrature_order=opts%axial_quadrature_order, &
                                                   bending_quadrature_order=opts%bending_quadrature_order, &
                                                   require_tensile=tensile, &
                                                   compression_mode=cmode, &
                                                   energy_polish_in=.TRUE., tensile_advisory=.NOT. tensile, &
                                                   refine_non_axial=refine_all, &
                                                   endconn_stiffness=endconn_k, endconn_direction=endconn_d0, &
                                                   endconn_mode=endconn_mode, waterline_z=CD_ZERO, dry_buoyancy=dry_b, &
                                                   water_weight=opts%rhoW*opts%g, current=cur_obj)
      END IF
      iters = iters + polish_iters
    END SUBROUTINE polish

  END SUBROUTINE hermite_static_primary

  SUBROUTINE hermite_static_current(ln, sections, types, opts, l0, frame_cs, cur)
    !! The deck's steady current for the finite-EI static solve (CD_HermiteStaticCurrentType):
    !! the uniform or profile velocity, the water density, the still-water surface z = 0 and
    !! the line's hydrodynamic sections (Diam, Cd_n, Cd_t) per element of the deck mesh l0.
    TYPE(DeckLine), INTENT(IN) :: ln
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: l0(:), frame_cs(2)
    TYPE(CD_HermiteStaticCurrentType), INTENT(OUT) :: cur
    REAL(wp), ALLOCATABLE :: can(:), cat(:)
    INTEGER :: e
    ALLOCATE (cur%arc_end(SIZE(l0)), cur%diam(SIZE(l0)), cur%cdn(SIZE(l0)), cur%cdt(SIZE(l0)))
    ALLOCATE (can(SIZE(l0)), cat(SIZE(l0)))
    CALL finite_hydro_arrays(ln, sections, types, cur%diam, cur%cdn, cur%cdt, can, cat)
    cur%arc_end(1) = l0(1)
    DO e = 2, SIZE(l0)
      cur%arc_end(e) = cur%arc_end(e - 1) + l0(e)
    END DO
    cur%rho = opts%rhoW
    cur%waterline_z = CD_ZERO
    cur%frame_cs = frame_cs
    IF (opts%has_current_profile) THEN
      cur%profile_z = opts%current_profile_z
      cur%profile_velocity = opts%current_profile_velocity
    ELSE
      cur%velocity = opts%current_velocity
    END IF
  END SUBROUTINE hermite_static_current

  SUBROUTINE hermite_static_stable(l0_deck, l0, ea, ei, w, diam_deck, dry_deck, q, fixed_dofs, contact_enabled, &
                                   contact_z, frame_cs, endconn_k, endconn_d0, endconn_mode, opts, stable, &
                                   ErrStat, ErrMsg, bathymetry, cur_obj)
    !! Stability of a converged deck-cable equilibrium on its final (possibly refined)
    !! mesh l0: positive definiteness of the tangent of the full static problem (the
    !! same contact, dry-buoyancy and end-connection terms as the solve) on the free
    !! DOFs. diam_deck/dry_deck live on the deck mesh l0_deck and are mapped by
    !! reference arc. One residual evaluation, no update.
    REAL(wp), INTENT(IN) :: l0_deck(:), l0(:), ea(:), ei(:), w(:), diam_deck(:), dry_deck(:), q(:)
    INTEGER, INTENT(IN) :: fixed_dofs(:)
    LOGICAL, INTENT(IN) :: contact_enabled
    REAL(wp), INTENT(IN) :: contact_z, frame_cs(2), endconn_k(2), endconn_d0(3, 2)
    INTEGER, INTENT(IN) :: endconn_mode(2)
    TYPE(DeckOptions), INTENT(IN) :: opts
    LOGICAL, INTENT(OUT) :: stable
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    TYPE(CD_HermiteStaticCurrentType), INTENT(IN), OPTIONAL :: cur_obj
    REAL(wp), ALLOCATABLE :: diam(:), dry(:), knnode(:), q_eval(:), curv(:)
    REAL(wp) :: res
    INTEGER :: i, ne, it, es
    CHARACTER(512) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    stable = .FALSE.
    ne = SIZE(l0)
    ALLOCATE (diam(SIZE(diam_deck)), dry(SIZE(dry_deck)))
    diam = diam_deck
    dry = dry_deck
    IF (ne /= SIZE(l0_deck)) THEN
      CALL remap_elem_by_reference_arc(diam, l0_deck, l0)
      CALL remap_elem_by_reference_arc(dry, l0_deck, l0)
    END IF
    ALLOCATE (q_eval(SIZE(q)), curv(ne + 1))
    IF (contact_enabled) THEN
      ALLOCATE (knnode(ne + 1))
      knnode = CD_ZERO
      DO i = 1, ne
        knnode(i) = knnode(i) + 0.5_wp*opts%kbot*diam(i)*l0(i)
        knnode(i + 1) = knnode(i + 1) + 0.5_wp*opts%kbot*diam(i)*l0(i)
      END DO
      CALL CD_HermiteCable_Static_Solve(l0, ea, ei, w, q, fixed_dofs, contact_z, CD_ZERO, 1, 1, &
                                        HUGE(CD_ONE), CD_ONE, q_eval, curv, res, it, es, em, n_buoy_steps=1, &
                                        contact_kn=knnode, bathymetry=bathymetry, contact_frame_cs=frame_cs, &
                                        axial_quadrature_order=opts%axial_quadrature_order, &
                                        bending_quadrature_order=opts%bending_quadrature_order, &
                                        endconn_stiffness=endconn_k, endconn_direction=endconn_d0, &
                                        endconn_mode=endconn_mode, waterline_z=CD_ZERO, dry_buoyancy=dry, &
                                        water_weight=opts%rhoW*opts%g, current=cur_obj, &
                                        stable=stable)
    ELSE
      CALL CD_HermiteCable_Static_Solve(l0, ea, ei, w, q, fixed_dofs, contact_z, CD_ZERO, 1, 1, &
                                        HUGE(CD_ONE), CD_ONE, q_eval, curv, res, it, es, em, n_buoy_steps=1, &
                                        axial_quadrature_order=opts%axial_quadrature_order, &
                                        bending_quadrature_order=opts%bending_quadrature_order, &
                                        endconn_stiffness=endconn_k, endconn_direction=endconn_d0, &
                                        endconn_mode=endconn_mode, waterline_z=CD_ZERO, dry_buoyancy=dry, &
                                        water_weight=opts%rhoW*opts%g, current=cur_obj, &
                                        stable=stable)
    END IF
    IF (es /= CD_HCSTAT_OK) THEN
      CALL fail_solve(ErrStat, ErrMsg, 'finite-EI static stability evaluation failed: '//TRIM(em))
    END IF
  END SUBROUTINE hermite_static_stable

  SUBROUTINE hermite_static_torsion(l0_deck, l0, ea, ei, w, diam_deck, dry_deck, q, curv, fixed_dofs, &
                                    contact_enabled, contact_z, frame_cs, endconn_k, endconn_d0, endconn_mode, opts, &
                                    tol, tors, ErrStat, ErrMsg, bathymetry, cur_obj)
    !! Torsion stage of a deck cable on its final mesh l0: CD_HermiteCable_Static_Solve from the
    !! converged untwisted state q (one EI and buoyancy stage, a polish) with the torsion
    !! description tors, under the same contact, dry-buoyancy, end-connection and current terms
    !! as hermite_static_stable. On success q and curv hold the twisted equilibrium and tors its
    !! accepted Theta, torque and stability report.
    REAL(wp), INTENT(IN) :: l0_deck(:), l0(:), ea(:), ei(:), w(:), diam_deck(:), dry_deck(:)
    REAL(wp), INTENT(INOUT) :: q(:), curv(:)
    INTEGER, INTENT(IN) :: fixed_dofs(:)
    LOGICAL, INTENT(IN) :: contact_enabled
    REAL(wp), INTENT(IN) :: contact_z, frame_cs(2), endconn_k(2), endconn_d0(3, 2), tol
    INTEGER, INTENT(IN) :: endconn_mode(2)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(CD_HermiteTorsionType), INTENT(INOUT) :: tors
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    TYPE(CD_HermiteStaticCurrentType), INTENT(IN), OPTIONAL :: cur_obj
    REAL(wp), ALLOCATABLE :: diam(:), dry(:), knnode(:), q_out(:)
    REAL(wp) :: res
    INTEGER :: i, ne, it, es
    CHARACTER(1024) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    ne = SIZE(l0)
    diam = diam_deck
    dry = dry_deck
    IF (ne /= SIZE(l0_deck)) THEN
      CALL remap_elem_by_reference_arc(diam, l0_deck, l0)
      CALL remap_elem_by_reference_arc(dry, l0_deck, l0)
    END IF
    ALLOCATE (q_out(SIZE(q)))
    IF (contact_enabled) THEN
      ALLOCATE (knnode(ne + 1))
      knnode = CD_ZERO
      DO i = 1, ne
        knnode(i) = knnode(i) + 0.5_wp*opts%kbot*diam(i)*l0(i)
        knnode(i + 1) = knnode(i + 1) + 0.5_wp*opts%kbot*diam(i)*l0(i)
      END DO
      CALL CD_HermiteCable_Static_Solve(l0, ea, ei, w, q, fixed_dofs, contact_z, CD_ZERO, 1, 200, &
                                        tol, 0.7_wp, q_out, curv, res, it, es, em, n_buoy_steps=1, &
                                        contact_kn=knnode, bathymetry=bathymetry, contact_frame_cs=frame_cs, &
                                        axial_quadrature_order=opts%axial_quadrature_order, &
                                        bending_quadrature_order=opts%bending_quadrature_order, &
                                        endconn_stiffness=endconn_k, endconn_direction=endconn_d0, &
                                        endconn_mode=endconn_mode, waterline_z=CD_ZERO, dry_buoyancy=dry, &
                                        water_weight=opts%rhoW*opts%g, current=cur_obj, torsion=tors)
    ELSE
      CALL CD_HermiteCable_Static_Solve(l0, ea, ei, w, q, fixed_dofs, contact_z, CD_ZERO, 1, 200, &
                                        tol, 0.7_wp, q_out, curv, res, it, es, em, n_buoy_steps=1, &
                                        axial_quadrature_order=opts%axial_quadrature_order, &
                                        bending_quadrature_order=opts%bending_quadrature_order, &
                                        endconn_stiffness=endconn_k, endconn_direction=endconn_d0, &
                                        endconn_mode=endconn_mode, waterline_z=CD_ZERO, dry_buoyancy=dry, &
                                        water_weight=opts%rhoW*opts%g, current=cur_obj, torsion=tors)
    END IF
    IF (es == CD_HCSTAT_BADINPUT) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI torsion static solve rejected the input: '//TRIM(em)); RETURN
    ELSE IF (es /= CD_HCSTAT_OK) THEN
      CALL fail_solve(ErrStat, ErrMsg, 'finite-EI torsion static solve failed: '//TRIM(em)); RETURN
    END IF
    IF (.NOT. tors%stable) THEN
      CALL fail_solve(ErrStat, ErrMsg, 'finite-EI torsion static solve ended on an unstable equilibrium'); RETURN
    END IF
    q = q_out
  END SUBROUTINE hermite_static_torsion

  SUBROUTINE audit_hermite_static(l0, q, ea, ei, w, diam, endconn_mode, physical, message, compression_note)
    !! Physical-branch audit of a converged deck cable (CD_HermiteCable_Branch_Audit).
    !! A rotationally restrained end (Finite/Rigid connection) may turn the centreline
    !! against the chord heading inside its bending boundary layer, of length
    !! sqrt(EI/T) at the end tension; five such lengths (at most a quarter of the line)
    !! are excluded from the backtracking measure there. A pinned end has no layer.
    !! The compression a bending-stiff line can carry is taken as twice the largest
    !! weight over one bending length, 2*max(|w|*lambda), lambda = (EI/|w|)^(1/3).
    !! diam are the element diameters on the same mesh (the self-contact clearance).
    REAL(wp), INTENT(IN) :: l0(:), q(:), ea(:), ei(:), w(:), diam(:)
    INTEGER, INTENT(IN) :: endconn_mode(2)
    LOGICAL, INTENT(OUT) :: physical
    CHARACTER(*), INTENT(OUT) :: message
    CHARACTER(*), INTENT(OUT), OPTIONAL :: compression_note
    TYPE(CD_HermiteBranchAuditType) :: audit
    REAL(wp) :: zone(2), qe(12), t_end, total, allowance, hl_max, excess, denom
    LOGICAL :: report_c
    INTEGER :: ne, iend, e, es
    CHARACTER(200) :: em

    physical = .FALSE.
    message = ''
    ne = SIZE(l0)
    total = SUM(l0)
    allowance = CD_ZERO
    DO e = 1, ne
      IF (ABS(w(e)) > CD_ZERO .AND. ei(e) > CD_ZERO) &
        allowance = MAX(allowance, 2.0_wp*ABS(w(e))*(ei(e)/ABS(w(e)))**(CD_ONE/3.0_wp))
    END DO
    zone = CD_ZERO
    DO iend = 1, 2
      IF (endconn_mode(iend) == CD_ENDCONN_PINNED) CYCLE
      e = MERGE(1, ne, iend == 1)
      qe(1:6) = q(6*(e - 1) + 1:6*e)
      qe(7:12) = q(6*e + 1:6*(e + 1))
      CALL CD_HermiteCable_Axial_Resultant(qe, l0(e), ea(e), MERGE(CD_ZERO, CD_ONE, iend == 1), t_end, es, em)
      zone(iend) = 0.25_wp*total
      IF (es == CD_HCABLE_OK .AND. t_end > CD_ZERO .AND. ei(e) > CD_ZERO) &
        zone(iend) = MIN(zone(iend), 5.0_wp*SQRT(ei(e)/t_end))
    END DO
    CALL CD_HermiteCable_Branch_Audit(l0, q, ea, audit, es, em, end_zone=zone, compression_allowance=allowance, &
                                      diameter=diam)
    IF (es /= CD_HCSTAT_OK) THEN
      message = 'physical-branch audit failed: '//TRIM(em)
      RETURN
    END IF
    physical = audit%physical
    IF (PRESENT(compression_note)) THEN
      ! Mesh adequacy: a cubic-Hermite element longer than the bending length
      ! lambda = (EI/|w|)^(1/3) cannot follow the bends of the line (touchdown, arch,
      ! grounded run between contact nodes); its pointwise axial resultant then
      ! oscillates about the tension. Report either that, or genuine compression.
      ! Both notes are judged on element-mean axial forces, never on the pointwise trace:
      ! the pointwise resultant, and a single element mean between tensile neighbours, dip
      ! next to a nodal seabed-contact reaction (a kink no element can follow, at every
      ! mesh) while the line in equilibrium stays tensile. Compression is reported when the
      ! 3-element smoothed mean exceeds the admissible band, or when the node Tension
      ! channel (the segment tension) falls below a tenth of the peak tension.
      hl_max = CD_ZERO
      DO e = 1, ne
        IF (ABS(w(e)) > CD_ZERO .AND. ei(e) > CD_ZERO) &
          hl_max = MAX(hl_max, l0(e)/(ei(e)/ABS(w(e)))**(CD_ONE/3.0_wp))
      END DO
      compression_note = ''
      ! The pointwise oscillation scales with (h*kappa)^2: the refinement factor that brings
      ! it below a tenth of the peak tension is the square root of the excess.
      ! The ratio is capped at 1e12 so a line with no tensile peak does not overflow, and the
      ! refinement factor below stays a representable integer.
      denom = MAX(CD_HC_OSCILLATION_REL_TOL*MAX(audit%axial_max, CD_ZERO), TINY(CD_ONE))
      excess = MIN(-audit%axial_min, 1.0E12_wp*denom)/denom
      ! Element-mean compression accounting for at least half the pointwise minimum is the
      ! physics of a bent equilibrium, not discretisation oscillation.
      IF (-audit%smoothed_axial_min >= -0.5_wp*audit%axial_min) excess = CD_ZERO
      report_c = audit%smoothed_compressed .OR. &
                 audit%nodal_axial_min < -CD_HC_OSCILLATION_REL_TOL*MAX(audit%mean_axial_max, CD_ZERO)
      IF (audit%smoothed_compressed .AND. excess > CD_ONE) THEN
        WRITE (compression_note, '(A,ES10.3,A,ES10.3,A,F5.2,A,F6.2,A,I0,A)') &
          'mesh too coarse for its bends: the pointwise axial resultant oscillates to ', audit%axial_min, &
          ' N (peak ', MAX(audit%axial_max, CD_ZERO), ' N; max h*kappa ', audit%h_kappa_peak, ', elements up to ', &
          hl_max, ' bending lengths); refine NumSegs about ', MAX(2, CEILING(SQRT(excess))), &
          'x there or set tensile_safety True'
      ELSE IF (report_c) THEN
        WRITE (compression_note, '(A,ES10.3,A,I0,A,ES10.3,A)') &
          'carries element-mean axial compression ', -MIN(audit%smoothed_axial_min, audit%nodal_axial_min), &
          ' N (about element ', audit%smoothed_min_elem, ', internal order; peak tension ', &
          MAX(audit%mean_axial_max, CD_ZERO), ' N) in a stable bent equilibrium'
      END IF
    END IF
    SELECT CASE (audit%failed_check)
    CASE (CD_HC_AUDIT_BACKTRACK)
      WRITE (message, '(A,I0,A,I0,A,ES10.3,A)') 'non-physical branch: the line loops or folds onto itself '// &
        '(elements ', audit%contact_elem_a, ' and ', audit%contact_elem_b, ' overlap by ', -audit%self_gap, ' m)'
    CASE (CD_HC_AUDIT_COMPRESSION)
      WRITE (message, '(A,ES10.3,A,ES10.3,A,I0,A,ES10.3,A)') 'non-physical branch: element-mean axial '// &
        'compression ', -audit%mean_axial_min, ' N exceeds the admissible ', audit%compression_limit, &
        ' N at element ', audit%axial_min_elem, ' (peak tension ', MAX(audit%mean_axial_max, CD_ZERO), ' N)'
    CASE (CD_HC_AUDIT_KINK)
      WRITE (message, '(A,ES10.3,A,ES10.3,A,I0)') 'unresolved/kinked equilibrium: max(h*kappa)=', &
        audit%h_kappa_peak, ' > safety limit=', CD_HC_KINK_LIMIT, ' at element ', audit%h_kappa_elem
    END SELECT
  END SUBROUTINE audit_hermite_static

  FUNCTION diam_on(l0_deck, l0, diam_deck) RESULT(diam)
    !! Element diameters of the deck mesh mapped onto a nested (refined) mesh.
    REAL(wp), INTENT(IN) :: l0_deck(:), l0(:), diam_deck(:)
    REAL(wp), ALLOCATABLE :: diam(:)
    ALLOCATE (diam(SIZE(diam_deck)))
    diam = diam_deck
    IF (SIZE(l0) /= SIZE(l0_deck)) CALL remap_elem_by_reference_arc(diam, l0_deck, l0)
  END FUNCTION diam_on

  PURE FUNCTION current_limit_diagnosis(msg) RESULT(out)
    !! The static current-limit diagnosis of a Hermite static failure message (the clause
    !! naming the axial compression the current leaves no tension-only equilibrium for, up
    !! to its closing ';'), or blank when the message carries none.
    CHARACTER(*), INTENT(IN) :: msg
    CHARACTER(512) :: out
    INTEGER :: i0, i1
    out = ''
    IF (INDEX(msg, 'tension-only equilibrium') == 0) RETURN
    i0 = INDEX(msg, 'the run on the seabed is in axial compression')
    IF (i0 == 0) i0 = INDEX(msg, 'the run on the seabed folds against its end')
    IF (i0 == 0) i0 = INDEX(msg, 'the line is in axial compression')
    IF (i0 == 0) RETURN
    i1 = INDEX(msg(i0:), ';')
    IF (i1 == 0) THEN
      out = msg(i0:)
    ELSE
      out = msg(i0:i0 + i1 - 2)
    END IF
  END FUNCTION current_limit_diagnosis

  PURE FUNCTION short_message(msg, max_len) RESULT(out)
    !! Bound a nested diagnostic to max_len characters, marking an elision.
    CHARACTER(*), INTENT(IN) :: msg
    INTEGER, INTENT(IN) :: max_len
    CHARACTER(max_len) :: out
    IF (LEN_TRIM(msg) <= max_len) THEN
      out = msg
    ELSE
      out = msg(1:max_len - 4)//' ...'
    END IF
  END FUNCTION short_message

  SUBROUTINE CD_Init_Deck_HermiteCable(deck_path, dt, cable, coupled_node, ErrStat, ErrMsg)
    !! Parse a single-cable deck (exactly one finite-EI LINE) and build it as a COUPLED
    !! cubic-Hermite lazy-wave cable driven at the fairlead. Fails closed on an EI=0 deck (use
    !! CD_Init_Deck_System) or a deck with more than one line (use the aggregate facade).
    CHARACTER(*), INTENT(IN) :: deck_path
    REAL(wp), INTENT(IN) :: dt
    TYPE(CD_HFMF_ModuleType), INTENT(INOUT) :: cable
    INTEGER, INTENT(OUT) :: coupled_node
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    TYPE(DeckLineType), ALLOCATABLE :: types(:)
    TYPE(DeckBody), ALLOCATABLE :: bodies(:)
    TYPE(DeckRodType), ALLOCATABLE :: rod_types(:)
    TYPE(DeckRod), ALLOCATABLE :: rods(:)
    TYPE(DeckPoint), ALLOCATABLE :: points(:)
    TYPE(DeckLine), ALLOCATABLE :: lines(:)
    TYPE(DeckSection), ALLOCATABLE :: sections(:)
    TYPE(DeckOptions) :: opts
    CHARACTER(NAMELEN), ALLOCATABLE :: channels(:)
    TYPE(CD_BathymetryType) :: bathymetry

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    coupled_node = 0
    CALL parse_deck(deck_path, types, bodies, rod_types, rods, points, lines, sections, opts, channels, &
                    ErrStat, ErrMsg, caller_driven=.TRUE.)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    IF (deck_has_torsion_columns(lines)) THEN
      CALL fail(ErrStat, ErrMsg, 'torsion is not yet supported in coupled OpenFAST runs (nor on the mixed '// &
                'EI = 0 + finite-EI aggregate route or in FAST.Farm); set TorsStiffness Free in the END '// &
                'CONNECTIONS rows'); RETURN
    END IF
    IF (.NOT. deck_has_finite_ei(types, sections)) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_HermiteCable: deck has no finite-EI (EI>0) line; '// &
                'EI=0 decks use CD_Init_Deck_System'); RETURN
    END IF
    IF (SIZE(lines) /= 1) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_HermiteCable builds one cable; multi-line mixed '// &
                'decks are handled by the OpenFAST aggregator'); RETURN
    END IF
    IF (SIZE(bodies) > 0 .OR. SIZE(rods) > 0) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_HermiteCable does not support BODY/ROD decks'); RETURN
    END IF
    ! A coupled cable is driven at its fairlead by the HOST (the platform, through
    ! CD_HFMF_UpdateStates), so a deck-declared motionFile prescribes the wrong boundary. Reject
    ! it rather than silently drop it -- parse_deck accepts a motionFile in caller_driven mode
    ! (it just needs dtM/TMax), and the other coupled entry points reject it explicitly too.
    IF (opts%has_motion_file) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_HermiteCable: a coupled cable fairlead is driven by the '// &
                'host (CD_HFMF_UpdateStates), not a deck motionFile; remove the motionFile OPTION'); RETURN
    END IF
    ! Fail closed on declared-but-unhandled environment: this single-cable entry applies
    ! structural, drag, added-mass, seabed-contact and friction loads, but no ambient fluid
    ! field. Ambient current and wave kinematics enter through the aggregate facade's shared
    ! host fluid field, not per cable from the deck. Rejecting them keeps the builder from
    ! silently running a deck that asked for physics it does not apply.
    IF (opts%has_current .OR. opts%has_current_profile) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_HermiteCable: a deck current is not supported by this '// &
                'single-cable entry; use the aggregate facade, which applies the host fluid field'); RETURN
    END IF
    IF (opts%has_wave) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_HermiteCable: deck waves are not supported by this '// &
                'single-cable entry; use the aggregate facade, which applies the host fluid field'); RETURN
    END IF
    IF (opts%waterkin_seastate) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_HermiteCable cannot consume WaveKinMod 2/SEASTATE; '// &
                'use the aggregate facade with its external SeaState field'); RETURN
    END IF
    IF (opts%has_bathymetry_file) THEN
      CALL load_bathymetry_file(path_join(deck_dir(deck_path), opts%bathymetry_file), bathymetry, ErrStat, ErrMsg, &
                                points=points)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL build_one_hermite_cable(lines(1), sections, types, points, opts, dt, cable, coupled_node, &
                                   ErrStat, ErrMsg, bathymetry=bathymetry)
      CALL CD_End_Bathymetry(bathymetry)
    ELSE
      CALL build_one_hermite_cable(lines(1), sections, types, points, opts, dt, cable, coupled_node, ErrStat, ErrMsg)
    END IF
  END SUBROUTINE CD_Init_Deck_HermiteCable

  SUBROUTINE CD_Init_Deck_Aggregate(deck_path, dt, agg, ErrStat, ErrMsg, env_gravity, env_rho_water, env_wtrdpth, &
                                    ptfm_init, external_fluid, coupled_positions, &
                                    n_turbines, turbine_ref_pos, farm_ptfm_init, forbid_deck_ambient, run_tmax, &
                                    range_files)
    !! Parse a MIXED deck ONCE and partition its lines into {EI=0 mooring} and
    !! {finite-EI cable}, returning the raw parts the OpenFAST aggregate facade wraps:
    !! the EI=0 mooring SYSTEM built from the mooring subset (over ALL deck points, the
    !! unbound cable endpoints being silently skipped by the point-coupled map) plus one
    !! COUPLED Hermite cable per finite-EI line. This is the aggregate composition entry:
    !! one CableDyn deck carrying both mooring lines and finite-EI power cables behind the
    !! same FMF moving-point facade. env_gravity / env_rho_water / env_wtrdpth are the
    !! coupled host's environment, threaded through the single parse so the EI=0 system and
    !! the cables are both built under the environment the host owns (host overrides deck).
    !!
    !! Scope: EI=0 lines with Fixed/Coupled/Vessel/Connect/Free points, Point3 buoys, Rigid6
    !! bodies and RODs (host-coupled or free), CONTROL, FAILURE and FAST.Farm turbines, plus
    !! finite-EI cables. Fails closed with a clear message on: a motionFile (the host drives the
    !! coupled boundary); deck waves (the host supplies wave kinematics); a deck current on
    !! a deck with a finite-EI cable, a Rigid6 body or a rod, under a host fluid field, or in
    !! FAST.Farm mode; a deck with a finite-EI cable that also carries Free/Connect dynamic
    !! points. A deck current on any other deck is a steady field applied through the lines.
    !! Coupled finite-EI flat/structured contact and friction use the same production
    !! Hermite residual as the standalone route.
    !! ptfm_init (optional, 6): initial platform displacement [surge, sway, heave,
    !! roll, pitch, yaw] about the origin. Every Coupled/Vessel point's coordinates
    !! are rigid-transformed BEFORE any build or static solve -- p' = r + M^T p with
    !! M the NWTC ZYX (3-2-1) global-to-local DCM, matching MoorDyn-F's PtfmInit
    !! convention -- so the static equilibrium is solved at the DISPLACED pose,
    !! correct by construction (never an implicit step from the undisplaced statics).
    CHARACTER(*), INTENT(IN) :: deck_path
    REAL(wp), INTENT(IN) :: dt
    TYPE(CD_DeckAggregateType), INTENT(INOUT) :: agg
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp), INTENT(IN), OPTIONAL :: env_gravity, env_rho_water, env_wtrdpth
    REAL(wp), INTENT(IN), OPTIONAL :: run_tmax
    REAL(wp), INTENT(IN), OPTIONAL :: ptfm_init(6)
    ! external_fluid: the host prescribes per-node ambient fluid kinematics each step
    ! (the OpenFAST shell sampling a SeaState WaveField). The EI=0 line models are built
    ! wave-capable at zero fields (see DeckOptions%external_fluid); the deck must not
    ! also declare its own waves/current (double-counting). Finite-EI cables receive the
    ! same host field through CD_HFMF_Set_Held_Fluid.
    LOGICAL, INTENT(IN), OPTIONAL :: external_fluid
    ! coupled_positions (3, n_moving): explicit placement of every host-prescribed
    ! (moving) point BEFORE the static solves, in the aggregate moving-set order --
    ! the system's BOUND Coupled/Vessel points in deck POINT order, then one coupled
    ! fairlead per finite-EI cable in deck LINE order. The generalization of ptfm_init
    ! (which is a rigid transform of the same points; the two are mutually exclusive).
    ! Consumed by the linearization probe: each perturbed init IS a static solve at
    ! the probed boundary.
    REAL(wp), INTENT(IN), OPTIONAL :: coupled_positions(:, :)
    ! FAST.Farm mode (n_turbines >= 1): every Coupled/Vessel point must carry the
    ! Turbine<J> vocabulary; each turbine-J point is transformed by that turbine's
    ! farm_ptfm_init(:, J) rigid displacement and shifted by turbine_ref_pos(:, J)
    ! into the FARM-GLOBAL frame the solver works in (MoorDyn's convention: deck
    ! coupled coordinates are turbine-local). Mutually exclusive with the
    ! single-turbine ptfm_init.
    INTEGER, INTENT(IN), OPTIONAL :: n_turbines
    REAL(wp), INTENT(IN), OPTIONAL :: turbine_ref_pos(:, :)
    REAL(wp), INTENT(IN), OPTIONAL :: farm_ptfm_init(:, :)
    ! forbid_deck_ambient: the caller's documented scope is STILL WATER (e.g. the
    ! FAST.Farm shell, where no farm-spanning fluid field exists), so a deck that
    ! declares its own waves/current OPTIONS must fail closed rather than silently
    ! self-drive ambient forcing against that scope. Independent of external_fluid
    ! (which rejects the same options for the opposite reason: double-counting).
    LOGICAL, INTENT(IN), OPTIONAL :: forbid_deck_ambient
    ! range_files: the caller writes the range graphs of the LINES flag r (the standalone
    ! mixed route); a coupled host does not, so the flag fails closed there.
    LOGICAL, INTENT(IN), OPTIONAL :: range_files

    INTEGER :: nturb
    TYPE(DeckLineType), ALLOCATABLE :: types(:)
    TYPE(DeckBody), ALLOCATABLE :: bodies(:)
    TYPE(DeckRodType), ALLOCATABLE :: rod_types(:)
    TYPE(DeckRod), ALLOCATABLE :: rods(:)
    TYPE(DeckPoint), ALLOCATABLE :: points(:)
    TYPE(DeckLine), ALLOCATABLE :: lines(:), ei0_lines(:)
    TYPE(DeckSection), ALLOCATABLE :: sections(:)
    TYPE(DeckOptions) :: opts
    CHARACTER(NAMELEN), ALLOCATABLE :: channels(:)
    TYPE(CD_BathymetryType) :: bathymetry
    TYPE(DeckFailure), ALLOCATABLE :: fails(:)
    TYPE(DeckControl), ALLOCATABLE :: ctrls(:)
    LOGICAL, ALLOCATABLE :: is_fin(:)
    INTEGER :: i, c, n_fin, n_ei0, cn, es, j, k, nctrl_lines, ne_line
    INTEGER :: n_rigid6, n_point3, n_rod, n_host_rod, n_host_body
    REAL(wp) :: fairlead_dcm(3, 3), host_dcm(3, 3)
    ! Preserve the complete multi-hierarchy finite-EI initialization diagnostic.
    ! This path feeds both the aggregate and OpenFAST facade; clipping it hides the
    ! mesh level/resolution evidence users need to correct a rejected deck.
    CHARACTER(2048) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    CALL CD_End_Deck_Aggregate(agg)
    IF (.NOT. (dt > CD_ZERO)) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate requires a positive coupling dt'); RETURN
    END IF
    CALL parse_deck(deck_path, types, bodies, rod_types, rods, points, lines, sections, opts, channels, &
                    ErrStat, ErrMsg, caller_driven=.TRUE., env_gravity=env_gravity, &
                    env_rho_water=env_rho_water, env_wtrdpth=env_wtrdpth, allow_turbine=.TRUE., &
                    failures=fails, controls=ctrls, run_tmax=run_tmax, host_coupled_objects=.TRUE.)
    IF (ErrStat == CD_DECKDRV_OK) THEN
      IF (deck_has_torsion_columns(lines)) THEN
        CALL fail(ErrStat, ErrMsg, 'torsion is not yet supported in coupled OpenFAST runs (nor on the mixed '// &
                  'EI = 0 + finite-EI aggregate route or in FAST.Farm); set TorsStiffness Free in the END '// &
                  'CONNECTIONS rows'); RETURN
      END IF
    END IF
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    host_dcm = CD_ZERO
    host_dcm(1, 1) = CD_ONE
    host_dcm(2, 2) = CD_ONE
    host_dcm(3, 3) = CD_ONE
    IF (PRESENT(ptfm_init)) THEN
      IF (.NOT. ALL(IEEE_IS_FINITE(ptfm_init))) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: ptfm_init must be finite'); RETURN
      END IF
      IF (MAXVAL(ABS(ptfm_init)) > CD_ZERO) THEN
        CALL apply_ptfm_init(points, ptfm_init)
        ! Coupled/Vessel RODS are platform-borne like Coupled points: their ends and their
        ! Rod<N>A/B attachment points move rigidly with the initial platform displacement.
        CALL apply_ptfm_host_rods(rods, points, ptfm_init)
        CALL apply_ptfm_host_bodies(bodies, points, ptfm_init)
        host_dcm = ptfm_zyx_dcm(ptfm_init(4:6))
        ! The transform runs AFTER parse_deck's finalize_and_validate, so the displaced
        ! geometry would otherwise bypass every position-dependent fail-closed check the
        ! parse established. Re-establish them on the mutated positions.
        CALL revalidate_ptfm_points(points, lines, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      END IF
    END IF
    ! ---- FAST.Farm mode -------------------------------------------------------
    nturb = 0
    IF (PRESENT(n_turbines)) nturb = MAX(0, n_turbines)
    IF (nturb > 0) THEN
      IF (PRESENT(ptfm_init)) THEN
        IF (MAXVAL(ABS(ptfm_init)) > CD_ZERO) THEN
          CALL fail(ErrStat, ErrMsg, 'farm mode uses farm_ptfm_init(6, n_turbines); the single-'// &
                    'turbine ptfm_init is mutually exclusive'); RETURN
        END IF
      END IF
      IF (.NOT. PRESENT(turbine_ref_pos)) THEN
        CALL fail(ErrStat, ErrMsg, 'farm mode requires turbine_ref_pos(3, n_turbines)'); RETURN
      END IF
      IF (SIZE(turbine_ref_pos, 1) /= 3 .OR. SIZE(turbine_ref_pos, 2) /= nturb .OR. &
          .NOT. ALL(IEEE_IS_FINITE(turbine_ref_pos))) THEN
        CALL fail(ErrStat, ErrMsg, 'turbine_ref_pos must be finite and shaped (3, n_turbines)'); RETURN
      END IF
      IF (PRESENT(farm_ptfm_init)) THEN
        IF (SIZE(farm_ptfm_init, 1) /= 6 .OR. SIZE(farm_ptfm_init, 2) /= nturb .OR. &
            .NOT. ALL(IEEE_IS_FINITE(farm_ptfm_init))) THEN
          CALL fail(ErrStat, ErrMsg, 'farm_ptfm_init must be finite and shaped (6, n_turbines)'); RETURN
        END IF
      END IF
      DO i = 1, SIZE(points)
        SELECT CASE (TRIM(points(i)%ptype))
        CASE ('coupled', 'vessel')
          IF (points(i)%turbine_id < 1) THEN
            CALL fail(ErrStat, ErrMsg, 'farm mode: every Coupled/Vessel point must use the '// &
                      'Turbine<J> vocabulary (plain Coupled is ambiguous in a farm deck)'); RETURN
          END IF
          IF (points(i)%turbine_id > nturb) THEN
            CALL fail(ErrStat, ErrMsg, 'a POINT references a turbine beyond n_turbines'); RETURN
          END IF
          ! turbine-local -> FARM-GLOBAL: the turbine's initial platform displacement
          ! (rigid, MoorDyn's PtfmInit convention) then the farm-layout reference offset
          IF (PRESENT(farm_ptfm_init)) THEN
            CALL apply_ptfm_point(points(i), farm_ptfm_init(:, points(i)%turbine_id))
          END IF
          points(i)%pos = points(i)%pos + turbine_ref_pos(:, points(i)%turbine_id)
        END SELECT
      END DO
      CALL revalidate_ptfm_points(points, lines, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    ELSE
      DO i = 1, SIZE(points)
        IF (points(i)%turbine_id > 0) THEN
          CALL fail(ErrStat, ErrMsg, 'the deck carries Turbine<J> points but no farm init was '// &
                    'given (pass n_turbines + turbine_ref_pos)'); RETURN
        END IF
      END DO
    END IF
    agg%n_turbines = nturb
    agg%cable_load_feedback = opts%cable_load_feedback
    agg%max_strain = opts%max_strain

    ! The standalone driver retains DeckOptions and evaluates a WaveKinMod-1 Fourier
    ! field at every structural step.  The coupled aggregate does neither: its fluid
    ! fields are refreshed exclusively by the host shell.  Reject self-driven waves
    ! here so a caller-driven deck cannot initialize successfully and then run with
    ! silently zero wave kinematics.
    IF (opts%waterkin_wave_mode == 1) THEN
      CALL fail(ErrStat, ErrMsg, 'WaterKin WaveKinMod 1 is supported only by the standalone driver; '// &
                'coupled aggregate runs must use WaveKinMod 2/SEASTATE through external_fluid')
      RETURN
    END IF
    IF (opts%mdc_wave_kin > 0 .OR. opts%mdc_currents > 0) THEN
      CALL fail(ErrStat, ErrMsg, 'the MoorDyn-C WaveKin 3/7 and Currents 1 files are not supported on the '// &
                'aggregate route (coupled runs take water kinematics from the host; standalone mixed '// &
                'EI=0/finite-EI decks reject deck water kinematics)')
      RETURN
    END IF

    IF (opts%waterkin_seastate) THEN
      IF (.NOT. PRESENT(external_fluid)) THEN
        CALL fail(ErrStat, ErrMsg, 'WaterKin WaveKinMod 2/SEASTATE requires the coupled host SeaState field')
        RETURN
      END IF
      IF (.NOT. external_fluid) THEN
        CALL fail(ErrStat, ErrMsg, 'WaterKin WaveKinMod 2/SEASTATE requires external_fluid from the coupled host')
        RETURN
      END IF
    END IF

    IF (PRESENT(external_fluid)) THEN
      IF (external_fluid) THEN
        ! Host-driven fields and deck-declared ambient models would double-count.
        IF (opts%has_wave) THEN
          CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: the host prescribes the ambient fluid '// &
                    '(external_fluid); remove the deck waves OPTION (double-counting)'); RETURN
        END IF
        IF (opts%has_current .OR. opts%has_current_profile) THEN
          IF (.NOT. (opts%waterkin_current_mode == 1 .AND. &
                     .NOT. opts%waterkin_host_current .AND. opts%has_current_profile)) THEN
            CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: the host prescribes the ambient fluid '// &
                      '(external_fluid); remove the deck current OPTION (double-counting)'); RETURN
          END IF
        END IF
        opts%external_fluid = .TRUE.
        IF (opts%has_waterkin_file .OR. opts%waterkin_seastate) THEN
          agg%host_wave_enabled = opts%waterkin_host_wave
          agg%host_current_enabled = opts%waterkin_host_current
          IF (opts%waterkin_current_mode == 1 .AND. opts%has_current_profile .AND. &
              .NOT. opts%waterkin_host_current) THEN
            agg%host_current_profile_z = opts%current_profile_z
            agg%host_current_profile_velocity = opts%current_profile_velocity
          END IF
        ELSE
          agg%host_wave_enabled = .TRUE.
          agg%host_current_enabled = .TRUE.
        END IF
      END IF
    END IF
    IF (PRESENT(forbid_deck_ambient)) THEN
      IF (forbid_deck_ambient) THEN
        IF (opts%has_wave) THEN
          CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: this coupled mode runs the mooring in '// &
                    'STILL WATER (no ambient fluid field covers the mooring span); remove the deck '// &
                    'waves OPTION'); RETURN
        END IF
        IF (opts%has_current .OR. opts%has_current_profile) THEN
          CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: this coupled mode runs the mooring in '// &
                    'STILL WATER (no ambient fluid field covers the mooring span); remove the deck '// &
                    'current OPTION'); RETURN
        END IF
      END IF
    END IF
    ! Nothing on the aggregate route evaluates deck waves: the fluid fields are refreshed
    ! only by the host (external_fluid). A waves OPTION that reached this point (no
    ! external_fluid and no still-water flag) would otherwise run with zero wave kinematics.
    ! A deck current is different: it is steady and is applied through the line models.
    IF (opts%has_wave) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: deck waves are not evaluated on the coupled '// &
                'aggregate route (the host supplies wave kinematics, e.g. OpenFAST SeaState through '// &
                'WaterKin WaveKinMod 2); remove the deck waves OPTION'); RETURN
    END IF
    agg%gravity = opts%g
    agg%rho_water = opts%rhoW
    ! point3 buoys ARE supported on the coupled facade: finalize_and_validate resolves
    ! the point3 BODY's Mass/Vol/CdA/Ca onto its single attachment point (which
    ! deck_point_type_to_system maps to a Free dynamic point), and the aggregate's
    ! init_deck_system_from_parsed carries the volume buoyancy + drag/added-mass and
    ! marches + checkpoint-mirrors the point like any Free/Connect point. rigid6 BODYs
    ! (6-DOF rigid dynamics) and RODs are not composed here -- fail closed by name.
    n_rigid6 = 0
    n_point3 = 0
    DO i = 1, SIZE(bodies)
      SELECT CASE (TRIM(bodies(i)%btype))
      CASE ('point3')
        n_point3 = n_point3 + 1
        ! The aggregate wires the point-fluid contract: a hydro-active buoy (CdA/Ca) becomes a
        ! fluid sampling node, so with a host ambient field (external_fluid) its Morison drag /
        ! Froude-Krylov / added-mass are served (point_environment_force). WITHOUT a host field
        ! (still water) there is nothing to drive them, so a CdA/Ca buoy would silently drop them
        ! -- fail closed in that case. C33/C44/C55 restoring stiffness on a point3 is not
        ! supported and always fails closed. Pure buoyancy (all zero) is served in either case.
        ! use ABS: CdA/Ca are validated non-negative, but C33/C44/C55 are only checked finite, so a
        ! SIGNED (negative) restoring stiffness must trip the restoring guard too.
        IF (ABS(bodies(i)%c33) > CD_ZERO .OR. ABS(bodies(i)%c44) > CD_ZERO .OR. &
            ABS(bodies(i)%c55) > CD_ZERO) THEN
          CALL fail(ErrStat, ErrMsg, 'a coupled point3 with C33/C44/C55 restoring stiffness is not '// &
                    'supported (the aggregate has no point restoring surface); set them to 0'); RETURN
        END IF
        IF ((ABS(bodies(i)%cda) > CD_ZERO .OR. ABS(bodies(i)%ca) > CD_ZERO) .AND. .NOT. opts%external_fluid) THEN
          CALL fail(ErrStat, ErrMsg, 'a coupled point3 with CdA/Ca /= 0 needs a host ambient fluid field '// &
                    '(external_fluid): in still water its Morison drag/added-mass has nothing to act against '// &
                    'and would be dropped -- either add the SeaState field or set CdA = Ca = 0'); RETURN
        END IF
        ! finalize_and_validate only enforces the one-attachment rule while processing an
        ! EXISTING Body<N> point, so a point3 BODY with ZERO referencing points slips past
        ! it -- and the aggregate builds from points/lines only, silently dropping the buoy.
        ! Require exactly one attachment here (the aggregate has no other way to place it).
        IF (count_body_point_refs(points, bodies(i)%id) /= 1) THEN
          CALL fail(ErrStat, ErrMsg, 'a point3 BODY must be referenced by exactly one Body<N> POINT row '// &
                    'on the coupled facade (no attachment point means the buoy is silently dropped)'); RETURN
        END IF
      CASE ('rigid6')
        n_rigid6 = n_rigid6 + 1
        ! Rigid6 6-DOF bodies ARE marched on the coupled aggregate by step_rigid6_system over
        ! the EI=0 system (buoyancy, C33/C44/C55 restoring, seabed, and the line attachment
        ! reactions are all self-contained). The fluid-FIELD-dependent loads (Morison drag +
        ! Froude-Krylov + added-mass) are served BY the fluid contract: with a host ambient field
        ! (external_fluid) the aggregate samples SeaState at the body reference point and holds it
        ! on the body, so CdA/Ca are honoured. WITHOUT a host field (still water, external_fluid =
        ! .FALSE.) there is nothing to drive drag/FK, so a body carrying CdA/Ca would silently drop
        ! them -- fail closed in that case only (restoring is always self-contained, always allowed).
        IF ((ABS(bodies(i)%cda) > CD_ZERO .OR. ABS(bodies(i)%ca) > CD_ZERO) .AND. .NOT. opts%external_fluid) THEN
          CALL fail(ErrStat, ErrMsg, 'a coupled Rigid6 body with CdA/Ca /= 0 needs a host ambient fluid field '// &
                    '(external_fluid): in still water its Morison drag/added-mass has nothing to act against '// &
                    'and would be dropped -- either add the SeaState field or set CdA = Ca = 0'); RETURN
        END IF
        IF (count_body_point_refs(points, bodies(i)%id) < 1) THEN
          CALL fail(ErrStat, ErrMsg, 'a Rigid6 BODY must be referenced by at least one Body<N> POINT row '// &
                    'on the coupled facade (no attachment point means the body is unconnected)'); RETURN
        END IF
      CASE DEFAULT
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate composes point-attached mooring lines, '// &
                  'coupled cables, point3 buoys, and Rigid6 bodies; other BODY types use '// &
                  'CD_Run_Deck_Driver'); RETURN
      END SELECT
    END DO
    ! RODS are marched on the coupled aggregate (the rod twin of the Rigid6 march), scope-validated
    ! below (n_rod block) and built into agg%rod. A rod deck mixed with Rigid6 bodies fails closed
    ! there (the aggregate marches one body/rod family per step).
    n_rod = SIZE(rods)
    n_host_rod = COUNT(rods%rod_type == 'coupled' .OR. rods%rod_type == 'vessel')
    n_host_body = COUNT(bodies%host_coupled)
    IF (opts%has_motion_file) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: the coupled boundary is driven by the host, '// &
                'not a deck motionFile; remove the motionFile OPTION'); RETURN
    END IF
    IF (SIZE(lines) == 0) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: deck defines no lines'); RETURN
    END IF

    ! Partition the lines: a line is a finite-EI (bending) cable iff ANY section has EI > 0.
    ALLOCATE (is_fin(SIZE(lines)))
    n_fin = 0
    DO i = 1, SIZE(lines)
      is_fin(i) = line_is_finite_ei(lines(i), types, sections)
      IF (is_fin(i)) n_fin = n_fin + 1
    END DO
    n_ei0 = SIZE(lines) - n_fin

    ! Aggregate Point channels are evaluated from the EI=0 system point store.
    ! A point attached only to a finite-EI cable has no live entry there, so
    ! accepting its Point<P>p* channel would expose the parse-time position after
    ! the cable starts moving.  Reject that unsupported routing at initialization;
    ! cable motion remains available through its line-node channels.
    CALL validate_aggregate_point_channels(channels, points, lines, is_fin, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN

    ! Coupled Rigid6 scope: pure EI=0 mooring bodies only. step_rigid6_system
    ! REPLACES the mooring step and drives the body attachment points as PRESCRIBED motion
    ! via CD_Step_System, so any OTHER dynamic point that needs the DynamicPoints integrator
    ! (a point3 buoy or a Free/Connect point), a finite-EI cable partition, FAST.Farm mode, or
    ! a non-flat bathymetry is not composed with a body march yet -- fail closed by name.
    IF (n_rigid6 > 0) THEN
      IF (n_fin > 0) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: a coupled Rigid6 body with a finite-EI cable '// &
                  'in the same deck is not supported'); RETURN
      END IF
      IF (nturb > 0) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: coupled Rigid6 bodies in a FAST.Farm deck are '// &
                  'not supported'); RETURN
      END IF
      IF (n_point3 > 0) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: a coupled deck mixing Rigid6 bodies and point3 '// &
                  'buoys is not supported (the body march and the DynamicPoints march are distinct)'); RETURN
      END IF
      IF (opts%has_bathymetry_file) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: a coupled Rigid6 deck requires a flat WtrDpth '// &
                  'seabed (no bathymetryFile)'); RETURN
      END IF
      ! Still water: the coupled boundary injects fluid via SeaState at the LINE nodes, not
      ! to a body reference point, so a deck-declared wave/current would apply a body
      ! Froude-Krylov (rhoW*Vol*fluid_accel, non-zero even at CdA=Ca=0) that the coupled
      ! reality cannot mirror. Keep the body unambiguously fluid-inert -- fail closed.
      IF (opts%has_wave .OR. opts%has_current .OR. opts%has_current_profile) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: a coupled Rigid6 deck runs in STILL WATER '// &
                  '(deck-owned body fluid fields are not supported); remove the deck waves/current OPTION'); RETURN
      END IF
      ! The host-driven ambient fluid path (external_fluid) IS served: the aggregate appends one
      ! fluid sampling node per body (its reference point) to nfluid, so the host samples SeaState
      ! there and CD_AGG_SetFluidFields holds the field on the body (CD_Rigid6_SetHeldFluid). The
      ! body's drag / Froude-Krylov / added-mass then come from that held field consistently with
      ! the lines -- the fluid contract. (Still water keeps external_fluid = .FALSE.; has_held stays
      ! FALSE and the body is bit-for-bit the pure-buoyancy/restoring march.)
      DO i = 1, SIZE(points)
        IF (points(i)%ptype == 'free' .OR. points(i)%ptype == 'connect') THEN
          CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: a coupled Rigid6 deck may not also carry '// &
                    'Free/Connect dynamic points'); RETURN
        END IF
      END DO
      IF (SIZE(fails) > 0) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: line FAILURE on a coupled Rigid6 deck is not '// &
                  'supported (the failure trigger is not evaluated against the post-body-march state)'); RETURN
      END IF
      ! Coupled/Vessel bodies become 6-DOF host nodes. They may share a deck with Free bodies: when
      ! the free-body march sub-cycles, the host-driven bodies follow the host path interpolated
      ! from the step start (interp_host_rigid). The linearization probe places translational
      ! moving points only.
      IF (n_host_body > 0 .AND. PRESENT(coupled_positions)) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: coupled_positions (the linearization probe) '// &
                  'does not support Coupled/Vessel BODIES'); RETURN
      END IF
    END IF

    ! Coupled ROD scope (the rod twin of the Rigid6 scope above): pure EI=0 mooring rods
    ! only. step_rod_system REPLACES the mooring step and drives the rod end points as PRESCRIBED
    ! motion, so a finite-EI cable, FAST.Farm mode, a non-flat bathymetry, a deck-owned ambient fluid
    ! field, another dynamic point, a Rigid6/point3 body, or line FAILURE is not composed with a rod march
    ! yet -- fail closed by name.
    IF (n_rod > 0) THEN
      IF (n_rigid6 > 0 .OR. n_point3 > 0) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: a coupled deck mixing RODs and Rigid6/point3 '// &
                  'bodies is not supported (the aggregate marches one body/rod family per step)'); RETURN
      END IF
      IF (n_fin > 0) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: a coupled ROD with a finite-EI cable in the '// &
                  'same deck is not supported'); RETURN
      END IF
      ! The aggregate rod march integrates Free rods and prescribes Coupled/Vessel ones; any other
      ! rod would be held at its pose, so a Pinned rod (which must turn about its pin) is refused.
      IF (ANY(rods%rod_type == 'pinned')) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: a Pinned ROD is not supported on the coupled '// &
                  'route (the coupled rod march does not turn rods about a pin); use the standalone driver'); RETURN
      END IF
      IF (nturb > 0) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: coupled RODs in a FAST.Farm deck are not '// &
                  'supported'); RETURN
      END IF
      IF (opts%has_bathymetry_file) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: a coupled ROD deck requires a flat WtrDpth '// &
                  'seabed (no bathymetryFile)'); RETURN
      END IF
      IF (opts%has_wave .OR. opts%has_current .OR. opts%has_current_profile) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: a coupled ROD deck runs in STILL WATER '// &
                  '(deck-owned rod fluid fields are not supported); remove the deck waves/current OPTION'); RETURN
      END IF
      DO i = 1, SIZE(points)
        IF (points(i)%ptype == 'free' .OR. points(i)%ptype == 'connect') THEN
          CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: a coupled ROD deck may not also carry '// &
                    'Free/Connect dynamic points'); RETURN
        END IF
      END DO
      IF (SIZE(fails) > 0) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: line FAILURE on a coupled ROD deck is not '// &
                  'supported (the failure trigger is not evaluated against the post-rod-march state)'); RETURN
      END IF
      ! Coupled/Vessel rods become 6-DOF host nodes (End A position + platform orientation). The
      ! linearization probe places translational moving points only, so it cannot carry them.
      IF (n_host_rod > 0 .AND. PRESENT(coupled_positions)) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: coupled_positions (the linearization probe) '// &
                  'does not support Coupled/Vessel RODS'); RETURN
      END IF
    END IF

    ! A deck carrying finite-EI cables is scoped to structural + drag + added-mass cables
    ! and Fixed/Coupled mooring endpoints only. Ambient current / waves reach the
    ! cable through the shared host fluid field, and Free/Connect dynamic
    ! points interact with the cable partition in ways this path does not handle -- fail
    ! closed rather than silently drop the physics. A PURE mooring deck (n_fin == 0) keeps
    ! the full EI=0 feature set so it composes to the plain CD_FMF_Init_From_Deck system.
    IF (n_fin > 0) THEN
      IF (opts%has_current .OR. opts%has_current_profile) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: ambient current on a deck with a finite-EI '// &
                  'cable is not supported (the cable does not receive a deck-owned current)'); RETURN
      END IF
      IF (opts%has_wave) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: wave kinematics on a deck with a finite-EI '// &
                  'cable is not supported (use the shared host wave field)'); RETURN
      END IF
      IF (deck_has_dynamic_points(points)) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: a deck with a finite-EI cable may not also '// &
                  'carry Free/Connect dynamic points'); RETURN
      END IF
    END IF

    ! CONTROL scope in the coupled aggregate: pure EI=0, non-farm decks (the
    ! system wrapper drives the segment update; finite-EI cable control and farm
    ! mode are not supported).
    IF (SIZE(ctrls) > 0) THEN
      IF (nturb > 0) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: CONTROL on a FAST.Farm deck is not supported'); RETURN
      END IF
      IF (n_fin > 0) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: CONTROL on a deck with finite-EI cables is '// &
                  'not supported'); RETURN
      END IF
    END IF

    ! FAILURE scope in the coupled aggregate: pure EI=0, non-farm, frictionless
    ! decks only (the same class the standalone march supports).
    IF (SIZE(fails) > 0) THEN
      IF (nturb > 0) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: FAILURE on a FAST.Farm deck is not supported'); RETURN
      END IF
      IF (n_fin > 0) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: FAILURE on a deck with finite-EI cables is '// &
                  'not supported'); RETURN
      END IF
      IF (opts%has_friction) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: FAILURE deck does not support seabed friction '// &
                  '(the dynamic-point rule)'); RETURN
      END IF
    END IF

    IF (PRESENT(coupled_positions)) THEN
      CALL apply_coupled_positions(points, lines, is_fin, coupled_positions, ptfm_init, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL revalidate_ptfm_points(points, lines, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END IF

    ! Free Rigid6 bodies and free rods start at their static equilibrium with the host's coupled
    ! points held at their initial (PtfmInit) pose, as on the standalone route (bodyIC static;
    ! bodyIC deck keeps the deck pose). The solve moves the bodies' start pose and the rod and
    ! attachment points before the system is built on them.
    IF ((n_rigid6 > 0 .OR. n_rod > 0) .AND. opts%body_ic_static) THEN
      IF (opts%has_bathymetry_file) THEN
        CALL load_bathymetry_file(path_join(deck_dir(deck_path), opts%bathymetry_file), bathymetry, ErrStat, ErrMsg, &
                                  points=points)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        CALL solve_body_equilibrium(types, bodies, rod_types, rods, points, lines, sections, opts, ErrStat, ErrMsg, &
                                    bathymetry=bathymetry)
        CALL CD_End_Bathymetry(bathymetry)
      ELSE
        CALL solve_body_equilibrium(types, bodies, rod_types, rods, points, lines, sections, opts, ErrStat, ErrMsg)
      END IF
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        ErrMsg = 'CD_Init_Deck_Aggregate: '//TRIM(ErrMsg)
        RETURN
      END IF
    END IF

    ! Build the EI=0 mooring system from the EI=0 line subset over ALL points. The finite-EI
    ! cable endpoints are Fixed/Coupled points bound to no EI=0 line, so the point-coupled map
    ! skips them (they are not Free/Connect, which would be rejected) and CD_Get_System_PointBlocks
    ! excludes them from the moving surface -- no double count. This is exactly the call
    ! CD_Init_Deck_System makes internally, so a pure-mooring deck (all lines EI=0) yields a
    ! system bit-for-bit identical to CD_FMF_Init_From_Deck's.
    IF (n_ei0 > 0) THEN
      ALLOCATE (ei0_lines(n_ei0))
      c = 0
      DO i = 1, SIZE(lines)
        IF (.NOT. is_fin(i)) THEN
          c = c + 1
          ei0_lines(c) = lines(i)
        END IF
      END DO
      IF (opts%has_bathymetry_file) THEN
        CALL load_bathymetry_file(path_join(deck_dir(deck_path), opts%bathymetry_file), bathymetry, ErrStat, ErrMsg, &
                                  points=points)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        CALL init_deck_system_from_parsed(types, points, ei0_lines, sections, opts, agg%sys, ErrStat, ErrMsg, &
                                          bathymetry=bathymetry, failures=fails)
        CALL CD_End_Bathymetry(bathymetry)
      ELSE
        CALL init_deck_system_from_parsed(types, points, ei0_lines, sections, opts, agg%sys, ErrStat, ErrMsg, &
                                          failures=fails)
      END IF
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        CALL CD_End_Deck_Aggregate(agg); RETURN
      END IF
      agg%has_sys = .TRUE.
    END IF
    ! Coupled Rigid6 runtime: build the body states + retain the deck options/points the
    ! per-step marcher needs (scope validated above -- pure EI=0, non-farm; CdA/Ca only with a
    ! host fluid field).
    IF (n_rigid6 > 0) THEN
      IF (PRESENT(ptfm_init)) THEN
        CALL CD_Init_Deck_Aggregate_Rigid6(bodies, points, opts, agg%rigid6, ErrStat, ErrMsg, ptfm_init=ptfm_init)
      ELSE
        CALL CD_Init_Deck_Aggregate_Rigid6(bodies, points, opts, agg%rigid6, ErrStat, ErrMsg)
      END IF
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        CALL CD_End_Deck_Aggregate(agg); RETURN
      END IF
      agg%has_rigid6 = .TRUE.
    END IF
    ! Coupled ROD runtime: build the rod states + retain the deck options/points the per-step
    ! marcher needs (scope validated above -- pure EI=0, non-farm, still water).
    IF (n_rod > 0) THEN
      CALL CD_Init_Deck_Aggregate_Rod(rod_types, rods, points, opts, agg%rod, ErrStat, ErrMsg, host_dcm=host_dcm)
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        CALL CD_End_Deck_Aggregate(agg); RETURN
      END IF
      agg%has_rod = .TRUE.
    END IF
    ! FAILURE runtime table: rows + the deck lines/points the trigger consumes (the
    ! failure scope above guarantees ei0_lines == lines, so deck line ids resolve
    ! to system line indices by array position exactly as the standalone march).
    IF (SIZE(fails) > 0) THEN
      CALL MOVE_ALLOC(fails, agg%failures)
      agg%fail_lines = lines
      agg%fail_points = points
    END IF
    ! CONTROL runtime table: flatten channel -> (system line, last element, base
    ! length). The scope above guarantees a pure EI=0 deck, so deck line ids
    ! resolve to system line indices by array position.
    IF (SIZE(ctrls) > 0) THEN
      nctrl_lines = 0
      DO i = 1, SIZE(ctrls)
        nctrl_lines = nctrl_lines + SIZE(ctrls(i)%line_ids)
        agg%n_ctrl_chans = MAX(agg%n_ctrl_chans, ctrls(i)%channel)
      END DO
      ALLOCATE (agg%ctrl_chan(nctrl_lines), agg%ctrl_line(nctrl_lines), agg%ctrl_elem(nctrl_lines), &
                agg%ctrl_base_l0(nctrl_lines))
      c = 0
      DO i = 1, SIZE(ctrls)
        DO k = 1, SIZE(ctrls(i)%line_ids)
          c = c + 1
          agg%ctrl_chan(c) = ctrls(i)%channel
          agg%ctrl_line(c) = 0
          DO j = 1, SIZE(lines)
            IF (lines(j)%id == ctrls(i)%line_ids(k)) agg%ctrl_line(c) = j
          END DO
          IF (agg%ctrl_line(c) < 1) THEN
            CALL fail(ErrStat, ErrMsg, 'CONTROL references a line the aggregate did not initialize')
            CALL CD_End_Deck_Aggregate(agg); RETURN
          END IF
          ! Fairlead element + base length from the BUILT model, never re-derived
          ! from the deck sections: the mesh builder reverses element order for
          ! anchor_is_end_b lines, so on a composite line a sections-scan picks the
          ! ANCHOR-side segment and a zero command would rewrite the fairlead
          ! segment to the wrong length. The built l0 is the single truth.
          ne_line = SIZE(agg%sys%lines(agg%ctrl_line(c))%l0)
          IF (ne_line < 1) THEN
            CALL fail(ErrStat, ErrMsg, 'CONTROL line has no elements')
            CALL CD_End_Deck_Aggregate(agg); RETURN
          END IF
          agg%ctrl_elem(c) = ne_line
          agg%ctrl_base_l0(c) = agg%sys%lines(agg%ctrl_line(c))%l0(ne_line)
          ! Update capability is an INIT-time property: verify it here so the apply
          ! loop can never fail for input reasons after its prevalidation (a mid-loop
          ! failure would leave mixed lengths). The deck path always supplies the
          ! seabed recompute inputs; this protects any future builder that does not.
          IF (agg%sys%lines(agg%ctrl_line(c))%has_seabed .AND. &
              .NOT. agg%sys%lines(agg%ctrl_line(c))%has_seabed_recompute) THEN
            CALL fail(ErrStat, ErrMsg, 'CONTROL line was built without the seabed recompute inputs')
            CALL CD_End_Deck_Aggregate(agg); RETURN
          END IF
          IF (agg%sys%lines(agg%ctrl_line(c))%has_viscoelastic) THEN
            IF (agg%sys%lines(agg%ctrl_line(c))%ve_mode(ne_line) /= 0) THEN
              ! same INIT-time rule: the runtime length update fails closed on a
              ! viscoelastic element (the dl_1 state has no rescaling law), so a
              ! deck composing CONTROL with a viscoelastic fairlead segment must
              ! not start at all
              CALL fail(ErrStat, ErrMsg, 'CONTROL targets a viscoelastic (ElasticMod 2) fairlead '// &
                        'segment; active line control is not supported on the viscoelastic model')
              CALL CD_End_Deck_Aggregate(agg); RETURN
            END IF
          END IF
        END DO
      END DO
    END IF

    ! Build one coupled Hermite cable per finite-EI line (the production bending path). Each
    ! cable owns its own static-seeded dynamic model and its coupled fairlead node.
    IF (n_fin > 0) THEN
      IF (opts%has_bathymetry_file) THEN
        CALL load_bathymetry_file(path_join(deck_dir(deck_path), opts%bathymetry_file), bathymetry, ErrStat, ErrMsg, &
                                  points=points)
        IF (ErrStat /= CD_DECKDRV_OK) THEN
          CALL CD_End_Deck_Aggregate(agg); RETURN
        END IF
      END IF
      ALLOCATE (agg%cables(n_fin), agg%cable_note(n_fin), agg%cable_points(2, n_fin))
      agg%cable_note = ''
      c = 0
      DO i = 1, SIZE(lines)
        IF (is_fin(i)) THEN
          c = c + 1
          agg%cable_points(:, c) = [lines(i)%nodeA, lines(i)%nodeB]
          fairlead_dcm = CD_ZERO
          fairlead_dcm(1, 1) = CD_ONE
          fairlead_dcm(2, 2) = CD_ONE
          fairlead_dcm(3, 3) = CD_ONE
          IF (nturb > 0 .AND. PRESENT(farm_ptfm_init)) THEN
            j = find_point(points, lines(i)%nodeA)
            IF (j > 0 .AND. points(j)%turbine_id > 0) &
              fairlead_dcm = ptfm_zyx_dcm(farm_ptfm_init(4:6, points(j)%turbine_id))
          ELSE IF (PRESENT(ptfm_init)) THEN
            fairlead_dcm = ptfm_zyx_dcm(ptfm_init(4:6))
          END IF
          IF (opts%has_bathymetry_file) THEN
            CALL build_one_hermite_cable(lines(i), sections, types, points, opts, dt, agg%cables(c), cn, es, em, &
                                         bathymetry=bathymetry, fairlead_orientation=fairlead_dcm, &
                                         init_note=agg%cable_note(c))
          ELSE
            CALL build_one_hermite_cable(lines(i), sections, types, points, opts, dt, agg%cables(c), cn, es, em, &
                                         fairlead_orientation=fairlead_dcm, init_note=agg%cable_note(c))
          END IF
          IF (es /= CD_DECKDRV_OK) THEN
            ErrStat = es
            ErrMsg = em
            IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
            CALL CD_End_Deck_Aggregate(agg); RETURN
          END IF
        END IF
      END DO
      IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
    END IF

    ! Retain the deck OUTPUTS channels and always build the deck-line-id -> object map. The
    ! map is also the authoritative line inventory for the coupled static profile, which is
    ! written even when the deck intentionally declares no time-history OUTPUTS channels.
    ! The OpenFAST shell uses the same map to emit CableDyn's OrcaFlex-vocabulary channels. The
    ! channels arriving here are already validated: parse_deck -> finalize_and_validate ->
    ! check_channel rejected any unknown token / out-of-range line-node before this point.
    ! Populate the channel store only when the deck declares channels (p%NumOuts remains zero
    ! otherwise); the small integer/logical map is retained independently of that selection.
    IF (SIZE(channels) > 0) THEN
      ALLOCATE (agg%channels(SIZE(channels)))
      agg%channels(:) = channels(:)
    END IF
    CALL build_line_object_map(lines, is_fin, agg%line_is_cable, agg%line_obj_index, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CALL CD_End_Deck_Aggregate(agg); RETURN
    END IF
    agg%n_lines = SIZE(lines)
    agg%n_points = SIZE(points)
    agg%n_sections = SIZE(sections)
    agg%n_ei0_lines = n_ei0
    agg%n_finite_ei_lines = n_fin
    CALL collect_aggregate_init_summaries(lines, agg, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CALL CD_End_Deck_Aggregate(agg); RETURN
    END IF

    ! Per moving slot, the driving turbine (0 outside farm mode) -- the SAME
    ! enumeration the coupled_positions override uses: the system's BOUND
    ! Coupled/Vessel points in deck POINT order, then one coupled fairlead per
    ! finite-EI cable in deck LINE order. Consumed by the OpenFAST shell to build
    ! its per-turbine meshes over the flat aggregate moving surface.
    CALL fill_turbine_of_moving(points, lines, is_fin, agg, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CALL CD_End_Deck_Aggregate(agg); RETURN
    END IF

    ! Range graphs and touchdown channels: fix the TDP references at the converged state.
    BLOCK
      LOGICAL :: files_ok, wants_range, wants_tdp
      TYPE(CD_HFMF_ModuleType) :: no_cables(0)
      files_ok = .FALSE.
      IF (PRESENT(range_files)) files_ok = range_files
      wants_range = ANY([(line_output_has_flag(lines(i)%outputs, 'r'), i=1, SIZE(lines))])
      wants_tdp = ANY([(CD_Is_TDP_Channel(to_lower(channels(i))), i=1, SIZE(channels))])
      IF (wants_range .AND. .NOT. files_ok) THEN
        CALL fail(ErrStat, ErrMsg, 'the LINES Outputs flag r (range graph) is written by the standalone driver; '// &
                  'a coupled run reports TDP<L> and node channels instead')
        CALL CD_End_Deck_Aggregate(agg); RETURN
      END IF
      IF (wants_range .OR. wants_tdp) THEN
        IF (opts%has_bathymetry_file) THEN
          CALL load_bathymetry_file(path_join(deck_dir(deck_path), opts%bathymetry_file), bathymetry, ErrStat, &
                                    ErrMsg)
          IF (ErrStat /= CD_DECKDRV_OK) THEN
            CALL CD_End_Deck_Aggregate(agg); RETURN
          END IF
        END IF
        IF (ALLOCATED(agg%cables)) THEN
          CALL range_setup_aggregate(agg%ranges, lines, channels, opts, agg%has_sys, agg%sys, agg%cables, &
                                     agg%line_is_cable, agg%line_obj_index, ErrStat, ErrMsg, bathymetry)
        ELSE
          CALL range_setup_aggregate(agg%ranges, lines, channels, opts, agg%has_sys, agg%sys, no_cables, &
                                     agg%line_is_cable, agg%line_obj_index, ErrStat, ErrMsg, bathymetry)
        END IF
        IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
        IF (ErrStat /= CD_DECKDRV_OK) THEN
          CALL CD_End_Deck_Aggregate(agg); RETURN
        END IF
      END IF
    END BLOCK
  END SUBROUTINE CD_Init_Deck_Aggregate

  SUBROUTINE validate_aggregate_point_channels(channels, points, lines, is_fin, ErrStat, ErrMsg)
    CHARACTER(*), INTENT(IN) :: channels(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    LOGICAL, INTENT(IN) :: is_fin(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i, l, pidx, comp
    LOGICAL :: attached_to_cable, served_by_system

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    DO i = 1, SIZE(channels)
      IF (.NOT. is_point_channel(to_lower(channels(i)))) CYCLE
      ! Point<P>F sums the line and cable end forces, which every route evaluates live
      IF (is_point_force_channel(to_lower(channels(i)))) CYCLE
      CALL parse_point_channel(channels(i), pidx, comp)
      attached_to_cable = .FALSE.
      served_by_system = .FALSE.
      DO l = 1, SIZE(lines)
        IF (lines(l)%nodea == pidx .OR. lines(l)%nodeb == pidx) THEN
          IF (is_fin(l)) THEN
            attached_to_cable = .TRUE.
          ELSE
            served_by_system = .TRUE.
          END IF
        END IF
      END DO
      ! A fixed cable endpoint is copied into the system store but never moves,
      ! so its parse-time position remains exact.  Only a host-driven cable-only
      ! point would become stale there during a coupled march.
      ! Nested tests: Fortran does not short-circuit .AND., and point_index returns 0
      ! for a point id that no line references.
      IF (attached_to_cable .AND. .NOT. served_by_system) THEN
        IF (point_index(points, pidx) > 0) THEN
          IF (TRIM(points(point_index(points, pidx))%ptype) == 'coupled' .OR. &
              TRIM(points(point_index(points, pidx))%ptype) == 'vessel') THEN
            CALL fail(ErrStat, ErrMsg, 'aggregate OUTPUT "'//TRIM(channels(i))//'" targets a cable-only point; '// &
                      'use the finite-EI cable line-node position channel instead')
            RETURN
          END IF
        END IF
      END IF
    END DO
  END SUBROUTINE validate_aggregate_point_channels

  SUBROUTINE fill_turbine_of_moving(points, lines, is_fin, agg, ErrStat, ErrMsg)
    !! Record, per aggregate moving slot, the turbine that drives it (0 = plain mode).
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    LOGICAL, INTENT(IN) :: is_fin(:)
    TYPE(CD_DeckAggregateType), INTENT(INOUT) :: agg
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i, l, n, istat
    LOGICAL :: bound_ei0

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    n = 0
    DO i = 1, SIZE(points)
      SELECT CASE (TRIM(points(i)%ptype))
      CASE ('coupled', 'vessel')
        bound_ei0 = .FALSE.
        DO l = 1, SIZE(lines)
          IF (is_fin(l)) CYCLE
          IF (lines(l)%nodeA == points(i)%id .OR. lines(l)%nodeB == points(i)%id) THEN
            bound_ei0 = .TRUE.; EXIT
          END IF
        END DO
        IF (bound_ei0) n = n + 1
      END SELECT
    END DO
    DO l = 1, SIZE(lines)
      IF (is_fin(l)) n = n + 1
    END DO
    ALLOCATE (agg%turbine_of_moving(n), STAT=istat)
    IF (istat /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'could not allocate the turbine-of-moving map'); RETURN
    END IF
    agg%turbine_of_moving = 0
    n = 0
    DO i = 1, SIZE(points)
      SELECT CASE (TRIM(points(i)%ptype))
      CASE ('coupled', 'vessel')
        bound_ei0 = .FALSE.
        DO l = 1, SIZE(lines)
          IF (is_fin(l)) CYCLE
          IF (lines(l)%nodeA == points(i)%id .OR. lines(l)%nodeB == points(i)%id) THEN
            bound_ei0 = .TRUE.; EXIT
          END IF
        END DO
        IF (bound_ei0) THEN
          n = n + 1
          agg%turbine_of_moving(n) = points(i)%turbine_id
        END IF
      END SELECT
    END DO
    DO l = 1, SIZE(lines)
      IF (.NOT. is_fin(l)) CYCLE
      n = n + 1
      DO i = 1, SIZE(points)
        IF (points(i)%id /= lines(l)%nodeA .AND. points(i)%id /= lines(l)%nodeB) CYCLE
        SELECT CASE (TRIM(points(i)%ptype))
        CASE ('coupled', 'vessel')
          agg%turbine_of_moving(n) = points(i)%turbine_id
        END SELECT
      END DO
    END DO
  END SUBROUTINE fill_turbine_of_moving

  SUBROUTINE CD_Deck_Query_dtM(deck_path, dtM, has_dtm, ErrStat, ErrMsg, env_gravity, env_rho_water, env_wtrdpth, &
                               tmax, has_tmax, n_ei0, n_finite_ei, has_motion_file, standalone_scan, has_line_outputs, &
                               input_files, has_objects, n_bodies_rods)
    !! Report lightweight deck run metadata without building anything. The entry is
    !! named for dtM because OpenFAST uses it to choose its module time step before
    !! aggregate initialization.
    !!
    !! By default this is a caller-driven scan: a coupled host must choose the module
    !! step BEFORE initializing the aggregate (whose
    !! dt freezes at Init), and the deck's declared dtM is the author's intent. Runs the
    !! SAME parser as the build entries (never a second scanner that could drift from the
    !! deck spec), under the same caller-driven + host-environment contract. Set
    !! standalone_scan=.TRUE. only for the executable's pre-dispatch scan; that applies
    !! the standalone parser gates and rejects FAST.Farm-only Turbine<J> vocabulary.
    !! has_dtm is .FALSE. (and dtM = 0) when the deck does not declare one.
    !! input_files: every auxiliary file the deck makes the run read (motionFile,
    !! bathymetryFile, WaterKin and its WaveKinFile, Syrope settings and OWC tables),
    !! as resolved against the deck directory; the executable keeps its outputs off them.
    !! has_objects: the deck has BODIES, RODS or Free/Connect points (the multibody march).
    !! n_bodies_rods: the number of BODIES plus RODS rows.
    CHARACTER(*), INTENT(IN) :: deck_path
    CHARACTER(CD_DECK_PATHLEN), ALLOCATABLE, INTENT(OUT), OPTIONAL :: input_files(:)
    REAL(wp), INTENT(OUT) :: dtM
    LOGICAL, INTENT(OUT) :: has_dtm
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp), INTENT(IN), OPTIONAL :: env_gravity, env_rho_water, env_wtrdpth
    REAL(wp), INTENT(OUT), OPTIONAL :: tmax
    LOGICAL, INTENT(OUT), OPTIONAL :: has_tmax, has_motion_file, has_line_outputs, has_objects
    INTEGER, INTENT(OUT), OPTIONAL :: n_ei0, n_finite_ei, n_bodies_rods
    LOGICAL, INTENT(IN), OPTIONAL :: standalone_scan

    TYPE(DeckLineType), ALLOCATABLE :: types(:)
    TYPE(DeckBody), ALLOCATABLE :: bodies(:)
    TYPE(DeckRodType), ALLOCATABLE :: rod_types(:)
    TYPE(DeckRod), ALLOCATABLE :: rods(:)
    TYPE(DeckPoint), ALLOCATABLE :: points(:)
    TYPE(DeckLine), ALLOCATABLE :: lines(:)
    TYPE(DeckSection), ALLOCATABLE :: sections(:)
    TYPE(DeckOptions) :: opts
    CHARACTER(NAMELEN), ALLOCATABLE :: channels(:)
    TYPE(DeckFailure), ALLOCATABLE :: fails(:)
    TYPE(DeckControl), ALLOCATABLE :: ctrls(:)

    INTEGER :: i, nei0_local, nfinite_local
    LOGICAL :: scan_standalone

    dtM = CD_ZERO
    has_dtm = .FALSE.
    IF (PRESENT(tmax)) tmax = CD_ZERO
    IF (PRESENT(has_tmax)) has_tmax = .FALSE.
    IF (PRESENT(has_motion_file)) has_motion_file = .FALSE.
    IF (PRESENT(has_line_outputs)) has_line_outputs = .FALSE.
    IF (PRESENT(has_objects)) has_objects = .FALSE.
    IF (PRESENT(n_bodies_rods)) n_bodies_rods = 0
    IF (PRESENT(n_ei0)) n_ei0 = 0
    IF (PRESENT(n_finite_ei)) n_finite_ei = 0
    scan_standalone = .FALSE.
    IF (PRESENT(standalone_scan)) scan_standalone = standalone_scan
    ! Metadata-only scan: it never builds or solves, so the default FAST.Farm
    ! Turbine<J> vocabulary is allowed here -- the OpenFAST shell queries dtM BEFORE the
    ! farm-capable aggregate init, and rejecting the vocabulary at the scan would abort
    ! valid farm decks before their consumer ever sees them. The same rule covers the
    ! FAILURE and CONTROL sections: the scan RECEIVES (and discards) them so a deck the
    ! downstream aggregate supports is never aborted here; the aggregate init re-parses
    ! and is the consuming entry the fail-closed contract protects.
    CALL parse_deck(deck_path, types, bodies, rod_types, rods, points, lines, sections, opts, channels, &
                    ErrStat, ErrMsg, caller_driven=.NOT. scan_standalone, env_gravity=env_gravity, &
                    env_rho_water=env_rho_water, env_wtrdpth=env_wtrdpth, &
                    allow_turbine=.NOT. scan_standalone, &
                    failures=fails, controls=ctrls, allow_static_finite_ei=scan_standalone, &
                    host_coupled_objects=.NOT. scan_standalone)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    IF (PRESENT(n_bodies_rods)) n_bodies_rods = SIZE(bodies) + SIZE(rods)
    has_dtm = opts%has_dtm
    IF (has_dtm) dtM = opts%dtM
    IF (PRESENT(has_tmax)) has_tmax = opts%has_tmax
    IF (PRESENT(tmax)) THEN
      IF (opts%has_tmax) tmax = opts%tmax
    END IF
    IF (PRESENT(has_motion_file)) has_motion_file = opts%has_motion_file
    IF (PRESENT(has_line_outputs)) has_line_outputs = any_line_outputs_requested(lines)
    IF (PRESENT(has_objects)) THEN
      has_objects = SIZE(bodies) > 0 .OR. SIZE(rods) > 0
      DO i = 1, SIZE(points)
        IF (TRIM(points(i)%ptype) == 'free' .OR. TRIM(points(i)%ptype) == 'connect') has_objects = .TRUE.
      END DO
    END IF
    nei0_local = 0
    nfinite_local = 0
    DO i = 1, SIZE(lines)
      IF (line_is_finite_ei(lines(i), types, sections)) THEN
        nfinite_local = nfinite_local + 1
      ELSE
        nei0_local = nei0_local + 1
      END IF
    END DO
    IF (PRESENT(n_ei0)) n_ei0 = nei0_local
    IF (PRESENT(n_finite_ei)) n_finite_ei = nfinite_local
    IF (PRESENT(input_files)) THEN
      ALLOCATE (input_files(0))
      IF (opts%has_motion_file) input_files = [input_files, opts%motion_file]
      IF (opts%has_bathymetry_file) &
        input_files = [CHARACTER(CD_DECK_PATHLEN) :: input_files, path_join(deck_dir(deck_path), opts%bathymetry_file)]
      IF (opts%has_waterkin_file) &
        input_files = [CHARACTER(CD_DECK_PATHLEN) :: input_files, path_join(deck_dir(deck_path), opts%waterkin_file)]
      IF (LEN_TRIM(opts%waterkin_wave_file) > 0) input_files = [input_files, opts%waterkin_wave_file]
      DO i = 1, SIZE(types)
        IF (.NOT. types(i)%is_syrope) CYCLE
        input_files = [CHARACTER(CD_DECK_PATHLEN) :: input_files, &
                       path_join(deck_dir(deck_path), TRIM(types(i)%syrope_file)), types(i)%syrope_owc_file]
      END DO
    END IF
  END SUBROUTINE CD_Deck_Query_dtM

  SUBROUTINE build_line_object_map(lines, is_fin, is_cable, obj_index, ErrStat, ErrMsg)
    !! Build the deck-line-id -> object map indexed directly by deck line id. A line is either
    !! an EI=0 system line (is_cable = .FALSE., obj_index = its rank among EI=0 lines = the
    !! CD_FMF/CD_System line index) or a finite-EI cable (is_cable = .TRUE., obj_index = its
    !! rank among finite-EI lines = the aggregate cable index). The ranks are assigned in deck
    !! order, EXACTLY matching how CD_Init_Deck_Aggregate builds the EI=0 system (from ei0_lines
    !! in deck order) and the cables (agg%cables(c) in deck order), so a resolved index addresses
    !! the correct object. obj_index = 0 marks a deck line id that no LINE defines.
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    LOGICAL, INTENT(IN) :: is_fin(:)
    LOGICAL, ALLOCATABLE, INTENT(OUT) :: is_cable(:)
    INTEGER, ALLOCATABLE, INTENT(OUT) :: obj_index(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: i, maxid, s_count, c_count

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    maxid = 0
    DO i = 1, SIZE(lines)
      IF (lines(i)%id < 1) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Init_Deck_Aggregate: a LINE has a non-positive id; the output '// &
                  'channel map is indexed by deck line id'); RETURN
      END IF
      maxid = MAX(maxid, lines(i)%id)
    END DO
    ALLOCATE (is_cable(maxid), obj_index(maxid))
    is_cable = .FALSE.
    obj_index = 0
    s_count = 0
    c_count = 0
    DO i = 1, SIZE(lines)
      IF (is_fin(i)) THEN
        c_count = c_count + 1
        is_cable(lines(i)%id) = .TRUE.
        obj_index(lines(i)%id) = c_count
      ELSE
        s_count = s_count + 1
        obj_index(lines(i)%id) = s_count
      END IF
    END DO
  END SUBROUTINE build_line_object_map

  SUBROUTINE CD_End_Deck_Aggregate(agg)
    !! Release a deck-aggregate bundle. Idempotent. The OpenFAST facade calls this after it
    !! has wrapped `sys` into its CD_FMF (a deep copy) and MOVE_ALLOCed `cables` out -- so a
    !! normal hand-off ends only the now-redundant `sys` copy, while a failed build ends
    !! whatever partial parts were allocated. No leak, no double free (MOVE_ALLOC leaves
    !! `cables` deallocated here).
    TYPE(CD_DeckAggregateType), INTENT(INOUT) :: agg
    INTEGER :: c, es
    CHARACTER(240) :: em
    IF (agg%has_sys) CALL CD_End_System(agg%sys, es, em)
    agg%has_sys = .FALSE.
    agg%n_turbines = 0
    agg%host_wave_enabled = .FALSE.
    agg%host_current_enabled = .FALSE.
    agg%cable_load_feedback = .TRUE.
    agg%max_strain = 0.5_wp
    IF (ALLOCATED(agg%host_current_profile_z)) DEALLOCATE (agg%host_current_profile_z)
    IF (ALLOCATED(agg%host_current_profile_velocity)) DEALLOCATE (agg%host_current_profile_velocity)
    IF (ALLOCATED(agg%turbine_of_moving)) DEALLOCATE (agg%turbine_of_moving)
    IF (ALLOCATED(agg%init_lines)) DEALLOCATE (agg%init_lines)
    agg%n_lines = 0
    agg%n_points = 0
    agg%n_sections = 0
    agg%n_ei0_lines = 0
    agg%n_finite_ei_lines = 0
    IF (ALLOCATED(agg%cables)) THEN
      DO c = 1, SIZE(agg%cables)
        CALL CD_HFMF_End(agg%cables(c))
      END DO
      DEALLOCATE (agg%cables)
    END IF
    IF (ALLOCATED(agg%cable_note)) DEALLOCATE (agg%cable_note)
    IF (ALLOCATED(agg%cable_points)) DEALLOCATE (agg%cable_points)
    IF (ALLOCATED(agg%channels)) DEALLOCATE (agg%channels)
    IF (ALLOCATED(agg%line_is_cable)) DEALLOCATE (agg%line_is_cable)
    IF (ALLOCATED(agg%line_obj_index)) DEALLOCATE (agg%line_obj_index)
    IF (ALLOCATED(agg%failures)) DEALLOCATE (agg%failures)
    IF (ALLOCATED(agg%fail_lines)) DEALLOCATE (agg%fail_lines)
    IF (ALLOCATED(agg%fail_points)) DEALLOCATE (agg%fail_points)
    agg%n_ctrl_chans = 0
    IF (ALLOCATED(agg%ctrl_chan)) DEALLOCATE (agg%ctrl_chan)
    IF (ALLOCATED(agg%ctrl_line)) DEALLOCATE (agg%ctrl_line)
    IF (ALLOCATED(agg%ctrl_elem)) DEALLOCATE (agg%ctrl_elem)
    IF (ALLOCATED(agg%ctrl_base_l0)) DEALLOCATE (agg%ctrl_base_l0)
    ! Release the Rigid6 runtime and clear the flag: without this a REUSED bundle (or a
    ! failed re-init that routes through here) would keep a stale has_rigid6 = .TRUE. and the
    ! previous deck's body allocatables, so a later non-Rigid6 deck could march a stale body.
    CALL CD_Rigid6_End(agg%rigid6)
    agg%has_rigid6 = .FALSE.
    CALL CD_Rod_End(agg%rod)
    agg%has_rod = .FALSE.
    CALL CD_Range_End(agg%ranges)
    agg%gravity = CD_ZERO
    agg%rho_water = CD_ZERO
  END SUBROUTINE CD_End_Deck_Aggregate

  SUBROUTINE CD_Run_Deck_Driver(deck_path, out_root, converged, ErrStat, ErrMsg)
    !! Parse a MoorDyn-style deck, run static IC and optional held-end dynamic march,
    !! write `<out_root>.out`.
    CHARACTER(*), INTENT(IN)  :: deck_path, out_root
    LOGICAL, INTENT(OUT) :: converged
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    CALL run_deck_driver(deck_path, out_root, converged, ErrStat, ErrMsg)
    ! the verification probe serves one run, whichever route it took and however it ended
    probe_armed = .FALSE.
  END SUBROUTINE CD_Run_Deck_Driver

  SUBROUTINE run_deck_driver(deck_path, out_root, converged, ErrStat, ErrMsg)
    !! CD_Run_Deck_Driver's body.
    CHARACTER(*), INTENT(IN)  :: deck_path, out_root
    LOGICAL, INTENT(OUT) :: converged
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    TYPE(DeckLineType), ALLOCATABLE :: types(:)
    TYPE(DeckBody), ALLOCATABLE :: bodies(:)
    TYPE(DeckRodType), ALLOCATABLE :: rod_types(:)
    TYPE(DeckRod), ALLOCATABLE :: rods(:)
    TYPE(DeckPoint), ALLOCATABLE :: points(:)
    TYPE(DeckLine), ALLOCATABLE :: lines(:)
    TYPE(DeckSection), ALLOCATABLE :: sections(:)
    TYPE(DeckOptions) :: opts
    CHARACTER(NAMELEN), ALLOCATABLE :: channels(:)
    REAL(wp), ALLOCATABLE :: q_all(:), ten_all(:), end_all(:, :), end_vec(:, :, :)
    INTEGER, ALLOCATABLE :: q_off(:), ten_off(:), nn(:), ne(:)
    CHARACTER(512) :: fail_msg
    TYPE(CD_ModelType), ALLOCATABLE :: models(:)
    TYPE(FiniteDeckModel), ALLOCATABLE :: finite_models(:)
    TYPE(CD_HFMF_ModuleType), ALLOCATABLE :: hermite_models(:)
    TYPE(CD_SystemType) :: point_system
    TYPE(CD_BathymetryType) :: bathymetry
    TYPE(DeckFailure), ALLOCATABLE :: fails(:)
    TYPE(CD_LineInitSummary), ALLOCATABLE :: init_summaries(:)
    INTEGER :: nl, li, es, j, n_finite
    LOGICAL :: line_conv, has_line_outputs, has_finite, has_dyn_points, has_rigid6, hermite_standalone_eligible
    CHARACTER(512) :: em

    converged = .FALSE.
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''

    CALL parse_deck(deck_path, types, bodies, rod_types, rods, points, lines, sections, opts, channels, &
                    ErrStat, ErrMsg, failures=fails)
    IF (ErrStat /= 0) RETURN
    ! Torsion (both ends of a line torsionally restrained) runs on the standalone cubic-Hermite
    ! route and the multibody march, in statics and dynamics (quasi-static torsion: no torsional
    ! inertia). One restrained end carries no torque (the other end is free to twist), so it is
    ! noted and ignored.
    DO li = 1, SIZE(lines)
      IF (COUNT(lines(li)%tors_mode /= TORS_FREE) == 1) WRITE (output_unit, '(A)') '  Note: line '// &
        TRIM(int_to_str(lines(li)%id))//' is torsionally restrained at one end only; with the other end free '// &
        'to twist it carries no torque, so no torsion is solved.'
    END DO
    IF (ANY([(line_torsion_active(lines(li)), li=1, SIZE(lines))])) THEN
      IF (opts%has_tmax .AND. opts%tmax > CD_ZERO .AND. .NOT. opts%alpha_force_blend) THEN
        CALL fail(ErrStat, ErrMsg, 'torsion in a dynamic run needs the force-blended generalised-alpha (OPTION '// &
                  'alpha_force_blend True)'); RETURN
      END IF
      IF (opts%n_modes > 0) THEN
        CALL fail(ErrStat, ErrMsg, 'modal analysis (OPTION nModes) of a line with torsion is not yet supported'); RETURN
      END IF
    END IF
    ! A FAILURE deck is inherently dynamic (the trigger fires at a committed march
    ! step) and runs on the point-system object graph -- the only path with the
    ! reserve-point detach machinery. Every other branch fails closed by name.
    IF (SIZE(fails) > 0) THEN
      IF (.NOT. (opts%has_dtm .AND. opts%has_tmax)) THEN
        CALL fail(ErrStat, ErrMsg, 'FAILURE requires a dynamic deck (dtM and TMax)'); RETURN
      END IF
      IF (deck_has_finite_ei(types, sections)) THEN
        CALL fail(ErrStat, ErrMsg, 'FAILURE is not supported on finite-EI decks'); RETURN
      END IF
      IF (SIZE(rods) > 0) THEN
        CALL fail(ErrStat, ErrMsg, 'FAILURE is not supported on ROD decks'); RETURN
      END IF
      IF (deck_has_rigid6_bodies(bodies)) THEN
        ! Rigid6 bodies with FAILURE run on the staggered body march, which integrates the
        ! detached line ends as free points; it takes no other dynamic point
        IF (deck_has_non_rigid6_dynamic_points(points, bodies)) THEN
          CALL fail(ErrStat, ErrMsg, 'FAILURE on a Rigid6 BODY deck does not support Connect/Free or '// &
                    'Point3 body points'); RETURN
        END IF
        IF (.NOT. opts%body_scheme_staggered) WRITE (output_unit, '(A)') &
          '  Note: a FAILURE deck marches its Rigid6 bodies on the staggered body scheme.'
      END IF
      IF (opts%has_motion_file) THEN
        CALL fail(ErrStat, ErrMsg, 'FAILURE deck does not support motionFile coupling'); RETURN
      END IF
      IF (opts%has_friction) THEN
        CALL fail(ErrStat, ErrMsg, 'FAILURE deck does not support seabed friction (the dynamic-point rule)'); RETURN
      END IF
    END IF
    CALL precompute_deck_wave(opts, ErrStat, ErrMsg)
    IF (ErrStat /= 0) RETURN
    IF (opts%has_bathymetry_file) THEN
      CALL load_bathymetry_file(path_join(deck_dir(deck_path), opts%bathymetry_file), bathymetry, ErrStat, ErrMsg, &
                                points=points)
      IF (ErrStat /= 0) RETURN
    END IF
    CALL print_static_input_warnings(types, points, lines, sections, opts)
    ! free Rigid6 bodies and rods (jointly with Free/Connect points) start at their static
    ! equilibrium on every route: static-only, TMax = 0 and the dynamic march (pinned rods turn
    ! about their pins, a rod pinned to a body with the body)
    IF (opts%has_bathymetry_file) THEN
      CALL solve_body_equilibrium(types, bodies, rod_types, rods, points, lines, sections, opts, ErrStat, &
                                  ErrMsg, bathymetry=bathymetry)
    ELSE
      CALL solve_body_equilibrium(types, bodies, rod_types, rods, points, lines, sections, opts, ErrStat, ErrMsg)
    END IF
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
      RETURN
    END IF
    has_line_outputs = any_line_outputs_requested(lines)
    has_finite = deck_has_finite_ei(types, sections)
    n_finite = 0
    DO li = 1, SIZE(lines)
      IF (line_is_finite_ei(lines(li), types, sections)) n_finite = n_finite + 1
    END DO
    has_dyn_points = deck_has_dynamic_points(points)
    has_rigid6 = deck_has_rigid6_bodies(bodies)
    IF (opts%n_modes > 0) THEN
      ! modal analysis about the static equilibrium: EI = 0 lines here, finite-EI lines on
      ! the cubic-Hermite route below
      CALL check_modal_deck(bodies, rods, points, lines, opts, n_finite, has_dyn_points, SIZE(fails) > 0, &
                            ErrStat, ErrMsg)
      IF (ErrStat == CD_DECKDRV_OK .AND. n_finite == 0) &
        CALL write_deck_modes_ei0(out_root, types, points, lines, sections, opts, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
        RETURN
      END IF
    END IF
    IF (opts%has_dtm .OR. opts%has_tmax) THEN
      IF (deck_needs_multibody(types, bodies, rods, points, lines, sections)) THEN
        ! bodies with pinned rods, pinned rods with lines, and mixed topologies: one march
        IF (opts%has_bathymetry_file) THEN
          CALL write_multibody_dynamic_out(deck_path, out_root, channels, types, bodies, rod_types, rods, points, &
                                           lines, sections, opts, n_finite, converged, ErrStat, ErrMsg, &
                                           bathymetry=bathymetry)
          CALL CD_End_Bathymetry(bathymetry)
        ELSE
          CALL write_multibody_dynamic_out(deck_path, out_root, channels, types, bodies, rod_types, rods, points, &
                                           lines, sections, opts, n_finite, converged, ErrStat, ErrMsg)
        END IF
        RETURN
      END IF
      IF (monolithic_march_eligible(opts, bodies, rods, SIZE(lines), has_finite, has_rigid6, has_dyn_points, &
                                    SIZE(fails))) THEN
        ! bodyScheme monolithic: Rigid6 bodies, free/pinned rods and Free/Connect points step
        ! monolithically with their EI=0 lines on the multibody march
        IF (opts%has_bathymetry_file) THEN
          CALL write_multibody_dynamic_out(deck_path, out_root, channels, types, bodies, rod_types, rods, points, &
                                           lines, sections, opts, n_finite, converged, ErrStat, ErrMsg, &
                                           bathymetry=bathymetry)
          CALL CD_End_Bathymetry(bathymetry)
        ELSE
          CALL write_multibody_dynamic_out(deck_path, out_root, channels, types, bodies, rod_types, rods, points, &
                                           lines, sections, opts, n_finite, converged, ErrStat, ErrMsg)
        END IF
        RETURN
      END IF
      IF (has_finite) THEN
        ! The standalone finite-EI march owns one homogeneous family of bending
        ! lines. Mixed EI=0/EI>0 composition belongs to the aggregate route; keep
        ! this guard ahead of BOTH the Hermite and compatibility dispatches so an
        ! EI=0 line can never be coerced through the all-lines Hermite builder.
        IF (.NOT. all_lines_have_finite_ei(types, lines, sections)) THEN
          IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
          CALL fail(ErrStat, ErrMsg, 'mixed EI=0 and finite-EI dynamic decks are not supported by this entry point')
          RETURN
        END IF
        ! (bodies, rods and Free/Connect points beside finite-EI lines never reach here:
        ! deck_needs_multibody routes them to the multibody march above)
        hermite_standalone_eligible = .TRUE.
        DO li = 1, SIZE(lines)
          ! The HFMF lifecycle drives End A and holds End B. Decks with two moving
          ! ends use the compatibility route, which supports that topology.
          j = find_point(points, lines(li)%nodeB)
          IF (j < 1 .OR. TRIM(points(j)%ptype) /= 'fixed') hermite_standalone_eligible = .FALSE.
        END DO
        ! The production cubic-Hermite route owns every eligible standalone finite-EI
        ! dynamic deck, including flat/structured contact, damping, friction, motion,
        ! and deck-owned fluid fields. The compatibility route remains only for the
        ! two-moving-end topology that the HFMF boundary cannot represent.
        IF (hermite_standalone_eligible) THEN
          ALLOCATE (hermite_models(SIZE(lines)))
          DO li = 1, SIZE(lines)
            IF (opts%has_bathymetry_file) THEN
              CALL build_one_hermite_cable(lines(li), sections, types, points, opts, opts%dtM, &
                                           hermite_models(li), j, ErrStat, ErrMsg, standalone_controls=.TRUE., &
                                           bathymetry=bathymetry)
            ELSE
              CALL build_one_hermite_cable(lines(li), sections, types, points, opts, opts%dtM, &
                                           hermite_models(li), j, ErrStat, ErrMsg, standalone_controls=.TRUE.)
            END IF
            IF (ErrStat /= CD_DECKDRV_OK) EXIT
          END DO
          IF (ErrStat == CD_DECKDRV_OK) THEN
            CALL collect_hermite_init_summaries(lines, hermite_models, init_summaries, ErrStat, ErrMsg)
          END IF
          IF (ErrStat == CD_DECKDRV_OK .AND. opts%n_modes > 0) &
            CALL write_deck_modes_hermite(out_root, lines, opts, hermite_models, ErrStat, ErrMsg)
          IF (ErrStat == CD_DECKDRV_OK) THEN
            CALL print_deck_init_report(deck_path, lines, points, sections, n_finite, init_summaries)
            CALL write_hermite_dynamic_out(out_root, channels, lines, points, opts, hermite_models, &
                                           converged, ErrStat, ErrMsg, bathymetry=bathymetry)
          END IF
          CALL end_hermite_cables(hermite_models)
        ELSE IF (opts%has_bathymetry_file) THEN
          CALL init_finite_deck_models(types, points, lines, sections, opts, finite_models, ErrStat, ErrMsg, &
                                       bathymetry=bathymetry)
        ELSE
          CALL init_finite_deck_models(types, points, lines, sections, opts, finite_models, ErrStat, ErrMsg)
        END IF
        IF (.NOT. ALLOCATED(finite_models)) THEN
          IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
          RETURN
        END IF
        IF (ErrStat /= 0) THEN
          IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
          RETURN
        END IF
        CALL collect_finite_init_summaries(lines, points, finite_models, init_summaries, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) THEN
          CALL end_finite_models(finite_models)
          IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
          RETURN
        END IF
        CALL print_deck_init_report(deck_path, lines, points, sections, n_finite, init_summaries)
        CALL write_finite_dynamic_out(out_root, channels, lines, points, opts, finite_models, &
                                      converged, ErrStat, ErrMsg, bathymetry=bathymetry)
        CALL end_finite_models(finite_models)
      ELSE IF (SIZE(lines) == 0 .AND. (SIZE(rods) > 0 .OR. has_rigid6)) THEN
        ! bodies (with rods fixed to them) and free or pinned rods, no lines
        IF (opts%has_bathymetry_file) THEN
          CALL write_objects_dynamic_out(out_root, channels, bodies, rod_types, rods, points, opts, converged, &
                                         ErrStat, ErrMsg, bathymetry=bathymetry)
        ELSE
          CALL write_objects_dynamic_out(out_root, channels, bodies, rod_types, rods, points, opts, converged, &
                                         ErrStat, ErrMsg)
        END IF
      ELSE IF (SIZE(rods) > 0 .AND. COUNT([(body_id_of_rod_type(rods(li)%rod_type) > 0, li=1, SIZE(rods))]) < &
               SIZE(rods)) THEN
        IF (has_rigid6 .OR. deck_has_non_rod_dynamic_points(points)) THEN
          IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
          CALL fail(ErrStat, ErrMsg, 'Rod dynamic deck cannot mix free, fixed or prescribed rods with Body<N>, '// &
                    'Connect, or Free points (rods fixed to a Rigid6 body, RODS type Body<N>, can)')
          RETURN
        END IF
        IF (ANY(rods%rod_type == 'pinned')) THEN
          IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
          CALL fail(ErrStat, ErrMsg, 'a Pinned ROD runs only on a deck without lines')
          RETURN
        END IF
        IF (opts%has_bathymetry_file) THEN
          CALL init_deck_system_from_parsed(types, points, lines, sections, opts, point_system, ErrStat, ErrMsg, &
                                            bathymetry=bathymetry)
        ELSE
          CALL init_deck_system_from_parsed(types, points, lines, sections, opts, point_system, ErrStat, ErrMsg)
        END IF
        IF (ErrStat /= CD_DECKDRV_OK) THEN
          IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
          RETURN
        END IF
        CALL collect_system_init_summaries(lines, points, point_system, init_summaries, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) THEN
          CALL CD_End_System(point_system, es, em)
          IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
          RETURN
        END IF
        CALL print_deck_init_report(deck_path, lines, points, sections, n_finite, init_summaries)
        IF (opts%has_bathymetry_file) THEN
          CALL write_rod_dynamic_out(out_root, channels, rod_types, rods, lines, points, opts, point_system, &
                                     converged, ErrStat, ErrMsg, bathymetry=bathymetry)
        ELSE
          CALL write_rod_dynamic_out(out_root, channels, rod_types, rods, lines, points, opts, point_system, &
                                     converged, ErrStat, ErrMsg)
        END IF
        CALL CD_End_System(point_system, es, em)
      ELSE IF (has_rigid6) THEN
        IF (deck_has_non_rigid6_dynamic_points(points, bodies)) THEN
          IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
          CALL fail(ErrStat, ErrMsg, &
                    'Rigid6 dynamic deck cannot mix Rigid6 body points with Connect/Free or Point3 body points')
          RETURN
        END IF
        IF (opts%has_bathymetry_file) THEN
          CALL init_deck_system_from_parsed(types, points, lines, sections, opts, point_system, ErrStat, ErrMsg, &
                                            bathymetry=bathymetry, failures=fails)
        ELSE
          CALL init_deck_system_from_parsed(types, points, lines, sections, opts, point_system, ErrStat, ErrMsg, &
                                            failures=fails)
        END IF
        IF (ErrStat /= 0) THEN
          IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
          RETURN
        END IF
        CALL collect_system_init_summaries(lines, points, point_system, init_summaries, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) THEN
          CALL CD_End_System(point_system, es, em)
          IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
          RETURN
        END IF
        CALL print_deck_init_report(deck_path, lines, points, sections, n_finite, init_summaries)
        IF (opts%has_bathymetry_file) THEN
          CALL write_rigid6_dynamic_out(out_root, channels, bodies, lines, points, opts, point_system, &
                                        converged, ErrStat, ErrMsg, bathymetry=bathymetry, rod_types=rod_types, &
                                        rods=rods, failures=fails)
        ELSE
          CALL write_rigid6_dynamic_out(out_root, channels, bodies, lines, points, opts, point_system, &
                                        converged, ErrStat, ErrMsg, rod_types=rod_types, rods=rods, failures=fails)
        END IF
        CALL CD_End_System(point_system, es, em)
      ELSE IF (has_dyn_points .OR. SIZE(fails) > 0) THEN
        IF (opts%has_motion_file) THEN
          IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
          CALL fail(ErrStat, ErrMsg, 'Connect/Free dynamic-point deck does not support motionFile coupling')
          RETURN
        END IF
        IF (opts%has_bathymetry_file) THEN
          CALL init_deck_system_from_parsed(types, points, lines, sections, opts, point_system, ErrStat, ErrMsg, &
                                            bathymetry=bathymetry, failures=fails)
        ELSE
          CALL init_deck_system_from_parsed(types, points, lines, sections, opts, point_system, ErrStat, ErrMsg, &
                                            failures=fails)
        END IF
        IF (ErrStat /= 0) THEN
          IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
          RETURN
        END IF
        CALL collect_system_init_summaries(lines, points, point_system, init_summaries, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) THEN
          CALL CD_End_System(point_system, es, em)
          IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
          RETURN
        END IF
        CALL print_deck_init_report(deck_path, lines, points, sections, n_finite, init_summaries)
        CALL write_system_dynamic_out(out_root, channels, lines, points, opts, point_system, converged, &
                                      ErrStat, ErrMsg, failures=fails, bathymetry=bathymetry)
        CALL CD_End_System(point_system, es, em)
      ELSE
        IF (opts%has_bathymetry_file) THEN
          CALL init_deck_models_from_parsed(types, points, lines, sections, opts, models, ErrStat, ErrMsg, &
                                            bathymetry=bathymetry)
        ELSE
          CALL init_deck_models_from_parsed(types, points, lines, sections, opts, models, ErrStat, ErrMsg)
        END IF
        IF (ErrStat /= 0) THEN
          IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
          RETURN
        END IF
        CALL collect_model_init_summaries(lines, points, models, init_summaries, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) THEN
          CALL end_models(models)
          IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
          RETURN
        END IF
        CALL print_deck_init_report(deck_path, lines, points, sections, n_finite, init_summaries)
        CALL write_dynamic_out(out_root, channels, lines, points, opts, models, converged, ErrStat, ErrMsg, &
                               bathymetry=bathymetry)
        CALL end_models(models)
      END IF
      IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
      RETURN
    END IF

    nl = SIZE(lines)
    ALLOCATE (q_off(nl + 1), ten_off(nl + 1), nn(nl), ne(nl))
    q_off(1) = 0; ten_off(1) = 0
    DO li = 1, nl
      ne(li) = 0
      DO j = 1, SIZE(sections)
        IF (sections(j)%line_id == lines(li)%id) ne(li) = ne(li) + sections(j)%nsegs
      END DO
      nn(li) = ne(li) + 1
      q_off(li + 1) = q_off(li) + 3*nn(li)
      ten_off(li + 1) = ten_off(li) + ne(li)
    END DO
    ALLOCATE (q_all(q_off(nl + 1)), ten_all(ten_off(nl + 1)), end_all(2, nl), end_vec(3, 2, nl))
    ! Free/Connect points of a static deck move to their force balance first
    IF (opts%has_bathymetry_file) THEN
      CALL solve_point_equilibrium(types, points, lines, sections, opts, ErrStat, ErrMsg, bathymetry=bathymetry)
    ELSE
      CALL solve_point_equilibrium(types, points, lines, sections, opts, ErrStat, ErrMsg)
    END IF
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      ErrMsg = 'CableDyn_DeckDriver: '//TRIM(ErrMsg)
      IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
      RETURN
    END IF
    converged = .TRUE.
    fail_msg = ''
    DO li = 1, nl
      IF (opts%has_bathymetry_file) THEN
        CALL solve_one_line(lines(li), sections, types, points, opts, &
                            q_all(q_off(li) + 1:q_off(li + 1)), &
                            ten_all(ten_off(li) + 1:ten_off(li + 1)), &
                            line_conv, es, em, bathymetry=bathymetry, end_ten=end_all(:, li), &
                            end_force=end_vec(:, :, li))
      ELSE
        CALL solve_one_line(lines(li), sections, types, points, opts, &
                            q_all(q_off(li) + 1:q_off(li + 1)), &
                            ten_all(ten_off(li) + 1:ten_off(li + 1)), &
                            line_conv, es, em, end_ten=end_all(:, li), end_force=end_vec(:, :, li))
      END IF
      IF (es == CD_DECKDRV_BADINPUT) THEN
        ErrStat = CD_DECKDRV_BADINPUT; ErrMsg = em
        IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
        RETURN
      ELSE IF (es == CD_DECKDRV_SOLVEFAIL) THEN
        ! keep the first failing line's diagnosis (line id, stage, solver reason) for the report
        IF (converged) fail_msg = em
        converged = .FALSE.
      END IF
    END DO

    IF (converged) THEN
      CALL collect_raw_init_summaries(lines, points, ne, q_all, q_off, ten_all, ten_off, init_summaries, &
                                      end_ten=end_all, end_force=end_vec)
      CALL print_deck_init_report(deck_path, lines, points, sections, n_finite, init_summaries)
      IF (.NOT. (opts%has_wtrdpth .OR. opts%has_bathymetry_file)) &
        CALL warn_line_below_anchor(lines, points, sections, q_all, q_off)
    END IF

    CALL write_out(out_root, channels, lines, points, ne, q_all, q_off, ten_all, ten_off, converged, ErrStat, ErrMsg, &
                   end_ten=end_all, end_force=end_vec, opts=opts, bathymetry=bathymetry)
    IF (opts%has_bathymetry_file) CALL CD_End_Bathymetry(bathymetry)
    IF (ErrStat /= 0) RETURN
    IF (.NOT. converged) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: '//TRIM(fail_msg)//' (.out written for inspection)'
    END IF
  END SUBROUTINE run_deck_driver

  SUBROUTINE CD_Deck_Equilibrium_Jacobian_Check(deck_path, rel_err, ErrStat, ErrMsg, points_only)
    !! Verification hook for the static-equilibrium Newton of solve_body_equilibrium: parse the
    !! deck and return the largest difference between its analytic Jacobian (condensed line end
    !! stiffness plus the objects' own terms) and a central-difference Jacobian of the full
    !! residual at the deck state, relative to the largest FD entry. points_only checks the
    !! Free/Connect point system alone (bodies and rods held).
    CHARACTER(*), INTENT(IN) :: deck_path
    REAL(wp), INTENT(OUT) :: rel_err
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    LOGICAL, INTENT(IN), OPTIONAL :: points_only

    TYPE(DeckLineType), ALLOCATABLE :: types(:)
    TYPE(DeckBody), ALLOCATABLE :: bodies(:)
    TYPE(DeckRodType), ALLOCATABLE :: rod_types(:)
    TYPE(DeckRod), ALLOCATABLE :: rods(:)
    TYPE(DeckPoint), ALLOCATABLE :: points(:)
    TYPE(DeckLine), ALLOCATABLE :: lines(:)
    TYPE(DeckSection), ALLOCATABLE :: sections(:)
    TYPE(DeckOptions) :: opts
    CHARACTER(NAMELEN), ALLOCATABLE :: channels(:)
    LOGICAL :: only_points

    rel_err = -CD_ONE
    only_points = .FALSE.
    IF (PRESENT(points_only)) only_points = points_only
    CALL parse_deck(deck_path, types, bodies, rod_types, rods, points, lines, sections, opts, channels, &
                    ErrStat, ErrMsg)
    IF (ErrStat /= 0) RETURN
    CALL solve_body_equilibrium(types, bodies, rod_types, rods, points, lines, sections, opts, ErrStat, ErrMsg, &
                                points_only=only_points, jac_check_err=rel_err)
  END SUBROUTINE CD_Deck_Equilibrium_Jacobian_Check

  ! --------------------------------------------------------------------------- !
  ! per-line static solve (multi-section)                                       !
  ! --------------------------------------------------------------------------- !

  SUBROUTINE init_one_model(ln, sections, types, points, opts, model, ErrStat, ErrMsg, bathymetry)
    !! Initialize one persistent model from a validated deck LINE.
    TYPE(DeckLine), INTENT(IN) :: ln
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(CD_ModelType), INTENT(INOUT) :: model
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    TYPE(CD_LineType), ALLOCATABLE :: lts(:)
    TYPE(CD_LineSection), ALLOCATABLE :: secs(:)
    TYPE(CableSolverConfig) :: static_cfg
    TYPE(GenAlphaConfig) :: dynamic_cfg
    INTEGER, ALLOCATABLE :: conn(:, :)
    REAL(wp), ALLOCATABLE :: l0(:), ea(:), mpl(:), diam(:), kn(:), cn(:), waterline(:)
    REAL(wp), ALLOCATABLE :: ba(:), fluid_velocity(:, :), fluid_acceleration(:, :), drag_waterline(:)
    REAL(wp), ALLOCATABLE :: hydro_diam(:), hydro_cdn(:), hydro_cdt(:), hydro_can(:), hydro_cat(:)
    REAL(wp), ALLOCATABLE :: ve_ead(:), ve_bas(:), ve_bad(:), ve_ambl(:), ve_vbet(:)
    REAL(wp) :: anchor(3), fairlead(3)
    REAL(wp), PARAMETER :: factors(4) = [0.25_wp, 0.5_wp, 0.75_wp, CD_ONE]
    INTEGER :: j, i, e, es
    LOGICAL :: want_wave_cfg
    CHARACTER(200) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    CALL gather_line_inputs(ln, sections, types, points, lts, secs, anchor, fairlead, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN

    dynamic_cfg%rho_inf = opts%rho_inf
    dynamic_cfg%rel_tol = opts%dynamic_rel_tol
    dynamic_cfg%abs_tol = opts%dynamic_abs_tol
    dynamic_cfg%max_iter = opts%dynamic_max_iter
    dynamic_cfg%armijo_max_backtracks = opts%dynamic_backtracks
    dynamic_cfg%modified_newton = opts%dynamic_modified_newton
    CALL CD_Build_Line_Mesh(secs, lts, .TRUE., conn, l0, ea, mpl, diam, es, em)
    IF (es /= CD_LINE_OK) THEN
      CALL fail(ErrStat, ErrMsg, 'line mesh for model init: '//TRIM(em)); RETURN
    END IF
    ALLOCATE (ba(SIZE(l0)), hydro_diam(SIZE(l0)), hydro_cdn(SIZE(l0)), hydro_cdt(SIZE(l0)), &
              hydro_can(SIZE(l0)), hydro_cat(SIZE(l0)), ve_ead(SIZE(l0)), ve_bas(SIZE(l0)), &
              ve_bad(SIZE(l0)), ve_ambl(SIZE(l0)), ve_vbet(SIZE(l0)))
    ve_ead = CD_ZERO
    ve_bas = CD_ZERO
    ve_bad = CD_ZERO
    ve_ambl = CD_ZERO
    ve_vbet = CD_ZERO
    e = 0
    DO i = 1, SIZE(secs)
      DO j = 1, secs(i)%n_segments
        e = e + 1
        CALL CD_Resolve_Legacy_BA(types(line_section_type(sections, ln%id, i))%ba, l0(e), ea(e), mpl(e), &
                                  ba(e), es, em)
        IF (es /= CD_DAMP_OK) THEN
          CALL fail(ErrStat, ErrMsg, 'BA resolution for model init: '//TRIM(em)); RETURN
        END IF
        IF (types(line_section_type(sections, ln%id, i))%elastic_mod > 1) THEN
          ! viscoelastic section (ElasticMod 2 or 3): the series-Kelvin law takes over this
          ! element's axial response -- Es stays in ea (the static composite the
          ! IC solves with), the dynamic stiffness (constant Ed, or the
          ! alphaMBL/vbeta load-dependent pair) and the two dashpots feed the
          ! per-element state model; the resolved ba doubles as the series-law
          ! static-branch Bs (the -zeta convention resolves identically for
          ! both roles)
          IF (types(line_section_type(sections, ln%id, i))%elastic_mod == 2) THEN
            ve_ead(e) = types(line_section_type(sections, ln%id, i))%ea_d
          ELSE
            ve_ambl(e) = types(line_section_type(sections, ln%id, i))%alpha_mbl
            ve_vbet(e) = types(line_section_type(sections, ln%id, i))%vbeta
          END IF
          ve_bas(e) = ba(e)
          ve_bad(e) = types(line_section_type(sections, ln%id, i))%ba_d
        END IF
        hydro_diam(e) = types(line_section_type(sections, ln%id, i))%diam
        hydro_cdn(e) = types(line_section_type(sections, ln%id, i))%cdn
        hydro_cdt(e) = types(line_section_type(sections, ln%id, i))%cdt
        hydro_can(e) = types(line_section_type(sections, ln%id, i))%can
        hydro_cat(e) = types(line_section_type(sections, ln%id, i))%cat
      END DO
    END DO
    ba = ba(SIZE(ba):1:-1)
    ve_ead = ve_ead(SIZE(ve_ead):1:-1)
    ve_bas = ve_bas(SIZE(ve_bas):1:-1)
    ve_bad = ve_bad(SIZE(ve_bad):1:-1)
    ve_ambl = ve_ambl(SIZE(ve_ambl):1:-1)
    ve_vbet = ve_vbet(SIZE(ve_vbet):1:-1)
    hydro_diam = hydro_diam(SIZE(hydro_diam):1:-1)
    hydro_cdn = hydro_cdn(SIZE(hydro_cdn):1:-1)
    hydro_cdt = hydro_cdt(SIZE(hydro_cdt):1:-1)
    hydro_can = hydro_can(SIZE(hydro_can):1:-1)
    hydro_cat = hydro_cat(SIZE(hydro_cat):1:-1)
    ! Syrope line: a dedicated basic build path (single section, taut, no seabed
    ! or hydro). Detected here and handled separately from the hydro variants
    ! below, which do not carry the working-curve state.
    BLOCK
      INTEGER :: syt, i2
      syt = 0
      DO i2 = 1, SIZE(secs)
        IF (types(line_section_type(sections, ln%id, i2))%is_syrope) &
          syt = line_section_type(sections, ln%id, i2)
      END DO
      IF (syt > 0) THEN
        CALL init_one_syrope_model(types, syt, ln, lts, secs, anchor, fairlead, l0, opts, &
                                   static_cfg, dynamic_cfg, factors, bathymetry, model, ErrStat, ErrMsg)
        RETURN
      END IF
    END BLOCK
    ! external_fluid: the host prescribes per-node fluid kinematics each step, so the
    ! model must be built with the full wave-capable hydro configuration (drag + FK +
    ! added mass + wetting waterlines) at zero initial fields -- the same arg set the
    ! deck-waves branches pass, minus any deck wave model. Zero fields contribute
    ! exactly zero load, so the undriven build is response-identical to the plain one.
    want_wave_cfg = opts%has_wave .OR. opts%external_fluid
    IF (opts%external_fluid .AND. .NOT. (opts%has_wtrdpth .OR. PRESENT(bathymetry))) THEN
      CALL fail(ErrStat, ErrMsg, 'host-driven ambient fluid (external_fluid) requires a seabed '// &
                '(WtrDpth or bathymetryFile) -- the coupled host always supplies one'); RETURN
    END IF
    IF (opts%has_current .OR. want_wave_cfg .OR. opts%has_wtrdpth .OR. PRESENT(bathymetry)) THEN
      ALLOCATE (fluid_velocity(3, SIZE(l0) + 1), drag_waterline(SIZE(l0) + 1))
      DO i = 1, SIZE(l0) + 1
        IF (opts%has_current) THEN
          fluid_velocity(:, i) = deck_current_velocity(opts, line_node_z(anchor, fairlead, l0, i), es, em)
          IF (es /= CD_HYDRO_OK) THEN
            CALL fail(ErrStat, ErrMsg, 'current profile for model init: '//TRIM(em)); RETURN
          END IF
        ELSE
          fluid_velocity(:, i) = CD_ZERO
        END IF
      END DO
      drag_waterline = CD_ZERO
    END IF
    IF (want_wave_cfg) THEN
      ALLOCATE (fluid_acceleration(3, SIZE(l0) + 1))
      fluid_acceleration = CD_ZERO
    END IF

    IF (PRESENT(bathymetry) .AND. want_wave_cfg) THEN
      ALLOCATE (waterline(SIZE(l0) + 1))
      waterline = CD_ZERO
      CALL CD_Nodal_Seabed_Stiffness(opts%kbot, diam, l0, kn, es, em)
      IF (es /= CD_LINE_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'seabed stiffness for model init: '//TRIM(em)); RETURN
      END IF
      ALLOCATE (cn(SIZE(kn)))
      cn = kn*(opts%cbot/opts%kbot)
      ! dynamic_tension_only clamps the ELASTIC force only -- BA axial damping stays
      ! active on slack elements BY DESIGN, matching MoorDyn exactly: MoorDyn_Line.f90's
      ! basic elasticity model clamps MagT ("cable can't push") while MagTd is computed
      ! unconditionally. "Slack exerts nothing" would be a DIFFERENT convention from
      ! MoorDyn's, whose deck dialect this parser reads.
      CALL CD_Init_Line_Model(model, anchor, fairlead, lts, secs, opts%g, opts%rhoW, .FALSE., &
                              static_cfg, dynamic_cfg, factors, ErrStat, ErrMsg, &
                              dynamic_tension_only=.TRUE., &
                              anchor_is_end_b=.TRUE., seabed_kn=kn, bathymetry=bathymetry, seabed_cn=cn, &
                              seabed_kbot=opts%kbot, seabed_contact_diameter=diam, &
                              seabed_cn_over_kn=opts%cbot/opts%kbot, &
                              seabed_mu=opts%friction_mu, seabed_mu_axial=opts%friction_mu_axial, ba=ba, &
                              ve_ea_d=ve_ead, ve_ba=ve_bas, ve_ba_d=ve_bad, ve_alpha_mbl=ve_ambl, ve_vbeta=ve_vbet, &
                              current_profile_z=opts%current_profile_z, &
                              current_profile_velocity=opts%current_profile_velocity, &
                              fluid_velocity=fluid_velocity, drag_waterline_z=drag_waterline, drag_rho=opts%rhoW, &
                              drag_diameter_elem=hydro_diam, drag_cdn_elem=hydro_cdn, drag_cdt_elem=hydro_cdt, &
                              fluid_acceleration=fluid_acceleration, fk_waterline_z=waterline, fk_rho=opts%rhoW, &
                              fk_diameter_elem=hydro_diam, fk_can_elem=hydro_can, fk_cat_elem=hydro_cat, &
                              added_mass_waterline_z=waterline, added_mass_rho=opts%rhoW, &
                              added_mass_diameter_elem=hydro_diam, added_mass_can_elem=hydro_can, &
                              added_mass_cat_elem=hydro_cat, buoyancy_waterline_z=waterline, &
                              buoyancy_rho=opts%rhoW, buoyancy_diameter_elem=hydro_diam, buoyancy_gravity=opts%g)
    ELSE IF (PRESENT(bathymetry) .AND. opts%has_current) THEN
      ALLOCATE (waterline(SIZE(l0) + 1))
      waterline = CD_ZERO
      CALL CD_Nodal_Seabed_Stiffness(opts%kbot, diam, l0, kn, es, em)
      IF (es /= CD_LINE_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'seabed stiffness for model init: '//TRIM(em)); RETURN
      END IF
      ALLOCATE (cn(SIZE(kn)))
      cn = kn*(opts%cbot/opts%kbot)
      CALL CD_Init_Line_Model(model, anchor, fairlead, lts, secs, opts%g, opts%rhoW, .FALSE., &
                              static_cfg, dynamic_cfg, factors, ErrStat, ErrMsg, &
                              dynamic_tension_only=.TRUE., &
                              anchor_is_end_b=.TRUE., seabed_kn=kn, bathymetry=bathymetry, seabed_cn=cn, &
                              seabed_kbot=opts%kbot, seabed_contact_diameter=diam, &
                              seabed_cn_over_kn=opts%cbot/opts%kbot, &
                              seabed_mu=opts%friction_mu, seabed_mu_axial=opts%friction_mu_axial, ba=ba, &
                              ve_ea_d=ve_ead, ve_ba=ve_bas, ve_ba_d=ve_bad, ve_alpha_mbl=ve_ambl, ve_vbeta=ve_vbet, &
                              current_profile_z=opts%current_profile_z, &
                              current_profile_velocity=opts%current_profile_velocity, &
                              fluid_velocity=fluid_velocity, drag_waterline_z=drag_waterline, drag_rho=opts%rhoW, &
                              drag_diameter_elem=hydro_diam, drag_cdn_elem=hydro_cdn, drag_cdt_elem=hydro_cdt, &
                              added_mass_waterline_z=waterline, added_mass_rho=opts%rhoW, &
                              added_mass_diameter_elem=hydro_diam, added_mass_can_elem=hydro_can, &
                              added_mass_cat_elem=hydro_cat, buoyancy_waterline_z=waterline, &
                              buoyancy_rho=opts%rhoW, buoyancy_diameter_elem=hydro_diam, buoyancy_gravity=opts%g)
    ELSE IF (PRESENT(bathymetry)) THEN
      ALLOCATE (waterline(SIZE(l0) + 1))
      waterline = CD_ZERO
      CALL CD_Nodal_Seabed_Stiffness(opts%kbot, diam, l0, kn, es, em)
      IF (es /= CD_LINE_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'seabed stiffness for model init: '//TRIM(em)); RETURN
      END IF
      ALLOCATE (cn(SIZE(kn)))
      cn = kn*(opts%cbot/opts%kbot)
      CALL CD_Init_Line_Model(model, anchor, fairlead, lts, secs, opts%g, opts%rhoW, .FALSE., &
                              static_cfg, dynamic_cfg, factors, ErrStat, ErrMsg, &
                              dynamic_tension_only=.TRUE., &
                              anchor_is_end_b=.TRUE., seabed_kn=kn, bathymetry=bathymetry, seabed_cn=cn, &
                              seabed_kbot=opts%kbot, seabed_contact_diameter=diam, &
                              seabed_cn_over_kn=opts%cbot/opts%kbot, &
                              seabed_mu=opts%friction_mu, seabed_mu_axial=opts%friction_mu_axial, ba=ba, &
                              ve_ea_d=ve_ead, ve_ba=ve_bas, ve_ba_d=ve_bad, ve_alpha_mbl=ve_ambl, ve_vbeta=ve_vbet, &
                              current_profile_z=opts%current_profile_z, &
                              current_profile_velocity=opts%current_profile_velocity, &
                              fluid_velocity=fluid_velocity, drag_waterline_z=drag_waterline, drag_rho=opts%rhoW, &
                              drag_diameter_elem=hydro_diam, drag_cdn_elem=hydro_cdn, drag_cdt_elem=hydro_cdt, &
                              added_mass_waterline_z=waterline, added_mass_rho=opts%rhoW, &
                              added_mass_diameter_elem=hydro_diam, added_mass_can_elem=hydro_can, &
                              added_mass_cat_elem=hydro_cat, buoyancy_waterline_z=waterline, &
                              buoyancy_rho=opts%rhoW, buoyancy_diameter_elem=hydro_diam, buoyancy_gravity=opts%g)
    ELSE IF (opts%has_wtrdpth .AND. want_wave_cfg) THEN
      ALLOCATE (waterline(SIZE(l0) + 1))
      waterline = CD_ZERO
      CALL CD_Nodal_Seabed_Stiffness(opts%kbot, diam, l0, kn, es, em)
      IF (es /= CD_LINE_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'seabed stiffness for model init: '//TRIM(em)); RETURN
      END IF
      ALLOCATE (cn(SIZE(kn)))
      cn = kn*(opts%cbot/opts%kbot)
      CALL CD_Init_Line_Model(model, anchor, fairlead, lts, secs, opts%g, opts%rhoW, .FALSE., &
                              static_cfg, dynamic_cfg, factors, ErrStat, ErrMsg, &
                              dynamic_tension_only=.TRUE., &
                              anchor_is_end_b=.TRUE., &
                              seabed_z_floor=-opts%wtrdpth, seabed_kn=kn, seabed_cn=cn, &
                              seabed_kbot=opts%kbot, seabed_contact_diameter=diam, &
                              seabed_cn_over_kn=opts%cbot/opts%kbot, &
                              seabed_mu=opts%friction_mu, seabed_mu_axial=opts%friction_mu_axial, ba=ba, &
                              ve_ea_d=ve_ead, ve_ba=ve_bas, ve_ba_d=ve_bad, ve_alpha_mbl=ve_ambl, ve_vbeta=ve_vbet, &
                              current_profile_z=opts%current_profile_z, &
                              current_profile_velocity=opts%current_profile_velocity, &
                              fluid_velocity=fluid_velocity, drag_waterline_z=drag_waterline, drag_rho=opts%rhoW, &
                              drag_diameter_elem=hydro_diam, drag_cdn_elem=hydro_cdn, drag_cdt_elem=hydro_cdt, &
                              fluid_acceleration=fluid_acceleration, fk_waterline_z=waterline, fk_rho=opts%rhoW, &
                              fk_diameter_elem=hydro_diam, fk_can_elem=hydro_can, fk_cat_elem=hydro_cat, &
                              added_mass_waterline_z=waterline, added_mass_rho=opts%rhoW, &
                              added_mass_diameter_elem=hydro_diam, added_mass_can_elem=hydro_can, &
                              added_mass_cat_elem=hydro_cat, buoyancy_waterline_z=waterline, &
                              buoyancy_rho=opts%rhoW, buoyancy_diameter_elem=hydro_diam, buoyancy_gravity=opts%g)
    ELSE IF (opts%has_wtrdpth .AND. opts%has_current) THEN
      ALLOCATE (waterline(SIZE(l0) + 1))
      waterline = CD_ZERO
      CALL CD_Nodal_Seabed_Stiffness(opts%kbot, diam, l0, kn, es, em)
      IF (es /= CD_LINE_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'seabed stiffness for model init: '//TRIM(em)); RETURN
      END IF
      ALLOCATE (cn(SIZE(kn)))
      cn = kn*(opts%cbot/opts%kbot)
      CALL CD_Init_Line_Model(model, anchor, fairlead, lts, secs, opts%g, opts%rhoW, .FALSE., &
                              static_cfg, dynamic_cfg, factors, ErrStat, ErrMsg, &
                              dynamic_tension_only=.TRUE., &
                              anchor_is_end_b=.TRUE., &
                              seabed_z_floor=-opts%wtrdpth, seabed_kn=kn, seabed_cn=cn, &
                              seabed_kbot=opts%kbot, seabed_contact_diameter=diam, &
                              seabed_cn_over_kn=opts%cbot/opts%kbot, &
                              seabed_mu=opts%friction_mu, seabed_mu_axial=opts%friction_mu_axial, ba=ba, &
                              ve_ea_d=ve_ead, ve_ba=ve_bas, ve_ba_d=ve_bad, ve_alpha_mbl=ve_ambl, ve_vbeta=ve_vbet, &
                              current_profile_z=opts%current_profile_z, &
                              current_profile_velocity=opts%current_profile_velocity, &
                              fluid_velocity=fluid_velocity, drag_waterline_z=drag_waterline, drag_rho=opts%rhoW, &
                              drag_diameter_elem=hydro_diam, drag_cdn_elem=hydro_cdn, drag_cdt_elem=hydro_cdt, &
                              added_mass_waterline_z=waterline, added_mass_rho=opts%rhoW, &
                              added_mass_diameter_elem=hydro_diam, added_mass_can_elem=hydro_can, &
                              added_mass_cat_elem=hydro_cat, buoyancy_waterline_z=waterline, &
                              buoyancy_rho=opts%rhoW, buoyancy_diameter_elem=hydro_diam, buoyancy_gravity=opts%g)
    ELSE IF (opts%has_wtrdpth) THEN
      ALLOCATE (waterline(SIZE(l0) + 1))
      waterline = CD_ZERO
      CALL CD_Nodal_Seabed_Stiffness(opts%kbot, diam, l0, kn, es, em)
      IF (es /= CD_LINE_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'seabed stiffness for model init: '//TRIM(em)); RETURN
      END IF
      ALLOCATE (cn(SIZE(kn)))
      cn = kn*(opts%cbot/opts%kbot)
      CALL CD_Init_Line_Model(model, anchor, fairlead, lts, secs, opts%g, opts%rhoW, .FALSE., &
                              static_cfg, dynamic_cfg, factors, ErrStat, ErrMsg, &
                              dynamic_tension_only=.TRUE., &
                              anchor_is_end_b=.TRUE., &
                              seabed_z_floor=-opts%wtrdpth, seabed_kn=kn, seabed_cn=cn, &
                              seabed_kbot=opts%kbot, seabed_contact_diameter=diam, &
                              seabed_cn_over_kn=opts%cbot/opts%kbot, &
                              seabed_mu=opts%friction_mu, seabed_mu_axial=opts%friction_mu_axial, ba=ba, &
                              ve_ea_d=ve_ead, ve_ba=ve_bas, ve_ba_d=ve_bad, ve_alpha_mbl=ve_ambl, ve_vbeta=ve_vbet, &
                              current_profile_z=opts%current_profile_z, &
                              current_profile_velocity=opts%current_profile_velocity, &
                              fluid_velocity=fluid_velocity, drag_waterline_z=drag_waterline, drag_rho=opts%rhoW, &
                              drag_diameter_elem=hydro_diam, drag_cdn_elem=hydro_cdn, drag_cdt_elem=hydro_cdt, &
                              added_mass_waterline_z=waterline, added_mass_rho=opts%rhoW, &
                              added_mass_diameter_elem=hydro_diam, added_mass_can_elem=hydro_can, &
                              added_mass_cat_elem=hydro_cat, buoyancy_waterline_z=waterline, &
                              buoyancy_rho=opts%rhoW, buoyancy_diameter_elem=hydro_diam, buoyancy_gravity=opts%g)
    ELSE IF (opts%has_current) THEN
      CALL CD_Init_Line_Model(model, anchor, fairlead, lts, secs, opts%g, opts%rhoW, .FALSE., &
                              static_cfg, dynamic_cfg, factors, ErrStat, ErrMsg, &
                              dynamic_tension_only=.TRUE., anchor_is_end_b=.TRUE., ba=ba, &
                              ve_ea_d=ve_ead, ve_ba=ve_bas, ve_ba_d=ve_bad, ve_alpha_mbl=ve_ambl, ve_vbeta=ve_vbet, &
                              current_profile_z=opts%current_profile_z, &
                              current_profile_velocity=opts%current_profile_velocity, &
                              fluid_velocity=fluid_velocity, drag_waterline_z=drag_waterline, drag_rho=opts%rhoW, &
                              drag_diameter_elem=hydro_diam, drag_cdn_elem=hydro_cdn, drag_cdt_elem=hydro_cdt)
    ELSE
      CALL CD_Init_Line_Model(model, anchor, fairlead, lts, secs, opts%g, opts%rhoW, .FALSE., &
                              static_cfg, dynamic_cfg, factors, ErrStat, ErrMsg, &
                              dynamic_tension_only=.TRUE., anchor_is_end_b=.TRUE., ba=ba, &
                              ve_ea_d=ve_ead, ve_ba=ve_bas, ve_ba_d=ve_bad, ve_alpha_mbl=ve_ambl, ve_vbeta=ve_vbet)
    END IF
    IF (ErrStat /= CD_MODEL_OK) THEN
      ErrMsg = 'CableDyn_DeckDriver: model init failed: '//TRIM(ErrMsg)
      IF (ErrStat /= CD_DECKDRV_BADINPUT) ErrStat = CD_DECKDRV_SOLVEFAIL
    END IF
  END SUBROUTINE init_one_model

  SUBROUTINE init_one_syrope_model(types, syt, ln, lts, secs, anchor, fairlead, l0, opts, &
                                   static_cfg, dynamic_cfg, factors, bathymetry, model, ErrStat, ErrMsg)
    !! Build one Syrope line model. The supported scope is a single-section taut line with
    !! no hydro. Builds the working-curve constitutive from the parse-resolved OWC data and
    !! solves the static equilibrium on the rest curve of the initial load history (the OWC
    !! for a virgin rope; with SYROPE IC, the Tmax0 working curve below its top strain and
    !! the OWC above): the secant EA of that curve at the solved mean strain. Each element
    !! then gets the running maximum of that history and the slow strain whose t = 0 kernel
    !! force equals its static tension, so the dynamic state starts in the static
    !! equilibrium. Tmean0 is not a state input (the fixed-end geometry and Tmax0 set the
    !! mean tension); a disagreement beyond 1 % is reported on the console.
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    INTEGER, INTENT(IN) :: syt
    TYPE(DeckLine), INTENT(IN) :: ln
    TYPE(CD_LineType), INTENT(INOUT) :: lts(:)
    TYPE(CD_LineSection), INTENT(IN) :: secs(:)
    REAL(wp), INTENT(IN) :: anchor(3), fairlead(3), l0(:), factors(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(CableSolverConfig), INTENT(IN) :: static_cfg
    TYPE(GenAlphaConfig), INTENT(IN) :: dynamic_cfg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    TYPE(CD_ModelType), INTENT(INOUT) :: model
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    TYPE(CD_SyropeType) :: td
    TYPE(CD_SyropeType), ALLOCATABLE :: stype(:)
    LOGICAL, ALLOCATABLE :: sis(:)
    REAL(wp), ALLOCATABLE :: sslow(:), stmax(:), kn(:), diam(:), cn(:), t_static(:)
    REAL(wp) :: eps0, t_ref, secant, total_l0, t_hist, eps_bar, t_mean_static
    INTEGER :: ne, e, es, n_owc, iter
    CHARACTER(200) :: em
    CHARACTER(24) :: s_eps, s_lo, s_hi

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (SIZE(secs) /= 1) THEN
      CALL fail(ErrStat, ErrMsg, 'a Syrope line must be a single section (composite Syrope lines are '// &
                'not supported yet)'); RETURN
    END IF
    IF (types(syt)%ei > CD_ZERO) THEN
      CALL fail(ErrStat, ErrMsg, 'a Syrope line does not support finite-EI bending'); RETURN
    END IF
    ! A flat WtrDpth seabed floor IS supported (a taut Syrope mooring clears it, so the
    ! penalty contact stays inactive and the OWC-secant taut IC below is unchanged).
    ! Structured bathymetry and hydro loads (current/waves/host fluid) are not supported.
    IF (PRESENT(bathymetry)) THEN
      CALL fail(ErrStat, ErrMsg, 'a Syrope line does not support a structured seabed (bathymetryFile); '// &
                'use WtrDpth'); RETURN
    END IF
    IF (opts%has_current) THEN
      CALL fail(ErrStat, ErrMsg, 'a Syrope line does not support current hydro loads'); RETURN
    END IF
    IF (opts%has_wave) THEN
      CALL fail(ErrStat, ErrMsg, 'a Syrope line does not support wave hydro loads'); RETURN
    END IF
    IF (opts%external_fluid) THEN
      CALL fail(ErrStat, ErrMsg, 'a Syrope line does not support host-driven hydro loads'); RETURN
    END IF
    ! the working-curve constitutive from the parse-resolved OWC data
    CALL CD_Syrope_Init(td, types(syt)%syrope_owc_strain, types(syt)%syrope_owc_tension, &
                        types(syt)%syrope_wc_mod, types(syt)%syrope_p1, types(syt)%syrope_p2, &
                        types(syt)%syrope_alpha, types(syt)%syrope_beta, &
                        types(syt)%syrope_c1, types(syt)%syrope_c2, es, em)
    IF (es /= CD_SYROPE_OK) THEN
      CALL fail(ErrStat, ErrMsg, TRIM(em)); RETURN
    END IF
    ! geometric strain of the taut line; the working-curve tension there and the
    ! OWC secant EA that makes the static solve land at that strain
    total_l0 = SUM(l0)
    eps0 = NORM2(fairlead - anchor)/total_l0 - CD_ONE
    IF (.NOT. (eps0 > CD_ZERO)) THEN
      CALL CD_Syrope_End(td)
      CALL fail(ErrStat, ErrMsg, 'a Syrope line must be taut at init (stretched length > unstretched)'); RETURN
    END IF
    ! the OWC table must cover the initial strain: the interpolation would clamp at
    ! the end rows and the line would start silently mis-tensioned
    n_owc = SIZE(types(syt)%syrope_owc_strain)
    IF (eps0 < types(syt)%syrope_owc_strain(1) .OR. eps0 > types(syt)%syrope_owc_strain(n_owc)) THEN
      WRITE (s_eps, '(ES10.3)') eps0
      WRITE (s_lo, '(ES10.3)') types(syt)%syrope_owc_strain(1)
      WRITE (s_hi, '(ES10.3)') types(syt)%syrope_owc_strain(n_owc)
      CALL CD_Syrope_End(td)
      CALL fail(ErrStat, ErrMsg, 'the Syrope line''s initial strain '//TRIM(ADJUSTL(s_eps))// &
                ' lies outside its OWC table strain range ['//TRIM(ADJUSTL(s_lo))//', '// &
                TRIM(ADJUSTL(s_hi))//']; extend the table or reduce the pretension'); RETURN
    END IF
    ! The load history: SYROPE IC Tmax0, or (no IC) a virgin rope loaded along the OWC.
    ! The static solve uses that history's rest curve (CD_Syrope_Static_Tension: the
    ! Tmax0 working curve below its top strain, the OWC above), so the equilibrium it
    ! finds is the rest state of the SAME constitutive state the dynamics start from.
    t_hist = CD_ZERO
    IF (ln%has_syrope_ic) t_hist = ln%syrope_tmax0
    CALL rest_tension(eps0, t_ref, es, em)
    IF (es /= CD_SYROPE_OK) THEN
      CALL CD_Syrope_End(td)
      CALL fail(ErrStat, ErrMsg, 'SYROPE IC working curve: '//TRIM(em)); RETURN
    END IF
    IF (.NOT. (t_ref > CD_ZERO)) THEN
      WRITE (s_eps, '(ES10.3)') eps0
      CALL CD_Syrope_End(td)
      CALL fail(ErrStat, ErrMsg, 'the Syrope line is slack on its SYROPE IC working curve: the initial '// &
                'strain '//TRIM(ADJUSTL(s_eps))//' is below the zero-tension strain of the Tmax0 curve; '// &
                'lower Tmax0 or shorten the line'); RETURN
    END IF
    secant = t_ref/eps0
    ne = SIZE(l0)
    ALLOCATE (stype(ne), sis(ne), sslow(ne), stmax(ne), t_static(ne))
    sis = .TRUE.
    DO e = 1, ne
      stype(e) = td
    END DO
    IF (opts%has_wtrdpth) THEN
      ! flat seabed floor at -WtrDpth: build the nodal penalty stiffness (inactive for a
      ! taut line clearing the floor) so a coupled Syrope mooring inits like the EI=0 path
      ALLOCATE (diam(ne))
      diam = types(syt)%diam
      CALL CD_Nodal_Seabed_Stiffness(opts%kbot, diam, l0, kn, es, em)
      IF (es /= CD_LINE_OK) THEN
        CALL release_syrope()
        CALL fail(ErrStat, ErrMsg, 'Syrope seabed stiffness: '//TRIM(em)); RETURN
      END IF
      ! carry the SAME contact physics the EI=0 WtrDpth branch does: normal damping cn
      ! from cBot and Coulomb friction from frictionMu, so a Syrope node that reaches the
      ! floor behaves identically to a plain EI=0 line (not just the spring alone)
      ALLOCATE (cn(SIZE(kn)))
      cn = kn*(opts%cbot/opts%kbot)
    END IF
    ! Static solve with a single secant EA (the line-local type's EA: lts is rebuilt
    ! line-local by gather_line_inputs; secs(1)%line_type indexes it, NOT the global syt).
    ! The secant is iterated to the rest curve at the solved mean strain, so the static
    ! line carries the curve tension on average (a chord-strain secant misses it by the sag).
    DO iter = 1, 6
      lts(secs(1)%line_type)%ea = secant
      CALL build_model(.FALSE.)
      IF (ErrStat /= CD_MODEL_OK) EXIT
      CALL CD_Get_Model_Tension(model, t_static, es, em)
      CALL CD_End_Model(model, ErrStat, ErrMsg)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = es
        ErrMsg = em
      END IF
      IF (ErrStat /= CD_MODEL_OK) EXIT
      eps_bar = SUM(l0*t_static)/(secant*SUM(l0))
      CALL rest_tension(eps_bar, t_ref, es, em)
      IF (es /= CD_SYROPE_OK .OR. .NOT. (t_ref > CD_ZERO .AND. eps_bar > CD_ZERO)) EXIT
      IF (ABS(t_ref/eps_bar - secant) <= 1.0e-10_wp*secant) EXIT
      secant = t_ref/eps_bar
    END DO
    IF (ErrStat /= CD_MODEL_OK) THEN
      CALL release_syrope()
      ErrMsg = 'CableDyn_DeckDriver: Syrope static solve failed: '//TRIM(ErrMsg)
      IF (ErrStat /= CD_DECKDRV_BADINPUT) ErrStat = CD_DECKDRV_SOLVEFAIL
      RETURN
    END IF
    ! Per element: the running maximum is the history's (raised to the element's static
    ! tension where that exceeds it, i.e. the element sits on the OWC; without SYROPE IC
    ! every element is a virgin rope at its own static tension), and the slow strain
    ! is the state whose t = 0 kernel force at the static strain equals the static element
    ! tension exactly, so t = 0 is the static equilibrium (zero initial transient).
    DO e = 1, ne
      stmax(e) = MAX(t_hist, t_static(e))
      CALL CD_Syrope_Slow_For_Tension(td, stmax(e), t_static(e)/secant, t_static(e), sslow(e), es, em)
      IF (es /= CD_SYROPE_OK) THEN
        CALL release_syrope()
        CALL fail(ErrStat, ErrMsg, 'Syrope initial state: '//TRIM(em)); RETURN
      END IF
    END DO
    IF (ln%has_syrope_ic) THEN
      ! Tmean0 does not enter the state: with fixed ends the mean tension follows from the
      ! geometry and the Tmax0 history. Name a disagreement rather than ignore it silently.
      t_mean_static = SUM(l0*t_static)/SUM(l0)
      IF (ABS(t_mean_static - ln%syrope_tmean0) > 0.01_wp*MAX(t_mean_static, ln%syrope_tmean0)) THEN
        WRITE (*, '(A,I0,A,ES11.4,A,ES11.4,A)') 'CableDyn: SYROPE IC line ', ln%id, &
          ': static equilibrium mean tension ', t_mean_static, ' N on the Tmax0 working curve; Tmean0 ', &
          ln%syrope_tmean0, ' N is superseded (the line starts at the equilibrium)'
      END IF
    END IF
    CALL build_model(.TRUE.)
    CALL release_syrope()
    IF (ErrStat /= CD_MODEL_OK) THEN
      ErrMsg = 'CableDyn_DeckDriver: Syrope model init failed: '//TRIM(ErrMsg)
      IF (ErrStat /= CD_DECKDRV_BADINPUT) ErrStat = CD_DECKDRV_SOLVEFAIL
    END IF

  CONTAINS

    SUBROUTINE rest_tension(eps, tension, es_out, em_out)
      !! The static curve of the initial load history at strain eps: the OWC for a virgin
      !! rope (no SYROPE IC), the Tmax0 working curve / OWC (CD_Syrope_Static_Tension) with it.
      REAL(wp), INTENT(IN) :: eps
      REAL(wp), INTENT(OUT) :: tension
      INTEGER, INTENT(OUT) :: es_out
      CHARACTER(*), INTENT(OUT) :: em_out
      es_out = CD_SYROPE_OK
      em_out = ''
      IF (ln%has_syrope_ic) THEN
        CALL CD_Syrope_Static_Tension(td, t_hist, eps, tension, es_out, em_out)
      ELSE
        tension = owc_table_interp(types(syt)%syrope_owc_strain, types(syt)%syrope_owc_tension, eps)
      END IF
    END SUBROUTINE rest_tension

    SUBROUTINE build_model(with_syrope)
      !! The line build (static solve + model init) at the current secant EA; with_syrope
      !! passes the per-element Syrope states, without it the build is the plain-EA probe
      !! whose element tensions are the static solution.
      LOGICAL, INTENT(IN) :: with_syrope
      IF (opts%has_wtrdpth .AND. with_syrope) THEN
        CALL CD_Init_Line_Model(model, anchor, fairlead, lts, secs, opts%g, opts%rhoW, .FALSE., &
                                static_cfg, dynamic_cfg, factors, ErrStat, ErrMsg, &
                                dynamic_tension_only=.TRUE., anchor_is_end_b=.TRUE., &
                                seabed_z_floor=-opts%wtrdpth, seabed_kn=kn, seabed_cn=cn, &
                                seabed_cn_over_kn=opts%cbot/opts%kbot, seabed_mu=opts%friction_mu, &
                                seabed_mu_axial=opts%friction_mu_axial, &
                                seabed_kbot=opts%kbot, seabed_contact_diameter=diam, &
                                syrope_is=sis, syrope_type=stype, syrope_slow0=sslow, syrope_tmax0=stmax)
      ELSE IF (opts%has_wtrdpth) THEN
        CALL CD_Init_Line_Model(model, anchor, fairlead, lts, secs, opts%g, opts%rhoW, .FALSE., &
                                static_cfg, dynamic_cfg, factors, ErrStat, ErrMsg, &
                                dynamic_tension_only=.TRUE., anchor_is_end_b=.TRUE., &
                                seabed_z_floor=-opts%wtrdpth, seabed_kn=kn, seabed_cn=cn, &
                                seabed_cn_over_kn=opts%cbot/opts%kbot, seabed_mu=opts%friction_mu, &
                                seabed_mu_axial=opts%friction_mu_axial, &
                                seabed_kbot=opts%kbot, seabed_contact_diameter=diam)
      ELSE IF (with_syrope) THEN
        CALL CD_Init_Line_Model(model, anchor, fairlead, lts, secs, opts%g, opts%rhoW, .FALSE., &
                                static_cfg, dynamic_cfg, factors, ErrStat, ErrMsg, &
                                dynamic_tension_only=.TRUE., anchor_is_end_b=.TRUE., &
                                syrope_is=sis, syrope_type=stype, syrope_slow0=sslow, syrope_tmax0=stmax)
      ELSE
        CALL CD_Init_Line_Model(model, anchor, fairlead, lts, secs, opts%g, opts%rhoW, .FALSE., &
                                static_cfg, dynamic_cfg, factors, ErrStat, ErrMsg, &
                                dynamic_tension_only=.TRUE., anchor_is_end_b=.TRUE.)
      END IF
    END SUBROUTINE build_model

    SUBROUTINE release_syrope()
      !! Free the constitutive copies (the model deep-copies what it keeps).
      INTEGER :: k
      CALL CD_Syrope_End(td)
      DO k = 1, ne
        CALL CD_Syrope_End(stype(k))
      END DO
    END SUBROUTINE release_syrope
  END SUBROUTINE init_one_syrope_model

  PURE REAL(wp) FUNCTION owc_table_interp(xp, fp, x) RESULT(y)
    !! Piecewise-linear interpolation with constant end extrapolation (numpy
    !! interp), for the OWC strain->tension reference tension at a given strain.
    REAL(wp), INTENT(IN) :: xp(:), fp(:), x
    INTEGER :: i, n
    n = SIZE(xp)
    IF (x <= xp(1)) THEN
      y = fp(1); RETURN
    END IF
    IF (x >= xp(n)) THEN
      y = fp(n); RETURN
    END IF
    DO i = 2, n
      IF (x <= xp(i)) THEN
        y = fp(i - 1) + (fp(i) - fp(i - 1))*(x - xp(i - 1))/(xp(i) - xp(i - 1))
        RETURN
      END IF
    END DO
    y = fp(n)
  END FUNCTION owc_table_interp

  SUBROUTINE gather_line_inputs(ln, sections, types, points, lts, secs, anchor, fairlead, ErrStat, ErrMsg)
    !! Convert one validated deck line into CableDyn_Line inputs.
    TYPE(DeckLine), INTENT(IN) :: ln
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(CD_LineType), ALLOCATABLE, INTENT(OUT) :: lts(:)
    TYPE(CD_LineSection), ALLOCATABLE, INTENT(OUT) :: secs(:)
    REAL(wp), INTENT(OUT) :: anchor(3), fairlead(3)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: ns, i, j

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    anchor = points(find_point(points, ln%nodeB))%pos
    fairlead = points(find_point(points, ln%nodeA))%pos
    ns = 0
    DO j = 1, SIZE(sections)
      IF (sections(j)%line_id == ln%id) ns = ns + 1
    END DO
    IF (ns < 1) THEN
      CALL fail(ErrStat, ErrMsg, 'LINE has no SECTIONS'); RETURN
    END IF
    ALLOCATE (lts(ns), secs(ns))
    i = 0
    DO j = 1, SIZE(sections)
      IF (sections(j)%line_id /= ln%id) CYCLE
      i = i + 1
      lts(i) = CD_LineType(ea=types(sections(j)%ltype)%ea, &
                           mass_per_length=types(sections(j)%ltype)%mass, &
                           diameter=types(sections(j)%ltype)%diam, &
                           ei=types(sections(j)%ltype)%ei)
      secs(i) = CD_LineSection(line_type=i, length=sections(j)%length, n_segments=sections(j)%nsegs)
    END DO
  END SUBROUTINE gather_line_inputs

  INTEGER FUNCTION line_section_type(sections, line_id, ordinal) RESULT(type_idx)
    !! Return the resolved DeckLineType index for the `ordinal`th section of line_id.
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    INTEGER, INTENT(IN) :: line_id, ordinal
    INTEGER :: j, count
    type_idx = 0
    count = 0
    DO j = 1, SIZE(sections)
      IF (sections(j)%line_id /= line_id) CYCLE
      count = count + 1
      IF (count == ordinal) THEN
        type_idx = sections(j)%ltype
        RETURN
      END IF
    END DO
  END FUNCTION line_section_type

  SUBROUTINE end_models(models)
    !! Best-effort cleanup for partially initialized model arrays.
    TYPE(CD_ModelType), INTENT(INOUT) :: models(:)
    INTEGER :: i, es
    CHARACTER(80) :: em
    DO i = 1, SIZE(models)
      CALL CD_End_Model(models(i), es, em)
    END DO
  END SUBROUTINE end_models

  SUBROUTINE end_finite_models(models)
    !! Best-effort cleanup for finite-EI dynamic deck model arrays.
    TYPE(FiniteDeckModel), INTENT(INOUT) :: models(:)
    INTEGER :: i, es
    CHARACTER(80) :: em
    DO i = 1, SIZE(models)
      CALL CD_End_FiniteEI_Model(models(i)%model, es, em)
      IF (ALLOCATED(models(i)%l0)) DEALLOCATE (models(i)%l0)
      IF (ALLOCATED(models(i)%ea)) DEALLOCATE (models(i)%ea)
      IF (ALLOCATED(models(i)%base_f_ext)) DEALLOCATE (models(i)%base_f_ext)
      IF (ALLOCATED(models(i)%diam)) DEALLOCATE (models(i)%diam)
      IF (ALLOCATED(models(i)%cdn)) DEALLOCATE (models(i)%cdn)
      IF (ALLOCATED(models(i)%cdt)) DEALLOCATE (models(i)%cdt)
      IF (ALLOCATED(models(i)%can)) DEALLOCATE (models(i)%can)
      IF (ALLOCATED(models(i)%cat)) DEALLOCATE (models(i)%cat)
      IF (ALLOCATED(models(i)%seabed_kn)) DEALLOCATE (models(i)%seabed_kn)
      IF (ALLOCATED(models(i)%seabed_cn)) DEALLOCATE (models(i)%seabed_cn)
      IF (ALLOCATED(models(i)%q_work)) DEALLOCATE (models(i)%q_work)
      IF (ALLOCATED(models(i)%v_work)) DEALLOCATE (models(i)%v_work)
      IF (ALLOCATED(models(i)%a_work)) DEALLOCATE (models(i)%a_work)
      IF (ALLOCATED(models(i)%f_ext_work)) DEALLOCATE (models(i)%f_ext_work)
      IF (ALLOCATED(models(i)%contact_work)) DEALLOCATE (models(i)%contact_work)
      IF (ALLOCATED(models(i)%env_work)) DEALLOCATE (models(i)%env_work)
      IF (ALLOCATED(models(i)%q_fixed_work)) DEALLOCATE (models(i)%q_fixed_work)
      IF (ALLOCATED(models(i)%v_fixed_work)) DEALLOCATE (models(i)%v_fixed_work)
      IF (ALLOCATED(models(i)%a_fixed_work)) DEALLOCATE (models(i)%a_fixed_work)
      IF (ALLOCATED(models(i)%free_map_work)) DEALLOCATE (models(i)%free_map_work)
      CALL CD_End_Bathymetry(models(i)%bathymetry)
      models(i)%n_elem = 0
      models(i)%has_seabed = .FALSE.
      models(i)%has_bathymetry = .FALSE.
      models(i)%seabed_z_floor = CD_ZERO
    END DO
  END SUBROUTINE end_finite_models

  SUBROUTINE end_hermite_cables(cables)
    !! Best-effort cleanup for the standalone production finite-EI route.
    TYPE(CD_HFMF_ModuleType), ALLOCATABLE, INTENT(INOUT) :: cables(:)
    INTEGER :: i
    IF (.NOT. ALLOCATED(cables)) RETURN
    DO i = 1, SIZE(cables)
      CALL CD_HFMF_End(cables(i))
    END DO
    DEALLOCATE (cables)
  END SUBROUTINE end_hermite_cables

  SUBROUTINE build_finite_section_mesh(ln, sections, types, conn, l0, ea, mpl, diam, ei, gas, gj, i_rt, i_rn, &
                                       ErrStat, ErrMsg)
    !! Build a sectioned finite-EI mesh directly from deck sections. The EI=0
    !! CableDyn_Line mesh builder intentionally rejects EI>0, so this path owns
    !! the simple serial connectivity needed by the Cosserat model.
    TYPE(DeckLine), INTENT(IN) :: ln
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    INTEGER, ALLOCATABLE, INTENT(OUT) :: conn(:, :)
    REAL(wp), ALLOCATABLE, INTENT(OUT) :: l0(:), ea(:), mpl(:), diam(:), ei(:)
    REAL(wp), ALLOCATABLE, INTENT(OUT) :: gas(:), gj(:), i_rt(:), i_rn(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: n_elem, i, j, e, tidx

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    n_elem = 0
    DO i = 1, SIZE(sections)
      IF (sections(i)%line_id == ln%id) n_elem = n_elem + sections(i)%nsegs
    END DO
    IF (n_elem < 1) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI line has no elements')
      RETURN
    END IF
    ALLOCATE (conn(2, n_elem), l0(n_elem), ea(n_elem), mpl(n_elem), diam(n_elem), ei(n_elem))
    ALLOCATE (gas(n_elem), gj(n_elem), i_rt(n_elem), i_rn(n_elem))
    e = 0
    DO i = 1, SIZE(sections)
      IF (sections(i)%line_id /= ln%id) CYCLE
      tidx = sections(i)%ltype
      DO j = 1, sections(i)%nsegs
        e = e + 1
        conn(:, e) = [e, e + 1]
        l0(e) = sections(i)%length/REAL(sections(i)%nsegs, wp)
        ea(e) = types(tidx)%ea
        mpl(e) = types(tidx)%mass
        diam(e) = types(tidx)%diam
        ei(e) = types(tidx)%ei
        gas(e) = types(tidx)%gas
        gj(e) = types(tidx)%gj
        i_rt(e) = types(tidx)%i_rt
        i_rn(e) = types(tidx)%i_rn
      END DO
    END DO
    l0 = l0(n_elem:1:-1)
    ea = ea(n_elem:1:-1)
    mpl = mpl(n_elem:1:-1)
    diam = diam(n_elem:1:-1)
    ei = ei(n_elem:1:-1)
    gas = gas(n_elem:1:-1)
    gj = gj(n_elem:1:-1)
    i_rt = i_rt(n_elem:1:-1)
    i_rn = i_rn(n_elem:1:-1)
  END SUBROUTINE build_finite_section_mesh

  SUBROUTINE finite_raw_ba_array(ln, sections, types, ba_raw)
    !! Expand the deck's unmodified BA/-zeta values onto the original finite-EI
    !! element order. Resolution is deliberately deferred until after any Hermite
    !! remeshing so the negative-zeta convention uses each final child length.
    TYPE(DeckLine), INTENT(IN) :: ln
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    REAL(wp), INTENT(OUT) :: ba_raw(:)
    INTEGER :: i, j, e, tidx

    e = 0
    DO i = 1, SIZE(sections)
      IF (sections(i)%line_id /= ln%id) CYCLE
      tidx = sections(i)%ltype
      DO j = 1, sections(i)%nsegs
        e = e + 1
        ba_raw(e) = types(tidx)%ba
      END DO
    END DO
    ba_raw = ba_raw(SIZE(ba_raw):1:-1)
  END SUBROUTINE finite_raw_ba_array

  SUBROUTINE finite_hydro_arrays(ln, sections, types, diam, cdn, cdt, can, cat)
    !! Expand section hydro coefficients to finite-EI element arrays.
    TYPE(DeckLine), INTENT(IN) :: ln
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    REAL(wp), INTENT(OUT) :: diam(:), cdn(:), cdt(:), can(:), cat(:)
    INTEGER :: i, j, e, tidx

    e = 0
    DO i = 1, SIZE(sections)
      IF (sections(i)%line_id /= ln%id) CYCLE
      tidx = sections(i)%ltype
      DO j = 1, sections(i)%nsegs
        e = e + 1
        diam(e) = types(tidx)%diam
        cdn(e) = types(tidx)%cdn
        cdt(e) = types(tidx)%cdt
        can(e) = types(tidx)%can
        cat(e) = types(tidx)%cat
      END DO
    END DO
    diam = diam(SIZE(diam):1:-1)
    cdn = cdn(SIZE(cdn):1:-1)
    cdt = cdt(SIZE(cdt):1:-1)
    can = can(SIZE(can):1:-1)
    cat = cat(SIZE(cat):1:-1)
  END SUBROUTINE finite_hydro_arrays

  SUBROUTINE remap_elem_by_reference_arc(a, l0_parent, l0_child)
    !! Map a piecewise-constant per-element field from a parent reference mesh to
    !! any nested child mesh.  Child midpoints select the parent, so interfaces are
    !! preserved without assuming a uniform refinement factor.
    REAL(wp), ALLOCATABLE, INTENT(INOUT) :: a(:)
    REAL(wp), INTENT(IN) :: l0_parent(:), l0_child(:)
    REAL(wp), ALLOCATABLE :: b(:)
    REAL(wp) :: s_mid, s_child, s_parent_end, tol_arc
    INTEGER :: j, parent

    IF (SIZE(l0_child) == SIZE(l0_parent)) RETURN
    ALLOCATE (b(SIZE(l0_child)))
    parent = 1
    s_child = CD_ZERO
    s_parent_end = l0_parent(1)
    tol_arc = 64.0_wp*EPSILON(CD_ONE)*MAX(CD_ONE, SUM(l0_parent))
    DO j = 1, SIZE(l0_child)
      s_mid = s_child + 0.5_wp*l0_child(j)
      DO WHILE (parent < SIZE(l0_parent) .AND. s_mid > s_parent_end + tol_arc)
        parent = parent + 1
        s_parent_end = s_parent_end + l0_parent(parent)
      END DO
      b(j) = a(parent)
      s_child = s_child + l0_child(j)
    END DO
    CALL MOVE_ALLOC(b, a)
  END SUBROUTINE remap_elem_by_reference_arc

  SUBROUTINE finite_section_closure(ea, ei, mpl, diam, gas_in, gj_in, i_rt_in, i_rn_in, &
                                    gas, gj, rho_a, i_rt, i_rn, ErrStat, ErrMsg)
    !! Close deck-format finite-EI properties for the Cosserat dynamic model.
    !! The native finite-EI LINE TYPES form may provide GAs/GJ/Irt/Irn explicitly.
    !! The compatibility 10-column form leaves those values at zero; in that case
    !! use a circular section closure with nu=0.3: GAs = EA/(2(1+nu)),
    !! GJ = 2EI/(2(1+nu)), I_rho_t = m r^2/4, I_rho_n = m r^2/2.
    REAL(wp), INTENT(IN) :: ea(:), ei(:), mpl(:), diam(:)
    REAL(wp), INTENT(IN) :: gas_in(:), gj_in(:), i_rt_in(:), i_rn_in(:)
    REAL(wp), ALLOCATABLE, INTENT(OUT) :: gas(:), gj(:), rho_a(:), i_rt(:), i_rn(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    REAL(wp), PARAMETER :: nu = 0.3_wp
    INTEGER :: n, i
    REAL(wp) :: r2
    LOGICAL :: has_explicit

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    n = SIZE(ea)
    IF (SIZE(ei) /= n .OR. SIZE(mpl) /= n .OR. SIZE(diam) /= n .OR. SIZE(gas_in) /= n .OR. &
        SIZE(gj_in) /= n .OR. SIZE(i_rt_in) /= n .OR. SIZE(i_rn_in) /= n) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI property arrays must share shape')
      RETURN
    END IF
    ALLOCATE (gas(n), gj(n), rho_a(n), i_rt(n), i_rn(n))
    DO i = 1, n
      rho_a(i) = mpl(i)
      r2 = 0.25_wp*diam(i)**2
      has_explicit = MAXVAL(ABS([gas_in(i), gj_in(i), i_rt_in(i), i_rn_in(i)])) > CD_ZERO
      IF (has_explicit) THEN
        IF (.NOT. (IEEE_IS_FINITE(gas_in(i)) .AND. IEEE_IS_FINITE(gj_in(i)) .AND. &
                   IEEE_IS_FINITE(i_rt_in(i)) .AND. IEEE_IS_FINITE(i_rn_in(i))) .OR. &
            .NOT. (gas_in(i) > CD_ZERO .AND. gj_in(i) > CD_ZERO .AND. &
                   i_rt_in(i) > CD_ZERO .AND. i_rn_in(i) > CD_ZERO)) THEN
          CALL fail(ErrStat, ErrMsg, 'explicit finite-EI GAs/GJ/Irt/Irn must all be finite and positive')
          RETURN
        END IF
        gas(i) = gas_in(i)
        gj(i) = gj_in(i)
        i_rt(i) = i_rt_in(i)
        i_rn(i) = i_rn_in(i)
      ELSE
        gas(i) = ea(i)/(2.0_wp*(CD_ONE + nu))
        gj(i) = 2.0_wp*ei(i)/(2.0_wp*(CD_ONE + nu))
        i_rt(i) = 0.25_wp*mpl(i)*r2
        i_rn(i) = 0.5_wp*mpl(i)*r2
      END IF
    END DO
  END SUBROUTINE finite_section_closure

  SUBROUTINE finite_reference_and_state(anchor, fairlead, l0, nodes_ref, q0)
    !! Reference nodes follow unstretched arc length from the anchor (End B, internal node 1)
    !! along the endpoint
    !! chord; the initial position state interpolates between actual endpoints.
    !! This preserves deck rest lengths while starting from a simple held-end chord.
    REAL(wp), INTENT(IN) :: anchor(3), fairlead(3), l0(:)
    REAL(wp), INTENT(OUT) :: nodes_ref(:, :), q0(:)
    INTEGER :: i, ne
    REAL(wp) :: chord(3), dir(3), chord_len, total, cum, frac

    ne = SIZE(l0)
    chord = fairlead - anchor
    chord_len = SQRT(DOT_PRODUCT(chord, chord))
    IF (chord_len > 100.0_wp*EPSILON(CD_ONE)) THEN
      dir = chord/chord_len
    ELSE
      dir = [CD_ZERO, CD_ZERO, CD_ONE]
    END IF
    total = SUM(l0)
    cum = CD_ZERO
    nodes_ref(:, 1) = anchor
    q0 = CD_ZERO
    q0(1:3) = anchor
    DO i = 1, ne
      cum = cum + l0(i)
      frac = cum/total
      nodes_ref(:, i + 1) = anchor + cum*dir
      q0(6*i + 1:6*i + 3) = anchor + frac*chord
    END DO
  END SUBROUTINE finite_reference_and_state

  SUBROUTINE finite_lazy_wave_reference_and_state(anchor, fairlead, l0, nodes_ref, q0, ErrStat, ErrMsg)
    !! Build a cubic-Hermite arch seed for a held-end finite-EI lazy-wave line.
    !!
    !! The deck format does not expose user endpoint slopes, so this seed uses the
    !! vertical lift direction orthogonal to the endpoint chord: the anchor tangent
    !! initially climbs away from the chord and the fairlead tangent returns toward it.
    !! Equilibrium is still governed by the finite-EI dynamic model and its loads.
    REAL(wp), INTENT(IN) :: anchor(3), fairlead(3), l0(:)
    REAL(wp), INTENT(OUT) :: nodes_ref(:, :), q0(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    REAL(wp), ALLOCATABLE :: arc(:), curvature(:)
    REAL(wp) :: chord(3), chord_len, chord_dir(3), lift(3), lift_norm, tan_a(3), tan_b(3)
    REAL(wp) :: handle_scale
    INTEGER :: nnode, es
    CHARACTER(200) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    nnode = SIZE(l0) + 1
    IF (SIZE(q0) /= 6*nnode .OR. SIZE(nodes_ref, 1) /= 3 .OR. SIZE(nodes_ref, 2) /= nnode) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI lazy-wave seed shape mismatch')
      RETURN
    END IF
    chord = fairlead - anchor
    chord_len = SQRT(DOT_PRODUCT(chord, chord))
    IF (chord_len <= 100.0_wp*EPSILON(CD_ONE)) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI lazy-wave endpoints are coincident')
      RETURN
    END IF
    chord_dir = chord/chord_len
    lift = [CD_ZERO, CD_ZERO, CD_ONE] - DOT_PRODUCT([CD_ZERO, CD_ZERO, CD_ONE], chord_dir)*chord_dir
    lift_norm = SQRT(DOT_PRODUCT(lift, lift))
    IF (lift_norm <= 100.0_wp*EPSILON(CD_ONE)) THEN
      lift = [CD_ONE, CD_ZERO, CD_ZERO] - DOT_PRODUCT([CD_ONE, CD_ZERO, CD_ZERO], chord_dir)*chord_dir
      lift_norm = SQRT(DOT_PRODUCT(lift, lift))
    END IF
    IF (lift_norm <= 100.0_wp*EPSILON(CD_ONE)) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI lazy-wave lift direction is degenerate')
      RETURN
    END IF
    lift = lift/lift_norm
    tan_a = chord_dir + lift
    tan_b = chord_dir - lift
    ALLOCATE (arc(nnode), curvature(nnode))
    CALL CD_FiniteEI_Hermite_Arch_Seed_LengthMatched(anchor, fairlead, tan_a, tan_b, l0, q0, nodes_ref, &
                                                     arc, curvature, handle_scale, es, em)
    IF (es /= CD_HARCH_OK) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI lazy-wave Hermite seed failed: '//TRIM(em))
      RETURN
    END IF
  END SUBROUTINE finite_lazy_wave_reference_and_state

  SUBROUTINE pack_translational_load(f3, f6)
    !! Map a 3-DOF/node force vector into the translational slots of a 6-DOF/node
    !! finite-EI generalized force vector.
    REAL(wp), INTENT(IN) :: f3(:)
    REAL(wp), INTENT(INOUT) :: f6(:)
    INTEGER :: i, nnode

    nnode = SIZE(f3)/3
    DO i = 1, nnode
      f6(6*i - 5:6*i - 3) = f3(3*i - 2:3*i)
    END DO
  END SUBROUTINE pack_translational_load

  SUBROUTINE finite_seabed_contact_force(q, v, z_floor, kn, cn, mu, f_ext, ErrStat, ErrMsg)
    !! One-sided normal seabed force packed into the translational z DOF of the
    !! 6-DOF/node finite-EI state. The damper engages only for downward velocity;
    !! regularized kinetic friction opposes horizontal slip using the active normal
    !! reaction.
    REAL(wp), INTENT(IN) :: q(:), v(:), z_floor, kn(:), cn(:), mu
    REAL(wp), INTENT(OUT) :: f_ext(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: nnode, i, ix, iy, iz
    REAL(wp), PARAMETER :: vreg = 1.0e-3_wp
    REAL(wp) :: gap, normal, normal_tangent, gate, gate_tangent, denom

    f_ext = CD_ZERO
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (MOD(SIZE(q), 6) /= 0 .OR. SIZE(v) /= SIZE(q) .OR. SIZE(f_ext) /= SIZE(q)) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI seabed state/load shapes must be 6*n_nodes')
      RETURN
    END IF
    nnode = SIZE(q)/6
    IF (SIZE(kn) /= nnode .OR. SIZE(cn) /= nnode) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI seabed arrays must have length n_nodes')
      RETURN
    END IF
    IF (.NOT. (ALL(IEEE_IS_FINITE(q)) .AND. ALL(IEEE_IS_FINITE(v)) .AND. IEEE_IS_FINITE(z_floor) .AND. &
               ALL(IEEE_IS_FINITE(kn)) .AND. ALL(IEEE_IS_FINITE(cn))) .OR. &
        .NOT. IEEE_IS_FINITE(mu) .OR. ANY(kn <= CD_ZERO) .OR. ANY(cn < CD_ZERO) .OR. mu < CD_ZERO) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI seabed inputs must be finite with kn > 0, cn >= 0, and mu >= 0')
      RETURN
    END IF
    DO i = 1, nnode
      ix = 6*i - 5
      iy = 6*i - 4
      iz = 6*i - 3
      gap = z_floor - q(iz)
      CALL CD_Seabed_Normal_Law(gap, kn(i), normal, normal_tangent)
      CALL CD_Seabed_Contact_Gate(gap, gate, gate_tangent)
      IF (normal <= CD_ZERO .AND. gate <= CD_ZERO) CYCLE
      IF (v(iz) < CD_ZERO) normal = normal - cn(i)*gate*v(iz)
      IF (mu > CD_ZERO) THEN
        denom = SQRT(v(ix)**2 + v(iy)**2 + vreg**2)
        f_ext(ix) = -mu*normal*v(ix)/denom
        f_ext(iy) = -mu*normal*v(iy)/denom
      END IF
      f_ext(iz) = normal
    END DO
  END SUBROUTINE finite_seabed_contact_force

  SUBROUTINE finite_bathymetry_contact_force(q, v, bathymetry, kn, cn, mu, f_ext, ErrStat, ErrMsg)
    !! One-sided finite-EI translational seabed contact against a structured
    !! bathymetry floor. The force law is the same as finite_seabed_contact_force,
    !! with z_floor evaluated at each node's current x/y.
    REAL(wp), INTENT(IN) :: q(:), v(:), kn(:), cn(:), mu
    TYPE(CD_BathymetryType), INTENT(IN) :: bathymetry
    REAL(wp), INTENT(OUT) :: f_ext(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: nnode, i, ix, iy, iz, es
    REAL(wp), PARAMETER :: vreg = 1.0e-3_wp
    REAL(wp) :: z_floor, gap, normal, normal_tangent, gate, gate_tangent, denom
    CHARACTER(160) :: em

    f_ext = CD_ZERO
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (MOD(SIZE(q), 6) /= 0 .OR. SIZE(v) /= SIZE(q) .OR. SIZE(f_ext) /= SIZE(q)) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI bathymetry contact state/load shapes must be 6*n_nodes')
      RETURN
    END IF
    nnode = SIZE(q)/6
    IF (SIZE(kn) /= nnode .OR. SIZE(cn) /= nnode) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI bathymetry contact arrays must have length n_nodes')
      RETURN
    END IF
    IF (.NOT. CD_Bathymetry_Is_Initialized(bathymetry)) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI bathymetry contact requires initialized bathymetry')
      RETURN
    END IF
    IF (.NOT. (ALL(IEEE_IS_FINITE(q)) .AND. ALL(IEEE_IS_FINITE(v)) .AND. &
               ALL(IEEE_IS_FINITE(kn)) .AND. ALL(IEEE_IS_FINITE(cn))) .OR. &
        .NOT. IEEE_IS_FINITE(mu) .OR. ANY(kn <= CD_ZERO) .OR. ANY(cn < CD_ZERO) .OR. mu < CD_ZERO) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI bathymetry contact inputs must be finite with kn > 0, cn >= 0, and mu >= 0')
      RETURN
    END IF
    DO i = 1, nnode
      ix = 6*i - 5
      iy = ix + 1
      iz = ix + 2
      CALL CD_Bathymetry_Floor(bathymetry, q(ix), q(iy), z_floor, es, em)
      IF (es /= CD_BATHY_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'finite-EI bathymetry floor query failed: '//TRIM(em))
        RETURN
      END IF
      gap = z_floor - q(iz)
      CALL CD_Seabed_Normal_Law(gap, kn(i), normal, normal_tangent)
      CALL CD_Seabed_Contact_Gate(gap, gate, gate_tangent)
      IF (normal <= CD_ZERO .AND. gate <= CD_ZERO) CYCLE
      IF (v(iz) < CD_ZERO) normal = normal - cn(i)*gate*v(iz)
      IF (mu > CD_ZERO) THEN
        denom = SQRT(v(ix)**2 + v(iy)**2 + vreg**2)
        f_ext(ix) = -mu*normal*v(ix)/denom
        f_ext(iy) = -mu*normal*v(iy)/denom
      END IF
      f_ext(iz) = normal
    END DO
  END SUBROUTINE finite_bathymetry_contact_force

  SUBROUTINE finite_seabed_contact_load_banded(q, v, z_floor, kn, cn, mu, free, kl, ku, free_map, &
                                               f_ext, jac_q_band, jac_v_band, ErrStat, ErrMsg)
    !! Finite-EI flat-seabed contact force and reduced free/free residual
    !! Jacobian bands. jac_* use the integrator callback convention:
    !! -d(force)/dq and -d(force)/dv.
    REAL(wp), INTENT(IN) :: q(:), v(:), z_floor, kn(:), cn(:), mu
    INTEGER, INTENT(IN) :: free(:), kl, ku
    INTEGER, INTENT(INOUT) :: free_map(:)
    REAL(wp), INTENT(OUT) :: f_ext(:), jac_q_band(:, :), jac_v_band(:, :)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: nnode, i, ix, iy, iz

    CALL init_finite_contact_band(q, v, kn, cn, mu, free, kl, ku, free_map, f_ext, jac_q_band, jac_v_band, &
                                  nnode, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    IF (.NOT. IEEE_IS_FINITE(z_floor)) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI seabed contact floor must be finite')
      RETURN
    END IF
    DO i = 1, nnode
      ix = 6*i - 5
      iy = ix + 1
      iz = ix + 2
      CALL add_finite_contact_node(q, v, ix, iy, iz, z_floor, CD_ZERO, CD_ZERO, kn(i), cn(i), mu, &
                                   free_map, kl, ku, f_ext, jac_q_band, jac_v_band, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END DO
  END SUBROUTINE finite_seabed_contact_load_banded

  SUBROUTINE finite_bathymetry_contact_load_banded(q, v, bathymetry, kn, cn, mu, free, kl, ku, free_map, &
                                                   f_ext, jac_q_band, jac_v_band, ErrStat, ErrMsg)
    !! Finite-EI bathymetry contact force and reduced free/free residual
    !! Jacobian bands, including floor-slope terms in dgap/dx and dgap/dy.
    REAL(wp), INTENT(IN) :: q(:), v(:), kn(:), cn(:), mu
    TYPE(CD_BathymetryType), INTENT(IN) :: bathymetry
    INTEGER, INTENT(IN) :: free(:), kl, ku
    INTEGER, INTENT(INOUT) :: free_map(:)
    REAL(wp), INTENT(OUT) :: f_ext(:), jac_q_band(:, :), jac_v_band(:, :)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: nnode, i, ix, iy, iz, es
    REAL(wp) :: z_floor, dfdx, dfdy
    CHARACTER(160) :: em

    CALL init_finite_contact_band(q, v, kn, cn, mu, free, kl, ku, free_map, f_ext, jac_q_band, jac_v_band, &
                                  nnode, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    IF (.NOT. CD_Bathymetry_Is_Initialized(bathymetry)) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI bathymetry contact requires initialized bathymetry')
      RETURN
    END IF
    DO i = 1, nnode
      ix = 6*i - 5
      iy = ix + 1
      iz = ix + 2
      CALL CD_Bathymetry_Floor_Gradient(bathymetry, q(ix), q(iy), z_floor, dfdx, dfdy, es, em)
      IF (es /= CD_BATHY_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'finite-EI bathymetry floor-gradient query failed: '//TRIM(em))
        RETURN
      END IF
      CALL add_finite_contact_node(q, v, ix, iy, iz, z_floor, dfdx, dfdy, kn(i), cn(i), mu, &
                                   free_map, kl, ku, f_ext, jac_q_band, jac_v_band, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END DO
  END SUBROUTINE finite_bathymetry_contact_load_banded

  SUBROUTINE init_finite_contact_band(q, v, kn, cn, mu, free, kl, ku, free_map, f_ext, jac_q_band, jac_v_band, &
                                      nnode, ErrStat, ErrMsg)
    !! Validate finite-EI contact state and build a persistent global-to-free map
    !! for direct band scatter.
    REAL(wp), INTENT(IN) :: q(:), v(:), kn(:), cn(:), mu
    INTEGER, INTENT(IN) :: free(:), kl, ku
    INTEGER, INTENT(INOUT) :: free_map(:)
    REAL(wp), INTENT(OUT) :: f_ext(:), jac_q_band(:, :), jac_v_band(:, :)
    INTEGER, INTENT(OUT) :: nnode, ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i, ndof, ldab

    f_ext = CD_ZERO
    jac_q_band = CD_ZERO
    jac_v_band = CD_ZERO
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    nnode = 0
    ndof = SIZE(q)
    ldab = 2*kl + ku + 1
    IF (MOD(ndof, 6) /= 0 .OR. SIZE(v) /= ndof .OR. SIZE(f_ext) /= ndof) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI contact state/load shapes must be 6*n_nodes')
      RETURN
    END IF
    nnode = ndof/6
    IF (SIZE(kn) /= nnode .OR. SIZE(cn) /= nnode) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI contact arrays must have length n_nodes')
      RETURN
    END IF
    IF (SIZE(free_map) < ndof .OR. SIZE(jac_q_band, 1) < ldab .OR. SIZE(jac_q_band, 2) /= SIZE(free) .OR. &
        SIZE(jac_v_band, 1) < ldab .OR. SIZE(jac_v_band, 2) /= SIZE(free)) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI contact band workspace shape mismatch')
      RETURN
    END IF
    IF (kl < 0 .OR. ku < 0 .OR. ANY(free < 1) .OR. ANY(free > ndof)) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI contact free-DOF map is invalid')
      RETURN
    END IF
    IF (.NOT. (ALL(IEEE_IS_FINITE(q)) .AND. ALL(IEEE_IS_FINITE(v)) .AND. &
               ALL(IEEE_IS_FINITE(kn)) .AND. ALL(IEEE_IS_FINITE(cn))) .OR. &
        .NOT. IEEE_IS_FINITE(mu) .OR. ANY(kn <= CD_ZERO) .OR. ANY(cn < CD_ZERO) .OR. mu < CD_ZERO) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI contact inputs must be finite with kn > 0, cn >= 0, and mu >= 0')
      RETURN
    END IF
    free_map(1:ndof) = 0
    DO i = 1, SIZE(free)
      IF (free_map(free(i)) /= 0) THEN
        CALL fail(ErrStat, ErrMsg, 'finite-EI contact free-DOF map contains a duplicate')
        RETURN
      END IF
      free_map(free(i)) = i
    END DO
  END SUBROUTINE init_finite_contact_band

  SUBROUTINE add_finite_contact_node(q, v, ix, iy, iz, z_floor, dfdx, dfdy, kn, cn, mu, &
                                     free_map, kl, ku, f_ext, jac_q_band, jac_v_band, ErrStat, ErrMsg)
    !! Scatter one finite-EI contact node into force and reduced banded residual tangents.
    REAL(wp), INTENT(IN) :: q(:), v(:), z_floor, dfdx, dfdy, kn, cn, mu
    INTEGER, INTENT(IN) :: ix, iy, iz, free_map(:), kl, ku
    REAL(wp), INTENT(INOUT) :: f_ext(:), jac_q_band(:, :), jac_v_band(:, :)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    REAL(wp), PARAMETER :: vreg = 1.0e-3_wp
    REAL(wp) :: gap, normal, normal_gap, gate, gate_gap, denom, denom3
    REAL(wp) :: dnormal_dgap, dnormal_dvz, dnormal_dq(3)
    REAL(wp) :: vx, vy, coeff_x, coeff_y

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    gap = z_floor - q(iz)
    CALL CD_Seabed_Normal_Law(gap, kn, normal, normal_gap)
    CALL CD_Seabed_Contact_Gate(gap, gate, gate_gap)
    dnormal_dgap = normal_gap
    dnormal_dvz = CD_ZERO
    IF (normal <= CD_ZERO .AND. gate <= CD_ZERO) RETURN
    IF (v(iz) < CD_ZERO) THEN
      normal = normal - cn*gate*v(iz)
      dnormal_dgap = dnormal_dgap - cn*gate_gap*v(iz)
      dnormal_dvz = -cn*gate
    END IF

    dnormal_dq = dnormal_dgap*[dfdx, dfdy, -CD_ONE]
    f_ext(iz) = f_ext(iz) + normal
    CALL scatter_finite_contact_band(jac_q_band, free_map, kl, ku, iz, ix, -dnormal_dq(1), ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL scatter_finite_contact_band(jac_q_band, free_map, kl, ku, iz, iy, -dnormal_dq(2), ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL scatter_finite_contact_band(jac_q_band, free_map, kl, ku, iz, iz, -dnormal_dq(3), ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL scatter_finite_contact_band(jac_v_band, free_map, kl, ku, iz, iz, -dnormal_dvz, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN

    IF (mu <= CD_ZERO) RETURN
    vx = v(ix)
    vy = v(iy)
    denom = SQRT(vx*vx + vy*vy + vreg*vreg)
    denom3 = denom*denom*denom
    f_ext(ix) = f_ext(ix) - mu*normal*vx/denom
    f_ext(iy) = f_ext(iy) - mu*normal*vy/denom

    coeff_x = mu*vx/denom
    coeff_y = mu*vy/denom
    CALL scatter_finite_contact_band(jac_q_band, free_map, kl, ku, ix, ix, coeff_x*dnormal_dq(1), ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL scatter_finite_contact_band(jac_q_band, free_map, kl, ku, ix, iy, coeff_x*dnormal_dq(2), ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL scatter_finite_contact_band(jac_q_band, free_map, kl, ku, ix, iz, coeff_x*dnormal_dq(3), ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL scatter_finite_contact_band(jac_q_band, free_map, kl, ku, iy, ix, coeff_y*dnormal_dq(1), ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL scatter_finite_contact_band(jac_q_band, free_map, kl, ku, iy, iy, coeff_y*dnormal_dq(2), ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL scatter_finite_contact_band(jac_q_band, free_map, kl, ku, iy, iz, coeff_y*dnormal_dq(3), ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN

    CALL scatter_finite_contact_band(jac_v_band, free_map, kl, ku, ix, ix, &
                                     mu*normal*(vy*vy + vreg*vreg)/denom3, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL scatter_finite_contact_band(jac_v_band, free_map, kl, ku, ix, iy, &
                                     -mu*normal*vx*vy/denom3, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL scatter_finite_contact_band(jac_v_band, free_map, kl, ku, iy, ix, &
                                     -mu*normal*vx*vy/denom3, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL scatter_finite_contact_band(jac_v_band, free_map, kl, ku, iy, iy, &
                                     mu*normal*(vx*vx + vreg*vreg)/denom3, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL scatter_finite_contact_band(jac_v_band, free_map, kl, ku, ix, iz, coeff_x*dnormal_dvz, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL scatter_finite_contact_band(jac_v_band, free_map, kl, ku, iy, iz, coeff_y*dnormal_dvz, ErrStat, ErrMsg)
  END SUBROUTINE add_finite_contact_node

  SUBROUTINE scatter_finite_contact_band(ab, free_map, kl, ku, row_dof, col_dof, value, ErrStat, ErrMsg)
    !! Add one global residual-Jacobian entry into reduced LAPACK band storage.
    REAL(wp), INTENT(INOUT) :: ab(:, :)
    INTEGER, INTENT(IN) :: free_map(:), kl, ku, row_dof, col_dof
    REAL(wp), INTENT(IN) :: value
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: irow, jcol, brow

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (row_dof < 1 .OR. row_dof > SIZE(free_map) .OR. col_dof < 1 .OR. col_dof > SIZE(free_map)) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI contact band scatter DOF out of range')
      RETURN
    END IF
    irow = free_map(row_dof)
    jcol = free_map(col_dof)
    IF (irow == 0 .OR. jcol == 0) RETURN
    brow = kl + ku + 1 + irow - jcol
    IF (brow < 1 .OR. brow > SIZE(ab, 1) .OR. jcol > SIZE(ab, 2)) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI contact tangent exceeds reduced bandwidth')
      RETURN
    END IF
    ab(brow, jcol) = ab(brow, jcol) + value
  END SUBROUTINE scatter_finite_contact_band

  SUBROUTINE finite_environment_force(model, opts, time, q, v, f_ext, ErrStat, ErrMsg)
    !! Translational Morison/FK environmental load for finite-EI deck dynamics.
    !! The force uses the same two-node wet-subsegment kernels as the EI=0 path,
    !! scattered only into translational DOFs. Rotational hydrodynamic moments
    !! are not supported on the finite-EI deck path.
    TYPE(FiniteDeckModel), INTENT(IN) :: model
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time, q(:), v(:)
    REAL(wp), INTENT(OUT) :: f_ext(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: e, a, b, ia, ib, es
    INTEGER :: idx(6)
    REAL(wp) :: xa(3), xb(3), va(3), vb(3), eta_a, eta_b
    REAL(wp) :: fluid_a(3), fluid_b(3), accel_a(3), accel_b(3), f2(6)
    CHARACTER(160) :: em

    f_ext = CD_ZERO
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (.NOT. (opts%has_current .OR. opts%has_wave)) RETURN
    IF (SIZE(q) /= SIZE(v) .OR. SIZE(f_ext) /= SIZE(q) .OR. MOD(SIZE(q), 6) /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI hydro state/load shapes must be 6*n_nodes')
      RETURN
    END IF
    DO e = 1, model%n_elem
      a = e
      b = e + 1
      ia = 6*a - 5
      ib = 6*b - 5
      xa = q(ia:ia + 2)
      xb = q(ib:ib + 2)
      va = v(ia:ia + 2)
      vb = v(ib:ib + 2)
      idx = [ia, ia + 1, ia + 2, ib, ib + 1, ib + 2]
      CALL finite_environment_node(opts, time, xa, eta_a, fluid_a, accel_a, es, em)
      IF (es /= CD_HYDRO_OK) THEN
        ErrStat = CD_DECKDRV_BADINPUT
        ErrMsg = 'CableDyn_DeckDriver: finite-EI environment node A failed: '//TRIM(em)
        RETURN
      END IF
      CALL finite_environment_node(opts, time, xb, eta_b, fluid_b, accel_b, es, em)
      IF (es /= CD_HYDRO_OK) THEN
        ErrStat = CD_DECKDRV_BADINPUT
        ErrMsg = 'CableDyn_DeckDriver: finite-EI environment node B failed: '//TRIM(em)
        RETURN
      END IF
      CALL CD_Morison_Drag_Element_Force(xa, xb, va, vb, model%l0(e), fluid_a, fluid_b, eta_a, eta_b, &
                                         opts%rhoW, model%diam(e), model%cdn(e), model%cdt(e), f2, es, em)
      IF (es /= CD_HYDRO_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: finite-EI drag element failed: '//TRIM(em)
        RETURN
      END IF
      f_ext(idx) = f_ext(idx) + f2
      IF (opts%has_wave) THEN
        CALL CD_Froude_Krylov_Element_Force(xa, xb, va, vb, model%l0(e), accel_a, accel_b, eta_a, eta_b, &
                                            opts%rhoW, model%diam(e), model%can(e), model%cat(e), f2, es, em)
        IF (es /= CD_HYDRO_OK) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: finite-EI FK element failed: '//TRIM(em)
          RETURN
        END IF
        f_ext(idx) = f_ext(idx) + f2
      END IF
    END DO
  END SUBROUTINE finite_environment_force

  SUBROUTINE finite_environment_load_banded(model, opts, time, q, v, free, kl, ku, free_map, &
                                            force, jac_q_band, jac_v_band, ErrStat, ErrMsg)
    !! Add finite-EI translational current/wave load plus reduced banded Jacobian.
    TYPE(FiniteDeckModel), INTENT(IN) :: model
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time, q(:), v(:)
    INTEGER, INTENT(IN) :: free(:), kl, ku
    INTEGER, INTENT(INOUT) :: free_map(:)
    REAL(wp), INTENT(INOUT) :: force(:), jac_q_band(:, :), jac_v_band(:, :)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: e, a, b, ia, ib, irow, jcol, es
    INTEGER :: idx(6)
    REAL(wp) :: xa(3), xb(3), va(3), vb(3), eta_a, eta_b
    REAL(wp) :: fluid_a(3), fluid_b(3), accel_a(3), accel_b(3), f2(6), jq2(6, 6), jv2(6, 6)
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (.NOT. (opts%has_current .OR. opts%has_wave)) RETURN
    IF (SIZE(q) /= SIZE(v) .OR. SIZE(force) /= SIZE(q) .OR. MOD(SIZE(q), 6) /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI hydro tangent state/load shapes must be 6*n_nodes')
      RETURN
    END IF
    IF (SIZE(free_map) < SIZE(q)) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI hydro tangent free map is undersized')
      RETURN
    END IF
    free_map(1:SIZE(q)) = 0
    DO irow = 1, SIZE(free)
      IF (free(irow) < 1 .OR. free(irow) > SIZE(q)) THEN
        CALL fail(ErrStat, ErrMsg, 'finite-EI hydro tangent free DOF out of range')
        RETURN
      END IF
      free_map(free(irow)) = irow
    END DO
    DO e = 1, model%n_elem
      a = e
      b = e + 1
      ia = 6*a - 5
      ib = 6*b - 5
      idx = [ia, ia + 1, ia + 2, ib, ib + 1, ib + 2]
      xa = q(ia:ia + 2)
      xb = q(ib:ib + 2)
      va = v(ia:ia + 2)
      vb = v(ib:ib + 2)
      CALL finite_environment_node(opts, time, xa, eta_a, fluid_a, accel_a, es, em)
      IF (es /= CD_HYDRO_OK) THEN
        ErrStat = CD_DECKDRV_BADINPUT
        ErrMsg = 'CableDyn_DeckDriver: finite-EI tangent node A failed: '//TRIM(em)
        RETURN
      END IF
      CALL finite_environment_node(opts, time, xb, eta_b, fluid_b, accel_b, es, em)
      IF (es /= CD_HYDRO_OK) THEN
        ErrStat = CD_DECKDRV_BADINPUT
        ErrMsg = 'CableDyn_DeckDriver: finite-EI tangent node B failed: '//TRIM(em)
        RETURN
      END IF
      CALL CD_Morison_Drag_Element_Load(xa, xb, va, vb, model%l0(e), fluid_a, fluid_b, eta_a, eta_b, &
                                        opts%rhoW, model%diam(e), model%cdn(e), model%cdt(e), &
                                        f2, jq2, jv2, es, em)
      IF (es /= CD_HYDRO_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: finite-EI drag tangent failed: '//TRIM(em)
        RETURN
      END IF
      force(idx) = force(idx) + f2
      DO jcol = 1, 6
        DO irow = 1, 6
          CALL scatter_finite_contact_band(jac_q_band, free_map, kl, ku, idx(irow), idx(jcol), &
                                           jq2(irow, jcol), ErrStat, ErrMsg)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
          CALL scatter_finite_contact_band(jac_v_band, free_map, kl, ku, idx(irow), idx(jcol), &
                                           jv2(irow, jcol), ErrStat, ErrMsg)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
        END DO
      END DO
      IF (opts%has_wave) THEN
        CALL CD_Froude_Krylov_Element_Load(xa, xb, va, vb, model%l0(e), accel_a, accel_b, eta_a, eta_b, &
                                           opts%rhoW, model%diam(e), model%can(e), model%cat(e), &
                                           f2, jq2, jv2, es, em)
        IF (es /= CD_HYDRO_OK) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: finite-EI FK tangent failed: '//TRIM(em)
          RETURN
        END IF
        force(idx) = force(idx) + f2
        DO jcol = 1, 6
          DO irow = 1, 6
            CALL scatter_finite_contact_band(jac_q_band, free_map, kl, ku, idx(irow), idx(jcol), &
                                             jq2(irow, jcol), ErrStat, ErrMsg)
            IF (ErrStat /= CD_DECKDRV_OK) RETURN
            CALL scatter_finite_contact_band(jac_v_band, free_map, kl, ku, idx(irow), idx(jcol), &
                                             jv2(irow, jcol), ErrStat, ErrMsg)
            IF (ErrStat /= CD_DECKDRV_OK) RETURN
          END DO
        END DO
      END IF
    END DO
  END SUBROUTINE finite_environment_load_banded

  SUBROUTINE finite_environment_node(opts, time, x, eta, fluid_velocity, fluid_acceleration, ErrStat, ErrMsg)
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time, x(3)
    REAL(wp), INTENT(OUT) :: eta, fluid_velocity(3), fluid_acceleration(3)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp) :: current_velocity(3)
    INTEGER :: es
    CHARACTER(160) :: em

    eta = CD_ZERO
    fluid_velocity = CD_ZERO
    fluid_acceleration = CD_ZERO
    ErrStat = CD_HYDRO_OK
    ErrMsg = ''
    IF (opts%has_wave) THEN
      CALL deck_wave_kinematics(opts, x(1), x(2), x(3), time, eta, fluid_velocity, fluid_acceleration, es, em)
      IF (es /= CD_HYDRO_OK) THEN
        ErrStat = es
        ErrMsg = em
        RETURN
      END IF
    END IF
    IF (opts%has_current) THEN
      current_velocity = deck_current_velocity(opts, x(3), es, em)
      IF (es /= CD_HYDRO_OK) THEN
        ErrStat = es
        ErrMsg = em
        RETURN
      END IF
      fluid_velocity = fluid_velocity + current_velocity
    END IF
  END SUBROUTINE finite_environment_node

  SUBROUTINE solve_point_equilibrium(types, points, lines, sections, opts, ErrStat, ErrMsg, bathymetry)
    !! Static force balance of the Free/Connect points: find the positions at which the
    !! forces of every attached line (each line re-solved to its tension-only static
    !! equilibrium for the current end positions), the point's own weight and buoyancy
    !! ((rhoW Vol - Mass) g) and its steady-current drag (0.5 rhoW CdA |u| u) sum to zero.
    !! The solve is solve_body_equilibrium with points_only: Newton (Levenberg-Marquardt)
    !! iteration on the stacked point positions from the deck positions, with the analytic
    !! condensed end stiffness of every attached line and warm-started line re-solves.
    !! points(:)%pos is updated in place. Points with no attached line, and decks whose moving
    !! points carry a finite-EI or Syrope line (no moving-end static solve there), keep their
    !! deck positions with a warning. A point that does not reach force balance fails closed
    !! with the point id and its residual.
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckPoint), INTENT(INOUT) :: points(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    INTEGER, ALLOCATABLE :: pidx(:)
    TYPE(DeckBody) :: no_bodies(0)
    TYPE(DeckRodType) :: no_rod_types(0)
    TYPE(DeckRod) :: no_rods(0)
    INTEGER :: np, i, j, k
    LOGICAL :: moving

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    np = 0
    DO i = 1, SIZE(points)
      IF (point_moves(i)) np = np + 1
    END DO
    IF (np == 0) RETURN
    ALLOCATE (pidx(np))
    np = 0
    DO i = 1, SIZE(points)
      IF (point_moves(i)) THEN
        np = np + 1
        pidx(np) = i
      END IF
    END DO
    ! every line attached to a moving point must be an EI=0, non-Syrope line
    DO j = 1, SIZE(lines)
      moving = .FALSE.
      DO k = 1, np
        IF (lines(j)%nodeA == points(pidx(k))%id .OR. lines(j)%nodeB == points(pidx(k))%id) moving = .TRUE.
      END DO
      IF (.NOT. moving) CYCLE
      DO i = 1, SIZE(sections)
        IF (sections(i)%line_id /= lines(j)%id) CYCLE
        IF (types(sections(i)%ltype)%is_syrope .OR. types(sections(i)%ltype)%ei > CD_ZERO) THEN
          WRITE (output_unit, '(A)') ' WARNING: Free/Connect points are held at their deck positions in the '// &
            'initial condition: LINE '//TRIM(int_to_str(lines(j)%id))//' (finite-EI or Syrope) has no '// &
            'moving-end static solve'
          RETURN
        END IF
      END DO
    END DO
    CALL solve_body_equilibrium(types, no_bodies, no_rod_types, no_rods, points, lines, sections, opts, ErrStat, &
                                ErrMsg, bathymetry, points_only=.TRUE.)

  CONTAINS

    LOGICAL FUNCTION point_moves(ip) RESULT(mv)
      INTEGER, INTENT(IN) :: ip
      INTEGER :: jl
      mv = .FALSE.
      IF (TRIM(points(ip)%ptype) /= 'free' .AND. TRIM(points(ip)%ptype) /= 'connect') RETURN
      DO jl = 1, SIZE(lines)
        IF (lines(jl)%nodeA == points(ip)%id .OR. lines(jl)%nodeB == points(ip)%id) mv = .TRUE.
      END DO
    END FUNCTION point_moves
  END SUBROUTINE solve_point_equilibrium

  SUBROUTINE print_static_input_warnings(types, points, lines, sections, opts)
    !! Standard-output WARNINGS (never failures) for admissible but non-physical or
    !! questionable inputs: a line end above the still-water level (the line is modelled
    !! fully submerged), a line type that sinks into the penalty seabed by more than its
    !! diameter (kBot too soft for its submerged weight), a slack anchored line that hangs
    !! below its anchor on a deck with no seabed (reported after the static solve by
    !! warn_line_below_anchor), and a line with fewer than three segments (a straight
    !! chord: a slack coarse line carries no tension).
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    INTEGER :: i, j, k, nseg
    REAL(wp) :: w, pen
    CHARACTER(32) :: b1, b2

    DO i = 1, SIZE(lines)
      DO k = 1, 2
        IF (k == 1) j = find_point(points, lines(i)%nodeA)
        IF (k == 2) j = find_point(points, lines(i)%nodeB)
        IF (j < 1) CYCLE
        IF (points(j)%pos(3) > CD_ZERO) THEN
          WRITE (b1, '(ES10.3)') points(j)%pos(3)
          WRITE (output_unit, '(A)') ' WARNING: LINE '//TRIM(int_to_str(lines(i)%id))//' end POINT '// &
            TRIM(int_to_str(points(j)%id))//' is above the still-water level (z = '//TRIM(ADJUSTL(b1))// &
            ' m); the line is modelled fully submerged (submerged weight, drag) up to it'
        END IF
      END DO
      nseg = 0
      DO j = 1, SIZE(sections)
        IF (sections(j)%line_id == lines(i)%id) nseg = nseg + sections(j)%nsegs
      END DO
      IF (nseg < 3) WRITE (output_unit, '(A)') ' WARNING: LINE '//TRIM(int_to_str(lines(i)%id))//' has only '// &
        TRIM(int_to_str(nseg))//' segment(s): each segment is a straight chord (a slack segment carries no '// &
        'tension); refine NumSegs for a catenary shape'
    END DO
    IF (opts%has_wtrdpth .OR. opts%has_bathymetry_file) THEN
      DO k = 1, SIZE(types)
        IF (.NOT. (types(k)%diam > CD_ZERO)) CYCLE
        w = (types(k)%mass - opts%rhoW*0.25_wp*ACOS(-CD_ONE)*types(k)%diam**2)*opts%g
        IF (.NOT. (w > CD_ZERO .AND. opts%kbot > CD_ZERO)) CYCLE
        ! a grounded run of this type sinks by its weight over the contact stiffness per length.
        ! The default kBot (1e5 Pa/m, the OrcaFlex default seabed stiffness) embeds a heavy
        ! studless chain by about half its volume-equivalent diameter, a normal soft-soil
        ! value; sinking by more than the full diameter means kBot is too soft for the line.
        pen = w/(opts%kbot*types(k)%diam)
        IF (pen > types(k)%diam) THEN
          WRITE (b1, '(ES10.3)') pen
          WRITE (b2, '(ES10.3)') types(k)%diam
          WRITE (output_unit, '(A)') ' WARNING: line type '//TRIM(types(k)%name)//' sinks '//TRIM(ADJUSTL(b1))// &
            ' m into the seabed (submerged weight / (kBot * Diam)), more than its '// &
            TRIM(ADJUSTL(b2))//' m diameter; kBot is soft for this line'
        END IF
      END DO
    END IF
  END SUBROUTINE print_static_input_warnings

  SUBROUTINE warn_line_below_anchor(lines, points, sections, q_all, q_off)
    !! Standard-output WARNING for a deck with no seabed (no WtrDpth or bathymetryFile) on
    !! which a line hangs below its lowest Fixed end by more than max(1 m, 1 % of its
    !! unstretched length). A coupled OpenFAST deck takes the water depth from the host;
    !! run standalone without it, a slack mooring hangs freely through the missing seabed.
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    REAL(wp), INTENT(IN) :: q_all(:)
    INTEGER, INTENT(IN) :: q_off(:)
    INTEGER :: i, j, k, n
    REAL(wp) :: z_fix, z_min, len0, drop
    LOGICAL :: has_fixed
    CHARACTER(32) :: b1

    DO i = 1, SIZE(lines)
      has_fixed = .FALSE.
      z_fix = HUGE(CD_ONE)
      DO k = 1, 2
        j = find_point(points, MERGE(lines(i)%nodeA, lines(i)%nodeB, k == 1))
        IF (j < 1) CYCLE
        IF (TRIM(points(j)%ptype) /= 'fixed') CYCLE
        has_fixed = .TRUE.
        z_fix = MIN(z_fix, points(j)%pos(3))
      END DO
      IF (.NOT. has_fixed) CYCLE
      len0 = CD_ZERO
      DO j = 1, SIZE(sections)
        IF (sections(j)%line_id == lines(i)%id) len0 = len0 + sections(j)%length
      END DO
      n = (q_off(i + 1) - q_off(i))/3
      IF (n < 1) CYCLE
      z_min = MINVAL(q_all(q_off(i) + 3:q_off(i + 1):3))
      drop = z_fix - z_min
      IF (drop > MAX(CD_ONE, 0.01_wp*len0)) THEN
        WRITE (b1, '(F12.2)') drop
        WRITE (output_unit, '(A)') ' WARNING: LINE '//TRIM(int_to_str(lines(i)%id))//' hangs '// &
          TRIM(ADJUSTL(b1))//' m below its Fixed anchor and the deck has no seabed (no WtrDpth or '// &
          'bathymetryFile). A coupled OpenFAST deck takes the water depth from the host; for a '// &
          'standalone run add WtrDpth.'
      END IF
    END DO
  END SUBROUTINE warn_line_below_anchor

  SUBROUTINE solve_one_line(ln, sections, types, points, opts, q, tension, converged, ErrStat, ErrMsg, bathymetry, &
                            end_ten, end_force)
    !! Solve one EI=0 line (Fixed anchor -> Coupled/held fairlead) built from its ordered
    !! SECTIONS to its tension-only static equilibrium: multi-section mesh, then the shared
    !! robust line initializer CD_Static_Line_Equilibrium (the same one the dynamic-model
    !! initial condition uses) with the optional penalty seabed and steady current.
    !! tension holds the element tensions (tension-only: never negative); end_ten(1:2) the
    !! magnitudes of the force the line exerts on its anchor / fairlead point (end element
    !! tension plus the end node's lumped loads), the AnchTen / FairTen values.
    !! On a non-converged solve ErrMsg carries the stage and the solver's reason.
    TYPE(DeckLine), INTENT(IN) :: ln
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(OUT) :: q(:), tension(:)
    LOGICAL, INTENT(OUT) :: converged
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    REAL(wp), INTENT(OUT), OPTIONAL :: end_ten(2)
    ! force vectors the line exerts on its End B (anchor, column 1) and End A (column 2) points
    REAL(wp), INTENT(OUT), OPTIONAL :: end_force(3, 2)

    TYPE(CD_LineType), ALLOCATABLE :: lts(:)
    TYPE(CD_LineSection), ALLOCATABLE :: secs(:)
    INTEGER, ALLOCATABLE :: conn(:, :)
    REAL(wp), ALLOCATABLE :: l0(:), ea(:), mpl(:), diam(:), w(:), load(:, :), f_ext(:)
    REAL(wp), ALLOCATABLE :: kn(:)
    REAL(wp) :: anchor(3), fairlead(3), force_a(3), force_b(3)
    INTEGER :: ne, n_dof, i, j, ns, es
    CHARACTER(200) :: em
    TYPE(CableSolverConfig) :: cfg
    TYPE(CD_StaticLineReport) :: report
    TYPE(CableCurrentLoad) :: cur

    converged = .FALSE.; ErrStat = CD_DECKDRV_OK; ErrMsg = ''
    ! Define the outputs on every exit path: an early error/non-converged return must not
    ! leave this line's q / tension block uninitialised for the inspection `.out`.
    q = CD_ZERO; tension = CD_ZERO
    IF (PRESENT(end_ten)) end_ten = CD_ZERO
    IF (PRESENT(end_force)) end_force = CD_ZERO
    force_a = CD_ZERO
    force_b = CD_ZERO
    ! NodeA is deck End A/fairlead; NodeB is deck End B/anchor. Internally the
    ! catenary/static model remains anchor -> fairlead.
    anchor = points(find_point(points, ln%nodeB))%pos
    fairlead = points(find_point(points, ln%nodeA))%pos

    ! A Syrope line carries only the placeholder EA (= alpha) in types(...)%ea; the
    ! working-curve constitutive is applied on the dynamic path (init_one_syrope_model,
    ! OWC-secant static seed). Running it through the static EI=0 solve would emit a
    ! wrong .out with that placeholder, so fail closed and point at the dynamic path.
    DO j = 1, SIZE(sections)
      IF (sections(j)%line_id /= ln%id) CYCLE
      IF (types(sections(j)%ltype)%is_syrope) THEN
        CALL fail(ErrStat, ErrMsg, 'a Syrope line has no static output; provide dtM and TMax to run the '// &
                  'dynamic working-curve path'); RETURN
      END IF
    END DO

    ! gather this line's sections (file order = End A -> End B) into CableDyn_Line inputs;
    ! one CD_LineType per section (duplicates allowed), section j -> type index j.
    ns = 0
    DO j = 1, SIZE(sections)
      IF (sections(j)%line_id == ln%id) ns = ns + 1
    END DO
    ALLOCATE (lts(ns), secs(ns))
    i = 0
    DO j = 1, SIZE(sections)
      IF (sections(j)%line_id /= ln%id) CYCLE
      i = i + 1
      lts(i) = CD_LineType(ea=types(sections(j)%ltype)%ea, &
                           mass_per_length=types(sections(j)%ltype)%mass, &
                           diameter=types(sections(j)%ltype)%diam, &
                           ei=types(sections(j)%ltype)%ei)   ! 0 (validated); lets the mesh re-check too
      secs(i) = CD_LineSection(line_type=i, length=sections(j)%length, n_segments=sections(j)%nsegs)
    END DO

    CALL CD_Build_Line_Mesh(secs, lts, .TRUE., conn, l0, ea, mpl, diam, es, em)
    IF (es /= CD_LINE_OK) THEN
      CALL fail(ErrStat, ErrMsg, 'line mesh: '//TRIM(em)); RETURN
    END IF
    ne = SIZE(l0)
    n_dof = 3*(ne + 1)

    ALLOCATE (w(ne), load(3, ne), f_ext(n_dof))
    CALL CD_Submerged_Weight(mpl, diam, opts%rhoW, opts%g, w, es, em)
    IF (es /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'submerged weight: '//TRIM(em)); RETURN
    END IF
    DO i = 1, ne
      load(:, i) = [CD_ZERO, CD_ZERO, -w(i)]
    END DO
    CALL CD_Assemble_Distributed_Load(conn, l0, load, f_ext, es, em)
    IF (es /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'load assembly: '//TRIM(em)); RETURN
    END IF

    ! Steady current: Morison drag on the line at rest, with the node velocities sampled the
    ! way the dynamic model samples them (deck profile at the straight-chord node depths) and
    ! each element's own section hydrodynamics.
    IF (opts%has_current) THEN
      cur%rho = opts%rhoW
      cur%waterline_z = CD_ZERO
      ALLOCATE (cur%node_velocity(3, ne + 1), cur%elem_diameter(ne), cur%elem_cdn(ne), cur%elem_cdt(ne))
      DO i = 1, ne + 1
        cur%node_velocity(:, i) = deck_current_velocity(opts, line_node_z(anchor, fairlead, l0, i), es, em)
        IF (es /= CD_HYDRO_OK) THEN
          CALL fail(ErrStat, ErrMsg, 'current profile: '//TRIM(em)); RETURN
        END IF
      END DO
      i = 0
      DO j = 1, SIZE(sections)
        IF (sections(j)%line_id /= ln%id) CYCLE
        cur%elem_diameter(i + 1:i + sections(j)%nsegs) = types(sections(j)%ltype)%diam
        cur%elem_cdn(i + 1:i + sections(j)%nsegs) = types(sections(j)%ltype)%cdn
        cur%elem_cdt(i + 1:i + sections(j)%nsegs) = types(sections(j)%ltype)%cdt
        i = i + sections(j)%nsegs
      END DO
      IF (opts%has_current_profile .AND. ALLOCATED(opts%current_profile_z)) THEN
        ! a depth profile is re-sampled at the node elevations inside the solve
        cur%profile_z = opts%current_profile_z
        cur%profile_velocity = opts%current_profile_velocity
      END IF
      ! file order is End A (fairlead) -> End B; the mesh runs anchor -> fairlead
      cur%elem_diameter = cur%elem_diameter(ne:1:-1)
      cur%elem_cdn = cur%elem_cdn(ne:1:-1)
      cur%elem_cdt = cur%elem_cdt(ne:1:-1)
    END IF
    IF (PRESENT(bathymetry) .OR. opts%has_wtrdpth) THEN
      CALL CD_Nodal_Seabed_Stiffness(opts%kbot, diam, l0, kn, es, em)
      IF (es /= CD_LINE_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'seabed stiffness: '//TRIM(em)); RETURN
      END IF
    END IF

    IF (PRESENT(bathymetry)) THEN
      IF (opts%has_current) THEN
        CALL CD_Static_Line_Equilibrium(anchor, fairlead, conn, l0, ea, w, f_ext, cfg, .TRUE., q, converged, &
                                        report, es, em, seabed_kn=kn, bathymetry=bathymetry, current=cur)
      ELSE
        CALL CD_Static_Line_Equilibrium(anchor, fairlead, conn, l0, ea, w, f_ext, cfg, .TRUE., q, converged, &
                                        report, es, em, seabed_kn=kn, bathymetry=bathymetry)
      END IF
    ELSE IF (opts%has_wtrdpth) THEN
      IF (opts%has_current) THEN
        CALL CD_Static_Line_Equilibrium(anchor, fairlead, conn, l0, ea, w, f_ext, cfg, .TRUE., q, converged, &
                                        report, es, em, seabed_z_floor=-opts%wtrdpth, seabed_kn=kn, current=cur)
      ELSE
        CALL CD_Static_Line_Equilibrium(anchor, fairlead, conn, l0, ea, w, f_ext, cfg, .TRUE., q, converged, &
                                        report, es, em, seabed_z_floor=-opts%wtrdpth, seabed_kn=kn)
      END IF
    ELSE IF (opts%has_current) THEN
      CALL CD_Static_Line_Equilibrium(anchor, fairlead, conn, l0, ea, w, f_ext, cfg, .TRUE., q, converged, &
                                      report, es, em, current=cur)
    ELSE
      CALL CD_Static_Line_Equilibrium(anchor, fairlead, conn, l0, ea, w, f_ext, cfg, .TRUE., q, converged, &
                                      report, es, em)
    END IF
    IF (es /= CD_STATIC_OK) THEN
      CALL fail(ErrStat, ErrMsg, 'static solve rejected the input: '//TRIM(em))
      RETURN
    END IF

    IF (.NOT. converged) THEN
      ! fail closed: the inspection state keeps its positions, tensions stay zero
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'line '//TRIM(int_to_str(ln%id))//' static equilibrium not found: '//TRIM(report%message)
      RETURN
    END IF
    ! tension-only line: slack elements report zero tension
    CALL CD_Compute_Cable_Tension(RESHAPE(q, [3, ne + 1]), conn, l0, ea, .TRUE., tension, es, em)
    IF (es /= 0) THEN
      CALL fail_solve(ErrStat, ErrMsg, 'tension recovery: '//TRIM(em)); RETURN
    END IF
    IF (PRESENT(end_ten) .OR. PRESENT(end_force)) THEN
      IF (PRESENT(bathymetry) .AND. opts%has_current) THEN
        CALL CD_Static_Line_End_Forces(q, conn, l0, ea, f_ext, .TRUE., force_a, force_b, es, em, &
                                       seabed_kn=kn, bathymetry=bathymetry, current=cur)
      ELSE IF (PRESENT(bathymetry)) THEN
        CALL CD_Static_Line_End_Forces(q, conn, l0, ea, f_ext, .TRUE., force_a, force_b, es, em, &
                                       seabed_kn=kn, bathymetry=bathymetry)
      ELSE IF (opts%has_wtrdpth .AND. opts%has_current) THEN
        CALL CD_Static_Line_End_Forces(q, conn, l0, ea, f_ext, .TRUE., force_a, force_b, es, em, &
                                       seabed_z_floor=-opts%wtrdpth, seabed_kn=kn, current=cur)
      ELSE IF (opts%has_wtrdpth) THEN
        CALL CD_Static_Line_End_Forces(q, conn, l0, ea, f_ext, .TRUE., force_a, force_b, es, em, &
                                       seabed_z_floor=-opts%wtrdpth, seabed_kn=kn)
      ELSE IF (opts%has_current) THEN
        CALL CD_Static_Line_End_Forces(q, conn, l0, ea, f_ext, .TRUE., force_a, force_b, es, em, current=cur)
      ELSE
        CALL CD_Static_Line_End_Forces(q, conn, l0, ea, f_ext, .TRUE., force_a, force_b, es, em)
      END IF
      IF (es /= 0) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'end-force recovery: '//TRIM(em)); RETURN
      END IF
      IF (PRESENT(end_ten)) end_ten = [NORM2(force_a), NORM2(force_b)]
    END IF
    ! fail closed on any non-finite reported quantity
    IF (.NOT. (ALL(IEEE_IS_FINITE(q)) .AND. ALL(IEEE_IS_FINITE(tension)) .AND. ALL(IEEE_IS_FINITE(force_a)) &
               .AND. ALL(IEEE_IS_FINITE(force_b)))) THEN
      converged = .FALSE.
      q = CD_ZERO
      tension = CD_ZERO
      IF (PRESENT(end_ten)) end_ten = CD_ZERO
      IF (PRESENT(end_force)) end_force = CD_ZERO
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'line '//TRIM(int_to_str(ln%id))//' static equilibrium not found: the solution is not finite'
      RETURN
    END IF
    IF (PRESENT(end_force)) THEN
      end_force(:, 1) = force_a
      end_force(:, 2) = force_b
    END IF
  END SUBROUTINE solve_one_line

  ! --------------------------------------------------------------------------- !
  ! deck parser                                                                 !
  ! --------------------------------------------------------------------------- !

  SUBROUTINE parse_deck(path, types, bodies, rod_types, rods, points, lines, sections, opts, channels, &
                        ErrStat, ErrMsg, caller_driven, env_gravity, env_rho_water, env_wtrdpth, &
                        allow_turbine, failures, controls, run_tmax, allow_static_finite_ei, host_coupled_objects)
    !! Sectioned MoorDyn-style parser. Sections: LINE TYPES / BODIES / ROD TYPES / RODS /
    !! POINTS / LINES / SECTIONS / OPTIONS / OUTPUTS (TABLE sections skip the column-name
    !! + units rows). Unsupported variants fail closed during validation.
    !! caller_driven marks decks marched externally (a coupled host steps the system),
    !! where the deck's own dtM/TMax pairing is advisory rather than required.
    !! env_gravity / env_rho_water / env_wtrdpth: caller-supplied environment,
    !! applied BEFORE equivalent-buoyancy conversion and validation so both run
    !! under the environment the model is actually built with.
    !! allow_turbine: the CompMooring=5 aggregate path consumes FAST.Farm Turbine<J>
    !! decks with the host's n_turbines/turbine_ref_pos (their coupled coordinates are
    !! turbine-local); the standalone driver consumes them when the deck carries a TURBINES
    !! section. Every other case fails closed on the vocabulary rather than silently
    !! solving turbine-local coordinates as global.
    CHARACTER(*), INTENT(IN) :: path
    TYPE(DeckLineType), ALLOCATABLE, INTENT(OUT) :: types(:)
    TYPE(DeckBody), ALLOCATABLE, INTENT(OUT) :: bodies(:)
    TYPE(DeckRodType), ALLOCATABLE, INTENT(OUT) :: rod_types(:)
    TYPE(DeckRod), ALLOCATABLE, INTENT(OUT) :: rods(:)
    TYPE(DeckPoint), ALLOCATABLE, INTENT(OUT) :: points(:)
    TYPE(DeckLine), ALLOCATABLE, INTENT(OUT) :: lines(:)
    TYPE(DeckSection), ALLOCATABLE, INTENT(OUT) :: sections(:)
    TYPE(DeckOptions), INTENT(OUT) :: opts
    CHARACTER(NAMELEN), ALLOCATABLE, INTENT(OUT) :: channels(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    LOGICAL, INTENT(IN), OPTIONAL :: caller_driven
    REAL(wp), INTENT(IN), OPTIONAL :: env_gravity, env_rho_water, env_wtrdpth
    REAL(wp), INTENT(IN), OPTIONAL :: run_tmax
    LOGICAL, INTENT(IN), OPTIONAL :: allow_turbine
    ! Metadata scans for the standalone executable may classify a static finite-EI
    ! deck before the executable supplies its non-marching aggregate init clock.
    LOGICAL, INTENT(IN), OPTIONAL :: allow_static_finite_ei
    ! host_coupled_objects: ONLY the CompMooring=5 aggregate drives Coupled/Vessel rods/bodies from its
    ! host mesh; every other entry point keeps the motionFile requirement.
    LOGICAL, INTENT(IN), OPTIONAL :: host_coupled_objects
    ! FAILURE rows. A deck DECLARING failures parsed by an entry point that does not
    ! consume them fails closed (never silently ignore a declared failure).
    TYPE(DeckFailure), ALLOCATABLE, INTENT(OUT), OPTIONAL :: failures(:)
    ! CONTROL rows: the same fail-closed contract for active line control.
    TYPE(DeckControl), ALLOCATABLE, INTENT(OUT), OPTIONAL :: controls(:)

    TYPE(DeckEquivalentBuoyancy), ALLOCATABLE :: equivs(:)
    TYPE(DeckFailure), ALLOCATABLE :: fails(:)
    TYPE(DeckControl), ALLOCATABLE :: ctrls(:)
    TYPE(DeckEndConnection), ALLOCATABLE :: endconns(:)
    ! EXTERNAL LOADS rows, applied to the bodies once the whole deck is read
    CHARACTER(DECK_RECLEN), ALLOCATABLE :: ext_rows(:)
    INTEGER, ALLOCATABLE :: ext_lines(:)
    INTEGER :: next_ext
    CHARACTER(DECK_RECLEN), ALLOCATABLE :: att_rows(:)
    INTEGER, ALLOCATABLE :: att_lines(:)
    INTEGER :: n_att
    CHARACTER(2*NAMELEN), ALLOCATABLE :: channel_keys(:)
    LOGICAL :: ext_march, types_stock_cols, rodtypes_legacy_cols, turb_ok, static_finite_ok
    INTEGER :: unit, ios, section, nt, nb, nrt, nr, np, nlin, nsec, neq, nch, nfl, nct, nec, lineno
    CHARACTER(DECK_RECLEN) :: line
    ! list_safe_row output: every token may gain a pair of quotes
    CHARACTER(3*DECK_RECLEN) :: row
    ! The whole header record: a title banner may carry "INPUT FILE" far to the right.
    CHARACTER(DECK_RECLEN) :: secname
    CHARACTER(256) :: why
    ! Deck line of each OUTPUTS channel, for finalizer messages.
    INTEGER, ALLOCATABLE :: channel_lines(:)
    INTEGER :: nch_before, i_ch
    INTEGER, PARAMETER :: NO_TEXT_COLS(0) = [INTEGER ::]
    INTEGER, PARAMETER :: SEC_NONE = 0, SEC_TYPES = 1, SEC_BODIES = 2, SEC_POINTS = 3, SEC_LINES = 4, &
                          SEC_SECTIONS = 5, SEC_OPTIONS = 6, SEC_OUTPUTS = 7, SEC_RODTYPES = 8, SEC_RODS = 9, &
                          SEC_EQUIV = 10, SEC_FAILURE = 11, SEC_CONTROL = 12, SEC_SYROPE_IC = 13, &
                          SEC_ENDCONN = 14, SEC_TURBINES = 15, SEC_EXTLOADS = 16, SEC_ATTACH = 17

    ErrStat = 0; ErrMsg = ''
    ext_march = .FALSE.
    IF (PRESENT(caller_driven)) ext_march = caller_driven
    static_finite_ok = .FALSE.
    IF (PRESENT(allow_static_finite_ei)) static_finite_ok = allow_static_finite_ei
    types_stock_cols = .FALSE.
    rodtypes_legacy_cols = .FALSE.
    ALLOCATE (types(0), points(0), lines(0), sections(0), channels(0))
    ALLOCATE (bodies(0))
    ALLOCATE (rod_types(0), rods(0))
    ALLOCATE (equivs(0))
    ALLOCATE (fails(0))
    ALLOCATE (ctrls(0))
    ALLOCATE (endconns(0))
    ALLOCATE (ext_rows(0), ext_lines(0))
    next_ext = 0
    ALLOCATE (att_rows(0), att_lines(0))
    n_att = 0
    nt = 0; nb = 0; nrt = 0; nr = 0; np = 0; nlin = 0; nsec = 0; neq = 0; nch = 0; nfl = 0; nct = 0; nec = 0
    section = SEC_NONE
    ALLOCATE (channel_lines(0))

    CALL CD_Open_Input(unit, path, ios, why)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open deck: '//TRIM(path)//input_open_reason(path, why)); RETURN
    END IF

    lineno = 0
    DO
      CALL next_record(unit, line, ios, lineno)
      IF (IS_IOSTAT_END(ios)) EXIT
      IF (ios /= 0) THEN
        CALL record_error(ios, 'deck', lineno, ErrStat, ErrMsg)
        CLOSE (unit); RETURN
      END IF
      IF (is_section_header(line, secname)) THEN
        CALL set_section(secname, section, ErrStat, ErrMsg)
        IF (ErrStat /= 0) THEN
          CALL add_row_context('deck', lineno, line, ErrMsg)
          CLOSE (unit); RETURN
        END IF
        CYCLE
      END IF
      ! TABLE sections (TYPES/POINTS/LINES/SECTIONS) carry a column-name row and a units
      ! row before the data. Rather than a fragile fixed skip, drop any row with NO numeric
      ! token (a header/units row) -- robust to 0, 1, or 2 such rows. A data row always
      ! carries a number. OPTIONS/OUTPUTS rows are taken verbatim (no header rows there).
      ! Table rows then pass list_safe_row before their list-directed READ; the FAILURE,
      ! CONTROL and SYROPE IC rows (comma lists) tokenize and parse each column strictly.
      SELECT CASE (section)
      CASE (SEC_NONE)
        CYCLE
      CASE (SEC_TYPES)
        IF (.NOT. has_numeric_token(line)) THEN
          ! The header row decides the drag/added-mass column order (stock MoorDyn
          ! vs CableDyn) -- the data rows alone are positionally indistinguishable.
          CALL sniff_types_header(line, types_stock_cols)
          CYCLE
        END IF
        ! column 4 (EA) may carry the SYROPE:<path>|alpha|beta settings-file reference
        CALL list_safe_row(line, [4], [1, 5], row, ErrStat, ErrMsg)
        IF (ErrStat == 0) CALL append_type(row, types, nt, types_stock_cols, ErrStat, ErrMsg)
      CASE (SEC_BODIES)
        IF (.NOT. has_numeric_token(line)) CYCLE
        CALL list_safe_row(line, NO_TEXT_COLS, [2], row, ErrStat, ErrMsg)
        IF (ErrStat == 0) CALL append_body(row, bodies, nb, ErrStat, ErrMsg)
      CASE (SEC_RODTYPES)
        IF (.NOT. has_numeric_token(line)) THEN
          ! The header row decides whether columns 6-7 carry the MoorDyn end coefficients
          ! (CdEnd CaEnd, the default) or the retired CableDyn axial ones (CdAx CaAx).
          CALL sniff_rod_types_header(line, rodtypes_legacy_cols)
          CYCLE
        END IF
        CALL list_safe_row(line, NO_TEXT_COLS, [1], row, ErrStat, ErrMsg)
        IF (ErrStat == 0) CALL append_rod_type(row, rod_types, nrt, rodtypes_legacy_cols, ErrStat, ErrMsg)
      CASE (SEC_RODS)
        IF (.NOT. has_numeric_token(line)) CYCLE
        CALL list_safe_row(line, NO_TEXT_COLS, [2, 3, 11], row, ErrStat, ErrMsg)
        IF (ErrStat == 0) CALL append_rod(row, rods, nr, ErrStat, ErrMsg)
      CASE (SEC_POINTS)
        IF (.NOT. has_numeric_token(line)) CYCLE
        CALL list_safe_row(line, NO_TEXT_COLS, [2], row, ErrStat, ErrMsg)
        IF (ErrStat == 0) CALL append_point(row, points, np, ErrStat, ErrMsg)
      CASE (SEC_LINES)
        IF (.NOT. has_numeric_token(line)) CYCLE
        CALL list_safe_row(line, NO_TEXT_COLS, [2, 3, 4, 7], row, ErrStat, ErrMsg)
        IF (ErrStat == 0) CALL append_line(row, lines, nlin, sections, nsec, ErrStat, ErrMsg)
      CASE (SEC_SECTIONS)
        IF (.NOT. has_numeric_token(line)) CYCLE
        CALL list_safe_row(line, NO_TEXT_COLS, [2], row, ErrStat, ErrMsg)
        IF (ErrStat == 0) CALL append_section(row, sections, nsec, ErrStat, ErrMsg)
      CASE (SEC_EQUIV)
        IF (.NOT. has_numeric_token(line)) CYCLE
        CALL list_safe_row(line, NO_TEXT_COLS, [1], row, ErrStat, ErrMsg)
        IF (ErrStat == 0) CALL append_equivalent_buoyancy(row, equivs, neq, ErrStat, ErrMsg)
      CASE (SEC_FAILURE)
        IF (.NOT. has_numeric_token(line)) CYCLE
        CALL append_failure(line, fails, nfl, ErrStat, ErrMsg)
      CASE (SEC_CONTROL)
        IF (.NOT. has_numeric_token(line)) CYCLE
        CALL append_control(line, ctrls, nct, ErrStat, ErrMsg)
      CASE (SEC_SYROPE_IC)
        IF (.NOT. has_numeric_token(line)) CYCLE
        CALL apply_syrope_ic(line, lines, nlin, ErrStat, ErrMsg)
      CASE (SEC_ENDCONN)
        IF (.NOT. has_numeric_token(line)) CYCLE
        CALL list_safe_row(line, NO_TEXT_COLS, [2, 3], row, ErrStat, ErrMsg)
        IF (ErrStat == 0) CALL append_end_connection(row, endconns, nec, ErrStat, ErrMsg)
      CASE (SEC_TURBINES)
        IF (.NOT. has_numeric_token(line)) CYCLE
        CALL list_safe_row(line, NO_TEXT_COLS, NO_TEXT_COLS, row, ErrStat, ErrMsg)
        IF (ErrStat == 0) CALL append_turbine(row, opts, ErrStat, ErrMsg)
      CASE (SEC_EXTLOADS)
        IF (.NOT. has_numeric_token(line)) CYCLE
        CALL list_safe_row(line, NO_TEXT_COLS, NO_TEXT_COLS, row, ErrStat, ErrMsg)
        IF (ErrStat == 0) THEN
          next_ext = next_ext + 1
          IF (next_ext > SIZE(ext_rows)) THEN
            ext_rows = [ext_rows, [(REPEAT(' ', DECK_RECLEN), i_ch=1, 4)]]
            ext_lines = [ext_lines, [0, 0, 0, 0]]
          END IF
          ext_rows(next_ext) = row(1:MIN(LEN(row), DECK_RECLEN))
          ext_lines(next_ext) = lineno
        END IF
      CASE (SEC_ATTACH)
        IF (.NOT. has_numeric_token(line)) CYCLE
        n_att = n_att + 1
        IF (n_att > SIZE(att_rows)) THEN
          att_rows = [att_rows, [(REPEAT(' ', DECK_RECLEN), i_ch=1, 16)]]
          att_lines = [att_lines, [(0, i_ch=1, 16)]]
        END IF
        att_rows(n_att) = line(1:MIN(LEN(line), DECK_RECLEN))
        att_lines(n_att) = lineno
      CASE (SEC_OPTIONS)
        CALL apply_option(line, opts, ErrStat, ErrMsg)
      CASE (SEC_OUTPUTS)
        ! Stock decks terminate the channel list with a bare END; everything after
        ! it is commentary.
        BLOCK
          CHARACTER(NAMELEN) :: tok1
          LOGICAL :: found1
          CALL get_token(line, 1, tok1, found1)
          IF (found1) THEN
            IF (to_lower(TRIM(tok1)) == 'end') THEN
              section = SEC_NONE
              CYCLE
            END IF
          END IF
        END BLOCK
        nch_before = nch
        CALL append_channel(line, channels, channel_keys, nch, ErrStat, ErrMsg)
        IF (nch > nch_before) channel_lines = [channel_lines(1:nch_before), (lineno, i_ch=nch_before + 1, nch)]
      END SELECT
      IF (ErrStat /= 0) THEN
        CALL add_row_context('deck', lineno, line, ErrMsg)
        CLOSE (unit); RETURN
      END IF
      ! Record where each table row came from, for the cross-reference checks that run
      ! after the whole deck is read.
      SELECT CASE (section)
      CASE (SEC_TYPES)
        IF (types(nt)%deck_line == 0) types(nt)%deck_line = lineno
      CASE (SEC_BODIES)
        IF (bodies(nb)%deck_line == 0) bodies(nb)%deck_line = lineno
      CASE (SEC_RODTYPES)
        IF (rod_types(nrt)%deck_line == 0) rod_types(nrt)%deck_line = lineno
      CASE (SEC_RODS)
        IF (rods(nr)%deck_line == 0) rods(nr)%deck_line = lineno
      CASE (SEC_POINTS)
        IF (points(np)%deck_line == 0) points(np)%deck_line = lineno
      CASE (SEC_LINES)
        IF (lines(nlin)%deck_line == 0) lines(nlin)%deck_line = lineno
        IF (nsec > 0) THEN
          IF (sections(nsec)%deck_line == 0) sections(nsec)%deck_line = lineno
        END IF
      CASE (SEC_SECTIONS)
        IF (sections(nsec)%deck_line == 0) sections(nsec)%deck_line = lineno
      END SELECT
    END DO
    CLOSE (unit)

    CALL trim_types(types, nt)
    CALL trim_bodies(bodies, nb)
    CALL trim_rod_types(rod_types, nrt)
    CALL trim_rods(rods, nr)
    CALL trim_points(points, np)
    CALL trim_lines(lines, nlin)
    CALL trim_sections(sections, nsec)
    CALL trim_equivalent_buoyancy(equivs, neq)
    CALL trim_channels(channels, nch)
    CALL trim_failures(fails, nfl)
    ! Validate FAILURE rows against the parsed points/lines here, where both exist;
    ! a deck declaring failures through an entry point that cannot consume them
    ! fails closed rather than silently running an intact system.
    IF (SIZE(fails) > 0) THEN
      IF (.NOT. PRESENT(failures)) THEN
        CALL fail(ErrStat, ErrMsg, 'this entry point does not support the FAILURE section')
        RETURN
      END IF
      CALL validate_failures(fails, points, lines, ErrStat, ErrMsg)
      IF (ErrStat /= 0) RETURN
    END IF
    IF (PRESENT(failures)) CALL MOVE_ALLOC(fails, failures)
    CALL trim_controls(ctrls, nct)
    IF (SIZE(ctrls) > 0) THEN
      IF (.NOT. PRESENT(controls)) THEN
        CALL fail(ErrStat, ErrMsg, 'this entry point does not support the CONTROL section')
        RETURN
      END IF
      CALL validate_controls(ctrls, lines, ErrStat, ErrMsg)
      IF (ErrStat /= 0) RETURN
    END IF
    IF (PRESENT(controls)) CALL MOVE_ALLOC(ctrls, controls)
    CALL trim_end_connections(endconns, nec)
    CALL resolve_end_connections(endconns, lines, ErrStat, ErrMsg)
    IF (ErrStat /= 0) RETURN
    DO i_ch = 1, n_att
      CALL append_line_attachment(att_rows(i_ch), lines, ErrStat, ErrMsg)
      IF (ErrStat /= 0) THEN
        CALL add_row_context('deck', att_lines(i_ch), att_rows(i_ch), ErrMsg)
        RETURN
      END IF
    END DO

    ! Caller-supplied environment overrides land HERE -- before equivalent-buoyancy
    ! conversion and validation -- so both run under the environment the model is
    ! actually built with (a host g/rhoW differing from the deck's would otherwise
    ! silently change converted masses or net-buoyancy acceptance). Non-finite or
    ! non-positive host values fall back to the deck / defaults; a deck-declared
    ! bathymetryFile keeps its structured seabed over the host's flat depth. With
    ! has_wtrdpth set here, the standard WtrDpth/kBot/cBot validation below covers
    ! the injected depth.
    IF (PRESENT(env_gravity)) THEN
      IF (IEEE_IS_FINITE(env_gravity) .AND. env_gravity > CD_ZERO) opts%g = env_gravity
    END IF
    IF (PRESENT(env_rho_water)) THEN
      IF (IEEE_IS_FINITE(env_rho_water) .AND. env_rho_water > CD_ZERO) opts%rhoW = env_rho_water
    END IF
    IF (PRESENT(host_coupled_objects)) opts%host_coupled_objects = host_coupled_objects
    IF (PRESENT(env_wtrdpth)) THEN
      IF (IEEE_IS_FINITE(env_wtrdpth) .AND. env_wtrdpth > CD_ZERO .AND. .NOT. opts%has_bathymetry_file) THEN
        opts%wtrdpth = env_wtrdpth
        opts%has_wtrdpth = .TRUE.
      END IF
    END IF
    CALL apply_equivalent_buoyancy(types, equivs, opts, ErrStat, ErrMsg)
    IF (ErrStat /= 0) RETURN
    ! MoorDyn WaterKin file: read it HERE (the deck directory is known and the
    ! result must precede validation so a file-declared current participates in
    ! every ambient/double-count rejection exactly like an inline OPTION).
    CALL resolve_deck_sea(opts, ErrStat, ErrMsg)
    IF (ErrStat /= 0) RETURN
    CALL resolve_deck_friction(opts, ErrStat, ErrMsg)
    IF (ErrStat /= 0) RETURN
    IF (opts%has_waterkin_file) THEN
      CALL read_waterkin_file(path_join(deck_dir(path), opts%waterkin_file), deck_dir(path), opts, ErrStat, ErrMsg, &
                              run_tmax)
      IF (ErrStat /= 0) RETURN
    END IF
    IF (opts%waterkin_seastate .AND. .NOT. ext_march) THEN
      CALL fail(ErrStat, ErrMsg, 'WaterKin WaveKinMod 2/SEASTATE is coupled-only; the standalone '// &
                'driver has no host SeaState field')
      RETURN
    END IF
    ! MoorDyn-C WaveKin 3/7 and Currents 1: their fixed-name files in the deck folder
    IF (opts%mdc_wave_kin > 0 .OR. opts%mdc_currents > 0) THEN
      CALL read_moordyn_c_kinematics(deck_dir(path), opts, ErrStat, ErrMsg)
      IF (ErrStat /= 0) RETURN
    END IF
    ! Syrope working-curve files: read each SYROPE line type's settings + OWC
    ! table HERE (the deck directory is known) and stash the resolved curve on
    ! the type, so the model build needs no deck-path threading.
    BLOCK
      INTEGER :: it
      DO it = 1, SIZE(types)
        IF (.NOT. types(it)%is_syrope) CYCLE
        CALL read_syrope_settings(path_join(deck_dir(path), TRIM(types(it)%syrope_file)), &
                                  types(it)%syrope_owc_strain, types(it)%syrope_owc_tension, &
                                  types(it)%syrope_wc_mod, types(it)%syrope_p1, types(it)%syrope_p2, &
                                  ErrStat, ErrMsg, owc_file=types(it)%syrope_owc_file)
        IF (ErrStat /= 0) RETURN
      END DO
    END BLOCK
    ! FAST.Farm vocabulary FIRST: Turbine<J>/T<J> normalizes to a coupled point tagged
    ! with its turbine BEFORE the stock endpoint-order pre-pass, so a stock-order farm
    ! line (NodeA = Fixed anchor, NodeB = Turbine<J> fairlead) is swapped like any
    ! coupled fairlead instead of surviving un-swapped and failing the End-A rule.
    turb_ok = .FALSE.
    IF (PRESENT(allow_turbine)) turb_ok = allow_turbine
    CALL normalize_turbine_points(points, turb_ok .OR. opts%n_turb > 0, ErrStat, ErrMsg)
    IF (ErrStat /= 0) RETURN
    IF (opts%n_turb > 0 .AND. .NOT. turb_ok) THEN
      CALL place_standalone_turbine_points(points, opts, ErrStat, ErrMsg)
      IF (ErrStat /= 0) RETURN
    END IF
    CALL collapse_zero_length_rods(rods, points, np, lines, opts)
    CALL resolve_rod_end_tokens(rods, bodies, points, np, lines)
    CALL trim_points(points, np)
    DO i_ch = 1, next_ext
      CALL apply_external_load(ext_rows(i_ch), i_ch, bodies, ErrStat, ErrMsg)
      IF (ErrStat /= 0) THEN
        CALL add_row_context('deck', ext_lines(i_ch), ext_rows(i_ch), ErrMsg)
        RETURN
      END IF
    END DO
    CALL normalize_stock_endpoint_order(points, lines, sections)
    CALL finalize_and_validate(types, bodies, rod_types, rods, points, lines, sections, opts, channels, ext_march, &
                               static_finite_ok, ErrStat, ErrMsg, channel_lines)
    IF (ErrStat == 0 .AND. opts%has_motion_file) THEN
      BLOCK
        CHARACTER(:), ALLOCATABLE :: resolved_path
        resolved_path = path_join(deck_dir(path), opts%motion_file)
        IF (LEN(resolved_path) > LEN(opts%motion_file)) THEN
          CALL fail(ErrStat, ErrMsg, 'motionFile path is too long after resolving relative to the deck directory')
        ELSE
          opts%motion_file = ''
          opts%motion_file(1:LEN(resolved_path)) = resolved_path
        END IF
      END BLOCK
    END IF
  END SUBROUTINE parse_deck

  SUBROUTINE append_failure(line, fails, nfl, ErrStat, ErrMsg)
    !! Parse one FAILURE row: FailID  Point  LineID[,LineID...]  FailTime  FailTen.
    !! Point accepts the MoorDyn P<n> form or a bare integer; rod attachments
    !! (R<n>A/R<n>B) fail closed -- CableDyn failures act on POINTS.
    CHARACTER(*), INTENT(IN) :: line
    TYPE(DeckFailure), ALLOCATABLE, INTENT(INOUT) :: fails(:)
    INTEGER, INTENT(INOUT) :: nfl
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    TYPE(DeckFailure), ALLOCATABLE :: grown(:)
    TYPE(DeckFailure) :: f
    ! Token buffers sized to the INPUT LINE: the LineID[,LineID...] column is a
    ! variable-length comma list, and a fixed NAMELEN buffer would silently
    ! truncate a long list -- detaching only the parsed prefix.
    CHARACTER(LEN(line)) :: tok_point, tok_lines, fields(5), piece
    INTEGER :: k, lo, hi, nl, istat, pos, nf
    INTEGER, ALLOCATABLE :: ids(:)
    LOGICAL :: ok

    ErrStat = 0; ErrMsg = ''
    ! Whitespace tokenization, NOT list-directed READ: the line-id column is a
    ! comma list ("1,2") and list-directed input would treat that comma as a value
    ! separator, silently shifting the FailTime/FailTen columns.
    pos = 1
    nf = 0
    DO WHILE (nf < 5)
      DO WHILE (pos <= LEN_TRIM(line))
        IF (line(pos:pos) /= ' ' .AND. line(pos:pos) /= CHAR(9)) EXIT
        pos = pos + 1
      END DO
      IF (pos > LEN_TRIM(line)) EXIT
      lo = pos
      DO WHILE (pos <= LEN_TRIM(line))
        IF (line(pos:pos) == ' ' .OR. line(pos:pos) == CHAR(9)) EXIT
        pos = pos + 1
      END DO
      nf = nf + 1
      fields(nf) = line(lo:pos - 1)
    END DO
    IF (nf < 5) THEN
      CALL fail(ErrStat, ErrMsg, 'FAILURE row needs 5 cols: FailID Point LineID[,LineID...] FailTime FailTen')
      RETURN
    END IF
    ! Reject unconsumed trailing tokens (the same class as the CONTROL row): a
    ! space-separated line list would silently shift or drop columns.
    DO WHILE (pos <= LEN_TRIM(line))
      IF (line(pos:pos) /= ' ' .AND. line(pos:pos) /= CHAR(9)) THEN
        CALL fail(ErrStat, ErrMsg, 'FAILURE row has trailing content after its 5 columns '// &
                  '(use a comma-separated line list with no spaces)')
        RETURN
      END IF
      pos = pos + 1
    END DO
    CALL parse_int_token(fields(1), f%fail_id, ok)
    IF (.NOT. ok) THEN
      CALL fail(ErrStat, ErrMsg, 'FAILURE FailID must be an integer')
      RETURN
    END IF
    tok_point = fields(2)
    tok_lines = fields(3)
    CALL parse_real_token(fields(4), f%fail_time, ok)
    IF (ok) CALL parse_real_token(fields(5), f%fail_ten, ok)
    IF (.NOT. ok) THEN
      CALL fail(ErrStat, ErrMsg, 'FAILURE FailTime/FailTen must be numeric')
      RETURN
    END IF
    tok_point = ADJUSTL(tok_point)
    IF (to_lower(tok_point(1:1)) == 'r') THEN
      CALL fail(ErrStat, ErrMsg, 'FAILURE at a rod end (R<n>A/R<n>B) is not supported; failures act on points')
      RETURN
    END IF
    IF (to_lower(tok_point(1:1)) == 'p') tok_point = tok_point(2:)
    CALL parse_int_token(tok_point, f%point_id, ok)
    IF (.NOT. ok .OR. f%point_id < 1) THEN
      CALL fail(ErrStat, ErrMsg, 'FAILURE Point must be P<n> or a positive point id')
      RETURN
    END IF
    ! Comma-separated line ids (a single id is the degenerate list).
    nl = 0
    ALLOCATE (ids(0))
    lo = 1
    tok_lines = ADJUSTL(tok_lines)
    DO
      hi = INDEX(tok_lines(lo:), ',')
      IF (hi == 0) THEN
        piece = tok_lines(lo:)
      ELSE
        piece = tok_lines(lo:lo + hi - 2)
      END IF
      CALL parse_int_token(piece, k, ok)
      IF (.NOT. ok .OR. k < 1) THEN
        CALL fail(ErrStat, ErrMsg, 'FAILURE line list must be positive line ids separated by commas')
        RETURN
      END IF
      ids = [ids, k]
      nl = nl + 1
      IF (hi == 0) EXIT
      lo = lo + hi
    END DO
    CALL MOVE_ALLOC(ids, f%line_ids)
    IF (.NOT. (IEEE_IS_FINITE(f%fail_time) .AND. IEEE_IS_FINITE(f%fail_ten))) THEN
      CALL fail(ErrStat, ErrMsg, 'FAILURE FailTime/FailTen must be finite')
      RETURN
    END IF
    IF (.NOT. (f%fail_time > CD_ZERO .OR. f%fail_ten > CD_ZERO)) THEN
      CALL fail(ErrStat, ErrMsg, 'FAILURE needs FailTime > 0 or FailTen > 0 (a row that can never fire)')
      RETURN
    END IF

    ALLOCATE (grown(nfl + 1), STAT=istat)
    IF (istat /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'FAILURE row allocation failed')
      RETURN
    END IF
    grown(1:nfl) = fails(1:nfl)
    grown(nfl + 1) = f
    CALL MOVE_ALLOC(grown, fails)
    nfl = nfl + 1
  END SUBROUTINE append_failure

  SUBROUTINE trim_failures(fails, nfl)
    TYPE(DeckFailure), ALLOCATABLE, INTENT(INOUT) :: fails(:)
    INTEGER, INTENT(IN) :: nfl
    TYPE(DeckFailure), ALLOCATABLE :: trimmed(:)
    IF (SIZE(fails) == nfl) RETURN
    ALLOCATE (trimmed(nfl))
    trimmed = fails(1:nfl)
    CALL MOVE_ALLOC(trimmed, fails)
  END SUBROUTINE trim_failures

  SUBROUTINE validate_failures(fails, points, lines, ErrStat, ErrMsg)
    !! Structural validation of FAILURE rows against the parsed deck: sequential
    !! FailIDs from 1, a known point, and every listed line attached to that point.
    TYPE(DeckFailure), INTENT(IN) :: fails(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i, j, k, pidx, lidx

    ErrStat = 0; ErrMsg = ''
    DO i = 1, SIZE(fails)
      IF (fails(i)%fail_id /= i) THEN
        CALL fail(ErrStat, ErrMsg, 'FAILURE FailIDs must be sequential from 1 (FailID '// &
                  TRIM(int_to_str(fails(i)%fail_id))//' is row '//TRIM(int_to_str(i))//')')
        RETURN
      END IF
      pidx = 0
      DO j = 1, SIZE(points)
        IF (points(j)%id == fails(i)%point_id) pidx = j
      END DO
      IF (pidx == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'FAILURE '//TRIM(int_to_str(fails(i)%fail_id))// &
                  ' references undefined point '//TRIM(int_to_str(fails(i)%point_id)))
        RETURN
      END IF
      DO k = 1, SIZE(fails(i)%line_ids)
        lidx = 0
        DO j = 1, SIZE(lines)
          IF (lines(j)%id == fails(i)%line_ids(k)) lidx = j
        END DO
        IF (lidx == 0) THEN
          CALL fail(ErrStat, ErrMsg, 'FAILURE '//TRIM(int_to_str(fails(i)%fail_id))// &
                    ' references undefined line '//TRIM(int_to_str(fails(i)%line_ids(k))))
          RETURN
        END IF
        IF (lines(lidx)%nodeA /= fails(i)%point_id .AND. lines(lidx)%nodeB /= fails(i)%point_id) THEN
          CALL fail(ErrStat, ErrMsg, 'FAILURE '//TRIM(int_to_str(fails(i)%fail_id))//' lists line '// &
                    TRIM(int_to_str(fails(i)%line_ids(k)))//', which is not attached to point '// &
                    TRIM(int_to_str(fails(i)%point_id)))
          RETURN
        END IF
      END DO
    END DO
  END SUBROUTINE validate_failures

  SUBROUTINE append_control(line, ctrls, nct, ErrStat, ErrMsg)
    !! Parse one CONTROL row: ChannelID  LineID[,LineID...]. Whitespace tokenized
    !! (the line-id column is a comma list) with line-length buffers -- the FAILURE
    !! parser's lessons applied as a class.
    CHARACTER(*), INTENT(IN) :: line
    TYPE(DeckControl), ALLOCATABLE, INTENT(INOUT) :: ctrls(:)
    INTEGER, INTENT(INOUT) :: nct
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    TYPE(DeckControl), ALLOCATABLE :: grown(:)
    TYPE(DeckControl) :: c
    CHARACTER(LEN(line)) :: fields(2), piece
    INTEGER :: k, lo, hi, istat, pos, nf
    INTEGER, ALLOCATABLE :: ids(:)
    LOGICAL :: ok

    ErrStat = 0; ErrMsg = ''
    pos = 1
    nf = 0
    DO WHILE (nf < 2)
      DO WHILE (pos <= LEN_TRIM(line))
        IF (line(pos:pos) /= ' ' .AND. line(pos:pos) /= CHAR(9)) EXIT
        pos = pos + 1
      END DO
      IF (pos > LEN_TRIM(line)) EXIT
      lo = pos
      DO WHILE (pos <= LEN_TRIM(line))
        IF (line(pos:pos) == ' ' .OR. line(pos:pos) == CHAR(9)) EXIT
        pos = pos + 1
      END DO
      nf = nf + 1
      fields(nf) = line(lo:pos - 1)
    END DO
    IF (nf < 2) THEN
      CALL fail(ErrStat, ErrMsg, 'CONTROL row needs 2 cols: ChannelID LineID[,LineID...]')
      RETURN
    END IF
    ! Reject unconsumed trailing tokens: "1 2 3" (spaces instead of the comma list
    ! "1 2,3") would otherwise silently leave line 3 uncontrolled.
    DO WHILE (pos <= LEN_TRIM(line))
      IF (line(pos:pos) /= ' ' .AND. line(pos:pos) /= CHAR(9)) THEN
        CALL fail(ErrStat, ErrMsg, 'CONTROL row has trailing content after ChannelID and the '// &
                  'comma-separated line list (use "chan id,id" -- no spaces inside the list)')
        RETURN
      END IF
      pos = pos + 1
    END DO
    CALL parse_int_token(fields(1), c%channel, ok)
    IF (.NOT. ok .OR. c%channel < 1) THEN
      CALL fail(ErrStat, ErrMsg, 'CONTROL ChannelID must be a positive integer')
      RETURN
    END IF
    ALLOCATE (ids(0))
    lo = 1
    DO
      hi = INDEX(fields(2) (lo:), ',')
      IF (hi == 0) THEN
        piece = fields(2) (lo:)
      ELSE
        piece = fields(2) (lo:lo + hi - 2)
      END IF
      CALL parse_int_token(piece, k, ok)
      IF (.NOT. ok .OR. k < 1) THEN
        CALL fail(ErrStat, ErrMsg, 'CONTROL line list must be positive line ids separated by commas')
        RETURN
      END IF
      ids = [ids, k]
      IF (hi == 0) EXIT
      lo = lo + hi
    END DO
    CALL MOVE_ALLOC(ids, c%line_ids)

    ALLOCATE (grown(nct + 1), STAT=istat)
    IF (istat /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'CONTROL row allocation failed')
      RETURN
    END IF
    grown(1:nct) = ctrls(1:nct)
    grown(nct + 1) = c
    CALL MOVE_ALLOC(grown, ctrls)
    nct = nct + 1
  END SUBROUTINE append_control

  SUBROUTINE trim_controls(ctrls, nct)
    TYPE(DeckControl), ALLOCATABLE, INTENT(INOUT) :: ctrls(:)
    INTEGER, INTENT(IN) :: nct
    TYPE(DeckControl), ALLOCATABLE :: trimmed(:)
    IF (SIZE(ctrls) == nct) RETURN
    ALLOCATE (trimmed(nct))
    trimmed = ctrls(1:nct)
    CALL MOVE_ALLOC(trimmed, ctrls)
  END SUBROUTINE trim_controls

  SUBROUTINE validate_controls(ctrls, lines, ErrStat, ErrMsg)
    !! CONTROL rows against the parsed deck: known lines, and at most ONE channel
    !! per line (MoorDyn rejects a re-assignment).
    TYPE(DeckControl), INTENT(IN) :: ctrls(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i, j, k, lidx
    INTEGER, ALLOCATABLE :: chan_of_line(:)

    ErrStat = 0; ErrMsg = ''
    ALLOCATE (chan_of_line(SIZE(lines)))
    chan_of_line = 0
    DO i = 1, SIZE(ctrls)
      DO k = 1, SIZE(ctrls(i)%line_ids)
        lidx = 0
        DO j = 1, SIZE(lines)
          IF (lines(j)%id == ctrls(i)%line_ids(k)) lidx = j
        END DO
        IF (lidx == 0) THEN
          CALL fail(ErrStat, ErrMsg, 'CONTROL channel '//TRIM(int_to_str(ctrls(i)%channel))// &
                    ' references undefined line '//TRIM(int_to_str(ctrls(i)%line_ids(k))))
          RETURN
        END IF
        IF (chan_of_line(lidx) /= 0 .AND. chan_of_line(lidx) /= ctrls(i)%channel) THEN
          CALL fail(ErrStat, ErrMsg, 'line '//TRIM(int_to_str(lines(lidx)%id))// &
                    ' is assigned to more than one CONTROL channel')
          RETURN
        END IF
        chan_of_line(lidx) = ctrls(i)%channel
      END DO
    END DO
  END SUBROUTINE validate_controls

  SUBROUTINE read_waterkin_file(path, deck_directory, opts, ErrStat, ErrMsg, run_tmax)
    !! read_waterkin_records, with a failure located as "WaterKin file line N: ...",
    !! N being the last line read when the failure was found. deck_directory is the folder
    !! of the deck that names the WaterKin file (MoorDyn-F resolves WaveKinFile there).
    CHARACTER(*), INTENT(IN) :: path, deck_directory
    TYPE(DeckOptions), INTENT(INOUT) :: opts
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp), INTENT(IN), OPTIONAL :: run_tmax
    INTEGER :: lineno

    CALL read_waterkin_records(path, deck_directory, opts, ErrStat, ErrMsg, lineno, run_tmax)
    IF (ErrStat /= 0) CALL add_file_line('WaterKin file', lineno, ErrMsg)
  END SUBROUTINE read_waterkin_file

  SUBROUTINE read_waterkin_records(path, deck_directory, opts, ErrStat, ErrMsg, lineno, run_tmax)
    !! Read a MoorDyn v2 water-kinematics file (the WaterKin OPTION target) for
    !! STANDALONE runs. Layout (MoorDyn_Misc.f90 setupWaterKin): two header lines,
    !! a waves header, WaveKinMod, WaveKinFile, dtWave, WaveDir, three grid-axis
    !! row PAIRS (coordtype line + entries line), a current header, CurrentMod,
    !! then depth rows `z ux uy` to end of file. CurrentMod 0/1 maps onto the
    !! N-level current profile, flipped to ascending z exactly as MoorDyn does.
    !! WaveKinMod 1 resamples WaveKinFile at dtWave and reduces it to immutable
    !! Fourier components. WaveKinMod 2 and SEASTATE select the coupled shell's
    !! nodewise SeaState field and are rejected when that field is unavailable.
    !! A relative WaveKinFile is resolved against the deck's folder (deck_directory), as
    !! MoorDyn-F resolves it against its primary input; when no file exists there, the
    !! WaterKin file's own folder is tried.
    !! lineno: records read so far (0 when the failure is not tied to a line of this file).
    CHARACTER(*), INTENT(IN) :: path, deck_directory
    TYPE(DeckOptions), INTENT(INOUT) :: opts
    REAL(wp), INTENT(IN), OPTIONAL :: run_tmax
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER, INTENT(OUT) :: lineno

    INTEGER :: unit, ios, k, nrow, wavekinmod, currentmod, row_status
    CHARACTER(256) :: why
    ! Value lines are split into whitespace tokens and each value is parsed whole: a
    ! list-directed READ would stop an unquoted WaveKinFile path at its first '/' and
    ! read "0.5/2" as 0.5.
    CHARACTER(DECK_RECLEN) :: line, wave_file, wavekin_token
    REAL(wp) :: dt_wave, wave_dir, fft_tmax, zrow(3)
    REAL(wp), ALLOCATABLE :: zrows(:), uxrows(:), uyrows(:)
    LOGICAL :: found, ok

    ErrStat = 0; ErrMsg = ''
    lineno = 0
    CALL CD_Open_Input(unit, path, ios, why)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open the WaterKin file: '//TRIM(path)//input_open_reason(path, why)); RETURN
    END IF
    ! two header lines + the waves header
    DO k = 1, 3
      CALL read_raw_record(unit, line, ios, lineno)
      IF (ios /= 0) THEN
        CALL fail(ErrStat, ErrMsg, 'WaterKin file ended inside its header'); CLOSE (unit); RETURN
      END IF
    END DO
    CALL read_raw_record(unit, line, ios, lineno)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'WaterKin file has no WaveKinMod line'); CLOSE (unit); RETURN
    END IF
    CALL get_token(line, 1, wavekin_token, found)
    IF (.NOT. found) THEN
      CALL fail(ErrStat, ErrMsg, 'WaterKin WaveKinMod line has no value'); CLOSE (unit); RETURN
    END IF
    wavekinmod = 0
    IF (to_lower(TRIM(strip_quotes(wavekin_token))) == 'seastate') THEN
      opts%waterkin_seastate = .TRUE.
      opts%waterkin_host_wave = .TRUE.
      wavekinmod = 2
    ELSE
      CALL parse_int_token(wavekin_token, wavekinmod, ok)
      IF (.NOT. ok) THEN
        CALL fail(ErrStat, ErrMsg, 'WaterKin WaveKinMod must be 0, 1, 2, or SEASTATE'); CLOSE (unit); RETURN
      END IF
    END IF
    IF (wavekinmod < 0 .OR. wavekinmod > 2) THEN
      CALL fail(ErrStat, ErrMsg, 'WaterKin WaveKinMod supports 0 (none), 1 (elevation history), '// &
                'or 2 (coupled SeaState hybrid)'); CLOSE (unit); RETURN
    END IF
    opts%waterkin_wave_mode = wavekinmod
    ! WaveKinFile, dtWave, WaveDir, and the three grid-axis PAIRS are present in
    ! the MoorDyn layout even at mod 0. Mode 1 reduces the elevation history to
    ! immutable Fourier components; mode 2 delegates all kinematics to SeaState.
    CALL read_raw_record(unit, line, ios, lineno)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'WaterKin file has no WaveKinFile line'); CLOSE (unit); RETURN
    END IF
    CALL get_token(line, 1, wave_file, found)
    IF (.NOT. found) wave_file = ''
    wave_file = strip_quotes(wave_file)
    CALL read_raw_record(unit, line, ios, lineno)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'WaterKin file has no dtWave line'); CLOSE (unit); RETURN
    END IF
    CALL get_token(line, 1, wavekin_token, found)
    CALL parse_real_token(wavekin_token, dt_wave, ok)
    IF (.NOT. ok) dt_wave = -CD_ONE
    IF (.NOT. IEEE_IS_FINITE(dt_wave) .OR. dt_wave < CD_ZERO) THEN
      CALL fail(ErrStat, ErrMsg, 'WaterKin dtWave must be finite and non-negative'); CLOSE (unit); RETURN
    END IF
    CALL read_raw_record(unit, line, ios, lineno)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'WaterKin file has no WaveDir line'); CLOSE (unit); RETURN
    END IF
    CALL get_token(line, 1, wavekin_token, found)
    CALL parse_real_token(wavekin_token, wave_dir, ok)
    IF (.NOT. ok .OR. .NOT. IEEE_IS_FINITE(wave_dir)) THEN
      CALL fail(ErrStat, ErrMsg, 'WaterKin WaveDir must be finite'); CLOSE (unit); RETURN
    END IF
    DO k = 1, 6
      CALL read_raw_record(unit, line, ios, lineno)
      IF (ios /= 0) THEN
        CALL fail(ErrStat, ErrMsg, 'WaterKin file ended inside the waves block'); CLOSE (unit); RETURN
      END IF
    END DO
    IF (wavekinmod == 1) THEN
      IF (LEN_TRIM(wave_file) == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'WaterKin WaveKinMod 1 requires WaveKinFile'); CLOSE (unit); RETURN
      END IF
      IF (dt_wave <= CD_ZERO) THEN
        CALL fail(ErrStat, ErrMsg, 'WaterKin WaveKinMod 1 requires positive dtWave'); CLOSE (unit); RETURN
      END IF
      fft_tmax = opts%tmax
      IF (PRESENT(run_tmax)) fft_tmax = run_tmax
      BLOCK
        LOGICAL :: in_deck_dir
        opts%waterkin_wave_file = path_join(deck_directory, TRIM(wave_file))
        INQUIRE (FILE=TRIM(opts%waterkin_wave_file), EXIST=in_deck_dir)
        IF (.NOT. in_deck_dir) opts%waterkin_wave_file = path_join(deck_dir(path), TRIM(wave_file))
      END BLOCK
      CALL read_wave_elevation_components(TRIM(opts%waterkin_wave_file), opts, &
                                          dt_wave, wave_dir, fft_tmax, ErrStat, ErrMsg)
      ! the WaveKinFile message already names its own file and line
      IF (ErrStat /= CD_DECKDRV_OK) THEN; CLOSE (unit); lineno = 0; RETURN; END IF
    ELSE IF (wavekinmod == 2) THEN
      opts%waterkin_seastate = .TRUE.
      opts%waterkin_host_wave = .TRUE.
    END IF
    ! current header + CurrentMod
    CALL read_raw_record(unit, line, ios, lineno)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'WaterKin file has no current header'); CLOSE (unit); RETURN
    END IF
    CALL read_raw_record(unit, line, ios, lineno)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'WaterKin file has no CurrentMod line'); CLOSE (unit); RETURN
    END IF
    CALL get_token(line, 1, wavekin_token, found)
    CALL parse_int_token(wavekin_token, currentmod, ok)
    IF (.NOT. ok) THEN
      CALL fail(ErrStat, ErrMsg, 'WaterKin CurrentMod must be an integer (0, 1, or 2)')
      CLOSE (unit); RETURN
    END IF
    IF (currentmod < 0 .OR. currentmod > 2) THEN
      CALL fail(ErrStat, ErrMsg, 'WaterKin CurrentMod supports 0 (none), 1 (depth profile), or 2 (SeaState hybrid)')
      CLOSE (unit); RETURN
    END IF
    opts%waterkin_current_mode = currentmod
    IF (currentmod == 2) THEN
      IF (wavekinmod == 1) THEN
        CALL fail(ErrStat, ErrMsg, 'WaterKin WaveKinMod 1 plus CurrentMod 2 mixes self-driven waves '// &
                  'with a host SeaState current, which the nodewise host field cannot separate')
        CLOSE (unit); RETURN
      END IF
      opts%waterkin_seastate = .TRUE.
      opts%waterkin_host_current = .TRUE.
    END IF
    IF (currentmod == 1) THEN
      ! MoorDyn's exact table grammar (MoorDyn_Misc.f90, verified against the
      ! md_VIV r-test file): TWO comment rows (the column-name and units headers),
      ! then up to FOUR more lines are probed until one parses as `z ux uy` (the
      ! new file format carries two extra info lines), then rows to end of file /
      ! the trailing "need this line" terminator.
      DO k = 1, 2
        CALL read_raw_record(unit, line, ios, lineno)
        IF (ios /= 0) THEN
          CALL fail(ErrStat, ErrMsg, 'WaterKin file ended inside the current-table header')
          CLOSE (unit); RETURN
        END IF
      END DO
      nrow = 0
      ALLOCATE (zrows(0), uxrows(0), uyrows(0))
      DO k = 1, 4
        CALL read_raw_record(unit, line, ios, lineno)
        IF (ios /= 0) EXIT
        CALL parse_real_row(line, zrow, row_status)
        IF (row_status == 2) THEN
          CALL fail(ErrStat, ErrMsg, 'malformed WaterKin current row "'//TRIM(line)//'" (expected z ux uy '// &
                    'as plain numbers)')
          CLOSE (unit); RETURN
        END IF
        IF (row_status == 0) THEN
          zrows = [zrow(1)]
          uxrows = [zrow(2)]
          uyrows = [zrow(3)]
          nrow = 1
          EXIT
        END IF
      END DO
      IF (nrow /= 1) THEN
        CALL fail(ErrStat, ErrMsg, 'could not find the WaterKin current profile table (checked 4 lines '// &
                  'after the two headers, the MoorDyn probe)')
        CLOSE (unit); RETURN
      END IF
      DO
        CALL read_raw_record(unit, line, ios, lineno)
        IF (ios /= 0) EXIT
        CALL parse_real_row(line, zrow, row_status)
        IF (row_status == 2) THEN
          CALL fail(ErrStat, ErrMsg, 'malformed WaterKin current row "'//TRIM(line)//'" (expected z ux uy '// &
                    'as plain numbers)')
          CLOSE (unit); RETURN
        END IF
        ! a non-numeric row (the terminator) ends the table
        IF (row_status /= 0) EXIT
        zrows = [zrows, zrow(1)]
        uxrows = [uxrows, zrow(2)]
        uyrows = [uyrows, zrow(3)]
        nrow = nrow + 1
      END DO
      ! the checks below concern the whole depth table, not one line
      lineno = 0
      IF (nrow < 2) THEN
        CALL fail(ErrStat, ErrMsg, 'WaterKin CurrentMod 1 needs at least two `z ux uy` depth rows')
        CLOSE (unit); RETURN
      END IF
      ! The z-depth column exists in TWO conventions: the shipped r-test files use
      ! z ELEVATIONS (-11..0, matching MoorDyn's code, which warns above the
      ! waterline), while the DOCUMENTATION uses positive-down depths (0, 150,
      ! 1000). Disambiguate by sign: all-nonpositive = elevations as-is;
      ! all-nonnegative with a positive entry = documented depths, converted to
      ! z = -depth (MoorDyn reads the column as elevations; CableDyn converts an
      ! all-non-negative column to z = -depth, the documented convention); MIXED
      ! signs are ambiguous and fail closed.
      IF (ANY(zrows > CD_ZERO)) THEN
        IF (ALL(zrows >= CD_ZERO)) THEN
          zrows = -zrows
        ELSE
          CALL fail(ErrStat, ErrMsg, 'WaterKin current depth column mixes signs: use either z '// &
                    'elevations (<= 0, the r-test convention) or positive-down depths (>= 0, the '// &
                    'documented convention)')
          CLOSE (unit); RETURN
        END IF
      END IF
      IF (.NOT. (ALL(IEEE_IS_FINITE(zrows)) .AND. ALL(IEEE_IS_FINITE(uxrows)) .AND. &
                 ALL(IEEE_IS_FINITE(uyrows)))) THEN
        CALL fail(ErrStat, ErrMsg, 'WaterKin current depth rows must be finite'); CLOSE (unit); RETURN
      END IF
      ! flip to ascending z exactly as MoorDyn does (deepest first is accepted)
      IF (zrows(1) > zrows(nrow)) THEN
        zrows = zrows(nrow:1:-1)
        uxrows = uxrows(nrow:1:-1)
        uyrows = uyrows(nrow:1:-1)
      END IF
      DO k = 1, nrow - 1
        IF (zrows(k + 1) - zrows(k) <= 100.0_wp*EPSILON(CD_ONE)) THEN
          CALL fail(ErrStat, ErrMsg, 'WaterKin current depths must be strictly monotonic')
          CLOSE (unit); RETURN
        END IF
      END DO
      IF (opts%has_current .OR. opts%has_current_profile) THEN
        CALL fail(ErrStat, ErrMsg, 'the deck declares BOTH a current OPTION and a WaterKin current '// &
                  '(double-counting); keep one'); CLOSE (unit); RETURN
      END IF
      IF (ALLOCATED(opts%current_profile_z)) DEALLOCATE (opts%current_profile_z)
      IF (ALLOCATED(opts%current_profile_velocity)) DEALLOCATE (opts%current_profile_velocity)
      ALLOCATE (opts%current_profile_z(nrow), opts%current_profile_velocity(3, nrow))
      opts%current_profile_z = zrows
      opts%current_profile_velocity(1, :) = uxrows
      opts%current_profile_velocity(2, :) = uyrows
      opts%current_profile_velocity(3, :) = CD_ZERO
      opts%has_current = .TRUE.
      opts%has_current_profile = .TRUE.
    END IF
    CLOSE (unit)
  END SUBROUTINE read_waterkin_records

  SUBROUTINE read_wave_elevation_components(path, opts, dt_wave, wave_dir, fft_tmax, ErrStat, ErrMsg)
    !! Read the MoorDyn-F WaveKinMod-1 `time elevation` history and reduce its
    !! dtWave-resampled real signal to the nonzero-frequency DFT components.
    !! The one-time O(N^2) setup avoids a runtime FFT dependency and is exact at
    !! the resampled stations; runtime evaluation uses CD_Component_Wave_Kinematics.
    CHARACTER(*), INTENT(IN) :: path
    TYPE(DeckOptions), INTENT(INOUT) :: opts
    REAL(wp), INTENT(IN) :: dt_wave, wave_dir, fft_tmax
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: unit, ios, n, n_window, j, k, nc, nraw, bracket, row_status, lineno
    CHARACTER(DECK_RECLEN) :: line
    CHARACTER(256) :: why
    REAL(wp) :: te_row(2), tr, dt, tol, angle, ca, sa, scale, frac
    REAL(wp) :: cos_step, sin_step, cos_j, sin_j, cos_next, trig_norm
    REAL(wp), ALLOCATABLE :: times(:), eta_rows(:), sample_eta(:)
    LOGICAL :: data_started

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (opts%has_wave) THEN
      CALL fail(ErrStat, ErrMsg, 'the deck declares BOTH a waves OPTION and WaterKin WaveKinMod 1 '// &
                '(double-counting); keep one')
      RETURN
    END IF
    IF (.NOT. IEEE_IS_FINITE(fft_tmax) .OR. fft_tmax <= CD_ZERO) THEN
      CALL fail(ErrStat, ErrMsg, 'WaterKin WaveKinMod 1 requires a finite positive deck or '// &
                'host TMax for its FFT window')
      RETURN
    END IF
    CALL CD_Open_Input(unit, path, ios, why)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open the WaterKin WaveKinFile: '//TRIM(path)// &
                input_open_reason(path, why)); RETURN
    END IF
    ALLOCATE (times(0), eta_rows(0))
    data_started = .FALSE.
    lineno = 0
    DO
      CALL read_raw_record(unit, line, ios, lineno)
      IF (ios /= 0) EXIT
      IF (is_blank_text(line)) CYCLE
      CALL parse_real_row(line, te_row, row_status)
      IF (row_status == 2) THEN
        CLOSE (unit)
        CALL fail(ErrStat, ErrMsg, 'WaterKin WaveKinFile row "'//TRIM(line)//'" is not "time elevation" '// &
                  'in plain numbers')
        CALL add_file_line('WaterKin WaveKinFile', lineno, ErrMsg)
        RETURN
      END IF
      IF (row_status /= 0) THEN
        IF (data_started) THEN
          CLOSE (unit)
          CALL fail(ErrStat, ErrMsg, 'WaterKin WaveKinFile contains a non-data row after its history begins')
          CALL add_file_line('WaterKin WaveKinFile', lineno, ErrMsg)
          RETURN
        END IF
        CYCLE
      END IF
      data_started = .TRUE.
      times = [times, te_row(1)]
      eta_rows = [eta_rows, te_row(2)]
    END DO
    CLOSE (unit)
    nraw = SIZE(times)
    IF (nraw < 4) THEN
      CALL fail(ErrStat, ErrMsg, 'WaterKin WaveKinFile needs at least four `time elevation` rows'); RETURN
    END IF
    IF (.NOT. (ALL(IEEE_IS_FINITE(times)) .AND. ALL(IEEE_IS_FINITE(eta_rows)))) THEN
      CALL fail(ErrStat, ErrMsg, 'WaterKin WaveKinFile rows must be finite'); RETURN
    END IF
    tol = 1000.0_wp*EPSILON(CD_ONE)*MAX(CD_ONE, ABS(times(nraw)))
    IF (ABS(times(1)) > tol) THEN
      CALL fail(ErrStat, ErrMsg, 'WaterKin WaveKinFile time history must start at t = 0'); RETURN
    END IF
    DO j = 1, nraw - 1
      IF (times(j + 1) <= times(j)) THEN
        CALL fail(ErrStat, ErrMsg, 'WaterKin WaveKinFile times must be strictly increasing'); RETURN
      END IF
    END DO
    ! MoorDyn-F sizes the resampled record from the RUN TMax, not from the input
    ! file length, then zero-pads to an efficient even FFT size. A longer file is
    ! truncated to the run window; a shorter file leaves the uncovered tail zero.
    dt = dt_wave
    ! Bound the resampled record before sizing it: CEILING of a ratio beyond the
    ! INTEGER range is undefined, and the one-time DFT setup grows with its square.
    IF (.NOT. (fft_tmax/dt <= MAX_WAVE_SAMPLES)) THEN
      CALL fail(ErrStat, ErrMsg, 'WaterKin TMax/dtWave needs more than '//TRIM(int_to_str(INT(MAX_WAVE_SAMPLES)))// &
                ' wave samples; increase dtWave or reduce TMax'); RETURN
    END IF
    n_window = CEILING(fft_tmax/dt)
    n = padded_fft_size(n_window)
    IF (n > LONG_WAVE_RECORD) WRITE (error_unit, '(A)') '   Note: reducing the WaterKin wave record ('// &
      TRIM(int_to_str(n))//' samples) to Fourier components; this one-time setup grows with the square '// &
      'of the sample count (a larger dtWave shortens it).'
    ALLOCATE (sample_eta(n))
    sample_eta = CD_ZERO
    bracket = 1
    DO j = 1, n_window
      tr = REAL(j - 1, wp)*dt
      IF (tr > times(nraw) + tol) CYCLE
      IF (ABS(tr - times(nraw)) <= tol) THEN
        sample_eta(j) = eta_rows(nraw)
        CYCLE
      END IF
      DO WHILE (bracket < nraw - 1 .AND. times(bracket + 1) < tr)
        bracket = bracket + 1
      END DO
      frac = (tr - times(bracket))/(times(bracket + 1) - times(bracket))
      sample_eta(j) = eta_rows(bracket) + frac*(eta_rows(bracket + 1) - eta_rows(bracket))
    END DO
    times = [(REAL(j - 1, wp)*dt, j=1, n)]
    eta_rows = sample_eta

    nc = n/2
    IF (ALLOCATED(opts%wave_component_omega)) DEALLOCATE (opts%wave_component_omega)
    IF (ALLOCATED(opts%wave_component_k)) DEALLOCATE (opts%wave_component_k)
    IF (ALLOCATED(opts%wave_component_amplitude)) DEALLOCATE (opts%wave_component_amplitude)
    IF (ALLOCATED(opts%wave_component_phase)) DEALLOCATE (opts%wave_component_phase)
    ALLOCATE (opts%wave_component_omega(nc), opts%wave_component_k(nc), &
              opts%wave_component_amplitude(nc), opts%wave_component_phase(nc))
    opts%wave_eta_mean = SUM(eta_rows)/REAL(n, wp)
    DO k = 1, nc
      ca = CD_ZERO
      sa = CD_ZERO
      angle = TWO_PI*REAL(k, wp)/REAL(n, wp)
      cos_step = COS(angle)
      sin_step = SIN(angle)
      cos_j = CD_ONE
      sin_j = CD_ZERO
      DO j = 1, n
        ca = ca + (eta_rows(j) - opts%wave_eta_mean)*cos_j
        sa = sa + (eta_rows(j) - opts%wave_eta_mean)*sin_j
        cos_next = cos_j*cos_step - sin_j*sin_step
        sin_j = sin_j*cos_step + cos_j*sin_step
        cos_j = cos_next
        IF (MOD(j, 256) == 0) THEN
          trig_norm = SQRT(cos_j*cos_j + sin_j*sin_j)
          cos_j = cos_j/trig_norm
          sin_j = sin_j/trig_norm
        END IF
      END DO
      scale = 2.0_wp/REAL(n, wp)
      IF (MOD(n, 2) == 0 .AND. k == nc) scale = CD_ONE/REAL(n, wp)
      ca = scale*ca
      sa = scale*sa
      ! Coefficients and runtime components must share the padded DFT time base.
      opts%wave_component_omega(k) = TWO_PI*REAL(k, wp)/(REAL(n, wp)*dt)
      opts%wave_component_k(k) = CD_ZERO
      opts%wave_component_amplitude(k) = SQRT(ca*ca + sa*sa)
      opts%wave_component_phase(k) = opts%wave_component_omega(k)*times(1) + ATAN2(sa, ca)
    END DO
    opts%wave_direction = wave_dir
    opts%wave_kind = WAVE_COMPONENTS
    opts%has_wave = .TRUE.
  CONTAINS

    INTEGER FUNCTION padded_fft_size(nwanted) RESULT(nfft)
      !! MoorDyn-F uses 2*PSF(ceil(nwanted/2), 9). Reproduce the effective
      !! small-prime (2,3,5,7) search without taking an FFT dependency.
      INTEGER, INTENT(IN) :: nwanted
      INTEGER :: half

      half = MAX((nwanted + 1)/2, 1)
      DO WHILE (.NOT. is_fft_smooth(half))
        half = half + 1
      END DO
      nfft = 2*half
    END FUNCTION padded_fft_size

    LOGICAL FUNCTION is_fft_smooth(value) RESULT(smooth)
      INTEGER, INTENT(IN) :: value
      INTEGER, PARAMETER :: primes(4) = [2, 3, 5, 7]
      INTEGER :: remainder, i, p

      remainder = value
      DO i = 1, SIZE(primes)
        p = primes(i)
        DO WHILE (MOD(remainder, p) == 0)
          remainder = remainder/p
        END DO
      END DO
      smooth = (remainder == 1)
    END FUNCTION is_fft_smooth

  END SUBROUTINE read_wave_elevation_components

  SUBROUTINE read_moordyn_c_kinematics(dir, opts, ErrStat, ErrMsg)
    !! The MoorDyn-C (v2.7.1) numeric water-kinematics OPTIONS, read from their fixed-name files in
    !! the deck folder and reduced to CableDyn's component waves and depth-profile current, which
    !! are evaluated exactly at every node (MoorDyn-C tabulates them on water_grid.txt and
    !! interpolates; that file is not read):
    !!  - WaveKin 3, wave_elevation.txt (`time elevation` rows from t = 0): resampled linearly at
    !!    dtWave to floor(t_last/dtWave) + 1 samples, the last dropped when odd, and reduced to
    !!    its discrete Fourier components; components above 0.5 Hz are dropped and the mean is
    !!    the mean-level offset, as MoorDyn-C does. Waves travel along +x.
    !!  - WaveKin 7, wave_frequencies.txt (`omega Re Im [beta]` rows, the first at omega = 0):
    !!    each row is the component |c| sin(omega t - k d + arg c) of MoorDyn-C's SUM_COMPONENTS
    !!    mode, d = x cos(beta) + y sin(beta); the omega = 0 row is the mean-level offset. The rows
    !!    must share one direction beta.
    !!  - Currents 1, current_profile.txt (`z ux uy uz` rows after its header rows): the steady
    !!    profile, linear in z and held beyond its ends, as MoorDyn-C's current grid.
    CHARACTER(*), INTENT(IN) :: dir
    TYPE(DeckOptions), INTENT(INOUT) :: opts
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp), ALLOCATABLE :: tab(:, :), eta(:), comp_w(:), comp_a(:), comp_p(:)
    REAL(wp) :: dt, tl, frac, ca, sa, angle, scale, beta, mean_level, arg
    INTEGER :: n, nt, j, k, nc, bracket
    INTEGER(KIND=8) :: kj
    CHARACTER(24) :: fname

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    beta = CD_ZERO
    mean_level = CD_ZERO
    fname = ''
    IF (opts%mdc_wave_kin > 0) THEN
      IF (opts%has_wave) THEN
        CALL fail(ErrStat, ErrMsg, 'the deck declares BOTH a waves OPTION and WaveKin '// &
                  TRIM(int_to_str(opts%mdc_wave_kin))//' (double-counting); keep one'); RETURN
      END IF
      IF (opts%has_waterkin_file) THEN
        CALL fail(ErrStat, ErrMsg, 'the deck declares BOTH a WaterKin file and WaveKin '// &
                  TRIM(int_to_str(opts%mdc_wave_kin))//'; keep one'); RETURN
      END IF
    END IF
    SELECT CASE (opts%mdc_wave_kin)
    CASE (3)
      fname = 'wave_elevation.txt'
      CALL read_table(fname, 2, 2, .FALSE., tab)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      n = SIZE(tab, 2)
      IF (n < 4) THEN
        CALL fail(ErrStat, ErrMsg, 'WaveKin 3: wave_elevation.txt needs at least four `time elevation` rows'); RETURN
      END IF
      IF (ABS(tab(1, 1)) > 1000.0_wp*EPSILON(CD_ONE)*MAX(CD_ONE, ABS(tab(1, n)))) THEN
        CALL fail(ErrStat, ErrMsg, 'WaveKin 3: wave_elevation.txt must start at t = 0'); RETURN
      END IF
      DO j = 1, n - 1
        IF (.NOT. tab(1, j + 1) > tab(1, j)) THEN
          CALL fail(ErrStat, ErrMsg, 'WaveKin 3: wave_elevation.txt times must be strictly increasing'); RETURN
        END IF
      END DO
      dt = opts%mdc_dt_wave
      IF (.NOT. (IEEE_IS_FINITE(dt) .AND. dt > CD_ZERO)) THEN
        CALL fail(ErrStat, ErrMsg, 'WaveKin 3 needs a positive dtWave'); RETURN
      END IF
      tl = tab(1, n)
      IF (.NOT. (tl/dt <= MAX_WAVE_SAMPLES)) THEN
        CALL fail(ErrStat, ErrMsg, 'WaveKin 3: wave_elevation.txt spans more than '// &
                  TRIM(int_to_str(INT(MAX_WAVE_SAMPLES)))//' dtWave samples; increase dtWave'); RETURN
      END IF
      nt = FLOOR(tl/dt) + 1
      IF (MOD(nt, 2) /= 0) nt = nt - 1
      IF (nt > LONG_WAVE_RECORD) WRITE (error_unit, '(A)') '   Note: reducing wave_elevation.txt ('// &
        TRIM(int_to_str(nt))//' samples) to Fourier components; this one-time setup grows with the square '// &
        'of the sample count (a larger dtWave shortens it).'
      IF (nt < 4) THEN
        CALL fail(ErrStat, ErrMsg, 'WaveKin 3: wave_elevation.txt spans fewer than four dtWave samples'); RETURN
      END IF
      ALLOCATE (eta(nt))
      bracket = 1
      DO j = 1, nt
        tl = REAL(j - 1, wp)*dt
        DO WHILE (bracket < n - 1 .AND. tab(1, bracket + 1) < tl)
          bracket = bracket + 1
        END DO
        frac = (tl - tab(1, bracket))/(tab(1, bracket + 1) - tab(1, bracket))
        frac = MIN(CD_ONE, MAX(CD_ZERO, frac))
        eta(j) = tab(2, bracket) + frac*(tab(2, bracket + 1) - tab(2, bracket))
      END DO
      ! discrete Fourier components on the record's own base (period nt dt); MoorDyn-C zeroes the
      ! bins above 0.5 Hz and keeps the mean
      mean_level = SUM(eta)/REAL(nt, wp)
      ALLOCATE (comp_w(0), comp_a(0), comp_p(0))
      DO k = 1, nt/2
        angle = TWO_PI*REAL(k, wp)/(REAL(nt, wp)*dt)
        IF (angle > 0.5_wp*TWO_PI) EXIT
        ca = CD_ZERO
        sa = CD_ZERO
        DO j = 1, nt
          kj = MOD(INT(k, KIND=8)*INT(j - 1, KIND=8), INT(nt, KIND=8))
          arg = TWO_PI*REAL(kj, wp)/REAL(nt, wp)
          ca = ca + (eta(j) - mean_level)*COS(arg)
          sa = sa + (eta(j) - mean_level)*SIN(arg)
        END DO
        scale = 2.0_wp/REAL(nt, wp)
        IF (k == nt/2) scale = CD_ONE/REAL(nt, wp)
        ca = scale*ca
        sa = scale*sa
        comp_w = [comp_w, angle]
        comp_a = [comp_a, SQRT(ca*ca + sa*sa)]
        comp_p = [comp_p, ATAN2(sa, ca)]
      END DO
      CALL install_components()
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CASE (7)
      fname = 'wave_frequencies.txt'
      CALL read_table(fname, 3, 4, .FALSE., tab)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      n = SIZE(tab, 2)
      IF (n < 2) THEN
        CALL fail(ErrStat, ErrMsg, 'WaveKin 7: wave_frequencies.txt needs at least two `omega Re Im` rows'); RETURN
      END IF
      IF (ABS(tab(1, 1)) > CD_ZERO) THEN
        CALL fail(ErrStat, ErrMsg, 'WaveKin 7: the first wave_frequencies.txt row must be at omega = 0'); RETURN
      END IF
      beta = tab(4, 1)
      DO j = 1, n
        IF (ABS(tab(4, j)) > TWO_PI) THEN
          CALL fail(ErrStat, ErrMsg, 'WaveKin 7: wave_frequencies.txt directions are radians within +-2 pi'); RETURN
        END IF
        IF (ABS(tab(4, j) - beta) > 1.0e-12_wp) THEN
          CALL fail(ErrStat, ErrMsg, 'WaveKin 7: wave_frequencies.txt rows with different directions '// &
                    '(short-crested seas) are not supported; give every row one direction'); RETURN
        END IF
        IF (j > 1) THEN
          IF (.NOT. tab(1, j) > CD_ZERO) THEN
            CALL fail(ErrStat, ErrMsg, 'WaveKin 7: wave_frequencies.txt frequencies after the first row '// &
                      'must be positive'); RETURN
          END IF
        END IF
      END DO
      ! |c| sin(omega t - k d + arg c) = |c| cos(k d - omega t + pi/2 - arg c)
      mean_level = tab(3, 1)
      comp_w = tab(1, 2:n)
      comp_a = SQRT(tab(2, 2:n)**2 + tab(3, 2:n)**2)
      comp_p = 0.25_wp*TWO_PI - ATAN2(tab(3, 2:n), tab(2, 2:n))
      CALL install_components()
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END SELECT
    IF (opts%mdc_currents == 1) THEN
      IF (opts%has_current) THEN
        CALL fail(ErrStat, ErrMsg, 'the deck declares BOTH a current OPTION (or a WaterKin current) and '// &
                  'Currents 1 (double-counting); keep one'); RETURN
      END IF
      fname = 'current_profile.txt'
      CALL read_table(fname, 3, 4, .TRUE., tab)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      n = SIZE(tab, 2)
      IF (n < 1) THEN
        CALL fail(ErrStat, ErrMsg, 'Currents 1: current_profile.txt has no `z ux uy uz` rows'); RETURN
      END IF
      DO j = 1, n - 1
        IF (.NOT. tab(1, j + 1) > tab(1, j)) THEN
          CALL fail(ErrStat, ErrMsg, 'Currents 1: current_profile.txt depths must be strictly increasing'); RETURN
        END IF
      END DO
      IF (ALLOCATED(opts%current_profile_z)) DEALLOCATE (opts%current_profile_z)
      IF (ALLOCATED(opts%current_profile_velocity)) DEALLOCATE (opts%current_profile_velocity)
      opts%current_profile_z = tab(1, :)
      opts%current_profile_velocity = tab(2:4, :)
      opts%has_current = .TRUE.
      opts%has_current_profile = .TRUE.
    END IF

  CONTAINS

    SUBROUTINE install_components()
      !! The component waves (omega, amplitude, phase in CableDyn's cos(k d - omega t + phase)
      !! convention), their direction beta [rad] and the mean level.
      IF (.NOT. (ALL(IEEE_IS_FINITE(comp_w)) .AND. ALL(IEEE_IS_FINITE(comp_a)) .AND. &
                 ALL(IEEE_IS_FINITE(comp_p)) .AND. IEEE_IS_FINITE(mean_level))) THEN
        CALL fail(ErrStat, ErrMsg, 'WaveKin '//TRIM(int_to_str(opts%mdc_wave_kin))//': '//TRIM(fname)// &
                  ' gives non-finite wave components'); RETURN
      END IF
      nc = SIZE(comp_w)
      IF (nc < 1) THEN
        CALL fail(ErrStat, ErrMsg, 'WaveKin '//TRIM(int_to_str(opts%mdc_wave_kin))//': '//TRIM(fname)// &
                  ' gives no wave component at or below 0.5 Hz'); RETURN
      END IF
      IF (ALLOCATED(opts%wave_component_omega)) DEALLOCATE (opts%wave_component_omega)
      IF (ALLOCATED(opts%wave_component_k)) DEALLOCATE (opts%wave_component_k)
      IF (ALLOCATED(opts%wave_component_amplitude)) DEALLOCATE (opts%wave_component_amplitude)
      IF (ALLOCATED(opts%wave_component_phase)) DEALLOCATE (opts%wave_component_phase)
      ALLOCATE (opts%wave_component_k(nc))
      opts%wave_component_omega = comp_w
      opts%wave_component_k = CD_ZERO
      opts%wave_component_amplitude = comp_a
      opts%wave_component_phase = comp_p
      opts%wave_eta_mean = mean_level
      opts%wave_direction = beta*45.0_wp/ATAN(CD_ONE)
      opts%wave_kind = WAVE_COMPONENTS
      opts%has_wave = .TRUE.
    END SUBROUTINE install_components

    SUBROUTINE read_table(name, nmin, nmax, headers, t)
      !! The numeric rows of file name in the deck folder: nmin to nmax columns (missing optional
      !! columns zero). headers: leading non-numeric rows are skipped; otherwise every non-blank
      !! row must be numeric, as MoorDyn-C reads these files.
      CHARACTER(*), INTENT(IN) :: name
      INTEGER, INTENT(IN) :: nmin, nmax
      LOGICAL, INTENT(IN) :: headers
      REAL(wp), ALLOCATABLE, INTENT(OUT) :: t(:, :)
      REAL(wp), ALLOCATABLE :: grown(:, :)
      REAL(wp) :: row(nmax)
      INTEGER :: unit, ios, st, lineno, nrow, nc_row
      LOGICAL :: started
      CHARACTER(DECK_RECLEN) :: line
      CHARACTER(256) :: why
      CHARACTER(CD_DECK_PATHLEN) :: fpath
      ALLOCATE (t(nmax, 16))
      fpath = path_join(dir, TRIM(name))
      CALL CD_Open_Input(unit, TRIM(fpath), ios, why)
      IF (ios /= 0) THEN
        CALL fail(ErrStat, ErrMsg, 'cannot open the MoorDyn-C kinematics file '//TRIM(fpath)// &
                  input_open_reason(TRIM(fpath), why)); RETURN
      END IF
      nrow = 0
      lineno = 0
      started = .FALSE.
      DO
        CALL read_raw_record(unit, line, ios, lineno)
        IF (ios /= 0) EXIT
        IF (is_blank_text(line)) CYCLE
        row = CD_ZERO
        st = 1
        DO nc_row = nmax, nmin, -1
          CALL parse_real_row(line, row(1:nc_row), st)
          IF (st == 0) EXIT
        END DO
        IF (st == 1 .AND. headers .AND. .NOT. started) CYCLE
        IF (st /= 0) THEN
          CLOSE (unit)
          CALL fail(ErrStat, ErrMsg, TRIM(name)//' row "'//TRIM(line)//'" is not '// &
                    TRIM(int_to_str(nmin))//' to '//TRIM(int_to_str(nmax))//' plain numbers')
          CALL add_file_line(TRIM(name), lineno, ErrMsg)
          RETURN
        END IF
        IF (nc_row < nmax) row(nc_row + 1:nmax) = CD_ZERO
        IF (.NOT. ALL(IEEE_IS_FINITE(row))) THEN
          CLOSE (unit)
          CALL fail(ErrStat, ErrMsg, TRIM(name)//' values must be finite')
          CALL add_file_line(TRIM(name), lineno, ErrMsg)
          RETURN
        END IF
        started = .TRUE.
        nrow = nrow + 1
        IF (nrow > SIZE(t, 2)) THEN
          ALLOCATE (grown(nmax, 2*SIZE(t, 2)))
          grown(:, 1:nrow - 1) = t(:, 1:nrow - 1)
          CALL MOVE_ALLOC(grown, t)
        END IF
        t(:, nrow) = row
      END DO
      CLOSE (unit)
      t = t(:, 1:nrow)
    END SUBROUTINE read_table
  END SUBROUTINE read_moordyn_c_kinematics

  SUBROUTINE set_section(secname, section, ErrStat, ErrMsg)
    CHARACTER(*), INTENT(IN) :: secname
    INTEGER, INTENT(OUT) :: section
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    ErrStat = 0; ErrMsg = ''
    ! A bare dashed rule, or the conventional MoorDyn end markers ("need this line",
    ! "END"), close the current section (no data follows until the next header).
    ! The stock MoorDyn deck TITLE BANNER ("--- MoorDyn Input File ---", first line of
    ! every OpenFAST-shipped deck) is the same dashed style and is preamble, not a
    ! section: tolerate it (and its free-text title line) the way MoorDyn itself does.
    ! All other unrecognized headers still fail closed below.
    IF (LEN_TRIM(secname) == 0 .OR. TRIM(secname) == 'END' .OR. INDEX(secname, 'NEED') > 0 .OR. &
        INDEX(secname, 'INPUT FILE') > 0) THEN
      section = 0; RETURN
    END IF
    SELECT CASE (TRIM(secname))
    CASE ('LINE TYPES', 'LINETYPES', 'LINE DICTIONARY')
      section = 1
    CASE ('BODIES', 'BODY')
      section = 2
    CASE ('POINTS', 'CONNECTION PROPERTIES', 'POINT PROPERTIES', 'CONNECTS')
      section = 3
    CASE ('LINES', 'LINE PROPERTIES')
      section = 4
    CASE ('SECTIONS')
      section = 5
    CASE ('OPTIONS', 'SOLVER OPTIONS')
      section = 6
    CASE ('OUTPUTS', 'OUTPUT')
      section = 7
    CASE ('ROD TYPES', 'RODTYPES', 'ROD DICTIONARY')
      section = 8
    CASE ('RODS', 'ROD LIST', 'ROD PROPERTIES')
      section = 9
    CASE ('EQUIVALENT BUOYANCY', 'EQUIVALENT SECTIONS', 'BUOYANCY SECTIONS')
      section = 10
    CASE ('FAILURE', 'FAILURES')
      section = 11
    CASE ('CONTROL', 'CONTROLS')
      section = 12
    CASE ('SYROPE IC')
      section = 13
    CASE ('END CONNECTIONS', 'END CONNECTION')
      section = 14
    CASE ('TURBINES', 'TURBINE')
      section = 15
    CASE ('EXTERNAL LOADS', 'EXTERNAL LOAD')
      section = 16
    CASE ('ATTACHMENTS', 'LINE ATTACHMENTS', 'CLUMPS')
      section = 17
    CASE DEFAULT
      IF (LEN_TRIM(secname) > NAMELEN) THEN
        CALL fail(ErrStat, ErrMsg, 'unknown deck section "'//secname(1:NAMELEN)//'..."')
      ELSE
        CALL fail(ErrStat, ErrMsg, 'unknown deck section "'//TRIM(secname)//'"')
      END IF
    END SELECT
  END SUBROUTINE set_section

  SUBROUTINE sniff_types_header(line, stock_cols)
    !! LINE TYPES column-order detection from the section's header row. The stock
    !! MoorDyn order (Cd Ca CdAx CaAx = normal drag, normal added mass, axial drag,
    !! axial added mass) and the CableDyn order (Cdn Cdt Can Cat) are positionally
    !! indistinguishable in the data rows, so the header names decide: 'CdAx'/'CaAx'
    !! selects the stock order, 'Cdt' the CableDyn order. Units rows and a deck with
    !! no recognizable header leave the order unchanged (default: CableDyn).
    CHARACTER(*), INTENT(IN) :: line
    LOGICAL, INTENT(INOUT) :: stock_cols
    CHARACTER(LEN(line)) :: lo
    lo = to_lower(line)
    IF (INDEX(lo, 'cdax') > 0 .OR. INDEX(lo, 'caax') > 0) THEN
      stock_cols = .TRUE.
    ELSE IF (INDEX(lo, 'cdt') > 0 .OR. INDEX(lo, 'cd_t') > 0) THEN
      stock_cols = .FALSE.
    END IF
  END SUBROUTINE sniff_types_header

  SUBROUTINE append_type(line, types, nt, stock_cols, ErrStat, ErrMsg)
    CHARACTER(*), INTENT(IN) :: line
    TYPE(DeckLineType), ALLOCATABLE, INTENT(INOUT) :: types(:)
    INTEGER, INTENT(INOUT) :: nt
    LOGICAL, INTENT(IN) :: stock_cols
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(DeckLineType) :: t
    ! EA may hold SYROPE:<settings path>|alpha|beta, so it gets a path-length buffer
    CHARACTER(CD_DECK_PATHLEN) :: ea_str
    CHARACTER(NAMELEN) :: ba_str
    INTEGER :: ios, ntok
    ErrStat = 0; ErrMsg = ''
    ntok = count_tokens(line)
    IF (ntok /= 10 .AND. ntok /= 14) THEN
      CALL fail(ErrStat, ErrMsg, 'LINE TYPES row needs 10 cols '// &
                '(Name Diam MassDenInAir EA BA/-zeta EI Cd_n Cd_t Ca_n Ca_t) or 14 cols '// &
                '(Name Diam MassDenInAir EA BA/-zeta EI GAs GJ Irt Irn Cd_n Cd_t Ca_n Ca_t)'); RETURN
    END IF
    ! EA and BA read as STRINGS: MoorDyn's viscoelastic syntax carries
    ! bar-separated parts (Es|Ed[|alpha], Bs|Bd) that a numeric read cannot see.
    IF (ntok == 10) THEN
      IF (stock_cols) THEN
        ! stock MoorDyn header order: Cd Ca CdAx CaAx = (Cd_n, Ca_n, Cd_t, Ca_t)
        READ (line, *, IOSTAT=ios) t%name, t%diam, t%mass, ea_str, ba_str, t%ei, t%cdn, t%can, t%cdt, t%cat
      ELSE
        READ (line, *, IOSTAT=ios) t%name, t%diam, t%mass, ea_str, ba_str, t%ei, t%cdn, t%cdt, t%can, t%cat
      END IF
    ELSE
      IF (stock_cols) THEN
        CALL fail(ErrStat, ErrMsg, 'the 14-column LINE TYPES row is a CableDyn form (... Cd_n Cd_t '// &
                  'Ca_n Ca_t); it does not combine with a stock-order header (Cd Ca CdAx CaAx)'); RETURN
      END IF
      READ (line, *, IOSTAT=ios) t%name, t%diam, t%mass, ea_str, ba_str, t%ei, t%gas, t%gj, t%i_rt, t%i_rn, &
        t%cdn, t%cdt, t%can, t%cat
    END IF
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'malformed LINE TYPES row'); RETURN
    END IF
    ! Drag and added-mass coefficients are magnitudes; a negative value would inject
    ! energy. Rejected here, with the row, on every route (static decks included).
    IF (t%cdn < CD_ZERO .OR. t%cdt < CD_ZERO .OR. t%can < CD_ZERO .OR. t%cat < CD_ZERO) THEN
      CALL fail(ErrStat, ErrMsg, 'LINE TYPES drag and added-mass coefficients (Cd_n Cd_t Ca_n Ca_t) '// &
                'must be non-negative'); RETURN
    END IF
    CALL parse_stiffness_columns(ea_str, ba_str, t, ErrStat, ErrMsg)
    IF (ErrStat /= 0) RETURN
    CALL grow_types(types, nt)
    nt = nt + 1; types(nt) = t
  END SUBROUTINE append_type

  SUBROUTINE parse_stiffness_columns(ea_str, ba_str, t, ErrStat, ErrMsg)
    !! MoorDyn's bar-separated stiffness/damping columns (MoorDyn.f90 line-type
    !! parse): EA parts select ElasticMod (1 plain; 2 = Es|Ed; 3 = Es|alphaMBL|
    !! vbeta; more is fatal); BA may carry Bs|Bd with no more parts than EA.
    CHARACTER(*), INTENT(IN) :: ea_str, ba_str
    TYPE(DeckLineType), INTENT(INOUT) :: t
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    CHARACTER(CD_DECK_PATHLEN) :: parts(3)
    INTEGER :: n_ea, n_ba, defect
    LOGICAL :: ok

    ErrStat = 0; ErrMsg = ''
    CALL split_bars(ea_str, parts, n_ea)
    IF (n_ea < 1 .OR. n_ea > 3) THEN
      CALL fail(ErrStat, ErrMsg, 'a LINE TYPES EA entry can have at most 3 bar-separated values'); RETURN
    END IF
    ! Syrope working-curve dialect: EA = SYROPE:<file>|alpha|beta (a settings
    ! file, not a numeric stiffness), BA = BA_s|BA_d. Detected on the first part so
    ! the numeric EA read below never sees the non-numeric token.
    IF (is_syrope_token(parts(1))) THEN
      ! the EA token was read through a fixed-width buffer, so a long SYROPE
      ! settings path could be silently truncated; a full buffer fails closed
      ! rather than resolving a wrong (shortened) path.
      IF (LEN_TRIM(ea_str) >= LEN(ea_str)) THEN
        CALL fail(ErrStat, ErrMsg, 'the Syrope EA column filled the input buffer and may be truncated '// &
                  '(shorten the SYROPE settings path)'); RETURN
      END IF
      CALL parse_syrope_columns(parts, n_ea, ba_str, t, ErrStat, ErrMsg)
      RETURN
    END IF
    CALL parse_real_token(parts(1), t%ea, ok, defect)
    IF (.NOT. ok) THEN
      IF (defect /= REAL_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'LINE TYPES EA '//real_defect_text(parts(1), defect)); RETURN
      END IF
      CALL fail(ErrStat, ErrMsg, 'malformed LINE TYPES EA value "'//TRIM(parts(1))//'"'); RETURN
    END IF
    t%elastic_mod = n_ea
    IF (n_ea == 2) THEN
      CALL parse_real_token(parts(2), t%ea_d, ok)
      IF (.NOT. ok) THEN
        CALL fail(ErrStat, ErrMsg, 'malformed dynamic stiffness (Es|Ed) in the EA column'); RETURN
      END IF
    ELSE IF (n_ea == 3) THEN
      CALL parse_real_token(parts(2), t%alpha_mbl, ok)
      IF (ok) CALL parse_real_token(parts(3), t%vbeta, ok)
      IF (.NOT. ok) THEN
        CALL fail(ErrStat, ErrMsg, 'malformed load-dependent stiffness (Es|alphaMBL|vbeta) in the '// &
                  'EA column'); RETURN
      END IF
    END IF
    CALL split_bars(ba_str, parts, n_ba)
    IF (n_ba < 1 .OR. n_ba > t%elastic_mod .OR. n_ba > 2) THEN
      CALL fail(ErrStat, ErrMsg, 'a LINE TYPES BA entry cannot have more bar-separated values than '// &
                'its EA entry (at most Bs|Bd)'); RETURN
    END IF
    CALL parse_real_token(parts(1), t%ba, ok, defect)
    IF (.NOT. ok) THEN
      IF (defect /= REAL_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'LINE TYPES BA '//real_defect_text(parts(1), defect)); RETURN
      END IF
      CALL fail(ErrStat, ErrMsg, 'malformed LINE TYPES BA value "'//TRIM(parts(1))//'"'); RETURN
    END IF
    IF (n_ba == 2) THEN
      CALL parse_real_token(parts(2), t%ba_d, ok)
      IF (.NOT. ok) THEN
        CALL fail(ErrStat, ErrMsg, 'malformed dynamic damping (Bs|Bd) in the BA column'); RETURN
      END IF
    END IF
  END SUBROUTINE parse_stiffness_columns

  PURE LOGICAL FUNCTION is_syrope_token(tok) RESULT(is_syr)
    !! The EA first-part carries the Syrope working-curve dialect prefix.
    CHARACTER(*), INTENT(IN) :: tok
    CHARACTER(7) :: pre
    pre = tok(1:MIN(7, LEN(tok)))
    is_syr = (to_lower(pre) == 'syrope:')
  END FUNCTION is_syrope_token

  SUBROUTINE parse_syrope_columns(ea_parts, n_ea, ba_str, t, ErrStat, ErrMsg)
    !! Parse the Syrope EA/BA columns: EA = SYROPE:<file>|alpha|beta (the fast-
    !! spring dynamic stiffness constants), BA = BA_s|BA_d.
    !! Records the settings-file reference and the constants on the line type;
    !! the OWC table is read and the constitutive built at model init.
    CHARACTER(*), INTENT(IN) :: ea_parts(3), ba_str
    INTEGER, INTENT(IN) :: n_ea
    TYPE(DeckLineType), INTENT(INOUT) :: t
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    CHARACTER(NAMELEN) :: ba_parts(3)
    INTEGER :: n_ba
    LOGICAL :: ok

    ErrStat = 0; ErrMsg = ''
    IF (n_ea /= 3) THEN
      CALL fail(ErrStat, ErrMsg, 'the Syrope EA column needs three parts: SYROPE:<file>|alpha|beta'); RETURN
    END IF
    t%is_syrope = .TRUE.
    ! strip the "SYROPE:" prefix (7 chars) for the settings-file reference
    t%syrope_file = ea_parts(1) (8:)
    IF (LEN_TRIM(t%syrope_file) < 1) THEN
      CALL fail(ErrStat, ErrMsg, 'the Syrope EA column has no settings file after SYROPE:'); RETURN
    END IF
    CALL parse_real_token(ea_parts(2), t%syrope_alpha, ok)
    IF (ok) CALL parse_real_token(ea_parts(3), t%syrope_beta, ok)
    IF (.NOT. ok) THEN
      CALL fail(ErrStat, ErrMsg, 'malformed Syrope alpha|beta in the EA column'); RETURN
    END IF
    IF (.NOT. (t%syrope_alpha > CD_ZERO .AND. t%syrope_beta > CD_ZERO)) THEN
      CALL fail(ErrStat, ErrMsg, 'Syrope alpha and beta (EA = SYROPE:file|alpha|beta) must be positive'); RETURN
    END IF
    ! the composite static EA is a placeholder until the OWC secant is known at
    ! init; keep it positive so the shared LINE TYPES finiteness check passes
    t%ea = t%syrope_alpha
    CALL split_bars(ba_str, ba_parts, n_ba)
    IF (n_ba /= 2) THEN
      CALL fail(ErrStat, ErrMsg, 'the Syrope BA column needs two parts: BA_s|BA_d'); RETURN
    END IF
    CALL parse_real_token(ba_parts(1), t%syrope_c1, ok)
    IF (ok) CALL parse_real_token(ba_parts(2), t%syrope_c2, ok)
    IF (.NOT. ok) THEN
      CALL fail(ErrStat, ErrMsg, 'malformed Syrope BA_s|BA_d in the BA column'); RETURN
    END IF
    IF (.NOT. (t%syrope_c1 >= CD_ZERO .AND. t%syrope_c2 >= CD_ZERO .AND. &
               t%syrope_c1 + t%syrope_c2 > CD_ZERO)) THEN
      CALL fail(ErrStat, ErrMsg, 'Syrope BA_s and BA_d must be non-negative with a positive sum'); RETURN
    END IF
    ! BA_s belongs exclusively to the Syrope constitutive contributor. Keeping
    ! the MoorDyn BA slot zero prevents deck assembly from also enabling the
    ! generic axial-damping contributor for the same dashpot.
    t%ba = CD_ZERO
  END SUBROUTINE parse_syrope_columns

  SUBROUTINE split_bars(s_in, parts, n)
    !! Split a token on '|' (MoorDyn's SplitByBars). Stores up to 3 parts; a
    !! token with MORE than 3 bar-separated fields reports n = 4 (a SURPLUS
    !! signal) so the caller fails closed rather than silently truncating the
    !! extra fields -- a 4th field means malformed viscoelastic parameters.
    CHARACTER(*), INTENT(IN) :: s_in
    CHARACTER(*), INTENT(OUT) :: parts(3)
    INTEGER, INTENT(OUT) :: n
    INTEGER :: lo, hi
    parts = ''
    n = 0
    lo = 1
    DO
      ! reaching this guard means 3 parts were stored WITHOUT the final-field
      ! (hi == 0) exit, so at least one more separator remains: report the
      ! surplus instead of dropping it
      IF (n == 3) THEN
        n = 4
        RETURN
      END IF
      hi = INDEX(s_in(lo:), '|')
      n = n + 1
      IF (hi == 0) THEN
        parts(n) = s_in(lo:)
        RETURN
      END IF
      parts(n) = s_in(lo:lo + hi - 2)
      lo = lo + hi
    END DO
  END SUBROUTINE split_bars

  SUBROUTINE append_body(line, bodies, nb, ErrStat, ErrMsg)
    CHARACTER(*), INTENT(IN) :: line
    TYPE(DeckBody), ALLOCATABLE, INTENT(INOUT) :: bodies(:)
    INTEGER, INTENT(INOUT) :: nb
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(DeckBody) :: b
    INTEGER :: ios, ntok
    ErrStat = 0; ErrMsg = ''
    ntok = count_tokens(line)
    IF (ntok == 14) THEN
      CALL parse_moordyn_body_row(line, b, ErrStat, ErrMsg)
      IF (ErrStat /= 0) RETURN
      CALL grow_bodies(bodies, nb)
      nb = nb + 1
      bodies(nb) = b
      RETURN
    END IF
    IF (ntok /= 15 .AND. ntok /= 18) THEN
      CALL fail(ErrStat, ErrMsg, 'BODIES row needs 14 cols (MoorDyn: ID Attachment X0 Y0 Z0 r0 p0 y0 Mass '// &
                'CG* I* Volume CdA* Ca*) or 15 cols plus optional Ixx Iyy Izz: '// &
                'ID Type X Y Z Rot1 Rot2 Rot3 Mass Vol C33 C44 C55 CdA Ca [Ixx Iyy Izz]'); RETURN
    END IF
    IF (ntok == 15) THEN
      READ (line, *, IOSTAT=ios) b%id, b%btype, b%pos(1), b%pos(2), b%pos(3), &
        b%rot(1), b%rot(2), b%rot(3), b%mass, b%vol, &
        b%c33, b%c44, b%c55, b%cda, b%ca
    ELSE
      READ (line, *, IOSTAT=ios) b%id, b%btype, b%pos(1), b%pos(2), b%pos(3), &
        b%rot(1), b%rot(2), b%rot(3), b%mass, b%vol, &
        b%c33, b%c44, b%c55, b%cda, b%ca, b%inertia(1), &
        b%inertia(2), b%inertia(3)
    END IF
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'malformed BODIES row'); RETURN
    END IF
    b%btype = to_lower(TRIM(b%btype))
    SELECT CASE (TRIM(b%btype))
    CASE ('coupled', 'vessel', 'cpld', 'ves')
      b%btype = 'rigid6'
      b%host_coupled = .TRUE.
    CASE ('coupledpinned', 'cpldpin')
      CALL fail(ErrStat, ErrMsg, 'CoupledPinned BODY is not supported (use Coupled or Free)'); RETURN
    END SELECT
    CALL grow_bodies(bodies, nb)
    nb = nb + 1
    bodies(nb) = b
  END SUBROUTINE append_body

  SUBROUTINE parse_moordyn_body_row(line, b, ErrStat, ErrMsg)
    !! MoorDyn v2 BODIES row: ID Attachment X0 Y0 Z0 r0 p0 y0 Mass CG* I* Volume CdA* Ca*, with
    !! bar lists CG = z | x|y|z, I = I (all axes) | Ixx|Iyy|Izz about the CG, CdA = CdA | CdA|CdA_rot
    !! (or 3/6 entries) and Ca = Ca | Cax|Cay|Caz. A Free body becomes a Rigid6 body with its CG
    !! (also the centre of buoyancy, as in MoorDyn). The body model is isotropic: 3-entry CdA/Ca
    !! lists must be equal, and rotational drag and other attachments fail closed by name.
    CHARACTER(*), INTENT(IN) :: line
    TYPE(DeckBody), INTENT(OUT) :: b
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    CHARACTER(NAMELEN) :: tok(14)
    REAL(wp) :: v(6)
    INTEGER :: k, n, ios
    LOGICAL :: found

    ErrStat = 0; ErrMsg = ''
    DO k = 1, 14
      CALL get_token(line, k, tok(k), found)
      IF (is_quoted_token(tok(k))) tok(k) = tok(k) (2:LEN_TRIM(tok(k)) - 1)
    END DO
    CALL parse_int_token(tok(1), b%id, found)
    IF (.NOT. found) THEN
      CALL fail(ErrStat, ErrMsg, 'malformed BODIES row (ID)'); RETURN
    END IF
    SELECT CASE (to_lower(TRIM(tok(2))))
    CASE ('free')
      b%btype = 'rigid6'
    CASE ('coupled', 'vessel', 'cpld', 'ves')
      b%btype = 'rigid6'
      b%host_coupled = .TRUE.
    CASE DEFAULT
      CALL fail(ErrStat, ErrMsg, 'BODIES attachment "'//TRIM(tok(2))//'" is not supported in the '// &
                '14-column MoorDyn row (Free, Coupled, or Vessel bodies)'); RETURN
    END SELECT
    READ (line, *, IOSTAT=ios) tok(1), tok(2), b%pos(1), b%pos(2), b%pos(3), b%rot(1), b%rot(2), b%rot(3), b%mass
    IF (ios == 0) THEN
      CALL parse_real_token(tok(12), b%vol, found)
      IF (.NOT. found) ios = 1
    END IF
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'malformed BODIES row'); RETURN
    END IF
    CALL bar_values(tok(10), v, n)
    SELECT CASE (n)
    CASE (1)
      b%cg = [CD_ZERO, CD_ZERO, v(1)]
    CASE (3)
      b%cg = v(1:3)
    CASE DEFAULT
      CALL fail(ErrStat, ErrMsg, 'BODIES CG needs 1 (z) or 3 (x|y|z) numbers'); RETURN
    END SELECT
    CALL bar_values(tok(11), v, n)
    SELECT CASE (n)
    CASE (1)
      b%inertia = v(1)
    CASE (3)
      b%inertia = v(1:3)
    CASE DEFAULT
      CALL fail(ErrStat, ErrMsg, 'BODIES I needs 1 or 3 (Ixx|Iyy|Izz) numbers; products of inertia '// &
                'are not supported'); RETURN
    END SELECT
    CALL bar_values(tok(13), v, n)
    SELECT CASE (n)
    CASE (1)
      b%cda = v(1)
    CASE (2)
      b%cda = v(1)
      IF (ABS(v(2)) > CD_ZERO) THEN
        CALL fail(ErrStat, ErrMsg, 'BODIES rotational drag area (second CdA entry) is not supported; set it to 0')
        RETURN
      END IF
    CASE (3, 6)
      b%cda = v(1)
      IF (ANY(ABS(v(1:3) - v(1)) > CD_ZERO) .OR. (n == 6 .AND. ANY(ABS(v(4:6)) > CD_ZERO))) THEN
        CALL fail(ErrStat, ErrMsg, 'BODIES CdA: direction-dependent and rotational drag areas are not '// &
                  'supported (use one value, or equal translational entries and zero rotational ones)'); RETURN
      END IF
    CASE DEFAULT
      CALL fail(ErrStat, ErrMsg, 'BODIES CdA needs 1, 2, 3 or 6 numbers'); RETURN
    END SELECT
    CALL bar_values(tok(14), v, n)
    SELECT CASE (n)
    CASE (1)
      b%ca = v(1)
    CASE (3)
      b%ca = v(1)
      IF (ANY(ABS(v(1:3) - v(1)) > CD_ZERO)) THEN
        CALL fail(ErrStat, ErrMsg, 'BODIES Ca: direction-dependent added mass is not supported (use equal '// &
                  'entries)'); RETURN
      END IF
    CASE DEFAULT
      CALL fail(ErrStat, ErrMsg, 'BODIES Ca needs 1 or 3 numbers'); RETURN
    END SELECT
  CONTAINS
    SUBROUTINE bar_values(t, vals, nv)
      !! The numbers of a '|'-separated list; nv = 0 on a malformed entry, 7 on more than 6.
      CHARACTER(*), INTENT(IN) :: t
      REAL(wp), INTENT(OUT) :: vals(6)
      INTEGER, INTENT(OUT) :: nv
      INTEGER :: p0, p1
      LOGICAL :: okv
      vals = CD_ZERO
      nv = 0
      p0 = 1
      DO
        p1 = INDEX(t(p0:), '|')
        IF (nv == 6) THEN
          nv = 7
          RETURN
        END IF
        nv = nv + 1
        ! strict whole-token read: NaN, Inf and subnormal entries are malformed
        IF (p1 == 0) THEN
          CALL parse_real_token(t(p0:), vals(nv), okv)
        ELSE
          CALL parse_real_token(t(p0:p0 + p1 - 2), vals(nv), okv)
        END IF
        IF (.NOT. okv) THEN
          nv = 0
          RETURN
        END IF
        IF (p1 == 0) EXIT
        p0 = p0 + p1
      END DO
    END SUBROUTINE bar_values
  END SUBROUTINE parse_moordyn_body_row

  SUBROUTINE sniff_rod_types_header(line, legacy_cols)
    !! ROD TYPES column semantics from the section's header row. Columns 6-7 are MoorDyn's
    !! CdEnd CaEnd; an older CableDyn header named its axial side coefficients (CdAx CaAx)
    !! there. The data rows cannot tell the two apart, so a header naming an axial
    !! coefficient in column 6 or 7 marks the section as legacy (its rows are then rejected
    !! with the migration message) and a header naming CdEnd/CaEnd there clears it. Units
    !! rows and headers with fewer than 6 names leave the state unchanged (default: MoorDyn).
    CHARACTER(*), INTENT(IN) :: line
    LOGICAL, INTENT(INOUT) :: legacy_cols
    CHARACTER(NAMELEN) :: tok
    LOGICAL :: found
    INTEGER :: k
    DO k = 6, 7
      CALL get_token(line, k, tok, found)
      IF (.NOT. found) RETURN
      SELECT CASE (to_lower(TRIM(tok)))
      CASE ('cdax', 'caax', 'cd_ax', 'ca_ax', 'cdt', 'cat', 'cd_t', 'ca_t')
        legacy_cols = .TRUE.
        RETURN
      CASE ('cdend', 'caend', 'cd_end', 'ca_end')
        legacy_cols = .FALSE.
        RETURN
      END SELECT
    END DO
  END SUBROUTINE sniff_rod_types_header

  SUBROUTINE append_rod_type(line, rod_types, nrt, legacy_cols, ErrStat, ErrMsg)
    !! ROD TYPES row: 7 columns Name Diam Mass/m Cd Ca CdEnd CaEnd (MoorDyn), or 9 columns
    !! with the CableDyn axial side coefficients CdAx CaAx appended (default 0 = MoorDyn).
    CHARACTER(*), INTENT(IN) :: line
    TYPE(DeckRodType), ALLOCATABLE, INTENT(INOUT) :: rod_types(:)
    INTEGER, INTENT(INOUT) :: nrt
    LOGICAL, INTENT(IN) :: legacy_cols
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(DeckRodType) :: rt
    INTEGER :: ios, ntok

    ErrStat = 0
    ErrMsg = ''
    IF (legacy_cols) THEN
      CALL fail(ErrStat, ErrMsg, 'ROD TYPES header names axial coefficients (CdAx CaAx) in columns 6-7, '// &
                'which are MoorDyn''s end coefficients CdEnd CaEnd; migrate the section to '// &
                '"Name Diam Mass/m Cd Ca CdEnd CaEnd CdAx CaAx" (old columns 6-7 move to 8-9, '// &
                'CdEnd CaEnd = 0 keeps the old model)')
      RETURN
    END IF
    ntok = count_tokens(line)
    IF (ntok /= 7 .AND. ntok /= 9) THEN
      CALL fail(ErrStat, ErrMsg, 'ROD TYPES row needs 7 cols (Name Diam Mass/m Cd Ca CdEnd CaEnd) '// &
                'or 9 cols (Name Diam Mass/m Cd Ca CdEnd CaEnd CdAx CaAx)')
      RETURN
    END IF
    IF (ntok == 7) THEN
      READ (line, *, IOSTAT=ios) rt%name, rt%diam, rt%mass, rt%cdn, rt%can, rt%cdend, rt%caend
    ELSE
      READ (line, *, IOSTAT=ios) rt%name, rt%diam, rt%mass, rt%cdn, rt%can, rt%cdend, rt%caend, rt%cdt, rt%cat
    END IF
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'malformed ROD TYPES row')
      RETURN
    END IF
    CALL grow_rod_types(rod_types, nrt)
    nrt = nrt + 1
    rod_types(nrt) = rt
  END SUBROUTINE append_rod_type

  SUBROUTINE append_rod(line, rods, nr, ErrStat, ErrMsg)
    CHARACTER(*), INTENT(IN) :: line
    TYPE(DeckRod), ALLOCATABLE, INTENT(INOUT) :: rods(:)
    INTEGER, INTENT(INOUT) :: nr
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(DeckRod) :: r
    INTEGER :: ios, ntok

    ErrStat = 0
    ErrMsg = ''
    ntok = count_tokens(line)
    IF (ntok /= 10 .AND. ntok /= 11) THEN
      CALL fail(ErrStat, ErrMsg, 'RODS row needs 10 cols plus optional Outputs: '// &
                'ID RodType Type XA YA ZA XB YB ZB NumSegs [Outputs]')
      RETURN
    END IF
    IF (ntok == 10) THEN
      READ (line, *, IOSTAT=ios) r%id, r%rtype_name, r%rod_type, r%end_a(1), r%end_a(2), r%end_a(3), &
        r%end_b(1), r%end_b(2), r%end_b(3), r%nsegs
      r%outputs = '-'
    ELSE
      READ (line, *, IOSTAT=ios) r%id, r%rtype_name, r%rod_type, r%end_a(1), r%end_a(2), r%end_a(3), &
        r%end_b(1), r%end_b(2), r%end_b(3), r%nsegs, r%outputs
    END IF
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'malformed RODS row')
      RETURN
    END IF
    r%rod_type = to_lower(TRIM(r%rod_type))
    ! MoorDyn attachment aliases
    SELECT CASE (TRIM(r%rod_type))
    CASE ('anchor', 'fix')
      r%rod_type = 'fixed'
    CASE ('pin')
      r%rod_type = 'pinned'
    CASE ('point', 'con')
      r%rod_type = 'free'
    CASE ('ves')
      r%rod_type = 'vessel'
    CASE ('cpld')
      r%rod_type = 'coupled'
    CASE ('coupledpinned', 'cpldpin', 'vesselpinned', 'vespin')
      ! rejected here, before a NumSegs 0 rod collapses to an unknown point type
      CALL fail(ErrStat, ErrMsg, 'CoupledPinned/VesselPinned RODS are not supported (use Coupled, Vessel, '// &
                'Pinned or Body<N>Pinned)'); RETURN
    CASE DEFAULT
      IF (starts_with(TRIM(r%rod_type), 'body') .AND. LEN_TRIM(r%rod_type) > 7) THEN
        IF (r%rod_type(LEN_TRIM(r%rod_type) - 2:LEN_TRIM(r%rod_type)) == 'pin' .AND. &
            r%rod_type(LEN_TRIM(r%rod_type) - 5:LEN_TRIM(r%rod_type)) /= 'pinned') &
          r%rod_type = TRIM(r%rod_type)//'ned'
      END IF
    END SELECT
    CALL grow_rods(rods, nr)
    nr = nr + 1
    rods(nr) = r
  END SUBROUTINE append_rod

  SUBROUTINE append_point(line, points, np, ErrStat, ErrMsg)
    CHARACTER(*), INTENT(IN) :: line
    TYPE(DeckPoint), ALLOCATABLE, INTENT(INOUT) :: points(:)
    INTEGER, INTENT(INOUT) :: np
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(DeckPoint) :: p
    INTEGER :: ios, ntok
    ErrStat = 0; ErrMsg = ''
    ntok = count_tokens(line)
    IF (ntok /= 5 .AND. ntok /= 9) THEN
      CALL fail(ErrStat, ErrMsg, 'POINTS row needs 5 (ID Type X Y Z) or 9 '// &
                '(ID Type X Y Z Mass Vol CdA Ca) cols'); RETURN
    END IF
    IF (ntok == 9) THEN
      READ (line, *, IOSTAT=ios) p%id, p%ptype, p%pos(1), p%pos(2), p%pos(3), p%mass, p%vol, p%cda, p%ca
    ELSE
      READ (line, *, IOSTAT=ios) p%id, p%ptype, p%pos(1), p%pos(2), p%pos(3)
    END IF
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'malformed POINTS row'); RETURN
    END IF
    ! Reported here, with the row, rather than later as a misleading range failure
    ! (a NaN depth would otherwise surface as an anchor "below the seabed").
    IF (.NOT. (ALL(IEEE_IS_FINITE(p%pos)) .AND. IEEE_IS_FINITE(p%mass) .AND. IEEE_IS_FINITE(p%vol) .AND. &
               IEEE_IS_FINITE(p%cda) .AND. IEEE_IS_FINITE(p%ca))) THEN
      CALL fail(ErrStat, ErrMsg, 'POINTS row has a non-finite value (X/Y/Z/Mass/Vol/CdA/Ca must be finite)')
      RETURN
    END IF
    IF (ANY(ABS(p%pos) > MAX_COORDINATE) .OR. MAX(ABS(p%mass), ABS(p%vol), ABS(p%cda)) > MAX_COEFFICIENT .OR. &
        ABS(p%ca) > MAX_COEFFICIENT_SMALL) THEN
      CALL fail(ErrStat, ErrMsg, 'POINTS row outside the admissible range (|X|, |Y|, |Z| <= 1e6 m; '// &
                '|Mass|, |Vol|, |CdA| <= 1e15; |Ca| <= 1e3)')
      RETURN
    END IF
    p%ptype = to_lower(p%ptype)
    CALL grow_points(points, np)
    np = np + 1; points(np) = p
  END SUBROUTINE append_point

  SUBROUTINE append_line(line, lines, nlin, sections, nsec, ErrStat, ErrMsg)
    CHARACTER(*), INTENT(IN) :: line
    TYPE(DeckLine), ALLOCATABLE, INTENT(INOUT) :: lines(:)
    INTEGER, INTENT(INOUT) :: nlin
    TYPE(DeckSection), ALLOCATABLE, INTENT(INOUT) :: sections(:)
    INTEGER, INTENT(INOUT) :: nsec
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(DeckLine) :: ln
    TYPE(DeckSection) :: s
    ! raw attachment tokens (quotes kept, so a quoted id is seen and rejected); a token
    ! longer than the buffer (found = .FALSE.) is rejected as malformed
    CHARACTER(NAMELEN + 2) :: attA, attB
    INTEGER :: ios, ntok
    LOGICAL :: found
    ErrStat = 0; ErrMsg = ''
    ntok = count_tokens(line)
    IF (ntok == 7) THEN
      ! Stock MoorDyn v2 form: ID LineType AttachA AttachB UnstrLen NumSegs Outputs.
      ! Equivalent to a LINES row plus one implicit single-type SECTIONS row.
      READ (line, *, IOSTAT=ios) ln%id, s%ltype_name, attA, attB, s%length, s%nsegs, ln%outputs
      IF (ios /= 0) THEN
        CALL fail(ErrStat, ErrMsg, 'malformed LINES row (stock 7-column form)'); RETURN
      END IF
      CALL get_token(line, 3, attA, found)
      IF (found) CALL get_token(line, 4, attB, found)
      IF (.NOT. found) THEN
        CALL fail(ErrStat, ErrMsg, 'malformed LINES row: an attachment token is too long'); RETURN
      END IF
      CALL parse_line_attachment(attA, ln%nodeA, ErrStat, ErrMsg)
      IF (ErrStat /= 0) RETURN
      CALL parse_line_attachment(attB, ln%nodeB, ErrStat, ErrMsg)
      IF (ErrStat /= 0) RETURN
      s%line_id = ln%id
      ln%stock_row = .TRUE.
      CALL grow_sections(sections, nsec)
      nsec = nsec + 1; sections(nsec) = s
    ELSE IF (ntok == 3 .OR. ntok == 4) THEN
      IF (ntok == 4) THEN
        READ (line, *, IOSTAT=ios) ln%id, attA, attB, ln%outputs
      ELSE
        READ (line, *, IOSTAT=ios) ln%id, attA, attB
        ln%outputs = '-'
      END IF
      IF (ios /= 0) THEN
        CALL fail(ErrStat, ErrMsg, 'malformed LINES row'); RETURN
      END IF
      CALL get_token(line, 2, attA, found)
      IF (found) CALL get_token(line, 3, attB, found)
      IF (.NOT. found) THEN
        CALL fail(ErrStat, ErrMsg, 'malformed LINES row: an attachment token is too long'); RETURN
      END IF
      CALL parse_line_attachment(attA, ln%nodeA, ErrStat, ErrMsg)
      IF (ErrStat /= 0) RETURN
      CALL parse_line_attachment(attB, ln%nodeB, ErrStat, ErrMsg)
      IF (ErrStat /= 0) RETURN
    ELSE
      CALL fail(ErrStat, ErrMsg, 'LINES row needs 3 (ID NodeA NodeB), 4 (+Outputs), or the stock '// &
                '7 cols (ID LineType AttachA AttachB UnstrLen NumSegs Outputs)'); RETURN
    END IF
    CALL grow_lines(lines, nlin)
    nlin = nlin + 1; lines(nlin) = ln
  END SUBROUTINE append_line

  SUBROUTINE apply_external_load(line, expected_id, bodies, ErrStat, ErrMsg)
    !! EXTERNAL LOADS row. Two column orders are read:
    !!   MoorDyn-F   ID Object Force Blin Bquad CSys
    !!   CableDyn    ID Object CSys Force Blin Bquad
    !! The order is unambiguous: CSys is a letter (G, L or -) and Force is numeric, so a
    !! letter in column 3 selects the CableDyn order and a letter in column 6 the MoorDyn-F
    !! order. ID numbers must run 1, 2, 3, ... in row order (MoorDyn-F's rule). Object is a
    !! Rigid6 Body<N>; CSys G (global) or L (body frame) for the force and the damping; Force
    !! 0 or f1|f2|f3 [N]; Blin [N s/m] and Bquad [N s^2/m^2] 1 (isotropic) or 3 entries,
    !! non-negative. The translational load F - Blin v - Bquad |v| v acts at the reference
    !! point. Several rows on one body are summed, keeping the global and body-frame sums
    !! apart (as MoorDyn-F does). Point3 bodies, rods and points fail closed by name.
    CHARACTER(*), INTENT(IN) :: line
    INTEGER, INTENT(IN) :: expected_id
    TYPE(DeckBody), INTENT(INOUT) :: bodies(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    CHARACTER(256) :: tok(6), csys
    LOGICAL :: found, ok_id
    INTEGER :: k, ib, bid, row_id, kf, iframe
    REAL(wp) :: f(3), bl(3), bq(3)
    ErrStat = 0; ErrMsg = ''
    IF (count_tokens(line) /= 6) THEN
      CALL fail(ErrStat, ErrMsg, 'EXTERNAL LOADS row needs 6 cols: ID Object Force Blin Bquad CSys '// &
                '(MoorDyn-F order) or ID Object CSys Force Blin Bquad'); RETURN
    END IF
    DO k = 1, 6
      CALL get_token(line, k, tok(k), found)
      IF (.NOT. found) THEN
        CALL fail(ErrStat, ErrMsg, 'EXTERNAL LOADS column '//TRIM(int_to_str(k))//' is too long'); RETURN
      END IF
      IF (is_quoted_token(tok(k))) tok(k) = tok(k) (2:LEN_TRIM(tok(k)) - 1)
    END DO
    CALL parse_int_token(tok(1), row_id, ok_id)
    IF (.NOT. ok_id .OR. row_id /= expected_id) THEN
      CALL fail(ErrStat, ErrMsg, 'EXTERNAL LOADS ID numbers must be sequential starting from 1 (expected '// &
                TRIM(int_to_str(expected_id))//', found "'//TRIM(tok(1))//'")'); RETURN
    END IF
    IF (is_csys_token(tok(3)) .AND. .NOT. is_csys_token(tok(6))) THEN
      csys = tok(3)
      kf = 4
    ELSE IF (is_csys_token(tok(6)) .AND. .NOT. is_csys_token(tok(3))) THEN
      csys = tok(6)
      kf = 3
    ELSE
      CALL fail(ErrStat, ErrMsg, 'EXTERNAL LOADS row needs the CSys letter (G or L) in column 6 '// &
                '(MoorDyn-F order ID Object Force Blin Bquad CSys) or in column 3 (ID Object CSys '// &
                'Force Blin Bquad)'); RETURN
    END IF
    bid = 0
    IF (starts_with(to_lower(TRIM(tok(2))), 'body')) bid = body_id_of_rod_type(tok(2))
    ib = 0
    IF (bid > 0) ib = find_body(bodies, bid)
    IF (ib == 0) THEN
      CALL fail(ErrStat, ErrMsg, 'EXTERNAL LOADS object "'//TRIM(tok(2))//'" is not supported (a Rigid6 '// &
                'Body<N> is; rod and point external loads are not)'); RETURN
    END IF
    IF (TRIM(bodies(ib)%btype) == 'point3') THEN
      CALL fail(ErrStat, ErrMsg, 'EXTERNAL LOADS apply to Rigid6 bodies only; Body'//TRIM(int_to_str(bid))// &
                ' is a Point3 body'); RETURN
    END IF
    CALL three_values(tok(kf), f, .TRUE.)
    IF (ErrStat /= 0) RETURN
    CALL three_values(tok(kf + 1), bl, .FALSE.)
    IF (ErrStat /= 0) RETURN
    CALL three_values(tok(kf + 2), bq, .FALSE.)
    IF (ErrStat /= 0) RETURN
    IF (ANY(bl < CD_ZERO) .OR. ANY(bq < CD_ZERO)) THEN
      CALL fail(ErrStat, ErrMsg, 'EXTERNAL LOADS Blin and Bquad must be non-negative'); RETURN
    END IF
    SELECT CASE (to_lower(TRIM(csys)))
    CASE ('g')
      iframe = 1
    CASE ('l')
      iframe = 2
    CASE DEFAULT
      CALL fail(ErrStat, ErrMsg, 'EXTERNAL LOADS CSys must be G or L for a body'); RETURN
    END SELECT
    bodies(ib)%ext_f(:, iframe) = bodies(ib)%ext_f(:, iframe) + f
    bodies(ib)%ext_blin(:, iframe) = bodies(ib)%ext_blin(:, iframe) + bl
    bodies(ib)%ext_bquad(:, iframe) = bodies(ib)%ext_bquad(:, iframe) + bq
  CONTAINS
    PURE LOGICAL FUNCTION is_csys_token(t) RESULT(yes)
      !! A CSys entry: a single letter G or L, or MoorDyn-F's '-' (which fails later for a body).
      CHARACTER(*), INTENT(IN) :: t
      yes = LEN_TRIM(t) == 1 .AND. INDEX('GgLl-', t(1:1)) > 0
    END FUNCTION is_csys_token

    SUBROUTINE three_values(t, v, zero_ok)
      !! One value (isotropic; for the force only 0) or three bar-separated values.
      CHARACTER(*), INTENT(IN) :: t
      REAL(wp), INTENT(OUT) :: v(3)
      LOGICAL, INTENT(IN) :: zero_ok
      CHARACTER(CD_DECK_PATHLEN) :: parts(3)
      INTEGER :: n, j
      LOGICAL :: okv
      v = CD_ZERO
      CALL split_bars(t, parts, n)
      IF (n == 1) THEN
        CALL parse_real_token(parts(1), v(1), okv)
        IF (.NOT. okv .OR. (zero_ok .AND. ABS(v(1)) > CD_ZERO)) THEN
          CALL fail(ErrStat, ErrMsg, 'EXTERNAL LOADS value "'//TRIM(t)//'" must be '// &
                    TRIM(MERGE('0 or f1|f2|f3       ', 'one or three numbers', zero_ok)))
          RETURN
        END IF
        v = v(1)
      ELSE IF (n == 3) THEN
        DO j = 1, 3
          CALL parse_real_token(parts(j), v(j), okv)
          IF (.NOT. okv) THEN
            CALL fail(ErrStat, ErrMsg, 'EXTERNAL LOADS value "'//TRIM(t)//'" is malformed'); RETURN
          END IF
        END DO
      ELSE
        CALL fail(ErrStat, ErrMsg, 'EXTERNAL LOADS value "'//TRIM(t)//'" needs one or three numbers'); RETURN
      END IF
      IF (.NOT. ALL(IEEE_IS_FINITE(v))) CALL fail(ErrStat, ErrMsg, 'EXTERNAL LOADS values must be finite')
    END SUBROUTINE three_values
  END SUBROUTINE apply_external_load

  SUBROUTINE rigid6_external_load(body, force, drag3)
    !! EXTERNAL LOADS of a Rigid6 body at its reference point: F - Blin v - Bquad |v| v per axis,
    !! the sum of the global-frame rows and the body-frame rows, and its velocity derivative drag3.
    TYPE(RigidBodyState), INTENT(IN) :: body
    REAL(wp), INTENT(OUT) :: force(3), drag3(3, 3)
    REAL(wp) :: v(3), f(3), d(3, 3)
    INTEGER :: k
    ! global-frame rows
    v = body%v
    f = body%ext_f(:, 1) - body%ext_blin(:, 1)*v - body%ext_bquad(:, 1)*ABS(v)*v
    d = CD_ZERO
    DO k = 1, 3
      d(k, k) = -body%ext_blin(k, 1) - 2.0_wp*body%ext_bquad(k, 1)*ABS(v(k))
    END DO
    force = f
    drag3 = d
    ! body-frame rows, rotated back to the global frame (exactly zero when there are none)
    v = MATMUL(TRANSPOSE(body%rot_mat), body%v)
    f = body%ext_f(:, 2) - body%ext_blin(:, 2)*v - body%ext_bquad(:, 2)*ABS(v)*v
    d = CD_ZERO
    DO k = 1, 3
      d(k, k) = -body%ext_blin(k, 2) - 2.0_wp*body%ext_bquad(k, 2)*ABS(v(k))
    END DO
    force = force + MATMUL(body%rot_mat, f)
    drag3 = drag3 + MATMUL(body%rot_mat, MATMUL(d, TRANSPOSE(body%rot_mat)))
  END SUBROUTINE rigid6_external_load

  SUBROUTINE append_turbine(line, opts, ErrStat, ErrMsg)
    !! TURBINES row: J X0 Y0 Z0 [PtfmSurge PtfmSway PtfmHeave PtfmRoll PtfmPitch PtfmYaw] -- the
    !! turbine's reference position (farm-global) and its initial platform displacement
    !! (MoorDyn-F PtfmInit convention), so Turbine<J> points run in the standalone driver.
    CHARACTER(*), INTENT(IN) :: line
    TYPE(DeckOptions), INTENT(INOUT) :: opts
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: ntok, j, ios
    REAL(wp) :: v(9)
    REAL(wp), ALLOCATABLE :: tmp(:, :)
    ErrStat = 0; ErrMsg = ''
    ntok = count_tokens(line)
    v = CD_ZERO
    IF (ntok == 4) THEN
      READ (line, *, IOSTAT=ios) j, v(1:3)
    ELSE IF (ntok == 10) THEN
      READ (line, *, IOSTAT=ios) j, v
    ELSE
      CALL fail(ErrStat, ErrMsg, 'TURBINES row needs 4 (J X0 Y0 Z0) or 10 cols (+ PtfmSurge PtfmSway '// &
                'PtfmHeave PtfmRoll PtfmPitch PtfmYaw)'); RETURN
    END IF
    IF (ios /= 0 .OR. .NOT. ALL(IEEE_IS_FINITE(v))) THEN
      CALL fail(ErrStat, ErrMsg, 'malformed TURBINES row'); RETURN
    END IF
    IF (ANY(ABS(v) > MAX_COORDINATE)) THEN
      CALL fail(ErrStat, ErrMsg, 'TURBINES positions and angles must be at most 1e6 in magnitude'); RETURN
    END IF
    IF (j < 1 .OR. j > 10000) THEN
      CALL fail(ErrStat, ErrMsg, 'TURBINES J must be between 1 and 10000'); RETURN
    END IF
    IF (.NOT. ALLOCATED(opts%turb_ref)) THEN
      ALLOCATE (opts%turb_ref(3, 0), opts%turb_ptfm(6, 0))
    END IF
    IF (j > SIZE(opts%turb_ref, 2)) THEN
      ALLOCATE (tmp(3, j))
      tmp = HUGE(CD_ONE)
      tmp(:, 1:SIZE(opts%turb_ref, 2)) = opts%turb_ref
      CALL MOVE_ALLOC(tmp, opts%turb_ref)
      ALLOCATE (tmp(6, j))
      tmp = CD_ZERO
      tmp(:, 1:SIZE(opts%turb_ptfm, 2)) = opts%turb_ptfm
      CALL MOVE_ALLOC(tmp, opts%turb_ptfm)
    ELSE IF (opts%turb_ref(1, j) < HUGE(CD_ONE)) THEN
      CALL fail(ErrStat, ErrMsg, 'duplicate TURBINES J '//TRIM(int_to_str(j))); RETURN
    END IF
    opts%turb_ref(:, j) = v(1:3)
    ! PtfmInit angles in degrees -> radians for the ZYX transform
    opts%turb_ptfm(:, j) = [v(4:6), v(7:9)*QUARTER_PI/45.0_wp]
    opts%n_turb = SIZE(opts%turb_ref, 2)
  END SUBROUTINE append_turbine

  SUBROUTINE place_standalone_turbine_points(points, opts, ErrStat, ErrMsg)
    !! Standalone TURBINES deck: each Turbine<J> point keeps its turbine-local coordinates and
    !! moves to the farm-global position ref_J + PtfmInit_J(p) (the FAST.Farm transform).
    TYPE(DeckPoint), INTENT(INOUT) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: i, j
    ErrStat = 0; ErrMsg = ''
    DO i = 1, SIZE(points)
      j = points(i)%turbine_id
      IF (j < 1) CYCLE
      IF (j > opts%n_turb) THEN
        CALL fail(ErrStat, ErrMsg, 'POINT '//TRIM(int_to_str(points(i)%id))//' references a turbine '// &
                  'without a TURBINES row'); RETURN
      END IF
      IF (.NOT. opts%turb_ref(1, j) < HUGE(CD_ONE)) THEN
        CALL fail(ErrStat, ErrMsg, 'POINT '//TRIM(int_to_str(points(i)%id))//' references a turbine '// &
                  'without a TURBINES row'); RETURN
      END IF
      points(i)%turb_local = points(i)%pos
      CALL apply_ptfm_point(points(i), opts%turb_ptfm(:, j))
      points(i)%pos = points(i)%pos + opts%turb_ref(:, j)
    END DO
  END SUBROUTINE place_standalone_turbine_points

  SUBROUTINE parse_line_attachment(tok, node, ErrStat, ErrMsg)
    !! A LINES attachment: a POINTS id, or a rod end R<N>A/R<N>B (also Rod<N>A/Rod<N>B, MoorDyn),
    !! returned as -(2 N + e) with e = 0 for End A and 1 for End B and resolved to the rod's end
    !! point by resolve_rod_end_tokens once the whole deck is read.
    CHARACTER(*), INTENT(IN) :: tok
    INTEGER, INTENT(OUT) :: node
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    !! The token is taken raw and whole: a quoted token, an id followed by other characters
    !! ("1x", or "1 x" inside quotes) or a non-integer id is malformed, never read as its
    !! leading integer.
    CHARACTER(*), PARAMETER :: WHY = ' must be an unquoted point id or rod end (R<N>A, R<N>B)'
    CHARACTER(NAMELEN) :: lo
    INTEGER :: rod_id, end_id
    LOGICAL :: ok
    ErrStat = 0; ErrMsg = ''
    node = 0
    IF (.NOT. is_quoted_token(ADJUSTL(tok))) THEN
      CALL parse_int_token(tok, node, ok)
      IF (ok) RETURN
      node = 0
      lo = to_lower(TRIM(ADJUSTL(tok)))
      IF (starts_with(lo, 'r') .AND. .NOT. starts_with(lo, 'rod') .AND. LEN_TRIM(lo) >= 3) lo = 'rod'//lo(2:)
      CALL parse_rod_point_type(lo, rod_id, end_id)
      IF (rod_id > 0 .AND. (end_id == 1 .OR. end_id == 2)) THEN
        node = -(2*rod_id + end_id - 1)
        RETURN
      END IF
    END IF
    CALL fail(ErrStat, ErrMsg, 'malformed LINES row: attachment '//TRIM(ADJUSTL(tok))//WHY)
  END SUBROUTINE parse_line_attachment

  SUBROUTINE resolve_rod_end_tokens(rods, bodies, points, np, lines)
    !! Bind the R<N>A/R<N>B line attachments to rod end points: an existing Rod<N>A/B POINT row, or
    !! an implicit one. The end points of a rod fixed to a body (RODS type Body<M>) become Body<M>
    !! attachment points at the rod end's body-frame coordinates, so their lines load the body.
    TYPE(DeckRod), INTENT(IN) :: rods(:)
    TYPE(DeckBody), INTENT(IN) :: bodies(:)
    TYPE(DeckPoint), ALLOCATABLE, INTENT(INOUT) :: points(:)
    INTEGER, INTENT(INOUT) :: np
    TYPE(DeckLine), INTENT(INOUT) :: lines(:)
    INTEGER :: i, k, j, rod_id, end_id, maxid, ir, bid
    CHARACTER(NAMELEN) :: want
    TYPE(DeckPoint) :: p

    maxid = 0
    DO i = 1, np
      maxid = MAX(maxid, points(i)%id)
    END DO
    DO i = 1, SIZE(lines)
      DO k = 1, 2
        IF (k == 1) j = lines(i)%nodeA
        IF (k == 2) j = lines(i)%nodeB
        IF (j >= 0) CYCLE
        rod_id = (-j)/2
        end_id = MOD(-j, 2) + 1
        want = 'rod'//TRIM(int_to_str(rod_id))//MERGE('a', 'b', end_id == 1)
        j = 0
        DO ir = 1, np
          IF (TRIM(points(ir)%ptype) == TRIM(want)) j = points(ir)%id
        END DO
        IF (j == 0) THEN
          maxid = maxid + 1
          p = DeckPoint()
          p%id = maxid
          p%ptype = want
          p%deck_line = lines(i)%deck_line
          CALL grow_points(points, np)
          np = np + 1
          points(np) = p
          j = maxid
        END IF
        IF (k == 1) lines(i)%nodeA = j
        IF (k == 2) lines(i)%nodeB = j
      END DO
    END DO
    ! rod ends on a body-fixed rod attach to the body
    DO i = 1, np
      IF (.NOT. is_rod_point_type(points(i)%ptype)) CYCLE
      CALL parse_rod_point_type(points(i)%ptype, rod_id, end_id)
      ir = find_rod(rods, rod_id)
      IF (ir == 0) CYCLE
      IF (.NOT. starts_with(TRIM(rods(ir)%rod_type), 'body')) CYCLE
      bid = body_id_of_rod_type(rods(ir)%rod_type)
      IF (bid < 1 .OR. find_body(bodies, bid) == 0) CYCLE
      points(i)%ptype = 'body'//TRIM(int_to_str(bid))
      points(i)%rod_ref = rod_id
      points(i)%rod_end = end_id
      IF (end_id == 1) points(i)%pos = rods(ir)%end_a
      IF (end_id == 2) points(i)%pos = rods(ir)%end_b
    END DO
  END SUBROUTINE resolve_rod_end_tokens

  SUBROUTINE collapse_zero_length_rods(rods, points, np, lines, opts)
    !! Zero-length rods (NumSegs 0, MoorDyn): the rod is a point-like connector at End A (End B
    !! is ignored). MoorDyn gives it no mass, volume or side loads, and its end terms act along
    !! the rod axis, which a zero-length rod does not have (zero for lines without bending
    !! stiffness), so it carries no hydrodynamic load either. Each one becomes one POINT at End A
    !! that both of its ends (R<N>A/R<N>B tokens and Rod<N>A/B POINT rows) resolve to: Free for a
    !! free rod, Fixed for a fixed or pinned rod, Coupled for a coupled rod and Body<M> for a rod
    !! fixed or pinned to body M. The rod leaves the rod list; opts%zl_rod/zl_point keep the map
    !! so that a Rod<N> output channel on it can be refused by name.
    TYPE(DeckRod), ALLOCATABLE, INTENT(INOUT) :: rods(:)
    TYPE(DeckPoint), ALLOCATABLE, INTENT(INOUT) :: points(:)
    INTEGER, INTENT(INOUT) :: np
    TYPE(DeckLine), INTENT(INOUT) :: lines(:)
    TYPE(DeckOptions), INTENT(INOUT) :: opts
    INTEGER :: i, k, j, e, maxid, pid, bid, rod_id, end_id
    CHARACTER(NAMELEN) :: ptype
    LOGICAL, ALLOCATABLE :: keep(:), drop(:)
    TYPE(DeckPoint) :: p

    IF (.NOT. ALLOCATED(opts%zl_rod)) ALLOCATE (opts%zl_rod(0), opts%zl_point(0))
    IF (.NOT. ANY(rods%nsegs == 0)) RETURN
    maxid = 0
    DO i = 1, np
      maxid = MAX(maxid, points(i)%id)
    END DO
    ALLOCATE (keep(SIZE(rods)), drop(np))
    keep = .TRUE.
    drop = .FALSE.
    DO i = 1, SIZE(rods)
      IF (rods(i)%nsegs /= 0) CYCLE
      keep(i) = .FALSE.
      SELECT CASE (TRIM(rods(i)%rod_type))
      CASE ('free')
        ptype = 'free'
      CASE ('fixed', 'pinned')
        ptype = 'fixed'
      CASE ('coupled', 'vessel')
        ptype = 'coupled'
      CASE DEFAULT
        bid = MAX(body_id_of_rod_type(rods(i)%rod_type), pinned_body_of_rod_type(rods(i)%rod_type))
        ptype = rods(i)%rod_type
        IF (bid > 0) ptype = 'body'//TRIM(int_to_str(bid))
      END SELECT
      ! the connector point: the first Rod<N>A/B POINT row, else a new point
      pid = 0
      DO k = 1, np
        IF (drop(k)) CYCLE
        IF (.NOT. is_rod_point_type(points(k)%ptype)) CYCLE
        CALL parse_rod_point_type(points(k)%ptype, rod_id, end_id)
        IF (rod_id /= rods(i)%id) CYCLE
        IF (pid == 0) THEN
          pid = points(k)%id
          points(k)%ptype = ptype
          points(k)%pos = rods(i)%end_a
        ELSE
          ! a second end row: its lines move to the connector point
          drop(k) = .TRUE.
          DO j = 1, SIZE(lines)
            IF (lines(j)%nodeA == points(k)%id) lines(j)%nodeA = pid
            IF (lines(j)%nodeB == points(k)%id) lines(j)%nodeB = pid
          END DO
        END IF
      END DO
      IF (pid == 0) THEN
        maxid = maxid + 1
        pid = maxid
        p = DeckPoint()
        p%id = pid
        p%ptype = ptype
        p%pos = rods(i)%end_a
        p%deck_line = rods(i)%deck_line
        CALL grow_points(points, np)
        np = np + 1
        points(np) = p
        drop = [drop, .FALSE.]
      END IF
      DO j = 1, SIZE(lines)
        DO e = 0, 1
          IF (lines(j)%nodeA == -(2*rods(i)%id + e)) lines(j)%nodeA = pid
          IF (lines(j)%nodeB == -(2*rods(i)%id + e)) lines(j)%nodeB = pid
        END DO
      END DO
      opts%zl_rod = [opts%zl_rod, rods(i)%id]
      opts%zl_point = [opts%zl_point, pid]
    END DO
    IF (ANY(drop(1:np))) THEN
      j = 0
      DO k = 1, np
        IF (drop(k)) CYCLE
        j = j + 1
        points(j) = points(k)
      END DO
      np = j
    END IF
    rods = PACK(rods, keep)
  END SUBROUTINE collapse_zero_length_rods

  INTEGER FUNCTION body_id_of_rod_type(rod_type) RESULT(bid)
    !! Body id of a RODS attachment Body<M> (0 when the token is not exactly Body<M>).
    CHARACTER(*), INTENT(IN) :: rod_type
    INTEGER :: ios
    CHARACTER(NAMELEN) :: lo
    bid = 0
    lo = to_lower(TRIM(rod_type))
    IF (.NOT. starts_with(lo, 'body') .OR. LEN_TRIM(lo) < 5) RETURN
    IF (VERIFY(lo(5:LEN_TRIM(lo)), '0123456789') /= 0) RETURN
    READ (lo(5:LEN_TRIM(lo)), *, IOSTAT=ios) bid
    IF (ios /= 0) bid = 0
  END FUNCTION body_id_of_rod_type

  INTEGER FUNCTION pinned_body_of_rod_type(rod_type) RESULT(bid)
    !! Body id of a RODS attachment Body<M>Pinned (0 when the token is not exactly Body<M>Pinned).
    CHARACTER(*), INTENT(IN) :: rod_type
    INTEGER :: n
    CHARACTER(NAMELEN) :: lo
    bid = 0
    lo = to_lower(TRIM(rod_type))
    n = LEN_TRIM(lo)
    IF (n < 11) RETURN
    IF (lo(n - 5:n) /= 'pinned') RETURN
    bid = body_id_of_rod_type(lo(1:n - 6))
  END FUNCTION pinned_body_of_rod_type

  SUBROUTINE append_end_connection(line, endconns, nec, ErrStat, ErrMsg)
    !! END CONNECTIONS row:
    !!   LineID  End  BendingStiffness  EzX  EzY  EzZ  [TorsStiffness  NxX  NxY  NxZ  [Pretwist]]
    !! End is A or B. BendingStiffness is a non-negative number in N m/rad,
    !! Pinned/Free/Zero, or Rigid/Infinity. Ez follows the line End-A-to-End-B
    !! convention and is normalized here. Rigid selects the exact tangent-direction
    !! constraint; it is never converted to a large finite penalty stiffness.
    !! The optional torsion columns (10 or 11 columns in all): TorsStiffness is Free/Zero/0
    !! (default), Rigid/Infinity/Inf, or a positive torsional stiffness in N m/rad; Nx is the
    !! zero-twist reference normal in the frame of Ez (finite, non-zero, not parallel to Ez;
    !! orthonormalised against Ez here); Pretwist [deg, default 0, any real value] rolls the end
    !! frame about Ez (right-hand rule).
    CHARACTER(*), INTENT(IN) :: line
    TYPE(DeckEndConnection), ALLOCATABLE, INTENT(INOUT) :: endconns(:)
    INTEGER, INTENT(INOUT) :: nec
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    TYPE(DeckEndConnection), ALLOCATABLE :: grown(:)
    TYPE(DeckEndConnection) :: ec
    CHARACTER(NAMELEN) :: end_token, stiffness_token, tors_token
    REAL(wp) :: ez_norm, nx_norm
    INTEGER :: ios, istat, ntok
    LOGICAL :: ok

    ErrStat = 0
    ErrMsg = ''
    ntok = count_tokens(line)
    IF (ntok /= 6 .AND. ntok /= 10 .AND. ntok /= 11) THEN
      CALL fail(ErrStat, ErrMsg, &
                'END CONNECTIONS row needs 6 columns (LineID End Stiffness EzX EzY EzZ), or 10 or 11 with '// &
                'the torsion columns (... TorsStiffness NxX NxY NxZ [Pretwist])')
      RETURN
    END IF
    tors_token = 'free'
    IF (ntok == 6) THEN
      READ (line, *, IOSTAT=ios) ec%line_id, end_token, stiffness_token, ec%ez
    ELSE IF (ntok == 10) THEN
      READ (line, *, IOSTAT=ios) ec%line_id, end_token, stiffness_token, ec%ez, tors_token, ec%nx
    ELSE
      READ (line, *, IOSTAT=ios) ec%line_id, end_token, stiffness_token, ec%ez, tors_token, ec%nx, ec%pretwist
    END IF
    IF (ios /= 0 .OR. ec%line_id < 1) THEN
      CALL fail(ErrStat, ErrMsg, 'malformed END CONNECTIONS row')
      RETURN
    END IF
    SELECT CASE (to_lower(TRIM(end_token)))
    CASE ('a', 'enda', 'end_a')
      ec%end_index = 1
    CASE ('b', 'endb', 'end_b')
      ec%end_index = 2
    CASE DEFAULT
      CALL fail(ErrStat, ErrMsg, 'END CONNECTIONS End must be A or B')
      RETURN
    END SELECT
    SELECT CASE (to_lower(TRIM(stiffness_token)))
    CASE ('pinned', 'free', 'zero')
      ec%mode = CD_ENDCONN_PINNED
      ec%stiffness = CD_ZERO
    CASE ('rigid', 'infinity', 'inf')
      ec%mode = CD_ENDCONN_RIGID
      ec%stiffness = CD_ZERO
    CASE DEFAULT
      CALL parse_real_token(stiffness_token, ec%stiffness, ok)
      IF (.NOT. ok) ec%stiffness = -CD_ONE
      IF (.NOT. IEEE_IS_FINITE(ec%stiffness) .OR. ec%stiffness < CD_ZERO) THEN
        CALL fail(ErrStat, ErrMsg, &
                  'END CONNECTIONS stiffness must be finite and non-negative, Pinned, or Rigid')
        RETURN
      END IF
      IF (ec%stiffness > CD_ZERO) THEN
        ec%mode = CD_ENDCONN_FINITE
      ELSE
        ec%mode = CD_ENDCONN_PINNED
      END IF
    END SELECT
    IF (.NOT. ALL(IEEE_IS_FINITE(ec%ez))) THEN
      CALL fail(ErrStat, ErrMsg, 'END CONNECTIONS no-moment direction must be finite')
      RETURN
    END IF
    ez_norm = SQRT(DOT_PRODUCT(ec%ez, ec%ez))
    IF (.NOT. IEEE_IS_FINITE(ez_norm) .OR. ez_norm <= SQRT(TINY(CD_ONE))) THEN
      CALL fail(ErrStat, ErrMsg, 'END CONNECTIONS no-moment direction must be non-zero')
      RETURN
    END IF
    ec%ez = ec%ez/ez_norm
    IF (ntok > 6) THEN
      SELECT CASE (to_lower(TRIM(tors_token)))
      CASE ('free', 'zero')
        ec%tors_mode = TORS_FREE
      CASE ('rigid', 'infinity', 'inf')
        ec%tors_mode = TORS_RIGID
      CASE DEFAULT
        CALL parse_real_token(tors_token, ec%tors_k, ok)
        IF (.NOT. ok) ec%tors_k = -CD_ONE
        IF (.NOT. IEEE_IS_FINITE(ec%tors_k) .OR. ec%tors_k < CD_ZERO) THEN
          CALL fail(ErrStat, ErrMsg, 'END CONNECTIONS torsional stiffness must be finite and non-negative, '// &
                    'Free, or Rigid')
          RETURN
        END IF
        ec%tors_mode = MERGE(TORS_FINITE, TORS_FREE, ec%tors_k > CD_ZERO)
      END SELECT
      IF (.NOT. (ALL(IEEE_IS_FINITE(ec%nx)) .AND. IEEE_IS_FINITE(ec%pretwist))) THEN
        CALL fail(ErrStat, ErrMsg, 'END CONNECTIONS torsion reference normal and pretwist must be finite')
        RETURN
      END IF
      nx_norm = SQRT(DOT_PRODUCT(ec%nx, ec%nx))
      IF (.NOT. IEEE_IS_FINITE(nx_norm) .OR. nx_norm <= SQRT(TINY(CD_ONE))) THEN
        CALL fail(ErrStat, ErrMsg, 'END CONNECTIONS torsion reference normal (NxX NxY NxZ) must be non-zero')
        RETURN
      END IF
      ec%nx = ec%nx/nx_norm
      IF (NORM2(cross3(ec%nx, ec%ez)) < TORS_NX_PARALLEL_TOL) THEN
        CALL fail(ErrStat, ErrMsg, 'END CONNECTIONS torsion reference normal (NxX NxY NxZ) must not be '// &
                  'parallel to the direction Ez')
        RETURN
      END IF
      ec%nx = ec%nx - DOT_PRODUCT(ec%nx, ec%ez)*ec%ez
      ec%nx = ec%nx/NORM2(ec%nx)
      ec%pretwist = ec%pretwist*DEG2RAD_TORS
    END IF

    ALLOCATE (grown(nec + 1), STAT=istat)
    IF (istat /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'END CONNECTIONS row allocation failed')
      RETURN
    END IF
    IF (nec > 0) grown(1:nec) = endconns(1:nec)
    grown(nec + 1) = ec
    CALL MOVE_ALLOC(grown, endconns)
    nec = nec + 1
  END SUBROUTINE append_end_connection

  SUBROUTINE append_line_attachment(row, lines, ErrStat, ErrMsg)
    !! One ATTACHMENTS row: LineID ArcLength Mass Volume CdA Ca [CdAx]. ArcLength [m, from
    !! End A] is one value or a series first:pitch:last (inclusive, first <= last, pitch > 0)
    !! of identical attachments; CdA is the drag area normal to the line and the optional
    !! CdAx (default 0) the axial one. Stored columns: arc, mass, volume, CdA, Ca, CdAx.
    CHARACTER(*), INTENT(IN) :: row
    TYPE(DeckLine), INTENT(INOUT) :: lines(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER, PARAMETER :: MAX_SERIES = 100000
    CHARACTER(DECK_RECLEN) :: tok
    INTEGER :: li, lid, k, n, p1, p2, nold
    REAL(wp) :: vals(5), s0, ds, s1, x
    INTEGER :: ntok
    REAL(wp), ALLOCATABLE :: grown(:, :)
    LOGICAL :: found, ok

    ErrStat = 0; ErrMsg = ''
    ntok = count_tokens(row)
    IF (ntok /= 6 .AND. ntok /= 7) THEN
      CALL fail(ErrStat, ErrMsg, 'ATTACHMENTS rows must be: LineID ArcLength Mass Volume CdA Ca [CdAx]'); RETURN
    END IF
    CALL get_token(row, 1, tok, found)
    CALL parse_int_token(tok, lid, ok)
    IF (.NOT. ok) THEN
      CALL fail(ErrStat, ErrMsg, 'ATTACHMENTS LineID must be an integer'); RETURN
    END IF
    li = find_line(lines, lid)
    IF (li == 0) THEN
      CALL fail(ErrStat, ErrMsg, 'ATTACHMENTS row references undefined LINE id '//TRIM(int_to_str(lid))); RETURN
    END IF
    vals = CD_ZERO
    DO k = 1, ntok - 2
      CALL get_token(row, k + 2, tok, found)
      CALL parse_real_token(tok, vals(k), ok)
      IF (.NOT. ok) THEN
        CALL fail(ErrStat, ErrMsg, 'ATTACHMENTS Mass, Volume, CdA, Ca and CdAx must be plain numbers'); RETURN
      END IF
    END DO
    IF (.NOT. ALL(IEEE_IS_FINITE(vals)) .OR. ANY(vals < CD_ZERO)) THEN
      CALL fail(ErrStat, ErrMsg, 'ATTACHMENTS Mass, Volume, CdA, Ca and CdAx must be finite and >= 0'); RETURN
    END IF
    IF (.NOT. (vals(1) > CD_ZERO .OR. vals(2) > CD_ZERO .OR. vals(3) > CD_ZERO .OR. vals(5) > CD_ZERO)) THEN
      CALL fail(ErrStat, ErrMsg, 'an ATTACHMENTS row needs a positive Mass, Volume, CdA or CdAx'); RETURN
    END IF
    CALL get_token(row, 2, tok, found)
    p1 = INDEX(tok, ':')
    IF (p1 == 0) THEN
      CALL parse_real_token(tok, s0, ok)
      ds = CD_ONE; s1 = s0
    ELSE
      p2 = INDEX(tok(p1 + 1:), ':')
      ok = p2 > 0
      IF (ok) THEN
        p2 = p1 + p2
        ok = INDEX(tok(p2 + 1:), ':') == 0
      END IF
      IF (ok) CALL parse_real_token(tok(1:p1 - 1), s0, ok)
      IF (ok) CALL parse_real_token(tok(p1 + 1:p2 - 1), ds, ok)
      IF (ok) CALL parse_real_token(tok(p2 + 1:), s1, ok)
    END IF
    IF (ok) ok = IEEE_IS_FINITE(s0) .AND. IEEE_IS_FINITE(ds) .AND. IEEE_IS_FINITE(s1)
    IF (ok) ok = s0 >= CD_ZERO .AND. ds > CD_ZERO .AND. s1 >= s0
    IF (.NOT. ok) THEN
      CALL fail(ErrStat, ErrMsg, 'ATTACHMENTS ArcLength must be a value >= 0 or a series first:pitch:last '// &
                'with 0 <= first <= last and pitch > 0'); RETURN
    END IF
    x = (s1 - s0)/ds
    IF (x > REAL(MAX_SERIES, wp)) THEN
      CALL fail(ErrStat, ErrMsg, 'an ATTACHMENTS series may hold at most 100000 attachments'); RETURN
    END IF
    n = INT(x + 1.0e-9_wp*MAX(CD_ONE, x)) + 1
    nold = 0
    IF (ALLOCATED(lines(li)%att)) nold = SIZE(lines(li)%att, 2)
    ALLOCATE (grown(6, nold + n))
    IF (nold > 0) grown(:, 1:nold) = lines(li)%att
    DO k = 1, n
      grown(:, nold + k) = [s0 + REAL(k - 1, wp)*ds, vals]
    END DO
    CALL MOVE_ALLOC(grown, lines(li)%att)
  END SUBROUTINE append_line_attachment

  SUBROUTINE trim_end_connections(endconns, nec)
    TYPE(DeckEndConnection), ALLOCATABLE, INTENT(INOUT) :: endconns(:)
    INTEGER, INTENT(IN) :: nec
    TYPE(DeckEndConnection), ALLOCATABLE :: trimmed(:)
    IF (SIZE(endconns) == nec) RETURN
    ALLOCATE (trimmed(nec))
    trimmed = endconns(1:nec)
    CALL MOVE_ALLOC(trimmed, endconns)
  END SUBROUTINE trim_end_connections

  SUBROUTINE resolve_end_connections(endconns, lines, ErrStat, ErrMsg)
    TYPE(DeckEndConnection), INTENT(IN) :: endconns(:)
    TYPE(DeckLine), INTENT(INOUT) :: lines(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: i, j, lidx

    ErrStat = 0
    ErrMsg = ''
    DO i = 1, SIZE(endconns)
      DO j = 1, i - 1
        IF (endconns(j)%line_id == endconns(i)%line_id .AND. &
            endconns(j)%end_index == endconns(i)%end_index) THEN
          CALL fail(ErrStat, ErrMsg, 'duplicate END CONNECTIONS row for line '// &
                    TRIM(int_to_str(endconns(i)%line_id))//' end '//MERGE('A', 'B', endconns(i)%end_index == 1))
          RETURN
        END IF
      END DO
      lidx = 0
      DO j = 1, SIZE(lines)
        IF (lines(j)%id == endconns(i)%line_id) THEN
          lidx = j
          EXIT
        END IF
      END DO
      IF (lidx == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'END CONNECTIONS row references unknown LineID '// &
                  TRIM(int_to_str(endconns(i)%line_id)))
        RETURN
      END IF
      lines(lidx)%endconn_mode(endconns(i)%end_index) = endconns(i)%mode
      lines(lidx)%endconn_k(endconns(i)%end_index) = endconns(i)%stiffness
      lines(lidx)%endconn_ez_ref(:, endconns(i)%end_index) = endconns(i)%ez
      lines(lidx)%tors_mode(endconns(i)%end_index) = endconns(i)%tors_mode
      lines(lidx)%tors_k(endconns(i)%end_index) = endconns(i)%tors_k
      lines(lidx)%tors_nx(:, endconns(i)%end_index) = endconns(i)%nx
      lines(lidx)%tors_pretwist(endconns(i)%end_index) = endconns(i)%pretwist
    END DO
  END SUBROUTINE resolve_end_connections

  SUBROUTINE apply_syrope_ic(line, lines, nlin, ErrStat, ErrMsg)
    !! MoorDyn-F SYROPE IC row: Line(s) Tmax0 Tmean0. Comma-separated line
    !! identifiers share one load-history pair.
    CHARACTER(*), INTENT(IN) :: line
    TYPE(DeckLine), INTENT(INOUT) :: lines(:)
    INTEGER, INTENT(IN) :: nlin
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER, ALLOCATABLE :: ids(:)
    INTEGER :: nids, i, j, ntok, lo, hi, n
    REAL(wp) :: tmax0, tmean0
    CHARACTER(LEN(line)) :: tok, id_list, piece
    LOGICAL :: found, ok

    ErrStat = 0
    ErrMsg = ''
    ! Whitespace tokens: the last two are Tmax0 Tmean0; all earlier tokens form the
    ! comma-separated line-id list ("1,2" or "1, 2"). Adjacent id tokens must be joined
    ! by a comma, so "1 2 ..." cannot silently become line 12.
    ntok = count_tokens(line)
    IF (ntok < 3) THEN
      CALL fail(ErrStat, ErrMsg, 'malformed SYROPE IC row (expected Line(s), Tmax0, Tmean0)')
      RETURN
    END IF
    id_list = ''
    DO i = 1, ntok - 2
      CALL get_token(line, i, tok, found)
      IF (i > 1) THEN
        n = LEN_TRIM(id_list)
        IF (id_list(n:n) /= ',' .AND. tok(1:1) /= ',') THEN
          CALL fail(ErrStat, ErrMsg, 'SYROPE IC line ids must be separated by commas')
          RETURN
        END IF
      END IF
      id_list = TRIM(id_list)//TRIM(tok)
    END DO
    CALL get_token(line, ntok - 1, tok, found)
    CALL parse_real_token(tok, tmax0, ok)
    IF (ok) THEN
      CALL get_token(line, ntok, tok, found)
      CALL parse_real_token(tok, tmean0, ok)
    END IF
    IF (.NOT. ok) THEN
      CALL fail(ErrStat, ErrMsg, 'SYROPE IC Tmax0 and Tmean0 must be plain numbers')
      RETURN
    END IF
    n = LEN_TRIM(id_list)
    nids = COUNT([(id_list(i:i) == ',', i=1, n)]) + 1
    ALLOCATE (ids(nids))
    lo = 1
    DO i = 1, nids
      hi = INDEX(id_list(lo:n), ',')
      IF (hi == 0) THEN
        piece = id_list(lo:n)
      ELSE
        piece = id_list(lo:lo + hi - 2)
        lo = lo + hi
      END IF
      CALL parse_int_token(piece, ids(i), ok)
      IF (.NOT. ok .OR. ids(i) < 1) THEN
        CALL fail(ErrStat, ErrMsg, 'SYROPE IC line list must be positive line ids separated by commas')
        RETURN
      END IF
    END DO
    IF (.NOT. (IEEE_IS_FINITE(tmax0) .AND. IEEE_IS_FINITE(tmean0) .AND. &
               tmax0 > CD_ZERO .AND. tmean0 >= CD_ZERO .AND. tmax0 >= tmean0)) THEN
      CALL fail(ErrStat, ErrMsg, 'SYROPE IC requires finite Tmax0 >= Tmean0 >= 0 with Tmax0 > 0')
      RETURN
    END IF
    DO i = 1, nids
      j = 0
      IF (nlin > 0) j = find_line(lines(1:nlin), ids(i))
      IF (j == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'SYROPE IC references undefined LINE id '//TRIM(int_to_str(ids(i))))
        RETURN
      END IF
      IF (lines(j)%has_syrope_ic) THEN
        CALL fail(ErrStat, ErrMsg, 'duplicate SYROPE IC assignment for LINE '//TRIM(int_to_str(ids(i))))
        RETURN
      END IF
      lines(j)%has_syrope_ic = .TRUE.
      lines(j)%syrope_tmax0 = tmax0
      lines(j)%syrope_tmean0 = tmean0
    END DO
  END SUBROUTINE apply_syrope_ic

  SUBROUTINE append_section(line, sections, nsec, ErrStat, ErrMsg)
    CHARACTER(*), INTENT(IN) :: line
    TYPE(DeckSection), ALLOCATABLE, INTENT(INOUT) :: sections(:)
    INTEGER, INTENT(INOUT) :: nsec
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(DeckSection) :: s
    INTEGER :: ios
    ErrStat = 0; ErrMsg = ''
    IF (count_tokens(line) /= 4) THEN
      CALL fail(ErrStat, ErrMsg, 'SECTIONS row needs 4 cols: LineID LineType Length NumSegs'); RETURN
    END IF
    READ (line, *, IOSTAT=ios) s%line_id, s%ltype_name, s%length, s%nsegs
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'malformed SECTIONS row'); RETURN
    END IF
    CALL grow_sections(sections, nsec)
    nsec = nsec + 1; sections(nsec) = s
  END SUBROUTINE append_section

  SUBROUTINE append_equivalent_buoyancy(line, equivs, neq, ErrStat, ErrMsg)
    CHARACTER(*), INTENT(IN) :: line
    TYPE(DeckEquivalentBuoyancy), ALLOCATABLE, INTENT(INOUT) :: equivs(:)
    INTEGER, INTENT(INOUT) :: neq
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    TYPE(DeckEquivalentBuoyancy) :: eq
    INTEGER :: ios

    ErrStat = 0
    ErrMsg = ''
    IF (count_tokens(line) /= 3) THEN
      CALL fail(ErrStat, ErrMsg, 'EQUIVALENT BUOYANCY row needs 3 cols: LineType Diam SubmergedWeightNpm')
      RETURN
    END IF
    READ (line, *, IOSTAT=ios) eq%ltype_name, eq%diameter, eq%submerged_weight
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'malformed EQUIVALENT BUOYANCY row')
      RETURN
    END IF
    CALL grow_equivalent_buoyancy(equivs, neq)
    neq = neq + 1
    equivs(neq) = eq
  END SUBROUTINE append_equivalent_buoyancy

  SUBROUTINE apply_equivalent_buoyancy(types, equivs, opts, ErrStat, ErrMsg)
    TYPE(DeckLineType), INTENT(INOUT) :: types(:)
    TYPE(DeckEquivalentBuoyancy), INTENT(IN) :: equivs(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    REAL(wp) :: mass_per_length(1)
    INTEGER :: i, j, idx, es
    CHARACTER(200) :: em

    ErrStat = 0
    ErrMsg = ''
    DO i = 1, SIZE(equivs)
      DO j = i + 1, SIZE(equivs)
        IF (to_lower(TRIM(equivs(i)%ltype_name)) == to_lower(TRIM(equivs(j)%ltype_name))) THEN
          CALL fail(ErrStat, ErrMsg, 'duplicate EQUIVALENT BUOYANCY row for LineType "'// &
                    TRIM(equivs(i)%ltype_name)//'"')
          RETURN
        END IF
      END DO
      idx = find_type(types, equivs(i)%ltype_name)
      IF (idx == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'EQUIVALENT BUOYANCY references unknown LineType "'// &
                  TRIM(equivs(i)%ltype_name)//'"')
        RETURN
      END IF
      IF (.NOT. (IEEE_IS_FINITE(equivs(i)%diameter) .AND. equivs(i)%diameter > CD_ZERO .AND. &
                 IEEE_IS_FINITE(equivs(i)%submerged_weight))) THEN
        CALL fail(ErrStat, ErrMsg, 'EQUIVALENT BUOYANCY needs finite Diam > 0 and finite submerged weight')
        RETURN
      END IF
      CALL CD_Equivalent_Buoyant_Section([equivs(i)%submerged_weight], [equivs(i)%diameter], opts%rhoW, opts%g, &
                                         mass_per_length, es, em)
      IF (es /= CD_HCDYN_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'EQUIVALENT BUOYANCY for LineType "'//TRIM(equivs(i)%ltype_name)//'": '// &
                  TRIM(em))
        RETURN
      END IF
      types(idx)%diam = equivs(i)%diameter
      types(idx)%mass = mass_per_length(1)
    END DO
  END SUBROUTINE apply_equivalent_buoyancy

  SUBROUTINE apply_option(line, opts, ErrStat, ErrMsg)
    CHARACTER(*), INTENT(IN) :: line
    CHARACTER(CD_DECK_PATHLEN) :: dval, val, option_line
    TYPE(DeckOptions), INTENT(INOUT) :: opts
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    CHARACTER(NAMELEN) :: kw, mode
    REAL(wp) :: x1, x2, x3, x4, x5, x6, x7, x8
    INTEGER :: i1, i2, ios, ntok, pdesc
    ErrStat = 0; ErrMsg = ''
    ! Scalar MoorDyn-style options already tolerate trailing descriptions because
    ! the generic parser consumes only value + keyword. Positional current/wave
    ! records end with their keyword, however, so a copied example such as
    ! "airy 2 8 0 waves - regular wave" would carry extra tokens past the
    ! special-form branch. Strip only a whitespace-delimited single-dash description here. Negative numeric values
    ! (for example -1.0) and section dash rules are unaffected.
    option_line = line
    DO pdesc = 2, LEN_TRIM(option_line) - 1
      IF (option_line(pdesc:pdesc) == '-') THEN
        IF (is_space(option_line(pdesc - 1:pdesc - 1)) .AND. &
            is_space(option_line(pdesc + 1:pdesc + 1))) THEN
          option_line(pdesc:) = ' '
          EXIT
        END IF
      END IF
    END DO
    ntok = count_tokens(option_line)
    ! Every number on an OPTIONS row must be admissible before any reader compares it:
    ! a NaN, Inf (or beyond-HUGE) or subnormal value fails HERE with a typed message, so
    ! no range guard ever sees NaN (for which "x < lo .OR. x > hi" is false) and no
    ! later division sees a denormal. A scalar row carries its value in token 1; a
    ! positional current/waves/wavetrain/dynamic_solver row in every token but its keyword.
    IF (ntok >= 1) THEN
      BLOCK
        CHARACTER(LEN(option_line)) :: otok, first_lc, last_lc
        LOGICAL :: found_o
        INTEGER :: jt, nscan, kdef
        CALL get_token(option_line, 1, first_lc, found_o)
        CALL get_token(option_line, ntok, last_lc, found_o)
        first_lc = to_lower(first_lc)
        last_lc = to_lower(last_lc)
        nscan = 1
        IF (ntok >= 3) THEN
          IF (TRIM(first_lc) == 'dynamic_solver' .OR. TRIM(last_lc) == 'current' .OR. &
              TRIM(last_lc) == 'waves' .OR. TRIM(last_lc) == 'wave' .OR. &
              TRIM(last_lc) == 'wavetrain' .OR. TRIM(last_lc) == 'wave_train') nscan = ntok
        END IF
        DO jt = 1, nscan
          CALL get_token(option_line, jt, otok, found_o)
          kdef = real_token_defect(strip_quotes(otok))
          IF (kdef /= REAL_OK) THEN
            CALL fail(ErrStat, ErrMsg, 'OPTIONS '//real_defect_text(strip_quotes(otok), kdef))
            RETURN
          END IF
        END DO
      END BLOCK
    END IF
    BLOCK
      ! spectral waves rows and multi-train wavetrain rows (CableDyn_WaveSpectra)
      TYPE(CD_WaveTrainType) :: train
      CHARACTER(16) :: wkw
      LOGICAL :: handled
      CALL CD_Sea_Parse_Train(option_line, wkw, handled, train, ErrStat, ErrMsg)
      IF (handled) THEN
        IF (ErrStat /= CD_SEA_OK) RETURN
        IF (TRIM(wkw) == 'wavetrain') THEN
          CALL CD_Sea_Add_Train(opts%sea, train, ErrStat, ErrMsg)
        ELSE
          opts%wave_train = train
          opts%wave_height = train%height
          opts%wave_period = train%period
          opts%wave_direction = train%direction
          opts%wave_gamma = CD_ONE
          opts%has_wave = .TRUE.
          opts%wave_kind = WAVE_SEA
        END IF
        RETURN
      END IF
    END BLOCK
    ! The positional records below are list-directed READs of the whole row. A value
    ! such as "1e-6/2" or "0,5" would be read partially (or shift the columns), so a
    ! record that names one of these forms must have separator-free tokens.
    IF (ntok == 5 .OR. ntok == 6 .OR. ntok == 10) THEN
      BLOCK
        CHARACTER(LEN(option_line)) :: first_tok, last_tok
        LOGICAL :: found_first, found_last
        INTEGER :: jt
        CALL get_token(option_line, 1, first_tok, found_first)
        CALL get_token(option_line, ntok, last_tok, found_last)
        first_tok = to_lower(first_tok)
        last_tok = to_lower(last_tok)
        IF (TRIM(first_tok) == 'dynamic_solver' .OR. &
            ((TRIM(first_tok) == 'uniform' .OR. TRIM(first_tok) == 'profile') .AND. &
             TRIM(last_tok) == 'current') .OR. &
            ((TRIM(first_tok) == 'airy' .OR. TRIM(first_tok) == 'jonswap' .OR. TRIM(first_tok) == 'stream' .OR. &
              TRIM(first_tok) == 'dean') .AND. &
             (TRIM(last_tok) == 'waves' .OR. TRIM(last_tok) == 'wave'))) THEN
          DO jt = 1, ntok
            CALL get_token(option_line, jt, first_tok, found_first)
            IF (has_list_separator(TRIM(first_tok))) THEN
              CALL fail(ErrStat, ErrMsg, 'OPTIONS value "'//TRIM(first_tok)//'" contains "/", ",", ";" '// &
                        'or a repeat count "n*"; write plain numbers with a "." decimal point')
              RETURN
            END IF
          END DO
        END IF
      END BLOCK
    END IF
    IF (ntok == 5 .OR. ntok == 6) THEN
      READ (option_line, *, IOSTAT=ios) mode
      IF (ios /= 0) THEN
        CALL fail(ErrStat, ErrMsg, 'malformed OPTIONS row'); RETURN
      END IF
      IF (to_lower(TRIM(mode)) == 'dynamic_solver') THEN
        IF (ntok == 5) THEN
          READ (option_line, *, IOSTAT=ios) mode, x1, x2, i1, i2
        ELSE
          READ (option_line, *, IOSTAT=ios) mode, x1, x2, i1, i2, x3
        END IF
        IF (ios /= 0) THEN
          CALL fail(ErrStat, ErrMsg, 'malformed dynamic_solver OPTIONS row'); RETURN
        END IF
        ! Every row is validated, including one a later row overrides.
        IF (ntok == 5) x3 = opts%rho_inf
        IF (.NOT. (IEEE_IS_FINITE(x1) .AND. x1 > CD_ZERO .AND. IEEE_IS_FINITE(x2) .AND. x2 > CD_ZERO .AND. &
                   i1 >= 1 .AND. i2 >= 0 .AND. IEEE_IS_FINITE(x3) .AND. x3 >= CD_ZERO .AND. x3 <= CD_ONE)) THEN
          CALL fail(ErrStat, ErrMsg, 'dynamic_solver needs finite positive tolerances, max_iter >= 1, '// &
                    'backtracks >= 0, and optional rhoInf in [0, 1]'); RETURN
        END IF
        opts%dynamic_rel_tol = x1
        opts%dynamic_abs_tol = x2
        opts%dynamic_max_iter = i1
        opts%dynamic_backtracks = i2
        IF (ntok == 6) opts%rho_inf = x3
        RETURN
      END IF
    END IF
    IF (ntok == 10) THEN
      ! A stock options row with trailing commentary can tokenize to any width, so a
      ! failed special-form READ falls through to the generic "value keyword" path
      ! rather than aborting.
      READ (option_line, *, IOSTAT=ios) mode, x1, x2, x3, x4, x5, x6, x7, x8, kw
      IF (ios == 0) THEN
      IF (to_lower(TRIM(kw)) == 'current') THEN
        IF (to_lower(TRIM(mode)) /= 'profile') THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION current profile row must start with "profile"'); RETURN
        END IF
        IF (.NOT. ALL(IEEE_IS_FINITE([x1, x2, x3, x4, x5, x6, x7, x8]))) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION current profile values must be finite'); RETURN
        END IF
        IF (ABS(x5 - x1) <= 100.0_wp*EPSILON(CD_ONE)) THEN
          CALL fail(ErrStat, ErrMsg, 'current profile depths must be strictly increasing'); RETURN
        END IF
        ! normalize to ASCENDING z (the N-level interpolation primitive's contract;
        ! a descending two-point row keeps its original meaning)
        IF (ALLOCATED(opts%current_profile_z)) DEALLOCATE (opts%current_profile_z)
        IF (ALLOCATED(opts%current_profile_velocity)) DEALLOCATE (opts%current_profile_velocity)
        ALLOCATE (opts%current_profile_z(2), opts%current_profile_velocity(3, 2))
        IF (x1 <= x5) THEN
          opts%current_profile_z = [x1, x5]
          opts%current_profile_velocity(:, 1) = [x2, x3, x4]
          opts%current_profile_velocity(:, 2) = [x6, x7, x8]
        ELSE
          opts%current_profile_z = [x5, x1]
          opts%current_profile_velocity(:, 1) = [x6, x7, x8]
          opts%current_profile_velocity(:, 2) = [x2, x3, x4]
        END IF
        opts%has_current = .TRUE.
        opts%has_current_profile = .TRUE.
        RETURN
      END IF
      END IF
    ELSE IF (ntok == 6) THEN
      READ (option_line, *, IOSTAT=ios) mode, x1, x2, x3, x4, kw
      IF (ios == 0) THEN
      IF (to_lower(TRIM(kw)) == 'waves' .OR. to_lower(TRIM(kw)) == 'wave') THEN
        IF (to_lower(TRIM(mode)) /= 'jonswap') THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION waves row with 6 tokens must start with "jonswap"'); RETURN
        END IF
        IF (.NOT. (ALL(IEEE_IS_FINITE([x1, x2, x3, x4])) .AND. x1 > CD_ZERO .AND. x2 > CD_ZERO .AND. &
                   x3 >= CD_ONE)) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION waves needs finite values, positive height/period, and '// &
                    'JONSWAP gamma >= 1'); RETURN
        END IF
        opts%wave_height = x1
        opts%wave_period = x2
        opts%wave_gamma = x3
        opts%wave_direction = x4
        opts%has_wave = .TRUE.
        opts%wave_kind = WAVE_JONSWAP
        RETURN
      END IF
      END IF
    ELSE IF (ntok == 5) THEN
      READ (option_line, *, IOSTAT=ios) mode, x1, x2, x3, kw
      IF (ios == 0) THEN
      IF (to_lower(TRIM(kw)) == 'current') THEN
        IF (to_lower(TRIM(mode)) /= 'uniform') THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION current supports only "uniform vx vy vz current"'); RETURN
        END IF
        IF (.NOT. ALL(IEEE_IS_FINITE([x1, x2, x3]))) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION current velocity must be finite'); RETURN
        END IF
        opts%current_velocity = [x1, x2, x3]
        opts%has_current = .TRUE.
        opts%has_current_profile = .FALSE.
        RETURN
      ELSE IF (to_lower(TRIM(kw)) == 'waves' .OR. to_lower(TRIM(kw)) == 'wave') THEN
        IF (to_lower(TRIM(mode)) /= 'airy' .AND. to_lower(TRIM(mode)) /= 'stream' .AND. &
            to_lower(TRIM(mode)) /= 'dean') THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION waves forms: "none waves", "airy|stream|dean H T dir waves", '// &
                    '"jonswap Hs Tp gamma dir waves", or a spectral pm/torsethaugen row (doc/options.rst)'); RETURN
        END IF
        IF (.NOT. (ALL(IEEE_IS_FINITE([x1, x2, x3])) .AND. x1 > CD_ZERO .AND. x2 > CD_ZERO)) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION waves needs finite values and positive height/period'); RETURN
        END IF
        opts%wave_height = x1
        opts%wave_period = x2
        opts%wave_direction = x3
        opts%has_wave = .TRUE.
        opts%wave_kind = WAVE_AIRY
        IF (to_lower(TRIM(mode)) /= 'airy') opts%wave_kind = WAVE_STREAM
        RETURN
      END IF
      END IF
    END IF
    IF (ntok < 2) THEN
      CALL fail(ErrStat, ErrMsg, 'OPTIONS row needs "value keyword"'); RETURN
    END IF
    ! A positional waves/current/solver row must end with its keyword; one followed by
    ! undashed commentary ("airy 2 8 0 waves regular") would otherwise reach the generic
    ! path and fail as an unknown keyword "2".
    IF (ntok >= 4) THEN
      BLOCK
        CHARACTER(LEN(option_line)) :: first_tok
        LOGICAL :: found_first
        CALL get_token(option_line, 1, first_tok, found_first)
        SELECT CASE (to_lower(TRIM(first_tok)))
        CASE ('airy', 'jonswap', 'stream', 'dean', 'uniform', 'profile', 'dynamic_solver')
          CALL fail(ErrStat, ErrMsg, 'OPTIONS row "'//TRIM(first_tok)//' ..." is a positional '// &
                    'waves/current/dynamic_solver row with the wrong number of values, or with text after '// &
                    'its keyword; write a description after " - "'); RETURN
        END SELECT
      END BLOCK
    END IF
    ! Stock MoorDyn options rows carry trailing commentary after the keyword
    ! ("0.001  dtM  - time step ..."); like MoorDyn, read the first two tokens
    ! and ignore the rest.
    CALL split_two_tokens(option_line, val, kw, ios, allow_trailing=.TRUE.)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'malformed OPTIONS row'); RETURN
    END IF
    SELECT CASE (to_lower(TRIM(kw)))
    CASE ('g', 'gravity'); CALL rd(val, opts%g, ErrStat, ErrMsg)
    CASE ('rhow', 'wtrdnsty', 'water_density'); CALL rd(val, opts%rhoW, ErrStat, ErrMsg)
    CASE ('wtrdpth', 'water_depth')
      CALL rd(val, opts%wtrdpth, ErrStat, ErrMsg); opts%has_wtrdpth = .TRUE.
    CASE ('bathymetryfile', 'bathymetry_file', 'seafloorfile', 'seafloor_file')
      opts%bathymetry_file = strip_quotes(val)
      opts%has_bathymetry_file = .TRUE.
    CASE ('kbot', 'kb'); CALL rd(val, opts%kbot, ErrStat, ErrMsg)
    CASE ('cbot', 'cb'); CALL rd(val, opts%cbot, ErrStat, ErrMsg)
    CASE ('icmode')
      ! the ICmode row is retired: there is no initial-condition choice to make
      CALL fail(ErrStat, ErrMsg, 'ICmode is not an option: CableDyn always solves the static '// &
                'equilibrium directly; delete the ICmode row')
    CASE ('bodyic')
      ! free Rigid6 bodies and rods start at their static equilibrium (static) or at the
      ! deck pose (deck, e.g. to release a body for a free-decay test)
      SELECT CASE (TRIM(to_lower(val)))
      CASE ('static')
        opts%body_ic_static = .TRUE.
      CASE ('deck')
        opts%body_ic_static = .FALSE.
      CASE DEFAULT
        CALL fail(ErrStat, ErrMsg, 'bodyIC "'//TRIM(val)//'" is not supported (use static or deck)')
      END SELECT
    CASE ('bodywetting')
      ! Rigid6 submergence: equivalent sphere at the centre of buoyancy (sphere) or always wet
      ! (moordyn, MoorDyn parity)
      SELECT CASE (TRIM(to_lower(val)))
      CASE ('sphere')
        opts%body_wetting_moordyn = .FALSE.
      CASE ('moordyn')
        opts%body_wetting_moordyn = .TRUE.
      CASE DEFAULT
        CALL fail(ErrStat, ErrMsg, 'bodyWetting "'//TRIM(val)//'" is not supported (use sphere or moordyn)')
      END SELECT
    CASE ('bodyscheme')
      ! Rigid6 bodies, rods and Free/Connect points: one monolithic implicit generalised-alpha
      ! step with the lines (monolithic) or the staggered coupling (staggered)
      SELECT CASE (TRIM(to_lower(val)))
      CASE ('monolithic')
        opts%body_scheme_staggered = .FALSE.
        opts%body_scheme_monolithic_named = .TRUE.
      CASE ('staggered')
        opts%body_scheme_staggered = .TRUE.
        opts%body_scheme_monolithic_named = .FALSE.
      CASE DEFAULT
        CALL fail(ErrStat, ErrMsg, 'bodyScheme "'//TRIM(val)//'" is not supported (use monolithic or staggered)')
      END SELECT
    CASE ('bodysubstep')
      ! monolithic scheme: resolve the stiffest object-mooring mode by sub-stepping (accuracy, the
      ! default) or take the coupling step as given (none)
      SELECT CASE (TRIM(to_lower(val)))
      CASE ('none')
        opts%body_substep_accuracy = .FALSE.
      CASE ('accuracy')
        opts%body_substep_accuracy = .TRUE.
      CASE DEFAULT
        CALL fail(ErrStat, ErrMsg, 'bodySubstep "'//TRIM(val)//'" is not supported (use none or accuracy)')
      END SELECT
    CASE ('rodhydro')
      ! rod waterplane moment: exact (displaced-volume) or with MoorDyn's extra term
      SELECT CASE (TRIM(to_lower(val)))
      CASE ('exact')
        opts%rod_hydro_moordyn = .FALSE.
      CASE ('moordyn')
        opts%rod_hydro_moordyn = .TRUE.
      CASE DEFAULT
        CALL fail(ErrStat, ErrMsg, 'rodHydro "'//TRIM(val)//'" is not supported (use exact or moordyn)')
      END SELECT
    CASE ('bodyhydro')
      ! Rigid6 fluid inertia: Morison with Froude-Krylov (morison) or without it (moordyn)
      SELECT CASE (TRIM(to_lower(val)))
      CASE ('morison')
        opts%body_hydro_moordyn = .FALSE.
      CASE ('moordyn')
        opts%body_hydro_moordyn = .TRUE.
      CASE DEFAULT
        CALL fail(ErrStat, ErrMsg, 'bodyHydro "'//TRIM(val)//'" is not supported (use morison or moordyn)')
      END SELECT
    CASE ('dtm', 'dt')
      CALL rd(val, opts%dtM, ErrStat, ErrMsg)
      opts%has_dtm = (ErrStat == 0)
    CASE ('tmax')
      CALL rd(val, opts%tmax, ErrStat, ErrMsg)
      opts%has_tmax = (ErrStat == 0)
    CASE ('rhoinf', 'rho_inf')
      CALL rd(val, opts%rho_inf, ErrStat, ErrMsg)
    CASE ('dtwave')
      ! MoorDyn-C WaveKin 3: the resampling step of wave_elevation.txt
      CALL rd(val, opts%mdc_dt_wave, ErrStat, ErrMsg)
    CASE ('ramptime', 'ramp_time', 'tramp')
      CALL rd(val, opts%ramp_time, ErrStat, ErrMsg)
    CASE ('maxstrain', 'max_strain')
      CALL rd(val, opts%max_strain, ErrStat, ErrMsg)
    CASE ('streamorder', 'stream_order')
      CALL rd(val, x1, ErrStat, ErrMsg)
      IF (ErrStat == 0) THEN
        IF (.NOT. (x1 >= CD_ZERO .AND. x1 <= 60.0_wp) .OR. ABS(x1 - 1.0_wp) < 0.5_wp .OR. &
            ABS(x1 - REAL(NINT(x1), wp)) > 16.0_wp*EPSILON(CD_ONE)*MAX(CD_ONE, ABS(x1))) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION StreamOrder must be 0 (default) or an integer in [2, 60]'); RETURN
        END IF
        opts%stream_order = NINT(x1)
      END IF
    CASE ('nmodes', 'n_modes', 'modes')
      CALL rd(val, x1, ErrStat, ErrMsg)
      IF (ErrStat == 0) THEN
        IF (.NOT. (x1 >= CD_ZERO .AND. x1 <= 1000.0_wp) .OR. &
            ABS(x1 - REAL(NINT(x1), wp)) > 16.0_wp*EPSILON(CD_ONE)*MAX(CD_ONE, ABS(x1))) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION nModes must be an integer in [0, 1000]'); RETURN
        END IF
        opts%n_modes = NINT(x1)
      END IF
    CASE ('wavespreading', 'wave_spreading')
      CALL rd(val, opts%wave_spreading, ErrStat, ErrMsg)
      IF (ErrStat == 0 .AND. .NOT. (IEEE_IS_FINITE(opts%wave_spreading) .AND. opts%wave_spreading >= CD_ZERO &
                                    .AND. opts%wave_spreading <= 1000.0_wp)) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTION WaveSpreading must be in [0, 1000]'); RETURN
      END IF
    CASE ('wavecomponents', 'wave_components', 'wavedirections', 'wave_directions')
      CALL rd(val, x1, ErrStat, ErrMsg)
      IF (ErrStat == 0) THEN
        IF (.NOT. (x1 >= CD_ONE .AND. x1 <= 100000.0_wp) .OR. &
            ABS(x1 - REAL(NINT(x1), wp)) > 16.0_wp*EPSILON(CD_ONE)*MAX(CD_ONE, ABS(x1))) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION '//TRIM(kw)//' must be an integer in [1, 100000]'); RETURN
        END IF
        IF (to_lower(TRIM(kw)) == 'wavecomponents' .OR. to_lower(TRIM(kw)) == 'wave_components') THEN
          IF (NINT(x1) < 2) THEN
            CALL fail(ErrStat, ErrMsg, 'OPTION WaveComponents must be >= 2'); RETURN
          END IF
          opts%sea%n_freq = NINT(x1)
        ELSE
          opts%sea%n_dir = NINT(x1)
        END IF
      END IF
    CASE ('rangestart', 'range_start')
      CALL rd(val, opts%range_start, ErrStat, ErrMsg)
      opts%has_range_start = (ErrStat == 0)
    CASE ('waveseed', 'wave_seed')
      CALL rd(val, x1, ErrStat, ErrMsg)
      IF (ErrStat == 0) THEN
        IF (.NOT. (x1 >= CD_ONE .AND. x1 <= 2147483646.0_wp)) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION WaveSeed must be an integer in [1, 2147483646]'); RETURN
        END IF
        IF (ABS(x1 - REAL(NINT(x1), wp)) > 16.0_wp*EPSILON(CD_ONE)*MAX(CD_ONE, ABS(x1))) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION WaveSeed must be an integer'); RETURN
        END IF
        opts%wave_seed = NINT(x1)
      END IF
    CASE ('modified_newton', 'modifiednewton')
      CALL rd_bool(val, opts%dynamic_modified_newton, ErrStat, ErrMsg)
    CASE ('adaptive_mesh', 'adaptivemesh')
      CALL rd_bool(val, opts%adaptive_mesh, ErrStat, ErrMsg)
    CASE ('alpha_force_blend', 'alphaforceblend')
      CALL rd_bool(val, opts%alpha_force_blend, ErrStat, ErrMsg)
    CASE ('cable_statics', 'cablestatics')
      SELECT CASE (TRIM(to_lower(val)))
      CASE ('continuation')
        opts%cable_statics_sequenced = .FALSE.
      CASE ('sequenced')
        opts%cable_statics_sequenced = .TRUE.
      CASE DEFAULT
        CALL fail(ErrStat, ErrMsg, 'OPTION cable_statics "'//TRIM(val)//'" must be continuation or sequenced')
      END SELECT
    CASE ('cable_load_feedback', 'cableloadfeedback')
      CALL rd_bool(val, opts%cable_load_feedback, ErrStat, ErrMsg)
    CASE ('tensile_safety', 'tensilesafety')
      CALL rd_tensile_mode(val, opts%tensile_mode, ErrStat, ErrMsg)
    CASE ('tensile_strain_tolerance', 'tensilestraintolerance')
      CALL rd(val, opts%tensile_strain_tolerance, ErrStat, ErrMsg)
      IF (ErrStat == 0) THEN
        IF (.NOT. IEEE_IS_FINITE(opts%tensile_strain_tolerance) .OR. &
            opts%tensile_strain_tolerance < CD_ZERO) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION tensile_strain_tolerance must be finite and non-negative')
          RETURN
        END IF
      END IF
    CASE ('recovery_max_substeps', 'recoverymaxsubsteps')
      CALL rd(val, x1, ErrStat, ErrMsg)
      IF (ErrStat == 0) THEN
        IF (.NOT. IEEE_IS_FINITE(x1) .OR. x1 < 4.0_wp .OR. x1 > 65536.0_wp) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION recovery_max_substeps must be in [4,65536]'); RETURN
        END IF
        IF (ABS(x1 - REAL(NINT(x1), wp)) > 16.0_wp*EPSILON(CD_ONE)*MAX(CD_ONE, ABS(x1))) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION recovery_max_substeps must be an integer'); RETURN
        END IF
        opts%recovery_max_substeps = NINT(x1)
      END IF
    CASE ('axial_quadrature_order', 'axialquadratureorder', 'axial_quadrature')
      CALL rd(val, x1, ErrStat, ErrMsg)
      IF (ErrStat == 0) THEN
        ! range first: NINT of a value beyond INTEGER range is undefined
        IF (.NOT. (ABS(x1) <= 1.0e6_wp)) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION axial_quadrature_order must be an integer from 1 to 6'); RETURN
        END IF
        IF (ABS(x1 - REAL(NINT(x1), wp)) > 16.0_wp*EPSILON(CD_ONE)*MAX(CD_ONE, ABS(x1))) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION axial_quadrature_order must be an integer'); RETURN
        END IF
        opts%axial_quadrature_order = NINT(x1)
        IF (opts%axial_quadrature_order < 1 .OR. opts%axial_quadrature_order > 6) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION axial_quadrature_order must be an integer from 1 to 6'); RETURN
        END IF
      END IF
    CASE ('bending_quadrature_order', 'bendingquadratureorder', 'bending_quadrature')
      CALL rd(val, x1, ErrStat, ErrMsg)
      IF (ErrStat == 0) THEN
        ! range first: NINT of a value beyond INTEGER range is undefined
        IF (.NOT. (ABS(x1) <= 1.0e6_wp)) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION bending_quadrature_order must be an integer from 1 to 6'); RETURN
        END IF
        IF (ABS(x1 - REAL(NINT(x1), wp)) > 16.0_wp*EPSILON(CD_ONE)*MAX(CD_ONE, ABS(x1))) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION bending_quadrature_order must be an integer'); RETURN
        END IF
        opts%bending_quadrature_order = NINT(x1)
        IF (opts%bending_quadrature_order < 1 .OR. opts%bending_quadrature_order > 6) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION bending_quadrature_order must be an integer from 1 to 6'); RETURN
        END IF
      END IF
    CASE ('motionfile', 'vesselmotion', 'vesselrao')
      ! motionFile (point rows), vesselMotion (6-DOF vessel record) and vesselRAO (RAO
      ! table on the deck waves) are three sources of the same prescribed motion.
      SELECT CASE (to_lower(TRIM(kw)))
      CASE ('vesselmotion')
        i1 = MOTION_VESSEL_FILE
      CASE ('vesselrao')
        i1 = MOTION_VESSEL_RAO
      CASE DEFAULT
        i1 = MOTION_POINT_ROWS
      END SELECT
      dval = strip_quotes(val)
      IF (TRIM(dval) == '0' .OR. to_lower(TRIM(dval)) == 'none') THEN
        ! Match the WaterKin selector convention. LAST OPTION WINS so a template
        ! can disable an earlier prescribed-motion path for a static variant.
        IF (opts%motion_kind == i1 .OR. .NOT. opts%has_motion_file) THEN
          opts%motion_file = ''
          opts%has_motion_file = .FALSE.
          opts%motion_kind = MOTION_POINT_ROWS
        END IF
      ELSE
        IF (opts%has_motion_file .AND. opts%motion_kind /= i1) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTIONS motionFile, vesselMotion and vesselRAO are alternative '// &
                    'prescribed-motion sources; give only one'); RETURN
        END IF
        opts%motion_file = strip_quotes(val)
        opts%has_motion_file = .TRUE.
        opts%motion_kind = i1
      END IF
    CASE ('vesselref')
      BLOCK
        CHARACTER(CD_DECK_PATHLEN) :: parts(3)
        INTEGER :: np, k
        CALL split_bars(val, parts, np)
        IF (np /= 3) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION vesselRef must be x|y|z (the vessel reference point, m)'); RETURN
        END IF
        DO k = 1, 3
          CALL rd(parts(k), opts%vessel_ref(k), ErrStat, ErrMsg)
          IF (ErrStat /= 0) RETURN
          IF (.NOT. IEEE_IS_FINITE(opts%vessel_ref(k))) THEN
            CALL fail(ErrStat, ErrMsg, 'OPTION vesselRef must be finite'); RETURN
          END IF
        END DO
      END BLOCK
    CASE ('current')
      IF (to_lower(TRIM(val)) == 'none') THEN
        opts%has_current = .FALSE.
        opts%current_velocity = CD_ZERO
        opts%has_current_profile = .FALSE.
      ELSE
        CALL fail(ErrStat, ErrMsg, 'OPTION current supports "none current" or "uniform vx vy vz current"')
      END IF
    CASE ('waves', 'wave')
      IF (to_lower(TRIM(val)) == 'none') THEN
        opts%has_wave = .FALSE.
        opts%wave_height = CD_ZERO
        opts%wave_period = CD_ZERO
        opts%wave_direction = CD_ZERO
        opts%wave_gamma = CD_ONE
        opts%wave_kind = WAVE_NONE
      ELSE
        CALL fail(ErrStat, ErrMsg, 'OPTION waves forms: "none waves", "airy|stream|dean H T dir waves", '// &
                  '"jonswap Hs Tp gamma dir waves", or a spectral pm/torsethaugen row (doc/options.rst)')
      END IF
    CASE ('frictionmuaxial', 'frictionmu_axial', 'mu_axial', 'muaxial')
      CALL rd(val, opts%friction_mu_axial_row, ErrStat, ErrMsg)
    CASE ('frictionmulateral', 'frictionmu_lateral', 'mu_lateral', 'mulateral', 'frictionmunormal', &
          'frictionmu_normal')
      CALL rd(val, opts%friction_mu_lateral_row, ErrStat, ErrMsg)
    CASE ('frictionmu', 'mu', 'frictioncoefficient')
      IF (to_lower(TRIM(val)) == 'none') THEN
        opts%friction_mu = CD_ZERO
        opts%has_friction = .FALSE.
      ELSE
        CALL rd(val, opts%friction_mu, ErrStat, ErrMsg)
        opts%has_friction = (ErrStat == 0 .AND. opts%friction_mu > CD_ZERO)
      END IF
    CASE ('mu_kt', 'mu_ka')
      ! MoorDyn-F seabed friction coefficients: named, so a stock deck is pointed at the
      ! CableDyn keywords rather than failing as an unknown keyword
      CALL fail(ErrStat, ErrMsg, 'OPTION '//TRIM(kw)//' is the MoorDyn-F seabed friction coefficient; CableDyn '// &
                'reads frictionMu (with frictionMuLateral for mu_kT and frictionMuAxial for mu_kA)')
    CASE ('mc', 'cv', 'fricdamp', 'statdynfricscale')
      CALL fail(ErrStat, ErrMsg, 'OPTION '//TRIM(kw)//' (MoorDyn static-to-kinetic friction ratio or '// &
                'friction damping) has no CableDyn equivalent: CableDyn applies one regularised Coulomb '// &
                'friction set by frictionMu, frictionMuLateral and frictionMuAxial; remove the row')
    CASE ('tscheme')
      ! Stock MoorDyn time-integration scheme selector (a scheme NAME, e.g. RK2,
      ! RK4 -- a string, not a number). CableDyn marches with implicit
      ! generalised-alpha, so the explicit-scheme choice is inapplicable and the
      ! keyword is accepted (value ignored) so stock decks run unchanged.
      CONTINUE
    CASE ('dtic', 'tmaxic', 'cdscaleic', 'threshic')
      ! Stock MoorDyn dynamic-relaxation IC controls. CableDyn's initial condition
      ! is a true Newton static solve, so relaxation tuning has no meaning here;
      ! the keywords are accepted so stock decks run unchanged.
      CALL rd(val, x1, ErrStat, ErrMsg)
    CASE ('writelog')
      ! Stock MoorDyn log-verbosity switch; CableDyn reports through ErrStat/ErrMsg.
      CALL rd(val, x1, ErrStat, ErrMsg)
    CASE ('dtout')
      ! Stock MoorDyn output-file cadence; CableDyn's output cadence is governed by
      ! the caller (driver print interval / OpenFAST glue), not the deck.
      CALL rd(val, x1, ErrStat, ErrMsg)
    CASE ('wavekin', 'waterkin')
      ! Stock water/wave-kinematics selector: the MoorDyn-C "WaveKin" and the
      ! MoorDyn-F "WaterKin" both name where kinematics come from. "0"/"none" =
      ! still water; a value WITH LETTERS is the MoorDyn-F water-kinematics FILE
      ! (read after the parse, in the deck directory); any other numeric mode
      ! fails closed -- CableDyn decks declare waves via the "waves" option.
      ! Dequote FIRST, then classify: a quoted reserved value ("SEASTATE", "none")
      ! must hit its keyword branch, never the filename path.
      dval = strip_quotes(val)
      IF (to_lower(TRIM(dval)) == 'seastate') THEN
        ! Defer the coupled-only contract until the entry point has supplied its
        ! external_fluid capability. This lets stock MoorDyn-F decks containing
        ! `SEASTATE WaterKin` pass unchanged through the OpenFAST facade while the
        ! standalone entry points still reject them explicitly.
        opts%mdc_wave_kin = 0
        opts%waterkin_file = ''
        opts%has_waterkin_file = .FALSE.
        opts%waterkin_wave_mode = 2
        opts%waterkin_current_mode = 2
        opts%waterkin_seastate = .TRUE.
        opts%waterkin_host_wave = .TRUE.
        opts%waterkin_host_current = .TRUE.
      ELSE IF (SCAN(TRIM(dval), 'abcdfghijklmnopqrstuvwxyzABCDFGHIJKLMNOPQRSTUVWXYZ') > 0 .AND. &
               to_lower(TRIM(dval)) /= 'none') THEN
        opts%mdc_wave_kin = 0
        opts%waterkin_file = dval
        opts%has_waterkin_file = .TRUE.
        opts%waterkin_wave_mode = -1
        opts%waterkin_current_mode = -1
        opts%waterkin_seastate = .FALSE.
        opts%waterkin_host_wave = .FALSE.
        opts%waterkin_host_current = .FALSE.
      ELSE
        opts%mdc_wave_kin = 0
        IF (to_lower(TRIM(dval)) /= 'none') THEN
          CALL rd(dval, x1, ErrStat, ErrMsg)
          IF (ErrStat /= 0 .OR. .NOT. (ABS(x1 - ANINT(x1)) < 1.0e-9_wp .AND. x1 > -0.5_wp .AND. x1 < 7.5_wp)) THEN
            CALL fail(ErrStat, ErrMsg, TRIM(kw)//' '//TRIM(val)//' not supported (0/none for still water, '// &
                      'the MoorDyn-C modes 3 and 7, or a MoorDyn water-kinematics FILENAME; deck waves use '// &
                      'the "waves" option)')
            RETURN
          END IF
          SELECT CASE (NINT(x1))
          CASE (1)
            CALL fail(ErrStat, ErrMsg, TRIM(kw)//' 1 (kinematics set node by node through the MoorDyn-C API) '// &
                      'has no source in a standalone deck; use WaveKin 3 or 7, a WaterKin file, or a coupled '// &
                      'host field')
            RETURN
          CASE (2)
            CALL fail(ErrStat, ErrMsg, TRIM(kw)//' 2 (MoorDyn-C FFT_GRID: wave_frequencies.txt resampled to '// &
                      'an even spectrum and tabulated on water_grid.txt) is not supported; WaveKin 7 evaluates '// &
                      'the same file''s components exactly at every node')
            RETURN
          CASE (4, 5, 6)
            CALL fail(ErrStat, ErrMsg, TRIM(kw)//' '//TRIM(int_to_str(NINT(x1)))//' is not supported '// &
                      '(no kinematics source in MoorDyn-C v2.7.1); use WaveKin 3 or 7')
            RETURN
          CASE (3, 7)
            opts%mdc_wave_kin = NINT(x1)
          END SELECT
        END IF
        ! 0/none = still water, LAST OPTION WINS: clear any earlier filename row so
        ! a generated deck can be overridden/disabled like every other OPTION.
        opts%waterkin_file = ''
        opts%has_waterkin_file = .FALSE.
        opts%waterkin_wave_mode = -1
        opts%waterkin_current_mode = -1
        opts%waterkin_seastate = .FALSE.
        opts%waterkin_host_wave = .FALSE.
        opts%waterkin_host_current = .FALSE.
      END IF
    CASE ('currents')
      ! Stock MoorDyn-C switch selecting where current kinematics come from: 0 none, 1 the steady
      ! depth table current_profile.txt in the deck folder (read_moordyn_c_kinematics); the
      ! time-varying and gridded tables fail closed by name (CableDyn decks may also declare
      ! current via the "current" option)
      CALL rd(val, x1, ErrStat, ErrMsg)
      IF (ErrStat /= 0) RETURN
      opts%mdc_currents = 0
      IF (ABS(x1 - ANINT(x1)) > 1.0e-9_wp .OR. x1 < -0.5_wp .OR. x1 > 5.5_wp) THEN
        CALL fail(ErrStat, ErrMsg, 'Currents '//TRIM(val)//' not supported (0 none, or 1 for the MoorDyn-C '// &
                  'steady profile current_profile.txt)')
        RETURN
      END IF
      SELECT CASE (NINT(x1))
      CASE (1)
        opts%mdc_currents = 1
      CASE (2)
        CALL fail(ErrStat, ErrMsg, 'Currents 2 (the MoorDyn-C time-varying profile current_profile_dynamic.txt) '// &
                  'is not supported; use Currents 1 or the "current" option')
      CASE (3, 4)
        CALL fail(ErrStat, ErrMsg, 'Currents '//TRIM(int_to_str(NINT(x1)))//' is not supported '// &
                  '(no current source in MoorDyn-C v2.7.1); use Currents 1')
      CASE (5)
        CALL fail(ErrStat, ErrMsg, 'Currents 5 (the MoorDyn-C 4-D current grid current_profile_4d.txt) is not '// &
                  'supported; use Currents 1 or the "current" option')
      END SELECT
    CASE DEFAULT
      CALL fail(ErrStat, ErrMsg, 'unknown OPTION keyword "'//TRIM(kw)//'"')
    END SELECT
    IF (ErrStat == 0) CALL check_option_row_value(kw, val, ErrStat, ErrMsg)
  END SUBROUTINE apply_option

  SUBROUTINE check_option_row_value(kw, val, ErrStat, ErrMsg)
    !! Range rules for one scalar OPTIONS row. Every row is checked, including one a
    !! later row with the same keyword overrides, so an invalid value (NaN, a negative
    !! depth) never passes silently because it is shadowed. The effective values are
    !! checked again, together, in finalize_and_validate.
    CHARACTER(*), INTENT(IN) :: kw, val
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp) :: x
    LOGICAL :: ok
    CHARACTER(16) :: rule

    ErrStat = 0; ErrMsg = ''
    SELECT CASE (to_lower(TRIM(kw)))
    CASE ('g', 'gravity', 'rhow', 'wtrdnsty', 'water_density', 'wtrdpth', 'water_depth', 'dtm', 'dt', 'dtwave')
      rule = 'positive'
    CASE ('tmax', 'tensile_strain_tolerance', 'tensilestraintolerance', 'ramptime', 'ramp_time', 'tramp', &
          'maxstrain', 'max_strain', 'rangestart', 'range_start')
      rule = 'non-negative'
    CASE ('frictionmu', 'mu', 'frictioncoefficient')
      IF (to_lower(TRIM(val)) == 'none') RETURN
      rule = 'non-negative'
    CASE ('frictionmuaxial', 'frictionmu_axial', 'mu_axial', 'muaxial', 'frictionmulateral', 'frictionmu_lateral', &
          'mu_lateral', 'mulateral', 'frictionmunormal', 'frictionmu_normal')
      rule = 'non-negative'
    CASE ('rhoinf', 'rho_inf')
      rule = 'unit'
    CASE ('kbot', 'kb', 'cbot', 'cb', 'dtic', 'tmaxic', 'cdscaleic', 'threshic', 'writelog', 'dtout')
      rule = 'finite'
    CASE DEFAULT
      RETURN
    END SELECT
    CALL parse_real_token(val, x, ok)
    IF (.NOT. ok) RETURN   ! a non-numeric value was already rejected by the keyword's reader
    IF (.NOT. IEEE_IS_FINITE(x)) THEN
      CALL fail(ErrStat, ErrMsg, 'OPTION '//TRIM(kw)//' must be finite'); RETURN
    END IF
    SELECT CASE (TRIM(rule))
    CASE ('positive')
      IF (.NOT. (x > CD_ZERO)) CALL fail(ErrStat, ErrMsg, 'OPTION '//TRIM(kw)//' must be positive')
    CASE ('non-negative')
      IF (x < CD_ZERO) CALL fail(ErrStat, ErrMsg, 'OPTION '//TRIM(kw)//' must be >= 0')
    CASE ('unit')
      IF (x < CD_ZERO .OR. x > CD_ONE) CALL fail(ErrStat, ErrMsg, 'OPTION '//TRIM(kw)//' must lie in [0, 1]')
    END SELECT
  END SUBROUTINE check_option_row_value

  SUBROUTINE append_channel(line, channels, keys, nch, ErrStat, ErrMsg)
    !! One OUTPUTS row: channel names separated by whitespace or commas, optionally
    !! quoted (the OpenFAST OutList style "FairTen1, FairTen2" is accepted). A name
    !! longer than the channel-name buffer fails closed rather than being truncated
    !! onto a different channel.
    CHARACTER(*), INTENT(IN) :: line
    CHARACTER(NAMELEN), ALLOCATABLE, INTENT(INOUT) :: channels(:)
    !> Identity keys of channels(1:nch), kept alongside so each key is computed once.
    CHARACTER(2*NAMELEN), ALLOCATABLE, INTENT(INOUT) :: keys(:)
    INTEGER, INTENT(INOUT) :: nch
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    CHARACTER(LEN(line)) :: work
    CHARACTER(2*NAMELEN) :: key
    CHARACTER(2*NAMELEN), ALLOCATABLE :: grown(:)
    INTEGER :: i, lo, n
    ErrStat = 0; ErrMsg = ''
    work = line
    DO i = 1, LEN_TRIM(work)
      IF (work(i:i) == '"' .OR. work(i:i) == "'" .OR. work(i:i) == ',' .OR. work(i:i) == CHAR(9)) &
        work(i:i) = ' '
    END DO
    n = LEN_TRIM(work)
    i = 1
    DO WHILE (i <= n)
      IF (work(i:i) == ' ') THEN
        i = i + 1
        CYCLE
      END IF
      lo = i
      DO WHILE (i <= n)
        IF (work(i:i) == ' ') EXIT
        i = i + 1
      END DO
      IF (i - lo > NAMELEN) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUTS channel name "'//work(lo:i - 1)//'" is longer than '// &
                  TRIM(int_to_str(NAMELEN))//' characters')
        RETURN
      END IF
      ! Each channel is one .out column, so a channel requested twice (also through an
      ! alias spelling of the same quantity) would write duplicate columns.
      BLOCK
        INTEGER :: j
        key = channel_identity_key(work(lo:i - 1))
        DO j = 1, nch
          IF (keys(j) == key) THEN
            CALL fail(ErrStat, ErrMsg, 'OUTPUTS channel "'//work(lo:i - 1)//'" duplicates the earlier channel "'// &
                      TRIM(channels(j))//'" (each channel may be requested once)')
            RETURN
          END IF
        END DO
      END BLOCK
      CALL grow_channels(channels, nch)
      IF (.NOT. ALLOCATED(keys)) ALLOCATE (keys(0))
      IF (nch + 1 > SIZE(keys)) THEN
        ALLOCATE (grown(MAX(4, 2*SIZE(keys))))
        grown(1:nch) = keys(1:nch)
        CALL MOVE_ALLOC(grown, keys)
      END IF
      nch = nch + 1; channels(nch) = work(lo:i - 1); keys(nch) = key
    END DO
  END SUBROUTINE append_channel

  FUNCTION channel_identity_key(ch) RESULT(key)
    !! Canonical identity of an OUTPUTS channel, for duplicate detection: names compare
    !! case-insensitively, numeric ids by value (FairTen01 = FairTen1), and alias
    !! spellings of one quantity collapse (Con<P>p{x,y,z} = Point<P>p{x,y,z};
    !! FairAngle<L> = FairDecl<L>, AnchAngle<L> = AnchDecl<L>). Names outside the parsed
    !! families keep their lowercased spelling.
    CHARACTER(*), INTENT(IN) :: ch
    CHARACTER(2*NAMELEN) :: key
    CHARACTER(NAMELEN) :: lo
    INTEGER :: a, b, c, d

    lo = to_lower(ch)
    key = TRIM(lo)
    IF (starts_with(lo, 'fairten') .OR. starts_with(lo, 'anchten')) THEN
      a = int_suffix(ch, 8)
      IF (a > 0) key = lo(1:7)//':'//TRIM(int_to_str(a))
    ELSE IF (is_endpoint_angle_channel(lo)) THEN
      a = endpoint_angle_line_id(ch)
      IF (a <= 0) RETURN
      IF (starts_with(lo, 'fairincl') .OR. starts_with(lo, 'anchincl')) THEN
        key = lo(1:8)//':'//TRIM(int_to_str(a))
      ELSE
        key = lo(1:4)//'decl:'//TRIM(int_to_str(a))
      END IF
    ELSE IF (is_point_force_channel(lo)) THEN
      CALL parse_point_force_channel(ch, a, b)
      IF (a > 0 .AND. b > 0) key = 'pointf:'//TRIM(int_to_str(a))//':'//TRIM(int_to_str(b))
    ELSE IF (CD_Is_TDP_Channel(lo)) THEN
      CALL CD_Parse_TDP_Channel(ch, a, b)
      IF (a > 0 .AND. b > 0) key = 'tdp:'//TRIM(int_to_str(a))//':'//TRIM(int_to_str(b))
    ELSE IF (is_point_channel(lo)) THEN
      CALL parse_point_channel(ch, a, b)
      IF (a > 0 .AND. b > 0) key = 'point:'//TRIM(int_to_str(a))//':'//TRIM(int_to_str(b))
    ELSE IF (starts_with(lo, 'ten') .OR. starts_with(lo, 'curv') .OR. starts_with(lo, 'bendmom') .OR. &
             starts_with(lo, 'l') .OR. starts_with(lo, 'torq') .OR. starts_with(lo, 'twist')) THEN
      CALL parse_line_node_channel(ch, a, b, c, d)
      IF (a > 0 .AND. b > 0 .AND. c > 0) key = 'node:'//TRIM(int_to_str(a))//':'//TRIM(int_to_str(b))// &
                                               ':'//TRIM(int_to_str(c))//':'//TRIM(int_to_str(d))
    END IF
  END FUNCTION channel_identity_key

  SUBROUTINE normalize_turbine_points(points, allow_turbine, ErrStat, ErrMsg)
    !! FAST.Farm vocabulary (MoorDyn's): Turbine<J> / T<J> = a COUPLED point that rides
    !! turbine J. Normalized here -- BEFORE the stock endpoint-order pre-pass and every
    !! validation -- to 'coupled' + turbine_id, so every downstream coupled contract
    !! (endpoint swapping, bound-coupled map, moving set, transforms) is unchanged. The
    !! farm context itself (n_turbines, ref positions, J range) is validated at
    !! aggregate init.
    TYPE(DeckPoint), INTENT(INOUT) :: points(:)
    LOGICAL, INTENT(IN) :: allow_turbine
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i

    ErrStat = 0
    ErrMsg = ''
    DO i = 1, SIZE(points)
      IF (starts_with(TRIM(points(i)%ptype), 'turbine') .OR. &
          (LEN_TRIM(points(i)%ptype) >= 2 .AND. points(i)%ptype(1:1) == 't' .AND. &
           all_digits(TRIM(points(i)%ptype(2:))))) THEN
        IF (.NOT. allow_turbine) THEN
          ! Farm decks carry TURBINE-LOCAL coupled coordinates; only the CompMooring=5
          ! aggregate path supplies the farm context (n_turbines, turbine_ref_pos).
          ! Solving them through any other entry point would silently treat farm-local
          ! coordinates as global.
          CALL fail(ErrStat, ErrMsg, 'POINT type "'//TRIM(points(i)%ptype)//'": Turbine<J> points need '// &
                    'a TURBINES section in the standalone driver (or the CompMooring=5 aggregate)'); RETURN
        END IF
        IF (starts_with(TRIM(points(i)%ptype), 'turbine')) THEN
          points(i)%turbine_id = int_suffix(TRIM(points(i)%ptype), 8)
        ELSE
          points(i)%turbine_id = int_suffix(TRIM(points(i)%ptype), 2)
        END IF
        IF (points(i)%turbine_id < 1) THEN
          CALL fail(ErrStat, ErrMsg, 'POINT type "'//TRIM(points(i)%ptype)// &
                    '" must carry a positive turbine number (Turbine<J>)'); RETURN
        END IF
        IF (ABS(points(i)%mass) > CD_ZERO .OR. ABS(points(i)%vol) > CD_ZERO .OR. &
            ABS(points(i)%cda) > CD_ZERO .OR. ABS(points(i)%ca) > CD_ZERO) THEN
          CALL fail(ErrStat, ErrMsg, 'Turbine<J> POINT rows must not carry Mass/Vol/CdA/Ca '// &
                    'load columns (those apply to Connect/Free points)'); RETURN
        END IF
        points(i)%ptype = 'coupled'
      END IF
    END DO
  END SUBROUTINE normalize_turbine_points

  SUBROUTINE normalize_stock_endpoint_order(points, lines, sections)
    !! Stock MoorDyn decks write lines anchor (End A) -> fairlead (End B); the CableDyn
    !! deck convention is the reverse (End A = fairlead side, End B = anchor). When a
    !! line arrives in stock order -- NodeA a Fixed anchor, NodeB a Coupled/Vessel/
    !! Body<N> fairlead -- swap the endpoints and reverse that line's SECTIONS order
    !! (deck sections run End A -> End B), so both dialects resolve to the same internal
    !! anchor->fairlead model. Lines already in CableDyn order, lines touching a dynamic
    !! (Connect/Free) endpoint (the pair condition never matches them), and unresolved
    !! point ids are untouched. The normalization runs on dynamic-point decks too: their
    !! anchored Fixed<->Coupled legs carry the same stock-order convention (a clump-split
    !! farm deck's anchor legs would otherwise reach the builders reversed).
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckLine), INTENT(INOUT) :: lines(:)
    TYPE(DeckSection), INTENT(INOUT) :: sections(:)
    INTEGER :: i, ia, ib, tmp, mode_tmp
    REAL(wp) :: k_tmp, ez_tmp(3)
    CHARACTER(NAMELEN) :: ta, tb
    DO i = 1, SIZE(lines)
      ia = find_point(points, lines(i)%nodeA)
      ib = find_point(points, lines(i)%nodeB)
      IF (ia == 0 .OR. ib == 0) CYCLE ! undefined ids fail closed in validation
      ta = TRIM(points(ia)%ptype)
      tb = TRIM(points(ib)%ptype)
      ! Swap when NodeA is the Fixed (bottom) end and NodeB is an upper-side point:
      ! coupled/vessel/body (the platform fairlead) or Free/Connect (a clump/junction
      ! hanging above its anchor -- a stock anchor-to-clump leg must not build with the
      ! clump as the anchor). Mixed Free<->Coupled pairs are left as written: stock
      ! decks legitimately write shared-segment lines in either direction and neither
      ! end is an anchor. A Fixed NodeA placed ABOVE a Free/Connect NodeB is not a bottom
      ! anchor but an elevated hang-off (a weight suspended from overhead attachments):
      ! that line is already in CableDyn order (End A = upper end) and is left as written,
      ! so the internal anchor->fairlead model keeps its fairlead above its anchor. (Both
      ! positions are global there; Coupled/Vessel/Body points may be body-relative.)
      IF (TRIM(ta) == 'fixed' .AND. (TRIM(tb) == 'coupled' .OR. TRIM(tb) == 'vessel' .OR. &
                                     starts_with(TRIM(tb), 'body') .OR. &
                                     ((TRIM(tb) == 'free' .OR. TRIM(tb) == 'connect') .AND. &
                                      points(ia)%pos(3) <= points(ib)%pos(3)))) THEN
        tmp = lines(i)%nodeA
        lines(i)%nodeA = lines(i)%nodeB
        lines(i)%nodeB = tmp
        mode_tmp = lines(i)%endconn_mode(1)
        lines(i)%endconn_mode(1) = lines(i)%endconn_mode(2)
        lines(i)%endconn_mode(2) = mode_tmp
        k_tmp = lines(i)%endconn_k(1)
        lines(i)%endconn_k(1) = lines(i)%endconn_k(2)
        lines(i)%endconn_k(2) = k_tmp
        ez_tmp = lines(i)%endconn_ez_ref(:, 1)
        lines(i)%endconn_ez_ref(:, 1) = -lines(i)%endconn_ez_ref(:, 2)
        lines(i)%endconn_ez_ref(:, 2) = -ez_tmp
        ! torsion: the reference normals swap with their ends; a pretwist is a roll about Ez,
        ! which is reversed, so its sign flips (Phi = pretwist B - pretwist A is unchanged)
        mode_tmp = lines(i)%tors_mode(1)
        lines(i)%tors_mode(1) = lines(i)%tors_mode(2)
        lines(i)%tors_mode(2) = mode_tmp
        k_tmp = lines(i)%tors_k(1)
        lines(i)%tors_k(1) = lines(i)%tors_k(2)
        lines(i)%tors_k(2) = k_tmp
        ez_tmp = lines(i)%tors_nx(:, 1)
        lines(i)%tors_nx(:, 1) = lines(i)%tors_nx(:, 2)
        lines(i)%tors_nx(:, 2) = ez_tmp
        k_tmp = lines(i)%tors_pretwist(1)
        lines(i)%tors_pretwist(1) = -lines(i)%tors_pretwist(2)
        lines(i)%tors_pretwist(2) = -k_tmp
        ! attachment arcs are measured from End A, which is now the other end
        IF (ALLOCATED(lines(i)%att)) &
          lines(i)%att(1, :) = SUM(sections%length, MASK=sections%line_id == lines(i)%id) - lines(i)%att(1, :)
        CALL reverse_line_sections(sections, lines(i)%id)
      END IF
    END DO
  END SUBROUTINE normalize_stock_endpoint_order

  SUBROUTINE reverse_line_sections(sections, line_id)
    !! Reverse the in-deck order of the SECTIONS rows belonging to one line (their
    !! positions in the global array are kept; only the payloads swap).
    TYPE(DeckSection), INTENT(INOUT) :: sections(:)
    INTEGER, INTENT(IN) :: line_id
    INTEGER :: idxs(SIZE(sections)), n, i
    TYPE(DeckSection) :: tmp
    n = 0
    DO i = 1, SIZE(sections)
      IF (sections(i)%line_id == line_id) THEN
        n = n + 1
        idxs(n) = i
      END IF
    END DO
    DO i = 1, n/2
      tmp = sections(idxs(i))
      sections(idxs(i)) = sections(idxs(n + 1 - i))
      sections(idxs(n + 1 - i)) = tmp
    END DO
  END SUBROUTINE reverse_line_sections

  SUBROUTINE check_fixed_point_above_seabed(pt, z_floor, what, ErrStat, ErrMsg)
    !! A Fixed point (anchor) must sit on or above the seabed. A point below it pins the
    !! attached line inside the penalty seabed, which is not a physical configuration
    !! (MoorDyn v2 rejects an anchor below the water depth the same way). An anchor within
    !! the practical seabed tolerance max(1 mm, 1e-5 |z_floor|) of the seabed, above or
    !! below (tabulated depths, rounded deck coordinates), rests on the seabed: its z is set
    !! to the seabed elevation. Further below is rejected.
    TYPE(DeckPoint), INTENT(INOUT) :: pt
    REAL(wp), INTENT(IN) :: z_floor
    CHARACTER(*), INTENT(IN) :: what
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    CHARACTER(32) :: zs, fs, ts
    REAL(wp) :: tol

    ErrStat = 0; ErrMsg = ''
    tol = CD_Static_Anchor_Seabed_Tolerance(z_floor)
    ! (a relative round-off margin keeps an anchor written exactly one tolerance off inside)
    IF (ABS(pt%pos(3) - z_floor) <= tol*(CD_ONE + 1.0e-9_wp)) THEN
      pt%pos(3) = z_floor
      RETURN
    END IF
    IF (pt%pos(3) > z_floor) RETURN
    WRITE (zs, '(G0.8)') pt%pos(3)
    WRITE (fs, '(G0.8)') z_floor
    WRITE (ts, '(ES9.2)') tol
    CALL fail(ErrStat, ErrMsg, 'POINT '//TRIM(int_to_str(pt%id))//' (Fixed) lies below the seabed: z = '// &
              TRIM(ADJUSTL(zs))//' m is under '//what//' = '//TRIM(ADJUSTL(fs))// &
              ' m by more than the '//TRIM(ADJUSTL(ts))//' m seabed tolerance; place the anchor on (or above) '// &
              'the seabed')
  END SUBROUTINE check_fixed_point_above_seabed

  SUBROUTINE check_fixed_points_on_bathymetry(points, bathymetry, ErrStat, ErrMsg)
    !! Structured-seabed counterpart of the flat WtrDpth anchor check: every Fixed point
    !! must sit on or above the bathymetry surface interpolated at its (x, y) (within the
    !! seabed tolerance, where it is placed on the surface).
    TYPE(DeckPoint), INTENT(INOUT) :: points(:)
    TYPE(CD_BathymetryType), INTENT(IN) :: bathymetry
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: i, es
    REAL(wp) :: z_floor
    CHARACTER(160) :: em

    ErrStat = 0; ErrMsg = ''
    DO i = 1, SIZE(points)
      IF (TRIM(points(i)%ptype) /= 'fixed') CYCLE
      CALL CD_Bathymetry_Floor(bathymetry, points(i)%pos(1), points(i)%pos(2), z_floor, es, em)
      IF (es /= CD_BATHY_OK) CYCLE
      CALL check_fixed_point_above_seabed(points(i), z_floor, 'the bathymetry seabed at its (x, y), z', &
                                          ErrStat, ErrMsg)
      IF (ErrStat /= 0) RETURN
    END DO
  END SUBROUTINE check_fixed_points_on_bathymetry

  SUBROUTINE finalize_and_validate(types, bodies, rod_types, rods, points, lines, sections, opts, &
                                   channels, caller_driven, allow_static_finite_ei, ErrStat, ErrMsg, channel_lines)
    !! Cross-resolve names + ids, reject unimplemented features, validate visible ranges.
    !! caller_driven: the system is marched by an external host, so the deck's dtM/TMax
    !! pairing (a standalone-driver marching contract) is not required. A failure that
    !! concerns one deck row is reported with that row's deck line
    !! ("deck line N: <message>"); channel_lines(i) is the deck line of channels(i).
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckBody), INTENT(IN) :: bodies(:)
    TYPE(DeckRodType), INTENT(IN) :: rod_types(:)
    TYPE(DeckRod), INTENT(INOUT) :: rods(:)
    TYPE(DeckPoint), INTENT(INOUT) :: points(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckSection), INTENT(INOUT) :: sections(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    CHARACTER(NAMELEN), INTENT(IN) :: channels(:)
    LOGICAL, INTENT(IN) :: caller_driven
    LOGICAL, INTENT(IN) :: allow_static_finite_ei
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER, INTENT(IN) :: channel_lines(:)
    INTEGER :: at_line

    CALL finalize_checks(types, bodies, rod_types, rods, points, lines, sections, opts, channels, &
                         caller_driven, allow_static_finite_ei, ErrStat, ErrMsg, channel_lines, at_line)
    IF (ErrStat /= 0) CALL add_deck_line(at_line, ErrMsg)
  END SUBROUTINE finalize_and_validate

  SUBROUTINE finalize_checks(types, bodies, rod_types, rods, points, lines, sections, opts, &
                             channels, caller_driven, allow_static_finite_ei, ErrStat, ErrMsg, channel_lines, at_line)
    !! The checks of finalize_and_validate. at_line is the deck line of the row under
    !! check when a check fails (0 for deck-wide checks such as the OPTIONS rules).
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckBody), INTENT(IN) :: bodies(:)
    TYPE(DeckRodType), INTENT(IN) :: rod_types(:)
    TYPE(DeckRod), INTENT(INOUT) :: rods(:)
    TYPE(DeckPoint), INTENT(INOUT) :: points(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckSection), INTENT(INOUT) :: sections(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    CHARACTER(NAMELEN), INTENT(IN) :: channels(:)
    LOGICAL, INTENT(IN) :: caller_driven
    LOGICAL, INTENT(IN) :: allow_static_finite_ei
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER, INTENT(IN) :: channel_lines(:)
    INTEGER, INTENT(OUT) :: at_line
    INTEGER :: i, j, idx, nsec_for_line, body_id, body_idx, rod_id, rod_idx, na_ref, nb_ref
    INTEGER :: nstep
    LOGICAL :: grid_ok
    CHARACTER(NAMELEN) :: ta, tb
    ErrStat = 0; ErrMsg = ''
    at_line = 0

    ! RangeStart opens the window of the range graphs, which the LINES flag r requests.
    IF (opts%has_range_start) THEN
      IF (.NOT. ANY([(line_output_has_flag(lines(i)%outputs, 'r'), i=1, SIZE(lines))])) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTION RangeStart needs a line with the LINES Outputs flag r (range graph)')
        RETURN
      END IF
      IF (.NOT. opts%has_tmax) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTION RangeStart needs a dynamic deck (TMax)'); RETURN
      END IF
      IF (opts%range_start > opts%tmax) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTION RangeStart exceeds TMax: the range window would hold no output time')
        RETURN
      END IF
    END IF

    ! A deck of bodies and rods alone (no lines) is complete; otherwise lines need their tables.
    IF (.NOT. (SIZE(lines) == 0 .AND. (SIZE(rods) > 0 .OR. SIZE(bodies) > 0))) THEN
      IF (SIZE(types) < 1 .OR. SIZE(points) < 1 .OR. SIZE(lines) < 1 .OR. SIZE(sections) < 1) THEN
        CALL fail(ErrStat, ErrMsg, 'deck needs >=1 LINE TYPE, POINT, LINE, and SECTION (or only BODIES/RODS)')
        RETURN
      END IF
    END IF
    IF (.NOT. (IEEE_IS_FINITE(opts%g) .AND. opts%g > CD_ZERO) .OR. &
        .NOT. (IEEE_IS_FINITE(opts%rhoW) .AND. opts%rhoW > CD_ZERO)) THEN
      CALL fail(ErrStat, ErrMsg, 'OPTIONS g and rhoW must be finite and positive'); RETURN
    END IF
    ! Admissible magnitudes (driver_format.md "Admissible input ranges"): beyond these the
    ! solver's force and length scales overflow instead of failing to converge.
    IF (opts%g > MAX_GRAVITY .OR. opts%rhoW > MAX_WATER_DENSITY) THEN
      CALL fail(ErrStat, ErrMsg, 'OPTIONS g must be at most 1e3 m/s^2 and rhoW at most 1e5 kg/m^3'); RETURN
    END IF
    IF (opts%has_wtrdpth) THEN
      IF (IEEE_IS_FINITE(opts%wtrdpth)) THEN
        IF (opts%wtrdpth > MAX_COORDINATE) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION WtrDpth must be at most 1e6 m'); RETURN
        END IF
      END IF
    END IF
    IF (IEEE_IS_FINITE(opts%kbot) .AND. IEEE_IS_FINITE(opts%cbot)) THEN
      IF (ABS(opts%kbot) > MAX_COEFFICIENT .OR. ABS(opts%cbot) > MAX_COEFFICIENT) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTIONS kBot and cBot must be at most 1e15 in magnitude'); RETURN
      END IF
    END IF
    ! WtrDpth (flat penalty seabed) and bathymetryFile (structured variable seabed)
    ! are OPTIONAL alternatives: a deck without either solves the line suspended.
    IF (opts%has_wtrdpth .AND. opts%has_bathymetry_file) THEN
      CALL fail(ErrStat, ErrMsg, 'OPTIONS WtrDpth and bathymetryFile are mutually exclusive'); RETURN
    END IF
    IF (opts%has_wtrdpth) THEN
      IF (.NOT. (IEEE_IS_FINITE(opts%wtrdpth) .AND. opts%wtrdpth > CD_ZERO) .OR. &
          .NOT. (IEEE_IS_FINITE(opts%kbot) .AND. opts%kbot > CD_ZERO) .OR. &
          .NOT. (IEEE_IS_FINITE(opts%cbot) .AND. opts%cbot >= CD_ZERO)) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTIONS WtrDpth/kBot must be finite and positive; cBot finite and non-negative')
        RETURN
      END IF
      DO i = 1, SIZE(points)
        IF (TRIM(points(i)%ptype) /= 'fixed') CYCLE
        CALL check_fixed_point_above_seabed(points(i), -opts%wtrdpth, 'the flat seabed z = -WtrDpth', ErrStat, ErrMsg)
        IF (ErrStat /= 0) THEN
          at_line = points(i)%deck_line
          RETURN
        END IF
      END DO
    END IF
    IF (opts%has_bathymetry_file) THEN
      IF (LEN_TRIM(opts%bathymetry_file) == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTION bathymetryFile requires a non-empty path'); RETURN
      END IF
      IF (.NOT. (IEEE_IS_FINITE(opts%kbot) .AND. opts%kbot > CD_ZERO) .OR. &
          .NOT. (IEEE_IS_FINITE(opts%cbot) .AND. opts%cbot >= CD_ZERO)) THEN
        CALL fail(ErrStat, ErrMsg, &
                  'OPTIONS bathymetryFile/kBot requires finite positive kBot and finite non-negative cBot')
        RETURN
      END IF
    END IF
    IF (.NOT. caller_driven) THEN
      ! Standalone-driver marching contract; an externally marched (coupled) system
      ! takes its clock from the host, so a stock deck's lone dtM is acceptable there.
      IF (opts%has_dtm .NEQV. opts%has_tmax) THEN
        CALL fail(ErrStat, ErrMsg, 'dynamic run requires both dtM and TMax options'); RETURN
      END IF
    END IF
    IF (opts%has_dtm) THEN
      IF (.NOT. (IEEE_IS_FINITE(opts%dtM) .AND. opts%dtM > CD_ZERO)) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTIONS dtM must be positive and TMax must be non-negative'); RETURN
      END IF
    END IF
    IF (opts%has_tmax) THEN
      IF (.NOT. (IEEE_IS_FINITE(opts%tmax) .AND. opts%tmax >= CD_ZERO)) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTIONS dtM must be positive and TMax must be non-negative'); RETURN
      END IF
    END IF
    IF (opts%has_dtm .AND. opts%has_tmax) THEN
      CALL grid_step_count(opts%tmax, opts%dtM, nstep, grid_ok)
      IF (.NOT. grid_ok) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTIONS TMax/dtM needs more than '//TRIM(int_to_str(HUGE(1) - 1))// &
                  ' time steps; increase dtM or reduce TMax'); RETURN
      END IF
      IF (ABS(REAL(nstep, wp)*opts%dtM - opts%tmax) > 100.0_wp*EPSILON(CD_ONE)*MAX(CD_ONE, opts%tmax)) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTIONS TMax must be an integer multiple of dtM'); RETURN
      END IF
    END IF
    IF (opts%has_motion_file .AND. .NOT. opts%has_dtm) THEN
      CALL fail(ErrStat, ErrMsg, 'OPTION motionFile requires dtM and TMax'); RETURN
    END IF
    IF (opts%has_motion_file .AND. opts%motion_kind /= MOTION_POINT_ROWS) THEN
      IF (opts%n_turb > 0) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTIONS vesselMotion/vesselRAO do not apply to a TURBINES deck; '// &
                  'use its per-turbine motionFile records'); RETURN
      END IF
      IF (opts%motion_kind == MOTION_VESSEL_RAO .AND. .NOT. opts%has_wave) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTION vesselRAO needs deck waves (airy, a spectral sea, wave trains, '// &
                  'a WaterKin WaveKinMod 1 file or MoorDyn-C WaveKin 3/7)'); RETURN
      END IF
      IF (opts%motion_kind == MOTION_VESSEL_RAO .AND. opts%wave_kind == WAVE_STREAM) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTION vesselRAO needs linear deck waves; a nonlinear stream-function '// &
                  'wave has no linear components to apply RAOs to'); RETURN
      END IF
    END IF
    ! the spread sea synthesises WaveComponents x WaveDirections components: bound the product
    ! (each factor alone is bounded when its row is read)
    IF (INT(opts%sea%n_freq, int64)*INT(opts%sea%n_dir, int64) > 100000_int64) THEN
      CALL fail(ErrStat, ErrMsg, 'OPTIONS WaveComponents x WaveDirections must be at most 100000 '// &
                'wave components'); RETURN
    END IF
    IF (opts%has_current) THEN
      ! A caller-driven (coupled) deck takes its clock from the host, as for frictionMu.
      IF (.NOT. caller_driven .AND. .NOT. opts%has_dtm) THEN
        CALL fail(ErrStat, ErrMsg, 'standalone OPTION current requires dtM and TMax'); RETURN
      END IF
      IF (.NOT. ALL(IEEE_IS_FINITE(opts%current_velocity))) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTION current velocity must be finite'); RETURN
      END IF
      IF (ANY(ABS(opts%current_velocity) > MAX_FLUID_SPEED)) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTION current velocity components must be at most 1e3 m/s'); RETURN
      END IF
      IF (opts%has_current_profile) THEN
        IF (.NOT. ALLOCATED(opts%current_profile_z) .OR. .NOT. ALLOCATED(opts%current_profile_velocity)) THEN
          CALL fail(ErrStat, ErrMsg, 'current profile declared without profile data'); RETURN
        END IF
        IF (.NOT. (ALL(IEEE_IS_FINITE(opts%current_profile_z)) .AND. &
                   ALL(IEEE_IS_FINITE(opts%current_profile_velocity)))) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION current profile depths and velocities must be finite'); RETURN
        END IF
        ! every current source (the OPTION, a WaterKin table, current_profile.txt) lands here
        IF (ANY(ABS(opts%current_profile_z) > MAX_COORDINATE) .OR. &
            ANY(ABS(opts%current_profile_velocity) > MAX_FLUID_SPEED)) THEN
          CALL fail(ErrStat, ErrMsg, 'current profile depths must be at most 1e6 m and velocities at most '// &
                    '1e3 m/s in magnitude'); RETURN
        END IF
        BLOCK
          INTEGER :: iz
          DO iz = 1, SIZE(opts%current_profile_z) - 1
            IF (opts%current_profile_z(iz + 1) - opts%current_profile_z(iz) <= 100.0_wp*EPSILON(CD_ONE)) THEN
              CALL fail(ErrStat, ErrMsg, 'current profile depths must be strictly increasing'); RETURN
            END IF
          END DO
        END BLOCK
      END IF
    END IF
    IF (opts%has_wave) THEN
      IF (.NOT. opts%has_dtm) THEN
        CALL fail(ErrStat, ErrMsg, 'deck waves require dtM and TMax'); RETURN
      END IF
      IF (.NOT. opts%has_wtrdpth) THEN
        CALL fail(ErrStat, ErrMsg, 'deck waves require WtrDpth'); RETURN
      END IF
      IF (opts%wave_kind == WAVE_COMPONENTS) THEN
        IF (.NOT. (ALLOCATED(opts%wave_component_omega) .AND. &
                   ALLOCATED(opts%wave_component_amplitude) .AND. &
                   ALLOCATED(opts%wave_component_phase))) THEN
          CALL fail(ErrStat, ErrMsg, 'the wave-component table (WaterKin WaveKinMod 1 or WaveKin 3/7) is '// &
                    'missing'); RETURN
        END IF
        IF (.NOT. (ALL(IEEE_IS_FINITE(opts%wave_component_omega)) .AND. &
                   ALL(opts%wave_component_omega > CD_ZERO) .AND. &
                   ALL(IEEE_IS_FINITE(opts%wave_component_amplitude)) .AND. &
                   ALL(opts%wave_component_amplitude >= CD_ZERO) .AND. &
                   ALL(IEEE_IS_FINITE(opts%wave_component_phase)) .AND. &
                   IEEE_IS_FINITE(opts%wave_eta_mean) .AND. IEEE_IS_FINITE(opts%wave_direction))) THEN
          CALL fail(ErrStat, ErrMsg, 'the wave components (WaterKin WaveKinMod 1 or WaveKin 3/7) must be '// &
                    'finite'); RETURN
        END IF
        IF (ANY(opts%wave_component_amplitude > MAX_WAVE_HEIGHT) .OR. &
            ANY(opts%wave_component_omega > MAX_WAVE_OMEGA)) THEN
          CALL fail(ErrStat, ErrMsg, 'the wave components (WaterKin WaveKinMod 1 or WaveKin 3/7) need '// &
                    'amplitudes of at most 1e3 m and frequencies of at most 1e4 rad/s'); RETURN
        END IF
      ELSE
        IF (.NOT. (IEEE_IS_FINITE(opts%wave_height) .AND. opts%wave_height > CD_ZERO .AND. &
                   IEEE_IS_FINITE(opts%wave_period) .AND. opts%wave_period > CD_ZERO .AND. &
                   IEEE_IS_FINITE(opts%wave_gamma) .AND. opts%wave_gamma >= CD_ONE .AND. &
                   IEEE_IS_FINITE(opts%wave_direction))) THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION waves needs finite height/period/gamma/direction with positive size')
          RETURN
        END IF
        IF (opts%wave_kind /= WAVE_SEA) THEN
          IF (opts%wave_height > MAX_WAVE_HEIGHT .OR. opts%wave_period < MIN_WAVE_PERIOD .OR. &
              opts%wave_period > MAX_WAVE_PERIOD .OR. opts%wave_gamma > MAX_COEFFICIENT_SMALL) THEN
            CALL fail(ErrStat, ErrMsg, 'OPTION waves needs height <= 1e3 m, period in [0.1, 1e5] s and '// &
                      'gamma <= 1e3'); RETURN
          END IF
        END IF
      END IF
    END IF
    IF (.NOT. (IEEE_IS_FINITE(opts%friction_mu) .AND. opts%friction_mu >= CD_ZERO)) THEN
      CALL fail(ErrStat, ErrMsg, 'OPTION frictionMu must be finite and non-negative'); RETURN
    END IF
    IF (opts%has_friction) THEN
      IF (.NOT. caller_driven .AND. .NOT. opts%has_dtm) THEN
        CALL fail(ErrStat, ErrMsg, 'standalone OPTION frictionMu requires dtM and TMax'); RETURN
      END IF
      IF (.NOT. (opts%has_wtrdpth .OR. opts%has_bathymetry_file)) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTION frictionMu requires WtrDpth or bathymetryFile'); RETURN
      END IF
    END IF
    IF (.NOT. (IEEE_IS_FINITE(opts%rho_inf) .AND. opts%rho_inf >= CD_ZERO .AND. opts%rho_inf <= CD_ONE)) THEN
      CALL fail(ErrStat, ErrMsg, 'OPTIONS rhoInf must be finite and in [0, 1]'); RETURN
    END IF
    IF (opts%axial_quadrature_order < 1 .OR. opts%axial_quadrature_order > 6 .OR. &
        opts%bending_quadrature_order < 1 .OR. opts%bending_quadrature_order > 6) THEN
      CALL fail(ErrStat, ErrMsg, 'OPTIONS quadrature orders must lie in [1, 6]'); RETURN
    END IF
    IF (.NOT. (IEEE_IS_FINITE(opts%dynamic_rel_tol) .AND. opts%dynamic_rel_tol > CD_ZERO .AND. &
               IEEE_IS_FINITE(opts%dynamic_abs_tol) .AND. opts%dynamic_abs_tol > CD_ZERO)) THEN
      CALL fail(ErrStat, ErrMsg, 'OPTIONS dynamic_solver tolerances must be finite and positive'); RETURN
    END IF
    IF (opts%dynamic_max_iter < 1 .OR. opts%dynamic_backtracks < 0) THEN
      CALL fail(ErrStat, ErrMsg, 'OPTIONS dynamic_solver needs max_iter >= 1 and backtracks >= 0'); RETURN
    END IF
    ! line types: unique names (first-match lookup would otherwise silently bind a section
    ! to an earlier same-named row with different properties) + every accepted numeric
    ! property finite. A generated deck carrying NaN/Inf in a column must fail closed here,
    ! not propagate a non-finite Diam/Mass/EA into the net-buoyant gate (where NaN compares
    ! false and slips through) or the static solve. EI finiteness + sign is gated per-section.
    DO i = 1, SIZE(types)
      DO j = i + 1, SIZE(types)
        IF (to_lower(TRIM(types(i)%name)) == to_lower(TRIM(types(j)%name))) THEN
          at_line = types(j)%deck_line
          CALL fail(ErrStat, ErrMsg, 'duplicate LINE TYPE name "'//TRIM(types(i)%name)//'"'); RETURN
        END IF
      END DO
      at_line = types(i)%deck_line
      IF (.NOT. (IEEE_IS_FINITE(types(i)%diam) .AND. IEEE_IS_FINITE(types(i)%mass) .AND. &
                 IEEE_IS_FINITE(types(i)%ea) .AND. IEEE_IS_FINITE(types(i)%ba) .AND. &
                 IEEE_IS_FINITE(types(i)%gas) .AND. IEEE_IS_FINITE(types(i)%gj) .AND. &
                 IEEE_IS_FINITE(types(i)%i_rt) .AND. IEEE_IS_FINITE(types(i)%i_rn) .AND. &
                 IEEE_IS_FINITE(types(i)%cdn) .AND. IEEE_IS_FINITE(types(i)%cdt) .AND. &
                 IEEE_IS_FINITE(types(i)%can) .AND. IEEE_IS_FINITE(types(i)%cat))) THEN
        CALL fail(ErrStat, ErrMsg, 'LINE TYPE "'//TRIM(types(i)%name)// &
                  '" has a non-finite property (Diam/Mass/EA/BA/GAs/GJ/Irt/Irn/Cd/Ca)'); RETURN
      END IF
      ! Viscoelastic stiffness (ElasticMod > 1, the Es|Ed pipe syntax) is validated
      ! here, at the single choke point every entry passes through, and fails
      ! closed by name when its parameters are inconsistent.
      IF (types(i)%elastic_mod == 2) THEN
        ! MoorDyn's fatal battery, surfaced at parse time with the type name:
        ! the dynamic stiffness must exceed the static one (equality makes the
        ! series spring infinite)
        IF (.NOT. (IEEE_IS_FINITE(types(i)%ea_d) .AND. types(i)%ea_d > types(i)%ea)) THEN
          CALL fail(ErrStat, ErrMsg, 'LINE TYPE "'//TRIM(types(i)%name)//'": the viscoelastic dynamic '// &
                    'stiffness Ed (EA = Es|Ed) must be finite and exceed the static Es')
          RETURN
        END IF
      ELSE IF (types(i)%elastic_mod == 3) THEN
        ! load-dependent pair (EA = Es|alphaMBL|vbeta): both strictly positive;
        ! the EA_D-vs-Es premise is state-dependent and is validated by the
        ! model at the initial condition (and fails closed at any later state)
        IF (.NOT. (IEEE_IS_FINITE(types(i)%alpha_mbl) .AND. types(i)%alpha_mbl > CD_ZERO .AND. &
                   IEEE_IS_FINITE(types(i)%vbeta) .AND. types(i)%vbeta > CD_ZERO)) THEN
          CALL fail(ErrStat, ErrMsg, 'LINE TYPE "'//TRIM(types(i)%name)//'": the load-dependent '// &
                    'viscoelastic pair (EA = Es|alphaMBL|vbeta) must be finite and positive')
          RETURN
        END IF
      END IF
      IF (types(i)%elastic_mod > 1) THEN
        IF (.NOT. (IEEE_IS_FINITE(types(i)%ba_d) .AND. types(i)%ba_d >= CD_ZERO)) THEN
          CALL fail(ErrStat, ErrMsg, 'LINE TYPE "'//TRIM(types(i)%name)//'": the viscoelastic dynamic '// &
                    'damping Bd (BA = Bs|Bd) must be finite and non-negative')
          RETURN
        END IF
        ! Viscoelastic stiffness is a DYNAMIC EI=0 model feature. The finite-EI
        ! (bending) build path (build_finite_section_mesh -> the Hermite/Cosserat
        ! model) stores only the static Es and carries no standard-linear-solid
        ! state, so a viscoelastic finite-EI type would silently run on Es alone
        ! (dropping Ed/alphaMBL/vbeta/Bd); it fails closed instead. EI > 0 is the EXACT
        ! predicate the deck's finite-EI routing uses (line_is_finite_ei /
        ! deck_has_finite_ei), so this single choke --
        ! reached by every entry point through finalize_and_validate -- covers
        ! the standalone finite-EI paths and the OpenFAST aggregate's cables.
        IF (types(i)%ei > CD_ZERO) THEN
          CALL fail(ErrStat, ErrMsg, 'LINE TYPE "'//TRIM(types(i)%name)//'": viscoelastic stiffness '// &
                    '(ElasticMod > 1) is not supported on a finite-EI (bending) line type (EI > 0); '// &
                    'the finite-EI model does not carry the standard-linear-solid state')
          RETURN
        END IF
      END IF
      ! Syrope (SYROPE:<file>) on a finite-EI line has no bending build path;
      ! the EI=0 build (init_one_syrope_model) fails closed by name for the
      ! sub-cases it does not cover (hydro, composite).
      IF (types(i)%is_syrope .AND. types(i)%ei > CD_ZERO) THEN
        CALL fail(ErrStat, ErrMsg, 'LINE TYPE "'//TRIM(types(i)%name)//'": Syrope is not supported on '// &
                  'a finite-EI (bending) line type (EI > 0)'); RETURN
      END IF
      IF (MAXVAL(ABS([types(i)%gas, types(i)%gj, types(i)%i_rt, types(i)%i_rn])) > CD_ZERO) THEN
        IF (.NOT. (types(i)%gas > CD_ZERO .AND. types(i)%gj > CD_ZERO .AND. &
                   types(i)%i_rt > CD_ZERO .AND. types(i)%i_rn > CD_ZERO)) THEN
          CALL fail(ErrStat, ErrMsg, 'LINE TYPE "'//TRIM(types(i)%name)// &
                    '": explicit finite-EI GAs/GJ/Irt/Irn must all be > 0'); RETURN
        END IF
      END IF
    END DO

    ! bodies: Point3 translational bodies and Rigid6 bodies.
    DO i = 1, SIZE(bodies)
      at_line = bodies(i)%deck_line
      IF (bodies(i)%id < 1) THEN
        CALL fail(ErrStat, ErrMsg, 'BODY id must be >= 1'); RETURN
      END IF
      DO j = i + 1, SIZE(bodies)
        IF (bodies(i)%id == bodies(j)%id) THEN
          at_line = bodies(j)%deck_line
          CALL fail(ErrStat, ErrMsg, 'duplicate BODY id '//TRIM(int_to_str(bodies(i)%id))); RETURN
        END IF
      END DO
      IF (.NOT. (ALL(IEEE_IS_FINITE(bodies(i)%pos)) .AND. ALL(IEEE_IS_FINITE(bodies(i)%rot)) .AND. &
                 IEEE_IS_FINITE(bodies(i)%mass) .AND. IEEE_IS_FINITE(bodies(i)%vol) .AND. &
                 IEEE_IS_FINITE(bodies(i)%c33) .AND. IEEE_IS_FINITE(bodies(i)%c44) .AND. &
                 IEEE_IS_FINITE(bodies(i)%c55) .AND. IEEE_IS_FINITE(bodies(i)%cda) .AND. &
                 IEEE_IS_FINITE(bodies(i)%ca) .AND. ALL(IEEE_IS_FINITE(bodies(i)%inertia)))) THEN
        CALL fail(ErrStat, ErrMsg, 'BODY has non-finite data'); RETURN
      END IF
      IF (ANY(ABS(bodies(i)%pos) > MAX_COORDINATE) .OR. ANY(ABS(bodies(i)%cg) > MAX_COORDINATE) .OR. &
          MAXVAL(ABS([bodies(i)%mass, bodies(i)%vol, bodies(i)%c33, bodies(i)%c44, bodies(i)%c55, &
                      bodies(i)%cda, bodies(i)%inertia])) > MAX_COEFFICIENT .OR. &
          ABS(bodies(i)%ca) > MAX_COEFFICIENT_SMALL .OR. ANY(ABS(bodies(i)%rot) > MAX_COORDINATE)) THEN
        CALL fail(ErrStat, ErrMsg, 'BODY data outside the admissible range (coordinates and angles <= 1e6, '// &
                  'Mass/Vol/stiffness/CdA/inertia <= 1e15, Ca <= 1e3 in magnitude)'); RETURN
      END IF
      SELECT CASE (TRIM(bodies(i)%btype))
      CASE ('point3')
        IF (.NOT. opts%has_dtm .AND. .NOT. caller_driven) THEN
          CALL fail(ErrStat, ErrMsg, 'Point3 BODY requires a dynamic deck with dtM and TMax'); RETURN
        END IF
        IF (bodies(i)%mass <= CD_ZERO .OR. bodies(i)%vol < CD_ZERO .OR. &
            bodies(i)%cda < CD_ZERO .OR. bodies(i)%ca < CD_ZERO) THEN
          CALL fail(ErrStat, ErrMsg, 'Point3 BODY requires Mass > 0 and non-negative Vol/CdA/Ca'); RETURN
        END IF
      CASE ('rigid6')
        IF (.NOT. opts%has_dtm .AND. .NOT. caller_driven) THEN
          CALL fail(ErrStat, ErrMsg, 'Rigid6 BODY requires a dynamic deck with dtM and TMax'); RETURN
        END IF
        IF (bodies(i)%host_coupled) THEN
          IF (.NOT. (opts%has_motion_file .OR. opts%host_coupled_objects)) THEN
            CALL fail(ErrStat, ErrMsg, 'Coupled/Vessel BODY requires a motionFile (or a coupled host)'); RETURN
          END IF
          ! a platform-borne body may be a massless attachment frame
          IF (bodies(i)%mass < CD_ZERO .OR. bodies(i)%vol < CD_ZERO .OR. bodies(i)%cda < CD_ZERO .OR. &
              bodies(i)%ca < CD_ZERO .OR. ANY(bodies(i)%inertia < CD_ZERO)) THEN
            CALL fail(ErrStat, ErrMsg, 'Coupled/Vessel BODY requires non-negative Mass/Ixx/Iyy/Izz/Vol/CdA/Ca')
            RETURN
          END IF
          CYCLE
        END IF
        IF (bodies(i)%mass <= CD_ZERO .OR. bodies(i)%vol < CD_ZERO .OR. &
            bodies(i)%cda < CD_ZERO .OR. bodies(i)%ca < CD_ZERO .OR. ANY(bodies(i)%inertia <= CD_ZERO)) THEN
          CALL fail(ErrStat, ErrMsg, 'Rigid6 BODY requires Mass/Ixx/Iyy/Izz > 0 and non-negative Vol/CdA/Ca')
          RETURN
        END IF
      CASE DEFAULT
        CALL fail(ErrStat, ErrMsg, 'unknown BODY type "'//TRIM(bodies(i)%btype)//'"'); RETURN
      END SELECT
    END DO

    DO i = 1, SIZE(rod_types)
      DO j = i + 1, SIZE(rod_types)
        IF (to_lower(TRIM(rod_types(i)%name)) == to_lower(TRIM(rod_types(j)%name))) THEN
          at_line = rod_types(j)%deck_line
          CALL fail(ErrStat, ErrMsg, 'duplicate ROD TYPE name "'//TRIM(rod_types(i)%name)//'"')
          RETURN
        END IF
      END DO
      at_line = rod_types(i)%deck_line
      IF (.NOT. (IEEE_IS_FINITE(rod_types(i)%diam) .AND. rod_types(i)%diam > CD_ZERO .AND. &
                 IEEE_IS_FINITE(rod_types(i)%mass) .AND. rod_types(i)%mass > CD_ZERO .AND. &
                 IEEE_IS_FINITE(rod_types(i)%cdn) .AND. rod_types(i)%cdn >= CD_ZERO .AND. &
                 IEEE_IS_FINITE(rod_types(i)%can) .AND. rod_types(i)%can >= CD_ZERO .AND. &
                 IEEE_IS_FINITE(rod_types(i)%cdt) .AND. rod_types(i)%cdt >= CD_ZERO .AND. &
                 IEEE_IS_FINITE(rod_types(i)%cat) .AND. rod_types(i)%cat >= CD_ZERO .AND. &
                 IEEE_IS_FINITE(rod_types(i)%cdend) .AND. rod_types(i)%cdend >= CD_ZERO .AND. &
                 IEEE_IS_FINITE(rod_types(i)%caend) .AND. rod_types(i)%caend >= CD_ZERO)) THEN
        CALL fail(ErrStat, ErrMsg, 'ROD TYPE "'//TRIM(rod_types(i)%name)// &
                  '" requires finite Diam/Mass > 0 and non-negative Cd/Ca')
        RETURN
      END IF
    END DO
    DO i = 1, SIZE(rods)
      at_line = rods(i)%deck_line
      ! A caller-driven deck (the coupled aggregate) is marched by the host, so it needs no deck
      ! dtM/TMax for its rods -- same host-owns-the-march rule as the Free/Connect endpoint guard.
      IF (.NOT. (opts%has_dtm .OR. caller_driven)) THEN
        CALL fail(ErrStat, ErrMsg, 'RODS require a dynamic deck with dtM and TMax')
        RETURN
      END IF
      IF (rods(i)%id < 1) THEN
        CALL fail(ErrStat, ErrMsg, 'ROD id must be >= 1')
        RETURN
      END IF
      DO j = i + 1, SIZE(rods)
        IF (rods(i)%id == rods(j)%id) THEN
          at_line = rods(j)%deck_line
          CALL fail(ErrStat, ErrMsg, 'duplicate ROD id '//TRIM(int_to_str(rods(i)%id)))
          RETURN
        END IF
      END DO
      IF (starts_with(TRIM(rods(i)%rod_type), 'body')) THEN
        ! a rod fixed (Body<N>) or pinned (Body<N>Pinned) to a Rigid6 body: its end coordinates
        ! are in the body frame
        body_id = MAX(body_id_of_rod_type(rods(i)%rod_type), pinned_body_of_rod_type(rods(i)%rod_type))
        IF (body_id < 1) THEN
          CALL fail(ErrStat, ErrMsg, 'ROD attachment "'//TRIM(rods(i)%rod_type)//'" is not supported '// &
                    '(use Body<N> to fix the rod to a body or Body<N>Pinned to pin its End A to it)')
          RETURN
        END IF
        idx = find_body(bodies, body_id)
        IF (idx == 0) THEN
          CALL fail(ErrStat, ErrMsg, 'ROD attachment "'//TRIM(rods(i)%rod_type)//'" references an undefined BODY')
          RETURN
        END IF
        IF (TRIM(bodies(idx)%btype) /= 'rigid6') THEN
          CALL fail(ErrStat, ErrMsg, 'ROD attachment "'//TRIM(rods(i)%rod_type)//'": rods fix only to '// &
                    'Rigid6 (Free) bodies')
          RETURN
        END IF
      ELSE IF (TRIM(rods(i)%rod_type) /= 'free' .AND. TRIM(rods(i)%rod_type) /= 'fixed' .AND. &
               TRIM(rods(i)%rod_type) /= 'coupled' .AND. TRIM(rods(i)%rod_type) /= 'vessel' .AND. &
               TRIM(rods(i)%rod_type) /= 'pinned') THEN
        CALL fail(ErrStat, ErrMsg, 'ROD type "'//TRIM(rods(i)%rod_type)// &
                  '" is not supported (supported: Free, Fixed, Pinned, Coupled, Vessel, Body<N>, Body<N>Pinned)')
        RETURN
      END IF
      IF ((TRIM(rods(i)%rod_type) == 'coupled' .OR. TRIM(rods(i)%rod_type) == 'vessel') .AND. &
          .NOT. (opts%has_motion_file .OR. opts%host_coupled_objects)) THEN
        CALL fail(ErrStat, ErrMsg, 'Coupled/Vessel ROD requires a motionFile (or a coupled host)')
        RETURN
      END IF
      IF (.NOT. valid_rod_output_flags(rods(i)%outputs)) THEN
        CALL fail(ErrStat, ErrMsg, 'ROD Outputs "'//TRIM(rods(i)%outputs)// &
                  '": supported rod-output flag is p')
        RETURN
      END IF
      idx = find_rod_type(rod_types, rods(i)%rtype_name)
      IF (idx == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'ROD references unknown RodType "'//TRIM(rods(i)%rtype_name)//'"')
        RETURN
      END IF
      rods(i)%rtype = idx
      IF (.NOT. (ALL(IEEE_IS_FINITE(rods(i)%end_a)) .AND. ALL(IEEE_IS_FINITE(rods(i)%end_b)))) THEN
        CALL fail(ErrStat, ErrMsg, 'ROD endpoints must be finite')
        RETURN
      END IF
      IF (ANY(ABS(rods(i)%end_a) > MAX_COORDINATE) .OR. ANY(ABS(rods(i)%end_b) > MAX_COORDINATE)) THEN
        CALL fail(ErrStat, ErrMsg, 'ROD endpoint coordinates must be at most 1e6 m in magnitude')
        RETURN
      END IF
      IF (SQRT(SUM((rods(i)%end_b - rods(i)%end_a)**2)) <= 100.0_wp*EPSILON(CD_ONE)) THEN
        CALL fail(ErrStat, ErrMsg, 'ROD endpoints must define a positive length (a zero-length rod is '// &
                  'declared with NumSegs 0, as in MoorDyn)')
        RETURN
      END IF
      IF (rods(i)%nsegs < 1) THEN
        CALL fail(ErrStat, ErrMsg, 'ROD NumSegs must be >= 1')
        RETURN
      END IF
    END DO

    ! points: positive unique ids, supported types only
    DO i = 1, SIZE(points)
      at_line = points(i)%deck_line
      IF (points(i)%id < 1) THEN
        CALL fail(ErrStat, ErrMsg, 'POINT id must be >= 1'); RETURN
      END IF
      DO j = i + 1, SIZE(points)
        IF (points(i)%id == points(j)%id) THEN
          at_line = points(j)%deck_line
          CALL fail(ErrStat, ErrMsg, 'duplicate POINT id '//TRIM(int_to_str(points(i)%id))); RETURN
        END IF
      END DO
      ! Every accepted point number must be finite. A point requested ONLY through a
      ! Point<P>p{x,y,z} channel (not a line endpoint) never enters the solve, so a NaN/Inf
      ! position would otherwise be written to the .out with CD_DECKDRV_OK -- fail closed here.
      IF (.NOT. (ALL(IEEE_IS_FINITE(points(i)%pos)) .AND. IEEE_IS_FINITE(points(i)%mass) .AND. &
                 IEEE_IS_FINITE(points(i)%vol) .AND. IEEE_IS_FINITE(points(i)%cda) .AND. &
                 IEEE_IS_FINITE(points(i)%ca))) THEN
        CALL fail(ErrStat, ErrMsg, 'POINT has non-finite position or load data (X/Y/Z/Mass/Vol/CdA/Ca)'); RETURN
      END IF
      SELECT CASE (TRIM(points(i)%ptype))
      CASE ('fixed', 'coupled', 'vessel')
        ! Mass/Vol/CdA/Ca (clump weight, buoyancy, drag area, added mass) apply only to
        ! Connect/Free points; non-zero values on a held point would be silently ignored,
        ! so fail closed rather than solve as if they were zero.
        IF (ABS(points(i)%mass) > CD_ZERO .OR. ABS(points(i)%vol) > CD_ZERO .OR. &
            ABS(points(i)%cda) > CD_ZERO .OR. ABS(points(i)%ca) > CD_ZERO) THEN
          CALL fail(ErrStat, ErrMsg, 'POINT '//'(Fixed/Coupled/Vessel) must not carry '// &
                    'Mass/Vol/CdA/Ca load columns (those apply to Connect/Free points)'); RETURN
        END IF
      CASE ('connect', 'free')
        ! Dynamic points integrate with the lines, so a STANDALONE deck must declare its
        ! marching step. A caller-driven deck is marched by the host (which supplies dt
        ! at Init), so the requirement does not apply -- the same host-owns-the-march
        ! rule the dtM/TMax pairing above already follows.
        IF (.NOT. (opts%has_dtm .OR. caller_driven)) THEN
          CALL fail(ErrStat, ErrMsg, 'POINT type "'//TRIM(points(i)%ptype)// &
                    '" requires dtM and TMax'); RETURN
        END IF
        ! Non-negative, not strictly positive: MoorDyn decks carry Mass=0 Connect
        ! junction points (mid-line splits) -- the dynamic point step advances them on
        ! the attached lines' end-node consistent-mass diagonal share, treated
        ! implicitly, so a massless bound point integrates stably. The system step
        ! fails closed if the TOTAL (point + attached end-node) mass is not positive.
        IF (.NOT. (points(i)%mass >= CD_ZERO)) THEN
          CALL fail(ErrStat, ErrMsg, 'POINT type "'//TRIM(points(i)%ptype)//'" requires Mass >= 0'); RETURN
        END IF
        IF (points(i)%vol < CD_ZERO .OR. points(i)%cda < CD_ZERO .OR. points(i)%ca < CD_ZERO) THEN
          CALL fail(ErrStat, ErrMsg, 'POINT type "'//TRIM(points(i)%ptype)// &
                    '" requires non-negative Vol/CdA/Ca'); RETURN
        END IF
      CASE DEFAULT
        IF (starts_with(TRIM(points(i)%ptype), 'body')) THEN
          body_id = int_suffix(TRIM(points(i)%ptype), 5)
          body_idx = find_body(bodies, body_id)
          IF (body_id < 1 .OR. body_idx == 0) THEN
            CALL fail(ErrStat, ErrMsg, 'POINT type "'//TRIM(points(i)%ptype)//'" references an undefined BODY')
            RETURN
          END IF
          IF (TRIM(bodies(body_idx)%btype) == 'point3' .AND. count_body_point_refs(points, body_id) /= 1) THEN
            CALL fail(ErrStat, ErrMsg, 'Point3 BODY currently supports exactly one Body<N> attachment point')
            RETURN
          END IF
          IF (ABS(points(i)%mass) > CD_ZERO .OR. ABS(points(i)%vol) > CD_ZERO .OR. &
              ABS(points(i)%cda) > CD_ZERO .OR. ABS(points(i)%ca) > CD_ZERO) THEN
            CALL fail(ErrStat, ErrMsg, 'Body<N> POINT rows use BODY Mass/Vol/CdA/Ca, not point load columns')
            RETURN
          END IF
          points(i)%body_id = body_id
          points(i)%body_offset = points(i)%pos
          points(i)%pos = bodies(body_idx)%pos + MATMUL(CD_Body_Rotation(bodies(body_idx)%rot(1), &
                                                                         bodies(body_idx)%rot(2), &
                                                                         bodies(body_idx)%rot(3)), &
                                                        points(i)%body_offset)
          points(i)%mass = bodies(body_idx)%mass
          points(i)%vol = bodies(body_idx)%vol
          points(i)%cda = bodies(body_idx)%cda
          points(i)%ca = bodies(body_idx)%ca
          CYCLE
        ELSE IF (is_rod_point_type(points(i)%ptype)) THEN
          CALL parse_rod_point_type(points(i)%ptype, rod_id, idx)
          rod_idx = find_rod(rods, rod_id)
          IF (rod_idx == 0) THEN
            CALL fail(ErrStat, ErrMsg, 'POINT type "'//TRIM(points(i)%ptype)//'" references an undefined ROD')
            RETURN
          END IF
          IF (ABS(points(i)%mass) > CD_ZERO .OR. ABS(points(i)%vol) > CD_ZERO .OR. &
              ABS(points(i)%cda) > CD_ZERO .OR. ABS(points(i)%ca) > CD_ZERO) THEN
            CALL fail(ErrStat, ErrMsg, 'Rod<N>A/B POINT rows use ROD TYPE properties, not point load columns')
            RETURN
          END IF
          points(i)%body_id = rod_id
          IF (idx == 1) THEN
            points(i)%pos = rods(rod_idx)%end_a
          ELSE
            points(i)%pos = rods(rod_idx)%end_b
          END IF
          ! a rod pinned to a body has its ends in the body frame: the end point starts at the
          ! body's deck pose
          body_idx = find_body(bodies, pinned_body_of_rod_type(rods(rod_idx)%rod_type))
          IF (body_idx > 0) THEN
            points(i)%body_offset = points(i)%pos
            points(i)%pos = bodies(body_idx)%pos + MATMUL(CD_Body_Rotation(bodies(body_idx)%rot(1), &
                                                                           bodies(body_idx)%rot(2), &
                                                                           bodies(body_idx)%rot(3)), &
                                                          points(i)%body_offset)
          END IF
          points(i)%mass = 0.5_wp*rod_types(rods(rod_idx)%rtype)%mass* &
                           SQRT(SUM((rods(rod_idx)%end_b - rods(rod_idx)%end_a)**2))
          points(i)%vol = CD_ZERO
          points(i)%cda = CD_ZERO
          points(i)%ca = CD_ZERO
          CYCLE
        END IF
        CALL fail(ErrStat, ErrMsg, 'unknown POINT type "'//TRIM(points(i)%ptype)//'"'); RETURN
      END SELECT
    END DO
    DO i = 1, SIZE(rods)
      at_line = rods(i)%deck_line
      na_ref = count_rod_point_refs(points, rods(i)%id, 1)
      nb_ref = count_rod_point_refs(points, rods(i)%id, 2)
      IF (na_ref > 1 .OR. nb_ref > 1) THEN
        CALL fail(ErrStat, ErrMsg, 'a ROD may have at most one Rod<N>A point and one Rod<N>B point')
        RETURN
      END IF
    END DO

    ! lines: positive unique ids, endpoints resolve, >=1 section, known output flags
    DO i = 1, SIZE(lines)
      at_line = lines(i)%deck_line
      IF (lines(i)%id < 1) THEN
        CALL fail(ErrStat, ErrMsg, 'LINE id must be >= 1'); RETURN
      END IF
      DO j = i + 1, SIZE(lines)
        IF (lines(i)%id == lines(j)%id) THEN
          at_line = lines(j)%deck_line
          CALL fail(ErrStat, ErrMsg, 'duplicate LINE id '//TRIM(int_to_str(lines(i)%id))); RETURN
        END IF
      END DO
      IF (.NOT. valid_line_output_flags(lines(i)%outputs)) THEN
        CALL fail(ErrStat, ErrMsg, 'LINE Outputs "'//TRIM(lines(i)%outputs)// &
                  '": supported line-output flags are p, t and r'); RETURN
      END IF
      IF (find_point(points, lines(i)%nodeA) == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'LINE '//TRIM(int_to_str(lines(i)%id))//' references undefined POINT id '// &
                  TRIM(int_to_str(lines(i)%nodeA))); RETURN
      END IF
      IF (find_point(points, lines(i)%nodeB) == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'LINE '//TRIM(int_to_str(lines(i)%id))//' references undefined POINT id '// &
                  TRIM(int_to_str(lines(i)%nodeB))); RETURN
      END IF
      IF (lines(i)%nodeA == lines(i)%nodeB) THEN
        CALL fail(ErrStat, ErrMsg, 'LINE NodeA and NodeB must differ'); RETURN
      END IF
      ! Deck convention follows OrcaFlex: End A (NodeA) is the fairlead/top end,
      ! End B (NodeB) is the anchor/bottom end. Internally the catenary/model
      ! still stores anchor -> fairlead, so deck adapters reverse the endpoint map.
      ta = TRIM(points(find_point(points, lines(i)%nodeA))%ptype)
      tb = TRIM(points(find_point(points, lines(i)%nodeB))%ptype)
      IF (deck_has_dynamic_points(points)) THEN
        ! Same host-owns-the-march rule as the POINT-level guard: a caller-driven deck
        ! is marched by the host, so it needs no deck dtM for its dynamic points.
        IF (.NOT. (opts%has_dtm .OR. caller_driven)) THEN
          CALL fail(ErrStat, ErrMsg, 'Connect/Free line endpoints require a dynamic deck with dtM and TMax')
          RETURN
        END IF
        IF (.NOT. endpoint_type_supported_dynamic(ta)) THEN
          CALL fail(ErrStat, ErrMsg, 'dynamic line endpoints must be Fixed/Coupled/Vessel/Connect/Free/'// &
                    'Body<N>/Rod<N>A/B')
          RETURN
        END IF
        IF (.NOT. endpoint_type_supported_dynamic(tb)) THEN
          CALL fail(ErrStat, ErrMsg, 'dynamic line endpoints must be Fixed/Coupled/Vessel/Connect/Free/'// &
                    'Body<N>/Rod<N>A/B')
          RETURN
        END IF
      ELSE
        IF (ta /= 'coupled' .AND. ta /= 'vessel' .AND. .NOT. starts_with(ta, 'body')) THEN
          CALL fail(ErrStat, ErrMsg, 'LINE End A (NodeA) must be Coupled/Vessel/Body<N> fairlead-side point')
          RETURN
        END IF
        IF (tb /= 'fixed') THEN
          ! FAST.Farm SHARED line: both ends coupled is legal iff BOTH endpoints carry
          ! the Turbine<J> vocabulary (the fairlead-to-fairlead line between turbines);
          ! any other non-anchor End B stays rejected.
          IF (.NOT. ((tb == 'coupled' .OR. tb == 'vessel') .AND. &
                     points(find_point(points, lines(i)%nodeA))%turbine_id > 0 .AND. &
                     points(find_point(points, lines(i)%nodeB))%turbine_id > 0)) THEN
            CALL fail(ErrStat, ErrMsg, 'LINE End B (NodeB) must be a Fixed (anchor) point '// &
                      '(exception: a FAST.Farm shared line between two Turbine<J> fairleads)'); RETURN
          END IF
        ELSE
          IF (points(find_point(points, lines(i)%nodeA))%pos(3) < &
              points(find_point(points, lines(i)%nodeB))%pos(3)) THEN
            CALL fail(ErrStat, ErrMsg, 'LINE End A fairlead (NodeA) must not be below End B anchor (NodeB)'); RETURN
          END IF
        END IF
      END IF
      nsec_for_line = 0
      DO j = 1, SIZE(sections)
        IF (sections(j)%line_id == lines(i)%id) nsec_for_line = nsec_for_line + 1
      END DO
      IF (nsec_for_line < 1) THEN
        CALL fail(ErrStat, ErrMsg, 'LINE '//TRIM(int_to_str(lines(i)%id))//' has no SECTIONS'); RETURN
      END IF
      IF (lines(i)%stock_row .AND. nsec_for_line > 1) THEN
        CALL fail(ErrStat, ErrMsg, 'LINE '//TRIM(int_to_str(lines(i)%id))//' is defined by a 7-column '// &
                  'LINES row (LineType, UnstrLen, NumSegs) and also has SECTIONS rows; describe the line '// &
                  'either with the 7-column row or with a 3/4-column LINES row plus SECTIONS rows'); RETURN
      END IF
    END DO

    ! sections: owning line exists, line type resolves (+ EI=0), ranges
    DO j = 1, SIZE(sections)
      at_line = sections(j)%deck_line
      IF (find_line(lines, sections(j)%line_id) == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'SECTION references undefined LINE id '// &
                  TRIM(int_to_str(sections(j)%line_id))); RETURN
      END IF
      idx = find_type(types, sections(j)%ltype_name)
      IF (idx == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'SECTION references unknown LineType "'// &
                  TRIM(sections(j)%ltype_name)//'"'); RETURN
      END IF
      sections(j)%ltype = idx
      ! EI gate: EI=0 reaches the positions-only cable path. EI>0 needs dynamics; a standalone
      ! deck supplies that through dtM/TMax, but a CALLER-DRIVEN (host-coupled) deck gets its
      ! timestep from the coupling step, so it does not need dtM -- the coupled cable marches at
      ! the caller's dt (CD_Init_Deck_HermiteCable / the aggregator). Only the standalone finite-EI
      ! run still requires dtM here.
      IF (.NOT. IEEE_IS_FINITE(types(idx)%ei)) THEN
        CALL fail(ErrStat, ErrMsg, 'LINE TYPE "'//TRIM(types(idx)%name)//'": EI must be finite'); RETURN
      ELSE IF (types(idx)%ei > CD_ZERO .AND. .NOT. opts%has_dtm .AND. .NOT. caller_driven .AND. &
               .NOT. (allow_static_finite_ei .AND. .NOT. opts%has_tmax)) THEN
        CALL fail(ErrStat, ErrMsg, 'finite-EI section (EI>0) requires a dynamic deck with dtM and TMax'); RETURN
      ELSE IF (types(idx)%ei < CD_ZERO) THEN
        CALL fail(ErrStat, ErrMsg, 'LINE TYPE "'//TRIM(types(idx)%name)//'": EI must be >= 0'); RETURN
      END IF
      IF (sections(j)%nsegs < 1 .OR. sections(j)%nsegs > 1000000 &
          .OR. .NOT. (IEEE_IS_FINITE(sections(j)%length) .AND. sections(j)%length > CD_ZERO)) THEN
        CALL fail(ErrStat, ErrMsg, 'SECTION needs 1 <= NumSegs <= 1e6 and a positive Length'); RETURN
      END IF
      ! Admissible magnitudes: beyond these the solver's force and length scales overflow or
      ! lose every significant digit (a 1e300 m section squares to Inf in the element strain).
      IF (sections(j)%length > 1.0e6_wp .OR. sections(j)%length/REAL(sections(j)%nsegs, wp) < 1.0e-6_wp) THEN
        CALL fail(ErrStat, ErrMsg, 'SECTION Length must be at most 1e6 m with segments of at least 1e-6 m'); RETURN
      END IF
      IF (types(idx)%ea > 1.0e15_wp .OR. ABS(types(idx)%mass) > 1.0e6_wp .OR. types(idx)%diam > 1.0e3_wp) THEN
        CALL fail(ErrStat, ErrMsg, 'LINE TYPE "'//TRIM(types(idx)%name)//'": outside the admissible range '// &
                  '(EA <= 1e15 N, |mass| <= 1e6 kg/m, Diam <= 1e3 m)'); RETURN
      END IF
      ! lower bounds (a positive EA or Diam this small overflows the stretch and drag scales)
      ! and the remaining stiffness, damping and hydrodynamic coefficients
      IF ((types(idx)%ea > CD_ZERO .AND. types(idx)%ea < MIN_EA) .OR. &
          (types(idx)%diam > CD_ZERO .AND. types(idx)%diam < MIN_DIAMETER) .OR. &
          types(idx)%ei > MAX_COEFFICIENT .OR. ABS(types(idx)%ba) > MAX_COEFFICIENT .OR. &
          MAX(types(idx)%cdn, types(idx)%cdt, types(idx)%can, types(idx)%cat) > MAX_COEFFICIENT_SMALL) THEN
        CALL fail(ErrStat, ErrMsg, 'LINE TYPE "'//TRIM(types(idx)%name)//'": outside the admissible range '// &
                  '(EA >= 1e-3 N, Diam >= 1e-6 m, EI and |BA| <= 1e15, Cd and Ca <= 1e3)'); RETURN
      END IF
      ! Diam/EA feed the cable mesh and the axial-stiffness solve; a non-positive value
      ! builds a degenerate element or a singular tangent. Finiteness is already gated at the
      ! LINE TYPE loop; here (where the type is actually used) require both strictly positive.
      IF (.NOT. (types(idx)%diam > CD_ZERO) .OR. .NOT. (types(idx)%ea > CD_ZERO)) THEN
        CALL fail(ErrStat, ErrMsg, 'LINE TYPE "'//TRIM(types(idx)%name)// &
                  '": Diam and EA must be > 0'); RETURN
      END IF
      ! Net-buoyant gate: EI=0 decks cannot build a lazy-wave arch. The finite-EI
      ! route has the cubic-Hermite arch seed and may proceed. A dynamic standalone
      ! run gets its clock from dtM; the executable's metadata scan also admits a
      ! clock-free static aggregate solve. Unsupported endpoint coupling is rejected
      ! before initialization.
      IF (types(idx)%mass <= opts%rhoW*QUARTER_PI*types(idx)%diam**2) THEN
        IF (types(idx)%ei <= CD_ZERO .OR. &
            (.NOT. opts%has_dtm .AND. .NOT. caller_driven .AND. &
             .NOT. (allow_static_finite_ei .AND. .NOT. opts%has_tmax))) THEN
          CALL fail(ErrStat, ErrMsg, 'LINE TYPE "'//TRIM(types(idx)%name)// &
                    '" is net-buoyant (dry mass <= displaced water mass): buoyant / lazy-wave '// &
                    'sections require a dynamic finite-EI deck'); RETURN
        END IF
      END IF
    END DO

    ! ATTACHMENTS: discrete clumps/buoyancy modules on a finite-EI line
    DO j = 1, SIZE(lines)
      IF (.NOT. ALLOCATED(lines(j)%att)) CYCLE
      at_line = lines(j)%deck_line
      IF (.NOT. line_is_finite_ei(lines(j), types, sections)) THEN
        CALL fail(ErrStat, ErrMsg, 'ATTACHMENTS name line '//TRIM(int_to_str(lines(j)%id))// &
                  ', which is not a finite-EI line; on an EI = 0 line use a Point at a line end'); RETURN
      END IF
      ! (a stock-order line measures from its anchor; an arc beyond it turns negative here)
      IF (MAXVAL(lines(j)%att(1, :)) > SUM(sections%length, MASK=sections%line_id == lines(j)%id)* &
          (CD_ONE + 1.0e-12_wp) + 1.0e-9_wp .OR. MINVAL(lines(j)%att(1, :)) < -1.0e-9_wp) THEN
        CALL fail(ErrStat, ErrMsg, 'ATTACHMENTS ArcLength lies beyond the end of line '// &
                  TRIM(int_to_str(lines(j)%id))); RETURN
      END IF
    END DO

    DO i = 1, SIZE(lines)
      at_line = lines(i)%deck_line
      IF (ANY(lines(i)%tors_mode /= TORS_FREE)) THEN
        CALL check_torsion_line(lines(i), ErrStat, ErrMsg)
        IF (ErrStat /= 0) RETURN
      END IF
      IF (.NOT. ANY(lines(i)%endconn_mode /= CD_ENDCONN_PINNED)) CYCLE
      IF (.NOT. line_is_finite_ei(lines(i), types, sections)) THEN
        CALL fail(ErrStat, ErrMsg, 'END CONNECTIONS requires a finite-EI line')
        RETURN
      END IF
      ! The production Hermite boundary supports a moving End A and a held End B.
      ! The two-moving-end route does not assemble bending
      ! connection forces or moments. Reject that topology at the common parser
      ! boundary so no entry point can silently reinterpret a declared connection
      ! as pinned, while retaining finite/rigid connections at either end of every
      ! supported Fixed-End-B cable.
      j = find_point(points, lines(i)%nodeB)
      IF (j < 1 .OR. TRIM(points(j)%ptype) /= 'fixed') THEN
        CALL fail(ErrStat, ErrMsg, 'non-pinned END CONNECTIONS require a finite-EI line with Fixed End B; '// &
                  'the two-moving-end compatibility solver does not apply bending connections')
        RETURN
      END IF
    END DO

    ! A history row is meaningful only for a line whose constitutive type is
    ! Syrope. The current production surface is single-section, so this also
    ! prevents an IC from being silently attached to a plain/composite line.
    DO i = 1, SIZE(lines)
      at_line = lines(i)%deck_line
      IF (.NOT. lines(i)%has_syrope_ic) CYCLE
      nsec_for_line = 0
      idx = 0
      DO j = 1, SIZE(sections)
        IF (sections(j)%line_id /= lines(i)%id) CYCLE
        nsec_for_line = nsec_for_line + 1
        IF (types(sections(j)%ltype)%is_syrope) idx = idx + 1
      END DO
      IF (nsec_for_line /= 1 .OR. idx /= 1) THEN
        CALL fail(ErrStat, ErrMsg, 'SYROPE IC can reference only a single-section Syrope LINE')
        RETURN
      END IF
    END DO

    DO i = 1, SIZE(channels)
      at_line = 0
      IF (i <= SIZE(channel_lines)) at_line = channel_lines(i)
      CALL check_channel(channels(i), lines, points, sections, ErrStat, ErrMsg, bodies, rods, opts%zl_rod)
      IF (ErrStat /= 0) RETURN
    END DO
    at_line = 0

  CONTAINS

    SUBROUTINE check_torsion_line(ln, es_t, em_t)
      !! A line with a torsional END CONNECTIONS restraint: a finite-EI (cubic-Hermite) line with
      !! a Fixed End B. With both ends restrained (torsion active) every section's LINE TYPES row
      !! must give an explicit GJ, End A may not be a rod end, a body End A must be a Rigid6 body,
      !! and ATTACHMENTS are not combined with it.
      TYPE(DeckLine), INTENT(IN) :: ln
      INTEGER, INTENT(OUT) :: es_t
      CHARACTER(*), INTENT(OUT) :: em_t
      INTEGER :: js, jp, jb
      CHARACTER(32) :: lid
      es_t = 0
      em_t = ''
      lid = TRIM(int_to_str(ln%id))
      IF (.NOT. line_is_finite_ei(ln, types, sections)) THEN
        CALL fail(es_t, em_t, 'torsional END CONNECTIONS (TorsStiffness Rigid or a stiffness) require a '// &
                  'finite-EI line; line '//TRIM(lid)//' has EI = 0')
        RETURN
      END IF
      jp = find_point(points, ln%nodeB)
      IF (jp < 1) RETURN
      IF (TRIM(points(jp)%ptype) /= 'fixed') THEN
        CALL fail(es_t, em_t, 'torsional END CONNECTIONS require a finite-EI line with Fixed End B; line '// &
                  TRIM(lid)//' has two moving ends')
        RETURN
      END IF
      IF (.NOT. ALL(ln%tors_mode /= TORS_FREE)) RETURN
      DO js = 1, SIZE(sections)
        IF (sections(js)%line_id /= ln%id) CYCLE
        IF (sections(js)%ltype < 1 .OR. sections(js)%ltype > SIZE(types)) CYCLE
        IF (.NOT. (types(sections(js)%ltype)%gj > CD_ZERO)) THEN
          CALL fail(es_t, em_t, 'line '//TRIM(lid)//' is torsionally restrained at both ends: its LINE TYPES '// &
                    'row "'//TRIM(types(sections(js)%ltype)%name)//'" must give an explicit GJ > 0 (the '// &
                    '14-column row; torsion has no EI/1.3 default)')
          RETURN
        END IF
      END DO
      IF (ALLOCATED(ln%att)) THEN
        CALL fail(es_t, em_t, 'line '//TRIM(lid)//': torsion is not combined with ATTACHMENTS in this build')
        RETURN
      END IF
      jp = find_point(points, ln%nodeA)
      IF (jp < 1) RETURN
      IF (is_rod_point_type(points(jp)%ptype)) THEN
        CALL fail(es_t, em_t, 'line '//TRIM(lid)//': a torsional END CONNECTION on a rod end is not supported '// &
                  '(a rod has no spin angle in this build)')
        RETURN
      END IF
      IF (starts_with(TRIM(points(jp)%ptype), 'body')) THEN
        jb = find_body(bodies, points(jp)%body_id)
        IF (jb > 0) THEN
          IF (TRIM(bodies(jb)%btype) /= 'rigid6') THEN
            CALL fail(es_t, em_t, 'line '//TRIM(lid)//': a torsional END CONNECTION on a body needs a Rigid6 '// &
                      'body')
            RETURN
          END IF
        END IF
      END IF
    END SUBROUTINE check_torsion_line
  END SUBROUTINE finalize_checks

  ! --------------------------------------------------------------------------- !
  ! output                                                                      !
  ! --------------------------------------------------------------------------- !

  SUBROUTINE write_out(out_root, channels, lines, points, ne, q_all, q_off, ten_all, ten_off, &
                       converged, ErrStat, ErrMsg, end_ten, end_force, opts, bathymetry)
    !! end_ten(1:2, line): line-end force magnitudes (anchor, fairlead) reported for
    !! AnchTen/FairTen and the end-node tension channels; absent, the end elements' tension.
    !! end_force(1:3, 1:2, line): the end-force vectors (anchor, fairlead) for Point<P>F channels.
    CHARACTER(*), INTENT(IN) :: out_root
    CHARACTER(NAMELEN), INTENT(IN) :: channels(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    INTEGER, INTENT(IN) :: ne(:), q_off(:), ten_off(:)
    REAL(wp), INTENT(IN) :: q_all(:)
    REAL(wp), INTENT(IN) :: ten_all(:)
    LOGICAL, INTENT(IN) :: converged
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp), INTENT(IN), OPTIONAL :: end_ten(:, :)
    REAL(wp), INTENT(IN), OPTIONAL :: end_force(:, :, :)
    ! range graphs (LINES flag r) and TDP<L> channels of the converged static state
    TYPE(DeckOptions), INTENT(IN), OPTIONAL :: opts
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    INTEGER :: unit, ios, i, nch, li, line_id, comp, es
    CHARACTER(LEN(out_root) + 8) :: path
    CHARACTER(512) :: em
    REAL(wp) :: val
    TYPE(CD_RangeSet) :: ranges
    ErrStat = 0; ErrMsg = ''
    nch = SIZE(channels)
    IF (converged .AND. PRESENT(opts)) THEN
      CALL range_setup(ranges, lines, channels, opts, ne + 1, .FALSE., ErrStat, ErrMsg, bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      DO li = 1, SIZE(lines)
        IF (.NOT. CD_Range_Needs_Sample(ranges, li)) CYCLE
        IF (PRESENT(end_ten)) THEN
          CALL range_sample_arrays(q_all(q_off(li) + 1:q_off(li + 1)), ten_all(ten_off(li) + 1:ten_off(li + 1)), &
                                   ranges%lines(li), end_ten(:, li))
        ELSE
          CALL range_sample_arrays(q_all(q_off(li) + 1:q_off(li + 1)), ten_all(ten_off(li) + 1:ten_off(li + 1)), &
                                   ranges%lines(li))
        END IF
        CALL CD_Range_Commit_Sample(ranges, li, CD_ZERO, es, em)
        CALL range_status(es, em, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      END DO
    END IF
    path = TRIM(out_root)//'.out'
    OPEN (NEWUNIT=unit, FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open output file: '//TRIM(path)); RETURN
    END IF
    WRITE (unit, '(A,L1,A)') '# CableDyn driver output (static IC; converged=', converged, ')'
    WRITE (unit, '(A)', ADVANCE='NO') 'Time(s)'
    DO i = 1, nch
      WRITE (unit, '(A,A)', ADVANCE='NO') char_tab(), TRIM(channels(i))
    END DO
    WRITE (unit, '(A)') ''
    WRITE (unit, TIME_COLUMN_FMT, ADVANCE='NO') CD_ZERO
    DO i = 1, nch
      IF (CD_Is_TDP_Channel(to_lower(channels(i)))) THEN
        ! a non-converged static state has no touchdown reference: reported as 0
        CALL CD_Parse_TDP_Channel(channels(i), line_id, comp)
        li = find_line(lines, line_id)
        val = CD_ZERO
        IF (CD_Range_Needs_Sample(ranges, li)) val = ranges%lines(li)%tdp(comp)
      ELSE
        val = channel_value(channels(i), lines, points, ne, q_all, q_off, ten_all, ten_off, end_ten, end_force)
      END IF
      WRITE (unit, '(A,ES15.7E3)', ADVANCE='NO') char_tab(), val
    END DO
    WRITE (unit, '(A)') ''
    CLOSE (unit)
    CALL write_static_line_outputs(out_root, lines, ne, q_all, q_off, ten_all, ten_off, ErrStat, ErrMsg)
    IF (ErrStat /= 0) RETURN
    CALL write_static_config_out(out_root, lines, ne, q_all, q_off, ten_all, ten_off, ErrStat, ErrMsg, end_ten)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    IF (converged) CALL range_write(ranges, out_root, ErrStat, ErrMsg)
  END SUBROUTINE write_out

  SUBROUTINE write_static_config_out(out_root, lines, ne, q_all, q_off, ten_all, ten_off, ErrStat, ErrMsg, end_ten)
    !! Write <out_root>.static.out -- the along-arc static configuration profile
    !! (the OrcaFlex range-graph analogue) in the OpenFAST/MoorDyn tabular format
    !! pyDatView reads: a title line, a channel-name header row, a units row, then
    !! ONE whitespace/tab-delimited data row per node of every line (keyed by the
    !! LineID column). Columns: LineID Node ArcLength X Y Z Tension Curvature
    !! BendMoment Declination Inclination Azimuth. ArcLength is the cumulative DEFORMED chord
    !! length from End A. Static decks are EI=0, so BendMoment is 0. Written after
    !! the static solve; it does not change the existing <out_root>.out.
    CHARACTER(*), INTENT(IN) :: out_root
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    INTEGER, INTENT(IN) :: ne(:), q_off(:), ten_off(:)
    REAL(wp), INTENT(IN) :: q_all(:), ten_all(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp), INTENT(IN), OPTIONAL :: end_ten(:, :)   !! (anchor, fairlead) end-force magnitudes per line

    INTEGER :: unit, ios, li, node, nnode, inode, base
    REAL(wp) :: s, r_prev(3), r_node(3), tenv, curv, dec, azi
    REAL(wp), ALLOCATABLE :: r_line(:, :)
    CHARACTER(LEN(out_root) + 16) :: path
    CHARACTER(1) :: tab

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    tab = char_tab()
    path = TRIM(out_root)//'.static.out'
    OPEN (NEWUNIT=unit, FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open static-configuration output file: '//TRIM(path)); RETURN
    END IF
    WRITE (unit, '(A)') 'CableDyn static configuration profile (deformed arc; public node order EndA -> EndB)'
    WRITE (unit, '(A)') 'LineID'//tab//'Node'//tab//'ArcLength'//tab//'X'//tab//'Y'//tab//'Z'//tab// &
      'Tension'//tab//'Curvature'//tab//'BendMoment'//tab//'Declination'//tab//'Inclination'//tab//'Azimuth'
    WRITE (unit, '(A)') '(-)'//tab//'(-)'//tab//'(m)'//tab//'(m)'//tab//'(m)'//tab//'(m)'//tab// &
      '(N)'//tab//'(1/m)'//tab//'(N.m)'//tab//'(deg)'//tab//'(deg)'//tab//'(deg)'
    r_prev = CD_ZERO
    DO li = 1, SIZE(lines)
      nnode = ne(li) + 1
      ! Build the deck-ordered (End A -> End B) node positions ONCE per line, then evaluate
      ! each node's geometry in O(1). The profile writes every node, so rebuilding the full
      ! r(3,nnode) inside each per-node call would be O(nnode^2) and stack-heavy on long decks.
      IF (ALLOCATED(r_line)) THEN
        IF (SIZE(r_line, 2) /= nnode) DEALLOCATE (r_line)
      END IF
      IF (.NOT. ALLOCATED(r_line)) ALLOCATE (r_line(3, nnode))
      DO node = 1, nnode
        base = q_off(li) + 3*(nnode - node)      ! deck node <-> internal node (nnode+1-node)
        r_line(:, node) = q_all(base + 1:base + 3)
      END DO
      s = CD_ZERO
      DO node = 1, nnode
        inode = deck_to_internal_node(node, ne(li))
        r_node = r_line(:, node)
        IF (node > 1) s = s + NORM2(r_node - r_prev)
        tenv = nodal_tension_value(ten_all(ten_off(li) + 1:ten_off(li) + ne(li)), inode)
        IF (PRESENT(end_ten)) THEN
          ! end nodes: the force the line exerts on its end point (internal node 1 = anchor)
          IF (inode == 1) tenv = end_ten(1, li)
          IF (inode == nnode) tenv = end_ten(2, li)
        END IF
        curv = line_geom_from_r(5, r_line, nnode, node)
        dec = line_geom_from_r(7, r_line, nnode, node)
        azi = line_geom_from_r(8, r_line, nnode, node)
        WRITE (unit, '(I0,A,I0,10(A,ES15.7E3))') lines(li)%id, tab, node, tab, s, tab, r_node(1), &
          tab, r_node(2), tab, r_node(3), tab, tenv, tab, curv, tab, CD_ZERO, tab, dec, &
          tab, dec - 90.0_wp, tab, azi
        r_prev = r_node
      END DO
    END DO
    CLOSE (unit)
  END SUBROUTINE write_static_config_out

  SUBROUTINE write_static_line_outputs(out_root, lines, ne, q_all, q_off, ten_all, ten_off, ErrStat, ErrMsg)
    !! Write optional per-line static files requested by the LINES Outputs flag.
    !! Node/segment order follows the public deck convention: End A -> End B.
    CHARACTER(*), INTENT(IN) :: out_root
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    INTEGER, INTENT(IN) :: ne(:), q_off(:), ten_off(:)
    REAL(wp), INTENT(IN) :: q_all(:), ten_all(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    DO i = 1, SIZE(lines)
      IF (.NOT. line_outputs_requested(lines(i)%outputs)) CYCLE
      IF (line_output_has_flag(lines(i)%outputs, 'p')) THEN
        CALL write_static_line_position_file(out_root, lines(i)%id, ne(i), q_all(q_off(i) + 1:q_off(i + 1)), &
                                             ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      END IF
      IF (line_output_has_flag(lines(i)%outputs, 't')) THEN
        CALL write_static_line_tension_file(out_root, lines(i)%id, ne(i), ten_all(ten_off(i) + 1:ten_off(i + 1)), &
                                            ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      END IF
    END DO
  END SUBROUTINE write_static_line_outputs

  SUBROUTINE write_static_line_position_file(out_root, line_id, nelem, q_line, ErrStat, ErrMsg)
    CHARACTER(*), INTENT(IN) :: out_root
    INTEGER, INTENT(IN) :: line_id, nelem
    REAL(wp), INTENT(IN) :: q_line(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: unit, ios, node, inode
    CHARACTER(LEN(out_root) + 32) :: path

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    path = TRIM(out_root)//'.Line'//TRIM(int_to_str(line_id))//'.p.out'
    OPEN (NEWUNIT=unit, FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open line position output file: '//TRIM(path)); RETURN
    END IF
    WRITE (unit, '(A)') '# CableDyn static line node positions; public node order EndA -> EndB'
    WRITE (unit, '(A)') 'Node'//char_tab()//'X(m)'//char_tab()//'Y(m)'//char_tab()//'Z(m)'
    DO node = 1, nelem + 1
      inode = deck_to_internal_node(node, nelem)
      WRITE (unit, '(I0,3(A,ES15.7E3))') node, char_tab(), q_line(3*inode - 2), char_tab(), q_line(3*inode - 1), &
        char_tab(), q_line(3*inode)
    END DO
    CLOSE (unit)
  END SUBROUTINE write_static_line_position_file

  SUBROUTINE write_static_line_tension_file(out_root, line_id, nelem, tension_line, ErrStat, ErrMsg)
    CHARACTER(*), INTENT(IN) :: out_root
    INTEGER, INTENT(IN) :: line_id, nelem
    REAL(wp), INTENT(IN) :: tension_line(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: unit, ios, seg, iseg
    CHARACTER(LEN(out_root) + 32) :: path

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    path = TRIM(out_root)//'.Line'//TRIM(int_to_str(line_id))//'.t.out'
    OPEN (NEWUNIT=unit, FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open line tension output file: '//TRIM(path)); RETURN
    END IF
    WRITE (unit, '(A)') '# CableDyn static line segment tensions; public segment order EndA -> EndB'
    WRITE (unit, '(A)') 'Segment'//char_tab()//'Tension(N)'
    DO seg = 1, nelem
      iseg = nelem - seg + 1
      WRITE (unit, '(I0,A,ES15.7E3)') seg, char_tab(), tension_line(iseg)
    END DO
    CLOSE (unit)
  END SUBROUTINE write_static_line_tension_file

  SUBROUTINE open_dynamic_line_outputs(out_root, lines, models, pos_units, ten_units, ErrStat, ErrMsg)
    !! Open optional per-line dynamic time-series files requested by LINE Outputs flags.
    CHARACTER(*), INTENT(IN) :: out_root
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(CD_ModelType), INTENT(IN) :: models(:)
    INTEGER, ALLOCATABLE, INTENT(OUT) :: pos_units(:), ten_units(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i, ios, ndof, nnode, ne, node, seg, es
    CHARACTER(LEN(out_root) + 32) :: path
    CHARACTER(256) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    ALLOCATE (pos_units(SIZE(lines)), ten_units(SIZE(lines)))
    pos_units = 0
    ten_units = 0
    DO i = 1, SIZE(lines)
      IF (.NOT. line_outputs_requested(lines(i)%outputs)) CYCLE
      ndof = CD_Model_NDOF(models(i), es, em)
      IF (es /= CD_MODEL_OK) THEN
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: dynamic line-output DOF query failed: '//TRIM(em)
        RETURN
      END IF
      nnode = ndof/3
      ne = nnode - 1
      IF (line_output_has_flag(lines(i)%outputs, 'p')) THEN
        path = TRIM(out_root)//'.Line'//TRIM(int_to_str(lines(i)%id))//'.p.out'
        OPEN (NEWUNIT=pos_units(i), FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
        IF (ios /= 0) THEN
          CALL close_dynamic_line_outputs(pos_units, ten_units)
          CALL fail(ErrStat, ErrMsg, 'cannot open dynamic line position output file: '//TRIM(path)); RETURN
        END IF
        WRITE (pos_units(i), '(A)') '# CableDyn dynamic line node positions; public node order EndA -> EndB'
        WRITE (pos_units(i), '(A)', ADVANCE='NO') 'Time(s)'
        DO node = 1, nnode
          WRITE (pos_units(i), '(A,A,I0,A)', ADVANCE='NO') char_tab(), 'Node', node, 'X(m)'
          WRITE (pos_units(i), '(A,A,I0,A)', ADVANCE='NO') char_tab(), 'Node', node, 'Y(m)'
          WRITE (pos_units(i), '(A,A,I0,A)', ADVANCE='NO') char_tab(), 'Node', node, 'Z(m)'
        END DO
        WRITE (pos_units(i), '(A)') ''
      END IF
      IF (line_output_has_flag(lines(i)%outputs, 't')) THEN
        path = TRIM(out_root)//'.Line'//TRIM(int_to_str(lines(i)%id))//'.t.out'
        OPEN (NEWUNIT=ten_units(i), FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
        IF (ios /= 0) THEN
          CALL close_dynamic_line_outputs(pos_units, ten_units)
          CALL fail(ErrStat, ErrMsg, 'cannot open dynamic line tension output file: '//TRIM(path)); RETURN
        END IF
        WRITE (ten_units(i), '(A)') '# CableDyn dynamic line segment tensions; public segment order EndA -> EndB'
        WRITE (ten_units(i), '(A)', ADVANCE='NO') 'Time(s)'
        DO seg = 1, ne
          WRITE (ten_units(i), '(A,A,I0,A)', ADVANCE='NO') char_tab(), 'Segment', seg, 'Tension(N)'
        END DO
        WRITE (ten_units(i), '(A)') ''
      END IF
    END DO
  END SUBROUTINE open_dynamic_line_outputs

  SUBROUTINE open_dynamic_system_line_outputs(out_root, lines, system, pos_units, ten_units, ErrStat, ErrMsg)
    !! Open optional per-line dynamic time-series files for a point-system deck.
    CHARACTER(*), INTENT(IN) :: out_root
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(CD_SystemType), INTENT(IN) :: system
    INTEGER, ALLOCATABLE, INTENT(OUT) :: pos_units(:), ten_units(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i, ios, ndof, nnode, ne, node, seg, es
    CHARACTER(LEN(out_root) + 32) :: path
    CHARACTER(256) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    ALLOCATE (pos_units(SIZE(lines)), ten_units(SIZE(lines)))
    pos_units = 0
    ten_units = 0
    DO i = 1, SIZE(lines)
      IF (.NOT. line_outputs_requested(lines(i)%outputs)) CYCLE
      ndof = CD_System_Line_NDOF(system, i, es, em)
      IF (es /= CD_SYSTEM_OK) THEN
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: system dynamic line-output DOF query failed: '//TRIM(em)
        RETURN
      END IF
      nnode = ndof/3
      ne = nnode - 1
      IF (line_output_has_flag(lines(i)%outputs, 'p')) THEN
        path = TRIM(out_root)//'.Line'//TRIM(int_to_str(lines(i)%id))//'.p.out'
        OPEN (NEWUNIT=pos_units(i), FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
        IF (ios /= 0) THEN
          CALL close_dynamic_line_outputs(pos_units, ten_units)
          CALL fail(ErrStat, ErrMsg, 'cannot open system dynamic line position output file: '//TRIM(path)); RETURN
        END IF
        WRITE (pos_units(i), '(A)') '# CableDyn dynamic line node positions; public node order EndA -> EndB'
        WRITE (pos_units(i), '(A)', ADVANCE='NO') 'Time(s)'
        DO node = 1, nnode
          WRITE (pos_units(i), '(A,A,I0,A)', ADVANCE='NO') char_tab(), 'Node', node, 'X(m)'
          WRITE (pos_units(i), '(A,A,I0,A)', ADVANCE='NO') char_tab(), 'Node', node, 'Y(m)'
          WRITE (pos_units(i), '(A,A,I0,A)', ADVANCE='NO') char_tab(), 'Node', node, 'Z(m)'
        END DO
        WRITE (pos_units(i), '(A)') ''
      END IF
      IF (line_output_has_flag(lines(i)%outputs, 't')) THEN
        path = TRIM(out_root)//'.Line'//TRIM(int_to_str(lines(i)%id))//'.t.out'
        OPEN (NEWUNIT=ten_units(i), FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
        IF (ios /= 0) THEN
          CALL close_dynamic_line_outputs(pos_units, ten_units)
          CALL fail(ErrStat, ErrMsg, 'cannot open system dynamic line tension output file: '//TRIM(path)); RETURN
        END IF
        WRITE (ten_units(i), '(A)') '# CableDyn dynamic line segment tensions; public segment order EndA -> EndB'
        WRITE (ten_units(i), '(A)', ADVANCE='NO') 'Time(s)'
        DO seg = 1, ne
          WRITE (ten_units(i), '(A,A,I0,A)', ADVANCE='NO') char_tab(), 'Segment', seg, 'Tension(N)'
        END DO
        WRITE (ten_units(i), '(A)') ''
      END IF
    END DO
  END SUBROUTINE open_dynamic_system_line_outputs

  SUBROUTINE write_dynamic_line_outputs(time, lines, models, pos_units, ten_units, work, ErrStat, ErrMsg)
    !! Append one time row to every requested dynamic per-line output file.
    REAL(wp), INTENT(IN) :: time
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(CD_ModelType), INTENT(IN) :: models(:)
    INTEGER, INTENT(IN) :: pos_units(:), ten_units(:)
    TYPE(ModelOutputWorkspace), INTENT(INOUT) :: work
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i, ndof, nnode, ne, es
    CHARACTER(256) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    DO i = 1, SIZE(lines)
      IF (pos_units(i) == 0 .AND. ten_units(i) == 0) CYCLE
      ndof = CD_Model_NDOF(models(i), es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: dynamic line-output DOF query failed: '//TRIM(em)
        RETURN
      END IF
      nnode = ndof/3
      ne = nnode - 1
      IF (pos_units(i) /= 0) THEN
        CALL ensure_model_output_workspace(work, ndof, 0)
        CALL CD_Get_Model_State(models(i), work%q(1:ndof), work%v(1:ndof), work%a(1:ndof), es, em)
        IF (es /= CD_MODEL_OK) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: dynamic line-output state recovery failed: '//TRIM(em)
          RETURN
        END IF
        CALL write_line_position_row(pos_units(i), time, work%q(1:ndof), 3, ne, ErrStat)
        IF (ErrStat /= CD_DECKDRV_OK) THEN
          ErrMsg = 'CableDyn_DeckDriver: non-finite dynamic line position output'
          RETURN
        END IF
      END IF
      IF (ten_units(i) /= 0) THEN
        CALL ensure_model_output_workspace(work, 0, ne)
        CALL CD_Get_Model_Tension(models(i), work%tension(1:ne), es, em)
        IF (es /= CD_MODEL_OK) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: dynamic line-output tension recovery failed: '//TRIM(em)
          RETURN
        END IF
        CALL write_line_tension_row(ten_units(i), time, work%tension(1:ne), ErrStat)
        IF (ErrStat /= CD_DECKDRV_OK) THEN
          ErrMsg = 'CableDyn_DeckDriver: non-finite dynamic line tension output'
          RETURN
        END IF
      END IF
    END DO
  END SUBROUTINE write_dynamic_line_outputs

  SUBROUTINE write_line_position_row(unit, time, q, stride, ne, ErrStat)
    !! One .Line<N>.p.out row in one WRITE: node positions in deck order (End A -> End B)
    !! from internal (anchor -> fairlead) state `q` with `stride` reals per node. A
    !! non-finite node leaves the row prefix before it non-advancing and fails.
    INTEGER, INTENT(IN) :: unit, stride, ne
    REAL(wp), INTENT(IN) :: time, q(:)
    INTEGER, INTENT(OUT) :: ErrStat
    INTEGER :: node, nw, c, base

    ErrStat = CD_DECKDRV_OK
    nw = ne + 1
    DO node = 1, ne + 1
      base = stride*(deck_to_internal_node(node, ne) - 1)
      IF (.NOT. ALL(IEEE_IS_FINITE(q(base + 1:base + 3)))) THEN
        nw = node - 1
        ErrStat = CD_DECKDRV_SOLVEFAIL
        EXIT
      END IF
    END DO
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      WRITE (unit, ROW_VALUES_FMT, ADVANCE='NO') time, &
        ((char_tab(), q(stride*(deck_to_internal_node(node, ne) - 1) + c), c=1, 3), node=1, nw)
    ELSE
      WRITE (unit, ROW_VALUES_FMT) time, &
        ((char_tab(), q(stride*(deck_to_internal_node(node, ne) - 1) + c), c=1, 3), node=1, nw)
    END IF
  END SUBROUTINE write_line_position_row

  SUBROUTINE write_line_tension_row(unit, time, tension, ErrStat)
    !! One .Line<N>.t.out row in one WRITE: element tensions in deck order (End A ->
    !! End B, i.e. internal order reversed). A non-finite segment leaves the row
    !! prefix before it non-advancing and fails.
    INTEGER, INTENT(IN) :: unit
    REAL(wp), INTENT(IN) :: time, tension(:)
    INTEGER, INTENT(OUT) :: ErrStat
    INTEGER :: seg, nw, ne

    ErrStat = CD_DECKDRV_OK
    ne = SIZE(tension)
    nw = ne
    DO seg = 1, ne
      IF (.NOT. IEEE_IS_FINITE(tension(ne - seg + 1))) THEN
        nw = seg - 1
        ErrStat = CD_DECKDRV_SOLVEFAIL
        EXIT
      END IF
    END DO
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      WRITE (unit, ROW_VALUES_FMT, ADVANCE='NO') time, (char_tab(), tension(ne - seg + 1), seg=1, nw)
    ELSE
      WRITE (unit, ROW_VALUES_FMT) time, (char_tab(), tension(ne - seg + 1), seg=1, nw)
    END IF
  END SUBROUTINE write_line_tension_row

  SUBROUTINE write_dynamic_system_line_outputs(time, lines, system, pos_units, ten_units, work, ErrStat, ErrMsg)
    !! Append one time row to requested dynamic per-line output files for a point-system deck.
    REAL(wp), INTENT(IN) :: time
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(CD_SystemType), INTENT(IN) :: system
    INTEGER, INTENT(IN) :: pos_units(:), ten_units(:)
    TYPE(ModelOutputWorkspace), INTENT(INOUT) :: work
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i, ndof, nnode, ne, es
    CHARACTER(256) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    DO i = 1, SIZE(lines)
      IF (pos_units(i) == 0 .AND. ten_units(i) == 0) CYCLE
      ndof = CD_System_Line_NDOF(system, i, es, em)
      IF (es /= CD_SYSTEM_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: system dynamic line-output DOF query failed: '//TRIM(em)
        RETURN
      END IF
      nnode = ndof/3
      ne = nnode - 1
      IF (pos_units(i) /= 0) THEN
        CALL ensure_model_output_workspace(work, ndof, 0)
        CALL CD_Get_System_Line_State(system, i, work%q(1:ndof), work%v(1:ndof), work%a(1:ndof), es, em)
        IF (es /= CD_SYSTEM_OK) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: system dynamic line-output state recovery failed: '//TRIM(em)
          RETURN
        END IF
        CALL write_line_position_row(pos_units(i), time, work%q(1:ndof), 3, ne, ErrStat)
        IF (ErrStat /= CD_DECKDRV_OK) THEN
          ErrMsg = 'CableDyn_DeckDriver: non-finite system dynamic line position output'
          RETURN
        END IF
      END IF
      IF (ten_units(i) /= 0) THEN
        CALL ensure_model_output_workspace(work, 0, ne)
        CALL CD_Get_System_Line_Tension(system, i, work%tension(1:ne), es, em)
        IF (es /= CD_SYSTEM_OK) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: system dynamic line-output tension recovery failed: '//TRIM(em)
          RETURN
        END IF
        CALL write_line_tension_row(ten_units(i), time, work%tension(1:ne), ErrStat)
        IF (ErrStat /= CD_DECKDRV_OK) THEN
          ErrMsg = 'CableDyn_DeckDriver: non-finite system dynamic line tension output'
          RETURN
        END IF
      END IF
    END DO
  END SUBROUTINE write_dynamic_system_line_outputs

  SUBROUTINE open_dynamic_finite_line_outputs(out_root, lines, models, pos_units, ten_units, ErrStat, ErrMsg)
    !! Open optional finite-EI per-line dynamic time-series files.
    CHARACTER(*), INTENT(IN) :: out_root
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(FiniteDeckModel), INTENT(IN) :: models(:)
    INTEGER, ALLOCATABLE, INTENT(OUT) :: pos_units(:), ten_units(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i, ios, nnode, ne, node, seg
    CHARACTER(LEN(out_root) + 32) :: path

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (SIZE(models) /= SIZE(lines)) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI line-output model count does not match line count')
      RETURN
    END IF
    ALLOCATE (pos_units(SIZE(lines)), ten_units(SIZE(lines)))
    pos_units = 0
    ten_units = 0
    DO i = 1, SIZE(lines)
      IF (.NOT. line_outputs_requested(lines(i)%outputs)) CYCLE
      ne = models(i)%n_elem
      nnode = ne + 1
      IF (line_output_has_flag(lines(i)%outputs, 'p')) THEN
        path = TRIM(out_root)//'.Line'//TRIM(int_to_str(lines(i)%id))//'.p.out'
        OPEN (NEWUNIT=pos_units(i), FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
        IF (ios /= 0) THEN
          CALL close_dynamic_line_outputs(pos_units, ten_units)
          CALL fail(ErrStat, ErrMsg, 'cannot open finite-EI line position output file: '//TRIM(path)); RETURN
        END IF
        WRITE (pos_units(i), '(A)') '# CableDyn finite-EI dynamic line node positions; public node order EndA -> EndB'
        WRITE (pos_units(i), '(A)', ADVANCE='NO') 'Time(s)'
        DO node = 1, nnode
          WRITE (pos_units(i), '(A,A,I0,A)', ADVANCE='NO') char_tab(), 'Node', node, 'X(m)'
          WRITE (pos_units(i), '(A,A,I0,A)', ADVANCE='NO') char_tab(), 'Node', node, 'Y(m)'
          WRITE (pos_units(i), '(A,A,I0,A)', ADVANCE='NO') char_tab(), 'Node', node, 'Z(m)'
        END DO
        WRITE (pos_units(i), '(A)') ''
      END IF
      IF (line_output_has_flag(lines(i)%outputs, 't')) THEN
        path = TRIM(out_root)//'.Line'//TRIM(int_to_str(lines(i)%id))//'.t.out'
        OPEN (NEWUNIT=ten_units(i), FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
        IF (ios /= 0) THEN
          CALL close_dynamic_line_outputs(pos_units, ten_units)
          CALL fail(ErrStat, ErrMsg, 'cannot open finite-EI line tension output file: '//TRIM(path)); RETURN
        END IF
        WRITE (ten_units(i), '(A)') '# CableDyn finite-EI dynamic line segment tensions; public segment order '// &
          'EndA -> EndB'
        WRITE (ten_units(i), '(A)', ADVANCE='NO') 'Time(s)'
        DO seg = 1, ne
          WRITE (ten_units(i), '(A,A,I0,A)', ADVANCE='NO') char_tab(), 'Segment', seg, 'Tension(N)'
        END DO
        WRITE (ten_units(i), '(A)') ''
      END IF
    END DO
  END SUBROUTINE open_dynamic_finite_line_outputs

  SUBROUTINE write_dynamic_finite_line_outputs(time, lines, models, pos_units, ten_units, work, ErrStat, ErrMsg)
    !! Append one row to requested finite-EI dynamic per-line output files.
    REAL(wp), INTENT(IN) :: time
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(FiniteDeckModel), INTENT(IN) :: models(:)
    INTEGER, INTENT(IN) :: pos_units(:), ten_units(:)
    TYPE(ModelOutputWorkspace), INTENT(INOUT) :: work
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i, nnode, ndof, ne, es
    CHARACTER(256) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    DO i = 1, SIZE(lines)
      IF (pos_units(i) == 0 .AND. ten_units(i) == 0) CYCLE
      ne = models(i)%n_elem
      nnode = ne + 1
      ndof = 6*nnode
      IF (pos_units(i) /= 0) THEN
        CALL ensure_model_output_workspace(work, ndof, 0)
        CALL CD_Get_FiniteEI_Model_State(models(i)%model, work%q(1:ndof), work%v(1:ndof), &
                                         work%a(1:ndof), es, em)
        IF (es /= 0) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: finite-EI line-output state recovery failed: '//TRIM(em)
          RETURN
        END IF
        CALL write_line_position_row(pos_units(i), time, work%q(1:ndof), 6, ne, ErrStat)
        IF (ErrStat /= CD_DECKDRV_OK) THEN
          ErrMsg = 'CableDyn_DeckDriver: non-finite finite-EI line position output'
          RETURN
        END IF
      END IF
      IF (ten_units(i) /= 0) THEN
        CALL ensure_model_output_workspace(work, 0, ne)
        CALL finite_model_tension(models(i), work%tension(1:ne), work, es, em)
        IF (es /= CD_DECKDRV_OK) THEN
          ErrStat = es
          ErrMsg = em
          RETURN
        END IF
        CALL write_line_tension_row(ten_units(i), time, work%tension(1:ne), ErrStat)
        IF (ErrStat /= CD_DECKDRV_OK) THEN
          ErrMsg = 'CableDyn_DeckDriver: non-finite finite-EI line tension output'
          RETURN
        END IF
      END IF
    END DO
  END SUBROUTINE write_dynamic_finite_line_outputs

  SUBROUTINE close_dynamic_line_outputs(pos_units, ten_units)
    INTEGER, ALLOCATABLE, INTENT(INOUT) :: pos_units(:), ten_units(:)
    INTEGER :: i

    IF (ALLOCATED(pos_units)) THEN
      DO i = 1, SIZE(pos_units)
        IF (pos_units(i) /= 0) CLOSE (pos_units(i))
      END DO
      DEALLOCATE (pos_units)
    END IF
    IF (ALLOCATED(ten_units)) THEN
      DO i = 1, SIZE(ten_units)
        IF (ten_units(i) /= 0) CLOSE (ten_units(i))
      END DO
      DEALLOCATE (ten_units)
    END IF
  END SUBROUTINE close_dynamic_line_outputs

  SUBROUTINE open_dynamic_rod_outputs(out_root, rods, pos_units, ErrStat, ErrMsg)
    !! Open optional per-rod dynamic endpoint-position time-series files.
    CHARACTER(*), INTENT(IN) :: out_root
    TYPE(DeckRod), INTENT(IN) :: rods(:)
    INTEGER, ALLOCATABLE, INTENT(OUT) :: pos_units(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i, ios
    CHARACTER(LEN(out_root) + 32) :: path

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    ALLOCATE (pos_units(SIZE(rods)))
    pos_units = 0
    DO i = 1, SIZE(rods)
      IF (.NOT. rod_outputs_requested(rods(i)%outputs)) CYCLE
      IF (rod_output_has_flag(rods(i)%outputs, 'p')) THEN
        path = TRIM(out_root)//'.Rod'//TRIM(int_to_str(rods(i)%id))//'.p.out'
        OPEN (NEWUNIT=pos_units(i), FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
        IF (ios /= 0) THEN
          CALL close_dynamic_rod_outputs(pos_units)
          CALL fail(ErrStat, ErrMsg, 'cannot open dynamic rod position output file: '//TRIM(path)); RETURN
        END IF
        WRITE (pos_units(i), '(A)') '# CableDyn dynamic rod endpoint positions; public end order EndA -> EndB'
        WRITE (pos_units(i), '(A)', ADVANCE='NO') 'Time(s)'
        WRITE (pos_units(i), '(A,A)', ADVANCE='NO') char_tab(), 'EndAX(m)'
        WRITE (pos_units(i), '(A,A)', ADVANCE='NO') char_tab(), 'EndAY(m)'
        WRITE (pos_units(i), '(A,A)', ADVANCE='NO') char_tab(), 'EndAZ(m)'
        WRITE (pos_units(i), '(A,A)', ADVANCE='NO') char_tab(), 'EndBX(m)'
        WRITE (pos_units(i), '(A,A)', ADVANCE='NO') char_tab(), 'EndBY(m)'
        WRITE (pos_units(i), '(A,A)', ADVANCE='NO') char_tab(), 'EndBZ(m)'
        WRITE (pos_units(i), '(A)') ''
      END IF
    END DO
  END SUBROUTINE open_dynamic_rod_outputs

  SUBROUTINE write_dynamic_rod_outputs(time, rods, rod_state, pos_units, ErrStat, ErrMsg)
    !! Append one row to requested per-rod dynamic endpoint-position files.
    REAL(wp), INTENT(IN) :: time
    TYPE(DeckRod), INTENT(IN) :: rods(:)
    TYPE(RodState), INTENT(IN) :: rod_state(:)
    INTEGER, INTENT(IN) :: pos_units(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i
    REAL(wp) :: arm_a(3), arm_b(3), end_a(3), end_b(3)

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (SIZE(rods) /= SIZE(rod_state) .OR. SIZE(pos_units) /= SIZE(rods)) THEN
      CALL fail(ErrStat, ErrMsg, 'dynamic rod-output arrays must share shape')
      RETURN
    END IF
    DO i = 1, SIZE(rods)
      IF (pos_units(i) == 0) CYCLE
      arm_a = MATMUL(rod_state(i)%rot_mat, [-rod_state(i)%half_length, CD_ZERO, CD_ZERO])
      arm_b = MATMUL(rod_state(i)%rot_mat, [rod_state(i)%half_length, CD_ZERO, CD_ZERO])
      end_a = rod_state(i)%r + arm_a
      end_b = rod_state(i)%r + arm_b
      IF (.NOT. (ALL(IEEE_IS_FINITE(end_a)) .AND. ALL(IEEE_IS_FINITE(end_b)))) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: non-finite dynamic rod position output'
        RETURN
      END IF
      WRITE (pos_units(i), TIME_COLUMN_FMT, ADVANCE='NO') time
      WRITE (pos_units(i), '(6(A,ES15.7E3))', ADVANCE='NO') char_tab(), end_a(1), char_tab(), end_a(2), &
        char_tab(), end_a(3), char_tab(), end_b(1), char_tab(), end_b(2), char_tab(), end_b(3)
      WRITE (pos_units(i), '(A)') ''
    END DO
  END SUBROUTINE write_dynamic_rod_outputs

  SUBROUTINE close_dynamic_rod_outputs(pos_units)
    INTEGER, ALLOCATABLE, INTENT(INOUT) :: pos_units(:)
    INTEGER :: i

    IF (ALLOCATED(pos_units)) THEN
      DO i = 1, SIZE(pos_units)
        IF (pos_units(i) /= 0) CLOSE (pos_units(i))
      END DO
      DEALLOCATE (pos_units)
    END IF
  END SUBROUTINE close_dynamic_rod_outputs

  SUBROUTINE write_dynamic_out(out_root, channels, lines, points, opts, models, converged, ErrStat, ErrMsg, &
                               bathymetry)
    CHARACTER(*), INTENT(IN) :: out_root
    CHARACTER(NAMELEN), INTENT(IN) :: channels(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(CD_ModelType), INTENT(INOUT) :: models(:)
    LOGICAL, INTENT(OUT) :: converged
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    INTEGER :: unit, ios, step, nstep, es, n_iter, step_substeps
    INTEGER, ALLOCATABLE :: pos_units(:), ten_units(:)
    INTEGER :: miss_count, consecutive_miss, max_consecutive_miss
    INTEGER :: recovery_event_count, recovery_max_substeps_used
    CHARACTER(LEN(out_root) + 8) :: path
    CHARACTER(256) :: em
    LOGICAL :: step_converged, stalled
    REAL(wp) :: t, first_miss_time, last_miss_time
    TYPE(MotionTable) :: motion
    TYPE(ModelOutputWorkspace) :: output_work
    TYPE(HydroUpdateWorkspace) :: hydro_work
    TYPE(LineStepWorkspace) :: step_work
    TYPE(DriverProgress) :: progress

    converged = .TRUE.
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    nstep = NINT(opts%tmax/opts%dtM)
    CALL range_setup_planned(output_work%rset, lines, channels, opts, ErrStat, ErrMsg, models=models, &
                             bathymetry=bathymetry)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    miss_count = 0
    consecutive_miss = 0
    max_consecutive_miss = 0
    recovery_event_count = 0
    recovery_max_substeps_used = 1
    first_miss_time = CD_ZERO
    last_miss_time = CD_ZERO
    IF (opts%has_motion_file) THEN
      CALL read_motion_file(opts%motion_file, points, opts, motion, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL apply_motion_to_models(models, lines, points, motion, 1, es, em)
      IF (es /= CD_DECKDRV_OK) THEN
        ErrStat = es
        ErrMsg = em
        RETURN
      END IF
    END IF
    IF (opts%has_wave .OR. opts%has_current) THEN
      CALL update_wave_models(models, opts, CD_ZERO, hydro_work, es, em, initial_condition=.TRUE.)
      IF (es /= CD_DECKDRV_OK) THEN
        ErrStat = es
        ErrMsg = em
        RETURN
      END IF
    END IF
    CALL open_dynamic_line_outputs(out_root, lines, models, pos_units, ten_units, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    path = TRIM(out_root)//'.out'
    OPEN (NEWUNIT=unit, FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
    IF (ios /= 0) THEN
      CALL close_dynamic_line_outputs(pos_units, ten_units)
      CALL fail(ErrStat, ErrMsg, 'cannot open output file: '//TRIM(path)); RETURN
    END IF
    WRITE (unit, '(A)') '# CableDyn driver output (dynamic; convergence quality is reported by status message)'
    CALL write_header(unit, channels)
    IF (opts%has_motion_file) THEN
      CALL write_model_row(unit, CD_ZERO, channels, lines, points, models, output_work, ErrStat, ErrMsg, motion, 1)
    ELSE
      CALL write_model_row(unit, CD_ZERO, channels, lines, points, models, output_work, ErrStat, ErrMsg)
    END IF
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      CALL close_dynamic_line_outputs(pos_units, ten_units)
      RETURN
    END IF
    CALL write_dynamic_line_outputs(CD_ZERO, lines, models, pos_units, ten_units, output_work, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      CALL close_dynamic_line_outputs(pos_units, ten_units)
      RETURN
    END IF
    CALL start_driver_progress(progress, nstep, opts%dtM)
    DO step = 1, nstep
      t = REAL(step, wp)*opts%dtM
      IF (opts%has_wave .OR. opts%has_current) THEN
        CALL update_wave_models(models, opts, t, hydro_work, es, em)
        IF (es /= CD_DECKDRV_OK) THEN
          CLOSE (unit)
          CALL close_dynamic_line_outputs(pos_units, ten_units)
          ErrStat = es
          ErrMsg = em
          RETURN
        END IF
      END IF
      IF (opts%has_motion_file) THEN
        CALL step_motion_models(models, lines, points, motion, step + 1, opts%dtM, &
                                opts%recovery_max_substeps, step_converged, stalled, n_iter, step_substeps, &
                                es, em, step_work)
      ELSE
        CALL step_held_models(models, opts%dtM, opts%recovery_max_substeps, step_converged, stalled, &
                              n_iter, step_substeps, es, em, step_work)
      END IF
      IF (step_substeps > 1) THEN
        recovery_event_count = recovery_event_count + 1
        recovery_max_substeps_used = MAX(recovery_max_substeps_used, step_substeps)
      END IF
      IF (es /= CD_DECKDRV_OK) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        converged = .FALSE.
        ErrStat = es
        ErrMsg = TRIM(em)//INSPECTION_NOTE
        RETURN
      END IF
      CALL update_dynamic_completion_quality(t, step_converged, stalled, miss_count, consecutive_miss, &
                                             max_consecutive_miss, first_miss_time, last_miss_time)
      IF (.NOT. step_converged .OR. stalled) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        CALL CD_Classify_Dynamic_Completion('dynamic run', nstep, miss_count, max_consecutive_miss, &
                                            first_miss_time, last_miss_time, converged, ErrStat, ErrMsg)
        RETURN
      END IF
      CALL check_models_plausibility(models, lines, opts%max_strain, t, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        converged = .FALSE.
        ErrMsg = TRIM(ErrMsg)//INSPECTION_NOTE
        RETURN
      END IF
      IF (opts%has_motion_file) THEN
        CALL write_model_row(unit, t, channels, lines, points, models, output_work, ErrStat, ErrMsg, motion, step + 1)
      ELSE
        CALL write_model_row(unit, t, channels, lines, points, models, output_work, ErrStat, ErrMsg)
      END IF
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        RETURN
      END IF
      CALL write_dynamic_line_outputs(t, lines, models, pos_units, ten_units, output_work, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        RETURN
      END IF
      CALL update_driver_progress(progress, step, t)
    END DO
    CLOSE (unit)
    CALL close_dynamic_line_outputs(pos_units, ten_units)
    CALL CD_Classify_Dynamic_Completion('dynamic run', nstep, miss_count, max_consecutive_miss, &
                                        first_miss_time, last_miss_time, converged, ErrStat, ErrMsg)
    IF (ErrStat == CD_DECKDRV_OK .AND. recovery_event_count > 0) THEN
      WRITE (output_unit, '(A,I0,A,I0,A)') '  Recovery audit: dynamic run subdivided ', &
        recovery_event_count, ' nominal interval(s); maximum substeps used=', recovery_max_substeps_used, '.'
    END IF
    IF (ErrStat == CD_DECKDRV_OK .AND. converged) CALL range_write(output_work%rset, out_root, ErrStat, ErrMsg)
  END SUBROUTINE write_dynamic_out

  SUBROUTINE write_system_dynamic_out(out_root, channels, lines, points, opts, system, converged, ErrStat, ErrMsg, &
                                      failures, bathymetry)
    CHARACTER(*), INTENT(IN) :: out_root
    CHARACTER(NAMELEN), INTENT(IN) :: channels(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    LOGICAL, INTENT(OUT) :: converged
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    ! FAILURE rows (mutable: rows flip failed=.TRUE. when they fire). Checked after
    ! every committed step against the row's time/tension thresholds.
    TYPE(DeckFailure), INTENT(INOUT), OPTIONAL :: failures(:)
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    INTEGER :: unit, ios, step, nstep, es, n_iter
    INTEGER, ALLOCATABLE :: pos_units(:), ten_units(:)
    INTEGER :: miss_count, consecutive_miss, max_consecutive_miss
    CHARACTER(LEN(out_root) + 8) :: path
    CHARACTER(256) :: em
    LOGICAL :: step_converged, stalled
    REAL(wp) :: t, first_miss_time, last_miss_time
    TYPE(HydroUpdateWorkspace) :: hydro_work
    TYPE(ModelOutputWorkspace) :: output_work
    TYPE(DriverProgress) :: progress

    converged = .TRUE.
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    nstep = NINT(opts%tmax/opts%dtM)
    CALL range_setup_planned(output_work%rset, lines, channels, opts, ErrStat, ErrMsg, system=system, &
                             bathymetry=bathymetry)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    miss_count = 0
    consecutive_miss = 0
    max_consecutive_miss = 0
    first_miss_time = CD_ZERO
    last_miss_time = CD_ZERO
    CALL open_dynamic_system_line_outputs(out_root, lines, system, pos_units, ten_units, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    path = TRIM(out_root)//'.out'
    OPEN (NEWUNIT=unit, FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
    IF (ios /= 0) THEN
      CALL close_dynamic_line_outputs(pos_units, ten_units)
      CALL fail(ErrStat, ErrMsg, 'cannot open output file: '//TRIM(path)); RETURN
    END IF
    WRITE (unit, '(A)') '# CableDyn driver output (dynamic points; convergence quality is reported by status message)'
    CALL write_header(unit, channels)
    CALL update_system_point_hydro(system, points, opts, CD_ZERO, hydro_work, es, em)
    IF (es /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      CALL close_dynamic_line_outputs(pos_units, ten_units)
      ErrStat = es
      ErrMsg = em
      RETURN
    END IF
    CALL update_system_line_hydro(system, opts, CD_ZERO, hydro_work, es, em, initial_condition=.TRUE.)
    IF (es /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      CALL close_dynamic_line_outputs(pos_units, ten_units)
      ErrStat = es
      ErrMsg = em
      RETURN
    END IF
    CALL write_system_model_row(unit, CD_ZERO, channels, lines, points, system, output_work, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      CALL close_dynamic_line_outputs(pos_units, ten_units)
      RETURN
    END IF
    CALL write_dynamic_system_line_outputs(CD_ZERO, lines, system, pos_units, ten_units, output_work, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      CALL close_dynamic_line_outputs(pos_units, ten_units)
      RETURN
    END IF
    CALL start_driver_progress(progress, nstep, opts%dtM)
    DO step = 1, nstep
      t = REAL(step, wp)*opts%dtM
      CALL update_system_point_hydro(system, points, opts, t, hydro_work, es, em)
      IF (es /= CD_DECKDRV_OK) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        ErrStat = es
        ErrMsg = em
        RETURN
      END IF
      CALL update_system_line_hydro(system, opts, t, hydro_work, es, em)
      IF (es /= CD_DECKDRV_OK) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        ErrStat = es
        ErrMsg = em
        RETURN
      END IF
      CALL CD_Step_System_DynamicPoints(system, opts%dtM, step_converged, stalled, n_iter, es, em)
      IF (es /= CD_SYSTEM_OK) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: dynamic point-system step failed: '//TRIM(em)
        RETURN
      END IF
      CALL update_dynamic_completion_quality(t, step_converged, stalled, miss_count, consecutive_miss, &
                                             max_consecutive_miss, first_miss_time, last_miss_time)
      IF (.NOT. step_converged .OR. stalled) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        CALL CD_Classify_Dynamic_Completion('dynamic point-system run', nstep, miss_count, &
                                            max_consecutive_miss, first_miss_time, last_miss_time, &
                                            converged, ErrStat, ErrMsg)
        RETURN
      END IF
      CALL CD_Check_System_Plausibility(system, opts%max_strain, t, ErrStat, ErrMsg, lines)
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        ErrMsg = TRIM(ErrMsg)//INSPECTION_NOTE
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        converged = .FALSE.
        RETURN
      END IF
      IF (PRESENT(failures)) THEN
        CALL check_and_fire_failures(system, lines, points, failures, t, es, em)
        IF (es /= CD_DECKDRV_OK) THEN
          CLOSE (unit)
          CALL close_dynamic_line_outputs(pos_units, ten_units)
          ErrStat = es
          ErrMsg = em
          RETURN
        END IF
      END IF
      CALL write_system_model_row(unit, t, channels, lines, points, system, output_work, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        RETURN
      END IF
      CALL write_dynamic_system_line_outputs(t, lines, system, pos_units, ten_units, output_work, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        RETURN
      END IF
      CALL update_driver_progress(progress, step, t)
    END DO
    CLOSE (unit)
    CALL close_dynamic_line_outputs(pos_units, ten_units)
    CALL CD_Classify_Dynamic_Completion('dynamic point-system run', nstep, miss_count, max_consecutive_miss, &
                                        first_miss_time, last_miss_time, converged, ErrStat, ErrMsg)
    IF (ErrStat == CD_DECKDRV_OK .AND. converged) CALL range_write(output_work%rset, out_root, ErrStat, ErrMsg)
  END SUBROUTINE write_system_dynamic_out

  SUBROUTINE CD_Fire_Deck_Failures(system, lines, points, failures, t, ErrStat, ErrMsg)
    !! Public wrapper over the standalone march's trigger for coupled callers (the
    !! OpenFAST aggregate facade): evaluate and fire every unfailed FAILURE row at
    !! committed time t against the given system. Identical semantics to the
    !! CD_Run_Deck_Driver march.
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckFailure), INTENT(INOUT) :: failures(:)
    REAL(wp), INTENT(IN) :: t
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    CALL check_and_fire_failures(system, lines, points, failures, t, ErrStat, ErrMsg)
  END SUBROUTINE CD_Fire_Deck_Failures

  SUBROUTINE CD_Replay_Deck_Failures(system, lines, points, failures, target_failed, ErrStat, ErrMsg)
    !! Checkpoint-restore replay: bring the failure TOPOLOGY of a freshly initialized
    !! system up to a restored set of fired flags, WITHOUT evaluating any trigger.
    !! For each row flagged fired in the checkpoint but not in this instance, the
    !! listed line ends still bound to the failing point detach onto the row's
    !! reserve (the same still-bound filter as the live trigger; an all-taken list
    !! is a no-op) and the row is marked failed. The restored state blocks are
    !! written AFTER this replay, so the kinematics the detach copies are interim
    !! and harmless. Un-firing (checkpoint says unfired, instance says fired) is
    !! impossible without a rebuild and fails closed.
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckFailure), INTENT(INOUT) :: failures(:)
    LOGICAL, INTENT(IN) :: target_failed(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: k, j, li, i, es, maxid
    INTEGER, ALLOCATABLE :: model_lines(:)
    CHARACTER(256) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (SIZE(target_failed) /= SIZE(failures)) THEN
      CALL fail(ErrStat, ErrMsg, 'failure-flag replay: flag count does not match the FAILURE rows')
      RETURN
    END IF
    maxid = 0
    DO i = 1, SIZE(points)
      maxid = MAX(maxid, points(i)%id)
    END DO
    DO k = 1, SIZE(failures)
      IF (failures(k)%failed .AND. .NOT. target_failed(k)) THEN
        CALL fail(ErrStat, ErrMsg, 'failure-flag replay cannot UN-fire a detached row (rebuild required)')
        RETURN
      END IF
      IF (.NOT. target_failed(k) .OR. failures(k)%failed) CYCLE
      IF (ALLOCATED(model_lines)) DEALLOCATE (model_lines)
      ALLOCATE (model_lines(SIZE(failures(k)%line_ids)))
      i = 0
      DO j = 1, SIZE(failures(k)%line_ids)
        li = deck_line_model_index(lines, failures(k)%line_ids(j))
        IF (li < 1) THEN
          CALL fail(ErrStat, ErrMsg, 'failure-flag replay references a line the system did not initialize')
          RETURN
        END IF
        IF (line_bound_to_point(system, li, failures(k)%point_id)) THEN
          i = i + 1
          model_lines(i) = li
        END IF
      END DO
      IF (i > 0) THEN
        CALL CD_Detach_System_LineEnds(system, failures(k)%point_id, model_lines(1:i), maxid + k, es, em)
        IF (es /= CD_SYSTEM_OK) THEN
          CALL fail(ErrStat, ErrMsg, 'failure-flag replay detach failed: '//TRIM(em))
          RETURN
        END IF
      END IF
      failures(k)%failed = .TRUE.
    END DO
  END SUBROUTINE CD_Replay_Deck_Failures

  SUBROUTINE check_and_fire_failures(system, lines, points, failures, t, ErrStat, ErrMsg)
    !! Evaluate every unfailed FAILURE row at a committed march step and fire the
    !! MoorDyn trigger: t >= FailTime (when > 0) OR the attachment-end tension of
    !! ANY listed line >= FailTen (when > 0). Firing detaches the listed line ends
    !! onto the row's pre-allocated reserve Free point (id = max deck point id +
    !! row index, the init rule).
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckFailure), INTENT(INOUT) :: failures(:)
    REAL(wp), INTENT(IN) :: t
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: k, j, li, ne, es, maxid, i
    INTEGER, ALLOCATABLE :: model_lines(:)
    REAL(wp), ALLOCATABLE :: tension(:)
    REAL(wp) :: ten_end
    LOGICAL :: fire
    CHARACTER(256) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    maxid = 0
    DO i = 1, SIZE(points)
      maxid = MAX(maxid, points(i)%id)
    END DO
    DO k = 1, SIZE(failures)
      IF (failures(k)%failed) CYCLE
      fire = failures(k)%fail_time > CD_ZERO .AND. t >= failures(k)%fail_time
      IF (.NOT. fire .AND. failures(k)%fail_ten > CD_ZERO) THEN
        DO j = 1, SIZE(failures(k)%line_ids)
          li = deck_line_model_index(lines, failures(k)%line_ids(j))
          IF (li < 1) THEN
            CALL fail(ErrStat, ErrMsg, 'FAILURE references a line the system did not initialize'); RETURN
          END IF
          ! A line end an earlier row already detached from this point no longer
          ! reads as this row's attachment: skip it (MoorDyn ignores duplicate
          ! failure configurations).
          IF (.NOT. line_bound_to_point(system, li, failures(k)%point_id)) CYCLE
          ne = CD_System_Line_NElem(system, li, es, em)
          IF (es /= CD_SYSTEM_OK) THEN
            CALL fail_solve(ErrStat, ErrMsg, 'FAILURE tension probe (element count): '//TRIM(em)); RETURN
          END IF
          ! Re-sized per listed line: rows may list several lines with different meshes.
          IF (ALLOCATED(tension)) THEN
            IF (SIZE(tension) /= ne) DEALLOCATE (tension)
          END IF
          IF (.NOT. ALLOCATED(tension)) ALLOCATE (tension(ne))
          CALL CD_Get_System_Line_Tension(system, li, tension, es, em)
          IF (es /= CD_SYSTEM_OK) THEN
            CALL fail_solve(ErrStat, ErrMsg, 'FAILURE tension probe: '//TRIM(em)); RETURN
          END IF
          ! Attachment end: deck nodeB binds the line's END_A (first node, element
          ! 1); deck nodeA binds END_B (last node, element ne) -- the init_deck
          ! binding convention.
          IF (lines(li)%nodeB == failures(k)%point_id) THEN
            ten_end = tension(1)
          ELSE
            ten_end = tension(ne)
          END IF
          IF (ten_end >= failures(k)%fail_ten) THEN
            fire = .TRUE.
            EXIT
          END IF
        END DO
      END IF
      IF (.NOT. fire) CYCLE
      ! Detach only the line ends STILL bound to the failing point: an earlier row
      ! (a duplicate or an overlapping list) may already have taken some or all of
      ! them, and MoorDyn ignores duplicate failure configurations rather than
      ! erroring. A row whose whole list is already gone completes as a no-op.
      IF (ALLOCATED(model_lines)) DEALLOCATE (model_lines)
      ALLOCATE (model_lines(SIZE(failures(k)%line_ids)))
      i = 0
      DO j = 1, SIZE(failures(k)%line_ids)
        li = deck_line_model_index(lines, failures(k)%line_ids(j))
        IF (li < 1) THEN
          CALL fail(ErrStat, ErrMsg, 'FAILURE references a line the system did not initialize'); RETURN
        END IF
        IF (line_bound_to_point(system, li, failures(k)%point_id)) THEN
          i = i + 1
          model_lines(i) = li
        END IF
      END DO
      IF (i == 0) THEN
        failures(k)%failed = .TRUE.
        WRITE (*, '(A,I0,A,F0.4,A)') 'CableDyn: FAILURE ', failures(k)%fail_id, ' at t = ', t, &
          ' s duplicates an earlier detach -- ignored'
        CYCLE
      END IF
      CALL CD_Detach_System_LineEnds(system, failures(k)%point_id, model_lines(1:i), maxid + k, es, em)
      IF (es /= CD_SYSTEM_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'FAILURE detach failed: '//TRIM(em)); RETURN
      END IF
      failures(k)%failed = .TRUE.
      WRITE (*, '(A,I0,A,F0.4,A,I0)') 'CableDyn: FAILURE ', failures(k)%fail_id, ' triggered at t = ', t, &
        ' s, detaching line end(s) onto reserve point ', maxid + k
    END DO
  END SUBROUTINE check_and_fire_failures

  LOGICAL FUNCTION line_bound_to_point(system, line_index, point_id) RESULT(bound)
    !! Whether either end of the model line is currently bound to the point.
    TYPE(CD_SystemType), INTENT(IN) :: system
    INTEGER, INTENT(IN) :: line_index, point_id
    INTEGER :: k
    bound = .FALSE.
    IF (.NOT. ALLOCATED(system%bindings)) RETURN
    DO k = 1, SIZE(system%bindings)
      IF (system%bindings(k)%line_index == line_index .AND. system%bindings(k)%point_id == point_id) THEN
        bound = .TRUE.
        RETURN
      END IF
    END DO
  END FUNCTION line_bound_to_point

  INTEGER FUNCTION deck_line_model_index(lines, line_id) RESULT(idx)
    !! Model index of a deck line id: lines initialize in deck order, so the model
    !! index is the position in the parsed lines array.
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    INTEGER, INTENT(IN) :: line_id
    INTEGER :: i
    idx = 0
    DO i = 1, SIZE(lines)
      IF (lines(i)%id == line_id) idx = i
    END DO
  END FUNCTION deck_line_model_index

  SUBROUTINE write_rigid6_dynamic_out(out_root, channels, bodies, lines, points, opts, system, &
                                      converged, ErrStat, ErrMsg, bathymetry, rod_types, rods, failures)
    !! March a point-connected system whose Body<N> points are driven by Rigid6 body states.
    CHARACTER(*), INTENT(IN) :: out_root
    CHARACTER(NAMELEN), INTENT(IN) :: channels(:)
    TYPE(DeckBody), INTENT(IN) :: bodies(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    LOGICAL, INTENT(OUT) :: converged
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    ! rods fixed to the bodies (RODS type Body<N>)
    TYPE(DeckRodType), INTENT(IN), OPTIONAL :: rod_types(:)
    TYPE(DeckRod), INTENT(IN), OPTIONAL :: rods(:)
    ! FAILURE rows, checked after every committed step (a fired row detaches its line ends onto
    ! a reserve free point, which step_rigid6_once then integrates)
    TYPE(DeckFailure), INTENT(INOUT), OPTIONAL :: failures(:)

    TYPE(RigidBodyState), ALLOCATABLE :: rigid(:)
    INTEGER :: unit, ios, step, nstep, es, n_iter
    INTEGER, ALLOCATABLE :: pos_units(:), ten_units(:)
    INTEGER :: miss_count, consecutive_miss, max_consecutive_miss
    CHARACTER(LEN(out_root) + 8) :: path
    CHARACTER(256) :: em
    LOGICAL :: step_converged, stalled
    REAL(wp) :: t, first_miss_time, last_miss_time
    TYPE(HydroUpdateWorkspace) :: hydro_work
    TYPE(RigidStepWorkspace) :: step_work
    TYPE(ModelOutputWorkspace) :: output_work
    TYPE(MotionTable) :: motion
    TYPE(DriverProgress) :: progress
    LOGICAL :: use_prescribed_rigid6

    converged = .TRUE.
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    miss_count = 0
    consecutive_miss = 0
    max_consecutive_miss = 0
    first_miss_time = CD_ZERO
    last_miss_time = CD_ZERO
    use_prescribed_rigid6 = opts%has_motion_file
    CALL init_rigid6_states(bodies, points, rigid, ErrStat, ErrMsg, rod_types, rods)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    IF (use_prescribed_rigid6) THEN
      CALL read_motion_file(opts%motion_file, points, opts, motion, ErrStat, ErrMsg, include_body_points=.TRUE.)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL set_prescribed_rigid6_states(points, motion, 1, rigid, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL apply_rigid6_states_to_system(system, points, rigid, step_work, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END IF

    nstep = NINT(opts%tmax/opts%dtM)
    CALL range_setup_planned(output_work%rset, lines, channels, opts, ErrStat, ErrMsg, system=system, &
                             bathymetry=bathymetry)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    path = TRIM(out_root)//'.out'
    OPEN (NEWUNIT=unit, FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open output file: '//TRIM(path)); RETURN
    END IF
    WRITE (unit, '(A)') '# CableDyn driver output (Rigid6 dynamic; convergence quality is reported by status message)'
    CALL write_header(unit, channels)
    CALL open_dynamic_system_line_outputs(out_root, lines, system, pos_units, ten_units, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      RETURN
    END IF
    CALL update_system_line_hydro(system, opts, CD_ZERO, hydro_work, es, em, initial_condition=.TRUE.)
    IF (es /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      CALL close_dynamic_line_outputs(pos_units, ten_units)
      ErrStat = es
      ErrMsg = em
      RETURN
    END IF
    CALL write_system_model_row(unit, CD_ZERO, channels, lines, points, system, output_work, ErrStat, ErrMsg, &
                                rigid=rigid, opts=opts, bathymetry=bathymetry)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      CALL close_dynamic_line_outputs(pos_units, ten_units)
      RETURN
    END IF
    CALL write_dynamic_system_line_outputs(CD_ZERO, lines, system, pos_units, ten_units, output_work, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      CALL close_dynamic_line_outputs(pos_units, ten_units)
      RETURN
    END IF
    CALL start_driver_progress(progress, nstep, opts%dtM)
    DO step = 1, nstep
      t = REAL(step, wp)*opts%dtM
      IF (use_prescribed_rigid6) THEN
        CALL step_prescribed_rigid6_system(system, points, opts, motion, rigid, step + 1, t, opts%dtM, &
                                           step_converged, stalled, n_iter, es, em, step_work, hydro_work)
      ELSE
        CALL update_system_line_hydro(system, opts, t, hydro_work, es, em)
        IF (es /= CD_DECKDRV_OK) THEN
          CLOSE (unit)
          CALL close_dynamic_line_outputs(pos_units, ten_units)
          ErrStat = es
          ErrMsg = em
          RETURN
        END IF
        CALL step_rigid6_system(system, points, opts, rigid, t, opts%dtM, step_converged, stalled, n_iter, &
                                es, em, step_work, bathymetry)
      END IF
      IF (es /= CD_DECKDRV_OK) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        ErrStat = es
        ErrMsg = em
        RETURN
      END IF
      CALL update_dynamic_completion_quality(t, step_converged, stalled, miss_count, consecutive_miss, &
                                             max_consecutive_miss, first_miss_time, last_miss_time)
      IF (.NOT. step_converged .OR. stalled) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        CALL CD_Classify_Dynamic_Completion('Rigid6 dynamic run', nstep, miss_count, max_consecutive_miss, &
                                            first_miss_time, last_miss_time, converged, ErrStat, ErrMsg)
        RETURN
      END IF
      CALL CD_Check_System_Plausibility(system, opts%max_strain, t, ErrStat, ErrMsg, lines)
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        ErrMsg = TRIM(ErrMsg)//INSPECTION_NOTE
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        converged = .FALSE.
        RETURN
      END IF
      IF (PRESENT(failures)) THEN
        CALL check_and_fire_failures(system, lines, points, failures, t, es, em)
        IF (es /= CD_DECKDRV_OK) THEN
          CLOSE (unit)
          CALL close_dynamic_line_outputs(pos_units, ten_units)
          ErrStat = es
          ErrMsg = em
          RETURN
        END IF
      END IF
      CALL write_system_model_row(unit, t, channels, lines, points, system, output_work, ErrStat, ErrMsg, &
                                  rigid=rigid, opts=opts, bathymetry=bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        RETURN
      END IF
      CALL write_dynamic_system_line_outputs(t, lines, system, pos_units, ten_units, output_work, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        RETURN
      END IF
      CALL update_driver_progress(progress, step, t)
    END DO
    CLOSE (unit)
    CALL close_dynamic_line_outputs(pos_units, ten_units)
    CALL CD_Classify_Dynamic_Completion('Rigid6 dynamic run', nstep, miss_count, max_consecutive_miss, &
                                        first_miss_time, last_miss_time, converged, ErrStat, ErrMsg)
    IF (ErrStat == CD_DECKDRV_OK .AND. converged) CALL range_write(output_work%rset, out_root, ErrStat, ErrMsg)
  END SUBROUTINE write_rigid6_dynamic_out

  SUBROUTINE write_rod_dynamic_out(out_root, channels, rod_types, rods, lines, points, opts, system, &
                                   converged, ErrStat, ErrMsg, bathymetry)
    !! March a point-connected system whose Rod<N>A/B points are driven by rigid rod states.
    CHARACTER(*), INTENT(IN) :: out_root
    CHARACTER(NAMELEN), INTENT(IN) :: channels(:)
    TYPE(DeckRodType), INTENT(IN) :: rod_types(:)
    TYPE(DeckRod), INTENT(IN) :: rods(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    LOGICAL, INTENT(OUT) :: converged
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    TYPE(RodState), ALLOCATABLE :: rod_state(:)
    INTEGER :: unit, ios, step, nstep, es, n_iter
    INTEGER, ALLOCATABLE :: pos_units(:), ten_units(:)
    INTEGER, ALLOCATABLE :: rod_pos_units(:)
    INTEGER :: miss_count, consecutive_miss, max_consecutive_miss
    CHARACTER(LEN(out_root) + 8) :: path
    CHARACTER(256) :: em
    LOGICAL :: step_converged, stalled
    REAL(wp) :: t, first_miss_time, last_miss_time
    TYPE(HydroUpdateWorkspace) :: hydro_work
    TYPE(RodStepWorkspace) :: step_work
    TYPE(ModelOutputWorkspace) :: output_work
    TYPE(MotionTable) :: motion
    TYPE(DriverProgress) :: progress
    LOGICAL :: use_prescribed_rods

    converged = .TRUE.
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    miss_count = 0
    consecutive_miss = 0
    max_consecutive_miss = 0
    first_miss_time = CD_ZERO
    last_miss_time = CD_ZERO
    use_prescribed_rods = opts%has_motion_file
    CALL init_rod_states(rod_types, rods, points, rod_state, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    IF (use_prescribed_rods) THEN
      CALL read_motion_file(opts%motion_file, points, opts, motion, ErrStat, ErrMsg, include_rod_points=.TRUE.)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL set_prescribed_rod_states(points, motion, 1, rod_state, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL apply_rod_states_to_system(system, points, rod_state, step_work, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END IF

    nstep = NINT(opts%tmax/opts%dtM)
    CALL range_setup_planned(output_work%rset, lines, channels, opts, ErrStat, ErrMsg, system=system, &
                             bathymetry=bathymetry)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    path = TRIM(out_root)//'.out'
    OPEN (NEWUNIT=unit, FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open output file: '//TRIM(path))
      RETURN
    END IF
    WRITE (unit, '(A)') '# CableDyn driver output (rod dynamic; convergence quality is reported by status message)'
    CALL write_header(unit, channels)
    CALL open_dynamic_system_line_outputs(out_root, lines, system, pos_units, ten_units, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      RETURN
    END IF
    CALL open_dynamic_rod_outputs(out_root, rods, rod_pos_units, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      CALL close_dynamic_line_outputs(pos_units, ten_units)
      RETURN
    END IF
    CALL update_system_line_hydro(system, opts, CD_ZERO, hydro_work, es, em, initial_condition=.TRUE.)
    IF (es /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      CALL close_dynamic_line_outputs(pos_units, ten_units)
      CALL close_dynamic_rod_outputs(rod_pos_units)
      ErrStat = es
      ErrMsg = em
      RETURN
    END IF
    CALL write_system_model_row(unit, CD_ZERO, channels, lines, points, system, output_work, ErrStat, ErrMsg, &
                                rods=rod_state, opts=opts, bathymetry=bathymetry)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      CALL close_dynamic_line_outputs(pos_units, ten_units)
      CALL close_dynamic_rod_outputs(rod_pos_units)
      RETURN
    END IF
    CALL write_dynamic_system_line_outputs(CD_ZERO, lines, system, pos_units, ten_units, output_work, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      CALL close_dynamic_line_outputs(pos_units, ten_units)
      CALL close_dynamic_rod_outputs(rod_pos_units)
      RETURN
    END IF
    CALL write_dynamic_rod_outputs(CD_ZERO, rods, rod_state, rod_pos_units, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      CALL close_dynamic_line_outputs(pos_units, ten_units)
      CALL close_dynamic_rod_outputs(rod_pos_units)
      RETURN
    END IF
    CALL start_driver_progress(progress, nstep, opts%dtM)
    DO step = 1, nstep
      t = REAL(step, wp)*opts%dtM
      IF (use_prescribed_rods) THEN
        CALL step_prescribed_rod_system(system, points, opts, motion, rod_state, step + 1, t, opts%dtM, &
                                        step_converged, stalled, n_iter, es, em, step_work, hydro_work, bathymetry)
      ELSE
        CALL update_system_line_hydro(system, opts, t, hydro_work, es, em)
        IF (es /= CD_DECKDRV_OK) THEN
          CLOSE (unit)
          CALL close_dynamic_line_outputs(pos_units, ten_units)
          CALL close_dynamic_rod_outputs(rod_pos_units)
          ErrStat = es
          ErrMsg = em
          RETURN
        END IF
        CALL step_rod_system(system, points, opts, rod_state, t, opts%dtM, step_converged, stalled, n_iter, &
                             es, em, step_work, bathymetry)
      END IF
      IF (es /= CD_DECKDRV_OK) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        CALL close_dynamic_rod_outputs(rod_pos_units)
        ErrStat = es
        ErrMsg = em
        RETURN
      END IF
      CALL update_dynamic_completion_quality(t, step_converged, stalled, miss_count, consecutive_miss, &
                                             max_consecutive_miss, first_miss_time, last_miss_time)
      IF (.NOT. step_converged .OR. stalled) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        CALL close_dynamic_rod_outputs(rod_pos_units)
        CALL CD_Classify_Dynamic_Completion('rod dynamic run', nstep, miss_count, max_consecutive_miss, &
                                            first_miss_time, last_miss_time, converged, ErrStat, ErrMsg)
        RETURN
      END IF
      CALL CD_Check_System_Plausibility(system, opts%max_strain, t, ErrStat, ErrMsg, lines)
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        ErrMsg = TRIM(ErrMsg)//INSPECTION_NOTE
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        CALL close_dynamic_rod_outputs(rod_pos_units)
        converged = .FALSE.
        RETURN
      END IF
      CALL write_system_model_row(unit, t, channels, lines, points, system, output_work, ErrStat, ErrMsg, &
                                  rods=rod_state, opts=opts, bathymetry=bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        CALL close_dynamic_rod_outputs(rod_pos_units)
        RETURN
      END IF
      CALL write_dynamic_system_line_outputs(t, lines, system, pos_units, ten_units, output_work, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        CALL close_dynamic_rod_outputs(rod_pos_units)
        RETURN
      END IF
      CALL write_dynamic_rod_outputs(t, rods, rod_state, rod_pos_units, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        CALL close_dynamic_rod_outputs(rod_pos_units)
        RETURN
      END IF
      CALL update_driver_progress(progress, step, t)
    END DO
    CLOSE (unit)
    CALL close_dynamic_line_outputs(pos_units, ten_units)
    CALL close_dynamic_rod_outputs(rod_pos_units)
    CALL CD_Classify_Dynamic_Completion('rod dynamic run', nstep, miss_count, max_consecutive_miss, &
                                        first_miss_time, last_miss_time, converged, ErrStat, ErrMsg)
    IF (ErrStat == CD_DECKDRV_OK .AND. converged) CALL range_write(output_work%rset, out_root, ErrStat, ErrMsg)
  END SUBROUTINE write_rod_dynamic_out

  SUBROUTINE init_rod_states(rod_types, rods, points, rod_state, ErrStat, ErrMsg, no_points)
    !! Runtime rod states from the deck rods. no_points: rods without line attachment points
    !! (rods fixed to a body, pinned rods, decks without lines).
    TYPE(DeckRodType), INTENT(IN) :: rod_types(:)
    TYPE(DeckRod), INTENT(IN) :: rods(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(RodState), ALLOCATABLE, INTENT(OUT) :: rod_state(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    LOGICAL, INTENT(IN), OPTIONAL :: no_points
    LOGICAL :: need_points

    INTEGER :: i, irt
    REAL(wp) :: radius, axis(3)

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    ALLOCATE (rod_state(SIZE(rods)))
    DO i = 1, SIZE(rods)
      irt = rods(i)%rtype
      rod_state(i)%rod_id = rods(i)%id
      rod_state(i)%is_free = TRIM(rods(i)%rod_type) == 'free'
      rod_state(i)%is_prescribed = TRIM(rods(i)%rod_type) == 'coupled' .OR. TRIM(rods(i)%rod_type) == 'vessel'
      rod_state(i)%is_pinned = TRIM(rods(i)%rod_type) == 'pinned'
      rod_state(i)%pin = rods(i)%end_a
      rod_state(i)%point_a_index = rod_point_index(points, rods(i)%id, 1)
      rod_state(i)%point_b_index = rod_point_index(points, rods(i)%id, 2)
      need_points = .TRUE.
      IF (PRESENT(no_points)) need_points = .NOT. no_points
      IF (need_points .AND. (rod_state(i)%point_a_index == 0 .OR. rod_state(i)%point_b_index == 0)) THEN
        CALL fail(ErrStat, ErrMsg, 'Rod state initialization requires Rod<N>A and Rod<N>B points')
        RETURN
      END IF
      rod_state(i)%length = SQRT(SUM((rods(i)%end_b - rods(i)%end_a)**2))
      rod_state(i)%half_length = 0.5_wp*rod_state(i)%length
      rod_state(i)%r = 0.5_wp*(rods(i)%end_a + rods(i)%end_b)
      axis = (rods(i)%end_b - rods(i)%end_a)/rod_state(i)%length
      rod_state(i)%rot_mat = rod_orientation_from_axis(axis)
      rod_state(i)%diam = rod_types(irt)%diam
      rod_state(i)%mass = rod_types(irt)%mass*rod_state(i)%length
      rod_state(i)%volume = QUARTER_PI*rod_state(i)%diam**2*rod_state(i)%length
      rod_state(i)%cdn = rod_types(irt)%cdn
      rod_state(i)%can = rod_types(irt)%can
      rod_state(i)%cdt = rod_types(irt)%cdt
      rod_state(i)%cat = rod_types(irt)%cat
      rod_state(i)%cdend = rod_types(irt)%cdend
      rod_state(i)%caend = rod_types(irt)%caend
      rod_state(i)%nsegs = MAX(1, rods(i)%nsegs)
      radius = 0.5_wp*rod_state(i)%diam
      rod_state(i)%inertia(1) = 0.5_wp*rod_state(i)%mass*radius*radius
      rod_state(i)%inertia(2) = rod_state(i)%mass*(3.0_wp*radius*radius + rod_state(i)%length**2)/12.0_wp
      rod_state(i)%inertia(3) = rod_state(i)%inertia(2)
    END DO
  END SUBROUTINE init_rod_states

  SUBROUTINE ensure_rod_step_workspace(work, ncoupled, nrod, npoint)
    TYPE(RodStepWorkspace), INTENT(INOUT) :: work
    INTEGER, INTENT(IN) :: ncoupled, nrod, npoint
    LOGICAL :: need_q, need_rods, need_points

    need_q = .NOT. ALLOCATED(work%q)
    IF (.NOT. need_q) need_q = SIZE(work%q) < ncoupled
    IF (need_q) THEN
      IF (ALLOCATED(work%q)) DEALLOCATE (work%q, work%v, work%a, work%loads)
      ALLOCATE (work%q(ncoupled), work%v(ncoupled), work%a(ncoupled), work%loads(ncoupled))
    END IF
    CALL ensure_square_workspace(work%dload_da, ncoupled)
    need_rods = .NOT. ALLOCATED(work%old_rods)
    IF (.NOT. need_rods) need_rods = SIZE(work%old_rods) /= nrod
    IF (need_rods) THEN
      IF (ALLOCATED(work%old_rods)) DEALLOCATE (work%old_rods)
      ALLOCATE (work%old_rods(nrod))
    END IF
    need_points = .NOT. ALLOCATED(work%old_points)
    IF (.NOT. need_points) need_points = SIZE(work%old_points) /= npoint
    IF (need_points) THEN
      IF (ALLOCATED(work%old_points)) DEALLOCATE (work%old_points)
      ALLOCATE (work%old_points(npoint))
    END IF
  END SUBROUTINE ensure_rod_step_workspace

  SUBROUTINE ensure_rigid_step_workspace(work, ncoupled, nbody, npoint)
    TYPE(RigidStepWorkspace), INTENT(INOUT) :: work
    INTEGER, INTENT(IN) :: ncoupled, nbody, npoint
    LOGICAL :: need_q, need_env, need_rigid, need_points

    need_q = .NOT. ALLOCATED(work%q)
    IF (.NOT. need_q) need_q = SIZE(work%q) < ncoupled
    IF (need_q) THEN
      IF (ALLOCATED(work%q)) DEALLOCATE (work%q, work%v, work%a, work%loads)
      ALLOCATE (work%q(ncoupled), work%v(ncoupled), work%a(ncoupled), work%loads(ncoupled))
    END IF
    CALL ensure_square_workspace(work%dload_da, ncoupled)
    need_env = .NOT. ALLOCATED(work%f_env)
    IF (.NOT. need_env) need_env = SIZE(work%f_env, 2) /= nbody
    IF (need_env) THEN
      IF (ALLOCATED(work%f_env)) DEALLOCATE (work%f_env, work%mass_eff)
      ALLOCATE (work%f_env(3, nbody), work%mass_eff(nbody))
    END IF
    need_rigid = .NOT. ALLOCATED(work%old_rigid)
    IF (.NOT. need_rigid) need_rigid = SIZE(work%old_rigid) /= nbody
    IF (need_rigid) THEN
      IF (ALLOCATED(work%old_rigid)) DEALLOCATE (work%old_rigid)
      ALLOCATE (work%old_rigid(nbody))
    END IF
    need_points = .NOT. ALLOCATED(work%old_points)
    IF (.NOT. need_points) need_points = SIZE(work%old_points) /= npoint
    IF (need_points) THEN
      IF (ALLOCATED(work%old_points)) DEALLOCATE (work%old_points)
      ALLOCATE (work%old_points(npoint))
    END IF
  END SUBROUTINE ensure_rigid_step_workspace

  SUBROUTINE ensure_square_workspace(a, n)
    !! Keep a dense n x n workspace allocated at exactly that shape.
    REAL(wp), ALLOCATABLE, INTENT(INOUT) :: a(:, :)
    INTEGER, INTENT(IN) :: n
    IF (ALLOCATED(a)) THEN
      IF (SIZE(a, 1) == n .AND. SIZE(a, 2) == n) RETURN
      DEALLOCATE (a)
    END IF
    ALLOCATE (a(n, n))
  END SUBROUTINE ensure_square_workspace

  SUBROUTINE rigid_coupled_acceleration(dload_da, dt, a_points, bases, arms, mass_eff, added6, inertia_body, &
                                        rot_mat, omega, f_global, m_global, dv0, dfo_dv, acc, alpha, &
                                        ErrStat, ErrMsg, pin_arm, m6_out, rhs_out)
    !! End-of-step rigid-body (rod or Rigid6) accelerations x = (acc, alpha) of the staggered
    !! central-difference corrector of step_rigid6_system / step_rod_system. The loads were
    !! evaluated at the predictor, whose position is the final position (Newmark beta = 0) and
    !! whose velocity differs from the final one by dv = dv0 + gamma dt x, dv0 = -gamma dt x_n
    !! (gamma = CD_RIGID_NEWMARK_GAMMA, x_n the previous step's acceleration).
    !!
    !! Attached line ends: the end-of-step line loads f_c (from the line step with the
    !! predicted fairlead motion) carry the end-node inertia at the predicted attachment
    !! accelerations a_c = a_points; it is moved to the actual ones with D = df_c/da_c
    !! (end-node structural + added mass): f_c+ = f_c + D (a_c+ - a_c). This implicit
    !! inertia term is exact (the end node is prescribed) and is what keeps a light body
    !! stable against the added-mass instability. The line velocity and position derivatives
    !! are deliberately NOT used: they are the end-segment damping and stiffness with the
    !! adjacent free node held fixed, while in the line step that node follows the end. Such a
    !! frozen-node (far too stiff) linearization in the corrector lags the body acceleration
    !! and pumps energy into the body-line modes (a dt-dependent negative damping); the line's
    !! actual response is already in f_c. With the arm map T_i = [I, -[arm_i]x],
    !! a_c_i+ = T_i x + c_i (c_i = omega x (omega x arm_i)).
    !!
    !! Body loads: f_global/m_global (global frame, about the reference point) hold f_c and
    !! every other body load at the predictor; dfo_dv is the 6x6 derivative of the non-line
    !! body loads (hydrodynamic drag, seabed-contact damping) w.r.t. (velocity, omega), exact
    !! for those loads and applied implicitly. Altogether
    !!   (M_body - sum_ij T_i^T D_ij T_j - gamma dt B) x
    !!     = F + sum_ij T_i^T D_ij (c_j - a_c_j) + B dv0,   B = dfo_dv.
    !! The gyroscopic moment of the structural inertia is added here. Attachments with
    !! bases(i) < 0 carry no line. M_body = diag(mass_eff I, R I_body R^T) + added6, where
    !! mass_eff is an isotropic translational mass and added6 a full 6x6 hydrodynamic
    !! added-mass matrix about the reference point (global frame; zero when not used).
    REAL(wp), INTENT(IN) :: dload_da(:, :), dt, a_points(:)
    INTEGER, INTENT(IN) :: bases(:)
    REAL(wp), INTENT(IN) :: arms(:, :), mass_eff, added6(6, 6), inertia_body(3), rot_mat(3, 3)
    REAL(wp), INTENT(IN) :: omega(3)
    REAL(wp), INTENT(IN) :: f_global(3), m_global(3)
    REAL(wp), INTENT(IN) :: dv0(6), dfo_dv(6, 6)
    REAL(wp), INTENT(OUT) :: acc(3), alpha(3)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    ! pin_arm: the reference point turns about a fixed pin at -pin_arm from it (a pinned rod):
    ! with x = T y + b, T = [-[r]x; I], b = [w x (w x r); 0], the rotational acceleration y solves
    ! T^T m6 T y = T^T (rhs - m6 b)
    REAL(wp), INTENT(IN), OPTIONAL :: pin_arm(3)
    ! m6_out/rhs_out: return the assembled system m6 x = rhs instead of solving it (the pinned-
    ! child group solve of mb_group_solve); acc and alpha are then zero
    REAL(wp), INTENT(OUT), OPTIONAL :: m6_out(6, 6), rhs_out(6)

    INTEGER :: i, j, k, bi, bj
    REAL(wp) :: m6(6, 6), rhs(6), inertia_g(3, 3), s_i(3, 3), s_j(3, 3), d_ij(3, 3), g(3), c_j(3)
    REAL(wp) :: t63(6, 3), b6(6), y(3)
    LOGICAL :: ok

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    acc = CD_ZERO
    alpha = CD_ZERO
    inertia_g = CD_ZERO
    DO k = 1, 3
      inertia_g(k, k) = inertia_body(k)
    END DO
    inertia_g = MATMUL(rot_mat, MATMUL(inertia_g, TRANSPOSE(rot_mat)))
    m6 = CD_ZERO
    DO k = 1, 3
      m6(k, k) = mass_eff
    END DO
    m6(4:6, 4:6) = inertia_g
    m6 = m6 + added6 - CD_RIGID_NEWMARK_GAMMA*dt*dfo_dv
    rhs(1:3) = f_global
    rhs(4:6) = m_global - cross3(omega, MATMUL(inertia_g, omega))
    rhs = rhs + MATMUL(dfo_dv, dv0)
    DO i = 1, SIZE(bases)
      bi = bases(i)
      IF (bi < 0) CYCLE
      s_i = skew3(arms(:, i))
      DO j = 1, SIZE(bases)
        bj = bases(j)
        IF (bj < 0) CYCLE
        d_ij = dload_da(bi + 1:bi + 3, bj + 1:bj + 3)
        IF (MAXVAL(ABS(d_ij)) <= CD_ZERO) CYCLE
        s_j = skew3(arms(:, j))
        ! T_i^T D_ij T_j with T = [I, -S], S = [arm]x (so T^T f = (f, arm x f)).
        m6(1:3, 1:3) = m6(1:3, 1:3) - d_ij
        m6(1:3, 4:6) = m6(1:3, 4:6) + MATMUL(d_ij, s_j)
        m6(4:6, 1:3) = m6(4:6, 1:3) - MATMUL(s_i, d_ij)
        m6(4:6, 4:6) = m6(4:6, 4:6) + MATMUL(s_i, MATMUL(d_ij, s_j))
        c_j = cross3(omega, cross3(omega, arms(:, j)))
        g = MATMUL(d_ij, c_j - a_points(bj + 1:bj + 3))
        rhs(1:3) = rhs(1:3) + g
        rhs(4:6) = rhs(4:6) + cross3(arms(:, i), g)
      END DO
    END DO
    ! A diverged attached line (or body load) reaches this solve as non-finite loads or
    ! load derivatives; name that condition instead of reporting a singular matrix.
    IF (.NOT. (ALL(IEEE_IS_FINITE(m6)) .AND. ALL(IEEE_IS_FINITE(rhs)))) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: rigid-body step received non-finite loads or load derivatives '// &
               '(an attached line or a body load diverged)'
      RETURN
    END IF
    IF (PRESENT(m6_out) .AND. PRESENT(rhs_out)) THEN
      m6_out = m6
      rhs_out = rhs
      RETURN
    END IF
    IF (PRESENT(pin_arm)) THEN
      t63 = CD_ZERO
      t63(1:3, :) = -skew3(pin_arm)
      DO k = 1, 3
        t63(3 + k, k) = CD_ONE
      END DO
      b6 = CD_ZERO
      b6(1:3) = cross3(omega, cross3(omega, pin_arm))
      CALL solve_sym3(MATMUL(TRANSPOSE(t63), MATMUL(m6, t63)), MATMUL(TRANSPOSE(t63), rhs - MATMUL(m6, b6)), y, ok)
      IF (.NOT. ok) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: pinned rod rotational inertia is singular'
        RETURN
      END IF
      alpha = y
      acc = MATMUL(t63(1:3, :), y) + b6(1:3)
      RETURN
    END IF
    CALL solve_rigid6x6(m6, rhs, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    acc = rhs(1:3)
    alpha = rhs(4:6)
  END SUBROUTINE rigid_coupled_acceleration

  LOGICAL FUNCTION is_object_channel(lo) RESULT(yes)
    !! Body<N>... and Rod<N>... output channels (MoorDyn-F names).
    CHARACTER(*), INTENT(IN) :: lo
    yes = .FALSE.
    IF (starts_with(lo, 'body') .AND. LEN_TRIM(lo) > 4) yes = VERIFY(lo(5:5), '0123456789') == 0
    IF (starts_with(lo, 'rod') .AND. LEN_TRIM(lo) > 3) yes = yes .OR. VERIFY(lo(4:4), '0123456789') == 0
  END FUNCTION is_object_channel

  SUBROUTINE parse_object_channel(ch, is_body, obj_id, node, qty)
    !! Body<N><q> and Rod<N><q> (whole object) or Rod<N>N<k>P{x,y,z} (node k, 0 = End A,
    !! NumSegs = End B) -> is_body, N, node (-1 when absent) and the quantity code qty of
    !! OBJ_QTY: 1-3 P, 4-6 R (rotation angles), 7-9 V, 10-12 RV, 13-15 A, 16-18 RA, 19-21 F,
    !! 22-24 M, 25 TenA, 26 TenB, 27 Sub. qty = 0 when malformed (a node takes P only).
    CHARACTER(*), INTENT(IN) :: ch
    LOGICAL, INTENT(OUT) :: is_body
    INTEGER, INTENT(OUT) :: obj_id, node, qty
    CHARACTER(NAMELEN) :: lo, rest
    INTEGER :: i, k, n
    lo = to_lower(TRIM(ch))
    obj_id = 0
    node = -1
    qty = 0
    is_body = starts_with(lo, 'body')
    k = 4
    IF (is_body) k = 5
    n = LEN_TRIM(lo)
    i = k
    DO WHILE (i <= n)
      IF (VERIFY(lo(i:i), '0123456789') /= 0) EXIT
      IF (obj_id > 99999999) RETURN
      obj_id = obj_id*10 + (IACHAR(lo(i:i)) - IACHAR('0'))
      i = i + 1
    END DO
    IF (i == k .OR. i > n) THEN
      obj_id = 0
      RETURN
    END IF
    rest = lo(i:n)
    IF (.NOT. is_body .AND. rest(1:1) == 'n') THEN
      node = 0
      i = 2
      DO WHILE (i <= LEN_TRIM(rest))
        IF (VERIFY(rest(i:i), '0123456789') /= 0) EXIT
        IF (node > 99999999) RETURN
        node = node*10 + (IACHAR(rest(i:i)) - IACHAR('0'))
        i = i + 1
      END DO
      IF (i == 2) RETURN
      rest = rest(i:)
      DO k = 1, 3
        IF (TRIM(rest) == TRIM(OBJ_QTY(k))) qty = k
      END DO
      RETURN
    END IF
    DO k = 1, SIZE(OBJ_QTY)
      IF (TRIM(rest) == TRIM(OBJ_QTY(k))) qty = k
    END DO
    ! bodies have no TenA/TenB/Sub; rods no yaw angle (MoorDyn-F vocabulary)
    IF (is_body .AND. qty > 24) qty = 0
    IF (.NOT. is_body .AND. qty == 6) qty = 0
  END SUBROUTINE parse_object_channel

  SUBROUTINE check_object_channel(ch, bodies, rods, ErrStat, ErrMsg)
    !! Validate a Body<N>/Rod<N> channel against the deck objects.
    CHARACTER(*), INTENT(IN) :: ch
    TYPE(DeckBody), INTENT(IN) :: bodies(:)
    TYPE(DeckRod), INTENT(IN) :: rods(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    LOGICAL :: is_body
    INTEGER :: oid, node, qty, ir
    ErrStat = 0; ErrMsg = ''
    CALL parse_object_channel(ch, is_body, oid, node, qty)
    IF (qty == 0) THEN
      CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": bad Body<N>/Rod<N> channel (Body<N>P|R|V|RV|A|RA|F|M'// &
                '{x,y,z}; Rod<N>P|V|RV|A|RA|F|M{x,y,z}, Rod<N>R{x,y}, Rod<N>TenA|TenB|Sub; Rod<N>N<k>P{x,y,z})')
      RETURN
    END IF
    IF (is_body) THEN
      IF (find_body(bodies, oid) == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": unknown body id'); RETURN
      END IF
      IF (TRIM(bodies(find_body(bodies, oid))%btype) /= 'rigid6') THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": Body<N> channels report Rigid6 bodies'); RETURN
      END IF
    ELSE
      ir = find_rod(rods, oid)
      IF (ir == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": unknown rod id'); RETURN
      END IF
      IF (node > rods(ir)%nsegs) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": rod node beyond NumSegs'); RETURN
      END IF
    END IF
  END SUBROUTINE check_object_channel

  SUBROUTINE object_channel_value(ch, val, found, rigid, rods, points, opts, time, system, mb, ErrStat, ErrMsg, &
                                  bathymetry)
    !! Value of a Body<N>/Rod<N> channel from the committed body and rod states; found = .FALSE.
    !! when the object is not in the given states, or when a load channel (F, M, TenA, TenB)
    !! is asked for without the load context (points, opts, time). Body angles are the x-y'-z''
    !! Euler angles of the deck convention [deg]; RV and RA are the angular velocity and
    !! acceleration [deg/s, deg/s^2]. Rod P, V and A are those of End A (MoorDyn-F), Rod Rx/Ry
    !! MoorDyn's roll and pitch of the axis from the vertical [deg]. Loads are evaluated at the
    !! committed state: Body F/M is the net external load about the reference point, Rod F/M
    !! about End A (weight, buoyancy, hydrodynamic and seabed loads, external loads, the line
    !! end forces and, for a body, its fixed rods and the pin forces of its pinned rods); Rod
    !! TenA/TenB is the magnitude of the summed line force at End A/B, Sub the submerged
    !! fraction of its length.
    CHARACTER(*), INTENT(IN) :: ch
    REAL(wp), INTENT(OUT) :: val
    LOGICAL, INTENT(OUT) :: found
    TYPE(RigidBodyState), INTENT(IN), OPTIONAL :: rigid(:)
    TYPE(RodState), INTENT(IN), OPTIONAL :: rods(:)
    TYPE(DeckPoint), INTENT(IN), OPTIONAL :: points(:)
    TYPE(DeckOptions), INTENT(IN), OPTIONAL :: opts
    REAL(wp), INTENT(IN), OPTIONAL :: time
    TYPE(CD_SystemType), INTENT(IN), OPTIONAL :: system
    TYPE(MultibodyMarch), INTENT(IN), OPTIONAL :: mb
    INTEGER, INTENT(OUT), OPTIONAL :: ErrStat
    CHARACTER(*), INTENT(OUT), OPTIONAL :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    LOGICAL :: is_body, have_ctx
    INTEGER :: oid, node, qty, ib, ir, body_of, es
    REAL(wp) :: ang(3), rr(3, 3), axis(3), half, ends(3), f6(6), ten(2), sub, arm(3), phi, beta
    TYPE(RodState) :: rs
    CHARACTER(256) :: em
    REAL(wp), PARAMETER :: R2D = 45.0_wp/QUARTER_PI

    val = CD_ZERO
    found = .FALSE.
    IF (PRESENT(ErrStat)) ErrStat = CD_DECKDRV_OK
    IF (PRESENT(ErrMsg)) ErrMsg = ''
    have_ctx = PRESENT(points) .AND. PRESENT(opts) .AND. PRESENT(time)
    CALL parse_object_channel(ch, is_body, oid, node, qty)
    IF (qty == 0) RETURN
    IF (is_body) THEN
      IF (.NOT. PRESENT(rigid)) RETURN
      DO ib = 1, SIZE(rigid)
        IF (rigid(ib)%body_id /= oid) CYCLE
        rr = rigid(ib)%rot_mat
        ang = [ATAN2(-rr(2, 3), rr(3, 3)), ASIN(MAX(-CD_ONE, MIN(CD_ONE, rr(1, 3)))), ATAN2(-rr(1, 2), rr(1, 1))]
        SELECT CASE (qty)
        CASE (1:3)
          val = rigid(ib)%r(qty)
        CASE (4:6)
          val = ang(qty - 3)*R2D
        CASE (7:9)
          val = rigid(ib)%v(qty - 6)
        CASE (10:12)
          val = rigid(ib)%omega(qty - 9)*R2D
        CASE (13:15)
          val = rigid(ib)%a(qty - 12)
        CASE (16:18)
          val = rigid(ib)%alpha(qty - 15)*R2D
        CASE DEFAULT
          IF (.NOT. have_ctx) RETURN
          CALL body_net_wrench(rigid, ib, points, opts, time, f6, es, em, system, mb, bathymetry)
          IF (es /= CD_DECKDRV_OK) THEN
            IF (PRESENT(ErrStat)) ErrStat = es
            IF (PRESENT(ErrMsg)) ErrMsg = em
            RETURN
          END IF
          val = f6(qty - 18)
        END SELECT
        found = .TRUE.
        RETURN
      END DO
      RETURN
    END IF
    ! rods: free, pinned and fixed rods, then rods fixed to a body (pose from the body's)
    body_of = 0
    IF (PRESENT(rods)) THEN
      DO ir = 1, SIZE(rods)
        IF (rods(ir)%rod_id /= oid) CYCLE
        found = .TRUE.
        rs = rods(ir)
        EXIT
      END DO
    END IF
    IF (.NOT. found .AND. PRESENT(rigid)) THEN
      DO ib = 1, SIZE(rigid)
        IF (.NOT. ALLOCATED(rigid(ib)%att_rods)) CYCLE
        DO ir = 1, SIZE(rigid(ib)%att_rods)
          IF (rigid(ib)%att_rods(ir)%rod_id /= oid) CYCLE
          found = .TRUE.
          body_of = ib
          rs = rigid(ib)%att_rods(ir)
          arm = MATMUL(rigid(ib)%rot_mat, rigid(ib)%att_c(:, ir))
          rs%r = rigid(ib)%r + arm
          rs%rot_mat = MATMUL(rigid(ib)%rot_mat, rigid(ib)%att_rot(:, :, ir))
          rs%v = rigid(ib)%v + cross3(rigid(ib)%omega, arm)
          rs%omega = rigid(ib)%omega
          rs%a = rigid(ib)%a + cross3(rigid(ib)%alpha, arm) + cross3(rigid(ib)%omega, cross3(rigid(ib)%omega, arm))
          rs%alpha = rigid(ib)%alpha
          rs%has_held = .FALSE.
          EXIT
        END DO
        IF (found) EXIT
      END DO
    END IF
    IF (.NOT. found) RETURN
    axis = rs%rot_mat(:, 1)
    half = rs%half_length
    arm = -half*axis
    ends = rs%r + arm
    IF (node >= 0) THEN
      IF (node > 0) ends = ends + (2.0_wp*half*REAL(node, wp)/REAL(MAX(1, rs%nsegs), wp))*axis
      val = ends(qty)
      RETURN
    END IF
    SELECT CASE (qty)
    CASE (1:3)
      val = ends(qty)
    CASE (4:5)
      ! MoorDyn: phi the axis tilt from vertical, beta its heading; roll = -phi sin(beta),
      ! pitch = phi cos(beta)
      phi = ACOS(MAX(-CD_ONE, MIN(CD_ONE, axis(3))))
      beta = ATAN2(axis(2), axis(1))
      IF (qty == 4) val = -phi*SIN(beta)*R2D
      IF (qty == 5) val = phi*COS(beta)*R2D
    CASE (7:9)
      ends = rs%v + cross3(rs%omega, arm)
      val = ends(qty - 6)
    CASE (10:12)
      val = rs%omega(qty - 9)*R2D
    CASE (13:15)
      ends = rs%a + cross3(rs%alpha, arm) + cross3(rs%omega, cross3(rs%omega, arm))
      val = ends(qty - 12)
    CASE (16:18)
      val = rs%alpha(qty - 15)*R2D
    CASE DEFAULT
      IF (.NOT. have_ctx) THEN
        found = .FALSE.
        RETURN
      END IF
      CALL rod_net_wrench(rs, body_of, points, opts, time, f6, ten, sub, es, em, system, mb, bathymetry)
      IF (es /= CD_DECKDRV_OK) THEN
        found = .FALSE.
        IF (PRESENT(ErrStat)) ErrStat = es
        IF (PRESENT(ErrMsg)) ErrMsg = em
        RETURN
      END IF
      SELECT CASE (qty)
      CASE (19:24)
        val = f6(qty - 18)
      CASE (25:26)
        val = ten(qty - 24)
      CASE DEFAULT
        val = sub
      END SELECT
    END SELECT
  END SUBROUTINE object_channel_value

  SUBROUTINE point_line_force(points, pidx, system, mb, f, ErrStat, ErrMsg)
    !! Summed force the EI=0 lines (and, on the multibody march, the finite-EI cables) exert on
    !! deck point pidx (each line's FairTen/AnchTen end force: without the end node's inertia).
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    INTEGER, INTENT(IN) :: pidx
    TYPE(CD_SystemType), INTENT(IN), OPTIONAL :: system
    TYPE(MultibodyMarch), INTENT(IN), OPTIONAL :: mb
    REAL(wp), INTENT(OUT) :: f(3)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: k, c, es
    REAL(wp) :: f_first(3), f_last(3), fl(3)
    CHARACTER(200) :: em
    f = CD_ZERO
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (pidx < 1) RETURN
    IF (PRESENT(system)) THEN
      IF (ALLOCATED(system%bindings)) THEN
        DO k = 1, SIZE(system%bindings)
          IF (system%bindings(k)%point_id /= points(pidx)%id) CYCLE
          CALL CD_Get_Model_EndForces(system%lines(system%bindings(k)%line_index), f_first, f_last, es, em)
          IF (es /= CD_MODEL_OK) THEN
            CALL fail_solve(ErrStat, ErrMsg, 'line end-force recovery failed: '//TRIM(em)); RETURN
          END IF
          IF (system%bindings(k)%line_end == CD_LINE_END_A) THEN
            f = f + f_first
          ELSE
            f = f + f_last
          END IF
        END DO
      END IF
    END IF
    IF (PRESENT(mb)) THEN
      IF (.NOT. ALLOCATED(mb%cables)) RETURN
      DO c = 1, SIZE(mb%cables)
        IF (mb%cable_points(1, c) /= points(pidx)%id) CYCLE
        CALL CD_HermiteCable_Dyn_End_Force(mb%cables(c)%line, mb%cables(c)%line%nn, fl, es, em)
        IF (es /= CD_HCDYN_OK) THEN
          CALL fail_solve(ErrStat, ErrMsg, 'cable end-force recovery failed: '//TRIM(em)); RETURN
        END IF
        f = f + [cable_global_component(mb%cables(c), fl, 1), cable_global_component(mb%cables(c), fl, 2), &
                 cable_global_component(mb%cables(c), fl, 3)]
      END DO
    END IF
  END SUBROUTINE point_line_force

  SUBROUTINE body_net_wrench(rigid, ib, points, opts, time, f6, ErrStat, ErrMsg, system, mb, bathymetry)
    !! Net external force and moment on body ib about its reference point (global axes) at its
    !! committed state: weight, buoyancy and hydrostatic restoring, the Morison and external
    !! loads, seabed contact, the loads of its fixed rods (without their inertial terms), the
    !! line forces at its attachment points and, on the multibody march, the pin forces of
    !! the rods pinned to it (their external loads less their inertia).
    TYPE(RigidBodyState), INTENT(IN) :: rigid(:)
    INTEGER, INTENT(IN) :: ib
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time
    REAL(wp), INTENT(OUT) :: f6(6)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_SystemType), INTENT(IN), OPTIONAL :: system
    TYPE(MultibodyMarch), INTENT(IN), OPTIONAL :: mb
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    REAL(wp) :: f(3), m(3), f2(3), m2(3), meff, d3(3, 3), w6(6, 6), a6(6, 6), arm(3), fr6(6), ten(2), sub
    REAL(wp) :: xk(6)
    INTEGER :: ip, ir

    f6 = CD_ZERO
    ASSOCIATE (body => rigid(ib))
      CALL rigid6_hydrostatics(body, opts, time, f, m, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL rigid6_environment_force(body, opts, time, f2, meff, d3, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      f = f + f2
      CALL rigid6_seabed_contact(body, opts, f2, m2, w6, ErrStat, ErrMsg, bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      f = f + f2
      m = m + m2
      CALL rigid6_external_load(body, f2, d3)
      f = f + f2
      IF (ALLOCATED(body%att_rods)) THEN
        CALL rigid6_rod_loads(body, opts, time, f2, m2, a6, w6, ErrStat, ErrMsg, bathymetry, no_bias=.TRUE.)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        f = f + f2
        m = m + m2
      END IF
      DO ip = 1, SIZE(body%point_indices)
        CALL point_line_force(points, body%point_indices(ip), system, mb, f2, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        arm = MATMUL(body%rot_mat, points(body%point_indices(ip))%body_offset)
        f = f + f2
        m = m + cross3(arm, f2)
      END DO
      IF (PRESENT(mb)) THEN
        ! the connection moments of the cables clamped (or elastically connected) to the body
        IF (ALLOCATED(mb%cab_mend)) THEN
          DO ip = 1, SIZE(mb%cables)
            IF (mb%cab_kind(ip) == 1 .AND. mb%cab_obj(ip) == ib) m = m + mb%cab_mend(:, ip)
          END DO
        END IF
        DO ir = 1, SIZE(mb%rods)
          IF (mb%rods(ir)%parent /= ib) CYCLE
          ! the pin force on the body: the rod's external loads less its inertia
          CALL rod_net_wrench(mb%rods(ir), 0, points, opts, time, fr6, ten, sub, ErrStat, ErrMsg, system, mb, &
                              bathymetry, added6=a6)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
          xk(1:3) = mb%rods(ir)%a
          xk(4:6) = mb%rods(ir)%alpha
          f2 = fr6(1:3) - mb%rods(ir)%mass*mb%rods(ir)%a - MATMUL(a6(1:3, :), xk)
          f = f + f2
          m = m + cross3(mb%rods(ir)%pin - body%r, f2)
        END DO
      END IF
    END ASSOCIATE
    f6(1:3) = f
    f6(4:6) = m
  END SUBROUTINE body_net_wrench

  SUBROUTINE rod_net_wrench(rs, body_of, points, opts, time, f6, ten, sub, ErrStat, ErrMsg, system, mb, bathymetry, &
                            added6)
    !! Net external force and moment on a rod about its End A (global axes) at its committed
    !! state (weight, buoyancy, Morison and seabed loads, the line forces at its ends), the
    !! summed line force magnitudes at End A and End B, and its submerged length fraction.
    !! body_of > 0: the rod is fixed to that body, and its end lines are the body attachment
    !! points made from its ends (DeckPoint rod_ref/rod_end). added6: its 6x6 added mass
    !! about its centre.
    TYPE(RodState), INTENT(IN) :: rs
    INTEGER, INTENT(IN) :: body_of
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time
    REAL(wp), INTENT(OUT) :: f6(6), ten(2), sub
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_SystemType), INTENT(IN), OPTIONAL :: system
    TYPE(MultibodyMarch), INTENT(IN), OPTIONAL :: mb
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    REAL(wp), INTENT(OUT), OPTIONAL :: added6(6, 6)
    REAL(wp) :: f(3), m(3), f2(3), m2(3), a6(6, 6), d6(6, 6), pa(3), pb(3), fe(3, 2), eta(2), za, zb, s0, s1
    REAL(wp) :: wv(3), wa(3)
    INTEGER :: ip, e, es
    CHARACTER(200) :: em

    f6 = CD_ZERO
    ten = CD_ZERO
    sub = CD_ZERO
    pa = rs%r - rs%half_length*rs%rot_mat(:, 1)
    pb = rs%r + rs%half_length*rs%rot_mat(:, 1)
    CALL rod_environment_force(rs, opts, time, f, m, a6, d6, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    IF (PRESENT(added6)) added6 = a6
    CALL rod_seabed_contact(rs, opts, f2, m2, d6, ErrStat, ErrMsg, bathymetry)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    f = f + f2 + [CD_ZERO, CD_ZERO, -rs%mass*opts%g]
    m = m + m2 + cross3(rs%r - pa, f)
    ! line forces at the ends
    fe = CD_ZERO
    DO e = 1, 2
      IF (body_of > 0) THEN
        DO ip = 1, SIZE(points)
          IF (points(ip)%rod_ref /= rs%rod_id .OR. points(ip)%rod_end /= e) CYCLE
          CALL point_line_force(points, ip, system, mb, f2, ErrStat, ErrMsg)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
          fe(:, e) = fe(:, e) + f2
        END DO
      ELSE
        ip = rs%point_a_index
        IF (e == 2) ip = rs%point_b_index
        IF (ip > 0) THEN
          CALL point_line_force(points, ip, system, mb, f2, ErrStat, ErrMsg)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
          fe(:, e) = fe(:, e) + f2
        END IF
      END IF
    END DO
    ten(1) = NORM2(fe(:, 1))
    ten(2) = NORM2(fe(:, 2))
    f = f + fe(:, 1) + fe(:, 2)
    m = m + cross3(pb - pa, fe(:, 2))
    ! the connection moments of the cables clamped (or elastically connected) to the rod's ends
    IF (PRESENT(mb) .AND. body_of == 0) THEN
      IF (ALLOCATED(mb%cab_mend)) THEN
        DO ip = 1, SIZE(mb%cables)
          IF (mb%cab_kind(ip) /= 2) CYCLE
          IF (mb%rods(mb%cab_obj(ip))%rod_id == rs%rod_id) m = m + mb%cab_mend(:, ip)
        END DO
      END IF
    END IF
    f6(1:3) = f
    f6(4:6) = m
    ! submerged fraction of the length below the local waterline (linear between the ends)
    eta = CD_ZERO
    IF (opts%has_wave) THEN
      CALL deck_wave_kinematics(opts, pa(1), pa(2), pa(3), time, eta(1), wv, wa, es, em)
      CALL deck_wave_kinematics(opts, pb(1), pb(2), pb(3), time, eta(2), wv, wa, es, em)
    END IF
    IF (rs%has_held) eta = [rs%held_eta(LBOUND(rs%held_eta, 1)), rs%held_eta(UBOUND(rs%held_eta, 1))]
    za = pa(3) - eta(1)
    zb = pb(3) - eta(2)
    IF (za <= CD_ZERO .AND. zb <= CD_ZERO) THEN
      sub = CD_ONE
    ELSE IF (za > CD_ZERO .AND. zb > CD_ZERO) THEN
      sub = CD_ZERO
    ELSE
      s0 = za/(za - zb)
      s1 = MAX(CD_ZERO, MIN(CD_ONE, s0))
      IF (za <= CD_ZERO) THEN
        sub = s1
      ELSE
        sub = CD_ONE - s1
      END IF
    END IF
  END SUBROUTINE rod_net_wrench

  SUBROUTINE objects_acceleration(opts, time, dt, dv0, acc, alpha, ErrStat, ErrMsg, body, rod, bathymetry)
    !! The acceleration of one body (with the rods fixed to it) or one free or pinned rod that
    !! carries no line: every load of the object at its current state (weight, hydrostatics,
    !! Morison, seabed contact) and the implicit drag of the central-difference corrector
    !! (rigid_coupled_acceleration with no attachment). A pinned rod turns about its pin.
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time, dt, dv0(6)
    REAL(wp), INTENT(OUT) :: acc(3), alpha(3)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(RigidBodyState), INTENT(IN), OPTIONAL :: body
    TYPE(RodState), INTENT(IN), OPTIONAL :: rod
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    REAL(wp) :: f(3), m(3), f2(3), m2(3), a6(6, 6), d6(6, 6), c6(6, 6), cg6(6, 6), meff, d3(3, 3)
    REAL(wp) :: no_d(0, 0), no_a(0), no_arm(3, 0)
    INTEGER :: no_base(0)

    acc = CD_ZERO
    alpha = CD_ZERO
    IF (PRESENT(body)) THEN
      CALL rigid6_environment_force(body, opts, time, f2, meff, d3, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL rigid6_hydrostatics(body, opts, time, f, m, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      f = f + f2
      CALL rigid6_cg_inertia(body, cg6, f2, m2)
      f = f + f2
      m = m + m2
      CALL rigid6_rod_loads(body, opts, time, f2, m2, a6, d6, ErrStat, ErrMsg, bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      f = f + f2
      m = m + m2
      cg6 = cg6 + a6
      CALL rigid6_seabed_contact(body, opts, f2, m2, c6, ErrStat, ErrMsg, bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      f = f + f2
      m = m + m2
      d6 = d6 + c6
      d6(1:3, 1:3) = d6(1:3, 1:3) + d3
      CALL rigid6_external_load(body, f2, d3)
      f = f + f2
      d6(1:3, 1:3) = d6(1:3, 1:3) + d3
      CALL rigid_coupled_acceleration(no_d, dt, no_a, no_base, no_arm, meff, cg6, body%inertia, body%rot_mat, &
                                      body%omega, f, m, dv0, d6, acc, alpha, ErrStat, ErrMsg)
    ELSE IF (PRESENT(rod)) THEN
      CALL rod_environment_force(rod, opts, time, f, m, a6, d6, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL rod_seabed_contact(rod, opts, f2, m2, c6, ErrStat, ErrMsg, bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      f = f + f2 + [CD_ZERO, CD_ZERO, -rod%mass*opts%g]
      m = m + m2
      IF (rod%is_pinned) THEN
        CALL rigid_coupled_acceleration(no_d, dt, no_a, no_base, no_arm, rod%mass, a6, rod%inertia, rod%rot_mat, &
                                        rod%omega, f, m, dv0, d6 + c6, acc, alpha, ErrStat, ErrMsg, &
                                        pin_arm=rod%r - rod%pin)
      ELSE
        CALL rigid_coupled_acceleration(no_d, dt, no_a, no_base, no_arm, rod%mass, a6, rod%inertia, rod%rot_mat, &
                                        rod%omega, f, m, dv0, d6 + c6, acc, alpha, ErrStat, ErrMsg)
      END IF
    END IF
  END SUBROUTINE objects_acceleration

  SUBROUTINE float_body_equilibrium(body, opts, ErrStat, ErrMsg, bathymetry)
    !! Static equilibrium of a body (with the rods fixed to it) that carries no line: heave and
    !! the two tilts about the reference point balance the weight, buoyancy and hydrostatic
    !! moment (Newton on [F_z, M_x, M_y] with a central-difference Jacobian, steps capped at
    !! 1 m / 0.1 rad). The horizontal position and heading, which nothing restrains, are kept.
    TYPE(RigidBodyState), INTENT(INOUT) :: body
    TYPE(DeckOptions), INTENT(IN) :: opts
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    TYPE(DeckOptions) :: calm
    TYPE(RigidBodyState) :: trial
    REAL(wp) :: r0(3), rj(3), jac(3, 3), dx(3), scale, h(3), pert(3)
    INTEGER :: it, k
    LOGICAL :: ok

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    calm = opts
    calm%has_wave = .FALSE.
    body%v = CD_ZERO
    body%omega = CD_ZERO
    scale = MAX(body%mass*opts%g, opts%rhoW*opts%g*body%vol, TINY(CD_ONE))
    IF (ALLOCATED(body%att_rods)) THEN
      DO k = 1, SIZE(body%att_rods)
        scale = MAX(scale, body%att_rods(k)%mass*opts%g)
      END DO
    END IF
    h = [1.0e-4_wp, 1.0e-6_wp, 1.0e-6_wp]
    DO it = 1, 60
      CALL residual(body, r0)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      IF (MAXVAL(ABS(r0)) <= 1.0e-10_wp*scale) RETURN
      DO k = 1, 3
        pert = CD_ZERO
        pert(k) = h(k)
        trial = body
        CALL move(trial, pert)
        CALL residual(trial, rj)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        jac(:, k) = rj
        trial = body
        CALL move(trial, -pert)
        CALL residual(trial, rj)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        jac(:, k) = (jac(:, k) - rj)/(2.0_wp*h(k))
      END DO
      CALL solve_sym3(jac, -r0, dx, ok)
      IF (.NOT. ok) EXIT
      dx(1) = MAX(-CD_ONE, MIN(CD_ONE, dx(1)))
      dx(2:3) = MAX(-0.1_wp, MIN(0.1_wp, dx(2:3)))
      CALL move(body, dx)
    END DO
    CALL residual(body, r0)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    IF (.NOT. ALL(ABS(r0) <= 1.0e-6_wp*scale)) THEN   ! NaN-aware
      CALL fail(ErrStat, ErrMsg, 'floating body '//TRIM(int_to_str(body%body_id))//' found no static equilibrium '// &
                '(bodyIC deck starts from the deck pose instead)')
    END IF
  CONTAINS
    SUBROUTINE move(b, d)
      TYPE(RigidBodyState), INTENT(INOUT) :: b
      REAL(wp), INTENT(IN) :: d(3)
      REAL(wp) :: rinc(3, 3), rv(3)
      b%r(3) = b%r(3) + d(1)
      rv = [d(2), d(3), CD_ZERO]
      rinc = CD_Exp_SO3(rv)
      b%rot_mat = MATMUL(rinc, b%rot_mat)
    END SUBROUTINE move
    SUBROUTINE residual(b, res)
      TYPE(RigidBodyState), INTENT(IN) :: b
      REAL(wp), INTENT(OUT) :: res(3)
      REAL(wp) :: f(3), m(3), f2(3), m2(3), a6(6, 6), d6(6, 6), meff, d3(3, 3)
      CALL rigid6_hydrostatics(b, calm, CD_ZERO, f, m, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL rigid6_environment_force(b, calm, CD_ZERO, f2, meff, d3, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      f = f + f2
      CALL rigid6_rod_loads(b, calm, CD_ZERO, f2, m2, a6, d6, ErrStat, ErrMsg, bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      f = f + f2
      m = m + m2
      CALL rigid6_seabed_contact(b, calm, f2, m2, d6, ErrStat, ErrMsg, bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      f = f + f2
      m = m + m2
      CALL rigid6_external_load(b, f2, d3)
      res = [f(3) + f2(3), m(1), m(2)]
    END SUBROUTINE residual
  END SUBROUTINE float_body_equilibrium

  SUBROUTINE write_objects_dynamic_out(out_root, channels, bodies, rod_types, rods, points, opts, converged, &
                                       ErrStat, ErrMsg, bathymetry)
    !! March the bodies (with the rods fixed to them) and the free and pinned rods of a deck
    !! without lines: each object is advanced by the staggered central-difference scheme of the
    !! line-coupled routes (Newmark gamma = 1/2, beta = 0, drag implicit), with no line loads. With
    !! bodyIC static a floating body starts at its hydrostatic equilibrium (float_body_equilibrium).
    CHARACTER(*), INTENT(IN) :: out_root
    CHARACTER(NAMELEN), INTENT(IN) :: channels(:)
    TYPE(DeckBody), INTENT(IN) :: bodies(:)
    TYPE(DeckRodType), INTENT(IN) :: rod_types(:)
    TYPE(DeckRod), INTENT(IN) :: rods(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    LOGICAL, INTENT(OUT) :: converged
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    TYPE(RigidBodyState), ALLOCATABLE :: rigid(:), old_rigid(:)
    TYPE(RodState), ALLOCATABLE :: rst(:), old_rst(:)
    TYPE(DeckRod), ALLOCATABLE :: own(:)
    INTEGER :: unit, ios, step, nstep, k, es
    REAL(wp) :: t, acc(3), alpha(3), dv0(6)
    CHARACTER(160) :: em
    TYPE(DriverProgress) :: progress

    converged = .TRUE.
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    CALL init_rigid6_states(bodies, points, rigid, ErrStat, ErrMsg, rod_types, rods, allow_no_points=.TRUE.)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    ALLOCATE (own(0))
    DO k = 1, SIZE(rods)
      SELECT CASE (TRIM(rods(k)%rod_type))
      CASE ('free', 'pinned', 'fixed')
        own = [own, rods(k)]
      CASE ('coupled', 'vessel')
        CALL fail(ErrStat, ErrMsg, 'a Coupled/Vessel ROD needs lines (a deck without lines has none to drive)')
        RETURN
      END SELECT
    END DO
    CALL init_rod_states(rod_types, own, points, rst, ErrStat, ErrMsg, no_points=.TRUE.)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    IF (opts%body_ic_static) THEN
      DO k = 1, SIZE(rigid)
        CALL float_body_equilibrium(rigid(k), opts, ErrStat, ErrMsg, bathymetry)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      END DO
    END IF
    ! initial accelerations
    DO k = 1, SIZE(rigid)
      CALL objects_acceleration(opts, CD_ZERO, CD_ZERO, [CD_ZERO, CD_ZERO, CD_ZERO, CD_ZERO, CD_ZERO, CD_ZERO], &
                                rigid(k)%a, rigid(k)%alpha, ErrStat, ErrMsg, body=rigid(k), bathymetry=bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END DO
    DO k = 1, SIZE(rst)
      IF (.NOT. (rst(k)%is_free .OR. rst(k)%is_pinned)) CYCLE
      CALL objects_acceleration(opts, CD_ZERO, CD_ZERO, [CD_ZERO, CD_ZERO, CD_ZERO, CD_ZERO, CD_ZERO, CD_ZERO], &
                                rst(k)%a, rst(k)%alpha, ErrStat, ErrMsg, rod=rst(k), bathymetry=bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END DO
    OPEN (NEWUNIT=unit, FILE=TRIM(out_root)//'.out', STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open output file: '//TRIM(out_root)//'.out'); RETURN
    END IF
    WRITE (unit, '(A)') '# CableDyn driver output (bodies and rods without lines, dynamic)'
    CALL write_header(unit, channels)
    CALL write_row(CD_ZERO)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      RETURN
    END IF
    nstep = NINT(opts%tmax/opts%dtM)
    CALL start_driver_progress(progress, nstep, opts%dtM)
    DO step = 1, nstep
      t = REAL(step, wp)*opts%dtM
      old_rigid = rigid
      old_rst = rst
      DO k = 1, SIZE(rigid)
        CALL CD_Rigid_Advance_Newmark(rigid(k)%r, rigid(k)%v, rigid(k)%rot_mat, rigid(k)%omega, rigid(k)%a, &
                                      rigid(k)%alpha, rigid(k)%a, rigid(k)%alpha, opts%dtM, CD_RIGID_NEWMARK_GAMMA, &
                                      CD_RIGID_NEWMARK_BETA, es, em)
        IF (es /= CD_RIGID_OK) CALL fail_solve(ErrStat, ErrMsg, 'body finite-rotation update failed: '//TRIM(em))
        IF (ErrStat /= CD_DECKDRV_OK) EXIT
        dv0(1:3) = -CD_RIGID_NEWMARK_GAMMA*opts%dtM*old_rigid(k)%a
        dv0(4:6) = -CD_RIGID_NEWMARK_GAMMA*opts%dtM*old_rigid(k)%alpha
        CALL objects_acceleration(opts, t, opts%dtM, dv0, acc, alpha, ErrStat, ErrMsg, body=rigid(k), &
                                  bathymetry=bathymetry)
        IF (ErrStat /= CD_DECKDRV_OK) EXIT
        rigid(k) = old_rigid(k)
        CALL CD_Rigid_Advance_Newmark(rigid(k)%r, rigid(k)%v, rigid(k)%rot_mat, rigid(k)%omega, old_rigid(k)%a, &
                                      old_rigid(k)%alpha, acc, alpha, opts%dtM, CD_RIGID_NEWMARK_GAMMA, &
                                      CD_RIGID_NEWMARK_BETA, es, em)
        IF (es /= CD_RIGID_OK) CALL fail_solve(ErrStat, ErrMsg, 'body finite-rotation update failed: '//TRIM(em))
        IF (ErrStat /= CD_DECKDRV_OK) EXIT
        rigid(k)%a = acc
        rigid(k)%alpha = alpha
      END DO
      IF (ErrStat == CD_DECKDRV_OK) THEN
        DO k = 1, SIZE(rst)
          IF (.NOT. (rst(k)%is_free .OR. rst(k)%is_pinned)) CYCLE
          CALL CD_Rigid_Advance_Newmark(rst(k)%r, rst(k)%v, rst(k)%rot_mat, rst(k)%omega, rst(k)%a, rst(k)%alpha, &
                                        rst(k)%a, rst(k)%alpha, opts%dtM, CD_RIGID_NEWMARK_GAMMA, &
                                        CD_RIGID_NEWMARK_BETA, es, em)
          IF (es /= CD_RIGID_OK) CALL fail_solve(ErrStat, ErrMsg, 'rod finite-rotation update failed: '//TRIM(em))
          IF (ErrStat /= CD_DECKDRV_OK) EXIT
          CALL pin_rod(rst(k))
          dv0(1:3) = -CD_RIGID_NEWMARK_GAMMA*opts%dtM*old_rst(k)%a
          dv0(4:6) = -CD_RIGID_NEWMARK_GAMMA*opts%dtM*old_rst(k)%alpha
          CALL objects_acceleration(opts, t, opts%dtM, dv0, acc, alpha, ErrStat, ErrMsg, rod=rst(k), &
                                    bathymetry=bathymetry)
          IF (ErrStat /= CD_DECKDRV_OK) EXIT
          rst(k) = old_rst(k)
          CALL CD_Rigid_Advance_Newmark(rst(k)%r, rst(k)%v, rst(k)%rot_mat, rst(k)%omega, old_rst(k)%a, &
                                        old_rst(k)%alpha, acc, alpha, opts%dtM, CD_RIGID_NEWMARK_GAMMA, &
                                        CD_RIGID_NEWMARK_BETA, es, em)
          IF (es /= CD_RIGID_OK) CALL fail_solve(ErrStat, ErrMsg, 'rod finite-rotation update failed: '//TRIM(em))
          IF (ErrStat /= CD_DECKDRV_OK) EXIT
          rst(k)%a = acc
          rst(k)%alpha = alpha
          CALL pin_rod(rst(k))
        END DO
      END IF
      IF (ErrStat == CD_DECKDRV_OK) CALL write_row(t)
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        converged = .FALSE.
        CLOSE (unit)
        RETURN
      END IF
      CALL update_driver_progress(progress, step, t)
    END DO
    CLOSE (unit)
  CONTAINS
    SUBROUTINE pin_rod(rod)
      !! A pinned rod's End A stays at the pin: its centre follows the orientation.
      TYPE(RodState), INTENT(INOUT) :: rod
      REAL(wp) :: arm(3)
      IF (.NOT. rod%is_pinned) RETURN
      arm = rod%half_length*rod%rot_mat(:, 1)
      rod%r = rod%pin + arm
      rod%v = cross3(rod%omega, arm)
    END SUBROUTINE pin_rod
    SUBROUTINE write_row(time)
      REAL(wp), INTENT(IN) :: time
      REAL(wp) :: vals(SIZE(channels))
      LOGICAL :: found
      INTEGER :: i
      DO i = 1, SIZE(channels)
        CALL object_channel_value(channels(i), vals(i), found, rigid, rst, points, opts, time, &
                                  ErrStat=ErrStat, ErrMsg=ErrMsg, bathymetry=bathymetry)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        IF (.NOT. found) THEN
          CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(channels(i))//'" is not available on a deck without '// &
                    'lines (Body<N> and Rod<N> channels are)')
          RETURN
        END IF
      END DO
      WRITE (unit, ROW_VALUES_FMT) time, (char_tab(), vals(i), i=1, SIZE(channels))
    END SUBROUTINE write_row
  END SUBROUTINE write_objects_dynamic_out

  ! --------------------------------------------------------------------------- !
  ! multibody march: Rigid6 bodies (with fixed and pinned rods), free, pinned    !
  ! and fixed rods, Free/Connect points, EI=0 lines and finite-EI cables        !
  ! --------------------------------------------------------------------------- !

  LOGICAL FUNCTION monolithic_march_eligible(opts, bodies, rods, n_lines, has_finite, has_rigid6, has_dyn_points, &
                                             n_fails) RESULT(eligible)
    !! bodyScheme monolithic routes a standalone dynamic deck of free Rigid6 bodies, Point3 buoys,
    !! free, fixed or pinned rods and Free/Connect points on EI=0 lines to the multibody march
    !! (whose step is then the monolithic implicit one). Decks with motionFile coupling, line
    !! FAILURES, finite-EI lines or Coupled/Vessel rods keep their own marches. A deck without
    !! lines has no coupling to solve and keeps its explicit central-difference march (the smaller
    !! phase error per step) unless it names bodyScheme monolithic.
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(DeckBody), INTENT(IN) :: bodies(:)
    TYPE(DeckRod), INTENT(IN) :: rods(:)
    INTEGER, INTENT(IN) :: n_lines
    LOGICAL, INTENT(IN) :: has_finite, has_rigid6, has_dyn_points
    INTEGER, INTENT(IN) :: n_fails
    INTEGER :: i
    eligible = .FALSE.
    IF (opts%body_scheme_staggered .OR. opts%has_motion_file .OR. has_finite .OR. n_fails > 0) RETURN
    IF (n_lines == 0 .AND. .NOT. opts%body_scheme_monolithic_named) RETURN
    IF (.NOT. (has_rigid6 .OR. SIZE(rods) > 0 .OR. has_dyn_points)) RETURN
    DO i = 1, SIZE(bodies)
      IF (TRIM(bodies(i)%btype) /= 'rigid6' .AND. TRIM(bodies(i)%btype) /= 'point3') RETURN
    END DO
    DO i = 1, SIZE(rods)
      IF (TRIM(rods(i)%rod_type) == 'coupled' .OR. TRIM(rods(i)%rod_type) == 'vessel') RETURN
    END DO
    eligible = .TRUE.
  END FUNCTION monolithic_march_eligible

  LOGICAL FUNCTION point_on_point3_body(point, bodies) RESULT(yes)
    !! Whether point is the Body<N> attachment of a Point3 BODY (the system steps it as a Free
    !! point carrying the BODY Mass/Vol/CdA/Ca).
    TYPE(DeckPoint), INTENT(IN) :: point
    TYPE(DeckBody), INTENT(IN) :: bodies(:)
    INTEGER :: ib
    yes = .FALSE.
    IF (.NOT. starts_with(TRIM(point%ptype), 'body')) RETURN
    ib = find_body(bodies, point%body_id)
    IF (ib > 0) yes = TRIM(bodies(ib)%btype) == 'point3'
  END FUNCTION point_on_point3_body

  LOGICAL FUNCTION deck_needs_multibody(types, bodies, rods, points, lines, sections) RESULT(needs)
    !! A dynamic deck that no single-family march covers: a rod pinned to a body, a pinned rod
    !! carrying lines, finite-EI lines beside EI=0 lines, bodies, rods or dynamic points,
    !! free/fixed rods beside Rigid6 bodies or Free/Connect points, or Rigid6 bodies beside
    !! Free/Connect points.
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckBody), INTENT(IN) :: bodies(:)
    TYPE(DeckRod), INTENT(IN) :: rods(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    INTEGER :: i
    LOGICAL :: has_rigid6
    needs = .FALSE.
    has_rigid6 = deck_has_rigid6_bodies(bodies)
    DO i = 1, SIZE(rods)
      IF (pinned_body_of_rod_type(rods(i)%rod_type) > 0) needs = .TRUE.
      IF (TRIM(rods(i)%rod_type) /= 'pinned') CYCLE
      IF (count_rod_point_refs(points, rods(i)%id, 1) + count_rod_point_refs(points, rods(i)%id, 2) > 0) &
        needs = .TRUE.
    END DO
    IF (needs .OR. SIZE(lines) == 0) RETURN
    IF (deck_has_finite_ei(types, sections)) THEN
      ! EI=0 and finite-EI lines between held or coupled points alone belong to the aggregate
      ! route (the executable runs them there); objects bring them to the multibody march
      needs = SIZE(bodies) > 0 .OR. SIZE(rods) > 0
      IF (.NOT. needs) needs = deck_has_dynamic_points(points)
      RETURN
    END IF
    IF (SIZE(rods) > 0) THEN
      IF (COUNT([(body_id_of_rod_type(rods(i)%rod_type) > 0, i=1, SIZE(rods))]) < SIZE(rods)) THEN
        needs = has_rigid6 .OR. deck_has_non_rod_dynamic_points(points)
        RETURN
      END IF
    END IF
    IF (has_rigid6) needs = deck_has_non_rigid6_dynamic_points(points, bodies)
  END FUNCTION deck_needs_multibody

  SUBROUTINE write_multibody_dynamic_out(deck_path, out_root, channels, types, bodies, rod_types, rods, points, &
                                         lines, sections, opts, n_finite, converged, ErrStat, ErrMsg, bathymetry)
    !! One staggered march over every object of a mixed deck. Each step:
    !!  1. predictor: the free bodies and the free and pinned rods move to their final positions
    !!     with their previous accelerations (central difference, Newmark gamma = 1/2, beta = 0);
    !!     a rod pinned to a body turns with its own rotation and keeps End A on the body's pin;
    !!  2. line step: the EI=0 lines (with the Free/Connect points integrated on their summed end
    !!     loads, CD_Step_System_DynamicPoints) and the finite-EI cables (End A driven by the
    !!     predicted attachment, End B held) are stepped to t + dt with that motion;
    !!  3. corrector: each body solves its equation of motion jointly with the rods pinned to it
    !!     (reduced coordinates: body twist and each pinned rod's rotation, mb_group_solve), each
    !!     free rod its own and each pinned rod its rotation about the pin, with the end-of-step
    !!     line loads, the EI=0 line end-node inertia and the object drag implicit
    !!     (rigid_coupled_acceleration); a cable end acts as a point force at its attachment
    !!     (pinned: translations coupled, no moment transfer).
    !! Steps are sub-cycled as in step_rigid6_system / step_rod_system so that the explicit
    !! object position resolves the stiffest object-mooring mode of the EI=0 lines.
    CHARACTER(*), INTENT(IN) :: deck_path, out_root
    CHARACTER(NAMELEN), INTENT(IN) :: channels(:)
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckBody), INTENT(IN) :: bodies(:)
    TYPE(DeckRodType), INTENT(IN) :: rod_types(:)
    TYPE(DeckRod), INTENT(IN) :: rods(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    INTEGER, INTENT(IN) :: n_finite
    LOGICAL, INTENT(OUT) :: converged
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    TYPE(MultibodyMarch) :: mb
    TYPE(DeckLine), ALLOCATABLE :: sys_lines(:), cab_lines(:)
    TYPE(DeckRod), ALLOCATABLE :: own(:)
    TYPE(DeckPoint), ALLOCATABLE :: pc(:)
    TYPE(CD_LineInitSummary), ALLOCATABLE :: sum_sys(:), sum_cab(:), summaries(:)
    LOGICAL, ALLOCATABLE :: is_fin(:), is_ei0(:)
    INTEGER, ALLOCATABLE :: pos_units(:), ten_units(:), cpos_units(:), cten_units(:), rod_units(:)
    INTEGER :: i, k, c, ir, ib, pa, pb, node, unit, ios, step, nstep, es, n_iter, bid
    INTEGER :: miss_count, consecutive_miss, max_consecutive_miss
    LOGICAL :: step_converged, stalled
    REAL(wp) :: t, first_miss_time, last_miss_time, rb(3, 3)
    CHARACTER(LEN(out_root) + 8) :: path
    CHARACTER(256) :: em
    TYPE(HydroUpdateWorkspace) :: hydro_work
    TYPE(ModelOutputWorkspace) :: output_work
    TYPE(DriverProgress) :: progress
    TYPE(CD_RangeSet) :: mb_ranges

    converged = .FALSE.
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    miss_count = 0
    consecutive_miss = 0
    max_consecutive_miss = 0
    first_miss_time = CD_ZERO
    last_miss_time = CD_ZERO
    ! ---- scope of the multibody march (fail closed by name) ----
    IF (opts%has_motion_file) THEN
      CALL fail(ErrStat, ErrMsg, 'a mixed-topology deck (bodies, rods, dynamic points, EI=0 and finite-EI '// &
                'lines together) does not support motionFile coupling'); RETURN
    END IF
    DO i = 1, SIZE(bodies)
      IF (TRIM(bodies(i)%btype) /= 'rigid6' .AND. TRIM(bodies(i)%btype) /= 'point3') THEN
        CALL fail(ErrStat, ErrMsg, 'a mixed-topology deck supports Free (Rigid6) and Point3 BODIES only; BODY '// &
                  TRIM(int_to_str(bodies(i)%id))//' is '//TRIM(bodies(i)%btype)); RETURN
      END IF
    END DO
    DO i = 1, SIZE(rods)
      IF (TRIM(rods(i)%rod_type) == 'coupled' .OR. TRIM(rods(i)%rod_type) == 'vessel') THEN
        CALL fail(ErrStat, ErrMsg, 'a mixed-topology deck does not support Coupled/Vessel RODS (ROD '// &
                  TRIM(int_to_str(rods(i)%id))//')'); RETURN
      END IF
    END DO
    ALLOCATE (is_fin(SIZE(lines)))
    DO i = 1, SIZE(lines)
      is_fin(i) = line_is_finite_ei(lines(i), types, sections)
      pa = find_point(points, lines(i)%nodeA)
      pb = find_point(points, lines(i)%nodeB)
      IF (is_fin(i)) THEN
        IF (TRIM(points(pb)%ptype) /= 'fixed') THEN
          CALL fail(ErrStat, ErrMsg, 'finite-EI LINE '//TRIM(int_to_str(lines(i)%id))//' in a mixed-topology '// &
                    'deck needs a Fixed End B (the cable is driven at End A)'); RETURN
        END IF
        IF (TRIM(points(pa)%ptype) == 'free' .OR. TRIM(points(pa)%ptype) == 'connect' .OR. &
            point_on_point3_body(points(pa), bodies)) THEN
          CALL fail(ErrStat, ErrMsg, 'finite-EI LINE '//TRIM(int_to_str(lines(i)%id))//': a cable end on a '// &
                    'Free/Connect point or a Point3 buoy is not supported; attach it to a Rigid6 body, '// &
                    'a rod end or a Fixed point'); RETURN
        END IF
        IF (TRIM(points(pa)%ptype) == 'coupled' .OR. TRIM(points(pa)%ptype) == 'vessel') THEN
          CALL fail(ErrStat, ErrMsg, 'finite-EI LINE '//TRIM(int_to_str(lines(i)%id))//': a Coupled End A '// &
                    'needs motionFile coupling, which a mixed-topology deck does not support'); RETURN
        END IF
        IF (lines(i)%endconn_mode(1) /= CD_ENDCONN_PINNED .AND. TRIM(points(pa)%ptype) /= 'fixed') THEN
          ! a clamped or elastic End A on a body or rod: implicit (monolithic step) only
          IF (opts%body_scheme_staggered) THEN
            CALL fail(ErrStat, ErrMsg, 'finite-EI LINE '//TRIM(int_to_str(lines(i)%id))//': a clamped or '// &
                      'elastic END CONNECTION on a body or rod needs bodyScheme monolithic (the staggered '// &
                      'scheme couples cable ends as point forces)')
            RETURN
          END IF
          BLOCK
            REAL(wp) :: rclamp(3, 3), dclamp(3)
            CALL clamp_object_frame(lines(i), points, bodies, rods, rclamp, dclamp, ErrStat, ErrMsg, &
                                    check_axis=.NOT. opts%body_ic_static)
          END BLOCK
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
        END IF
      END IF
    END DO
    ! Free/Connect points integrate on the EI=0 line end loads: each needs one
    DO k = 1, SIZE(points)
      IF (TRIM(points(k)%ptype) /= 'free' .AND. TRIM(points(k)%ptype) /= 'connect') CYCLE
      IF (.NOT. ANY([(.NOT. is_fin(i) .AND. (lines(i)%nodeA == points(k)%id .OR. lines(i)%nodeB == points(k)%id), &
                      i=1, SIZE(lines))])) THEN
        CALL fail(ErrStat, ErrMsg, 'POINT '//TRIM(int_to_str(points(k)%id))//' (Free/Connect) in a '// &
                  'mixed-topology deck must carry at least one EI=0 line'); RETURN
      END IF
    END DO
    ALLOCATE (is_ei0(SIZE(lines)))
    is_ei0 = .NOT. is_fin
    sys_lines = PACK(lines, is_ei0)
    cab_lines = PACK(lines, is_fin)
    mb%has_sys = SIZE(sys_lines) > 0
    mb%has_dyn = .FALSE.
    mb%implicit = .NOT. opts%body_scheme_staggered
    DO k = 1, SIZE(points)
      IF (TRIM(points(k)%ptype) == 'free' .OR. TRIM(points(k)%ptype) == 'connect') mb%has_dyn = .TRUE.
      ! a Point3 buoy is the Free point it is attached at (its Body<N> row, BODY Mass/Vol/CdA/Ca)
      IF (point_on_point3_body(points(k), bodies)) mb%has_dyn = .TRUE.
    END DO
    CALL build_line_object_map(lines, is_fin, mb%line_is_cable, mb%line_obj_index, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN

    ! ---- EI=0 system: body and rod points are prescribed by their objects ----
    IF (mb%has_sys) THEN
      pc = points
      DO k = 1, SIZE(pc)
        IF (starts_with(TRIM(pc(k)%ptype), 'body') .AND. .NOT. point_on_point3_body(pc(k), bodies)) &
          pc(k)%ptype = 'coupled'
        IF (is_rod_point_type(pc(k)%ptype)) pc(k)%ptype = 'coupled'
      END DO
      CALL init_deck_system_from_parsed(types, pc, sys_lines, sections, opts, mb%system, ErrStat, ErrMsg, &
                                        bathymetry=bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL collect_system_init_summaries(sys_lines, points, mb%system, sum_sys, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) GOTO 900
    ELSE
      ALLOCATE (sum_sys(0))
    END IF

    ! ---- finite-EI cables: End A is driven like a coupled fairlead ----
    ALLOCATE (mb%cables(SIZE(cab_lines)), mb%cab_kind(SIZE(cab_lines)), mb%cab_obj(SIZE(cab_lines)), &
              mb%cab_off(3, SIZE(cab_lines)), mb%cab_force(3, SIZE(cab_lines)), &
              mb%cab_clamp(SIZE(cab_lines)), mb%cab_moment(3, SIZE(cab_lines)), mb%cab_fend(3, SIZE(cab_lines)), &
              mb%cab_mend(3, SIZE(cab_lines)), mb%cab_f0(3, SIZE(cab_lines)), mb%cab_m0(3, SIZE(cab_lines)))
    mb%cab_kind = 0
    mb%cab_obj = 0
    mb%cab_off = CD_ZERO
    mb%cab_force = CD_ZERO
    mb%cab_clamp = .FALSE.
    mb%cab_moment = CD_ZERO
    mb%cab_fend = CD_ZERO
    mb%cab_mend = CD_ZERO
    mb%cab_f0 = CD_ZERO
    mb%cab_m0 = CD_ZERO
    DO c = 1, SIZE(cab_lines)
      pc = points
      pa = find_point(points, cab_lines(c)%nodeA)
      IF (TRIM(pc(pa)%ptype) /= 'fixed') pc(pa)%ptype = 'coupled'
      mb%cab_clamp(c) = (cab_lines(c)%endconn_mode(1) /= CD_ENDCONN_PINNED .OR. line_torsion_active(cab_lines(c))) &
                        .AND. TRIM(points(pa)%ptype) /= 'fixed'
      IF (mb%cab_clamp(c)) THEN
        ! End A clamped or elastic on its object: the connection direction is stored in the object
        ! frame and turns with the object's orientation (the OpenFAST parent-frame contract)
        BLOCK
          TYPE(DeckLine) :: lnc
          REAL(wp) :: rclamp(3, 3), dclamp(3)
          lnc = cab_lines(c)
          CALL clamp_object_frame(lnc, points, bodies, rods, rclamp, dclamp, ErrStat, ErrMsg, &
                                  check_axis=.NOT. opts%body_ic_static)
          IF (ErrStat /= CD_DECKDRV_OK) GOTO 900
          lnc%endconn_ez_ref(:, 1) = dclamp
          CALL build_one_hermite_cable(lnc, sections, types, pc, opts, opts%dtM, mb%cables(c), node, &
                                       ErrStat, ErrMsg, standalone_controls=.TRUE., bathymetry=bathymetry, &
                                       fairlead_orientation=TRANSPOSE(rclamp))
        END BLOCK
        ! re-stepped inside the outer Newton of the monolithic step: its end loads must be
        ! converged well inside the junction tolerance
        mb%cables(c)%tol = MIN(mb%cables(c)%tol, CLAMPED_CABLE_TOL)
      ELSE
        CALL build_one_hermite_cable(cab_lines(c), sections, types, pc, opts, opts%dtM, mb%cables(c), node, &
                                     ErrStat, ErrMsg, standalone_controls=.TRUE., bathymetry=bathymetry)
      END IF
      IF (ErrStat /= CD_DECKDRV_OK) GOTO 900
    END DO
    IF (SIZE(cab_lines) > 0) THEN
      CALL collect_hermite_init_summaries(cab_lines, mb%cables, sum_cab, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) GOTO 900
    ELSE
      ALLOCATE (sum_cab(0))
    END IF
    summaries = [sum_sys, sum_cab]
    CALL print_deck_init_report(deck_path, lines, points, sections, n_finite, summaries)

    ! ---- objects ----
    CALL init_rigid6_states(bodies, points, mb%rigid, ErrStat, ErrMsg, rod_types, rods, allow_no_points=.TRUE.)
    IF (ErrStat /= CD_DECKDRV_OK) GOTO 900
    DO ib = 1, SIZE(mb%rigid)
      ! a deck without lines (the monolithic scheme's body-only decks): bodyIC static floats each
      ! body to its hydrostatic equilibrium, as the line-less staggered march does
      IF (SIZE(lines) == 0 .AND. opts%body_ic_static) THEN
        CALL float_body_equilibrium(mb%rigid(ib), opts, ErrStat, ErrMsg, bathymetry)
        IF (ErrStat /= CD_DECKDRV_OK) GOTO 900
      END IF
      CALL sync_attached_rods(mb%rigid(ib))
    END DO
    ALLOCATE (own(0))
    DO i = 1, SIZE(rods)
      IF (body_id_of_rod_type(rods(i)%rod_type) > 0) CYCLE
      own = [own, rods(i)]
    END DO
    CALL init_rod_states(rod_types, own, points, mb%rods, ErrStat, ErrMsg, no_points=.TRUE.)
    IF (ErrStat /= CD_DECKDRV_OK) GOTO 900
    DO ir = 1, SIZE(mb%rods)
      bid = pinned_body_of_rod_type(own(ir)%rod_type)
      IF (bid < 1) CYCLE
      ! a rod pinned to a body: ends in the body frame, placed with the body's current pose
      DO ib = 1, SIZE(mb%rigid)
        IF (mb%rigid(ib)%body_id == bid) mb%rods(ir)%parent = ib
      END DO
      ib = mb%rods(ir)%parent
      mb%rods(ir)%is_pinned = .TRUE.
      mb%rods(ir)%pin_body = own(ir)%end_a
      ! the pin follows the body's (static-equilibrium) pose; the rod's orientation relative to
      ! the body is the deck's (updated by the static solve)
      rb = mb%rigid(ib)%rot_mat
      mb%rods(ir)%rot_mat = MATMUL(rb, mb%rods(ir)%rot_mat)
      mb%rods(ir)%omega = CD_ZERO
      CALL mb_snap_pinned(mb%rods(ir), mb%rigid)
    END DO
    ! cable attachments
    DO c = 1, SIZE(cab_lines)
      pa = find_point(points, cab_lines(c)%nodeA)
      IF (starts_with(TRIM(points(pa)%ptype), 'body')) THEN
        DO ib = 1, SIZE(mb%rigid)
          IF (mb%rigid(ib)%body_id == points(pa)%body_id) THEN
            mb%cab_kind(c) = 1
            mb%cab_obj(c) = ib
            mb%cab_off(:, c) = points(pa)%body_offset
          END IF
        END DO
      ELSE IF (is_rod_point_type(points(pa)%ptype)) THEN
        CALL parse_rod_point_type(points(pa)%ptype, bid, k)
        DO ir = 1, SIZE(mb%rods)
          IF (mb%rods(ir)%rod_id /= bid) CYCLE
          mb%cab_kind(c) = 2
          mb%cab_obj(c) = ir
          mb%cab_off(:, c) = [MERGE(-CD_ONE, CD_ONE, k == 1), CD_ZERO, CD_ZERO]
        END DO
        IF (mb%cab_kind(c) == 0) THEN
          ! an end of a rod fixed to a body resolves to a Body<M> point (resolve_rod_end_tokens)
          CALL fail(ErrStat, ErrMsg, 'finite-EI LINE '//TRIM(int_to_str(cab_lines(c)%id))//' attaches to an '// &
                    'unresolved rod end'); GOTO 900
        END IF
      END IF
    END DO
    ALLOCATE (mb%cable_points(2, SIZE(cab_lines)))
    DO c = 1, SIZE(cab_lines)
      mb%cable_points(:, c) = [cab_lines(c)%nodeA, cab_lines(c)%nodeB]
      ! the committed end loads of the initial state (outputs at t = 0, the first step's entry)
      CALL mb_cable_committed_loads(mb, c, mb%cab_fend(:, c), mb%cab_mend(:, c), ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) GOTO 900
    END DO
    CALL range_setup_aggregate(mb_ranges, lines, channels, opts, mb%has_sys, mb%system, mb%cables, &
                               mb%line_is_cable, mb%line_obj_index, ErrStat, ErrMsg, bathymetry)
    IF (ErrStat /= CD_DECKDRV_OK) GOTO 900

    ! ---- output ----
    nstep = NINT(opts%tmax/opts%dtM)
    path = TRIM(out_root)//'.out'
    OPEN (NEWUNIT=unit, FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open output file: '//TRIM(path)); GOTO 900
    END IF
    WRITE (unit, '(A)') '# CableDyn driver output (multibody dynamic; convergence quality is reported by '// &
      'status message)'
    CALL write_header(unit, channels)
    IF (mb%has_sys) THEN
      CALL open_dynamic_system_line_outputs(out_root, sys_lines, mb%system, pos_units, ten_units, ErrStat, ErrMsg)
    ELSE
      ALLOCATE (pos_units(0), ten_units(0))
    END IF
    IF (ErrStat == CD_DECKDRV_OK) &
      CALL open_dynamic_hermite_line_outputs(out_root, cab_lines, mb%cables, cpos_units, cten_units, ErrStat, ErrMsg)
    IF (ErrStat == CD_DECKDRV_OK) CALL open_dynamic_rod_outputs(out_root, own, rod_units, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) GOTO 800
    IF (probe_armed .AND. SIZE(mb%rigid) > 0) THEN
      mb%rigid(1)%v = probe_v0
      mb%rigid(1)%omega = probe_w0
      IF (ALLOCATED(probe_rec)) DEALLOCATE (probe_rec)
      ALLOCATE (probe_rec(CD_MB_PROBE_NCOL, 0:nstep))
      probe_rec = CD_ZERO
      CALL probe_record(0, CD_ZERO)
    END IF
    CALL mb_hydro(CD_ZERO, .TRUE.)
    IF (ErrStat /= CD_DECKDRV_OK) GOTO 800
    CALL mb_outputs(CD_ZERO)
    IF (ErrStat /= CD_DECKDRV_OK) GOTO 800
    CALL start_driver_progress(progress, nstep, opts%dtM)
    DO step = 1, nstep
      t = REAL(step, wp)*opts%dtM
      CALL mb_hydro(t, .FALSE.)
      IF (ErrStat /= CD_DECKDRV_OK) GOTO 800
      CALL mb_step(mb, points, opts, t, opts%dtM, step_converged, stalled, n_iter, es, em, bathymetry)
      IF (es /= CD_DECKDRV_OK) THEN
        ErrStat = es
        ErrMsg = em
        GOTO 800
      END IF
      CALL update_dynamic_completion_quality(t, step_converged, stalled, miss_count, consecutive_miss, &
                                             max_consecutive_miss, first_miss_time, last_miss_time)
      IF (.NOT. step_converged .OR. stalled) THEN
        CALL CD_Classify_Dynamic_Completion('multibody dynamic run', nstep, miss_count, max_consecutive_miss, &
                                            first_miss_time, last_miss_time, converged, ErrStat, ErrMsg)
        GOTO 800
      END IF
      IF (mb%has_sys) THEN
        CALL CD_Check_System_Plausibility(mb%system, opts%max_strain, t, ErrStat, ErrMsg, sys_lines)
        IF (ErrStat /= CD_DECKDRV_OK) THEN
          ErrMsg = TRIM(ErrMsg)//INSPECTION_NOTE
          GOTO 800
        END IF
      END IF
      CALL mb_outputs(t)
      IF (ErrStat /= CD_DECKDRV_OK) GOTO 800
      IF (ALLOCATED(probe_rec) .AND. probe_armed) CALL probe_record(step, t)
      CALL update_driver_progress(progress, step, t)
    END DO
    IF (mb%implicit .AND. mb%n_steps_imp > 0) THEN
      WRITE (*, '(A,F6.2,A,I0,A,I0)') '  Monolithic body/point step: mean outer iterations ', &
        REAL(mb%n_outer, wp)/REAL(mb%n_steps_imp, wp), ', max ', mb%max_outer, ', step halvings ', mb%n_subdiv
    END IF
    CALL CD_Classify_Dynamic_Completion('multibody dynamic run', nstep, miss_count, max_consecutive_miss, &
                                        first_miss_time, last_miss_time, converged, ErrStat, ErrMsg)
    IF (ErrStat == CD_DECKDRV_OK .AND. converged) CALL range_write(mb_ranges, out_root, ErrStat, ErrMsg)
800 CONTINUE
    CLOSE (unit)
    IF (ALLOCATED(pos_units)) CALL close_dynamic_line_outputs(pos_units, ten_units)
    IF (ALLOCATED(cpos_units)) CALL close_dynamic_line_outputs(cpos_units, cten_units)
    IF (ALLOCATED(rod_units)) CALL close_dynamic_rod_outputs(rod_units)
900 CONTINUE
    IF (ErrStat /= CD_DECKDRV_OK) converged = .FALSE.
    IF (mb%has_sys) CALL CD_End_System(mb%system, es, em)
    IF (ALLOCATED(mb%cables)) CALL end_hermite_cables(mb%cables)
    probe_armed = .FALSE.

  CONTAINS

    SUBROUTINE probe_record(col, time)
      !! Column col of the probe record: t, r(3), v(3), rot_mat(9, column-major), omega(3), a(3) of
      !! body 1; finite-EI cable 1 energy (kinetic plus elastic), End A connection moment(3) and end
      !! force(3) on its attachment (committed).
      INTEGER, INTENT(IN) :: col
      REAL(wp), INTENT(IN) :: time
      probe_rec(1, col) = time
      probe_rec(2:4, col) = mb%rigid(1)%r
      probe_rec(5:7, col) = mb%rigid(1)%v
      probe_rec(8:16, col) = RESHAPE(mb%rigid(1)%rot_mat, [9])
      probe_rec(17:19, col) = mb%rigid(1)%omega
      probe_rec(20:22, col) = mb%rigid(1)%a
      ! finite-EI cable 1: structural kinetic plus elastic energy, committed End A connection
      ! moment and end force on its attachment
      IF (SIZE(mb%cables) > 0) THEN
        BLOCK
          REAL(wp) :: ke, se
          INTEGER :: es_p
          CHARACTER(200) :: em_p
          CALL CD_HermiteCable_Dyn_Energy(mb%cables(1)%line, ke, se, es_p, em_p)
          probe_rec(23, col) = ke + se
          IF (es_p /= CD_HCDYN_OK) probe_rec(23, col) = -HUGE(CD_ONE)
        END BLOCK
        probe_rec(24:26, col) = mb%cab_mend(:, 1)
        probe_rec(27:29, col) = mb%cab_fend(:, 1)
      END IF
    END SUBROUTINE probe_record

    SUBROUTINE mb_hydro(time, initial)
      REAL(wp), INTENT(IN) :: time
      LOGICAL, INTENT(IN) :: initial
      IF (mb%has_sys) THEN
        IF (mb%has_dyn) CALL update_system_point_hydro(mb%system, points, opts, time, hydro_work, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        IF (initial) THEN
          CALL update_system_line_hydro(mb%system, opts, time, hydro_work, ErrStat, ErrMsg, initial_condition=.TRUE.)
        ELSE
          CALL update_system_line_hydro(mb%system, opts, time, hydro_work, ErrStat, ErrMsg)
        END IF
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      END IF
      IF (SIZE(mb%cables) > 0) CALL update_hermite_deck_fluid(mb%cables, opts, time, ErrStat, ErrMsg)
    END SUBROUTINE mb_hydro

    SUBROUTINE mb_outputs(time)
      REAL(wp), INTENT(IN) :: time
      REAL(wp) :: vals(SIZE(channels))
      LOGICAL :: found
      INTEGER :: j
      CALL CD_Deck_Range_Sample_Aggregate(mb_ranges, mb%has_sys, mb%system, mb%cables, mb%line_is_cable, &
                                          mb%line_obj_index, time, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      DO j = 1, SIZE(channels)
        IF (is_object_channel(to_lower(channels(j)))) THEN
          CALL mb_object_channel(mb, points, opts, time, channels(j), vals(j), found, ErrStat, ErrMsg, bathymetry)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
          IF (.NOT. found) THEN
            CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(channels(j))//'": no state for that body or rod'); RETURN
          END IF
        ELSE IF (is_point_force_channel(to_lower(channels(j)))) THEN
          CALL mb_point_force(mb, channels(j), vals(j), ErrStat, ErrMsg)
        ELSE
          CALL CD_Eval_Aggregate_Channel(channels(j), mb%has_sys, mb%system, mb%cables, mb%line_is_cable, &
                                         mb%line_obj_index, vals(j), ErrStat, ErrMsg, ranges=mb_ranges)
        END IF
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        IF (.NOT. IEEE_IS_FINITE(vals(j))) THEN
          CALL fail_solve(ErrStat, ErrMsg, 'non-finite multibody output channel "'//TRIM(channels(j))//'"'); RETURN
        END IF
      END DO
      WRITE (unit, ROW_VALUES_FMT) time, (char_tab(), vals(j), j=1, SIZE(channels))
      IF (mb%has_sys) THEN
        CALL write_dynamic_system_line_outputs(time, sys_lines, mb%system, pos_units, ten_units, output_work, &
                                               ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      END IF
      IF (SIZE(mb%cables) > 0) THEN
        CALL write_dynamic_hermite_line_outputs(time, cab_lines, mb%cables, cpos_units, cten_units, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      END IF
      CALL write_dynamic_rod_outputs(time, own, mb%rods, rod_units, ErrStat, ErrMsg)
    END SUBROUTINE mb_outputs
  END SUBROUTINE write_multibody_dynamic_out

  SUBROUTINE CD_Multibody_Probe_Arm(v0, omega0)
    !! Arm the multibody-march probe (verification tests): the next multibody run starts body 1
    !! with velocity v0 and angular velocity omega0 (global frame, m/s and rad/s) and records its
    !! full-precision state after every step (CD_Multibody_Probe_Get). The run disarms it.
    REAL(wp), INTENT(IN) :: v0(3), omega0(3)
    probe_armed = .TRUE.
    probe_v0 = v0
    probe_w0 = omega0
    IF (ALLOCATED(probe_rec)) DEALLOCATE (probe_rec)
  END SUBROUTINE CD_Multibody_Probe_Arm

  SUBROUTINE CD_Multibody_Probe_Get(rec)
    !! The record of the last probed multibody run: rec(CD_MB_PROBE_NCOL, 0:nstep), columns t,
    !! r(3), v(3), rot_mat(9, column-major), omega(3), a(3) of body 1 (1-22), then finite-EI cable
    !! 1's energy (23), committed End A connection moment (24-26) and end force (27-29)
    !! (probe_record); unallocated when none.
    REAL(wp), ALLOCATABLE, INTENT(OUT) :: rec(:, :)
    IF (ALLOCATED(probe_rec)) rec = probe_rec
  END SUBROUTINE CD_Multibody_Probe_Get

  SUBROUTINE mb_snap_pinned(rod, rigid)
    !! A pinned rod keeps End A on its pin: a fixed point, or the pin point of its parent body.
    !! Its centre, velocity and acceleration follow the pin motion and the rod's own rotation.
    TYPE(RodState), INTENT(INOUT) :: rod
    TYPE(RigidBodyState), INTENT(IN) :: rigid(:)
    REAL(wp) :: p(3), v_pin(3), a_pin(3), arm(3)
    IF (.NOT. rod%is_pinned) RETURN
    v_pin = CD_ZERO
    a_pin = CD_ZERO
    IF (rod%parent > 0) THEN
      ASSOCIATE (b => rigid(rod%parent))
        p = MATMUL(b%rot_mat, rod%pin_body)
        rod%pin = b%r + p
        v_pin = b%v + cross3(b%omega, p)
        a_pin = b%a + cross3(b%alpha, p) + cross3(b%omega, cross3(b%omega, p))
      END ASSOCIATE
    END IF
    arm = rod%half_length*rod%rot_mat(:, 1)
    rod%r = rod%pin + arm
    rod%v = v_pin + cross3(rod%omega, arm)
    rod%a = a_pin + cross3(rod%alpha, arm) + cross3(rod%omega, cross3(rod%omega, arm))
  END SUBROUTINE mb_snap_pinned

  SUBROUTINE mb_attachment_motion(mb, c, x, v, a, es, em, dcm, w, al)
    !! Position, velocity and acceleration of cable c's End A attachment (body point, rod end or
    !! held point); optionally the attached object's orientation as a global-to-object DCM (the
    !! OpenFAST mesh convention of CD_HFMF_UpdateStates) and its angular velocity and
    !! acceleration in global axes (identity and zero at a held point). es/em carry the held
    !! point's kinematics query status (CD_HFMF_OK otherwise).
    TYPE(MultibodyMarch), INTENT(IN) :: mb
    INTEGER, INTENT(IN) :: c
    REAL(wp), INTENT(OUT) :: x(3), v(3), a(3)
    INTEGER, INTENT(OUT) :: es
    CHARACTER(*), INTENT(OUT) :: em
    REAL(wp), INTENT(OUT), OPTIONAL :: dcm(3, 3), w(3), al(3)
    REAL(wp) :: arm(3), rot(3, 3), wo(3), alo(3)
    es = CD_HFMF_OK
    em = ''
    rot = CD_ZERO
    rot(1, 1) = CD_ONE
    rot(2, 2) = CD_ONE
    rot(3, 3) = CD_ONE
    wo = CD_ZERO
    alo = CD_ZERO
    SELECT CASE (mb%cab_kind(c))
    CASE (1)
      ASSOCIATE (b => mb%rigid(mb%cab_obj(c)))
        arm = MATMUL(b%rot_mat, mb%cab_off(:, c))
        x = b%r + arm
        v = b%v + cross3(b%omega, arm)
        a = b%a + cross3(b%alpha, arm) + cross3(b%omega, cross3(b%omega, arm))
        rot = b%rot_mat
        wo = b%omega
        alo = b%alpha
      END ASSOCIATE
    CASE (2)
      ASSOCIATE (r => mb%rods(mb%cab_obj(c)))
        arm = mb%cab_off(1, c)*r%half_length*r%rot_mat(:, 1)
        x = r%r + arm
        v = r%v + cross3(r%omega, arm)
        a = r%a + cross3(r%alpha, arm) + cross3(r%omega, cross3(r%omega, arm))
        rot = r%rot_mat
        wo = r%omega
        alo = r%alpha
      END ASSOCIATE
    CASE DEFAULT
      CALL CD_HFMF_GetCoupledKinematics(mb%cables(c), x, v, a, es, em)
      v = CD_ZERO
      a = CD_ZERO
    END SELECT
    IF (PRESENT(dcm)) dcm = TRANSPOSE(rot)
    IF (PRESENT(w)) w = wo
    IF (PRESENT(al)) al = alo
  END SUBROUTINE mb_attachment_motion

  SUBROUTINE mb_cable_drive(mb, c, dt, ErrStat, ErrMsg)
    !! Step cable c over dt with its End A attachment's current (end-of-step) motion, the object
    !! orientation driving a clamped or elastic connection, and read its committed end force and
    !! connection moment into cab_fend/cab_mend.
    TYPE(MultibodyMarch), INTENT(INOUT) :: mb
    INTEGER, INTENT(IN) :: c
    REAL(wp), INTENT(IN) :: dt
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp) :: xa(3), va(3), aa(3), dcm(3, 3), wa(3), ala(3)
    INTEGER :: es
    CHARACTER(300) :: em
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    mb%cables(c)%dt = dt
    IF (mb%cab_clamp(c)) THEN
      CALL mb_attachment_motion(mb, c, xa, va, aa, es, em, dcm, wa, ala)
      IF (es == CD_HFMF_OK) CALL CD_HFMF_UpdateStates(mb%cables(c), xa, va, aa, es, em, u_orientation=dcm, &
                                                      u_angular_velocity=wa, u_angular_acceleration=ala)
    ELSE
      CALL mb_attachment_motion(mb, c, xa, va, aa, es, em)
      IF (es == CD_HFMF_OK) CALL CD_HFMF_UpdateStates(mb%cables(c), xa, va, aa, es, em)
    END IF
    IF (es == CD_HFMF_OK) CALL CD_HFMF_CalcOutput(mb%cables(c), mb%cab_fend(:, c), es, em, &
                                                  y_moment=mb%cab_mend(:, c))
    IF (es /= CD_HFMF_OK) CALL fail_solve(ErrStat, ErrMsg, 'multibody finite-EI cable step failed: '//TRIM(em))
  END SUBROUTINE mb_cable_drive

  SUBROUTINE mb_cable_committed_loads(mb, c, f, m, ErrStat, ErrMsg)
    !! Committed end force and connection moment of cable c on its End A attachment.
    TYPE(MultibodyMarch), INTENT(INOUT) :: mb
    INTEGER, INTENT(IN) :: c
    REAL(wp), INTENT(OUT) :: f(3), m(3)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: es
    CHARACTER(300) :: em
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    CALL CD_HFMF_CalcOutput(mb%cables(c), f, es, em, y_moment=m)
    IF (es /= CD_HFMF_OK) CALL fail_solve(ErrStat, ErrMsg, 'multibody cable end-load query failed: '//TRIM(em))
  END SUBROUTINE mb_cable_committed_loads

  SUBROUTINE mb_cable_arm(mb, c, arm)
    !! Arm from the attached object's reference point (body reference, rod centre) to cable c's
    !! End A.
    TYPE(MultibodyMarch), INTENT(IN) :: mb
    INTEGER, INTENT(IN) :: c
    REAL(wp), INTENT(OUT) :: arm(3)
    arm = CD_ZERO
    SELECT CASE (mb%cab_kind(c))
    CASE (1)
      arm = MATMUL(mb%rigid(mb%cab_obj(c))%rot_mat, mb%cab_off(:, c))
    CASE (2)
      arm = mb%cab_off(1, c)*mb%rods(mb%cab_obj(c))%half_length*mb%rods(mb%cab_obj(c))%rot_mat(:, 1)
    END SELECT
  END SUBROUTINE mb_cable_arm

  SUBROUTINE mb_rod_bases(mb, points, rod, bases, arms)
    !! System coupled-DOF bases (-1: no EI=0 line) and arms of a rod's End A and End B points.
    TYPE(MultibodyMarch), INTENT(IN) :: mb
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(RodState), INTENT(IN) :: rod
    INTEGER, INTENT(OUT) :: bases(2)
    REAL(wp), INTENT(OUT) :: arms(3, 2)
    bases = -1
    arms(:, 1) = -rod%half_length*rod%rot_mat(:, 1)
    arms(:, 2) = rod%half_length*rod%rot_mat(:, 1)
    IF (.NOT. mb%has_sys) RETURN
    IF (rod%point_a_index > 0) bases(1) = system_point_base(mb%system, points(rod%point_a_index)%id)
    IF (rod%point_b_index > 0) bases(2) = system_point_base(mb%system, points(rod%point_b_index)%id)
  END SUBROUTINE mb_rod_bases

  SUBROUTINE mb_body_terms(mb, points, opts, ib, time, dt, dv0, fx, mx, m6, rhs, ErrStat, ErrMsg, bathymetry, &
                           state, explicit_lines)
    !! The corrector system m6 x = rhs of body ib (rigid6_body_acceleration's loads plus the extra
    !! point loads fx/mx of the cables attached to it), about its reference point. state replaces
    !! the body's march state (the monolithic scheme evaluates it at the alpha level);
    !! explicit_lines takes the line loads in mb%loads as given, without the end-node inertia
    !! derivative (the monolithic loads already carry the end-node inertia).
    TYPE(MultibodyMarch), INTENT(IN) :: mb
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    INTEGER, INTENT(IN) :: ib
    REAL(wp), INTENT(IN) :: time, dt, dv0(6), fx(3), mx(3)
    REAL(wp), INTENT(OUT) :: m6(6, 6), rhs(6)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    TYPE(RigidBodyState), INTENT(IN), OPTIONAL :: state
    LOGICAL, INTENT(IN), OPTIONAL :: explicit_lines
    LOGICAL :: expl
    expl = .FALSE.
    IF (PRESENT(explicit_lines)) expl = explicit_lines
    IF (PRESENT(state)) THEN
      CALL body_terms_of(state)
    ELSE
      CALL body_terms_of(mb%rigid(ib))
    END IF
  CONTAINS
    SUBROUTINE body_terms_of(body)
      TYPE(RigidBodyState), INTENT(IN) :: body
      INTEGER :: ip, pidx, n
      INTEGER, ALLOCATABLE :: att_base(:)
      REAL(wp), ALLOCATABLE :: att_arm(:, :)
      REAL(wp) :: f_body(3), m_global(3), f_env(3), meff, drag3(3, 3), load_dv(6, 6), cg6(6, 6)
      REAL(wp) :: f2(3), m2(3), rod6(6, 6), rodd6(6, 6), arm(3), acc(3), alpha(3)
      REAL(wp) :: no_d(0, 0), no_a(0)

      CALL rigid6_environment_force(body, opts, time, f_env, meff, drag3, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL rigid6_hydrostatics(body, opts, time, f_body, m_global, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL rigid6_cg_inertia(body, cg6, f2, m2)
      f_body = f_body + f2 + f_env
      m_global = m_global + m2
      load_dv = CD_ZERO
      IF (ALLOCATED(body%att_rods)) THEN
        CALL rigid6_rod_loads(body, opts, time, f2, m2, rod6, rodd6, ErrStat, ErrMsg, bathymetry)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        f_body = f_body + f2
        m_global = m_global + m2
        cg6 = cg6 + rod6
      END IF
      CALL rigid6_seabed_contact(body, opts, f2, m2, load_dv, ErrStat, ErrMsg, bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      f_body = f_body + f2
      m_global = m_global + m2
      load_dv(1:3, 1:3) = load_dv(1:3, 1:3) + drag3
      IF (ALLOCATED(body%att_rods)) load_dv = load_dv + rodd6
      CALL rigid6_external_load(body, f2, drag3)
      f_body = f_body + f2 + fx
      m_global = m_global + mx
      load_dv(1:3, 1:3) = load_dv(1:3, 1:3) + drag3
      n = SIZE(body%point_indices)
      ALLOCATE (att_base(n), att_arm(3, n))
      att_base = -1
      DO ip = 1, n
        pidx = body%point_indices(ip)
        arm = MATMUL(body%rot_mat, points(pidx)%body_offset)
        att_arm(:, ip) = arm
        IF (.NOT. mb%has_sys) CYCLE
        att_base(ip) = system_point_base(mb%system, points(pidx)%id)
        IF (att_base(ip) < 0) CYCLE
        f2 = mb%loads(att_base(ip) + 1:att_base(ip) + 3)
        f_body = f_body + f2
        m_global = m_global + cross3(arm, f2)
      END DO
      IF (mb%has_sys .AND. .NOT. expl) THEN
        CALL rigid_coupled_acceleration(mb%dload_da, dt, mb%a, att_base, att_arm, meff, cg6, body%inertia, &
                                        body%rot_mat, body%omega, f_body, m_global, dv0, load_dv, acc, alpha, &
                                        ErrStat, ErrMsg, m6_out=m6, rhs_out=rhs)
      ELSE
        CALL rigid_coupled_acceleration(no_d, dt, no_a, att_base(1:0), att_arm(:, 1:0), meff, cg6, body%inertia, &
                                        body%rot_mat, body%omega, f_body, m_global, dv0, load_dv, acc, alpha, &
                                        ErrStat, ErrMsg, m6_out=m6, rhs_out=rhs)
      END IF
    END SUBROUTINE body_terms_of
  END SUBROUTINE mb_body_terms

  SUBROUTINE mb_rod_terms(mb, points, opts, ir, time, dt, dv0, fx, mx, m6, rhs, ErrStat, ErrMsg, bathymetry, &
                          state, explicit_lines)
    !! The corrector system m6 x = rhs of rod ir about its centre (rod_body_acceleration's loads
    !! plus the extra point loads fx/mx of the cables attached to it). state and explicit_lines
    !! as in mb_body_terms.
    TYPE(MultibodyMarch), INTENT(IN) :: mb
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    INTEGER, INTENT(IN) :: ir
    REAL(wp), INTENT(IN) :: time, dt, dv0(6), fx(3), mx(3)
    REAL(wp), INTENT(OUT) :: m6(6, 6), rhs(6)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    TYPE(RodState), INTENT(IN), OPTIONAL :: state
    LOGICAL, INTENT(IN), OPTIONAL :: explicit_lines
    LOGICAL :: expl
    expl = .FALSE.
    IF (PRESENT(explicit_lines)) expl = explicit_lines
    IF (PRESENT(state)) THEN
      CALL rod_terms_of(state)
    ELSE
      CALL rod_terms_of(mb%rods(ir))
    END IF
  CONTAINS
    SUBROUTINE rod_terms_of(rod)
      TYPE(RodState), INTENT(IN) :: rod
      INTEGER :: bases(2), k
      REAL(wp) :: arms(3, 2), f_body(3), m_global(3), f2(3), m2(3), added6(6, 6), drag6(6, 6), c6(6, 6)
      REAL(wp) :: acc(3), alpha(3), no_d(0, 0), no_a(0)

      CALL mb_rod_bases(mb, points, rod, bases, arms)
      f_body = [CD_ZERO, CD_ZERO, -rod%mass*opts%g] + fx
      m_global = mx
      DO k = 1, 2
        IF (bases(k) < 0) CYCLE
        f2 = mb%loads(bases(k) + 1:bases(k) + 3)
        f_body = f_body + f2
        m_global = m_global + cross3(arms(:, k), f2)
      END DO
      CALL rod_environment_force(rod, opts, time, f2, m2, added6, drag6, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      f_body = f_body + f2
      m_global = m_global + m2
      CALL rod_seabed_contact(rod, opts, f2, m2, c6, ErrStat, ErrMsg, bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      f_body = f_body + f2
      m_global = m_global + m2
      IF (mb%has_sys .AND. .NOT. expl) THEN
        CALL rigid_coupled_acceleration(mb%dload_da, dt, mb%a, bases, arms, rod%mass, added6, rod%inertia, &
                                        rod%rot_mat, rod%omega, f_body, m_global, dv0, drag6 + c6, acc, alpha, &
                                        ErrStat, ErrMsg, m6_out=m6, rhs_out=rhs)
      ELSE
        CALL rigid_coupled_acceleration(no_d, dt, no_a, bases(1:0), arms(:, 1:0), rod%mass, added6, rod%inertia, &
                                        rod%rot_mat, rod%omega, f_body, m_global, dv0, drag6 + c6, acc, alpha, &
                                        ErrStat, ErrMsg, m6_out=m6, rhs_out=rhs)
      END IF
    END SUBROUTINE rod_terms_of
  END SUBROUTINE mb_rod_terms

  SUBROUTINE mb_group_system(m6b, rhsb, xb, wb, has_body, nc, m6c, rhsc, pinw, rc, wc, amat, bvec)
    !! The reduced-coordinate equations amat [x6; yc] = bvec of mb_group_solve (see there).
    REAL(wp), INTENT(IN) :: m6b(6, 6), rhsb(6), xb(3), wb(3)
    LOGICAL, INTENT(IN) :: has_body
    INTEGER, INTENT(IN) :: nc
    REAL(wp), INTENT(IN) :: m6c(6, 6, nc), rhsc(6, nc), pinw(3, nc), rc(3, nc), wc(3, nc)
    REAL(wp), INTENT(OUT) :: amat(:, :), bvec(:)
    INTEGER :: k, o, nb
    REAL(wp) :: gb(6, 6), gc(6, 3), bias(6), r(6), p(3), l(3)
    nb = MERGE(6, 0, has_body)
    amat = CD_ZERO
    bvec = CD_ZERO
    IF (has_body) THEN
      amat(1:6, 1:6) = m6b
      bvec(1:6) = rhsb
    END IF
    DO k = 1, nc
      o = nb + 3*(k - 1)
      p = pinw(:, k) - xb
      l = rc(:, k) - pinw(:, k)
      gb = CD_ZERO
      gb(1, 1) = CD_ONE
      gb(2, 2) = CD_ONE
      gb(3, 3) = CD_ONE
      gb(1:3, 4:6) = -skew3(p)
      gc = CD_ZERO
      gc(1:3, :) = -skew3(l)
      gc(4, 1) = CD_ONE
      gc(5, 2) = CD_ONE
      gc(6, 3) = CD_ONE
      bias = CD_ZERO
      bias(1:3) = cross3(wc(:, k), cross3(wc(:, k), l))
      IF (has_body) bias(1:3) = bias(1:3) + cross3(wb, cross3(wb, p))
      r = rhsc(:, k) - MATMUL(m6c(:, :, k), bias)
      IF (has_body) THEN
        amat(1:6, 1:6) = amat(1:6, 1:6) + MATMUL(TRANSPOSE(gb), MATMUL(m6c(:, :, k), gb))
        amat(1:6, o + 1:o + 3) = MATMUL(TRANSPOSE(gb), MATMUL(m6c(:, :, k), gc))
        amat(o + 1:o + 3, 1:6) = MATMUL(TRANSPOSE(gc), MATMUL(m6c(:, :, k), gb))
        bvec(1:6) = bvec(1:6) + MATMUL(TRANSPOSE(gb), r)
      END IF
      amat(o + 1:o + 3, o + 1:o + 3) = MATMUL(TRANSPOSE(gc), MATMUL(m6c(:, :, k), gc))
      bvec(o + 1:o + 3) = MATMUL(TRANSPOSE(gc), r)
    END DO
  END SUBROUTINE mb_group_system

  SUBROUTINE mb_group_solve(m6b, rhsb, xb, wb, has_body, nc, m6c, rhsc, pinw, rc, wc, x6, yc, ac, ErrStat, ErrMsg)
    !! Accelerations of a body and the rods pinned to it, in reduced coordinates: the body twist
    !! acceleration x6 (6) and each pinned rod's angular acceleration yc(:, k). Rod k's centre
    !! acceleration is X_k = Gb x6 + Gc yc + bias with Gb = [[I, -[p]x], [0, 0]], p = pin - xb,
    !! Gc = [[-[l]x], [I]], l = rc - pin, bias = [wb x (wb x p) + wc x (wc x l); 0]; the equations
    !! are the virtual work of every member, Gb^T (M_k X_k - rhs_k) summed into the body rows and
    !! Gc^T (M_k X_k - rhs_k) in rod k's. Without a body (has_body false) the pin is fixed and
    !! only the rod rows remain. ac(:, k) returns X_k(1:3).
    REAL(wp), INTENT(IN) :: m6b(6, 6), rhsb(6), xb(3), wb(3)
    LOGICAL, INTENT(IN) :: has_body
    INTEGER, INTENT(IN) :: nc
    REAL(wp), INTENT(IN) :: m6c(6, 6, nc), rhsc(6, nc), pinw(3, nc), rc(3, nc), wc(3, nc)
    REAL(wp), INTENT(OUT) :: x6(6), yc(3, nc), ac(3, nc)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: k, n, o, nb
    REAL(wp) :: p(3), l(3), xk(6)
    REAL(wp), ALLOCATABLE :: amat(:, :), bvec(:)
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    nb = MERGE(6, 0, has_body)
    n = nb + 3*nc
    ALLOCATE (amat(n, n), bvec(n))
    x6 = CD_ZERO
    yc = CD_ZERO
    ac = CD_ZERO
    CALL mb_group_system(m6b, rhsb, xb, wb, has_body, nc, m6c, rhsc, pinw, rc, wc, amat, bvec)
    CALL CD_Solve_Dense_As_Banded(amat, bvec, ErrStat, em)
    IF (ErrStat /= CD_LINALG_OK .OR. .NOT. ALL(IEEE_IS_FINITE(bvec))) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: body/pinned-rod acceleration system is singular: '//TRIM(em)
      RETURN
    END IF
    ErrStat = CD_DECKDRV_OK
    IF (has_body) x6 = bvec(1:6)
    DO k = 1, nc
      o = nb + 3*(k - 1)
      yc(:, k) = bvec(o + 1:o + 3)
      p = pinw(:, k) - xb
      l = rc(:, k) - pinw(:, k)
      xk(1:3) = cross3(yc(:, k), l) + cross3(wc(:, k), cross3(wc(:, k), l))
      IF (has_body) xk(1:3) = xk(1:3) + x6(1:3) + cross3(x6(4:6), p) + cross3(wb, cross3(wb, p))
      ac(:, k) = xk(1:3)
    END DO
  END SUBROUTINE mb_group_solve

  SUBROUTINE mb_accelerations(mb, points, opts, time, dt, ErrStat, ErrMsg, bathymetry)
    !! End-of-step (dt > 0, from the predictor state and the loads in mb%loads/dload_da/a and
    !! mb%cab_force) or instantaneous (dt = 0) accelerations of every free body, free rod and
    !! pinned rod; returned in mb%acc_b/alpha_b and mb%acc_r/alpha_r.
    TYPE(MultibodyMarch), INTENT(INOUT) :: mb
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time, dt
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    INTEGER :: ib, ir, c, k, nc
    INTEGER, ALLOCATABLE :: kids(:)
    REAL(wp) :: fxb(3, SIZE(mb%rigid)), mxb(3, SIZE(mb%rigid)), fxr(3, SIZE(mb%rods)), mxr(3, SIZE(mb%rods))
    REAL(wp) :: arm(3), dv0(6), m6b(6, 6), rhsb(6), x6(6)
    REAL(wp), ALLOCATABLE :: m6c(:, :, :), rhsc(:, :), pinw(:, :), rc(:, :), wc(:, :), yc(:, :), ac(:, :)
    REAL(wp) :: m6(6, 6), rhs(6)

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    ! cable end loads on their attachments (point forces, and the connection moment of a cable
    ! clamped or elastically connected to its object)
    fxb = CD_ZERO
    mxb = CD_ZERO
    fxr = CD_ZERO
    mxr = CD_ZERO
    DO c = 1, SIZE(mb%cables)
      CALL mb_cable_arm(mb, c, arm)
      SELECT CASE (mb%cab_kind(c))
      CASE (1)
        fxb(:, mb%cab_obj(c)) = fxb(:, mb%cab_obj(c)) + mb%cab_force(:, c)
        mxb(:, mb%cab_obj(c)) = mxb(:, mb%cab_obj(c)) + cross3(arm, mb%cab_force(:, c)) + mb%cab_moment(:, c)
      CASE (2)
        fxr(:, mb%cab_obj(c)) = fxr(:, mb%cab_obj(c)) + mb%cab_force(:, c)
        mxr(:, mb%cab_obj(c)) = mxr(:, mb%cab_obj(c)) + cross3(arm, mb%cab_force(:, c)) + mb%cab_moment(:, c)
      END SELECT
    END DO
    ! bodies with their pinned rods
    DO ib = 1, SIZE(mb%rigid)
      dv0 = CD_ZERO
      IF (dt > CD_ZERO) THEN
        dv0(1:3) = -CD_RIGID_NEWMARK_GAMMA*dt*mb%old_rigid(ib)%a
        dv0(4:6) = -CD_RIGID_NEWMARK_GAMMA*dt*mb%old_rigid(ib)%alpha
      END IF
      CALL mb_body_terms(mb, points, opts, ib, time, dt, dv0, fxb(:, ib), mxb(:, ib), m6b, rhsb, ErrStat, ErrMsg, &
                         bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      kids = PACK([(ir, ir=1, SIZE(mb%rods))], [(mb%rods(ir)%parent == ib, ir=1, SIZE(mb%rods))])
      nc = SIZE(kids)
      ALLOCATE (m6c(6, 6, nc), rhsc(6, nc), pinw(3, nc), rc(3, nc), wc(3, nc), yc(3, nc), ac(3, nc))
      DO k = 1, nc
        ir = kids(k)
        dv0 = CD_ZERO
        IF (dt > CD_ZERO) THEN
          dv0(1:3) = -CD_RIGID_NEWMARK_GAMMA*dt*mb%old_rods(ir)%a
          dv0(4:6) = -CD_RIGID_NEWMARK_GAMMA*dt*mb%old_rods(ir)%alpha
        END IF
        CALL mb_rod_terms(mb, points, opts, ir, time, dt, dv0, fxr(:, ir), mxr(:, ir), m6c(:, :, k), rhsc(:, k), &
                          ErrStat, ErrMsg, bathymetry)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        pinw(:, k) = mb%rods(ir)%pin
        rc(:, k) = mb%rods(ir)%r
        wc(:, k) = mb%rods(ir)%omega
      END DO
      IF (nc == 0) THEN
        CALL solve_rigid6x6(m6b, rhsb, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        x6 = rhsb
      ELSE
        CALL mb_group_solve(m6b, rhsb, mb%rigid(ib)%r, mb%rigid(ib)%omega, .TRUE., nc, m6c, rhsc, pinw, rc, wc, &
                            x6, yc, ac, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        DO k = 1, nc
          mb%acc_r(:, kids(k)) = ac(:, k)
          mb%alpha_r(:, kids(k)) = yc(:, k)
        END DO
      END IF
      mb%acc_b(:, ib) = x6(1:3)
      mb%alpha_b(:, ib) = x6(4:6)
      DEALLOCATE (m6c, rhsc, pinw, rc, wc, yc, ac)
    END DO
    ! free rods and rods pinned to a fixed point
    DO ir = 1, SIZE(mb%rods)
      IF (mb%rods(ir)%parent > 0) CYCLE
      IF (.NOT. (mb%rods(ir)%is_free .OR. mb%rods(ir)%is_pinned)) CYCLE
      dv0 = CD_ZERO
      IF (dt > CD_ZERO) THEN
        dv0(1:3) = -CD_RIGID_NEWMARK_GAMMA*dt*mb%old_rods(ir)%a
        dv0(4:6) = -CD_RIGID_NEWMARK_GAMMA*dt*mb%old_rods(ir)%alpha
      END IF
      CALL mb_rod_terms(mb, points, opts, ir, time, dt, dv0, fxr(:, ir), mxr(:, ir), m6, rhs, ErrStat, ErrMsg, &
                        bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      IF (mb%rods(ir)%is_pinned) THEN
        ALLOCATE (m6c(6, 6, 1), rhsc(6, 1), pinw(3, 1), rc(3, 1), wc(3, 1), yc(3, 1), ac(3, 1))
        m6c(:, :, 1) = m6
        rhsc(:, 1) = rhs
        pinw(:, 1) = mb%rods(ir)%pin
        rc(:, 1) = mb%rods(ir)%r
        wc(:, 1) = mb%rods(ir)%omega
        CALL mb_group_solve(m6, rhs, [CD_ZERO, CD_ZERO, CD_ZERO], [CD_ZERO, CD_ZERO, CD_ZERO], .FALSE., 1, m6c, &
                            rhsc, pinw, rc, wc, x6, yc, ac, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        mb%acc_r(:, ir) = ac(:, 1)
        mb%alpha_r(:, ir) = yc(:, 1)
        DEALLOCATE (m6c, rhsc, pinw, rc, wc, yc, ac)
      ELSE
        CALL solve_rigid6x6(m6, rhs, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        mb%acc_r(:, ir) = rhs(1:3)
        mb%alpha_r(:, ir) = rhs(4:6)
      END IF
    END DO
  END SUBROUTINE mb_accelerations

  SUBROUTINE mb_scatter(mb, points, ErrStat, ErrMsg)
    !! Write the current body and rod motion into the EI=0 system's coupled points: the lines'
    !! current end motion (so the Free/Connect points keep theirs) with the Body<N> and
    !! Rod<N>A/B points overwritten by their objects.
    TYPE(MultibodyMarch), INTENT(INOUT) :: mb
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: es, ir, k, base
    INTEGER :: bases(2)
    REAL(wp) :: arms(3, 2)
    CHARACTER(160) :: em
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (.NOT. mb%has_sys) RETURN
    CALL CD_Get_System_CoupledMotion(mb%system, mb%q, mb%v, mb%a, es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      CALL fail_solve(ErrStat, ErrMsg, 'multibody coupled-motion query failed: '//TRIM(em)); RETURN
    END IF
    CALL scatter_rigid6_point_motion(mb%system, points, mb%rigid, mb%q, mb%v, mb%a)
    DO ir = 1, SIZE(mb%rods)
      CALL mb_rod_bases(mb, points, mb%rods(ir), bases, arms)
      DO k = 1, 2
        base = bases(k)
        IF (base < 0) CYCLE
        mb%q(base + 1:base + 3) = mb%rods(ir)%r + arms(:, k)
        mb%v(base + 1:base + 3) = mb%rods(ir)%v + cross3(mb%rods(ir)%omega, arms(:, k))
        mb%a(base + 1:base + 3) = mb%rods(ir)%a + cross3(mb%rods(ir)%alpha, arms(:, k)) + &
                                  cross3(mb%rods(ir)%omega, cross3(mb%rods(ir)%omega, arms(:, k)))
      END DO
    END DO
    CALL CD_Update_System_Point_States(mb%system, mb%q, mb%v, mb%a, es, em)
    IF (es /= CD_SYSTEM_OK) CALL fail_solve(ErrStat, ErrMsg, 'multibody point-state update failed: '//TRIM(em))
  END SUBROUTINE mb_scatter

  SUBROUTINE mb_line_loads(mb, ErrStat, ErrMsg)
    !! The EI=0 line loads on the coupled points and their end-node inertia derivative at the
    !! current line state (with the current point motion), and the cable end forces.
    TYPE(MultibodyMarch), INTENT(INOUT) :: mb
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: es, c
    CHARACTER(160) :: em
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (mb%has_sys) THEN
      CALL CD_Calc_System_CoupledLoads(mb%system, mb%loads, es, em)
      IF (es == CD_SYSTEM_OK) CALL CD_Calc_System_CoupledAccelDerivative(mb%system, mb%dload_da, es, em)
      IF (es /= CD_SYSTEM_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'multibody line-load query failed: '//TRIM(em)); RETURN
      END IF
    END IF
    DO c = 1, SIZE(mb%cables)
      CALL CD_HFMF_CalcOutput(mb%cables(c), mb%cab_force(:, c), es, em, y_moment=mb%cab_moment(:, c))
      IF (es /= CD_HFMF_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'multibody cable end-force query failed: '//TRIM(em)); RETURN
      END IF
    END DO
  END SUBROUTINE mb_line_loads

  SUBROUTINE mb_step(mb, points, opts, time, dt, converged, stalled, n_iter, ErrStat, ErrMsg, bathymetry)
    !! Advance the multibody march from time - dt to time, sub-cycled so that the explicit object
    !! positions resolve the stiffest object-mooring mode of the EI=0 lines (rigid_substep_count).
    TYPE(MultibodyMarch), INTENT(INOUT) :: mb
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time, dt
    LOGICAL, INTENT(OUT) :: converged, stalled
    INTEGER, INTENT(OUT) :: n_iter, ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    INTEGER :: ib, ir, ip, nsub, isub, it, k, bases(2)
    LOGICAL :: conv_s, stall_s
    REAL(wp) :: omega2, mass6(6), arms(3, 2), f_d(3), m_d(3), added6(6, 6), drag6(6, 6)

    converged = .TRUE.
    stalled = .FALSE.
    n_iter = 0
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (mb%has_sys) THEN
      k = mb%system%n_system_coupled_dof
      IF (.NOT. ALLOCATED(mb%q)) THEN
        ALLOCATE (mb%q(k), mb%v(k), mb%a(k), mb%loads(k), mb%dload_da(k, k))
      END IF
    END IF
    IF (.NOT. ALLOCATED(mb%acc_b)) THEN
      ALLOCATE (mb%acc_b(3, SIZE(mb%rigid)), mb%alpha_b(3, SIZE(mb%rigid)), mb%acc_r(3, SIZE(mb%rods)), &
                mb%alpha_r(3, SIZE(mb%rods)))
    END IF
    IF (mb%implicit) THEN
      ! monolithic implicit generalised-alpha: no sub-cycling
      IF (.NOT. mb%started) THEN
        CALL mb_start_accelerations(mb, points, opts, time, dt, ErrStat, ErrMsg, bathymetry)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      END IF
      IF (.NOT. ALLOCATED(mb%jb_off)) THEN
        CALL mb_junction_layout(mb, points)
        IF (mb%has_sys) ALLOCATE (mb%pt_af(SIZE(mb%system%points)))
      END IF
      IF (.NOT. opts%body_substep_accuracy) THEN
        CALL mb_step_implicit(mb, points, opts, time, dt, converged, stalled, n_iter, ErrStat, ErrMsg, bathymetry)
        RETURN
      END IF
    END IF
    omega2 = CD_ZERO
    ! a body-only monolithic deck still resolves its hydrostatic restoring
    IF (mb%has_sys .OR. mb%implicit) THEN
      DO ib = 1, SIZE(mb%rigid)
        BLOCK
          INTEGER :: att_base(SIZE(mb%rigid(ib)%point_indices))
          REAL(wp) :: att_arm(3, SIZE(mb%rigid(ib)%point_indices))
          DO ip = 1, SIZE(mb%rigid(ib)%point_indices)
            att_base(ip) = -1
            IF (mb%has_sys) att_base(ip) = system_point_base(mb%system, &
                                                             points(mb%rigid(ib)%point_indices(ip))%id)
            att_arm(:, ip) = MATMUL(mb%rigid(ib)%rot_mat, points(mb%rigid(ib)%point_indices(ip))%body_offset)
          END DO
          mass6(1:3) = mb%rigid(ib)%mass
          IF (mb%rigid(ib)%r(3) < CD_ZERO) mass6(1:3) = mass6(1:3) + opts%rhoW*mb%rigid(ib)%vol* &
                                                        MAX(CD_ZERO, mb%rigid(ib)%ca)
          mass6(4:6) = global_inertia_diag(mb%rigid(ib)%rot_mat, mb%rigid(ib)%inertia)
          IF (ALLOCATED(mb%rigid(ib)%att_rods)) THEN
            DO k = 1, SIZE(mb%rigid(ib)%att_rods)
              mass6(1:3) = mass6(1:3) + mb%rigid(ib)%att_rods(k)%mass
            END DO
          END IF
          omega2 = MAX(omega2, rigid_omega2_estimate(mb%system, att_base, att_arm, mass6, &
                                                     [CD_ZERO, CD_ZERO, mb%rigid(ib)%c33, mb%rigid(ib)%c44, &
                                                      mb%rigid(ib)%c55, CD_ZERO]))
        END BLOCK
      END DO
    END IF
    IF (mb%has_sys) THEN
      DO ir = 1, SIZE(mb%rods)
        IF (.NOT. (mb%rods(ir)%is_free .OR. mb%rods(ir)%is_pinned)) CYCLE
        CALL mb_rod_bases(mb, points, mb%rods(ir), bases, arms)
        CALL rod_environment_force(mb%rods(ir), opts, time - dt, f_d, m_d, added6, drag6, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        mass6(1:3) = mb%rods(ir)%mass
        mass6(4:6) = global_inertia_diag(mb%rods(ir)%rot_mat, mb%rods(ir)%inertia)
        DO k = 1, 6
          mass6(k) = mass6(k) + MAX(CD_ZERO, added6(k, k))
        END DO
        omega2 = MAX(omega2, rigid_omega2_estimate(mb%system, bases, arms, mass6))
      END DO
    END IF
    IF (mb%implicit) THEN
      ! bodySubstep accuracy (default): resolve the stiffest object-mooring mode to the phase accuracy
      ! of the staggered sub-steps (the monolithic step is stable without it)
      nsub = rigid_substep_count(omega2, dt, ACCURACY_OMEGA_DT)
      DO isub = 1, nsub
        CALL mb_step_implicit(mb, points, opts, time - dt + REAL(isub, wp)*dt/REAL(nsub, wp), dt/REAL(nsub, wp), &
                              conv_s, stall_s, it, ErrStat, ErrMsg, bathymetry)
        converged = converged .AND. conv_s
        stalled = stalled .OR. stall_s
        n_iter = n_iter + it
        IF (ErrStat /= CD_DECKDRV_OK .OR. .NOT. conv_s) RETURN
      END DO
      RETURN
    END IF
    nsub = rigid_substep_count(omega2, dt)
    DO isub = 1, nsub
      CALL mb_step_once(mb, points, opts, time - dt + REAL(isub, wp)*dt/REAL(nsub, wp), dt/REAL(nsub, wp), &
                        conv_s, stall_s, it, ErrStat, ErrMsg, bathymetry)
      converged = converged .AND. conv_s
      stalled = stalled .OR. stall_s
      n_iter = n_iter + it
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END DO
  END SUBROUTINE mb_step

  SUBROUTINE mb_step_once(mb, points, opts, time, dt, converged, stalled, n_iter, ErrStat, ErrMsg, bathymetry)
    !! One staggered step of the multibody march (see write_multibody_dynamic_out).
    TYPE(MultibodyMarch), INTENT(INOUT) :: mb
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time, dt
    LOGICAL, INTENT(OUT) :: converged, stalled
    INTEGER, INTENT(OUT) :: n_iter, ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    INTEGER :: ib, ir, c, es
    REAL(wp) :: x(3), v(3), a(3)
    CHARACTER(160) :: em

    converged = .TRUE.
    stalled = .FALSE.
    n_iter = 0
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    ! 0. the first step starts from the instantaneous accelerations of the initial state
    IF (.NOT. mb%started) THEN
      CALL mb_scatter(mb, points, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL mb_line_loads(mb, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      mb%old_rigid = mb%rigid
      mb%old_rods = mb%rods
      CALL mb_accelerations(mb, points, opts, time - dt, CD_ZERO, ErrStat, ErrMsg, bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      DO ib = 1, SIZE(mb%rigid)
        mb%rigid(ib)%a = mb%acc_b(:, ib)
        mb%rigid(ib)%alpha = mb%alpha_b(:, ib)
      END DO
      DO ir = 1, SIZE(mb%rods)
        IF (.NOT. (mb%rods(ir)%is_free .OR. mb%rods(ir)%is_pinned)) CYCLE
        mb%rods(ir)%a = mb%acc_r(:, ir)
        mb%rods(ir)%alpha = mb%alpha_r(:, ir)
      END DO
      mb%started = .TRUE.
    END IF
    mb%old_rigid = mb%rigid
    mb%old_rods = mb%rods
    ! 1. predictor
    DO ib = 1, SIZE(mb%rigid)
      CALL CD_Rigid_Advance_Newmark(mb%rigid(ib)%r, mb%rigid(ib)%v, mb%rigid(ib)%rot_mat, mb%rigid(ib)%omega, &
                                    mb%rigid(ib)%a, mb%rigid(ib)%alpha, mb%rigid(ib)%a, mb%rigid(ib)%alpha, dt, &
                                    CD_RIGID_NEWMARK_GAMMA, CD_RIGID_NEWMARK_BETA, es, em)
      IF (es /= CD_RIGID_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'body finite-rotation update failed: '//TRIM(em)); RETURN
      END IF
      mb%rigid(ib)%eta = CD_Log_SO3(MATMUL(mb%rigid(ib)%rot_mat, TRANSPOSE(mb%rigid(ib)%rot_ref)))
      CALL sync_attached_rods(mb%rigid(ib))
    END DO
    DO ir = 1, SIZE(mb%rods)
      IF (.NOT. (mb%rods(ir)%is_free .OR. mb%rods(ir)%is_pinned)) CYCLE
      CALL CD_Rigid_Advance_Newmark(mb%rods(ir)%r, mb%rods(ir)%v, mb%rods(ir)%rot_mat, mb%rods(ir)%omega, &
                                    mb%rods(ir)%a, mb%rods(ir)%alpha, mb%rods(ir)%a, mb%rods(ir)%alpha, dt, &
                                    CD_RIGID_NEWMARK_GAMMA, CD_RIGID_NEWMARK_BETA, es, em)
      IF (es /= CD_RIGID_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'rod finite-rotation update failed: '//TRIM(em)); RETURN
      END IF
      CALL mb_snap_pinned(mb%rods(ir), mb%rigid)
    END DO
    ! 2. line step to t + dt with the predicted attachment motion
    IF (mb%has_sys) THEN
      CALL mb_scatter(mb, points, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      IF (mb%has_dyn) THEN
        CALL CD_Step_System_DynamicPoints(mb%system, dt, converged, stalled, n_iter, es, em)
      ELSE
        CALL CD_Step_System(mb%system, dt, mb%q, mb%v, mb%a, converged, stalled, n_iter, es, em)
      END IF
      IF (es /= CD_SYSTEM_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'multibody line-system step failed: '//TRIM(em)); RETURN
      END IF
    END IF
    DO c = 1, SIZE(mb%cables)
      CALL mb_attachment_motion(mb, c, x, v, a, es, em)
      mb%cables(c)%dt = dt
      IF (es == CD_HFMF_OK) CALL CD_HFMF_UpdateStates(mb%cables(c), x, v, a, es, em)
      IF (es /= CD_HFMF_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'multibody finite-EI cable step failed: '//TRIM(em)); RETURN
      END IF
      ! the committed end loads (the probe and the object load channels read them)
      CALL mb_cable_committed_loads(mb, c, mb%cab_fend(:, c), mb%cab_mend(:, c), ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END DO
    ! 3. corrector from the end-of-step line loads at the predictor
    IF (mb%has_sys) THEN
      ! the lines' end motion after the step (the integrated Free/Connect points), objects at the predictor
      CALL mb_scatter(mb, points, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END IF
    CALL mb_line_loads(mb, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL mb_accelerations(mb, points, opts, time, dt, ErrStat, ErrMsg, bathymetry)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    DO ib = 1, SIZE(mb%rigid)
      mb%rigid(ib) = mb%old_rigid(ib)
      CALL CD_Rigid_Advance_Newmark(mb%rigid(ib)%r, mb%rigid(ib)%v, mb%rigid(ib)%rot_mat, mb%rigid(ib)%omega, &
                                    mb%old_rigid(ib)%a, mb%old_rigid(ib)%alpha, mb%acc_b(:, ib), mb%alpha_b(:, ib), &
                                    dt, CD_RIGID_NEWMARK_GAMMA, CD_RIGID_NEWMARK_BETA, es, em)
      IF (es /= CD_RIGID_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'body finite-rotation update failed: '//TRIM(em)); RETURN
      END IF
      mb%rigid(ib)%a = mb%acc_b(:, ib)
      mb%rigid(ib)%alpha = mb%alpha_b(:, ib)
      mb%rigid(ib)%eta = CD_Log_SO3(MATMUL(mb%rigid(ib)%rot_mat, TRANSPOSE(mb%rigid(ib)%rot_ref)))
      mb%rigid(ib)%accel_valid = .TRUE.
      CALL sync_attached_rods(mb%rigid(ib))
    END DO
    DO ir = 1, SIZE(mb%rods)
      IF (.NOT. (mb%rods(ir)%is_free .OR. mb%rods(ir)%is_pinned)) CYCLE
      mb%rods(ir) = mb%old_rods(ir)
      CALL CD_Rigid_Advance_Newmark(mb%rods(ir)%r, mb%rods(ir)%v, mb%rods(ir)%rot_mat, mb%rods(ir)%omega, &
                                    mb%old_rods(ir)%a, mb%old_rods(ir)%alpha, mb%acc_r(:, ir), mb%alpha_r(:, ir), &
                                    dt, CD_RIGID_NEWMARK_GAMMA, CD_RIGID_NEWMARK_BETA, es, em)
      IF (es /= CD_RIGID_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'rod finite-rotation update failed: '//TRIM(em)); RETURN
      END IF
      mb%rods(ir)%a = mb%acc_r(:, ir)
      mb%rods(ir)%alpha = mb%alpha_r(:, ir)
      mb%rods(ir)%accel_valid = .TRUE.
      CALL mb_snap_pinned(mb%rods(ir), mb%rigid)
    END DO
    ! the Body<N> and Rod<N>A/B points follow the corrected objects
    CALL mb_scatter(mb, points, ErrStat, ErrMsg)
  END SUBROUTINE mb_step_once

  SUBROUTINE mb_start_accelerations(mb, points, opts, time, dt, ErrStat, ErrMsg, bathymetry)
    !! The first step starts from the instantaneous accelerations of the initial state: the
    !! objects' from the current line loads with the end-node inertia implicit (mb_accelerations
    !! at dt = 0); Free/Connect points keep the lines' end acceleration.
    TYPE(MultibodyMarch), INTENT(INOUT) :: mb
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time, dt
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    INTEGER :: ib, ir
    CALL mb_scatter(mb, points, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL mb_line_loads(mb, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    mb%old_rigid = mb%rigid
    mb%old_rods = mb%rods
    CALL mb_accelerations(mb, points, opts, time - dt, CD_ZERO, ErrStat, ErrMsg, bathymetry)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    DO ib = 1, SIZE(mb%rigid)
      mb%rigid(ib)%a = mb%acc_b(:, ib)
      mb%rigid(ib)%alpha = mb%alpha_b(:, ib)
    END DO
    DO ir = 1, SIZE(mb%rods)
      IF (.NOT. (mb%rods(ir)%is_free .OR. mb%rods(ir)%is_pinned)) CYCLE
      mb%rods(ir)%a = mb%acc_r(:, ir)
      mb%rods(ir)%alpha = mb%alpha_r(:, ir)
    END DO
    ! the Body<N> and Rod<N>A/B line ends take the objects' initial accelerations
    CALL mb_scatter(mb, points, ErrStat, ErrMsg)
    mb%started = .TRUE.
  END SUBROUTINE mb_start_accelerations

  SUBROUTINE mb_junction_layout(mb, points)
    !! Junction coordinates of the monolithic scheme, one contiguous block per group: a free body
    !! (6: acceleration, angular acceleration) followed by the rods pinned to it (3 each: angular
    !! acceleration about the pin), a free rod (6), a rod pinned to a fixed point (3) and a
    !! Free/Connect point (3). jactive flags the EI=0 coupled DOFs these junctions move.
    TYPE(MultibodyMarch), INTENT(INOUT) :: mb
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    INTEGER :: ib, ir, p, np, nsc, ng, base, k, bases(2), ip
    REAL(wp) :: arms(3, 2)
    np = 0
    nsc = 0
    IF (mb%has_sys) THEN
      np = SIZE(mb%system%points)
      nsc = mb%system%n_system_coupled_dof
    END IF
    ng = SIZE(mb%rigid) + SIZE(mb%rods) + np
    ALLOCATE (mb%jb_off(SIZE(mb%rigid)), mb%jr_off(SIZE(mb%rods)), mb%jp_off(np), mb%g_kind(ng), mb%g_idx(ng), &
              mb%g_lo(ng), mb%g_hi(ng), mb%jactive(nsc), mb%floads(nsc), mb%fabs(nsc), mb%kline(nsc, nsc), &
              mb%q0(nsc), mb%v0(nsc), mb%a0(nsc), mb%jobj(nsc))
    mb%jb_off = -1
    mb%jr_off = -1
    mb%jp_off = -1
    mb%jactive = .FALSE.
    mb%jobj = .FALSE.
    mb%nj = 0
    mb%ng = 0
    DO ib = 1, SIZE(mb%rigid)
      CALL add_group(1, ib)
      mb%jb_off(ib) = mb%nj
      mb%nj = mb%nj + 6
      DO ir = 1, SIZE(mb%rods)
        IF (mb%rods(ir)%parent /= ib .OR. .NOT. mb%rods(ir)%is_pinned) CYCLE
        mb%jr_off(ir) = mb%nj
        mb%nj = mb%nj + 3
      END DO
      mb%g_hi(mb%ng) = mb%nj
    END DO
    DO ir = 1, SIZE(mb%rods)
      IF (mb%rods(ir)%parent > 0) CYCLE
      IF (mb%rods(ir)%is_free) THEN
        CALL add_group(2, ir)
        mb%jr_off(ir) = mb%nj
        mb%nj = mb%nj + 6
      ELSE IF (mb%rods(ir)%is_pinned) THEN
        CALL add_group(3, ir)
        mb%jr_off(ir) = mb%nj
        mb%nj = mb%nj + 3
      ELSE
        CYCLE
      END IF
      mb%g_hi(mb%ng) = mb%nj
    END DO
    DO p = 1, np
      IF (.NOT. mb%system%points(p)%active) CYCLE
      IF (mb%system%points(p)%point_type /= CD_POINT_FREE .AND. &
          mb%system%points(p)%point_type /= CD_POINT_CONNECT) CYCLE
      base = CD_System_Point_Base(mb%system, p)
      IF (base < 0) CYCLE
      CALL add_group(4, p)
      mb%jp_off(p) = mb%nj
      mb%nj = mb%nj + 3
      mb%g_hi(mb%ng) = mb%nj
      mb%jactive(base + 1:base + 3) = .TRUE.
    END DO
    IF (mb%has_sys) THEN
      DO ib = 1, SIZE(mb%rigid)
        DO ip = 1, SIZE(mb%rigid(ib)%point_indices)
          base = system_point_base(mb%system, points(mb%rigid(ib)%point_indices(ip))%id)
          IF (base >= 0) mb%jactive(base + 1:base + 3) = .TRUE.
          IF (base >= 0) mb%jobj(base + 1:base + 3) = .TRUE.
        END DO
      END DO
      DO ir = 1, SIZE(mb%rods)
        IF (mb%jr_off(ir) < 0) CYCLE
        CALL mb_rod_bases(mb, points, mb%rods(ir), bases, arms)
        DO k = 1, 2
          IF (bases(k) >= 0) mb%jactive(bases(k) + 1:bases(k) + 3) = .TRUE.
          IF (bases(k) >= 0) mb%jobj(bases(k) + 1:bases(k) + 3) = .TRUE.
        END DO
      END DO
    END IF
    ALLOCATE (mb%is_rot(mb%nj), mb%gam(nsc, mb%nj), mb%jbeta(mb%nj))
    mb%jact_idx = PACK([(k, k=1, nsc)], mb%jactive)
    mb%is_rot = .FALSE.
    DO ib = 1, SIZE(mb%rigid)
      mb%is_rot(mb%jb_off(ib) + 4:mb%jb_off(ib) + 6) = .TRUE.
    END DO
    DO ir = 1, SIZE(mb%rods)
      IF (mb%jr_off(ir) < 0) CYCLE
      IF (mb%rods(ir)%is_pinned) THEN
        mb%is_rot(mb%jr_off(ir) + 1:mb%jr_off(ir) + 3) = .TRUE.
      ELSE
        mb%is_rot(mb%jr_off(ir) + 4:mb%jr_off(ir) + 6) = .TRUE.
      END IF
    END DO
  CONTAINS
    SUBROUTINE add_group(kind, idx)
      INTEGER, INTENT(IN) :: kind, idx
      mb%ng = mb%ng + 1
      mb%g_kind(mb%ng) = kind
      mb%g_idx(mb%ng) = idx
      mb%g_lo(mb%ng) = mb%nj + 1
    END SUBROUTINE add_group
  END SUBROUTINE mb_junction_layout

  SUBROUTINE mb_imp_states(mb, x, dt, gam_na, beta_na, gam_p, beta_p, ErrStat, ErrMsg)
    !! The end-of-step states of every junction from the step-entry states (mb%old_*) and the
    !! trial end-of-step accelerations x: Newmark gam_na/beta_na for the bodies and rods (on R^3
    !! and on SO(3)), gam_p/beta_p for the Free/Connect points.
    TYPE(MultibodyMarch), INTENT(INOUT) :: mb
    REAL(wp), INTENT(IN) :: x(:), dt, gam_na, beta_na, gam_p, beta_p
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: ib, ir, p, o, es
    CHARACTER(160) :: em
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    DO ib = 1, SIZE(mb%rigid)
      o = mb%jb_off(ib)
      mb%rigid(ib) = mb%old_rigid(ib)
      CALL CD_Rigid_Advance_Newmark(mb%rigid(ib)%r, mb%rigid(ib)%v, mb%rigid(ib)%rot_mat, mb%rigid(ib)%omega, &
                                    mb%old_rigid(ib)%a, mb%old_rigid(ib)%alpha, x(o + 1:o + 3), x(o + 4:o + 6), dt, &
                                    gam_na, beta_na, es, em)
      IF (es /= CD_RIGID_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'body finite-rotation update failed: '//TRIM(em)); RETURN
      END IF
      mb%rigid(ib)%a = x(o + 1:o + 3)
      mb%rigid(ib)%alpha = x(o + 4:o + 6)
      mb%rigid(ib)%eta = CD_Log_SO3(MATMUL(mb%rigid(ib)%rot_mat, TRANSPOSE(mb%rigid(ib)%rot_ref)))
      CALL sync_attached_rods(mb%rigid(ib))
    END DO
    DO ir = 1, SIZE(mb%rods)
      o = mb%jr_off(ir)
      IF (o < 0) CYCLE
      mb%rods(ir) = mb%old_rods(ir)
      IF (mb%rods(ir)%is_pinned) THEN
        CALL CD_Rigid_Advance_Newmark(mb%rods(ir)%r, mb%rods(ir)%v, mb%rods(ir)%rot_mat, mb%rods(ir)%omega, &
                                      mb%old_rods(ir)%a, mb%old_rods(ir)%alpha, mb%old_rods(ir)%a, x(o + 1:o + 3), &
                                      dt, gam_na, beta_na, es, em)
        mb%rods(ir)%alpha = x(o + 1:o + 3)
      ELSE
        CALL CD_Rigid_Advance_Newmark(mb%rods(ir)%r, mb%rods(ir)%v, mb%rods(ir)%rot_mat, mb%rods(ir)%omega, &
                                      mb%old_rods(ir)%a, mb%old_rods(ir)%alpha, x(o + 1:o + 3), x(o + 4:o + 6), &
                                      dt, gam_na, beta_na, es, em)
        mb%rods(ir)%a = x(o + 1:o + 3)
        mb%rods(ir)%alpha = x(o + 4:o + 6)
      END IF
      IF (es /= CD_RIGID_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'rod finite-rotation update failed: '//TRIM(em)); RETURN
      END IF
      CALL mb_snap_pinned(mb%rods(ir), mb%rigid)
    END DO
    DO p = 1, SIZE(mb%jp_off)
      o = mb%jp_off(p)
      IF (o < 0) CYCLE
      ASSOCIATE (pt => mb%system%points(p), p0 => mb%old_points(p))
        pt%q = p0%q + dt*p0%v + dt*dt*((0.5_wp - beta_p)*p0%a + beta_p*x(o + 1:o + 3))
        pt%v = p0%v + dt*((CD_ONE - gam_p)*p0%a + gam_p*x(o + 1:o + 3))
        pt%a = x(o + 1:o + 3)
      END ASSOCIATE
    END DO
  END SUBROUTINE mb_imp_states

  SUBROUTINE mb_imp_scatter(mb, points, ErrStat, ErrMsg)
    !! The end-of-step motion of every coupled line end: the step-entry motion of the held ends
    !! with the object attachments and the Free/Connect points overwritten.
    TYPE(MultibodyMarch), INTENT(INOUT) :: mb
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: ir, k, base, p, es, bases(2)
    REAL(wp) :: arms(3, 2)
    CHARACTER(160) :: em
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (.NOT. mb%has_sys) RETURN
    mb%q = mb%q0
    mb%v = mb%v0
    mb%a = mb%a0
    CALL scatter_rigid6_point_motion(mb%system, points, mb%rigid, mb%q, mb%v, mb%a)
    DO ir = 1, SIZE(mb%rods)
      CALL mb_rod_bases(mb, points, mb%rods(ir), bases, arms)
      DO k = 1, 2
        base = bases(k)
        IF (base < 0) CYCLE
        mb%q(base + 1:base + 3) = mb%rods(ir)%r + arms(:, k)
        mb%v(base + 1:base + 3) = mb%rods(ir)%v + cross3(mb%rods(ir)%omega, arms(:, k))
        mb%a(base + 1:base + 3) = mb%rods(ir)%a + cross3(mb%rods(ir)%alpha, arms(:, k)) + &
                                  cross3(mb%rods(ir)%omega, cross3(mb%rods(ir)%omega, arms(:, k)))
      END DO
    END DO
    DO p = 1, SIZE(mb%jp_off)
      IF (mb%jp_off(p) < 0) CYCLE
      base = CD_System_Point_Base(mb%system, p)
      mb%q(base + 1:base + 3) = mb%system%points(p)%q
      mb%v(base + 1:base + 3) = mb%system%points(p)%v
      mb%a(base + 1:base + 3) = mb%system%points(p)%a
    END DO
    CALL CD_Update_System_Point_States(mb%system, mb%q, mb%v, mb%a, es, em)
    IF (es /= CD_SYSTEM_OK) CALL fail_solve(ErrStat, ErrMsg, 'multibody point-state update failed: '//TRIM(em))
  END SUBROUTINE mb_imp_scatter

  SUBROUTINE mb_imp_gamma(mb, points)
    !! gam = d q_{n+1} / (beta h^2 d x): the first-order map from the junction accelerations to
    !! the coupled line-end positions (translation and small rotation of each attachment).
    TYPE(MultibodyMarch), INTENT(INOUT) :: mb
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    INTEGER :: ib, ir, ip, k, o, ob, base, p, bases(2)
    REAL(wp) :: arm(3), arms(3, 2), l(3)
    IF (.NOT. mb%has_sys) RETURN
    mb%gam = CD_ZERO
    DO ib = 1, SIZE(mb%rigid)
      o = mb%jb_off(ib)
      DO ip = 1, SIZE(mb%rigid(ib)%point_indices)
        base = system_point_base(mb%system, points(mb%rigid(ib)%point_indices(ip))%id)
        IF (base < 0) CYCLE
        arm = MATMUL(mb%rigid(ib)%rot_mat, points(mb%rigid(ib)%point_indices(ip))%body_offset)
        DO k = 1, 3
          mb%gam(base + k, o + k) = CD_ONE
        END DO
        mb%gam(base + 1:base + 3, o + 4:o + 6) = -skew3(arm)
      END DO
    END DO
    DO ir = 1, SIZE(mb%rods)
      o = mb%jr_off(ir)
      IF (o < 0) CYCLE
      CALL mb_rod_bases(mb, points, mb%rods(ir), bases, arms)
      DO k = 1, 2
        base = bases(k)
        IF (base < 0) CYCLE
        IF (mb%rods(ir)%is_pinned) THEN
          l = mb%rods(ir)%r + arms(:, k) - mb%rods(ir)%pin
          mb%gam(base + 1:base + 3, o + 1:o + 3) = -skew3(l)
          IF (mb%rods(ir)%parent > 0) THEN
            ob = mb%jb_off(mb%rods(ir)%parent)
            DO ip = 1, 3
              mb%gam(base + ip, ob + ip) = CD_ONE
            END DO
            mb%gam(base + 1:base + 3, ob + 4:ob + 6) = -skew3(mb%rods(ir)%pin - mb%rigid(mb%rods(ir)%parent)%r)
          END IF
        ELSE
          DO ip = 1, 3
            mb%gam(base + ip, o + ip) = CD_ONE
          END DO
          mb%gam(base + 1:base + 3, o + 4:o + 6) = -skew3(arms(:, k))
        END IF
      END DO
    END DO
    DO p = 1, SIZE(mb%jp_off)
      o = mb%jp_off(p)
      IF (o < 0) CYCLE
      base = CD_System_Point_Base(mb%system, p)
      DO k = 1, 3
        mb%gam(base + k, o + k) = CD_ONE
      END DO
    END DO
  END SUBROUTINE mb_imp_gamma

  SUBROUTINE mb_imp_alpha(mb, af, am, am_p)
    !! The generalised-alpha evaluation states: positions, orientations (geodesic) and velocities
    !! at t_{n+1-alpha_f}, accelerations at the alpha_m level (am for the bodies and rods, am_p
    !! for the Free/Connect points), between mb%old_* and the current end-of-step states.
    TYPE(MultibodyMarch), INTENT(INOUT) :: mb
    REAL(wp), INTENT(IN) :: af, am, am_p
    INTEGER :: ib, ir, p
    mb%rig_af = mb%rigid
    DO ib = 1, SIZE(mb%rigid)
      CALL blend6(mb%old_rigid(ib)%r, mb%old_rigid(ib)%rot_mat, mb%old_rigid(ib)%v, mb%old_rigid(ib)%omega, &
                  mb%old_rigid(ib)%a, mb%old_rigid(ib)%alpha, mb%rig_af(ib)%r, mb%rig_af(ib)%rot_mat, &
                  mb%rig_af(ib)%v, mb%rig_af(ib)%omega, mb%rig_af(ib)%a, mb%rig_af(ib)%alpha)
      mb%rig_af(ib)%eta = CD_Log_SO3(MATMUL(mb%rig_af(ib)%rot_mat, TRANSPOSE(mb%rig_af(ib)%rot_ref)))
      CALL sync_attached_rods(mb%rig_af(ib))
    END DO
    mb%rod_af = mb%rods
    DO ir = 1, SIZE(mb%rods)
      IF (mb%jr_off(ir) < 0) CYCLE
      CALL blend6(mb%old_rods(ir)%r, mb%old_rods(ir)%rot_mat, mb%old_rods(ir)%v, mb%old_rods(ir)%omega, &
                  mb%old_rods(ir)%a, mb%old_rods(ir)%alpha, mb%rod_af(ir)%r, mb%rod_af(ir)%rot_mat, &
                  mb%rod_af(ir)%v, mb%rod_af(ir)%omega, mb%rod_af(ir)%a, mb%rod_af(ir)%alpha)
      CALL mb_snap_pinned(mb%rod_af(ir), mb%rig_af)
    END DO
    DO p = 1, SIZE(mb%jp_off)
      IF (mb%jp_off(p) < 0) CYCLE
      mb%pt_af(p) = mb%system%points(p)
      mb%pt_af(p)%q = (CD_ONE - af)*mb%system%points(p)%q + af*mb%old_points(p)%q
      mb%pt_af(p)%v = (CD_ONE - af)*mb%system%points(p)%v + af*mb%old_points(p)%v
      mb%pt_af(p)%a = (CD_ONE - am_p)*mb%system%points(p)%a + am_p*mb%old_points(p)%a
    END DO
  CONTAINS
    SUBROUTINE blend6(r0, rot0, v0, w0, a0, al0, r, rot, v, w, a, al)
      REAL(wp), INTENT(IN) :: r0(3), rot0(3, 3), v0(3), w0(3), a0(3), al0(3)
      REAL(wp), INTENT(INOUT) :: r(3), rot(3, 3), v(3), w(3), a(3), al(3)
      REAL(wp) :: th(3), rn(3, 3)
      th = CD_Log_SO3(MATMUL(rot, TRANSPOSE(rot0)))
      rn = MATMUL(CD_Exp_SO3((CD_ONE - af)*th), rot0)
      rot = rn
      r = (CD_ONE - af)*r + af*r0
      v = (CD_ONE - af)*v + af*v0
      w = (CD_ONE - af)*w + af*w0
      a = (CD_ONE - am)*a + am*a0
      al = (CD_ONE - am)*al + am*al0
    END SUBROUTINE blend6
  END SUBROUTINE mb_imp_alpha

  SUBROUTINE mb_imp_group_residual(mb, points, opts, g, time, res, ErrStat, ErrMsg, bathymetry)
    !! Rows g_lo:g_hi of the junction residual of group g at the alpha-level states (mb%rig_af,
    !! mb%rod_af, mb%pt_af): M(q_af) a_am - F(t_af, q_af, v_af) - (line and cable loads), with the
    !! line loads in mb%loads (alpha-level end reactions) and the cable end forces in mb%cab_force.
    !! A pinned rod's rows are its virtual work about the pin (mb_group_system).
    TYPE(MultibodyMarch), INTENT(INOUT) :: mb
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    INTEGER, INTENT(IN) :: g
    REAL(wp), INTENT(IN) :: time
    REAL(wp), INTENT(INOUT) :: res(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    INTEGER :: lo, hi, idx, nc, k, ir, base, n
    INTEGER, ALLOCATABLE :: kids(:)
    REAL(wp) :: fx(3), mx(3), m6b(6, 6), rhsb(6), x6(6), fenv(3), meff, arm(3), z6(6)
    REAL(wp), ALLOCATABLE :: m6c(:, :, :), rhsc(:, :), pinw(:, :), rc(:, :), wc(:, :), amat(:, :), bvec(:), xg(:)

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    z6 = CD_ZERO
    lo = mb%g_lo(g)
    hi = mb%g_hi(g)
    idx = mb%g_idx(g)
    SELECT CASE (mb%g_kind(g))
    CASE (1)
      CALL cable_load(1, idx, fx, mx)
      CALL mb_body_terms(mb, points, opts, idx, time, CD_ZERO, z6, fx, mx, m6b, rhsb, ErrStat, &
                         ErrMsg, bathymetry, state=mb%rig_af(idx), explicit_lines=.TRUE.)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      x6(1:3) = mb%rig_af(idx)%a
      x6(4:6) = mb%rig_af(idx)%alpha
      kids = PACK([(ir, ir=1, SIZE(mb%rods))], [(mb%rods(ir)%parent == idx .AND. mb%rods(ir)%is_pinned, &
                                                 ir=1, SIZE(mb%rods))])
      nc = SIZE(kids)
      IF (nc == 0) THEN
        res(lo:lo + 5) = MATMUL(m6b, x6) - rhsb
        RETURN
      END IF
      n = 6 + 3*nc
      ALLOCATE (m6c(6, 6, nc), rhsc(6, nc), pinw(3, nc), rc(3, nc), wc(3, nc), amat(n, n), bvec(n), xg(n))
      xg(1:6) = x6
      DO k = 1, nc
        ir = kids(k)
        CALL cable_load(2, ir, fx, mx)
        CALL mb_rod_terms(mb, points, opts, ir, time, CD_ZERO, z6, fx, mx, m6c(:, :, k), &
                          rhsc(:, k), ErrStat, ErrMsg, bathymetry, state=mb%rod_af(ir), explicit_lines=.TRUE.)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        pinw(:, k) = mb%rod_af(ir)%pin
        rc(:, k) = mb%rod_af(ir)%r
        wc(:, k) = mb%rod_af(ir)%omega
        xg(6 + 3*k - 2:6 + 3*k) = mb%rod_af(ir)%alpha
      END DO
      CALL mb_group_system(m6b, rhsb, mb%rig_af(idx)%r, mb%rig_af(idx)%omega, .TRUE., nc, m6c, rhsc, pinw, rc, &
                           wc, amat, bvec)
      res(lo:hi) = MATMUL(amat, xg) - bvec
    CASE (2)
      CALL cable_load(2, idx, fx, mx)
      CALL mb_rod_terms(mb, points, opts, idx, time, CD_ZERO, z6, fx, mx, m6b, rhsb, ErrStat, &
                        ErrMsg, bathymetry, state=mb%rod_af(idx), explicit_lines=.TRUE.)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      x6(1:3) = mb%rod_af(idx)%a
      x6(4:6) = mb%rod_af(idx)%alpha
      res(lo:lo + 5) = MATMUL(m6b, x6) - rhsb
    CASE (3)
      CALL cable_load(2, idx, fx, mx)
      CALL mb_rod_terms(mb, points, opts, idx, time, CD_ZERO, z6, fx, mx, m6b, rhsb, ErrStat, &
                        ErrMsg, bathymetry, state=mb%rod_af(idx), explicit_lines=.TRUE.)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      ALLOCATE (m6c(6, 6, 1), rhsc(6, 1), pinw(3, 1), rc(3, 1), wc(3, 1), amat(3, 3), bvec(3))
      m6c(:, :, 1) = m6b
      rhsc(:, 1) = rhsb
      pinw(:, 1) = mb%rod_af(idx)%pin
      rc(:, 1) = mb%rod_af(idx)%r
      wc(:, 1) = mb%rod_af(idx)%omega
      CALL mb_group_system(m6b, rhsb, [CD_ZERO, CD_ZERO, CD_ZERO], [CD_ZERO, CD_ZERO, CD_ZERO], .FALSE., 1, m6c, &
                           rhsc, pinw, rc, wc, amat, bvec)
      res(lo:hi) = MATMUL(amat, mb%rod_af(idx)%alpha) - bvec
    CASE (4)
      base = CD_System_Point_Base(mb%system, idx)
      CALL CD_System_Point_Environment(mb%pt_af(idx), mb%pt_af(idx)%v, fenv, meff, ErrStat, ErrMsg)
      IF (ErrStat /= CD_SYSTEM_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'Free/Connect point load failed: '//TRIM(ErrMsg)); RETURN
      END IF
      ErrStat = CD_DECKDRV_OK
      res(lo:hi) = meff*mb%pt_af(idx)%a - (mb%pt_af(idx)%force + fenv + mb%loads(base + 1:base + 3))
    END SELECT
  CONTAINS
    SUBROUTINE cable_load(kind, obj, f, m)
      !! The finite-EI cable end forces on object obj (kind 1 body, 2 rod) and their moment
      !! about its reference point, at the alpha-level pose.
      INTEGER, INTENT(IN) :: kind, obj
      REAL(wp), INTENT(OUT) :: f(3), m(3)
      INTEGER :: cc
      f = CD_ZERO
      m = CD_ZERO
      IF (.NOT. ALLOCATED(mb%cables)) RETURN
      DO cc = 1, SIZE(mb%cables)
        IF (mb%cab_kind(cc) /= kind .OR. mb%cab_obj(cc) /= obj) CYCLE
        IF (kind == 1) THEN
          arm = MATMUL(mb%rig_af(obj)%rot_mat, mb%cab_off(:, cc))
        ELSE
          arm = mb%cab_off(1, cc)*mb%rod_af(obj)%half_length*mb%rod_af(obj)%rot_mat(:, 1)
        END IF
        f = f + mb%cab_force(:, cc)
        ! a clamped or elastic End A also returns its connection moment to the object
        m = m + cross3(arm, mb%cab_force(:, cc)) + mb%cab_moment(:, cc)
      END DO
    END SUBROUTINE cable_load
  END SUBROUTINE mb_imp_group_residual

  SUBROUTINE mb_imp_row_scales(mb, points, opts, bh2, rscale)
    !! The force (translation rows) and moment (rotation rows) scale of every junction row, from
    !! its own object: the larger of its weight, its buoyancy, the line reactions at its
    !! attachments (their magnitudes summed, so a junction whose line loads cancel keeps their
    !! scale) and the cable end forces on it (at least 1 N), times its size (at least 1 m) for
    !! moments. A body holding a line restrained in torsion has its moment rows scaled by its
    !! rotational step stiffness instead when that is smaller, I_min/(beta h^2) + sum 1/C (bh2 =
    !! beta h^2) times TORS_ROT_REF, so that the junction tolerance bounds the rotation error
    !! (JUNCTION_TOL TORS_ROT_REF rad): the weight of a heavy body with a small rotational
    !! inertia would otherwise accept a moment residual far above the line torque.
    TYPE(MultibodyMarch), INTENT(IN) :: mb
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: bh2
    REAL(wp), INTENT(OUT) :: rscale(:)
    REAL(wp), PARAMETER :: TORS_ROT_REF = 1.0e-2_wp
    INTEGER :: ib, ir, p, ip, k, o, base, bases(2)
    REAL(wp) :: f, l, arms(3, 2), kt
    rscale = CD_ONE
    DO ib = 1, SIZE(mb%rigid)
      o = mb%jb_off(ib)
      f = MAX(CD_ONE, mb%rigid(ib)%mass*opts%g, opts%rhoW*mb%rigid(ib)%vol*opts%g)
      l = CD_ONE
      DO ip = 1, SIZE(mb%rigid(ib)%point_indices)
        l = MAX(l, NORM2(points(mb%rigid(ib)%point_indices(ip))%body_offset))
        IF (.NOT. mb%has_sys) CYCLE
        base = system_point_base(mb%system, points(mb%rigid(ib)%point_indices(ip))%id)
        IF (base >= 0) f = MAX(f, NORM2(mb%fabs(base + 1:base + 3)))
      END DO
      f = MAX(f, cable_force(1, ib))
      rscale(o + 1:o + 3) = f
      rscale(o + 4:o + 6) = f*l
      kt = torsion_stiffness(ib)
      IF (kt > CD_ZERO) rscale(o + 4:o + 6) = MIN(f*l, MAX(CD_ONE, &
                                                         (MINVAL(mb%rigid(ib)%inertia)/bh2 + kt)*TORS_ROT_REF))
    END DO
    DO ir = 1, SIZE(mb%rods)
      o = mb%jr_off(ir)
      IF (o < 0) CYCLE
      f = MAX(CD_ONE, mb%rods(ir)%mass*opts%g, opts%rhoW*mb%rods(ir)%volume*opts%g)
      IF (mb%has_sys) THEN
        CALL mb_rod_bases(mb, points, mb%rods(ir), bases, arms)
        DO k = 1, 2
          IF (bases(k) >= 0) f = MAX(f, NORM2(mb%fabs(bases(k) + 1:bases(k) + 3)))
        END DO
      END IF
      f = MAX(f, cable_force(2, ir))
      l = MAX(CD_ONE, mb%rods(ir)%length)
      IF (mb%rods(ir)%is_pinned) THEN
        rscale(o + 1:o + 3) = f*l
      ELSE
        rscale(o + 1:o + 3) = f
        rscale(o + 4:o + 6) = f*l
      END IF
    END DO
    DO p = 1, SIZE(mb%jp_off)
      o = mb%jp_off(p)
      IF (o < 0) CYCLE
      base = CD_System_Point_Base(mb%system, p)
      f = MAX(CD_ONE, mb%system%points(p)%mass*opts%g, NORM2(mb%system%points(p)%force), &
              NORM2(mb%fabs(base + 1:base + 3)))
      rscale(o + 1:o + 3) = f
    END DO

  CONTAINS
    REAL(wp) FUNCTION cable_force(kind, obj) RESULT(fc)
      INTEGER, INTENT(IN) :: kind, obj
      INTEGER :: cc
      fc = CD_ZERO
      IF (.NOT. ALLOCATED(mb%cables)) RETURN
      DO cc = 1, SIZE(mb%cables)
        IF (mb%cab_kind(cc) == kind .AND. mb%cab_obj(cc) == obj) fc = MAX(fc, NORM2(mb%cab_force(:, cc)))
      END DO
    END FUNCTION cable_force

    REAL(wp) FUNCTION torsion_stiffness(obj) RESULT(ks)
      !! Summed torsional stiffness 1/C of the active torsional cables on body obj (0: none).
      INTEGER, INTENT(IN) :: obj
      INTEGER :: cc
      REAL(wp) :: cmp
      ks = CD_ZERO
      IF (.NOT. ALLOCATED(mb%cables)) RETURN
      DO cc = 1, SIZE(mb%cables)
        IF (mb%cab_kind(cc) /= 1 .OR. mb%cab_obj(cc) /= obj) CYCLE
        IF (.NOT. mb%cables(cc)%line%torsion%active) CYCLE
        cmp = CD_HermiteTorsion_Compliance(mb%cables(cc)%line%torsion, mb%cables(cc)%line%l0)
        IF (cmp > CD_ZERO) ks = ks + CD_ONE/cmp
      END DO
    END FUNCTION torsion_stiffness
  END SUBROUTINE mb_imp_row_scales

  RECURSIVE SUBROUTINE mb_step_implicit(mb, points, opts, time, dt, converged, stalled, n_iter, ErrStat, ErrMsg, &
                                        bathymetry, depth)
    !! One monolithic implicit generalised-alpha step of the multibody march (bodyScheme
    !! monolithic): a multilevel Newton on the junction accelerations x (free bodies, free and
    !! pinned rods, Free/Connect points). Each outer iteration moves every junction to its
    !! Newmark end-of-step state, steps the EI=0 lines with that end motion from the step-entry
    !! state (warm-started from the previous iteration), which return their alpha-level end
    !! reactions and condensed end tangents (CD_Step_System_Junction), steps the finite-EI
    !! cables, and evaluates the junction residual at the alpha level; the Jacobian is the
    !! objects' own (6-column finite differences per group, which carries the mass, the
    !! gyroscopic and hydrodynamic terms and the rotating lever) plus beta h^2 Gam^T K Gam from
    !! the lines. A step that does not converge in MAX_OUTER iterations restarts as two half
    !! steps, to depth MAX_DEPTH, then fails naming the group with the largest residual.
    TYPE(MultibodyMarch), INTENT(INOUT) :: mb
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time, dt
    LOGICAL, INTENT(OUT) :: converged, stalled
    INTEGER, INTENT(OUT) :: n_iter, ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    INTEGER, INTENT(IN), OPTIONAL :: depth
    INTEGER, PARAMETER :: MAX_OUTER = 12, MAX_DEPTH = 6
    REAL(wp), PARAMETER :: ROT_CAP = 0.25_wp
    ! outer convergence: force rows within JUNCTION_TOL of the step's force scale (moment rows
    ! times the object length scale); the line reactions carry the inner tolerance
    REAL(wp), PARAMETER :: JUNCTION_TOL = 1.0e-6_wp, PREDICTOR_TOL = 1.0e-9_wp
    CHARACTER(24) :: tstr
    INTEGER :: dep, it, g, c, ib, ir, p, o, es, lit, nj, gworst, it2
    LOGICAL :: lconv, lstall, first, ok, conv2, stall2, refresh, lines_stepped, tors_turn, lim
    INTEGER, PARAMETER :: TAN_MAX_AGE = 20
    REAL(wp) :: rho, am, af, beta_na, gam_na, t_af, h, fac, dth, worst, tol_it, am_p, gam_p, beta_p
    REAL(wp), ALLOCATABLE :: x(:), xp(:), r(:), rp(:), jac(:, :), dx(:), kg(:, :), ga(:, :), rscale(:)
    CHARACTER(160) :: em

    converged = .FALSE.
    stalled = .FALSE.
    n_iter = 0
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    dep = 0
    IF (PRESENT(depth)) dep = depth
    ! Every junction takes its loads, the line reactions among them, at the lines' force level
    ! t_{n+1-af}. The bodies and rods carry their inertia at the same level (am = af, hence
    ! gamma = 1/2, beta = 1/4): their principal roots are those of the trapezoidal rule, second
    ! order without numerical dissipation (a linear undamped body conserves its energy), where
    ! the lines' alpha_m would add a period error of order (1 - rhoInf) (omega dt)^2; the
    ! accuracy sub-steps resolve their modes. The Free/Connect points, whose inertia is mostly
    ! that of the line ends and whose stiff modes nothing sub-steps, keep the lines' own
    ! generalised-alpha parameters and dissipation (am_p, gam_p, beta_p).
    rho = opts%rho_inf
    af = rho/(rho + CD_ONE)
    am = af
    gam_na = 0.5_wp
    beta_na = 0.25_wp
    am_p = (2.0_wp*rho - CD_ONE)/(rho + CD_ONE)
    gam_p = 0.5_wp - am_p + af
    beta_p = 0.25_wp*(CD_ONE - am_p + af)**2
    mb%jbeta = beta_na
    DO p = 1, SIZE(mb%jp_off)
      IF (mb%jp_off(p) >= 0) mb%jbeta(mb%jp_off(p) + 1:mb%jp_off(p) + 3) = beta_p
    END DO
    t_af = time - af*dt
    nj = mb%nj
    ALLOCATE (x(nj), xp(nj), r(nj), rp(nj), jac(nj, nj), dx(nj), rscale(nj))
    ! step-entry states
    mb%old_rigid = mb%rigid
    mb%old_rods = mb%rods
    IF (mb%has_sys) THEN
      mb%old_points = mb%system%points
      CALL CD_Get_System_CoupledMotion(mb%system, mb%q0, mb%v0, mb%a0, es, em)
      IF (es /= CD_SYSTEM_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'multibody coupled-motion query failed: '//TRIM(em)); RETURN
      END IF
    END IF
    DO c = 1, SIZE(mb%cables)
      CALL CD_HFMF_Snapshot(mb%cables(c), es, em)
      IF (es /= CD_HFMF_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'multibody cable snapshot failed: '//TRIM(em)); RETURN
      END IF
      ! the step-entry end loads of a clamped cable (its alpha-level blend)
      IF (mb%cab_clamp(c)) THEN
        CALL mb_cable_committed_loads(mb, c, mb%cab_f0(:, c), mb%cab_m0(:, c), ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      END IF
    END DO
    ! constant-acceleration predictor
    DO ib = 1, SIZE(mb%rigid)
      o = mb%jb_off(ib)
      x(o + 1:o + 3) = mb%old_rigid(ib)%a
      x(o + 4:o + 6) = mb%old_rigid(ib)%alpha
    END DO
    DO ir = 1, SIZE(mb%rods)
      o = mb%jr_off(ir)
      IF (o < 0) CYCLE
      IF (mb%rods(ir)%is_pinned) THEN
        x(o + 1:o + 3) = mb%old_rods(ir)%alpha
      ELSE
        x(o + 1:o + 3) = mb%old_rods(ir)%a
        x(o + 4:o + 6) = mb%old_rods(ir)%alpha
      END IF
    END DO
    DO p = 1, SIZE(mb%jp_off)
      o = mb%jp_off(p)
      IF (o >= 0) x(o + 1:o + 3) = mb%old_points(p)%a
    END DO
    first = .TRUE.
    lines_stepped = .FALSE.
    ok = .FALSE.
    tors_turn = .FALSE.
    gworst = 0
    DO it = 1, MAX_OUTER
      ! a body holding a line restrained in torsion turns by less than pi/2 per step: the line
      ! sees the body only through its orientation, which cannot tell a turn of psi from one of
      ! psi - 2 pi, so a larger trial turn could settle one turn off. The trial is held inside
      ! the limit; a step whose solution lies outside it does not converge and is halved.
      CALL mb_torsion_turn_limit(mb, x, dt, beta_na, lim)
      tors_turn = tors_turn .OR. lim
      CALL mb_imp_states(mb, x, dt, gam_na, beta_na, gam_p, beta_p, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) EXIT
      CALL mb_imp_scatter(mb, points, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) EXIT
      IF (mb%has_sys) THEN
        IF (.NOT. first) CALL CD_System_Junction_Rewind(mb%system)
        lines_stepped = .TRUE.
        ! the lines' condensed tangent is refreshed on the first solve of a step when it is
        ! TAN_MAX_AGE steps old or the previous step needed more than two outer iterations,
        ! and on every solve from the third outer iteration on; otherwise the last one is kept
        IF (it == 1) THEN
          refresh = mb%tan_age >= TAN_MAX_AGE .OR. mb%last_outer > 2
        ELSE
          refresh = it >= 3
        END IF
        IF (refresh) THEN
          mb%tan_age = 0
          mb%n_refresh = mb%n_refresh + 1
        END IF
        CALL CD_Step_System_Junction(mb%system, dt, mb%q, mb%v, mb%a, mb%jactive,.NOT. first, mb%floads, &
                                     mb%kline, lconv, lstall, lit, es, em, refresh=refresh, &
                                     load_abs=mb%fabs, levels=[beta_na, gam_na, am], level_dofs=mb%jobj)
        n_iter = n_iter + lit
        IF (es /= CD_SYSTEM_OK) THEN
          CALL fail_solve(ErrStat, ErrMsg, 'multibody line-system step failed: '//TRIM(em))
          EXIT
        END IF
        IF (.NOT. lconv) EXIT
        mb%loads = mb%floads
      END IF
      ! finite-EI cables with a pinned End A: stepped once, with the attachment motion of the
      ! Newmark predictor; their end force is held through the outer iterations (explicit
      ! coupling at the predictor). A cable clamped (or elastically connected) to its object is
      ! re-stepped from the step entry at every outer iteration with the iterate's motion and
      ! orientation, and loads the junction at the alpha level (implicit coupling)
      DO c = 1, SIZE(mb%cables)
        IF (.NOT. (first .OR. mb%cab_clamp(c))) CYCLE
        IF (.NOT. first) THEN
          CALL CD_HFMF_Restore(mb%cables(c), es, em)
          IF (es /= CD_HFMF_OK) THEN
            CALL fail_solve(ErrStat, ErrMsg, 'multibody cable restore failed: '//TRIM(em)); EXIT
          END IF
        END IF
        CALL mb_cable_drive(mb, c, dt, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) EXIT
        IF (mb%cab_clamp(c)) THEN
          mb%cab_force(:, c) = (CD_ONE - af)*mb%cab_fend(:, c) + af*mb%cab_f0(:, c)
          mb%cab_moment(:, c) = (CD_ONE - af)*mb%cab_mend(:, c) + af*mb%cab_m0(:, c)
        ELSE
          mb%cab_force(:, c) = mb%cab_fend(:, c)
        END IF
      END DO
      IF (ErrStat /= CD_DECKDRV_OK) EXIT
      first = .FALSE.
      CALL mb_imp_alpha(mb, af, am, am_p)
      DO g = 1, mb%ng
        CALL mb_imp_group_residual(mb, points, opts, g, t_af, r, ErrStat, ErrMsg, bathymetry)
        IF (ErrStat /= CD_DECKDRV_OK) EXIT
      END DO
      IF (ErrStat /= CD_DECKDRV_OK) EXIT
      IF (.NOT. ALL(IEEE_IS_FINITE(r))) EXIT
      IF (it == 1) CALL mb_imp_row_scales(mb, points, opts, beta_na*dt*dt, rscale)
      ! every row against its own object's force (moment) scale
      worst = CD_ZERO
      DO g = 1, mb%ng
        DO c = mb%g_lo(g), mb%g_hi(g)
          IF (ABS(r(c))/rscale(c) > worst) THEN
            worst = ABS(r(c))/rscale(c)
            gworst = g
          END IF
        END DO
      END DO
      ! the predictor itself is accepted only well inside the tolerance: a residual left just
      ! under it would act as a persistent force bias (a body at rest would drift)
      tol_it = JUNCTION_TOL
      IF (it == 1) tol_it = PREDICTOR_TOL
      IF (worst <= tol_it) THEN
        ok = .TRUE.
        mb%n_outer = mb%n_outer + it
        mb%max_outer = MAX(mb%max_outer, it)
        mb%last_outer = it
        IF (mb%tan_age < HUGE(1)) mb%tan_age = mb%tan_age + 1
        EXIT
      END IF
      IF (it == MAX_OUTER) EXIT
      ! Jacobian: the objects' own part by finite differences per group (lines held), the
      ! lines' condensed tangent through the attachment map
      IF (mb%has_sys) CALL mb_imp_gamma(mb, points)
      jac = CD_ZERO
      DO g = 1, mb%ng
        DO c = mb%g_lo(g), mb%g_hi(g)
          h = 1.0e-6_wp*MAX(CD_ONE, ABS(x(c)))
          xp = x
          xp(c) = x(c) + h
          CALL mb_imp_states(mb, xp, dt, gam_na, beta_na, gam_p, beta_p, ErrStat, ErrMsg)
          IF (ErrStat /= CD_DECKDRV_OK) EXIT
          CALL mb_imp_alpha(mb, af, am, am_p)
          CALL mb_imp_group_residual(mb, points, opts, g, t_af, rp, ErrStat, ErrMsg, bathymetry)
          IF (ErrStat /= CD_DECKDRV_OK) EXIT
          jac(mb%g_lo(g):mb%g_hi(g), c) = (rp(mb%g_lo(g):mb%g_hi(g)) - r(mb%g_lo(g):mb%g_hi(g)))/h
        END DO
        IF (ErrStat /= CD_DECKDRV_OK) EXIT
      END DO
      IF (ErrStat /= CD_DECKDRV_OK) EXIT
      IF (mb%has_sys) THEN
        ! only the junction-driven coupled DOFs carry rows of gam
        ! each column through its own Newmark beta (d q_{n+1} / d x = beta h^2)
        ga = mb%gam(mb%jact_idx, :)
        kg = MATMUL(mb%kline(mb%jact_idx, mb%jact_idx), ga*SPREAD(mb%jbeta, 1, SIZE(ga, 1)))
        jac = jac + dt*dt*MATMUL(TRANSPOSE(ga), kg)
      END IF
      ! clamped cables: their end force and moment follow the object motion within the step; the
      ! condensed dynamic end tangent (translations and rotations of the attachment) enters by
      ! finite differences of the cable step over the columns of the object's group, each
      ! perturbing the end-of-step pose by CABLE_FD rad or m
      DO c = 1, SIZE(mb%cables)
        IF (.NOT. mb%cab_clamp(c)) CYCLE
        g = mb_cable_group(mb, c)
        IF (g == 0) CYCLE
        CALL cable_columns(c, g)
        IF (ErrStat /= CD_DECKDRV_OK) EXIT
      END DO
      IF (ErrStat /= CD_DECKDRV_OK) EXIT
      dx = -r
      CALL CD_Solve_Dense_As_Banded(jac, dx, es, em)
      IF (es /= CD_LINALG_OK .OR. .NOT. ALL(IEEE_IS_FINITE(dx))) EXIT
      ! per-object rotation step cap
      fac = CD_ONE
      DO c = 1, nj
        IF (.NOT. mb%is_rot(c)) CYCLE
        dth = beta_na*dt*dt*ABS(dx(c))
        IF (dth > ROT_CAP) fac = MIN(fac, ROT_CAP/dth)
      END DO
      x = x + fac*dx
    END DO
    IF (ok) THEN
      DO ib = 1, SIZE(mb%rigid)
        mb%rigid(ib)%accel_valid = .TRUE.
      END DO
      DO ir = 1, SIZE(mb%rods)
        IF (mb%jr_off(ir) >= 0) mb%rods(ir)%accel_valid = .TRUE.
      END DO
      mb%n_steps_imp = mb%n_steps_imp + 1
      converged = .TRUE.
      RETURN
    END IF
    IF (ErrStat /= CD_DECKDRV_OK .AND. ErrStat /= CD_DECKDRV_SOLVEFAIL) RETURN
    ! failure: back to the step-entry state, then two half steps
    mb%rigid = mb%old_rigid
    mb%rods = mb%old_rods
    IF (mb%has_sys) THEN
      IF (lines_stepped) CALL CD_System_Junction_Rewind(mb%system)
      mb%system%points = mb%old_points
    END IF
    DO c = 1, SIZE(mb%cables)
      CALL CD_HFMF_Restore(mb%cables(c), es, em)
    END DO
    mb%tan_age = HUGE(1)
    IF (dep >= MAX_DEPTH) THEN
      IF (ErrStat == CD_DECKDRV_OK .AND. tors_turn) THEN
        WRITE (tstr, '(ES12.5)') time
        CALL fail_solve(ErrStat, ErrMsg, 'monolithic body/point step at t = '//TRIM(ADJUSTL(tstr))// &
                        ' s: a body holding a line restrained in torsion turns by more than 90 deg in one step '// &
                        'even after '//TRIM(int_to_str(MAX_DEPTH))//' step halvings; reduce dtM')
      ELSE IF (ErrStat == CD_DECKDRV_OK) THEN
        IF (gworst > 0) THEN
          SELECT CASE (mb%g_kind(gworst))
          CASE (1)
            em = 'BODY '//TRIM(int_to_str(mb%rigid(mb%g_idx(gworst))%body_id))
          CASE (2, 3)
            em = 'ROD '//TRIM(int_to_str(mb%rods(mb%g_idx(gworst))%rod_id))
          CASE DEFAULT
            em = 'POINT '//TRIM(int_to_str(mb%system%points(mb%g_idx(gworst))%id))
          END SELECT
        ELSE
          em = 'a line step'
        END IF
        WRITE (tstr, '(ES12.5)') time
        CALL fail_solve(ErrStat, ErrMsg, 'monolithic body/point step did not converge at t = '// &
                        TRIM(ADJUSTL(tstr))//' s after '//TRIM(int_to_str(MAX_DEPTH))// &
                        ' step halvings (largest residual: '//TRIM(em)//')')
      END IF
      RETURN
    END IF
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    mb%n_subdiv = mb%n_subdiv + 1
    CALL mb_step_implicit(mb, points, opts, time - 0.5_wp*dt, 0.5_wp*dt, converged, stalled, it2, ErrStat, ErrMsg, &
                          bathymetry, dep + 1)
    n_iter = n_iter + it2
    IF (ErrStat /= CD_DECKDRV_OK .OR. .NOT. converged) RETURN
    CALL mb_step_implicit(mb, points, opts, time, 0.5_wp*dt, conv2, stall2, it2, ErrStat, ErrMsg, bathymetry, &
                          dep + 1)
    n_iter = n_iter + it2
    converged = conv2
    stalled = stall2
  CONTAINS
    SUBROUTINE cable_columns(cc, gg)
      !! Add clamped cable cc's end-load derivative to the Jacobian columns of its group gg:
      !! the cable re-stepped from the step entry with each column perturbed, the group residual
      !! re-evaluated at the unperturbed objects with the perturbed cable loads.
      INTEGER, INTENT(IN) :: cc, gg
      REAL(wp), PARAMETER :: CABLE_FD = 1.0e-5_wp
      INTEGER :: col, lo, hi
      REAL(wp) :: fsave(3), msave(3), hc
      lo = mb%g_lo(gg)
      hi = mb%g_hi(gg)
      fsave = mb%cab_force(:, cc)
      msave = mb%cab_moment(:, cc)
      hc = CABLE_FD/(beta_na*dt*dt)
      DO col = lo, hi
        xp = x
        xp(col) = x(col) + hc
        CALL mb_imp_states(mb, xp, dt, gam_na, beta_na, gam_p, beta_p, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        CALL CD_HFMF_Restore(mb%cables(cc), es, em)
        IF (es /= CD_HFMF_OK) THEN
          CALL fail_solve(ErrStat, ErrMsg, 'multibody cable restore failed: '//TRIM(em)); RETURN
        END IF
        CALL mb_cable_drive(mb, cc, dt, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        CALL mb_imp_states(mb, x, dt, gam_na, beta_na, gam_p, beta_p, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        CALL mb_imp_alpha(mb, af, am, am_p)
        mb%cab_force(:, cc) = (CD_ONE - af)*mb%cab_fend(:, cc) + af*mb%cab_f0(:, cc)
        mb%cab_moment(:, cc) = (CD_ONE - af)*mb%cab_mend(:, cc) + af*mb%cab_m0(:, cc)
        CALL mb_imp_group_residual(mb, points, opts, gg, t_af, rp, ErrStat, ErrMsg, bathymetry)
        mb%cab_force(:, cc) = fsave
        mb%cab_moment(:, cc) = msave
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        jac(lo:hi, col) = jac(lo:hi, col) + (rp(lo:hi) - r(lo:hi))/hc
      END DO
    END SUBROUTINE cable_columns
  END SUBROUTINE mb_step_implicit

  SUBROUTINE mb_torsion_turn_limit(mb, x, dt, beta_na, limited)
    !! Keep every body that holds a cable restrained in torsion within a turn of TURN_FRAC
    !! CD_HTORS_MAX_STEP over the step to the trial accelerations x: when the Newmark rotation
    !! increment dt omega_n + dt^2 ((1/2 - beta) alpha_n + beta alpha_{n+1}) of
    !! CD_Rigid_Advance_Newmark is larger, alpha_{n+1} is moved so that the increment keeps its
    !! direction at that length (limited = .TRUE.). The cable sees the body only through its
    !! orientation, which cannot tell a turn of psi from one of psi - 2 pi.
    TYPE(MultibodyMarch), INTENT(IN) :: mb
    REAL(wp), INTENT(INOUT) :: x(:)
    REAL(wp), INTENT(IN) :: dt, beta_na
    LOGICAL, INTENT(OUT) :: limited
    REAL(wp), PARAMETER :: TURN_FRAC = 0.9_wp
    INTEGER :: c, ib, o
    REAL(wp) :: base(3), dpsi(3), s
    limited = .FALSE.
    IF (.NOT. ALLOCATED(mb%cables)) RETURN
    DO c = 1, SIZE(mb%cables)
      IF (mb%cab_kind(c) /= 1 .OR. .NOT. mb%cables(c)%line%torsion%active) CYCLE
      ib = mb%cab_obj(c)
      o = mb%jb_off(ib)
      IF (o < 0) CYCLE
      base = dt*mb%old_rigid(ib)%omega + dt*dt*(0.5_wp - beta_na)*mb%old_rigid(ib)%alpha
      dpsi = base + dt*dt*beta_na*x(o + 4:o + 6)
      IF (NORM2(dpsi) <= TURN_FRAC*CD_HTORS_MAX_STEP) CYCLE
      ! non-finite trials are left to the residual's finite check
      IF (.NOT. ALL(IEEE_IS_FINITE(dpsi))) CYCLE
      s = TURN_FRAC*CD_HTORS_MAX_STEP/NORM2(dpsi)
      x(o + 4:o + 6) = (s*dpsi - base)/(dt*dt*beta_na)
      limited = .TRUE.
    END DO
  END SUBROUTINE mb_torsion_turn_limit

  INTEGER FUNCTION mb_cable_group(mb, c) RESULT(g)
    !! The junction group that carries cable c's End A object (0: a held attachment or an object
    !! without junction coordinates). A rod pinned to a body belongs to the body's group.
    TYPE(MultibodyMarch), INTENT(IN) :: mb
    INTEGER, INTENT(IN) :: c
    INTEGER :: gg, kind, obj
    g = 0
    kind = 0
    obj = mb%cab_obj(c)
    SELECT CASE (mb%cab_kind(c))
    CASE (1)
      kind = 1
    CASE (2)
      IF (mb%rods(obj)%parent > 0) THEN
        kind = 1
        obj = mb%rods(obj)%parent
      ELSE
        kind = 2
      END IF
    CASE DEFAULT
      RETURN
    END SELECT
    DO gg = 1, mb%ng
      IF (kind == 1 .AND. mb%g_kind(gg) == 1 .AND. mb%g_idx(gg) == obj) g = gg
      IF (kind == 2 .AND. (mb%g_kind(gg) == 2 .OR. mb%g_kind(gg) == 3) .AND. mb%g_idx(gg) == obj) g = gg
    END DO
  END FUNCTION mb_cable_group

  SUBROUTINE mb_point_force(mb, ch, val, ErrStat, ErrMsg)
    !! Point<P>F{x,y,z,H} on the multibody march: the resultant of the forces the attached EI=0
    !! lines and finite-EI cables exert on point P.
    TYPE(MultibodyMarch), INTENT(IN) :: mb
    CHARACTER(*), INTENT(IN) :: ch
    REAL(wp), INTENT(OUT) :: val
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    CALL CD_Eval_Aggregate_Channel(ch, mb%has_sys, mb%system, mb%cables, mb%line_is_cable, mb%line_obj_index, val, &
                                   ErrStat, ErrMsg, cable_points=mb%cable_points)
  END SUBROUTINE mb_point_force

  SUBROUTINE mb_object_channel(mb, points, opts, time, ch, val, found, ErrStat, ErrMsg, bathymetry)
    !! Body<N>/Rod<N> channel of the multibody march.
    TYPE(MultibodyMarch), INTENT(IN) :: mb
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time
    CHARACTER(*), INTENT(IN) :: ch
    REAL(wp), INTENT(OUT) :: val
    LOGICAL, INTENT(OUT) :: found
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (mb%has_sys) THEN
      CALL object_channel_value(ch, val, found, mb%rigid, mb%rods, points, opts, time, mb%system, mb, ErrStat, &
                                ErrMsg, bathymetry)
    ELSE
      CALL object_channel_value(ch, val, found, mb%rigid, mb%rods, points, opts, time, mb=mb, ErrStat=ErrStat, &
                                ErrMsg=ErrMsg, bathymetry=bathymetry)
    END IF
  END SUBROUTINE mb_object_channel

  SUBROUTINE solve_rigid6x6(m6, rhs, ErrStat, ErrMsg)
    !! Solve the 6x6 rigid-body step system m6 x = rhs in place (rhs returns x) by Gaussian
    !! elimination with partial pivoting (the load derivatives need not be symmetric).
    REAL(wp), INTENT(INOUT) :: m6(6, 6), rhs(6)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: i, k, p
    REAL(wp) :: row(6), tmp, scale
    CHARACTER(24) :: s_piv, s_scale

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    scale = MAXVAL(ABS(m6))
    DO k = 1, 6
      p = k - 1 + MAXLOC(ABS(m6(k:6, k)), DIM=1)
      IF (.NOT. (ABS(m6(p, k)) > 1.0e-12_wp*scale)) THEN
        WRITE (s_piv, '(ES10.3)') m6(p, k)
        WRITE (s_scale, '(ES10.3)') scale
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: rigid-body 6x6 step matrix (body + added mass, attached line-end '// &
                 'inertia/damping/stiffness, linearized body loads) is singular: pivot '// &
                 TRIM(ADJUSTL(s_piv))//' vs matrix scale '//TRIM(ADJUSTL(s_scale))
        RETURN
      END IF
      IF (p /= k) THEN
        row = m6(k, :)
        m6(k, :) = m6(p, :)
        m6(p, :) = row
        tmp = rhs(k)
        rhs(k) = rhs(p)
        rhs(p) = tmp
      END IF
      DO i = k + 1, 6
        tmp = m6(i, k)/m6(k, k)
        m6(i, k:6) = m6(i, k:6) - tmp*m6(k, k:6)
        rhs(i) = rhs(i) - tmp*rhs(k)
      END DO
    END DO
    DO i = 6, 1, -1
      rhs(i) = (rhs(i) - SUM(m6(i, i + 1:6)*rhs(i + 1:6)))/m6(i, i)
    END DO
    IF (.NOT. ALL(IEEE_IS_FINITE(rhs))) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: rigid-body acceleration solve produced a non-finite value'
    END IF
  END SUBROUTINE solve_rigid6x6

  PURE FUNCTION skew3(a) RESULT(s)
    !! Cross-product matrix: skew3(a) b = a x b.
    REAL(wp), INTENT(IN) :: a(3)
    REAL(wp) :: s(3, 3)
    s(1, :) = [CD_ZERO, -a(3), a(2)]
    s(2, :) = [a(3), CD_ZERO, -a(1)]
    s(3, :) = [-a(2), a(1), CD_ZERO]
  END FUNCTION skew3

  PURE FUNCTION global_inertia_diag(rot_mat, inertia) RESULT(d)
    !! Diagonal of R diag(inertia) R^T: a body-frame principal inertia in the global frame.
    REAL(wp), INTENT(IN) :: rot_mat(3, 3), inertia(3)
    REAL(wp) :: d(3)
    INTEGER :: k
    DO k = 1, 3
      d(k) = SUM(rot_mat(k, :)**2*inertia)
    END DO
  END FUNCTION global_inertia_diag

  FUNCTION rigid_omega2_estimate(system, bases, arms, mass6, k6_extra) RESULT(omega2)
    !! Estimate of the largest squared natural frequency of a free rigid body on its moorings,
    !! for the stability limit of the explicit central-difference position update. Each
    !! attached line acts at its attachment as the directional spring
    !!   K = k_ax t t^T + (T/L) (I - t t^T)
    !! (t the unit chord towards the line's other end, L the chord length, k_ax = 1/sum(l0/EA)
    !! the static axial stiffness, T the end-element tension), carried to the reference point
    !! as T_i^T K T_i; the body's own diagonal stiffnesses k6_extra (hydrostatic restoring) are
    !! added. omega^2 is the largest ratio of a diagonal stiffness to the diagonal of the
    !! inertia mass6 (structural plus added mass).
    TYPE(CD_SystemType), INTENT(IN) :: system
    INTEGER, INTENT(IN) :: bases(:)
    REAL(wp), INTENT(IN) :: arms(:, :), mass6(6)
    REAL(wp), INTENT(IN), OPTIONAL :: k6_extra(6)
    REAL(wp) :: omega2
    REAL(wp) :: k6(6), katt(3, 3), s(3, 3), krot(3, 3)
    INTEGER :: i, k

    k6 = CD_ZERO
    IF (PRESENT(k6_extra)) k6 = k6_extra
    DO i = 1, SIZE(bases)
      IF (bases(i) < 0) CYCLE
      katt = line_attachment_stiffness(system, bases(i) + 1)
      s = skew3(arms(:, i))
      krot = -MATMUL(s, MATMUL(katt, s))
      DO k = 1, 3
        k6(k) = k6(k) + katt(k, k)
        k6(3 + k) = k6(3 + k) + krot(k, k)
      END DO
    END DO
    omega2 = CD_ZERO
    DO k = 1, 6
      IF (mass6(k) > CD_ZERO) omega2 = MAX(omega2, k6(k)/mass6(k))
    END DO
  END FUNCTION rigid_omega2_estimate

  FUNCTION line_attachment_stiffness(system, dof) RESULT(katt)
    !! Sum over the lines whose coupled end carries system coupled DOF dof (the x DOF of the
    !! attachment) of the directional spring k_ax t t^T + (T/L)(I - t t^T) of rigid_omega2_estimate.
    TYPE(CD_SystemType), INTENT(IN) :: system
    INTEGER, INTENT(IN) :: dof
    REAL(wp) :: katt(3, 3)
    REAL(wp) :: t(3), chord(3), lc_len, k_ax, ten, el(3), ll, eye(3, 3)
    INTEGER :: i, j, lo, nc, es, node, far, nn, ee
    CHARACTER(160) :: em

    katt = CD_ZERO
    eye = CD_ZERO
    DO i = 1, 3
      eye(i, i) = CD_ONE
    END DO
    lo = 1
    DO i = 1, system%n_lines
      nc = CD_Model_NCoupledDOF(system%lines(i), es, em)
      IF (es /= CD_MODEL_OK) nc = 0
      DO j = 1, nc
        IF (system%coupled_dof_map(lo + j - 1) /= dof) CYCLE
        IF (.NOT. ALL(system%lines(i)%ea > CD_ZERO)) CYCLE
        k_ax = CD_ONE/SUM(system%lines(i)%l0/system%lines(i)%ea)
        nn = SIZE(system%lines(i)%l0) + 1
        node = (system%lines(i)%fixed_dofs(j) - 1)/3 + 1
        IF (node == 1) THEN
          far = nn
          ee = 1
        ELSE
          far = 1
          ee = nn - 1
        END IF
        chord = system%lines(i)%q(3*far - 2:3*far) - system%lines(i)%q(3*node - 2:3*node)
        lc_len = NORM2(chord)
        IF (.NOT. (lc_len > CD_ZERO)) THEN
          katt = katt + k_ax*eye
          CYCLE
        END IF
        t = chord/lc_len
        el = system%lines(i)%q(3*ee + 1:3*ee + 3) - system%lines(i)%q(3*ee - 2:3*ee)
        ll = NORM2(el)
        ten = MAX(CD_ZERO, system%lines(i)%ea(ee)*(ll/system%lines(i)%l0(ee) - CD_ONE))
        katt = katt + k_ax*SPREAD(t, 2, 3)*SPREAD(t, 1, 3) + ten/lc_len*(eye - SPREAD(t, 2, 3)*SPREAD(t, 1, 3))
      END DO
      lo = lo + nc
    END DO
  END FUNCTION line_attachment_stiffness

  PURE INTEGER FUNCTION rigid_substep_count(omega2, dt, omega_dt_max) RESULT(nsub)
    !! Sub-steps per coupled step so that omega*dt_sub stays at or below RIGID_OMEGA_DT_MAX,
    !! capped at RIGID_MAX_SUBSTEPS. The explicit central-difference stability limit is
    !! omega*dt < 2, and omega from rigid_omega2_estimate (directional line stiffness, added
    !! mass included) understates the coupled body-line mode by up to about 1.6x (a light rod
    !! on short lines goes unstable at an estimated omega*dt of 1.27). The limit 0.4 is set by
    !! accuracy, not stability: a rod released out of equilibrium at dt 0.1 s keeps its
    !! fairlead-tension transient within 1.5% of a dt 0.005 s run. omega_dt_max replaces the
    !! limit (bodySubstep accuracy of the monolithic scheme).
    REAL(wp), INTENT(IN) :: omega2, dt
    REAL(wp), INTENT(IN), OPTIONAL :: omega_dt_max
    REAL(wp), PARAMETER :: RIGID_OMEGA_DT_MAX = 0.4_wp
    INTEGER, PARAMETER :: RIGID_MAX_SUBSTEPS = 256
    REAL(wp) :: ratio, lim
    nsub = 1
    IF (.NOT. (omega2 > CD_ZERO .AND. dt > CD_ZERO)) RETURN
    lim = RIGID_OMEGA_DT_MAX
    IF (PRESENT(omega_dt_max)) lim = omega_dt_max
    ratio = SQRT(omega2)*dt/lim
    IF (.NOT. (ratio < REAL(RIGID_MAX_SUBSTEPS, wp))) THEN
      nsub = RIGID_MAX_SUBSTEPS
    ELSE IF (ratio > CD_ONE) THEN
      nsub = CEILING(ratio)
    END IF
  END FUNCTION rigid_substep_count

  SUBROUTINE step_rod_system(system, points, opts, rod_state, time, dt, converged, stalled, n_iter, ErrStat, ErrMsg, &
                             work, bathymetry, host_mask, host_q, host_v, host_a, host_start)
    !! Advance rods and lines from time - dt to time: step_rod_once, sub-cycled so that the
    !! explicit central-difference rod position resolves the stiffest rod-mooring mode
    !! (rigid_substep_count). converged is the AND and stalled the OR over the sub-steps.
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(RodState), INTENT(INOUT) :: rod_state(:)
    REAL(wp), INTENT(IN) :: time, dt
    LOGICAL, INTENT(OUT) :: converged, stalled
    INTEGER, INTENT(OUT) :: n_iter, ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(RodStepWorkspace), INTENT(INOUT) :: work
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    ! host_mask/host_q/host_v/host_a: the host-prescribed (moving) coupled DOFs and their
    ! t + dt kinematics (a coupled host). They enter the line step as its prescribed end motion
    ! while the line ends keep their step-start state, exactly as a plain moving step does.
    LOGICAL, INTENT(IN), OPTIONAL :: host_mask(:)
    REAL(wp), INTENT(IN), OPTIONAL :: host_q(:), host_v(:), host_a(:)

    INTEGER :: ir, nsub, isub, it, base_a, base_b, k
    ! host_start: step-start state of the host-driven rods (see step_rigid6_system)
    TYPE(RodState), INTENT(IN), OPTIONAL :: host_start(:)
    REAL(wp), ALLOCATABLE :: hk_end(:, :)
    LOGICAL :: conv_s, stall_s
    REAL(wp) :: omega2, arms(3, 2), mass6(6), added6(6, 6), drag6(6, 6), f_dummy(3), m_dummy(3)
    REAL(wp), ALLOCATABLE :: q0h(:), v0h(:), a0h(:)

    converged = .TRUE.
    stalled = .FALSE.
    n_iter = 0
    omega2 = CD_ZERO
    DO ir = 1, SIZE(rod_state)
      IF (.NOT. rod_state(ir)%is_free) CYCLE
      arms(:, 1) = MATMUL(rod_state(ir)%rot_mat, [-rod_state(ir)%half_length, CD_ZERO, CD_ZERO])
      arms(:, 2) = -arms(:, 1)
      base_a = system_point_base(system, points(rod_state(ir)%point_a_index)%id)
      base_b = system_point_base(system, points(rod_state(ir)%point_b_index)%id)
      ! structural inertia plus the rod's wet added mass (its 6x6 added-mass diagonal)
      CALL rod_environment_force(rod_state(ir), opts, time - dt, f_dummy, m_dummy, added6, drag6, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      mass6(1:3) = rod_state(ir)%mass
      mass6(4:6) = global_inertia_diag(rod_state(ir)%rot_mat, rod_state(ir)%inertia)
      DO k = 1, 6
        mass6(k) = mass6(k) + MAX(CD_ZERO, added6(k, k))
      END DO
      omega2 = MAX(omega2, rigid_omega2_estimate(system, [base_a, base_b], arms, mass6))
    END DO
    nsub = rigid_substep_count(omega2, dt)
    CALL host_substep_start(system, nsub, q0h, v0h, a0h, ErrStat, ErrMsg, host_mask)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    DO isub = 1, nsub
      IF (nsub > 1 .AND. PRESENT(host_start)) THEN
        IF (isub == 1) CALL save_host_end_rod(rod_state, hk_end)
        CALL interp_host_rod(rod_state, host_start, hk_end, REAL(isub, wp)/REAL(nsub, wp))
      END IF
      IF (.NOT. PRESENT(host_mask)) THEN
        CALL step_rod_once(system, points, opts, rod_state, time - dt + REAL(isub, wp)*dt/REAL(nsub, wp), &
                           dt/REAL(nsub, wp), conv_s, stall_s, it, ErrStat, ErrMsg, work, bathymetry)
      ELSE IF (nsub == 1) THEN
        CALL step_rod_once(system, points, opts, rod_state, time, dt, conv_s, stall_s, it, ErrStat, ErrMsg, work, &
                           bathymetry, host_mask, host_q, host_v, host_a)
      ELSE
        ! sub-steps take the host motion linearly interpolated from the step start
        CALL step_rod_once(system, points, opts, rod_state, time - dt + REAL(isub, wp)*dt/REAL(nsub, wp), &
                           dt/REAL(nsub, wp), conv_s, stall_s, it, ErrStat, ErrMsg, work, bathymetry, host_mask, &
                           q0h + REAL(isub, wp)/REAL(nsub, wp)*(host_q - q0h), &
                           v0h + REAL(isub, wp)/REAL(nsub, wp)*(host_v - v0h), &
                           a0h + REAL(isub, wp)/REAL(nsub, wp)*(host_a - a0h))
      END IF
      converged = converged .AND. conv_s
      stalled = stalled .OR. stall_s
      n_iter = n_iter + it
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END DO
  END SUBROUTINE step_rod_system

  SUBROUTINE save_host_end_rigid(rigid, hk)
    !! Record the t + dt kinematics of the host-driven bodies (columns: r, v, a, omega, alpha,
    !! rot_mat) before sub-stepping moves them along the interpolated host path.
    TYPE(RigidBodyState), INTENT(IN) :: rigid(:)
    REAL(wp), ALLOCATABLE, INTENT(INOUT) :: hk(:, :)
    INTEGER :: ib
    IF (ALLOCATED(hk)) DEALLOCATE (hk)
    ALLOCATE (hk(24, SIZE(rigid)))
    DO ib = 1, SIZE(rigid)
      hk(:, ib) = [rigid(ib)%r, rigid(ib)%v, rigid(ib)%a, rigid(ib)%omega, rigid(ib)%alpha, &
                   RESHAPE(rigid(ib)%rot_mat, [9])]
    END DO
  END SUBROUTINE save_host_end_rigid

  SUBROUTINE interp_host_rigid(rigid, start, hk, s)
    !! Place every host-driven body at fraction s of its step: position, velocity, acceleration
    !! and angular rates linear between the staged step start and the t + dt values in hk, the
    !! rotation along the geodesic R0 exp(s log(R0^T R1)); s = 1 restores the t + dt state.
    TYPE(RigidBodyState), INTENT(INOUT) :: rigid(:)
    TYPE(RigidBodyState), INTENT(IN) :: start(:)
    REAL(wp), INTENT(IN) :: hk(:, :), s
    INTEGER :: ib
    REAL(wp) :: r1(3, 3)
    DO ib = 1, SIZE(rigid)
      IF (.NOT. rigid(ib)%is_prescribed .OR. ib > SIZE(start)) CYCLE
      r1 = RESHAPE(hk(16:24, ib), [3, 3])
      IF (s >= CD_ONE) THEN
        rigid(ib)%r = hk(1:3, ib)
        rigid(ib)%v = hk(4:6, ib)
        rigid(ib)%a = hk(7:9, ib)
        rigid(ib)%omega = hk(10:12, ib)
        rigid(ib)%alpha = hk(13:15, ib)
        rigid(ib)%rot_mat = r1
      ELSE
        rigid(ib)%r = start(ib)%r + s*(hk(1:3, ib) - start(ib)%r)
        rigid(ib)%v = start(ib)%v + s*(hk(4:6, ib) - start(ib)%v)
        rigid(ib)%a = start(ib)%a + s*(hk(7:9, ib) - start(ib)%a)
        rigid(ib)%omega = start(ib)%omega + s*(hk(10:12, ib) - start(ib)%omega)
        rigid(ib)%alpha = start(ib)%alpha + s*(hk(13:15, ib) - start(ib)%alpha)
        rigid(ib)%rot_mat = MATMUL(start(ib)%rot_mat, &
                                   CD_Exp_SO3(s*CD_Log_SO3(MATMUL(TRANSPOSE(start(ib)%rot_mat), r1))))
      END IF
      rigid(ib)%eta = CD_Log_SO3(MATMUL(rigid(ib)%rot_mat, TRANSPOSE(rigid(ib)%rot_ref)))
    END DO
  END SUBROUTINE interp_host_rigid

  SUBROUTINE save_host_end_rod(rods, hk)
    !! Rod twin of save_host_end_rigid.
    TYPE(RodState), INTENT(IN) :: rods(:)
    REAL(wp), ALLOCATABLE, INTENT(INOUT) :: hk(:, :)
    INTEGER :: ir
    IF (ALLOCATED(hk)) DEALLOCATE (hk)
    ALLOCATE (hk(24, SIZE(rods)))
    DO ir = 1, SIZE(rods)
      hk(:, ir) = [rods(ir)%r, rods(ir)%v, rods(ir)%a, rods(ir)%omega, rods(ir)%alpha, &
                   RESHAPE(rods(ir)%rot_mat, [9])]
    END DO
  END SUBROUTINE save_host_end_rod

  SUBROUTINE interp_host_rod(rods, start, hk, s)
    !! Rod twin of interp_host_rigid (the rod centre and frame of each host-driven rod).
    TYPE(RodState), INTENT(INOUT) :: rods(:)
    TYPE(RodState), INTENT(IN) :: start(:)
    REAL(wp), INTENT(IN) :: hk(:, :), s
    INTEGER :: ir
    REAL(wp) :: r1(3, 3)
    DO ir = 1, SIZE(rods)
      IF (.NOT. rods(ir)%is_prescribed .OR. ir > SIZE(start)) CYCLE
      r1 = RESHAPE(hk(16:24, ir), [3, 3])
      IF (s >= CD_ONE) THEN
        rods(ir)%r = hk(1:3, ir)
        rods(ir)%v = hk(4:6, ir)
        rods(ir)%a = hk(7:9, ir)
        rods(ir)%omega = hk(10:12, ir)
        rods(ir)%alpha = hk(13:15, ir)
        rods(ir)%rot_mat = r1
      ELSE
        rods(ir)%r = start(ir)%r + s*(hk(1:3, ir) - start(ir)%r)
        rods(ir)%v = start(ir)%v + s*(hk(4:6, ir) - start(ir)%v)
        rods(ir)%a = start(ir)%a + s*(hk(7:9, ir) - start(ir)%a)
        rods(ir)%omega = start(ir)%omega + s*(hk(10:12, ir) - start(ir)%omega)
        rods(ir)%alpha = start(ir)%alpha + s*(hk(13:15, ir) - start(ir)%alpha)
        rods(ir)%rot_mat = MATMUL(start(ir)%rot_mat, &
                                  CD_Exp_SO3(s*CD_Log_SO3(MATMUL(TRANSPOSE(start(ir)%rot_mat), r1))))
      END IF
    END DO
  END SUBROUTINE interp_host_rod

  SUBROUTINE step_rod_once(system, points, opts, rod_state, time, dt, converged, stalled, n_iter, ErrStat, ErrMsg, &
                           work, bathymetry, host_mask, host_q, host_v, host_a)
    !! One staggered central-difference step of the free rods and their lines (the scheme of
    !! step_rigid6_once; the rod adds its 6x6 added-mass matrix and distributed drag).
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(RodState), INTENT(INOUT) :: rod_state(:)
    REAL(wp), INTENT(IN) :: time, dt
    LOGICAL, INTENT(OUT) :: converged, stalled
    INTEGER, INTENT(OUT) :: n_iter, ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(RodStepWorkspace), INTENT(INOUT) :: work
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    ! host_mask/host_q/host_v/host_a: the host-prescribed (moving) coupled DOFs and their
    ! t + dt kinematics (a coupled host). They enter the line step as its prescribed end motion
    ! while the line ends keep their step-start state, exactly as a plain moving step does.
    LOGICAL, INTENT(IN), OPTIONAL :: host_mask(:)
    REAL(wp), INTENT(IN), OPTIONAL :: host_q(:), host_v(:), host_a(:)

    INTEGER :: ir, es
    REAL(wp) :: dv0(6), acc(3), alpha(3)
    CHARACTER(160) :: em

    converged = .FALSE.
    stalled = .FALSE.
    n_iter = 0
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    CALL ensure_rod_step_workspace(work, system%n_system_coupled_dof, SIZE(rod_state), SIZE(system%points))
    ! 0. a free rod without a committed acceleration (the first step) gets the instantaneous
    ! one from the current line loads, so the predictor starts from the actual a_0
    IF (.NOT. ALL(rod_state%accel_valid .OR. .NOT. rod_state%is_free)) THEN
      CALL rigid_start_loads(system, work%q(1:system%n_system_coupled_dof), work%v(1:system%n_system_coupled_dof), &
                             work%a(1:system%n_system_coupled_dof), work%loads(1:system%n_system_coupled_dof), &
                             work%dload_da, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      DO ir = 1, SIZE(rod_state)
        IF (rod_state(ir)%accel_valid .OR. .NOT. rod_state(ir)%is_free) CYCLE
        CALL rod_body_acceleration(system, points, opts, rod_state(ir), time - dt, CD_ZERO, &
                                   [CD_ZERO, CD_ZERO, CD_ZERO, CD_ZERO, CD_ZERO, CD_ZERO], work, acc, alpha, &
                                   ErrStat, ErrMsg, bathymetry)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        rod_state(ir)%a = acc
        rod_state(ir)%alpha = alpha
        rod_state(ir)%accel_valid = .TRUE.
      END DO
    END IF
    work%old_rods = rod_state
    work%old_points = system%points
    CALL CD_Get_System_CoupledMotion(system, work%q(1:system%n_system_coupled_dof), &
                                     work%v(1:system%n_system_coupled_dof), &
                                     work%a(1:system%n_system_coupled_dof), es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: rod coupled-motion query failed: '//TRIM(em)
      RETURN
    END IF
    CALL overlay_host_motion(work%q(1:system%n_system_coupled_dof), work%v(1:system%n_system_coupled_dof), &
                             work%a(1:system%n_system_coupled_dof), host_mask, host_q, host_v, host_a)
    ! 1. predictor for the free rods (central difference; see step_rigid6_once for the
    ! staggered predictor-corrector) and the line step to t + dt
    DO ir = 1, SIZE(rod_state)
      IF (.NOT. rod_state(ir)%is_free) THEN
        IF (.NOT. rod_state(ir)%is_prescribed) THEN
          rod_state(ir)%v = CD_ZERO
          rod_state(ir)%a = CD_ZERO
          rod_state(ir)%omega = CD_ZERO
          rod_state(ir)%alpha = CD_ZERO
        END IF
        CYCLE
      END IF
      CALL CD_Rigid_Advance_Newmark(rod_state(ir)%r, rod_state(ir)%v, rod_state(ir)%rot_mat, rod_state(ir)%omega, &
                                    rod_state(ir)%a, rod_state(ir)%alpha, rod_state(ir)%a, rod_state(ir)%alpha, &
                                    dt, CD_RIGID_NEWMARK_GAMMA, CD_RIGID_NEWMARK_BETA, es, em)
      IF (es /= CD_RIGID_OK) THEN
        rod_state = work%old_rods
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: rod finite-rotation update failed: '//TRIM(em)
        RETURN
      END IF
    END DO
    CALL scatter_rod_point_motion(system, points, rod_state, work%q(1:system%n_system_coupled_dof), &
                                  work%v(1:system%n_system_coupled_dof), &
                                  work%a(1:system%n_system_coupled_dof))
    CALL CD_Update_System_Point_States(system, work%q(1:system%n_system_coupled_dof), &
                                       work%v(1:system%n_system_coupled_dof), &
                                       work%a(1:system%n_system_coupled_dof), es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      rod_state = work%old_rods
      system%points = work%old_points
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: rod point-state update failed: '//TRIM(em)
      RETURN
    END IF
    CALL CD_Step_System(system, dt, work%q(1:system%n_system_coupled_dof), &
                        work%v(1:system%n_system_coupled_dof), work%a(1:system%n_system_coupled_dof), &
                        converged, stalled, n_iter, es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      rod_state = work%old_rods
      system%points = work%old_points
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: rod line-system step failed: '//TRIM(em)
      RETURN
    END IF
    IF (.NOT. ANY(rod_state%is_free)) RETURN
    ! 2. corrector from the end-of-step line loads at the predictor
    CALL CD_Calc_System_CoupledLoads(system, work%loads(1:system%n_system_coupled_dof), es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      rod_state = work%old_rods
      system%points = work%old_points
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: rod coupled-load query failed: '//TRIM(em)
      RETURN
    END IF
    CALL CD_Calc_System_CoupledAccelDerivative(system, work%dload_da, es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      rod_state = work%old_rods
      system%points = work%old_points
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: rod line-end load-derivative query failed: '//TRIM(em)
      RETURN
    END IF

    DO ir = 1, SIZE(rod_state)
      IF (.NOT. rod_state(ir)%is_free) CYCLE
      dv0(1:3) = -CD_RIGID_NEWMARK_GAMMA*dt*work%old_rods(ir)%a
      dv0(4:6) = -CD_RIGID_NEWMARK_GAMMA*dt*work%old_rods(ir)%alpha
      CALL rod_body_acceleration(system, points, opts, rod_state(ir), time, dt, dv0, work, acc, alpha, &
                                 ErrStat, ErrMsg, bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        rod_state = work%old_rods
        system%points = work%old_points
        RETURN
      END IF
      ! the Newmark update from the start-of-step state with (a_n, a_{n+1})
      rod_state(ir) = work%old_rods(ir)
      CALL CD_Rigid_Advance_Newmark(rod_state(ir)%r, rod_state(ir)%v, rod_state(ir)%rot_mat, rod_state(ir)%omega, &
                                    work%old_rods(ir)%a, work%old_rods(ir)%alpha, acc, alpha, dt, &
                                    CD_RIGID_NEWMARK_GAMMA, CD_RIGID_NEWMARK_BETA, es, em)
      IF (es /= CD_RIGID_OK) THEN
        rod_state = work%old_rods
        system%points = work%old_points
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: rod finite-rotation update failed: '//TRIM(em)
        RETURN
      END IF
      rod_state(ir)%a = acc
      rod_state(ir)%alpha = alpha
    END DO
    ! the Rod<N>A/B point records follow the corrected rods
    CALL scatter_rod_point_motion(system, points, rod_state, work%q(1:system%n_system_coupled_dof), &
                                  work%v(1:system%n_system_coupled_dof), &
                                  work%a(1:system%n_system_coupled_dof))
    CALL CD_Update_System_Point_States(system, work%q(1:system%n_system_coupled_dof), &
                                       work%v(1:system%n_system_coupled_dof), &
                                       work%a(1:system%n_system_coupled_dof), es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      rod_state = work%old_rods
      system%points = work%old_points
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: rod point-state update failed: '//TRIM(em)
      RETURN
    END IF
  END SUBROUTINE step_rod_once

  SUBROUTINE rod_body_acceleration(system, points, opts, rod, time, dt, dv0, work, acc, alpha, ErrStat, ErrMsg, &
                                   bathymetry)
    !! The acceleration of a free rod at its current state and time from its weight, the
    !! distributed Morison / buoyancy loads (rod_environment_force), the seabed contact and the
    !! line loads in work%loads (evaluated with the attachment accelerations work%a, end-node
    !! inertia derivative work%dload_da): rigid_coupled_acceleration with the step dt and
    !! velocity offset dv0 (dt = 0, dv0 = 0: the instantaneous acceleration).
    TYPE(CD_SystemType), INTENT(IN) :: system
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(RodState), INTENT(IN) :: rod
    REAL(wp), INTENT(IN) :: time, dt, dv0(6)
    TYPE(RodStepWorkspace), INTENT(IN) :: work
    REAL(wp), INTENT(OUT) :: acc(3), alpha(3)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    INTEGER :: base_a, base_b
    REAL(wp) :: f_body(3), f_env(3), f_seabed(3), m_env(3), m_seabed(3), m_global(3)
    REAL(wp) :: f_a(3), f_b(3), added6(6, 6), drag6(6, 6), contact_dv(6, 6), att_arm(3, 2)

    acc = CD_ZERO
    alpha = CD_ZERO
    att_arm(:, 1) = MATMUL(rod%rot_mat, [-rod%half_length, CD_ZERO, CD_ZERO])
    att_arm(:, 2) = -att_arm(:, 1)
    base_a = system_point_base(system, points(rod%point_a_index)%id)
    base_b = system_point_base(system, points(rod%point_b_index)%id)
    f_a = CD_ZERO
    f_b = CD_ZERO
    IF (base_a >= 0) f_a = work%loads(base_a + 1:base_a + 3)
    IF (base_b >= 0) f_b = work%loads(base_b + 1:base_b + 3)
    ! Weight acts at the rod centre (full dry mass); buoyancy is applied wet-volume-scaled
    ! inside rod_environment_force (f_env / m_env) so dry / partially submerged rods are correct.
    f_body = [CD_ZERO, CD_ZERO, -rod%mass*opts%g] + f_a + f_b
    m_global = cross3(att_arm(:, 1), f_a) + cross3(att_arm(:, 2), f_b)
    CALL rod_environment_force(rod, opts, time, f_env, m_env, added6, drag6, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL rod_seabed_contact(rod, opts, f_seabed, m_seabed, contact_dv, ErrStat, ErrMsg, bathymetry)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    f_body = f_body + f_env + f_seabed
    m_global = m_global + m_env + m_seabed
    CALL rigid_coupled_acceleration(work%dload_da, dt, work%a(1:system%n_system_coupled_dof), [base_a, base_b], &
                                    att_arm, rod%mass, added6, rod%inertia, rod%rot_mat, rod%omega, f_body, &
                                    m_global, dv0, drag6 + contact_dv, acc, alpha, ErrStat, ErrMsg)
  END SUBROUTINE rod_body_acceleration

  SUBROUTINE step_prescribed_rod_system(system, points, opts, motion, rod_state, time_index, time, dt, &
                                        converged, stalled, n_iter, ErrStat, ErrMsg, work, hydro_work, bathymetry)
    !! Impose the motionFile rows on prescribed rods, then march the free rods and lines. The
    !! optional structured bathymetry is forwarded (absent stays absent) so free rods keep their
    !! seabed contact when a bathymetryFile deck also carries prescribed rods.
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(MotionTable), INTENT(IN) :: motion
    TYPE(RodState), INTENT(INOUT) :: rod_state(:)
    INTEGER, INTENT(IN) :: time_index
    REAL(wp), INTENT(IN) :: time, dt
    LOGICAL, INTENT(OUT) :: converged, stalled
    INTEGER, INTENT(OUT) :: n_iter, ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(RodStepWorkspace), INTENT(INOUT) :: work
    TYPE(HydroUpdateWorkspace), INTENT(INOUT) :: hydro_work
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    INTEGER :: es
    CHARACTER(160) :: em

    converged = .FALSE.
    stalled = .FALSE.
    n_iter = 0
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    CALL ensure_rod_step_workspace(work, system%n_system_coupled_dof, SIZE(rod_state), SIZE(system%points))
    work%old_rods = rod_state
    work%old_points = system%points
    CALL set_prescribed_rod_states(points, motion, time_index, rod_state, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      rod_state = work%old_rods
      system%points = work%old_points
      RETURN
    END IF
    CALL apply_rod_states_to_system(system, points, rod_state, work, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      rod_state = work%old_rods
      system%points = work%old_points
      RETURN
    END IF
    CALL update_system_line_hydro(system, opts, time, hydro_work, es, em)
    IF (es /= CD_DECKDRV_OK) THEN
      rod_state = work%old_rods
      system%points = work%old_points
      ErrStat = es
      ErrMsg = em
      RETURN
    END IF
    CALL step_rod_system(system, points, opts, rod_state, time, dt, converged, stalled, n_iter, ErrStat, ErrMsg, &
                         work, bathymetry)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      rod_state = work%old_rods
      system%points = work%old_points
      RETURN
    END IF
  END SUBROUTINE step_prescribed_rod_system

  SUBROUTINE apply_rod_states_to_system(system, points, rod_state, work, ErrStat, ErrMsg)
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(RodState), INTENT(IN) :: rod_state(:)
    TYPE(RodStepWorkspace), INTENT(INOUT) :: work
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: es
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    CALL ensure_rod_step_workspace(work, system%n_system_coupled_dof, SIZE(rod_state), SIZE(system%points))
    CALL CD_Get_System_CoupledMotion(system, work%q(1:system%n_system_coupled_dof), &
                                     work%v(1:system%n_system_coupled_dof), &
                                     work%a(1:system%n_system_coupled_dof), es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: prescribed rod coupled-motion query failed: '//TRIM(em)
      RETURN
    END IF
    CALL scatter_rod_point_motion(system, points, rod_state, work%q(1:system%n_system_coupled_dof), &
                                  work%v(1:system%n_system_coupled_dof), &
                                  work%a(1:system%n_system_coupled_dof))
    CALL CD_Update_System_Point_States(system, work%q(1:system%n_system_coupled_dof), &
                                       work%v(1:system%n_system_coupled_dof), &
                                       work%a(1:system%n_system_coupled_dof), es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: prescribed rod point-state update failed: '//TRIM(em)
      RETURN
    END IF
  END SUBROUTINE apply_rod_states_to_system

  SUBROUTINE set_prescribed_rod_states(points, motion, time_index, rod_state, ErrStat, ErrMsg)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(MotionTable), INTENT(IN) :: motion
    INTEGER, INTENT(IN) :: time_index
    TYPE(RodState), INTENT(INOUT) :: rod_state(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: ir, ia, ib
    REAL(wp) :: qa(3), qb(3), va(3), vb(3), aa(3), ab(3), span(3), vrel(3), arel(3)
    REAL(wp) :: length, tol

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (time_index < 1 .OR. time_index > motion%n_time) THEN
      CALL fail(ErrStat, ErrMsg, 'prescribed rod motion time index is outside the motion table')
      RETURN
    END IF
    DO ir = 1, SIZE(rod_state)
      IF (.NOT. rod_state(ir)%is_prescribed) THEN
        IF (.NOT. rod_state(ir)%is_free) THEN
          rod_state(ir)%v = CD_ZERO
          rod_state(ir)%a = CD_ZERO
          rod_state(ir)%omega = CD_ZERO
          rod_state(ir)%alpha = CD_ZERO
        END IF
        CYCLE
      END IF
      ia = find_motion_point(motion, points(rod_state(ir)%point_a_index)%id)
      ib = find_motion_point(motion, points(rod_state(ir)%point_b_index)%id)
      IF (ia == 0 .OR. ib == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'motionFile missing Rod<N>A/B point rows for prescribed ROD '// &
                  TRIM(int_to_str(rod_state(ir)%rod_id)))
        RETURN
      END IF
      qa = motion%q(:, ia, time_index)
      qb = motion%q(:, ib, time_index)
      va = motion%v(:, ia, time_index)
      vb = motion%v(:, ib, time_index)
      aa = motion%a(:, ia, time_index)
      ab = motion%a(:, ib, time_index)
      span = qb - qa
      length = SQRT(SUM(span*span))
      tol = 1.0e-8_wp*MAX(CD_ONE, rod_state(ir)%length)
      IF (ABS(length - rod_state(ir)%length) > tol) THEN
        CALL fail(ErrStat, ErrMsg, 'motionFile prescribed ROD '//TRIM(int_to_str(rod_state(ir)%rod_id))// &
                  ' does not preserve rod length')
        RETURN
      END IF
      IF (length <= 100.0_wp*EPSILON(CD_ONE)) THEN
        CALL fail(ErrStat, ErrMsg, 'motionFile prescribed ROD has degenerate endpoints')
        RETURN
      END IF
      vrel = vb - va
      arel = ab - aa
      rod_state(ir)%r = 0.5_wp*(qa + qb)
      rod_state(ir)%v = 0.5_wp*(va + vb)
      rod_state(ir)%a = 0.5_wp*(aa + ab)
      rod_state(ir)%rot_mat = rod_orientation_from_axis(span/length)
      rod_state(ir)%omega = cross3(span, vrel)/(length*length)
      rod_state(ir)%alpha = cross3(span, arel)/(length*length)
    END DO
  END SUBROUTINE set_prescribed_rod_states

  SUBROUTINE rod_seabed_contact(rod, opts, force, moment, load_dv, ErrStat, ErrMsg, bathymetry)
    !! One-sided seabed contact distributed along a rigid rod. kBot/cBot are per unit contact
    !! area (N/m^3, N.s/m^3), as for line nodes: the rod is split into ncontact = max(20,
    !! NumSegs) equal segments and each of the ncontact + 1 stations (End A, interior nodes,
    !! End B) carries a spring kBot*d*dl and a downward-only damper cBot*d*dl over its tributary
    !! length dl (L/ncontact inside, half that at the ends). The per-station forces are summed into a
    !! force and a moment about the rod centre, so a rod lying on the bed is supported along
    !! its whole length with the distributed rotational stiffness. load_dv returns the 6x6
    !! derivative of (force, moment) w.r.t. the rod (velocity, angular velocity) from the
    !! active normal dampers, which the rigid-body step applies implicitly; the springs and the
    !! regularized friction act at the evaluated position and velocity.
    TYPE(RodState), INTENT(IN) :: rod
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(OUT) :: force(3), moment(3), load_dv(6, 6)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    INTEGER :: i, ncontact
    REAL(wp), PARAMETER :: vreg = 1.0e-3_wp
    REAL(wp) :: arm(3), r_eval(3), v_eval(3), f_i(3), z_floor, penetration, normal, denom
    REAL(wp) :: dl, s, contact_width, blk(3, 3)
    LOGICAL :: has_floor

    force = CD_ZERO
    moment = CD_ZERO
    load_dv = CD_ZERO
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    contact_width = rod%diam
    ncontact = MAX(20, rod%nsegs)
    DO i = 0, ncontact
      s = -rod%half_length + rod%length*REAL(i, wp)/REAL(ncontact, wp)
      dl = rod%length/REAL(ncontact, wp)
      IF (i == 0 .OR. i == ncontact) dl = 0.5_wp*dl
      arm = MATMUL(rod%rot_mat, [s, CD_ZERO, CD_ZERO])
      r_eval = rod%r + arm
      v_eval = rod%v + cross3(rod%omega, arm)
      CALL deck_seabed_floor_at(r_eval(1), r_eval(2), opts, has_floor, z_floor, ErrStat, ErrMsg, bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      IF (.NOT. has_floor) CYCLE
      penetration = z_floor - r_eval(3)
      IF (penetration <= CD_ZERO) CYCLE
      normal = opts%kbot*contact_width*dl*penetration
      IF (v_eval(3) < CD_ZERO) THEN
        normal = normal - opts%cbot*contact_width*dl*v_eval(3)
        blk = CD_ZERO
        blk(3, 3) = -opts%cbot*contact_width*dl
        CALL add_arm_block6(load_dv, blk, arm)
      END IF
      f_i = CD_ZERO
      IF (opts%has_friction) THEN
        denom = SQRT(v_eval(1)**2 + v_eval(2)**2 + vreg**2)
        f_i(1) = -opts%friction_mu*normal*v_eval(1)/denom
        f_i(2) = -opts%friction_mu*normal*v_eval(2)/denom
      END IF
      f_i(3) = normal
      force = force + f_i
      moment = moment + cross3(arm, f_i)
    END DO
  END SUBROUTINE rod_seabed_contact

  PURE SUBROUTINE add_arm_block6(mat, blk, arm)
    !! Add T^T blk T to a 6x6 rigid-body matrix about the reference point, T = [I, -[arm]x]
    !! mapping (translation, rotation) of the reference point to the point at arm: the 3x3
    !! blk (a point-load derivative w.r.t. that point's motion) becomes the force/moment
    !! derivative w.r.t. the body motion.
    REAL(wp), INTENT(INOUT) :: mat(6, 6)
    REAL(wp), INTENT(IN) :: blk(3, 3), arm(3)
    REAL(wp) :: s(3, 3), b_s(3, 3)
    s = skew3(arm)
    b_s = MATMUL(blk, s)
    mat(1:3, 1:3) = mat(1:3, 1:3) + blk
    mat(1:3, 4:6) = mat(1:3, 4:6) - b_s
    mat(4:6, 1:3) = mat(4:6, 1:3) + MATMUL(s, blk)
    mat(4:6, 4:6) = mat(4:6, 4:6) - MATMUL(s, b_s)
  END SUBROUTINE add_arm_block6

  SUBROUTINE rod_environment_force(rod, opts, time, force, moment, added_mass, drag_dv, ErrStat, ErrMsg)
    !! Distributed hydrostatic and Morison loads of a rigid rod about its centre, the rod's 6x6
    !! hydrodynamic added-mass matrix about the same point (global frame) and the 6x6 derivative
    !! drag_dv of the drag force/moment w.r.t. the rod (velocity, angular velocity), which the
    !! rigid-body step uses to treat the quadratic drag implicitly.
    !!
    !! The rod is split into its NumSegs equal segments. Each cross-section (slice normal to the
    !! axis q) is wet below the local free surface: with the axis at angle phi to the vertical a
    !! slice spans r sin(phi) above and below its centre, and the part below the surface is the
    !! circular segment of area A_w(d) = r^2 acos(-d/r) + d sqrt(r^2 - d^2), d = (eta - z)/sin(phi),
    !! whose centroid lies -(2/3)(r^2 - d^2)^(3/2)/A_w from the slice centre along the in-slice
    !! up-slope direction p. The free surface is taken linear between the segment end stations,
    !! so every segment splits into a fully wet, a partially wet and a dry part at known axial
    !! positions; the fully wet part is integrated by 2-point Gauss (NumSegs = 1 gives a two-point
    !! rule) and the partially wet part by 10-point Gauss in
    !! theta, d = r sin(theta), in which the integrands are smooth. Buoyancy rhoW g A_w per unit
    !! length acts vertically at the wet centroid, so the hydrostatic force and moment are those
    !! of the displaced volume of the cylinder (end caps included) at any tilt: the waterplane
    !! restoring of a surface-piercing rod follows from it and the loads are continuous in the
    !! submergence. The other terms scale with the wet fraction f = A_w/A of each station:
    !!   added mass    rhoW A f [Ca (I - q q^T) + CaAx q q^T]      (rotational part from the arm)
    !!   drag          (1/2) rhoW d f [Cd |u_n| u_n + CdAx pi |u_t| u_t]
    !!   fluid inertia rhoW A f [(1 + Ca)(I - q q^T) + CaAx q q^T] du  (+ q q^T du without the
    !!                 end-cap dynamic pressure below)
    !! and each station carries the centripetal reaction -A_i w x (w x p_i) of its added mass.
    !! At each rod end the MoorDyn end terms act with the end slice's wet fraction: added mass
    !! rhoW CaEnd V_end q q^T (V_end = (2/3) pi r^3), axial drag (1/2) rhoW CdEnd A |u_q| u_q and
    !! axial fluid inertia rhoW CaEnd V_end (du.q) q; with deck waves the end cap also carries the
    !! dynamic pressure -(p_dyn - rhoW g eta*) A n_e (n_e the outward normal; eta* the waterline
    !! elevation of a surface-piercing rod, zero for a submerged one, so that the cap carries the
    !! still-water hydrostatic pressure plus p_dyn). The dynamic pressure carries the axial
    !! Froude-Krylov force, so the side axial inertia keeps only CaAx then; with host-held fluid
    !! and no host dynamic pressure the side keeps 1 + CaAx. Host-held fluid is sampled at the NumSegs + 1
    !! segment stations and interpolated linearly along the rod; when the host also supplies the
    !! dynamic pressure the end caps carry it as with deck waves (side axial term CaAx only).
    TYPE(RodState), INTENT(IN) :: rod
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time
    REAL(wp), INTENT(OUT) :: force(3), moment(3), added_mass(6, 6), drag_dv(6, 6)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    REAL(wp), PARAMETER :: gp2(2) = [-0.57735026918962576451_wp, 0.57735026918962576451_wp]
    REAL(wp), PARAMETER :: gx10(10) = [-0.97390652851717174343_wp, -0.86506336668898453635_wp, &
                                       -0.67940956829902443559_wp, -0.43339539412924721340_wp, &
                                       -0.14887433898163121571_wp, 0.14887433898163121571_wp, &
                                       0.43339539412924721340_wp, 0.67940956829902443559_wp, &
                                       0.86506336668898453635_wp, 0.97390652851717174343_wp]
    REAL(wp), PARAMETER :: gw10(10) = [0.06667134430868813799_wp, 0.14945134915058039260_wp, &
                                       0.21908636251598201383_wp, 0.26926671930999651616_wp, &
                                       0.29552422471475281451_wp, 0.29552422471475281451_wp, &
                                       0.26926671930999651616_wp, 0.21908636251598201383_wp, &
                                       0.14945134915058039260_wp, 0.06667134430868813799_wp]
    REAL(wp), PARAMETER :: HALF_PI = 2.0_wp*QUARTER_PI
    INTEGER :: nseg, j, k, ie
    LOGICAL :: calm, use_pdyn
    REAL(wp) :: axis(3), pvec(3), axis_outer(3, 3), a_unit(3, 3), eye3(3, 3)
    REAL(wp) :: r0, area, lseg, sphi, rs, eta_mean, ax_fk, s_a, h_a, h_b, dh, tlo, thi, tmp, th1, th2, th
    REAL(wp) :: f_end(2), eta_end(2), h_st(0:MAX(1, rod%nsegs))
    REAL(wp) :: vol_end, kq, vq, u(3), du(3), eta, pd, x(3), v_end(3), arm(3), n_e(3), eta_star, f_c(3)

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    force = CD_ZERO
    moment = CD_ZERO
    added_mass = CD_ZERO
    drag_dv = CD_ZERO
    nseg = MAX(1, rod%nsegs)
    axis = rod%rot_mat(:, 1)
    r0 = 0.5_wp*rod%diam
    area = QUARTER_PI*rod%diam**2
    lseg = rod%length/REAL(nseg, wp)
    sphi = SQRT(MAX(CD_ZERO, CD_ONE - axis(3)**2))
    rs = r0*sphi
    pvec = CD_ZERO
    IF (sphi > 1.0e-12_wp) pvec = ([CD_ZERO, CD_ZERO, CD_ONE] - axis(3)*axis)/sphi
    eye3 = CD_ZERO
    DO k = 1, 3
      eye3(k, k) = CD_ONE
    END DO
    axis_outer = SPREAD(axis, DIM=2, NCOPIES=3)*SPREAD(axis, DIM=1, NCOPIES=3)
    a_unit = rod%can*(eye3 - axis_outer) + rod%cat*axis_outer
    calm = .NOT. (rod%has_held .OR. opts%has_wave .OR. opts%has_current)
    use_pdyn = (opts%has_wave .AND. .NOT. rod%has_held) .OR. (rod%has_held .AND. rod%has_held_pd)
    ax_fk = rod%cat
    IF (.NOT. use_pdyn) ax_fk = CD_ONE + rod%cat
    eta_mean = CD_ZERO
    IF (use_pdyn .AND. .NOT. rod%has_held .AND. opts%wave_kind == WAVE_COMPONENTS) eta_mean = opts%wave_eta_mean

    ! free-surface clearance h = eta - z at the segment end stations
    DO j = 0, nseg
      s_a = -rod%half_length + REAL(j, wp)*lseg
      x = rod%r + s_a*axis
      CALL fluid_at(x, s_a, u, du, eta, pd, .FALSE.)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      h_st(j) = eta - x(3)
      IF (j == 0) eta_end(1) = eta
      IF (j == nseg) eta_end(2) = eta
    END DO

    DO j = 1, nseg
      s_a = -rod%half_length + REAL(j - 1, wp)*lseg
      h_a = h_st(j - 1)
      h_b = h_st(j)
      dh = h_b - h_a
      IF (rs <= 1.0e-9_wp*r0) THEN
        ! (near-)vertical rod: every slice is wet or dry as a whole
        IF (ABS(dh) <= TINY(CD_ONE)) THEN
          IF (h_a > CD_ZERO) CALL gauss2(CD_ZERO, CD_ONE, CD_ONE, CD_ZERO)
        ELSE
          tmp = -h_a/dh
          IF (dh > CD_ZERO) THEN
            CALL gauss2(MAX(CD_ZERO, tmp), CD_ONE, CD_ONE, CD_ZERO)
          ELSE
            CALL gauss2(CD_ZERO, MIN(CD_ONE, tmp), CD_ONE, CD_ZERO)
          END IF
        END IF
      ELSE IF (ABS(dh) <= 1.0e-12_wp*rs) THEN
        ! the surface runs parallel to the segment: one wet fraction along it
        IF (h_a >= rs) THEN
          CALL gauss2(CD_ZERO, CD_ONE, CD_ONE, CD_ZERO)
        ELSE IF (h_a > -rs) THEN
          th = ASIN(h_a/rs)
          CALL gauss2(CD_ZERO, CD_ONE, wet_fraction(th), wet_offset(th))
        END IF
      ELSE
        tlo = (-rs - h_a)/dh
        thi = (rs - h_a)/dh
        IF (tlo > thi) THEN
          tmp = tlo
          tlo = thi
          thi = tmp
        END IF
        tlo = MIN(CD_ONE, MAX(CD_ZERO, tlo))
        thi = MIN(CD_ONE, MAX(CD_ZERO, thi))
        ! outer parts: fully wet or dry
        IF (tlo > CD_ZERO .AND. h_a + dh*0.5_wp*tlo >= rs) CALL gauss2(CD_ZERO, tlo, CD_ONE, CD_ZERO)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        IF (thi < CD_ONE .AND. h_a + dh*0.5_wp*(thi + CD_ONE) >= rs) CALL gauss2(thi, CD_ONE, CD_ONE, CD_ZERO)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        ! partially wet part, integrated in theta (h = rs sin(theta), t linear in h)
        IF (thi > tlo) THEN
          th1 = ASIN(MIN(CD_ONE, MAX(-CD_ONE, (h_a + dh*tlo)/rs)))
          th2 = ASIN(MIN(CD_ONE, MAX(-CD_ONE, (h_a + dh*thi)/rs)))
          DO k = 1, 10
            th = 0.5_wp*(th1 + th2) + 0.5_wp*(th2 - th1)*gx10(k)
            tmp = (rs*SIN(th) - h_a)/dh
            CALL station(s_a + tmp*lseg, ABS(0.5_wp*(th2 - th1)*gw10(k)*lseg*rs*COS(th)/dh), &
                         wet_fraction(th), wet_offset(th))
            IF (ErrStat /= CD_DECKDRV_OK) RETURN
          END DO
        END IF
      END IF
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END DO

    ! rodHydro moordyn: MoorDyn's waterplane moment (pi d^4/16) rho g sin(phi) cos(phi) with its
    ! end-cap moment, whose net exceeds the exact displaced-volume moment by (pi d^4/32) rho g
    ! sin(phi) cos(phi); applied, as in MoorDyn, while End A is below the surface and End B above
    IF (opts%rod_hydro_moordyn .AND. h_st(0) > CD_ZERO .AND. h_st(nseg) < CD_ZERO .AND. sphi > CD_ZERO) THEN
      moment = moment + opts%rhoW*opts%g*(QUARTER_PI*rod%diam**4/8.0_wp)*axis(3)* &
               cross3(axis, [CD_ZERO, CD_ZERO, CD_ONE])
    END IF
    ! MoorDyn end effects and the end-cap dynamic pressure
    IF (.NOT. (rod%cdend > CD_ZERO .OR. rod%caend > CD_ZERO .OR. use_pdyn)) RETURN
    DO ie = 1, 2
      IF (rs <= 1.0e-9_wp*r0) THEN
        f_end(ie) = MERGE(CD_ONE, CD_ZERO, h_st((ie - 1)*nseg) > CD_ZERO)
      ELSE
        f_end(ie) = wet_fraction(ASIN(MIN(CD_ONE, MAX(-CD_ONE, h_st((ie - 1)*nseg)/rs))))
      END IF
    END DO
    vol_end = (2.0_wp/3.0_wp)*QUARTER_PI*rod%diam**2*r0
    DO ie = 1, 2
      IF (.NOT. (f_end(ie) > CD_ZERO)) CYCLE
      s_a = rod%half_length*REAL(2*ie - 3, wp)
      arm = s_a*axis
      n_e = REAL(2*ie - 3, wp)*axis
      x = rod%r + arm
      v_end = rod%v + cross3(rod%omega, arm)
      CALL fluid_at(x, s_a, u, du, eta, pd, .TRUE.)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      added_mass(1:3, 1:3) = added_mass(1:3, 1:3) + f_end(ie)*opts%rhoW*rod%caend*vol_end*axis_outer
      kq = 0.5_wp*opts%rhoW*rod%cdend*area*f_end(ie)
      vq = DOT_PRODUCT(u - v_end, axis)
      f_c = kq*ABS(vq)*vq*axis + f_end(ie)*opts%rhoW*rod%caend*vol_end*DOT_PRODUCT(du, axis)*axis
      IF (use_pdyn) THEN
        eta_star = (CD_ONE - f_end(3 - ie))*(eta_end(3 - ie) - eta_mean)
        f_c = f_c - f_end(ie)*opts%rhoW*(pd - opts%g*eta_star)*area*n_e
      END IF
      ! every end term acts along the axis through the centre: no moment about it
      force = force + f_c
      CALL add_arm_block6(drag_dv, -2.0_wp*kq*ABS(vq)*axis_outer, arm)
    END DO

  CONTAINS

    PURE REAL(wp) FUNCTION wet_fraction(theta) RESULT(f)
      !! Wet fraction of a slice whose chord lies at d = r sin(theta) above its centre.
      REAL(wp), INTENT(IN) :: theta
      f = (HALF_PI + theta + SIN(theta)*COS(theta))/(4.0_wp*QUARTER_PI)
    END FUNCTION wet_fraction

    PURE REAL(wp) FUNCTION wet_offset(theta) RESULT(c)
      !! Offset of the slice's wet centroid along the up-slope direction p.
      REAL(wp), INTENT(IN) :: theta
      REAL(wp) :: aw
      aw = r0*r0*(HALF_PI + theta + SIN(theta)*COS(theta))
      c = CD_ZERO
      IF (aw > TINY(CD_ONE)) c = -(2.0_wp/3.0_wp)*(r0*COS(theta))**3/aw
    END FUNCTION wet_offset

    SUBROUTINE gauss2(t1, t2, f, c)
      !! 2-point Gauss stations on the segment fraction [t1, t2] with wet fraction f, offset c.
      REAL(wp), INTENT(IN) :: t1, t2, f, c
      INTEGER :: m
      IF (.NOT. (t2 > t1)) RETURN
      DO m = 1, 2
        CALL station(s_a + lseg*(0.5_wp*(t1 + t2) + 0.5_wp*(t2 - t1)*gp2(m)), 0.5_wp*(t2 - t1)*lseg, f, c)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      END DO
    END SUBROUTINE gauss2

    SUBROUTINE station(s, w, f, c)
      !! Loads of the slice at axial position s with length weight w, wet fraction f and wet
      !! centroid offset c.
      REAL(wp), INTENT(IN) :: s, w, f, c
      REAL(wp) :: arm_s(3), xs(3), vs(3), us(3), dus(3), etas, pds, vol, a_i(3, 3), s_i(3, 3), a_s(3, 3)
      REAL(wp) :: rel(3), rel_axial(3), rel_normal(3), vn, vt, kn, kt, acc_axial(3), f_i(3), blk(3, 3), fb(3)

      IF (.NOT. (f > CD_ZERO .AND. w > CD_ZERO)) RETURN
      arm_s = s*axis
      xs = rod%r + arm_s
      vs = rod%v + cross3(rod%omega, arm_s)
      CALL fluid_at(xs, s, us, dus, etas, pds, .FALSE.)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      vol = area*f*w
      a_i = opts%rhoW*vol*a_unit
      s_i = skew3(arm_s)
      a_s = MATMUL(a_i, s_i)
      added_mass(1:3, 1:3) = added_mass(1:3, 1:3) + a_i
      added_mass(1:3, 4:6) = added_mass(1:3, 4:6) - a_s
      added_mass(4:6, 1:3) = added_mass(4:6, 1:3) + MATMUL(s_i, a_i)
      added_mass(4:6, 4:6) = added_mass(4:6, 4:6) - MATMUL(s_i, a_s)
      f_i = -MATMUL(a_i, cross3(rod%omega, cross3(rod%omega, arm_s)))
      force = force + f_i
      moment = moment + cross3(arm_s, f_i)
      ! buoyancy of the wet part of the slice, at its centroid
      fb = [CD_ZERO, CD_ZERO, opts%rhoW*vol*opts%g]
      force = force + fb
      moment = moment + cross3(arm_s + c*pvec, fb)
      rel = us - vs
      acc_axial = DOT_PRODUCT(dus, axis)*axis
      rel_axial = DOT_PRODUCT(rel, axis)*axis
      rel_normal = rel - rel_axial
      vt = SQRT(SUM(rel_axial*rel_axial))
      vn = SQRT(SUM(rel_normal*rel_normal))
      kn = 0.5_wp*opts%rhoW*rod%cdn*rod%diam*f*w
      kt = 0.5_wp*opts%rhoW*rod%cdt*(4.0_wp*QUARTER_PI)*rod%diam*f*w
      f_i = kn*vn*rel_normal + kt*vt*rel_axial + &
            opts%rhoW*vol*((CD_ONE + rod%can)*(dus - acc_axial) + ax_fk*acc_axial)
      force = force + f_i
      moment = moment + cross3(arm_s, f_i)
      blk = -2.0_wp*kt*vt*axis_outer
      IF (vn > CD_ZERO) THEN
        blk = blk - kn*vn*(eye3 - axis_outer) - kn*SPREAD(rel_normal, DIM=2, NCOPIES=3)* &
              SPREAD(rel_normal, DIM=1, NCOPIES=3)/vn
      END IF
      CALL add_arm_block6(drag_dv, blk, arm_s)
    END SUBROUTINE station

    SUBROUTINE fluid_at(xq, s, uq, duq, etaq, pdq, want_pdyn)
      !! Fluid velocity, acceleration, surface elevation and (with want_pdyn) dynamic pressure
      !! per unit density at xq (axial position s on the rod).
      REAL(wp), INTENT(IN) :: xq(3), s
      REAL(wp), INTENT(OUT) :: uq(3), duq(3), etaq, pdq
      LOGICAL, INTENT(IN) :: want_pdyn
      INTEGER :: es, ih
      REAL(wp) :: tq
      CHARACTER(160) :: em

      uq = CD_ZERO
      duq = CD_ZERO
      etaq = CD_ZERO
      pdq = CD_ZERO
      IF (calm) RETURN
      IF (rod%has_held) THEN
        ! linear interpolation between the host's segment stations (exact at the stations)
        tq = (s + rod%half_length)/lseg
        ih = MIN(nseg - 1, MAX(0, INT(tq)))
        tq = MIN(CD_ONE, MAX(CD_ZERO, tq - REAL(ih, wp)))
        uq = (CD_ONE - tq)*rod%held_vel(:, ih) + tq*rod%held_vel(:, ih + 1)
        duq = (CD_ONE - tq)*rod%held_acc(:, ih) + tq*rod%held_acc(:, ih + 1)
        etaq = (CD_ONE - tq)*rod%held_eta(ih) + tq*rod%held_eta(ih + 1)
        IF (want_pdyn .AND. rod%has_held_pd) pdq = (CD_ONE - tq)*rod%held_pd(ih) + tq*rod%held_pd(ih + 1)
        RETURN
      END IF
      IF (opts%has_wave) THEN
        IF (want_pdyn) THEN
          CALL deck_wave_kinematics(opts, xq(1), xq(2), xq(3), time, etaq, uq, duq, es, em, pdyn=pdq)
        ELSE
          CALL deck_wave_kinematics(opts, xq(1), xq(2), xq(3), time, etaq, uq, duq, es, em)
        END IF
        IF (es /= CD_HYDRO_OK) THEN
          ErrStat = CD_DECKDRV_BADINPUT
          ErrMsg = 'CableDyn_DeckDriver: rod wave kinematics failed: '//TRIM(em)
          RETURN
        END IF
      END IF
      IF (opts%has_current) THEN
        uq = uq + deck_current_velocity(opts, xq(3), es, em)
        IF (es /= CD_HYDRO_OK) THEN
          ErrStat = CD_DECKDRV_BADINPUT
          ErrMsg = 'CableDyn_DeckDriver: rod current profile failed: '//TRIM(em)
          RETURN
        END IF
      END IF
    END SUBROUTINE fluid_at
  END SUBROUTINE rod_environment_force

  SUBROUTINE init_rigid6_states(bodies, points, rigid, ErrStat, ErrMsg, rod_types, rods, allow_no_points)
    !! Build runtime Rigid6 states and collect their Body<N> attachment points. With rod_types and
    !! rods, the rods fixed to a body (RODS type Body<N>, ends in the body frame) become part of it.
    !! allow_no_points: a body may carry no attachment point (decks without lines).
    TYPE(DeckBody), INTENT(IN) :: bodies(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(RigidBodyState), ALLOCATABLE, INTENT(OUT) :: rigid(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(DeckRodType), INTENT(IN), OPTIONAL :: rod_types(:)
    TYPE(DeckRod), INTENT(IN), OPTIONAL :: rods(:)
    LOGICAL, INTENT(IN), OPTIONAL :: allow_no_points

    INTEGER :: i, nrigid, ir, k, na
    LOGICAL :: no_pts
    TYPE(DeckRod), ALLOCATABLE :: att(:)

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    nrigid = 0
    DO i = 1, SIZE(bodies)
      IF (TRIM(bodies(i)%btype) == 'rigid6') nrigid = nrigid + 1
    END DO
    ALLOCATE (rigid(nrigid))
    ir = 0
    DO i = 1, SIZE(bodies)
      IF (TRIM(bodies(i)%btype) /= 'rigid6') CYCLE
      ir = ir + 1
      rigid(ir)%body_id = bodies(i)%id
      rigid(ir)%body_index = i
      rigid(ir)%is_prescribed = bodies(i)%host_coupled
      ! a host-driven body starts at rest in the host's Init pose; its a/alpha are the host's
      rigid(ir)%accel_valid = bodies(i)%host_coupled
      rigid(ir)%r_ref = bodies(i)%pos
      rigid(ir)%r = bodies(i)%pos
      rigid(ir)%rot_ref = CD_Body_Rotation(bodies(i)%rot(1), bodies(i)%rot(2), bodies(i)%rot(3))
      rigid(ir)%rot_mat = rigid(ir)%rot_ref
      IF (bodies(i)%has_eq) THEN
        ! start at the static-equilibrium pose; the restoring reference stays the deck pose
        rigid(ir)%r = bodies(i)%pos_eq
        rigid(ir)%rot_mat = bodies(i)%rot_eq
        rigid(ir)%eta = CD_Log_SO3(MATMUL(rigid(ir)%rot_mat, TRANSPOSE(rigid(ir)%rot_ref)))
      END IF
      rigid(ir)%mass = bodies(i)%mass
      rigid(ir)%vol = bodies(i)%vol
      rigid(ir)%cda = bodies(i)%cda
      rigid(ir)%ca = bodies(i)%ca
      rigid(ir)%inertia = bodies(i)%inertia
      rigid(ir)%c33 = bodies(i)%c33
      rigid(ir)%c44 = bodies(i)%c44
      rigid(ir)%c55 = bodies(i)%c55
      rigid(ir)%cg = bodies(i)%cg
      rigid(ir)%cb = bodies(i)%cg
      rigid(ir)%ext_f = bodies(i)%ext_f
      rigid(ir)%ext_blin = bodies(i)%ext_blin
      rigid(ir)%ext_bquad = bodies(i)%ext_bquad
      CALL collect_body_point_indices(points, bodies(i)%id, rigid(ir)%point_indices)
      no_pts = .FALSE.
      IF (PRESENT(allow_no_points)) no_pts = allow_no_points
      na = 0
      IF (PRESENT(rods) .AND. PRESENT(rod_types)) THEN
        ALLOCATE (att(0))
        DO k = 1, SIZE(rods)
          IF (body_id_of_rod_type(rods(k)%rod_type) /= bodies(i)%id) CYCLE
          att = [att, rods(k)]
        END DO
        na = SIZE(att)
        IF (na > 0) THEN
          ! the rod ends are body-frame coordinates: its state in the body frame, moved with the body
          ALLOCATE (rigid(ir)%att_c(3, na), rigid(ir)%att_rot(3, 3, na))
          DO k = 1, na
            att(k)%rod_type = 'fixed'
          END DO
          CALL init_rod_states(rod_types, att, points, rigid(ir)%att_rods, ErrStat, ErrMsg, no_points=.TRUE.)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
          DO k = 1, na
            rigid(ir)%att_c(:, k) = rigid(ir)%att_rods(k)%r
            rigid(ir)%att_rot(:, :, k) = rigid(ir)%att_rods(k)%rot_mat
          END DO
          CALL sync_attached_rods(rigid(ir))
        END IF
        DEALLOCATE (att)
      END IF
      IF (SIZE(rigid(ir)%point_indices) < 1 .AND. .NOT. no_pts .AND. na == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'Rigid6 BODY requires at least one Body<N> attachment point')
        RETURN
      END IF
    END DO
  END SUBROUTINE init_rigid6_states

  SUBROUTINE sync_attached_rods(body)
    !! Move the rods fixed to a body with its current pose and twist.
    TYPE(RigidBodyState), INTENT(INOUT) :: body
    INTEGER :: k
    REAL(wp) :: arm(3)
    IF (.NOT. ALLOCATED(body%att_rods)) RETURN
    DO k = 1, SIZE(body%att_rods)
      arm = MATMUL(body%rot_mat, body%att_c(:, k))
      body%att_rods(k)%r = body%r + arm
      body%att_rods(k)%rot_mat = MATMUL(body%rot_mat, body%att_rot(:, :, k))
      body%att_rods(k)%v = body%v + cross3(body%omega, arm)
      body%att_rods(k)%omega = body%omega
      body%att_rods(k)%has_held = .FALSE.
    END DO
  END SUBROUTINE sync_attached_rods

  SUBROUTINE rigid6_rod_loads(body, opts, time, force, moment, mass6, drag6, ErrStat, ErrMsg, bathymetry, no_bias)
    !! The rods fixed to a body, lumped into it about its reference point o (global frame): each
    !! rod's weight, hydrostatic and Morison loads (rod_environment_force) and seabed contact at its
    !! centre c, moved to o (F, M + r x F, r = c - o); its structural mass m I and inertia R J R^T
    !! plus its added mass about c, mass6 = T^T M_c T with T = [[I, -[r]x], [0, I]]; the velocity
    !! terms -M_c [w x (w x r); 0] and the gyroscopic -w x (R J R^T w); and the drag and damping
    !! velocity derivative T^T D_c T. Each rod's pose and twist are taken from the body's.
    TYPE(RigidBodyState), INTENT(IN) :: body
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time
    REAL(wp), INTENT(OUT) :: force(3), moment(3), mass6(6, 6), drag6(6, 6)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    ! no_bias: leave out the centripetal and gyroscopic terms (the external loads only)
    LOGICAL, INTENT(IN), OPTIONAL :: no_bias
    INTEGER :: k, j
    REAL(wp) :: f(3), m(3), fc(3), mc(3), a6(6, 6), d6(6, 6), c6(6, 6), mc6(6, 6), t6(6, 6), r(3), jg(3, 3)
    REAL(wp) :: bias(6)
    TYPE(RodState) :: rs

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    force = CD_ZERO
    moment = CD_ZERO
    mass6 = CD_ZERO
    drag6 = CD_ZERO
    IF (.NOT. ALLOCATED(body%att_rods)) RETURN
    DO k = 1, SIZE(body%att_rods)
      rs = body%att_rods(k)
      r = MATMUL(body%rot_mat, body%att_c(:, k))
      rs%r = body%r + r
      rs%rot_mat = MATMUL(body%rot_mat, body%att_rot(:, :, k))
      rs%v = body%v + cross3(body%omega, r)
      rs%omega = body%omega
      rs%has_held = .FALSE.
      CALL rod_environment_force(rs, opts, time, f, m, a6, d6, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL rod_seabed_contact(rs, opts, fc, mc, c6, ErrStat, ErrMsg, bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      f = f + fc + [CD_ZERO, CD_ZERO, -rs%mass*opts%g]
      m = m + mc
      d6 = d6 + c6
      jg = CD_ZERO
      DO j = 1, 3
        jg(j, j) = rs%inertia(j)
      END DO
      jg = MATMUL(rs%rot_mat, MATMUL(jg, TRANSPOSE(rs%rot_mat)))
      mc6 = a6
      DO j = 1, 3
        mc6(j, j) = mc6(j, j) + rs%mass
      END DO
      mc6(4:6, 4:6) = mc6(4:6, 4:6) + jg
      bias = -MATMUL(mc6(:, 1:3), cross3(body%omega, cross3(body%omega, r)))
      bias(4:6) = bias(4:6) - cross3(body%omega, MATMUL(jg, body%omega))
      IF (PRESENT(no_bias)) THEN
        IF (no_bias) bias = CD_ZERO
      END IF
      f = f + bias(1:3)
      m = m + bias(4:6)
      t6 = CD_ZERO
      DO j = 1, 6
        t6(j, j) = CD_ONE
      END DO
      t6(1:3, 4:6) = -skew3(r)
      force = force + f
      moment = moment + m + cross3(r, f)
      mass6 = mass6 + MATMUL(TRANSPOSE(t6), MATMUL(mc6, t6))
      drag6 = drag6 + MATMUL(TRANSPOSE(t6), MATMUL(d6, t6))
    END DO
  END SUBROUTINE rigid6_rod_loads

  SUBROUTINE solve_body_equilibrium_core(types, bodies, rod_types, rods, points, lines, sections, opts, ErrStat, &
                                         ErrMsg, bathymetry, points_only, jac_check_err, ext_pt, ext_fm, &
                                         end_force_a, quiet, skipped, ext_km, ext_rot)
    !! Static equilibrium of the free objects of a deck: free Rigid6 bodies (six DOFs: position
    !! and a rotation-vector increment on SO(3)), free rods (position and the two rotations
    !! normal to the axis; the rod is symmetric about it) and, jointly with them, the
    !! Free/Connect points. With points_only the bodies and rods are held and only the points
    !! move (the point initial condition, solve_point_equilibrium); otherwise the bodies and rods
    !! move (bodyIC static) together with the points, and a deck without free bodies or rods is
    !! left to the point initial condition.
    !!
    !! The residual is the net force and moment of the loads the dynamic step applies at rest:
    !! weight, buoyancy and hydrostatic restoring, steady-current drag (the body loads at zero
    !! velocity without the wave field, through rigid6_environment_force / rod_environment_force),
    !! seabed contact, and the end force of every attached line. Only the lines attached to a
    !! moving object are solved, each to its static equilibrium for the current end positions:
    !! warm-started from its last converged shape (shifted with the end motion) by one Newton
    !! solve of the exact tension-only law, and by the robust cold initializer
    !! (CD_Static_Line_Equilibrium, as solve_one_line) on the first call or when the warm solve
    !! fails. Moments are divided by the object's length scale (largest attachment arm or rod
    !! half length, at least 1 m) and the rotation unknowns multiplied by it, so the forces and
    !! moments are comparable.
    !!
    !! Jacobian: the line terms are analytic. Each line's condensed end stiffness
    !!   K_c = K_ee - K_ei K_ii^-1 K_ie
    !! (its static tangent at the converged shape, element axial and geometric stiffness plus
    !! the seabed penalty, condensed onto the two end nodes) gives d(end force)/d(end position)
    !! = -K_c, mapped to the object unknowns through the attachment arms, plus the moment of
    !! the end force under a rotation of the arm. The objects' own loads (no lines, cheap) are
    !! differentiated by central differences. The line's steady-current drag stiffness is not in
    !! K_c; the residual is exact, so it only slows convergence in a current. A line exactly at
    !! its slack/taut kink has no one-sided stiffness: when the analytic Newton system is
    !! singular or its step fails, the iteration falls back to a central-difference Jacobian of
    !! the full residual (warm-started line solves per column). Newton steps in a trust region
    !! whose radius starts at the first Newton step (capped at a quarter of the shortest moving
    !! line), widens after a well-predicted step on its boundary and shrinks after a rejected
    !! one, with Levenberg-Marquardt steps as the fallback. A trial is accepted when the residual
    !! drops or when the Newton step from it is at most half the current one (a taut line
    !! swinging about its anchor: every straight step overstretches it by its sagitta). Each
    !! step turns an object by at most 0.25 rad, and accepted rotations are folded into the base
    !! orientation (rebase_rotations) so the Jacobian stays exact. Converged when the largest
    !! scaled residual is below 1e-9 of the force scale (largest net weight or line end force)
    !! and the equilibrium is stable (equilibrium_stable). A failed or unstable result is
    !! retried from the deck pose with the rotations held first, then released; the solve fails
    !! closed above 1e-6 or on an unstable equilibrium, with the object named.
    !!
    !! On success a body gets its equilibrium pose in has_eq/pos_eq/rot_eq (pos/rot stay the
    !! restoring reference), a rod its moved ends, and every moved point its position. Only an
    !! object attached to at least one line moves. Rigid6 bodies prescribed by a motionFile stay
    !! put; bodyIC deck keeps every body and rod pose. jac_check_err (a verification hook):
    !! instead of solving, return the largest difference between the analytic and a
    !! central-difference Jacobian at the deck state, relative to the largest FD entry.
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckBody), INTENT(INOUT) :: bodies(:)
    TYPE(DeckRodType), INTENT(IN) :: rod_types(:)
    TYPE(DeckRod), INTENT(INOUT) :: rods(:)
    TYPE(DeckPoint), INTENT(INOUT) :: points(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    LOGICAL, INTENT(IN), OPTIONAL :: points_only
    REAL(wp), INTENT(OUT), OPTIONAL :: jac_check_err
    ! Extra loads (the clamped-end corrections of solve_body_equilibrium): on the object carrying
    ! point ext_pt(e), the force ext_fm(1:3, e) at that point and the moment ext_fm(4:6, e).
    INTEGER, INTENT(IN), OPTIONAL :: ext_pt(:)
    REAL(wp), INTENT(IN), OPTIONAL :: ext_fm(:, :)
    ! ... and a moment stiffness of the extra load (a finite-EI line's condensed torsion): with
    ! the carrying body turned from the orientation ext_rot(:, :, e) by the rotation vector dw
    ! (global axes), the moment ext_fm(4:6, e) becomes ext_fm(4:6, e) - ext_km(:, :, e) dw. The
    ! central-difference own-load Jacobian carries it into the Newton step and the stability test.
    REAL(wp), INTENT(IN), OPTIONAL :: ext_km(:, :, :), ext_rot(:, :, :)
    ! The end force every moving line exerts on its End A point at the solution (zero for a line
    ! that does not move), and quiet: no notes or completion line.
    REAL(wp), INTENT(OUT), OPTIONAL :: end_force_a(:, :)
    LOGICAL, INTENT(IN), OPTIONAL :: quiet
    ! skipped: the objects were held at their deck poses (a moving line has no moving-end
    ! static solve), so nothing was balanced
    LOGICAL, INTENT(OUT), OPTIONAL :: skipped

    TYPE :: LineStaticCache
      !! A moving line's mesh and loads (fixed) and its last converged shape (the warm seed).
      LOGICAL :: ready = .FALSE., has_q = .FALSE.
      INTEGER :: nn = 0
      INTEGER, ALLOCATABLE :: conn(:, :)
      REAL(wp), ALLOCATABLE :: l0(:), ea(:), w(:), f_ext(:), kn(:), q(:), s(:)
      REAL(wp), ALLOCATABLE :: dia(:), cdn(:), cdt(:)
      REAL(wp) :: anchor(3) = CD_ZERO, fairlead(3) = CD_ZERO
      REAL(wp) :: ef(3, 2) = CD_ZERO, kc(6, 6) = CD_ZERO
    END TYPE

    INTEGER, PARAMETER :: OBJ_BODY = 1, OBJ_ROD = 2, OBJ_POINT = 3, OBJ_PIN = 4, MAX_IT = 200
    INTEGER, ALLOCATABLE :: okind(:), idx(:), off(:), ndof(:), ppar(:)
    LOGICAL :: has_pin
    INTEGER :: ibp
    REAL(wp), ALLOCATABLE :: lsc(:), base_r(:, :), base_rot(:, :, :), e1(:, :), e2(:, :)
    REAL(wp), ALLOCATABLE :: x(:), r(:), r_try(:), x_try(:), jac(:, :), a(:, :), g(:), dx(:), dxn(:)
    REAL(wp), ALLOCATABLE :: dxc(:), jtry(:, :), rmask(:), base_rot0(:, :, :), e1_0(:, :), e2_0(:, :)
    INTEGER :: phase, kbad
    LOGICAL :: unstable, silent
    TYPE(LineStaticCache), ALLOCATABLE :: lc(:)
    LOGICAL, ALLOCATABLE :: lmove(:)
    TYPE(DeckOptions) :: opts_calm
    INTEGER :: nobj, n, i, j, k, it, inner, info, worst, jk
    LOGICAL :: ok, only_points
    REAL(wp) :: sc, rnorm, rnorm_try, mu, step_cap, len_min, dmax, trust, pred
    CHARACTER(160) :: lin_msg
    CHARACTER(24) :: b1

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    only_points = .FALSE.
    IF (PRESENT(points_only)) only_points = points_only
    IF (PRESENT(jac_check_err)) jac_check_err = -CD_ONE
    IF (PRESENT(end_force_a)) end_force_a = CD_ZERO
    silent = .FALSE.
    IF (PRESENT(quiet)) silent = quiet
    IF (PRESENT(skipped)) skipped = .FALSE.
    IF (.NOT. (only_points .OR. opts%body_ic_static)) RETURN
    ! the objects that move: free Rigid6 bodies and free rods with a line, then Free/Connect points
    ALLOCATE (okind(SIZE(bodies) + SIZE(rods) + SIZE(points)), idx(SIZE(bodies) + SIZE(rods) + SIZE(points)))
    nobj = 0
    IF (.NOT. only_points) THEN
      IF (.NOT. opts%has_motion_file) THEN
        DO i = 1, SIZE(bodies)
          IF (TRIM(bodies(i)%btype) /= 'rigid6') CYCLE
          IF (bodies(i)%host_coupled) CYCLE
          IF (.NOT. body_has_line(i)) CYCLE
          nobj = nobj + 1
          okind(nobj) = OBJ_BODY
          idx(nobj) = i
        END DO
      END IF
      DO i = 1, SIZE(rods)
        IF (TRIM(rods(i)%rod_type) /= 'free') CYCLE
        k = rod_point_index(points, rods(i)%id, 1)
        j = rod_point_index(points, rods(i)%id, 2)
        ok = point_has_line(k)
        IF (.NOT. ok) ok = point_has_line(j)
        IF (.NOT. ok) CYCLE
        nobj = nobj + 1
        okind(nobj) = OBJ_ROD
        idx(nobj) = i
      END DO
      ! pinned rods (to a fixed pin or to a body) with a line, or on a moving body: two
      ! rotations about the pin; the pin force acts on the parent body
      IF (.NOT. opts%has_motion_file) THEN
        DO i = 1, SIZE(rods)
          ibp = pinned_body_of_rod_type(rods(i)%rod_type)
          IF (TRIM(rods(i)%rod_type) /= 'pinned' .AND. ibp < 1) CYCLE
          k = rod_point_index(points, rods(i)%id, 1)
          j = rod_point_index(points, rods(i)%id, 2)
          ok = point_has_line(k)
          IF (.NOT. ok) ok = point_has_line(j)
          IF (.NOT. ok .AND. ibp > 0) THEN
            ibp = find_body(bodies, ibp)
            IF (ibp > 0) ok = body_has_line(ibp)
          END IF
          IF (.NOT. ok) CYCLE
          nobj = nobj + 1
          okind(nobj) = OBJ_PIN
          idx(nobj) = i
        END DO
      END IF
      IF (nobj == 0) RETURN
    END IF
    DO i = 1, SIZE(points)
      IF (TRIM(points(i)%ptype) /= 'free' .AND. TRIM(points(i)%ptype) /= 'connect') CYCLE
      IF (.NOT. point_has_line(i)) CYCLE
      nobj = nobj + 1
      okind(nobj) = OBJ_POINT
      idx(nobj) = i
    END DO
    IF (nobj == 0) RETURN
    ALLOCATE (lmove(SIZE(lines)), lc(SIZE(lines)))
    DO j = 1, SIZE(lines)
      lmove(j) = line_moves(j)
    END DO
    ! every line attached to a moving object must be a non-Syrope line; a finite-EI line enters
    ! with its axial and weight properties only (its bending changes the end forces of a slender
    ! cable little; the cable's own static shape is solved with its bending stiffness afterwards)
    DO j = 1, SIZE(lines)
      IF (.NOT. lmove(j)) CYCLE
      DO i = 1, SIZE(sections)
        IF (sections(i)%line_id /= lines(j)%id) CYCLE
        k = sections(i)%ltype
        ok = types(k)%is_syrope
        IF (types(k)%ei > CD_ZERO) ok = ok .OR. types(k)%mass <= opts%rhoW*QUARTER_PI*types(k)%diam**2
        IF (ok) THEN
          IF (.NOT. silent) WRITE (output_unit, '(A)') ' WARNING: bodies, rods and points are held at their '// &
            'deck poses in the initial condition: LINE '//TRIM(int_to_str(lines(j)%id))//' (Syrope or buoyant '// &
            'finite-EI) has no moving-end static solve'
          IF (PRESENT(skipped)) skipped = .TRUE.
          RETURN
        END IF
      END DO
    END DO
    DO j = 1, SIZE(lines)
      IF (silent) EXIT
      IF (.NOT. lmove(j)) CYCLE
      IF (.NOT. line_is_finite_ei(lines(j), types, sections)) CYCLE
      WRITE (output_unit, '(A)') '   Note: the body/rod/point static solve treats finite-EI LINE '// &
        TRIM(int_to_str(lines(j)%id))//' as a cable without bending stiffness.'
    END DO

    ALLOCATE (off(nobj), ndof(nobj), lsc(nobj), base_r(3, nobj), base_rot(3, 3, nobj), e1(3, nobj), e2(3, nobj))
    n = 0
    DO k = 1, nobj
      off(k) = n
      lsc(k) = CD_ONE
      base_rot(:, :, k) = CD_ZERO
      e1(:, k) = CD_ZERO
      e2(:, k) = CD_ZERO
      SELECT CASE (okind(k))
      CASE (OBJ_BODY)
        ndof(k) = 6
        base_r(:, k) = bodies(idx(k))%pos
        base_rot(:, :, k) = CD_Body_Rotation(bodies(idx(k))%rot(1), bodies(idx(k))%rot(2), bodies(idx(k))%rot(3))
        DO i = 1, SIZE(points)
          IF (points(i)%body_id == bodies(idx(k))%id .AND. starts_with(TRIM(points(i)%ptype), 'body')) &
            lsc(k) = MAX(lsc(k), NORM2(points(i)%body_offset))
        END DO
      CASE (OBJ_ROD)
        ndof(k) = 5
        base_r(:, k) = 0.5_wp*(rods(idx(k))%end_a + rods(idx(k))%end_b)
        base_rot(:, :, k) = rod_orientation_from_axis(rods(idx(k))%end_b - rods(idx(k))%end_a)
        e1(:, k) = base_rot(:, 2, k)
        e2(:, k) = base_rot(:, 3, k)
        lsc(k) = MAX(CD_ONE, 0.5_wp*NORM2(rods(idx(k))%end_b - rods(idx(k))%end_a))
      CASE (OBJ_PIN)
        ndof(k) = 2
        base_r(:, k) = rods(idx(k))%end_a
        ibp = find_body(bodies, pinned_body_of_rod_type(rods(idx(k))%rod_type))
        IF (ibp > 0) THEN
          ! ends in the body frame: the deck orientation at the body's deck pose
          base_rot(:, :, k) = rod_orientation_from_axis(MATMUL(CD_Body_Rotation(bodies(ibp)%rot(1), &
                                                                                bodies(ibp)%rot(2), &
                                                                                bodies(ibp)%rot(3)), &
                                                               rods(idx(k))%end_b - rods(idx(k))%end_a))
        ELSE
          base_rot(:, :, k) = rod_orientation_from_axis(rods(idx(k))%end_b - rods(idx(k))%end_a)
        END IF
        e1(:, k) = base_rot(:, 2, k)
        e2(:, k) = base_rot(:, 3, k)
        lsc(k) = MAX(CD_ONE, NORM2(rods(idx(k))%end_b - rods(idx(k))%end_a))
      CASE DEFAULT
        ndof(k) = 3
        base_r(:, k) = points(idx(k))%pos
      END SELECT
      n = n + ndof(k)
    END DO
    ! the parent object of each pinned rod (0: a fixed pin or a held body)
    ALLOCATE (ppar(nobj))
    ppar = 0
    has_pin = .FALSE.
    DO k = 1, nobj
      IF (okind(k) /= OBJ_PIN) CYCLE
      has_pin = .TRUE.
      ibp = pinned_body_of_rod_type(rods(idx(k))%rod_type)
      DO j = 1, nobj
        IF (okind(j) == OBJ_BODY) THEN
          IF (bodies(idx(j))%id == ibp) ppar(k) = j
        END IF
      END DO
    END DO
    ! the body loads at rest are the still-water ones (no wave field; current kept)
    opts_calm = opts
    opts_calm%has_wave = .FALSE.
    len_min = HUGE(CD_ONE)
    DO j = 1, SIZE(lines)
      IF (lmove(j)) len_min = MIN(len_min, line_length(lines(j)%id))
    END DO
    IF (len_min > 1.0e30_wp) len_min = CD_ONE
    step_cap = 0.25_wp*len_min
    ALLOCATE (x(n), r(n), r_try(n), x_try(n), jac(n, n), a(n, n), g(n), dx(n), dxn(n), dxc(n), jtry(n, n))
    ALLOCATE (rmask(n))
    rmask = CD_ONE
    x = CD_ZERO
    IF (PRESENT(jac_check_err)) THEN
      CALL jacobian_check(jac_check_err)
      RETURN
    END IF
    base_rot0 = base_rot
    e1_0 = e1
    e2_0 = e2
    ! Phase 1 solves all unknowns from the deck pose. If it fails, or ends on an unstable
    ! equilibrium (a body turned over), phase 2 restarts from the deck pose with the rotations
    ! held (the objects translate to their line force balance) and phase 3 releases them.
    phase = 1
    DO
      CALL residual(x, r, sc, ok, .TRUE.)
      IF (.NOT. ok) RETURN
      rnorm = NORM2(r)
      mu = 1.0e-8_wp
      trust = -CD_ONE
      DO it = 1, MAX_IT
        IF (MAXVAL(ABS(r)) <= 1.0e-9_wp*sc) EXIT
        ! the analytic Jacobian, and a central-difference one of the full residual when the
        ! analytic step fails (a line exactly at its slack/taut kink has no one-sided stiffness;
        ! central differences see both sides)
        DO jk = 1, 2
          IF (jk == 1) THEN
            CALL analytic_jacobian(x, jac, ok)
          ELSE
            CALL fd_jacobian(x, jac, ok)
          END IF
          IF (.NOT. ok) RETURN
          a = MATMUL(TRANSPOSE(jac), jac)
          g = MATMUL(TRANSPOSE(jac), r)
          dmax = MAX(MAXVAL([(a(k, k), k=1, n)]), TINY(CD_ONE))
          ok = .FALSE.
          ! Newton step J dx = -r inside a trust region: the radius starts at the first Newton
          ! step, doubles after a well-predicted step on its boundary and shrinks after a poor or
          ! rejected one (a warm line solve that cannot follow a long trial step counts as rejected)
          dxn = -r
          rnorm_try = rnorm
          CALL CD_Solve_Dense_As_Banded(jac, dxn, info, lin_msg)
          IF (info == CD_LINALG_OK .AND. ALL(IEEE_IS_FINITE(dxn))) THEN
            IF (trust < CD_ZERO) trust = MIN(NORM2(dxn), step_cap)
            DO inner = 1, 8
              dx = dxn
              IF (NORM2(dx) > trust) dx = dx*(trust/NORM2(dx))
              dx = dx*rotation_step_factor(dx)
              ! the residual drop the linearization promises for the (possibly shortened) step
              pred = rnorm*MIN(CD_ONE, NORM2(dx)/MAX(NORM2(dxn), TINY(CD_ONE)))
              x_try = x + dx
              CALL residual(x_try, r_try, sc, ok, .TRUE.)
              IF (ok) THEN
                rnorm_try = NORM2(r_try)
                ok = rnorm_try < rnorm
                ! Natural-level test when the force residual grew: a straight step along a curved
                ! valley (a taut line swinging about its anchor) overstretches the stiff line by
                ! the step's sagitta, and the force residual rejects every step longer than a few
                ! centimetres although the pose is nearer the equilibrium. The Newton step length
                ! measures the distance in displacement units, where the overstretch counts only
                ! as its small length: the step is also accepted when the Newton step from the
                ! trial point (its own analytic Jacobian) is at most half the current one.
                IF (.NOT. ok .AND. jk == 1) THEN
                  CALL analytic_jacobian(x_try, jtry, ok)
                  IF (ok) THEN
                    dxc = -r_try
                    CALL CD_Solve_Dense_As_Banded(jtry, dxc, info, lin_msg)
                    ok = info == CD_LINALG_OK
                    IF (ok) ok = ALL(IEEE_IS_FINITE(dxc))
                    IF (ok) ok = NORM2(dxc) <= 0.5_wp*NORM2(dxn)
                  END IF
                END IF
              END IF
              ErrStat = CD_DECKDRV_OK
              ErrMsg = ''
              IF (ok) THEN
                ! a well-predicted step on the region boundary widens the region
                IF (rnorm - rnorm_try > 0.5_wp*pred .AND. NORM2(dx) >= 0.99_wp*trust) &
                  trust = MIN(2.0_wp*trust, step_cap)
                EXIT
              END IF
              trust = 0.25_wp*MIN(trust, NORM2(dx))
            END DO
          ELSE IF (jk == 1) THEN
            CYCLE
          END IF
          DO inner = 1, 40
            IF (ok) EXIT
            ! Levenberg-Marquardt step (J^T J + mu D) dx = -J^T r, D = diag(J^T J) floored
            jac = a
            DO k = 1, n
              jac(k, k) = a(k, k) + mu*MAX(a(k, k), 1.0e-12_wp*dmax)
            END DO
            dx = -g
            CALL CD_Solve_Dense_As_Banded(jac, dx, info, lin_msg)
            IF (info == CD_LINALG_OK .AND. ALL(IEEE_IS_FINITE(dx))) THEN
              IF (NORM2(dx) > step_cap) dx = dx*(step_cap/NORM2(dx))
              dx = dx*rotation_step_factor(dx)
              x_try = x + dx
              CALL residual(x_try, r_try, sc, ok, .TRUE.)
              IF (ok) THEN
                rnorm_try = NORM2(r_try)
                ok = rnorm_try < rnorm
              END IF
              ErrStat = CD_DECKDRV_OK
              ErrMsg = ''
            END IF
            IF (ok) EXIT
            mu = 8.0_wp*MAX(mu, 1.0e-10_wp)
          END DO
          IF (ok) EXIT
        END DO
        IF (.NOT. ok) EXIT
        mu = MAX(0.25_wp*mu, 1.0e-12_wp)
        x = x_try
        r = r_try
        rnorm = rnorm_try
        CALL rebase_rotations(x)
        ! a rod's moment rows are projected on its (now turned) normal directions
        IF (ANY(okind(1:nobj) == OBJ_ROD)) THEN
          CALL residual(x, r, sc, ok, .TRUE.)
          IF (.NOT. ok) THEN
            ! r no longer matches x: never go on to the stability test on a stale residual
            IF (ErrStat == CD_DECKDRV_OK) CALL fail_solve(ErrStat, ErrMsg, 'static body/rod equilibrium: '// &
                                                          'the residual at an accepted step could not be evaluated')
            RETURN
          END IF
          rnorm = NORM2(r)
        END IF
      END DO
      IF (phase == 2) THEN
        rmask = CD_ONE
        phase = 3
        CYCLE
      END IF
      unstable = .FALSE.
      IF (MAXVAL(ABS(r)) <= 1.0e-6_wp*sc) unstable = .NOT. equilibrium_stable(kbad)
      IF (phase == 1 .AND. (unstable .OR. MAXVAL(ABS(r)) > 1.0e-6_wp*sc) .AND. ANY(ndof(1:nobj) > 3)) THEN
        phase = 2
        x = CD_ZERO
        base_rot = base_rot0
        e1 = e1_0
        e2 = e2_0
        DO k = 1, nobj
          IF (ndof(k) > 3) rmask(off(k) + 4:off(k) + ndof(k)) = CD_ZERO
        END DO
        CYCLE
      END IF
      EXIT
    END DO
    IF (unstable) THEN
      IF (only_points) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'static point equilibrium found is unstable: '// &
                        TRIM(object_name(kbad))//' is not restrained by its lines at the balance point')
      ELSE
        CALL fail_solve(ErrStat, ErrMsg, 'static body/rod equilibrium found is unstable: '// &
                        TRIM(object_name(kbad))//' balances turned over (for example upside down or yawed '// &
                        'against its lines); correct the deck pose or use OPTION bodyIC deck')
      END IF
      RETURN
    END IF
    IF (MAXVAL(ABS(r)) > 1.0e-6_wp*sc) THEN
      worst = 1
      DO k = 1, nobj
        IF (MAXVAL(ABS(r(off(k) + 1:off(k) + ndof(k)))) > MAXVAL(ABS(r(off(worst) + 1:off(worst) + ndof(worst))))) &
          worst = k
      END DO
      WRITE (b1, '(ES10.3)') MAXVAL(ABS(r(off(worst) + 1:off(worst) + ndof(worst))))
      IF (only_points) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'static point equilibrium not found: '//TRIM(object_name(worst))// &
                        ' keeps an unbalanced force of '//TRIM(ADJUSTL(b1))//' N')
      ELSE
        CALL fail_solve(ErrStat, ErrMsg, 'static body/rod equilibrium not found after '// &
                        TRIM(int_to_str(MIN(it, MAX_IT)))// &
                        ' iterations: '//TRIM(object_name(worst))//' keeps an unbalanced force (or moment / '// &
                        'length scale) of '//TRIM(ADJUSTL(b1))//' N (no nearby equilibrium, or one the moorings '// &
                        'do not restrain; OPTION bodyIC deck starts from the deck pose instead)')
      END IF
      RETURN
    END IF
    IF (PRESENT(end_force_a)) THEN
      ! the lines at the solution itself (the last solves may belong to a rejected trial)
      CALL residual(x, r, sc, ok, .TRUE.)
      IF (.NOT. ok) THEN
        IF (ErrStat == CD_DECKDRV_OK) CALL fail_solve(ErrStat, ErrMsg, 'static body/rod equilibrium: the line '// &
                                                      'end forces at the solution could not be evaluated')
        RETURN
      END IF
      DO j = 1, SIZE(lines)
        IF (lmove(j)) end_force_a(:, j) = lc(j)%ef(:, 2)
      END DO
    END IF
    CALL apply_state(x, bodies, rods, points)
    IF (only_points .OR. silent) RETURN
    dmax = CD_ZERO
    DO k = 1, nobj
      IF (ndof(k) >= 3) dmax = MAX(dmax, NORM2(x(off(k) + 1:off(k) + 3)))
    END DO
    WRITE (b1, '(ES10.3)') dmax
    WRITE (output_unit, '(A)') '   Initial conditions: body/rod static equilibrium ('//TRIM(int_to_str(nobj))// &
      ' object(s), largest move '//TRIM(ADJUSTL(b1))//' m) completed.'

  CONTAINS

    LOGICAL FUNCTION point_has_line(ip) RESULT(has)
      INTEGER, INTENT(IN) :: ip
      INTEGER :: jl
      has = .FALSE.
      IF (ip < 1) RETURN
      DO jl = 1, SIZE(lines)
        IF (lines(jl)%nodeA == points(ip)%id .OR. lines(jl)%nodeB == points(ip)%id) has = .TRUE.
      END DO
    END FUNCTION point_has_line

    LOGICAL FUNCTION body_has_line(ib) RESULT(has)
      INTEGER, INTENT(IN) :: ib
      INTEGER :: ip
      INTEGER :: ir
      has = .FALSE.
      DO ip = 1, SIZE(points)
        IF (starts_with(TRIM(points(ip)%ptype), 'body') .AND. points(ip)%body_id == bodies(ib)%id) THEN
          IF (point_has_line(ip)) has = .TRUE.
        END IF
      END DO
      ! a line on a rod pinned to the body loads the body through the pin
      DO ir = 1, SIZE(rods)
        IF (pinned_body_of_rod_type(rods(ir)%rod_type) /= bodies(ib)%id) CYCLE
        IF (point_has_line(rod_point_index(points, rods(ir)%id, 1))) has = .TRUE.
        IF (point_has_line(rod_point_index(points, rods(ir)%id, 2))) has = .TRUE.
      END DO
    END FUNCTION body_has_line

    INTEGER FUNCTION owner(ip) RESULT(ko)
      !! The moving object that carries point ip (0: a held point).
      INTEGER, INTENT(IN) :: ip
      INTEGER :: kk
      ko = 0
      IF (ip < 1) RETURN
      DO kk = 1, nobj
        SELECT CASE (okind(kk))
        CASE (OBJ_BODY)
          IF (starts_with(TRIM(points(ip)%ptype), 'body') .AND. points(ip)%body_id == bodies(idx(kk))%id) ko = kk
        CASE (OBJ_ROD, OBJ_PIN)
          IF (is_rod_point_type(points(ip)%ptype) .AND. points(ip)%body_id == rods(idx(kk))%id) ko = kk
        CASE DEFAULT
          IF (idx(kk) == ip) ko = kk
        END SELECT
        IF (ko > 0) RETURN
      END DO
    END FUNCTION owner

    LOGICAL FUNCTION line_moves(jl) RESULT(mv)
      INTEGER, INTENT(IN) :: jl
      INTEGER :: ia, ib
      ia = find_point(points, lines(jl)%nodeA)
      ib = find_point(points, lines(jl)%nodeB)
      mv = .FALSE.
      IF (ia > 0) mv = owner(ia) > 0
      IF (ib > 0 .AND. .NOT. mv) mv = owner(ib) > 0
    END FUNCTION line_moves

    REAL(wp) FUNCTION line_length(line_id) RESULT(total)
      INTEGER, INTENT(IN) :: line_id
      INTEGER :: js
      total = CD_ZERO
      DO js = 1, SIZE(sections)
        IF (sections(js)%line_id == line_id) total = total + sections(js)%length
      END DO
      IF (total <= CD_ZERO) total = HUGE(CD_ONE)
    END FUNCTION line_length

    CHARACTER(40) FUNCTION object_name(kk) RESULT(nm)
      INTEGER, INTENT(IN) :: kk
      SELECT CASE (okind(kk))
      CASE (OBJ_BODY)
        nm = 'BODY '//TRIM(int_to_str(bodies(idx(kk))%id))
      CASE (OBJ_ROD, OBJ_PIN)
        nm = 'ROD '//TRIM(int_to_str(rods(idx(kk))%id))
      CASE DEFAULT
        nm = 'POINT '//TRIM(int_to_str(points(idx(kk))%id))
      END SELECT
    END FUNCTION object_name

    SUBROUTINE pinned_parent_pose(bd, xb, rb)
      !! Pose of a pinned rod's parent body: its equilibrium iterate, else its deck pose.
      TYPE(DeckBody), INTENT(IN) :: bd
      REAL(wp), INTENT(OUT) :: xb(3), rb(3, 3)
      IF (bd%has_eq) THEN
        xb = bd%pos_eq
        rb = bd%rot_eq
      ELSE
        xb = bd%pos
        rb = CD_Body_Rotation(bd%rot(1), bd%rot(2), bd%rot(3))
      END IF
    END SUBROUTINE pinned_parent_pose

    SUBROUTINE apply_state(xs, bds, rds, pts)
      !! The poses for the unknowns xs: body equilibrium poses, rod ends, and the global
      !! positions of every point carried by a moving object.
      REAL(wp), INTENT(IN) :: xs(:)
      TYPE(DeckBody), INTENT(INOUT) :: bds(:)
      TYPE(DeckRod), INTENT(INOUT) :: rds(:)
      TYPE(DeckPoint), INTENT(INOUT) :: pts(:)
      INTEGER :: kk, ip, o, ia, ib
      REAL(wp) :: rot(3, 3), c(3), u(3), hl, rb(3, 3), xb(3)
      DO kk = 1, nobj
        o = off(kk)
        SELECT CASE (okind(kk))
        CASE (OBJ_BODY)
          rot = MATMUL(CD_Exp_SO3(xs(o + 4:o + 6)/lsc(kk)), base_rot(:, :, kk))
          bds(idx(kk))%has_eq = .TRUE.
          bds(idx(kk))%pos_eq = base_r(:, kk) + xs(o + 1:o + 3)
          bds(idx(kk))%rot_eq = rot
          DO ip = 1, SIZE(pts)
            IF (starts_with(TRIM(pts(ip)%ptype), 'body') .AND. pts(ip)%body_id == bds(idx(kk))%id) &
              pts(ip)%pos = bds(idx(kk))%pos_eq + MATMUL(rot, pts(ip)%body_offset)
          END DO
        CASE (OBJ_ROD)
          c = base_r(:, kk) + xs(o + 1:o + 3)
          rot = CD_Exp_SO3((xs(o + 4)*e1(:, kk) + xs(o + 5)*e2(:, kk))/lsc(kk))
          u = MATMUL(rot, base_rot(:, 1, kk))
          hl = 0.5_wp*NORM2(rods(idx(kk))%end_b - rods(idx(kk))%end_a)
          rds(idx(kk))%end_a = c - hl*u
          rds(idx(kk))%end_b = c + hl*u
          ia = rod_point_index(pts, rds(idx(kk))%id, 1)
          IF (ia > 0) pts(ia)%pos = rds(idx(kk))%end_a
          ia = rod_point_index(pts, rds(idx(kk))%id, 2)
          IF (ia > 0) pts(ia)%pos = rds(idx(kk))%end_b
        CASE (OBJ_PIN)
          rot = MATMUL(CD_Exp_SO3((xs(o + 1)*e1(:, kk) + xs(o + 2)*e2(:, kk))/lsc(kk)), base_rot(:, :, kk))
          u = rot(:, 1)
          hl = NORM2(rods(idx(kk))%end_b - rods(idx(kk))%end_a)
          ib = find_body(bds, pinned_body_of_rod_type(rds(idx(kk))%rod_type))
          IF (ib > 0) THEN
            ! the pin follows the body (already placed: bodies precede rods); the rod's ends
            ! stay in the body frame
            CALL pinned_parent_pose(bds(ib), xb, rb)
            c = xb + MATMUL(rb, rds(idx(kk))%end_a)
            rds(idx(kk))%end_b = rds(idx(kk))%end_a + MATMUL(TRANSPOSE(rb), hl*u)
          ELSE
            c = rds(idx(kk))%end_a
            rds(idx(kk))%end_b = c + hl*u
          END IF
          ia = rod_point_index(pts, rds(idx(kk))%id, 1)
          IF (ia > 0) pts(ia)%pos = c
          ia = rod_point_index(pts, rds(idx(kk))%id, 2)
          IF (ia > 0) pts(ia)%pos = c + hl*u
        CASE DEFAULT
          pts(idx(kk))%pos = base_r(:, kk) + xs(o + 1:o + 3)
        END SELECT
      END DO
    END SUBROUTINE apply_state

    SUBROUTINE own_loads(xs, fk, mk, cen, sc_out, good)
      !! Each moving object's own loads (no lines) at the unknowns xs: force fk and moment mk
      !! about its reference point cen. sc_out is the largest net weight.
      REAL(wp), INTENT(IN) :: xs(:)
      REAL(wp), INTENT(OUT) :: fk(:, :), mk(:, :), cen(:, :), sc_out
      LOGICAL, INTENT(OUT) :: good
      TYPE(DeckBody), ALLOCATABLE :: bds(:)
      TYPE(DeckRod), ALLOCATABLE :: rds(:)
      TYPE(DeckPoint), ALLOCATABLE :: pts(:)
      TYPE(RigidBodyState), ALLOCATABLE :: rig(:)
      TYPE(RodState), ALLOCATABLE :: rst(:)
      REAL(wp) :: f(3), m(3), f2(3), m2(3), w6(6, 6), a6(6, 6), d3(3, 3), meff, u(3), xb(3), rb(3, 3)
      INTEGER :: kk, es_l, ib
      CHARACTER(512) :: em_l
      TYPE(DeckRod) :: rg

      good = .FALSE.
      sc_out = TINY(CD_ONE)**0.25_wp
      fk = CD_ZERO
      mk = CD_ZERO
      bds = bodies
      rds = rods
      pts = points
      CALL apply_state(xs, bds, rds, pts)
      DO kk = 1, nobj
        SELECT CASE (okind(kk))
        CASE (OBJ_BODY)
          CALL init_rigid6_states(bds(idx(kk):idx(kk)), pts, rig, ErrStat, ErrMsg, rod_types, rds, &
                                  allow_no_points=.TRUE.)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
          cen(:, kk) = rig(1)%r
          sc_out = MAX(sc_out, ABS((opts%rhoW*rig(1)%vol - rig(1)%mass)*opts%g))
          CALL rigid6_hydrostatics(rig(1), opts_calm, CD_ZERO, f, m, ErrStat, ErrMsg)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
          CALL rigid6_environment_force(rig(1), opts_calm, CD_ZERO, f2, meff, d3, ErrStat, ErrMsg)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
          f = f + f2
          CALL rigid6_seabed_contact(rig(1), opts, f2, m2, w6, ErrStat, ErrMsg, bathymetry)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
          fk(:, kk) = f + f2
          mk(:, kk) = m + m2
          CALL rigid6_external_load(rig(1), f2, d3)
          fk(:, kk) = fk(:, kk) + f2
          IF (ALLOCATED(rig(1)%att_rods)) THEN
            CALL rigid6_rod_loads(rig(1), opts_calm, CD_ZERO, f2, m2, a6, w6, ErrStat, ErrMsg, bathymetry)
            IF (ErrStat /= CD_DECKDRV_OK) RETURN
            fk(:, kk) = fk(:, kk) + f2
            mk(:, kk) = mk(:, kk) + m2
            DO es_l = 1, SIZE(rig(1)%att_rods)
              sc_out = MAX(sc_out, rig(1)%att_rods(es_l)%mass*opts%g)
            END DO
          END IF
        CASE (OBJ_ROD)
          CALL init_rod_states(rod_types, rds(idx(kk):idx(kk)), pts, rst, ErrStat, ErrMsg)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
          cen(:, kk) = rst(1)%r
          f = [CD_ZERO, CD_ZERO, -rst(1)%mass*opts%g]
          sc_out = MAX(sc_out, ABS(f(3)))
          CALL rod_environment_force(rst(1), opts_calm, CD_ZERO, f2, m2, a6, w6, ErrStat, ErrMsg)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
          fk(:, kk) = f + f2
          mk(:, kk) = m2
          CALL rod_seabed_contact(rst(1), opts, f2, m2, w6, ErrStat, ErrMsg, bathymetry)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
          fk(:, kk) = fk(:, kk) + f2
          mk(:, kk) = mk(:, kk) + m2
        CASE (OBJ_PIN)
          ! the rod in global coordinates; loads and moment about the pin (End A)
          rg = rds(idx(kk))
          ib = find_body(bds, pinned_body_of_rod_type(rg%rod_type))
          IF (ib > 0) THEN
            CALL pinned_parent_pose(bds(ib), xb, rb)
            rg%end_a = xb + MATMUL(rb, rds(idx(kk))%end_a)
            rg%end_b = xb + MATMUL(rb, rds(idx(kk))%end_b)
          END IF
          rg%rod_type = 'free'
          CALL init_rod_states(rod_types, [rg], pts, rst, ErrStat, ErrMsg, no_points=.TRUE.)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
          cen(:, kk) = rg%end_a
          f = [CD_ZERO, CD_ZERO, -rst(1)%mass*opts%g]
          sc_out = MAX(sc_out, ABS(f(3)))
          CALL rod_environment_force(rst(1), opts_calm, CD_ZERO, f2, m2, a6, w6, ErrStat, ErrMsg)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
          fk(:, kk) = f + f2
          mk(:, kk) = m2
          CALL rod_seabed_contact(rst(1), opts, f2, m2, w6, ErrStat, ErrMsg, bathymetry)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
          fk(:, kk) = fk(:, kk) + f2
          mk(:, kk) = mk(:, kk) + m2 + cross3(rst(1)%r - rg%end_a, fk(:, kk))
        CASE DEFAULT
          ! Free/Connect point weight, buoyancy and steady-current drag
          cen(:, kk) = pts(idx(kk))%pos
          fk(3, kk) = (opts%rhoW*pts(idx(kk))%vol - pts(idx(kk))%mass)*opts%g
          sc_out = MAX(sc_out, ABS(fk(3, kk)))
          IF (opts%has_current .AND. pts(idx(kk))%cda > CD_ZERO) THEN
            u = deck_current_velocity(opts, pts(idx(kk))%pos(3), es_l, em_l)
            IF (es_l /= CD_HYDRO_OK) THEN
              CALL fail(ErrStat, ErrMsg, 'static equilibrium: current profile at point '// &
                        TRIM(int_to_str(pts(idx(kk))%id))//': '//TRIM(em_l)); RETURN
            END IF
            fk(:, kk) = fk(:, kk) + 0.5_wp*opts%rhoW*pts(idx(kk))%cda*NORM2(u)*u
          END IF
        END SELECT
      END DO
      ! the extra (clamped-end correction) loads, at their points carried by the objects
      IF (PRESENT(ext_pt) .AND. PRESENT(ext_fm)) THEN
        DO es_l = 1, SIZE(ext_pt)
          kk = owner(ext_pt(es_l))
          IF (kk == 0) CYCLE
          fk(:, kk) = fk(:, kk) + ext_fm(1:3, es_l)
          mk(:, kk) = mk(:, kk) + cross3(pts(ext_pt(es_l))%pos - cen(:, kk), ext_fm(1:3, es_l)) + ext_fm(4:6, es_l)
          IF (PRESENT(ext_km) .AND. PRESENT(ext_rot)) THEN
            IF (okind(kk) == OBJ_BODY) mk(:, kk) = mk(:, kk) - MATMUL(ext_km(:, :, es_l), &
                                                CD_Log_SO3(MATMUL(bds(idx(kk))%rot_eq, TRANSPOSE(ext_rot(:, :, es_l)))))
          END IF
        END DO
      END IF
      good = .TRUE.
    END SUBROUTINE own_loads

    SUBROUTINE assemble_residual(fk, mk, rs)
      !! Stack the per-object force and (scaled, for a rod projected) moment into rs.
      REAL(wp), INTENT(IN) :: fk(:, :), mk(:, :)
      REAL(wp), INTENT(OUT) :: rs(:)
      INTEGER :: kk, o
      rs = CD_ZERO
      DO kk = 1, nobj
        o = off(kk)
        IF (okind(kk) == OBJ_PIN) THEN
          ! a pinned rod: its moment about the pin (the pin force goes to the parent)
          rs(o + 1) = DOT_PRODUCT(mk(:, kk), e1(:, kk))/lsc(kk)
          rs(o + 2) = DOT_PRODUCT(mk(:, kk), e2(:, kk))/lsc(kk)
          CYCLE
        END IF
        rs(o + 1:o + 3) = fk(:, kk)
        SELECT CASE (okind(kk))
        CASE (OBJ_BODY)
          rs(o + 4:o + 6) = mk(:, kk)/lsc(kk)
        CASE (OBJ_ROD)
          rs(o + 4) = DOT_PRODUCT(mk(:, kk), e1(:, kk))/lsc(kk)
          rs(o + 5) = DOT_PRODUCT(mk(:, kk), e2(:, kk))/lsc(kk)
        END SELECT
      END DO
    END SUBROUTINE assemble_residual

    SUBROUTINE residual(xs, rs, sc_out, good, with_lines)
      !! Scaled net force / moment on every moving object at the unknowns xs (own loads plus,
      !! with with_lines, the moving lines solved at the current end positions); sc_out is the
      !! force scale. good = .FALSE. (ErrStat set) when a line or a body load fails.
      REAL(wp), INTENT(IN) :: xs(:)
      REAL(wp), INTENT(OUT) :: rs(:), sc_out
      LOGICAL, INTENT(OUT) :: good
      LOGICAL, INTENT(IN) :: with_lines
      TYPE(DeckBody), ALLOCATABLE :: bds(:)
      TYPE(DeckRod), ALLOCATABLE :: rds(:)
      TYPE(DeckPoint), ALLOCATABLE :: pts(:)
      REAL(wp) :: fk(3, nobj), mk(3, nobj), cen(3, nobj)
      INTEGER :: kk, jl, ie, ip

      CALL own_loads(xs, fk, mk, cen, sc_out, good)
      IF (.NOT. good) RETURN
      IF (with_lines) THEN
        good = .FALSE.
        bds = bodies
        rds = rods
        pts = points
        CALL apply_state(xs, bds, rds, pts)
        DO jl = 1, SIZE(lines)
          IF (.NOT. lmove(jl)) CYCLE
          CALL cached_line_solve(jl, pts, ErrStat, ErrMsg)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
          sc_out = MAX(sc_out, NORM2(lc(jl)%ef(:, 1)), NORM2(lc(jl)%ef(:, 2)))
          ! column 1 acts on End B, column 2 on End A
          DO ie = 1, 2
            ip = line_end_point(jl, ie)
            kk = owner(ip)
            IF (kk == 0) CYCLE
            fk(:, kk) = fk(:, kk) + lc(jl)%ef(:, ie)
            mk(:, kk) = mk(:, kk) + cross3(pts(ip)%pos - cen(:, kk), lc(jl)%ef(:, ie))
          END DO
        END DO
      END IF
      ! a pinned rod's net force acts on its parent body at the pin
      DO kk = 1, nobj
        IF (okind(kk) /= OBJ_PIN) CYCLE
        IF (ppar(kk) == 0) CYCLE
        fk(:, ppar(kk)) = fk(:, ppar(kk)) + fk(:, kk)
        mk(:, ppar(kk)) = mk(:, ppar(kk)) + cross3(cen(:, kk) - cen(:, ppar(kk)), fk(:, kk))
      END DO
      CALL assemble_residual(fk, mk, rs)
      good = ALL(IEEE_IS_FINITE(rs))
      IF (.NOT. good) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'static equilibrium: non-finite load'
      END IF
      ! held unknowns (rmask = 0) carry no residual
      rs = rs*rmask
    END SUBROUTINE residual

    SUBROUTINE mask_jacobian(jm)
      !! A held unknown (rmask = 0) keeps an identity row and column, so its step is zero.
      REAL(wp), INTENT(INOUT) :: jm(:, :)
      INTEGER :: ii
      DO ii = 1, n
        IF (rmask(ii) > CD_ZERO) CYCLE
        jm(ii, :) = CD_ZERO
        jm(:, ii) = CD_ZERO
        jm(ii, ii) = CD_ONE
      END DO
    END SUBROUTINE mask_jacobian

    LOGICAL FUNCTION equilibrium_stable(kb) RESULT(stable)
      !! Whether the converged equilibrium x is statically stable: the symmetric part of the
      !! stiffness -dR/dx (analytic Jacobian, scaled unknowns: a congruence, so definiteness is
      !! kept) must be positive semi-definite, tested by a Cholesky factorization with a small
      !! diagonal shift (a slack line or a neutral mode leaves a zero eigenvalue). kb: the object
      !! owning the first failing pivot. .TRUE. when the Jacobian cannot be formed.
      INTEGER, INTENT(OUT) :: kb
      REAL(wp) :: s(n, n), shift, piv
      INTEGER :: ii, jj, info_c
      LOGICAL :: gd
      stable = .TRUE.
      kb = 1
      CALL analytic_jacobian(x, jtry, gd)
      ErrStat = CD_DECKDRV_OK
      ErrMsg = ''
      IF (.NOT. gd) RETURN
      s = -0.5_wp*(jtry + TRANSPOSE(jtry))
      shift = CD_ZERO
      DO ii = 1, n
        shift = MAX(shift, ABS(s(ii, ii)))
      END DO
      shift = 1.0e-8_wp*MAX(shift, TINY(CD_ONE))
      DO ii = 1, n
        s(ii, ii) = s(ii, ii) + shift
      END DO
      ! in-place lower Cholesky (n is a few unknowns per object); info_c: the first
      ! non-positive pivot, 0 when s is positive definite
      info_c = 0
      DO jj = 1, n
        piv = s(jj, jj) - DOT_PRODUCT(s(jj, 1:jj - 1), s(jj, 1:jj - 1))
        IF (.NOT. (piv > CD_ZERO)) THEN
          info_c = jj
          EXIT
        END IF
        s(jj, jj) = SQRT(piv)
        DO ii = jj + 1, n
          s(ii, jj) = (s(ii, jj) - DOT_PRODUCT(s(ii, 1:jj - 1), s(jj, 1:jj - 1)))/s(jj, jj)
        END DO
      END DO
      stable = info_c <= 0
      IF (stable) RETURN
      DO ii = 1, nobj
        IF (info_c > off(ii) .AND. info_c <= off(ii) + ndof(ii)) kb = ii
      END DO
    END FUNCTION equilibrium_stable

    INTEGER FUNCTION line_end_point(jl, ie) RESULT(ip)
      !! The point index of line jl's End B (ie = 1) or End A (ie = 2).
      INTEGER, INTENT(IN) :: jl, ie
      IF (ie == 1) THEN
        ip = find_point(points, lines(jl)%nodeB)
      ELSE
        ip = find_point(points, lines(jl)%nodeA)
      END IF
    END FUNCTION line_end_point

    SUBROUTINE end_map(kk, arm, pmap)
      !! pmap (3 x ndof(kk)): d(attachment position)/d(object unknowns) for an attachment at
      !! arm from the object's reference point.
      INTEGER, INTENT(IN) :: kk
      REAL(wp), INTENT(IN) :: arm(3)
      REAL(wp), INTENT(OUT) :: pmap(:, :)
      REAL(wp) :: grot(3, 3)
      INTEGER :: nr
      pmap = CD_ZERO
      pmap(1, 1) = CD_ONE
      pmap(2, 2) = CD_ONE
      pmap(3, 3) = CD_ONE
      nr = ndof(kk) - 3
      IF (nr > 0) THEN
        CALL rot_map(kk, grot)
        pmap(:, 4:3 + nr) = -MATMUL(skew3(arm), grot(:, 1:nr))
      END IF
    END SUBROUTINE end_map

    REAL(wp) FUNCTION rotation_step_factor(dxs) RESULT(fac)
      !! The factor (<= 1) that limits every object's rotation in the step dxs to ROT_STEP_MAX
      !! radians, so a step cannot turn a body or rod over onto an unstable equilibrium.
      REAL(wp), INTENT(IN) :: dxs(:)
      REAL(wp), PARAMETER :: ROT_STEP_MAX = 0.25_wp
      REAL(wp) :: ang
      INTEGER :: kk
      fac = CD_ONE
      DO kk = 1, nobj
        IF (okind(kk) == OBJ_PIN) THEN
          ang = NORM2(dxs(off(kk) + 1:off(kk) + 2))/lsc(kk)
          IF (ang > ROT_STEP_MAX) fac = MIN(fac, ROT_STEP_MAX/ang)
          CYCLE
        END IF
        IF (ndof(kk) <= 3) CYCLE
        ang = NORM2(dxs(off(kk) + 4:off(kk) + ndof(kk)))/lsc(kk)
        IF (ang > ROT_STEP_MAX) fac = MIN(fac, ROT_STEP_MAX/ang)
      END DO
    END FUNCTION rotation_step_factor

    SUBROUTINE rebase_rotations(xs)
      !! Fold each object's rotation unknowns into its base orientation and zero them (the pose
      !! is unchanged). rot_map is the derivative of the rotation at zero rotation unknowns, so
      !! the analytic Jacobian stays exact however far the object has turned; a rod's normal
      !! directions e1/e2 turn with it.
      REAL(wp), INTENT(INOUT) :: xs(:)
      INTEGER :: kk, o
      DO kk = 1, nobj
        o = off(kk)
        SELECT CASE (okind(kk))
        CASE (OBJ_BODY)
          base_rot(:, :, kk) = MATMUL(CD_Exp_SO3(xs(o + 4:o + 6)/lsc(kk)), base_rot(:, :, kk))
          xs(o + 4:o + 6) = CD_ZERO
        CASE (OBJ_ROD)
          base_rot(:, :, kk) = MATMUL(CD_Exp_SO3((xs(o + 4)*e1(:, kk) + xs(o + 5)*e2(:, kk))/lsc(kk)), &
                                      base_rot(:, :, kk))
          e1(:, kk) = base_rot(:, 2, kk)
          e2(:, kk) = base_rot(:, 3, kk)
          xs(o + 4:o + 5) = CD_ZERO
        CASE (OBJ_PIN)
          base_rot(:, :, kk) = MATMUL(CD_Exp_SO3((xs(o + 1)*e1(:, kk) + xs(o + 2)*e2(:, kk))/lsc(kk)), &
                                      base_rot(:, :, kk))
          e1(:, kk) = base_rot(:, 2, kk)
          e2(:, kk) = base_rot(:, 3, kk)
          xs(o + 1:o + 2) = CD_ZERO
        CASE DEFAULT
        END SELECT
      END DO
    END SUBROUTINE rebase_rotations

    SUBROUTINE rot_map(kk, grot)
      !! grot(:, 1:nrot): d(rotation vector)/d(rotation unknowns) of object kk at zero rotation
      !! unknowns (rebase_rotations keeps them there at every accepted iterate).
      INTEGER, INTENT(IN) :: kk
      REAL(wp), INTENT(OUT) :: grot(3, 3)
      INTEGER :: ii
      grot = CD_ZERO
      IF (okind(kk) == OBJ_BODY) THEN
        DO ii = 1, 3
          grot(ii, ii) = CD_ONE/lsc(kk)
        END DO
      ELSE IF (okind(kk) == OBJ_ROD) THEN
        grot(:, 1) = e1(:, kk)/lsc(kk)
        grot(:, 2) = e2(:, kk)/lsc(kk)
      END IF
    END SUBROUTINE rot_map

    SUBROUTINE moment_rows(kk, qm)
      !! qm (nrot x 3): the scaled (rod: projected) moment residual rows of object kk.
      INTEGER, INTENT(IN) :: kk
      REAL(wp), INTENT(OUT) :: qm(:, :)
      INTEGER :: ii
      qm = CD_ZERO
      IF (okind(kk) == OBJ_BODY) THEN
        DO ii = 1, 3
          qm(ii, ii) = CD_ONE/lsc(kk)
        END DO
      ELSE IF (okind(kk) == OBJ_ROD) THEN
        qm(1, :) = e1(:, kk)/lsc(kk)
        qm(2, :) = e2(:, kk)/lsc(kk)
      END IF
    END SUBROUTINE moment_rows

    SUBROUTINE analytic_jacobian(xs, jm, good)
      !! Jacobian of the residual at xs: central differences of the objects' own loads plus
      !! the analytic line terms from each moving line's condensed end stiffness (the lines are
      !! solved at xs first, which a warm start makes nearly free).
      REAL(wp), INTENT(IN) :: xs(:)
      REAL(wp), INTENT(OUT) :: jm(:, :)
      LOGICAL, INTENT(OUT) :: good
      TYPE(DeckBody), ALLOCATABLE :: bds(:)
      TYPE(DeckRod), ALLOCATABLE :: rds(:)
      TYPE(DeckPoint), ALLOCATABLE :: pts(:)
      REAL(wp) :: xp(SIZE(xs)), rp(SIZE(xs)), rm(SIZE(xs)), scd, hh
      REAL(wp) :: fk(3, nobj), mk(3, nobj), cen(3, nobj)
      REAL(wp) :: pm(3, 6), dmat(3, 6), qm(3, 3), grot(3, 3), arm(3), blk(3, 3), mom(3, 6)
      INTEGER :: kk, kp, jl, ie, iep, ip, ipp, o, op, nr, nrp, col, me, pe
      LOGICAL :: gd

      good = .FALSE.
      jm = CD_ZERO
      ! a pinned rod couples its parent's unknowns into its attachment motion: the full-residual
      ! central differences serve both
      IF (has_pin) THEN
        CALL fd_jacobian(xs, jm, good)
        RETURN
      END IF
      ! own loads: central differences (no line solves)
      DO col = 1, SIZE(xs)
        hh = 1.0e-6_wp*MAX(CD_ONE, len_min)
        xp = xs
        xp(col) = xs(col) + hh
        CALL residual(xp, rp, scd, gd, .FALSE.)
        IF (.NOT. gd) RETURN
        xp(col) = xs(col) - hh
        CALL residual(xp, rm, scd, gd, .FALSE.)
        IF (.NOT. gd) RETURN
        jm(:, col) = (rp - rm)/(2.0_wp*hh)
      END DO
      ! line terms
      CALL own_loads(xs, fk, mk, cen, scd, gd)
      IF (.NOT. gd) RETURN
      bds = bodies
      rds = rods
      pts = points
      CALL apply_state(xs, bds, rds, pts)
      DO jl = 1, SIZE(lines)
        IF (.NOT. lmove(jl)) CYCLE
        CALL cached_line_solve(jl, pts, ErrStat, ErrMsg, want_k=.TRUE., k_ok=gd)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        IF (.NOT. gd) THEN
          ! the condensed stiffness could not be formed: central differences of the full residual
          CALL fd_jacobian(xs, jm, good)
          RETURN
        END IF
        DO ie = 1, 2
          ip = line_end_point(jl, ie)
          kk = owner(ip)
          IF (kk == 0) CYCLE
          o = off(kk)
          nr = ndof(kk) - 3
          arm = pts(ip)%pos - cen(:, kk)
          IF (nr > 0) CALL moment_rows(kk, qm(1:nr, :))
          DO iep = 1, 2
            ipp = line_end_point(jl, iep)
            kp = owner(ipp)
            IF (kp == 0) CYCLE
            op = off(kp)
            nrp = ndof(kp) - 3
            CALL end_map(kp, pts(ipp)%pos - cen(:, kp), pm(:, 1:ndof(kp)))
            ! d(end force on ie)/d(end position of iep) = -K_c(ie, iep)
            blk = -lc(jl)%kc(3*ie - 2:3*ie, 3*iep - 2:3*iep)
            dmat(:, 1:ndof(kp)) = MATMUL(blk, pm(:, 1:ndof(kp)))
            pe = op + ndof(kp)
            jm(o + 1:o + 3, op + 1:pe) = jm(o + 1:o + 3, op + 1:pe) + dmat(:, 1:ndof(kp))
            IF (nr > 0) THEN
              me = o + 3 + nr
              mom(1:nr, 1:ndof(kp)) = MATMUL(qm(1:nr, :), MATMUL(skew3(arm), dmat(:, 1:ndof(kp))))
              jm(o + 4:me, op + 1:pe) = jm(o + 4:me, op + 1:pe) + mom(1:nr, 1:ndof(kp))
            END IF
          END DO
          ! the end force's moment under a rotation of its own arm: (dtheta x arm) x f
          IF (nr > 0) THEN
            CALL rot_map(kk, grot)
            me = o + 3 + nr
            blk = MATMUL(skew3(lc(jl)%ef(:, ie)), skew3(arm))
            mom(1:nr, 1:nr) = MATMUL(qm(1:nr, :), MATMUL(blk, grot(:, 1:nr)))
            jm(o + 4:me, o + 4:me) = jm(o + 4:me, o + 4:me) + mom(1:nr, 1:nr)
          END IF
        END DO
      END DO
      CALL mask_jacobian(jm)
      good = .TRUE.
    END SUBROUTINE analytic_jacobian

    SUBROUTINE jacobian_check(err)
      !! Largest |J_analytic - J_FD| over the largest |J_FD| at x, J_FD by central differences of
      !! the full residual (each column re-solving the lines).
      REAL(wp), INTENT(OUT) :: err
      REAL(wp) :: jfd(n, n)
      LOGICAL :: gd
      err = -CD_ONE
      CALL residual(x, r, sc, gd, .TRUE.)
      IF (.NOT. gd) RETURN
      CALL analytic_jacobian(x, jac, gd)
      IF (.NOT. gd) RETURN
      CALL fd_jacobian(x, jfd, gd, 1.0e-5_wp)
      IF (.NOT. gd) RETURN
      err = MAXVAL(ABS(jac - jfd))/MAX(MAXVAL(ABS(jfd)), TINY(CD_ONE))
    END SUBROUTINE jacobian_check

    SUBROUTINE fd_jacobian(xs, jm, good, rel_step)
      !! Central-difference Jacobian of the full residual at xs (each column re-solves the
      !! moving lines, warm-started), step rel_step (default 1e-6) times the line length scale.
      REAL(wp), INTENT(IN) :: xs(:)
      REAL(wp), INTENT(OUT) :: jm(:, :)
      LOGICAL, INTENT(OUT) :: good
      REAL(wp), INTENT(IN), OPTIONAL :: rel_step
      REAL(wp) :: xp(SIZE(xs)), rp(SIZE(xs)), rm(SIZE(xs)), scd, hh
      INTEGER :: col
      hh = 1.0e-6_wp
      IF (PRESENT(rel_step)) hh = rel_step
      hh = hh*MAX(CD_ONE, len_min)
      jm = CD_ZERO
      DO col = 1, SIZE(xs)
        xp = xs
        xp(col) = xs(col) + hh
        CALL residual(xp, rp, scd, good, .TRUE.)
        IF (.NOT. good) RETURN
        xp(col) = xs(col) - hh
        CALL residual(xp, rm, scd, good, .TRUE.)
        IF (.NOT. good) RETURN
        jm(:, col) = (rp - rm)/(2.0_wp*hh)
      END DO
      CALL mask_jacobian(jm)
    END SUBROUTINE fd_jacobian

    SUBROUTINE prepare_line(jl, es_out, em_out)
      !! Line jl's mesh, submerged weight, external load, seabed stiffness and per-element
      !! drag coefficients (anchor -> fairlead order), as solve_one_line builds them.
      INTEGER, INTENT(IN) :: jl
      INTEGER, INTENT(OUT) :: es_out
      CHARACTER(*), INTENT(OUT) :: em_out
      TYPE(CD_LineType), ALLOCATABLE :: lts(:)
      TYPE(CD_LineSection), ALLOCATABLE :: secs(:)
      REAL(wp), ALLOCATABLE :: mpl(:), diam(:), load(:, :)
      INTEGER :: js, ii, ns, ne, es_l
      CHARACTER(200) :: em_l

      es_out = CD_DECKDRV_OK
      em_out = ''
      ns = 0
      DO js = 1, SIZE(sections)
        IF (sections(js)%line_id == lines(jl)%id) ns = ns + 1
      END DO
      ALLOCATE (lts(ns), secs(ns))
      ii = 0
      DO js = 1, SIZE(sections)
        IF (sections(js)%line_id /= lines(jl)%id) CYCLE
        ii = ii + 1
        ! a finite-EI line enters the static object solve without its bending stiffness
        lts(ii) = CD_LineType(ea=types(sections(js)%ltype)%ea, mass_per_length=types(sections(js)%ltype)%mass, &
                              diameter=types(sections(js)%ltype)%diam, ei=CD_ZERO)
        secs(ii) = CD_LineSection(line_type=ii, length=sections(js)%length, n_segments=sections(js)%nsegs)
      END DO
      CALL CD_Build_Line_Mesh(secs, lts, .TRUE., lc(jl)%conn, lc(jl)%l0, lc(jl)%ea, mpl, diam, es_l, em_l)
      IF (es_l /= CD_LINE_OK) THEN
        CALL fail(es_out, em_out, 'line mesh: '//TRIM(em_l)); RETURN
      END IF
      ne = SIZE(lc(jl)%l0)
      lc(jl)%nn = ne + 1
      ALLOCATE (lc(jl)%w(ne), load(3, ne), lc(jl)%f_ext(3*(ne + 1)), lc(jl)%s(ne + 1))
      CALL CD_Submerged_Weight(mpl, diam, opts%rhoW, opts%g, lc(jl)%w, es_l, em_l)
      IF (es_l /= 0) THEN
        CALL fail(es_out, em_out, 'submerged weight: '//TRIM(em_l)); RETURN
      END IF
      DO ii = 1, ne
        load(:, ii) = [CD_ZERO, CD_ZERO, -lc(jl)%w(ii)]
      END DO
      CALL CD_Assemble_Distributed_Load(lc(jl)%conn, lc(jl)%l0, load, lc(jl)%f_ext, es_l, em_l)
      IF (es_l /= 0) THEN
        CALL fail(es_out, em_out, 'load assembly: '//TRIM(em_l)); RETURN
      END IF
      ! arc-length fraction of every node (the warm-start shift weights)
      lc(jl)%s(1) = CD_ZERO
      DO ii = 1, ne
        lc(jl)%s(ii + 1) = lc(jl)%s(ii) + lc(jl)%l0(ii)
      END DO
      lc(jl)%s = lc(jl)%s/MAX(lc(jl)%s(ne + 1), TINY(CD_ONE))
      IF (opts%has_current) THEN
        ALLOCATE (lc(jl)%dia(ne), lc(jl)%cdn(ne), lc(jl)%cdt(ne))
        ii = 0
        DO js = 1, SIZE(sections)
          IF (sections(js)%line_id /= lines(jl)%id) CYCLE
          lc(jl)%dia(ii + 1:ii + sections(js)%nsegs) = types(sections(js)%ltype)%diam
          lc(jl)%cdn(ii + 1:ii + sections(js)%nsegs) = types(sections(js)%ltype)%cdn
          lc(jl)%cdt(ii + 1:ii + sections(js)%nsegs) = types(sections(js)%ltype)%cdt
          ii = ii + sections(js)%nsegs
        END DO
        ! file order is End A (fairlead) -> End B; the mesh runs anchor -> fairlead
        lc(jl)%dia = lc(jl)%dia(ne:1:-1)
        lc(jl)%cdn = lc(jl)%cdn(ne:1:-1)
        lc(jl)%cdt = lc(jl)%cdt(ne:1:-1)
      END IF
      IF (PRESENT(bathymetry) .OR. opts%has_wtrdpth) THEN
        CALL CD_Nodal_Seabed_Stiffness(opts%kbot, diam, lc(jl)%l0, lc(jl)%kn, es_l, em_l)
        IF (es_l /= CD_LINE_OK) THEN
          CALL fail(es_out, em_out, 'seabed stiffness: '//TRIM(em_l)); RETURN
        END IF
      END IF
      lc(jl)%ready = .TRUE.
    END SUBROUTINE prepare_line

    SUBROUTINE cached_line_solve(jl, pts, es_out, em_out, want_k, k_ok)
      !! Solve line jl between its end points in pts: a warm start from the last converged
      !! shape (the node positions shifted by the end motion, weighted by arc length) through
      !! one Newton solve of the exact tension-only law, and the robust cold initializer when
      !! there is no shape yet or the warm solve does not converge. Stores the shape, the end
      !! forces lc(jl)%ef (column 1 on End B, 2 on End A) and, with want_k, the condensed end
      !! stiffness lc(jl)%kc; k_ok (optional) is false when that stiffness could not be formed.
      INTEGER, INTENT(IN) :: jl
      TYPE(DeckPoint), INTENT(IN) :: pts(:)
      INTEGER, INTENT(OUT) :: es_out
      CHARACTER(*), INTENT(OUT) :: em_out
      LOGICAL, INTENT(IN), OPTIONAL :: want_k
      LOGICAL, INTENT(OUT), OPTIONAL :: k_ok
      TYPE(CableSolverConfig) :: cfg, cfg_w
      TYPE(CD_StaticLineReport) :: report
      TYPE(CableCurrentLoad), ALLOCATABLE :: curp
      REAL(wp), ALLOCATABLE :: zf, q0(:), q(:), tq(:)
      REAL(wp) :: c_old(3), c_new(3), rot_w(3, 3), sc_w
      REAL(wp) :: anchor(3), fairlead(3), fa(3), fb(3)
      INTEGER :: nn, ii, es_l, nit
      LOGICAL :: conv, stalled, at_floor
      CHARACTER(512) :: em_l

      es_out = CD_DECKDRV_OK
      em_out = ''
      IF (PRESENT(k_ok)) k_ok = .FALSE.
      IF (.NOT. lc(jl)%ready) THEN
        CALL prepare_line(jl, es_out, em_out)
        IF (es_out /= CD_DECKDRV_OK) RETURN
      END IF
      nn = lc(jl)%nn
      anchor = pts(find_point(pts, lines(jl)%nodeB))%pos
      fairlead = pts(find_point(pts, lines(jl)%nodeA))%pos
      IF (opts%has_wtrdpth .AND. .NOT. PRESENT(bathymetry)) THEN
        ALLOCATE (zf)
        zf = -opts%wtrdpth
      END IF
      IF (opts%has_current) THEN
        ALLOCATE (curp)
        curp%rho = opts%rhoW
        curp%waterline_z = CD_ZERO
        ALLOCATE (curp%node_velocity(3, nn))
        DO ii = 1, nn
          curp%node_velocity(:, ii) = deck_current_velocity(opts, line_node_z(anchor, fairlead, lc(jl)%l0, ii), &
                                                            es_l, em_l)
          IF (es_l /= CD_HYDRO_OK) THEN
            CALL fail(es_out, em_out, 'current profile: '//TRIM(em_l)); RETURN
          END IF
        END DO
        curp%elem_diameter = lc(jl)%dia
        curp%elem_cdn = lc(jl)%cdn
        curp%elem_cdt = lc(jl)%cdt
        IF (opts%has_current_profile .AND. ALLOCATED(opts%current_profile_z)) THEN
          curp%profile_z = opts%current_profile_z
          curp%profile_velocity = opts%current_profile_velocity
        END IF
      END IF
      ALLOCATE (q(3*nn))
      conv = .FALSE.
      IF (lc(jl)%has_q) THEN
        ALLOCATE (q0(3*nn))
        ! the last shape moved with its chord: rotated from the old to the new chord direction
        ! about the anchor and scaled by the chord-length ratio, so every element strain changes
        ! by the same small amount (a nodal shift would load a stiff line with a large, uneven
        ! strain error)
        c_old = lc(jl)%fairlead - lc(jl)%anchor
        c_new = fairlead - anchor
        rot_w = chord_rotation(c_old, c_new)
        sc_w = NORM2(c_new)/MAX(NORM2(c_old), TINY(CD_ONE))
        DO ii = 1, nn
          q0(3*ii - 2:3*ii) = anchor + sc_w*MATMUL(rot_w, lc(jl)%q(3*ii - 2:3*ii) - lc(jl)%anchor)
        END DO
        q0(1:3) = anchor
        q0(3*nn - 2:3*nn) = fairlead
        ! (a) plain Newton with the compression-capable law, accepted when no element is
        ! compressed beyond the 1e-6 round-off band (every element taut: it is then the
        ! tension-only equilibrium), as the cold initializer's first stage accepts it
        CALL CD_Static_Cable_Solve(q0, lc(jl)%conn, lc(jl)%l0, lc(jl)%ea, .FALSE., lc(jl)%f_ext, &
                                   [1, 2, 3, 3*nn - 2, 3*nn - 1, 3*nn], cfg, q, conv, stalled, at_floor, nit, &
                                   es_l, em_l, seabed_z_floor=zf, seabed_kn=lc(jl)%kn, current=curp, &
                                   bathymetry=bathymetry)
        IF (es_l /= CD_STATIC_OK) conv = .FALSE.
        IF (conv) conv = ALL(IEEE_IS_FINITE(q))
        IF (conv) THEN
          ALLOCATE (tq(nn - 1))
          CALL CD_Compute_Cable_Tension(RESHAPE(q, [3, nn]), lc(jl)%conn, lc(jl)%l0, lc(jl)%ea, .FALSE., tq, &
                                        es_l, em_l)
          conv = es_l == 0
          IF (conv) conv = MINVAL(tq) >= -1.0e-6_wp*MAX(MAXVAL(ABS(tq)), TINY(CD_ONE))
        END IF
        IF (.NOT. conv) THEN
          ! (b) the exact tension-only law (a slack run), Levenberg-Marquardt, short budget
          cfg_w%max_iter = 10
          CALL CD_Static_Cable_Solve(q0, lc(jl)%conn, lc(jl)%l0, lc(jl)%ea, .TRUE., lc(jl)%f_ext, &
                                     [1, 2, 3, 3*nn - 2, 3*nn - 1, 3*nn], cfg_w, q, conv, stalled, at_floor, nit, &
                                     es_l, em_l, seabed_z_floor=zf, seabed_kn=lc(jl)%kn, current=curp, &
                                     bathymetry=bathymetry, regularized=.TRUE.)
          IF (es_l /= CD_STATIC_OK) conv = .FALSE.
          IF (conv) conv = ALL(IEEE_IS_FINITE(q))
        END IF
      END IF
      IF (.NOT. conv) THEN
        CALL CD_Static_Line_Equilibrium(anchor, fairlead, lc(jl)%conn, lc(jl)%l0, lc(jl)%ea, lc(jl)%w, &
                                        lc(jl)%f_ext, cfg, .TRUE., q, conv, report, es_l, em_l, seabed_z_floor=zf, &
                                        seabed_kn=lc(jl)%kn, bathymetry=bathymetry, current=curp)
        IF (es_l /= CD_STATIC_OK) THEN
          CALL fail(es_out, em_out, 'static equilibrium: line '//TRIM(int_to_str(lines(jl)%id))// &
                    ' static solve rejected the input: '//TRIM(em_l)); RETURN
        END IF
        IF (.NOT. conv) THEN
          es_out = CD_DECKDRV_SOLVEFAIL
          em_out = 'static equilibrium: line '//TRIM(int_to_str(lines(jl)%id))//' static equilibrium not found: '// &
                   TRIM(report%message)
          RETURN
        END IF
      END IF
      CALL CD_Static_Line_End_Forces(q, lc(jl)%conn, lc(jl)%l0, lc(jl)%ea, lc(jl)%f_ext, .TRUE., fa, fb, es_l, &
                                     em_l, seabed_z_floor=zf, seabed_kn=lc(jl)%kn, bathymetry=bathymetry, &
                                     current=curp)
      IF (es_l /= 0 .OR. .NOT. (ALL(IEEE_IS_FINITE(fa)) .AND. ALL(IEEE_IS_FINITE(fb)))) THEN
        CALL fail_solve(es_out, em_out, 'static equilibrium: line '//TRIM(int_to_str(lines(jl)%id))// &
                        ' end-force recovery failed: '//TRIM(em_l)); RETURN
      END IF
      lc(jl)%ef(:, 1) = fa
      lc(jl)%ef(:, 2) = fb
      CALL MOVE_ALLOC(q, lc(jl)%q)
      lc(jl)%has_q = .TRUE.
      lc(jl)%anchor = anchor
      lc(jl)%fairlead = fairlead
      IF (PRESENT(want_k)) THEN
        IF (want_k) THEN
          CALL condensed_end_stiffness(jl, zf, conv)
          IF (PRESENT(k_ok)) k_ok = conv
        END IF
      END IF
    END SUBROUTINE cached_line_solve

    SUBROUTINE condensed_end_stiffness(jl, zf, ok)
      !! lc(jl)%kc: the static tangent of line jl at its stored shape condensed onto its end
      !! nodes, K_c = K_ee - K_ei K_ii^-1 K_ie (end 1 = node 1 = End B, end 2 = the last node =
      !! End A). K is the element axial + geometric stiffness of the exact tension-only law plus
      !! the seabed penalty k_n on the vertical of every node below the floor. ok is false (and
      !! kc is not set) when the banded interior tangent cannot be assembled or factorized.
      INTEGER, INTENT(IN) :: jl
      REAL(wp), ALLOCATABLE, INTENT(IN) :: zf
      LOGICAL, INTENT(OUT) :: ok
      REAL(wp), ALLOCATABLE :: nodes(:, :), kb(:, :), kb_copy(:, :), fint(:), ten(:), kie(:, :), xs(:, :)
      INTEGER, ALLOCATABLE :: free(:), ipiv(:)
      REAL(wp) :: kee(6, 6), blk(3, 3), chord(3), tt(3), ll, tens, dfx, eye(3, 3), bp(3, 3)
      INTEGER :: nn, ne, nf, kl, ku, ldab, ee, na, nb, ii, jj, es_l, info, pair, ni, nj, si, sj
      CHARACTER(200) :: em_l
      EXTERNAL :: dgbsv

      ok = .FALSE.
      nn = lc(jl)%nn
      ne = nn - 1
      nodes = RESHAPE(lc(jl)%q, [3, nn])
      eye = CD_ZERO
      DO ii = 1, 3
        eye(ii, ii) = CD_ONE
      END DO
      kee = CD_ZERO
      nf = MAX(0, 3*(nn - 2))
      ALLOCATE (kie(nf, 6), free(nf))
      kie = CD_ZERO
      free = [(ii, ii=4, 3*nn - 3)]
      DO ee = 1, ne
        na = lc(jl)%conn(1, ee)
        nb = lc(jl)%conn(2, ee)
        IF (end_slot(na, nn) == 0 .AND. end_slot(nb, nn) == 0) CYCLE
        chord = nodes(:, nb) - nodes(:, na)
        ll = NORM2(chord)
        blk = CD_ZERO
        IF (ll > lc(jl)%l0(ee) .AND. ll > CD_ZERO) THEN
          tt = chord/ll
          tens = lc(jl)%ea(ee)*(ll - lc(jl)%l0(ee))/lc(jl)%l0(ee)
          blk = lc(jl)%ea(ee)/lc(jl)%l0(ee)*SPREAD(tt, 2, 3)*SPREAD(tt, 1, 3) + &
                tens/ll*(eye - SPREAD(tt, 2, 3)*SPREAD(tt, 1, 3))
        END IF
        ! the element's (a,a), (b,b), (a,b), (b,a) blocks into the end / interior-end parts
        DO pair = 1, 4
          SELECT CASE (pair)
          CASE (1)
            ni = na; nj = na; bp = blk
          CASE (2)
            ni = nb; nj = nb; bp = blk
          CASE (3)
            ni = na; nj = nb; bp = -blk
          CASE DEFAULT
            ni = nb; nj = na; bp = -blk
          END SELECT
          si = end_slot(ni, nn)
          sj = end_slot(nj, nn)
          IF (si > 0 .AND. sj > 0) THEN
            kee(3*si - 2:3*si, 3*sj - 2:3*sj) = kee(3*si - 2:3*si, 3*sj - 2:3*sj) + bp
          ELSE IF (si == 0 .AND. sj > 0) THEN
            kie(3*(ni - 2) + 1:3*(ni - 2) + 3, 3*sj - 2:3*sj) = kie(3*(ni - 2) + 1:3*(ni - 2) + 3, 3*sj - 2:3*sj) + bp
          END IF
        END DO
      END DO
      ! seabed penalty on the end nodes
      IF (ALLOCATED(lc(jl)%kn)) THEN
        IF (node_on_floor(nodes(:, 1), zf)) kee(3, 3) = kee(3, 3) + lc(jl)%kn(1)
        IF (node_on_floor(nodes(:, nn), zf)) kee(6, 6) = kee(6, 6) + lc(jl)%kn(nn)
      END IF
      IF (nf > 0) THEN
        CALL CD_Cable_Free_Bandwidth(lc(jl)%conn, nn, free, kl, ku, es_l, em_l)
        IF (es_l /= 0) RETURN
        ldab = 2*kl + ku + 1
        ALLOCATE (kb(ldab, nf), fint(3*nn), ten(ne), ipiv(nf))
        CALL CD_Assemble_Cable_Tangent_Force_Banded_Free(nodes, lc(jl)%conn, lc(jl)%l0, lc(jl)%ea, .TRUE., free, &
                                                         kl, ku, kb, fint, ten, es_l, em_l)
        IF (es_l /= 0) RETURN
        IF (ALLOCATED(lc(jl)%kn)) THEN
          DO ii = 2, nn - 1
            IF (node_on_floor(nodes(:, ii), zf)) THEN
              jj = 3*(ii - 2) + 3
              kb(kl + ku + 1, jj) = kb(kl + ku + 1, jj) + lc(jl)%kn(ii)
            END IF
          END DO
        END IF
        kb_copy = kb
        xs = kie
        CALL dgbsv(nf, kl, ku, 6, kb, ldab, ipiv, xs, nf, info)
        IF (info /= 0) THEN
          ! a slack, unsupported run leaves K_ii singular: regularize its diagonal lightly
          dfx = 1.0e-10_wp*MAX(MAXVAL(ABS(kb_copy(kl + ku + 1, :))), TINY(CD_ONE))
          kb = kb_copy
          kb(kl + ku + 1, :) = kb(kl + ku + 1, :) + dfx
          xs = kie
          CALL dgbsv(nf, kl, ku, 6, kb, ldab, ipiv, xs, nf, info)
        END IF
        IF (info /= 0) RETURN
        kee = kee - MATMUL(TRANSPOSE(kie), xs)
      END IF
      IF (.NOT. ALL(IEEE_IS_FINITE(kee))) RETURN
      lc(jl)%kc = kee
      ok = .TRUE.
    END SUBROUTINE condensed_end_stiffness

    PURE FUNCTION chord_rotation(a, b) RESULT(rot)
      !! The rotation taking the direction of a to that of b about their common normal
      !! (the identity for parallel or degenerate chords).
      REAL(wp), INTENT(IN) :: a(3), b(3)
      REAL(wp) :: rot(3, 3), ua(3), ub(3), ax(3), s, c
      INTEGER :: ii
      rot = CD_ZERO
      DO ii = 1, 3
        rot(ii, ii) = CD_ONE
      END DO
      IF (.NOT. (NORM2(a) > CD_ZERO .AND. NORM2(b) > CD_ZERO)) RETURN
      ua = a/NORM2(a)
      ub = b/NORM2(b)
      ax = cross3(ua, ub)
      s = NORM2(ax)
      c = DOT_PRODUCT(ua, ub)
      IF (s <= 1.0e-14_wp .OR. c <= CD_ZERO) RETURN
      ! Rodrigues: R = I + [ax]x + [ax]x^2 (1 - c)/s^2 (ax unnormalized, |ax| = s)
      rot = rot + skew3(ax) + MATMUL(skew3(ax), skew3(ax))*((CD_ONE - c)/(s*s))
    END FUNCTION chord_rotation

    PURE INTEGER FUNCTION end_slot(node, nn) RESULT(sl)
      !! 1 for the first node (End B), 2 for the last node (End A), 0 for an interior node.
      INTEGER, INTENT(IN) :: node, nn
      sl = 0
      IF (node == 1) sl = 1
      IF (node == nn) sl = 2
    END FUNCTION end_slot

    LOGICAL FUNCTION node_on_floor(pos, zf) RESULT(below)
      !! Whether a node is at or below the seabed (bathymetry, or the flat floor zf).
      REAL(wp), INTENT(IN) :: pos(3)
      REAL(wp), ALLOCATABLE, INTENT(IN) :: zf
      REAL(wp) :: zfl
      INTEGER :: es_b
      CHARACTER(160) :: em_b
      below = .FALSE.
      IF (PRESENT(bathymetry)) THEN
        CALL CD_Bathymetry_Floor(bathymetry, pos(1), pos(2), zfl, es_b, em_b)
        IF (es_b /= CD_BATHY_OK) RETURN
      ELSE IF (ALLOCATED(zf)) THEN
        zfl = zf
      ELSE
        RETURN
      END IF
      below = pos(3) <= zfl
    END FUNCTION node_on_floor
  END SUBROUTINE solve_body_equilibrium_core

  SUBROUTINE solve_body_equilibrium(types, bodies, rod_types, rods, points, lines, sections, opts, ErrStat, &
                                    ErrMsg, bathymetry, points_only, jac_check_err)
    !! Static equilibrium of the free objects of a deck (solve_body_equilibrium_core), including
    !! the finite-EI lines whose End A is clamped (Rigid) or elastically connected to a body or a
    !! rod. The core solve carries a finite-EI line as a cable without bending stiffness; for a
    !! connected End A the bending changes the end force and adds the connection moment, which
    !! the object must carry. Each pass solves the core with extra loads on the End A points: the
    !! difference between the cubic-Hermite cable's static end force (bending, the connection
    !! direction turned with the object) and the core's own end force of that line, and the
    !! Hermite connection moment, both evaluated at the previous pass's equilibrium. The passes
    !! repeat from the deck state until these loads change by at most 1e-7 of the force scale
    !! (moments of the force scale times 1 m), so the converged pose balances the Hermite cable
    !! exactly: at the fixed point the core's surrogate end force cancels. A deck without such a
    !! line is the core solve unchanged. A line with condensed torsion also returns its torque,
    !! which depends on the object's rotation as strongly as GJ/L: each pass then also gives the
    !! core the torque's moment stiffness (1/C) a a^T about the previous pass's pose (a = dTheta/dw
    !! of the cable at that pose, its shape held; C the line torsional compliance), so the passes
    !! converge whatever the ratio of the object's own restoring stiffness to GJ/L (the passes
    !! alone would need it far above GJ/L), to 1e-10 of the force scale.
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckBody), INTENT(INOUT) :: bodies(:)
    TYPE(DeckRodType), INTENT(IN) :: rod_types(:)
    TYPE(DeckRod), INTENT(INOUT) :: rods(:)
    TYPE(DeckPoint), INTENT(INOUT) :: points(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    LOGICAL, INTENT(IN), OPTIONAL :: points_only
    REAL(wp), INTENT(OUT), OPTIONAL :: jac_check_err
    INTEGER, PARAMETER :: MAX_PASS = 60
    REAL(wp), PARAMETER :: PASS_TOL = 1.0e-7_wp, PASS_TOL_TORSION = 1.0e-10_wp
    TYPE(DeckBody), ALLOCATABLE :: bodies0(:)
    TYPE(DeckRod), ALLOCATABLE :: rods0(:)
    TYPE(DeckPoint), ALLOCATABLE :: points0(:)
    INTEGER, ALLOCATABLE :: cl(:), ext_pt(:)
    REAL(wp), ALLOCATABLE :: ext_fm(:, :), new_fm(:, :), fs(:, :), ext_km(:, :, :), ext_rot(:, :, :)
    REAL(wp), ALLOCATABLE :: new_km(:, :, :), new_rot(:, :, :)
    INTEGER :: j, pa, e, pass, ncl, eworst
    LOGICAL :: only_points, held
    REAL(wp) :: scale, change, pass_tol_eff
    CHARACTER(24) :: b1

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    only_points = .FALSE.
    IF (PRESENT(points_only)) only_points = points_only
    ! the lines with a connected End A on a Rigid6 body point or a rod end
    ALLOCATE (cl(0))
    IF (.NOT. only_points .AND. .NOT. PRESENT(jac_check_err) .AND. opts%body_ic_static) THEN
      DO j = 1, SIZE(lines)
        IF (lines(j)%endconn_mode(1) == CD_ENDCONN_PINNED .AND. .NOT. line_torsion_active(lines(j))) CYCLE
        IF (.NOT. line_is_finite_ei(lines(j), types, sections)) CYCLE
        pa = find_point(points, lines(j)%nodeA)
        IF (pa < 1) CYCLE
        IF (starts_with(TRIM(points(pa)%ptype), 'body')) THEN
          cl = [cl, j]
        ELSE IF (is_rod_point_type(points(pa)%ptype)) THEN
          cl = [cl, j]
        END IF
      END DO
    END IF
    ncl = SIZE(cl)
    IF (ncl == 0) THEN
      CALL solve_body_equilibrium_core(types, bodies, rod_types, rods, points, lines, sections, opts, ErrStat, &
                                       ErrMsg, bathymetry, points_only, jac_check_err)
      RETURN
    END IF
    ! the connection directions against the deck poses (the passes turn the objects)
    DO e = 1, ncl
      BLOCK
        REAL(wp) :: rclamp(3, 3), dclamp(3)
        CALL clamp_object_frame(lines(cl(e)), points, bodies, rods, rclamp, dclamp, ErrStat, ErrMsg)
      END BLOCK
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END DO
    bodies0 = bodies
    rods0 = rods
    points0 = points
    ALLOCATE (ext_pt(ncl), ext_fm(6, ncl), new_fm(6, ncl), fs(3, SIZE(lines)))
    ALLOCATE (ext_km(3, 3, ncl), ext_rot(3, 3, ncl), new_km(3, 3, ncl), new_rot(3, 3, ncl))
    pass_tol_eff = PASS_TOL
    DO e = 1, ncl
      ext_pt(e) = find_point(points, lines(cl(e))%nodeA)
      IF (line_torsion_active(lines(cl(e)))) pass_tol_eff = PASS_TOL_TORSION
    END DO
    ext_fm = CD_ZERO
    ext_km = CD_ZERO
    ext_rot = CD_ZERO
    DO e = 1, ncl
      ext_rot(1, 1, e) = CD_ONE
      ext_rot(2, 2, e) = CD_ONE
      ext_rot(3, 3, e) = CD_ONE
    END DO
    DO pass = 1, MAX_PASS
      bodies = bodies0
      rods = rods0
      points = points0
      CALL solve_body_equilibrium_core(types, bodies, rod_types, rods, points, lines, sections, opts, ErrStat, &
                                       ErrMsg, bathymetry, ext_pt=ext_pt, ext_fm=ext_fm, end_force_a=fs, &
                                       quiet=pass > 1, skipped=held, ext_km=ext_km, ext_rot=ext_rot)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      ! the objects stay at their deck poses (the core has already said why): nothing to balance
      IF (held) RETURN
      scale = CD_ONE
      DO e = 1, ncl
        CALL hermite_end_loads(cl(e), new_fm(:, e), new_km(:, :, e), new_rot(:, :, e))
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        new_fm(1:3, e) = new_fm(1:3, e) - fs(:, cl(e))
        scale = MAX(scale, NORM2(fs(:, cl(e))), NORM2(new_fm(1:3, e) + fs(:, cl(e))))
      END DO
      change = MAXVAL(ABS(new_fm - ext_fm))
      eworst = MAXLOC(MAXVAL(ABS(new_fm - ext_fm), DIM=1), DIM=1)
      ext_fm = new_fm
      ext_km = new_km
      ext_rot = new_rot
      IF (change <= pass_tol_eff*scale) EXIT
    END DO
    IF (change > pass_tol_eff*scale) THEN
      WRITE (b1, '(ES10.3)') change/scale
      CALL fail_solve(ErrStat, ErrMsg, 'static body/rod equilibrium with the clamped or elastic END CONNECTION '// &
                      'of finite-EI LINE '//TRIM(int_to_str(lines(cl(eworst))%id))//' did not converge after '// &
                      TRIM(int_to_str(MAX_PASS))//' passes (relative end-load change '//TRIM(ADJUSTL(b1))// &
                      '); OPTION bodyIC deck starts from the deck pose instead')
      RETURN
    END IF
    WRITE (output_unit, '(A)') '   Initial conditions: the end moments and bending end forces of '// &
      TRIM(int_to_str(ncl))//' clamped or elastic finite-EI line end(s) balanced in '// &
      TRIM(int_to_str(pass))//' static pass(es).'

  CONTAINS

    SUBROUTINE hermite_end_loads(jl, fm, km, rot)
      !! The cubic-Hermite static end force and connection moment of line jl on its End A object,
      !! at the current (solved) object poses and point positions; for a line with condensed
      !! torsion, km = (1/C) a a^T, the torque's moment stiffness against a rotation of the object
      !! with the cable shape held (a = dTheta/dw: the End A frame turns, and a clamped end's
      !! tangent with it), in global axes, and rot the object's orientation (km = 0 otherwise).
      INTEGER, INTENT(IN) :: jl
      REAL(wp), INTENT(OUT) :: fm(6), km(3, 3), rot(3, 3)
      TYPE(CD_HFMF_ModuleType) :: cab
      TYPE(DeckLine) :: lnc
      TYPE(DeckPoint), ALLOCATABLE :: pc(:)
      REAL(wp) :: rclamp(3, 3), dclamp(3), dtb
      INTEGER :: node, es
      CHARACTER(512) :: note
      CHARACTER(300) :: em
      fm = CD_ZERO
      km = CD_ZERO
      lnc = lines(jl)
      CALL clamp_object_frame(lnc, points, bodies, rods, rclamp, dclamp, ErrStat, ErrMsg, check_axis=.FALSE.)
      rot = rclamp
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      lnc%endconn_ez_ref(:, 1) = dclamp
      pc = points
      pc(find_point(points, lnc%nodeA))%ptype = 'coupled'
      dtb = CD_ONE
      IF (opts%dtM > CD_ZERO) dtb = opts%dtM
      CALL build_one_hermite_cable(lnc, sections, types, pc, opts, dtb, cab, node, ErrStat, ErrMsg, &
                                   standalone_controls=.TRUE., bathymetry=bathymetry, &
                                   fairlead_orientation=TRANSPOSE(rclamp), init_note=note)
      IF (ErrStat == CD_DECKDRV_OK) THEN
        CALL CD_HFMF_CalcOutput(cab, fm(1:3), es, em, y_moment=fm(4:6))
        IF (es /= CD_HFMF_OK) CALL fail_solve(ErrStat, ErrMsg, 'finite-EI LINE '//TRIM(int_to_str(lnc%id))// &
                                              ' static end loads failed: '//TRIM(em))
      END IF
      IF (ErrStat == CD_DECKDRV_OK .AND. cab%line%torsion%active) THEN
        BLOCK
          REAL(wp) :: th, mt, eg(6), a(3), ag(3), cc
          REAL(wp), ALLOCATABLE :: gq(:)
          INTEGER :: nb
          ALLOCATE (gq(cab%line%ndof))
          CALL CD_HermiteCable_Dyn_Torsion_State(cab%line, th, mt, es, em, gq, eg)
          IF (es == CD_HCDYN_OK) THEN
            ! End A is the cable's last node (internal end 2)
            a = eg(4:6)
            IF (cab%line%endconn_mode(2) == CD_ENDCONN_RIGID) THEN
              nb = cab%line%ndof - 3
              a = a + cross3(cab%line%q(nb + 1:nb + 3), gq(nb + 1:nb + 3))
            END IF
            ag = [cab%frame_c*a(1) - cab%frame_s*a(2), cab%frame_s*a(1) + cab%frame_c*a(2), a(3)]
            cc = CD_HermiteTorsion_Compliance(cab%line%torsion, cab%line%l0)
            km = SPREAD(ag, 2, 3)*SPREAD(ag, 1, 3)/cc
          END IF
        END BLOCK
      END IF
      CALL CD_HFMF_End(cab)
    END SUBROUTINE hermite_end_loads
  END SUBROUTINE solve_body_equilibrium

  SUBROUTINE CD_Init_Deck_Aggregate_Rigid6(bodies, points, opts, rt, ErrStat, ErrMsg, ptfm_init)
    !! Populate the opaque Rigid6 runtime for the coupled aggregate: build the body states and
    !! retain the deck options + points the per-step marcher needs (the aggregate keeps neither).
    !! Coupled/Vessel bodies become host nodes (one per body, in deck BODY order) at their
    !! reference point; ptfm_init (the host's initial platform displacement) moves them rigidly
    !! with the platform (reference pose included), and the body frame in platform axes, O0 R,
    !! then follows the host orientation.
    TYPE(DeckBody), INTENT(IN) :: bodies(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(CD_Rigid6RuntimeType), INTENT(OUT) :: rt
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp), INTENT(IN), OPTIONAL :: ptfm_init(6)
    INTEGER :: ib, k, nh
    REAL(wp) :: mt(3, 3)

    CALL init_rigid6_states(bodies, points, rt%rigid, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    rt%opts = opts
    rt%points = points
    rt%host_o0 = CD_ZERO
    rt%host_o0(1, 1) = CD_ONE
    rt%host_o0(2, 2) = CD_ONE
    rt%host_o0(3, 3) = CD_ONE
    IF (PRESENT(ptfm_init)) rt%host_o0 = ptfm_zyx_dcm(ptfm_init(4:6))
    mt = TRANSPOSE(rt%host_o0)
    nh = COUNT(rt%rigid%is_prescribed)
    ALLOCATE (rt%host_body(nh), rt%host_rrel(3, 3, nh))
    k = 0
    DO ib = 1, SIZE(rt%rigid)
      IF (.NOT. rt%rigid(ib)%is_prescribed) CYCLE
      k = k + 1
      rt%host_body(k) = ib
      IF (PRESENT(ptfm_init)) THEN
        rt%rigid(ib)%r_ref = ptfm_init(1:3) + MATMUL(mt, rt%rigid(ib)%r_ref)
        rt%rigid(ib)%r = rt%rigid(ib)%r_ref
        rt%rigid(ib)%rot_ref = MATMUL(mt, rt%rigid(ib)%rot_ref)
        rt%rigid(ib)%rot_mat = rt%rigid(ib)%rot_ref
        rt%rigid(ib)%eta = CD_ZERO
      END IF
      rt%host_rrel(:, :, k) = MATMUL(rt%host_o0, rt%rigid(ib)%rot_mat)
    END DO
    rt%snap_rigid = rt%rigid
    rt%stage_rigid = rt%rigid
  END SUBROUTINE CD_Init_Deck_Aggregate_Rigid6

  PURE INTEGER FUNCTION CD_Rigid6_NHost(rt) RESULT(n)
    !! Number of host-driven (Coupled/Vessel) bodies, i.e. the body host nodes (0 if unpopulated).
    TYPE(CD_Rigid6RuntimeType), INTENT(IN) :: rt
    n = 0
    IF (ALLOCATED(rt%host_body)) n = SIZE(rt%host_body)
  END FUNCTION CD_Rigid6_NHost

  PURE LOGICAL FUNCTION CD_Rigid6_AllHost(rt) RESULT(all_host)
    !! Whether every body of the runtime is host-driven (no body is integrated).
    TYPE(CD_Rigid6RuntimeType), INTENT(IN) :: rt
    all_host = CD_Rigid6_NBodies(rt) > 0 .AND. CD_Rigid6_NHost(rt) == CD_Rigid6_NBodies(rt)
  END FUNCTION CD_Rigid6_AllHost

  SUBROUTINE CD_Rigid6_SetHostKinematics(rt, position, velocity, acceleration, ErrStat, ErrMsg, orientation, &
                                         angular_velocity, angular_acceleration)
    !! Impose the host node kinematics (reference-point position/velocity/acceleration, the host
    !! orientation and angular rates, all global; arrays shaped (3[,3], NHost)) on every
    !! Coupled/Vessel body: R = O^T (O0 R0). Without an orientation the Init orientation is held;
    !! without angular rates they are zero. Validates every shape before any change.
    TYPE(CD_Rigid6RuntimeType), INTENT(INOUT) :: rt
    REAL(wp), INTENT(IN) :: position(:, :), velocity(:, :), acceleration(:, :)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp), INTENT(IN), OPTIONAL :: orientation(:, :, :)
    REAL(wp), INTENT(IN), OPTIONAL :: angular_velocity(:, :), angular_acceleration(:, :)
    INTEGER :: k, ib, nh
    REAL(wp) :: o(3, 3)

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    nh = CD_Rigid6_NHost(rt)
    IF (nh == 0) RETURN
    IF (SIZE(position, 1) /= 3 .OR. SIZE(position, 2) /= nh .OR. SIZE(velocity, 1) /= 3 .OR. &
        SIZE(velocity, 2) /= nh .OR. SIZE(acceleration, 1) /= 3 .OR. SIZE(acceleration, 2) /= nh) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Rigid6_SetHostKinematics: arrays must be shaped (3, NHost)'); RETURN
    END IF
    IF (PRESENT(orientation)) THEN
      IF (SIZE(orientation, 1) /= 3 .OR. SIZE(orientation, 2) /= 3 .OR. SIZE(orientation, 3) /= nh) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Rigid6_SetHostKinematics: orientation must be shaped (3, 3, NHost)')
        RETURN
      END IF
    END IF
    IF (PRESENT(angular_velocity) .NEQV. PRESENT(angular_acceleration)) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Rigid6_SetHostKinematics: angular rates must be supplied together'); RETURN
    END IF
    IF (PRESENT(angular_velocity)) THEN
      IF (SIZE(angular_velocity, 1) /= 3 .OR. SIZE(angular_velocity, 2) /= nh .OR. &
          SIZE(angular_acceleration, 1) /= 3 .OR. SIZE(angular_acceleration, 2) /= nh) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Rigid6_SetHostKinematics: angular rates must be shaped (3, NHost)'); RETURN
      END IF
    END IF
    DO k = 1, nh
      ib = rt%host_body(k)
      o = rt%host_o0
      IF (PRESENT(orientation)) o = orientation(:, :, k)
      rt%rigid(ib)%rot_mat = MATMUL(TRANSPOSE(o), rt%host_rrel(:, :, k))
      rt%rigid(ib)%eta = CD_Log_SO3(MATMUL(rt%rigid(ib)%rot_mat, TRANSPOSE(rt%rigid(ib)%rot_ref)))
      rt%rigid(ib)%r = position(:, k)
      rt%rigid(ib)%v = velocity(:, k)
      rt%rigid(ib)%a = acceleration(:, k)
      rt%rigid(ib)%omega = CD_ZERO
      rt%rigid(ib)%alpha = CD_ZERO
      IF (PRESENT(angular_velocity)) THEN
        rt%rigid(ib)%omega = angular_velocity(:, k)
        rt%rigid(ib)%alpha = angular_acceleration(:, k)
      END IF
      rt%rigid(ib)%accel_valid = .TRUE.
    END DO
  END SUBROUTINE CD_Rigid6_SetHostKinematics

  SUBROUTINE CD_Rigid6_GetHostKinematics(rt, k, position, velocity, acceleration, orientation, angular_velocity, &
                                         angular_acceleration)
    !! The committed kinematics of host node k (the k-th Coupled/Vessel body's reference point)
    !! and the host orientation O = (O0 R0) R^T it implies.
    TYPE(CD_Rigid6RuntimeType), INTENT(IN) :: rt
    INTEGER, INTENT(IN) :: k
    REAL(wp), INTENT(OUT) :: position(3), velocity(3), acceleration(3), orientation(3, 3)
    REAL(wp), INTENT(OUT) :: angular_velocity(3), angular_acceleration(3)
    INTEGER :: ib

    ! an out-of-range k returns rest at the origin with the identity orientation (the
    ! *_HostWrench siblings fail closed on it)
    position = CD_ZERO
    velocity = CD_ZERO
    acceleration = CD_ZERO
    orientation = CD_ZERO
    orientation(1, 1) = CD_ONE
    orientation(2, 2) = CD_ONE
    orientation(3, 3) = CD_ONE
    angular_velocity = CD_ZERO
    angular_acceleration = CD_ZERO
    IF (.NOT. ALLOCATED(rt%host_body)) RETURN
    IF (k < 1 .OR. k > SIZE(rt%host_body)) RETURN
    ib = rt%host_body(k)
    position = rt%rigid(ib)%r
    velocity = rt%rigid(ib)%v
    acceleration = rt%rigid(ib)%a
    orientation = MATMUL(rt%host_rrel(:, :, k), TRANSPOSE(rt%rigid(ib)%rot_mat))
    angular_velocity = rt%rigid(ib)%omega
    angular_acceleration = rt%rigid(ib)%alpha
  END SUBROUTINE CD_Rigid6_GetHostKinematics

  SUBROUTINE CD_Rigid6_ScatterHostPoints(system, rt, q, v, a)
    !! Write the Body<N> attachment-point kinematics of every Coupled/Vessel body into the full
    !! coupled-block arrays (3, n_system_coupled_dof/3); every other block is left untouched.
    TYPE(CD_SystemType), INTENT(IN) :: system
    TYPE(CD_Rigid6RuntimeType), INTENT(IN) :: rt
    REAL(wp), INTENT(INOUT) :: q(:, :), v(:, :), a(:, :)
    INTEGER :: k, ib, ip, pidx, base
    REAL(wp) :: arm(3)

    DO k = 1, CD_Rigid6_NHost(rt)
      ib = rt%host_body(k)
      DO ip = 1, SIZE(rt%rigid(ib)%point_indices)
        pidx = rt%rigid(ib)%point_indices(ip)
        base = system_point_base(system, rt%points(pidx)%id)
        IF (base < 0 .OR. base/3 + 1 > SIZE(q, 2)) CYCLE
        arm = MATMUL(rt%rigid(ib)%rot_mat, rt%points(pidx)%body_offset)
        q(:, base/3 + 1) = rt%rigid(ib)%r + arm
        v(:, base/3 + 1) = rt%rigid(ib)%v + cross3(rt%rigid(ib)%omega, arm)
        a(:, base/3 + 1) = rt%rigid(ib)%a + cross3(rt%rigid(ib)%alpha, arm) + &
                           cross3(rt%rigid(ib)%omega, cross3(rt%rigid(ib)%omega, arm))
      END DO
    END DO
  END SUBROUTINE CD_Rigid6_ScatterHostPoints

  SUBROUTINE CD_Rigid6_HostWrench(system, rt, loads, k, force, moment, ErrStat, ErrMsg)
    !! The load the k-th Coupled/Vessel body returns to its host node (MoorDyn-F's coupled body
    !! net force with its inertial part), about the body reference point: the attached line loads
    !! at its Body<N> points (loads: the system's coupled-point loads shaped
    !! (3, n_system_coupled_dof/3), which already carry the line-end inertia), weight at the CG,
    !! buoyancy and waterplane restoring, the Morison/Froude-Krylov force of the held host fluid,
    !! seabed contact and external loads -- the loads rigid6_body_acceleration integrates for a
    !! free body -- minus the rigid-body and added-mass inertia M a (CG offset, velocity and
    !! gyroscopic terms included) at the host-prescribed acceleration.
    TYPE(CD_SystemType), INTENT(IN) :: system
    TYPE(CD_Rigid6RuntimeType), INTENT(IN) :: rt
    REAL(wp), INTENT(IN) :: loads(:, :)
    INTEGER, INTENT(IN) :: k
    REAL(wp), INTENT(OUT) :: force(3), moment(3)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: ib, ip, pidx, base, j
    REAL(wp) :: f_env(3), mass_eff, drag3(3, 3), f_h(3), m_h(3), cg6(6, 6), f_bias(3), m_bias(3)
    REAL(wp) :: f_sb(3), m_sb(3), load_dv(6, 6), f_ext(3), arm(3), ig(3, 3), m6(6, 6), acc6(6), w6(6)

    force = CD_ZERO
    moment = CD_ZERO
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (k < 1 .OR. k > CD_Rigid6_NHost(rt)) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Rigid6_HostWrench: host node index out of range'); RETURN
    END IF
    ib = rt%host_body(k)
    CALL rigid6_environment_force(rt%rigid(ib), rt%opts, CD_ZERO, f_env, mass_eff, drag3, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL rigid6_hydrostatics(rt%rigid(ib), rt%opts, CD_ZERO, f_h, m_h, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL rigid6_cg_inertia(rt%rigid(ib), cg6, f_bias, m_bias)
    CALL rigid6_seabed_contact(rt%rigid(ib), rt%opts, f_sb, m_sb, load_dv, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL rigid6_external_load(rt%rigid(ib), f_ext, drag3)
    w6(1:3) = f_h + f_bias + f_env + f_sb + f_ext
    w6(4:6) = m_h + m_bias + m_sb
    DO ip = 1, SIZE(rt%rigid(ib)%point_indices)
      pidx = rt%rigid(ib)%point_indices(ip)
      base = system_point_base(system, rt%points(pidx)%id)
      IF (base < 0) CYCLE
      IF (base/3 + 1 > SIZE(loads, 2)) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Rigid6_HostWrench: load array does not cover the body points'); RETURN
      END IF
      arm = MATMUL(rt%rigid(ib)%rot_mat, rt%points(pidx)%body_offset)
      w6(1:3) = w6(1:3) + loads(:, base/3 + 1)
      w6(4:6) = w6(4:6) + cross3(arm, loads(:, base/3 + 1))
    END DO
    ig = CD_ZERO
    DO j = 1, 3
      ig(j, j) = rt%rigid(ib)%inertia(j)
    END DO
    ig = MATMUL(rt%rigid(ib)%rot_mat, MATMUL(ig, TRANSPOSE(rt%rigid(ib)%rot_mat)))
    m6 = cg6
    DO j = 1, 3
      m6(j, j) = m6(j, j) + mass_eff
    END DO
    m6(4:6, 4:6) = m6(4:6, 4:6) + ig
    w6(4:6) = w6(4:6) - cross3(rt%rigid(ib)%omega, MATMUL(ig, rt%rigid(ib)%omega))
    acc6(1:3) = rt%rigid(ib)%a
    acc6(4:6) = rt%rigid(ib)%alpha
    w6 = w6 - MATMUL(m6, acc6)
    force = w6(1:3)
    moment = w6(4:6)
  END SUBROUTINE CD_Rigid6_HostWrench

  SUBROUTINE CD_Rigid6_Stage(rt)
    !! Save the step-start bodies before a host transfer (restored by CD_Rigid6_Unstage).
    TYPE(CD_Rigid6RuntimeType), INTENT(INOUT) :: rt
    IF (ALLOCATED(rt%rigid)) rt%stage_rigid = rt%rigid
  END SUBROUTINE CD_Rigid6_Stage

  SUBROUTINE CD_Rigid6_Unstage(rt)
    !! Undo the host transfer of a failed staged step (see CD_Rigid6_Stage).
    TYPE(CD_Rigid6RuntimeType), INTENT(INOUT) :: rt
    IF (ALLOCATED(rt%stage_rigid)) rt%rigid = rt%stage_rigid
  END SUBROUTINE CD_Rigid6_Unstage

  SUBROUTINE CD_Step_Aggregate_Rigid6(system, rt, time, dt, converged, stalled, n_iter, ErrStat, ErrMsg, host_mask, &
                                      host_q, host_v, host_a, interp_hosts)
    !! Advance the aggregate's Rigid6 bodies one mooring step over its EI=0 system (flat seabed;
    !! body fluid loads come from the host-held field (CD_Rigid6_SetHeldFluid) when set,
    !! otherwise still water).
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    TYPE(CD_Rigid6RuntimeType), INTENT(INOUT) :: rt
    REAL(wp), INTENT(IN) :: time, dt
    LOGICAL, INTENT(OUT) :: converged, stalled
    INTEGER, INTENT(OUT) :: n_iter, ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    ! host_mask/host_q/host_v/host_a: the host's moving coupled DOFs at t + dt (step_rigid6_system)
    LOGICAL, INTENT(IN), OPTIONAL :: host_mask(:)
    REAL(wp), INTENT(IN), OPTIONAL :: host_q(:), host_v(:), host_a(:)
    ! interp_hosts: the host-driven bodies were staged this step (CD_Rigid6_Stage) and hold their
    ! t + dt pose; sub-steps take their motion interpolated from the staged step start
    LOGICAL, INTENT(IN), OPTIONAL :: interp_hosts
    LOGICAL :: interp

    interp = .FALSE.
    IF (PRESENT(interp_hosts)) interp = interp_hosts .AND. ALLOCATED(rt%stage_rigid)
    IF (interp) THEN
      CALL step_rigid6_system(system, rt%points, rt%opts, rt%rigid, time, dt, converged, stalled, &
                              n_iter, ErrStat, ErrMsg, rt%work, host_mask=host_mask, host_q=host_q, host_v=host_v, &
                              host_a=host_a, host_start=rt%stage_rigid)
    ELSE
      CALL step_rigid6_system(system, rt%points, rt%opts, rt%rigid, time, dt, converged, stalled, &
                              n_iter, ErrStat, ErrMsg, rt%work, host_mask=host_mask, host_q=host_q, host_v=host_v, &
                              host_a=host_a)
    END IF
  END SUBROUTINE CD_Step_Aggregate_Rigid6

  PURE INTEGER FUNCTION CD_Rigid6_NBodies(rt) RESULT(n)
    !! Number of Rigid6 bodies the runtime owns (0 if unpopulated).
    TYPE(CD_Rigid6RuntimeType), INTENT(IN) :: rt
    n = 0
    IF (ALLOCATED(rt%rigid)) n = SIZE(rt%rigid)
  END FUNCTION CD_Rigid6_NBodies

  SUBROUTINE CD_Rigid6_GetRefPositions(rt, xyz, ErrStat, ErrMsg)
    !! Current committed reference position of every Rigid6 body, shaped (3, NBodies) -- the
    !! points at which the host samples SeaState for the coupled fluid contract. Fail closed on
    !! a wrong-shaped array; a no-op (leaving xyz untouched) when the runtime owns no bodies.
    TYPE(CD_Rigid6RuntimeType), INTENT(IN) :: rt
    REAL(wp), INTENT(OUT) :: xyz(:, :)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: ib, nb
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    nb = CD_Rigid6_NBodies(rt)
    IF (nb == 0) RETURN
    IF (SIZE(xyz, 1) /= 3 .OR. SIZE(xyz, 2) /= nb) THEN
      ErrStat = CD_DECKDRV_BADINPUT
      ErrMsg = 'CableDyn_DeckDriver: CD_Rigid6_GetRefPositions array must be shaped (3, NBodies)'
      RETURN
    END IF
    DO ib = 1, nb
      xyz(:, ib) = rt%rigid(ib)%r
    END DO
  END SUBROUTINE CD_Rigid6_GetRefPositions

  SUBROUTINE CD_Rigid6_SetHeldFluid(rt, fluid_velocity, fluid_acceleration, waterline_z, ErrStat, ErrMsg)
    !! Store the host-sampled ambient fluid (velocity, acceleration, free-surface elevation) at
    !! each body reference point for the NEXT advance -- the coupled fluid contract. Once set, the
    !! body's Morison drag / Froude-Krylov / added-mass are taken from these fields in
    !! rigid6_environment_force (in place of a deck wave/current model). Fail closed on a
    !! wrong-shaped array or a non-finite field; a no-op when the runtime owns no bodies.
    TYPE(CD_Rigid6RuntimeType), INTENT(INOUT) :: rt
    REAL(wp), INTENT(IN) :: fluid_velocity(:, :), fluid_acceleration(:, :), waterline_z(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: ib, nb
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    nb = CD_Rigid6_NBodies(rt)
    IF (nb == 0) RETURN
    IF (SIZE(fluid_velocity, 1) /= 3 .OR. SIZE(fluid_velocity, 2) /= nb .OR. &
        SIZE(fluid_acceleration, 1) /= 3 .OR. SIZE(fluid_acceleration, 2) /= nb .OR. &
        SIZE(waterline_z) /= nb) THEN
      ErrStat = CD_DECKDRV_BADINPUT
      ErrMsg = 'CableDyn_DeckDriver: CD_Rigid6_SetHeldFluid fields must be shaped (3, NBodies) / (NBodies)'
      RETURN
    END IF
    IF (.NOT. (ALL(IEEE_IS_FINITE(fluid_velocity)) .AND. ALL(IEEE_IS_FINITE(fluid_acceleration)) .AND. &
               ALL(IEEE_IS_FINITE(waterline_z)))) THEN
      ErrStat = CD_DECKDRV_BADINPUT
      ErrMsg = 'CableDyn_DeckDriver: CD_Rigid6_SetHeldFluid fields must be finite'
      RETURN
    END IF
    DO ib = 1, nb
      rt%rigid(ib)%held_vel = fluid_velocity(:, ib)
      rt%rigid(ib)%held_acc = fluid_acceleration(:, ib)
      rt%rigid(ib)%held_eta = waterline_z(ib)
      rt%rigid(ib)%has_held = .TRUE.
    END DO
  END SUBROUTINE CD_Rigid6_SetHeldFluid

  SUBROUTINE CD_Rigid6_Snapshot(rt)
    !! Capture the step-start body states for a correction-rewind (twin of the system snapshot).
    TYPE(CD_Rigid6RuntimeType), INTENT(INOUT) :: rt
    IF (ALLOCATED(rt%rigid)) rt%snap_rigid = rt%rigid
  END SUBROUTINE CD_Rigid6_Snapshot

  SUBROUTINE CD_Rigid6_Restore(rt)
    !! Rewind the body states to the last snapshot (correction re-advance / staged-step undo).
    TYPE(CD_Rigid6RuntimeType), INTENT(INOUT) :: rt
    IF (ALLOCATED(rt%snap_rigid)) rt%rigid = rt%snap_rigid
  END SUBROUTINE CD_Rigid6_Restore

  SUBROUTINE CD_Rigid6_End(rt)
    !! Release the runtime's allocatable stores (opaque; the aggregate cannot reach the
    !! private components). Idempotent.
    TYPE(CD_Rigid6RuntimeType), INTENT(INOUT) :: rt
    TYPE(CD_Rigid6RuntimeType) :: fresh
    ! intrinsic assignment of a default-initialised value releases every allocatable
    ! component, the workspace (dload_da included) and the options arrays
    rt = fresh
  END SUBROUTINE CD_Rigid6_End

  SUBROUTINE CD_Init_Deck_Aggregate_Rod(rod_types, rods, points, opts, rt, ErrStat, ErrMsg, host_dcm)
    !! Populate the opaque rod runtime for the coupled aggregate: build the rod states and retain
    !! the deck options + points the per-step marcher needs (the aggregate keeps neither). The rod
    !! twin of CD_Init_Deck_Aggregate_Rigid6. Coupled/Vessel rods become host nodes (one per rod,
    !! in deck ROD order) at their End A; host_dcm is the host orientation at Init (the ZYX
    !! global-to-platform DCM of PtfmInit, identity when absent), so the rod frame in platform
    !! axes is host_dcm R0 and follows the host orientation afterwards.
    TYPE(DeckRodType), INTENT(IN) :: rod_types(:)
    TYPE(DeckRod), INTENT(IN) :: rods(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(CD_RodRuntimeType), INTENT(OUT) :: rt
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp), INTENT(IN), OPTIONAL :: host_dcm(3, 3)
    INTEGER :: ir, k, nh

    CALL init_rod_states(rod_types, rods, points, rt%rods, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    rt%opts = opts
    rt%points = points
    rt%host_o0 = CD_ZERO
    rt%host_o0(1, 1) = CD_ONE
    rt%host_o0(2, 2) = CD_ONE
    rt%host_o0(3, 3) = CD_ONE
    IF (PRESENT(host_dcm)) rt%host_o0 = host_dcm
    nh = COUNT(rt%rods%is_prescribed)
    ALLOCATE (rt%host_rod(nh), rt%host_rrel(3, 3, nh))
    k = 0
    DO ir = 1, SIZE(rt%rods)
      IF (.NOT. rt%rods(ir)%is_prescribed) CYCLE
      k = k + 1
      rt%host_rod(k) = ir
      rt%host_rrel(:, :, k) = MATMUL(rt%host_o0, rt%rods(ir)%rot_mat)
      ! a host-driven rod starts at rest in the host's Init pose; its a/alpha are the host's
      rt%rods(ir)%accel_valid = .TRUE.
    END DO
    rt%snap_rods = rt%rods
    rt%stage_rods = rt%rods
  END SUBROUTINE CD_Init_Deck_Aggregate_Rod

  PURE INTEGER FUNCTION CD_Rod_NHost(rt) RESULT(n)
    !! Number of host-driven (Coupled/Vessel) rods, i.e. the rod host nodes (0 if unpopulated).
    TYPE(CD_RodRuntimeType), INTENT(IN) :: rt
    n = 0
    IF (ALLOCATED(rt%host_rod)) n = SIZE(rt%host_rod)
  END FUNCTION CD_Rod_NHost

  SUBROUTINE CD_Rod_SetHostKinematics(rt, position, velocity, acceleration, ErrStat, ErrMsg, orientation, &
                                      angular_velocity, angular_acceleration)
    !! Impose the host node kinematics (End A position/velocity/acceleration, the host
    !! orientation and angular rates, all global; arrays shaped (3[,3], NHost)) on every
    !! Coupled/Vessel rod: R = O^T (O0 R0), centre = End A + (L/2) R e1 with the rigid
    !! velocity/acceleration transfer. Without an orientation the Init orientation is held;
    !! without angular rates they are zero. Atomic: validates everything before any change.
    TYPE(CD_RodRuntimeType), INTENT(INOUT) :: rt
    REAL(wp), INTENT(IN) :: position(:, :), velocity(:, :), acceleration(:, :)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp), INTENT(IN), OPTIONAL :: orientation(:, :, :)
    REAL(wp), INTENT(IN), OPTIONAL :: angular_velocity(:, :), angular_acceleration(:, :)
    INTEGER :: k, ir, nh
    REAL(wp) :: o(3, 3), rot(3, 3), arm(3), w(3), al(3)

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    nh = CD_Rod_NHost(rt)
    IF (nh == 0) RETURN
    IF (SIZE(position, 1) /= 3 .OR. SIZE(position, 2) /= nh .OR. SIZE(velocity, 1) /= 3 .OR. &
        SIZE(velocity, 2) /= nh .OR. SIZE(acceleration, 1) /= 3 .OR. SIZE(acceleration, 2) /= nh) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Rod_SetHostKinematics: arrays must be shaped (3, NHost)'); RETURN
    END IF
    IF (PRESENT(orientation)) THEN
      IF (SIZE(orientation, 1) /= 3 .OR. SIZE(orientation, 2) /= 3 .OR. SIZE(orientation, 3) /= nh) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Rod_SetHostKinematics: orientation must be shaped (3, 3, NHost)'); RETURN
      END IF
    END IF
    IF (PRESENT(angular_velocity) .NEQV. PRESENT(angular_acceleration)) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Rod_SetHostKinematics: angular rates must be supplied together'); RETURN
    END IF
    IF (PRESENT(angular_velocity)) THEN
      IF (SIZE(angular_velocity, 1) /= 3 .OR. SIZE(angular_velocity, 2) /= nh .OR. &
          SIZE(angular_acceleration, 1) /= 3 .OR. SIZE(angular_acceleration, 2) /= nh) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Rod_SetHostKinematics: angular rates must be shaped (3, NHost)'); RETURN
      END IF
    END IF
    DO k = 1, nh
      ir = rt%host_rod(k)
      o = rt%host_o0
      IF (PRESENT(orientation)) o = orientation(:, :, k)
      w = CD_ZERO
      al = CD_ZERO
      IF (PRESENT(angular_velocity)) THEN
        w = angular_velocity(:, k)
        al = angular_acceleration(:, k)
      END IF
      rot = MATMUL(TRANSPOSE(o), rt%host_rrel(:, :, k))
      arm = rt%rods(ir)%half_length*rot(:, 1)
      rt%rods(ir)%rot_mat = rot
      rt%rods(ir)%r = position(:, k) + arm
      rt%rods(ir)%v = velocity(:, k) + cross3(w, arm)
      rt%rods(ir)%a = acceleration(:, k) + cross3(al, arm) + cross3(w, cross3(w, arm))
      rt%rods(ir)%omega = w
      rt%rods(ir)%alpha = al
      rt%rods(ir)%accel_valid = .TRUE.
    END DO
  END SUBROUTINE CD_Rod_SetHostKinematics

  SUBROUTINE CD_Rod_GetHostKinematics(rt, k, position, velocity, acceleration, orientation, angular_velocity, &
                                      angular_acceleration)
    !! The committed kinematics of host node k (End A of the k-th Coupled/Vessel rod) and the
    !! host orientation O = (O0 R0) R^T it implies -- the inverse of CD_Rod_SetHostKinematics.
    TYPE(CD_RodRuntimeType), INTENT(IN) :: rt
    INTEGER, INTENT(IN) :: k
    REAL(wp), INTENT(OUT) :: position(3), velocity(3), acceleration(3), orientation(3, 3)
    REAL(wp), INTENT(OUT) :: angular_velocity(3), angular_acceleration(3)
    INTEGER :: ir
    REAL(wp) :: arm(3)

    ! an out-of-range k returns rest at the origin with the identity orientation
    position = CD_ZERO
    velocity = CD_ZERO
    acceleration = CD_ZERO
    orientation = CD_ZERO
    orientation(1, 1) = CD_ONE
    orientation(2, 2) = CD_ONE
    orientation(3, 3) = CD_ONE
    angular_velocity = CD_ZERO
    angular_acceleration = CD_ZERO
    IF (.NOT. ALLOCATED(rt%host_rod)) RETURN
    IF (k < 1 .OR. k > SIZE(rt%host_rod)) RETURN
    ir = rt%host_rod(k)
    arm = rt%rods(ir)%half_length*rt%rods(ir)%rot_mat(:, 1)
    position = rt%rods(ir)%r - arm
    velocity = rt%rods(ir)%v - cross3(rt%rods(ir)%omega, arm)
    acceleration = rt%rods(ir)%a - cross3(rt%rods(ir)%alpha, arm) - &
                   cross3(rt%rods(ir)%omega, cross3(rt%rods(ir)%omega, arm))
    orientation = MATMUL(rt%host_rrel(:, :, k), TRANSPOSE(rt%rods(ir)%rot_mat))
    angular_velocity = rt%rods(ir)%omega
    angular_acceleration = rt%rods(ir)%alpha
  END SUBROUTINE CD_Rod_GetHostKinematics

  SUBROUTINE CD_Rod_ScatterHostPoints(system, rt, q, v, a)
    !! Write the Rod<N>A/B attachment-point kinematics of every Coupled/Vessel rod into the
    !! full coupled-block arrays (3, n_system_coupled_dof/3) of the EI=0 system; every other
    !! block is left untouched.
    TYPE(CD_SystemType), INTENT(IN) :: system
    TYPE(CD_RodRuntimeType), INTENT(IN) :: rt
    REAL(wp), INTENT(INOUT) :: q(:, :), v(:, :), a(:, :)
    INTEGER :: k, ir, j, base, pidx
    REAL(wp) :: arm(3)

    DO k = 1, CD_Rod_NHost(rt)
      ir = rt%host_rod(k)
      DO j = 1, 2
        IF (j == 1) THEN
          pidx = rt%rods(ir)%point_a_index
          arm = -rt%rods(ir)%half_length*rt%rods(ir)%rot_mat(:, 1)
        ELSE
          pidx = rt%rods(ir)%point_b_index
          arm = rt%rods(ir)%half_length*rt%rods(ir)%rot_mat(:, 1)
        END IF
        base = system_point_base(system, rt%points(pidx)%id)
        IF (base < 0 .OR. base/3 + 1 > SIZE(q, 2)) CYCLE
        q(:, base/3 + 1) = rt%rods(ir)%r + arm
        v(:, base/3 + 1) = rt%rods(ir)%v + cross3(rt%rods(ir)%omega, arm)
        a(:, base/3 + 1) = rt%rods(ir)%a + cross3(rt%rods(ir)%alpha, arm) + &
                           cross3(rt%rods(ir)%omega, cross3(rt%rods(ir)%omega, arm))
      END DO
    END DO
  END SUBROUTINE CD_Rod_ScatterHostPoints

  SUBROUTINE CD_Rod_HostWrench(system, rt, loads, k, force, moment, ErrStat, ErrMsg)
    !! The load the k-th Coupled/Vessel rod returns to its host node (MoorDyn-F's coupled-rod
    !! net force with its inertial part), about End A: the attached line loads at Rod<N>A/B
    !! (loads: the system's coupled-point loads shaped (3, n_system_coupled_dof/3), which already
    !! carry the line-end inertia), the rod weight, the hydrostatic/Morison loads of
    !! rod_environment_force (held host fluid when set), seabed contact, and the rigid-body and
    !! added-mass inertia -M a of the rod at its host-prescribed acceleration, including the
    !! gyroscopic term w x (I w).
    TYPE(CD_SystemType), INTENT(IN) :: system
    TYPE(CD_RodRuntimeType), INTENT(IN) :: rt
    REAL(wp), INTENT(IN) :: loads(:, :)
    INTEGER, INTENT(IN) :: k
    REAL(wp), INTENT(OUT) :: force(3), moment(3)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: ir, base, j
    REAL(wp) :: arm(3), f_end(3, 2), f_env(3), m_env(3), f_sb(3), m_sb(3), added6(6, 6), drag6(6, 6)
    REAL(wp) :: dv(6, 6), acc6(6), ig(3, 3), mc(3)

    force = CD_ZERO
    moment = CD_ZERO
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (k < 1 .OR. k > CD_Rod_NHost(rt)) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Rod_HostWrench: host node index out of range'); RETURN
    END IF
    ir = rt%host_rod(k)
    arm = rt%rods(ir)%half_length*rt%rods(ir)%rot_mat(:, 1)
    f_end = CD_ZERO
    DO j = 1, 2
      IF (j == 1) THEN
        base = system_point_base(system, rt%points(rt%rods(ir)%point_a_index)%id)
      ELSE
        base = system_point_base(system, rt%points(rt%rods(ir)%point_b_index)%id)
      END IF
      IF (base < 0) CYCLE
      IF (base/3 + 1 > SIZE(loads, 2)) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Rod_HostWrench: load array does not cover the rod points'); RETURN
      END IF
      f_end(:, j) = loads(:, base/3 + 1)
    END DO
    CALL rod_environment_force(rt%rods(ir), rt%opts, CD_ZERO, f_env, m_env, added6, drag6, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL rod_seabed_contact(rt%rods(ir), rt%opts, f_sb, m_sb, dv, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    acc6(1:3) = rt%rods(ir)%a
    acc6(4:6) = rt%rods(ir)%alpha
    ig = CD_ZERO
    DO j = 1, 3
      ig(j, j) = rt%rods(ir)%inertia(j)
    END DO
    ig = MATMUL(rt%rods(ir)%rot_mat, MATMUL(ig, TRANSPOSE(rt%rods(ir)%rot_mat)))
    force = f_end(:, 1) + f_end(:, 2) + [CD_ZERO, CD_ZERO, -rt%rods(ir)%mass*rt%opts%g] + f_env + f_sb - &
            rt%rods(ir)%mass*rt%rods(ir)%a - MATMUL(added6(1:3, :), acc6)
    mc = cross3(-arm, f_end(:, 1)) + cross3(arm, f_end(:, 2)) + m_env + m_sb - &
         MATMUL(ig, rt%rods(ir)%alpha) - cross3(rt%rods(ir)%omega, MATMUL(ig, rt%rods(ir)%omega)) - &
         MATMUL(added6(4:6, :), acc6)
    moment = mc + cross3(arm, force)
  END SUBROUTINE CD_Rod_HostWrench

  SUBROUTINE CD_Rod_Stage(rt)
    !! Save the step-start rods before a host transfer (restored by CD_Rod_Unstage on failure).
    TYPE(CD_RodRuntimeType), INTENT(INOUT) :: rt
    IF (ALLOCATED(rt%rods)) rt%stage_rods = rt%rods
  END SUBROUTINE CD_Rod_Stage

  SUBROUTINE CD_Rod_Unstage(rt)
    !! Undo the host transfer of a failed staged step (see CD_Rod_Stage).
    TYPE(CD_RodRuntimeType), INTENT(INOUT) :: rt
    IF (ALLOCATED(rt%stage_rods)) rt%rods = rt%stage_rods
  END SUBROUTINE CD_Rod_Unstage

  SUBROUTINE CD_Step_Aggregate_Rod(system, rt, time, dt, converged, stalled, n_iter, ErrStat, ErrMsg, host_mask, &
                                   host_q, host_v, host_a, interp_hosts)
    !! Advance the aggregate's rigid rods one mooring step over its EI=0 system (flat seabed; the
    !! bathymetry argument is omitted, mirroring the Rigid6 flat-seabed march).
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    TYPE(CD_RodRuntimeType), INTENT(INOUT) :: rt
    REAL(wp), INTENT(IN) :: time, dt
    LOGICAL, INTENT(OUT) :: converged, stalled
    INTEGER, INTENT(OUT) :: n_iter, ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    ! host_mask/host_q/host_v/host_a: the host's moving coupled DOFs at t + dt (step_rod_system)
    LOGICAL, INTENT(IN), OPTIONAL :: host_mask(:)
    REAL(wp), INTENT(IN), OPTIONAL :: host_q(:), host_v(:), host_a(:)
    ! interp_hosts: the host-driven rods were staged this step (CD_Rod_Stage); see the Rigid6 twin
    LOGICAL, INTENT(IN), OPTIONAL :: interp_hosts
    LOGICAL :: interp

    interp = .FALSE.
    IF (PRESENT(interp_hosts)) interp = interp_hosts .AND. ALLOCATED(rt%stage_rods)
    IF (interp) THEN
      CALL step_rod_system(system, rt%points, rt%opts, rt%rods, time, dt, converged, stalled, &
                           n_iter, ErrStat, ErrMsg, rt%work, host_mask=host_mask, host_q=host_q, host_v=host_v, &
                           host_a=host_a, host_start=rt%stage_rods)
    ELSE
      CALL step_rod_system(system, rt%points, rt%opts, rt%rods, time, dt, converged, stalled, &
                           n_iter, ErrStat, ErrMsg, rt%work, host_mask=host_mask, host_q=host_q, host_v=host_v, &
                           host_a=host_a)
    END IF
  END SUBROUTINE CD_Step_Aggregate_Rod

  PURE INTEGER FUNCTION CD_Rod_NRods(rt) RESULT(n)
    !! Number of rods the runtime owns (0 if unpopulated).
    TYPE(CD_RodRuntimeType), INTENT(IN) :: rt
    n = 0
    IF (ALLOCATED(rt%rods)) n = SIZE(rt%rods)
  END FUNCTION CD_Rod_NRods

  SUBROUTINE CD_Rod_Hydro_Probe(diam, length, nsegs, coef, centre, axis, vel, omega, force, moment, added_mass, &
                                ErrStat, ErrMsg, wave, held, moordyn_hydro)
    !! Diagnostic entry for the rod hydrodynamic model: the hydrostatic and Morison loads
    !! (rod_environment_force: no weight, no contact) of one rigid rod about its centre in still
    !! water with the free surface at z = 0, rhoW = 1025 kg/m^3 and g = 9.80665 m/s^2.
    !! coef = [Cd, Ca, CdEnd, CaEnd, CdAx, CaAx]; axis is the End A -> End B direction.
    !! wave = [H, T, t]: a regular Airy wave along +x in 200 m of water, evaluated at time t.
    !! held: take that wave as a host field sampled at the NumSegs + 1 segment stations
    !! (velocity, acceleration, elevation and dynamic pressure), as the coupled rods do.
    !! moordyn_hydro: OPTION rodHydro moordyn (MoorDyn's waterplane moment).
    REAL(wp), INTENT(IN) :: diam, length, coef(6), centre(3), axis(3), vel(3), omega(3)
    INTEGER, INTENT(IN) :: nsegs
    REAL(wp), INTENT(OUT) :: force(3), moment(3), added_mass(6, 6)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp), INTENT(IN), OPTIONAL :: wave(3)
    LOGICAL, INTENT(IN), OPTIONAL :: held, moordyn_hydro
    TYPE(RodState) :: rod
    TYPE(DeckOptions) :: opts
    REAL(wp) :: drag_dv(6, 6), t, x(3)
    INTEGER :: j, nseg
    LOGICAL :: use_held

    rod%diam = diam
    rod%length = length
    rod%half_length = 0.5_wp*length
    rod%nsegs = MAX(1, nsegs)
    rod%cdn = coef(1)
    rod%can = coef(2)
    rod%cdend = coef(3)
    rod%caend = coef(4)
    rod%cdt = coef(5)
    rod%cat = coef(6)
    rod%r = centre
    rod%rot_mat = rod_orientation_from_axis(axis/NORM2(axis))
    rod%v = vel
    rod%omega = omega
    IF (PRESENT(moordyn_hydro)) opts%rod_hydro_moordyn = moordyn_hydro
    t = CD_ZERO
    IF (PRESENT(wave)) THEN
      opts%has_wave = .TRUE.
      opts%wave_kind = WAVE_AIRY
      opts%wave_height = wave(1)
      opts%wave_period = wave(2)
      opts%wtrdpth = 200.0_wp
      t = wave(3)
      CALL precompute_deck_wave(opts, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      use_held = .FALSE.
      IF (PRESENT(held)) use_held = held
      IF (use_held) THEN
        nseg = rod%nsegs
        ALLOCATE (rod%held_vel(3, 0:nseg), rod%held_acc(3, 0:nseg), rod%held_eta(0:nseg), rod%held_pd(0:nseg))
        DO j = 0, nseg
          x = rod%r + (-rod%half_length + REAL(j, wp)*length/REAL(nseg, wp))*rod%rot_mat(:, 1)
          CALL deck_wave_kinematics(opts, x(1), x(2), x(3), t, rod%held_eta(j), rod%held_vel(:, j), &
                                    rod%held_acc(:, j), ErrStat, ErrMsg, pdyn=rod%held_pd(j))
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
        END DO
        rod%has_held = .TRUE.
        rod%has_held_pd = .TRUE.
        opts%has_wave = .FALSE.
      END IF
    END IF
    CALL rod_environment_force(rod, opts, t, force, moment, added_mass, drag_dv, ErrStat, ErrMsg)
  END SUBROUTINE CD_Rod_Hydro_Probe

  SUBROUTINE CD_Rigid6_Fluid_Probe(mass, vol, cda, ca, pos, vel, fluid_vel, fluid_acc, moordyn_hydro, force, &
                                   effective_mass, ErrStat, ErrMsg)
    !! Diagnostic entry for the Rigid6 Morison model (rigid6_environment_force): the lumped fluid
    !! force on a body at pos moving at vel in a held fluid sample (velocity fluid_vel,
    !! acceleration fluid_acc), and its effective translational mass; rhoW = 1025 kg/m^3,
    !! g = 9.80665 m/s^2, still-water surface at z = 0. moordyn_hydro: OPTION bodyHydro moordyn.
    REAL(wp), INTENT(IN) :: mass, vol, cda, ca, pos(3), vel(3), fluid_vel(3), fluid_acc(3)
    LOGICAL, INTENT(IN) :: moordyn_hydro
    REAL(wp), INTENT(OUT) :: force(3), effective_mass
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(RigidBodyState) :: body
    TYPE(DeckOptions) :: opts
    REAL(wp) :: drag_dv(3, 3)
    body%mass = mass
    body%vol = vol
    body%cda = cda
    body%ca = ca
    body%r = pos
    body%v = vel
    body%rot_mat = CD_ZERO
    body%rot_mat(1, 1) = CD_ONE
    body%rot_mat(2, 2) = CD_ONE
    body%rot_mat(3, 3) = CD_ONE
    body%has_held = .TRUE.
    body%held_vel = fluid_vel
    body%held_acc = fluid_acc
    opts%body_hydro_moordyn = moordyn_hydro
    CALL rigid6_environment_force(body, opts, CD_ZERO, force, effective_mass, drag_dv, ErrStat, ErrMsg)
  END SUBROUTINE CD_Rigid6_Fluid_Probe

  SUBROUTINE CD_Deck_Fluid_Probe(deck_path, pos, times, eta, vel, acc, ErrStat, ErrMsg)
    !! Verification entry: parse a standalone deck and return its water kinematics at the points
    !! pos(3, n) and times times(n): the surface elevation eta(n), the fluid velocity vel(3, n)
    !! (waves plus current) and acceleration acc(3, n), the fields every standalone object
    !! samples (deck_wave_kinematics and deck_current_velocity).
    CHARACTER(*), INTENT(IN) :: deck_path
    REAL(wp), INTENT(IN) :: pos(:, :), times(:)
    REAL(wp), INTENT(OUT) :: eta(:), vel(:, :), acc(:, :)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(DeckLineType), ALLOCATABLE :: types(:)
    TYPE(DeckBody), ALLOCATABLE :: bodies(:)
    TYPE(DeckRodType), ALLOCATABLE :: rod_types(:)
    TYPE(DeckRod), ALLOCATABLE :: rods(:)
    TYPE(DeckPoint), ALLOCATABLE :: points(:)
    TYPE(DeckLine), ALLOCATABLE :: lines(:)
    TYPE(DeckSection), ALLOCATABLE :: sections(:)
    TYPE(DeckOptions) :: opts
    CHARACTER(NAMELEN), ALLOCATABLE :: channels(:)
    INTEGER :: i
    eta = CD_ZERO
    vel = CD_ZERO
    acc = CD_ZERO
    CALL parse_deck(deck_path, types, bodies, rod_types, rods, points, lines, sections, opts, channels, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL precompute_deck_wave(opts, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    DO i = 1, SIZE(times)
      CALL deck_wave_kinematics(opts, pos(1, i), pos(2, i), pos(3, i), times(i), eta(i), vel(:, i), acc(:, i), &
                                ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      vel(:, i) = vel(:, i) + deck_current_velocity(opts, pos(3, i), ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END DO
  END SUBROUTINE CD_Deck_Fluid_Probe

  SUBROUTINE CD_Rigid6_Hydrostatics_Probe(mass, vol, cg, cstiff, rot_ref, pos, rot, moordyn_wetting, force, moment, &
                                          phi, ErrStat, ErrMsg)
    !! Diagnostic entry for the Rigid6 hydrostatic model (rigid6_hydrostatics): weight at the CG,
    !! buoyancy at the CB (= CG) scaled by the submerged fraction phi, and the waterplane restoring
    !! cstiff = [C33, C44, C55] about the reference pose (reference point at the origin, rotation
    !! rot_ref), for a body at pos with rotation rot; still water at z = 0, rhoW = 1025 kg/m^3,
    !! g = 9.80665 m/s^2.
    REAL(wp), INTENT(IN) :: mass, vol, cg(3), cstiff(3), rot_ref(3, 3), pos(3), rot(3, 3)
    LOGICAL, INTENT(IN) :: moordyn_wetting
    REAL(wp), INTENT(OUT) :: force(3), moment(3), phi
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(RigidBodyState) :: body
    TYPE(DeckOptions) :: opts

    body%mass = mass
    body%vol = vol
    body%cg = cg
    body%cb = cg
    body%c33 = cstiff(1)
    body%c44 = cstiff(2)
    body%c55 = cstiff(3)
    body%rot_ref = rot_ref
    body%r = pos
    body%rot_mat = rot
    opts%body_wetting_moordyn = moordyn_wetting
    CALL rigid6_wet_fraction(body, opts, CD_ZERO, phi, ErrStat, ErrMsg)
    IF (ErrStat == CD_DECKDRV_OK) CALL rigid6_hydrostatics(body, opts, CD_ZERO, force, moment, ErrStat, ErrMsg)
  END SUBROUTINE CD_Rigid6_Hydrostatics_Probe

  PURE INTEGER FUNCTION CD_Rod_NFluidStations(rt) RESULT(n)
    !! Number of host fluid sampling stations over all rods: NumSegs + 1 per rod (0 if unpopulated).
    TYPE(CD_RodRuntimeType), INTENT(IN) :: rt
    n = 0
    IF (ALLOCATED(rt%rods)) n = SUM(MAX(1, rt%rods%nsegs) + 1)
  END FUNCTION CD_Rod_NFluidStations

  PURE INTEGER FUNCTION CD_Rod_NStations(rt, ir) RESULT(n)
    !! Number of host fluid sampling stations of rod ir (NumSegs + 1).
    TYPE(CD_RodRuntimeType), INTENT(IN) :: rt
    INTEGER, INTENT(IN) :: ir
    n = MAX(1, rt%rods(ir)%nsegs) + 1
  END FUNCTION CD_Rod_NStations

  SUBROUTINE CD_Rod_GetFluidPositions(rt, xyz, ErrStat, ErrMsg)
    !! Return the host fluid sampling stations of every rod, rod-major, End A to End B: the
    !! NumSegs + 1 segment ends s_j = -L/2 + j L/NumSegs of the rod's hydrodynamic segments.
    TYPE(CD_RodRuntimeType), INTENT(IN) :: rt
    REAL(wp), INTENT(OUT) :: xyz(:, :)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: ir, j, k, nseg
    REAL(wp) :: axis(3), s

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (.NOT. ALLOCATED(rt%rods)) RETURN
    IF (SIZE(xyz, 1) /= 3 .OR. SIZE(xyz, 2) /= CD_Rod_NFluidStations(rt)) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Rod_GetFluidPositions: array must be shaped (3, sum of NumSegs + 1)'); RETURN
    END IF
    k = 0
    DO ir = 1, SIZE(rt%rods)
      axis = rt%rods(ir)%rot_mat(:, 1)
      nseg = MAX(1, rt%rods(ir)%nsegs)
      DO j = 0, nseg
        k = k + 1
        s = -rt%rods(ir)%half_length + REAL(j, wp)*(rt%rods(ir)%length/REAL(nseg, wp))
        xyz(:, k) = rt%rods(ir)%r + s*axis
      END DO
    END DO
  END SUBROUTINE CD_Rod_GetFluidPositions

  SUBROUTINE CD_Rod_SetHeldFluid(rt, fluid_velocity, fluid_acceleration, waterline_z, ErrStat, ErrMsg, &
                                 dynamic_pressure)
    !! Hold the host fluid field sampled at the CD_Rod_GetFluidPositions stations on every rod:
    !! velocity and acceleration (3, n), waterline (n) and, optionally, the wave dynamic pressure
    !! per unit density (n). Atomic: validates everything before any change.
    TYPE(CD_RodRuntimeType), INTENT(INOUT) :: rt
    REAL(wp), INTENT(IN) :: fluid_velocity(:, :), fluid_acceleration(:, :), waterline_z(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp), INTENT(IN), OPTIONAL :: dynamic_pressure(:)
    INTEGER :: ir, k, n, nst

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (.NOT. ALLOCATED(rt%rods)) RETURN
    n = CD_Rod_NFluidStations(rt)
    IF (SIZE(fluid_velocity, 1) /= 3 .OR. SIZE(fluid_velocity, 2) /= n .OR. &
        SIZE(fluid_acceleration, 1) /= 3 .OR. SIZE(fluid_acceleration, 2) /= n .OR. &
        SIZE(waterline_z) /= n) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Rod_SetHeldFluid: arrays must match the NumSegs + 1 stations per rod'); RETURN
    END IF
    IF (.NOT. (ALL(IEEE_IS_FINITE(fluid_velocity)) .AND. ALL(IEEE_IS_FINITE(fluid_acceleration)) .AND. &
               ALL(IEEE_IS_FINITE(waterline_z)))) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Rod_SetHeldFluid: non-finite host field'); RETURN
    END IF
    IF (PRESENT(dynamic_pressure)) THEN
      IF (SIZE(dynamic_pressure) /= n) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Rod_SetHeldFluid: dynamic pressure must match the stations'); RETURN
      END IF
      IF (.NOT. ALL(IEEE_IS_FINITE(dynamic_pressure))) THEN
        CALL fail(ErrStat, ErrMsg, 'CD_Rod_SetHeldFluid: non-finite host dynamic pressure'); RETURN
      END IF
    END IF
    k = 0
    DO ir = 1, SIZE(rt%rods)
      nst = CD_Rod_NStations(rt, ir)
      CALL size_held(rt%rods(ir), nst)
      rt%rods(ir)%held_vel(:, 0:nst - 1) = fluid_velocity(:, k + 1:k + nst)
      rt%rods(ir)%held_acc(:, 0:nst - 1) = fluid_acceleration(:, k + 1:k + nst)
      rt%rods(ir)%held_eta(0:nst - 1) = waterline_z(k + 1:k + nst)
      rt%rods(ir)%held_pd = CD_ZERO
      rt%rods(ir)%has_held_pd = PRESENT(dynamic_pressure)
      IF (PRESENT(dynamic_pressure)) rt%rods(ir)%held_pd(0:nst - 1) = dynamic_pressure(k + 1:k + nst)
      rt%rods(ir)%has_held = .TRUE.
      k = k + nst
    END DO

  CONTAINS

    SUBROUTINE size_held(rod, nst)
      !! (Re)allocate the held station arrays with bounds 0:nst-1 (kept when already sized).
      TYPE(RodState), INTENT(INOUT) :: rod
      INTEGER, INTENT(IN) :: nst
      IF (ALLOCATED(rod%held_vel)) THEN
        IF (LBOUND(rod%held_vel, 2) == 0 .AND. UBOUND(rod%held_vel, 2) == nst - 1) RETURN
        DEALLOCATE (rod%held_vel, rod%held_acc, rod%held_eta, rod%held_pd)
      END IF
      ALLOCATE (rod%held_vel(3, 0:nst - 1), rod%held_acc(3, 0:nst - 1), rod%held_eta(0:nst - 1), &
                rod%held_pd(0:nst - 1))
    END SUBROUTINE size_held
  END SUBROUTINE CD_Rod_SetHeldFluid

  SUBROUTINE CD_Rod_Snapshot(rt)
    !! Capture the step-start rod states for a correction-rewind (twin of the system snapshot).
    TYPE(CD_RodRuntimeType), INTENT(INOUT) :: rt
    IF (ALLOCATED(rt%rods)) rt%snap_rods = rt%rods
  END SUBROUTINE CD_Rod_Snapshot

  SUBROUTINE CD_Rod_Restore(rt)
    !! Rewind the rod states to the last snapshot (correction re-advance / staged-step undo).
    TYPE(CD_RodRuntimeType), INTENT(INOUT) :: rt
    IF (ALLOCATED(rt%snap_rods)) rt%rods = rt%snap_rods
  END SUBROUTINE CD_Rod_Restore

  SUBROUTINE CD_Rod_End(rt)
    !! Release the runtime's allocatable stores (opaque; idempotent). Rod twin of CD_Rigid6_End.
    TYPE(CD_RodRuntimeType), INTENT(INOUT) :: rt
    TYPE(CD_RodRuntimeType) :: fresh
    ! releases every allocatable component (see CD_Rigid6_End)
    rt = fresh
  END SUBROUTINE CD_Rod_End

  PURE INTEGER FUNCTION CD_Rod_MirrorSize(rt) RESULT(n)
    !! Reals required for every rod's committed rigid-body state:
    !! r, v, a, omega, alpha, and the 3x3 orientation matrix.
    TYPE(CD_RodRuntimeType), INTENT(IN) :: rt
    n = 0
    IF (ALLOCATED(rt%rods)) n = CD_ROD_MIRROR_PER_ROD*SIZE(rt%rods)
  END FUNCTION CD_Rod_MirrorSize

  SUBROUTINE CD_Rod_Get_States(rt, states, ErrStat, ErrMsg)
    TYPE(CD_RodRuntimeType), INTENT(IN) :: rt
    REAL(wp), INTENT(OUT) :: states(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: ir, k

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (.NOT. ALLOCATED(rt%rods)) RETURN
    IF (SIZE(states) /= CD_ROD_MIRROR_PER_ROD*SIZE(rt%rods)) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Rod_Get_States: state array size mismatch'); RETURN
    END IF
    DO ir = 1, SIZE(rt%rods)
      k = CD_ROD_MIRROR_PER_ROD*(ir - 1)
      states(k + 1:k + 3) = rt%rods(ir)%r
      states(k + 4:k + 6) = rt%rods(ir)%v
      states(k + 7:k + 9) = rt%rods(ir)%a
      states(k + 10:k + 12) = rt%rods(ir)%omega
      states(k + 13:k + 15) = rt%rods(ir)%alpha
      states(k + 16:k + 24) = RESHAPE(rt%rods(ir)%rot_mat, [9])
    END DO
  END SUBROUTINE CD_Rod_Get_States

  SUBROUTINE CD_Rod_Set_States(rt, states, ErrStat, ErrMsg)
    TYPE(CD_RodRuntimeType), INTENT(INOUT) :: rt
    REAL(wp), INTENT(IN) :: states(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: ir, k

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (.NOT. ALLOCATED(rt%rods)) RETURN
    IF (SIZE(states) /= CD_ROD_MIRROR_PER_ROD*SIZE(rt%rods)) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Rod_Set_States: state array size mismatch'); RETURN
    END IF
    IF (.NOT. ALL(IEEE_IS_FINITE(states))) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Rod_Set_States: non-finite state value'); RETURN
    END IF
    DO ir = 1, SIZE(rt%rods)
      k = CD_ROD_MIRROR_PER_ROD*(ir - 1)
      rt%rods(ir)%r = states(k + 1:k + 3)
      rt%rods(ir)%v = states(k + 4:k + 6)
      rt%rods(ir)%a = states(k + 7:k + 9)
      rt%rods(ir)%omega = states(k + 10:k + 12)
      rt%rods(ir)%alpha = states(k + 13:k + 15)
      rt%rods(ir)%rot_mat = RESHAPE(states(k + 16:k + 24), [3, 3])
      rt%rods(ir)%accel_valid = .TRUE.
    END DO
  END SUBROUTINE CD_Rod_Set_States

  SUBROUTINE CD_Rod_Apply_States(system, rt, ErrStat, ErrMsg)
    !! Re-derive Rod<N>A/B system-point kinematics immediately after a mirror
    !! restore, so a restart-time CalcOutput cannot observe the pre-restore ends.
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    TYPE(CD_RodRuntimeType), INTENT(INOUT) :: rt
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (.NOT. ALLOCATED(rt%rods)) RETURN
    CALL apply_rod_states_to_system(system, rt%points, rt%rods, rt%work, ErrStat, ErrMsg)
  END SUBROUTINE CD_Rod_Apply_States

  PURE INTEGER FUNCTION CD_Rigid6_MirrorSize(rt) RESULT(n)
    !! Reals the checkpoint mirror needs for ALL Rigid6 bodies: CD_RIGID6_MIRROR_PER_BODY per
    !! body (r, v, a, omega, alpha, rot_mat) -- the dynamic 6-DOF state a restart cannot
    !! re-derive from the deck. The reference frame (r_ref/rot_ref) is constant and the
    !! restoring coordinate eta is re-derived from the restored orientation on set.
    TYPE(CD_Rigid6RuntimeType), INTENT(IN) :: rt
    n = 0
    IF (ALLOCATED(rt%rigid)) n = CD_RIGID6_MIRROR_PER_BODY*SIZE(rt%rigid)
  END FUNCTION CD_Rigid6_MirrorSize

  SUBROUTINE CD_Rigid6_Get_States(rt, states, ErrStat, ErrMsg)
    !! Pack every body's dynamic 6-DOF state into the flat mirror array (CD_Rigid6_MirrorSize),
    !! one block per body: r(3) v(3) a(3) omega(3) alpha(3) rot_mat(9). No-op if unpopulated.
    TYPE(CD_Rigid6RuntimeType), INTENT(IN) :: rt
    REAL(wp), INTENT(OUT) :: states(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: ib, k
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (.NOT. ALLOCATED(rt%rigid)) RETURN
    IF (SIZE(states) /= CD_RIGID6_MIRROR_PER_BODY*SIZE(rt%rigid)) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Rigid6_Get_States: state array size mismatch'); RETURN
    END IF
    DO ib = 1, SIZE(rt%rigid)
      k = CD_RIGID6_MIRROR_PER_BODY*(ib - 1)
      states(k + 1:k + 3) = rt%rigid(ib)%r
      states(k + 4:k + 6) = rt%rigid(ib)%v
      states(k + 7:k + 9) = rt%rigid(ib)%a
      states(k + 10:k + 12) = rt%rigid(ib)%omega
      states(k + 13:k + 15) = rt%rigid(ib)%alpha
      states(k + 16:k + 24) = RESHAPE(rt%rigid(ib)%rot_mat, [9])
    END DO
  END SUBROUTINE CD_Rigid6_Get_States

  SUBROUTINE CD_Rigid6_Set_States(rt, states, ErrStat, ErrMsg)
    !! Unpack the flat mirror array back into every body's dynamic state, recomputing the
    !! derived restoring coordinate eta = Log_SO3(rot_mat . rot_ref^T) from the restored
    !! orientation. Fails closed on a size mismatch or a non-finite value (never a silent bad
    !! restart). No-op if unpopulated.
    TYPE(CD_Rigid6RuntimeType), INTENT(INOUT) :: rt
    REAL(wp), INTENT(IN) :: states(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: ib, k
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (.NOT. ALLOCATED(rt%rigid)) RETURN
    IF (SIZE(states) /= CD_RIGID6_MIRROR_PER_BODY*SIZE(rt%rigid)) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Rigid6_Set_States: state array size mismatch'); RETURN
    END IF
    IF (.NOT. ALL(IEEE_IS_FINITE(states))) THEN
      CALL fail(ErrStat, ErrMsg, 'CD_Rigid6_Set_States: non-finite state value'); RETURN
    END IF
    DO ib = 1, SIZE(rt%rigid)
      k = CD_RIGID6_MIRROR_PER_BODY*(ib - 1)
      rt%rigid(ib)%r = states(k + 1:k + 3)
      rt%rigid(ib)%v = states(k + 4:k + 6)
      rt%rigid(ib)%a = states(k + 7:k + 9)
      rt%rigid(ib)%omega = states(k + 10:k + 12)
      rt%rigid(ib)%alpha = states(k + 13:k + 15)
      rt%rigid(ib)%rot_mat = RESHAPE(states(k + 16:k + 24), [3, 3])
      rt%rigid(ib)%eta = CD_Log_SO3(MATMUL(rt%rigid(ib)%rot_mat, TRANSPOSE(rt%rigid(ib)%rot_ref)))
      rt%rigid(ib)%accel_valid = .TRUE.
    END DO
  END SUBROUTINE CD_Rigid6_Set_States

  SUBROUTINE step_rigid6_system(system, points, opts, rigid, time, dt, converged, stalled, n_iter, ErrStat, ErrMsg, &
                                work, bathymetry, host_mask, host_q, host_v, host_a, host_start)
    !! Advance Rigid6 bodies and lines from time - dt to time: step_rigid6_once, sub-cycled so
    !! that the explicit central-difference body position resolves the stiffest body-mooring
    !! mode (rigid_substep_count). converged is the AND and stalled the OR over the sub-steps.
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(RigidBodyState), INTENT(INOUT) :: rigid(:)
    REAL(wp), INTENT(IN) :: time
    REAL(wp), INTENT(IN) :: dt
    LOGICAL, INTENT(OUT) :: converged, stalled
    INTEGER, INTENT(OUT) :: n_iter, ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(RigidStepWorkspace), INTENT(INOUT) :: work
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    ! host_mask/host_q/host_v/host_a: the host-prescribed (moving) coupled DOFs and their
    ! t + dt kinematics (a coupled host). They enter the line step as its prescribed end motion
    ! while the line ends keep their step-start state, exactly as a plain moving step does.
    LOGICAL, INTENT(IN), OPTIONAL :: host_mask(:)
    REAL(wp), INTENT(IN), OPTIONAL :: host_q(:), host_v(:), host_a(:)
    ! host_start: the step-start state of the host-driven (is_prescribed) bodies, which hold their
    ! t + dt pose on entry; sub-steps then move them along the interpolated host path
    TYPE(RigidBodyState), INTENT(IN), OPTIONAL :: host_start(:)
    REAL(wp), ALLOCATABLE :: q0h(:), v0h(:), a0h(:)
    INTEGER :: ib, ip, nsub, isub, it
    REAL(wp), ALLOCATABLE :: hk_end(:, :)
    LOGICAL :: conv_s, stall_s
    REAL(wp) :: omega2, mass6(6)

    converged = .TRUE.
    stalled = .FALSE.
    n_iter = 0
    omega2 = CD_ZERO
    DO ib = 1, SIZE(rigid)
      IF (rigid(ib)%is_prescribed) CYCLE
      BLOCK
        INTEGER :: att_base(SIZE(rigid(ib)%point_indices))
        REAL(wp) :: att_arm(3, SIZE(rigid(ib)%point_indices))
        DO ip = 1, SIZE(rigid(ib)%point_indices)
          att_base(ip) = system_point_base(system, points(rigid(ib)%point_indices(ip))%id)
          att_arm(:, ip) = MATMUL(rigid(ib)%rot_mat, points(rigid(ib)%point_indices(ip))%body_offset)
        END DO
        ! structural mass and inertia plus the submerged body's translational added mass
        mass6(1:3) = rigid(ib)%mass
        IF (rigid(ib)%r(3) < CD_ZERO) mass6(1:3) = mass6(1:3) + opts%rhoW*rigid(ib)%vol*MAX(CD_ZERO, rigid(ib)%ca)
        mass6(4:6) = global_inertia_diag(rigid(ib)%rot_mat, rigid(ib)%inertia)
        omega2 = MAX(omega2, rigid_omega2_estimate(system, att_base, att_arm, mass6, &
                                                   [CD_ZERO, CD_ZERO, rigid(ib)%c33, rigid(ib)%c44, &
                                                    rigid(ib)%c55, CD_ZERO]))
      END BLOCK
    END DO
    nsub = rigid_substep_count(omega2, dt)
    CALL host_substep_start(system, nsub, q0h, v0h, a0h, ErrStat, ErrMsg, host_mask)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    DO isub = 1, nsub
      IF (nsub > 1 .AND. PRESENT(host_start)) THEN
        IF (isub == 1) CALL save_host_end_rigid(rigid, hk_end)
        CALL interp_host_rigid(rigid, host_start, hk_end, REAL(isub, wp)/REAL(nsub, wp))
      END IF
      IF (.NOT. PRESENT(host_mask)) THEN
        CALL step_rigid6_once(system, points, opts, rigid, time - dt + REAL(isub, wp)*dt/REAL(nsub, wp), &
                              dt/REAL(nsub, wp), conv_s, stall_s, it, ErrStat, ErrMsg, work, bathymetry)
      ELSE IF (nsub == 1) THEN
        CALL step_rigid6_once(system, points, opts, rigid, time, dt, conv_s, stall_s, it, ErrStat, ErrMsg, work, &
                              bathymetry, host_mask, host_q, host_v, host_a)
      ELSE
        ! sub-steps take the host motion linearly interpolated from the step start
        CALL step_rigid6_once(system, points, opts, rigid, time - dt + REAL(isub, wp)*dt/REAL(nsub, wp), &
                              dt/REAL(nsub, wp), conv_s, stall_s, it, ErrStat, ErrMsg, work, bathymetry, host_mask, &
                              q0h + REAL(isub, wp)/REAL(nsub, wp)*(host_q - q0h), &
                              v0h + REAL(isub, wp)/REAL(nsub, wp)*(host_v - v0h), &
                              a0h + REAL(isub, wp)/REAL(nsub, wp)*(host_a - a0h))
      END IF
      converged = converged .AND. conv_s
      stalled = stalled .OR. stall_s
      n_iter = n_iter + it
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END DO
  END SUBROUTINE step_rigid6_system

  SUBROUTINE step_rigid6_once(system, points, opts, rigid, time, dt, converged, stalled, n_iter, ErrStat, ErrMsg, &
                              work, bathymetry, host_mask, host_q, host_v, host_a)
    !! Advance Rigid6 bodies and their lines one step by a staggered central-difference
    !! (Newmark gamma = 1/2, beta = 0) predictor-corrector:
    !!  1. predictor: each body moves to r + dt v + dt^2 a_n / 2 (its final position, beta = 0)
    !!     with velocity v + dt a_n, and the lines are stepped to t + dt with that fairlead
    !!     motion, so the end-of-step line loads carry the lines' own response (waves and drag
    !!     on the lines, nodal dynamics) at the body's actual position instead of lagging a step;
    !!  2. corrector: the end-of-step acceleration solves the equation of motion with the line
    !!     loads and every body load at the predictor, the line end-node inertia and the body
    !!     drag implicit (rigid_coupled_acceleration); the velocity is the trapezoidal average.
    !! The scheme is second order and free of numerical damping, so the moored-body response
    !! converges with dt instead of carrying a dt-dependent damping, and the line ends are
    !! never displaced from the positions the lines were solved with. Position-dependent body
    !! loads (hydrostatic restoring, seabed springs) act explicitly: stable for
    !! dt*SQRT(k/m) < 2. The Body<N> point records are finally set to the corrected motion (the
    !! same map a checkpoint restore applies).
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(RigidBodyState), INTENT(INOUT) :: rigid(:)
    REAL(wp), INTENT(IN) :: time
    REAL(wp), INTENT(IN) :: dt
    LOGICAL, INTENT(OUT) :: converged, stalled
    INTEGER, INTENT(OUT) :: n_iter, ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(RigidStepWorkspace), INTENT(INOUT) :: work
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    ! host_mask/host_q/host_v/host_a: the host-prescribed (moving) coupled DOFs and their
    ! t + dt kinematics (a coupled host). They enter the line step as its prescribed end motion
    ! while the line ends keep their step-start state, exactly as a plain moving step does.
    LOGICAL, INTENT(IN), OPTIONAL :: host_mask(:)
    REAL(wp), INTENT(IN), OPTIONAL :: host_q(:), host_v(:), host_a(:)

    INTEGER :: ib, es, p, base
    REAL(wp) :: dv0(6), acc(3), alpha(3)
    CHARACTER(160) :: em
    ! detached: the active free points that are not deck points -- the reserve points a line
    ! FAILURE moved line ends onto. They are integrated on their line-end loads; every other
    ! point follows its body or stays held.
    LOGICAL :: detached(SIZE(system%points))

    converged = .FALSE.
    stalled = .FALSE.
    n_iter = 0
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    CALL ensure_rigid_step_workspace(work, system%n_system_coupled_dof, SIZE(rigid), SIZE(system%points))
    DO p = 1, SIZE(system%points)
      detached(p) = system%points(p)%active .AND. system%points(p)%point_type == CD_POINT_FREE .AND. &
                    ALL(points%id /= system%points(p)%id)
    END DO
    ! 0. a body without a committed acceleration (the first step) gets the instantaneous one
    ! from the current line loads, so the predictor starts from the actual a_0
    IF (.NOT. ALL(rigid%accel_valid)) THEN
      CALL rigid_start_loads(system, work%q(1:system%n_system_coupled_dof), work%v(1:system%n_system_coupled_dof), &
                             work%a(1:system%n_system_coupled_dof), work%loads(1:system%n_system_coupled_dof), &
                             work%dload_da, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      DO ib = 1, SIZE(rigid)
        IF (rigid(ib)%accel_valid) CYCLE
        CALL rigid6_body_acceleration(system, points, opts, rigid(ib), time - dt, CD_ZERO, &
                                      [CD_ZERO, CD_ZERO, CD_ZERO, CD_ZERO, CD_ZERO, CD_ZERO], work, ib, &
                                      acc, alpha, ErrStat, ErrMsg, bathymetry)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        rigid(ib)%a = acc
        rigid(ib)%alpha = alpha
        rigid(ib)%accel_valid = .TRUE.
      END DO
    END IF
    work%old_rigid = rigid
    work%old_points = system%points
    CALL CD_Get_System_CoupledMotion(system, work%q(1:system%n_system_coupled_dof), &
                                     work%v(1:system%n_system_coupled_dof), &
                                     work%a(1:system%n_system_coupled_dof), es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: Rigid6 coupled-motion query failed: '//TRIM(em)
      RETURN
    END IF
    CALL overlay_host_motion(work%q(1:system%n_system_coupled_dof), work%v(1:system%n_system_coupled_dof), &
                             work%a(1:system%n_system_coupled_dof), host_mask, host_q, host_v, host_a)
    ! 1. predictor (previous acceleration held) and the line step to t + dt; a host-driven
    ! body already carries its t + dt state
    DO ib = 1, SIZE(rigid)
      IF (rigid(ib)%is_prescribed) CYCLE
      CALL CD_Rigid_Advance_Newmark(rigid(ib)%r, rigid(ib)%v, rigid(ib)%rot_mat, rigid(ib)%omega, rigid(ib)%a, &
                                    rigid(ib)%alpha, rigid(ib)%a, rigid(ib)%alpha, dt, CD_RIGID_NEWMARK_GAMMA, &
                                    CD_RIGID_NEWMARK_BETA, es, em)
      IF (es /= CD_RIGID_OK) THEN
        rigid = work%old_rigid
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: Rigid6 finite-rotation update failed: '//TRIM(em)
        RETURN
      END IF
      rigid(ib)%eta = CD_Log_SO3(MATMUL(rigid(ib)%rot_mat, TRANSPOSE(rigid(ib)%rot_ref)))
    END DO
    CALL scatter_rigid6_point_motion(system, points, rigid, work%q(1:system%n_system_coupled_dof), &
                                     work%v(1:system%n_system_coupled_dof), &
                                     work%a(1:system%n_system_coupled_dof))
    CALL CD_Update_System_Point_States(system, work%q(1:system%n_system_coupled_dof), &
                                       work%v(1:system%n_system_coupled_dof), &
                                       work%a(1:system%n_system_coupled_dof), es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      rigid = work%old_rigid
      system%points = work%old_points
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: Rigid6 point-state update failed: '//TRIM(em)
      RETURN
    END IF
    IF (ANY(detached)) THEN
      ! the body points hold the predictor just stored; the detached line ends move freely
      CALL CD_Step_System_DynamicPoints(system, dt, converged, stalled, n_iter, es, em, integrate=detached)
      IF (es == CD_SYSTEM_OK) THEN
        DO p = 1, SIZE(system%points)
          IF (.NOT. detached(p)) CYCLE
          base = CD_System_Point_Base(system, p)
          IF (base < 0) CYCLE
          work%q(base + 1:base + 3) = system%points(p)%q
          work%v(base + 1:base + 3) = system%points(p)%v
          work%a(base + 1:base + 3) = system%points(p)%a
        END DO
      END IF
    ELSE
      CALL CD_Step_System(system, dt, work%q(1:system%n_system_coupled_dof), &
                          work%v(1:system%n_system_coupled_dof), work%a(1:system%n_system_coupled_dof), &
                          converged, stalled, n_iter, es, em)
    END IF
    IF (es /= CD_SYSTEM_OK) THEN
      rigid = work%old_rigid
      system%points = work%old_points
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: Rigid6 line-system step failed: '//TRIM(em)
      RETURN
    END IF
    ! 2. corrector from the end-of-step line loads at the predictor
    CALL CD_Calc_System_CoupledLoads(system, work%loads(1:system%n_system_coupled_dof), es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      rigid = work%old_rigid
      system%points = work%old_points
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: Rigid6 coupled-load query failed: '//TRIM(em)
      RETURN
    END IF
    CALL CD_Calc_System_CoupledAccelDerivative(system, work%dload_da, es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      rigid = work%old_rigid
      system%points = work%old_points
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: Rigid6 line-end load-derivative query failed: '//TRIM(em)
      RETURN
    END IF
    DO ib = 1, SIZE(rigid)
      IF (rigid(ib)%is_prescribed) CYCLE
      dv0(1:3) = -CD_RIGID_NEWMARK_GAMMA*dt*work%old_rigid(ib)%a
      dv0(4:6) = -CD_RIGID_NEWMARK_GAMMA*dt*work%old_rigid(ib)%alpha
      CALL rigid6_body_acceleration(system, points, opts, rigid(ib), time, dt, dv0, work, ib, acc, alpha, &
                                    ErrStat, ErrMsg, bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        rigid = work%old_rigid
        system%points = work%old_points
        RETURN
      END IF
      ! the Newmark update from the start-of-step state with (a_n, a_{n+1})
      rigid(ib) = work%old_rigid(ib)
      CALL CD_Rigid_Advance_Newmark(rigid(ib)%r, rigid(ib)%v, rigid(ib)%rot_mat, rigid(ib)%omega, &
                                    work%old_rigid(ib)%a, work%old_rigid(ib)%alpha, acc, alpha, dt, &
                                    CD_RIGID_NEWMARK_GAMMA, CD_RIGID_NEWMARK_BETA, es, em)
      IF (es /= CD_RIGID_OK) THEN
        rigid = work%old_rigid
        system%points = work%old_points
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: Rigid6 finite-rotation update failed: '//TRIM(em)
        RETURN
      END IF
      rigid(ib)%a = acc
      rigid(ib)%alpha = alpha
      rigid(ib)%eta = CD_Log_SO3(MATMUL(rigid(ib)%rot_mat, TRANSPOSE(rigid(ib)%rot_ref)))
    END DO
    ! the Body<N> point records follow the corrected bodies
    CALL scatter_rigid6_point_motion(system, points, rigid, work%q(1:system%n_system_coupled_dof), &
                                     work%v(1:system%n_system_coupled_dof), &
                                     work%a(1:system%n_system_coupled_dof))
    CALL CD_Update_System_Point_States(system, work%q(1:system%n_system_coupled_dof), &
                                       work%v(1:system%n_system_coupled_dof), &
                                       work%a(1:system%n_system_coupled_dof), es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      rigid = work%old_rigid
      system%points = work%old_points
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: Rigid6 point-state update failed: '//TRIM(em)
      RETURN
    END IF
  END SUBROUTINE step_rigid6_once

  SUBROUTINE rigid_start_loads(system, q, v, a, loads, dload_da, ErrStat, ErrMsg)
    !! The coupled point motion, the line loads on the coupled points and their end-node
    !! inertia derivative at the current (start-of-step) line state.
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    REAL(wp), INTENT(OUT) :: q(:), v(:), a(:), loads(:), dload_da(:, :)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: es
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    CALL CD_Get_System_CoupledMotion(system, q, v, a, es, em)
    IF (es == CD_SYSTEM_OK) CALL CD_Calc_System_CoupledLoads(system, loads, es, em)
    IF (es == CD_SYSTEM_OK) CALL CD_Calc_System_CoupledAccelDerivative(system, dload_da, es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: initial rigid-body line-load query failed: '//TRIM(em)
    END IF
  END SUBROUTINE rigid_start_loads

  SUBROUTINE rigid6_body_acceleration(system, points, opts, body, time, dt, dv0, work, ib, acc, alpha, &
                                      ErrStat, ErrMsg, bathymetry)
    !! The acceleration of Rigid6 body ib at its current state and time from every body load
    !! and the line loads in work%loads (evaluated with the attachment accelerations work%a,
    !! end-node inertia derivative work%dload_da): rigid_coupled_acceleration with the step dt
    !! and velocity offset dv0 (dt = 0, dv0 = 0: the instantaneous acceleration). Stores the
    !! environment force and effective mass in work%f_env(:, ib) / work%mass_eff(ib).
    TYPE(CD_SystemType), INTENT(IN) :: system
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(RigidBodyState), INTENT(IN) :: body
    REAL(wp), INTENT(IN) :: time, dt, dv0(6)
    TYPE(RigidStepWorkspace), INTENT(INOUT) :: work
    INTEGER, INTENT(IN) :: ib
    REAL(wp), INTENT(OUT) :: acc(3), alpha(3)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    ! Rigid6 added mass is the isotropic translational rhoW*phi*Vol*Ca already folded into
    ! mass_eff (MoorDyn Body semantics: no rotational added inertia); body%inertia is about the CG.
    INTEGER :: ip, pidx, base
    INTEGER :: att_base(SIZE(body%point_indices))
    REAL(wp) :: att_arm(3, SIZE(body%point_indices))
    REAL(wp) :: f_body(3), f_seabed(3), m_global(3), m_seabed(3), f_attach(3), arm(3)
    REAL(wp) :: drag3(3, 3), load_dv(6, 6), cg6(6, 6), f_bias(3), m_bias(3)
    REAL(wp) :: f_rod(3), m_rod(3), rod6(6, 6), rodd6(6, 6)

    acc = CD_ZERO
    alpha = CD_ZERO
    CALL rigid6_environment_force(body, opts, time, work%f_env(:, ib), work%mass_eff(ib), drag3, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    ! weight at the CG, buoyancy at the CB, waterplane restoring in the heading frame
    CALL rigid6_hydrostatics(body, opts, time, f_body, m_global, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    ! CG offset: mass-matrix coupling blocks and the centripetal/gyroscopic terms about the reference
    CALL rigid6_cg_inertia(body, cg6, f_bias, m_bias)
    f_body = f_body + f_bias + work%f_env(:, ib)
    m_global = m_global + m_bias
    ! rods fixed to the body: their loads, mass and added mass about the reference point
    IF (ALLOCATED(body%att_rods)) THEN
      CALL rigid6_rod_loads(body, opts, time, f_rod, m_rod, rod6, rodd6, ErrStat, ErrMsg, bathymetry)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      f_body = f_body + f_rod
      m_global = m_global + m_rod
      cg6 = cg6 + rod6
    END IF
    CALL rigid6_seabed_contact(body, opts, f_seabed, m_seabed, load_dv, ErrStat, ErrMsg, bathymetry)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    f_body = f_body + f_seabed
    m_global = m_global + m_seabed
    ! velocity derivative of the non-line body loads (translational drag, seabed damping, rods,
    ! external damping)
    load_dv(1:3, 1:3) = load_dv(1:3, 1:3) + drag3
    IF (ALLOCATED(body%att_rods)) load_dv = load_dv + rodd6
    CALL rigid6_external_load(body, f_rod, drag3)
    f_body = f_body + f_rod
    load_dv(1:3, 1:3) = load_dv(1:3, 1:3) + drag3
    DO ip = 1, SIZE(body%point_indices)
      pidx = body%point_indices(ip)
      base = system_point_base(system, points(pidx)%id)
      arm = MATMUL(body%rot_mat, points(pidx)%body_offset)
      att_base(ip) = base
      att_arm(:, ip) = arm
      IF (base < 0) CYCLE
      f_attach = work%loads(base + 1:base + 3)
      f_body = f_body + f_attach
      m_global = m_global + cross3(arm, f_attach)
    END DO
    CALL rigid_coupled_acceleration(work%dload_da, dt, work%a(1:system%n_system_coupled_dof), att_base, att_arm, &
                                    work%mass_eff(ib), cg6, body%inertia, body%rot_mat, body%omega, &
                                    f_body, m_global, dv0, load_dv, acc, alpha, ErrStat, ErrMsg)
  END SUBROUTINE rigid6_body_acceleration

  SUBROUTINE step_prescribed_rigid6_system(system, points, opts, motion, rigid, time_index, time, dt, converged, &
                                           stalled, n_iter, ErrStat, ErrMsg, work, hydro_work)
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(MotionTable), INTENT(IN) :: motion
    TYPE(RigidBodyState), INTENT(INOUT) :: rigid(:)
    INTEGER, INTENT(IN) :: time_index
    REAL(wp), INTENT(IN) :: time, dt
    LOGICAL, INTENT(OUT) :: converged, stalled
    INTEGER, INTENT(OUT) :: n_iter, ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(RigidStepWorkspace), INTENT(INOUT) :: work
    TYPE(HydroUpdateWorkspace), INTENT(INOUT) :: hydro_work

    INTEGER :: es
    CHARACTER(160) :: em

    converged = .FALSE.
    stalled = .FALSE.
    n_iter = 0
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    CALL ensure_rigid_step_workspace(work, system%n_system_coupled_dof, SIZE(rigid), SIZE(system%points))
    work%old_rigid = rigid
    work%old_points = system%points
    CALL set_prescribed_rigid6_states(points, motion, time_index, rigid, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      rigid = work%old_rigid
      system%points = work%old_points
      RETURN
    END IF
    CALL apply_rigid6_states_to_system(system, points, rigid, work, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      rigid = work%old_rigid
      system%points = work%old_points
      RETURN
    END IF
    CALL update_system_line_hydro(system, opts, time, hydro_work, es, em)
    IF (es /= CD_DECKDRV_OK) THEN
      rigid = work%old_rigid
      system%points = work%old_points
      ErrStat = es
      ErrMsg = em
      RETURN
    END IF
    CALL CD_Step_System(system, dt, work%q(1:system%n_system_coupled_dof), &
                        work%v(1:system%n_system_coupled_dof), work%a(1:system%n_system_coupled_dof), &
                        converged, stalled, n_iter, es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      rigid = work%old_rigid
      system%points = work%old_points
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: prescribed Rigid6 line-system step failed: '//TRIM(em)
      RETURN
    END IF
  END SUBROUTINE step_prescribed_rigid6_system

  SUBROUTINE apply_rigid6_states_to_system(system, points, rigid, work, ErrStat, ErrMsg)
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(RigidBodyState), INTENT(IN) :: rigid(:)
    TYPE(RigidStepWorkspace), INTENT(INOUT) :: work
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: es
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    CALL ensure_rigid_step_workspace(work, system%n_system_coupled_dof, SIZE(rigid), SIZE(system%points))
    CALL CD_Get_System_CoupledMotion(system, work%q(1:system%n_system_coupled_dof), &
                                     work%v(1:system%n_system_coupled_dof), &
                                     work%a(1:system%n_system_coupled_dof), es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: prescribed Rigid6 coupled-motion query failed: '//TRIM(em)
      RETURN
    END IF
    CALL scatter_rigid6_point_motion(system, points, rigid, work%q(1:system%n_system_coupled_dof), &
                                     work%v(1:system%n_system_coupled_dof), &
                                     work%a(1:system%n_system_coupled_dof))
    CALL CD_Update_System_Point_States(system, work%q(1:system%n_system_coupled_dof), &
                                       work%v(1:system%n_system_coupled_dof), &
                                       work%a(1:system%n_system_coupled_dof), es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: prescribed Rigid6 point-state update failed: '//TRIM(em)
      RETURN
    END IF
  END SUBROUTINE apply_rigid6_states_to_system

  SUBROUTINE set_prescribed_rigid6_states(points, motion, time_index, rigid, ErrStat, ErrMsg)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(MotionTable), INTENT(IN) :: motion
    INTEGER, INTENT(IN) :: time_index
    TYPE(RigidBodyState), INTENT(INOUT) :: rigid(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: ib, ip, pidx, midx
    REAL(wp) :: qpt(3), vpt(3), apt(3), r_candidate(3), r_body(3), v_body(3), a_body(3)
    REAL(wp) :: tol
    LOGICAL :: have_body_state, is_translation

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (time_index < 1 .OR. time_index > motion%n_time) THEN
      CALL fail(ErrStat, ErrMsg, 'prescribed Rigid6 motion time index is outside the motion table')
      RETURN
    END IF
    tol = 1.0e-8_wp
    DO ib = 1, SIZE(rigid)
      have_body_state = .FALSE.
      is_translation = .TRUE.
      r_body = CD_ZERO
      v_body = CD_ZERO
      a_body = CD_ZERO
      DO ip = 1, SIZE(rigid(ib)%point_indices)
        pidx = rigid(ib)%point_indices(ip)
        midx = find_motion_point(motion, points(pidx)%id)
        IF (midx == 0) THEN
          CALL fail(ErrStat, ErrMsg, 'motionFile missing Body<N> point rows for prescribed Rigid6 BODY '// &
                    TRIM(int_to_str(rigid(ib)%body_id)))
          RETURN
        END IF
        qpt = motion%q(:, midx, time_index)
        vpt = motion%v(:, midx, time_index)
        apt = motion%a(:, midx, time_index)
        r_candidate = qpt - MATMUL(rigid(ib)%rot_ref, points(pidx)%body_offset)
        IF (.NOT. have_body_state) THEN
          r_body = r_candidate
          v_body = vpt
          a_body = apt
          have_body_state = .TRUE.
        ELSE
          IF (SQRT(SUM((r_candidate - r_body)**2)) > tol .OR. &
              SQRT(SUM((vpt - v_body)**2)) > tol .OR. SQRT(SUM((apt - a_body)**2)) > tol) THEN
            is_translation = .FALSE.
          END IF
        END IF
      END DO
      IF (.NOT. have_body_state) THEN
        CALL fail(ErrStat, ErrMsg, 'prescribed Rigid6 BODY has no Body<N> attachment points')
        RETURN
      END IF
      IF (is_translation) THEN
        rigid(ib)%r = r_body
        rigid(ib)%v = v_body
        rigid(ib)%a = a_body
        rigid(ib)%rot_mat = rigid(ib)%rot_ref
        rigid(ib)%omega = CD_ZERO
        rigid(ib)%alpha = CD_ZERO
        rigid(ib)%eta = CD_ZERO
      ELSE
        CALL recover_rigid6_motion(points, motion, time_index, rigid(ib), ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      END IF
    END DO
  END SUBROUTINE set_prescribed_rigid6_states

  SUBROUTINE recover_rigid6_motion(points, motion, time_index, body, ErrStat, ErrMsg)
    !! Recover the rigid 6-DOF motion (pose + spatial angular velocity/acceleration)
    !! of a prescribed Rigid6 body from its Body<N> attachment-point motion rows.
    !! Orientation via the Davenport q-method on the centered reference->current arm
    !! pairs (always a proper rotation, exact for planar attachment sets); omega and
    !! alpha via the symmetric 3x3 least-squares normal equations on the centered
    !! velocity/acceleration rows. Fails closed on collinear attachment geometry
    !! (rotation unobservable) and on rows that do not describe one rigid motion.
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(MotionTable), INTENT(IN) :: motion
    INTEGER, INTENT(IN) :: time_index
    TYPE(RigidBodyState), INTENT(INOUT) :: body
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    REAL(wp), PARAMETER :: FIT_TOL = 1.0e-6_wp
    REAL(wp), PARAMETER :: RANK_TOL = 1.0e-12_wp
    INTEGER :: n, ip, pidx, midx
    REAL(wp), ALLOCATABLE :: s0(:, :), qw(:, :), vw(:, :), aw(:, :), cw(:, :)
    REAL(wp) :: s0bar(3), qbar(3), vbar(3), abar(3)
    REAL(wp) :: bmat(3, 3), a0(3, 3), amat(3, 3), r_rel(3, 3)
    REAL(wp) :: rhs(3), omega(3), alpha(3), r_body(3), arm_bar(3), resid(3)
    REAL(wp) :: s2, scale_q, scale_v, scale_a, dvec(3)
    LOGICAL :: ok

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    n = SIZE(body%point_indices)
    ALLOCATE (s0(3, n), qw(3, n), vw(3, n), aw(3, n), cw(3, n))
    DO ip = 1, n
      pidx = body%point_indices(ip)
      midx = find_motion_point(motion, points(pidx)%id)
      s0(:, ip) = MATMUL(body%rot_ref, points(pidx)%body_offset)
      qw(:, ip) = motion%q(:, midx, time_index)
      vw(:, ip) = motion%v(:, midx, time_index)
      aw(:, ip) = motion%a(:, midx, time_index)
    END DO
    s0bar = SUM(s0, DIM=2)/REAL(n, wp)
    qbar = SUM(qw, DIM=2)/REAL(n, wp)
    vbar = SUM(vw, DIM=2)/REAL(n, wp)
    abar = SUM(aw, DIM=2)/REAL(n, wp)

    ! Rank guard on the centered reference arms: collinear attachments leave the
    ! rotation about the attachment axis unobservable -> only pure translation is
    ! prescribable for that geometry (and the caller has already ruled that out).
    a0 = CD_ZERO
    s2 = CD_ZERO
    DO ip = 1, n
      dvec = s0(:, ip) - s0bar
      s2 = s2 + SUM(dvec**2)
      a0(1, 1) = a0(1, 1) + SUM(dvec**2) - dvec(1)*dvec(1)
      a0(2, 2) = a0(2, 2) + SUM(dvec**2) - dvec(2)*dvec(2)
      a0(3, 3) = a0(3, 3) + SUM(dvec**2) - dvec(3)*dvec(3)
      a0(1, 2) = a0(1, 2) - dvec(1)*dvec(2)
      a0(1, 3) = a0(1, 3) - dvec(1)*dvec(3)
      a0(2, 3) = a0(2, 3) - dvec(2)*dvec(3)
    END DO
    a0(2, 1) = a0(1, 2)
    a0(3, 1) = a0(1, 3)
    a0(3, 2) = a0(2, 3)
    IF (s2 <= CD_ZERO .OR. det3(a0) <= RANK_TOL*s2**3) THEN
      CALL fail(ErrStat, ErrMsg, 'motionFile prescribed Rigid6 BODY '// &
                TRIM(int_to_str(body%body_id))//' is not a pure translation and its '// &
                'attachment geometry is collinear, so the rotation cannot be recovered')
      RETURN
    END IF

    ! Davenport q-method: R_rel = argmin sum |(q_i - qbar) - R (s0_i - s0bar)|^2.
    bmat = CD_ZERO
    DO ip = 1, n
      bmat = bmat + SPREAD(qw(:, ip) - qbar, DIM=2, NCOPIES=3)* &
             SPREAD(s0(:, ip) - s0bar, DIM=1, NCOPIES=3)
    END DO
    CALL davenport_rotation(bmat, r_rel, ok)
    IF (.NOT. ok) THEN
      CALL fail(ErrStat, ErrMsg, 'motionFile prescribed Rigid6 BODY '// &
                TRIM(int_to_str(body%body_id))//' rotation eigensolve failed')
      RETURN
    END IF
    r_body = qbar - MATMUL(r_rel, s0bar)

    ! Rigidity check: every row must sit on the recovered pose.
    scale_q = MAX(CD_ONE, SQRT(s2))
    DO ip = 1, n
      resid = qw(:, ip) - (r_body + MATMUL(r_rel, s0(:, ip)))
      IF (SQRT(SUM(resid**2)) > FIT_TOL*scale_q) THEN
        CALL fail(ErrStat, ErrMsg, 'motionFile prescribed Rigid6 BODY '// &
                  TRIM(int_to_str(body%body_id))//' rows do not describe a rigid motion '// &
                  '(position residual exceeds the rigid-fit tolerance)')
        RETURN
      END IF
      cw(:, ip) = MATMUL(r_rel, s0(:, ip) - s0bar)
    END DO

    ! Angular velocity: v_i - vbar = omega x c_i  ->  A omega = sum c_i x (v_i - vbar),
    ! A = sum (|c|^2 I - c c^T) (= a0 rotated by R_rel, same determinant/rank).
    amat = MATMUL(r_rel, MATMUL(a0, TRANSPOSE(r_rel)))
    rhs = CD_ZERO
    DO ip = 1, n
      rhs = rhs + cross3(cw(:, ip), vw(:, ip) - vbar)
    END DO
    CALL solve_sym3(amat, rhs, omega, ok)
    IF (.NOT. ok) THEN
      CALL fail(ErrStat, ErrMsg, 'motionFile prescribed Rigid6 BODY '// &
                TRIM(int_to_str(body%body_id))//' angular-velocity solve is singular')
      RETURN
    END IF
    scale_v = MAX(CD_ONE, MAXVAL(SQRT(SUM(vw**2, DIM=1))))
    DO ip = 1, n
      resid = vw(:, ip) - vbar - cross3(omega, cw(:, ip))
      IF (SQRT(SUM(resid**2)) > FIT_TOL*scale_v) THEN
        CALL fail(ErrStat, ErrMsg, 'motionFile prescribed Rigid6 BODY '// &
                  TRIM(int_to_str(body%body_id))//' rows do not describe a rigid motion '// &
                  '(velocity residual exceeds the rigid-fit tolerance)')
        RETURN
      END IF
    END DO

    ! Angular acceleration: a_i - abar - omega x (omega x c_i) = alpha x c_i.
    rhs = CD_ZERO
    DO ip = 1, n
      rhs = rhs + cross3(cw(:, ip), aw(:, ip) - abar - cross3(omega, cross3(omega, cw(:, ip))))
    END DO
    CALL solve_sym3(amat, rhs, alpha, ok)
    IF (.NOT. ok) THEN
      CALL fail(ErrStat, ErrMsg, 'motionFile prescribed Rigid6 BODY '// &
                TRIM(int_to_str(body%body_id))//' angular-acceleration solve is singular')
      RETURN
    END IF
    scale_a = MAX(CD_ONE, MAXVAL(SQRT(SUM(aw**2, DIM=1))))
    DO ip = 1, n
      resid = aw(:, ip) - abar - cross3(alpha, cw(:, ip)) - cross3(omega, cross3(omega, cw(:, ip)))
      IF (SQRT(SUM(resid**2)) > FIT_TOL*scale_a) THEN
        CALL fail(ErrStat, ErrMsg, 'motionFile prescribed Rigid6 BODY '// &
                  TRIM(int_to_str(body%body_id))//' rows do not describe a rigid motion '// &
                  '(acceleration residual exceeds the rigid-fit tolerance)')
        RETURN
      END IF
    END DO

    arm_bar = MATMUL(r_rel, s0bar)
    body%r = r_body
    body%v = vbar - cross3(omega, arm_bar)
    body%a = abar - cross3(alpha, arm_bar) - cross3(omega, cross3(omega, arm_bar))
    body%rot_mat = MATMUL(r_rel, body%rot_ref)
    body%omega = omega
    body%alpha = alpha
    body%eta = CD_Log_SO3(r_rel)
  END SUBROUTINE recover_rigid6_motion

  SUBROUTINE davenport_rotation(bmat, r_rel, ok)
    !! Davenport q-method (Wahba's problem, unit weights): the proper rotation
    !! maximizing tr(R^T B) is built from the eigenvector of the largest eigenvalue
    !! of the symmetric 4x4 K matrix. Layout: q = [q_vec(3); q_scalar].
    REAL(wp), INTENT(IN) :: bmat(3, 3)
    REAL(wp), INTENT(OUT) :: r_rel(3, 3)
    LOGICAL, INTENT(OUT) :: ok

    REAL(wp) :: kmat(4, 4), sigma, zvec(3), eig(4), work(32), qv(3), q0, qn
    INTEGER :: info
    EXTERNAL :: dsyev

    sigma = bmat(1, 1) + bmat(2, 2) + bmat(3, 3)
    zvec = [bmat(2, 3) - bmat(3, 2), bmat(3, 1) - bmat(1, 3), bmat(1, 2) - bmat(2, 1)]
    kmat(1:3, 1:3) = bmat + TRANSPOSE(bmat)
    kmat(1, 1) = kmat(1, 1) - sigma
    kmat(2, 2) = kmat(2, 2) - sigma
    kmat(3, 3) = kmat(3, 3) - sigma
    kmat(1:3, 4) = zvec
    kmat(4, 1:3) = zvec
    kmat(4, 4) = sigma
    CALL dsyev('V', 'U', 4, kmat, 4, eig, work, SIZE(work), info)
    ok = (info == 0)
    IF (.NOT. ok) THEN
      r_rel = CD_ZERO
      RETURN
    END IF
    qv = kmat(1:3, 4)
    q0 = kmat(4, 4)
    qn = SQRT(SUM(qv**2) + q0**2)
    qv = qv/qn
    q0 = q0/qn
    ! b = A r attitude matrix for q = [qv; q0] (Markley & Mortari convention):
    ! A = (q0^2 - |qv|^2) I + 2 qv qv^T - 2 q0 [qv]_x.
    r_rel(1, 1) = q0*q0 - SUM(qv**2) + 2.0_wp*qv(1)*qv(1)
    r_rel(2, 2) = q0*q0 - SUM(qv**2) + 2.0_wp*qv(2)*qv(2)
    r_rel(3, 3) = q0*q0 - SUM(qv**2) + 2.0_wp*qv(3)*qv(3)
    r_rel(1, 2) = 2.0_wp*qv(1)*qv(2) + 2.0_wp*q0*qv(3)
    r_rel(2, 1) = 2.0_wp*qv(1)*qv(2) - 2.0_wp*q0*qv(3)
    r_rel(1, 3) = 2.0_wp*qv(1)*qv(3) - 2.0_wp*q0*qv(2)
    r_rel(3, 1) = 2.0_wp*qv(1)*qv(3) + 2.0_wp*q0*qv(2)
    r_rel(2, 3) = 2.0_wp*qv(2)*qv(3) + 2.0_wp*q0*qv(1)
    r_rel(3, 2) = 2.0_wp*qv(2)*qv(3) - 2.0_wp*q0*qv(1)
  END SUBROUTINE davenport_rotation

  PURE FUNCTION det3(m) RESULT(d)
    REAL(wp), INTENT(IN) :: m(3, 3)
    REAL(wp) :: d
    d = m(1, 1)*(m(2, 2)*m(3, 3) - m(2, 3)*m(3, 2)) - &
        m(1, 2)*(m(2, 1)*m(3, 3) - m(2, 3)*m(3, 1)) + &
        m(1, 3)*(m(2, 1)*m(3, 2) - m(2, 2)*m(3, 1))
  END FUNCTION det3

  SUBROUTINE solve_sym3(a, b, x, ok)
    !! Cramer solve of the symmetric positive-definite 3x3 normal equations with a
    !! determinant guard (the caller's rank check makes a true singularity an internal
    !! inconsistency, not an input error, but fail closed anyway).
    REAL(wp), INTENT(IN) :: a(3, 3), b(3)
    REAL(wp), INTENT(OUT) :: x(3)
    LOGICAL, INTENT(OUT) :: ok

    REAL(wp) :: d, m(3, 3)
    INTEGER :: j

    d = det3(a)
    ok = (ABS(d) > TINY(CD_ONE)*1.0e6_wp)
    IF (.NOT. ok) THEN
      x = CD_ZERO
      RETURN
    END IF
    DO j = 1, 3
      m = a
      m(:, j) = b
      x(j) = det3(m)/d
    END DO
  END SUBROUTINE solve_sym3

  SUBROUTINE rigid6_seabed_contact(body, opts, force, moment, load_dv, ErrStat, ErrMsg, bathymetry)
    !! One-sided seabed contact for the Rigid6 reference point. A Rigid6 body declares no
    !! contact footprint (and a MoorDyn Body has no seabed contact at all), so the per-area
    !! kBot/cBot (N/m^3, N.s/m^3) act over a fixed reference contact area
    !! RIGID6_CONTACT_AREA = 1 m^2: k = kBot*1 m^2 [N/m], c = cBot*1 m^2 [N.s/m]. This is a
    !! penalty that keeps the reference point out of the bed, not a footprint model.
    !! load_dv returns the 6x6 derivative of the normal damping force w.r.t. the body
    !! (velocity, angular velocity), which the rigid-body step applies implicitly; the spring
    !! and the regularized friction act at the evaluated position and velocity.
    TYPE(RigidBodyState), INTENT(IN) :: body
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(OUT) :: force(3), moment(3), load_dv(6, 6)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    REAL(wp), PARAMETER :: vreg = 1.0e-3_wp
    REAL(wp), PARAMETER :: RIGID6_CONTACT_AREA = CD_ONE
    REAL(wp) :: z_floor, penetration, normal, denom
    LOGICAL :: has_floor

    force = CD_ZERO
    moment = CD_ZERO
    load_dv = CD_ZERO
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    CALL deck_seabed_floor_at(body%r(1), body%r(2), opts, has_floor, z_floor, ErrStat, ErrMsg, bathymetry)
    IF (ErrStat /= CD_DECKDRV_OK .OR. .NOT. has_floor) RETURN
    penetration = z_floor - body%r(3)
    IF (penetration <= CD_ZERO) RETURN
    normal = opts%kbot*RIGID6_CONTACT_AREA*penetration
    IF (body%v(3) < CD_ZERO) THEN
      normal = normal - opts%cbot*RIGID6_CONTACT_AREA*body%v(3)
      load_dv(3, 3) = -opts%cbot*RIGID6_CONTACT_AREA
    END IF
    IF (opts%has_friction) THEN
      denom = SQRT(body%v(1)**2 + body%v(2)**2 + vreg**2)
      force(1) = -opts%friction_mu*normal*body%v(1)/denom
      force(2) = -opts%friction_mu*normal*body%v(2)/denom
    END IF
    force(3) = normal
  END SUBROUTINE rigid6_seabed_contact

  SUBROUTINE deck_seabed_floor_at(x, y, opts, has_floor, z_floor, ErrStat, ErrMsg, bathymetry)
    !! Resolve the active seabed elevation from structured bathymetry or flat WtrDpth.
    REAL(wp), INTENT(IN) :: x, y
    TYPE(DeckOptions), INTENT(IN) :: opts
    LOGICAL, INTENT(OUT) :: has_floor
    REAL(wp), INTENT(OUT) :: z_floor
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    INTEGER :: es
    CHARACTER(160) :: em
    LOGICAL :: bathy_ready

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    has_floor = .FALSE.
    z_floor = CD_ZERO
    ! Precompute, NOT `.AND.`: Fortran does not guarantee short-circuit, so evaluating
    ! CD_Bathymetry_Is_Initialized (non-optional dummy) on an absent OPTIONAL bathymetry
    ! is non-conforming (F2018 15.5.2.12) and dereferences it at -O0.
    bathy_ready = .FALSE.
    IF (PRESENT(bathymetry)) bathy_ready = CD_Bathymetry_Is_Initialized(bathymetry)
    IF (bathy_ready) THEN
      CALL CD_Bathymetry_Floor(bathymetry, x, y, z_floor, es, em)
      IF (es /= CD_BATHY_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'deck bathymetry floor query failed: '//TRIM(em))
        RETURN
      END IF
      has_floor = .TRUE.
    ELSE IF (opts%has_wtrdpth) THEN
      z_floor = -opts%wtrdpth
      has_floor = .TRUE.
    END IF
  END SUBROUTINE deck_seabed_floor_at

  SUBROUTINE rigid6_wet_fraction(body, opts, time, phi, ErrStat, ErrMsg)
    !! Submerged fraction phi of a Rigid6 body. bodyWetting sphere (default): an equivalent
    !! sphere of the body volume, r_e = (3 V/(4 pi))^(1/3), centred at the centre of buoyancy,
    !! immersed to h = clamp(eta - (z_cb - r_e), 0, 2 r_e): phi = pi h^2 (3 r_e - h)/(3 V), zero
    !! when dry and continuous (C1) through the surface. A body without volume uses a sphere of
    !! projected area CdA. bodyWetting moordyn, and a body with waterplane stiffness
    !! (C33/C44/C55, a surface-piercing hull given as data): phi = 1.
    TYPE(RigidBodyState), INTENT(IN) :: body
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time
    REAL(wp), INTENT(OUT) :: phi
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: es
    REAL(wp) :: x_cb(3), eta, u(3), du(3), r_e, h
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    phi = CD_ONE
    IF (opts%body_wetting_moordyn .OR. rigid6_has_waterplane(body)) RETURN
    x_cb = body%r + MATMUL(body%rot_mat, body%cb)
    eta = CD_ZERO
    IF (body%has_held) THEN
      eta = body%held_eta
    ELSE IF (opts%has_wave) THEN
      CALL deck_wave_kinematics(opts, x_cb(1), x_cb(2), x_cb(3), time, eta, u, du, es, em)
      IF (es /= CD_HYDRO_OK) THEN
        ErrStat = CD_DECKDRV_BADINPUT
        ErrMsg = 'CableDyn_DeckDriver: Rigid6 wave kinematics failed: '//TRIM(em)
        RETURN
      END IF
    END IF
    IF (body%vol > CD_ZERO) THEN
      r_e = (3.0_wp*body%vol/(16.0_wp*QUARTER_PI))**(CD_ONE/3.0_wp)
    ELSE
      r_e = SQRT(MAX(CD_ZERO, body%cda)/(4.0_wp*QUARTER_PI))
    END IF
    IF (.NOT. (r_e > CD_ZERO)) THEN
      phi = MERGE(CD_ONE, CD_ZERO, x_cb(3) <= eta)
      RETURN
    END IF
    h = MIN(2.0_wp*r_e, MAX(CD_ZERO, eta - (x_cb(3) - r_e)))
    phi = h*h*(3.0_wp*r_e - h)/(4.0_wp*r_e**3)
  END SUBROUTINE rigid6_wet_fraction

  PURE LOGICAL FUNCTION rigid6_has_waterplane(body) RESULT(has)
    !! A body with hydrostatic stiffness data describes a surface-piercing hull: its buoyancy is
    !! the full Volume at the reference pose plus the linear restoring.
    TYPE(RigidBodyState), INTENT(IN) :: body
    has = ABS(body%c33) > CD_ZERO .OR. ABS(body%c44) > CD_ZERO .OR. ABS(body%c55) > CD_ZERO
  END FUNCTION rigid6_has_waterplane

  SUBROUTINE rigid6_hydrostatics(body, opts, time, force, moment, ErrStat, ErrMsg)
    !! Weight, buoyancy and hydrostatic restoring of a Rigid6 body about its reference point:
    !! the weight -m g at the centre of gravity, the buoyancy rhoW g phi V at the centre of
    !! buoyancy (phi from rigid6_wet_fraction), and the linear waterplane restoring
    !!   F_z = -C33 dz,  M = -C44 tau1 h1 - C55 tau2 h2,
    !! where tau is the tilt rotation vector that carries the vertical to the body axis that was
    !! vertical at the deck pose, h1 the horizontal projection of the body x axis R e1 (the
    !! heading; from R e2 turned by -90 deg when the x axis points up) and h2 = e3 x h1,
    !! tau_i = tau.h_i. The moment is thereby taken about the body's own roll and pitch axes at
    !! any heading.
    TYPE(RigidBodyState), INTENT(IN) :: body
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time
    REAL(wp), INTENT(OUT) :: force(3), moment(3)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp) :: phi, f_g(3), f_b(3), n(3), axis(3), sn, cn, tau(3), h1(3), h2(3), xb(3), rel(3, 3)
    REAL(wp), PARAMETER :: e3(3) = [CD_ZERO, CD_ZERO, CD_ONE]

    force = CD_ZERO
    moment = CD_ZERO
    CALL rigid6_wet_fraction(body, opts, time, phi, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    f_g = [CD_ZERO, CD_ZERO, -body%mass*opts%g]
    f_b = [CD_ZERO, CD_ZERO, opts%rhoW*phi*body%vol*opts%g]
    force = f_g + f_b
    moment = cross3(MATMUL(body%rot_mat, body%cg), f_g) + cross3(MATMUL(body%rot_mat, body%cb), f_b)
    IF (.NOT. rigid6_has_waterplane(body)) RETURN
    force(3) = force(3) - body%c33*(body%r(3) - body%r_ref(3))
    IF (ABS(body%c44) <= CD_ZERO .AND. ABS(body%c55) <= CD_ZERO) RETURN
    rel = MATMUL(body%rot_mat, TRANSPOSE(body%rot_ref))
    n = rel(:, 3)
    axis = cross3(e3, n)
    sn = NORM2(axis)
    cn = n(3)
    tau = CD_ZERO
    IF (sn > CD_ZERO) tau = ATAN2(sn, cn)*axis/sn
    xb = body%rot_mat(:, 1)
    h1 = [xb(1), xb(2), CD_ZERO]
    IF (NORM2(h1) < 1.0e-6_wp) THEN
      xb = body%rot_mat(:, 2)
      h1 = cross3([xb(1), xb(2), CD_ZERO], e3)
    END IF
    h1 = h1/NORM2(h1)
    h2 = cross3(e3, h1)
    moment = moment - body%c44*DOT_PRODUCT(tau, h1)*h1 - body%c55*DOT_PRODUCT(tau, h2)*h2
  END SUBROUTINE rigid6_hydrostatics

  SUBROUTINE rigid6_cg_inertia(body, cg6, f_bias, m_bias)
    !! The centre-of-gravity offset c = R cg of a Rigid6 body about its reference point: the
    !! coupling blocks cg6 = [[0, -m [c]x], [m [c]x, -m [c]x [c]x]] that complete
    !! diag(m I, R J_cg R^T) to the rigid-body mass matrix about the reference point, and the
    !! velocity terms of the equations of motion about it that the diagonal form leaves out:
    !!   f_bias = -m w x (w x c),   m_bias = m w x (c x (c x w)).
    TYPE(RigidBodyState), INTENT(IN) :: body
    REAL(wp), INTENT(OUT) :: cg6(6, 6), f_bias(3), m_bias(3)
    REAL(wp) :: c(3), s(3, 3)
    c = MATMUL(body%rot_mat, body%cg)
    s = skew3(c)
    cg6 = CD_ZERO
    cg6(1:3, 4:6) = -body%mass*s
    cg6(4:6, 1:3) = body%mass*s
    cg6(4:6, 4:6) = -body%mass*MATMUL(s, s)
    f_bias = -body%mass*cross3(body%omega, cross3(body%omega, c))
    m_bias = body%mass*cross3(body%omega, cross3(c, cross3(c, body%omega)))
  END SUBROUTINE rigid6_cg_inertia

  SUBROUTINE rigid6_environment_force(body, opts, time, force, effective_mass, drag_dv, ErrStat, ErrMsg)
    !! Lumped translational Morison force on a Rigid6 reference point, and the 3x3 derivative
    !! drag_dv of the quadratic drag w.r.t. the body velocity,
    !!   d/dv [c |rel| rel] = -c (|rel| I + rel rel^T/|rel|),  rel = u - v,  c = rhoW phi CdA/2,
    !! which the rigid-body step uses to treat the drag implicitly. Drag, fluid inertia
    !! rhoW phi V (1 + Ca) du (omitted with bodyHydro moordyn, as in MoorDyn) and added mass
    !! rhoW phi V Ca scale with the submerged fraction phi (rigid6_wet_fraction), so they fade in
    !! continuously as the body crosses the surface. Fluid kinematics come from the host-held
    !! sample (coupled runs) or the deck wave/current model at the reference point.
    TYPE(RigidBodyState), INTENT(IN) :: body
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time
    REAL(wp), INTENT(OUT) :: force(3), effective_mass, drag_dv(3, 3)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: es
    REAL(wp) :: eta, rel(3), rel_speed, fluid_velocity(3), fluid_acceleration(3), phi, fk
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    force = CD_ZERO
    drag_dv = CD_ZERO
    effective_mass = body%mass
    CALL rigid6_wet_fraction(body, opts, time, phi, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK .OR. .NOT. (phi > CD_ZERO)) RETURN

    fluid_velocity = CD_ZERO
    fluid_acceleration = CD_ZERO
    eta = CD_ZERO
    IF (body%has_held) THEN
      ! COUPLED fluid contract: the host (SeaState via the aggregate) has sampled the ambient
      ! field at this body's reference point and stored it on the body.
      fluid_velocity = body%held_vel
      fluid_acceleration = body%held_acc
    ELSE
      IF (opts%has_wave) THEN
        CALL deck_wave_kinematics(opts, body%r(1), body%r(2), body%r(3), time, eta, fluid_velocity, &
                                  fluid_acceleration, es, em)
        IF (es /= CD_HYDRO_OK) THEN
          ErrStat = CD_DECKDRV_BADINPUT
          ErrMsg = 'CableDyn_DeckDriver: Rigid6 wave kinematics failed: '//TRIM(em)
          RETURN
        END IF
      END IF
      IF (opts%has_current) THEN
        fluid_velocity = fluid_velocity + deck_current_velocity(opts, body%r(3), es, em)
        IF (es /= CD_HYDRO_OK) THEN
          ErrStat = CD_DECKDRV_BADINPUT
          ErrMsg = 'CableDyn_DeckDriver: Rigid6 current profile failed: '//TRIM(em)
          RETURN
        END IF
      END IF
    END IF

    effective_mass = body%mass + phi*opts%rhoW*body%vol*body%ca
    ! Drag uses the relative velocity (fluid - body), so a body moving in still water
    ! (fluid_velocity = 0 -> rel = -v) is damped exactly like a run with an explicit zero current.
    rel = fluid_velocity - body%v
    rel_speed = SQRT(SUM(rel*rel))
    fk = CD_ONE + body%ca
    IF (opts%body_hydro_moordyn) fk = CD_ZERO
    force = 0.5_wp*opts%rhoW*phi*body%cda*rel_speed*rel + opts%rhoW*phi*body%vol*fk*fluid_acceleration
    drag_dv = rigid6_drag_derivative(0.5_wp*opts%rhoW*phi*body%cda, rel, rel_speed)
  END SUBROUTINE rigid6_environment_force

  PURE FUNCTION rigid6_drag_derivative(coef, rel, rel_speed) RESULT(d)
    !! d/dv of coef*|rel|*rel with rel = u - v: -coef*(|rel| I + rel rel^T/|rel|) (zero at rest).
    REAL(wp), INTENT(IN) :: coef, rel(3), rel_speed
    REAL(wp) :: d(3, 3)
    INTEGER :: k
    d = CD_ZERO
    IF (.NOT. (rel_speed > CD_ZERO)) RETURN
    d = -coef*SPREAD(rel, DIM=2, NCOPIES=3)*SPREAD(rel, DIM=1, NCOPIES=3)/rel_speed
    DO k = 1, 3
      d(k, k) = d(k, k) - coef*rel_speed
    END DO
  END FUNCTION rigid6_drag_derivative

  SUBROUTINE write_hermite_dynamic_out(out_root, channels, lines, points, opts, cables, converged, ErrStat, ErrMsg, &
                                       bathymetry)
    !! Standalone finite-EI march on the same production cubic-Hermite lifecycle used by
    !! the aggregate/OpenFAST route, for suspended and seabed-contact cables.
    CHARACTER(*), INTENT(IN) :: out_root
    CHARACTER(NAMELEN), INTENT(IN) :: channels(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(CD_HFMF_ModuleType), INTENT(INOUT) :: cables(:)
    LOGICAL, INTENT(OUT) :: converged
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    INTEGER :: unit, ios, step, nstep, i, es, pidx, tensile_events, tensile_element
    INTEGER :: recovery_events, recovery_max_used
    INTEGER, ALLOCATABLE :: pos_units(:), ten_units(:)
    CHARACTER(LEN(out_root) + 8) :: path
    CHARACTER(256) :: em
    REAL(wp) :: t, up(3), uv(3), ua(3), tensile_force, tensile_threshold, tensile_xi, tensile_time, turn
    ! Per-step tangent turn [deg] above which the time-step note is printed (see below).
    REAL(wp), PARAMETER :: TURN_NOTE_FORCE_BLEND = 0.25_wp, TURN_NOTE_CONFIG_BLEND = 0.1_wp
    REAL(wp), PARAMETER :: RAD2DEG = 57.29577951308232_wp
    TYPE(MotionTable) :: motion
    TYPE(DriverProgress) :: progress
    TYPE(CD_RangeSet) :: ranges

    converged = .FALSE.; ErrStat = CD_DECKDRV_OK; ErrMsg = ''
    nstep = NINT(opts%tmax/opts%dtM)
    IF (SIZE(cables) /= SIZE(lines)) THEN
      CALL fail(ErrStat, ErrMsg, 'Hermite standalone cable count does not match line count'); RETURN
    END IF
    IF (opts%has_motion_file) THEN
      CALL read_motion_file(opts%motion_file, points, opts, motion, ErrStat, ErrMsg, &
                            with_roll=ANY([(line_torsion_active(lines(i)), i=1, SIZE(lines))]))
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL check_motion_roll(ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      ! Install row 1 without advancing the cable clock. The first pass makes the
      ! t=0 fluid sample use the prescribed geometry. The held-field setter refreshes
      ! the consistent free acceleration and deliberately zeros fixed DOFs, so repeat
      ! the boundary transfer afterwards to preserve the prescribed q/v/a verbatim.
      CALL apply_motion_to_hermite_cables(cables, lines, points, motion, 1, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END IF
    CALL update_hermite_deck_fluid(cables, opts, CD_ZERO, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    IF (opts%has_motion_file) THEN
      CALL apply_motion_to_hermite_cables(cables, lines, points, motion, 1, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      ! Row 1 is now the committed boundary q/v/a and the t=0 fluid field is installed.
      ! Recompute the free-node predictor from the COMPLETE structural/contact/hydro
      ! residual at that state, while the HFMF hook preserves the prescribed boundary
      ! acceleration. This explicit lifecycle station prevents a motion/contact deck
      ! from carrying the pre-motion contact acceleration into its first implicit step.
      DO i = 1, SIZE(cables)
        CALL CD_HFMF_Refresh_Acceleration(cables(i), es, em)
        IF (es /= CD_HFMF_OK) THEN
          CALL fail_solve(ErrStat, ErrMsg, 'Hermite row-1 acceleration refresh failed: '//TRIM(em)); RETURN
        END IF
      END DO
    END IF

    CALL range_setup_planned(ranges, lines, channels, opts, ErrStat, ErrMsg, cables=cables, bathymetry=bathymetry)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    path = TRIM(out_root)//'.out'
    OPEN (NEWUNIT=unit, FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open output file: '//TRIM(path)); RETURN
    END IF
    WRITE (unit, '(A)') '# CableDyn driver output (finite-EI dynamic; production cubic-Hermite route)'
    CALL write_header(unit, channels)
    CALL open_dynamic_hermite_line_outputs(out_root, lines, cables, pos_units, ten_units, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CLOSE (unit); RETURN
    END IF
    CALL write_hermite_model_row(unit, CD_ZERO, channels, lines, points, cables, ErrStat, ErrMsg, &
                                 motion=motion, motion_time_index=MERGE(1, 0, opts%has_motion_file), &
                                 has_motion=opts%has_motion_file, ranges=ranges)
    IF (ErrStat == CD_DECKDRV_OK) &
      CALL write_hermite_static_profile(out_root, lines, cables, ErrStat, ErrMsg)
    IF (ErrStat == CD_DECKDRV_OK) &
      CALL write_dynamic_hermite_line_outputs(CD_ZERO, lines, cables, pos_units, ten_units, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CLOSE (unit); CALL close_dynamic_line_outputs(pos_units, ten_units); RETURN
    END IF

    CALL start_driver_progress(progress, nstep, opts%dtM)
    DO step = 1, nstep
      t = REAL(step, wp)*opts%dtM
      CALL update_hermite_deck_fluid(cables, opts, t, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) EXIT
      DO i = 1, SIZE(cables)
        IF (opts%has_motion_file) THEN
          pidx = find_point(points, lines(i)%nodeA)
          CALL prescribed_point_state(points(pidx), motion, step + 1, up, uv, ua, ErrStat, ErrMsg)
          IF (ErrStat /= CD_DECKDRV_OK) EXIT
        ELSE
          CALL CD_HFMF_GetCoupledKinematics(cables(i), up, uv, ua, es, em)
          IF (es /= CD_HFMF_OK) THEN
            ErrStat = CD_DECKDRV_SOLVEFAIL
            ErrMsg = 'CableDyn_DeckDriver: Hermite endpoint query failed: '//TRIM(em); EXIT
          END IF
          uv = CD_ZERO; ua = CD_ZERO
        END IF
        IF (motion%has_rot) THEN
          ! vessel motion: the fairlead end connection turns with the vessel (the DCM is
          ! global-to-vessel, the transpose of the vessel rotation)
          CALL CD_HFMF_UpdateStates(cables(i), up, uv, ua, es, em, &
                                    u_orientation=TRANSPOSE(motion%rot(:, :, step + 1)), &
                                    u_angular_velocity=motion%omega(:, step + 1), &
                                    u_angular_acceleration=motion%alpha(:, step + 1))
        ELSE IF (motion%has_roll .AND. line_torsion_active(lines(i)) .AND. &
                 find_motion_point(motion, lines(i)%nodeA) > 0) THEN
          ! imposed roll of End A about its director: Phi = Pretwist(B) - (Pretwist(A) + roll)
          CALL CD_HFMF_UpdateStates(cables(i), up, uv, ua, es, em, &
                                    u_twist=lines(i)%tors_pretwist(2) - lines(i)%tors_pretwist(1) - &
                                    motion%roll(find_motion_point(motion, lines(i)%nodeA), step + 1))
        ELSE
          CALL CD_HFMF_UpdateStates(cables(i), up, uv, ua, es, em)
        END IF
        IF (es /= CD_HFMF_OK) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: Hermite standalone step failed: '//TRIM(em); EXIT
        END IF
      END DO
      IF (ErrStat /= CD_DECKDRV_OK) EXIT
      CALL write_hermite_model_row(unit, t, channels, lines, points, cables, ErrStat, ErrMsg, &
                                   motion=motion, motion_time_index=MERGE(step + 1, 0, opts%has_motion_file), &
                                   has_motion=opts%has_motion_file, ranges=ranges)
      IF (ErrStat == CD_DECKDRV_OK) &
        CALL write_dynamic_hermite_line_outputs(t, lines, cables, pos_units, ten_units, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) EXIT
      CALL update_driver_progress(progress, step, t)
    END DO
    CLOSE (unit)
    CALL close_dynamic_line_outputs(pos_units, ten_units)
    IF (opts%tensile_mode == CD_HCDYN_TENSILE_WARN) THEN
      DO i = 1, SIZE(cables)
        CALL CD_HFMF_Get_Tensile_Diagnostics(cables(i), tensile_events, tensile_force, &
                                             tensile_threshold, tensile_element, tensile_xi, tensile_time, es, em)
        IF (es == CD_HFMF_OK) THEN
          IF (tensile_events > 0) THEN
            WRITE (output_unit, '(A,I0,A,I0,A,ES12.4,A,ES12.4,A,I0,A,F7.4,A,F12.5,A)') &
              '  Tensile monitor: line ', lines(i)%id, ' recorded ', tensile_events, &
              ' accepted integration-step event(s); worst element-mean axial force=', tensile_force, &
              ' N, threshold=-', tensile_threshold, ' N, element=', tensile_element, ', xi=', tensile_xi, &
              ', t=', tensile_time, ' s.'
          ELSE
            WRITE (output_unit, '(A,I0,A)') '  Tensile monitor: line ', lines(i)%id, &
              ' recorded no compression events.'
          END IF
        END IF
      END DO
    END IF
    ! Time-step audit: the largest turn of a nodal tangent over one step measures how well
    ! dtM resolves the rotation of the line. Calibrated on the GoM 80 m lazy-wave cable under
    ! 3 m / 12 s surge and heave: with the configuration blend the mean hang-off tension
    ! erred by 34 / 8 / 2 % at 0.63 / 0.31 / 0.16 deg per step; with the force blend it erred
    ! by up to 15 / 1.2 / 0.3 % at 0.57 / 0.28 / 0.14 deg per step (heave). It is accuracy
    ! advice for a completed run, so a failed march (its own diagnostic) skips it.
    DO i = 1, SIZE(cables)
      IF (ErrStat /= CD_DECKDRV_OK) EXIT
      turn = CD_HermiteCable_Dyn_Max_Step_Rotation(cables(i)%line)*RAD2DEG
      IF (opts%alpha_force_blend .AND. turn > TURN_NOTE_FORCE_BLEND) THEN
        WRITE (output_unit, '(A,I0,A,F7.3,A)') '  Note: line ', lines(i)%id, ': a nodal tangent turned up to ', &
          turn, ' deg in one step; a smaller dtM would resolve the line''s rotation (mean tension errors of '// &
          'about 1 % and more above 0.25 deg per step).'
      ELSE IF (.NOT. opts%alpha_force_blend .AND. turn > TURN_NOTE_CONFIG_BLEND) THEN
        WRITE (output_unit, '(A,I0,A,F7.3,A)') '  Note: line ', lines(i)%id, ': a nodal tangent turned up to ', &
          turn, ' deg in one step; with the configuration blend this inflates the mean tension (about 2 % '// &
          'at 0.16 deg per step): set True alpha_force_blend or a smaller dtM.'
      END IF
    END DO
    DO i = 1, SIZE(cables)
      CALL CD_HFMF_Get_Recovery_Diagnostics(cables(i), recovery_events, recovery_max_used, es, em)
      IF (es == CD_HFMF_OK .AND. recovery_events > 0) THEN
        WRITE (output_unit, '(A,I0,A,I0,A,I0,A)') '  Recovery audit: line ', lines(i)%id, &
          ' subdivided ', recovery_events, ' nominal interval(s); maximum substeps used=', &
          recovery_max_used, '.'
      END IF
    END DO
    converged = ErrStat == CD_DECKDRV_OK
    IF (converged) CALL range_write(ranges, out_root, ErrStat, ErrMsg)
    converged = ErrStat == CD_DECKDRV_OK

  CONTAINS

    SUBROUTINE check_motion_roll(est, emt)
      !! The motionFile roll column drives a torsional line through its End A point only, and
      !! starts from the static state (roll 0 at t = 0; a constant twist is the Pretwist).
      INTEGER, INTENT(OUT) :: est
      CHARACTER(*), INTENT(OUT) :: emt
      INTEGER :: ip, li
      LOGICAL :: used
      est = CD_DECKDRV_OK
      emt = ''
      IF (.NOT. motion%has_roll) RETURN
      DO ip = 1, motion%n_point
        IF (.NOT. ANY(ABS(motion%roll(ip, :)) > CD_ZERO)) CYCLE
        used = .FALSE.
        DO li = 1, SIZE(lines)
          IF (lines(li)%nodeA == motion%point_ids(ip) .AND. line_torsion_active(lines(li))) used = .TRUE.
        END DO
        IF (.NOT. used) THEN
          CALL fail(est, emt, 'motionFile: point '//TRIM(int_to_str(motion%point_ids(ip)))//' has a non-zero roll '// &
                    'column, but no line restrained in torsion at both ends (END CONNECTIONS TorsStiffness) '// &
                    'has its End A there'); RETURN
        END IF
        IF (ABS(motion%roll(ip, 1)) > CD_ZERO) THEN
          CALL fail(est, emt, 'motionFile: the roll column of point '//TRIM(int_to_str(motion%point_ids(ip)))// &
                    ' must be 0 at t = 0 (the static solve uses the END CONNECTIONS Pretwist, which takes a '// &
                    'constant twist)'); RETURN
        END IF
      END DO
    END SUBROUTINE check_motion_roll
  END SUBROUTINE write_hermite_dynamic_out

  SUBROUTINE write_hermite_static_profile(out_root, lines, cables, ErrStat, ErrMsg)
    !! Persist the converged finite-EI initialization as the same engineering range
    !! table emitted by the coupled OpenFAST facade.  This is independent of OUTPUTS:
    !! every node is available for touchdown, curvature, and tension inspection.
    CHARACTER(*), INTENT(IN) :: out_root
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cables(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: unit, ios, li, node, nn
    REAL(wp) :: s, xyz(3), xyz_prev(3), tension, curvature, bend_moment, declination, azimuth
    CHARACTER(NAMELEN) :: channel
    CHARACTER(LEN(out_root) + 16) :: path
    CHARACTER(1) :: tab

    ErrStat = CD_DECKDRV_OK; ErrMsg = ''
    IF (SIZE(lines) /= SIZE(cables)) THEN
      CALL fail(ErrStat, ErrMsg, 'Hermite static-profile cable count does not match line count'); RETURN
    END IF
    path = TRIM(out_root)//'.static.out'
    OPEN (NEWUNIT=unit, FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open Hermite static profile: '//TRIM(path)); RETURN
    END IF
    tab = CHAR(9)
    WRITE (unit, '(A)') 'CableDyn standalone static configuration (deformed arc; public node order End A -> End B)'
    WRITE (unit, '(A)') 'LineID'//tab//'Node'//tab//'ArcLength'//tab//'X'//tab//'Y'//tab//'Z'//tab// &
      'Tension'//tab//'Curvature'//tab//'BendMoment'//tab//'Declination'//tab//'Inclination'//tab//'Azimuth'
    WRITE (unit, '(A)') '(-)'//tab//'(-)'//tab//'(m)'//tab//'(m)'//tab//'(m)'//tab//'(m)'//tab// &
      '(N)'//tab//'(1/m)'//tab//'(N.m)'//tab//'(deg)'//tab//'(deg)'//tab//'(deg)'

    DO li = 1, SIZE(lines)
      nn = CD_HFMF_NNodes(cables(li))
      IF (nn < 2) THEN
        CLOSE (unit, STATUS='DELETE')
        CALL fail(ErrStat, ErrMsg, 'Hermite static-profile line has fewer than two nodes'); RETURN
      END IF
      s = CD_ZERO; xyz_prev = CD_ZERO
      DO node = 1, nn
        CALL eval_node('px', xyz(1)); IF (ErrStat /= CD_DECKDRV_OK) RETURN
        CALL eval_node('py', xyz(2)); IF (ErrStat /= CD_DECKDRV_OK) RETURN
        CALL eval_node('pz', xyz(3)); IF (ErrStat /= CD_DECKDRV_OK) RETURN
        CALL eval_node('Ten', tension); IF (ErrStat /= CD_DECKDRV_OK) RETURN
        CALL eval_node('Curv', curvature); IF (ErrStat /= CD_DECKDRV_OK) RETURN
        CALL eval_node('BendMom', bend_moment); IF (ErrStat /= CD_DECKDRV_OK) RETURN
        CALL eval_node('Dec', declination); IF (ErrStat /= CD_DECKDRV_OK) RETURN
        CALL eval_node('Azi', azimuth); IF (ErrStat /= CD_DECKDRV_OK) RETURN
        IF (node > 1) s = s + NORM2(xyz - xyz_prev)
        WRITE (unit, '(I0,A,I0,10(A,ES15.7E3))') lines(li)%id, tab, node, tab, s, tab, xyz(1), tab, xyz(2), &
          tab, xyz(3), tab, tension, tab, curvature, tab, bend_moment, tab, declination, &
          tab, declination - 90.0_wp, tab, azimuth
        xyz_prev = xyz
      END DO
    END DO
    CLOSE (unit)
    CALL write_hermite_static_element_profile(out_root, lines, cables, ErrStat, ErrMsg)

  CONTAINS
    SUBROUTINE eval_node(kind, value)
      CHARACTER(*), INTENT(IN) :: kind
      REAL(wp), INTENT(OUT) :: value
      CHARACTER(LEN(ErrMsg)) :: eval_msg
      IF (kind == 'px' .OR. kind == 'py' .OR. kind == 'pz' .OR. kind == 'Dec' .OR. kind == 'Azi') THEN
        WRITE (channel, '(A,I0,A,I0,A)') 'L', lines(li)%id, 'N', node, TRIM(kind)
      ELSE
        WRITE (channel, '(A,I0,A,I0)') TRIM(kind), lines(li)%id, 'N', node
      END IF
      CALL eval_cable_channel(cables(li), TRIM(channel), value, ErrStat, eval_msg)
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        CLOSE (unit, STATUS='DELETE')
        ErrMsg = 'CableDyn_DeckDriver: Hermite static-profile channel '//TRIM(channel)//' failed: '//TRIM(eval_msg)
      END IF
    END SUBROUTINE eval_node
  END SUBROUTINE write_hermite_static_profile

  SUBROUTINE write_hermite_static_element_profile(out_root, lines, cables, ErrStat, ErrMsg)
    !! Element-wise extrema for verification and design extraction.  Curvature and
    !! axial-resultant extrema are searched over each complete Hermite field rather
    !! than sampled only at nodes or integration points.  Public element orientation
    !! follows End A to End B, matching the nodal static profile.
    CHARACTER(*), INTENT(IN) :: out_root
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cables(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: unit, ios, li, public_element, internal_element, ne, es
    REAL(wp) :: qr(12), l0, arc_start, arc_end, curvature_peak, u_curvature_internal, &
                u_curvature_public, arc_peak, moment_peak, minimum_resultant, minimum_u_internal, &
                minimum_u_public, maximum_resultant, maximum_u_internal, maximum_u_public
    CHARACTER(200) :: em
    CHARACTER(LEN(out_root) + 20) :: path
    CHARACTER(1) :: tab

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (SIZE(lines) /= SIZE(cables)) THEN
      CALL fail(ErrStat, ErrMsg, 'Hermite static-element cable count does not match line count'); RETURN
    END IF
    path = TRIM(out_root)//'.elements.out'
    OPEN (NEWUNIT=unit, FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open Hermite static-element profile: '//TRIM(path)); RETURN
    END IF
    tab = CHAR(9)
    WRITE (unit, '(A)') 'CableDyn continuous Hermite-element extrema (public order End A -> End B)'
    WRITE (unit, '(A)') 'LineID'//tab//'Element'//tab//'ReferenceArcStart'//tab//'ReferenceArcEnd'//tab// &
      'PeakXi'//tab//'PeakReferenceArc'//tab//'PeakCurvature'//tab//'BendMomentAtPeak'//tab// &
      'MinimumAxialResultant'//tab//'MinimumXi'//tab//'MaximumAxialResultant'//tab//'MaximumXi'
    WRITE (unit, '(A)') '(-)'//tab//'(-)'//tab//'(m)'//tab//'(m)'//tab//'(-)'//tab//'(m)'//tab// &
      '(1/m)'//tab//'(N.m)'//tab//'(N)'//tab//'(-)'//tab//'(N)'//tab//'(-)'

    DO li = 1, SIZE(lines)
      ne = cables(li)%line%ne
      arc_start = CD_ZERO
      DO public_element = 1, ne
        internal_element = ne - public_element + 1
        l0 = cables(li)%line%l0(internal_element)
        qr(1:6) = cables(li)%line%q(6*(internal_element - 1) + 1:6*(internal_element - 1) + 6)
        qr(7:12) = cables(li)%line%q(6*internal_element + 1:6*internal_element + 6)
        CALL CD_HermiteCable_Peak_Curvature(qr, l0, curvature_peak, u_curvature_internal, es, em)
        IF (es /= CD_HCABLE_OK) THEN
          CLOSE (unit, STATUS='DELETE')
          CALL fail_solve(ErrStat, ErrMsg, 'continuous curvature extraction failed: '//TRIM(em)); RETURN
        END IF
        CALL CD_HermiteCable_Axial_Resultant_Range(qr, l0, cables(li)%line%EA(internal_element), &
                                                   minimum_resultant, minimum_u_internal, &
                                                   maximum_resultant, maximum_u_internal, es, em)
        IF (es /= CD_HCABLE_OK) THEN
          CLOSE (unit, STATUS='DELETE')
          CALL fail_solve(ErrStat, ErrMsg, 'continuous axial-resultant extraction failed: '//TRIM(em)); RETURN
        END IF
        arc_end = arc_start + l0
        u_curvature_public = CD_ONE - u_curvature_internal
        minimum_u_public = CD_ONE - minimum_u_internal
        maximum_u_public = CD_ONE - maximum_u_internal
        arc_peak = arc_start + u_curvature_public*l0
        moment_peak = cables(li)%line%EI(internal_element)*curvature_peak
        WRITE (unit, '(I0,A,I0,10(A,ES15.7E3))') lines(li)%id, tab, public_element, &
          tab, arc_start, tab, arc_end, tab, u_curvature_public, tab, arc_peak, tab, curvature_peak, &
          tab, moment_peak, tab, minimum_resultant, tab, minimum_u_public, tab, maximum_resultant, &
          tab, maximum_u_public
        arc_start = arc_end
      END DO
    END DO
    CLOSE (unit)
  END SUBROUTINE write_hermite_static_element_profile

  SUBROUTINE apply_motion_to_hermite_cables(cables, lines, points, motion, time_index, ErrStat, ErrMsg)
    !! Transfer one prescribed-motion row into the Hermite boundary without solving
    !! the interior or advancing time. Each standalone Hermite cable is oriented with
    !! its coupled/fairlead endpoint at line NodeA.
    TYPE(CD_HFMF_ModuleType), INTENT(INOUT) :: cables(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(MotionTable), INTENT(IN) :: motion
    INTEGER, INTENT(IN) :: time_index
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: i, pidx, es
    REAL(wp) :: q(3), v(3), a(3)
    CHARACTER(200) :: em

    ErrStat = CD_DECKDRV_OK; ErrMsg = ''
    IF (SIZE(cables) /= SIZE(lines)) THEN
      CALL fail(ErrStat, ErrMsg, 'Hermite motion cable count does not match line count'); RETURN
    END IF
    DO i = 1, SIZE(cables)
      pidx = find_point(points, lines(i)%nodeA)
      IF (pidx < 1) THEN
        CALL fail(ErrStat, ErrMsg, 'Hermite motion line NodeA references an unknown point'); RETURN
      END IF
      CALL prescribed_point_state(points(pidx), motion, time_index, q, v, a, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      IF (motion%has_rot) THEN
        ! vessel motion: an end connection at the fairlead turns with the vessel
        CALL CD_HFMF_SetCoupledKinematics(cables(i), q, v, a, es, em, &
                                          u_orientation=TRANSPOSE(motion%rot(:, :, time_index)), &
                                          u_angular_velocity=motion%omega(:, time_index), &
                                          u_angular_acceleration=motion%alpha(:, time_index))
      ELSE
        CALL CD_HFMF_SetCoupledKinematics(cables(i), q, v, a, es, em)
      END IF
      IF (es /= CD_HFMF_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: initial Hermite prescribed-motion transfer failed: '//TRIM(em)
        RETURN
      END IF
    END DO
  END SUBROUTINE apply_motion_to_hermite_cables

  SUBROUTINE update_hermite_deck_fluid(cables, opts, time, ErrStat, ErrMsg)
    TYPE(CD_HFMF_ModuleType), INTENT(INOUT) :: cables(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: i, j, nn, es
    REAL(wp) :: eta, wv(3), wa(3)
    CHARACTER(200) :: em
    ErrStat = CD_DECKDRV_OK; ErrMsg = ''
    IF (.NOT. (opts%has_current .OR. opts%has_wave)) RETURN
    DO i = 1, SIZE(cables)
      nn = CD_HFMF_NNodes(cables(i))
      BLOCK
        REAL(wp) :: xyz(3, nn), fv(3, nn), fa(3, nn), wl(nn)
        CALL CD_HFMF_GetNodePositions(cables(i), xyz, es, em)
        IF (es /= CD_HFMF_OK) THEN
          CALL hermite_fluid_fail('node-position query', em); RETURN
        END IF
        fv = CD_ZERO; fa = CD_ZERO; wl = CD_ZERO
        DO j = 1, nn
          IF (opts%has_current) THEN
            fv(:, j) = deck_current_velocity(opts, xyz(3, j), es, em)
            IF (es /= CD_HYDRO_OK) THEN
              CALL hermite_fluid_fail('current profile', em); RETURN
            END IF
          END IF
          IF (opts%has_wave) THEN
            CALL deck_wave_kinematics(opts, xyz(1, j), xyz(2, j), xyz(3, j), time, eta, wv, wa, es, em)
            IF (es /= CD_HYDRO_OK) THEN
              CALL hermite_fluid_fail('wave kinematics', em); RETURN
            END IF
            fv(:, j) = fv(:, j) + wv; fa(:, j) = wa; wl(j) = eta
          END IF
        END DO
        CALL CD_HFMF_Set_Held_Fluid(cables(i), fv, fa, wl, es, em)
        IF (es /= CD_HFMF_OK) THEN
          CALL hermite_fluid_fail('held-field update', em); RETURN
        END IF
      END BLOCK
    END DO
  CONTAINS
    SUBROUTINE hermite_fluid_fail(where, msg)
      CHARACTER(*), INTENT(IN) :: where, msg
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: Hermite '//TRIM(where)//' failed: '//TRIM(msg)
    END SUBROUTINE hermite_fluid_fail
  END SUBROUTINE update_hermite_deck_fluid

  SUBROUTINE write_hermite_model_row(unit, time, channels, lines, points, cables, ErrStat, ErrMsg, &
                                     motion, motion_time_index, has_motion, ranges)
    INTEGER, INTENT(IN) :: unit, motion_time_index
    REAL(wp), INTENT(IN) :: time
    CHARACTER(NAMELEN), INTENT(IN) :: channels(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cables(:)
    TYPE(MotionTable), INTENT(IN) :: motion
    LOGICAL, INTENT(IN) :: has_motion
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_RangeSet), INTENT(INOUT), OPTIONAL :: ranges
    INTEGER :: i, line_id, li, pidx, comp, pp, mi, k, es
    REAL(wp) :: val, f(3), fl(3)
    CHARACTER(NAMELEN) :: lo
    CHARACTER(200) :: em
    ErrStat = CD_DECKDRV_OK; ErrMsg = ''
    IF (PRESENT(ranges)) THEN
      DO li = 1, SIZE(lines)
        IF (.NOT. CD_Range_Needs_Sample(ranges, li)) CYCLE
        CALL range_sample_cable(cables(li), ranges%lines(li), ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        CALL CD_Range_Commit_Sample(ranges, li, time, es, em)
        CALL range_status(es, em, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      END DO
    END IF
    WRITE (unit, TIME_COLUMN_FMT, ADVANCE='NO') time
    DO i = 1, SIZE(channels)
      lo = to_lower(channels(i))
      IF (is_point_force_channel(lo)) THEN
        ! resultant of the end forces the cables exert on the point (End A = the cable's last node)
        CALL parse_point_force_channel(channels(i), pidx, comp)
        f = CD_ZERO
        DO li = 1, SIZE(lines)
          DO k = 1, 2
            IF (k == 1 .AND. lines(li)%nodeA /= pidx) CYCLE
            IF (k == 2 .AND. lines(li)%nodeB /= pidx) CYCLE
            CALL CD_HermiteCable_Dyn_End_Force(cables(li)%line, MERGE(cables(li)%line%nn, 1, k == 1), fl, es, em)
            IF (es /= CD_HCDYN_OK) THEN
              CALL fail_solve(ErrStat, ErrMsg, 'Hermite point-force recovery failed: '//TRIM(em)); RETURN
            END IF
            f = f + [cable_global_component(cables(li), fl, 1), cable_global_component(cables(li), fl, 2), &
                     cable_global_component(cables(li), fl, 3)]
          END DO
        END DO
        IF (comp == 4) THEN
          val = SQRT(f(1)**2 + f(2)**2)
        ELSE
          val = f(comp)
        END IF
      ELSE IF (CD_Is_TDP_Channel(lo)) THEN
        CALL CD_Parse_TDP_Channel(channels(i), line_id, comp)
        li = find_line(lines, line_id)
        val = CD_ZERO
        IF (PRESENT(ranges)) THEN
          IF (CD_Range_Needs_Sample(ranges, li)) val = ranges%lines(li)%tdp(comp)
        END IF
      ELSE IF (is_point_channel(lo)) THEN
        CALL parse_point_channel(channels(i), pidx, comp)
        pp = point_index(points, pidx)
        IF (pp < 1) THEN
          CALL fail(ErrStat, ErrMsg, 'Hermite Point OUTPUT references an unknown point'); RETURN
        END IF
        IF (has_motion .AND. (TRIM(points(pp)%ptype) == 'coupled' .OR. TRIM(points(pp)%ptype) == 'vessel')) THEN
          mi = find_motion_point(motion, pidx)
          IF (mi < 1) THEN
            CALL fail(ErrStat, ErrMsg, 'Hermite motion OUTPUT is missing its point'); RETURN
          END IF
          val = motion%q(comp, mi, motion_time_index)
        ELSE
          val = points(pp)%pos(comp)
        END IF
      ELSE
        IF (starts_with(lo, 'fairten') .OR. starts_with(lo, 'anchten')) THEN
          line_id = int_suffix(channels(i), 8)
        ELSE IF (is_endpoint_angle_channel(lo)) THEN
          line_id = endpoint_angle_line_id(channels(i))
        ELSE
          CALL parse_line_node_channel(channels(i), line_id, pidx, pp, comp)
        END IF
        li = find_line(lines, line_id)
        CALL eval_cable_channel(cables(li), channels(i), val, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      END IF
      IF (.NOT. IEEE_IS_FINITE(val)) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'non-finite Hermite dynamic output'); RETURN
      END IF
      WRITE (unit, '(A,ES15.7E3)', ADVANCE='NO') char_tab(), val
    END DO
    WRITE (unit, '(A)') ''
  END SUBROUTINE write_hermite_model_row

  SUBROUTINE open_dynamic_hermite_line_outputs(out_root, lines, cables, pos_units, ten_units, ErrStat, ErrMsg)
    CHARACTER(*), INTENT(IN) :: out_root
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cables(:)
    INTEGER, ALLOCATABLE, INTENT(OUT) :: pos_units(:), ten_units(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: i, ios, node, seg
    CHARACTER(LEN(out_root) + 32) :: path
    ErrStat = CD_DECKDRV_OK; ErrMsg = ''
    ALLOCATE (pos_units(SIZE(lines)), ten_units(SIZE(lines)))
    pos_units = 0; ten_units = 0
    DO i = 1, SIZE(lines)
      IF (.NOT. line_outputs_requested(lines(i)%outputs)) CYCLE
      IF (line_output_has_flag(lines(i)%outputs, 'p')) THEN
        path = TRIM(out_root)//'.Line'//TRIM(int_to_str(lines(i)%id))//'.p.out'
        OPEN (NEWUNIT=pos_units(i), FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
        IF (ios /= 0) THEN
          CALL close_dynamic_line_outputs(pos_units, ten_units)
          CALL fail(ErrStat, ErrMsg, 'cannot open Hermite line position output: '//TRIM(path)); RETURN
        END IF
        WRITE (pos_units(i), '(A)') '# CableDyn finite-EI Hermite line node positions; public node order EndA -> EndB'
        WRITE (pos_units(i), '(A)', ADVANCE='NO') 'Time(s)'
        DO node = 1, cables(i)%line%nn
          WRITE (pos_units(i), '(A,A,I0,A)', ADVANCE='NO') char_tab(), 'Node', node, 'X(m)'
          WRITE (pos_units(i), '(A,A,I0,A)', ADVANCE='NO') char_tab(), 'Node', node, 'Y(m)'
          WRITE (pos_units(i), '(A,A,I0,A)', ADVANCE='NO') char_tab(), 'Node', node, 'Z(m)'
        END DO
        WRITE (pos_units(i), '(A)') ''
      END IF
      IF (line_output_has_flag(lines(i)%outputs, 't')) THEN
        path = TRIM(out_root)//'.Line'//TRIM(int_to_str(lines(i)%id))//'.t.out'
        OPEN (NEWUNIT=ten_units(i), FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
        IF (ios /= 0) THEN
          CALL close_dynamic_line_outputs(pos_units, ten_units)
          CALL fail(ErrStat, ErrMsg, 'cannot open Hermite line tension output: '//TRIM(path)); RETURN
        END IF
        WRITE (ten_units(i), '(A)') '# CableDyn finite-EI Hermite segment tensions; public order EndA -> EndB'
        WRITE (ten_units(i), '(A)', ADVANCE='NO') 'Time(s)'
        DO seg = 1, cables(i)%line%ne
          WRITE (ten_units(i), '(A,A,I0,A)', ADVANCE='NO') char_tab(), 'Segment', seg, 'Tension(N)'
        END DO
        WRITE (ten_units(i), '(A)') ''
      END IF
    END DO
  END SUBROUTINE open_dynamic_hermite_line_outputs

  SUBROUTINE write_dynamic_hermite_line_outputs(time, lines, cables, pos_units, ten_units, ErrStat, ErrMsg)
    REAL(wp), INTENT(IN) :: time
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cables(:)
    INTEGER, INTENT(IN) :: pos_units(:), ten_units(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: i, node, inode, seg, k
    ErrStat = CD_DECKDRV_OK; ErrMsg = ''
    DO i = 1, SIZE(lines)
      ! Each row is assembled in deck order and written in one WRITE; a non-finite entry
      ! leaves the row prefix before it non-advancing and fails.
      IF (pos_units(i) /= 0) THEN
        BLOCK
          REAL(wp) :: xyz(3*cables(i)%line%nn)
          DO node = 1, cables(i)%line%nn
            inode = deck_to_internal_node(node, cables(i)%line%ne)
            DO k = 1, 3
              xyz(3*node - 3 + k) = cable_global_component(cables(i), cables(i)%line%q(6*inode - 5:6*inode - 3), k)
            END DO
            IF (.NOT. ALL(IEEE_IS_FINITE(xyz(3*node - 2:3*node)))) THEN
              WRITE (pos_units(i), ROW_VALUES_FMT, ADVANCE='NO') time, (char_tab(), xyz(k), k=1, 3*node - 3)
              CALL fail_solve(ErrStat, ErrMsg, 'non-finite Hermite line position output'); RETURN
            END IF
          END DO
          WRITE (pos_units(i), ROW_VALUES_FMT) time, (char_tab(), xyz(k), k=1, SIZE(xyz))
        END BLOCK
      END IF
      IF (ten_units(i) /= 0) THEN
        BLOCK
          REAL(wp) :: tension(cables(i)%line%ne)
          DO seg = 1, cables(i)%line%ne
            tension(seg) = cable_element_tension(cables(i), cables(i)%line%ne - seg + 1)
            IF (.NOT. IEEE_IS_FINITE(tension(seg))) THEN
              WRITE (ten_units(i), ROW_VALUES_FMT, ADVANCE='NO') time, (char_tab(), tension(k), k=1, seg - 1)
              CALL fail_solve(ErrStat, ErrMsg, 'non-finite Hermite line tension output'); RETURN
            END IF
          END DO
          WRITE (ten_units(i), ROW_VALUES_FMT) time, (char_tab(), tension(k), k=1, SIZE(tension))
        END BLOCK
      END IF
    END DO
  END SUBROUTINE write_dynamic_hermite_line_outputs

  SUBROUTINE write_finite_dynamic_out(out_root, channels, lines, points, opts, models, converged, ErrStat, ErrMsg, &
                                      bathymetry)
    CHARACTER(*), INTENT(IN) :: out_root
    CHARACTER(NAMELEN), INTENT(IN) :: channels(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(FiniteDeckModel), INTENT(INOUT) :: models(:)
    LOGICAL, INTENT(OUT) :: converged
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    INTEGER :: unit, ios, step, nstep, es, n_iter
    INTEGER, ALLOCATABLE :: pos_units(:), ten_units(:)
    INTEGER :: miss_count, consecutive_miss, max_consecutive_miss
    CHARACTER(LEN(out_root) + 8) :: path
    CHARACTER(256) :: em
    LOGICAL :: step_converged, stalled
    REAL(wp) :: t, first_miss_time, last_miss_time
    TYPE(MotionTable) :: motion
    TYPE(ModelOutputWorkspace) :: output_work
    TYPE(DriverProgress) :: progress

    converged = .TRUE.
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    nstep = NINT(opts%tmax/opts%dtM)
    CALL range_setup_planned(output_work%rset, lines, channels, opts, ErrStat, ErrMsg, fmodels=models, &
                             bathymetry=bathymetry)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    miss_count = 0
    consecutive_miss = 0
    max_consecutive_miss = 0
    first_miss_time = CD_ZERO
    last_miss_time = CD_ZERO
    IF (opts%has_motion_file) THEN
      CALL read_motion_file(opts%motion_file, points, opts, motion, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL apply_motion_to_finite_models(models, lines, points, motion, 1, es, em)
      IF (es /= CD_DECKDRV_OK) THEN
        ErrStat = es
        ErrMsg = em
        RETURN
      END IF
    END IF
    ! Seed a_0 with the t=0 seabed-contact + current/wave loads so the first step does not
    ! march from a gravity-only initial acceleration (mirrors the EI=0 update_wave_models recompute).
    CALL seed_finite_initial_acceleration(models, opts, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    path = TRIM(out_root)//'.out'
    OPEN (NEWUNIT=unit, FILE=path, STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open output file: '//TRIM(path)); RETURN
    END IF
    WRITE (unit, '(A)') '# CableDyn driver output (finite-EI dynamic; convergence quality in the status message)'
    CALL write_header(unit, channels)
    CALL open_dynamic_finite_line_outputs(out_root, lines, models, pos_units, ten_units, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      RETURN
    END IF
    IF (opts%has_motion_file) THEN
      CALL write_finite_model_row(unit, CD_ZERO, channels, lines, points, models, output_work, ErrStat, ErrMsg, &
                                  motion, 1)
    ELSE
      CALL write_finite_model_row(unit, CD_ZERO, channels, lines, points, models, output_work, ErrStat, ErrMsg)
    END IF
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      CALL close_dynamic_line_outputs(pos_units, ten_units)
      RETURN
    END IF
    CALL write_dynamic_finite_line_outputs(CD_ZERO, lines, models, pos_units, ten_units, output_work, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      CLOSE (unit)
      CALL close_dynamic_line_outputs(pos_units, ten_units)
      RETURN
    END IF
    CALL start_driver_progress(progress, nstep, opts%dtM)
    DO step = 1, nstep
      t = REAL(step, wp)*opts%dtM
      IF (opts%has_motion_file) THEN
        ! Moving-support march: the prescribed endpoint translations follow the motionFile
        ! trajectory to t_{n+1}, their velocity/acceleration coupling into the dynamic residual
        ! (the gen-alpha sets the fixed DOFs to the targets -- no separate re-apply needed).
        CALL step_finite_held_models(models, opts, t, opts%dtM, step_converged, stalled, n_iter, es, em, &
                                     motion=motion, lines=lines, points=points, time_index=step + 1)
      ELSE
        CALL step_finite_held_models(models, opts, t, opts%dtM, step_converged, stalled, n_iter, es, em)
      END IF
      IF (es /= CD_DECKDRV_OK) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        ErrStat = es
        ErrMsg = em
        RETURN
      END IF
      CALL update_dynamic_completion_quality(t, step_converged, stalled, miss_count, consecutive_miss, &
                                             max_consecutive_miss, first_miss_time, last_miss_time)
      IF (.NOT. step_converged .OR. stalled) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        CALL CD_Classify_Dynamic_Completion('finite-EI dynamic run', nstep, miss_count, &
                                            max_consecutive_miss, first_miss_time, last_miss_time, &
                                            converged, ErrStat, ErrMsg)
        RETURN
      END IF
      IF (opts%has_motion_file) THEN
        CALL write_finite_model_row(unit, t, channels, lines, points, models, output_work, ErrStat, ErrMsg, &
                                    motion, step + 1)
      ELSE
        CALL write_finite_model_row(unit, t, channels, lines, points, models, output_work, ErrStat, ErrMsg)
      END IF
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        RETURN
      END IF
      CALL write_dynamic_finite_line_outputs(t, lines, models, pos_units, ten_units, output_work, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        CLOSE (unit)
        CALL close_dynamic_line_outputs(pos_units, ten_units)
        RETURN
      END IF
      CALL update_driver_progress(progress, step, t)
    END DO
    CLOSE (unit)
    CALL close_dynamic_line_outputs(pos_units, ten_units)
    CALL CD_Classify_Dynamic_Completion('finite-EI dynamic run', nstep, miss_count, max_consecutive_miss, &
                                        first_miss_time, last_miss_time, converged, ErrStat, ErrMsg)
    IF (ErrStat == CD_DECKDRV_OK .AND. converged) CALL range_write(output_work%rset, out_root, ErrStat, ErrMsg)
  END SUBROUTINE write_finite_dynamic_out

  FUNCTION deck_current_velocity(opts, z, ErrStat, ErrMsg) RESULT(velocity)
    !! Return the deck current velocity at elevation z, with two-point profile
    !! interpolation when a profile current is active.
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: z
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp) :: velocity(3)

    ErrStat = CD_HYDRO_OK
    ErrMsg = ''
    IF (.NOT. opts%has_current) THEN
      velocity = CD_ZERO
    ELSE IF (.NOT. opts%has_current_profile) THEN
      velocity = opts%current_velocity
    ELSE
      CALL CD_Current_Profile_Velocity(z, opts%current_profile_z, opts%current_profile_velocity, &
                                       velocity, ErrStat, ErrMsg)
    END IF
  END FUNCTION deck_current_velocity

  PURE REAL(wp) FUNCTION line_node_z(anchor, fairlead, l0, node_id) RESULT(z)
    !! Straight-line elevation estimate for initial environment fields before
    !! the persistent line model exposes its static equilibrium state.
    REAL(wp), INTENT(IN) :: anchor(3), fairlead(3), l0(:)
    INTEGER, INTENT(IN) :: node_id
    REAL(wp) :: total, s

    total = SUM(l0)
    IF (total <= CD_ZERO) THEN
      z = anchor(3)
      RETURN
    END IF
    IF (node_id <= 1) THEN
      s = CD_ZERO
    ELSE IF (node_id > SIZE(l0)) THEN
      s = total
    ELSE
      s = SUM(l0(1:node_id - 1))
    END IF
    z = anchor(3) + (fairlead(3) - anchor(3))*s/total
  END FUNCTION line_node_z

  SUBROUTINE deck_wave_kinematics(opts, x, y, z, time, eta, velocity, acceleration, ErrStat, ErrMsg, pdyn)
    !! Dispatch the active deck wave model to the hydro kinematics primitive. During the
    !! optional start-up ramp (OPTION rampTime) every wave amplitude is scaled by the
    !! half-cosine factor r(t) (the Wheeler stretching then sees the ramped surface) and
    !! the fluid acceleration is the exact time derivative of the ramped velocity,
    !! r*a + (dr/dt)*u. The WaterKin mean-level offset is not ramped. With no ramp, or
    !! once t >= rampTime, the evaluation is the unramped one bit-for-bit.
    !! pdyn (optional): the linear wave dynamic pressure per unit density [m^2/s^2].
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: x, y, z, time
    REAL(wp), INTENT(OUT) :: eta, velocity(3), acceleration(3)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp), INTENT(OUT), OPTIONAL :: pdyn
    REAL(wp) :: ramp, ramp_rate

    IF (opts%has_wave .AND. .NOT. opts%wave_cache_ready) THEN
      CALL fail(ErrStat, ErrMsg, 'deck wave kinematics called before wave precompute')
      RETURN
    END IF
    IF (PRESENT(pdyn)) pdyn = CD_ZERO
    CALL deck_wave_ramp(opts%ramp_time, time, ramp, ramp_rate)
    IF (opts%wave_kind /= WAVE_NONE .AND. ramp <= CD_ZERO) THEN
      ! still water before the ramp opens
      eta = CD_ZERO
      IF (opts%wave_kind == WAVE_COMPONENTS) eta = opts%wave_eta_mean
      velocity = CD_ZERO
      acceleration = CD_ZERO
      ErrStat = CD_HYDRO_OK
      ErrMsg = ''
      RETURN
    END IF
    SELECT CASE (opts%wave_kind)
    CASE (WAVE_AIRY)
      CALL CD_Airy_Wave_Kinematics_Precomputed(x, y, z, time, ramp*opts%wave_height, opts%wave_omega, opts%wave_k, &
                                               opts%wtrdpth, opts%wave_direction, .TRUE., eta, velocity, &
                                               acceleration, ErrStat, ErrMsg, pdyn)
    CASE (WAVE_JONSWAP)
      CALL CD_Component_Wave_Kinematics(x, y, z, time, opts%wtrdpth, opts%wave_direction, .TRUE., &
                                        opts%jonswap_omega, opts%jonswap_k, opts%jonswap_amplitude, &
                                        opts%jonswap_phase, eta, velocity, acceleration, ErrStat, ErrMsg, &
                                        inputs_validated=.TRUE., amplitude_scale=ramp, pdyn=pdyn, &
                                        exp_m2kd=opts%jonswap_e2kd)
    CASE (WAVE_SEA)
      CALL CD_Sea_Kinematics(opts%sea, x, y, z, time, opts%wtrdpth, ramp, eta, velocity, acceleration, &
                             ErrStat, ErrMsg, pdyn)
    CASE (WAVE_STREAM)
      CALL CD_Stream_Kinematics(opts%stream, x, y, z, time, ramp, eta, velocity, acceleration, ErrStat, ErrMsg, &
                                pdyn)
    CASE (WAVE_COMPONENTS)
      IF (ramp < CD_ONE) THEN
        CALL CD_Component_Wave_Kinematics(x, y, z - opts%wave_eta_mean, time, &
                                          opts%wtrdpth + opts%wave_eta_mean, opts%wave_direction, .TRUE., &
                                          opts%wave_component_omega, opts%wave_component_k, &
                                          opts%wave_component_amplitude, opts%wave_component_phase, &
                                          eta, velocity, acceleration, ErrStat, ErrMsg, inputs_validated=.TRUE., &
                                          amplitude_scale=ramp, pdyn=pdyn)
      ELSE
        CALL CD_Component_Wave_Kinematics(x, y, z - opts%wave_eta_mean, time, &
                                          opts%wtrdpth + opts%wave_eta_mean, opts%wave_direction, .TRUE., &
                                          opts%wave_component_omega, opts%wave_component_k, &
                                          opts%wave_component_amplitude, opts%wave_component_phase, &
                                          eta, velocity, acceleration, ErrStat, ErrMsg, inputs_validated=.TRUE., &
                                          pdyn=pdyn)
      END IF
      eta = eta + opts%wave_eta_mean
    CASE DEFAULT
      eta = CD_ZERO
      velocity = CD_ZERO
      acceleration = CD_ZERO
      ErrStat = CD_HYDRO_OK
      ErrMsg = ''
    END SELECT
    IF (ErrStat == CD_HYDRO_OK .AND. ramp > CD_ZERO .AND. ramp < CD_ONE) &
      acceleration = acceleration + (ramp_rate/ramp)*velocity
  END SUBROUTINE deck_wave_kinematics

  PURE SUBROUTINE deck_wave_ramp(ramp_time, time, ramp, ramp_rate)
    !! Half-cosine start-up ramp r(t) = (1 - cos(pi*t/T))/2 on [0, T], 1 afterwards, and
    !! its rate dr/dt; T <= 0 disables the ramp (r = 1). r and dr/dt are continuous, so
    !! the ramped fluid velocity starts from rest with zero acceleration.
    REAL(wp), INTENT(IN) :: ramp_time, time
    REAL(wp), INTENT(OUT) :: ramp, ramp_rate
    REAL(wp) :: arg

    ramp = CD_ONE
    ramp_rate = CD_ZERO
    IF (.NOT. (ramp_time > CD_ZERO) .OR. time >= ramp_time) RETURN
    IF (time <= CD_ZERO) THEN
      ramp = CD_ZERO
      RETURN
    END IF
    arg = 4.0_wp*QUARTER_PI*time/ramp_time
    ramp = 0.5_wp*(CD_ONE - COS(arg))
    ramp_rate = 2.0_wp*QUARTER_PI*SIN(arg)/ramp_time
  END SUBROUTINE deck_wave_ramp

  SUBROUTINE check_modal_deck(bodies, rods, points, lines, opts, n_finite, has_dyn_points, has_failures, &
                              ErrStat, ErrMsg)
    !! OPTION nModes runs on decks of lines between fixed and prescribed points: all
    !! EI = 0 lines (static or dynamic deck), or all finite-EI lines on the standalone
    !! cubic-Hermite route (dynamic deck, every End B Fixed); flat seabed only.
    TYPE(DeckBody), INTENT(IN) :: bodies(:)
    TYPE(DeckRod), INTENT(IN) :: rods(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    INTEGER, INTENT(IN) :: n_finite
    LOGICAL, INTENT(IN) :: has_dyn_points, has_failures
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: li, j
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (SIZE(bodies) > 0 .OR. SIZE(rods) > 0 .OR. has_dyn_points .OR. has_failures .OR. SIZE(lines) == 0) THEN
      CALL fail(ErrStat, ErrMsg, 'OPTION nModes needs a deck of lines between Fixed and Coupled/Vessel points '// &
                '(no BODIES, RODS, Connect/Free points or FAILURE)'); RETURN
    END IF
    IF (opts%has_bathymetry_file) THEN
      CALL fail(ErrStat, ErrMsg, 'OPTION nModes supports a flat WtrDpth seabed only (not bathymetryFile)'); RETURN
    END IF
    IF (n_finite > 0) THEN
      IF (n_finite /= SIZE(lines) .OR. .NOT. opts%has_dtm) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTION nModes on finite-EI lines needs a dynamic deck (dtM, TMax) whose '// &
                  'lines are all finite-EI'); RETURN
      END IF
      DO li = 1, SIZE(lines)
        j = find_point(points, lines(li)%nodeB)
        IF (j < 1) CYCLE
        IF (TRIM(points(j)%ptype) /= 'fixed') THEN
          CALL fail(ErrStat, ErrMsg, 'OPTION nModes on finite-EI lines needs every End B Fixed'); RETURN
        END IF
      END DO
    END IF
  END SUBROUTINE check_modal_deck

  SUBROUTINE write_deck_modes_ei0(out_root, types, points, lines, sections, opts, ErrStat, ErrMsg)
    !! <out_root>.modes.out for EI = 0 lines: each line model is built at its static
    !! equilibrium (the initial condition of the dynamics) and its opts%n_modes lowest
    !! modes solved with the end nodes held (CableDyn_Modal).
    CHARACTER(*), INTENT(IN) :: out_root
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_ModelType), ALLOCATABLE :: models(:)
    TYPE(ModalLineResult), ALLOCATABLE :: res(:)
    REAL(wp), ALLOCATABLE :: kmat(:, :), mmat(:, :), floor_z(:)
    LOGICAL, ALLOCATABLE :: free(:)
    INTEGER :: li, n, nm, es, kd
    CHARACTER(512) :: em

    ALLOCATE (models(0)) ! defined descriptor for the INTENT(OUT) dummy (-Wmaybe-uninitialized at -O0)
    CALL init_deck_models_from_parsed(types, points, lines, sections, opts, models, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    ALLOCATE (res(SIZE(lines)))
    DO li = 1, SIZE(lines)
      ASSOCIATE (m => models(li))
        n = SIZE(m%q)
        ALLOCATE (free(n), floor_z(n/3))
        free = .TRUE.
        free(m%fixed_dofs) = .FALSE.
        floor_z = m%seabed_z_floor
        IF (m%has_added_mass .AND. m%has_seabed) THEN
          CALL CD_Modal_Bar_Band(m%q, m%elem_conn, m%l0, m%ea, m%rho_a, m%tension_only, kd, kmat, mmat, es, em, &
                                 am_rho=m%added_mass_rho, am_waterline=m%added_mass_waterline_z, &
                                 am_diam=m%added_mass_diameter_elem, am_can=m%added_mass_can_elem, &
                                 am_cat=m%added_mass_cat_elem, seabed_kn=m%seabed_kn, floor_z=floor_z)
        ELSE IF (m%has_added_mass) THEN
          CALL CD_Modal_Bar_Band(m%q, m%elem_conn, m%l0, m%ea, m%rho_a, m%tension_only, kd, kmat, mmat, es, em, &
                                 am_rho=m%added_mass_rho, am_waterline=m%added_mass_waterline_z, &
                                 am_diam=m%added_mass_diameter_elem, am_can=m%added_mass_can_elem, &
                                 am_cat=m%added_mass_cat_elem)
        ELSE IF (m%has_seabed) THEN
          CALL CD_Modal_Bar_Band(m%q, m%elem_conn, m%l0, m%ea, m%rho_a, m%tension_only, kd, kmat, mmat, es, em, &
                                 seabed_kn=m%seabed_kn, floor_z=floor_z)
        ELSE
          CALL CD_Modal_Bar_Band(m%q, m%elem_conn, m%l0, m%ea, m%rho_a, m%tension_only, kd, kmat, mmat, es, em)
        END IF
        nm = MIN(opts%n_modes, COUNT(free))
        ALLOCATE (res(li)%omega2(MAX(nm, 1)), res(li)%shapes(n, MAX(nm, 1)), res(li)%q(n))
        res(li)%q = m%q
        res(li)%dof_per_node = 3
        IF (es == CD_MODAL_OK .AND. nm > 0) &
          CALL CD_Modal_Solve_Band(kmat, mmat, kd, free, nm, res(li)%omega2, res(li)%shapes, res(li)%n_found, &
                                   es, em)
        IF (ALLOCATED(kmat)) DEALLOCATE (kmat, mmat)
        DEALLOCATE (free, floor_z)
      END ASSOCIATE
      IF (es /= CD_MODAL_OK) THEN
        CALL end_models(models)
        CALL fail(ErrStat, ErrMsg, 'line '//TRIM(int_to_str(lines(li)%id))//' modal analysis: '//TRIM(em))
        RETURN
      END IF
    END DO
    CALL end_models(models)
    CALL write_modes_file(out_root, lines, res, ErrStat, ErrMsg)
  END SUBROUTINE write_deck_modes_ei0

  SUBROUTINE write_deck_modes_hermite(out_root, lines, opts, cables, ErrStat, ErrMsg)
    !! <out_root>.modes.out for finite-EI lines on the cubic-Hermite route, at the static
    !! equilibrium the march starts from; the DOFs the march holds are held.
    CHARACTER(*), INTENT(IN) :: out_root
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cables(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(ModalLineResult), ALLOCATABLE :: res(:)
    REAL(wp), ALLOCATABLE :: kmat(:, :), mmat(:, :), floor_z(:)
    LOGICAL, ALLOCATABLE :: free(:)
    INTEGER :: li, n, nm, es, kd
    CHARACTER(512) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    ALLOCATE (res(SIZE(lines)))
    DO li = 1, SIZE(lines)
      ASSOCIATE (c => cables(li)%line)
        n = SIZE(c%q)
        ALLOCATE (free(n), floor_z(c%nn))
        free = c%freemask
        floor_z = c%seabed_z
        IF (c%has_am .AND. c%has_contact) THEN
          CALL CD_Modal_Hermite_Band(c%q, c%l0, c%EA, c%EI, c%rho_a, kd, kmat, mmat, es, em, &
                                     axial_order=c%axial_quadrature_order, &
                                     bending_order=c%bending_quadrature_order, am_rho=c%am_rho, &
                                     am_waterline=c%am_wl, am_diam=c%am_diam, am_can=c%am_can, am_cat=c%am_cat, &
                                     contact_kn=c%contact_kn, floor_z=floor_z)
        ELSE IF (c%has_am) THEN
          CALL CD_Modal_Hermite_Band(c%q, c%l0, c%EA, c%EI, c%rho_a, kd, kmat, mmat, es, em, &
                                     axial_order=c%axial_quadrature_order, &
                                     bending_order=c%bending_quadrature_order, am_rho=c%am_rho, &
                                     am_waterline=c%am_wl, am_diam=c%am_diam, am_can=c%am_can, am_cat=c%am_cat)
        ELSE IF (c%has_contact) THEN
          CALL CD_Modal_Hermite_Band(c%q, c%l0, c%EA, c%EI, c%rho_a, kd, kmat, mmat, es, em, &
                                     axial_order=c%axial_quadrature_order, &
                                     bending_order=c%bending_quadrature_order, contact_kn=c%contact_kn, &
                                     floor_z=floor_z)
        ELSE
          CALL CD_Modal_Hermite_Band(c%q, c%l0, c%EA, c%EI, c%rho_a, kd, kmat, mmat, es, em, &
                                     axial_order=c%axial_quadrature_order, &
                                     bending_order=c%bending_quadrature_order)
        END IF
        nm = MIN(opts%n_modes, COUNT(free))
        ALLOCATE (res(li)%omega2(MAX(nm, 1)), res(li)%shapes(n, MAX(nm, 1)), res(li)%q(n))
        res(li)%q = c%q
        res(li)%dof_per_node = 6
        IF (es == CD_MODAL_OK .AND. nm > 0) &
          CALL CD_Modal_Solve_Band(kmat, mmat, kd, free, nm, res(li)%omega2, res(li)%shapes, res(li)%n_found, &
                                   es, em)
        IF (ALLOCATED(kmat)) DEALLOCATE (kmat, mmat)
        DEALLOCATE (free, floor_z)
      END ASSOCIATE
      IF (es /= CD_MODAL_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'line '//TRIM(int_to_str(lines(li)%id))//' modal analysis: '//TRIM(em))
        RETURN
      END IF
    END DO
    CALL write_modes_file(out_root, lines, res, ErrStat, ErrMsg)
  END SUBROUTINE write_deck_modes_hermite

  SUBROUTINE write_modes_file(out_root, lines, res, ErrStat, ErrMsg)
    !! <out_root>.modes.out: a frequency table (LineID Mode Frequency Period Omega) and a
    !! mode-shape table (LineID Mode Node X Y Z dX dY dZ). The line models hold their nodes
    !! End B first; the table numbers them End A first, like every other line output.
    CHARACTER(*), INTENT(IN) :: out_root
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(ModalLineResult), INTENT(IN) :: res(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: unit, ios, li, part, nn, k, dpn, src, dst
    REAL(wp), ALLOCATABLE :: q_a(:), shapes_a(:, :)
    CHARACTER(1) :: tb
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    tb = char_tab()
    OPEN (NEWUNIT=unit, FILE=TRIM(out_root)//'.modes.out', STATUS='REPLACE', ACTION='WRITE', IOSTAT=ios)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open modal output file: '//TRIM(out_root)//'.modes.out'); RETURN
    END IF
    CALL CD_Modal_Write_Header(unit)
    DO part = 1, 2
      IF (part == 1) THEN
        WRITE (unit, '(A)') '# Natural frequencies'
        WRITE (unit, '(A)') 'LineID'//tb//'Mode'//tb//'Frequency'//tb//'Period'//tb//'Omega'
        WRITE (unit, '(A)') '(-)'//tb//'(-)'//tb//'(Hz)'//tb//'(s)'//tb//'(rad/s)'
      ELSE
        WRITE (unit, '(A)') '# Mode shapes (nodal translations, unit largest nodal displacement)'
        WRITE (unit, '(A)') 'LineID'//tb//'Mode'//tb//'Node'//tb//'X'//tb//'Y'//tb//'Z'//tb//'dX'//tb//'dY'//tb//'dZ'
        WRITE (unit, '(A)') '(-)'//tb//'(-)'//tb//'(-)'//tb//'(m)'//tb//'(m)'//tb//'(m)'//tb//'(-)'//tb//'(-)'// &
          tb//'(-)'
      END IF
      DO li = 1, SIZE(lines)
        dpn = res(li)%dof_per_node
        nn = SIZE(res(li)%q)/dpn
        IF (ALLOCATED(q_a)) DEALLOCATE (q_a, shapes_a)
        ALLOCATE (q_a(SIZE(res(li)%q)), shapes_a(SIZE(res(li)%shapes, 1), SIZE(res(li)%shapes, 2)))
        DO k = 1, nn
          src = dpn*(nn - k)
          dst = dpn*(k - 1)
          q_a(dst + 1:dst + dpn) = res(li)%q(src + 1:src + dpn)
          shapes_a(dst + 1:dst + dpn, :) = res(li)%shapes(src + 1:src + dpn, :)
        END DO
        CALL CD_Modal_Write_Line(unit, lines(li)%id, q_a, dpn, res(li)%omega2, shapes_a, res(li)%n_found, part)
      END DO
    END DO
    CLOSE (unit)
  END SUBROUTINE write_modes_file

  SUBROUTINE resolve_deck_friction(opts, ErrStat, ErrMsg)
    !! Resolve the seabed friction coefficients once OPTIONS is read. frictionMu is the
    !! isotropic shorthand; frictionMuAxial / frictionMuLateral override it along and across
    !! the line (OrcaFlex axial/normal pair). The lateral coefficient is kept in
    !! friction_mu (so every friction path keeps its activation), the axial one in
    !! friction_mu_axial; an equal pair stays isotropic, bit-for-bit.
    TYPE(DeckOptions), INTENT(INOUT) :: opts
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp) :: iso

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    opts%friction_mu_axial = -1.0_wp
    IF (opts%friction_mu_axial_row < CD_ZERO .AND. opts%friction_mu_lateral_row < CD_ZERO) RETURN
    IF (.NOT. (IEEE_IS_FINITE(opts%friction_mu_axial_row) .AND. IEEE_IS_FINITE(opts%friction_mu_lateral_row))) THEN
      CALL fail(ErrStat, ErrMsg, 'OPTIONS frictionMuAxial/frictionMuLateral must be finite'); RETURN
    END IF
    iso = opts%friction_mu
    IF (opts%friction_mu_lateral_row >= CD_ZERO) opts%friction_mu = opts%friction_mu_lateral_row
    opts%friction_mu_axial = iso
    IF (opts%friction_mu_axial_row >= CD_ZERO) opts%friction_mu_axial = opts%friction_mu_axial_row
    IF ((opts%friction_mu > CD_ZERO) .NEQV. (opts%friction_mu_axial > CD_ZERO)) THEN
      CALL fail(ErrStat, ErrMsg, 'anisotropic seabed friction needs both the axial and the lateral '// &
                'coefficient positive (frictionMuAxial, frictionMuLateral, or frictionMu for the other)'); RETURN
    END IF
    opts%has_friction = opts%friction_mu > CD_ZERO
    IF (.NOT. (ABS(opts%friction_mu_axial - opts%friction_mu) > CD_ZERO)) opts%friction_mu_axial = -1.0_wp
  END SUBROUTINE resolve_deck_friction

  SUBROUTINE resolve_deck_sea(opts, ErrStat, ErrMsg)
    !! Resolve the parsed wave rows into one wave model once OPTIONS is read: wavetrain rows
    !! (a multi-train sea) exclude every waves row; a spectral waves row of a new spectrum,
    !! or a JONSWAP waves row with OPTION WaveSpreading > 0 or a non-default
    !! WaveComponents, becomes a one-train sea spread by WaveSpreading. A plain JONSWAP
    !! waves row otherwise keeps its original synthesis unchanged.
    TYPE(DeckOptions), INTENT(INOUT) :: opts
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_WaveTrainType) :: train

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (opts%sea%n_trains > 0) THEN
      IF (opts%has_wave) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTIONS declare both wavetrain rows and a waves row; keep one'); RETURN
      END IF
      IF (opts%wave_spreading > CD_ZERO) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTION WaveSpreading applies to a waves row; a wavetrain row carries '// &
                  'its own spreading exponent'); RETURN
      END IF
      opts%has_wave = .TRUE.
      opts%wave_kind = WAVE_SEA
      opts%wave_height = opts%sea%trains(1)%height
      opts%wave_period = opts%sea%trains(1)%period
      opts%wave_direction = opts%sea%trains(1)%direction
      opts%wave_gamma = CD_ONE
      RETURN
    END IF
    IF (.NOT. opts%has_wave) THEN
      IF (opts%wave_spreading > CD_ZERO) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTION WaveSpreading needs a spectral waves row'); RETURN
      END IF
      RETURN
    END IF
    SELECT CASE (opts%wave_kind)
    CASE (WAVE_SEA)
      train = opts%wave_train
    CASE (WAVE_JONSWAP)
      IF (.NOT. (opts%wave_spreading > CD_ZERO .OR. opts%sea%n_freq /= CD_JONSWAP_COMPONENTS)) RETURN
      train%kind = CD_TRAIN_JONSWAP
      train%height = opts%wave_height
      train%period = opts%wave_period
      train%gamma = opts%wave_gamma
      train%direction = opts%wave_direction
    CASE DEFAULT
      IF (opts%wave_spreading > CD_ZERO) THEN
        CALL fail(ErrStat, ErrMsg, 'OPTION WaveSpreading needs a spectral waves row (a regular wave '// &
                  'cannot be spread)'); RETURN
      END IF
      RETURN
    END SELECT
    train%spreading = opts%wave_spreading
    CALL CD_Sea_Add_Train(opts%sea, train, ErrStat, ErrMsg)
    IF (ErrStat /= CD_SEA_OK) RETURN
    opts%wave_kind = WAVE_SEA
    opts%wave_gamma = CD_ONE
  END SUBROUTINE resolve_deck_sea

  SUBROUTINE precompute_deck_wave(opts, ErrStat, ErrMsg)
    TYPE(DeckOptions), INTENT(INOUT) :: opts
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: k

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    opts%wave_cache_ready = .FALSE.
    opts%wave_omega = CD_ZERO
    opts%wave_k = CD_ZERO
    opts%jonswap_omega = CD_ZERO
    opts%jonswap_k = CD_ZERO
    opts%jonswap_amplitude = CD_ZERO
    opts%jonswap_phase = CD_ZERO
    IF (.NOT. opts%has_wave) RETURN
    SELECT CASE (opts%wave_kind)
    CASE (WAVE_AIRY)
      opts%wave_omega = 8.0_wp*QUARTER_PI/opts%wave_period
      CALL CD_Solve_Dispersion_Wavenumber(opts%wave_omega, opts%wtrdpth, opts%g, opts%wave_k, ErrStat, ErrMsg)
    CASE (WAVE_JONSWAP)
      ! Seeded random phases and bin-jittered frequencies: the record never repeats with
      ! the 2*pi/d_omega period of an equally spaced deterministic comb.
      CALL CD_JONSWAP_Random_Components(opts%wave_height, opts%wave_period, opts%wave_gamma, opts%wtrdpth, opts%g, &
                                        opts%wave_seed, opts%jonswap_omega, opts%jonswap_k, opts%jonswap_amplitude, &
                                        opts%jonswap_phase, ErrStat, ErrMsg)
      opts%jonswap_e2kd = EXP(-2.0_wp*(opts%jonswap_k*opts%wtrdpth))
    CASE (WAVE_SEA)
      CALL CD_Sea_Synthesise(opts%sea, opts%wtrdpth, opts%g, opts%wave_seed, ErrStat, ErrMsg)
    CASE (WAVE_STREAM)
      CALL CD_Stream_Solve(opts%stream, opts%wave_height, opts%wave_period, opts%wtrdpth, opts%g, &
                           opts%wave_direction, opts%stream_order, ErrStat, ErrMsg)
    CASE (WAVE_COMPONENTS)
      IF (.NOT. (ALLOCATED(opts%wave_component_omega) .AND. ALLOCATED(opts%wave_component_k) .AND. &
                 ALLOCATED(opts%wave_component_amplitude) .AND. ALLOCATED(opts%wave_component_phase))) THEN
        CALL fail(ErrStat, ErrMsg, 'WaterKin component table is not allocated during wave precompute')
        RETURN
      END IF
      IF (opts%wtrdpth + opts%wave_eta_mean <= CD_ZERO) THEN
        CALL fail(ErrStat, ErrMsg, 'WaterKin mean elevation leaves a non-positive effective depth')
        RETURN
      END IF
      DO k = 1, SIZE(opts%wave_component_omega)
        CALL CD_Solve_Dispersion_Wavenumber(opts%wave_component_omega(k), &
                                            opts%wtrdpth + opts%wave_eta_mean, opts%g, &
                                            opts%wave_component_k(k), ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) EXIT
      END DO
    CASE DEFAULT
      CALL fail(ErrStat, ErrMsg, 'unsupported wave kind during deck wave precompute')
      RETURN
    END SELECT
    IF (ErrStat /= CD_DECKDRV_OK) THEN
      ErrMsg = 'CableDyn_DeckDriver: wave precompute failed: '//TRIM(ErrMsg)
      RETURN
    END IF
    opts%wave_cache_ready = .TRUE.
  END SUBROUTINE precompute_deck_wave

  SUBROUTINE update_system_point_hydro(system, points, opts, time, work, ErrStat, ErrMsg)
    !! Update lumped Free/Connect point fluid kinematics for current and deck waves.
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time
    TYPE(HydroUpdateWorkspace), INTENT(INOUT) :: work
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i, es
    REAL(wp) :: eta, wave_velocity(3), wave_acceleration(3)
    REAL(wp) :: fluid_density
    CHARACTER(160) :: em
    LOGICAL :: points_ready

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    ! The system may carry MORE points than the deck declares: line-failure reserve
    ! points are appended after the deck points (in deck order) with inert hydro
    ! columns (V = CdA = Ca = 0), so their fluid-field rows stay zero here.
    points_ready = ALLOCATED(system%points)
    IF (points_ready) points_ready = SIZE(system%points) >= SIZE(points)
    IF (.NOT. points_ready) THEN
      CALL fail(ErrStat, ErrMsg, 'point hydro update requires a point-connected system matching the deck points')
      RETURN
    END IF
    CALL ensure_hydro_workspace(work, 0, SIZE(system%points))
    work%fluid_velocity(:, 1:SIZE(system%points)) = CD_ZERO
    work%fluid_acceleration(:, 1:SIZE(system%points)) = CD_ZERO
    work%waterline(1:SIZE(system%points)) = CD_ZERO
    DO i = 1, SIZE(points)
      IF (opts%has_current) THEN
        work%fluid_velocity(:, i) = work%fluid_velocity(:, i) + &
                                    deck_current_velocity(opts, system%points(i)%q(3), es, em)
        IF (es /= CD_HYDRO_OK) THEN
          ErrStat = CD_DECKDRV_BADINPUT
          ErrMsg = 'CableDyn_DeckDriver: point current profile failed: '//TRIM(em)
          RETURN
        END IF
      END IF
      IF (opts%has_wave) THEN
        CALL deck_wave_kinematics(opts, system%points(i)%q(1), system%points(i)%q(2), system%points(i)%q(3), &
                                  time, eta, wave_velocity, wave_acceleration, es, em)
        IF (es /= CD_HYDRO_OK) THEN
          ErrStat = CD_DECKDRV_BADINPUT
          ErrMsg = 'CableDyn_DeckDriver: point wave kinematics failed: '//TRIM(em)
          RETURN
        END IF
        work%fluid_velocity(:, i) = work%fluid_velocity(:, i) + wave_velocity
        work%fluid_acceleration(:, i) = work%fluid_acceleration(:, i) + wave_acceleration
        work%waterline(i) = eta
      END IF
    END DO
    fluid_density = opts%rhoW
    CALL CD_Update_System_Point_Fluid_Fields(system, work%fluid_velocity(:, 1:SIZE(system%points)), &
                                             work%fluid_acceleration(:, 1:SIZE(system%points)), &
                                             work%waterline(1:SIZE(system%points)), fluid_density, es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: point fluid-field update failed: '//TRIM(em)
      RETURN
    END IF
  END SUBROUTINE update_system_point_hydro

  SUBROUTINE ensure_hydro_workspace(work, ndof, nnode)
    TYPE(HydroUpdateWorkspace), INTENT(INOUT) :: work
    INTEGER, INTENT(IN) :: ndof, nnode
    LOGICAL :: need_q, need_fluid

    need_q = .NOT. ALLOCATED(work%q)
    IF (.NOT. need_q) need_q = SIZE(work%q) < ndof
    IF (need_q) THEN
      IF (ALLOCATED(work%q)) DEALLOCATE (work%q, work%v, work%a)
      ALLOCATE (work%q(ndof), work%v(ndof), work%a(ndof))
    END IF
    need_fluid = .NOT. ALLOCATED(work%waterline)
    IF (.NOT. need_fluid) need_fluid = SIZE(work%waterline) < nnode
    IF (need_fluid) THEN
      IF (ALLOCATED(work%waterline)) DEALLOCATE (work%fluid_velocity, work%fluid_acceleration, work%waterline)
      ALLOCATE (work%fluid_velocity(3, nnode), work%fluid_acceleration(3, nnode), work%waterline(nnode))
    END IF
  END SUBROUTINE ensure_hydro_workspace

  SUBROUTINE update_system_line_hydro(system, opts, time, work, ErrStat, ErrMsg, initial_condition)
    !! Refresh the contained EI=0 line-model hydro fields for point-system paths: sample
    !! the deck current/wave field at every node and hold it over the coming step. A
    !! march-step call leaves the committed line acceleration untouched (see
    !! update_wave_models); only the initial-condition call re-derives it.
    TYPE(CD_SystemType), INTENT(INOUT) :: system
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time
    TYPE(HydroUpdateWorkspace), INTENT(INOUT) :: work
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    LOGICAL, INTENT(IN), OPTIONAL :: initial_condition

    INTEGER :: i, j, ndof, nnode, es
    REAL(wp) :: eta, wave_velocity(3), wave_acceleration(3)
    LOGICAL :: at_initial_condition, changed
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    at_initial_condition = .FALSE.
    IF (PRESENT(initial_condition)) at_initial_condition = initial_condition
    IF (.NOT. (opts%has_wave .OR. opts%has_current)) RETURN
    IF (.NOT. system%initialized .OR. .NOT. ALLOCATED(system%lines)) THEN
      CALL fail(ErrStat, ErrMsg, 'line hydro update requires an initialized point-connected system')
      RETURN
    END IF
    DO i = 1, SIZE(system%lines)
      ndof = CD_Model_NDOF(system%lines(i), es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: system-line DOF query failed during hydro update: '//TRIM(em)
        RETURN
      END IF
      nnode = ndof/3
      CALL ensure_hydro_workspace(work, ndof, nnode)
      CALL CD_Get_Model_State(system%lines(i), work%q(1:ndof), work%v(1:ndof), work%a(1:ndof), es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: system-line state query failed during hydro update: '//TRIM(em)
        RETURN
      END IF
      DO j = 1, nnode
        wave_velocity = CD_ZERO
        wave_acceleration = CD_ZERO
        eta = CD_ZERO
        IF (opts%has_wave) THEN
          CALL deck_wave_kinematics(opts, work%q(3*j - 2), work%q(3*j - 1), work%q(3*j), time, eta, wave_velocity, &
                                    wave_acceleration, es, em)
          IF (es /= CD_HYDRO_OK) THEN
            ErrStat = CD_DECKDRV_BADINPUT
            ErrMsg = 'CableDyn_DeckDriver: system-line wave kinematics failed: '//TRIM(em)
            RETURN
          END IF
        END IF
        work%fluid_velocity(:, j) = wave_velocity
        IF (opts%has_current) THEN
          work%fluid_velocity(:, j) = work%fluid_velocity(:, j) + deck_current_velocity(opts, work%q(3*j), es, em)
          IF (es /= CD_HYDRO_OK) THEN
            ErrStat = CD_DECKDRV_BADINPUT
            ErrMsg = 'CableDyn_DeckDriver: system-line current profile failed: '//TRIM(em)
            RETURN
          END IF
        END IF
        work%fluid_acceleration(:, j) = wave_acceleration
        work%waterline(j) = eta
      END DO
      IF (opts%has_wave) THEN
        CALL CD_Update_Model_Hydro_Fields(system%lines(i), es, em, fluid_velocity=work%fluid_velocity(:, 1:nnode), &
                                          drag_waterline_z=work%waterline(1:nnode), &
                                          fluid_acceleration=work%fluid_acceleration(:, 1:nnode), &
                                          fk_waterline_z=work%waterline(1:nnode), &
                                          added_mass_waterline_z=work%waterline(1:nnode), &
                                          buoyancy_waterline_z=work%waterline(1:nnode), fields_changed=changed)
      ELSE
        CALL CD_Update_Model_Hydro_Fields(system%lines(i), es, em, fluid_velocity=work%fluid_velocity(:, 1:nnode), &
                                          drag_waterline_z=work%waterline(1:nnode), fields_changed=changed)
      END IF
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: system-line hydro-field update failed: '//TRIM(em)
        RETURN
      END IF
      ! The held field is the load over the NEXT interval; the committed acceleration
      ! belongs to the current station and is re-derived only at the initial condition.
      IF (.NOT. (at_initial_condition .AND. changed)) CYCLE
      CALL CD_Recompute_Model_Acceleration(system%lines(i), es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: system-line acceleration recompute after hydro update failed: '//TRIM(em)
        RETURN
      END IF
    END DO
  END SUBROUTINE update_system_line_hydro

  SUBROUTINE update_wave_models(models, opts, time, work, ErrStat, ErrMsg, initial_condition)
    !! Sample the deck current/wave field at every node of the standalone EI=0 line models
    !! and install it as the held fluid field for the coming step. The committed
    !! acceleration is the generalized-alpha ALGORITHMIC acceleration: a march-step call
    !! must not overwrite it with the equilibrium acceleration of the new field (doing so
    !! every step destroys the high-frequency dissipation -- grounded or contact-dominated
    !! lines then blow up, and a physically null current changes the answer). Only the
    !! initial-condition call (initial_condition = .TRUE., before the first step)
    !! re-derives the acceleration, and only for a line whose sampled field differs from
    !! the stored one, so a zero current is bit-identical to no current.
    TYPE(CD_ModelType), INTENT(INOUT) :: models(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time
    TYPE(HydroUpdateWorkspace), INTENT(INOUT) :: work
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    LOGICAL, INTENT(IN), OPTIONAL :: initial_condition

    INTEGER :: i, j, ndof, nnode, es
    REAL(wp) :: eta, wave_velocity(3), wave_acceleration(3)
    LOGICAL :: at_initial_condition, changed
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    at_initial_condition = .FALSE.
    IF (PRESENT(initial_condition)) at_initial_condition = initial_condition
    DO i = 1, SIZE(models)
      ndof = CD_Model_NDOF(models(i), es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: model DOF query failed during wave update: '//TRIM(em)
        RETURN
      END IF
      nnode = ndof/3
      CALL ensure_hydro_workspace(work, ndof, nnode)
      CALL CD_Get_Model_State(models(i), work%q(1:ndof), work%v(1:ndof), work%a(1:ndof), es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: model state query failed during wave update: '//TRIM(em)
        RETURN
      END IF
      DO j = 1, nnode
        wave_velocity = CD_ZERO
        wave_acceleration = CD_ZERO
        eta = CD_ZERO
        IF (opts%has_wave) THEN
          CALL deck_wave_kinematics(opts, work%q(3*j - 2), work%q(3*j - 1), work%q(3*j), time, eta, wave_velocity, &
                                    wave_acceleration, es, em)
          IF (es /= CD_HYDRO_OK) THEN
            ErrStat = CD_DECKDRV_BADINPUT
            ErrMsg = 'CableDyn_DeckDriver: wave kinematics failed: '//TRIM(em)
            RETURN
          END IF
        END IF
        work%waterline(j) = eta
        work%fluid_velocity(:, j) = wave_velocity
        IF (opts%has_current) THEN
          work%fluid_velocity(:, j) = work%fluid_velocity(:, j) + deck_current_velocity(opts, work%q(3*j), es, em)
          IF (es /= CD_HYDRO_OK) THEN
            ErrStat = CD_DECKDRV_BADINPUT
            ErrMsg = 'CableDyn_DeckDriver: model current profile failed: '//TRIM(em)
            RETURN
          END IF
        END IF
        work%fluid_acceleration(:, j) = wave_acceleration
      END DO
      IF (opts%has_wave) THEN
        CALL CD_Update_Model_Hydro_Fields(models(i), es, em, fluid_velocity=work%fluid_velocity(:, 1:nnode), &
                                          drag_waterline_z=work%waterline(1:nnode), &
                                          fluid_acceleration=work%fluid_acceleration(:, 1:nnode), &
                                          fk_waterline_z=work%waterline(1:nnode), &
                                          added_mass_waterline_z=work%waterline(1:nnode), &
                                          buoyancy_waterline_z=work%waterline(1:nnode), fields_changed=changed)
      ELSE
        CALL CD_Update_Model_Hydro_Fields(models(i), es, em, fluid_velocity=work%fluid_velocity(:, 1:nnode), &
                                          drag_waterline_z=work%waterline(1:nnode), fields_changed=changed)
      END IF
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: model wave-field update failed: '//TRIM(em)
        RETURN
      END IF
      IF (.NOT. (at_initial_condition .AND. changed)) CYCLE
      CALL CD_Recompute_Model_Acceleration(models(i), es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: acceleration recompute after wave update failed: '//TRIM(em)
        RETURN
      END IF
    END DO
  END SUBROUTINE update_wave_models

  SUBROUTINE check_model_plausibility(model, max_strain, line_id, time, ErrStat, ErrMsg)
    !! Per-step plausibility guard on one committed EI=0 line state. A generalized-alpha
    !! step can converge on a numerically unstable (exploding) trajectory; its residual
    !! test is then satisfied while the tensions are unphysical. The committed state
    !! fails here if any nodal position/velocity is non-finite or any element is
    !! stretched beyond max_strain (engineering strain; max_strain <= 0 disables the
    !! strain bound). The default bound (50 %) is several times the breaking strain of
    !! steel, polyester and nylon mooring lines, so a real run can never reach it.
    TYPE(CD_ModelType), INTENT(IN) :: model
    REAL(wp), INTENT(IN) :: max_strain, time
    INTEGER, INTENT(IN) :: line_id
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: e, na, nb, worst_elem
    REAL(wp) :: strain, worst_strain
    CHARACTER(200) :: detail

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (.NOT. model%initialized) RETURN
    IF (.NOT. (ALL(IEEE_IS_FINITE(model%q)) .AND. ALL(IEEE_IS_FINITE(model%v)))) THEN
      WRITE (detail, '(A,I0,A,ES12.5,A)') 'line ', line_id, ' has a non-finite nodal state at t = ', time, ' s'
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: plausibility guard: '//TRIM(detail)// &
               '; the dynamic solution is numerically unstable (reduce dtM)'
      RETURN
    END IF
    IF (.NOT. (max_strain > CD_ZERO)) RETURN
    worst_strain = -HUGE(CD_ONE)
    worst_elem = 0
    DO e = 1, model%n_elem
      na = model%elem_conn(1, e)
      nb = model%elem_conn(2, e)
      strain = NORM2(model%q(3*nb - 2:3*nb) - model%q(3*na - 2:3*na))/model%l0(e) - CD_ONE
      IF (strain > worst_strain) THEN
        worst_strain = strain
        worst_elem = e
      END IF
    END DO
    IF (worst_elem == 0 .OR. worst_strain <= max_strain) RETURN
    ! ES formats: a finite but enormous strain must not overflow the buffer (IOSTAT keeps the
    ! clean failure even then)
    WRITE (detail, '(A,I0,A,I0,A,ES10.3,A,ES10.3,A,ES12.5,A,ES10.3,A)', IOSTAT=e) 'line ', line_id, ' element ', &
      worst_elem, ' strain ', 100.0_wp*worst_strain, ' % exceeds maxStrain ', 100.0_wp*max_strain, ' % at t = ', &
      time, ' s (elastic tension ~', model%ea(worst_elem)*worst_strain, ' N)'
    ErrStat = CD_DECKDRV_SOLVEFAIL
    ErrMsg = 'CableDyn_DeckDriver: plausibility guard: '//TRIM(detail)// &
             '; the dynamic solution is numerically unstable -- reduce dtM (OPTION maxStrain sets the bound)'
  END SUBROUTINE check_model_plausibility

  SUBROUTINE check_models_plausibility(models, lines, max_strain, time, ErrStat, ErrMsg)
    !! The plausibility guard over the standalone EI=0 line models (models(i) is deck line i).
    TYPE(CD_ModelType), INTENT(IN) :: models(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    REAL(wp), INTENT(IN) :: max_strain, time
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: i, line_id

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    DO i = 1, SIZE(models)
      line_id = i
      IF (i <= SIZE(lines)) line_id = lines(i)%id
      CALL check_model_plausibility(models(i), max_strain, line_id, time, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END DO
  END SUBROUTINE check_models_plausibility

  SUBROUTINE CD_Check_System_Plausibility(system, max_strain, time, ErrStat, ErrMsg, lines)
    !! The plausibility guard over every EI=0 line of a point-connected system, for the
    !! standalone point/body/rod marches and the coupled OpenFAST step. lines (the deck
    !! lines, system line i = deck line i) only labels the message with deck line ids.
    TYPE(CD_SystemType), INTENT(IN) :: system
    REAL(wp), INTENT(IN) :: max_strain, time
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(DeckLine), INTENT(IN), OPTIONAL :: lines(:)
    INTEGER :: i, line_id

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (.NOT. ALLOCATED(system%lines)) RETURN
    DO i = 1, SIZE(system%lines)
      line_id = i
      IF (PRESENT(lines)) THEN
        IF (i <= SIZE(lines)) line_id = lines(i)%id
      END IF
      CALL check_model_plausibility(system%lines(i), max_strain, line_id, time, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END DO
  END SUBROUTINE CD_Check_System_Plausibility

  SUBROUTINE write_header(unit, channels)
    INTEGER, INTENT(IN) :: unit
    CHARACTER(NAMELEN), INTENT(IN) :: channels(:)
    INTEGER :: i

    WRITE (unit, '(A)', ADVANCE='NO') 'Time(s)'
    DO i = 1, SIZE(channels)
      WRITE (unit, '(A,A)', ADVANCE='NO') char_tab(), TRIM(channels(i))
    END DO
    WRITE (unit, '(A)') ''
  END SUBROUTINE write_header

  SUBROUTINE ensure_model_output_workspace(work, ndof, nelem)
    TYPE(ModelOutputWorkspace), INTENT(INOUT) :: work
    INTEGER, INTENT(IN) :: ndof, nelem
    LOGICAL :: need_q, need_tension

    IF (ndof > 0) THEN
      need_q = .NOT. ALLOCATED(work%q)
      IF (.NOT. need_q) need_q = SIZE(work%q) < ndof
      IF (need_q) THEN
        IF (ALLOCATED(work%q)) DEALLOCATE (work%q, work%v, work%a)
        ALLOCATE (work%q(ndof), work%v(ndof), work%a(ndof))
      END IF
    END IF
    IF (nelem > 0) THEN
      need_tension = .NOT. ALLOCATED(work%tension)
      IF (.NOT. need_tension) need_tension = SIZE(work%tension) < nelem
      IF (need_tension) THEN
        IF (ALLOCATED(work%tension)) DEALLOCATE (work%tension)
        ALLOCATE (work%tension(nelem))
      END IF
    END IF
  END SUBROUTINE ensure_model_output_workspace

  SUBROUTINE write_model_row(unit, time, channels, lines, points, models, work, ErrStat, ErrMsg, motion, &
                             motion_time_index)
    INTEGER, INTENT(IN) :: unit
    REAL(wp), INTENT(IN) :: time
    CHARACTER(NAMELEN), INTENT(IN) :: channels(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(CD_ModelType), INTENT(IN) :: models(:)
    TYPE(ModelOutputWorkspace), INTENT(INOUT) :: work
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(MotionTable), INTENT(IN), OPTIONAL :: motion
    INTEGER, INTENT(IN), OPTIONAL :: motion_time_index

    CALL write_planned_row(unit, time, channels, lines, points, work, '', ErrStat, ErrMsg, models=models, &
                           motion=motion, motion_time_index=motion_time_index)
  END SUBROUTINE write_model_row

  SUBROUTINE write_finite_model_row(unit, time, channels, lines, points, models, work, ErrStat, ErrMsg, &
                                    motion, motion_time_index)
    INTEGER, INTENT(IN) :: unit
    REAL(wp), INTENT(IN) :: time
    CHARACTER(NAMELEN), INTENT(IN) :: channels(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(FiniteDeckModel), INTENT(IN) :: models(:)
    TYPE(ModelOutputWorkspace), INTENT(INOUT) :: work
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(MotionTable), INTENT(IN), OPTIONAL :: motion
    INTEGER, INTENT(IN), OPTIONAL :: motion_time_index

    CALL write_planned_row(unit, time, channels, lines, points, work, 'finite-EI ', ErrStat, ErrMsg, &
                           fmodels=models, motion=motion, motion_time_index=motion_time_index)
  END SUBROUTINE write_finite_model_row

  SUBROUTINE write_system_model_row(unit, time, channels, lines, points, system, work, ErrStat, ErrMsg, rigid, &
                                    rods, opts, bathymetry)
    !! rigid/rods: the body and rod states that Body<N>/Rod<N> channels report.
    INTEGER, INTENT(IN) :: unit
    REAL(wp), INTENT(IN) :: time
    CHARACTER(NAMELEN), INTENT(IN) :: channels(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(CD_SystemType), INTENT(IN) :: system
    TYPE(ModelOutputWorkspace), INTENT(INOUT) :: work
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(RigidBodyState), INTENT(IN), OPTIONAL :: rigid(:)
    TYPE(RodState), INTENT(IN), OPTIONAL :: rods(:)
    ! the load context of the Body/Rod F, M, TenA, TenB and Sub channels
    TYPE(DeckOptions), INTENT(IN), OPTIONAL :: opts
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    CALL write_planned_row(unit, time, channels, lines, points, work, 'system ', ErrStat, ErrMsg, system=system, &
                           rigid=rigid, rods=rods, opts=opts, bathymetry=bathymetry)
  END SUBROUTINE write_system_model_row

  SUBROUTINE write_planned_row(unit, time, channels, lines, points, work, label, ErrStat, ErrMsg, models, &
                               fmodels, system, motion, motion_time_index, rigid, rods, opts, bathymetry)
    !! Shared dynamic .out row writer for the EI=0 line (`models`), finite-EI (`fmodels`)
    !! and point-system (`system`) paths; exactly one of the three is present. The
    !! channel list is resolved into descriptors on the first row, each referenced
    !! line's state and tensions are fetched at most once per row, and the row is
    !! emitted by one formatted WRITE. Values and text are identical to evaluating
    !! every channel through model_channel_value / finite_model_channel_value /
    !! system_channel_value: any channel the plan cannot resolve, and any per-row
    !! query failure, is delegated to that routine so its value or error is unchanged.
    !! On an error the row prefix up to the failing channel is left non-advancing.
    INTEGER, INTENT(IN) :: unit
    REAL(wp), INTENT(IN) :: time
    CHARACTER(NAMELEN), INTENT(IN) :: channels(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(ModelOutputWorkspace), INTENT(INOUT) :: work
    CHARACTER(*), INTENT(IN) :: label
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_ModelType), INTENT(IN), OPTIONAL :: models(:)
    TYPE(FiniteDeckModel), INTENT(IN), OPTIONAL :: fmodels(:)
    TYPE(CD_SystemType), INTENT(IN), OPTIONAL :: system
    TYPE(MotionTable), INTENT(IN), OPTIONAL :: motion
    INTEGER, INTENT(IN), OPTIONAL :: motion_time_index
    TYPE(RigidBodyState), INTENT(IN), OPTIONAL :: rigid(:)
    TYPE(RodState), INTENT(IN), OPTIONAL :: rods(:)
    TYPE(DeckOptions), INTENT(IN), OPTIONAL :: opts
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry

    INTEGER, PARAMETER :: CH_LEGACY = 0, CH_FAIRTEN = 1, CH_ANCHTEN = 2, CH_ANGLE = 3, CH_NODE_TEN = 4, &
                          CH_NODE_STATE = 5, CH_POINT_MOTION = 6, CH_POINT_FIXED = 7, CH_POINT_LINE = 8, &
                          CH_SYS_POINT = 9, CH_TDP = 10
    INTEGER :: i, k, n, li, off, nd, ne, nnode, stride, es
    LOGICAL :: has_motion, ok
    REAL(wp) :: val, q_point(3), v_point(3), a_point(3)
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    n = SIZE(channels)
    has_motion = PRESENT(motion) .AND. PRESENT(motion_time_index)
    stride = 3
    IF (PRESENT(fmodels)) stride = 6
    IF (.NOT. work%plan_ready) THEN
      CALL build_plan()
    ELSE IF (SIZE(work%ch_kind) /= n .OR. SIZE(work%line_ndof) /= SIZE(lines) .OR. &
             (work%plan_motion .NEQV. has_motion)) THEN
      CALL build_plan()
    END IF
    work%row = work%row + 1
    IF (work%rset%active) THEN
      CALL sample_ranges()
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END IF

    DO i = 1, n
      li = work%ch_line(i)
      SELECT CASE (work%ch_kind(i))
      CASE (CH_FAIRTEN, CH_ANCHTEN, CH_NODE_TEN)
        CALL fetch_tension(li, ok)
        IF (.NOT. ok) THEN
          CALL legacy_value(i, val)
        ELSE
          off = work%ten_off(li)
          ne = work%line_ne(li)
          IF (work%ch_kind(i) == CH_FAIRTEN) THEN
            val = work%line_ten(off + ne)
            CALL end_tension_override(li, ne + 1, ne, val)
          ELSE IF (work%ch_kind(i) == CH_ANCHTEN) THEN
            val = work%line_ten(off + 1)
            CALL end_tension_override(li, 1, ne, val)
          ELSE
            val = nodal_tension_value(work%line_ten(off + 1:off + ne), work%ch_node(i))
            CALL end_tension_override(li, work%ch_node(i), ne, val)
          END IF
        END IF
      CASE (CH_ANGLE, CH_NODE_STATE, CH_POINT_LINE)
        CALL fetch_state(li, ok)
        IF (.NOT. ok) THEN
          CALL legacy_value(i, val)
        ELSE
          off = work%state_off(li)
          nd = work%line_ndof(li)
          nnode = nd/stride
          IF (work%ch_kind(i) == CH_ANGLE) THEN
            val = line_geom_value(7, work%ch_node(i), nnode, work%line_q(off + 1:off + nd), stride)
            IF (work%ch_aux(i) == 1) val = val - 90.0_wp
          ELSE IF (work%ch_kind(i) == CH_POINT_LINE) THEN
            val = work%line_q(off + 3*(work%ch_node(i) - 1) + work%ch_comp(i))
          ELSE
            k = stride*(deck_to_internal_node(work%ch_node(i), nnode - 1) - 1) + work%ch_comp(i)
            SELECT CASE (work%ch_aux(i))
            CASE (1)   ! position
              val = work%line_q(off + k)
            CASE (2)   ! velocity
              val = work%line_v(off + k)
            CASE (4)   ! acceleration
              val = work%line_a(off + k)
            CASE DEFAULT   ! geometric channels (curvature / EI=0 bend moment / declination / azimuth)
              val = line_geom_value(work%ch_aux(i), work%ch_node(i), nnode, work%line_q(off + 1:off + nd), stride)
            END SELECT
          END IF
        END IF
      CASE (CH_POINT_MOTION)
        val = motion%q(work%ch_comp(i), work%ch_aux(i), motion_time_index)
      CASE (CH_POINT_FIXED)
        val = points(work%ch_aux(i))%pos(work%ch_comp(i))
      CASE (CH_TDP)
        val = work%rset%lines(li)%tdp(work%ch_comp(i))
      CASE (CH_SYS_POINT)
        CALL CD_Get_System_Point_State(system, work%ch_aux(i), q_point, v_point, a_point, es, em)
        IF (es /= CD_SYSTEM_OK) THEN
          CALL legacy_value(i, val)
        ELSE
          val = q_point(work%ch_comp(i))
        END IF
      CASE DEFAULT
        CALL legacy_value(i, val)
      END SELECT
      IF (ErrStat /= CD_DECKDRV_OK) THEN
        WRITE (unit, ROW_VALUES_FMT, ADVANCE='NO') time, (char_tab(), work%ch_val(k), k=1, i - 1)
        RETURN
      END IF
      IF (.NOT. IEEE_IS_FINITE(val)) THEN
        WRITE (unit, ROW_VALUES_FMT, ADVANCE='NO') time, (char_tab(), work%ch_val(k), k=1, i - 1)
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: non-finite '//label//'dynamic output channel "'//TRIM(channels(i))//'"'
        RETURN
      END IF
      work%ch_val(i) = val
    END DO
    WRITE (unit, ROW_VALUES_FMT) time, (char_tab(), work%ch_val(k), k=1, n)

  CONTAINS

    SUBROUTINE sample_ranges()
      !! Sample every line with a range file or TDP channel at this row's committed state.
      INTEGER :: il, es_r
      CHARACTER(512) :: em_r
      DO il = 1, SIZE(lines)
        IF (.NOT. CD_Range_Needs_Sample(work%rset, il)) CYCLE
        IF (PRESENT(models)) THEN
          CALL range_sample_model(models(il), work%rset%lines(il), ErrStat, ErrMsg)
        ELSE IF (PRESENT(fmodels)) THEN
          CALL range_sample_fmodel(fmodels(il), work%rset%lines(il), ErrStat, ErrMsg)
        ELSE
          CALL range_sample_model(system%lines(il), work%rset%lines(il), ErrStat, ErrMsg)
        END IF
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        CALL CD_Range_Commit_Sample(work%rset, il, time, es_r, em_r)
        CALL range_status(es_r, em_r, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      END DO
    END SUBROUTINE sample_ranges

    SUBROUTINE legacy_value(ich, v)
      !! Evaluate channel `ich` through the channel-at-a-time routine of the active path.
      INTEGER, INTENT(IN) :: ich
      REAL(wp), INTENT(OUT) :: v
      LOGICAL :: found
      v = CD_ZERO
      IF (CD_Is_TDP_Channel(to_lower(channels(ich)))) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(channels(ich))//'": no touchdown state on this route')
        RETURN
      END IF
      IF (is_object_channel(to_lower(channels(ich)))) THEN
        IF (PRESENT(opts) .AND. PRESENT(system)) THEN
          CALL object_channel_value(channels(ich), v, found, rigid, rods, points, opts, time, system, &
                                    ErrStat=ErrStat, ErrMsg=ErrMsg, bathymetry=bathymetry)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
        ELSE
          CALL object_channel_value(channels(ich), v, found, rigid, rods)
        END IF
        IF (.NOT. found) CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(channels(ich))//'": this route has no '// &
                                   'state for that body or rod')
        RETURN
      END IF
      IF (PRESENT(models)) THEN
        CALL model_channel_value(channels(ich), lines, points, models, work, v, ErrStat, ErrMsg, motion, &
                                 motion_time_index)
      ELSE IF (PRESENT(fmodels)) THEN
        CALL finite_model_channel_value(channels(ich), lines, points, fmodels, work, v, ErrStat, ErrMsg, &
                                        motion, motion_time_index)
      ELSE
        CALL system_channel_value(channels(ich), lines, points, system, work, v, ErrStat, ErrMsg)
      END IF
    END SUBROUTINE legacy_value

    SUBROUTINE fetch_state(il, fetched)
      !! Copy line `il`'s committed q/v/a into the row cache once per row.
      INTEGER, INTENT(IN) :: il
      LOGICAL, INTENT(OUT) :: fetched
      INTEGER :: o, m, es
      CHARACTER(160) :: msg
      fetched = work%state_row(il) == work%row
      IF (fetched) RETURN
      o = work%state_off(il)
      m = work%line_ndof(il)
      IF (PRESENT(models)) THEN
        CALL CD_Get_Model_State(models(il), work%line_q(o + 1:o + m), work%line_v(o + 1:o + m), &
                                work%line_a(o + 1:o + m), es, msg)
        fetched = es == CD_MODEL_OK
      ELSE IF (PRESENT(fmodels)) THEN
        CALL CD_Get_FiniteEI_Model_State(fmodels(il)%model, work%line_q(o + 1:o + m), work%line_v(o + 1:o + m), &
                                         work%line_a(o + 1:o + m), es, msg)
        fetched = es == 0
      ELSE
        CALL CD_Get_System_Line_State(system, il, work%line_q(o + 1:o + m), work%line_v(o + 1:o + m), &
                                      work%line_a(o + 1:o + m), es, msg)
        fetched = es == CD_SYSTEM_OK
      END IF
      IF (fetched) work%state_row(il) = work%row
    END SUBROUTINE fetch_state

    SUBROUTINE end_tension_override(il, inode, nel, v)
      !! EI=0 model/system lines: an end node reports the force the line exerts on its end
      !! point (end element tension + the end node's lumped loads) instead of the element
      !! tension; interior nodes and finite-EI models keep v.
      INTEGER, INTENT(IN) :: il, inode, nel
      REAL(wp), INTENT(INOUT) :: v
      INTEGER :: es_o
      CHARACTER(160) :: msg_o
      IF (inode /= 1 .AND. inode /= nel + 1) RETURN
      IF (PRESENT(models)) THEN
        CALL line_model_end_tension(models(il), inode, nel + 1, v, es_o, msg_o)
      ELSE IF (PRESENT(system)) THEN
        CALL line_model_end_tension(system%lines(il), inode, nel + 1, v, es_o, msg_o)
      ELSE
        RETURN
      END IF
      IF (es_o /= CD_DECKDRV_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: dynamic end-tension recovery failed: '//TRIM(msg_o)
      END IF
    END SUBROUTINE end_tension_override

    SUBROUTINE fetch_tension(il, fetched)
      !! Recover line `il`'s element tensions into the row cache once per row.
      INTEGER, INTENT(IN) :: il
      LOGICAL, INTENT(OUT) :: fetched
      INTEGER :: o, m, es
      CHARACTER(160) :: msg
      fetched = work%ten_row(il) == work%row
      IF (fetched) RETURN
      o = work%ten_off(il)
      m = work%line_ne(il)
      IF (PRESENT(models)) THEN
        CALL CD_Get_Model_Tension(models(il), work%line_ten(o + 1:o + m), es, msg)
        fetched = es == CD_MODEL_OK
      ELSE IF (PRESENT(fmodels)) THEN
        CALL finite_model_tension(fmodels(il), work%line_ten(o + 1:o + m), work, es, msg)
        fetched = es == CD_DECKDRV_OK
      ELSE
        CALL CD_Get_System_Line_Tension(system, il, work%line_ten(o + 1:o + m), es, msg)
        fetched = es == CD_SYSTEM_OK
      END IF
      IF (fetched) work%ten_row(il) = work%row
    END SUBROUTINE fetch_tension

    SUBROUTINE line_sizes(il, sized, tension_sized)
      !! Record line `il`'s state length and element count. `sized` is false when the
      !! DOF query fails; `tension_sized` additionally requires the tension length the
      !! channel-at-a-time routines use to agree with the node count.
      INTEGER, INTENT(IN) :: il
      LOGICAL, INTENT(OUT) :: sized, tension_sized
      INTEGER :: es, ndof_l, ne_l
      CHARACTER(160) :: msg
      tension_sized = .FALSE.
      IF (PRESENT(models)) THEN
        ndof_l = CD_Model_NDOF(models(il), es, msg)
        sized = es == CD_MODEL_OK
        ne_l = ndof_l/3 - 1
        tension_sized = sized
      ELSE IF (PRESENT(fmodels)) THEN
        ne_l = fmodels(il)%n_elem
        ndof_l = 6*(ne_l + 1)
        sized = .TRUE.
        tension_sized = .TRUE.
      ELSE
        ndof_l = CD_System_Line_NDOF(system, il, es, msg)
        sized = es == CD_SYSTEM_OK
        ne_l = ndof_l/3 - 1
        IF (sized) THEN
          tension_sized = CD_System_Line_NElem(system, il, es, msg) == ne_l
          tension_sized = tension_sized .AND. es == CD_SYSTEM_OK
        END IF
      END IF
      IF (.NOT. sized) RETURN
      work%line_ndof(il) = ndof_l
      work%line_ne(il) = ne_l
    END SUBROUTINE line_sizes

    SUBROUTINE build_plan()
      !! Resolve every channel name into a descriptor, mirroring the branch order of
      !! the channel-at-a-time routines; anything else stays CH_LEGACY.
      INTEGER :: j, il, nl, pidx, comp, kind, node, ppos, midx
      LOGICAL :: sized, tension_sized
      CHARACTER(NAMELEN) :: lo

      nl = SIZE(lines)
      IF (ALLOCATED(work%ch_kind)) DEALLOCATE (work%ch_kind, work%ch_line, work%ch_node, work%ch_comp, &
                                               work%ch_aux, work%ch_val)
      IF (ALLOCATED(work%line_ndof)) DEALLOCATE (work%line_ndof, work%line_ne, work%state_off, work%ten_off, &
                                                 work%state_row, work%ten_row)
      IF (ALLOCATED(work%line_q)) DEALLOCATE (work%line_q, work%line_v, work%line_a, work%line_ten)
      ALLOCATE (work%ch_kind(n), work%ch_line(n), work%ch_node(n), work%ch_comp(n), work%ch_aux(n), work%ch_val(n))
      ALLOCATE (work%line_ndof(nl), work%line_ne(nl), work%state_off(nl + 1), work%ten_off(nl + 1), &
                work%state_row(nl), work%ten_row(nl))
      work%ch_kind = CH_LEGACY
      work%ch_line = 1
      work%ch_node = 0
      work%ch_comp = 0
      work%ch_aux = 0
      work%ch_val = CD_ZERO
      work%line_ndof = 0
      work%line_ne = 0
      work%state_row = 0
      work%ten_row = 0
      work%row = 0

      DO j = 1, n
        lo = to_lower(channels(j))
        IF (starts_with(lo, 'fairten') .OR. starts_with(lo, 'anchten')) THEN
          il = find_line(lines, int_suffix(channels(j), 8))
          IF (il < 1) CYCLE
          CALL line_sizes(il, sized, tension_sized)
          IF (.NOT. tension_sized) CYCLE
          work%ch_line(j) = il
          work%ch_kind(j) = CH_ANCHTEN
          IF (starts_with(lo, 'fairten')) work%ch_kind(j) = CH_FAIRTEN
        ELSE IF (is_endpoint_angle_channel(lo)) THEN
          il = find_line(lines, endpoint_angle_line_id(channels(j)))
          IF (il < 1) CYCLE
          CALL line_sizes(il, sized, tension_sized)
          IF (.NOT. sized) CYCLE
          work%ch_line(j) = il
          work%ch_kind(j) = CH_ANGLE
          work%ch_node(j) = work%line_ndof(il)/stride
          IF (is_fair_endpoint_angle(lo)) work%ch_node(j) = 1
          IF (starts_with(lo, 'fairincl') .OR. starts_with(lo, 'anchincl')) work%ch_aux(j) = 1
        ELSE IF (CD_Is_TDP_Channel(lo)) THEN
          CALL CD_Parse_TDP_Channel(channels(j), il, comp)
          il = find_line(lines, il)
          IF (il < 1) CYCLE
          IF (.NOT. CD_Range_Needs_Sample(work%rset, il)) CYCLE
          work%ch_kind(j) = CH_TDP
          work%ch_line(j) = il
          work%ch_comp(j) = comp
        ELSE IF (is_point_force_channel(lo) .OR. is_object_channel(lo)) THEN
          CYCLE   ! evaluated channel-at-a-time (CH_LEGACY)
        ELSE IF (is_point_channel(lo)) THEN
          CALL parse_point_channel(channels(j), pidx, comp)
          work%ch_comp(j) = comp
          IF (PRESENT(models)) THEN
            IF (has_motion) THEN
              midx = find_motion_point(motion, pidx)
              IF (midx > 0) THEN
                work%ch_kind(j) = CH_POINT_MOTION
                work%ch_aux(j) = midx
                CYCLE
              END IF
            END IF
            ppos = point_index(points, pidx)
            IF (ppos == 0) CYCLE
            work%ch_kind(j) = CH_POINT_FIXED
            work%ch_aux(j) = ppos
            DO il = 1, nl
              IF (lines(il)%nodea /= pidx .AND. lines(il)%nodeb /= pidx) CYCLE
              CALL line_sizes(il, sized, tension_sized)
              IF (.NOT. sized) THEN
                work%ch_kind(j) = CH_LEGACY
              ELSE
                work%ch_kind(j) = CH_POINT_LINE
                work%ch_line(j) = il
                work%ch_node(j) = 1
                IF (lines(il)%nodea == pidx) work%ch_node(j) = work%line_ndof(il)/3
              END IF
              EXIT
            END DO
          ELSE IF (PRESENT(fmodels)) THEN
            ppos = point_index(points, pidx)
            IF (ppos == 0) CYCLE
            IF (has_motion .AND. (TRIM(points(ppos)%ptype) == 'coupled' .OR. &
                                  TRIM(points(ppos)%ptype) == 'vessel')) THEN
              midx = find_motion_point(motion, points(ppos)%id)
              IF (midx == 0) CYCLE
              work%ch_kind(j) = CH_POINT_MOTION
              work%ch_aux(j) = midx
            ELSE
              work%ch_kind(j) = CH_POINT_FIXED
              work%ch_aux(j) = ppos
            END IF
          ELSE
            IF (point_index(points, pidx) == 0) CYCLE
            work%ch_kind(j) = CH_SYS_POINT
            work%ch_aux(j) = pidx
          END IF
        ELSE
          CALL parse_line_node_channel(channels(j), il, node, kind, comp)
          il = find_line(lines, il)
          IF (il < 1) CYCLE
          CALL line_sizes(il, sized, tension_sized)
          IF (.NOT. sized) CYCLE
          IF (node < 1 .OR. node > work%line_ndof(il)/stride) CYCLE
          IF (kind == 3) THEN
            IF (.NOT. tension_sized) CYCLE
            work%ch_kind(j) = CH_NODE_TEN
            work%ch_node(j) = deck_to_internal_node(node, work%line_ne(il))
          ELSE
            ! The finite-EI material bend moment keeps its reference-curvature evaluator.
            IF (PRESENT(fmodels) .AND. kind == 6) CYCLE
            work%ch_kind(j) = CH_NODE_STATE
            work%ch_node(j) = node
            work%ch_aux(j) = kind
            work%ch_comp(j) = comp
          END IF
          work%ch_line(j) = il
        END IF
      END DO

      work%state_off(1) = 0
      work%ten_off(1) = 0
      DO il = 1, nl
        work%state_off(il + 1) = work%state_off(il) + work%line_ndof(il)
        work%ten_off(il + 1) = work%ten_off(il) + MAX(0, work%line_ne(il))
      END DO
      ALLOCATE (work%line_q(work%state_off(nl + 1)), work%line_v(work%state_off(nl + 1)), &
                work%line_a(work%state_off(nl + 1)), work%line_ten(work%ten_off(nl + 1)))
      work%plan_ready = .TRUE.
      work%plan_motion = has_motion
    END SUBROUTINE build_plan
  END SUBROUTINE write_planned_row

  SUBROUTINE start_driver_progress(progress, nstep, dt)
    !! Initialize a low-noise wall-clock progress report for a standalone march.
    !! Twenty committed-step updates (5% spacing) keep long PowerShell runs visible
    !! without putting terminal I/O in the per-step performance path.
    TYPE(DriverProgress), INTENT(OUT) :: progress
    INTEGER, INTENT(IN) :: nstep
    REAL(wp), INTENT(IN) :: dt

    progress%nstep = nstep
    progress%report_stride = MAX(1, (nstep + 19)/20)
    IF (nstep <= 0) RETURN
    CALL SYSTEM_CLOCK(progress%start_count, progress%count_rate)
    WRITE (output_unit, '(A,I0,A,F12.3,A,ES12.5,A)') &
      '  Dynamic simulation: ', nstep, ' step(s), simulated duration ', REAL(nstep, wp)*dt, &
      ' s, dtM = ', dt, ' s.'
    FLUSH (output_unit)
  END SUBROUTINE start_driver_progress

  SUBROUTINE update_driver_progress(progress, step, simulated_time)
    !! Report only committed steps. ETA is based on average elapsed wall time per
    !! committed step, so failed/retried nonlinear work is honestly included.
    TYPE(DriverProgress), INTENT(IN) :: progress
    INTEGER, INTENT(IN) :: step
    REAL(wp), INTENT(IN) :: simulated_time

    INTEGER(int64) :: now
    REAL(wp) :: elapsed, remaining, percent
    CHARACTER(16) :: elapsed_text, remaining_text

    IF (progress%nstep <= 0 .OR. step <= 0) RETURN
    IF (step < progress%nstep .AND. MOD(step, progress%report_stride) /= 0) RETURN
    CALL SYSTEM_CLOCK(now)
    IF (progress%count_rate > 0_int64 .AND. now >= progress%start_count) THEN
      elapsed = REAL(now - progress%start_count, wp)/REAL(progress%count_rate, wp)
    ELSE
      elapsed = CD_ZERO
    END IF
    remaining = CD_ZERO
    IF (step < progress%nstep .AND. elapsed > CD_ZERO) &
      remaining = elapsed*REAL(progress%nstep - step, wp)/REAL(step, wp)
    percent = 100.0_wp*REAL(step, wp)/REAL(progress%nstep, wp)
    elapsed_text = wall_time_text(elapsed)
    remaining_text = wall_time_text(remaining)
    WRITE (output_unit, '(A,F6.1,A,F12.3,A,A,A,A)') '  Progress: ', percent, '% | t = ', &
      simulated_time, ' s | elapsed ', TRIM(elapsed_text), ' | ETA ', TRIM(remaining_text)
    FLUSH (output_unit)
  END SUBROUTINE update_driver_progress

  PURE FUNCTION wall_time_text(seconds) RESULT(text)
    REAL(wp), INTENT(IN) :: seconds
    CHARACTER(16) :: text
    INTEGER :: total, hours, minutes, secs

    total = MAX(0, NINT(seconds))
    hours = total/3600
    minutes = MOD(total, 3600)/60
    secs = MOD(total, 60)
    WRITE (text, '(I3.3,A,I2.2,A,I2.2)') hours, ':', minutes, ':', secs
  END FUNCTION wall_time_text

  SUBROUTINE update_dynamic_completion_quality(time, step_converged, stalled, miss_count, consecutive_miss, &
                                               max_consecutive_miss, first_miss_time, last_miss_time)
    !! Accumulate nonlinear convergence quality for a completed dynamic step.
    REAL(wp), INTENT(IN) :: time
    LOGICAL, INTENT(IN) :: step_converged, stalled
    INTEGER, INTENT(INOUT) :: miss_count, consecutive_miss, max_consecutive_miss
    REAL(wp), INTENT(INOUT) :: first_miss_time, last_miss_time

    IF (step_converged .AND. .NOT. stalled) THEN
      consecutive_miss = 0
      RETURN
    END IF
    miss_count = miss_count + 1
    consecutive_miss = consecutive_miss + 1
    max_consecutive_miss = MAX(max_consecutive_miss, consecutive_miss)
    IF (miss_count == 1) first_miss_time = time
    last_miss_time = time
  END SUBROUTINE update_dynamic_completion_quality

  SUBROUTINE CD_Classify_Dynamic_Completion(label, nstep, miss_count, max_consecutive_miss, first_miss_time, &
                                            last_miss_time, converged, ErrStat, ErrMsg)
    !! Public classifier for completed finite-output dynamic marches. Any nonlinear
    !! convergence miss makes the run a solve failure. The output remains available
    !! for diagnosis, but callers must not treat it as an accepted response history.
    CHARACTER(*), INTENT(IN) :: label
    INTEGER, INTENT(IN) :: nstep, miss_count, max_consecutive_miss
    REAL(wp), INTENT(IN) :: first_miss_time, last_miss_time
    LOGICAL, INTENT(OUT) :: converged
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    CHARACTER(512) :: msg_buf
    INTEGER :: ios
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    converged = miss_count == 0
    IF (miss_count == 0) RETURN

    ! Format into a fixed local buffer, then truncating-assign to the caller's
    ! ErrMsg so a short caller buffer cannot raise an end-of-record I/O error.
    ErrStat = CD_DECKDRV_SOLVEFAIL
    ! G-format times stay readable beyond 1e5 s; IOSTAT keeps an over-long label from aborting
    WRITE (msg_buf, '(A,A,A,I0,A,I0,A,G0.6,A,G0.6,A,I0,A)', IOSTAT=ios) &
      'CableDyn_DeckDriver: ', TRIM(label), ' did not converge: ', miss_count, '/', nstep, &
      ' nonlinear convergence misses between t=', first_miss_time, ' and ', last_miss_time, &
      ' s; max consecutive misses=', max_consecutive_miss, ' (.out written for inspection only).'
    ErrMsg = msg_buf
  END SUBROUTINE CD_Classify_Dynamic_Completion

  SUBROUTINE system_channel_value(ch, lines, points, system, work, val, ErrStat, ErrMsg)
    CHARACTER(*), INTENT(IN) :: ch
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(CD_SystemType), INTENT(IN) :: system
    TYPE(ModelOutputWorkspace), INTENT(INOUT) :: work
    REAL(wp), INTENT(OUT) :: val
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: li, pidx, comp, kind, node, ndof, nnode, es, ne, inode
    REAL(wp) :: q_point(3), v_point(3), a_point(3)
    CHARACTER(NAMELEN) :: lo
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    val = CD_ZERO
    lo = to_lower(ch)
    IF (starts_with(lo, 'fairten') .OR. starts_with(lo, 'anchten')) THEN
      li = find_line(lines, int_suffix(ch, 8))
      ne = CD_System_Line_NElem(system, li, es, em)
      IF (es /= CD_SYSTEM_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: system element-count query failed: '//TRIM(em)
        RETURN
      END IF
      ! the force the line exerts on its end point (fairlead = internal last node)
      IF (starts_with(lo, 'fairten')) THEN
        CALL line_model_end_tension(system%lines(li), ne + 1, ne + 1, val, es, em)
      ELSE
        CALL line_model_end_tension(system%lines(li), 1, ne + 1, val, es, em)
      END IF
      IF (es /= CD_DECKDRV_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: system dynamic end-tension recovery failed: '//TRIM(em)
        RETURN
      END IF
    ELSE IF (is_endpoint_angle_channel(lo)) THEN
      li = find_line(lines, endpoint_angle_line_id(ch))
      ndof = CD_System_Line_NDOF(system, li, es, em)
      IF (es /= CD_SYSTEM_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: system DOF query failed for line-angle channel: '//TRIM(em)
        RETURN
      END IF
      nnode = ndof/3
      CALL ensure_model_output_workspace(work, ndof, 0)
      CALL CD_Get_System_Line_State(system, li, work%q(1:ndof), work%v(1:ndof), work%a(1:ndof), es, em)
      IF (es /= CD_SYSTEM_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: system state query failed for line-angle channel: '//TRIM(em)
        RETURN
      END IF
      IF (is_fair_endpoint_angle(lo)) THEN
        val = line_geom_value(7, 1, nnode, work%q(1:ndof), 3)          ! End A declination [deg]
      ELSE
        val = line_geom_value(7, nnode, nnode, work%q(1:ndof), 3)      ! End B declination [deg]
      END IF
      val = endpoint_angle_from_declination(lo, val)
    ELSE IF (is_point_force_channel(lo)) THEN
      ! walk the live endpoint bindings, not the parse-time deck topology: a FAILURE detach
      ! moves a line end onto a reserve point by rebinding it
      CALL system_point_force_value(ch, system, val, ErrStat, ErrMsg)
    ELSE IF (is_point_channel(lo)) THEN
      CALL parse_point_channel(ch, pidx, comp)
      IF (point_index(points, pidx) == 0) THEN
        ErrStat = CD_DECKDRV_BADINPUT
        ErrMsg = 'CableDyn_DeckDriver: system Point OUTPUT channel references an unknown point'
        RETURN
      END IF
      CALL CD_Get_System_Point_State(system, pidx, q_point, v_point, a_point, es, em)
      IF (es /= CD_SYSTEM_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: system point-state output failed: '//TRIM(em)
        RETURN
      END IF
      val = q_point(comp)
    ELSE
      CALL parse_line_node_channel(ch, li, node, kind, comp)
      li = find_line(lines, li)
      ndof = CD_System_Line_NDOF(system, li, es, em)
      IF (es /= CD_SYSTEM_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: system DOF query failed for line-node channel: '//TRIM(em)
        RETURN
      END IF
      nnode = ndof/3
      IF (node < 1 .OR. node > nnode) THEN
        ErrStat = CD_DECKDRV_BADINPUT
        ErrMsg = 'CableDyn_DeckDriver: system line-node OUTPUT channel node index is out of range'
        RETURN
      END IF
      inode = deck_to_internal_node(node, nnode - 1)
      IF (kind == 3) THEN
        CALL ensure_model_output_workspace(work, 0, nnode - 1)
        CALL CD_Get_System_Line_Tension(system, li, work%tension(1:nnode - 1), es, em)
        IF (es /= CD_SYSTEM_OK) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: system nodal tension recovery failed: '//TRIM(em)
          RETURN
        END IF
        val = nodal_tension_value(work%tension(1:nnode - 1), inode)
        ! an end node reports the line-end force (FairTen/AnchTen), as the planned writer does
        IF (inode == 1 .OR. inode == nnode) THEN
          CALL line_model_end_tension(system%lines(li), inode, nnode, val, es, em)
          IF (es /= CD_DECKDRV_OK) THEN
            ErrStat = CD_DECKDRV_SOLVEFAIL
            ErrMsg = 'CableDyn_DeckDriver: system end-tension recovery failed: '//TRIM(em)
            RETURN
          END IF
        END IF
      ELSE
        CALL ensure_model_output_workspace(work, ndof, 0)
        CALL CD_Get_System_Line_State(system, li, work%q(1:ndof), work%v(1:ndof), work%a(1:ndof), es, em)
        IF (es /= CD_SYSTEM_OK) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: system state query failed for line-node channel: '//TRIM(em)
          RETURN
        END IF
        SELECT CASE (kind)
        CASE (1)   ! position
          val = work%q(3*(inode - 1) + comp)
        CASE (2)   ! velocity
          val = work%v(3*(inode - 1) + comp)
        CASE (4)   ! acceleration
          val = work%a(3*(inode - 1) + comp)
        CASE DEFAULT   ! curvature (5) / bend moment (6, EI=0 => 0) / declination (7) / azimuth (8)
          val = line_geom_value(kind, node, nnode, work%q(1:ndof), 3)
        END SELECT
      END IF
    END IF
  END SUBROUTINE system_channel_value

  SUBROUTINE finite_model_channel_value(ch, lines, points, models, work, val, ErrStat, ErrMsg, motion, &
                                        motion_time_index)
    CHARACTER(*), INTENT(IN) :: ch
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(FiniteDeckModel), INTENT(IN) :: models(:)
    TYPE(ModelOutputWorkspace), INTENT(INOUT) :: work
    REAL(wp), INTENT(OUT) :: val
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(MotionTable), INTENT(IN), OPTIONAL :: motion
    INTEGER, INTENT(IN), OPTIONAL :: motion_time_index

    INTEGER :: li, pidx, comp, kind, node, nnode, es, inode, ppos, midx
    CHARACTER(NAMELEN) :: lo
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    val = CD_ZERO
    lo = to_lower(ch)
    IF (is_point_force_channel(lo)) THEN
      CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": Point<P>F channels are not available on the '// &
                'two-moving-end finite-EI route (use FairTen/AnchTen)')
      RETURN
    END IF
    IF (starts_with(lo, 'fairten') .OR. starts_with(lo, 'anchten')) THEN
      li = find_line(lines, int_suffix(ch, 8))
      CALL ensure_model_output_workspace(work, 0, models(li)%n_elem)
      CALL finite_model_tension(models(li), work%tension(1:models(li)%n_elem), work, es, em)
      IF (es /= CD_DECKDRV_OK) THEN
        ErrStat = es
        ErrMsg = em
        RETURN
      END IF
      IF (starts_with(lo, 'fairten')) THEN
        val = work%tension(models(li)%n_elem)
      ELSE
        val = work%tension(1)
      END IF
    ELSE IF (is_endpoint_angle_channel(lo)) THEN
      li = find_line(lines, endpoint_angle_line_id(ch))
      nnode = models(li)%n_elem + 1
      CALL ensure_model_output_workspace(work, 6*nnode, 0)
      CALL CD_Get_FiniteEI_Model_State(models(li)%model, work%q(1:6*nnode), work%v(1:6*nnode), &
                                       work%a(1:6*nnode), es, em)
      IF (es /= 0) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: finite-EI state query failed for line-angle channel: '//TRIM(em)
        RETURN
      END IF
      IF (is_fair_endpoint_angle(lo)) THEN
        val = line_geom_value(7, 1, nnode, work%q(1:6*nnode), 6)          ! End A declination [deg]
      ELSE
        val = line_geom_value(7, nnode, nnode, work%q(1:6*nnode), 6)      ! End B declination [deg]
      END IF
      val = endpoint_angle_from_declination(lo, val)
    ELSE IF (is_point_channel(lo)) THEN
      CALL parse_point_channel(ch, pidx, comp)
      ppos = point_index(points, pidx)
      IF (ppos == 0) THEN
        ErrStat = CD_DECKDRV_BADINPUT
        ErrMsg = 'CableDyn_DeckDriver: finite-EI Point OUTPUT channel references an unknown point'
        RETURN
      END IF
      IF (PRESENT(motion) .AND. PRESENT(motion_time_index) .AND. &
          (TRIM(points(ppos)%ptype) == 'coupled' .OR. TRIM(points(ppos)%ptype) == 'vessel')) THEN
        midx = find_motion_point(motion, points(ppos)%id)
        IF (midx == 0) THEN
          ErrStat = CD_DECKDRV_BADINPUT
          ErrMsg = 'CableDyn_DeckDriver: finite-EI motion output missing point id '//TRIM(int_to_str(points(ppos)%id))
          RETURN
        END IF
        val = motion%q(comp, midx, motion_time_index)
      ELSE
        val = points(ppos)%pos(comp)
      END IF
    ELSE
      CALL parse_line_node_channel(ch, li, node, kind, comp)
      li = find_line(lines, li)
      nnode = models(li)%n_elem + 1
      IF (node < 1 .OR. node > nnode) THEN
        ErrStat = CD_DECKDRV_BADINPUT
        ErrMsg = 'CableDyn_DeckDriver: finite-EI line-node OUTPUT channel node index is out of range'
        RETURN
      END IF
      inode = deck_to_internal_node(node, models(li)%n_elem)
      IF (kind == 3) THEN
        CALL ensure_model_output_workspace(work, 0, models(li)%n_elem)
        CALL finite_model_tension(models(li), work%tension(1:models(li)%n_elem), work, es, em)
        IF (es /= CD_DECKDRV_OK) THEN
          ErrStat = es
          ErrMsg = em
          RETURN
        END IF
        val = nodal_tension_value(work%tension(1:models(li)%n_elem), inode)
      ELSE
        CALL ensure_model_output_workspace(work, 6*nnode, 0)
        CALL CD_Get_FiniteEI_Model_State(models(li)%model, work%q(1:6*nnode), work%v(1:6*nnode), &
                                         work%a(1:6*nnode), es, em)
        IF (es /= 0) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: finite-EI state query failed for line-node channel: '//TRIM(em)
          RETURN
        END IF
        SELECT CASE (kind)
        CASE (1)   ! position
          val = work%q(6*(inode - 1) + comp)
        CASE (2)   ! velocity
          val = work%v(6*(inode - 1) + comp)
        CASE (4)   ! acceleration
          val = work%a(6*(inode - 1) + comp)
        CASE (6)   ! bend moment [N.m] = EI(node) * |kvec_current - kvec_reference|
          BLOCK
            REAL(wp) :: r_cur(3, nnode), kc(3), kr(3)
            INTEGER :: nn
            ! OrcaFlex-convention bend moment: EI*|kappa - kappa_ref|, the curvature RELATIVE
            ! to the stress-free reference shape, so a cable resting at its reference reports
            ! ~0. On this route the reference (nodes_ref) is a straight rod, so kappa_ref = 0
            ! and the value is EI times the geometric curvature.
            DO nn = 1, nnode
              r_cur(:, nn) = work%q(6*nn - 5:6*nn - 3)
            END DO
            kc = node_curvature_vector(r_cur, nnode, inode)
            kr = node_curvature_vector(models(li)%model%nodes_ref, nnode, inode)
            val = nodal_ei_value(models(li)%ei, inode)*NORM2(kc - kr)
          END BLOCK
        CASE DEFAULT   ! curvature (5) / declination (7) / azimuth (8) -- geometric
          val = line_geom_value(kind, node, nnode, work%q(1:6*nnode), 6)
        END SELECT
      END IF
    END IF
  END SUBROUTINE finite_model_channel_value

  SUBROUTINE finite_model_tension(deck_model, tension, work, ErrStat, ErrMsg)
    !! Recover an axial-tension scalar per element from the translational stretch.
    !! This is an output diagnostic for deck channels; the dynamic residual still
    !! uses the full Cosserat internal force/tangent.
    TYPE(FiniteDeckModel), INTENT(IN) :: deck_model
    REAL(wp), INTENT(OUT) :: tension(:)
    TYPE(ModelOutputWorkspace), INTENT(INOUT) :: work
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: e, es, nnode
    REAL(wp) :: xa(3), xb(3), length
    CHARACTER(160) :: em

    tension = CD_ZERO
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (SIZE(tension) /= deck_model%n_elem) THEN
      CALL fail(ErrStat, ErrMsg, 'finite-EI tension output has wrong shape')
      RETURN
    END IF
    nnode = deck_model%n_elem + 1
    CALL ensure_model_output_workspace(work, 6*nnode, 0)
    CALL CD_Get_FiniteEI_Model_State(deck_model%model, work%q(1:6*nnode), work%v(1:6*nnode), &
                                     work%a(1:6*nnode), es, em)
    IF (es /= 0) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: finite-EI tension state query failed: '//TRIM(em)
      RETURN
    END IF
    DO e = 1, deck_model%n_elem
      xa = work%q(6*e - 5:6*e - 3)
      xb = work%q(6*(e + 1) - 5:6*(e + 1) - 3)
      length = SQRT(DOT_PRODUCT(xb - xa, xb - xa))
      tension(e) = deck_model%ea(e)*(length/deck_model%l0(e) - CD_ONE)
    END DO
  END SUBROUTINE finite_model_tension

  SUBROUTINE model_channel_value(ch, lines, points, models, work, val, ErrStat, ErrMsg, motion, motion_time_index)
    CHARACTER(*), INTENT(IN) :: ch
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(CD_ModelType), INTENT(IN) :: models(:)
    TYPE(ModelOutputWorkspace), INTENT(INOUT) :: work
    REAL(wp), INTENT(OUT) :: val
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(MotionTable), INTENT(IN), OPTIONAL :: motion
    INTEGER, INTENT(IN), OPTIONAL :: motion_time_index

    INTEGER :: li, pidx, comp, kind, node, ndof, nnode, es, ne, inode, midx
    CHARACTER(NAMELEN) :: lo
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    val = CD_ZERO
    lo = to_lower(ch)
    IF (starts_with(lo, 'fairten') .OR. starts_with(lo, 'anchten')) THEN
      li = find_line(lines, int_suffix(ch, 8))
      ne = model_nelem_from_line(lines(li), models(li), es, em)
      IF (es /= CD_DECKDRV_OK) THEN
        ErrStat = es
        ErrMsg = em
        RETURN
      END IF
      ! the force the line exerts on its end point (fairlead = internal last node)
      IF (starts_with(lo, 'fairten')) THEN
        CALL line_model_end_tension(models(li), ne + 1, ne + 1, val, es, em)
      ELSE
        CALL line_model_end_tension(models(li), 1, ne + 1, val, es, em)
      END IF
      IF (es /= CD_DECKDRV_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: dynamic end-tension recovery failed: '//TRIM(em)
        RETURN
      END IF
    ELSE IF (is_endpoint_angle_channel(lo)) THEN
      li = find_line(lines, endpoint_angle_line_id(ch))
      ndof = CD_Model_NDOF(models(li), es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: model DOF query failed for line-angle channel: '//TRIM(em)
        RETURN
      END IF
      nnode = ndof/3
      CALL ensure_model_output_workspace(work, ndof, 0)
      CALL CD_Get_Model_State(models(li), work%q(1:ndof), work%v(1:ndof), work%a(1:ndof), es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: model state query failed for line-angle channel: '//TRIM(em)
        RETURN
      END IF
      IF (is_fair_endpoint_angle(lo)) THEN
        val = line_geom_value(7, 1, nnode, work%q(1:ndof), 3)          ! End A declination [deg]
      ELSE
        val = line_geom_value(7, nnode, nnode, work%q(1:ndof), 3)      ! End B declination [deg]
      END IF
      val = endpoint_angle_from_declination(lo, val)
    ELSE IF (is_point_force_channel(lo)) THEN
      CALL point_force_value(ch, lines, models, val, ErrStat, ErrMsg)
    ELSE IF (is_point_channel(lo)) THEN
      CALL parse_point_channel(ch, pidx, comp)
      IF (PRESENT(motion) .AND. PRESENT(motion_time_index)) THEN
        midx = find_motion_point(motion, pidx)
        IF (midx > 0) THEN
          val = motion%q(comp, midx, motion_time_index)
        ELSE
          CALL model_point_channel_value(pidx, comp, lines, points, models, work, val, ErrStat, ErrMsg)
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
        END IF
      ELSE
        CALL model_point_channel_value(pidx, comp, lines, points, models, work, val, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      END IF
    ELSE
      CALL parse_line_node_channel(ch, li, node, kind, comp)
      li = find_line(lines, li)
      ndof = CD_Model_NDOF(models(li), es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: model DOF query failed for line-node channel: '//TRIM(em)
        RETURN
      END IF
      nnode = ndof/3
      IF (node < 1 .OR. node > nnode) THEN
        ErrStat = CD_DECKDRV_BADINPUT
        ErrMsg = 'CableDyn_DeckDriver: line-node OUTPUT channel node index is out of range'
        RETURN
      END IF
      inode = deck_to_internal_node(node, nnode - 1)
      IF (kind == 3) THEN
        CALL ensure_model_output_workspace(work, 0, nnode - 1)
        CALL CD_Get_Model_Tension(models(li), work%tension(1:nnode - 1), es, em)
        IF (es /= CD_MODEL_OK) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: dynamic nodal tension recovery failed: '//TRIM(em)
          RETURN
        END IF
        val = nodal_tension_value(work%tension(1:nnode - 1), inode)
        ! an end node reports the line-end force (FairTen/AnchTen), as the planned writer does
        IF (inode == 1 .OR. inode == nnode) THEN
          CALL line_model_end_tension(models(li), inode, nnode, val, es, em)
          IF (es /= CD_DECKDRV_OK) THEN
            ErrStat = CD_DECKDRV_SOLVEFAIL
            ErrMsg = 'CableDyn_DeckDriver: dynamic end-tension recovery failed: '//TRIM(em)
            RETURN
          END IF
        END IF
      ELSE
        CALL ensure_model_output_workspace(work, ndof, 0)
        CALL CD_Get_Model_State(models(li), work%q(1:ndof), work%v(1:ndof), work%a(1:ndof), es, em)
        IF (es /= CD_MODEL_OK) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: model state query failed for line-node channel: '//TRIM(em)
          RETURN
        END IF
        SELECT CASE (kind)
        CASE (1)   ! position
          val = work%q(3*(inode - 1) + comp)
        CASE (2)   ! velocity
          val = work%v(3*(inode - 1) + comp)
        CASE (4)   ! acceleration
          val = work%a(3*(inode - 1) + comp)
        CASE DEFAULT   ! curvature (5) / bend moment (6, EI=0 => 0) / declination (7) / azimuth (8)
          val = line_geom_value(kind, node, nnode, work%q(1:ndof), 3)
        END SELECT
      END IF
    END IF
  END SUBROUTINE model_channel_value

  SUBROUTINE model_point_channel_value(point_id, comp, lines, points, models, work, val, ErrStat, ErrMsg)
    !! Dynamic independent-line point output. Deck point coordinates are immutable
    !! parse data, so line endpoints must be read from the current model state after
    !! held or prescribed-motion updates.
    INTEGER, INTENT(IN) :: point_id, comp
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(CD_ModelType), INTENT(IN) :: models(:)
    TYPE(ModelOutputWorkspace), INTENT(INOUT) :: work
    REAL(wp), INTENT(OUT) :: val
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i, es, ndof, nnode, internal_node, ppos
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    ppos = point_index(points, point_id)
    IF (ppos == 0) THEN
      ErrStat = CD_DECKDRV_BADINPUT
      ErrMsg = 'CableDyn_DeckDriver: Point OUTPUT channel references an unknown point'
      RETURN
    END IF
    val = points(ppos)%pos(comp)
    DO i = 1, SIZE(lines)
      internal_node = 0
      IF (lines(i)%nodea == point_id) THEN
        ndof = CD_Model_NDOF(models(i), es, em)
        IF (es /= CD_MODEL_OK) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: model DOF query failed for point channel: '//TRIM(em)
          RETURN
        END IF
        nnode = ndof/3
        internal_node = nnode
      ELSE IF (lines(i)%nodeb == point_id) THEN
        internal_node = 1
        ndof = CD_Model_NDOF(models(i), es, em)
        IF (es /= CD_MODEL_OK) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: model DOF query failed for point channel: '//TRIM(em)
          RETURN
        END IF
        nnode = ndof/3
      END IF
      IF (internal_node > 0) THEN
        CALL ensure_model_output_workspace(work, ndof, 0)
        CALL CD_Get_Model_State(models(i), work%q(1:ndof), work%v(1:ndof), work%a(1:ndof), es, em)
        IF (es /= CD_MODEL_OK) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: model state query failed for point channel: '//TRIM(em)
          RETURN
        END IF
        val = work%q(3*(internal_node - 1) + comp)
        RETURN
      END IF
    END DO
  END SUBROUTINE model_point_channel_value

  INTEGER FUNCTION model_nelem_from_line(line, model, ErrStat, ErrMsg) RESULT(ne)
    TYPE(DeckLine), INTENT(IN) :: line
    TYPE(CD_ModelType), INTENT(IN) :: model
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: ndof, es
    CHARACTER(160) :: em

    ndof = CD_Model_NDOF(model, es, em)
    IF (es /= CD_MODEL_OK) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: model DOF query failed for LINE '//TRIM(int_to_str(line%id))//': '//TRIM(em)
      ne = 0
      RETURN
    END IF
    ne = ndof/3 - 1
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
  END FUNCTION model_nelem_from_line

  SUBROUTINE seed_finite_initial_acceleration(models, opts, ErrStat, ErrMsg)
    !! Recompute each finite-EI line's stored initial acceleration so it is consistent with the
    !! t=0 configuration-dependent loads the in-loop callback applies during the first step:
    !! seabed contact AND the current/wave environment force. CD_Init_FiniteEI_Model builds a_0
    !! from gravity/buoyancy (base_f_ext) alone, so without this seed the first generalized-alpha
    !! predictor starts from an a_0 inconsistent with the residual -- injecting a spurious startup
    !! transient for grounded or hydrodynamically loaded finite-EI cables. Mirrors the EI=0 path's
    !! update_wave_models recompute at t=0. The stored load is restored to base_f_ext afterwards
    !! so the per-step reset invariant in step_finite_held_models is preserved (the contact/env
    !! contribution is re-added through the callback each step and must not be double-counted).
    TYPE(FiniteDeckModel), INTENT(INOUT) :: models(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i, es
    LOGICAL :: use_live_env
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    use_live_env = opts%has_current .OR. opts%has_wave
    DO i = 1, SIZE(models)
      IF (.NOT. (models(i)%has_seabed .OR. use_live_env)) CYCLE
      CALL CD_Get_FiniteEI_Model_State(models(i)%model, models(i)%q_work, models(i)%v_work, &
                                       models(i)%a_work, es, em)
      IF (es /= 0) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: finite-EI state query before initial-load seed failed: '//TRIM(em)
        RETURN
      END IF
      models(i)%contact_work = CD_ZERO
      models(i)%env_work = CD_ZERO
      IF (models(i)%has_seabed) THEN
        IF (models(i)%has_bathymetry) THEN
          CALL finite_bathymetry_contact_force(models(i)%q_work, models(i)%v_work, models(i)%bathymetry, &
                                               models(i)%seabed_kn, models(i)%seabed_cn, opts%friction_mu, &
                                               models(i)%contact_work, ErrStat, ErrMsg)
        ELSE
          CALL finite_seabed_contact_force(models(i)%q_work, models(i)%v_work, models(i)%seabed_z_floor, &
                                           models(i)%seabed_kn, models(i)%seabed_cn, opts%friction_mu, &
                                           models(i)%contact_work, ErrStat, ErrMsg)
        END IF
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      END IF
      IF (use_live_env) THEN
        CALL finite_environment_force(models(i), opts, CD_ZERO, models(i)%q_work, models(i)%v_work, &
                                      models(i)%env_work, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      END IF
      models(i)%f_ext_work = models(i)%base_f_ext + models(i)%contact_work + models(i)%env_work
      CALL CD_Set_FiniteEI_Model_Load(models(i)%model, models(i)%f_ext_work, es, em, &
                                      recompute_acceleration=.TRUE.)
      IF (es /= 0) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: finite-EI initial-acceleration seed failed: '//TRIM(em)
        RETURN
      END IF
      models(i)%f_ext_work = models(i)%base_f_ext
      CALL CD_Set_FiniteEI_Model_Load(models(i)%model, models(i)%f_ext_work, es, em, &
                                      recompute_acceleration=.FALSE.)
      IF (es /= 0) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: finite-EI load restore after seed failed: '//TRIM(em)
        RETURN
      END IF
    END DO
  END SUBROUTINE seed_finite_initial_acceleration

  SUBROUTINE step_finite_held_models(models, opts, time, dt, converged, stalled, n_iter, ErrStat, ErrMsg, &
                                     motion, lines, points, time_index)
    !! Advance every finite-EI line model one step. With no motion arguments the prescribed
    !! endpoints are HELD at their stored positions. When motion/lines/points/time_index are
    !! supplied (together), each line's prescribed endpoint translations follow the motionFile
    !! trajectory to t_{n+1} as a MOVING support (their velocity/acceleration couple into the
    !! dynamic residual), rather than being teleported-and-held.
    TYPE(FiniteDeckModel), INTENT(INOUT) :: models(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    REAL(wp), INTENT(IN) :: time
    REAL(wp), INTENT(IN) :: dt
    LOGICAL, INTENT(OUT) :: converged, stalled
    INTEGER, INTENT(OUT) :: n_iter, ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(MotionTable), INTENT(IN), OPTIONAL :: motion
    TYPE(DeckLine), INTENT(IN), OPTIONAL :: lines(:)
    TYPE(DeckPoint), INTENT(IN), OPTIONAL :: points(:)
    INTEGER, INTENT(IN), OPTIONAL :: time_index

    INTEGER :: i, es, line_iter, active_model
    LOGICAL :: line_converged, line_stalled, use_motion, use_live_env, line_has_live_load
    CHARACTER(160) :: em

    converged = .TRUE.
    stalled = .FALSE.
    n_iter = 0
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    use_motion = PRESENT(motion) .AND. PRESENT(lines) .AND. PRESENT(points) .AND. PRESENT(time_index)
    use_live_env = opts%has_current .OR. opts%has_wave
    active_model = 0
    DO i = 1, SIZE(models)
      line_has_live_load = models(i)%has_seabed .OR. use_live_env
      IF (line_has_live_load) THEN
        CALL CD_Get_FiniteEI_Model_State(models(i)%model, models(i)%q_work, models(i)%v_work, models(i)%a_work, es, em)
        IF (es /= 0) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: finite-EI state query before load update failed: '//TRIM(em)
          RETURN
        END IF
        models(i)%f_ext_work = models(i)%base_f_ext
        CALL CD_Set_FiniteEI_Model_Load(models(i)%model, models(i)%f_ext_work, es, em, &
                                        recompute_acceleration=.FALSE.)
        IF (es /= 0) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: finite-EI load update failed: '//TRIM(em)
          RETURN
        END IF
      END IF
      active_model = i
      IF (use_motion) THEN
        CALL finite_motion_targets(models(i), lines(i), points, motion, time_index, models(i)%q_fixed_work, &
                                   models(i)%v_fixed_work, models(i)%a_fixed_work, ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
        IF (line_has_live_load) THEN
          ! a live load always carries its banded tangent
          CALL CD_Step_FiniteEI_Model(models(i)%model, dt, line_converged, line_stalled, line_iter, es, em, &
                                      q_fixed_target=models(i)%q_fixed_work, v_fixed_target=models(i)%v_fixed_work, &
                                      a_fixed_target=models(i)%a_fixed_work, &
                                      load_force_proc=finite_deck_dynamic_force, &
                                      load_band_proc=finite_deck_dynamic_load_banded)
        ELSE
          CALL CD_Step_FiniteEI_Model(models(i)%model, dt, line_converged, line_stalled, line_iter, es, em, &
                                      q_fixed_target=models(i)%q_fixed_work, v_fixed_target=models(i)%v_fixed_work, &
                                      a_fixed_target=models(i)%a_fixed_work)
        END IF
      ELSE
        IF (line_has_live_load) THEN
          CALL CD_Step_FiniteEI_Model(models(i)%model, dt, line_converged, line_stalled, line_iter, es, em, &
                                      load_force_proc=finite_deck_dynamic_force, &
                                      load_band_proc=finite_deck_dynamic_load_banded)
        ELSE
          CALL CD_Step_FiniteEI_Model(models(i)%model, dt, line_converged, line_stalled, line_iter, es, em)
        END IF
      END IF
      IF (es /= 0) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: finite-EI dynamic step failed: '//TRIM(em)
        RETURN
      END IF
      converged = converged .AND. line_converged
      stalled = stalled .OR. line_stalled
      n_iter = MAX(n_iter, line_iter)
    END DO

  CONTAINS

    SUBROUTINE finite_deck_dynamic_force(q_in, v_in, force, ErrStatCb, ErrMsgCb)
      REAL(wp), INTENT(IN) :: q_in(:), v_in(:)
      REAL(wp), INTENT(OUT) :: force(:)
      INTEGER, INTENT(OUT) :: ErrStatCb
      CHARACTER(*), INTENT(OUT) :: ErrMsgCb

      force = CD_ZERO
      ErrStatCb = CD_DECKDRV_OK
      ErrMsgCb = ''
      IF (active_model < 1 .OR. active_model > SIZE(models)) THEN
        ErrStatCb = CD_DECKDRV_SOLVEFAIL
        ErrMsgCb = 'finite-EI dynamic force callback has no active model'
        RETURN
      END IF
      IF (SIZE(q_in) /= SIZE(force) .OR. SIZE(v_in) /= SIZE(force) .OR. &
          SIZE(force) /= SIZE(models(active_model)%base_f_ext)) THEN
        ErrStatCb = CD_DECKDRV_SOLVEFAIL
        ErrMsgCb = 'finite-EI dynamic force callback shape mismatch'
        RETURN
      END IF
      models(active_model)%env_work = CD_ZERO
      models(active_model)%contact_work = CD_ZERO
      IF (models(active_model)%has_seabed) THEN
        IF (models(active_model)%has_bathymetry) THEN
          CALL finite_bathymetry_contact_force(q_in, v_in, models(active_model)%bathymetry, &
                                               models(active_model)%seabed_kn, models(active_model)%seabed_cn, &
                                               opts%friction_mu, models(active_model)%contact_work, ErrStatCb, ErrMsgCb)
        ELSE
          CALL finite_seabed_contact_force(q_in, v_in, models(active_model)%seabed_z_floor, &
                                           models(active_model)%seabed_kn, models(active_model)%seabed_cn, &
                                           opts%friction_mu, models(active_model)%contact_work, ErrStatCb, ErrMsgCb)
        END IF
        IF (ErrStatCb /= CD_DECKDRV_OK) RETURN
      END IF
      IF (opts%has_current .OR. opts%has_wave) THEN
        CALL finite_environment_force(models(active_model), opts, time, q_in, v_in, models(active_model)%env_work, &
                                      ErrStatCb, ErrMsgCb)
        IF (ErrStatCb /= CD_DECKDRV_OK) RETURN
      END IF
      force = models(active_model)%contact_work + models(active_model)%env_work
    END SUBROUTINE finite_deck_dynamic_force

    SUBROUTINE finite_deck_dynamic_load_banded(q_in, v_in, free, kl, ku, force, jac_q_band, jac_v_band, &
                                               ErrStatCb, ErrMsgCb)
      REAL(wp), INTENT(IN) :: q_in(:), v_in(:)
      INTEGER, INTENT(IN) :: free(:), kl, ku
      REAL(wp), INTENT(OUT) :: force(:), jac_q_band(:, :), jac_v_band(:, :)
      INTEGER, INTENT(OUT) :: ErrStatCb
      CHARACTER(*), INTENT(OUT) :: ErrMsgCb

      force = CD_ZERO
      jac_q_band = CD_ZERO
      jac_v_band = CD_ZERO
      ErrStatCb = CD_DECKDRV_OK
      ErrMsgCb = ''
      IF (active_model < 1 .OR. active_model > SIZE(models)) THEN
        ErrStatCb = CD_DECKDRV_SOLVEFAIL
        ErrMsgCb = 'finite-EI dynamic banded load callback has no active model'
        RETURN
      END IF
      IF (SIZE(q_in) /= SIZE(force) .OR. SIZE(v_in) /= SIZE(force) .OR. &
          SIZE(force) /= SIZE(models(active_model)%base_f_ext)) THEN
        ErrStatCb = CD_DECKDRV_SOLVEFAIL
        ErrMsgCb = 'finite-EI dynamic banded load callback shape mismatch'
        RETURN
      END IF
      models(active_model)%contact_work = CD_ZERO
      models(active_model)%env_work = CD_ZERO
      IF (models(active_model)%has_seabed) THEN
        IF (models(active_model)%has_bathymetry) THEN
          CALL finite_bathymetry_contact_load_banded(q_in, v_in, models(active_model)%bathymetry, &
                                                     models(active_model)%seabed_kn, models(active_model)%seabed_cn, &
                                                     opts%friction_mu, free, kl, ku, &
                                                     models(active_model)%free_map_work, &
                                                     models(active_model)%contact_work, jac_q_band, jac_v_band, &
                                                     ErrStatCb, ErrMsgCb)
        ELSE
          CALL finite_seabed_contact_load_banded(q_in, v_in, models(active_model)%seabed_z_floor, &
                                                 models(active_model)%seabed_kn, models(active_model)%seabed_cn, &
                                                 opts%friction_mu, free, kl, ku, &
                                                 models(active_model)%free_map_work, &
                                                 models(active_model)%contact_work, jac_q_band, jac_v_band, &
                                                 ErrStatCb, ErrMsgCb)
        END IF
        IF (ErrStatCb /= CD_DECKDRV_OK) RETURN
        force = force + models(active_model)%contact_work
      END IF
      IF (opts%has_current .OR. opts%has_wave) THEN
        CALL finite_environment_load_banded(models(active_model), opts, time, q_in, v_in, free, kl, ku, &
                                            models(active_model)%free_map_work, models(active_model)%env_work, &
                                            jac_q_band, jac_v_band, ErrStatCb, ErrMsgCb)
        IF (ErrStatCb /= CD_DECKDRV_OK) RETURN
        force = force + models(active_model)%env_work
      END IF
    END SUBROUTINE finite_deck_dynamic_load_banded
  END SUBROUTINE step_finite_held_models

  SUBROUTINE finite_motion_targets(model, line, points, motion, time_index, q_ft, v_ft, a_ft, ErrStat, ErrMsg)
    !! Build the t_{n+1} prescribed-support target vectors for a finite-EI line: the full
    !! current model state with the two endpoint TRANSLATION triplets (DOFs 1..3 and
    !! ndof-5..ndof-3) overwritten by the motionFile sample. Only those fixed entries are read
    !! by the moving-support gen-alpha; the rest carry the (finite) current state.
    TYPE(FiniteDeckModel), INTENT(IN) :: model
    TYPE(DeckLine), INTENT(IN) :: line
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(MotionTable), INTENT(IN) :: motion
    INTEGER, INTENT(IN) :: time_index
    REAL(wp), INTENT(OUT) :: q_ft(:), v_ft(:), a_ft(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: ndof, pa, pb, es
    CHARACTER(160) :: em
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    ndof = SIZE(q_ft)
    CALL CD_Get_FiniteEI_Model_State(model%model, q_ft, v_ft, a_ft, es, em)
    IF (es /= 0) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: finite-EI state query for motion targets failed: '//TRIM(em)
      RETURN
    END IF
    pa = find_point(points, line%nodeB)
    pb = find_point(points, line%nodeA)
    CALL prescribed_point_state(points(pa), motion, time_index, q_ft(1:3), v_ft(1:3), a_ft(1:3), ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL prescribed_point_state(points(pb), motion, time_index, q_ft(ndof - 5:ndof - 3), &
                                v_ft(ndof - 5:ndof - 3), a_ft(ndof - 5:ndof - 3), ErrStat, ErrMsg)
  END SUBROUTINE finite_motion_targets

  SUBROUTINE step_held_models(models, dt, recovery_max_substeps, converged, stalled, n_iter, &
                              max_substeps_used, ErrStat, ErrMsg, work)
    TYPE(CD_ModelType), INTENT(INOUT) :: models(:)
    REAL(wp), INTENT(IN) :: dt
    INTEGER, INTENT(IN) :: recovery_max_substeps
    LOGICAL, INTENT(OUT) :: converged, stalled
    INTEGER, INTENT(OUT) :: n_iter, max_substeps_used, ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(LineStepWorkspace), INTENT(INOUT) :: work

    INTEGER :: i, j, ndof, nc, es, line_iter, line_substeps
    LOGICAL :: line_converged, line_stalled
    CHARACTER(160) :: em

    converged = .TRUE.
    stalled = .FALSE.
    n_iter = 0
    max_substeps_used = 1
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    DO i = 1, SIZE(models)
      ndof = CD_Model_NDOF(models(i), es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: model DOF query failed: '//TRIM(em)
        RETURN
      END IF
      nc = CD_Model_NCoupledDOF(models(i), es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: model coupled-DOF count failed: '//TRIM(em)
        RETURN
      END IF
      CALL ensure_line_step_workspace(work, ndof, nc, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL CD_Get_Model_State(models(i), work%q(1:ndof), work%v(1:ndof), work%a(1:ndof), es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: model state query failed: '//TRIM(em)
        RETURN
      END IF
      CALL CD_Get_Model_CoupledDofs(models(i), work%coupled_dofs(1:nc), es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: model coupled-DOF query failed: '//TRIM(em)
        RETURN
      END IF
      DO j = 1, nc
        work%v(work%coupled_dofs(j)) = CD_ZERO
        work%a(work%coupled_dofs(j)) = CD_ZERO
      END DO
      CALL CD_Step_Model_Recovering(models(i), dt, line_converged, line_stalled, line_iter, es, em, &
                                    prescribed_q=work%q(1:ndof), prescribed_v=work%v(1:ndof), &
                                    prescribed_a=work%a(1:ndof), max_substeps=recovery_max_substeps, &
                                    substeps_used=line_substeps)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: dynamic step failed: '//TRIM(em)
        RETURN
      END IF
      converged = converged .AND. line_converged
      stalled = stalled .OR. line_stalled
      n_iter = MAX(n_iter, line_iter)
      max_substeps_used = MAX(max_substeps_used, line_substeps)
    END DO
  END SUBROUTINE step_held_models

  SUBROUTINE step_motion_models(models, lines, points, motion, time_index, dt, recovery_max_substeps, &
                                converged, stalled, n_iter, max_substeps_used, ErrStat, ErrMsg, work)
    TYPE(CD_ModelType), INTENT(INOUT) :: models(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(MotionTable), INTENT(IN) :: motion
    INTEGER, INTENT(IN) :: time_index
    REAL(wp), INTENT(IN) :: dt
    INTEGER, INTENT(IN) :: recovery_max_substeps
    LOGICAL, INTENT(OUT) :: converged, stalled
    INTEGER, INTENT(OUT) :: n_iter, max_substeps_used, ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(LineStepWorkspace), INTENT(INOUT) :: work

    INTEGER :: i, ndof, es, line_iter, line_substeps
    LOGICAL :: line_converged, line_stalled
    CHARACTER(160) :: em

    converged = .TRUE.
    stalled = .FALSE.
    n_iter = 0
    max_substeps_used = 1
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    DO i = 1, SIZE(models)
      ndof = CD_Model_NDOF(models(i), es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: model DOF query failed: '//TRIM(em)
        RETURN
      END IF
      CALL ensure_line_step_workspace(work, ndof, 0, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL prescribed_full_state(models(i), lines(i), points, motion, time_index, &
                                 work%q(1:ndof), work%v(1:ndof), work%a(1:ndof), es, em)
      IF (es /= CD_DECKDRV_OK) THEN
        ErrStat = es
        ErrMsg = em
        RETURN
      END IF
      CALL CD_Step_Model_Recovering(models(i), dt, line_converged, line_stalled, line_iter, es, em, &
                                    prescribed_q=work%q(1:ndof), prescribed_v=work%v(1:ndof), &
                                    prescribed_a=work%a(1:ndof), max_substeps=recovery_max_substeps, &
                                    substeps_used=line_substeps)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: dynamic prescribed-motion step failed: '//TRIM(em)
        RETURN
      END IF
      converged = converged .AND. line_converged
      stalled = stalled .OR. line_stalled
      n_iter = MAX(n_iter, line_iter)
      max_substeps_used = MAX(max_substeps_used, line_substeps)
    END DO
  END SUBROUTINE step_motion_models

  SUBROUTINE apply_motion_to_models(models, lines, points, motion, time_index, ErrStat, ErrMsg)
    TYPE(CD_ModelType), INTENT(INOUT) :: models(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(MotionTable), INTENT(IN) :: motion
    INTEGER, INTENT(IN) :: time_index
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i, j, ndof, nc, es
    INTEGER, ALLOCATABLE :: coupled_dofs(:)
    REAL(wp), ALLOCATABLE :: qc(:), vc(:), ac(:)
    CHARACTER(160) :: em
    TYPE(LineStepWorkspace) :: work

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    DO i = 1, SIZE(models)
      nc = CD_Model_NCoupledDOF(models(i), es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: model coupled-DOF count failed: '//TRIM(em)
        RETURN
      END IF
      ndof = CD_Model_NDOF(models(i), es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: model DOF query failed: '//TRIM(em)
        RETURN
      END IF
      CALL ensure_line_step_workspace(work, ndof, nc, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL prescribed_full_state(models(i), lines(i), points, motion, time_index, &
                                 work%q(1:ndof), work%v(1:ndof), work%a(1:ndof), es, em)
      IF (es /= CD_DECKDRV_OK) THEN
        ErrStat = es
        ErrMsg = em
        RETURN
      END IF
      ALLOCATE (coupled_dofs(nc), qc(nc), vc(nc), ac(nc))
      CALL CD_Get_Model_CoupledDofs(models(i), coupled_dofs, es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: model coupled-DOF query failed: '//TRIM(em)
        RETURN
      END IF
      DO j = 1, nc
        qc(j) = work%q(coupled_dofs(j))
        vc(j) = work%v(coupled_dofs(j))
        ac(j) = work%a(coupled_dofs(j))
      END DO
      CALL CD_Update_Model_CoupledMotion(models(i), qc, vc, ac, es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: initial prescribed motion update failed: '//TRIM(em)
        RETURN
      END IF
      DEALLOCATE (coupled_dofs, qc, vc, ac)
    END DO
  END SUBROUTINE apply_motion_to_models

  SUBROUTINE apply_motion_to_finite_models(models, lines, points, motion, time_index, ErrStat, ErrMsg, &
                                           recompute_acceleration)
    TYPE(FiniteDeckModel), INTENT(INOUT) :: models(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(MotionTable), INTENT(IN) :: motion
    INTEGER, INTENT(IN) :: time_index
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    LOGICAL, INTENT(IN), OPTIONAL :: recompute_acceleration

    INTEGER :: i, ndof, pa, pb, es
    INTEGER :: dofs(6)
    REAL(wp) :: q_vals(6), v_vals(6), a_vals(6)
    LOGICAL :: do_recompute
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    do_recompute = .TRUE.
    IF (PRESENT(recompute_acceleration)) do_recompute = recompute_acceleration
    DO i = 1, SIZE(models)
      ndof = 6*(models(i)%n_elem + 1)
      pa = find_point(points, lines(i)%nodeB)
      pb = find_point(points, lines(i)%nodeA)
      CALL prescribed_point_state(points(pa), motion, time_index, q_vals(1:3), v_vals(1:3), a_vals(1:3), &
                                  ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL prescribed_point_state(points(pb), motion, time_index, q_vals(4:6), v_vals(4:6), a_vals(4:6), &
                                  ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      dofs = [1, 2, 3, ndof - 5, ndof - 4, ndof - 3]
      CALL CD_Set_FiniteEI_Model_PrescribedDofs(models(i)%model, dofs, q_vals, v_vals, a_vals, es, em, &
                                                recompute_acceleration=do_recompute)
      IF (es /= CD_DYN_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: finite-EI prescribed motion update failed: '//TRIM(em)
        RETURN
      END IF
    END DO
  END SUBROUTINE apply_motion_to_finite_models

  SUBROUTINE prescribed_full_state(model, line, points, motion, time_index, q, v, a, ErrStat, ErrMsg)
    TYPE(CD_ModelType), INTENT(IN) :: model
    TYPE(DeckLine), INTENT(IN) :: line
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(MotionTable), INTENT(IN) :: motion
    INTEGER, INTENT(IN) :: time_index
    REAL(wp), INTENT(OUT) :: q(:), v(:), a(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: ndof, es, pa, pb
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    ndof = CD_Model_NDOF(model, es, em)
    IF (es /= CD_MODEL_OK) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: model DOF query failed: '//TRIM(em)
      RETURN
    END IF
    IF (SIZE(q) /= ndof .OR. SIZE(v) /= ndof .OR. SIZE(a) /= ndof) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: prescribed-motion workspace has wrong size'
      RETURN
    END IF
    CALL CD_Get_Model_State(model, q, v, a, es, em)
    IF (es /= CD_MODEL_OK) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: model state query failed: '//TRIM(em)
      RETURN
    END IF
    pa = find_point(points, line%nodeB)
    pb = find_point(points, line%nodeA)
    CALL prescribed_point_state(points(pa), motion, time_index, q(1:3), v(1:3), a(1:3), ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL prescribed_point_state(points(pb), motion, time_index, q(ndof - 2:ndof), v(ndof - 2:ndof), &
                                a(ndof - 2:ndof), ErrStat, ErrMsg)
  END SUBROUTINE prescribed_full_state

  SUBROUTINE ensure_line_step_workspace(work, ndof, ncoupled, ErrStat, ErrMsg)
    TYPE(LineStepWorkspace), INTENT(INOUT) :: work
    INTEGER, INTENT(IN) :: ndof, ncoupled
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: istat
    LOGICAL :: need_coupled

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (ndof < 1 .OR. ncoupled < 0) THEN
      CALL fail(ErrStat, ErrMsg, 'line-step workspace sizes must be non-negative')
      RETURN
    END IF
    CALL ensure_real_buffer(work%q, ndof, 'line-step q workspace', ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL ensure_real_buffer(work%v, ndof, 'line-step v workspace', ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    CALL ensure_real_buffer(work%a, ndof, 'line-step a workspace', ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    IF (ncoupled > 0) THEN
      need_coupled = .NOT. ALLOCATED(work%coupled_dofs)
      IF (.NOT. need_coupled) need_coupled = SIZE(work%coupled_dofs) < ncoupled
      IF (need_coupled) THEN
        IF (ALLOCATED(work%coupled_dofs)) DEALLOCATE (work%coupled_dofs)
        ALLOCATE (work%coupled_dofs(ncoupled), STAT=istat)
        IF (istat /= 0) THEN
          CALL fail(ErrStat, ErrMsg, 'line-step coupled-DOF workspace allocation failed')
          RETURN
        END IF
      END IF
    END IF
  CONTAINS

    SUBROUTINE ensure_real_buffer(buffer, n, label, ErrStat, ErrMsg)
      REAL(wp), ALLOCATABLE, INTENT(INOUT) :: buffer(:)
      INTEGER, INTENT(IN) :: n
      CHARACTER(*), INTENT(IN) :: label
      INTEGER, INTENT(OUT) :: ErrStat
      CHARACTER(*), INTENT(OUT) :: ErrMsg
      INTEGER :: istat
      LOGICAL :: need_buffer

      ErrStat = CD_DECKDRV_OK
      ErrMsg = ''
      need_buffer = .NOT. ALLOCATED(buffer)
      IF (.NOT. need_buffer) need_buffer = SIZE(buffer) < n
      IF (need_buffer) THEN
        IF (ALLOCATED(buffer)) DEALLOCATE (buffer)
        ALLOCATE (buffer(n), STAT=istat)
        IF (istat /= 0) CALL fail(ErrStat, ErrMsg, TRIM(label)//' allocation failed')
      END IF
    END SUBROUTINE ensure_real_buffer
  END SUBROUTINE ensure_line_step_workspace

  SUBROUTINE prescribed_point_state(point, motion, time_index, q, v, a, ErrStat, ErrMsg)
    TYPE(DeckPoint), INTENT(IN) :: point
    TYPE(MotionTable), INTENT(IN) :: motion
    INTEGER, INTENT(IN) :: time_index
    REAL(wp), INTENT(OUT) :: q(3), v(3), a(3)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: midx

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    SELECT CASE (TRIM(point%ptype))
    CASE ('fixed')
      q = point%pos
      v = CD_ZERO
      a = CD_ZERO
    CASE ('coupled', 'vessel')
      midx = find_motion_point(motion, point%id)
      IF (midx == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'motionFile missing Coupled/Vessel point id '//TRIM(int_to_str(point%id)))
        RETURN
      END IF
      q = motion%q(:, midx, time_index)
      v = motion%v(:, midx, time_index)
      a = motion%a(:, midx, time_index)
    CASE DEFAULT
      CALL fail(ErrStat, ErrMsg, 'prescribed motion only supports Fixed/Coupled/Vessel line endpoints')
    END SELECT
  END SUBROUTINE prescribed_point_state

  SUBROUTINE read_motion_file(path, points, opts, motion, ErrStat, ErrMsg, include_rod_points, include_body_points, &
                              with_roll)
    !! Prescribed point motion: rows "time point_id x y z vx vy vz ax ay az". with_roll (a deck
    !! with a torsional line) also reads an optional 12th column, the roll [deg] of the line end
    !! frames at that point about their directors (motion%roll, radians); a point gives it on
    !! every row or on none, and without with_roll a 12th token stays commentary.
    CHARACTER(*), INTENT(IN) :: path
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(MotionTable), INTENT(OUT) :: motion
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    LOGICAL, INTENT(IN), OPTIONAL :: include_rod_points
    LOGICAL, INTENT(IN), OPTIONAL :: include_body_points
    LOGICAL, INTENT(IN), OPTIONAL :: with_roll

    INTEGER :: unit, ios, ip, it, pid, nstep, lineno, row_status, ipt
    LOGICAL :: read_roll, roll_ok
    LOGICAL, ALLOCATABLE :: roll_seen(:, :)
    CHARACTER(DECK_RECLEN) :: roll_tok
    REAL(wp) :: t, qv(3), vv(3), av(3), tol, row(11), trow(21), rq(3, 3), rp(3)
    CHARACTER(DECK_RECLEN) :: line
    CHARACTER(256) :: why
    LOGICAL, ALLOCATABLE :: seen(:, :), turb_seen(:, :)
    LOGICAL :: accept_rod_points, accept_body_points, grid_ok
    INTEGER :: jturb

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    accept_rod_points = .FALSE.
    accept_body_points = .FALSE.
    IF (PRESENT(include_rod_points)) accept_rod_points = include_rod_points
    IF (PRESENT(include_body_points)) accept_body_points = include_body_points
    read_roll = .FALSE.
    IF (PRESENT(with_roll)) read_roll = with_roll
    CALL grid_step_count(opts%tmax, opts%dtM, nstep, grid_ok)
    IF (.NOT. grid_ok .OR. nstep < 0) THEN
      CALL fail(ErrStat, ErrMsg, 'motionFile needs finite dtM > 0 and TMax >= 0 with a representable step count')
      RETURN
    END IF
    motion%n_time = nstep + 1
    motion%n_point = count_motion_points(points, accept_rod_points, accept_body_points)
    IF (motion%n_point < 1) THEN
      IF (accept_rod_points .OR. accept_body_points) THEN
        CALL fail(ErrStat, ErrMsg, 'motionFile requires at least one eligible prescribed point')
      ELSE
        CALL fail(ErrStat, ErrMsg, 'motionFile requires at least one Coupled/Vessel point')
      END IF
      RETURN
    END IF
    ALLOCATE (motion%point_ids(motion%n_point), motion%time(motion%n_time), &
              motion%q(3, motion%n_point, motion%n_time), motion%v(3, motion%n_point, motion%n_time), &
              motion%a(3, motion%n_point, motion%n_time), seen(motion%n_point, motion%n_time), STAT=ios)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot allocate the motionFile table for '//TRIM(int_to_str(motion%n_time))// &
                ' time steps x '//TRIM(int_to_str(motion%n_point))//' points; increase dtM or reduce TMax')
      RETURN
    END IF
    CALL fill_motion_point_ids(points, motion%point_ids, accept_rod_points, accept_body_points)
    DO it = 1, motion%n_time
      motion%time(it) = REAL(it - 1, wp)*opts%dtM
    END DO
    motion%q = CD_ZERO
    motion%v = CD_ZERO
    motion%a = CD_ZERO
    seen = .FALSE.
    ALLOCATE (roll_seen(MERGE(motion%n_point, 0, read_roll), MERGE(motion%n_time, 0, read_roll)), STAT=ios)
    IF (ios == 0 .AND. read_roll) ALLOCATE (motion%roll(motion%n_point, motion%n_time), STAT=ios)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot allocate the motionFile roll table'); RETURN
    END IF
    roll_seen = .FALSE.
    IF (read_roll) motion%roll = CD_ZERO
    tol = 100.0_wp*EPSILON(CD_ONE)*MAX(CD_ONE, opts%tmax)
    IF (opts%motion_kind /= MOTION_POINT_ROWS) THEN
      IF (accept_rod_points .OR. accept_body_points) THEN
        CALL fail(ErrStat, ErrMsg, 'vesselMotion/vesselRAO move Coupled/Vessel line points; decks with '// &
                  'prescribed rods or Rigid6 bodies take motionFile rows')
        RETURN
      END IF
      CALL build_vessel_motion(path, points, opts, motion, ErrStat, ErrMsg)
      IF (ErrStat == CD_DECKDRV_OK) CALL note_motion_start_velocity(motion, opts%dtM)
      RETURN
    END IF
    CALL CD_Open_Input(unit, path, ios, why)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open motionFile: '//TRIM(path)//input_open_reason(path, why))
      RETURN
    END IF
    lineno = 0
    DO
      CALL next_record(unit, line, ios, lineno)
      IF (IS_IOSTAT_END(ios)) EXIT
      IF (ios /= 0) THEN
        CLOSE (unit)
        CALL record_error(ios, 'motionFile', lineno, ErrStat, ErrMsg)
        RETURN
      END IF
      IF (opts%n_turb > 0) THEN
        ! TURBINES deck: per-turbine rigid-body records
        !   time J x y z q0 q1 q2 q3 vx vy vz wx wy wz ax ay az alx aly alz
        ! drive every Turbine<J> point: p = x + R(q) p_local, with its velocity and acceleration
        CALL parse_real_row(line, trow, row_status)
        IF (row_status /= 0 .OR. .NOT. ALL(IEEE_IS_FINITE(trow))) THEN
          CLOSE (unit)
          CALL fail(ErrStat, ErrMsg, 'TURBINES motion rows must be: time J x y z q0 q1 q2 q3 vx vy vz '// &
                    'wx wy wz ax ay az alx aly alz')
          CALL add_row_context('motionFile', lineno, line, ErrMsg)
          RETURN
        END IF
        IF (ANY(ABS(trow(3:9)) > MAX_COORDINATE) .OR. ANY(ABS(trow(10:15)) > MAX_MOTION_SPEED) .OR. &
            ANY(ABS(trow(16:21)) > MAX_MOTION_ACCEL)) THEN
          CLOSE (unit)
          CALL fail(ErrStat, ErrMsg, 'value outside the admissible range (|x| <= 1e6 m, rates <= 1e4, '// &
                    'accelerations <= 1e6)')
          CALL add_row_context('motionFile', lineno, line, ErrMsg)
          RETURN
        END IF
        ! J: an integer naming a declared TURBINES row (as point rows check point_id)
        jturb = 0
        IF (ABS(trow(2)) <= REAL(HUGE(1), wp)) THEN
          IF (.NOT. (ABS(trow(2) - AINT(trow(2))) > CD_ZERO)) jturb = NINT(trow(2))
        END IF
        IF (jturb >= 1 .AND. ALLOCATED(opts%turb_ref)) THEN
          IF (jturb > SIZE(opts%turb_ref, 2)) THEN
            jturb = 0
          ELSE IF (.NOT. (opts%turb_ref(1, jturb) < HUGE(CD_ONE))) THEN
            jturb = 0
          END IF
        ELSE
          jturb = 0
        END IF
        IF (jturb < 1) THEN
          CLOSE (unit)
          CALL fail(ErrStat, ErrMsg, 'J must be the integer id of a TURBINES row')
          CALL add_row_context('motionFile', lineno, line, ErrMsg)
          RETURN
        END IF
        IF (ABS(NORM2(trow(6:9)) - CD_ONE) > 1.0e-6_wp) THEN
          CLOSE (unit)
          CALL fail(ErrStat, ErrMsg, 'the quaternion q0 q1 q2 q3 must have unit norm (within 1e-6)')
          CALL add_row_context('motionFile', lineno, line, ErrMsg)
          RETURN
        END IF
        it = 0
        IF (ABS(trow(1)/opts%dtM) < MAX_GRID_STEPS) it = NINT(trow(1)/opts%dtM) + 1
        grid_ok = it >= 1 .AND. it <= motion%n_time
        IF (grid_ok) grid_ok = ABS(motion%time(it) - trow(1)) <= tol
        IF (.NOT. grid_ok) THEN
          CLOSE (unit)
          CALL fail(ErrStat, ErrMsg, 'time is outside the dtM/TMax grid')
          CALL add_row_context('motionFile', lineno, line, ErrMsg)
          RETURN
        END IF
        IF (.NOT. ALLOCATED(turb_seen)) THEN
          ALLOCATE (turb_seen(SIZE(opts%turb_ref, 2), motion%n_time), STAT=ios)
          IF (ios /= 0) THEN
            CLOSE (unit)
            CALL fail(ErrStat, ErrMsg, 'cannot allocate the TURBINES motion bookkeeping'); RETURN
          END IF
          turb_seen = .FALSE.
        END IF
        IF (turb_seen(jturb, it)) THEN
          CLOSE (unit)
          CALL fail(ErrStat, ErrMsg, 'duplicate row for turbine '//TRIM(int_to_str(jturb))//' at this time')
          CALL add_row_context('motionFile', lineno, line, ErrMsg)
          RETURN
        END IF
        turb_seen(jturb, it) = .TRUE.
        rq = quat_rotation(trow(6:9))
        DO ip = 1, motion%n_point
          ipt = find_point(points, motion%point_ids(ip))
          IF (ipt < 1) CYCLE
          IF (points(ipt)%turbine_id /= jturb) CYCLE
          rp = MATMUL(rq, points(ipt)%turb_local)
          motion%q(:, ip, it) = trow(3:5) + rp
          motion%v(:, ip, it) = trow(10:12) + cross3(trow(13:15), rp)
          motion%a(:, ip, it) = trow(16:18) + cross3(trow(19:21), rp) + cross3(trow(13:15), cross3(trow(13:15), rp))
          seen(ip, it) = .TRUE.
        END DO
        CYCLE
      END IF
      ! strict per-column read: "0.1/2" or "1,5" is malformed, never a partial row
      CALL parse_real_row(line, row, row_status)
      IF (row_status /= 0) THEN
        CLOSE (unit)
        CALL fail(ErrStat, ErrMsg, 'rows must be: time point_id x y z vx vy vz ax ay az')
        CALL add_row_context('motionFile', lineno, line, ErrMsg)
        RETURN
      END IF
      t = row(1)
      qv = row(3:5)
      vv = row(6:8)
      av = row(9:11)
      IF (.NOT. (IEEE_IS_FINITE(t) .AND. ALL(IEEE_IS_FINITE(row)))) THEN
        CLOSE (unit)
        CALL fail(ErrStat, ErrMsg, 'non-finite value')
        CALL add_row_context('motionFile', lineno, line, ErrMsg)
        RETURN
      END IF
      IF (ANY(ABS(qv) > MAX_COORDINATE) .OR. ANY(ABS(vv) > MAX_MOTION_SPEED) .OR. ANY(ABS(av) > MAX_MOTION_ACCEL)) THEN
        CLOSE (unit)
        CALL fail(ErrStat, ErrMsg, 'value outside the admissible range (|x| <= 1e6 m, |v| <= 1e4 m/s, '// &
                  '|a| <= 1e6 m/s^2)')
        CALL add_row_context('motionFile', lineno, line, ErrMsg)
        RETURN
      END IF
      pid = 0
      IF (ABS(row(2)) <= REAL(HUGE(1), wp)) THEN
        IF (.NOT. (ABS(row(2) - AINT(row(2))) > CD_ZERO)) pid = NINT(row(2))
      END IF
      IF (pid < 1) THEN
        CLOSE (unit)
        CALL fail(ErrStat, ErrMsg, 'point_id must be a positive integer')
        CALL add_row_context('motionFile', lineno, line, ErrMsg)
        RETURN
      END IF
      ! Nested tests: Fortran does not guarantee short-circuit evaluation, so the time
      ! index is range-checked before motion%time(it) is referenced.
      it = 0
      IF (ABS(t/opts%dtM) < MAX_GRID_STEPS) it = NINT(t/opts%dtM) + 1
      grid_ok = it >= 1 .AND. it <= motion%n_time
      IF (grid_ok) grid_ok = ABS(motion%time(it) - t) <= tol
      IF (.NOT. grid_ok) THEN
        CLOSE (unit)
        CALL fail(ErrStat, ErrMsg, 'time is outside the dtM/TMax grid')
        CALL add_row_context('motionFile', lineno, line, ErrMsg)
        RETURN
      END IF
      ip = find_motion_point(motion, pid)
      IF (ip == 0) THEN
        CLOSE (unit)
        IF (accept_rod_points .OR. accept_body_points) THEN
          CALL fail(ErrStat, ErrMsg, 'references point id '//TRIM(int_to_str(pid))// &
                    ', which is not eligible for prescribed motion')
        ELSE
          CALL fail(ErrStat, ErrMsg, 'references point id '//TRIM(int_to_str(pid))// &
                    ', which is not Coupled/Vessel')
        END IF
        CALL add_row_context('motionFile', lineno, line, ErrMsg)
        RETURN
      END IF
      IF (seen(ip, it)) THEN
        CLOSE (unit)
        CALL fail(ErrStat, ErrMsg, 'duplicate row for point '//TRIM(int_to_str(pid))// &
                  ' at this time')
        CALL add_row_context('motionFile', lineno, line, ErrMsg)
        RETURN
      END IF
      motion%q(:, ip, it) = qv
      motion%v(:, ip, it) = vv
      motion%a(:, ip, it) = av
      seen(ip, it) = .TRUE.
      IF (read_roll) THEN
        ! the optional roll column: a 12th token shaped like a number must be one
        CALL get_token(line, 12, roll_tok, roll_ok)
        IF (roll_ok) roll_ok = numeric_token_shape(roll_tok)
        IF (roll_ok) THEN
          CALL parse_real_token(roll_tok, motion%roll(ip, it), roll_ok)
          IF (roll_ok) roll_ok = IEEE_IS_FINITE(motion%roll(ip, it))
          IF (.NOT. roll_ok) THEN
            CLOSE (unit)
            CALL fail(ErrStat, ErrMsg, 'the roll column (12th, degrees) must be a finite number')
            CALL add_row_context('motionFile', lineno, line, ErrMsg)
            RETURN
          END IF
          motion%roll(ip, it) = motion%roll(ip, it)*QUARTER_PI/45.0_wp
          roll_seen(ip, it) = .TRUE.
        END IF
      END IF
    END DO
    CLOSE (unit)
    IF (read_roll) THEN
      DO ip = 1, motion%n_point
        IF (ANY(roll_seen(ip, :)) .AND. .NOT. ALL(roll_seen(ip, :))) THEN
          CALL fail(ErrStat, ErrMsg, 'motionFile: point '//TRIM(int_to_str(motion%point_ids(ip)))//' gives the '// &
                    'roll column (12th) on some rows only; give it on every row of the point or on none')
          RETURN
        END IF
      END DO
      motion%has_roll = ANY(roll_seen)
    END IF
    IF (.NOT. ALL(seen)) THEN
      IF (accept_rod_points .OR. accept_body_points) THEN
        CALL fail(ErrStat, ErrMsg, 'motionFile must provide every eligible prescribed point at every dtM time')
      ELSE
        CALL fail(ErrStat, ErrMsg, 'motionFile must provide every Coupled/Vessel point at every dtM time')
      END IF
      RETURN
    END IF
    CALL note_motion_start_velocity(motion, opts%dtM)
  END SUBROUTINE read_motion_file

  SUBROUTINE build_vessel_motion(path, points, opts, motion, ErrStat, ErrMsg)
    !! Fill the prescribed-motion table from a rigid vessel: the vesselMotion 6-DOF record
    !! or the vesselRAO table driven by the deck waves. Every Coupled/Vessel point moves
    !! rigidly with the vessel from its deck position (the reference pose, vessel axes =
    !! global axes): x = r + R p, v = dr/dt + w x R p, a = d2r/dt2 + al x R p + w x (w x R p),
    !! with p = deck position - vesselRef. The rotation is kept for end connections.
    CHARACTER(*), INTENT(IN) :: path
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(MotionTable), INTENT(INOUT) :: motion
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp), ALLOCATABLE :: rref(:, :), vref(:, :), aref(:, :)
    INTEGER :: ip, it, ipt, ios
    REAL(wp) :: p_local(3)

    ErrStat = CD_DECKDRV_OK; ErrMsg = ''
    ALLOCATE (motion%rot(3, 3, motion%n_time), motion%omega(3, motion%n_time), motion%alpha(3, motion%n_time), &
              rref(3, motion%n_time), vref(3, motion%n_time), aref(3, motion%n_time), STAT=ios)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot allocate the vessel motion history; increase dtM or reduce TMax'); RETURN
    END IF
    IF (opts%motion_kind == MOTION_VESSEL_FILE) THEN
      CALL read_vessel_record(path, opts, motion, rref, vref, aref, ErrStat, ErrMsg)
    ELSE
      CALL synthesize_vessel_rao(path, opts, motion, rref, vref, aref, ErrStat, ErrMsg)
    END IF
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    motion%has_rot = .TRUE.
    DO ip = 1, motion%n_point
      ipt = find_point(points, motion%point_ids(ip))
      IF (ipt < 1) THEN
        CALL fail(ErrStat, ErrMsg, 'vessel motion references an unknown point'); RETURN
      END IF
      p_local = points(ipt)%pos - opts%vessel_ref
      DO it = 1, motion%n_time
        CALL CD_Vessel_Point_Kinematics(rref(:, it), vref(:, it), aref(:, it), motion%rot(:, :, it), &
                                        motion%omega(:, it), motion%alpha(:, it), p_local, &
                                        motion%q(:, ip, it), motion%v(:, ip, it), motion%a(:, ip, it))
      END DO
    END DO
  END SUBROUTINE build_vessel_motion

  SUBROUTINE read_vessel_record(path, opts, motion, rref, vref, aref, ErrStat, ErrMsg)
    !! vesselMotion record: one row per dtM grid time, either
    !!   time x y z roll pitch yaw vx vy vz wx wy wz ax ay az alx aly alz          (19 values)
    !!   time x y z q0 q1 q2 q3 vx vy vz wx wy wz ax ay az alx aly alz             (20 values)
    !! (x, y, z) is the reference-point position [m], roll/pitch/yaw the OrcaFlex Euler angles
    !! [deg] (R = Rz(yaw) Ry(pitch) Rx(roll)) or (q0..q3) a unit quaternion (scalar first),
    !! v/a the reference-point velocity and acceleration, w/al the angular velocity [rad/s]
    !! and acceleration [rad/s2] in global axes. All rows use one form.
    CHARACTER(*), INTENT(IN) :: path
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(MotionTable), INTENT(INOUT) :: motion
    REAL(wp), INTENT(OUT) :: rref(:, :), vref(:, :), aref(:, :)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp), PARAMETER :: D2R = QUARTER_PI/45.0_wp
    CHARACTER(DECK_RECLEN) :: line
    CHARACTER(256) :: why
    INTEGER :: unit, ios, lineno, ntok, nform, row_status, it, off
    REAL(wp) :: row(20), tol, qn
    LOGICAL, ALLOCATABLE :: seen(:)
    LOGICAL :: grid_ok

    ErrStat = CD_DECKDRV_OK; ErrMsg = ''
    ALLOCATE (seen(motion%n_time))
    seen = .FALSE.
    rref = CD_ZERO; vref = CD_ZERO; aref = CD_ZERO
    tol = 100.0_wp*EPSILON(CD_ONE)*MAX(CD_ONE, opts%tmax)
    CALL CD_Open_Input(unit, path, ios, why)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open vesselMotion file: '//TRIM(path)//input_open_reason(path, why))
      RETURN
    END IF
    lineno = 0
    nform = 0
    DO
      CALL next_record(unit, line, ios, lineno)
      IF (IS_IOSTAT_END(ios)) EXIT
      IF (ios /= 0) THEN
        CLOSE (unit)
        CALL record_error(ios, 'vesselMotion file', lineno, ErrStat, ErrMsg)
        RETURN
      END IF
      ntok = count_tokens(line)
      IF (nform == 0 .AND. (ntok == 19 .OR. ntok == 20)) nform = ntok
      row_status = 1
      IF (ntok == nform) CALL parse_real_row(line, row(1:ntok), row_status)
      IF (row_status /= 0) THEN
        CLOSE (unit)
        CALL fail(ErrStat, ErrMsg, 'rows must be: time x y z roll pitch yaw vx vy vz wx wy wz ax ay az '// &
                  'alx aly alz (19 values) or time x y z q0 q1 q2 q3 vx vy vz wx wy wz ax ay az alx aly alz '// &
                  '(20 values), one form for the whole file')
        CALL add_row_context('vesselMotion file', lineno, line, ErrMsg)
        RETURN
      END IF
      IF (.NOT. ALL(IEEE_IS_FINITE(row(1:ntok)))) THEN
        CLOSE (unit)
        CALL fail(ErrStat, ErrMsg, 'non-finite value')
        CALL add_row_context('vesselMotion file', lineno, line, ErrMsg)
        RETURN
      END IF
      ! positions/angles, rates and accelerations all stay within the admissible scales
      IF (ANY(ABS(row(2:ntok)) > MAX_COORDINATE)) THEN
        CLOSE (unit)
        CALL fail(ErrStat, ErrMsg, 'value outside the admissible range (magnitudes <= 1e6)')
        CALL add_row_context('vesselMotion file', lineno, line, ErrMsg)
        RETURN
      END IF
      it = 0
      IF (ABS(row(1)/opts%dtM) < MAX_GRID_STEPS) it = NINT(row(1)/opts%dtM) + 1
      grid_ok = it >= 1 .AND. it <= motion%n_time
      IF (grid_ok) grid_ok = ABS(motion%time(it) - row(1)) <= tol
      IF (.NOT. grid_ok) THEN
        CLOSE (unit)
        CALL fail(ErrStat, ErrMsg, 'time is outside the dtM/TMax grid')
        CALL add_row_context('vesselMotion file', lineno, line, ErrMsg)
        RETURN
      END IF
      IF (seen(it)) THEN
        CLOSE (unit)
        CALL fail(ErrStat, ErrMsg, 'duplicate row at this time')
        CALL add_row_context('vesselMotion file', lineno, line, ErrMsg)
        RETURN
      END IF
      rref(:, it) = row(2:4)
      IF (nform == 19) THEN
        motion%rot(:, :, it) = CD_Vessel_Euler_DCM(row(5:7)*D2R)
        off = 7
      ELSE
        qn = NORM2(row(5:8))
        IF (ABS(qn - CD_ONE) > 1.0e-6_wp) THEN
          CLOSE (unit)
          CALL fail(ErrStat, ErrMsg, 'the quaternion q0 q1 q2 q3 must have unit norm (within 1e-6)')
          CALL add_row_context('vesselMotion file', lineno, line, ErrMsg)
          RETURN
        END IF
        motion%rot(:, :, it) = quat_rotation(row(5:8))
        off = 8
      END IF
      vref(:, it) = row(off + 1:off + 3)
      motion%omega(:, it) = row(off + 4:off + 6)
      aref(:, it) = row(off + 7:off + 9)
      motion%alpha(:, it) = row(off + 10:off + 12)
      seen(it) = .TRUE.
    END DO
    CLOSE (unit)
    IF (.NOT. ALL(seen)) THEN
      CALL fail(ErrStat, ErrMsg, 'vesselMotion file must provide one row at every dtM time from 0 to TMax')
    END IF
  END SUBROUTINE read_vessel_record

  SUBROUTINE read_rao_table(path, rao, ErrStat, ErrMsg)
    !! vesselRAO table: blocks headed "HEADING <deg>" (relative wave heading), each with one
    !! row per wave period
    !!   period  surgeA surgeP  swayA swayP  heaveA heaveP  rollA rollP  pitchA pitchP  yawA yawP
    !! (period [s]; amplitudes in m/m and deg/m; phases as lags in deg relative to the wave
    !! crest at the vessel reference point). Every block lists the same periods.
    CHARACTER(*), INTENT(IN) :: path
    TYPE(CD_VesselRAOType), INTENT(OUT) :: rao
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER, PARAMETER :: MAXH = 361, MAXP = 2000
    CHARACTER(DECK_RECLEN) :: line
    CHARACTER(256) :: why
    CHARACTER(DECK_RECLEN) :: tok
    INTEGER :: unit, ios, lineno, nh, np, np_first, row_status, i, j, k, es
    INTEGER, ALLOCATABLE :: perm_p(:), perm_h(:)
    REAL(wp) :: row(13), x
    REAL(wp), ALLOCATABLE :: heads(:), pers(:, :), amp(:, :, :), ph(:, :, :)
    REAL(wp), ALLOCATABLE :: amp_s(:, :, :), ph_s(:, :, :), per_s(:), head_s(:)
    LOGICAL :: found, ok
    CHARACTER(200) :: em

    ErrStat = CD_DECKDRV_OK; ErrMsg = ''
    ! read buffers at the table limits (about 75 MB); STAT keeps a failed allocation a clean error
    ALLOCATE (heads(MAXH), pers(MAXP, MAXH), amp(6, MAXP, MAXH), ph(6, MAXP, MAXH), STAT=ios)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot allocate the vesselRAO read buffers'); RETURN
    END IF
    CALL CD_Open_Input(unit, path, ios, why)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open vesselRAO file: '//TRIM(path)//input_open_reason(path, why))
      RETURN
    END IF
    lineno = 0; nh = 0; np = 0; np_first = 0
    DO
      CALL next_record(unit, line, ios, lineno)
      IF (IS_IOSTAT_END(ios)) EXIT
      IF (ios /= 0) THEN
        CLOSE (unit)
        CALL record_error(ios, 'vesselRAO file', lineno, ErrStat, ErrMsg)
        RETURN
      END IF
      CALL get_token(line, 1, tok, found)
      IF (to_lower(TRIM(tok)) == 'heading') THEN
        CALL get_token(line, 2, tok, found)
        ok = found .AND. count_tokens(line) == 2
        IF (ok) CALL parse_real_token(tok, x, ok)
        IF (ok) ok = IEEE_IS_FINITE(x)
        IF (.NOT. ok .OR. nh >= MAXH) THEN
          CLOSE (unit)
          CALL fail(ErrStat, ErrMsg, 'a heading row must be "HEADING <deg>" with one finite value '// &
                    '(at most 361 headings)')
          CALL add_row_context('vesselRAO file', lineno, line, ErrMsg)
          RETURN
        END IF
        IF (nh > 0) THEN
          IF (.NOT. close_block()) THEN
            CLOSE (unit); RETURN
          END IF
        END IF
        nh = nh + 1
        heads(nh) = x
        np = 0
        CYCLE
      END IF
      row_status = 1
      IF (count_tokens(line) == 13) CALL parse_real_row(line, row, row_status)
      IF (row_status /= 0 .OR. nh == 0 .OR. np >= MAXP) THEN
        CLOSE (unit)
        CALL fail(ErrStat, ErrMsg, 'data rows must follow a "HEADING <deg>" row and hold 13 values: period '// &
                  'surgeAmp surgePhase swayAmp swayPhase heaveAmp heavePhase rollAmp rollPhase pitchAmp '// &
                  'pitchPhase yawAmp yawPhase (at most 2000 periods)')
        CALL add_row_context('vesselRAO file', lineno, line, ErrMsg)
        RETURN
      END IF
      IF (.NOT. ALL(IEEE_IS_FINITE(row))) THEN
        CLOSE (unit)
        CALL fail(ErrStat, ErrMsg, 'non-finite value')
        CALL add_row_context('vesselRAO file', lineno, line, ErrMsg)
        RETURN
      END IF
      np = np + 1
      pers(np, nh) = row(1)
      DO k = 1, 6
        amp(k, np, nh) = row(2*k)
        ph(k, np, nh) = row(2*k + 1)
      END DO
    END DO
    CLOSE (unit)
    IF (nh == 0) THEN
      CALL fail(ErrStat, ErrMsg, 'vesselRAO file holds no "HEADING <deg>" block'); RETURN
    END IF
    IF (.NOT. close_block()) RETURN
    ! Sort periods and headings ascending (the table may list them in either order).
    ALLOCATE (perm_p(np_first), perm_h(nh), per_s(np_first), head_s(nh), amp_s(6, np_first, nh), &
              ph_s(6, np_first, nh))
    CALL sort_index(pers(1:np_first, 1), perm_p)
    CALL sort_index(heads(1:nh), perm_h)
    DO j = 1, nh
      head_s(j) = heads(perm_h(j))
      DO i = 1, np_first
        amp_s(:, i, j) = amp(:, perm_p(i), perm_h(j))
        ph_s(:, i, j) = ph(:, perm_p(i), perm_h(j))
      END DO
    END DO
    DO i = 1, np_first
      per_s(i) = pers(perm_p(i), 1)
    END DO
    CALL CD_Vessel_RAO_Set(rao, per_s, head_s, amp_s, ph_s, es, em)
    IF (es /= CD_VESSEL_OK) CALL fail(ErrStat, ErrMsg, 'vesselRAO file: '//TRIM(em))
  CONTAINS
    LOGICAL FUNCTION close_block() RESULT(good)
      !! The finished heading block must be non-empty and repeat the first block's periods.
      good = .FALSE.
      IF (np == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'a vesselRAO heading block holds no period rows')
        RETURN
      END IF
      IF (nh == 1) THEN
        np_first = np
      ELSE IF (np /= np_first) THEN
        CALL fail(ErrStat, ErrMsg, 'every vesselRAO heading block must list the same periods')
        RETURN
      ELSE IF (ANY(ABS(pers(1:np, nh) - pers(1:np, 1)) > CD_ZERO)) THEN
        CALL fail(ErrStat, ErrMsg, 'every vesselRAO heading block must list the same periods in the same order')
        RETURN
      END IF
      good = .TRUE.
    END FUNCTION close_block
  END SUBROUTINE read_rao_table

  SUBROUTINE sort_index(x, perm)
    !! Ascending insertion-sort permutation of x (small tables).
    REAL(wp), INTENT(IN) :: x(:)
    INTEGER, INTENT(OUT) :: perm(:)
    INTEGER :: i, j, k
    DO i = 1, SIZE(x)
      perm(i) = i
    END DO
    DO i = 2, SIZE(x)
      k = perm(i)
      j = i - 1
      DO WHILE (j >= 1)
        IF (.NOT. x(perm(j)) > x(k)) EXIT
        perm(j + 1) = perm(j)
        j = j - 1
      END DO
      perm(j + 1) = k
    END DO
  END SUBROUTINE sort_index

  SUBROUTINE synthesize_vessel_rao(path, opts, motion, rref, vref, aref, ErrStat, ErrMsg)
    !! Vessel motion from the vesselRAO table and the deck wave components (Airy, JONSWAP,
    !! spectral seas and wave trains with their spreading, WaterKin components). A component
    !! of elevation a cos(k x_along - omega t + phi), travelling along beta, has elevation
    !! a cos(omega t - eps) at the vessel reference point, eps = k x_along(ref) + phi, and
    !! drives DOF j as A_j(omega, beta) a cos(omega t - eps - P_j). The relative heading is the
    !! component's direction (vessel axes = global axes). The response carries the deck wave
    !! ramp (OPTION rampTime).
    CHARACTER(*), INTENT(IN) :: path
    TYPE(DeckOptions), INTENT(IN) :: opts
    TYPE(MotionTable), INTENT(INOUT) :: motion
    REAL(wp), INTENT(OUT) :: rref(:, :), vref(:, :), aref(:, :)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp), PARAMETER :: R2D = 45.0_wp/QUARTER_PI
    TYPE(CD_VesselRAOType) :: rao
    REAL(wp), ALLOCATABLE :: om(:), kk(:), amp(:), phs(:), dir(:), eps(:), cre(:, :), cim(:, :)
    REAL(wp) :: cb, sb, r, rd, rdd, x6(6), v6(6), a6(6)
    INTEGER :: nc, i, it, es, nclamp
    LOGICAL :: clamped
    CHARACTER(200) :: em

    ErrStat = CD_DECKDRV_OK; ErrMsg = ''
    rref = CD_ZERO; vref = CD_ZERO; aref = CD_ZERO
    CALL read_rao_table(path, rao, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK) RETURN
    IF (.NOT. opts%wave_cache_ready) THEN
      CALL fail(ErrStat, ErrMsg, 'vesselRAO synthesis called before the wave precompute'); RETURN
    END IF
    SELECT CASE (opts%wave_kind)
    CASE (WAVE_AIRY)
      ALLOCATE (om(1), kk(1), amp(1), phs(1))
      om(1) = opts%wave_omega; kk(1) = opts%wave_k; amp(1) = 0.5_wp*opts%wave_height; phs(1) = CD_ZERO
    CASE (WAVE_JONSWAP)
      ALLOCATE (om, SOURCE=opts%jonswap_omega); ALLOCATE (kk, SOURCE=opts%jonswap_k)
      ALLOCATE (amp, SOURCE=opts%jonswap_amplitude); ALLOCATE (phs, SOURCE=opts%jonswap_phase)
    CASE (WAVE_COMPONENTS)
      ALLOCATE (om, SOURCE=opts%wave_component_omega); ALLOCATE (kk, SOURCE=opts%wave_component_k)
      ALLOCATE (amp, SOURCE=opts%wave_component_amplitude); ALLOCATE (phs, SOURCE=opts%wave_component_phase)
    CASE (WAVE_SEA)
      nc = opts%sea%n_comp
      ALLOCATE (om, SOURCE=opts%sea%omega(1:nc)); ALLOCATE (kk, SOURCE=opts%sea%k(1:nc))
      ALLOCATE (amp, SOURCE=opts%sea%amplitude(1:nc)); ALLOCATE (phs, SOURCE=opts%sea%phase(1:nc))
      ALLOCATE (dir(nc))
      DO i = 1, nc
        dir(i) = ATAN2(opts%sea%sinb(i), opts%sea%cosb(i))*R2D
      END DO
    CASE (WAVE_STREAM)
      CALL fail(ErrStat, ErrMsg, 'vesselRAO needs linear deck waves; a nonlinear stream-function wave has '// &
                'no linear components to apply RAOs to'); RETURN
    CASE DEFAULT
      CALL fail(ErrStat, ErrMsg, 'vesselRAO needs deck waves'); RETURN
    END SELECT
    nc = SIZE(om)
    IF (.NOT. ALLOCATED(dir)) THEN
      ALLOCATE (dir(nc))
      dir = opts%wave_direction
    END IF
    ALLOCATE (eps(nc), cre(6, nc), cim(6, nc))
    cre = CD_ZERO; cim = CD_ZERO
    nclamp = 0
    DO i = 1, nc
      cb = COS(dir(i)*QUARTER_PI/45.0_wp)
      sb = SIN(dir(i)*QUARTER_PI/45.0_wp)
      eps(i) = kk(i)*(opts%vessel_ref(1)*cb + opts%vessel_ref(2)*sb) + phs(i)
      IF (.NOT. (amp(i) > CD_ZERO)) CYCLE
      CALL CD_Vessel_RAO_Eval(rao, TWO_PI/om(i), dir(i), cre(:, i), cim(:, i), clamped, es, em)
      IF (es /= CD_VESSEL_OK) THEN
        CALL fail(ErrStat, ErrMsg, 'vesselRAO: '//TRIM(em)); RETURN
      END IF
      IF (clamped) nclamp = nclamp + 1
    END DO
    IF (nclamp > 0) WRITE (output_unit, '(A,I0,A,I0,A)') '  Note: vesselRAO: ', nclamp, ' of ', nc, &
      ' wave components lie outside the RAO period range and take the RAO of the nearest tabulated period.'
    DO it = 1, motion%n_time
      CALL CD_Vessel_Ramp(opts%ramp_time, motion%time(it), r, rd, rdd)
      CALL CD_Vessel_RAO_Motion(cre, cim, om, amp, eps, motion%time(it), r, rd, rdd, x6, v6, a6)
      rref(:, it) = opts%vessel_ref + x6(1:3)
      vref(:, it) = v6(1:3)
      aref(:, it) = a6(1:3)
      motion%rot(:, :, it) = CD_Vessel_Euler_DCM(x6(4:6))
      CALL CD_Vessel_Euler_Angular(x6(4:6), v6(4:6), a6(4:6), motion%omega(:, it), motion%alpha(:, it))
    END DO
  END SUBROUTINE synthesize_vessel_rao

  SUBROUTINE note_motion_start_velocity(motion, dt)
    !! Standard-output note for a prescribed motion that starts moving: the lines start at
    !! rest in their static equilibrium, so an end that starts at speed sends an axial shock
    !! down the line (a harmonic started at t = 0 begins at its peak velocity). The start
    !! speed is the larger of the tabulated t = 0 velocity and the velocity implied by the
    !! first two samples.
    TYPE(MotionTable), INTENT(IN) :: motion
    REAL(wp), INTENT(IN) :: dt
    REAL(wp), PARAMETER :: START_SPEED_NOTE = 0.1_wp   ! m/s
    INTEGER :: ip
    REAL(wp) :: speed
    CHARACTER(32) :: b1

    DO ip = 1, motion%n_point
      speed = NORM2(motion%v(:, ip, 1))
      IF (motion%n_time >= 2 .AND. dt > CD_ZERO) &
        speed = MAX(speed, NORM2(motion%q(:, ip, 2) - motion%q(:, ip, 1))/dt)
      IF (speed > START_SPEED_NOTE) THEN
        WRITE (b1, '(F10.3)') speed
        WRITE (output_unit, '(A)') '  Note: motionFile point '//TRIM(int_to_str(motion%point_ids(ip)))// &
          ' starts moving at '//TRIM(ADJUSTL(b1))//' m/s while the lines start at rest; the sudden start '// &
          'sends an axial shock down the line. Start the motion from rest, or ramp its amplitude in '// &
          'over one or two periods in the motion file.'
      END IF
    END DO
  END SUBROUTINE note_motion_start_velocity

  INTEGER FUNCTION count_motion_points(points, include_rod_points, include_body_points) RESULT(n)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    LOGICAL, INTENT(IN) :: include_rod_points, include_body_points
    INTEGER :: ids(SIZE(points))
    CALL fill_motion_point_ids(points, ids, include_rod_points, include_body_points, n)
  END FUNCTION count_motion_points

  SUBROUTINE fill_motion_point_ids(points, ids, include_rod_points, include_body_points, n_found)
    !! The ids of the prescribed-motion points: Coupled/Vessel points, plus rod-end and Body<N>
    !! points when included (the two flags are independent); n_found (optional) counts them.
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    INTEGER, INTENT(OUT) :: ids(:)
    LOGICAL, INTENT(IN) :: include_rod_points, include_body_points
    INTEGER, INTENT(OUT), OPTIONAL :: n_found
    INTEGER :: i, n
    LOGICAL :: take
    n = 0
    DO i = 1, SIZE(points)
      take = points(i)%ptype == 'coupled' .OR. points(i)%ptype == 'vessel'
      IF (.NOT. take .AND. include_rod_points) take = is_rod_point_type(points(i)%ptype)
      IF (.NOT. take .AND. include_body_points) take = starts_with(TRIM(points(i)%ptype), 'body')
      IF (take) THEN
        n = n + 1
        ids(n) = points(i)%id
      END IF
    END DO
    IF (PRESENT(n_found)) n_found = n
  END SUBROUTINE fill_motion_point_ids

  INTEGER FUNCTION find_motion_point(motion, point_id) RESULT(idx)
    TYPE(MotionTable), INTENT(IN) :: motion
    INTEGER, INTENT(IN) :: point_id
    INTEGER :: i
    idx = 0
    DO i = 1, motion%n_point
      IF (motion%point_ids(i) == point_id) THEN
        idx = i
        RETURN
      END IF
    END DO
  END FUNCTION find_motion_point

  LOGICAL FUNCTION is_endpoint_angle_channel(lo) RESULT(is_angle)
    !! Endpoint orientation channels. FairAngle/AnchAngle are retained as compatibility aliases for
    !! OrcaFlex-compatible declination; FairDecl/AnchDecl make that convention explicit, while
    !! FairIncl/AnchIncl report signed inclination below the horizontal.
    CHARACTER(*), INTENT(IN) :: lo
    is_angle = starts_with(lo, 'fairangle') .OR. starts_with(lo, 'anchangle') .OR. &
               starts_with(lo, 'fairdecl') .OR. starts_with(lo, 'anchdecl') .OR. &
               starts_with(lo, 'fairincl') .OR. starts_with(lo, 'anchincl')
  END FUNCTION is_endpoint_angle_channel

  LOGICAL FUNCTION is_fair_endpoint_angle(lo) RESULT(is_fair)
    CHARACTER(*), INTENT(IN) :: lo
    is_fair = starts_with(lo, 'fairangle') .OR. starts_with(lo, 'fairdecl') .OR. &
              starts_with(lo, 'fairincl')
  END FUNCTION is_fair_endpoint_angle

  INTEGER FUNCTION endpoint_angle_line_id(ch) RESULT(line_id)
    CHARACTER(*), INTENT(IN) :: ch
    CHARACTER(NAMELEN) :: lo
    lo = to_lower(ch)
    IF (starts_with(lo, 'fairangle') .OR. starts_with(lo, 'anchangle')) THEN
      line_id = int_suffix(ch, 10)
    ELSE
      line_id = int_suffix(ch, 9)
    END IF
  END FUNCTION endpoint_angle_line_id

  REAL(wp) FUNCTION endpoint_angle_from_declination(lo, declination) RESULT(angle)
    !! Inclination is signed below horizontal: 0 = horizontal, +90 = vertically down,
    !! -90 = vertically up. Declination and the Angle alias remain 0..180 from +GZ.
    CHARACTER(*), INTENT(IN) :: lo
    REAL(wp), INTENT(IN) :: declination
    angle = declination
    IF (starts_with(lo, 'fairincl') .OR. starts_with(lo, 'anchincl')) angle = declination - 90.0_wp
  END FUNCTION endpoint_angle_from_declination

  REAL(wp) FUNCTION channel_value(ch, lines, points, ne, q_all, q_off, ten_all, ten_off, end_ten, end_force) RESULT(v)
    CHARACTER(*), INTENT(IN) :: ch
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    INTEGER, INTENT(IN) :: ne(:), q_off(:), ten_off(:)
    REAL(wp), INTENT(IN) :: q_all(:)
    REAL(wp), INTENT(IN) :: ten_all(:)
    REAL(wp), INTENT(IN), OPTIONAL :: end_ten(:, :)   !! (anchor, fairlead) end-force magnitudes per line
    REAL(wp), INTENT(IN), OPTIONAL :: end_force(:, :, :)   !! (xyz, anchor/fairlead, line) end-force vectors
    INTEGER :: li, pidx, comp, kind, node, nnode, inode
    REAL(wp) :: fsum(3)
    CHARACTER(NAMELEN) :: lo
    v = CD_ZERO
    lo = to_lower(ch)
    ! FairTen<L>/AnchTen<L>: L is the external LINE id -> array index. The deck
    ! follows OrcaFlex End A=fairlead, End B=anchor, while internal arrays are
    ! anchor -> fairlead. With end_ten they are the force the line exerts on its end
    ! point (end element tension + the end node's lumped loads, MoorDyn/OrcaFlex end
    ! tension); without it the end elements' tension (fairlead ne, anchor 1).
    IF (starts_with(lo, 'fairten')) THEN
      li = find_line(lines, int_suffix(ch, 8))
      IF (PRESENT(end_ten)) THEN
        v = end_ten(2, li)
      ELSE
        v = ten_all(ten_off(li) + ne(li))        ! deck End A fairlead = internal last element
      END IF
    ELSE IF (starts_with(lo, 'anchten')) THEN
      li = find_line(lines, int_suffix(ch, 8))
      IF (PRESENT(end_ten)) THEN
        v = end_ten(1, li)
      ELSE
        v = ten_all(ten_off(li) + 1)             ! deck End B anchor = internal first element
      END IF
    ELSE IF (is_endpoint_angle_channel(lo)) THEN
      li = find_line(lines, endpoint_angle_line_id(ch))
      IF (is_fair_endpoint_angle(lo)) THEN
        v = line_geom_value(7, 1, ne(li) + 1, q_all(q_off(li) + 1:q_off(li + 1)), 3)
      ELSE
        v = line_geom_value(7, ne(li) + 1, ne(li) + 1, q_all(q_off(li) + 1:q_off(li + 1)), 3)
      END IF
      v = endpoint_angle_from_declination(lo, v)
    ELSE IF (is_point_force_channel(lo)) THEN
      ! resultant of the end forces of the lines bound to the point (End A = fairlead slot 2)
      CALL parse_point_force_channel(ch, pidx, comp)
      fsum = CD_ZERO
      IF (PRESENT(end_force)) THEN
        DO li = 1, SIZE(lines)
          IF (lines(li)%nodeA == pidx) fsum = fsum + end_force(:, 2, li)
          IF (lines(li)%nodeB == pidx) fsum = fsum + end_force(:, 1, li)
        END DO
      END IF
      IF (comp == 4) THEN
        v = SQRT(fsum(1)**2 + fsum(2)**2)
      ELSE
        v = fsum(comp)
      END IF
    ELSE IF (is_point_channel(lo)) THEN
      CALL parse_point_channel(ch, pidx, comp)
      v = points(point_index(points, pidx))%pos(comp)
    ELSE
      CALL parse_line_node_channel(ch, li, node, kind, comp)
      li = find_line(lines, li)
      nnode = ne(li) + 1
      SELECT CASE (kind)
      CASE (3)   ! nodal tension (end nodes: the end force, as FairTen/AnchTen)
        inode = deck_to_internal_node(node, ne(li))
        v = nodal_tension_value(ten_all(ten_off(li) + 1:ten_off(li) + ne(li)), inode)
        IF (PRESENT(end_ten)) THEN
          IF (inode == 1) v = end_ten(1, li)
          IF (inode == nnode) v = end_ten(2, li)
        END IF
      CASE (1)   ! position
        v = q_all(q_off(li) + 3*(deck_to_internal_node(node, ne(li)) - 1) + comp)
      CASE (5, 6, 7, 8)   ! curvature / bend moment / declination / azimuth (static EI=0 => bend moment 0)
        v = line_geom_value(kind, node, nnode, q_all(q_off(li) + 1:q_off(li + 1)), 3)
      CASE DEFAULT   ! velocity (2) / acceleration (4): zero in a static configuration
        v = CD_ZERO
      END SELECT
    END IF
  END FUNCTION channel_value

  INTEGER FUNCTION deck_to_internal_node(deck_node, nelem) RESULT(internal_node)
    !! Deck node numbering follows End A(fairlead)->End B(anchor). Internal line
    !! states are anchor->fairlead, so reverse node ids at the deck boundary.
    INTEGER, INTENT(IN) :: deck_node, nelem
    internal_node = nelem + 2 - deck_node
  END FUNCTION deck_to_internal_node

  SUBROUTINE check_channel(ch, lines, points, sections, ErrStat, ErrMsg, bodies, rods, zl_rod)
    CHARACTER(*), INTENT(IN) :: ch
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(DeckBody), INTENT(IN), OPTIONAL :: bodies(:)
    TYPE(DeckRod), INTENT(IN), OPTIONAL :: rods(:)
    ! zero-length rods collapsed to connector points (collapse_zero_length_rods)
    INTEGER, INTENT(IN), OPTIONAL :: zl_rod(:)
    CHARACTER(NAMELEN) :: lo
    INTEGER :: pidx, comp, kind, line_id, node, li, nelem
    LOGICAL :: is_body
    ErrStat = 0; ErrMsg = ''
    lo = to_lower(ch)
    IF (is_object_channel(lo)) THEN
      IF (.NOT. (PRESENT(bodies) .AND. PRESENT(rods))) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": Body<N>/Rod<N> channels are not supported here')
        RETURN
      END IF
      IF (PRESENT(zl_rod)) THEN
        CALL parse_object_channel(ch, is_body, pidx, node, comp)
        IF (.NOT. is_body .AND. ANY(zl_rod == pidx)) THEN
          CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": rod '//TRIM(int_to_str(pidx))//' has zero length '// &
                    '(NumSegs 0) and is modelled as a point; report it with Point<P> channels')
          RETURN
        END IF
      END IF
      CALL check_object_channel(ch, bodies, rods, ErrStat, ErrMsg)
    ELSE IF (starts_with(lo, 'fairten') .OR. starts_with(lo, 'anchten')) THEN
      IF (find_line(lines, int_suffix(ch, 8)) == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": unknown line id'); RETURN
      END IF
    ELSE IF (is_endpoint_angle_channel(lo)) THEN
      IF (find_line(lines, endpoint_angle_line_id(ch)) == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": unknown line id'); RETURN
      END IF
    ELSE IF (is_point_force_channel(lo)) THEN
      CALL parse_point_force_channel(ch, pidx, comp)
      IF (comp < 1 .OR. point_index(points, pidx) == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": bad point id or component'); RETURN
      END IF
    ELSE IF (CD_Is_TDP_Channel(lo)) THEN
      CALL CD_Parse_TDP_Channel(ch, line_id, comp)
      IF (comp < 1) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": bad touchdown channel (use TDP<L>s, TDP<L>x, '// &
                  'TDP<L>y, TDP<L>z, TDP<L>Lay or TDP<L>Exc)'); RETURN
      END IF
      IF (find_line(lines, line_id) == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": unknown line id'); RETURN
      END IF
    ELSE IF (is_point_channel(lo)) THEN
      CALL parse_point_channel(ch, pidx, comp)
      IF (comp < 1 .OR. comp > 3 .OR. point_index(points, pidx) == 0) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": bad point id or component'); RETURN
      END IF
    ELSE IF (starts_with(lo, 'torq') .OR. starts_with(lo, 'twist')) THEN
      CALL parse_line_node_channel(ch, line_id, node, kind, comp)
      li = find_line(lines, line_id)
      IF (li /= 0 .AND. node == 0 .AND. names_node_zero(lo)) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": node numbers start at 1 = End A (MoorDyn '// &
                  'numbers from N0)'); RETURN
      END IF
      IF (li == 0 .OR. kind == 0 .OR. node < 1) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": bad torsion channel (use Torq<L>N<J>, '// &
                  'Twist<L>N<J> or Twist<L>, with a known line id)'); RETURN
      END IF
      nelem = line_nelem_from_sections(lines(li)%id, sections)
      IF (node > nelem + 1) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": node index exceeds line node count'); RETURN
      END IF
      IF (.NOT. line_torsion_active(lines(li))) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": line '//TRIM(int_to_str(line_id))//' is not '// &
                  'torsionally restrained at both ends (END CONNECTIONS TorsStiffness), so it carries no '// &
                  'torque'); RETURN
      END IF
    ELSE IF (starts_with(lo, 'ten') .OR. starts_with(lo, 'curv') .OR. &
             starts_with(lo, 'bendmom') .OR. starts_with(lo, 'l')) THEN
      CALL parse_line_node_channel(ch, line_id, node, kind, comp)
      li = find_line(lines, line_id)
      IF (li /= 0 .AND. node == 0 .AND. names_node_zero(lo)) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": node numbers start at 1 = End A (MoorDyn '// &
                  'numbers from N0)'); RETURN
      END IF
      IF (li == 0 .OR. kind == 0 .OR. node < 1 .OR. comp < 0 .OR. comp > 3) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": bad line-node channel syntax'); RETURN
      END IF
      nelem = line_nelem_from_sections(lines(li)%id, sections)
      IF (node > nelem + 1) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": node index exceeds line node count'); RETURN
      END IF
    ELSE
      CALL fail(ErrStat, ErrMsg, 'OUTPUT channel "'//TRIM(ch)// &
                '" not supported (use FairTen<L>, AnchTen<L>, FairIncl<L>, AnchIncl<L>, '// &
                'FairDecl<L>, AnchDecl<L> (FairAngle/AnchAngle aliases), '// &
                'Point<P>p{x,y,z} (alias Con<P>p{x,y,z}), Point<P>F{x,y,z,H}, '// &
                'Ten<L>N<J>, Curv<L>N<J>, BendMom<L>N<J>, Torq<L>N<J>, Twist<L>N<J>, Twist<L>, '// &
                'L<L>N<J>p{x,y,z}, L<L>N<J>v{x,y,z}, L<L>N<J>a{x,y,z}, L<L>N<J>Dec, L<L>N<J>Azi, '// &
                'TDP<L>{s,x,y,z,Lay,Exc}, or the Body<N>/Rod<N> channels)'); RETURN
    END IF
  END SUBROUTINE check_channel

  PURE LOGICAL FUNCTION names_node_zero(lo) RESULT(yes)
    !! True when a lower-cased line-node channel names node 0 ("...n0" at the end or before
    !! a letter), the MoorDyn End A numbering.
    CHARACTER(*), INTENT(IN) :: lo
    INTEGER :: k, n
    yes = .FALSE.
    n = LEN_TRIM(lo)
    DO k = 2, n - 1
      IF (lo(k:k + 1) /= 'n0') CYCLE
      IF (INDEX('0123456789', lo(k - 1:k - 1)) == 0) CYCLE
      IF (k + 1 == n) THEN
        yes = .TRUE.
      ELSE
        yes = INDEX('0123456789', lo(k + 2:k + 2)) == 0
      END IF
      IF (yes) RETURN
    END DO
  END FUNCTION names_node_zero

  LOGICAL FUNCTION is_point_channel(lo) RESULT(is_point)
    !! Point position channels: Point<P>p{x,y,z}, or the MoorDyn v1 spelling Con<P>p{x,y,z}
    !! ("con" followed by a digit, so no other channel family is captured).
    CHARACTER(*), INTENT(IN) :: lo
    is_point = starts_with(lo, 'point')
    IF (is_point) RETURN
    IF (starts_with(lo, 'con') .AND. LEN(lo) >= 4) is_point = VERIFY(lo(4:4), '0123456789') == 0
  END FUNCTION is_point_channel

  LOGICAL FUNCTION is_point_force_channel(lo) RESULT(yes)
    !! Point<P>F{x,y,z} / Point<P>FH: the resultant of the line-end forces on point P.
    CHARACTER(*), INTENT(IN) :: lo
    INTEGER :: pidx, comp
    yes = .FALSE.
    IF (.NOT. starts_with(lo, 'point')) RETURN
    CALL parse_point_force_channel(lo, pidx, comp)
    yes = comp > 0
  END FUNCTION is_point_force_channel

  SUBROUTINE parse_point_force_channel(ch, pidx, comp)
    !! Point<P>F{x,y,z,H} -> point id P and component 1..3 (x, y, z) or 4 (horizontal
    !! magnitude); comp = 0 when malformed.
    CHARACTER(*), INTENT(IN) :: ch
    INTEGER, INTENT(OUT) :: pidx, comp
    CHARACTER(NAMELEN) :: lo
    INTEGER :: n, i
    lo = to_lower(ch)
    pidx = 0
    comp = 0
    n = LEN_TRIM(lo)
    IF (n < 8 .OR. .NOT. starts_with(lo, 'point')) RETURN
    IF (lo(n - 1:n - 1) /= 'f') RETURN
    IF (VERIFY(lo(6:n - 2), '0123456789') /= 0) RETURN
    IF (n - 2 - 6 + 1 > 9) RETURN
    DO i = 6, n - 2
      pidx = pidx*10 + (IACHAR(lo(i:i)) - IACHAR('0'))
    END DO
    SELECT CASE (lo(n:n))
    CASE ('x'); comp = 1
    CASE ('y'); comp = 2
    CASE ('z'); comp = 3
    CASE ('h'); comp = 4
    CASE DEFAULT; pidx = 0
    END SELECT
  END SUBROUTINE parse_point_force_channel

  SUBROUTINE point_force_value(ch, lines, models, val, ErrStat, ErrMsg)
    !! Point<P>F{x,y,z,H}: the resultant of the forces the attached EI=0 lines exert on point P
    !! (each the FairTen/AnchTen end force, CD_Get_Model_EndForces) -- for a Fixed point the
    !! anchor load, for a free point the line load it balances; H is the horizontal magnitude.
    !! models(i) is deck line i's model (End A = internal last node).
    CHARACTER(*), INTENT(IN) :: ch
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(CD_ModelType), INTENT(IN) :: models(:)
    REAL(wp), INTENT(OUT) :: val
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: pidx, comp, k, es
    REAL(wp) :: f(3), f_first(3), f_last(3)
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    val = CD_ZERO
    CALL parse_point_force_channel(ch, pidx, comp)
    f = CD_ZERO
    DO k = 1, MIN(SIZE(lines), SIZE(models))
      IF (lines(k)%nodeA /= pidx .AND. lines(k)%nodeB /= pidx) CYCLE
      CALL CD_Get_Model_EndForces(models(k), f_first, f_last, es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: point force recovery failed: '//TRIM(em)
        RETURN
      END IF
      IF (lines(k)%nodeA == pidx) f = f + f_last
      IF (lines(k)%nodeB == pidx) f = f + f_first
    END DO
    IF (comp == 4) THEN
      val = SQRT(f(1)**2 + f(2)**2)
    ELSE
      val = f(comp)
    END IF
  END SUBROUTINE point_force_value

  SUBROUTINE system_point_force_value(ch, system, val, ErrStat, ErrMsg)
    !! Point<P>F{x,y,z,H} on the point-system route: the resultant of the end forces of every line
    !! end currently bound to point P (system%bindings, End A = internal first node), so a
    !! FAILURE detach, which rebinds a line end to a reserve point, moves that force with it.
    CHARACTER(*), INTENT(IN) :: ch
    TYPE(CD_SystemType), INTENT(IN) :: system
    REAL(wp), INTENT(OUT) :: val
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: pidx, comp, k, es
    REAL(wp) :: f(3), f_first(3), f_last(3)
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    val = CD_ZERO
    CALL parse_point_force_channel(ch, pidx, comp)
    f = CD_ZERO
    IF (ALLOCATED(system%bindings)) THEN
      DO k = 1, SIZE(system%bindings)
        IF (system%bindings(k)%point_id /= pidx) CYCLE
        CALL CD_Get_Model_EndForces(system%lines(system%bindings(k)%line_index), f_first, f_last, es, em)
        IF (es /= CD_MODEL_OK) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: point force recovery failed: '//TRIM(em)
          RETURN
        END IF
        IF (system%bindings(k)%line_end == CD_LINE_END_A) THEN
          f = f + f_first
        ELSE
          f = f + f_last
        END IF
      END DO
    END IF
    IF (comp == 4) THEN
      val = SQRT(f(1)**2 + f(2)**2)
    ELSE
      val = f(comp)
    END IF
  END SUBROUTINE system_point_force_value

  SUBROUTINE parse_point_channel(ch, pidx, comp)
    !! Point<P>p{x,y,z} / Con<P>p{x,y,z} -> point id P and component 1..3 (0 when malformed).
    CHARACTER(*), INTENT(IN) :: ch
    INTEGER, INTENT(OUT) :: pidx, comp
    CHARACTER(NAMELEN) :: lo
    INTEGER :: pp, i, d0, d1
    lo = to_lower(ch)
    pidx = 0; comp = 0
    d0 = 6
    IF (.NOT. starts_with(lo, 'point')) d0 = 4
    pp = INDEX(lo, 'p', BACK=.TRUE.)
    IF (pp <= d0) RETURN
    d1 = pp - 1
    pidx = 0
    DO i = d0, d1
      IF (lo(i:i) < '0' .OR. lo(i:i) > '9') THEN; pidx = 0; RETURN; END IF
      IF (pidx > (HUGE(pidx) - (IACHAR(lo(i:i)) - IACHAR('0')))/10) THEN; pidx = 0; RETURN; END IF
      pidx = pidx*10 + (IACHAR(lo(i:i)) - IACHAR('0'))
    END DO
    ! The component char must be the FINAL trimmed char: the advertised syntax is exactly
    ! `Point<P>p{x,y,z}`, so a typo with trailing text (Point2px_raw, Point2pzz) is rejected
    ! (comp = 0) rather than silently accepted as the leading component.
    IF (pp + 1 /= LEN_TRIM(lo)) RETURN
    SELECT CASE (lo(pp + 1:pp + 1))
    CASE ('x'); comp = 1
    CASE ('y'); comp = 2
    CASE ('z'); comp = 3
    CASE DEFAULT; comp = 0
    END SELECT
  END SUBROUTINE parse_point_channel

  SUBROUTINE parse_line_node_channel(ch, line_id, node_id, kind, comp)
    !! Parse supported line-node output channels (kind codes shared with the writers):
    !!   Ten<L>N<J>        -> kind=3, comp=0    nodal tension       [N]
    !!   Curv<L>N<J>       -> kind=5, comp=0    curvature           [1/m]
    !!   BendMom<L>N<J>    -> kind=6, comp=0    bend moment         [N.m]
    !!   L<L>N<J>p{x,y,z}  -> kind=1, comp=1..3 position            [m]
    !!   L<L>N<J>v{x,y,z}  -> kind=2, comp=1..3 velocity            [m/s]
    !!   L<L>N<J>a{x,y,z}  -> kind=4, comp=1..3 acceleration        [m/s^2]
    !!   L<L>N<J>Dec       -> kind=7, comp=0    declination         [deg]
    !!   L<L>N<J>Azi       -> kind=8, comp=0    azimuth             [deg]
    !!   Torq<L>N<J>       -> kind=9, comp=0    line torque         [N.m]
    !!   Twist<L>N<J>      -> kind=10, comp=0   twist from End A    [deg]
    !!   Twist<L>          -> kind=11, comp=0   total twist (node 1) [deg]
    CHARACTER(*), INTENT(IN) :: ch
    INTEGER, INTENT(OUT) :: line_id, node_id, kind, comp

    CHARACTER(NAMELEN) :: lo
    INTEGER :: npos, field_pos, last, sfx

    lo = to_lower(ch)
    line_id = 0
    node_id = 0
    kind = 0
    comp = 0
    last = LEN_TRIM(lo)
    ! Scalar-per-node channels with a leading keyword: Ten / Curv / BendMom / Torq / Twist, and
    ! the line total Twist<L> (kind 11, node 1).
    IF (starts_with(lo, 'torq')) THEN
      CALL parse_keyword_line_node(lo, 4, last, line_id, node_id)
      IF (line_id > 0 .AND. node_id > 0) kind = 9
      RETURN
    ELSE IF (starts_with(lo, 'twist')) THEN
      IF (last > 5) THEN
        IF (INDEX(lo(6:last), 'n') == 0) THEN
          line_id = parse_positive_int(lo, 6, last)
          IF (line_id > 0) THEN
            node_id = 1
            kind = 11
          END IF
          RETURN
        END IF
      END IF
      CALL parse_keyword_line_node(lo, 5, last, line_id, node_id)
      IF (line_id > 0 .AND. node_id > 0) kind = 10
      RETURN
    ELSE IF (starts_with(lo, 'ten')) THEN
      CALL parse_keyword_line_node(lo, 3, last, line_id, node_id)
      IF (line_id > 0 .AND. node_id > 0) kind = 3
      RETURN
    ELSE IF (starts_with(lo, 'curv')) THEN
      CALL parse_keyword_line_node(lo, 4, last, line_id, node_id)
      IF (line_id > 0 .AND. node_id > 0) kind = 5
      RETURN
    ELSE IF (starts_with(lo, 'bendmom')) THEN
      CALL parse_keyword_line_node(lo, 7, last, line_id, node_id)
      IF (line_id > 0 .AND. node_id > 0) kind = 6
      RETURN
    END IF
    ! L<L>N<J>... channels: p/v/a{x,y,z} (component) or Dec/Azi (scalar).
    IF (.NOT. starts_with(lo, 'l')) RETURN
    npos = INDEX(lo(2:last), 'n')
    IF (npos == 0) RETURN
    npos = npos + 1
    ! Three-letter scalar suffixes first (Dec / Azi), so 'a' in "azi" is not read as accel.
    IF (last >= npos + 4) THEN
      sfx = last - 2
      IF (lo(sfx:last) == 'dec' .OR. lo(sfx:last) == 'azi') THEN
        line_id = parse_positive_int(lo, 2, npos - 1)
        node_id = parse_positive_int(lo, npos + 1, sfx - 1)
        IF (line_id <= 0 .OR. node_id <= 0) RETURN
        IF (lo(sfx:last) == 'dec') kind = 7
        IF (lo(sfx:last) == 'azi') kind = 8
        RETURN
      END IF
    END IF
    ! Component channels: p/v/a followed by x/y/z.
    field_pos = 0
    IF (last >= npos + 3) THEN
      IF (lo(last - 1:last - 1) == 'p' .OR. lo(last - 1:last - 1) == 'v' .OR. &
          lo(last - 1:last - 1) == 'a') field_pos = last - 1
    END IF
    IF (field_pos == 0) RETURN
    line_id = parse_positive_int(lo, 2, npos - 1)
    node_id = parse_positive_int(lo, npos + 1, field_pos - 1)
    IF (line_id <= 0 .OR. node_id <= 0) RETURN
    SELECT CASE (lo(field_pos:field_pos))
    CASE ('p'); kind = 1
    CASE ('v'); kind = 2
    CASE ('a'); kind = 4
    CASE DEFAULT; kind = 0
    END SELECT
    SELECT CASE (lo(last:last))
    CASE ('x'); comp = 1
    CASE ('y'); comp = 2
    CASE ('z'); comp = 3
    CASE DEFAULT; comp = 0
    END SELECT
    IF (comp == 0) kind = 0
  END SUBROUTINE parse_line_node_channel

  SUBROUTINE parse_keyword_line_node(lo, prefix_len, last, line_id, node_id)
    !! Parse `<keyword><line digits>n<node digits>` (lo already lowercased). The 'n'
    !! separator is the first 'n' AFTER the keyword prefix, so keyword letters that
    !! themselves contain 'n' (e.g. "bendmom") do not confuse the line/node split.
    CHARACTER(*), INTENT(IN) :: lo
    INTEGER, INTENT(IN) :: prefix_len, last
    INTEGER, INTENT(OUT) :: line_id, node_id
    INTEGER :: npos

    line_id = 0
    node_id = 0
    IF (last <= prefix_len) RETURN
    npos = INDEX(lo(prefix_len + 1:last), 'n')
    IF (npos == 0) RETURN
    npos = npos + prefix_len
    line_id = parse_positive_int(lo, prefix_len + 1, npos - 1)
    node_id = parse_positive_int(lo, npos + 1, last)
  END SUBROUTINE parse_keyword_line_node

  INTEGER FUNCTION parse_positive_int(s, first, last) RESULT(n)
    CHARACTER(*), INTENT(IN) :: s
    INTEGER, INTENT(IN) :: first, last
    INTEGER :: i, c

    n = 0
    IF (first > last .OR. first < 1 .OR. last > LEN_TRIM(s)) RETURN
    DO i = first, last
      c = IACHAR(s(i:i))
      IF (c < IACHAR('0') .OR. c > IACHAR('9')) THEN
        n = 0
        RETURN
      END IF
      IF (n > (HUGE(n) - (c - IACHAR('0')))/10) THEN
        n = 0
        RETURN
      END IF
      n = n*10 + (c - IACHAR('0'))
    END DO
  END FUNCTION parse_positive_int

  INTEGER FUNCTION line_nelem_from_sections(line_id, sections) RESULT(nelem)
    INTEGER, INTENT(IN) :: line_id
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    INTEGER :: i

    nelem = 0
    DO i = 1, SIZE(sections)
      IF (sections(i)%line_id == line_id) nelem = nelem + sections(i)%nsegs
    END DO
  END FUNCTION line_nelem_from_sections

  REAL(wp) FUNCTION nodal_tension_value(tension, node_id) RESULT(value)
    REAL(wp), INTENT(IN) :: tension(:)
    INTEGER, INTENT(IN) :: node_id

    IF (node_id <= 1) THEN
      value = tension(1)
    ELSE IF (node_id >= SIZE(tension) + 1) THEN
      value = tension(SIZE(tension))
    ELSE
      value = 0.5_wp*(tension(node_id - 1) + tension(node_id))
    END IF
  END FUNCTION nodal_tension_value

  ! -------------------------------------------------------------------------- !
  ! Geometric output channels (curvature, bend moment, declination, azimuth).  !
  ! All are pure functions of the line node positions, so ONE definition serves !
  ! EI=0 and finite-EI lines and every writer. Curvature is the discrete Menger !
  ! (circumcircle) curvature; the axial tangent is oriented End A -> End B      !
  ! (increasing deck node index = OrcaFlex node Ez axis). Declination is the    !
  ! angle from +GZ (0 = up, 90 = horizontal, 180 = down) and azimuth is measured !
  ! from +GX toward +GY in [0,360) deg -- doc/conventions.rst section 7.       !
  ! -------------------------------------------------------------------------- !

  PURE FUNCTION cd_cross(a, b) RESULT(c)
    REAL(wp), INTENT(IN) :: a(3), b(3)
    REAL(wp) :: c(3)
    c = [a(2)*b(3) - a(3)*b(2), a(3)*b(1) - a(1)*b(3), a(1)*b(2) - a(2)*b(1)]
  END FUNCTION cd_cross

  PURE REAL(wp) FUNCTION menger_curvature(p1, p2, p3) RESULT(kappa)
    !! Curvature 1/R of the unique circle through three points (Menger curvature):
    !!   kappa = 2 |u x w| / (|u| |w| |w-u|),  u = p2-p1, w = p3-p1.
    !! Exact 1/R for three cocircular points at any spacing; 0 for collinear points.
    REAL(wp), INTENT(IN) :: p1(3), p2(3), p3(3)
    REAL(wp) :: u(3), w(3), den
    kappa = CD_ZERO
    u = p2 - p1
    w = p3 - p1
    den = NORM2(u)*NORM2(w)*NORM2(w - u)
    IF (den <= TINY(CD_ONE)) RETURN
    kappa = 2.0_wp*NORM2(cd_cross(u, w))/den
  END FUNCTION menger_curvature

  PURE REAL(wp) FUNCTION deck_node_curvature(r, nnode, deck_node) RESULT(kappa)
    !! Discrete curvature [1/m] at a deck node (1 = End A ... nnode = End B).
    !! Interior nodes use the circumcircle of the node and its two neighbours; end
    !! nodes adopt the nearest interior node's value, mirroring how the tension
    !! channel gives an end node its adjacent element's value.
    REAL(wp), INTENT(IN) :: r(:, :)      ! 3 x nnode, deck order (col 1 = End A)
    INTEGER, INTENT(IN) :: nnode, deck_node
    INTEGER :: j
    kappa = CD_ZERO
    IF (nnode < 3) RETURN                ! a single element is straight
    j = deck_node
    IF (j < 2) j = 2
    IF (j > nnode - 1) j = nnode - 1
    kappa = menger_curvature(r(:, j - 1), r(:, j), r(:, j + 1))
  END FUNCTION deck_node_curvature

  PURE FUNCTION circumcircle_curvature_vector(p1, p2, p3) RESULT(kvec)
    !! Discrete curvature VECTOR at p2 of the circle through p1,p2,p3: magnitude 1/R,
    !! direction from p2 toward the circumcircle centre. kvec = (c - p2)/|c - p2|^2 with
    !! the standard 3-point circumcentre c. Zero for collinear points. Used to form the
    !! reference-relative bending strain |kvec_current - kvec_reference|.
    REAL(wp), INTENT(IN) :: p1(3), p2(3), p3(3)
    REAL(wp) :: kvec(3), a(3), b(3), axb(3), num(3), cp(3), axb2, d2
    kvec = CD_ZERO
    a = p1 - p2
    b = p3 - p2
    axb = cd_cross(a, b)
    axb2 = DOT_PRODUCT(axb, axb)
    IF (axb2 <= TINY(CD_ONE)) RETURN                       ! collinear -> zero curvature
    num = DOT_PRODUCT(a, a)*b - DOT_PRODUCT(b, b)*a
    cp = cd_cross(num, axb)/(2.0_wp*axb2)                  ! circumcentre relative to p2
    d2 = DOT_PRODUCT(cp, cp)
    IF (d2 <= TINY(CD_ONE)) RETURN
    kvec = cp/d2                                           ! |kvec| = 1/R, toward the centre
  END FUNCTION circumcircle_curvature_vector

  PURE FUNCTION node_curvature_vector(r, nnode, node) RESULT(kvec)
    !! Discrete curvature vector [1/m] at a node (any consistent node order; the vector is
    !! traversal-direction independent). Interior nodes use the circumcircle of the node and
    !! its two neighbours; end nodes adopt the nearest interior node's value.
    REAL(wp), INTENT(IN) :: r(:, :)      ! 3 x nnode
    INTEGER, INTENT(IN) :: nnode, node
    REAL(wp) :: kvec(3)
    INTEGER :: j
    kvec = CD_ZERO
    IF (nnode < 3) RETURN
    j = node
    IF (j < 2) j = 2
    IF (j > nnode - 1) j = nnode - 1
    kvec = circumcircle_curvature_vector(r(:, j - 1), r(:, j), r(:, j + 1))
  END FUNCTION node_curvature_vector

  PURE FUNCTION deck_node_tangent(r, nnode, deck_node) RESULT(t)
    !! Unnormalised axial tangent at a deck node, oriented End A -> End B. Interior
    !! nodes use a central difference; end nodes a one-sided difference.
    REAL(wp), INTENT(IN) :: r(:, :)
    INTEGER, INTENT(IN) :: nnode, deck_node
    REAL(wp) :: t(3)
    t = CD_ZERO
    IF (nnode < 2) RETURN
    IF (deck_node <= 1) THEN
      t = r(:, 2) - r(:, 1)
    ELSE IF (deck_node >= nnode) THEN
      t = r(:, nnode) - r(:, nnode - 1)
    ELSE
      t = r(:, deck_node + 1) - r(:, deck_node - 1)
    END IF
  END FUNCTION deck_node_tangent

  PURE REAL(wp) FUNCTION tangent_declination_deg(t) RESULT(dec)
    !! Angle from +GZ [deg]: 0 = straight up, 90 = horizontal, 180 = straight down.
    REAL(wp), INTENT(IN) :: t(3)
    REAL(wp) :: n
    dec = CD_ZERO
    n = NORM2(t)
    IF (n <= TINY(CD_ONE)) RETURN
    dec = ACOS(MAX(-CD_ONE, MIN(CD_ONE, t(3)/n)))*CD_RAD2DEG
  END FUNCTION tangent_declination_deg

  PURE REAL(wp) FUNCTION tangent_azimuth_deg(t) RESULT(azi)
    !! Azimuth [deg] in [0,360): horizontal-plane angle from +GX toward +GY. A
    !! vertical tangent has no defined azimuth and returns 0.
    REAL(wp), INTENT(IN) :: t(3)
    azi = CD_ZERO
    IF (ABS(t(1)) <= TINY(CD_ONE) .AND. ABS(t(2)) <= TINY(CD_ONE)) RETURN
    azi = ATAN2(t(2), t(1))*CD_RAD2DEG
    IF (azi < CD_ZERO) azi = azi + 360.0_wp
  END FUNCTION tangent_azimuth_deg

  PURE REAL(wp) FUNCTION line_geom_value(kind, deck_node, nnode, q_flat, stride) RESULT(v)
    !! Shared evaluator for the GEOMETRIC output channels so every writer computes them
    !! identically. `q_flat` holds the line node positions in INTERNAL order
    !! (anchor->fairlead) with `stride` reals per node (3 for EI=0, 6 for finite-EI).
    !! kind: 5 curvature, 7 declination, 8 azimuth. Bend moment is NOT geometric -- it is
    !! the MATERIAL moment EI*(kappa - kappa_0), computed per path (zero on EI=0 lines;
    !! finite_model_channel_value and range_sample_fmodel on finite-EI lines), so it is not
    !! handled here and
    !! kind = 6 returns 0.
    INTEGER, INTENT(IN) :: kind, deck_node, nnode, stride
    REAL(wp), INTENT(IN) :: q_flat(:)
    REAL(wp) :: r(3, nnode)
    INTEGER :: j, base
    ! Deck node j (1 = End A) <-> internal node (nnode+1-j); extract deck-ordered positions.
    DO j = 1, nnode
      base = stride*(nnode - j)
      r(:, j) = q_flat(base + 1:base + 3)
    END DO
    v = line_geom_from_r(kind, r, nnode, deck_node)
  END FUNCTION line_geom_value

  PURE REAL(wp) FUNCTION line_geom_from_r(kind, r, nnode, deck_node) RESULT(v)
    !! Geometric channel value (kind: 5 curvature, 7 declination, 8 azimuth) from the
    !! deck-ordered node positions r(3, nnode). Factored out of line_geom_value so a caller
    !! that writes EVERY node of a line (the .static.out profile) builds r ONCE per line
    !! rather than rebuilding it inside each per-node call -- O(nnode) instead of O(nnode^2).
    INTEGER, INTENT(IN) :: kind, nnode, deck_node
    REAL(wp), INTENT(IN) :: r(3, nnode)
    v = CD_ZERO
    SELECT CASE (kind)
    CASE (5)   ! curvature [1/m] (OrcaFlex "Curvature" is the geometric centreline curvature)
      v = deck_node_curvature(r, nnode, deck_node)
    CASE (7)   ! declination [deg]
      v = tangent_declination_deg(deck_node_tangent(r, nnode, deck_node))
    CASE (8)   ! azimuth [deg]
      v = tangent_azimuth_deg(deck_node_tangent(r, nnode, deck_node))
    END SELECT
  END FUNCTION line_geom_from_r

  PURE REAL(wp) FUNCTION nodal_ei_value(ei, node_id) RESULT(value)
    !! Nodal bend stiffness from per-element EI (internal order), using the SAME averaging as
    !! nodal_tension_value: end nodes take the adjacent element, interior nodes average the
    !! two adjacent elements. Homogeneous section => the section EI; a section boundary => the
    !! mean of the two sections' EI. Used by the finite-EI material bend-moment channel.
    REAL(wp), INTENT(IN) :: ei(:)
    INTEGER, INTENT(IN) :: node_id
    IF (node_id <= 1) THEN
      value = ei(1)
    ELSE IF (node_id >= SIZE(ei) + 1) THEN
      value = ei(SIZE(ei))
    ELSE
      value = 0.5_wp*(ei(node_id - 1) + ei(node_id))
    END IF
  END FUNCTION nodal_ei_value

  SUBROUTINE set_init_summary(line_id, tension, declination, azimuth, summary, fair_force, force_is_total)
    !! Convert the public End-A tangent convention into a fairlead load vector.
    !! The vector is the force exerted by the line on the fairlead, so it points
    !! from End A into the line toward End B.
    INTEGER, INTENT(IN) :: line_id
    REAL(wp), INTENT(IN) :: tension, declination, azimuth
    TYPE(CD_LineInitSummary), INTENT(OUT) :: summary
    REAL(wp), INTENT(IN), OPTIONAL :: fair_force(3)
    LOGICAL, INTENT(IN), OPTIONAL :: force_is_total
    REAL(wp) :: dec_rad, azi_rad

    summary%line_id = line_id
    summary%fair_tension = tension
    summary%fair_declination = declination
    summary%fair_inclination = declination - 90.0_wp
    summary%fair_azimuth = azimuth
    dec_rad = declination/CD_RAD2DEG
    azi_rad = azimuth/CD_RAD2DEG
    summary%fair_force = tension*[SIN(dec_rad)*COS(azi_rad), SIN(dec_rad)*SIN(azi_rad), COS(dec_rad)]
    IF (PRESENT(fair_force)) summary%fair_force = fair_force
    summary%force_is_total = .TRUE.
    IF (PRESENT(force_is_total)) summary%force_is_total = force_is_total
  END SUBROUTINE set_init_summary

  SUBROUTINE init_summary_channels(line_id, fair_ten, fair_dec, fair_azi)
    INTEGER, INTENT(IN) :: line_id
    CHARACTER(NAMELEN), INTENT(OUT) :: fair_ten, fair_dec, fair_azi
    WRITE (fair_ten, '(A,I0)') 'FairTen', line_id
    WRITE (fair_dec, '(A,I0)') 'FairDecl', line_id
    WRITE (fair_azi, '(A,I0,A)') 'L', line_id, 'N1Azi'
  END SUBROUTINE init_summary_channels

  SUBROUTINE collect_aggregate_init_summaries(lines, agg, ErrStat, ErrMsg)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(CD_DeckAggregateType), INTENT(INOUT) :: agg
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: i, es
    REAL(wp) :: tension, declination, azimuth, fair_force(3), f_first(3)
    CHARACTER(NAMELEN) :: cten, cdec, cazi
    CHARACTER(240) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    ALLOCATE (agg%init_lines(SIZE(lines)))
    DO i = 1, SIZE(lines)
      CALL init_summary_channels(lines(i)%id, cten, cdec, cazi)
      CALL CD_Eval_Aggregate_Channel(cten, agg%has_sys, agg%sys, agg%cables, agg%line_is_cable, &
                                     agg%line_obj_index, tension, es, em)
      IF (es == CD_DECKDRV_OK) &
        CALL CD_Eval_Aggregate_Channel(cdec, agg%has_sys, agg%sys, agg%cables, agg%line_is_cable, &
                                       agg%line_obj_index, declination, es, em)
      IF (es == CD_DECKDRV_OK) &
        CALL CD_Eval_Aggregate_Channel(cazi, agg%has_sys, agg%sys, agg%cables, agg%line_is_cable, &
                                       agg%line_obj_index, azimuth, es, em)
      IF (es /= CD_DECKDRV_OK) THEN
        ErrStat = es
        ErrMsg = 'CableDyn_DeckDriver: initialization report failed for LINE '// &
                 TRIM(int_to_str(lines(i)%id))//': '//TRIM(em)
        RETURN
      END IF
      IF (agg%line_is_cable(lines(i)%id)) THEN
        CALL CD_HFMF_CalcOutput(agg%cables(agg%line_obj_index(lines(i)%id)), fair_force, es, em)
        IF (es /= 0) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: initialization fairlead reaction failed for LINE '// &
                   TRIM(int_to_str(lines(i)%id))//': '//TRIM(em)
          RETURN
        END IF
        CALL set_init_summary(lines(i)%id, tension, declination, azimuth, agg%init_lines(i), fair_force=fair_force)
        IF (ALLOCATED(agg%cable_note)) agg%init_lines(i)%note = agg%cable_note(agg%line_obj_index(lines(i)%id))
      ELSE IF (agg%has_sys) THEN
        ! The force the EI=0 line exerts on its fairlead (internal last node), as the
        ! standalone driver reports it (collect_system_init_summaries).
        CALL CD_Get_Model_EndForces(agg%sys%lines(agg%line_obj_index(lines(i)%id)), f_first, fair_force, es, em)
        IF (es /= CD_MODEL_OK) THEN
          ErrStat = CD_DECKDRV_SOLVEFAIL
          ErrMsg = 'CableDyn_DeckDriver: initialization fairlead reaction failed for LINE '// &
                   TRIM(int_to_str(lines(i)%id))//': '//TRIM(em)
          RETURN
        END IF
        CALL set_init_summary(lines(i)%id, tension, declination, azimuth, agg%init_lines(i), fair_force=fair_force)
      ELSE
        CALL set_init_summary(lines(i)%id, tension, declination, azimuth, agg%init_lines(i))
      END IF
    END DO
  END SUBROUTINE collect_aggregate_init_summaries

  SUBROUTINE collect_raw_init_summaries(lines, points, ne, q_all, q_off, ten_all, ten_off, summaries, end_ten, &
                                        end_force)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    INTEGER, INTENT(IN) :: ne(:), q_off(:), ten_off(:)
    REAL(wp), INTENT(IN) :: q_all(:), ten_all(:)
    TYPE(CD_LineInitSummary), ALLOCATABLE, INTENT(OUT) :: summaries(:)
    REAL(wp), INTENT(IN), OPTIONAL :: end_ten(:, :)   !! (anchor, fairlead) end-force magnitudes per line
    !! (anchor, fairlead) end-force vectors per line; the fairlead vector is the reported force
    REAL(wp), INTENT(IN), OPTIONAL :: end_force(:, :, :)
    INTEGER :: i
    REAL(wp) :: tension, declination, azimuth
    CHARACTER(NAMELEN) :: cten, cdec, cazi

    ALLOCATE (summaries(SIZE(lines)))
    DO i = 1, SIZE(lines)
      CALL init_summary_channels(lines(i)%id, cten, cdec, cazi)
      tension = channel_value(cten, lines, points, ne, q_all, q_off, ten_all, ten_off, end_ten)
      declination = channel_value(cdec, lines, points, ne, q_all, q_off, ten_all, ten_off)
      azimuth = channel_value(cazi, lines, points, ne, q_all, q_off, ten_all, ten_off)
      IF (PRESENT(end_force)) THEN
        CALL set_init_summary(lines(i)%id, tension, declination, azimuth, summaries(i), fair_force=end_force(:, 2, i))
      ELSE
        CALL set_init_summary(lines(i)%id, tension, declination, azimuth, summaries(i))
      END IF
    END DO
  END SUBROUTINE collect_raw_init_summaries

  SUBROUTINE collect_model_init_summaries(lines, points, models, summaries, ErrStat, ErrMsg)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(CD_ModelType), INTENT(IN) :: models(:)
    TYPE(CD_LineInitSummary), ALLOCATABLE, INTENT(OUT) :: summaries(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(ModelOutputWorkspace) :: work
    INTEGER :: i, es
    REAL(wp) :: tension, declination, azimuth, f_first(3), fair_force(3)
    CHARACTER(NAMELEN) :: cten, cdec, cazi
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK; ErrMsg = ''
    ALLOCATE (summaries(SIZE(lines)))
    DO i = 1, SIZE(lines)
      CALL init_summary_channels(lines(i)%id, cten, cdec, cazi)
      CALL model_channel_value(cten, lines, points, models, work, tension, ErrStat, ErrMsg)
      IF (ErrStat == CD_DECKDRV_OK) CALL model_channel_value(cdec, lines, points, models, work, declination, &
                                                             ErrStat, ErrMsg)
      IF (ErrStat == CD_DECKDRV_OK) CALL model_channel_value(cazi, lines, points, models, work, azimuth, &
                                                             ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      ! the force vector the line exerts on its fairlead (internal last node)
      CALL CD_Get_Model_EndForces(models(i), f_first, fair_force, es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: end-force recovery failed: '//TRIM(em)
        RETURN
      END IF
      CALL set_init_summary(lines(i)%id, tension, declination, azimuth, summaries(i), fair_force=fair_force)
    END DO
  END SUBROUTINE collect_model_init_summaries

  SUBROUTINE collect_system_init_summaries(lines, points, system, summaries, ErrStat, ErrMsg)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(CD_SystemType), INTENT(IN) :: system
    TYPE(CD_LineInitSummary), ALLOCATABLE, INTENT(OUT) :: summaries(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(ModelOutputWorkspace) :: work
    INTEGER :: i, es
    REAL(wp) :: tension, declination, azimuth, f_first(3), fair_force(3)
    CHARACTER(NAMELEN) :: cten, cdec, cazi
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK; ErrMsg = ''
    ALLOCATE (summaries(SIZE(lines)))
    DO i = 1, SIZE(lines)
      CALL init_summary_channels(lines(i)%id, cten, cdec, cazi)
      CALL system_channel_value(cten, lines, points, system, work, tension, ErrStat, ErrMsg)
      IF (ErrStat == CD_DECKDRV_OK) CALL system_channel_value(cdec, lines, points, system, work, declination, &
                                                              ErrStat, ErrMsg)
      IF (ErrStat == CD_DECKDRV_OK) CALL system_channel_value(cazi, lines, points, system, work, azimuth, &
                                                              ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      ! the force vector the line exerts on its fairlead (internal last node)
      CALL CD_Get_Model_EndForces(system%lines(i), f_first, fair_force, es, em)
      IF (es /= CD_MODEL_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: end-force recovery failed: '//TRIM(em)
        RETURN
      END IF
      CALL set_init_summary(lines(i)%id, tension, declination, azimuth, summaries(i), fair_force=fair_force)
    END DO
  END SUBROUTINE collect_system_init_summaries

  SUBROUTINE collect_finite_init_summaries(lines, points, models, summaries, ErrStat, ErrMsg)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(FiniteDeckModel), INTENT(IN) :: models(:)
    TYPE(CD_LineInitSummary), ALLOCATABLE, INTENT(OUT) :: summaries(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(ModelOutputWorkspace) :: work
    INTEGER :: i
    REAL(wp) :: tension, declination, azimuth
    CHARACTER(NAMELEN) :: cten, cdec, cazi

    ErrStat = CD_DECKDRV_OK; ErrMsg = ''
    ALLOCATE (summaries(SIZE(lines)))
    DO i = 1, SIZE(lines)
      CALL init_summary_channels(lines(i)%id, cten, cdec, cazi)
      CALL finite_model_channel_value(cten, lines, points, models, work, tension, ErrStat, ErrMsg)
      IF (ErrStat == CD_DECKDRV_OK) CALL finite_model_channel_value(cdec, lines, points, models, work, declination, &
                                                                    ErrStat, ErrMsg)
      IF (ErrStat == CD_DECKDRV_OK) CALL finite_model_channel_value(cazi, lines, points, models, work, azimuth, &
                                                                    ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      ! The retained Cosserat compatibility route does not expose its complete
      ! prescribed-DOF reaction. Report the auditable axial component explicitly;
      ! the production Hermite/OpenFAST paths above report the full reaction.
      CALL set_init_summary(lines(i)%id, tension, declination, azimuth, summaries(i), force_is_total=.FALSE.)
    END DO
  END SUBROUTINE collect_finite_init_summaries

  SUBROUTINE collect_hermite_init_summaries(lines, cables, summaries, ErrStat, ErrMsg)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(CD_HFMF_ModuleType), INTENT(INOUT) :: cables(:)
    TYPE(CD_LineInitSummary), ALLOCATABLE, INTENT(OUT) :: summaries(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: i
    REAL(wp) :: tension, declination, azimuth, fair_force(3)
    CHARACTER(NAMELEN) :: cten, cdec, cazi

    ErrStat = CD_DECKDRV_OK; ErrMsg = ''
    ALLOCATE (summaries(SIZE(lines)))
    DO i = 1, SIZE(lines)
      CALL init_summary_channels(lines(i)%id, cten, cdec, cazi)
      CALL eval_cable_channel(cables(i), cten, tension, ErrStat, ErrMsg)
      IF (ErrStat == CD_DECKDRV_OK) CALL eval_cable_channel(cables(i), cdec, declination, ErrStat, ErrMsg)
      IF (ErrStat == CD_DECKDRV_OK) CALL eval_cable_channel(cables(i), cazi, azimuth, ErrStat, ErrMsg)
      IF (ErrStat == CD_DECKDRV_OK) CALL CD_HFMF_CalcOutput(cables(i), fair_force, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL set_init_summary(lines(i)%id, tension, declination, azimuth, summaries(i), fair_force=fair_force)
    END DO
  END SUBROUTINE collect_hermite_init_summaries

  SUBROUTINE print_deck_init_report(deck_path, lines, points, sections, n_finite, summaries)
    !! The initialization report goes to stderr (see doc/cli.rst).
    CHARACTER(*), INTENT(IN) :: deck_path
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    INTEGER, INTENT(IN) :: n_finite
    TYPE(CD_LineInitSummary), INTENT(IN) :: summaries(:)
    INTEGER :: i
    REAL(wp) :: f_incl

    WRITE (error_unit, '(A)') '  Parsing CableDyn input file: '//TRIM(deck_path)
    WRITE (error_unit, '(A,I0,A,I0,A,I0,A,I0,A,I0,A)') &
      '   Created CableDyn model: ', SIZE(lines), ' line object(s), ', SIZE(points), ' point(s), ', &
      SIZE(sections), ' section(s) [EI=0: ', SIZE(lines) - n_finite, ', finite-EI: ', n_finite, '].'
    WRITE (error_unit, '(A)') '   Initial conditions: Newton static equilibrium with load continuation completed.'
    WRITE (error_unit, '(A)') '   Fairlead convention: force is on End A toward End B; '// &
      'inclinations are signed below horizontal.'
    DO i = 1, SIZE(summaries)
      WRITE (error_unit, '(A,I0,A,ES13.5E3,A)') '   Line ', summaries(i)%line_id, &
        ' fairlead effective tension: ', summaries(i)%fair_tension, ' N'
      ! The force carries the end node's share of the line load (and, finite-EI, the end
      ! shear), so its angle differs slightly from the line tangent's: both are printed.
      f_incl = ATAN2(-summaries(i)%fair_force(3), NORM2(summaries(i)%fair_force(1:2)))*CD_RAD2DEG
      IF (summaries(i)%force_is_total) THEN
        WRITE (error_unit, '(A,3(ES13.5E3,:,A))', ADVANCE='NO') '      force [Fx, Fy, Fz]: [', &
          summaries(i)%fair_force(1), ', ', summaries(i)%fair_force(2), ', ', summaries(i)%fair_force(3), '] N'
      ELSE
        WRITE (error_unit, '(A,3(ES13.5E3,:,A))', ADVANCE='NO') '      axial force component [Fx, Fy, Fz]: [', &
          summaries(i)%fair_force(1), ', ', summaries(i)%fair_force(2), ', ', summaries(i)%fair_force(3), '] N'
      END IF
      WRITE (error_unit, '(A,F9.3,A)') ', inclination=', f_incl, ' deg'
      WRITE (error_unit, '(A,F9.3,A,F9.3,A,F9.3,A)') '      line tangent: inclination=', &
        summaries(i)%fair_inclination, ' deg, declination=', summaries(i)%fair_declination, &
        ' deg, azimuth=', summaries(i)%fair_azimuth, ' deg'
    END DO
    WRITE (error_unit, '(A)') '  CableDyn initialization completed.'
  END SUBROUTINE print_deck_init_report

  ! -------------------------------------------------------------------------- !
  ! Range graphs (LINES flag r) and touchdown channels (TDP<L>...). A route     !
  ! samples a line into its CD_RangeLine scratch with the SAME evaluators its   !
  ! Ten / Curv / BendMom / L<L>N<J>Dec channels use, so every envelope is built  !
  ! from the channel values themselves; CableDyn_RangeOutput adds the seabed     !
  ! clearance, accumulates the envelopes and locates the touchdown point.        !
  ! -------------------------------------------------------------------------- !

  SUBROUTINE range_status(es, em, ErrStat, ErrMsg)
    !! Map a CableDyn_RangeOutput status onto the deck-driver status space.
    INTEGER, INTENT(IN) :: es
    CHARACTER(*), INTENT(IN) :: em
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (es == CD_RANGE_OK) RETURN
    ErrStat = CD_DECKDRV_SOLVEFAIL
    IF (es == CD_RANGE_BADINPUT) ErrStat = CD_DECKDRV_BADINPUT
    ErrMsg = 'CableDyn_DeckDriver: '//TRIM(em)
  END SUBROUTINE range_status

  SUBROUTINE range_setup(rset, lines, channels, opts, nnodes, by_id, ErrStat, ErrMsg, bathymetry)
    !! Size the range set of a run from the LINES flag r and the TDP<L> channels. by_id:
    !! rset%lines(k) is deck line id k (the aggregate line map) and nnodes is indexed by
    !! id; otherwise rset%lines(i) is lines(i) and nnodes follows the deck line order.
    TYPE(CD_RangeSet), INTENT(INOUT) :: rset
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    CHARACTER(*), INTENT(IN) :: channels(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    INTEGER, INTENT(IN) :: nnodes(:)
    LOGICAL, INTENT(IN) :: by_id
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    INTEGER, ALLOCATABLE :: ids(:)
    LOGICAL, ALLOCATABLE :: want_r(:), want_t(:)
    INTEGER :: i, k, n, line_id, comp, es
    CHARACTER(512) :: em

    n = SIZE(nnodes)
    ALLOCATE (ids(n), want_r(n), want_t(n))
    want_r = .FALSE.
    want_t = .FALSE.
    DO k = 1, n
      ids(k) = k
      IF (.NOT. by_id .AND. k <= SIZE(lines)) ids(k) = lines(k)%id
    END DO
    DO i = 1, SIZE(lines)
      k = i
      IF (by_id) k = lines(i)%id
      IF (k < 1 .OR. k > n) CYCLE
      want_r(k) = line_output_has_flag(lines(i)%outputs, 'r')
    END DO
    DO i = 1, SIZE(channels)
      IF (.NOT. CD_Is_TDP_Channel(to_lower(channels(i)))) CYCLE
      CALL CD_Parse_TDP_Channel(channels(i), line_id, comp)
      k = line_id
      IF (.NOT. by_id) k = find_line(lines, line_id)
      IF (k >= 1 .AND. k <= n) want_t(k) = .TRUE.
    END DO
    CALL CD_Range_Setup(rset, ids, nnodes, want_r, want_t, opts%range_start, opts%has_wtrdpth, -opts%wtrdpth, &
                        es, em, bathymetry=bathymetry)
    CALL range_status(es, em, ErrStat, ErrMsg)
    IF (ErrStat /= CD_DECKDRV_OK .OR. .NOT. ALLOCATED(rset%lines)) RETURN
    ! a line with condensed torsion adds its torque and twist envelopes
    DO i = 1, SIZE(lines)
      k = i
      IF (by_id) k = lines(i)%id
      IF (k >= 1 .AND. k <= SIZE(rset%lines)) rset%lines(k)%has_torsion = line_torsion_active(lines(i))
    END DO
  END SUBROUTINE range_setup

  SUBROUTINE range_setup_planned(rset, lines, channels, opts, ErrStat, ErrMsg, models, fmodels, system, cables, &
                                 bathymetry)
    !! Range set of a standalone route, in deck line order, sized from the built line
    !! objects (exactly one of models, fmodels, system, cables is present).
    TYPE(CD_RangeSet), INTENT(INOUT) :: rset
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    CHARACTER(*), INTENT(IN) :: channels(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_ModelType), INTENT(IN), OPTIONAL :: models(:)
    TYPE(FiniteDeckModel), INTENT(IN), OPTIONAL :: fmodels(:)
    TYPE(CD_SystemType), INTENT(IN), OPTIONAL :: system
    TYPE(CD_HFMF_ModuleType), INTENT(IN), OPTIONAL :: cables(:)
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    INTEGER :: nnodes(SIZE(lines)), il, es
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    nnodes = 0
    DO il = 1, SIZE(lines)
      es = 0
      IF (PRESENT(models)) THEN
        nnodes(il) = CD_Model_NDOF(models(il), es, em)/3
      ELSE IF (PRESENT(fmodels)) THEN
        nnodes(il) = fmodels(il)%n_elem + 1
      ELSE IF (PRESENT(system)) THEN
        nnodes(il) = CD_System_Line_NDOF(system, il, es, em)/3
      ELSE IF (PRESENT(cables)) THEN
        nnodes(il) = cables(il)%line%nn
      END IF
      IF (es /= 0) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'range-graph setup: '//TRIM(em)); RETURN
      END IF
    END DO
    CALL range_setup(rset, lines, channels, opts, nnodes, .FALSE., ErrStat, ErrMsg, bathymetry)
  END SUBROUTINE range_setup_planned

  SUBROUTINE range_write(rset, out_root, ErrStat, ErrMsg)
    !! Write the range files of a completed run.
    TYPE(CD_RangeSet), INTENT(IN) :: rset
    CHARACTER(*), INTENT(IN) :: out_root
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: es
    CHARACTER(512) :: em
    CALL CD_Range_Write_Files(rset, out_root, es, em)
    CALL range_status(es, em, ErrStat, ErrMsg)
  END SUBROUTINE range_write

  SUBROUTINE range_positions(rl, stride)
    !! Public-order node positions from rl%qs (INTERNAL order, `stride` reals per node).
    TYPE(CD_RangeLine), INTENT(INOUT) :: rl
    INTEGER, INTENT(IN) :: stride
    INTEGER :: j, nn, base
    nn = rl%nn
    DO j = 1, nn
      base = stride*(nn - j)
      rl%r(:, j) = rl%qs(base + 1:base + 3)
    END DO
  END SUBROUTINE range_positions

  SUBROUTINE range_fill_ei0(rl, stride)
    !! Node values of an EI=0-style line from rl%qs (positions in INTERNAL order anchor ->
    !! fairlead, `stride` reals per node) and rl%ten_e (element tensions, internal order):
    !! the Ten channel's segment tension, Menger curvature, zero bend moment and declination.
    TYPE(CD_RangeLine), INTENT(INOUT) :: rl
    INTEGER, INTENT(IN) :: stride
    INTEGER :: j, nn

    nn = rl%nn
    CALL range_positions(rl, stride)
    DO j = 1, nn
      rl%val(CD_RQ_TENSION, j) = nodal_tension_value(rl%ten_e(1:nn - 1), deck_to_internal_node(j, nn - 1))
      rl%val(CD_RQ_CURVATURE, j) = line_geom_from_r(5, rl%r, nn, j)
      rl%val(CD_RQ_BEND, j) = CD_ZERO
      rl%val(CD_RQ_DECLINATION, j) = line_geom_from_r(7, rl%r, nn, j)
    END DO
  END SUBROUTINE range_fill_ei0

  SUBROUTINE range_sample_model(model, rl, ErrStat, ErrMsg)
    !! Sample an EI=0 line model; an end node reports the FairTen/AnchTen end force.
    TYPE(CD_ModelType), INTENT(IN) :: model
    TYPE(CD_RangeLine), INTENT(INOUT) :: rl
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: nn, es
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    nn = rl%nn
    CALL CD_Get_Model_State(model, rl%qs(1:3*nn), rl%vs(1:3*nn), rl%as(1:3*nn), es, em)
    IF (es == CD_MODEL_OK .AND. .NOT. rl%want_range) THEN
      CALL range_positions(rl, 3)   ! a touchdown-only line needs the positions alone
      RETURN
    END IF
    IF (es == CD_MODEL_OK) CALL CD_Get_Model_Tension(model, rl%ten_e(1:nn - 1), es, em)
    IF (es /= CD_MODEL_OK) THEN
      CALL fail_solve(ErrStat, ErrMsg, 'range-graph sample of line '//TRIM(int_to_str(rl%line_id))//' failed: '// &
                      TRIM(em)); RETURN
    END IF
    CALL range_fill_ei0(rl, 3)
    ! deck node 1 (End A) = internal node nn; deck node nn = internal node 1
    CALL line_model_end_tension(model, nn, nn, rl%val(CD_RQ_TENSION, 1), es, em)
    IF (es == CD_DECKDRV_OK) CALL line_model_end_tension(model, 1, nn, rl%val(CD_RQ_TENSION, nn), es, em)
    IF (es /= CD_DECKDRV_OK) THEN
      CALL fail_solve(ErrStat, ErrMsg, 'range-graph end-tension recovery failed: '//TRIM(em)); RETURN
    END IF
  END SUBROUTINE range_sample_model

  SUBROUTINE range_sample_arrays(q_line, ten_line, rl, end_ten)
    !! Sample a static EI=0 line from its solved arrays (internal order), with the end
    !! forces (anchor, fairlead) of the static Ten channel when present.
    REAL(wp), INTENT(IN) :: q_line(:), ten_line(:)
    TYPE(CD_RangeLine), INTENT(INOUT) :: rl
    REAL(wp), INTENT(IN), OPTIONAL :: end_ten(2)
    INTEGER :: nn

    nn = rl%nn
    rl%qs(1:3*nn) = q_line(1:3*nn)
    rl%ten_e(1:nn - 1) = ten_line(1:nn - 1)
    CALL range_fill_ei0(rl, 3)
    IF (PRESENT(end_ten)) THEN
      rl%val(CD_RQ_TENSION, nn) = end_ten(1)
      rl%val(CD_RQ_TENSION, 1) = end_ten(2)
    END IF
  END SUBROUTINE range_sample_arrays

  SUBROUTINE range_sample_fmodel(fmodel, rl, ErrStat, ErrMsg)
    !! Sample a finite-EI (two-moving-end route) line with the evaluators of
    !! finite_model_channel_value: chord-stretch element tension, geometric curvature and
    !! the reference-relative bend moment EI * |kappa - kappa_ref|.
    TYPE(FiniteDeckModel), INTENT(IN) :: fmodel
    TYPE(CD_RangeLine), INTENT(INOUT) :: rl
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: nn, ne, e, j, inode, es
    REAL(wp) :: xa(3), xb(3), length, kc(3), kr(3)
    CHARACTER(160) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    nn = rl%nn
    ne = nn - 1
    IF (fmodel%n_elem /= ne) THEN
      CALL fail_solve(ErrStat, ErrMsg, 'range-graph sample: finite-EI line size changed'); RETURN
    END IF
    CALL CD_Get_FiniteEI_Model_State(fmodel%model, rl%qs(1:6*nn), rl%vs(1:6*nn), rl%as(1:6*nn), es, em)
    IF (es /= 0) THEN
      CALL fail_solve(ErrStat, ErrMsg, 'range-graph sample of line '//TRIM(int_to_str(rl%line_id))//' failed: '// &
                      TRIM(em)); RETURN
    END IF
    IF (.NOT. rl%want_range) THEN
      CALL range_positions(rl, 6)
      RETURN
    END IF
    DO e = 1, ne
      xa = rl%qs(6*e - 5:6*e - 3)
      xb = rl%qs(6*(e + 1) - 5:6*(e + 1) - 3)
      length = SQRT(DOT_PRODUCT(xb - xa, xb - xa))
      rl%ten_e(e) = fmodel%ea(e)*(length/fmodel%l0(e) - CD_ONE)
    END DO
    CALL range_fill_ei0(rl, 6)
    DO j = 1, nn
      ! the circumcircle of the reversed node triple is the same circle (bit for bit)
      inode = deck_to_internal_node(j, ne)
      kc = node_curvature_vector(rl%r, nn, j)
      kr = node_curvature_vector(fmodel%model%nodes_ref, nn, inode)
      rl%val(CD_RQ_BEND, j) = nodal_ei_value(fmodel%ei, inode)*NORM2(kc - kr)
    END DO
  END SUBROUTINE range_sample_fmodel

  SUBROUTINE range_sample_cable(cable, rl, ErrStat, ErrMsg)
    !! Sample a cubic-Hermite cable with the evaluators of eval_cable_channel: end-force
    !! tension at the ends and the length-weighted element-mean axial force inside, the
    !! larger one-sided exact curvature and EI * curvature traces, and the declination of
    !! the cable-local state; positions are rotated into the deck's global frame.
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cable
    TYPE(CD_RangeLine), INTENT(INOUT) :: rl
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: nn, ne, e, j, k, inode, es
    REAL(wp) :: curv, bend
    CHARACTER(200) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    nn = rl%nn
    ne = nn - 1
    IF (cable%line%nn /= nn .OR. cable%line%ne /= ne .OR. SIZE(cable%line%q) < 6*nn) THEN
      CALL fail_solve(ErrStat, ErrMsg, 'range-graph sample: cable state not available'); RETURN
    END IF
    DO j = 1, nn
      inode = nn + 1 - j
      rl%r(:, j) = cable%line%q(6*(inode - 1) + 1:6*(inode - 1) + 3)
    END DO
    IF (rl%want_range) THEN
      DO j = 1, nn
        rl%val(CD_RQ_DECLINATION, j) = line_geom_from_r(7, rl%r, nn, j)
      END DO
    END IF
    DO j = 1, nn
      inode = nn + 1 - j
      DO k = 1, 3
        rl%r(k, j) = cable_global_component(cable, cable%line%q(6*(inode - 1) + 1:6*(inode - 1) + 3), k)
      END DO
    END DO
    IF (.NOT. rl%want_range) RETURN   ! a touchdown-only line needs the positions alone
    ! element traces: mean axial force, curvature at xi = 0 (vs) and xi = 1 (as)
    DO e = 1, ne
      rl%ten_e(e) = cable_element_mean_tension(cable, e)
      CALL cable_element_curvature(cable, e, CD_ZERO, rl%vs(e), es, em)
      IF (es == CD_HCABLE_OK) CALL cable_element_curvature(cable, e, CD_ONE, rl%as(e), es, em)
      IF (es /= CD_HCABLE_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'range-graph curvature sample failed: '//TRIM(em)); RETURN
      END IF
    END DO
    DO j = 1, nn
      inode = nn + 1 - j
      IF (inode == 1 .OR. inode == nn) THEN
        CALL cable_end_tension(cable, inode, rl%val(CD_RQ_TENSION, j), ErrStat, ErrMsg)
        IF (ErrStat /= CD_DECKDRV_OK) RETURN
      ELSE
        rl%val(CD_RQ_TENSION, j) = (cable%line%l0(inode - 1)*rl%ten_e(inode - 1) + &
                                    cable%line%l0(inode)*rl%ten_e(inode))/ &
                                   (cable%line%l0(inode - 1) + cable%line%l0(inode))
      END IF
      curv = CD_ZERO
      bend = CD_ZERO
      IF (inode > 1) THEN
        curv = MAX(curv, rl%as(inode - 1))
        bend = MAX(bend, cable%line%EI(inode - 1)*rl%as(inode - 1))
      END IF
      IF (inode <= ne) THEN
        curv = MAX(curv, rl%vs(inode))
        bend = MAX(bend, cable%line%EI(inode)*rl%vs(inode))
      END IF
      rl%val(CD_RQ_CURVATURE, j) = curv
      rl%val(CD_RQ_BEND, j) = bend
    END DO
    IF (rl%has_torsion .AND. cable%line%torsion%active) THEN
      ! condensed torsion: the committed torque (uniform) and the cable's own twist from End A
      ! (public node 1, the last internal node), as the Torq<L>N<J> and Twist<L>N<J> channels
      rl%val(CD_RQ_TORQUE, :) = cable%line%torsion%torque
      rl%val(CD_RQ_TWIST, 1) = CD_ZERO
      DO j = 2, nn
        inode = nn + 1 - j
        rl%val(CD_RQ_TWIST, j) = rl%val(CD_RQ_TWIST, j - 1) + cable%line%torsion%torque* &
                                 cable%line%l0(inode)/cable%line%torsion%gj(inode)*45.0_wp/QUARTER_PI
      END DO
    END IF
  END SUBROUTINE range_sample_cable

  SUBROUTINE aggregate_line_positions(system, cables, line_is_cable, line_obj_index, line_id, r, ErrStat, ErrMsg)
    !! Global node positions r(3, nn) of deck line id line_id of an aggregate, End A -> End B.
    TYPE(CD_SystemType), INTENT(IN) :: system
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cables(:)
    LOGICAL, INTENT(IN) :: line_is_cable(:)
    INTEGER, INTENT(IN) :: line_obj_index(:)
    INTEGER, INTENT(IN) :: line_id
    REAL(wp), INTENT(OUT) :: r(:, :)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: nn, j, k, inode, obj, es
    CHARACTER(200) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    r = CD_ZERO
    nn = SIZE(r, 2)
    obj = line_obj_index(line_id)
    IF (line_is_cable(line_id)) THEN
      IF (obj < 1 .OR. obj > SIZE(cables)) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'touchdown sample: cable index out of range'); RETURN
      END IF
      IF (cables(obj)%line%nn /= nn) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'touchdown sample: cable size changed'); RETURN
      END IF
      DO j = 1, nn
        inode = nn + 1 - j
        DO k = 1, 3
          r(k, j) = cable_global_component(cables(obj), cables(obj)%line%q(6*(inode - 1) + 1:6*(inode - 1) + 3), k)
        END DO
      END DO
    ELSE
      BLOCK
        REAL(wp) :: q(3*nn), v(3*nn), a(3*nn)
        CALL CD_Get_System_Line_State(system, obj, q, v, a, es, em)
        IF (es /= CD_SYSTEM_OK) THEN
          CALL fail_solve(ErrStat, ErrMsg, 'touchdown sample: '//TRIM(em)); RETURN
        END IF
        DO j = 1, nn
          r(:, j) = q(3*(nn - j) + 1:3*(nn - j) + 3)
        END DO
      END BLOCK
    END IF
  END SUBROUTINE aggregate_line_positions

  SUBROUTINE range_setup_aggregate(rset, lines, channels, opts, has_sys, system, cables, line_is_cable, &
                                   line_obj_index, ErrStat, ErrMsg, bathymetry)
    !! Range set of an aggregate (EI=0 system + Hermite cables), keyed by deck line id, with
    !! the touchdown references fixed at the current (initial) state.
    TYPE(CD_RangeSet), INTENT(INOUT) :: rset
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    CHARACTER(*), INTENT(IN) :: channels(:)
    TYPE(DeckOptions), INTENT(IN) :: opts
    LOGICAL, INTENT(IN) :: has_sys
    TYPE(CD_SystemType), INTENT(IN) :: system
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cables(:)
    LOGICAL, INTENT(IN) :: line_is_cable(:)
    INTEGER, INTENT(IN) :: line_obj_index(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(CD_BathymetryType), INTENT(IN), OPTIONAL :: bathymetry
    INTEGER, ALLOCATABLE :: nnodes(:)
    INTEGER :: k, obj, es
    CHARACTER(512) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    ALLOCATE (nnodes(SIZE(line_obj_index)))
    nnodes = 0
    DO k = 1, SIZE(line_obj_index)
      obj = line_obj_index(k)
      IF (obj < 1) CYCLE
      IF (line_is_cable(k)) THEN
        IF (obj <= SIZE(cables)) nnodes(k) = cables(obj)%line%nn
      ELSE IF (has_sys) THEN
        nnodes(k) = CD_System_Line_NDOF(system, obj, es, em)/3
        IF (es /= CD_SYSTEM_OK) THEN
          CALL fail_solve(ErrStat, ErrMsg, 'range-graph setup: '//TRIM(em)); RETURN
        END IF
      END IF
    END DO
    CALL range_setup(rset, lines, channels, opts, nnodes, .TRUE., ErrStat, ErrMsg, bathymetry)
    IF (ErrStat /= CD_DECKDRV_OK .OR. .NOT. rset%active) RETURN
    DO k = 1, SIZE(rset%lines)
      IF (.NOT. rset%lines(k)%want_tdp) CYCLE
      CALL aggregate_line_positions(system, cables, line_is_cable, line_obj_index, k, rset%lines(k)%r, &
                                    ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL CD_Range_Clearance(rset, rset%lines(k)%r, rset%lines(k)%val(CD_RQ_CLEARANCE, :), es, em)
      IF (es == CD_RANGE_OK) CALL CD_Range_TDP_Reference(rset%lines(k), rset%lines(k)%r, &
                                                         rset%lines(k)%val(CD_RQ_CLEARANCE, :), es, em)
      CALL range_status(es, em, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END DO
  END SUBROUTINE range_setup_aggregate

  SUBROUTINE CD_Deck_Range_Sample_Aggregate(rset, has_sys, system, cables, line_is_cable, line_obj_index, time, &
                                            ErrStat, ErrMsg)
    !! Sample every line of an aggregate range set at a committed output time.
    TYPE(CD_RangeSet), INTENT(INOUT) :: rset
    LOGICAL, INTENT(IN) :: has_sys
    TYPE(CD_SystemType), INTENT(IN) :: system
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cables(:)
    LOGICAL, INTENT(IN) :: line_is_cable(:)
    INTEGER, INTENT(IN) :: line_obj_index(:)
    REAL(wp), INTENT(IN) :: time
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: k, obj, es
    CHARACTER(512) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (.NOT. rset%active) RETURN
    DO k = 1, SIZE(rset%lines)
      IF (.NOT. CD_Range_Needs_Sample(rset, k)) CYCLE
      obj = line_obj_index(k)
      IF (line_is_cable(k)) THEN
        CALL range_sample_cable(cables(obj), rset%lines(k), ErrStat, ErrMsg)
      ELSE IF (has_sys) THEN
        CALL range_sample_model(system%lines(obj), rset%lines(k), ErrStat, ErrMsg)
      ELSE
        CALL fail_solve(ErrStat, ErrMsg, 'range-graph sample: line maps to no system')
      END IF
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL CD_Range_Commit_Sample(rset, k, time, es, em)
      CALL range_status(es, em, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
    END DO
  END SUBROUTINE CD_Deck_Range_Sample_Aggregate

  SUBROUTINE CD_Deck_Range_Write(rset, out_root, ErrStat, ErrMsg)
    !! Write <out_root>.Line<L>.range.out for the lines of a range set.
    TYPE(CD_RangeSet), INTENT(IN) :: rset
    CHARACTER(*), INTENT(IN) :: out_root
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    CALL range_write(rset, out_root, ErrStat, ErrMsg)
  END SUBROUTINE CD_Deck_Range_Write

  SUBROUTINE aggregate_tdp_value(ch, system, cables, line_is_cable, line_obj_index, ranges, val, ErrStat, ErrMsg)
    !! TDP<L> channel of an aggregate from the current node positions and the reference
    !! fixed at initialization.
    CHARACTER(*), INTENT(IN) :: ch
    TYPE(CD_SystemType), INTENT(IN) :: system
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cables(:)
    LOGICAL, INTENT(IN) :: line_is_cable(:)
    INTEGER, INTENT(IN) :: line_obj_index(:)
    TYPE(CD_RangeSet), INTENT(IN) :: ranges
    REAL(wp), INTENT(OUT) :: val
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: line_id, comp, nn, es
    CHARACTER(512) :: em

    val = CD_ZERO
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    CALL CD_Parse_TDP_Channel(ch, line_id, comp)
    IF (line_id < 1 .OR. line_id > SIZE(line_obj_index) .OR. comp < 1) THEN
      CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": unresolved touchdown channel'); RETURN
    END IF
    IF (.NOT. CD_Range_Needs_Sample(ranges, line_id)) THEN
      CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": no touchdown reference for that line'); RETURN
    END IF
    IF (.NOT. ranges%lines(line_id)%tdp_ready) THEN
      CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": no touchdown reference for that line'); RETURN
    END IF
    nn = ranges%lines(line_id)%nn
    BLOCK
      REAL(wp) :: r(3, nn), clearance(nn), tdp(CD_TDP_N)
      CALL aggregate_line_positions(system, cables, line_is_cable, line_obj_index, line_id, r, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL CD_Range_Clearance(ranges, r, clearance, es, em)
      CALL range_status(es, em, ErrStat, ErrMsg)
      IF (ErrStat /= CD_DECKDRV_OK) RETURN
      CALL CD_Range_TDP_Evaluate(ranges%lines(line_id), r, clearance, tdp)
      val = tdp(comp)
    END BLOCK
  END SUBROUTINE aggregate_tdp_value

  ! -------------------------------------------------------------------------- !
  ! OpenFAST CompMooring=5 output-channel evaluation. The OpenFAST shell holds  !
  ! only the built aggregate (an EI=0 mooring system + N finite-EI cables) plus !
  ! the deck-line-id -> object map; it resolves each deck OUTPUTS token to a     !
  ! value through CD_Eval_Aggregate_Channel, which delegates to the SAME private !
  ! evaluators the standalone .out writers use. So a coupled run and a driver    !
  ! run report identical channel values on a shared configuration.              !
  ! -------------------------------------------------------------------------- !

  SUBROUTINE CD_Eval_Aggregate_Channel(ch, has_sys, system, cables, line_is_cable, line_obj_index, val, ErrStat, &
                                       ErrMsg, cable_points, rigid_rt, rod_rt, ranges)
    !! Evaluate ONE deck OUTPUTS channel token against a built aggregate. The token's deck line
    !! id is resolved through the map to either an EI=0 system line (eval_system_line_channel) or
    !! a finite-EI cable (eval_cable_channel); Point<P> channels read the EI=0 system point state.
    !! The channel is assumed already validated (parse_deck -> check_channel); an internally
    !! inconsistent token or a failed state query still fails closed here.
    CHARACTER(*), INTENT(IN) :: ch
    LOGICAL, INTENT(IN) :: has_sys
    TYPE(CD_SystemType), INTENT(IN) :: system
    ! ALLOCATABLE so a pure-mooring deck that declares channels (ncable = 0, cables unallocated)
    ! can pass its cables store: only a channel resolving to a cable dereferences it.
    TYPE(CD_HFMF_ModuleType), ALLOCATABLE, INTENT(IN) :: cables(:)
    LOGICAL, INTENT(IN) :: line_is_cable(:)
    INTEGER, INTENT(IN) :: line_obj_index(:)
    REAL(wp), INTENT(OUT) :: val
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    ! Point<P>F channels: the deck point ids of each cable's End A and End B (cable_points(:, c));
    ! absent, only the EI=0 lines' end forces are summed
    INTEGER, INTENT(IN), OPTIONAL :: cable_points(:, :)
    ! Body<N>/Rod<N> channels: the coupled Rigid6 bodies or rods the aggregate marches
    TYPE(CD_Rigid6RuntimeType), INTENT(IN), OPTIONAL :: rigid_rt
    TYPE(CD_RodRuntimeType), INTENT(IN), OPTIONAL :: rod_rt
    ! TDP<L> channels: the touchdown references fixed at initialization
    TYPE(CD_RangeSet), INTENT(IN), OPTIONAL :: ranges

    CHARACTER(NAMELEN) :: lo
    LOGICAL :: found
    INTEGER :: line_id, node, kind, comp, pidx, es, k, c
    REAL(wp) :: qp(3), vp(3), ap(3), f(3), f_first(3), f_last(3), fl(3)
    CHARACTER(200) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    val = CD_ZERO
    lo = to_lower(ch)

    ! Body<N>/Rod<N>: the coupled body or rod state and loads. The loads are evaluated with
    ! time = 0: the coupled runtimes carry no time-dependent deck field (CD_Init_Deck_Aggregate
    ! rejects deck waves and, for Rigid6/ROD decks, a deck current; the host field is held).
    IF (is_object_channel(lo)) THEN
      found = .FALSE.
      IF (PRESENT(rigid_rt)) THEN
        IF (ALLOCATED(rigid_rt%rigid)) THEN
          IF (has_sys) THEN
            CALL object_channel_value(ch, val, found, rigid_rt%rigid, points=rigid_rt%points, opts=rigid_rt%opts, &
                                      time=CD_ZERO, system=system, ErrStat=ErrStat, ErrMsg=ErrMsg)
          ELSE
            CALL object_channel_value(ch, val, found, rigid_rt%rigid, points=rigid_rt%points, opts=rigid_rt%opts, &
                                      time=CD_ZERO, ErrStat=ErrStat, ErrMsg=ErrMsg)
          END IF
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
        END IF
      END IF
      IF (.NOT. found .AND. PRESENT(rod_rt)) THEN
        IF (ALLOCATED(rod_rt%rods)) THEN
          IF (has_sys) THEN
            CALL object_channel_value(ch, val, found, rods=rod_rt%rods, points=rod_rt%points, opts=rod_rt%opts, &
                                      time=CD_ZERO, system=system, ErrStat=ErrStat, ErrMsg=ErrMsg)
          ELSE
            CALL object_channel_value(ch, val, found, rods=rod_rt%rods, points=rod_rt%points, opts=rod_rt%opts, &
                                      time=CD_ZERO, ErrStat=ErrStat, ErrMsg=ErrMsg)
          END IF
          IF (ErrStat /= CD_DECKDRV_OK) RETURN
        END IF
      END IF
      IF (.NOT. found) CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": the coupled aggregate has no state '// &
                                 'for that body or rod')
      RETURN
    END IF

    ! Point<P>F{x,y,z,H}: the resultant of the forces the attached lines and cables exert on P.
    IF (is_point_force_channel(lo)) THEN
      CALL parse_point_force_channel(ch, pidx, comp)
      f = CD_ZERO
      IF (has_sys .AND. ALLOCATED(system%bindings)) THEN
        DO k = 1, SIZE(system%bindings)
          IF (system%bindings(k)%point_id /= pidx) CYCLE
          CALL CD_Get_Model_EndForces(system%lines(system%bindings(k)%line_index), f_first, f_last, es, em)
          IF (es /= CD_MODEL_OK) THEN
            ErrStat = CD_DECKDRV_SOLVEFAIL
            ErrMsg = 'CableDyn_DeckDriver: OUTPUT "'//TRIM(ch)//'": '//TRIM(em)
            RETURN
          END IF
          IF (system%bindings(k)%line_end == CD_LINE_END_A) THEN
            f = f + f_first
          ELSE
            f = f + f_last
          END IF
        END DO
      END IF
      IF (PRESENT(cable_points) .AND. ALLOCATED(cables)) THEN
        DO c = 1, MIN(SIZE(cable_points, 2), SIZE(cables))
          DO k = 1, 2
            IF (cable_points(k, c) /= pidx) CYCLE
            ! End A is the cable's last (driven) node, End B its first (held) node
            CALL CD_HermiteCable_Dyn_End_Force(cables(c)%line, MERGE(cables(c)%line%nn, 1, k == 1), fl, es, em)
            IF (es /= CD_HCDYN_OK) THEN
              ErrStat = CD_DECKDRV_SOLVEFAIL
              ErrMsg = 'CableDyn_DeckDriver: OUTPUT "'//TRIM(ch)//'": '//TRIM(em)
              RETURN
            END IF
            f = f + [cable_global_component(cables(c), fl, 1), cable_global_component(cables(c), fl, 2), &
                     cable_global_component(cables(c), fl, 3)]
          END DO
        END DO
      END IF
      IF (comp == 4) THEN
        val = SQRT(f(1)**2 + f(2)**2)
      ELSE
        val = f(comp)
      END IF
      RETURN
    END IF

    ! TDP<L>{s,x,y,z,Lay,Exc}: the touchdown point of the current configuration.
    IF (CD_Is_TDP_Channel(lo)) THEN
      IF (.NOT. PRESENT(ranges)) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": touchdown channels are not available here'); RETURN
      END IF
      IF (ALLOCATED(cables)) THEN
        CALL aggregate_tdp_value(ch, system, cables, line_is_cable, line_obj_index, ranges, val, ErrStat, ErrMsg)
      ELSE
        BLOCK
          TYPE(CD_HFMF_ModuleType) :: no_cables(0)
          CALL aggregate_tdp_value(ch, system, no_cables, line_is_cable, line_obj_index, ranges, val, ErrStat, &
                                   ErrMsg)
        END BLOCK
      END IF
      RETURN
    END IF

    ! Point<P>p{x,y,z}: an EI=0 system point's current position.
    IF (is_point_channel(lo)) THEN
      CALL parse_point_channel(ch, pidx, comp)
      IF (comp < 1 .OR. comp > 3) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": bad point component'); RETURN
      END IF
      IF (.NOT. has_sys) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": Point channels need an EI=0 mooring system '// &
                  '(a cable-endpoint Point channel is not supported)'); RETURN
      END IF
      CALL CD_Get_System_Point_State(system, pidx, qp, vp, ap, es, em)
      IF (es /= CD_SYSTEM_OK) THEN
        ErrStat = CD_DECKDRV_SOLVEFAIL
        ErrMsg = 'CableDyn_DeckDriver: OUTPUT "'//TRIM(ch)//'": '//TRIM(em)
        RETURN
      END IF
      val = qp(comp)
      RETURN
    END IF

    ! Resolve the channel's deck line id; every other line-node token uses its own parser.
    IF (starts_with(lo, 'fairten') .OR. starts_with(lo, 'anchten')) THEN
      line_id = int_suffix(ch, 8)
    ELSE IF (is_endpoint_angle_channel(lo)) THEN
      line_id = endpoint_angle_line_id(ch)
    ELSE
      CALL parse_line_node_channel(ch, line_id, node, kind, comp)
    END IF
    IF (line_id < 1 .OR. line_id > SIZE(line_obj_index)) THEN
      CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": unresolved line id'); RETURN
    END IF
    IF (line_obj_index(line_id) < 1) THEN
      CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": line id maps to no built line'); RETURN
    END IF

    IF (line_is_cable(line_id)) THEN
      IF (.NOT. ALLOCATED(cables)) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": channel maps to a cable but none are built'); RETURN
      END IF
      IF (line_obj_index(line_id) > SIZE(cables)) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": cable index out of range'); RETURN
      END IF
      CALL eval_cable_channel(cables(line_obj_index(line_id)), ch, val, ErrStat, ErrMsg)
    ELSE
      IF (.NOT. has_sys) THEN
        CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": line maps to the EI=0 system but no system '// &
                  'is present'); RETURN
      END IF
      CALL eval_system_line_channel(system, line_obj_index(line_id), ch, val, ErrStat, ErrMsg)
    END IF
  END SUBROUTINE CD_Eval_Aggregate_Channel

  SUBROUTINE CD_Eval_Aggregate_Segment_Tensions(line_id, has_sys, system, cables, line_is_cable, line_obj_index, &
                                                tension, ErrStat, ErrMsg)
    !! Segment (element) tensions of deck line line_id in public order End A -> End B, the
    !! values the standalone driver writes to .Line<L>.t.out: the EI=0 element tensions of
    !! CD_Get_Model_Tension, or the Hermite element-midpoint axial tension of a finite-EI cable.
    !! tension must hold exactly the line's element count.
    INTEGER, INTENT(IN) :: line_id
    LOGICAL, INTENT(IN) :: has_sys
    TYPE(CD_SystemType), INTENT(IN) :: system
    TYPE(CD_HFMF_ModuleType), ALLOCATABLE, INTENT(IN) :: cables(:)
    LOGICAL, INTENT(IN) :: line_is_cable(:)
    INTEGER, INTENT(IN) :: line_obj_index(:)
    REAL(wp), INTENT(OUT) :: tension(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: obj, ne, seg, es
    CHARACTER(200) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    tension = CD_ZERO
    IF (line_id < 1 .OR. line_id > SIZE(line_obj_index)) THEN
      CALL fail(ErrStat, ErrMsg, 'segment tensions: unknown line id'); RETURN
    END IF
    obj = line_obj_index(line_id)
    IF (obj < 1) THEN
      CALL fail(ErrStat, ErrMsg, 'segment tensions: line id maps to no built line'); RETURN
    END IF
    IF (line_is_cable(line_id)) THEN
      IF (.NOT. ALLOCATED(cables)) THEN
        CALL fail(ErrStat, ErrMsg, 'segment tensions: line maps to a cable but none are built'); RETURN
      END IF
      IF (obj > SIZE(cables)) THEN
        CALL fail(ErrStat, ErrMsg, 'segment tensions: cable index out of range'); RETURN
      END IF
      ne = cables(obj)%line%ne
      IF (SIZE(tension) /= ne) THEN
        CALL fail(ErrStat, ErrMsg, 'segment tensions: output size does not match the element count'); RETURN
      END IF
      DO seg = 1, ne
        tension(seg) = cable_element_tension(cables(obj), ne - seg + 1)
      END DO
      RETURN
    END IF
    IF (.NOT. has_sys) THEN
      CALL fail(ErrStat, ErrMsg, 'segment tensions: line maps to the EI=0 system but no system is present'); RETURN
    END IF
    ne = CD_System_Line_NElem(system, obj, es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      CALL fail_solve(ErrStat, ErrMsg, 'segment tensions: '//TRIM(em)); RETURN
    END IF
    IF (SIZE(tension) /= ne) THEN
      CALL fail(ErrStat, ErrMsg, 'segment tensions: output size does not match the element count'); RETURN
    END IF
    BLOCK
      REAL(wp) :: internal(ne)
      CALL CD_Get_System_Line_Tension(system, obj, internal, es, em)
      IF (es /= CD_SYSTEM_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'segment tensions: '//TRIM(em)); RETURN
      END IF
      tension = internal(ne:1:-1)
    END BLOCK
  END SUBROUTINE CD_Eval_Aggregate_Segment_Tensions

  SUBROUTINE CD_Rigid6_Inventory(rt, body_ids, rod_ids, rod_nsegs)
    !! Deck ids of the Rigid6 bodies the runtime owns (runtime order), and of the rods fixed or
    !! pinned to them (body order, then attachment order) with their NumSegs: the objects the
    !! Body<N>/Rod<N> channels of CD_Eval_Aggregate_Channel resolve on this runtime.
    TYPE(CD_Rigid6RuntimeType), INTENT(IN) :: rt
    INTEGER, ALLOCATABLE, INTENT(OUT) :: body_ids(:), rod_ids(:), rod_nsegs(:)
    INTEGER :: ib, ir, n, nb

    nb = CD_Rigid6_NBodies(rt)
    ALLOCATE (body_ids(nb))
    n = 0
    DO ib = 1, nb
      body_ids(ib) = rt%rigid(ib)%body_id
      IF (ALLOCATED(rt%rigid(ib)%att_rods)) n = n + SIZE(rt%rigid(ib)%att_rods)
    END DO
    ALLOCATE (rod_ids(n), rod_nsegs(n))
    n = 0
    DO ib = 1, nb
      IF (.NOT. ALLOCATED(rt%rigid(ib)%att_rods)) CYCLE
      DO ir = 1, SIZE(rt%rigid(ib)%att_rods)
        n = n + 1
        rod_ids(n) = rt%rigid(ib)%att_rods(ir)%rod_id
        rod_nsegs(n) = MAX(1, rt%rigid(ib)%att_rods(ir)%nsegs)
      END DO
    END DO
  END SUBROUTINE CD_Rigid6_Inventory

  SUBROUTINE CD_Rod_Inventory(rt, rod_ids, rod_nsegs)
    !! Deck ids and NumSegs of the rods the rod runtime owns (runtime order).
    TYPE(CD_RodRuntimeType), INTENT(IN) :: rt
    INTEGER, ALLOCATABLE, INTENT(OUT) :: rod_ids(:), rod_nsegs(:)
    INTEGER :: ir, n

    n = CD_Rod_NRods(rt)
    ALLOCATE (rod_ids(n), rod_nsegs(n))
    DO ir = 1, n
      rod_ids(ir) = rt%rods(ir)%rod_id
      rod_nsegs(ir) = MAX(1, rt%rods(ir)%nsegs)
    END DO
  END SUBROUTINE CD_Rod_Inventory

  LOGICAL FUNCTION CD_Channel_Token_Parses(ch) RESULT(ok)
    !! Whether ch is a well-formed OUTPUTS token of a family CD_Eval_Aggregate_Channel
    !! evaluates (object ids and line/node ranges are checked by the evaluator itself). The
    !! in-process channel query of the C API admits caller tokens through this gate, since the
    !! evaluator otherwise relies on parse_deck having validated the deck's own OUTPUTS.
    CHARACTER(*), INTENT(IN) :: ch
    CHARACTER(NAMELEN) :: lo
    INTEGER :: line_id, node, kind, comp, pidx, oid
    LOGICAL :: is_body

    ok = .FALSE.
    IF (LEN_TRIM(ch) < 1 .OR. LEN_TRIM(ch) > NAMELEN) RETURN
    IF (VERIFY(TRIM(ch), 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789') /= 0) RETURN
    lo = to_lower(ch)
    IF (is_object_channel(lo)) THEN
      CALL parse_object_channel(ch, is_body, oid, node, kind)
      ok = kind > 0 .AND. oid > 0
    ELSE IF (is_point_force_channel(lo)) THEN
      CALL parse_point_force_channel(ch, pidx, comp)
      ok = pidx > 0 .AND. comp >= 1 .AND. comp <= 4
    ELSE IF (CD_Is_TDP_Channel(lo)) THEN
      CALL CD_Parse_TDP_Channel(ch, line_id, comp)
      ok = line_id > 0 .AND. comp >= 1
    ELSE IF (is_point_channel(lo)) THEN
      CALL parse_point_channel(ch, pidx, comp)
      ok = pidx > 0 .AND. comp >= 1 .AND. comp <= 3
    ELSE IF (starts_with(lo, 'fairten') .OR. starts_with(lo, 'anchten')) THEN
      ok = LEN_TRIM(lo) > 7
      IF (ok) ok = VERIFY(lo(8:LEN_TRIM(lo)), '0123456789') == 0
      IF (ok) ok = int_suffix(ch, 8) > 0
    ELSE IF (is_endpoint_angle_channel(lo)) THEN
      ok = endpoint_angle_line_id(ch) > 0
    ELSE
      CALL parse_line_node_channel(ch, line_id, node, kind, comp)
      ok = line_id > 0 .AND. node > 0 .AND. kind > 0
    END IF
  END FUNCTION CD_Channel_Token_Parses

  SUBROUTINE line_model_end_tension(model, inode, nnode, val, ErrStat, ErrMsg)
    !! Magnitude of the force an EI=0 line model exerts on the point holding its end node
    !! inode (1 or nnode, internal anchor -> fairlead order): the end element tension plus
    !! the end node's lumped external loads (CD_Get_Model_EndForces), the FairTen/AnchTen
    !! convention shared by the static, dynamic and coupled routes.
    TYPE(CD_ModelType), INTENT(IN) :: model
    INTEGER, INTENT(IN) :: inode, nnode
    REAL(wp), INTENT(OUT) :: val
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp) :: f_first(3), f_last(3)
    INTEGER :: es
    CHARACTER(160) :: em

    val = CD_ZERO
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    CALL CD_Get_Model_EndForces(model, f_first, f_last, es, em)
    IF (es /= CD_MODEL_OK) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = em
      RETURN
    END IF
    IF (inode == 1) THEN
      val = NORM2(f_first)
    ELSE IF (inode == nnode) THEN
      val = NORM2(f_last)
    END IF
  END SUBROUTINE line_model_end_tension

  SUBROUTINE eval_system_line_channel(system, li, ch, val, ErrStat, ErrMsg)
    !! Evaluate one channel for EI=0 system line `li` (internal system line index). Mirrors the
    !! standalone driver's system_channel_value but takes the resolved line index directly and
    !! uses stack-local buffers instead of a shared workspace. Deck runs End A (fairlead) -> End
    !! B (anchor); internal state runs anchor -> fairlead, so fairlead = internal last node.
    TYPE(CD_SystemType), INTENT(IN) :: system
    INTEGER, INTENT(IN) :: li
    CHARACTER(*), INTENT(IN) :: ch
    REAL(wp), INTENT(OUT) :: val
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    CHARACTER(NAMELEN) :: lo
    INTEGER :: line_id, node, kind, comp, ndof, nnode, ne, inode, es
    CHARACTER(200) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    val = CD_ZERO
    lo = to_lower(ch)
    IF (starts_with(lo, 'fairten') .OR. starts_with(lo, 'anchten')) THEN
      ne = CD_System_Line_NElem(system, li, es, em)
      IF (es /= CD_SYSTEM_OK) THEN
        CALL sys_solvefail(ch, em, ErrStat, ErrMsg); RETURN
      END IF
      ! the force the line exerts on its end point (fairlead = internal last node)
      IF (starts_with(lo, 'fairten')) THEN
        CALL line_model_end_tension(system%lines(li), ne + 1, ne + 1, val, es, em)
      ELSE
        CALL line_model_end_tension(system%lines(li), 1, ne + 1, val, es, em)
      END IF
      IF (es /= CD_DECKDRV_OK) THEN
        CALL sys_solvefail(ch, em, ErrStat, ErrMsg); RETURN
      END IF
      RETURN
    END IF
    ndof = CD_System_Line_NDOF(system, li, es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      CALL sys_solvefail(ch, em, ErrStat, ErrMsg); RETURN
    END IF
    nnode = ndof/3
    IF (is_endpoint_angle_channel(lo)) THEN
      BLOCK
        REAL(wp) :: q(ndof), v(ndof), a(ndof)
        CALL CD_Get_System_Line_State(system, li, q, v, a, es, em)
        IF (es /= CD_SYSTEM_OK) THEN
          CALL sys_solvefail(ch, em, ErrStat, ErrMsg); RETURN
        END IF
        IF (is_fair_endpoint_angle(lo)) THEN
          val = line_geom_value(7, 1, nnode, q, 3)          ! End A declination [deg]
        ELSE
          val = line_geom_value(7, nnode, nnode, q, 3)      ! End B declination [deg]
        END IF
        val = endpoint_angle_from_declination(lo, val)
      END BLOCK
      RETURN
    END IF
    CALL parse_line_node_channel(ch, line_id, node, kind, comp)
    IF (node < 1 .OR. node > nnode) THEN
      CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": node index out of range'); RETURN
    END IF
    inode = deck_to_internal_node(node, nnode - 1)
    IF (kind == 3) THEN
      BLOCK
        REAL(wp) :: tension(nnode - 1)
        CALL CD_Get_System_Line_Tension(system, li, tension, es, em)
        IF (es /= CD_SYSTEM_OK) THEN
          CALL sys_solvefail(ch, em, ErrStat, ErrMsg); RETURN
        END IF
        val = nodal_tension_value(tension, inode)
        IF (inode == 1 .OR. inode == nnode) THEN
          CALL line_model_end_tension(system%lines(li), inode, nnode, val, es, em)
          IF (es /= CD_DECKDRV_OK) THEN
            CALL sys_solvefail(ch, em, ErrStat, ErrMsg); RETURN
          END IF
        END IF
      END BLOCK
      RETURN
    END IF
    BLOCK
      REAL(wp) :: q(ndof), v(ndof), a(ndof)
      CALL CD_Get_System_Line_State(system, li, q, v, a, es, em)
      IF (es /= CD_SYSTEM_OK) THEN
        CALL sys_solvefail(ch, em, ErrStat, ErrMsg); RETURN
      END IF
      SELECT CASE (kind)
      CASE (1)   ! position
        val = q(3*(inode - 1) + comp)
      CASE (2)   ! velocity
        val = v(3*(inode - 1) + comp)
      CASE (4)   ! acceleration
        val = a(3*(inode - 1) + comp)
      CASE DEFAULT   ! curvature (5) / bend moment (6, EI=0 => 0) / declination (7) / azimuth (8)
        val = line_geom_value(kind, node, nnode, q, 3)
      END SELECT
    END BLOCK
  END SUBROUTINE eval_system_line_channel

  SUBROUTINE sys_solvefail(ch, em, ErrStat, ErrMsg)
    !! Common system-accessor failure surface (a solve/query failure, not a bad token).
    CHARACTER(*), INTENT(IN) :: ch, em
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    ErrStat = CD_DECKDRV_SOLVEFAIL
    ErrMsg = 'CableDyn_DeckDriver: OUTPUT "'//TRIM(ch)//'": '//TRIM(em)
  END SUBROUTINE sys_solvefail

  SUBROUTINE eval_cable_channel(cable, ch, val, ErrStat, ErrMsg)
    !! Evaluate one channel for a finite-EI Hermite power cable (CD_HFMF). Mirrors the driver's
    !! finite_model_channel_value but reads the cable's committed state directly from the CD_HFMF
    !! line (stride-6 DOFs: r at 6*(n-1)+1..3, tangent m at +4..6) and recovers the
    !! complete elastic plus Kelvin-Voigt axial resultant. Node ordering runs anchor (node 1, held)
    !! -> fairlead (node nn, the coupled endpoint), so deck End A = internal node nn. Bend moment is
    !! EI(node) * |kvec_current - kvec_reference|; the built cable's reference is straight
    !! (kvec_reference = 0), so it reduces to EI * geometric curvature magnitude.
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cable
    CHARACTER(*), INTENT(IN) :: ch
    REAL(wp), INTENT(OUT) :: val
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    CHARACTER(NAMELEN) :: lo
    INTEGER :: line_id, node, kind, comp, nnode, nelem, inode, es
    CHARACTER(200) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    val = CD_ZERO
    lo = to_lower(ch)
    nelem = cable%line%ne
    nnode = cable%line%nn
    IF (nelem < 1 .OR. nnode /= nelem + 1 .OR. SIZE(cable%line%q) < 6*nnode) THEN
      CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": cable state not available'); RETURN
    END IF
    IF (starts_with(lo, 'fairten')) THEN
      CALL cable_end_tension(cable, nnode, val, ErrStat, ErrMsg)
      RETURN
    ELSE IF (starts_with(lo, 'anchten')) THEN
      CALL cable_end_tension(cable, 1, val, ErrStat, ErrMsg)
      RETURN
    ELSE IF (is_endpoint_angle_channel(lo)) THEN
      IF (is_fair_endpoint_angle(lo)) THEN
        val = line_geom_value(7, 1, nnode, cable%line%q(1:6*nnode), 6)
      ELSE
        val = line_geom_value(7, nnode, nnode, cable%line%q(1:6*nnode), 6)
      END IF
      val = endpoint_angle_from_declination(lo, val)
      RETURN
    END IF
    CALL parse_line_node_channel(ch, line_id, node, kind, comp)
    IF (node < 1 .OR. node > nnode) THEN
      CALL fail(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": node index out of range'); RETURN
    END IF
    inode = deck_to_internal_node(node, nelem)
    SELECT CASE (kind)
    CASE (3)   ! nodal tension
      BLOCK
        IF (inode == 1 .OR. inode == nnode) THEN
          ! a line end: the same support-reaction tension as FairTen/AnchTen
          CALL cable_end_tension(cable, inode, val, ErrStat, ErrMsg)
        ELSE
          ! Segment tension, as the EI=0 nodal channel: the length-weighted average of
          ! the two adjacent element-mean axial forces. The pointwise resultant at the
          ! node is not reported: with a stiff EA it oscillates about the element mean
          ! wherever an element cannot follow the line (a nodal seabed-contact kink, a
          ! section junction), by up to several times the line tension at any mesh.
          val = (cable%line%l0(inode - 1)*cable_element_mean_tension(cable, inode - 1) + &
                 cable%line%l0(inode)*cable_element_mean_tension(cable, inode))/ &
                (cable%line%l0(inode - 1) + cable%line%l0(inode))
        END IF
      END BLOCK
    CASE (1)   ! position (cable-local state rotated to the deck's global frame)
      val = cable_global_component(cable, cable%line%q(6*(inode - 1) + 1:6*(inode - 1) + 3), comp)
    CASE (2)   ! velocity
      val = cable_global_component(cable, cable%line%v(6*(inode - 1) + 1:6*(inode - 1) + 3), comp)
    CASE (4)   ! acceleration
      val = cable_global_component(cable, cable%line%a(6*(inode - 1) + 1:6*(inode - 1) + 3), comp)
    CASE (5)   ! exact Hermite curvature, retaining the larger interface trace
      CALL cable_nodal_curvature(cable, inode, val, es, em)
      IF (es /= CD_HCABLE_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": '//TRIM(em)); RETURN
      END IF
    CASE (6)   ! exact |EI*kappa|, retaining the larger interface trace
      CALL cable_nodal_bend_moment(cable, inode, val, es, em)
      IF (es /= CD_HCABLE_OK) THEN
        CALL fail_solve(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": '//TRIM(em)); RETURN
      END IF
    CASE (9, 10, 11)   ! condensed torsion: torque [N m], twist from End A to node J, total twist [deg]
      BLOCK
        REAL(wp) :: th, mt
        INTEGER :: e
        CALL CD_HermiteCable_Dyn_Torsion_State(cable%line, th, mt, es, em)
        IF (es /= CD_HCDYN_OK) THEN
          CALL fail_solve(ErrStat, ErrMsg, 'OUTPUT "'//TRIM(ch)//'": '//TRIM(em)); RETURN
        END IF
        IF (kind == 9) THEN
          val = mt
        ELSE IF (kind == 11) THEN
          val = mt*CD_HermiteTorsion_Compliance(cable%line%torsion, cable%line%l0)*45.0_wp/QUARTER_PI
        ELSE IF (cable%line%torsion%active) THEN
          ! End A is the last internal node: the cable's own twist over the elements inode..ne
          val = CD_ZERO
          DO e = inode, nelem
            val = val + cable%line%l0(e)/cable%line%torsion%gj(e)
          END DO
          val = mt*val*45.0_wp/QUARTER_PI
        END IF
      END BLOCK
    CASE (8)   ! azimuth: local-frame azimuth plus the cable's frame heading, wrapped
      val = line_geom_value(kind, node, nnode, cable%line%q(1:6*nnode), 6)
      IF (.NOT. cable_frame_is_identity(cable)) THEN
        val = MODULO(val + ATAN2(cable%frame_s, cable%frame_c)*45.0_wp/QUARTER_PI, 360.0_wp)
      END IF
    CASE DEFAULT   ! declination (7) -- rotation-invariant geometric scalar
      val = line_geom_value(kind, node, nnode, cable%line%q(1:6*nnode), 6)
    END SELECT
  END SUBROUTINE eval_cable_channel

  PURE FUNCTION cable_frame_is_identity(cable) RESULT(is_id)
    !! Exact identity-heading test. Order comparisons preserve the bit-for-bit
    !! identity fast path without tripping -Wcompare-reals.
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cable
    LOGICAL :: is_id
    is_id = .NOT. (ABS(cable%frame_s) > CD_ZERO .OR. ABS(cable%frame_c - CD_ONE) > CD_ZERO)
  END FUNCTION cable_frame_is_identity

  PURE FUNCTION cable_global_component(cable, v_local, comp) RESULT(val)
    !! One component of a cable-local vector expressed in the deck's global frame (the
    !! transpose of the cable's frame rotation about +z). Identity heading reads the
    !! component straight through, bit-for-bit.
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cable
    REAL(wp), INTENT(IN) :: v_local(3)
    INTEGER, INTENT(IN) :: comp
    REAL(wp) :: val
    IF (cable_frame_is_identity(cable)) THEN
      val = v_local(comp)
    ELSE
      SELECT CASE (comp)
      CASE (1)
        val = cable%frame_c*v_local(1) - cable%frame_s*v_local(2)
      CASE (2)
        val = cable%frame_s*v_local(1) + cable%frame_c*v_local(2)
      CASE DEFAULT
        val = v_local(3)
      END SELECT
    END IF
  END FUNCTION cable_global_component

  REAL(wp) FUNCTION cable_element_tension(cable, e) RESULT(t)
    !! Axial tension at the material midpoint of Hermite element e (internal order).
    !! This evaluates the SAME strain measure used by CD_HermiteCable_Element,
    !! eps=|dr/ds|-1.  A chord-length diagnostic is invalid for a curved cubic element:
    !! it systematically reports compression when the arc is longer than its chord.
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cable
    INTEGER, INTENT(IN) :: e
    t = cable_axial_tension(cable, e, 0.5_wp)
  END FUNCTION cable_element_tension

  REAL(wp) FUNCTION cable_axial_tension(cable, e, xi) RESULT(t)
    !! Constitutive axial force at xi in [0,1].  Hermite tangent DOFs are dr/ds,
    !! while the public shape derivative is with respect to xi, hence division by L.
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cable
    INTEGER, INTENT(IN) :: e
    REAL(wp), INTENT(IN) :: xi
    REAL(wp) :: qr(12), vr(12), l0, viscous
    INTEGER :: es
    CHARACTER(160) :: em
    t = CD_ZERO
    IF (e < 1 .OR. e > cable%line%ne) RETURN
    l0 = cable%line%l0(e)
    IF (.NOT. (l0 > CD_ZERO)) RETURN
    qr(1:6) = cable%line%q(6*(e - 1) + 1:6*(e - 1) + 6)
    qr(7:12) = cable%line%q(6*e + 1:6*e + 6)
    CALL CD_HermiteCable_Axial_Resultant(qr, l0, cable%line%EA(e), xi, t, es, em)
    IF (es /= CD_HCABLE_OK) THEN
      t = CD_ZERO
      RETURN
    END IF
    IF (cable%line%has_axial_damping) THEN
      vr(1:6) = cable%line%v(6*(e - 1) + 1:6*(e - 1) + 6)
      vr(7:12) = cable%line%v(6*e + 1:6*e + 6)
      CALL CD_HermiteCable_Axial_Damping_Resultant(qr, vr, l0, cable%line%BA(e), xi, &
                                                   viscous, es, em)
      IF (es /= 0) THEN
        t = CD_ZERO
      ELSE
        t = t + viscous
      END IF
    END IF
  END FUNCTION cable_axial_tension

  REAL(wp) FUNCTION cable_element_mean_tension(cable, e) RESULT(t)
    !! Element-mean axial force of element e (elastic plus Kelvin-Voigt): the three-point
    !! Gauss mean of cable_axial_tension, the quantity the static branch audit uses.
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cable
    INTEGER, INTENT(IN) :: e
    REAL(wp), PARAMETER :: G3X(3) = [0.5_wp - 0.5_wp*SQRT(0.6_wp), 0.5_wp, 0.5_wp + 0.5_wp*SQRT(0.6_wp)]
    REAL(wp), PARAMETER :: G3W(3) = [5.0_wp/18.0_wp, 8.0_wp/18.0_wp, 5.0_wp/18.0_wp]
    INTEGER :: k
    t = CD_ZERO
    DO k = 1, 3
      t = t + G3W(k)*cable_axial_tension(cable, e, G3X(k))
    END DO
  END FUNCTION cable_element_mean_tension

  SUBROUTINE cable_end_tension(cable, inode, tension, ErrStat, ErrMsg)
    !! Line-end tension of a finite-EI Hermite cable (inode = 1 anchor, nn fairlead): the
    !! magnitude of the force the line exerts on its end point at rest
    !! (CD_HermiteCable_Dyn_End_Force) -- the end element's weak-form elastic force plus the
    !! end node's share of the submerged weight, dry-part buoyancy, seabed contact and
    !! ambient-fluid drag, the same end force the EI = 0 lines report. The static profile,
    !! the standalone dynamic march and the coupled facade all read it from the committed
    !! state, so a static-only run and a dynamic run at rest report the identical value. The
    !! constitutive stretch EA*(|dr/ds| - 1) sampled AT the end node is not used: with a stiff
    !! EA and elements long against the local curvature, the pointwise axial force of the
    !! discrete solution oscillates between Gauss stations and nodes, while the integrated
    !! nodal force is fixed by the equilibrium the solver enforces.
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cable
    INTEGER, INTENT(IN) :: inode
    REAL(wp), INTENT(OUT) :: tension
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp) :: force(3)
    INTEGER :: es
    CHARACTER(200) :: em

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    tension = CD_ZERO
    CALL CD_HermiteCable_Dyn_End_Force(cable%line, MERGE(1, cable%line%nn, inode == 1), force, es, em)
    IF (es /= CD_HCDYN_OK) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: finite-EI end-force recovery failed: '//TRIM(em)
      RETURN
    END IF
    tension = NORM2(force)
  END SUBROUTINE cable_end_tension

  SUBROUTINE cable_nodal_curvature(cable, inode, curvature, ErrStat, ErrMsg)
    !! Exact one-sided Hermite curvature traces at an internal line node.  Curvature
    !! need not be continuous across a material interface because the interpolation
    !! is C1, so the public nodal value conservatively retains the larger trace.
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cable
    INTEGER, INTENT(IN) :: inode
    REAL(wp), INTENT(OUT) :: curvature
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp) :: trace

    ErrStat = CD_HCABLE_OK
    ErrMsg = ''
    curvature = CD_ZERO
    IF (inode < 1 .OR. inode > cable%line%nn) THEN
      ErrStat = 1; ErrMsg = 'cable_nodal_curvature: node index out of range'; RETURN
    END IF
    IF (inode > 1) THEN
      CALL cable_element_curvature(cable, inode - 1, CD_ONE, trace, ErrStat, ErrMsg)
      IF (ErrStat /= CD_HCABLE_OK) RETURN
      curvature = MAX(curvature, trace)
    END IF
    IF (inode <= cable%line%ne) THEN
      CALL cable_element_curvature(cable, inode, CD_ZERO, trace, ErrStat, ErrMsg)
      IF (ErrStat /= CD_HCABLE_OK) RETURN
      curvature = MAX(curvature, trace)
    END IF
  END SUBROUTINE cable_nodal_curvature

  SUBROUTINE cable_nodal_bend_moment(cable, inode, bend_moment, ErrStat, ErrMsg)
    !! Magnitudes of the two one-sided EI*kappa traces at a node.  Taking their
    !! maximum avoids inventing an averaged EI at a stepped section interface.
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cable
    INTEGER, INTENT(IN) :: inode
    REAL(wp), INTENT(OUT) :: bend_moment
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp) :: curvature

    ErrStat = CD_HCABLE_OK
    ErrMsg = ''
    bend_moment = CD_ZERO
    IF (inode < 1 .OR. inode > cable%line%nn) THEN
      ErrStat = 1; ErrMsg = 'cable_nodal_bend_moment: node index out of range'; RETURN
    END IF
    IF (inode > 1) THEN
      CALL cable_element_curvature(cable, inode - 1, CD_ONE, curvature, ErrStat, ErrMsg)
      IF (ErrStat /= CD_HCABLE_OK) RETURN
      bend_moment = MAX(bend_moment, cable%line%EI(inode - 1)*curvature)
    END IF
    IF (inode <= cable%line%ne) THEN
      CALL cable_element_curvature(cable, inode, CD_ZERO, curvature, ErrStat, ErrMsg)
      IF (ErrStat /= CD_HCABLE_OK) RETURN
      bend_moment = MAX(bend_moment, cable%line%EI(inode)*curvature)
    END IF
  END SUBROUTINE cable_nodal_bend_moment

  SUBROUTINE cable_element_curvature(cable, e, xi, curvature, ErrStat, ErrMsg)
    TYPE(CD_HFMF_ModuleType), INTENT(IN) :: cable
    INTEGER, INTENT(IN) :: e
    REAL(wp), INTENT(IN) :: xi
    REAL(wp), INTENT(OUT) :: curvature
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    REAL(wp) :: qr(12)

    IF (e < 1 .OR. e > cable%line%ne) THEN
      ErrStat = 1; ErrMsg = 'cable_element_curvature: element index out of range'; curvature = CD_ZERO; RETURN
    END IF
    qr(1:6) = cable%line%q(6*(e - 1) + 1:6*(e - 1) + 6)
    qr(7:12) = cable%line%q(6*e + 1:6*e + 6)
    CALL CD_HermiteCable_Curvature(qr, cable%line%l0(e), xi, curvature, ErrStat, ErrMsg)
  END SUBROUTINE cable_element_curvature

  FUNCTION CD_Channel_Unit(ch) RESULT(unit)
    !! OrcaFlex-vocabulary output unit for a channel token, by kind: tension (FairTen/AnchTen/Ten)
    !! -> (N); curvature (Curv) -> (1/m); bend moment (BendMom) -> (N.m); endpoint orientation/
    !! Dec/Azi -> (deg); position (Point/...p) -> (m); velocity (...v) -> (m/s);
    !! acceleration (...a) -> (m/s2).
    CHARACTER(*), INTENT(IN) :: ch
    CHARACTER(10) :: unit
    CHARACTER(NAMELEN) :: lo
    INTEGER :: line_id, node, kind, comp
    LOGICAL :: is_body
    lo = to_lower(ch)
    IF (is_object_channel(lo)) THEN
      CALL parse_object_channel(ch, is_body, line_id, node, kind)
      SELECT CASE (kind)
      CASE (1:3); unit = '(m)'
      CASE (4:6); unit = '(deg)'
      CASE (7:9); unit = '(m/s)'
      CASE (10:12); unit = '(deg/s)'
      CASE (13:15); unit = '(m/s2)'
      CASE (16:18); unit = '(deg/s2)'
      CASE (19:21, 25:26); unit = '(N)'
      CASE (22:24); unit = '(N.m)'
      CASE DEFAULT; unit = '(-)'
      END SELECT
    ELSE IF (starts_with(lo, 'fairten') .OR. starts_with(lo, 'anchten')) THEN
      unit = '(N)'
    ELSE IF (is_endpoint_angle_channel(lo)) THEN
      unit = '(deg)'
    ELSE IF (is_point_force_channel(lo)) THEN
      unit = '(N)'
    ELSE IF (is_point_channel(lo) .OR. CD_Is_TDP_Channel(lo)) THEN
      unit = '(m)'
    ELSE
      CALL parse_line_node_channel(ch, line_id, node, kind, comp)
      SELECT CASE (kind)
      CASE (3); unit = '(N)'
      CASE (5); unit = '(1/m)'
      CASE (6); unit = '(N.m)'
      CASE (7, 8); unit = '(deg)'
      CASE (1); unit = '(m)'
      CASE (2); unit = '(m/s)'
      CASE (4); unit = '(m/s2)'
      CASE DEFAULT; unit = '(-)'
      END SELECT
    END IF
  END FUNCTION CD_Channel_Unit

  ! --------------------------------------------------------------------------- !
  ! small helpers                                                               !
  ! --------------------------------------------------------------------------- !

  LOGICAL FUNCTION is_section_header(line, secname) RESULT(is_hdr)
    CHARACTER(*), INTENT(IN)  :: line
    CHARACTER(*), INTENT(OUT) :: secname
    CHARACTER(LEN(line)) :: s
    INTEGER :: i, n
    LOGICAL :: had_dash
    is_hdr = .FALSE.
    secname = ''
    had_dash = (INDEX(line, '---') > 0)
    n = 0; s = ''
    DO i = 1, LEN_TRIM(line)
      IF (line(i:i) == '-') CYCLE
      IF (is_space(line(i:i))) THEN
        IF (n > 0) THEN
          IF (s(n:n) /= ' ') THEN; n = n + 1; s(n:n) = ' '; END IF
        END IF
      ELSE
        n = n + 1; s(n:n) = up(line(i:i))
      END IF
    END DO
    IF (n > 0) THEN
      IF (s(n:n) == ' ') n = n - 1
    END IF
    IF (had_dash) THEN
      is_hdr = .TRUE.
      secname = s(1:n)
    END IF
  END FUNCTION is_section_header

  INTEGER FUNCTION find_type(types, name) RESULT(idx)
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    CHARACTER(*), INTENT(IN) :: name
    INTEGER :: i
    idx = 0
    DO i = 1, SIZE(types)
      IF (to_lower(TRIM(types(i)%name)) == to_lower(TRIM(name))) THEN; idx = i; RETURN; END IF
    END DO
  END FUNCTION find_type

  INTEGER FUNCTION find_point(points, id) RESULT(idx)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    INTEGER, INTENT(IN) :: id
    INTEGER :: i
    idx = 0
    DO i = 1, SIZE(points)
      IF (points(i)%id == id) THEN; idx = i; RETURN; END IF
    END DO
  END FUNCTION find_point

  INTEGER FUNCTION find_body(bodies, id) RESULT(idx)
    TYPE(DeckBody), INTENT(IN) :: bodies(:)
    INTEGER, INTENT(IN) :: id
    INTEGER :: i
    idx = 0
    DO i = 1, SIZE(bodies)
      IF (bodies(i)%id == id) THEN; idx = i; RETURN; END IF
    END DO
  END FUNCTION find_body

  INTEGER FUNCTION find_rod_type(rod_types, name) RESULT(idx)
    TYPE(DeckRodType), INTENT(IN) :: rod_types(:)
    CHARACTER(*), INTENT(IN) :: name
    INTEGER :: i
    idx = 0
    DO i = 1, SIZE(rod_types)
      IF (to_lower(TRIM(rod_types(i)%name)) == to_lower(TRIM(name))) THEN
        idx = i
        RETURN
      END IF
    END DO
  END FUNCTION find_rod_type

  INTEGER FUNCTION find_rod(rods, id) RESULT(idx)
    TYPE(DeckRod), INTENT(IN) :: rods(:)
    INTEGER, INTENT(IN) :: id
    INTEGER :: i
    idx = 0
    DO i = 1, SIZE(rods)
      IF (rods(i)%id == id) THEN
        idx = i
        RETURN
      END IF
    END DO
  END FUNCTION find_rod

  INTEGER FUNCTION count_body_point_refs(points, body_id) RESULT(n)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    INTEGER, INTENT(IN) :: body_id
    INTEGER :: i
    n = 0
    DO i = 1, SIZE(points)
      IF (starts_with(TRIM(points(i)%ptype), 'body')) THEN
        IF (int_suffix(TRIM(points(i)%ptype), 5) == body_id) n = n + 1
      END IF
    END DO
  END FUNCTION count_body_point_refs

  LOGICAL FUNCTION is_rod_point_type(ptype) RESULT(is_rod)
    CHARACTER(*), INTENT(IN) :: ptype
    INTEGER :: n, end_id
    CALL parse_rod_point_type(ptype, n, end_id)
    is_rod = (n > 0 .AND. (end_id == 1 .OR. end_id == 2))
  END FUNCTION is_rod_point_type

  SUBROUTINE parse_rod_point_type(ptype, rod_id, end_id)
    CHARACTER(*), INTENT(IN) :: ptype
    INTEGER, INTENT(OUT) :: rod_id, end_id
    CHARACTER(NAMELEN) :: s
    INTEGER :: i, c

    s = to_lower(TRIM(ptype))
    rod_id = 0
    end_id = 0
    IF (.NOT. starts_with(s, 'rod')) RETURN
    DO i = 4, LEN_TRIM(s)
      c = IACHAR(s(i:i))
      IF (c >= IACHAR('0') .AND. c <= IACHAR('9')) THEN
        ! a digit string beyond the default INTEGER range names no rod (never wraps)
        IF (rod_id > (HUGE(rod_id) - (c - IACHAR('0')))/10) THEN
          rod_id = 0
          RETURN
        END IF
        rod_id = rod_id*10 + (c - IACHAR('0'))
      ELSE
        IF (i == 4 .OR. rod_id < 1) THEN
          rod_id = 0
          RETURN
        END IF
        IF (i /= LEN_TRIM(s)) THEN
          rod_id = 0
          RETURN
        END IF
        IF (s(i:i) == 'a') THEN
          end_id = 1
        ELSE IF (s(i:i) == 'b') THEN
          end_id = 2
        ELSE
          rod_id = 0
        END IF
        RETURN
      END IF
    END DO
    rod_id = 0
  END SUBROUTINE parse_rod_point_type

  INTEGER FUNCTION count_rod_point_refs(points, rod_id, end_id) RESULT(n)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    INTEGER, INTENT(IN) :: rod_id, end_id
    INTEGER :: i, rid, eid

    n = 0
    DO i = 1, SIZE(points)
      CALL parse_rod_point_type(points(i)%ptype, rid, eid)
      IF (rid == rod_id .AND. eid == end_id) n = n + 1
    END DO
  END FUNCTION count_rod_point_refs

  INTEGER FUNCTION rod_point_index(points, rod_id, end_id) RESULT(idx)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    INTEGER, INTENT(IN) :: rod_id, end_id
    INTEGER :: i, rid, eid

    idx = 0
    DO i = 1, SIZE(points)
      CALL parse_rod_point_type(points(i)%ptype, rid, eid)
      IF (rid == rod_id .AND. eid == end_id) THEN
        idx = i
        RETURN
      END IF
    END DO
  END FUNCTION rod_point_index

  SUBROUTINE collect_body_point_indices(points, body_id, indices)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    INTEGER, INTENT(IN) :: body_id
    INTEGER, ALLOCATABLE, INTENT(OUT) :: indices(:)
    INTEGER :: i, n
    n = count_body_point_refs(points, body_id)
    ALLOCATE (indices(n))
    n = 0
    DO i = 1, SIZE(points)
      IF (points(i)%body_id == body_id) THEN
        n = n + 1
        indices(n) = i
      END IF
    END DO
  END SUBROUTINE collect_body_point_indices

  INTEGER FUNCTION find_line(lines, id) RESULT(idx)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    INTEGER, INTENT(IN) :: id
    INTEGER :: i
    idx = 0
    DO i = 1, SIZE(lines)
      IF (lines(i)%id == id) THEN; idx = i; RETURN; END IF
    END DO
  END FUNCTION find_line

  LOGICAL FUNCTION deck_has_finite_ei(types, sections) RESULT(has_finite)
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    INTEGER :: i
    has_finite = .FALSE.
    DO i = 1, SIZE(sections)
      IF (sections(i)%ltype >= 1 .AND. sections(i)%ltype <= SIZE(types)) THEN
        IF (types(sections(i)%ltype)%ei > CD_ZERO) THEN
          has_finite = .TRUE.
          RETURN
        END IF
      END IF
    END DO
  END FUNCTION deck_has_finite_ei

  LOGICAL FUNCTION deck_has_dynamic_points(points) RESULT(has_dynamic)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    INTEGER :: i
    has_dynamic = .FALSE.
    DO i = 1, SIZE(points)
      IF (points(i)%ptype == 'connect' .OR. points(i)%ptype == 'free' .OR. &
          starts_with(TRIM(points(i)%ptype), 'body')) THEN
        has_dynamic = .TRUE.
        RETURN
      END IF
      IF (is_rod_point_type(points(i)%ptype)) THEN
        has_dynamic = .TRUE.
        RETURN
      END IF
    END DO
  END FUNCTION deck_has_dynamic_points

  LOGICAL FUNCTION deck_has_rigid6_bodies(bodies) RESULT(has_rigid)
    TYPE(DeckBody), INTENT(IN) :: bodies(:)
    INTEGER :: i
    has_rigid = .FALSE.
    DO i = 1, SIZE(bodies)
      IF (TRIM(bodies(i)%btype) == 'rigid6') THEN
        has_rigid = .TRUE.
        RETURN
      END IF
    END DO
  END FUNCTION deck_has_rigid6_bodies

  LOGICAL FUNCTION deck_has_non_rigid6_dynamic_points(points, bodies) RESULT(has_other)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckBody), INTENT(IN) :: bodies(:)
    INTEGER :: i, ib
    has_other = .FALSE.
    DO i = 1, SIZE(points)
      SELECT CASE (points(i)%ptype)
      CASE ('connect', 'free')
        has_other = .TRUE.
        RETURN
      CASE DEFAULT
        IF (starts_with(TRIM(points(i)%ptype), 'body')) THEN
          ib = find_body(bodies, points(i)%body_id)
          IF (ib < 1 .OR. TRIM(bodies(ib)%btype) /= 'rigid6') THEN
            has_other = .TRUE.
            RETURN
          END IF
        END IF
      END SELECT
    END DO
  END FUNCTION deck_has_non_rigid6_dynamic_points

  LOGICAL FUNCTION deck_has_non_rod_dynamic_points(points) RESULT(has_other)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    INTEGER :: i
    has_other = .FALSE.
    DO i = 1, SIZE(points)
      IF (points(i)%ptype == 'connect' .OR. points(i)%ptype == 'free') THEN
        has_other = .TRUE.
        RETURN
      END IF
      IF (starts_with(TRIM(points(i)%ptype), 'body')) THEN
        has_other = .TRUE.
        RETURN
      END IF
    END DO
  END FUNCTION deck_has_non_rod_dynamic_points

  LOGICAL FUNCTION endpoint_type_supported_dynamic(ptype) RESULT(ok)
    CHARACTER(*), INTENT(IN) :: ptype
    ok = ptype == 'fixed' .OR. ptype == 'coupled' .OR. ptype == 'vessel' .OR. &
         ptype == 'connect' .OR. ptype == 'free' .OR. starts_with(TRIM(ptype), 'body')
    IF (.NOT. ok) ok = is_rod_point_type(ptype)
  END FUNCTION endpoint_type_supported_dynamic

  INTEGER FUNCTION deck_point_type_to_system(ptype) RESULT(point_type)
    CHARACTER(*), INTENT(IN) :: ptype
    SELECT CASE (ptype)
    CASE ('fixed')
      point_type = CD_POINT_FIXED
    CASE ('coupled', 'vessel')
      point_type = CD_POINT_COUPLED
    CASE ('free')
      point_type = CD_POINT_FREE
    CASE ('connect')
      point_type = CD_POINT_CONNECT
    CASE DEFAULT
      IF (starts_with(TRIM(ptype), 'body')) THEN
        point_type = CD_POINT_FREE
      ELSE IF (is_rod_point_type(ptype)) THEN
        point_type = CD_POINT_FREE
      ELSE
        point_type = CD_POINT_COUPLED
      END IF
    END SELECT
  END FUNCTION deck_point_type_to_system

  SUBROUTINE apply_ptfm_point(point, ptfm_init)
    !! Rigid-transform ONE deck point by an initial platform displacement about the
    !! origin: p' = r + M^T p (M = the ZYX 3-2-1 DCM) -- the per-point core of
    !! apply_ptfm_init, used per turbine in FAST.Farm mode.
    TYPE(DeckPoint), INTENT(INOUT) :: point
    REAL(wp), INTENT(IN) :: ptfm_init(6)
    REAL(wp) :: dcm(3, 3)
    dcm = ptfm_zyx_dcm(ptfm_init(4:6))
    point%pos = ptfm_init(1:3) + MATMUL(TRANSPOSE(dcm), point%pos)
  END SUBROUTINE apply_ptfm_point

  SUBROUTINE apply_ptfm_init(points, ptfm_init)
    !! Rigid-transform every Coupled/Vessel deck point by the initial platform
    !! displacement about the origin: p' = r + M^T p, with M the ZYX (3-2-1)
    !! global-to-local DCM -- MoorDyn-F's PtfmInit convention exactly (its OrMat is the
    !! same matrix, applied transposed). Fixed anchors, Free/Connect points, and
    !! body/rod-attached points are NOT platform-borne and stay where the deck put them.
    TYPE(DeckPoint), INTENT(INOUT) :: points(:)
    REAL(wp), INTENT(IN) :: ptfm_init(6)
    REAL(wp) :: dcm(3, 3)
    INTEGER :: i
    dcm = ptfm_zyx_dcm(ptfm_init(4:6))
    DO i = 1, SIZE(points)
      SELECT CASE (TRIM(points(i)%ptype))
      CASE ('coupled', 'vessel')
        points(i)%pos = ptfm_init(1:3) + MATMUL(TRANSPOSE(dcm), points(i)%pos)
      END SELECT
    END DO
  END SUBROUTINE apply_ptfm_init

  SUBROUTINE apply_ptfm_host_bodies(bodies, points, ptfm_init)
    !! Rigid-transform the Body<N> attachment points of every Coupled/Vessel BODY by the initial
    !! platform displacement (the body pose itself moves in CD_Init_Deck_Aggregate_Rigid6).
    TYPE(DeckBody), INTENT(IN) :: bodies(:)
    TYPE(DeckPoint), INTENT(INOUT) :: points(:)
    REAL(wp), INTENT(IN) :: ptfm_init(6)
    INTEGER :: i, j
    DO i = 1, SIZE(bodies)
      IF (.NOT. bodies(i)%host_coupled) CYCLE
      DO j = 1, SIZE(points)
        IF (points(j)%body_id == bodies(i)%id .AND. starts_with(TRIM(points(j)%ptype), 'body')) &
          CALL apply_ptfm_point(points(j), ptfm_init)
      END DO
    END DO
  END SUBROUTINE apply_ptfm_host_bodies

  SUBROUTINE apply_ptfm_host_rods(rods, points, ptfm_init)
    !! Rigid-transform every Coupled/Vessel ROD (its End A/B and its Rod<N>A/B attachment
    !! points) by the initial platform displacement, p' = r + M^T p (apply_ptfm_init).
    TYPE(DeckRod), INTENT(INOUT) :: rods(:)
    TYPE(DeckPoint), INTENT(INOUT) :: points(:)
    REAL(wp), INTENT(IN) :: ptfm_init(6)
    REAL(wp) :: dcm(3, 3)
    INTEGER :: i, j, k
    dcm = ptfm_zyx_dcm(ptfm_init(4:6))
    DO i = 1, SIZE(rods)
      IF (TRIM(rods(i)%rod_type) /= 'coupled' .AND. TRIM(rods(i)%rod_type) /= 'vessel') CYCLE
      rods(i)%end_a = ptfm_init(1:3) + MATMUL(TRANSPOSE(dcm), rods(i)%end_a)
      rods(i)%end_b = ptfm_init(1:3) + MATMUL(TRANSPOSE(dcm), rods(i)%end_b)
      DO j = 1, 2
        k = rod_point_index(points, rods(i)%id, j)
        IF (k > 0) CALL apply_ptfm_point(points(k), ptfm_init)
      END DO
    END DO
  END SUBROUTINE apply_ptfm_host_rods

  SUBROUTINE apply_coupled_positions(points, lines, is_fin, coupled_positions, ptfm_init, ErrStat, ErrMsg)
    !! Place every host-prescribed (moving) point at an explicit position before the
    !! static solves, in the aggregate moving-set order: the system's BOUND
    !! Coupled/Vessel points in deck POINT order (a Coupled point bound only to a
    !! finite-EI cable is NOT in the system's coupled map -- bound-only counting),
    !! followed by one coupled fairlead per finite-EI cable in deck LINE order.
    !! Fails closed on a shape/count mismatch, non-finite input, or combination with
    !! a nonzero ptfm_init (the two mutate the same points).
    TYPE(DeckPoint), INTENT(INOUT) :: points(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    LOGICAL, INTENT(IN) :: is_fin(:)
    REAL(wp), INTENT(IN) :: coupled_positions(:, :)
    REAL(wp), INTENT(IN), OPTIONAL :: ptfm_init(6)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg

    INTEGER :: i, l, icol
    LOGICAL :: bound_ei0

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (PRESENT(ptfm_init)) THEN
      IF (MAXVAL(ABS(ptfm_init)) > CD_ZERO) THEN
        CALL fail(ErrStat, ErrMsg, 'coupled_positions and a nonzero ptfm_init are mutually '// &
                  'exclusive (both place the host-prescribed points)'); RETURN
      END IF
    END IF
    IF (SIZE(coupled_positions, 1) /= 3) THEN
      CALL fail(ErrStat, ErrMsg, 'coupled_positions must be shaped (3, n_moving)'); RETURN
    END IF
    IF (.NOT. ALL(IEEE_IS_FINITE(coupled_positions))) THEN
      CALL fail(ErrStat, ErrMsg, 'coupled_positions must be finite'); RETURN
    END IF
    icol = 0
    DO i = 1, SIZE(points)
      SELECT CASE (TRIM(points(i)%ptype))
      CASE ('coupled', 'vessel')
        bound_ei0 = .FALSE.
        DO l = 1, SIZE(lines)
          IF (is_fin(l)) CYCLE
          IF (lines(l)%nodeA == points(i)%id .OR. lines(l)%nodeB == points(i)%id) THEN
            bound_ei0 = .TRUE.; EXIT
          END IF
        END DO
        IF (bound_ei0) THEN
          icol = icol + 1
          IF (icol > SIZE(coupled_positions, 2)) THEN
            CALL fail(ErrStat, ErrMsg, 'coupled_positions has fewer columns than the deck has '// &
                      'host-prescribed points'); RETURN
          END IF
          points(i)%pos = coupled_positions(:, icol)
        END IF
      END SELECT
    END DO
    DO l = 1, SIZE(lines)
      IF (.NOT. is_fin(l)) CYCLE
      DO i = 1, SIZE(points)
        IF (points(i)%id /= lines(l)%nodeA .AND. points(i)%id /= lines(l)%nodeB) CYCLE
        SELECT CASE (TRIM(points(i)%ptype))
        CASE ('coupled', 'vessel')
          icol = icol + 1
          IF (icol > SIZE(coupled_positions, 2)) THEN
            CALL fail(ErrStat, ErrMsg, 'coupled_positions has fewer columns than the deck has '// &
                      'host-prescribed points'); RETURN
          END IF
          points(i)%pos = coupled_positions(:, icol)
        END SELECT
      END DO
    END DO
    IF (icol /= SIZE(coupled_positions, 2)) THEN
      CALL fail(ErrStat, ErrMsg, 'coupled_positions column count does not match the deck''s '// &
                'host-prescribed point count'); RETURN
    END IF
  END SUBROUTINE apply_coupled_positions

  SUBROUTINE revalidate_ptfm_points(points, lines, ErrStat, ErrMsg)
    !! Re-establish the parse's position-dependent contracts on ptfm_init-displaced
    !! geometry (the transform runs after finalize_and_validate, so without this a
    !! displaced deck could hand the static builders geometry the undisplaced deck
    !! would have failed closed on): every point position stays finite, and on a
    !! static deck no LINE's fairlead-side End A ends up below its Fixed End B anchor
    !! (the ordering contract the catenary seeding relies on).
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: i, ia, ib
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    DO i = 1, SIZE(points)
      IF (.NOT. ALL(IEEE_IS_FINITE(points(i)%pos))) THEN
        CALL fail(ErrStat, ErrMsg, 'ptfm_init produced a non-finite point position'); RETURN
      END IF
    END DO
    IF (deck_has_dynamic_points(points)) RETURN
    DO i = 1, SIZE(lines)
      ia = find_point(points, lines(i)%nodeA)
      ib = find_point(points, lines(i)%nodeB)
      IF (ia == 0 .OR. ib == 0) CYCLE   ! endpoint resolution already validated by the parse
      IF (TRIM(points(ib)%ptype) == 'fixed') THEN
        IF (points(ia)%pos(3) < points(ib)%pos(3)) THEN
          CALL fail(ErrStat, ErrMsg, 'ptfm_init displaces a LINE End A fairlead (NodeA) below its '// &
                    'Fixed End B anchor (NodeB)'); RETURN
        END IF
      END IF
    END DO
  END SUBROUTINE revalidate_ptfm_points

  PURE FUNCTION ptfm_zyx_dcm(theta) RESULT(m)
    !! The NWTC ZYX (3-2-1) Euler global-to-local DCM, transcribed verbatim from
    !! NWTC_Num's EulerConstructZYX so the deck-side transform and the OpenFAST
    !! shell/glue side (which use the NWTC function) agree to the last bit.
    !! theta = [theta_x, theta_y, theta_z] in radians.
    REAL(wp), INTENT(IN) :: theta(3)
    REAL(wp) :: m(3, 3)
    REAL(wp) :: cx, sx, cy, sy, cz, sz
    cx = COS(theta(1)); sx = SIN(theta(1))
    cy = COS(theta(2)); sy = SIN(theta(2))
    cz = COS(theta(3)); sz = SIN(theta(3))
    m(1, 1) = cy*cz
    m(2, 1) = sx*sy*cz - sz*cx
    m(3, 1) = sx*sz + sy*cx*cz
    m(1, 2) = sz*cy
    m(2, 2) = sx*sy*sz + cx*cz
    m(3, 2) = -sx*cz + sy*sz*cx
    m(1, 3) = -sy
    m(2, 3) = sx*cy
    m(3, 3) = cx*cy
  END FUNCTION ptfm_zyx_dcm

  PURE LOGICAL FUNCTION line_torsion_active(ln) RESULT(active)
    !! Condensed torsion is solved on a line only when both ends declare a torsional restraint.
    TYPE(DeckLine), INTENT(IN) :: ln
    active = ALL(ln%tors_mode /= TORS_FREE)
  END FUNCTION line_torsion_active

  PURE LOGICAL FUNCTION deck_has_torsion_columns(lines) RESULT(has)
    !! Some END CONNECTIONS row declares a torsional restraint (TorsStiffness not Free).
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    INTEGER :: i
    has = .FALSE.
    DO i = 1, SIZE(lines)
      IF (ANY(lines(i)%tors_mode /= TORS_FREE)) has = .TRUE.
    END DO
  END FUNCTION deck_has_torsion_columns

  LOGICAL FUNCTION line_is_finite_ei(ln, types, sections) RESULT(is_finite)
    !! A LINE is a finite-EI (bending) cable iff ANY of its sections has EI > 0.
    !! Factored from all_lines_have_finite_ei's per-line finite test so the OpenFAST
    !! aggregate (CD_Init_Deck_Aggregate) can partition a mixed deck into its
    !! {EI=0 mooring} and {finite-EI cable} subsets from one shared predicate.
    TYPE(DeckLine), INTENT(IN) :: ln
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    INTEGER :: j
    is_finite = .FALSE.
    DO j = 1, SIZE(sections)
      IF (sections(j)%line_id /= ln%id) CYCLE
      IF (sections(j)%ltype >= 1 .AND. sections(j)%ltype <= SIZE(types)) THEN
        IF (types(sections(j)%ltype)%ei > CD_ZERO) THEN
          is_finite = .TRUE.
          RETURN
        END IF
      END IF
    END DO
  END FUNCTION line_is_finite_ei

  LOGICAL FUNCTION all_lines_have_finite_ei(types, lines, sections) RESULT(all_finite)
    !! Every line is fully finite-EI: each line has at least one finite-EI section
    !! (line_is_finite_ei) AND no line carries an EI=0 section. Used to reject a deck
    !! that mixes EI=0 and finite-EI sections on the standalone finite-EI dynamic path.
    TYPE(DeckLineType), INTENT(IN) :: types(:)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    TYPE(DeckSection), INTENT(IN) :: sections(:)
    INTEGER :: i, j
    all_finite = .TRUE.
    DO i = 1, SIZE(lines)
      DO j = 1, SIZE(sections)
        IF (sections(j)%line_id /= lines(i)%id) CYCLE
        IF (sections(j)%ltype < 1 .OR. sections(j)%ltype > SIZE(types)) THEN
          all_finite = .FALSE.
          CYCLE
        END IF
        IF (.NOT. (types(sections(j)%ltype)%ei > CD_ZERO)) all_finite = .FALSE.
      END DO
      all_finite = all_finite .AND. line_is_finite_ei(lines(i), types, sections)
    END DO
  END FUNCTION all_lines_have_finite_ei

  INTEGER FUNCTION point_index(points, id) RESULT(idx)
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    INTEGER, INTENT(IN) :: id
    idx = find_point(points, id)
  END FUNCTION point_index

  LOGICAL FUNCTION starts_with(s, prefix) RESULT(yes)
    CHARACTER(*), INTENT(IN) :: s, prefix
    yes = LEN_TRIM(prefix) <= LEN_TRIM(s)
    IF (yes) yes = (s(1:LEN_TRIM(prefix)) == prefix)
  END FUNCTION starts_with

  LOGICAL FUNCTION line_outputs_requested(flags) RESULT(requested)
    CHARACTER(*), INTENT(IN) :: flags
    CHARACTER(NAMELEN) :: lo

    lo = to_lower(TRIM(flags))
    requested = LEN_TRIM(lo) > 0 .AND. TRIM(lo) /= '-'
  END FUNCTION line_outputs_requested

  LOGICAL FUNCTION any_line_outputs_requested(lines) RESULT(requested)
    TYPE(DeckLine), INTENT(IN) :: lines(:)
    INTEGER :: i

    ! the per-line time-series files (p, t); the range graph (r) is not one of them
    requested = .FALSE.
    DO i = 1, SIZE(lines)
      IF (line_output_has_flag(lines(i)%outputs, 'p') .OR. line_output_has_flag(lines(i)%outputs, 't')) THEN
        requested = .TRUE.
        RETURN
      END IF
    END DO
  END FUNCTION any_line_outputs_requested

  LOGICAL FUNCTION line_output_has_flag(flags, flag) RESULT(has_flag)
    CHARACTER(*), INTENT(IN) :: flags
    CHARACTER(*), INTENT(IN) :: flag
    CHARACTER(NAMELEN) :: lo

    lo = to_lower(TRIM(flags))
    has_flag = INDEX(lo, flag(1:1)) > 0
  END FUNCTION line_output_has_flag

  LOGICAL FUNCTION valid_line_output_flags(flags) RESULT(ok)
    CHARACTER(*), INTENT(IN) :: flags
    CHARACTER(NAMELEN) :: lo
    INTEGER :: i

    lo = to_lower(TRIM(flags))
    ok = .TRUE.
    IF (LEN_TRIM(lo) == 0 .OR. TRIM(lo) == '-') RETURN
    DO i = 1, LEN_TRIM(lo)
      SELECT CASE (lo(i:i))
      CASE ('p', 't', 'r')
      CASE DEFAULT
        ok = .FALSE.
        RETURN
      END SELECT
    END DO
  END FUNCTION valid_line_output_flags

  LOGICAL FUNCTION rod_outputs_requested(flags) RESULT(requested)
    CHARACTER(*), INTENT(IN) :: flags
    CHARACTER(NAMELEN) :: lo

    lo = to_lower(TRIM(flags))
    requested = LEN_TRIM(lo) > 0 .AND. TRIM(lo) /= '-'
  END FUNCTION rod_outputs_requested

  LOGICAL FUNCTION rod_output_has_flag(flags, flag) RESULT(has_flag)
    CHARACTER(*), INTENT(IN) :: flags
    CHARACTER(*), INTENT(IN) :: flag
    CHARACTER(NAMELEN) :: lo

    lo = to_lower(TRIM(flags))
    has_flag = INDEX(lo, to_lower(flag(1:1))) > 0
  END FUNCTION rod_output_has_flag

  LOGICAL FUNCTION valid_rod_output_flags(flags) RESULT(ok)
    CHARACTER(*), INTENT(IN) :: flags
    CHARACTER(NAMELEN) :: lo
    INTEGER :: i

    lo = to_lower(TRIM(flags))
    ok = .TRUE.
    IF (LEN_TRIM(lo) == 0 .OR. TRIM(lo) == '-') RETURN
    DO i = 1, LEN_TRIM(lo)
      IF (lo(i:i) /= 'p') THEN
        ok = .FALSE.
        RETURN
      END IF
    END DO
  END FUNCTION valid_rod_output_flags

  PURE LOGICAL FUNCTION all_digits(s) RESULT(ok)
    !! True when every character of s is a decimal digit (T<J> vocabulary detection).
    CHARACTER(*), INTENT(IN) :: s
    INTEGER :: i
    ok = LEN(s) > 0
    DO i = 1, LEN(s)
      IF (s(i:i) < '0' .OR. s(i:i) > '9') THEN
        ok = .FALSE.; RETURN
      END IF
    END DO
  END FUNCTION all_digits

  INTEGER FUNCTION int_suffix(s, from) RESULT(n)
    CHARACTER(*), INTENT(IN) :: s
    INTEGER, INTENT(IN) :: from
    INTEGER :: i, c
    n = 0
    DO i = from, LEN_TRIM(s)
      c = IACHAR(s(i:i))
      IF (c < IACHAR('0') .OR. c > IACHAR('9')) THEN; n = 0; RETURN; END IF
      ! a suffix too large for INTEGER is no valid id (never wrap around to a small one)
      IF (n > (HUGE(n) - (c - IACHAR('0')))/10) THEN; n = 0; RETURN; END IF
      n = n*10 + (c - IACHAR('0'))
    END DO
  END FUNCTION int_suffix

  CHARACTER(24) FUNCTION es_to_str(x) RESULT(s)
    !! x in ES10.3 (asterisks never abort: the WRITE carries IOSTAT).
    REAL(wp), INTENT(IN) :: x
    INTEGER :: ios
    s = ''
    WRITE (s, '(ES10.3)', IOSTAT=ios) x
  END FUNCTION es_to_str

  CHARACTER(24) FUNCTION int_to_str(i) RESULT(s)
    INTEGER, INTENT(IN) :: i
    WRITE (s, '(I0)') i
  END FUNCTION int_to_str

  SUBROUTINE rd(val, x, ErrStat, ErrMsg)
    CHARACTER(*), INTENT(IN) :: val
    REAL(wp), INTENT(OUT) :: x
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    LOGICAL :: ok
    INTEGER :: defect
    ErrStat = 0; ErrMsg = ''
    ! strict whole-token read: "1/20" or "0,5" is an error, never 1 or 0; NaN, Inf and
    ! subnormal values are rejected here, before any range guard compares them
    CALL parse_real_token(val, x, ok, defect)
    IF (ok) RETURN
    IF (defect /= REAL_OK) THEN
      CALL fail(ErrStat, ErrMsg, 'OPTION '//real_defect_text(val, defect))
    ELSE
      CALL fail(ErrStat, ErrMsg, 'malformed numeric OPTION value "'//TRIM(val)// &
                '" (write a plain number with a "." decimal point)')
    END IF
  END SUBROUTINE rd

  SUBROUTINE rd_bool(val, x, ErrStat, ErrMsg)
    CHARACTER(*), INTENT(IN) :: val
    LOGICAL, INTENT(OUT) :: x
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    CHARACTER(NAMELEN) :: lo

    ErrStat = 0
    ErrMsg = ''
    lo = to_lower(TRIM(val))
    SELECT CASE (TRIM(lo))
    CASE ('true', 't', 'yes', 'y', 'on', '1')
      x = .TRUE.
    CASE ('false', 'f', 'no', 'n', 'off', '0')
      x = .FALSE.
    CASE DEFAULT
      CALL fail(ErrStat, ErrMsg, 'malformed logical OPTION value "'//TRIM(val)//'"')
    END SELECT
  END SUBROUTINE rd_bool

  SUBROUTINE rd_tensile_mode(val, mode, ErrStat, ErrMsg)
    CHARACTER(*), INTENT(IN) :: val
    INTEGER, INTENT(OUT) :: mode
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    CHARACTER(NAMELEN) :: lo

    ErrStat = 0; ErrMsg = ''
    lo = to_lower(TRIM(val))
    SELECT CASE (TRIM(lo))
    CASE ('true', 't', 'yes', 'y', 'on', '1', 'error')
      mode = CD_HCDYN_TENSILE_ERROR
    CASE ('warn', 'warning', 'monitor')
      mode = CD_HCDYN_TENSILE_WARN
    CASE ('false', 'f', 'no', 'n', 'off', '0')
      mode = CD_HCDYN_TENSILE_OFF
    CASE DEFAULT
      CALL fail(ErrStat, ErrMsg, &
                'malformed tensile_safety value "'//TRIM(val)//'" (use False, warn, or True)')
    END SELECT
  END SUBROUTINE rd_tensile_mode

  SUBROUTINE scatter_rigid6_point_motion(system, points, rigid, q, v, a)
    TYPE(CD_SystemType), INTENT(IN) :: system
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(RigidBodyState), INTENT(IN) :: rigid(:)
    REAL(wp), INTENT(INOUT) :: q(:), v(:), a(:)
    INTEGER :: ib, ip, pidx, base
    REAL(wp) :: arm(3)
    DO ib = 1, SIZE(rigid)
      DO ip = 1, SIZE(rigid(ib)%point_indices)
        pidx = rigid(ib)%point_indices(ip)
        base = system_point_base(system, points(pidx)%id)
        IF (base < 0) CYCLE
        arm = MATMUL(rigid(ib)%rot_mat, points(pidx)%body_offset)
        q(base + 1:base + 3) = rigid(ib)%r + arm
        v(base + 1:base + 3) = rigid(ib)%v + cross3(rigid(ib)%omega, arm)
        a(base + 1:base + 3) = rigid(ib)%a + cross3(rigid(ib)%alpha, arm) + &
                               cross3(rigid(ib)%omega, cross3(rigid(ib)%omega, arm))
      END DO
    END DO
  END SUBROUTINE scatter_rigid6_point_motion

  SUBROUTINE host_substep_start(system, nsub, q0h, v0h, a0h, ErrStat, ErrMsg, host_mask)
    !! The step-start coupled motion a sub-cycled step interpolates the host motion from (only
    !! with a host overlay and more than one sub-step).
    TYPE(CD_SystemType), INTENT(IN) :: system
    INTEGER, INTENT(IN) :: nsub
    REAL(wp), ALLOCATABLE, INTENT(INOUT) :: q0h(:), v0h(:), a0h(:)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    LOGICAL, INTENT(IN), OPTIONAL :: host_mask(:)
    INTEGER :: es
    CHARACTER(160) :: em
    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    IF (.NOT. PRESENT(host_mask) .OR. nsub <= 1) RETURN
    ALLOCATE (q0h(system%n_system_coupled_dof), v0h(system%n_system_coupled_dof), a0h(system%n_system_coupled_dof))
    CALL CD_Get_System_CoupledMotion(system, q0h, v0h, a0h, es, em)
    IF (es /= CD_SYSTEM_OK) THEN
      ErrStat = CD_DECKDRV_SOLVEFAIL
      ErrMsg = 'CableDyn_DeckDriver: host sub-step start motion query failed: '//TRIM(em)
    END IF
  END SUBROUTINE host_substep_start

  PURE SUBROUTINE overlay_host_motion(q, v, a, host_mask, host_q, host_v, host_a)
    !! Replace the host-prescribed coupled DOFs of a step's input motion by the host's.
    REAL(wp), INTENT(INOUT) :: q(:), v(:), a(:)
    LOGICAL, INTENT(IN), OPTIONAL :: host_mask(:)
    REAL(wp), INTENT(IN), OPTIONAL :: host_q(:), host_v(:), host_a(:)
    IF (.NOT. (PRESENT(host_mask) .AND. PRESENT(host_q) .AND. PRESENT(host_v) .AND. PRESENT(host_a))) RETURN
    WHERE (host_mask)
      q = host_q
      v = host_v
      a = host_a
    END WHERE
  END SUBROUTINE overlay_host_motion

  SUBROUTINE scatter_rod_point_motion(system, points, rod_state, q, v, a)
    TYPE(CD_SystemType), INTENT(IN) :: system
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(RodState), INTENT(IN) :: rod_state(:)
    REAL(wp), INTENT(INOUT) :: q(:), v(:), a(:)
    INTEGER :: ir, base
    REAL(wp) :: arm(3)

    DO ir = 1, SIZE(rod_state)
      base = system_point_base(system, points(rod_state(ir)%point_a_index)%id)
      IF (base >= 0) THEN
        arm = MATMUL(rod_state(ir)%rot_mat, [-rod_state(ir)%half_length, CD_ZERO, CD_ZERO])
        q(base + 1:base + 3) = rod_state(ir)%r + arm
        v(base + 1:base + 3) = rod_state(ir)%v + cross3(rod_state(ir)%omega, arm)
        a(base + 1:base + 3) = rod_state(ir)%a + cross3(rod_state(ir)%alpha, arm) + &
                               cross3(rod_state(ir)%omega, cross3(rod_state(ir)%omega, arm))
      END IF
      base = system_point_base(system, points(rod_state(ir)%point_b_index)%id)
      IF (base >= 0) THEN
        arm = MATMUL(rod_state(ir)%rot_mat, [rod_state(ir)%half_length, CD_ZERO, CD_ZERO])
        q(base + 1:base + 3) = rod_state(ir)%r + arm
        v(base + 1:base + 3) = rod_state(ir)%v + cross3(rod_state(ir)%omega, arm)
        a(base + 1:base + 3) = rod_state(ir)%a + cross3(rod_state(ir)%alpha, arm) + &
                               cross3(rod_state(ir)%omega, cross3(rod_state(ir)%omega, arm))
      END IF
    END DO
  END SUBROUTINE scatter_rod_point_motion

  PURE FUNCTION rod_orientation_from_axis(axis) RESULT(rot)
    REAL(wp), INTENT(IN) :: axis(3)
    REAL(wp) :: rot(3, 3), ytmp(3), zaxis(3), yaxis(3), xaxis(3), ynorm

    xaxis = axis/SQRT(SUM(axis*axis))
    IF (ABS(xaxis(3)) < 0.9_wp) THEN
      ytmp = [CD_ZERO, CD_ZERO, CD_ONE]
    ELSE
      ytmp = [CD_ZERO, CD_ONE, CD_ZERO]
    END IF
    zaxis = cross3(xaxis, ytmp)
    zaxis = zaxis/SQRT(SUM(zaxis*zaxis))
    yaxis = cross3(zaxis, xaxis)
    ynorm = SQRT(SUM(yaxis*yaxis))
    IF (ynorm > CD_ZERO) yaxis = yaxis/ynorm
    rot(:, 1) = xaxis
    rot(:, 2) = yaxis
    rot(:, 3) = zaxis
  END FUNCTION rod_orientation_from_axis

  SUBROUTINE clamp_object_frame(ln, points, bodies, rods, rot, d0, ErrStat, ErrMsg, check_axis)
    !! The object frame of a finite-EI line's End A END CONNECTION on a Rigid6 body point or a rod
    !! end, at the object's current pose (its static-equilibrium pose once solved): rot, the
    !! object-to-global rotation, and d0, the connection direction (End A to End B) in the object
    !! frame. On a body point the deck direction is given in the body frame. On a rod end it must
    !! be parallel to the rod axis (either sense, in the frame of the rod's deck coordinates): a
    !! rod has no spin angle in its static solve, and a direction along the axis makes the
    !! connection moment normal to the axis. check_axis = .FALSE. (after the static solve has
    !! turned the rod; the deck direction was checked before it) keeps only the sense.
    TYPE(DeckLine), INTENT(IN) :: ln
    TYPE(DeckPoint), INTENT(IN) :: points(:)
    TYPE(DeckBody), INTENT(IN) :: bodies(:)
    TYPE(DeckRod), INTENT(IN) :: rods(:)
    REAL(wp), INTENT(OUT) :: rot(3, 3), d0(3)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    LOGICAL, INTENT(IN), OPTIONAL :: check_axis
    INTEGER :: pa, ib, ir, rid, iend
    REAL(wp) :: axis(3), ez(3), an
    LOGICAL :: check
    CHARACTER(64) :: who

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    rot = CD_ZERO
    rot(1, 1) = CD_ONE
    rot(2, 2) = CD_ONE
    rot(3, 3) = CD_ONE
    ez = ln%endconn_ez_ref(:, 1)
    d0 = ez
    check = .TRUE.
    IF (PRESENT(check_axis)) check = check_axis
    who = 'finite-EI LINE '//TRIM(int_to_str(ln%id))//' End A'
    pa = find_point(points, ln%nodeA)
    IF (pa < 1) THEN
      CALL fail(ErrStat, ErrMsg, TRIM(who)//' references an unknown point'); RETURN
    END IF
    IF (starts_with(TRIM(points(pa)%ptype), 'body')) THEN
      ib = find_body(bodies, points(pa)%body_id)
      IF (ib < 1) THEN
        CALL fail(ErrStat, ErrMsg, TRIM(who)//' is on an unknown body'); RETURN
      END IF
      IF (TRIM(bodies(ib)%btype) /= 'rigid6') THEN
        CALL fail(ErrStat, ErrMsg, TRIM(who)//': a clamped or elastic END CONNECTION on a body needs a '// &
                  'Rigid6 body'); RETURN
      END IF
      rot = deck_body_pose_rotation(bodies(ib))
    ELSE IF (is_rod_point_type(points(pa)%ptype)) THEN
      CALL parse_rod_point_type(points(pa)%ptype, rid, iend)
      ir = find_rod(rods, rid)
      IF (ir < 1) THEN
        CALL fail(ErrStat, ErrMsg, TRIM(who)//' is on an unknown rod'); RETURN
      END IF
      axis = rods(ir)%end_b - rods(ir)%end_a
      an = NORM2(axis)
      IF (.NOT. an > CD_ZERO) THEN
        CALL fail(ErrStat, ErrMsg, TRIM(who)//': a clamped or elastic END CONNECTION needs a rod of '// &
                  'non-zero length'); RETURN
      END IF
      axis = axis/an
      IF (check .AND. NORM2(cross3(axis, ez)) > 1.0e-6_wp) THEN
        CALL fail(ErrStat, ErrMsg, TRIM(who)//': the END CONNECTION direction on a rod end must be '// &
                  'parallel to the rod axis (either sense)'); RETURN
      END IF
      d0 = [SIGN(CD_ONE, DOT_PRODUCT(axis, ez)), CD_ZERO, CD_ZERO]
      ib = pinned_body_of_rod_type(rods(ir)%rod_type)
      IF (ib > 0) THEN
        ib = find_body(bodies, ib)
        IF (ib > 0) axis = MATMUL(deck_body_pose_rotation(bodies(ib)), axis)
      END IF
      rot = rod_orientation_from_axis(axis)
    ELSE
      CALL fail(ErrStat, ErrMsg, TRIM(who)//': a clamped or elastic END CONNECTION needs a Fixed point, a '// &
                'Rigid6 body point or a rod end'); RETURN
    END IF
  END SUBROUTINE clamp_object_frame

  FUNCTION deck_body_pose_rotation(bd) RESULT(rot)
    !! Body-to-global rotation of a deck body at its static-equilibrium pose (else its deck pose).
    TYPE(DeckBody), INTENT(IN) :: bd
    REAL(wp) :: rot(3, 3)
    IF (bd%has_eq) THEN
      rot = bd%rot_eq
    ELSE
      rot = CD_Body_Rotation(bd%rot(1), bd%rot(2), bd%rot(3))
    END IF
  END FUNCTION deck_body_pose_rotation

  INTEGER FUNCTION system_point_base(system, point_id) RESULT(base)
    TYPE(CD_SystemType), INTENT(IN) :: system
    INTEGER, INTENT(IN) :: point_id

    INTEGER :: i, local_base

    base = -1
    IF (.NOT. ALLOCATED(system%bindings) .OR. .NOT. ALLOCATED(system%coupled_dof_map)) RETURN
    DO i = 1, SIZE(system%bindings)
      IF (system%bindings(i)%point_id /= point_id) CYCLE
      local_base = 6*(system%bindings(i)%line_index - 1) + 3*(system%bindings(i)%line_end - 1)
      base = system%coupled_dof_map(local_base + 1) - 1
      RETURN
    END DO
  END FUNCTION system_point_base

  PURE FUNCTION cross3(a, b) RESULT(c)
    REAL(wp), INTENT(IN) :: a(3), b(3)
    REAL(wp) :: c(3)
    c = [a(2)*b(3) - a(3)*b(2), a(3)*b(1) - a(1)*b(3), a(1)*b(2) - a(2)*b(1)]
  END FUNCTION cross3

