  SUBROUTINE load_bathymetry_file(path, bathymetry, ErrStat, ErrMsg, points)
    !! Read a structured bathymetry file with rows "x y depth". Rows may be in
    !! any order, but must form a complete rectangular grid with no duplicates.
    !! points (optional): the deck points; every Fixed point is then checked to sit on or
    !! above the loaded seabed (the bathymetry is released again on that failure); anchors
    !! within the seabed tolerance are placed on the surface.
    CHARACTER(*), INTENT(IN) :: path
    TYPE(CD_BathymetryType), INTENT(OUT) :: bathymetry
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    TYPE(DeckPoint), INTENT(INOUT), OPTIONAL :: points(:)

    INTEGER :: unit, ios, nrec, nx, ny, i, ix, iy, es, lineno, row_status
    REAL(wp) :: row(3)
    REAL(wp), ALLOCATABLE :: xr(:), yr(:), dr(:), xgrid(:), ygrid(:), depth(:, :)
    LOGICAL, ALLOCATABLE :: filled(:, :)
    CHARACTER(DECK_RECLEN) :: line
    CHARACTER(200) :: em
    CHARACTER(256) :: why

    ErrStat = CD_DECKDRV_OK
    ErrMsg = ''
    nrec = 0
    ALLOCATE (xr(0), yr(0), dr(0))
    CALL CD_Open_Input(unit, path, ios, why)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open bathymetry file: '//TRIM(path)//input_open_reason(path, why))
      RETURN
    END IF
    lineno = 0
    DO
      CALL next_record(unit, line, ios, lineno)
      IF (IS_IOSTAT_END(ios)) EXIT
      IF (ios /= 0) THEN
        CLOSE (unit)
        CALL record_error(ios, 'bathymetry file', lineno, ErrStat, ErrMsg)
        RETURN
      END IF
      IF (count_tokens(line) /= 3) THEN
        CLOSE (unit)
        CALL fail(ErrStat, ErrMsg, 'rows must be "x y depth"')
        CALL add_row_context('bathymetry file', lineno, line, ErrMsg)
        RETURN
      END IF
      CALL parse_real_row(line, row, row_status)
      IF (row_status /= 0) THEN
        CLOSE (unit)
        CALL fail(ErrStat, ErrMsg, 'malformed row (expected x y depth as plain numbers)')
        CALL add_row_context('bathymetry file', lineno, line, ErrMsg)
        RETURN
      END IF
      CALL grow_real(xr, nrec + 1)
      CALL grow_real(yr, nrec + 1)
      CALL grow_real(dr, nrec + 1)
      nrec = nrec + 1
      xr(nrec) = row(1)
      yr(nrec) = row(2)
      dr(nrec) = row(3)
    END DO
    CLOSE (unit)
    IF (nrec < 4) THEN
      CALL fail(ErrStat, ErrMsg, 'bathymetry file needs at least a 2x2 grid')
      RETURN
    END IF
    CALL trim_real(xr, nrec)
    CALL trim_real(yr, nrec)
    CALL trim_real(dr, nrec)
    IF (.NOT. (ALL(IEEE_IS_FINITE(xr)) .AND. ALL(IEEE_IS_FINITE(yr)) .AND. ALL(IEEE_IS_FINITE(dr)))) THEN
      CALL fail(ErrStat, ErrMsg, 'bathymetry file coordinates and depths must be finite')
      RETURN
    END IF
    IF (ANY(dr <= CD_ZERO)) THEN
      CALL fail(ErrStat, ErrMsg, 'bathymetry file depths must be positive')
      RETURN
    END IF

    CALL sorted_unique(xr, xgrid)
    CALL sorted_unique(yr, ygrid)
    nx = SIZE(xgrid)
    ny = SIZE(ygrid)
    IF (nx < 2 .OR. ny < 2 .OR. nrec /= nx*ny) THEN
      CALL fail(ErrStat, ErrMsg, 'bathymetry file must define one complete rectangular grid')
      RETURN
    END IF
    ALLOCATE (depth(nx, ny), filled(nx, ny))
    depth = CD_ZERO
    filled = .FALSE.
    DO i = 1, nrec
      ix = find_exact_real(xgrid, xr(i))
      iy = find_exact_real(ygrid, yr(i))
      IF (ix < 1 .OR. iy < 1) THEN
        CALL fail(ErrStat, ErrMsg, 'internal bathymetry grid lookup failed')
        RETURN
      END IF
      IF (filled(ix, iy)) THEN
        CALL fail(ErrStat, ErrMsg, 'bathymetry file has duplicate x/y entries')
        RETURN
      END IF
      depth(ix, iy) = dr(i)
      filled(ix, iy) = .TRUE.
    END DO
    IF (.NOT. ALL(filled)) THEN
      CALL fail(ErrStat, ErrMsg, 'bathymetry file grid is incomplete')
      RETURN
    END IF
    CALL CD_Init_Bathymetry(bathymetry, xgrid, ygrid, depth, es, em)
    IF (es /= CD_BATHY_OK .OR. .NOT. CD_Bathymetry_Is_Initialized(bathymetry)) THEN
      CALL fail(ErrStat, ErrMsg, 'bathymetry init failed: '//TRIM(em))
      RETURN
    END IF
    IF (PRESENT(points)) THEN
      CALL check_fixed_points_on_bathymetry(points, bathymetry, ErrStat, ErrMsg)
      IF (ErrStat /= 0) CALL CD_End_Bathymetry(bathymetry)
    END IF
  END SUBROUTINE load_bathymetry_file

  SUBROUTINE sorted_unique(values, unique)
    REAL(wp), INTENT(IN) :: values(:)
    REAL(wp), ALLOCATABLE, INTENT(OUT) :: unique(:)

    REAL(wp), ALLOCATABLE :: tmp(:)
    REAL(wp) :: key
    INTEGER :: i, j, n

    ALLOCATE (tmp(SIZE(values)))
    tmp = values
    DO i = 2, SIZE(tmp)
      key = tmp(i)
      j = i - 1
      ! Nested test: .AND. does not short-circuit, so a combined condition would read
      ! tmp(0) once j reaches 0 (every new minimum).
      DO WHILE (j >= 1)
        IF (.NOT. (tmp(j) > key)) EXIT
        tmp(j + 1) = tmp(j)
        j = j - 1
      END DO
      tmp(j + 1) = key
    END DO
    n = 1
    DO i = 2, SIZE(tmp)
      IF (.NOT. same_real_coord(tmp(i), tmp(n))) THEN
        n = n + 1
        tmp(n) = tmp(i)
      END IF
    END DO
    ALLOCATE (unique(n))
    unique = tmp(1:n)
  END SUBROUTINE sorted_unique

  INTEGER FUNCTION find_exact_real(values, target) RESULT(idx)
    REAL(wp), INTENT(IN) :: values(:), target
    INTEGER :: i

    idx = 0
    DO i = 1, SIZE(values)
      IF (same_real_coord(values(i), target)) THEN
        idx = i
        RETURN
      END IF
    END DO
  END FUNCTION find_exact_real

  LOGICAL FUNCTION same_real_coord(a, b) RESULT(same)
    REAL(wp), INTENT(IN) :: a, b

    same = ABS(a - b) <= 16.0_wp*EPSILON(CD_ONE)*MAX(CD_ONE, ABS(a), ABS(b))
  END FUNCTION same_real_coord

  SUBROUTINE grow_real(a, n)
    REAL(wp), ALLOCATABLE, INTENT(INOUT) :: a(:)
    INTEGER, INTENT(IN) :: n
    REAL(wp), ALLOCATABLE :: tmp(:)
    INTEGER :: old

    IF (SIZE(a) >= n) RETURN
    old = SIZE(a)
    ALLOCATE (tmp(MAX(n, MAX(16, 2*MAX(1, old)))))
    tmp = CD_ZERO
    IF (old > 0) tmp(1:old) = a
    CALL MOVE_ALLOC(tmp, a)
  END SUBROUTINE grow_real

  SUBROUTINE trim_real(a, n)
    REAL(wp), ALLOCATABLE, INTENT(INOUT) :: a(:)
    INTEGER, INTENT(IN) :: n
    REAL(wp), ALLOCATABLE :: tmp(:)

    ALLOCATE (tmp(n))
    IF (n > 0) tmp = a(1:n)
    CALL MOVE_ALLOC(tmp, a)
  END SUBROUTINE trim_real

  SUBROUTINE read_syrope_settings(path, owc_strain, owc_tension, wc_mod, p1, p2, ErrStat, ErrMsg, owc_file)
    !! Read a Syrope settings file (the SYROPE:<file> reference): rows of the
    !! form "<value> <name> <description...>". Recognizes OWC (the original-
    !! working-curve table path, resolved relative to the settings file),
    !! WCType (LINEAR/QUADRATIC/EXP), and k1/k2 (the working-curve shape
    !! parameters p1/p2). Then reads the OWC strain-tension table (header/units
    !! rows dropped as non-numeric).
    CHARACTER(*), INTENT(IN) :: path
    REAL(wp), ALLOCATABLE, INTENT(OUT) :: owc_strain(:), owc_tension(:)
    INTEGER, INTENT(OUT) :: wc_mod
    REAL(wp), INTENT(OUT) :: p1, p2
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    ! the OWC table path, resolved against the settings file (blank until it is known)
    CHARACTER(*), INTENT(OUT), OPTIONAL :: owc_file

    INTEGER :: unit, ios, n, lineno, row_status, split_stat
    CHARACTER(DECK_RECLEN) :: line, owc_path, val, name
    LOGICAL :: have_owc, have_wc, have_k1, have_k2
    REAL(wp) :: row(2)
    REAL(wp), ALLOCATABLE :: es(:), ts(:)
    CHARACTER(256) :: why

    ErrStat = 0; ErrMsg = ''
    IF (PRESENT(owc_file)) owc_file = ''
    wc_mod = 0; p1 = CD_ZERO; p2 = CD_ZERO
    owc_path = ''
    have_owc = .FALSE.; have_wc = .FALSE.; have_k1 = .FALSE.; have_k2 = .FALSE.
    CALL CD_Open_Input(unit, path, ios, why)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open Syrope settings file: '//TRIM(path)//input_open_reason(path, why))
      RETURN
    END IF
    lineno = 0
    DO
      CALL next_record(unit, line, ios, lineno)
      IF (IS_IOSTAT_END(ios)) EXIT
      IF (ios /= 0) THEN
        CLOSE (unit)
        CALL record_error(ios, 'Syrope settings file', lineno, ErrStat, ErrMsg)
        RETURN
      END IF
      ! Whitespace split, not a list-directed READ: the OWC value is a path whose '/'
      ! separators a list-directed READ would treat as end of input.
      val = ''
      name = ''
      CALL split_two_tokens(line, val, name, split_stat, allow_trailing=.TRUE.)
      IF (split_stat /= 0) CYCLE
      val = strip_quotes(val)
      SELECT CASE (to_lower(TRIM(name)))
      CASE ('owc', 'wctype', 'k1', 'k2')
        IF ((to_lower(TRIM(name)) == 'owc' .AND. have_owc) .OR. (to_lower(TRIM(name)) == 'wctype' .AND. have_wc) &
            .OR. (to_lower(TRIM(name)) == 'k1' .AND. have_k1) .OR. (to_lower(TRIM(name)) == 'k2' .AND. have_k2)) THEN
          CLOSE (unit)
          CALL fail(ErrStat, ErrMsg, 'duplicate Syrope '//TRIM(name)//' row')
          CALL add_row_context('Syrope settings file', lineno, line, ErrMsg)
          RETURN
        END IF
      END SELECT
      SELECT CASE (to_lower(TRIM(name)))
      CASE ('owc')
        owc_path = val; have_owc = .TRUE.
      CASE ('wctype')
        SELECT CASE (to_lower(TRIM(val)))
        CASE ('linear'); wc_mod = CD_SYROPE_WC_LINEAR
        CASE ('quadratic'); wc_mod = CD_SYROPE_WC_QUADRATIC
        CASE ('exp'); wc_mod = CD_SYROPE_WC_EXP
        CASE DEFAULT
          CLOSE (unit)
          CALL fail(ErrStat, ErrMsg, 'Syrope WCType must be LINEAR, QUADRATIC, or EXP')
          CALL add_row_context('Syrope settings file', lineno, line, ErrMsg)
          RETURN
        END SELECT
        have_wc = .TRUE.
      CASE ('k1', 'k2')
        IF (to_lower(TRIM(name)) == 'k1') THEN
          CALL parse_real_token(val, p1, have_k1)
        ELSE
          CALL parse_real_token(val, p2, have_k2)
        END IF
        IF (.NOT. MERGE(have_k1, have_k2, to_lower(TRIM(name)) == 'k1')) THEN
          CLOSE (unit)
          CALL fail(ErrStat, ErrMsg, 'Syrope '//TRIM(name)//' value "'//TRIM(val)//'" is not a plain number')
          CALL add_row_context('Syrope settings file', lineno, line, ErrMsg)
          RETURN
        END IF
      END SELECT
    END DO
    CLOSE (unit)
    IF (.NOT. (have_owc .AND. have_wc .AND. have_k1 .AND. have_k2)) THEN
      CALL fail(ErrStat, ErrMsg, 'the Syrope settings file '//TRIM(path)//' needs OWC, WCType, k1, and k2 rows')
      RETURN
    END IF
    IF (PRESENT(owc_file)) owc_file = path_join(deck_dir(path), TRIM(owc_path))
    CALL CD_Open_Input(unit, path_join(deck_dir(path), TRIM(owc_path)), ios, why)
    IF (ios /= 0) THEN
      CALL fail(ErrStat, ErrMsg, 'cannot open Syrope OWC table: '//TRIM(owc_path)// &
                input_open_reason(path_join(deck_dir(path), TRIM(owc_path)), why)); RETURN
    END IF
    ALLOCATE (es(0), ts(0))
    lineno = 0
    DO
      CALL next_record(unit, line, ios, lineno)
      IF (IS_IOSTAT_END(ios)) EXIT
      IF (ios /= 0) THEN
        CLOSE (unit)
        CALL record_error(ios, 'Syrope OWC table', lineno, ErrStat, ErrMsg)
        RETURN
      END IF
      IF (.NOT. has_numeric_token(line)) CYCLE
      CALL parse_real_row(line, row, row_status)
      IF (row_status /= 0) THEN
        CLOSE (unit)
        CALL fail(ErrStat, ErrMsg, 'malformed row (expected strain tension as plain numbers)')
        CALL add_row_context('Syrope OWC table', lineno, line, ErrMsg)
        RETURN
      END IF
      es = [es, row(1)]; ts = [ts, row(2)]
    END DO
    CLOSE (unit)
    n = SIZE(es)
    IF (n < 2) THEN
      CALL fail(ErrStat, ErrMsg, 'the Syrope OWC table needs at least two rows'); RETURN
    END IF
    CALL MOVE_ALLOC(es, owc_strain)
    CALL MOVE_ALLOC(ts, owc_tension)
  END SUBROUTINE read_syrope_settings

  FUNCTION deck_dir(path) RESULT(dir)
    CHARACTER(*), INTENT(IN) :: path
    CHARACTER(:), ALLOCATABLE :: dir
    INTEGER :: i, p

    p = 0
    DO i = 1, LEN_TRIM(path)
      IF (path(i:i) == '/' .OR. path(i:i) == '\') p = i
    END DO
    IF (p > 0) THEN
      dir = path(1:p)
    ELSE
      dir = ''
    END IF
  END FUNCTION deck_dir

  FUNCTION path_join(dir, name) RESULT(path)
    CHARACTER(*), INTENT(IN) :: dir, name
    CHARACTER(:), ALLOCATABLE :: path, clean_name
    LOGICAL :: is_absolute

    clean_name = TRIM(ADJUSTL(name))
    is_absolute = .FALSE.
    IF (LEN(clean_name) >= 2) is_absolute = clean_name(2:2) == ':'
    IF (LEN(clean_name) >= 1) THEN
      is_absolute = is_absolute .OR. clean_name(1:1) == '/' .OR. clean_name(1:1) == '\'
    END IF
    IF (is_absolute) THEN
      path = clean_name
    ELSE
      path = TRIM(dir)//clean_name
    END IF
  END FUNCTION path_join

  SUBROUTINE next_record(unit, line, ios, lineno)
    !! Next non-blank record with any inline `#`/`!`/(non-leading)`--` comment stripped.
    !! ios < 0 at end of file. A record whose non-comment text does not fit in `line`
    !! returns ios = REC_TOO_LONG (with the part that fits) rather than a silently
    !! truncated row; other positive ios values are read errors. lineno, when present,
    !! is advanced by every physical record consumed (blank and comment records too),
    !! so on return it is the file line number of the returned record.
    !! A UTF-8 byte-order mark before the first record is dropped. Records holding only
    !! ASCII whitespace (space, tab, CR, LF, FF, VT) are blank; in returned text CR,
    !! LF, FF and VT become spaces, so every tokenizer separates on spaces and tabs
    !! alone. Non-comment text holding a NUL byte or a non-ASCII whitespace character
    !! returns ios = REC_NUL_CHAR or REC_BAD_CHAR instead of a row whose tokens would
    !! silently absorb it.
    INTEGER, INTENT(IN)  :: unit
    CHARACTER(*), INTENT(OUT) :: line
    INTEGER, INTENT(OUT) :: ios
    INTEGER, INTENT(INOUT), OPTIONAL :: lineno
    CHARACTER(LEN(line)) :: buf
    INTEGER :: p, i
    LOGICAL :: overflow
    line = ''
    DO
      CALL read_whole_record(unit, buf, ios, overflow)
      IF (ios /= 0) RETURN
      IF (PRESENT(lineno)) THEN
        lineno = lineno + 1
        IF (lineno == 1) CALL CD_Strip_BOM(buf)
      END IF
      p = scan_comment(buf)
      IF (overflow .AND. p == 0) THEN
        ! text continues past the buffer and no comment starts inside it
        line = ADJUSTL(buf)
        ios = REC_TOO_LONG
        RETURN
      END IF
      IF (p > 0) buf(p:) = ' '
      DO i = 1, LEN_TRIM(buf)
        IF (is_space(buf(i:i))) buf(i:i) = ' '
      END DO
      buf = ADJUSTL(buf)
      IF (LEN_TRIM(buf) > 0) THEN
        line = buf
        ios = record_charset_status(buf)
        RETURN
      END IF
    END DO
  END SUBROUTINE next_record

  INTEGER FUNCTION record_charset_status(text) RESULT(stat)
    !! 0 for record text a tokenizer can split reliably; REC_NUL_CHAR when it holds a
    !! NUL byte; REC_BAD_CHAR when it holds a UTF-8 encoded non-ASCII whitespace
    !! character (U+0085, U+00A0, U+1680, U+2000..U+200A, U+2028, U+2029, U+202F,
    !! U+205F, U+3000), which looks like a separator but is part of a token.
    CHARACTER(*), INTENT(IN) :: text
    INTEGER :: i, n, b1, b2, b3

    stat = 0
    n = LEN_TRIM(text)
    IF (INDEX(text(1:n), ACHAR(0)) > 0) THEN
      stat = REC_NUL_CHAR
      RETURN
    END IF
    DO i = 1, n - 1
      b1 = IACHAR(text(i:i))
      IF (b1 < 194 .OR. b1 > 227) CYCLE
      b2 = IACHAR(text(i + 1:i + 1))
      IF (b1 == 194) THEN
        IF (b2 == 133 .OR. b2 == 160) stat = REC_BAD_CHAR
      ELSE IF (i + 2 <= n) THEN
        b3 = IACHAR(text(i + 2:i + 2))
        SELECT CASE (b1)
        CASE (225)
          IF (b2 == 154 .AND. b3 == 128) stat = REC_BAD_CHAR
        CASE (226)
          IF (b2 == 128 .AND. ((b3 >= 128 .AND. b3 <= 138) .OR. b3 == 168 .OR. b3 == 169 .OR. b3 == 175)) &
            stat = REC_BAD_CHAR
          IF (b2 == 129 .AND. b3 == 159) stat = REC_BAD_CHAR
        CASE (227)
          IF (b2 == 128 .AND. b3 == 128) stat = REC_BAD_CHAR
        END SELECT
      END IF
      IF (stat /= 0) RETURN
    END DO
  END FUNCTION record_charset_status

  SUBROUTINE read_raw_record(unit, line, ios, lineno)
    !! Next physical record, comments included (the positional WaterKin layout counts
    !! every line). A record longer than line is cut to it; a UTF-8 byte-order mark
    !! before the first record is dropped; lineno counts the records read.
    INTEGER, INTENT(IN) :: unit
    CHARACTER(*), INTENT(OUT) :: line
    INTEGER, INTENT(OUT) :: ios
    INTEGER, INTENT(INOUT) :: lineno
    LOGICAL :: overflow

    CALL read_whole_record(unit, line, ios, overflow)
    IF (ios /= 0) RETURN
    lineno = lineno + 1
    IF (lineno == 1) CALL CD_Strip_BOM(line)
  END SUBROUTINE read_raw_record

  PURE LOGICAL FUNCTION is_blank_text(s) RESULT(blank)
    !! True when s holds only ASCII whitespace (see is_space).
    CHARACTER(*), INTENT(IN) :: s
    blank = first_nonspace(s, 1, LEN_TRIM(s)) > LEN_TRIM(s)
  END FUNCTION is_blank_text

  SUBROUTINE add_file_line(what, lineno, ErrMsg)
    !! Rewrite an auxiliary-file error as "<what> line N: <message>" (lineno > 0).
    CHARACTER(*), INTENT(IN) :: what
    INTEGER, INTENT(IN) :: lineno
    CHARACTER(*), INTENT(INOUT) :: ErrMsg
    CHARACTER(:), ALLOCATABLE :: body
    CHARACTER(*), PARAMETER :: prefix = 'CableDyn_DeckDriver: '

    IF (lineno <= 0) RETURN
    body = TRIM(ErrMsg)
    IF (LEN(body) >= LEN(prefix)) THEN
      IF (body(1:LEN(prefix)) == prefix) body = body(LEN(prefix) + 1:)
    END IF
    ErrMsg = prefix//what//' line '//TRIM(int_to_str(lineno))//': '//body
  END SUBROUTINE add_file_line

  SUBROUTINE read_whole_record(unit, buf, ios, overflow)
    !! Read one physical record into buf. When the record is longer than buf, the rest
    !! is consumed (so the next read starts on the next record) and overflow reports
    !! whether any of that remainder was non-blank. A final record without a line
    !! terminator that exactly fills buf (or its remainder chunks) reaches end of file
    !! while the remainder is consumed; the unit is then stepped back before the
    !! end-of-file position so the next read reports end of file, not a read error.
    INTEGER, INTENT(IN) :: unit
    CHARACTER(*), INTENT(OUT) :: buf
    INTEGER, INTENT(OUT) :: ios
    LOGICAL, INTENT(OUT) :: overflow
    CHARACTER(256) :: chunk
    INTEGER :: nread, ios_rest, ios_back

    overflow = .FALSE.
    buf = ''
    nread = 0
    READ (unit, '(A)', ADVANCE='NO', SIZE=nread, IOSTAT=ios) buf
    IF (IS_IOSTAT_EOR(ios)) THEN
      ios = 0
      RETURN
    END IF
    IF (ios /= 0) RETURN
    DO
      chunk = ''
      nread = 0
      READ (unit, '(A)', ADVANCE='NO', SIZE=nread, IOSTAT=ios_rest) chunk
      IF (nread > 0) THEN
        IF (LEN_TRIM(chunk(1:nread)) > 0) overflow = .TRUE.
      END IF
      IF (ios_rest /= 0) EXIT
    END DO
    IF (IS_IOSTAT_END(ios_rest)) BACKSPACE (unit, IOSTAT=ios_back)
  END SUBROUTINE read_whole_record

  SUBROUTINE record_error(ios, what, lineno, ErrStat, ErrMsg)
    !! Error for a non-end-of-file next_record status: an over-long record or a read error.
    INTEGER, INTENT(IN) :: ios, lineno
    CHARACTER(*), INTENT(IN) :: what
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    IF (ios == REC_TOO_LONG) THEN
      CALL fail(ErrStat, ErrMsg, TRIM(what)//' line '//TRIM(int_to_str(lineno))//' is longer than '// &
                TRIM(int_to_str(DECK_RECLEN))//' characters (shorten the row or move commentary after '// &
                'a # comment)')
    ELSE IF (ios == REC_BAD_CHAR) THEN
      CALL fail(ErrStat, ErrMsg, TRIM(what)//' line '//TRIM(int_to_str(lineno))//' contains a non-ASCII '// &
                'whitespace character (such as a no-break space) outside a comment; separate values with '// &
                'ASCII spaces or tabs')
    ELSE IF (ios == REC_NUL_CHAR) THEN
      CALL fail(ErrStat, ErrMsg, TRIM(what)//' line '//TRIM(int_to_str(lineno))//' contains a NUL character '// &
                'outside a comment; save the file as plain text')
    ELSE
      CALL fail(ErrStat, ErrMsg, 'cannot read '//TRIM(what)//' line '//TRIM(int_to_str(lineno)))
    END IF
  END SUBROUTINE record_error

  SUBROUTINE add_deck_line(lineno, ErrMsg)
    !! Rewrite a deck error as "deck line N: <message>" when lineno (the deck line of the
    !! row it concerns) is known; a message that already names its line is unchanged.
    INTEGER, INTENT(IN) :: lineno
    CHARACTER(*), INTENT(INOUT) :: ErrMsg
    CHARACTER(:), ALLOCATABLE :: body
    CHARACTER(*), PARAMETER :: prefix = 'CableDyn_DeckDriver: '

    IF (lineno <= 0) RETURN
    body = TRIM(ErrMsg)
    IF (LEN(body) >= LEN(prefix)) THEN
      IF (body(1:LEN(prefix)) == prefix) body = body(LEN(prefix) + 1:)
    END IF
    IF (LEN(body) >= 10) THEN
      IF (body(1:10) == 'deck line ') RETURN
    END IF
    ErrMsg = prefix//'deck line '//TRIM(int_to_str(lineno))//': '//body
  END SUBROUTINE add_deck_line

  FUNCTION input_open_reason(path, why) RESULT(reason)
    !! Reason suffix for an input file that CD_Open_Input could not open: the refusal
    !! reason for a name that cannot be opened exactly (why), else the file-level cause
    !! for the spelling the runtime was given.
    CHARACTER(*), INTENT(IN) :: path, why
    CHARACTER(:), ALLOCATABLE :: reason, native
    CHARACTER(256) :: unused
    INTEGER :: stat

    IF (LEN_TRIM(why) > 0) THEN
      reason = ' ('//TRIM(why)//')'
    ELSE
      CALL CD_Native_Path(path, native, stat, unused)
      reason = open_failure(native)
    END IF
  END FUNCTION input_open_reason

  SUBROUTINE add_row_context(what, lineno, row, ErrMsg)
    !! Rewrite a row-level parse error as "<what> line N: <message> [row: <text>]" so the
    !! user can find the offending record. The row text is shortened to keep the message
    !! itself intact in fixed-length caller buffers.
    CHARACTER(*), INTENT(IN) :: what, row
    INTEGER, INTENT(IN) :: lineno
    CHARACTER(*), INTENT(INOUT) :: ErrMsg
    CHARACTER(:), ALLOCATABLE :: body, shown
    CHARACTER(*), PARAMETER :: prefix = 'CableDyn_DeckDriver: '
    INTEGER, PARAMETER :: max_row = 96

    body = TRIM(ErrMsg)
    IF (LEN(body) >= LEN(prefix)) THEN
      IF (body(1:LEN(prefix)) == prefix) body = body(LEN(prefix) + 1:)
    END IF
    shown = TRIM(ADJUSTL(row))
    IF (LEN(shown) > max_row) shown = shown(1:max_row - 3)//'...'
    ErrMsg = prefix//TRIM(what)//' line '//TRIM(int_to_str(lineno))//': '//body//' [row: '//shown//']'
  END SUBROUTINE add_row_context

  PURE SUBROUTINE token_bounds(s, pos, lo, hi)
    !! Next whitespace-delimited token of s at or after pos. A token that opens with a
    !! quote runs to the matching close quote (whitespace inside it is kept) and then to
    !! the next whitespace. lo = 0 when no token remains; pos moves past the token.
    CHARACTER(*), INTENT(IN) :: s
    INTEGER, INTENT(INOUT) :: pos
    INTEGER, INTENT(OUT) :: lo, hi
    INTEGER :: n, q

    n = LEN_TRIM(s)
    lo = 0
    hi = 0
    DO WHILE (pos <= n)
      IF (.NOT. is_space(s(pos:pos))) EXIT
      pos = pos + 1
    END DO
    IF (pos > n) RETURN
    lo = pos
    IF (s(pos:pos) == '"' .OR. s(pos:pos) == "'") THEN
      q = INDEX(s(pos + 1:n), s(pos:pos))
      IF (q > 0) THEN
        pos = pos + q + 1
      ELSE
        pos = n + 1
      END IF
    END IF
    DO WHILE (pos <= n)
      IF (is_space(s(pos:pos))) EXIT
      pos = pos + 1
    END DO
    hi = pos - 1
  END SUBROUTINE token_bounds

  PURE LOGICAL FUNCTION is_quoted_token(tok) RESULT(quoted)
    CHARACTER(*), INTENT(IN) :: tok
    quoted = .FALSE.
    IF (LEN(tok) >= 1) quoted = tok(1:1) == '"' .OR. tok(1:1) == "'"
  END FUNCTION is_quoted_token

  PURE LOGICAL FUNCTION has_list_separator(tok) RESULT(bad)
    !! True for an unquoted token a list-directed READ would not take whole: one holding
    !! '/' (end of input: later items keep stale values), ',' or ';' (value separators),
    !! or the r*value repeat-count form.
    CHARACTER(*), INTENT(IN) :: tok
    INTEGER :: star
    bad = SCAN(tok, '/,;') > 0
    IF (bad) RETURN
    star = INDEX(tok, '*')
    IF (star > 1) bad = VERIFY(tok(1:star - 1), '0123456789') == 0
  END FUNCTION has_list_separator

  SUBROUTINE list_safe_row(line, text_cols, char_cols, clean, ErrStat, ErrMsg)
    !! Guard a whitespace-separated row before a list-directed READ. Every unquoted token
    !! outside text_cols that holds a list-directed separator is rejected, so "500/2" or
    !! "1,5" can never be read as 500 or 1 with the following columns silently unset or
    !! shifted. Tokens in text_cols (file paths, bar/comma lists read as strings) are kept
    !! verbatim and quoted in clean, so the READ takes them whole. Well-formed quoted
    !! tokens pass through unchanged.
    !! char_cols lists the columns read as CHARACTER (names, types, flags; text_cols are
    !! character columns too). Every other column holds a number or an id, so there a
    !! quoted token is rejected (a list-directed READ into a character id would silently
    !! unquote "1 x" and a later integer read take its leading 1), and a number that is
    !! not finite (NaN, Inf, beyond HUGE) or is subnormal is rejected before any range
    !! guard compares it. A token that opens a quote must be one non-empty value inside
    !! one pair of matching quotes.
    CHARACTER(*), INTENT(IN) :: line
    INTEGER, INTENT(IN) :: text_cols(:), char_cols(:)
    CHARACTER(*), INTENT(OUT) :: clean
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    INTEGER :: pos, lo, hi, col, out_len, need, kdef
    CHARACTER(1) :: q
    LOGICAL :: as_text, as_char

    ErrStat = 0
    ErrMsg = ''
    clean = ''
    out_len = 0
    pos = 1
    col = 0
    DO
      CALL token_bounds(line, pos, lo, hi)
      IF (lo == 0) EXIT
      col = col + 1
      as_text = ANY(text_cols == col)
      as_char = as_text .OR. ANY(char_cols == col)
      IF (is_quoted_token(line(lo:hi))) THEN
        ! one pair of matching quotes around non-empty text, nothing after the close
        IF (hi - lo + 1 < 3 .OR. line(hi:hi) /= line(lo:lo) .OR. INDEX(line(lo + 1:hi - 1), line(lo:lo)) > 0) THEN
          CALL fail(ErrStat, ErrMsg, 'column '//TRIM(int_to_str(col))//' value '//line(lo:MIN(hi, lo + 63))// &
                    ' has invalid quoting; a quoted value must be non-empty text inside one pair of '// &
                    'matching quotes')
          RETURN
        END IF
        IF (.NOT. as_char) THEN
          CALL fail(ErrStat, ErrMsg, 'column '//TRIM(int_to_str(col))//' must be an unquoted number, got '// &
                    line(lo:MIN(hi, lo + 63)))
          RETURN
        END IF
      ELSE IF (.NOT. as_char) THEN
        kdef = real_token_defect(line(lo:hi))
        IF (kdef /= REAL_OK) THEN
          CALL fail(ErrStat, ErrMsg, 'column '//TRIM(int_to_str(col))//' '//real_defect_text(line(lo:hi), kdef))
          RETURN
        END IF
      END IF
      q = ' '
      ! Name and flag columns are stored in NAMELEN buffers; a longer token would be
      ! truncated by the READ and could alias another name, so it is rejected whole.
      need = hi - lo + 1
      IF (is_quoted_token(line(lo:hi)) .AND. need >= 2) need = need - 2
      IF (.NOT. as_text .AND. need > NAMELEN) THEN
        CALL fail(ErrStat, ErrMsg, 'column '//TRIM(int_to_str(col))//' value "'// &
                  line(lo:MIN(hi, lo + 23))//'..." is longer than '//TRIM(int_to_str(NAMELEN))// &
                  ' characters; shorten the name')
        RETURN
      END IF
      IF (.NOT. is_quoted_token(line(lo:hi))) THEN
        IF (as_text) THEN
          q = '"'
          IF (INDEX(line(lo:hi), '"') > 0) q = "'"
          IF (INDEX(line(lo:hi), "'") > 0 .AND. q == "'") THEN
            CALL fail(ErrStat, ErrMsg, 'column '//TRIM(int_to_str(col))//' value "'//line(lo:hi)// &
                      '" mixes both quote characters')
            RETURN
          END IF
        ELSE IF (has_list_separator(line(lo:hi))) THEN
          CALL fail(ErrStat, ErrMsg, 'column '//TRIM(int_to_str(col))//' value "'//line(lo:hi)// &
                    '" contains "/", ",", ";" or a repeat count "n*"; write plain numbers with a "." '// &
                    'decimal point, and quote text values that need these characters')
          RETURN
        ELSE IF (.NOT. as_char .AND. SCAN(line(lo:hi), '0123456789') > 0 .AND. &
                 VERIFY(line(lo:hi), '0123456789.+-eEdD') == 0) THEN
          ! a list-directed READ takes "500+2" as 500e2 and "10-5" as 1e-4
          IF (.NOT. numeric_token_shape(line(lo:hi))) THEN
            CALL fail(ErrStat, ErrMsg, 'column '//TRIM(int_to_str(col))//' value "'//line(lo:hi)// &
                      '" is not a plain number (write an exponent with e, as in 1.0e5)')
            RETURN
          END IF
        END IF
      END IF
      need = hi - lo + 1
      IF (q /= ' ') need = need + 2
      IF (out_len > 0) out_len = out_len + 1
      IF (out_len + need > LEN(clean)) THEN
        CALL fail(ErrStat, ErrMsg, 'row is too long to parse')
        RETURN
      END IF
      IF (q /= ' ') THEN
        clean(out_len + 1:out_len + need) = q//line(lo:hi)//q
      ELSE
        clean(out_len + 1:out_len + need) = line(lo:hi)
      END IF
      out_len = out_len + need
    END DO
  END SUBROUTINE list_safe_row

  SUBROUTINE get_token(s, k, tok, found)
    !! The k-th whitespace token of s (quotes kept); found = .FALSE. when s has fewer.
    CHARACTER(*), INTENT(IN) :: s
    INTEGER, INTENT(IN) :: k
    CHARACTER(*), INTENT(OUT) :: tok
    LOGICAL, INTENT(OUT) :: found
    INTEGER :: pos, lo, hi, j
    tok = ''
    found = .FALSE.
    pos = 1
    lo = 0
    hi = 0
    DO j = 1, k
      CALL token_bounds(s, pos, lo, hi)
      IF (lo == 0) RETURN
    END DO
    IF (lo == 0) RETURN
    tok = s(lo:hi)
    found = LEN(tok) >= hi - lo + 1
  END SUBROUTINE get_token

  PURE INTEGER FUNCTION real_value_defect(x) RESULT(k)
    !! Why an input number is inadmissible: REAL_OK for zero or a finite normal number,
    !! REAL_NONFINITE for NaN or +-Inf (also a decimal string beyond HUGE, which reads as
    !! Inf), REAL_SUBNORMAL for a nonzero magnitude below TINY. Classified without any
    !! ordered comparison on a non-finite value, so it never raises an invalid-operation
    !! trap; every later range guard can then compare safely.
    REAL(wp), INTENT(IN) :: x
    k = REAL_OK
    IF (.NOT. IEEE_IS_FINITE(x)) THEN
      k = REAL_NONFINITE
    ELSE IF (ABS(x) > CD_ZERO) THEN
      IF (ABS(x) < TINY(x)) k = REAL_SUBNORMAL
    END IF
  END FUNCTION real_value_defect

  FUNCTION real_defect_text(tok, k) RESULT(msg)
    !! The typed message for an inadmissible number token (see real_value_defect).
    CHARACTER(*), INTENT(IN) :: tok
    INTEGER, INTENT(IN) :: k
    CHARACTER(:), ALLOCATABLE :: msg
    IF (k == REAL_SUBNORMAL) THEN
      msg = 'value "'//TRIM(ADJUSTL(tok))//'" is subnormal (a nonzero magnitude below 2.2e-308); '// &
            'write 0 or a normal number'
    ELSE
      msg = 'value "'//TRIM(ADJUSTL(tok))//'" is not a finite number (NaN, Inf and magnitudes '// &
            'beyond 1.8e308 are not accepted)'
    END IF
  END FUNCTION real_defect_text

  INTEGER FUNCTION real_token_defect(tok) RESULT(k)
    !! real_value_defect of a token that reads whole as a real number; REAL_OK for a token
    !! that is not a number at all (a name), which its own reader then judges.
    CHARACTER(*), INTENT(IN) :: tok
    REAL(wp) :: x
    INTEGER :: ios
    k = REAL_OK
    IF (LEN_TRIM(tok) == 0) RETURN
    IF (.NOT. numeric_token_shape(tok)) RETURN
    READ (tok, *, IOSTAT=ios) x
    IF (ios /= 0) RETURN
    k = real_value_defect(x)
  END FUNCTION real_token_defect

  PURE LOGICAL FUNCTION numeric_token_shape(tok) RESULT(ok)
    !! True iff the token is spelled as one decimal real number: [sign] digits [. digits]
    !! (or [sign] . digits) with an optional exponent letter e/E/d/D, [sign] digits; or the
    !! words inf, infinity or nan (so their reader can name them). A list-directed READ
    !! would also take "1+2" as 1e2 and "10-5" as 1e-4, or stop at a separator; neither is
    !! a number here.
    CHARACTER(*), INTENT(IN) :: tok
    CHARACTER(LEN(tok)) :: t
    INTEGER :: n, i, nd
    LOGICAL :: seen_digit
    ok = .FALSE.
    t = ADJUSTL(tok)
    n = LEN_TRIM(t)
    IF (n == 0) RETURN
    i = 1
    IF (t(1:1) == '+' .OR. t(1:1) == '-') i = 2
    IF (i > n) RETURN
    SELECT CASE (to_lower(t(i:n)))
    CASE ('inf', 'infinity', 'nan')
      ok = .TRUE.
      RETURN
    END SELECT
    seen_digit = .FALSE.
    nd = 0
    DO WHILE (i <= n)
      IF (INDEX('0123456789', t(i:i)) == 0) EXIT
      seen_digit = .TRUE.
      i = i + 1
    END DO
    IF (i <= n) THEN
      IF (t(i:i) == '.') THEN
        i = i + 1
        DO WHILE (i <= n)
          IF (INDEX('0123456789', t(i:i)) == 0) EXIT
          seen_digit = .TRUE.
          i = i + 1
        END DO
      END IF
    END IF
    IF (.NOT. seen_digit) RETURN
    IF (i <= n) THEN
      IF (INDEX('eEdD', t(i:i)) == 0) RETURN
      i = i + 1
      IF (i <= n) THEN
        IF (t(i:i) == '+' .OR. t(i:i) == '-') i = i + 1
      END IF
      DO WHILE (i <= n)
        IF (INDEX('0123456789', t(i:i)) == 0) RETURN
        nd = nd + 1
        i = i + 1
      END DO
      IF (nd == 0) RETURN
    END IF
    ok = .TRUE.
  END FUNCTION numeric_token_shape

  SUBROUTINE parse_real_token(tok, x, ok, defect)
    !! Read one token as a real number, whole (numeric_token_shape). An empty token,
    !! embedded blanks or quotes, a list-directed separator ('/', ',', ';', '*') or a sign
    !! inside the mantissa ("1+2") is rejected instead of being read up to the separator
    !! or as an exponent. A number that is not finite (NaN, Inf, or a decimal
    !! beyond HUGE) or is subnormal is rejected too (ok = .FALSE., x = 0), so no input
    !! value can carry NaN into a range guard or a denormal into a division; defect
    !! (optional) reports which (REAL_OK when the token is simply not a number).
    CHARACTER(*), INTENT(IN) :: tok
    REAL(wp), INTENT(OUT) :: x
    LOGICAL, INTENT(OUT) :: ok
    INTEGER, INTENT(OUT), OPTIONAL :: defect
    CHARACTER(LEN(tok)) :: t
    INTEGER :: n, ios, k
    x = CD_ZERO
    ok = .FALSE.
    IF (PRESENT(defect)) defect = REAL_OK
    t = ADJUSTL(tok)
    n = LEN_TRIM(t)
    IF (n == 0) RETURN
    IF (.NOT. numeric_token_shape(t(1:n))) RETURN
    READ (t(1:n), *, IOSTAT=ios) x
    IF (ios /= 0) THEN
      x = CD_ZERO
      RETURN
    END IF
    k = real_value_defect(x)
    IF (PRESENT(defect)) defect = k
    IF (k /= REAL_OK) THEN
      x = CD_ZERO
      RETURN
    END IF
    ok = .TRUE.
  END SUBROUTINE parse_real_token

  SUBROUTINE parse_int_token(tok, k, ok)
    !! Read one token as a default INTEGER: an optional sign and decimal digits only, and
    !! a value that fits (no wrap-around on long digit strings).
    CHARACTER(*), INTENT(IN) :: tok
    INTEGER, INTENT(OUT) :: k
    LOGICAL, INTENT(OUT) :: ok
    CHARACTER(LEN(tok)) :: t
    INTEGER :: n, first, lead, ios
    INTEGER(int64) :: k64
    k = 0
    ok = .FALSE.
    t = ADJUSTL(tok)
    n = LEN_TRIM(t)
    IF (n == 0) RETURN
    first = 1
    IF (t(1:1) == '+' .OR. t(1:1) == '-') first = 2
    IF (first > n) RETURN
    IF (VERIFY(t(first:n), '0123456789') /= 0) RETURN
    lead = VERIFY(t(first:n), '0')
    IF (lead == 0) THEN
      ok = .TRUE.
      RETURN
    END IF
    IF (n - (first + lead - 1) + 1 > 18) RETURN
    READ (t(1:n), *, IOSTAT=ios) k64
    IF (ios /= 0) RETURN
    IF (ABS(k64) > INT(HUGE(k), int64)) RETURN
    k = INT(k64)
    ok = .TRUE.
  END SUBROUTINE parse_int_token

  PURE FUNCTION quat_rotation(q) RESULT(r)
    !! Rotation matrix of the unit quaternion q = (q0, q1, q2, q3) (normalised here).
    REAL(wp), INTENT(IN) :: q(4)
    REAL(wp) :: r(3, 3), u(4)
    u = q/MAX(NORM2(q), TINY(CD_ONE))
    r(1, :) = [CD_ONE - 2.0_wp*(u(3)**2 + u(4)**2), 2.0_wp*(u(2)*u(3) - u(1)*u(4)), 2.0_wp*(u(2)*u(4) + u(1)*u(3))]
    r(2, :) = [2.0_wp*(u(2)*u(3) + u(1)*u(4)), CD_ONE - 2.0_wp*(u(2)**2 + u(4)**2), 2.0_wp*(u(3)*u(4) - u(1)*u(2))]
    r(3, :) = [2.0_wp*(u(2)*u(4) - u(1)*u(3)), 2.0_wp*(u(3)*u(4) + u(1)*u(2)), CD_ONE - 2.0_wp*(u(2)**2 + u(3)**2)]
  END FUNCTION quat_rotation

  SUBROUTINE parse_real_row(line, vals, status)
    !! Strictly read the first SIZE(vals) whitespace tokens of an auxiliary-file row as
    !! reals; later tokens are commentary. status = 0 on success; 1 when the first token is
    !! not a number at all (a header or terminator row); 2 when the row starts like a number
    !! but a required column is missing or is not a plain number (for example "1/2").
    CHARACTER(*), INTENT(IN) :: line
    REAL(wp), INTENT(OUT) :: vals(:)
    INTEGER, INTENT(OUT) :: status
    CHARACTER(LEN(line)) :: tok
    INTEGER :: j
    LOGICAL :: found, ok

    vals = CD_ZERO
    CALL get_token(line, 1, tok, found)
    status = 1
    IF (.NOT. found) RETURN
    ! a header or units row ("Strain / Tension") is not data even where a lone '/' would
    ! read as a list-directed number
    IF (.NOT. numeric_token_shape(tok)) RETURN
    status = 2
    DO j = 1, SIZE(vals)
      CALL get_token(line, j, tok, found)
      IF (.NOT. found) RETURN
      CALL parse_real_token(tok, vals(j), ok)
      IF (.NOT. ok) RETURN
    END DO
    status = 0
  END SUBROUTINE parse_real_row

  SUBROUTINE grid_step_count(tmax, dt, nstep, ok)
    !! NINT(tmax/dt) with the range checked first, so an extreme TMax/dtM ratio fails
    !! closed instead of overflowing the default INTEGER step counter.
    REAL(wp), INTENT(IN) :: tmax, dt
    INTEGER, INTENT(OUT) :: nstep
    LOGICAL, INTENT(OUT) :: ok
    REAL(wp) :: ratio
    nstep = 0
    ok = .FALSE.
    IF (.NOT. (IEEE_IS_FINITE(tmax) .AND. IEEE_IS_FINITE(dt))) RETURN
    IF (.NOT. dt > CD_ZERO) RETURN
    ! range first, without dividing: a tiny dt would overflow tmax/dt (a trapped FPE)
    IF (dt < CD_ONE) THEN
      IF (ABS(tmax) > MAX_GRID_STEPS*dt) RETURN
    END IF
    ratio = tmax/dt
    IF (.NOT. IEEE_IS_FINITE(ratio)) RETURN
    IF (ABS(ratio) > MAX_GRID_STEPS) RETURN
    nstep = NINT(ratio)
    ok = .TRUE.
  END SUBROUTINE grid_step_count

  INTEGER FUNCTION scan_comment(buf) RESULT(p)
    !! First comment char to strip: `#`/`!` anywhere, or `--` only when it starts
    !! a whitespace-delimited comment. Section-header dash rules (`---`) survive.
    CHARACTER(*), INTENT(IN) :: buf
    INTEGER :: ph, pe, pdash, search_from
    LOGICAL :: at_start
    p = 0
    ph = INDEX(buf, '#')
    pe = INDEX(buf, '!')
    IF (ph > 0) p = ph
    IF (pe > 0 .AND. (p == 0 .OR. pe < p)) p = pe
    IF (INDEX(buf, '---') == 0) THEN
      search_from = 1
      DO
        pdash = INDEX(buf(search_from:), '--')
        IF (pdash == 0) EXIT
        pdash = search_from + pdash - 1
        ! gfortran does not short-circuit .OR., so guard the buf(pdash-1:...) substring
        ! with a nested test -- a flat `pdash == 1 .OR. is_space(buf(pdash-1:...))` forms
        ! buf(0:0) when pdash == 1 (out of bounds; benign read under Release, a -fcheck trap).
        IF (pdash == 1) THEN
          at_start = .TRUE.
        ELSE
          at_start = is_space(buf(pdash - 1:pdash - 1))
        END IF
        IF (at_start) THEN
          IF (p == 0 .OR. pdash < p) p = pdash
          EXIT
        END IF
        search_from = pdash + 2
        IF (search_from > LEN_TRIM(buf)) EXIT
      END DO
    END IF
  END FUNCTION scan_comment

  PURE LOGICAL FUNCTION is_space(ch) RESULT(yes)
    !! The ASCII token separators: space, tab, LF, VT, FF, CR.
    CHARACTER(*), INTENT(IN) :: ch
    INTEGER :: c
    c = IACHAR(ch(1:1))
    yes = c == 32 .OR. (c >= 9 .AND. c <= 13)
  END FUNCTION is_space

  PURE INTEGER FUNCTION first_nonspace(s, from, n) RESULT(i)
    !! First position in from..n of s that is not a separator, or n + 1.
    CHARACTER(*), INTENT(IN) :: s
    INTEGER, INTENT(IN) :: from, n
    DO i = from, n
      IF (.NOT. is_space(s(i:i))) RETURN
    END DO
    i = MAX(from, n + 1)
  END FUNCTION first_nonspace

  PURE INTEGER FUNCTION first_space(s, from, n) RESULT(i)
    !! First position in from..n of s that is a separator, or n + 1.
    CHARACTER(*), INTENT(IN) :: s
    INTEGER, INTENT(IN) :: from, n
    DO i = from, n
      IF (is_space(s(i:i))) RETURN
    END DO
    i = MAX(from, n + 1)
  END FUNCTION first_space

  PURE FUNCTION strip_quotes(s) RESULT(out)
    !! Remove one pair of matching surrounding quotes (single or double) from a
    !! token: the stock MoorDyn decks write file options as "name.dat", and
    !! storing the quotes verbatim makes every downstream open fail on a file
    !! literally named with quotes. Unquoted tokens pass through unchanged.
    CHARACTER(*), INTENT(IN) :: s
    CHARACTER(LEN(s)) :: out
    CHARACTER(512) :: t
    INTEGER :: n
    t = ADJUSTL(s)
    n = LEN_TRIM(t)
    out = t
    IF (n >= 2) THEN
      IF ((t(1:1) == '"' .AND. t(n:n) == '"') .OR. (t(1:1) == "'" .AND. t(n:n) == "'")) THEN
        out = t(2:n - 1)
      END IF
    END IF
  END FUNCTION strip_quotes

  LOGICAL FUNCTION has_numeric_token(s) RESULT(yes)
    !! True iff any whitespace-separated token of s is spelled as a real number
    !! (numeric_token_shape). Data rows carry a number; column-name / units rows
    !! ("TypeName Diam ...", "(-) (m) ...", "Strain / Tension") do not.
    CHARACTER(*), INTENT(IN) :: s
    INTEGER :: i, j, n
    yes = .FALSE.
    n = LEN_TRIM(s); i = 1
    DO WHILE (i <= n)
      i = first_nonspace(s, i, n)
      IF (i > n) EXIT
      j = first_space(s, i, n)
      IF (numeric_token_shape(s(i:j - 1))) THEN; yes = .TRUE.; RETURN; END IF
      i = j
    END DO
  END FUNCTION has_numeric_token

  PURE INTEGER FUNCTION count_tokens(s) RESULT(k)
    !! Number of whitespace-delimited tokens; a quoted token counts once even when it
    !! contains whitespace (the same tokens a list-directed READ sees).
    CHARACTER(*), INTENT(IN) :: s
    INTEGER :: pos, lo, hi
    k = 0
    pos = 1
    DO
      CALL token_bounds(s, pos, lo, hi)
      IF (lo == 0) EXIT
      k = k + 1
    END DO
  END FUNCTION count_tokens

  PURE SUBROUTINE split_two_tokens(s, first, second, ErrStat, allow_trailing)
    CHARACTER(*), INTENT(IN) :: s
    CHARACTER(*), INTENT(OUT) :: first, second
    INTEGER, INTENT(OUT) :: ErrStat
    LOGICAL, INTENT(IN), OPTIONAL :: allow_trailing
    INTEGER :: i, j, n

    first = ''
    second = ''
    ErrStat = 1
    n = LEN_TRIM(s)
    i = first_nonspace(s, 1, n)
    IF (i > n) RETURN
    j = first_space(s, i, n)
    first = s(i:j - 1)
    i = first_nonspace(s, j, n)
    IF (i > n) RETURN
    j = first_space(s, i, n)
    second = s(i:j - 1)
    i = first_nonspace(s, j, n)
    IF (i <= n) THEN
      ! trailing content after the second token: an error unless the caller opts
      ! into stock-MoorDyn-style trailing commentary ("0.001  dtM  - time step ...")
      IF (PRESENT(allow_trailing)) THEN
        IF (allow_trailing) ErrStat = 0
      END IF
      RETURN
    END IF
    ErrStat = 0
  END SUBROUTINE split_two_tokens

  PURE FUNCTION to_lower(s) RESULT(out)
    CHARACTER(*), INTENT(IN) :: s
    CHARACTER(LEN(s)) :: out
    INTEGER :: i, c
    DO i = 1, LEN(s)
      c = IACHAR(s(i:i))
      IF (c >= IACHAR('A') .AND. c <= IACHAR('Z')) THEN
        out(i:i) = ACHAR(c + 32)
      ELSE
        out(i:i) = s(i:i)
      END IF
    END DO
  END FUNCTION to_lower

  PURE CHARACTER(1) FUNCTION up(c) RESULT(o)
    CHARACTER(1), INTENT(IN) :: c
    INTEGER :: k
    k = IACHAR(c)
    IF (k >= IACHAR('a') .AND. k <= IACHAR('z')) THEN
      o = ACHAR(k - 32)
    ELSE
      o = c
    END IF
  END FUNCTION up

  PURE CHARACTER(1) FUNCTION char_tab() RESULT(t)
    t = ACHAR(9)
  END FUNCTION char_tab

  SUBROUTINE fail(ErrStat, ErrMsg, msg)
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    CHARACTER(*), INTENT(IN)  :: msg
    ErrStat = CD_DECKDRV_BADINPUT
    ErrMsg = 'CableDyn_DeckDriver: '//msg
  END SUBROUTINE fail

  FUNCTION open_failure(path) RESULT(reason)
    !! Reason suffix for a failed OPEN(STATUS='OLD') of an input file: the file is
    !! absent, is already connected to another unit of this process (the Fortran
    !! runtime refuses a second connection), or exists but could not be opened.
    CHARACTER(*), INTENT(IN) :: path
    CHARACTER(:), ALLOCATABLE :: reason
    LOGICAL :: exists, connected
    INTEGER :: ios

    exists = .FALSE.
    connected = .FALSE.
    INQUIRE (FILE=path, EXIST=exists, OPENED=connected, IOSTAT=ios)
    IF (ios /= 0 .OR. .NOT. exists) THEN
      reason = ' (file not found)'
    ELSE IF (connected) THEN
      reason = ' (the file exists but is already open in this process)'
    ELSE
      reason = ' (the file exists but could not be opened: permission denied or in use)'
    END IF
  END FUNCTION open_failure

  SUBROUTINE fail_solve(ErrStat, ErrMsg, msg)
    !! Report a numerical failure of an accepted deck (non-convergence, a rejected
    !! equilibrium branch, or a non-finite result): the driver exits with status 2.
    INTEGER, INTENT(OUT) :: ErrStat
    CHARACTER(*), INTENT(OUT) :: ErrMsg
    CHARACTER(*), INTENT(IN)  :: msg
    ErrStat = CD_DECKDRV_SOLVEFAIL
    ErrMsg = 'CableDyn_DeckDriver: '//msg
  END SUBROUTINE fail_solve

END MODULE CableDyn_DeckDriver
